CREATE OR REPLACE FUNCTION "admin_api"."platform_issue_acknowledge"("p_issue_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_uid uuid:=auth.uid(); v_row pipeline.platform_issues;
begin
  if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank()<5 then raise exception 'pim_admin role required' using errcode='42501'; end if;
  update pipeline.platform_issues set acknowledged_by=v_uid, acknowledged_at=now(), acknowledged_note=left(nullif(trim(p_note),''),500)
   where id=p_issue_id and resolved_at is null returning * into v_row;
  if v_row.id is null then raise exception 'open platform issue not found' using errcode='P0002'; end if;
  return to_jsonb(v_row)-'acknowledged_by';
end $$;


ALTER FUNCTION "admin_api"."platform_issue_acknowledge"("p_issue_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin_api"."scholarship_ai_run_status"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_rank int:=security.scholarship_ai_role_rank(); v_actor uuid:=auth.uid(); v_r pipeline.scholarship_ai_runs%rowtype;
begin
 if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
 select * into v_r from pipeline.scholarship_ai_runs where id=p_run_id;
 if not found then raise exception 'run not found'; end if;
 return jsonb_build_object('id',v_r.id,'status',v_r.status,'total_items',v_r.total_items,'processed_items',v_r.processed_items,'validated_items',v_r.validated_items,'review_items',v_r.review_items,'no_candidate_items',v_r.no_candidate_items,'failed_items',v_r.failed_items,'api_calls',case when v_rank>=4 then v_r.api_calls else null end,'input_tokens',case when v_rank>=4 then v_r.input_tokens else null end,'output_tokens',case when v_rank>=4 then v_r.output_tokens else null end,'cost_usd',case when v_rank>=4 then v_r.cost_usd else null end,'created_at',v_r.created_at,'started_at',v_r.started_at,'completed_at',v_r.completed_at);
end $$;


ALTER FUNCTION "admin_api"."scholarship_ai_run_status"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin_api"."scholarship_ai_settings_write"("p_country_code" "text", "p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_rank int:=security.scholarship_ai_role_rank(); v_actor uuid:=auth.uid(); v_country text:=upper(p_country_code); v_p uuid; v_row pipeline.scholarship_ai_settings%rowtype;
begin
 if v_rank<5 then raise exception 'PIM Admin role required' using errcode='42501'; end if;
 if p_patch ? 'default_profile_id' then v_p:=nullif(p_patch->>'default_profile_id','')::uuid; end if;
 insert into pipeline.scholarship_ai_settings(country_code) values(v_country) on conflict do nothing;
 update pipeline.scholarship_ai_settings set
   enabled=case when p_patch?'enabled' then (p_patch->>'enabled')::boolean else enabled end,
   schedule_on_change=case when p_patch?'schedule_on_change' then (p_patch->>'schedule_on_change')::boolean else schedule_on_change end,
   default_task_class=coalesce(nullif(p_patch->>'default_task_class',''),default_task_class),
   default_profile_id=case when p_patch?'default_profile_id' then v_p else default_profile_id end,
   max_records_per_run=case when p_patch?'max_records_per_run' then least(greatest((p_patch->>'max_records_per_run')::int,1),200) else max_records_per_run end,
   daily_budget_usd=case when p_patch?'daily_budget_usd' then greatest((p_patch->>'daily_budget_usd')::numeric,0) else daily_budget_usd end,
   schedule_actor=case when coalesce((p_patch->>'schedule_on_change')::boolean,schedule_on_change) then v_actor else null end,
   updated_by=v_actor,updated_at=now(),metadata=metadata||jsonb_build_object('change_control_ref','CF-CHG-20260906-221')
 where country_code=v_country returning * into v_row;
 return to_jsonb(v_row)-'schedule_actor'-'updated_by';
end $$;


ALTER FUNCTION "admin_api"."scholarship_ai_settings_write"("p_country_code" "text", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin_api"."scholarship_runtime_settings_write"("p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank integer; v_uid uuid:=auth.uid(); v_country text:=upper(coalesce(nullif(p_patch->>'country_code',''),'AU')); v_row pipeline.scholarship_runtime_settings;
begin
 if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank(); if v_rank<5 then raise exception 'pim_admin role required' using errcode='42501'; end if;
 insert into pipeline.scholarship_runtime_settings(country_code,enabled,detail_batch_limit,auto_dispatch,catalogue_refresh_hours,detail_refresh_hours,updated_by,updated_at,metadata)
 values(v_country,coalesce((p_patch->>'enabled')::boolean,true),least(greatest(coalesce(nullif(p_patch->>'detail_batch_limit','')::integer,25),1),100),coalesce((p_patch->>'auto_dispatch')::boolean,true),least(greatest(coalesce(nullif(p_patch->>'catalogue_refresh_hours','')::integer,168),1),2160),least(greatest(coalesce(nullif(p_patch->>'detail_refresh_hours','')::integer,168),1),2160),v_uid,now(),jsonb_build_object('international_only',true,'publication_authorised',false,'route_mode','managed','change_control_ref','CF-166'))
 on conflict(country_code) do update set enabled=excluded.enabled,detail_batch_limit=excluded.detail_batch_limit,auto_dispatch=excluded.auto_dispatch,catalogue_refresh_hours=excluded.catalogue_refresh_hours,detail_refresh_hours=excluded.detail_refresh_hours,updated_by=v_uid,updated_at=now(),metadata=excluded.metadata
 returning * into v_row;
 return to_jsonb(v_row)-'updated_by';
end $$;


ALTER FUNCTION "admin_api"."scholarship_runtime_settings_write"("p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin_api"."statistics_dataset_registry_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
begin
  if auth.uid() is null then raise exception 'authentication_required'; end if;
  if security.current_role_rank() < 1 then raise exception 'not_authorised'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.display_order,x.label) from (
    select dataset_key,label,dataset_type,description,display_enabled,display_order,dataset_route,compare_enabled,source_system_code,source_authority,admin_import_system
    from pipeline.statistics_dataset_registry
  ) x),'[]'::jsonb);
end $$;


ALTER FUNCTION "admin_api"."statistics_dataset_registry_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin_api"."statistics_dataset_registry_write"("p_dataset" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $_$
declare k text; r pipeline.statistics_dataset_registry;
begin
  if auth.uid() is null then raise exception 'authentication_required'; end if;
  if security.current_role_rank() < 4 then raise exception 'admin_role_required'; end if;
  k:=lower(trim(coalesce(p_dataset->>'dataset_key','')));
  if k !~ '^[a-z0-9_]{2,64}$' then raise exception 'invalid_dataset_key'; end if;
  insert into pipeline.statistics_dataset_registry(dataset_key,label,dataset_type,description,display_enabled,display_order,dataset_route,compare_enabled,source_system_code,source_authority,admin_import_system,updated_at)
  values(k,trim(coalesce(p_dataset->>'label',k)),coalesce(nullif(p_dataset->>'dataset_type',''),'statistics'),coalesce(p_dataset->>'description',''),coalesce((p_dataset->>'display_enabled')::boolean,true),coalesce((p_dataset->>'display_order')::integer,100),nullif(p_dataset->>'dataset_route',''),coalesce((p_dataset->>'compare_enabled')::boolean,true),nullif(p_dataset->>'source_system_code',''),nullif(p_dataset->>'source_authority',''),nullif(p_dataset->>'admin_import_system',''),now())
  on conflict(dataset_key) do update set label=excluded.label,dataset_type=excluded.dataset_type,description=excluded.description,display_enabled=excluded.display_enabled,display_order=excluded.display_order,dataset_route=excluded.dataset_route,compare_enabled=excluded.compare_enabled,source_system_code=excluded.source_system_code,source_authority=excluded.source_authority,admin_import_system=excluded.admin_import_system,updated_at=now()
  returning * into r;
  return to_jsonb(r);
end $_$;


ALTER FUNCTION "admin_api"."statistics_dataset_registry_write"("p_dataset" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."courses_list"("p_provider_id" "uuid" DEFAULT NULL::"uuid", "p_country" character DEFAULT NULL::"bpchar", "p_level_code" "text" DEFAULT NULL::"text", "p_publication" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "stable_key" "text", "provider_id" "uuid", "provider_name" "text", "canonical_title" "text", "course_code" "text", "level_code" "text", "publication_status" "text", "completeness_score" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'api', 'catalogue', 'ref', 'publishing', 'security'
    AS $$
select c.id,c.stable_key,c.provider_id,coalesce(p.display_name,p.canonical_name),c.canonical_title,c.course_code,sl.code,c.publication_status,max(es.completeness_score)
from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
left join ref.study_levels sl on sl.id=c.study_level_id left join publishing.entity_states es on es.entity_id=c.id
where security.current_role_rank()>=1
  and not exists (select 1 from security.layer4_search_blocked_courses cf_block where cf_block.course_id=c.id)
  and (p_provider_id is null or c.provider_id=p_provider_id)
  and (p_country is null or co.iso_alpha2=p_country)
  and (p_level_code is null or sl.code=p_level_code)
  and (p_publication is null or c.publication_status=p_publication)
group by c.id,p.canonical_name,p.display_name,sl.code
order by c.canonical_title
limit least(greatest(coalesce(p_limit,100),1),500) offset greatest(coalesce(p_offset,0),0)
$$;


ALTER FUNCTION "api"."courses_list"("p_provider_id" "uuid", "p_country" character, "p_level_code" "text", "p_publication" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."providers_list"("p_country" character DEFAULT NULL::"bpchar", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "stable_key" "text", "canonical_name" "text", "display_name" "text", "country_code" character, "publication_status" "text", "course_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'api', 'catalogue', 'ref', 'security'
    AS $$
select p.id,p.stable_key,p.canonical_name,p.display_name,c.iso_alpha2,p.publication_status,count(cr.id)::bigint
from catalogue.providers p join ref.countries c on c.id=p.country_id left join catalogue.courses cr on cr.provider_id=p.id and not exists (select 1 from security.layer4_search_blocked_courses cf_course_block where cf_course_block.course_id=cr.id)
where security.current_role_rank()>=1 and not exists (select 1 from security.layer4_search_blocked_providers cf_block where cf_block.provider_id=p.id) and (p_country is null or c.iso_alpha2=p_country)
group by p.id,c.iso_alpha2
order by coalesce(p.display_name,p.canonical_name)
limit least(greatest(coalesce(p_limit,100),1),500) offset greatest(coalesce(p_offset,0),0)
$$;


ALTER FUNCTION "api"."providers_list"("p_country" character, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."query_embedding_cache_get"("p_cache_key" "text", "p_model_name" "text", "p_profile_version" "text") RETURNS TABLE("embedding" "extensions"."vector", "hit_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'api', 'search', 'extensions'
    AS $$
begin
 update search.query_embedding_cache q set last_used_at=now(),hit_count=q.hit_count+1 where q.cache_key=p_cache_key and q.model_name=p_model_name and q.profile_version=p_profile_version and q.expires_at>now();
 return query select q.embedding,q.hit_count from search.query_embedding_cache q where q.cache_key=p_cache_key and q.model_name=p_model_name and q.profile_version=p_profile_version and q.expires_at>now();
end$$;


ALTER FUNCTION "api"."query_embedding_cache_get"("p_cache_key" "text", "p_model_name" "text", "p_profile_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."query_embedding_cache_put"("p_cache_key" "text", "p_model_name" "text", "p_profile_version" "text", "p_embedding" "extensions"."vector", "p_ttl_seconds" integer DEFAULT 604800) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'api', 'search', 'extensions'
    AS $$
insert into search.query_embedding_cache(cache_key,model_name,profile_version,embedding,expires_at)
values(p_cache_key,p_model_name,p_profile_version,p_embedding,now()+make_interval(secs=>least(greatest(coalesce(p_ttl_seconds,604800),60),2592000)))
on conflict(cache_key) do update set model_name=excluded.model_name,profile_version=excluded.profile_version,embedding=excluded.embedding,created_at=now(),last_used_at=now(),hit_count=0,expires_at=excluded.expires_at;
$$;


ALTER FUNCTION "api"."query_embedding_cache_put"("p_cache_key" "text", "p_model_name" "text", "p_profile_version" "text", "p_embedding" "extensions"."vector", "p_ttl_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."search_courses"("p_query" "text", "p_country" character DEFAULT NULL::"bpchar", "p_level_code" "text" DEFAULT NULL::"text", "p_has_scholarship" boolean DEFAULT NULL::boolean, "p_limit" integer DEFAULT 20) RETURNS TABLE("course_id" "uuid", "provider_name" "text", "course_title" "text", "level_code" "text", "rank" real, "has_fee" boolean, "has_intake" boolean, "has_english" boolean, "has_scholarship" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'api', 'search', 'ref', 'security'
    AS $$
select d.course_id,d.provider_name,d.course_title,sl.code,
       ts_rank_cd(d.search_tsv,websearch_to_tsquery('english',coalesce(p_query,'')))::real,
       d.has_fee,d.has_intake,d.has_english,d.has_scholarship
from search.course_documents d left join ref.study_levels sl on sl.id=d.study_level_id join ref.countries co on co.id=d.country_id
where security.current_role_rank()>=1 and not exists (select 1 from security.layer4_search_blocked_courses cf_block where cf_block.course_id=d.course_id) and d.publication_status in ('published','internal')
 and (p_country is null or co.iso_alpha2=p_country)
 and (p_level_code is null or sl.code=p_level_code)
 and (p_has_scholarship is null or d.has_scholarship=p_has_scholarship)
 and (coalesce(trim(p_query),'')='' or d.search_tsv @@ websearch_to_tsquery('english',p_query))
order by ts_rank_cd(d.search_tsv,websearch_to_tsquery('english',coalesce(p_query,''))) desc,d.course_title
limit least(greatest(coalesce(p_limit,20),1),50)
$$;


ALTER FUNCTION "api"."search_courses"("p_query" "text", "p_country" character, "p_level_code" "text", "p_has_scholarship" boolean, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "api"."search_courses"("p_query" "text", "p_country" character, "p_level_code" "text", "p_has_scholarship" boolean, "p_limit" integer) IS 'DEPRECATED internal service-only Search RPC. Consumer integrations must use versioned M1-SEARCH contracts.';



CREATE OR REPLACE FUNCTION "api"."vector_candidates"("p_embedding" "extensions"."vector", "p_profile_code" "text", "p_country" character DEFAULT NULL::"bpchar", "p_level_code" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("course_id" "uuid", "distance" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'api', 'search', 'ref', 'security', 'extensions'
    AS $$
select e.course_id,(e.embedding<=>p_embedding)::double precision
from search.course_embeddings e join search.profiles sp on sp.id=e.profile_id join search.course_documents d on d.course_id=e.course_id
join ref.countries co on co.id=d.country_id left join ref.study_levels sl on sl.id=d.study_level_id
where security.current_role_rank()>=1 and not exists (select 1 from security.layer4_search_blocked_courses cf_block where cf_block.course_id=d.course_id) and sp.code=p_profile_code and (p_country is null or co.iso_alpha2=p_country) and (p_level_code is null or sl.code=p_level_code)
order by e.embedding<=>p_embedding limit least(greatest(coalesce(p_limit,50),1),100)
$$;


ALTER FUNCTION "api"."vector_candidates"("p_embedding" "extensions"."vector", "p_profile_code" "text", "p_country" character, "p_level_code" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_course_lookup_preview_v1"("p_identifier" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'api', 'search', 'pg_catalog'
    AS $$
with hit as (
  select d.*, 'exact_course_code'::text as match_type, 0 as match_priority
  from search.course_documents d
  where not exists (select 1 from security.layer4_search_blocked_courses cf_block where cf_block.course_id=d.course_id)
    and nullif(trim(p_identifier),'') is not null
    and lower(d.course_code)=lower(trim(p_identifier))
  union all
  select d.*, 'exact_course_id'::text as match_type, 1 as match_priority
  from search.course_documents d
  where not exists (select 1 from security.layer4_search_blocked_courses cf_block where cf_block.course_id=d.course_id)
    and nullif(trim(p_identifier),'') is not null
    and lower(d.course_stable_key)=lower(trim(p_identifier))
), chosen as (
  select * from hit order by match_priority,course_stable_key limit 1
), state as (
  select generation,content_hash from search.projection_state where projection_code='courses'
)
select jsonb_build_object(
 'contract_version','website-course-lookup-preview-v1','boundary','server-side-showcase-only',
 'meta',jsonb_build_object('mode','exact','projection_version','course-v3','projection_generation',(select generation from state),'projection_hash',(select content_hash from state),'publication_authority','not_granted'),
 'item',(select jsonb_build_object(
   'course_id',course_stable_key,'title',course_title,'course_code',course_code,
   'provider',jsonb_build_object('provider_id',provider_stable_key,'name',provider_name),
   'country',country_code,'study_level',study_level_code,
   'field',case when primary_field_code is null then null else jsonb_build_object('code',primary_field_code,'name',primary_field_name) end,
   'locations',to_jsonb(subdivision_codes),'delivery_modes',to_jsonb(delivery_modes),
   'regulatory_tuition',jsonb_build_object('state',regulatory_tuition_state,'amount',regulatory_tuition_amount,'currency',trim(regulatory_tuition_currency),'basis',regulatory_tuition_basis),
   'provider_current_tuition',jsonb_build_object('has_value',has_provider_current_tuition,'annual_amount',provider_annual_tuition_amount,'annual_currency',trim(provider_annual_tuition_currency),'options',provider_tuition_options),
   'official_course_url',official_course_url,'intakes',intake_options,'english_requirements',english_requirement_options,'scholarships',scholarship_options,
   'visibility',jsonb_build_object('publication_status',publication_status),
   'freshness',jsonb_build_object('source_updated_at',source_updated_at,'generated_at',generated_at),
   'match',jsonb_build_object('mode',match_type,'keyword_score',1000)
 ) from chosen)
);
$$;


ALTER FUNCTION "api"."website_course_lookup_preview_v1"("p_identifier" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_course_search_preview_v1"("p_query" "text" DEFAULT NULL::"text", "p_country_codes" "text"[] DEFAULT NULL::"text"[], "p_provider_keys" "text"[] DEFAULT NULL::"text"[], "p_provider_name" "text" DEFAULT NULL::"text", "p_subdivision_codes" "text"[] DEFAULT NULL::"text"[], "p_level_codes" "text"[] DEFAULT NULL::"text"[], "p_field_codes" "text"[] DEFAULT NULL::"text"[], "p_delivery_modes" "text"[] DEFAULT NULL::"text"[], "p_provider_annual_tuition_min" numeric DEFAULT NULL::numeric, "p_provider_annual_tuition_max" numeric DEFAULT NULL::numeric, "p_has_intake" boolean DEFAULT NULL::boolean, "p_has_english" boolean DEFAULT NULL::boolean, "p_has_scholarship" boolean DEFAULT NULL::boolean, "p_sort" "text" DEFAULT 'relevance'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'api', 'search', 'pg_catalog'
    AS $$
with params as (
 select greatest(1,least(coalesce(p_limit,20),50)) lim,
        greatest(coalesce(p_offset,0),0) off,
        nullif(trim(coalesce(p_query,'')),'') q,
        case when nullif(trim(coalesce(p_query,'')),'') is null then null else websearch_to_tsquery('english',trim(p_query)) end tsq,
        case when p_sort in ('relevance','title','provider_annual_tuition_asc','provider_annual_tuition_desc','earliest_intake') then p_sort else 'relevance' end sort_code
), ranked as (
 select d.*,ts_rank_cd(d.search_tsv,(select tsq from params))::real score
 from search.course_documents d
 where not exists (select 1 from security.layer4_search_blocked_courses cf_block where cf_block.course_id=d.course_id)
    and (select q from params) is not null
   and d.search_tsv @@ (select tsq from params)
   and (p_country_codes is null or d.country_code=any(p_country_codes))
   and (p_provider_keys is null or d.provider_stable_key=any(p_provider_keys))
   and (p_provider_name is null or d.provider_name ilike '%'||trim(p_provider_name)||'%')
   and (p_subdivision_codes is null or d.subdivision_codes && p_subdivision_codes)
   and (p_level_codes is null or d.study_level_code=any(p_level_codes))
   and (p_field_codes is null or d.primary_field_code=any(p_field_codes))
   and (p_delivery_modes is null or d.delivery_modes && p_delivery_modes)
   and (p_provider_annual_tuition_min is null or d.provider_annual_tuition_amount>=p_provider_annual_tuition_min)
   and (p_provider_annual_tuition_max is null or d.provider_annual_tuition_amount<=p_provider_annual_tuition_max)
   and (p_has_intake is null or d.has_intake=p_has_intake)
   and (p_has_english is null or d.has_english=p_has_english)
   and (p_has_scholarship is null or d.has_scholarship=p_has_scholarship)
 union all
 select d.*,0::real score
 from search.course_documents d
 where not exists (select 1 from security.layer4_search_blocked_courses cf_block where cf_block.course_id=d.course_id)
    and (select q from params) is null
   and (p_country_codes is null or d.country_code=any(p_country_codes))
   and (p_provider_keys is null or d.provider_stable_key=any(p_provider_keys))
   and (p_provider_name is null or d.provider_name ilike '%'||trim(p_provider_name)||'%')
   and (p_subdivision_codes is null or d.subdivision_codes && p_subdivision_codes)
   and (p_level_codes is null or d.study_level_code=any(p_level_codes))
   and (p_field_codes is null or d.primary_field_code=any(p_field_codes))
   and (p_delivery_modes is null or d.delivery_modes && p_delivery_modes)
   and (p_provider_annual_tuition_min is null or d.provider_annual_tuition_amount>=p_provider_annual_tuition_min)
   and (p_provider_annual_tuition_max is null or d.provider_annual_tuition_amount<=p_provider_annual_tuition_max)
   and (p_has_intake is null or d.has_intake=p_has_intake)
   and (p_has_english is null or d.has_english=p_has_english)
   and (p_has_scholarship is null or d.has_scholarship=p_has_scholarship)
), paged as (
 select * from ranked
 order by case when (select sort_code from params)='relevance' then score end desc,
          case when (select sort_code from params)='title' then course_title end asc,
          case when (select sort_code from params)='provider_annual_tuition_asc' then provider_annual_tuition_amount end asc nulls last,
          case when (select sort_code from params)='provider_annual_tuition_desc' then provider_annual_tuition_amount end desc nulls last,
          case when (select sort_code from params)='earliest_intake' then earliest_intake_date end asc nulls last,
          course_title,course_stable_key
 limit (select lim from params) offset (select off from params)
), state as (select generation,content_hash from search.projection_state where projection_code='courses')
select jsonb_build_object(
 'contract_version','website-course-search-preview-v1','boundary','server-side-showcase-only',
 'meta',jsonb_build_object('mode','deterministic_fts','limit',(select lim from params),'offset',(select off from params),'projection_version','course-v3','projection_generation',(select generation from state),'projection_hash',(select content_hash from state),'sort',(select sort_code from params),'publication_authority','not_granted'),
 'items',coalesce(jsonb_agg(jsonb_build_object(
   'course_id',course_stable_key,'title',course_title,'course_code',course_code,
   'provider',jsonb_build_object('provider_id',provider_stable_key,'name',provider_name),
   'country',country_code,'study_level',study_level_code,
   'field',case when primary_field_code is null then null else jsonb_build_object('code',primary_field_code,'name',primary_field_name) end,
   'locations',to_jsonb(subdivision_codes),'delivery_modes',to_jsonb(delivery_modes),
   'regulatory_tuition',jsonb_build_object('state',regulatory_tuition_state,'amount',regulatory_tuition_amount,'currency',trim(regulatory_tuition_currency),'basis',regulatory_tuition_basis),
   'provider_current_tuition',jsonb_build_object('has_value',has_provider_current_tuition,'annual_amount',provider_annual_tuition_amount,'annual_currency',trim(provider_annual_tuition_currency),'options',provider_tuition_options),
   'official_course_url',official_course_url,'intakes',intake_options,'english_requirements',english_requirement_options,'scholarships',scholarship_options,
   'visibility',jsonb_build_object('publication_status',publication_status),
   'freshness',jsonb_build_object('source_updated_at',source_updated_at,'generated_at',generated_at),
   'match',jsonb_build_object('mode',case when (select q from params) is null then 'filter' else 'fts' end,'keyword_score',score)
 ) order by case when (select sort_code from params)='relevance' then score end desc,
            case when (select sort_code from params)='title' then course_title end asc,
            case when (select sort_code from params)='provider_annual_tuition_asc' then provider_annual_tuition_amount end asc nulls last,
            case when (select sort_code from params)='provider_annual_tuition_desc' then provider_annual_tuition_amount end desc nulls last,
            case when (select sort_code from params)='earliest_intake' then earliest_intake_date end asc nulls last,
            course_title,course_stable_key),'[]'::jsonb)
) from paged;
$$;


ALTER FUNCTION "api"."website_course_search_preview_v1"("p_query" "text", "p_country_codes" "text"[], "p_provider_keys" "text"[], "p_provider_name" "text", "p_subdivision_codes" "text"[], "p_level_codes" "text"[], "p_field_codes" "text"[], "p_delivery_modes" "text"[], "p_provider_annual_tuition_min" numeric, "p_provider_annual_tuition_max" numeric, "p_has_intake" boolean, "p_has_english" boolean, "p_has_scholarship" boolean, "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_course_search_v1"("p_query" "text" DEFAULT NULL::"text", "p_country_codes" "text"[] DEFAULT NULL::"text"[], "p_subdivision_codes" "text"[] DEFAULT NULL::"text"[], "p_level_codes" "text"[] DEFAULT NULL::"text"[], "p_field_codes" "text"[] DEFAULT NULL::"text"[], "p_delivery_modes" "text"[] DEFAULT NULL::"text"[], "p_has_fee" boolean DEFAULT NULL::boolean, "p_has_scholarship" boolean DEFAULT NULL::boolean, "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'api', 'search'
    AS $$
with params as (
  select greatest(1,least(coalesce(p_limit,20),50)) as lim,
         greatest(coalesce(p_offset,0),0) as off,
         websearch_to_tsquery('english',coalesce(nullif(trim(p_query),''),'')) as tsq
), ranked as (
  select d.*,
    case when coalesce(trim(p_query),'')='' then 0::real else ts_rank_cd(d.search_tsv,(select tsq from params))::real end as score
  from search.course_documents d
  where not exists (select 1 from security.layer4_search_blocked_courses cf_block where cf_block.course_id=d.course_id)
    and d.publication_status='published'
    and (p_country_codes is null or d.country_code=any(p_country_codes))
    and (p_subdivision_codes is null or d.subdivision_codes && p_subdivision_codes)
    and (p_level_codes is null or d.study_level_code=any(p_level_codes))
    and (p_field_codes is null or d.primary_field_code=any(p_field_codes))
    and (p_delivery_modes is null or d.delivery_modes && p_delivery_modes)
    and (p_has_fee is null or d.has_fee=p_has_fee)
    and (p_has_scholarship is null or d.has_scholarship=p_has_scholarship)
    and (coalesce(trim(p_query),'')='' or d.search_tsv @@ (select tsq from params))
), paged as (
  select * from ranked
  order by score desc,course_title,course_stable_key
  limit (select lim from params) offset (select off from params)
)
select jsonb_build_object(
  'contract_version','website-course-search-v1',
  'meta',jsonb_build_object(
    'mode','keyword',
    'limit',(select lim from params),
    'offset',(select off from params),
    'projection_version','course-v2'
  ),
  'items',coalesce(jsonb_agg(jsonb_build_object(
    'course_key',course_stable_key,
    'title',course_title,
    'course_code',course_code,
    'provider',jsonb_build_object('provider_key',provider_stable_key,'name',provider_name),
    'country',country_code,
    'study_level',study_level_code,
    'field',case when primary_field_code is null then null else jsonb_build_object('code',primary_field_code,'name',primary_field_name) end,
    'states',to_jsonb(subdivision_codes),
    'delivery_modes',to_jsonb(delivery_modes),
    'readiness',jsonb_build_object('has_state',has_state,'has_link',has_link,'has_fee',has_fee,'has_intake',has_intake,'has_english',has_english,'has_scholarship',has_scholarship),
    'match',jsonb_build_object('keyword_score',score)
  ) order by score desc,course_title,course_stable_key),'[]'::jsonb)
)
from paged
$$;


