CREATE OR REPLACE FUNCTION "api"."website_integration_auth_v1"("p_token_sha256" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$ select exists(select 1 from private.website_integration_credentials c
 where c.credential_name='coursefinder_website_wix_pilot_v1'
 and c.enabled and c.token_sha256=lower(coalesce(p_token_sha256,''))); $$;


ALTER FUNCTION "api"."website_integration_auth_v1"("p_token_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_integration_rate_check_v1"("p_identity" "text", "p_resource" "text", "p_limit" integer DEFAULT 60, "p_window_seconds" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
declare
 v_identity text:=nullif(trim(coalesce(p_identity,'')),'');
 v_resource text:=nullif(trim(coalesce(p_resource,'')),'');
 v_limit integer:=least(greatest(coalesce(p_limit,60),1),1000);
 v_window integer:=least(greatest(coalesce(p_window_seconds,60),10),3600);
 v_now timestamptz:=clock_timestamp(); v_epoch bigint; v_start timestamptz; v_count integer; v_retry integer;
begin
 if v_identity is null or v_resource is null then raise exception using errcode='22023',message='identity_and_resource_required'; end if;
 v_epoch:=floor(extract(epoch from v_now)/v_window)::bigint*v_window; v_start:=to_timestamp(v_epoch);
 insert into private.website_integration_rate_windows(identity,resource,window_started_at,request_count,updated_at)
 values(v_identity,v_resource,v_start,1,v_now)
 on conflict(identity,resource,window_started_at) do update
 set request_count=private.website_integration_rate_windows.request_count+1,updated_at=excluded.updated_at
 returning request_count into v_count;
 v_retry:=greatest(1,ceil(extract(epoch from(v_start+make_interval(secs=>v_window)-v_now)))::integer);
 delete from private.website_integration_rate_windows where window_started_at<v_now-interval '1 day';
 return jsonb_build_object('allowed',v_count<=v_limit,'count',v_count,'limit',v_limit,'window_seconds',v_window,
 'retry_after_seconds',case when v_count<=v_limit then 0 else v_retry end);
end; $$;


ALTER FUNCTION "api"."website_integration_rate_check_v1"("p_identity" "text", "p_resource" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_text_array"("p" "jsonb") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case jsonb_typeof(p)
    when 'array' then nullif(array(select btrim(x) from jsonb_array_elements_text(p) x where btrim(x)<>''), '{}')
    when 'string' then case when btrim(p #>> '{}')<>'' then array[btrim(p #>> '{}')] end
  end $$;


ALTER FUNCTION "api"."website_text_array"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_v2_annual"("p_opts" "jsonb", "p_reg" numeric, "p_weeks" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'api'
    AS $$
  with pt as (select api.website_v2_latest_fee(p_opts) o)
  select case when (select o from pt) is not null then
              case api.website_v2_fee_basis((select o->>'basis' from pt))
                   when 'annual' then ((select o->>'amount' from pt))::numeric
                   when 'indicative_annual' then ((select o->>'amount' from pt))::numeric
                   when 'course_total' then case when p_weeks >= 52 then round(((select o->>'amount' from pt))::numeric / (p_weeks/52.0)) end end
              when p_reg >= 1000 and p_weeks >= 52 then round(p_reg / (p_weeks/52.0)) end
$$;


ALTER FUNCTION "api"."website_v2_annual"("p_opts" "jsonb", "p_reg" numeric, "p_weeks" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_v2_course_item"("p_course_id" "uuid", "p_cities" "text"[] DEFAULT NULL::"text"[], "p_postcodes" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'search', 'catalogue', 'ref', 'pipeline', 'security', 'api'
    AS $_$
declare d search.course_documents; v jsonb;
begin
  select * into d from search.course_documents where course_id = p_course_id;
  if not found then return null; end if;
  v := jsonb_build_object(
    'course_id', d.course_stable_key,
    'course_code', d.course_code,
    'title', d.course_title,
    'country_code', d.country_code,
    'provider', jsonb_build_object('provider_id', d.provider_stable_key, 'name', security.provider_presentable_name(d.provider_name), 'legal_name', d.provider_name,
                  'university_groups', security.provider_university_groups(d.provider_id),
                  'ranking_summary', api.website_v2_ranking_summary(d.provider_id),
                  'logo', api.website_v2_provider_logo(d.provider_id)),
    'campuses', coalesce((select jsonb_agg(jsonb_build_object('city', security.place_presentable(k.city), 'postcode', k.postcode, 'subdivision_code', s.code,
                   'is_primary', coalesce(cc.is_primary,false), 'metro_area', rc.metro_area, 'regional_category', rc.category, 'regional_category_name', rc.category_name)
                   order by (p_cities is not null and (lower(btrim(k.city)) = any(p_cities) or lower(rc.metro_area) = any(p_cities))) desc,
                            (p_postcodes is not null and btrim(k.postcode) = any(p_postcodes)) desc, cc.is_primary desc nulls last, k.city)
                 from catalogue.course_campuses cc join catalogue.campuses k on k.id = cc.campus_id
                 left join ref.subdivisions s on s.id = k.subdivision_id left join pipeline.campus_regional_class rc on rc.campus_id = k.id
                 where cc.course_id = d.course_id), '[]'::jsonb),
    'study_level', jsonb_build_object('code', d.study_level_code, 'name', (select sl.name from ref.study_levels sl where sl.code = d.study_level_code limit 1)),
    'study_area', jsonb_build_object('code', d.primary_field_code, 'name', d.primary_field_name),
    'duration_months', (select round(c.duration_value * case lower(coalesce(c.duration_unit,'')) when 'weeks' then 12.0/52 when 'months' then 1 when 'years' then 12 end)::int
                        from catalogue.courses c where c.id = d.course_id),
    'delivery_modes', to_jsonb(d.delivery_modes),
    'tuition', api.website_v2_tuition(d),
    'intakes', coalesce((select jsonb_agg(distinct jsonb_build_object('label', i->>'label', 'month', api.website_v2_label_month(i->>'label'), 'year', i->'year',
                  'start_date', i->'start_date', 'application_deadline', i->'application_deadline'))
                 from jsonb_array_elements(coalesce(d.intake_options,'[]'::jsonb)) i where nullif(i->>'label','') is not null), '[]'::jsonb),
    'entry_requirements', jsonb_build_object(
        'summary', (select 'English: ' || string_agg(
                case e->>'test_code' when 'IELTS' then 'IELTS ' || to_char((e->>'overall_score')::numeric,'FM90.0')
                     when 'PTE' then 'PTE Academic ' || trim(to_char((e->>'overall_score')::numeric,'FM999'))
                     when 'TOEFL_IBT' then 'TOEFL iBT ' || trim(to_char((e->>'overall_score')::numeric,'FM999'))
                     else coalesce(e->>'test_name', e->>'test_code') || ' ' || (e->>'overall_score') end, ', '
                order by case e->>'test_code' when 'IELTS' then 1 when 'PTE' then 2 when 'TOEFL_IBT' then 3 else 4 end)
              from jsonb_array_elements(coalesce(d.english_requirement_options,'[]'::jsonb)) e where (e->>'overall_score') ~ '^[0-9]+(\.[0-9]+)?$'),
        'basis', case when jsonb_array_length(coalesce(d.english_requirement_options,'[]'::jsonb)) > 0 then 'english_only' end),
    'english_requirements', coalesce((select jsonb_agg(jsonb_build_object('test_code', e->>'test_code', 'test_name', e->>'test_name',
                  'min_overall_score', e->'overall_score',
                  'min_band_score', (select min(z.v::numeric) from jsonb_each_text(case when jsonb_typeof(e->'component_scores')='object' then e->'component_scores' else '{}'::jsonb end) z(k2,v) where z.v ~ '^[0-9]+(\.[0-9]+)?$'),
                  'source', case when e->>'notes' ~* 'policy|central|university standard' then 'university_policy' else 'course_page' end))
                 from jsonb_array_elements(coalesce(d.english_requirement_options,'[]'::jsonb)) e), '[]'::jsonb),
    'official_url', d.official_course_url,
    'scholarship_count', jsonb_array_length(coalesce(d.scholarship_options,'[]'::jsonb)),
    'subdivision_codes', to_jsonb(d.subdivision_codes),
    'publication_status', d.publication_status,
    'freshness', jsonb_build_object('projection_updated_at', d.updated_at, 'source_updated_at', d.source_updated_at));
  v := v || jsonb_build_object(
    'campus_city', v->'campuses'->0->'city',
    'campus_metro_area', v->'campuses'->0->'metro_area');
  return v;
end $_$;


ALTER FUNCTION "api"."website_v2_course_item"("p_course_id" "uuid", "p_cities" "text"[], "p_postcodes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_v2_fee_basis"("p_basis" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case when p_basis ~* 'total|course' and p_basis !~* 'annual' then 'course_total'
              when p_basis ~* 'session|semester|trimester|unit|credit' then 'per_session'
              when p_basis ~* 'indicative' then 'indicative_annual'
              when p_basis ~* 'annual|per.?year|yearly' then 'annual'
              else 'unspecified' end
$$;


ALTER FUNCTION "api"."website_v2_fee_basis"("p_basis" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_v2_has_fee"("p_opts" "jsonb", "p_reg" numeric) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'api'
    AS $$
  select api.website_v2_latest_fee(p_opts) is not null or coalesce(p_reg,0) >= 1000
$$;


ALTER FUNCTION "api"."website_v2_has_fee"("p_opts" "jsonb", "p_reg" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_v2_label_month"("p_label" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select m.n from (values (1,'jan'),(2,'feb'),(3,'mar'),(4,'apr'),(5,'may'),(6,'jun'),(7,'jul'),(8,'aug'),(9,'sep'),(10,'oct'),(11,'nov'),(12,'dec')) m(n,k)
  where strpos(lower(coalesce(p_label,'')), m.k) > 0
  order by strpos(lower(p_label), m.k) limit 1
$$;


ALTER FUNCTION "api"."website_v2_label_month"("p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_v2_latest_fee"("p_opts" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select o from jsonb_array_elements(coalesce(p_opts,'[]'::jsonb)) o
  where (o->>'amount') ~ '^[0-9]+(\.[0-9]+)?$' and (o->>'amount')::numeric >= 1000
  order by nullif(o->>'fee_year','')::int desc nulls last limit 1
$_$;


ALTER FUNCTION "api"."website_v2_latest_fee"("p_opts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_v2_provider_campuses"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref', 'pipeline', 'security'
    AS $$
  select coalesce(jsonb_agg(distinct jsonb_build_object('city', security.place_presentable(k.city), 'postcode', k.postcode, 'subdivision_code', s.code,
           'metro_area', rc.metro_area, 'regional_category', rc.category, 'regional_category_name', rc.category_name)), '[]'::jsonb)
  from catalogue.campuses k
  left join ref.subdivisions s on s.id = k.subdivision_id
  left join pipeline.campus_regional_class rc on rc.campus_id = k.id
  where k.provider_id = p_provider_id and nullif(btrim(k.city),'') is not null and coalesce(k.status,'active') <> 'inactive'
$$;


ALTER FUNCTION "api"."website_v2_provider_campuses"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_v2_provider_logo"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'catalogue'
    AS $$
  select jsonb_build_object('storage_path', a.storage_path, 'mime_type', a.mime_type, 'content_hash', a.content_hash,
           'updated_at', coalesce(a.verified_at, a.observed_at), 'source_url', a.source_url,
           'attribution', 'Logo of the provider, from the provider''s own website', 'terms_status', 'management_decision_pending')
  from catalogue.provider_assets a
  where a.provider_id = p_provider_id and a.asset_type = 'logo' and a.status = 'approved' and a.is_primary and a.storage_path is not null
  order by coalesce(a.verified_at, a.observed_at) desc nulls last limit 1
$$;


ALTER FUNCTION "api"."website_v2_provider_logo"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_v2_ranking_summary"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'ranking'
    AS $$
  with r as (
    select distinct on (s.code) s.code, e.edition_year, o.rank_display, o.rank_low, o.rank_exact
    from ranking.observation_provider_links l
    join ranking.observations o on o.id = l.observation_id
    join ranking.editions e on e.id = o.edition_id and e.status = 'accepted'
    join ranking.systems s on s.id = e.system_id
    where l.provider_id = p_provider_id
    order by s.code, e.edition_year desc, l.is_primary desc nulls last
  )
  select case when count(*) = 0 then null else jsonb_object_agg(r.code, jsonb_build_object(
    'edition_year', r.edition_year, 'rank_display', r.rank_display, 'rank_low', coalesce(r.rank_low, r.rank_exact),
    'terms_status', 'management_decision_pending')) end
  from r
$$;


ALTER FUNCTION "api"."website_v2_ranking_summary"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."website_v2_scholarship_item"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'scholarship', 'catalogue', 'search', 'ref', 'security', 'api'
    AS $$
  with s as (select * from scholarship.scholarships where id = p_id),
  p as (select pr.* from catalogue.providers pr join s on s.provider_id = pr.id),
  cr as (select c.* from scholarship.criteria c join s on c.scholarship_id = s.id where coalesce(c.status,'active') not in ('rejected','superseded','withdrawn')),
  st as (select case when bool_or('international' = any(value_codes)) and bool_or('domestic' = any(value_codes)) then 'both'
                     when bool_or('international' = any(value_codes)) then 'international'
                     when bool_or('domestic' = any(value_codes)) then 'domestic' end v from cr where criterion_type='student_type'),
  acad as (select value_number, coalesce(value_json->>'scale', value_text) scale, human_text from cr where criterion_type='academic_minimum' order by confidence desc nulls last limit 1),
  nat as (select coalesce((select codes from scholarship.nationality_readings nr join s on nr.scholarship_id=s.id),
                          (select array_agg(distinct x) from cr, unnest(cr.value_codes) x where cr.criterion_type in ('nationality','citizenship_and_residency'))) codes),
  lv as (select array_agg(distinct d.study_level_code order by d.study_level_code) levels, count(distinct m.course_id) n
         from scholarship.course_mappings m join s on m.scholarship_id=s.id join search.course_documents d on d.course_id=m.course_id where m.mapping_state='mapped'),
  areas as (select array_agg(distinct d.primary_field_code order by d.primary_field_code) codes from scholarship.course_mappings m join s on m.scholarship_id=s.id join search.course_documents d on d.course_id=m.course_id where m.mapping_state='mapped' and d.primary_field_code is not null)
  select jsonb_build_object(
    'scholarship_id', s.stable_key,
    'name', s.name,
    'official_url', s.source_url, 'official_scholarship_url', s.source_url,
    'provider', jsonb_build_object('provider_id', p.stable_key, 'name', security.provider_presentable_name(coalesce(p.display_name,p.canonical_name)),
                  'cities', (select coalesce(jsonb_agg(distinct security.place_presentable(k.city)), '[]'::jsonb) from catalogue.campuses k where k.provider_id=p.id and nullif(btrim(k.city),'') is not null),
                  'country_code', (select trim(c.iso_alpha2::text) from ref.countries c where c.id=p.country_id),
                  'logo', api.website_v2_provider_logo(p.id)),
    'university_id', p.stable_key,
    'campus_city', coalesce(security.place_presentable(p.primary_city), (select security.place_presentable(min(k.city)) from catalogue.campuses k where k.provider_id=p.id and nullif(btrim(k.city),'') is not null)),
    'scholarship_type', s.scholarship_type, 'scholarship_type_bucket', s.scholarship_type,
    'amount_value', coalesce(s.award_amount, s.award_percentage),
    'amount_type', case when s.award_value_type='fixed_amount' then 'fixed_amount'
                        when s.award_value_type='percentage' and s.award_percentage >= 100 then 'full_tuition'
                        when s.award_value_type='percentage' then 'percentage_tuition' end,
    'amount_type_detail', s.award_value_type,
    'amount_currency', s.award_currency_code,
    'amount_is_maximum', coalesce(s.award_value_is_maximum,false),
    'amount_note', s.award_value_text,
    'scholarship_percentage', s.award_percentage,
    'value_classification', case when s.award_value_type='percentage' and s.award_percentage >= 100 then 'full_tuition'
                                 when s.award_value_type='percentage' then 'partial_tuition'
                                 when s.award_value_type='fixed_amount' then 'fixed_amount' else 'not_stated' end,
    'application_open_date', s.application_open_date,
    'application_deadline', s.application_close_date, 'application_closing_date', s.application_close_date,
    'deadline_is_rolling', (coalesce(s.description,'') || ' ' || coalesce(s.award_value_text,'')) ~* '(rolling (basis|applications|intake|admission)|until (all )?(places|funds|positions) (are )?(filled|allocated)|open (all|throughout the) year|year[- ]round)',
    'current_status', case when s.application_close_date is null then 'check_provider'
                           when s.application_close_date < current_date then 'closed'
                           when s.application_open_date > current_date then 'opening_soon' else 'open' end,
    'study_levels', to_jsonb(coalesce((select levels from lv), '{}'::text[])), 'study_levels_list', to_jsonb(coalesce((select levels from lv), '{}'::text[])),
    'study_levels_source', case when (select n from lv) > 0 then 'linked_courses' end,
    'study_stages', coalesce((select jsonb_agg(distinct value_text) from cr where criterion_type='study_stage' and value_text is not null), '[]'::jsonb),
    'student_type', (select v from st),
    'study_load', (select string_agg(distinct value_text, ', ') from cr where criterion_type='study_load'),
    'study_area_codes', case when (select codes from areas) is not null then to_jsonb((select codes from areas)) end,
    'academic_minimum', (select jsonb_build_object('value', value_number, 'scale', scale, 'text', human_text) from acad),
    'min_academic_score', (select value_number from acad where upper(scale) in ('WAM','PERCENTAGE','%') and value_number between 0 and 100),
    'automatic_consideration', case when exists (select 1 from cr where criterion_type='application_method' and value_text='automatic') then true
                                    when s.application_required then false end,
    'citizenship_eligibility', to_jsonb((select codes from nat)), 'eligible_countries_list', to_jsonb((select codes from nat)),
    'gender', (select string_agg(distinct value_text, ', ') from cr where criterion_type='gender'),
    'age_min', (select min(value_number) from cr where criterion_type='minimum_age'),
    'age_max', null,
    'renewable', case when s.award_duration_basis in ('annual','annual_program_duration','program_duration','per_semester') then true
                      when s.award_duration_basis in ('one_off','first_year') then false end,
    'eligibility_summary', (select string_agg(human_text, ' ') from cr where criterion_type='published_eligibility_narrative'),
    'reference_code', (select i.identifier_value from scholarship.identifiers i where i.scholarship_id=s.id and i.scheme in ('study_australia_scholarship_id','dfat_award_scheme') order by i.is_primary desc limit 1),
    'course_count', coalesce((select n from lv), 0),
    'last_verified_date', s.updated_at::date,
    'publication_status', s.publication_status)
  from s, p
$$;


ALTER FUNCTION "api"."website_v2_scholarship_item"("p_id" "uuid") OWNER TO "postgres";

