CREATE OR REPLACE FUNCTION "api"."zoho_integration_rate_check_v1"("p_identity" "text", "p_resource" "text", "p_limit" integer DEFAULT 120, "p_window_seconds" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
declare
  v_identity text := nullif(trim(coalesce(p_identity,'')), '');
  v_resource text := nullif(trim(coalesce(p_resource,'')), '');
  v_limit integer := least(greatest(coalesce(p_limit,120),1),1000);
  v_window integer := least(greatest(coalesce(p_window_seconds,60),10),3600);
  v_now timestamptz := clock_timestamp();
  v_epoch bigint;
  v_start timestamptz;
  v_count integer;
  v_retry integer;
begin
  if v_identity is null or v_resource is null then
    raise exception using errcode='22023', message='identity_and_resource_required';
  end if;

  v_epoch := floor(extract(epoch from v_now) / v_window)::bigint * v_window;
  v_start := to_timestamp(v_epoch);

  insert into private.zoho_integration_rate_windows(identity, resource, window_started_at, request_count, updated_at)
  values (v_identity, v_resource, v_start, 1, v_now)
  on conflict (identity, resource, window_started_at)
  do update set request_count = private.zoho_integration_rate_windows.request_count + 1,
                updated_at = excluded.updated_at
  returning request_count into v_count;

  v_retry := greatest(1, ceil(extract(epoch from (v_start + make_interval(secs => v_window) - v_now)))::integer);

  delete from private.zoho_integration_rate_windows
   where window_started_at < v_now - interval '1 day';

  return jsonb_build_object(
    'allowed', v_count <= v_limit,
    'count', v_count,
    'limit', v_limit,
    'window_seconds', v_window,
    'retry_after_seconds', case when v_count <= v_limit then 0 else v_retry end
  );
end;
$$;


ALTER FUNCTION "api"."zoho_integration_rate_check_v1"("p_identity" "text", "p_resource" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."zoho_provider_lookup_v1"("p_identifier" "text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref', 'api'
    AS $$
  with x as (
    select
      p.id, p.stable_key, p.canonical_name, p.display_name, p.short_name,
      c.iso_alpha2::text country_code, p.website, p.description,
      p.primary_city, p.lifecycle_status, p.publication_status,
      p.last_verified_at, p.updated_at
    from catalogue.providers p
    join ref.countries c on c.id=p.country_id
    where not exists (select 1 from security.layer4_search_blocked_providers cf_block where cf_block.provider_id=p.id)
      and lower(p.stable_key)=lower(btrim(p_identifier))
       or exists (
         select 1 from catalogue.provider_identifiers i
         where i.provider_id=p.id and lower(i.identifier)=lower(btrim(p_identifier))
       )
    order by case when lower(p.stable_key)=lower(btrim(p_identifier)) then 0 else 1 end
    limit 1
  )
  select case when exists(select 1 from x) then jsonb_build_object(
    'contract_version','zoho-integration-v1',
    'resource','provider',
    'item',(select jsonb_build_object(
      'provider_id',stable_key,'name',canonical_name,'display_name',display_name,
      'short_name',short_name,'country_code',country_code,'website',website,
      'description',description,'primary_city',primary_city,
      'lifecycle_status',lifecycle_status,'publication_status',publication_status,
      'freshness',jsonb_build_object('last_verified_at',last_verified_at,'updated_at',updated_at)
    ) from x),
    'generated_at',now()
  ) else jsonb_build_object(
    'contract_version','zoho-integration-v1','resource','provider','error',
    jsonb_build_object('code','NOT_FOUND','message','Provider identifier not found')
  ) end;
$$;


ALTER FUNCTION "api"."zoho_provider_lookup_v1"("p_identifier" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."zoho_provider_search_v1"("p_query" "text" DEFAULT NULL::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_changed_since" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref', 'api'
    AS $$
  with base as (
    select
      p.id,
      p.stable_key,
      p.canonical_name,
      p.display_name,
      c.iso_alpha2::text as country_code,
      p.website,
      p.lifecycle_status,
      p.publication_status,
      p.last_verified_at,
      p.updated_at
    from catalogue.providers p
    join ref.countries c on c.id = p.country_id
    where not exists (select 1 from security.layer4_search_blocked_providers cf_block where cf_block.provider_id=p.id)
      and (p_query is null or btrim(p_query) = '' or
           p.canonical_name ilike '%' || btrim(p_query) || '%' or
           p.display_name ilike '%' || btrim(p_query) || '%' or
           p.stable_key ilike '%' || btrim(p_query) || '%')
      and (p_country_code is null or c.iso_alpha2 = upper(p_country_code))
      and (p_changed_since is null or p.updated_at > p_changed_since)
  ),
  page as (
    select * from base
    order by lower(canonical_name), stable_key
    limit greatest(1, least(coalesce(p_limit,20),50))
    offset greatest(coalesce(p_offset,0),0)
  )
  select jsonb_build_object(
    'contract_version','zoho-integration-v1',
    'resource','providers',
    'items', coalesce(jsonb_agg(jsonb_build_object(
      'provider_id', stable_key,
      'name', canonical_name,
      'display_name', display_name,
      'country_code', country_code,
      'website', website,
      'lifecycle_status', lifecycle_status,
      'publication_status', publication_status,
      'freshness', jsonb_build_object(
        'last_verified_at', last_verified_at,
        'updated_at', updated_at
      )
    ) order by lower(canonical_name), stable_key), '[]'::jsonb),
    'page', jsonb_build_object(
      'limit', greatest(1, least(coalesce(p_limit,20),50)),
      'offset', greatest(coalesce(p_offset,0),0),
      'total', (select count(*) from base)
    ),
    'generated_at', now()
  ) from page;
$$;


ALTER FUNCTION "api"."zoho_provider_search_v1"("p_query" "text", "p_country_code" "text", "p_changed_since" timestamp with time zone, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


