CREATE OR REPLACE FUNCTION "l4_api"."override_apply"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text", "p_value" "jsonb", "p_reason_code" "text", "p_comment" "text" DEFAULT NULL::"text", "p_evidence_refs" "uuid"[] DEFAULT '{}'::"uuid"[], "p_approval_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'l4_api', 'security', 'auth'
    AS $$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  return security.layer4_override_apply_impl(auth.uid(),p_entity_type,p_entity_id,p_field_code,p_value,p_reason_code,p_comment,p_evidence_refs,p_approval_context);
end $$;


ALTER FUNCTION "l4_api"."override_apply"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text", "p_value" "jsonb", "p_reason_code" "text", "p_comment" "text", "p_evidence_refs" "uuid"[], "p_approval_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."override_history"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'l4_api', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank int;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',d.id,'event_type',d.event_type,'underlying_value',d.underlying_value,'override_value',d.override_value,
      'reason_code',d.reason_code,'comment',d.comment,'evidence_refs',d.evidence_refs,
      'actor_id',d.actor_id,'actor_email',d.actor_email,'created_at',d.created_at,'supersedes_override_id',d.supersedes_override_id
    ) order by d.created_at desc,d.id desc)
    from pipeline.layer4_override_decisions d
    where d.entity_type=p_entity_type and d.entity_id=p_entity_id and d.field_code=p_field_code
  ),'[]'::jsonb);
end $$;


ALTER FUNCTION "l4_api"."override_history"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."override_revert"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text", "p_reason_code" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'l4_api', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_rank int; v_reg pipeline.layer4_field_registry%rowtype;
        v_prev pipeline.layer4_override_decisions%rowtype; v_id uuid; v_email text; v_underlying jsonb;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  select * into v_reg from pipeline.layer4_field_registry where entity_type=p_entity_type and field_code=p_field_code and enabled;
  if not found or v_reg.editability_class='immutable' then raise exception 'field is not revertible through Layer 4' using errcode='42501'; end if;
  if v_rank<v_reg.min_role_rank then raise exception 'insufficient role for Layer 4 field' using errcode='42501'; end if;
  if length(trim(coalesce(p_reason_code,'')))<3 then raise exception 'reason code required' using errcode='22023'; end if;
  select * into v_prev from pipeline.layer4_override_decisions
   where entity_type=p_entity_type and entity_id=p_entity_id and field_code=p_field_code
   order by created_at desc,id desc limit 1;
  if not found or v_prev.event_type='revert' then raise exception 'no active Layer 4 override to revert' using errcode='22023'; end if;
  v_underlying:=security.layer4_underlying_value(p_entity_type,p_entity_id,p_field_code);
  select email into v_email from auth.users where id=v_actor;
  insert into pipeline.layer4_override_decisions(
    entity_type,entity_id,field_code,event_type,underlying_value,override_value,
    reason_code,comment,actor_id,actor_email,supersedes_override_id
  ) values (
    p_entity_type,p_entity_id,p_field_code,'revert',v_underlying,null,
    trim(p_reason_code),nullif(trim(coalesce(p_comment,'')),''),v_actor,v_email,v_prev.id
  ) returning id into v_id;
  return jsonb_build_object('ok',true,'override_id',v_id,'event_type','revert','effective_value',v_underlying,'effective_source','UNDERLYING','canonical_changed',false);
end $$;


ALTER FUNCTION "l4_api"."override_revert"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text", "p_reason_code" "text", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."publication_control_execute"("p_entity_type" "text", "p_entity_ids" "uuid"[], "p_target_scope" "text", "p_action" "text", "p_confirmation_token" "text", "p_reason_code" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'security', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_rank int; v_ids uuid[]; v_id uuid; v_expected text; v_event text; v_results jsonb:='[]'::jsonb; v_result jsonb;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<5 then raise exception 'PIM Admin role required' using errcode='42501'; end if;
  if p_action not in ('publish','unpublish','rollback') then raise exception 'invalid publication action' using errcode='22023'; end if;
  if p_target_scope not in ('search_api','website','zoho','governed_publication') then raise exception 'invalid target scope' using errcode='22023'; end if;
  if length(trim(coalesce(p_reason_code,'')))<3 then raise exception 'reason code required' using errcode='22023'; end if;
  select array_agg(distinct x order by x) into v_ids from unnest(coalesce(p_entity_ids,'{}'::uuid[])) x;
  if coalesce(array_length(v_ids,1),0)<1 or array_length(v_ids,1)>100 then raise exception 'publication cohort must contain 1 to 100 records' using errcode='22023'; end if;
  v_expected:=md5(p_entity_type||'|'||p_target_scope||'|'||p_action||'|'||array_to_string(v_ids,','));
  if coalesce(p_confirmation_token,'')<>v_expected then raise exception 'preview confirmation token mismatch' using errcode='22023'; end if;
  v_event:=case p_action when 'publish' then 'publishable' when 'unpublish' then 'not_publishable' else 'revert' end;
  foreach v_id in array v_ids loop
    v_result:=public.layer4_publication_decide(p_entity_type,v_id,p_target_scope,v_event,'{}'::jsonb,'[]'::jsonb,p_reason_code,p_comment,jsonb_build_object('cohort_token',v_expected,'cohort_size',array_length(v_ids,1),'action',p_action));
    v_results:=v_results||jsonb_build_array(jsonb_build_object('entity_id',v_id,'result',v_result));
  end loop;
  return jsonb_build_object('ok',true,'count',array_length(v_ids,1),'target_scope',p_target_scope,'action',p_action,'cohort_token',v_expected,'results',v_results,'consumer_cutover_authorised',false,'auto_publication_enabled',false);
end $$;


ALTER FUNCTION "l4_api"."publication_control_execute"("p_entity_type" "text", "p_entity_ids" "uuid"[], "p_target_scope" "text", "p_action" "text", "p_confirmation_token" "text", "p_reason_code" "text", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."publication_control_preview"("p_entity_type" "text", "p_entity_ids" "uuid"[], "p_target_scope" "text", "p_action" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'security', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_rank int; v_ids uuid[]; v_id uuid; v_items jsonb:='[]'::jsonb; v_token text; v_state jsonb; v_auto boolean;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<5 then raise exception 'PIM Admin role required' using errcode='42501'; end if;
  if p_action not in ('publish','unpublish','rollback') then raise exception 'invalid publication action' using errcode='22023'; end if;
  if p_target_scope not in ('search_api','website','zoho','governed_publication') then raise exception 'invalid target scope' using errcode='22023'; end if;
  select array_agg(distinct x order by x) into v_ids from unnest(coalesce(p_entity_ids,'{}'::uuid[])) x;
  if coalesce(array_length(v_ids,1),0)<1 then raise exception 'at least one entity required' using errcode='22023'; end if;
  if array_length(v_ids,1)>100 then raise exception 'publication cohort exceeds 100 records' using errcode='22023'; end if;
  foreach v_id in array v_ids loop
    if not security.layer4_entity_exists(p_entity_type,v_id) then raise exception 'entity not found: %',v_id using errcode='22023'; end if;
    v_state:=public.layer4_publication_state(p_entity_type,v_id,p_target_scope);
    v_items:=v_items||jsonb_build_array(jsonb_build_object('entity_id',v_id,'current_state',v_state));
  end loop;
  select auto_publication_enabled into v_auto from pipeline.publication_control_settings where singleton=true;
  v_token:=md5(p_entity_type||'|'||p_target_scope||'|'||p_action||'|'||array_to_string(v_ids,','));
  return jsonb_build_object('entity_type',p_entity_type,'target_scope',p_target_scope,'action',p_action,'count',array_length(v_ids,1),'confirmation_token',v_token,'items',v_items,'auto_publication_enabled',coalesce(v_auto,false),'mutated',false);
end $$;


ALTER FUNCTION "l4_api"."publication_control_preview"("p_entity_type" "text", "p_entity_ids" "uuid"[], "p_target_scope" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."publication_decide"("p_entity_type" "text", "p_entity_id" "uuid", "p_target_scope" "text", "p_event_type" "text", "p_readiness_snapshot" "jsonb", "p_overridden_checks" "jsonb", "p_reason_code" "text", "p_comment" "text" DEFAULT NULL::"text", "p_approval_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'l4_api', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_rank int; v_prev uuid; v_id uuid; v_email text;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<5 then raise exception 'PIM Admin role required for publication override' using errcode='42501'; end if;
  if not security.layer4_entity_exists(p_entity_type,p_entity_id) then raise exception 'entity not found' using errcode='22023'; end if;
  if p_event_type='publishable' and security.layer4_entity_or_parent_blocked(p_entity_type,p_entity_id,'publication') then raise exception 'entity publication blocked by Layer 4' using errcode='42501'; end if;
  if p_event_type not in ('publishable','not_publishable','revert') then raise exception 'invalid publication decision' using errcode='22023'; end if;
  if length(trim(coalesce(p_reason_code,'')))<3 then raise exception 'reason code required' using errcode='22023'; end if;
  select id into v_prev from pipeline.layer4_publication_decisions
   where entity_type=p_entity_type and entity_id=p_entity_id and target_scope=coalesce(nullif(trim(p_target_scope),''),'governed_publication')
   order by created_at desc,id desc limit 1;
  if p_event_type='revert' and v_prev is null then raise exception 'no publication override to revert' using errcode='22023'; end if;
  select email into v_email from auth.users where id=v_actor;
  insert into pipeline.layer4_publication_decisions(
    entity_type,entity_id,target_scope,event_type,readiness_snapshot,overridden_checks,
    reason_code,comment,actor_id,actor_email,supersedes_decision_id,approval_context
  ) values (
    p_entity_type,p_entity_id,coalesce(nullif(trim(p_target_scope),''),'governed_publication'),p_event_type,
    coalesce(p_readiness_snapshot,'{}'),coalesce(p_overridden_checks,'[]'),trim(p_reason_code),
    nullif(trim(coalesce(p_comment,'')),''),v_actor,v_email,v_prev,coalesce(p_approval_context,'{}')
  ) returning id into v_id;
  return jsonb_build_object('ok',true,'publication_decision_id',v_id,'event_type',p_event_type,'publication_status_changed',false,'consumer_cutover_authorised',false);
end $$;


ALTER FUNCTION "l4_api"."publication_decide"("p_entity_type" "text", "p_entity_id" "uuid", "p_target_scope" "text", "p_event_type" "text", "p_readiness_snapshot" "jsonb", "p_overridden_checks" "jsonb", "p_reason_code" "text", "p_comment" "text", "p_approval_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."publication_state"("p_entity_type" "text", "p_entity_id" "uuid", "p_target_scope" "text" DEFAULT 'governed_publication'::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'l4_api', 'security', 'auth'
    AS $$ select security.layer4_publication_state_read(p_entity_type,p_entity_id,p_target_scope) $$;


ALTER FUNCTION "l4_api"."publication_state"("p_entity_type" "text", "p_entity_id" "uuid", "p_target_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pim_api"."manual_pim_candidate_decide"("p_candidate_id" "uuid", "p_action" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'security', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_rank int; v_status text;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<5 then raise exception 'PIM Operator role required' using errcode='42501'; end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'decision reason required' using errcode='22023'; end if;
  v_status:=case p_action when 'validate' then 'validated' when 'review' then 'needs_review' when 'ready' then 'ready_for_acquisition' when 'reject' then 'rejected' when 'cancel' then 'cancelled' else null end;
  if v_status is null then raise exception 'invalid candidate action' using errcode='22023'; end if;
  update pipeline.pim_source_candidates set status=v_status,decision_reason=trim(p_reason),updated_by=v_actor,updated_at=now() where id=p_candidate_id;
  if not found then raise exception 'candidate not found' using errcode='22023'; end if;
  return jsonb_build_object('ok',true,'candidate_id',p_candidate_id,'status',v_status,'canonical_written',false,'published',false);
end $$;


ALTER FUNCTION "pim_api"."manual_pim_candidate_decide"("p_candidate_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pim_api"."manual_pim_candidate_register"("p_entity_type" "text", "p_target_provider_id" "uuid" DEFAULT NULL::"uuid", "p_source_kind" "text" DEFAULT 'first_party'::"text", "p_external_identifier" "text" DEFAULT NULL::"text", "p_source_url" "text" DEFAULT NULL::"text", "p_evidence_id" "uuid" DEFAULT NULL::"uuid", "p_candidate_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'security', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_rank int; v_id uuid;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<5 then raise exception 'PIM Operator role required' using errcode='42501'; end if;
  if p_entity_type not in ('provider','course','campus','scholarship') then raise exception 'invalid entity type' using errcode='22023'; end if;
  if p_source_kind not in ('authority','first_party') then raise exception 'invalid source kind' using errcode='22023'; end if;
  if p_entity_type in ('course','campus','scholarship') and p_target_provider_id is null then raise exception 'target Provider required' using errcode='22023'; end if;
  if p_evidence_id is null and length(trim(coalesce(p_source_url,'')))<8 then raise exception 'source URL or Evidence required' using errcode='22023'; end if;
  if p_evidence_id is not null and not exists(select 1 from pipeline.evidence_artifacts where id=p_evidence_id) then raise exception 'Evidence not found' using errcode='22023'; end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'reason required' using errcode='22023'; end if;
  insert into pipeline.pim_source_candidates(entity_type,target_provider_id,source_kind,external_identifier,source_url,evidence_id,candidate_payload,reason,created_by,updated_by)
  values(p_entity_type,p_target_provider_id,p_source_kind,nullif(trim(coalesce(p_external_identifier,'')),''),nullif(trim(coalesce(p_source_url,'')),''),p_evidence_id,coalesce(p_candidate_payload,'{}'::jsonb),trim(p_reason),v_actor,v_actor)
  returning id into v_id;
  return jsonb_build_object('ok',true,'candidate_id',v_id,'status','submitted','canonical_written',false,'published',false);
exception when unique_violation then
  raise exception 'matching active source-backed candidate already exists' using errcode='23505';
end $$;


ALTER FUNCTION "pim_api"."manual_pim_candidate_register"("p_entity_type" "text", "p_target_provider_id" "uuid", "p_source_kind" "text", "p_external_identifier" "text", "p_source_url" "text", "p_evidence_id" "uuid", "p_candidate_payload" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pim_api"."manual_pim_candidates_read"("p_status" "text" DEFAULT NULL::"text", "p_entity_type" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'security', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_rank int; v_items jsonb;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<5 then raise exception 'PIM Operator role required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) into v_items
  from (
    select id,entity_type,target_provider_id,source_kind,external_identifier,source_url,evidence_id,candidate_payload,status,reason,decision_reason,created_by,created_at,updated_by,updated_at
    from pipeline.pim_source_candidates
    where (p_status is null or status=p_status) and (p_entity_type is null or entity_type=p_entity_type)
    order by created_at desc limit least(greatest(coalesce(p_limit,100),1),200)
  ) x;
  return jsonb_build_object('items',v_items);
end $$;


ALTER FUNCTION "pim_api"."manual_pim_candidates_read"("p_status" "text", "p_entity_type" "text", "p_limit" integer) OWNER TO "postgres";


