CREATE OR REPLACE FUNCTION "pipeline"."layer2_carry_forward_discovery_candidates"("p_new_version" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_new pipeline.layer2_source_profile_versions; v_old pipeline.layer2_source_profile_versions; v_n integer:=0;
begin
  select * into v_new from pipeline.layer2_source_profile_versions where id=p_new_version;
  if not found then return 0; end if;
  select * into v_old from pipeline.layer2_source_profile_versions
   where profile_id=v_new.profile_id and version_no<v_new.version_no order by version_no desc limit 1;
  if not found then return 0; end if;
  if (v_new.configuration->'discovery_strategy') is distinct from (v_old.configuration->'discovery_strategy')
     or (v_new.configuration->'url_patterns') is distinct from (v_old.configuration->'url_patterns') then return 0; end if;
  if exists (select 1 from pipeline.layer2_course_discovery_candidates where source_profile_version_id=v_new.id) then return 0; end if;
  insert into pipeline.layer2_course_discovery_candidates(trial_course_id,course_id,source_profile_version_id,provider_attempt_id,evidence_id,
         discovered_url,discovered_title,discovered_regulatory_code,match_score,match_basis,status,selected,blocker,created_at)
  select c.trial_course_id,c.course_id,v_new.id,c.provider_attempt_id,c.evidence_id,c.discovered_url,c.discovered_title,c.discovered_regulatory_code,
         c.match_score,coalesce(c.match_basis,'{}'::jsonb)||jsonb_build_object('carried_forward_from_version',v_old.id,'carried_forward_at',now()),
         c.status,c.selected,c.blocker,c.created_at
    from pipeline.layer2_course_discovery_candidates c where c.source_profile_version_id=v_old.id;
  get diagnostics v_n=row_count;
  return v_n;
end $$;


ALTER FUNCTION "pipeline"."layer2_carry_forward_discovery_candidates"("p_new_version" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer2_course_decision_context_snapshot"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pipeline', 'catalogue', 'public'
    AS $$
select jsonb_build_object(
 'course_id',c.id,
 'qilt_provider', case when exists(select 1 from catalogue.provider_outcomes po where po.provider_id=c.provider_id and coalesce(po.status,'active')='active') then 'present' else 'not_available' end,
 'qilt_study_area', case when exists(select 1 from catalogue.provider_outcomes po where po.provider_id=c.provider_id and po.external_study_area_id is not null and coalesce(po.status,'active')='active') then 'present' else 'not_available' end,
 'prisms_provider', case when exists(select 1 from catalogue.student_flow_observations sf where sf.provider_id=c.provider_id and coalesce(sf.status,'active')='active') then 'present' else 'not_available' end,
 'prisms_state', case when exists(select 1 from catalogue.student_flow_observations sf where sf.subdivision_id is not null and coalesce(sf.status,'active')='active') then 'present' else 'not_available' end,
 'context_is_course_grain', false
)
from catalogue.courses c where c.id=p_course_id;
$$;


ALTER FUNCTION "pipeline"."layer2_course_decision_context_snapshot"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer2_course_factual_snapshot"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pipeline', 'catalogue', 'public'
    AS $$
select jsonb_build_object(
  'course_id', c.id,
  'identity', case when c.stable_key is not null and c.provider_id is not null and coalesce(c.canonical_title,c.display_title) is not null then 'present' else 'ambiguous' end,
  'course_url', case when coalesce(c.course_url,(select cl.url from catalogue.course_links cl where cl.link_type = 'official_course' and cl.course_id=c.id and coalesce(cl.status,'active')='active' order by cl.is_primary desc nulls last, cl.created_at desc limit 1)) is not null then 'present' else 'not_yet_enriched' end,
  'provider_current_tuition', case when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.audience='international' and f.fee_type='provider_current_tuition' and coalesce(f.status,'active')='active') then 'present' else 'not_yet_enriched' end,
  'intakes', case when exists(select 1 from catalogue.course_intakes i where i.course_id=c.id and coalesce(i.status,'active')='active') then 'present' else 'not_yet_enriched' end,
  'english_requirements', case when exists(select 1 from catalogue.course_english_requirements e where e.course_id=c.id and coalesce(e.status,'active')='active') then 'present' else 'not_yet_enriched' end,
  'campus_delivery', case when exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.id) then 'present' else 'not_yet_enriched' end,
  'description', case when nullif(btrim(c.description),'') is not null then 'present' else 'not_yet_enriched' end,
  'verification', case when c.last_verified_at is null then 'not_yet_enriched' when c.last_verified_at < now()-interval '180 days' then 'stale' else 'present' end
)
from catalogue.courses c where c.id=p_course_id;
$$;


ALTER FUNCTION "pipeline"."layer2_course_factual_snapshot"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer2_evidence_version_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_job_version uuid;
begin
  if new.job_id is not null then
    select source_profile_version_id into v_job_version from pipeline.jobs where id=new.job_id;
    if v_job_version is not null then
      if new.source_profile_version_id is null then new.source_profile_version_id:=v_job_version;
      elsif new.source_profile_version_id<>v_job_version then raise exception 'Evidence configuration version does not match Job configuration version' using errcode='23514';
      end if;
    end if;
  end if;
  return new;
end
$$;


ALTER FUNCTION "pipeline"."layer2_evidence_version_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer2_provider_trial_summary"("p_trial_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pipeline'
    AS $$
select coalesce(jsonb_agg(x order by (x->>'cost_per_resolved_field_usd')::numeric nulls last,(x->>'resolution_rate')::numeric desc),'[]'::jsonb)
from (
 select jsonb_build_object(
   'provider_id',r.acquisition_provider_id,'provider_key',max(ap.provider_key),'attempted_rows',count(*),
   'acquisition_success_rate',round((count(*) filter(where r.acquisition_success is true))::numeric/nullif(count(*),0),4),
   'deterministic_success_rate',round((count(*) filter(where r.deterministic_extraction_success is true))::numeric/nullif(count(*),0),4),
   'correct_rate',round((count(*) filter(where r.correctness_status='correct'))::numeric/nullif(count(*) filter(where r.correctness_status in ('correct','incorrect')),0),4),
   'fields_targeted',sum(r.fields_targeted),'fields_resolved',sum(r.fields_resolved),
   'resolution_rate',round(sum(r.fields_resolved)::numeric/nullif(sum(r.fields_targeted),0),4),
   'vendor_units',sum(coalesce(r.vendor_units,0)),'vendor_cost_usd',case when count(*) filter(where r.vendor_cost_usd is null)>0 then null else sum(r.vendor_cost_usd) end,
   'cost_per_resolved_field_usd',case when count(*) filter(where r.vendor_cost_usd is null)>0 then null else round(sum(r.vendor_cost_usd)/nullif(sum(r.fields_resolved),0),6) end,
   'avg_latency_ms',round(avg(r.latency_ms) filter(where r.latency_ms is not null),1),
   'layer3_escalation_rate',round((count(*) filter(where r.layer3_required))::numeric/nullif(count(*),0),4),
   'layer4_escalation_rate',round((count(*) filter(where r.layer4_required))::numeric/nullif(count(*),0),4),
   'avg_evidence_quality',round(avg(r.evidence_quality_score),4)
 ) x
 from pipeline.layer2_provider_trial_results r join pipeline.layer2_acquisition_providers ap on ap.id=r.acquisition_provider_id
 where r.trial_id=p_trial_id group by r.acquisition_provider_id
) s$$;


ALTER FUNCTION "pipeline"."layer2_provider_trial_summary"("p_trial_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer2_route_scope_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_domain text; v_target text; v_enabled boolean;
begin
  select domain,target_entity_type,enabled into v_domain,v_target,v_enabled
  from pipeline.layer2_source_profiles where id=new.profile_id;
  if v_domain is null then raise exception 'Layer 2 source profile not found' using errcode='23503'; end if;
  if not (
    (v_domain='course_facts' and v_target='course_fact')
    or (v_domain='scholarship' and v_target='scholarship')
    or (v_domain='provider_asset' and v_target='provider_asset')
  ) then
    raise exception 'Layer 2 acquisition routes are limited to Course, Scholarship and Provider Asset enrichment; QILT/PRISMS remain Layer 1' using errcode='23514';
  end if;
  if not coalesce(v_enabled,false) then
    raise exception 'Layer 2 source profile is not enabled' using errcode='23514';
  end if;
  return new;
end $$;


ALTER FUNCTION "pipeline"."layer2_route_scope_guard"() OWNER TO "postgres";


