CREATE TABLE IF NOT EXISTS "pipeline"."layer3_model_profiles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "code" "text" NOT NULL,
    "aggregator_provider" "text" NOT NULL,
    "base_url" "text" NOT NULL,
    "model_identifier" "text" NOT NULL,
    "secret_env_key" "text" NOT NULL,
    "allowed_task_classes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "prompt_profile_version" "text" NOT NULL,
    "prompt_system" "text" NOT NULL,
    "structured_output_schema" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "deterministic_validators" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "max_input_tokens" integer NOT NULL,
    "max_output_tokens" integer NOT NULL,
    "requests_per_minute" integer NOT NULL,
    "requests_per_day" integer NOT NULL,
    "retry_ceiling" integer DEFAULT 1 NOT NULL,
    "timeout_ms" integer DEFAULT 30000 NOT NULL,
    "fallback_profile_id" "uuid",
    "cost_ceiling_usd" numeric(12,6) DEFAULT 0 NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "paused" boolean DEFAULT true NOT NULL,
    "last_validation_result" "jsonb",
    "quality_benchmark" "jsonb",
    "change_control_ref" "text" NOT NULL,
    "uat_ref" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "retired_at" timestamp with time zone,
    "retired_reason" "text",
    "holdout_qualification" "jsonb",
    CONSTRAINT "layer3_model_profiles_base_url_check" CHECK (("base_url" ~* '^https://'::"text")),
    CONSTRAINT "layer3_model_profiles_check" CHECK ((("fallback_profile_id" IS NULL) OR ("fallback_profile_id" <> "id"))),
    CONSTRAINT "layer3_model_profiles_cost_ceiling_usd_check" CHECK (("cost_ceiling_usd" >= (0)::numeric)),
    CONSTRAINT "layer3_model_profiles_max_input_tokens_check" CHECK ((("max_input_tokens" >= 128) AND ("max_input_tokens" <= 2000000))),
    CONSTRAINT "layer3_model_profiles_max_output_tokens_check" CHECK ((("max_output_tokens" >= 32) AND ("max_output_tokens" <= 200000))),
    CONSTRAINT "layer3_model_profiles_requests_per_day_check" CHECK ((("requests_per_day" >= 1) AND ("requests_per_day" <= 10000000))),
    CONSTRAINT "layer3_model_profiles_requests_per_minute_check" CHECK ((("requests_per_minute" >= 1) AND ("requests_per_minute" <= 100000))),
    CONSTRAINT "layer3_model_profiles_retry_ceiling_check" CHECK ((("retry_ceiling" >= 0) AND ("retry_ceiling" <= 10))),
    CONSTRAINT "layer3_model_profiles_timeout_ms_check" CHECK ((("timeout_ms" >= 1000) AND ("timeout_ms" <= 180000)))
);


ALTER TABLE "pipeline"."layer3_model_profiles" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."layer3_model_profiles" IS 'M2.4 Layer 3 model profiles. A16 international-contact profile uses retry_ceiling=2 only after immutable benchmark evidence showed malformed structured output; profile remains disabled until dedicated contact benchmark PASS.';



COMMENT ON COLUMN "pipeline"."layer3_model_profiles"."retired_at" IS 'CF-247 model routing: when the profile was retired (disabled and paused, kept for audit).';



COMMENT ON COLUMN "pipeline"."layer3_model_profiles"."holdout_qualification" IS 'CF-247 model routing: latest fresh-holdout qualification (layer3-model-routing).';



CREATE OR REPLACE FUNCTION "pipeline"."layer3_routed_profile"("p_task_class" "text") RETURNS "pipeline"."layer3_model_profiles"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select p.* from pipeline.layer3_model_profiles p
   where p_task_class=any(p.allowed_task_classes) and p.enabled and not p.paused and p.retired_at is null
     and coalesce((p.quality_benchmark->>'pass')::boolean,false) and coalesce((p.holdout_qualification->>'pass')::boolean,false)
   order by p.updated_at desc limit 1
$$;


ALTER FUNCTION "pipeline"."layer3_routed_profile"("p_task_class" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."platform_edge_call_log_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin
  begin
    if new.url like '%/functions/v1/%' then
      insert into pipeline.platform_edge_calls(id,function_name,created_at)
      values (new.id, left(split_part(split_part(split_part(new.url,'/functions/v1/',2),'?',1),'/',1),120), now())
      on conflict (id) do update set function_name=excluded.function_name, created_at=excluded.created_at;
    end if;
  exception when others then null;  -- never block an outbound call because of the health log
  end;
  return null;
end $$;


ALTER FUNCTION "pipeline"."platform_edge_call_log_trg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."resolve_regulatory_sources"("p_country_code" "text") RETURNS TABLE("source_id" "uuid", "source_type" "text", "source_label" "text", "source_url" "text", "trust_rank" smallint, "system_code" "text", "system_name" "text", "system_type" "text", "system_base_url" "text", "system_config" "jsonb", "source_metadata" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'integration', 'ref'
    AS $$
  select
    s.id,
    s.source_type,
    s.label,
    s.url,
    s.trust_rank,
    i.code,
    i.name,
    i.system_type,
    i.base_url,
    i.config,
    s.metadata
  from ref.countries c
  join pipeline.sources s on s.country_id = c.id and s.provider_id is null
  left join integration.systems i on i.id = s.system_id
  where upper(c.iso_alpha2::text) = upper(p_country_code)
    and s.status = 'active'
    and coalesce(i.status, 'active') = 'active'
  order by s.trust_rank asc, s.label asc;
$$;


ALTER FUNCTION "pipeline"."resolve_regulatory_sources"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."scholarship_candidate_semantic_terminal_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $_$
declare
  v_title text:=lower(trim(replace(replace(replace(coalesce(new.observed_title,''),'&amp;','&'),'&#x2019;','’'),'&#x27;','''')));
  v_url text:=lower(coalesce(nullif(new.detail_target_url,''),nullif(new.scholarship_url,''),''));
begin
  if v_title ~ '(terms? and conditions|terms? & conditions|conditions of award|scholarship conditions|award conditions)'
     or v_url ~ '(terms[-_% ]?and[-_% ]?conditions|term[-_% ]?conditions|conditions[-_% ]?of[-_% ]?award|scholarship[-_% ]?conditions)'
     or (v_url ~ '\.pdf([?#].*)?$' and v_title ~ '(terms?|conditions|policy|guidelines?)') then
    new.classification:='support_or_navigation';
    new.classification_reason:='CF-220 supporting terms/conditions document retained as Evidence; not an individual Scholarship detail';
    new.classified_at:=now();
  elsif v_title ~ '^(search|about us|learn more|scholarships? & grants|academic scholarships|external scholarships|scholarships and fees|financial aid for international students|domestic student scholarships|prestigious.*scholarships|home country sponsored scholarships)$'
     or v_url ~ '/search\.html([?#].*)?$'
     or v_url ~ '/about-us(\.html)?([?#].*)?$'
     or v_url ~ '/scholarships/domestic/?([?#].*)?$'
     or v_url ~ '/home-country-sponsored-scholarships/?([?#].*)?$' then
    new.classification:='support_or_navigation';
    new.classification_reason:='CF-191 semantic terminal guard: navigation, collection, domestic or support page is not an individual international Scholarship';
    new.classified_at:=now();
  elsif v_title ~ '^(scholarships?|scholarships? & grants|scholarships? for international students|international scholarships?)$'
        or v_url ~ '/scholarships/?([?#].*)?$' then
    new.classification:='catalogue_or_filter';
    new.classification_reason:='CF-191 semantic terminal guard: Scholarship catalogue root retained as Evidence only';
    new.classified_at:=now();
  end if;
  return new;
end
$_$;


ALTER FUNCTION "pipeline"."scholarship_candidate_semantic_terminal_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."svc_invoke_evidence_link_index"("p_limit" integer DEFAULT 60) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'vault', 'net', 'public'
    AS $$
declare v_key text; v_base text; v_id bigint;
begin
  v_key := public.svc_pilot_issue_nonce('evidence-link-index')::text; v_base := public.coursefinder_runtime_edge_base_url();
  if v_key is null or v_base is null then raise exception 'runtime automation secret or Edge base URL missing'; end if;
  select net.http_post(url:=rtrim(v_base,'/')||'/evidence-link-index',
    headers:=jsonb_build_object('content-type','application/json','x-cf-run-nonce',v_key),
    body:=jsonb_build_object('limit',p_limit), timeout_milliseconds:=120000) into v_id;
  return v_id;
end $$;


ALTER FUNCTION "pipeline"."svc_invoke_evidence_link_index"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."svc_layer2_provider_probe_result"("p_request_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'net', 'public', 'extensions'
    AS $$
declare v_probe record;v_rec net._http_response;v_headers jsonb;v_body text;v_credit numeric;v_remaining numeric;v_fixed numeric;v_is_json boolean;begin
 select * into v_probe from pipeline.layer2_provider_probe_requests where request_id=p_request_id;if not found then raise exception 'probe request not found';end if;
 select * into v_rec from net._http_response where id=p_request_id;if not found then return jsonb_build_object('ok',false,'pending',true,'request_id',p_request_id,'provider_key',v_probe.provider_key,'profile_key',v_probe.profile_key);end if;
 if v_rec.error_msg is not null then return jsonb_build_object('ok',false,'pending',false,'request_id',p_request_id,'provider_key',v_probe.provider_key,'profile_key',v_probe.profile_key,'error_class','transport','message',v_rec.error_msg,'elapsed_ms',round(extract(epoch from(v_rec.created-v_probe.started_at))*1000)::int);end if;
 v_headers:=v_rec.headers;v_body:=v_rec.content;v_is_json:=coalesce(v_headers->>'content-type',v_headers->>'Content-Type','') ilike '%json%';
 begin v_credit:=coalesce(nullif(v_headers->>'Scrape.do-Request-Cost','')::numeric,nullif(v_headers->>'scrape.do-request-cost','')::numeric);exception when invalid_text_representation then v_credit:=null;end;
 begin v_remaining:=coalesce(nullif(v_headers->>'Scrape.do-Remaining-Credits','')::numeric,nullif(v_headers->>'scrape.do-remaining-credits','')::numeric);exception when invalid_text_representation then v_remaining:=null;end;
 select nullif(request_template->>'fixed_credit_units','')::numeric into v_fixed from pipeline.layer2_acquisition_providers where provider_key=v_probe.provider_key;v_credit:=coalesce(v_credit,v_fixed);
 return jsonb_build_object('ok',v_rec.status_code between 200 and 299,'pending',false,'request_id',p_request_id,'provider_key',v_probe.provider_key,'profile_key',v_probe.profile_key,'http_status',v_rec.status_code,'elapsed_ms',round(extract(epoch from(v_rec.created-v_probe.started_at))*1000)::int,'content_type',coalesce(v_headers->>'content-type',v_headers->>'Content-Type'),'response_bytes',octet_length(coalesce(v_body,'')),'vendor_units',v_credit,'remaining_vendor_units',v_remaining,'body_sha256',encode(digest(coalesce(v_body,''),'sha256'),'hex'),'json_success',case when v_is_json then coalesce((v_body::jsonb->>'success')::boolean,true) else null end,'has_markdown',case when v_is_json then coalesce(length(v_body::jsonb#>>'{data,markdown}')>0,false) else null end,'has_html',case when v_is_json then coalesce(length(v_body::jsonb#>>'{data,html}')>0,false) else v_rec.status_code between 200 and 299 end,'has_screenshot',case when v_is_json then coalesce(length(v_body::jsonb#>>'{data,screenshot}')>0,false) else null end);
exception when others then return jsonb_build_object('ok',false,'pending',false,'request_id',p_request_id,'provider_key',coalesce(v_probe.provider_key,'unknown'),'error_class','result_parse','message',sqlerrm);end$$;


ALTER FUNCTION "pipeline"."svc_layer2_provider_probe_result"("p_request_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."svc_layer2_provider_probe_start"("p_profile_key" "text", "p_provider_key" "text", "p_target_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'vault', 'net', 'public'
    AS $$
declare v_cfg jsonb;v_provider record;v_secret text;v_host text;v_allowed boolean:=false;v_req bigint;v_url text;v_params jsonb:='{}';v_body jsonb:='{}';v_headers jsonb:='{}';begin
 select v.configuration into v_cfg from pipeline.layer2_source_profiles p join pipeline.layer2_source_profile_versions v on v.id=p.current_version_id where p.profile_key=p_profile_key and p.enabled and not p.paused and v.validation_status='valid';
 if v_cfg is null then raise exception 'executable source profile not found';end if;
 v_host:=lower(split_part(split_part(p_target_url,'://',2),'/',1));if v_host='' then raise exception 'invalid target url';end if;
 select exists(select 1 from jsonb_array_elements_text(coalesce(v_cfg->'url_patterns','[]'::jsonb)) x where lower(split_part(split_part(x,'://',2),'/',1))=v_host or v_host like '%.'||lower(split_part(split_part(x,'://',2),'/',1))) or lower(split_part(split_part(coalesce(v_cfg->>'base_domain',''),'://',2),'/',1))=v_host into v_allowed;
 if not v_allowed then raise exception 'target url outside source profile boundary';end if;
 select p.* into v_provider from pipeline.layer2_acquisition_providers p join pipeline.layer2_profile_provider_routes r on r.acquisition_provider_id=p.id join pipeline.layer2_source_profiles sp on sp.id=r.profile_id where sp.profile_key=p_profile_key and p.provider_key=p_provider_key and p.enabled and r.enabled;
 if not found then raise exception 'provider is not an enabled route for profile';end if;
 if v_provider.auth_scheme<>'none' then select decrypted_secret into v_secret from vault.decrypted_secrets where id=v_provider.vault_secret_id;if v_secret is null then raise exception 'provider credential missing';end if;end if;
 if v_provider.adapter_type='direct_http' then v_req:=net.http_get(p_target_url,'{}',jsonb_build_object('User-Agent','CourseFinder Layer2 bounded probe/1.1'),least(v_provider.timeout_seconds*1000,120000));
 elsif v_provider.provider_key='firecrawl' then v_body:=coalesce(v_provider.request_template->'static_body','{}')||jsonb_build_object(coalesce(v_provider.request_template->>'target_url_field','url'),p_target_url);v_headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_secret);v_req:=net.http_post(v_provider.base_url,v_body,'{}',v_headers,least(v_provider.timeout_seconds*1000,120000));
 else v_url:=v_provider.base_url;v_params:=coalesce(v_provider.request_template->'static_query','{}')||jsonb_build_object(coalesce(v_provider.request_template->>'target_url_parameter','url'),p_target_url);if v_provider.auth_scheme='query_param' then v_params:=v_params||jsonb_build_object(coalesce(v_provider.auth_field_name,'token'),v_secret);elsif v_provider.auth_scheme='bearer' then v_headers:=jsonb_build_object('Authorization','Bearer '||v_secret);elsif v_provider.auth_scheme='header' then v_headers:=jsonb_build_object(coalesce(v_provider.auth_field_name,'X-API-Key'),v_secret);end if;v_req:=net.http_get(v_url,v_params,v_headers,least(v_provider.timeout_seconds*1000,120000));end if;
 insert into pipeline.layer2_provider_probe_requests(request_id,profile_key,provider_key,target_url) values(v_req,p_profile_key,p_provider_key,p_target_url);
 return jsonb_build_object('ok',true,'request_id',v_req,'profile_key',p_profile_key,'provider_key',p_provider_key,'queued_at',now());
end$$;


ALTER FUNCTION "pipeline"."svc_layer2_provider_probe_start"("p_profile_key" "text", "p_provider_key" "text", "p_target_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."svc_pilot_invoke_edge"("p_function" "text", "p_body" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'vault', 'net', 'public'
    AS $$ declare v_key text;v_id bigint;v_base text; begin if p_function not in('layer3-work-dispatch','layer1-ca-ab-alis-degrees','layer1-ca-bc-epbc-programs','layer1-ca-qc-university-programs','layer1-ca-sk-programs','layer1-ca-mb-programs','layer1-ca-ns-sk-programs','layer1-ca-cna-programs','layer1-ca-firstparty-catalogues','layer1-ca-provider-geography','layer1-ca-on-college-programs','layer1-ca-algonquin-catalogue','layer1-ca-conestoga-catalogue','layer1-ca-fanshawe-pgwp','layer1-ca-mohawk-catalogue','layer1-ca-durham-programs') then raise exception 'Edge function is not allowlisted';end if; v_key:=public.svc_pilot_issue_nonce(p_function)::text;v_base:=public.coursefinder_runtime_edge_base_url(); if v_key is null then raise exception 'runtime automation secret missing';end if; if v_base is null then raise exception 'runtime Edge base URL missing';end if; select net.http_post(url:=rtrim(v_base,'/')||'/'||p_function,headers:=jsonb_build_object('content-type','application/json','x-cf-run-nonce',v_key),body:=coalesce(p_body,'{}'::jsonb),timeout_milliseconds:=30000) into v_id; perform pipeline.edge_request_note(v_id, p_function, p_body->>'mode'); return v_id; end $$;


