CREATE OR REPLACE FUNCTION "pipeline"."svc_pilot_submit_nonce"("p_function" "text", "p_body" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'net', 'public', 'extensions'
    AS $$ declare v_nonce uuid:=extensions.gen_random_uuid();v_id bigint;v_base text; begin if not exists(select 1 from pipeline.pilot_nonce_functions f where f.function_name=p_function) then raise exception 'one-time Edge function is not allowlisted';end if; insert into pipeline.pilot_edge_nonces(id,function_name,expires_at) values(v_nonce,p_function,now()+interval '5 minutes'); v_base:=public.coursefinder_runtime_edge_base_url(); if v_base is null then raise exception 'runtime Edge base URL missing';end if; select net.http_post(url:=rtrim(v_base,'/')||'/'||p_function,headers:=jsonb_build_object('content-type','application/json','x-cf-run-nonce',v_nonce::text),body:=coalesce(p_body,'{}'::jsonb),timeout_milliseconds:=case when p_function='layer3-work-dispatch' then 300000 else 120000 end) into v_id; perform pipeline.edge_request_note(v_id, p_function, p_body->>'mode'); return v_id; end $$;


ALTER FUNCTION "pipeline"."svc_pilot_submit_nonce"("p_function" "text", "p_body" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."svc_prisms_apply_observations"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'catalogue', 'ref', 'public', 'extensions'
    AS $$
declare
  r jsonb;
  v_changed integer:=0;
  v_seen integer:=0;
  v_rc integer;
  v_country uuid;
  v_survey uuid;
  v_source pipeline.sources%rowtype;
  v_provider uuid;
  v_course uuid;
  v_area uuid;
  v_field uuid;
  v_suppressed boolean;
  v_value bigint;
  v_suppression_code text;
begin
  if p_rows is null or jsonb_typeof(p_rows)<>'array' then
    raise exception 'p_rows must be a JSON array';
  end if;
  if jsonb_array_length(p_rows)>5000 then
    raise exception 'bounded apply limit exceeded';
  end if;

  select id into v_country from ref.countries where iso_alpha2='AU';
  select id into v_survey from ref.outcome_surveys
  where code='prisms_international_students' and source_family='PRISMS' and status='active';

  for r in select value from jsonb_array_elements(p_rows)
  loop
    v_seen:=v_seen+1;
    v_provider:=nullif(r->>'provider_id','')::uuid;
    v_course:=nullif(r->>'course_id','')::uuid;
    v_area:=nullif(r->>'external_study_area_id','')::uuid;
    v_field:=nullif(r->>'field_of_study_id','')::uuid;
    v_suppressed:=coalesce((r->>'is_suppressed')::boolean,false);
    v_value:=nullif(r->>'metric_value','')::bigint;
    v_suppression_code:=nullif(r->>'suppression_code','');

    if (r->>'host_country_id')::uuid is distinct from v_country then
      raise exception 'PRISMS observation host country must be AU';
    end if;
    if (r->>'survey_id')::uuid is distinct from v_survey then
      raise exception 'PRISMS observation survey is invalid';
    end if;
    if not exists(
      select 1 from ref.outcome_metrics m
      where m.id=(r->>'metric_id')::uuid and m.survey_id=v_survey and m.status='active'
    ) then
      raise exception 'PRISMS observation metric is invalid';
    end if;
    if coalesce(nullif(r->>'audience',''),'international') <> 'international' then
      raise exception 'PRISMS observation audience must be international';
    end if;
    if nullif(r->>'source_observation_key','') is null then
      raise exception 'PRISMS source observation key is required';
    end if;
    if (not v_suppressed and (v_value is null or v_value < 0 or v_suppression_code is not null))
       or (v_suppressed and (v_value is not null or v_suppression_code is null)) then
      raise exception 'PRISMS observation must contain either an exact non-negative count or an explicit suppression marker';
    end if;

    select * into v_source from pipeline.sources where id=(r->>'source_id')::uuid;
    if v_source.id is null
       or v_source.country_id is distinct from v_country
       or coalesce(v_source.metadata->>'source_system','') <> 'PRISMS'
       or coalesce(v_source.metadata->>'identity_authority','true') <> 'false' then
      raise exception 'PRISMS observation source is invalid';
    end if;
    if not exists(
      select 1 from pipeline.evidence_artifacts e
      where e.id=(r->>'evidence_id')::uuid
        and e.source_id=v_source.id
        and e.evidence_type='prisms_published_workbook'
    ) then
      raise exception 'PRISMS observation evidence is invalid';
    end if;

    if v_provider is not null then
      if coalesce(v_source.metadata->>'published_provider_dimension','false') <> 'true' then
        raise exception 'source does not publish a Provider dimension';
      end if;
      if not exists(
        select 1 from catalogue.providers p
        join ref.countries c on c.id=p.country_id
        where p.id=v_provider and c.iso_alpha2='AU'
      ) then
        raise exception 'PRISMS Provider target must be an existing AU CRICOS Provider';
      end if;
    end if;

    if v_course is not null then
      if coalesce(v_source.metadata->>'published_course_dimension','false') <> 'true' then
        raise exception 'source does not publish a Course dimension';
      end if;
      if v_provider is null or not exists(
        select 1 from catalogue.courses co
        join catalogue.providers p on p.id=co.provider_id
        join ref.countries c on c.id=p.country_id
        where co.id=v_course and co.provider_id=v_provider and c.iso_alpha2='AU'
      ) then
        raise exception 'PRISMS Course target must be an existing AU CRICOS Course under the mapped Provider';
      end if;
    end if;

    if nullif(r->>'subdivision_id','') is not null and not exists(
      select 1 from ref.subdivisions s
      where s.id=(r->>'subdivision_id')::uuid
        and s.country_id=v_country
        and s.status='active'
    ) then
      raise exception 'PRISMS subdivision must be an active AU subdivision';
    end if;

    if v_area is not null and not exists(
      select 1 from ref.external_study_areas esa
      where esa.id=v_area and esa.source_system='PRISMS' and esa.status='active'
    ) then
      raise exception 'PRISMS external study area is invalid';
    end if;

    if v_field is not null and not exists(
      select 1 from ref.external_study_area_mappings eam
      where eam.external_study_area_id=v_area
        and eam.field_of_study_id=v_field
        and eam.status='active'
    ) then
      raise exception 'canonical field requires an active governed PRISMS study-area mapping';
    end if;

    if nullif(r->>'study_level_id','') is not null and not exists(
      select 1 from ref.study_levels sl
      where sl.id=(r->>'study_level_id')::uuid and sl.status='active'
    ) then
      raise exception 'PRISMS study level is invalid';
    end if;

    insert into catalogue.student_flow_observations(
      host_country_id,provider_id,course_id,subdivision_id,
      external_study_area_id,field_of_study_id,study_level_id,
      survey_id,metric_id,audience,period_start,period_end,period_type,
      source_geography_type,source_geography_key,source_geography_name,
      source_remoteness_area,source_sector_code,source_provider_type,
      source_nationality_code,source_nationality_name,
      source_study_area_code,source_study_area_name,source_observation_key,
      metric_value,is_suppressed,suppression_code,
      source_id,evidence_id,observed_at,status,metadata
    )
    values(
      v_country,v_provider,v_course,nullif(r->>'subdivision_id','')::uuid,
      v_area,v_field,nullif(r->>'study_level_id','')::uuid,
      v_survey,(r->>'metric_id')::uuid,'international',
      (r->>'period_start')::date,(r->>'period_end')::date,
      coalesce(nullif(r->>'period_type',''),'ytd'),
      nullif(r->>'source_geography_type',''),
      nullif(r->>'source_geography_key',''),
      nullif(r->>'source_geography_name',''),
      nullif(r->>'source_remoteness_area',''),
      nullif(r->>'source_sector_code',''),
      nullif(r->>'source_provider_type',''),
      nullif(r->>'source_nationality_code',''),
      nullif(r->>'source_nationality_name',''),
      nullif(r->>'source_study_area_code',''),
      nullif(r->>'source_study_area_name',''),
      r->>'source_observation_key',
      v_value,v_suppressed,v_suppression_code,
      v_source.id,(r->>'evidence_id')::uuid,
      coalesce(nullif(r->>'observed_at','')::timestamptz,now()),
      coalesce(nullif(r->>'status',''),'current'),
      coalesce(r->'metadata','{}'::jsonb)
    )
    on conflict(source_id,source_observation_key)
    do update set
      provider_id=excluded.provider_id,
      course_id=excluded.course_id,
      subdivision_id=excluded.subdivision_id,
      external_study_area_id=excluded.external_study_area_id,
      field_of_study_id=excluded.field_of_study_id,
      study_level_id=excluded.study_level_id,
      audience=excluded.audience,
      period_start=excluded.period_start,
      period_end=excluded.period_end,
      period_type=excluded.period_type,
      source_geography_type=excluded.source_geography_type,
      source_geography_key=excluded.source_geography_key,
      source_geography_name=excluded.source_geography_name,
      source_remoteness_area=excluded.source_remoteness_area,
      source_sector_code=excluded.source_sector_code,
      source_provider_type=excluded.source_provider_type,
      source_nationality_code=excluded.source_nationality_code,
      source_nationality_name=excluded.source_nationality_name,
      source_study_area_code=excluded.source_study_area_code,
      source_study_area_name=excluded.source_study_area_name,
      metric_value=excluded.metric_value,
      is_suppressed=excluded.is_suppressed,
      suppression_code=excluded.suppression_code,
      evidence_id=excluded.evidence_id,
      observed_at=excluded.observed_at,
      status=excluded.status,
      metadata=excluded.metadata,
      updated_at=now()
    where (
      catalogue.student_flow_observations.provider_id,
      catalogue.student_flow_observations.course_id,
      catalogue.student_flow_observations.subdivision_id,
      catalogue.student_flow_observations.external_study_area_id,
      catalogue.student_flow_observations.field_of_study_id,
      catalogue.student_flow_observations.study_level_id,
      catalogue.student_flow_observations.audience,
      catalogue.student_flow_observations.period_start,
      catalogue.student_flow_observations.period_end,
      catalogue.student_flow_observations.period_type,
      catalogue.student_flow_observations.source_geography_type,
      catalogue.student_flow_observations.source_geography_key,
      catalogue.student_flow_observations.source_geography_name,
      catalogue.student_flow_observations.source_remoteness_area,
      catalogue.student_flow_observations.source_sector_code,
      catalogue.student_flow_observations.source_provider_type,
      catalogue.student_flow_observations.source_nationality_code,
      catalogue.student_flow_observations.source_nationality_name,
      catalogue.student_flow_observations.source_study_area_code,
      catalogue.student_flow_observations.source_study_area_name,
      catalogue.student_flow_observations.metric_value,
      catalogue.student_flow_observations.is_suppressed,
      catalogue.student_flow_observations.suppression_code,
      catalogue.student_flow_observations.evidence_id,
      catalogue.student_flow_observations.status,
      catalogue.student_flow_observations.metadata
    ) is distinct from (
      excluded.provider_id,
      excluded.course_id,
      excluded.subdivision_id,
      excluded.external_study_area_id,
      excluded.field_of_study_id,
      excluded.study_level_id,
      excluded.audience,
      excluded.period_start,
      excluded.period_end,
      excluded.period_type,
      excluded.source_geography_type,
      excluded.source_geography_key,
      excluded.source_geography_name,
      excluded.source_remoteness_area,
      excluded.source_sector_code,
      excluded.source_provider_type,
      excluded.source_nationality_code,
      excluded.source_nationality_name,
      excluded.source_study_area_code,
      excluded.source_study_area_name,
      excluded.metric_value,
      excluded.is_suppressed,
      excluded.suppression_code,
      excluded.evidence_id,
      excluded.status,
      excluded.metadata
    );

    get diagnostics v_rc=row_count;
    v_changed:=v_changed+v_rc;
  end loop;

  return jsonb_build_object('seen',v_seen,'changed',v_changed);
end
$$;


ALTER FUNCTION "pipeline"."svc_prisms_apply_observations"("p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."svc_qilt_apply_observations"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'catalogue', 'ref', 'public', 'extensions'
    AS $$
declare
  r jsonb; v_changed integer:=0; v_seen integer:=0; v_rc integer;
begin
  if p_rows is null or jsonb_typeof(p_rows)<>'array' then raise exception 'p_rows must be a JSON array'; end if;
  if jsonb_array_length(p_rows)>5000 then raise exception 'bounded apply limit exceeded'; end if;
  for r in select value from jsonb_array_elements(p_rows) loop
    v_seen:=v_seen+1;
    if not exists(select 1 from catalogue.providers p join ref.countries c on c.id=p.country_id where p.id=(r->>'provider_id')::uuid and c.iso_alpha2='AU') then
      raise exception 'QILT observation provider is not canonical AU CRICOS provider'; end if;
    if not exists(select 1 from ref.outcome_surveys s where s.id=(r->>'survey_id')::uuid and s.source_family='QILT' and s.status='active') then
      raise exception 'QILT observation survey is invalid'; end if;
    if not exists(select 1 from pipeline.source_provider_mappings m where m.source_id=(r->>'source_id')::uuid and m.source_entity_key=r->>'source_institution_key' and m.status='verified' and (m.provider_id=(r->>'provider_id')::uuid or (coalesce((m.metadata->>'statistical_equivalence_fanout')::boolean,false) and coalesce(m.metadata->'equivalent_provider_ids','[]'::jsonb) ? (r->>'provider_id')))) then
      raise exception 'QILT observation lacks verified source-to-CRICOS mapping'; end if;

    insert into catalogue.provider_outcomes(
      provider_id,survey_id,metric_id,external_study_area_id,study_level_id,audience,source_cohort_code,
      collection_year_from,collection_year_to,metric_value,response_count,confidence_low,confidence_high,
      national_benchmark,source_id,evidence_id,source_institution_key,source_study_area_code,source_metric_code,
      observed_at,status,metadata
    ) values (
      (r->>'provider_id')::uuid,(r->>'survey_id')::uuid,(r->>'metric_id')::uuid,
      nullif(r->>'external_study_area_id','')::uuid,nullif(r->>'study_level_id','')::uuid,
      coalesce(nullif(r->>'audience',''),'all'),coalesce(nullif(r->>'source_cohort_code',''),'ALL'),
      (r->>'collection_year_from')::smallint,(r->>'collection_year_to')::smallint,
      nullif(r->>'metric_value','')::numeric,nullif(r->>'response_count','')::integer,
      nullif(r->>'confidence_low','')::numeric,nullif(r->>'confidence_high','')::numeric,
      nullif(r->>'national_benchmark','')::numeric,(r->>'source_id')::uuid,nullif(r->>'evidence_id','')::uuid,
      r->>'source_institution_key',nullif(r->>'source_study_area_code',''),r->>'source_metric_code',
      coalesce(nullif(r->>'observed_at','')::timestamptz,now()),coalesce(nullif(r->>'status',''),'current'),coalesce(r->'metadata','{}'::jsonb)
    )
    on conflict (
      provider_id,survey_id,metric_id,
      (coalesce(external_study_area_id,'00000000-0000-0000-0000-000000000000'::uuid)),
      (coalesce(study_level_id,'00000000-0000-0000-0000-000000000000'::uuid)),
      audience,source_cohort_code,collection_year_from,collection_year_to,source_id
    ) do update set
      metric_value=excluded.metric_value,response_count=excluded.response_count,
      confidence_low=excluded.confidence_low,confidence_high=excluded.confidence_high,
      national_benchmark=excluded.national_benchmark,evidence_id=excluded.evidence_id,
      source_institution_key=excluded.source_institution_key,source_study_area_code=excluded.source_study_area_code,
      source_metric_code=excluded.source_metric_code,observed_at=excluded.observed_at,status=excluded.status,
      metadata=excluded.metadata,updated_at=now()
    where (catalogue.provider_outcomes.metric_value,catalogue.provider_outcomes.response_count,
           catalogue.provider_outcomes.confidence_low,catalogue.provider_outcomes.confidence_high,
           catalogue.provider_outcomes.national_benchmark,catalogue.provider_outcomes.evidence_id,
           catalogue.provider_outcomes.source_institution_key,catalogue.provider_outcomes.source_study_area_code,
           catalogue.provider_outcomes.source_metric_code,catalogue.provider_outcomes.status,catalogue.provider_outcomes.metadata)
      is distinct from
          (excluded.metric_value,excluded.response_count,excluded.confidence_low,excluded.confidence_high,
           excluded.national_benchmark,excluded.evidence_id,excluded.source_institution_key,excluded.source_study_area_code,
           excluded.source_metric_code,excluded.status,excluded.metadata);
    get diagnostics v_rc=row_count; v_changed:=v_changed+v_rc;
  end loop;
  return jsonb_build_object('seen',v_seen,'changed',v_changed);
end $$;


ALTER FUNCTION "pipeline"."svc_qilt_apply_observations"("p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."sync_layer1_statistical_edition"("p_source_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'ref', 'catalogue'
    AS $$
declare v pipeline.sources%rowtype; v_family_code text; v_family pipeline.layer1_dataset_families%rowtype;
        v_key text; v_year integer; v_start date; v_end date; v_count bigint; v_prior uuid;
begin
 select * into v from pipeline.sources where id=p_source_id;
 if v.id is null then return; end if;
 if upper(coalesce(v.metadata->>'source_system',v.metadata->>'publisher','')) not in ('QILT','PRISMS') then return; end if;
 v_family_code:=case
   when v.metadata->>'survey_code'='qilt_gos' then 'au_qilt_gos'
   when v.metadata->>'survey_code'='qilt_ses' then 'au_qilt_ses'
   when v.metadata->>'survey_code'='qilt_gosl' then 'au_qilt_gosl'
   when v.metadata->>'survey_code'='qilt_ess' then 'au_qilt_ess'
   when upper(coalesce(v.metadata->>'source_system',''))='PRISMS' then 'au_prisms_student_flow'
 end;
 if v_family_code is null then return; end if;
 select * into v_family from pipeline.layer1_dataset_families where family_code=v_family_code;
 v_key:=coalesce(v.metadata->>'collection_version',v.metadata->>'edition_year',substring(v.label from '(20[0-9]{2}(?:-[0-9]{2})?)'),'unknown');
 v_year:=case when v_key ~ '^20[0-9]{2}' then substring(v_key from 1 for 4)::integer else null end;
 v_start:=nullif(v.metadata->>'period_start','')::date;
 v_end:=nullif(v.metadata->>'period_end','')::date;
 if v_family.source_system='QILT' then select count(*)::bigint into v_count from catalogue.provider_outcomes where source_id=v.id;
 else select count(*)::bigint into v_count from catalogue.student_flow_observations where source_id=v.id; end if;

 insert into pipeline.layer1_dataset_editions(family_id,source_id,edition_key,edition_year,period_start,period_end,status,observation_count,last_verified_at,metadata)
 values(v_family.id,v.id,v_key,v_year,v_start,v_end,'retained',v_count,coalesce(v.last_success_at,v.last_checked_at),
        jsonb_build_object('retained_for_comparison',true,'identity_authority',false))
 on conflict(source_id) do update set edition_key=excluded.edition_key,edition_year=excluded.edition_year,period_start=excluded.period_start,period_end=excluded.period_end,
 observation_count=excluded.observation_count,last_verified_at=excluded.last_verified_at,metadata=pipeline.layer1_dataset_editions.metadata||excluded.metadata;

 select f.current_source_id into v_prior from pipeline.layer1_dataset_families f where f.id=v_family.id;
 if v_prior is null or not exists(
   select 1 from pipeline.layer1_dataset_editions cur join pipeline.layer1_dataset_editions neu on neu.source_id=v.id
   where cur.source_id=v_prior and neu.family_id=cur.family_id
     and coalesce(neu.period_end,make_date(coalesce(neu.edition_year,0),12,31),date '0001-01-01')
         <= coalesce(cur.period_end,make_date(coalesce(cur.edition_year,0),12,31),date '0001-01-01')
 ) then
   update pipeline.layer1_dataset_editions set status='retained' where family_id=v_family.id and source_id<>v.id and status='current';
   update pipeline.layer1_dataset_editions set status='current' where source_id=v.id;
   update pipeline.layer1_dataset_families set current_source_id=v.id,updated_at=now() where id=v_family.id;
   update pipeline.sources set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('edition_status','retained','retain_for_comparison',true) where id=v_prior and v_prior is not null;
   update pipeline.sources set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('dataset_family_code',v_family.family_code,'dataset_family_label',v_family.label,'edition_key',v_key,'edition_year',v_year,'edition_status','current','retain_for_comparison',true) where id=v.id;

   if not exists(select 1 from pipeline.layer1_source_operations where source_id=v.id) then
     insert into pipeline.layer1_source_operations(
       source_id,authority_name,authority_domains,expected_format,expected_count_kind,active,paused,
       verification_cadence_days,ingestion_cadence_days,variance_warn_percent,variance_block_percent,
       previous_accepted_count,last_expected_count,last_verified_at,verification_status,verification_message,
       variance_percent,variance_decision,next_verification_at,next_ingestion_at,change_reason,updated_at
     )
     select v.id,o.authority_name,o.authority_domains,o.expected_format,'observations',true,false,
       o.verification_cadence_days,o.ingestion_cadence_days,o.variance_warn_percent,o.variance_block_percent,
       v_count,v_count,coalesce(v.last_success_at,v.last_checked_at),'passed',
       'New statistical edition registered automatically; retained editions remain available for comparison.',
       0,'pass',now()+(o.verification_cadence_days||' days')::interval,
       now()+(coalesce(o.ingestion_cadence_days,30)||' days')::interval,
       'CF-CHG-20260902-067 automatic statistical edition rollover',now()
     from pipeline.layer1_source_operations o where o.source_id=v_prior
     limit 1;
   end if;

   if v_prior is not null and not exists(select 1 from pipeline.refresh_policies where layer=1 and source_id=v.id) then
     insert into pipeline.refresh_policies(
       country_code,layer,source_profile_id,entity_type,entity_id,freshness_class,cadence_interval,next_due_at,
       hash_sensitive,important_date_sensitive,enabled,change_control_ref,updated_at,source_id
     )
     select country_code,layer,source_profile_id,entity_type,entity_id,freshness_class,cadence_interval,
       now()+cadence_interval,hash_sensitive,important_date_sensitive,enabled,'CF-CHG-20260902-067',now(),v.id
     from pipeline.refresh_policies where layer=1 and source_id=v_prior
     order by updated_at desc limit 1;
     update pipeline.refresh_policies set enabled=false,updated_at=now(),change_control_ref='CF-CHG-20260902-067'
     where layer=1 and source_id=v_prior;
   end if;
 end if;
end $$;


ALTER FUNCTION "pipeline"."sync_layer1_statistical_edition"("p_source_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."trg_layer1_seen_departures"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_res jsonb;
begin
  if new.status='completed' and old.status is distinct from 'completed' and new.mode='apply'
     and exists (select 1 from pipeline.layer1_source_operations o where o.source_id=new.source_id and o.seen_tracking_since is not null) then
    begin
      v_res:=security.layer1_seen_departures_v1(new.id,false,null);
    exception when others then
      v_res:=jsonb_build_object('status','failed','error',left(sqlerrm,300));
    end;
    update pipeline.layer1_run_queue set result=coalesce(result,'{}'::jsonb)||jsonb_build_object('departures',v_res) where id=new.id;
  end if;
  return null;
end $$;


