CREATE OR REPLACE FUNCTION "public"."admin_adapter_autobuild"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_reason text := btrim(coalesce(p_args->>'reason', ''));
        v_today int; v_cap int; v_id uuid; v jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'PIM Operator or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'states' then
    select coalesce(jsonb_object_agg(x.id, security.adapter_autobuild_state_v1(x.id::uuid)), '{}'::jsonb) into v
      from (select distinct jsonb_array_elements_text(coalesce(p_args->'provider_ids', '[]'::jsonb)) id limit 200) x;
    return v;
  end if;
  if p_action = 'read' then
    return security.adapter_autobuild_state_v1(v_pid) || jsonb_build_object('can_manage', v_rank >= 6,
      'today', (select count(*) from pipeline.adapter_autobuilds b where (b.created_at at time zone 'Australia/Melbourne')::date = (now() at time zone 'Australia/Melbourne')::date),
      'per_day', (security.firecrawl_setting('autobuild_per_day') #>> '{}')::int,
      'model', security.firecrawl_setting('builder_model') #>> '{}');
  end if;
  if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'start' then
    if not exists (select 1 from catalogue.providers where id = v_pid) then raise exception 'unknown provider'; end if;
    if exists (select 1 from pipeline.uni_adapters u where u.provider_id = v_pid and u.admit) then raise exception 'this provider already has an admitting adapter: change it in the builder instead'; end if;
    if exists (select 1 from pipeline.adapter_autobuilds b where b.provider_id = v_pid and b.status not in ('done', 'failed', 'stopped')) then raise exception 'a build is already running for this provider'; end if;
    v_today := (select count(*) from pipeline.adapter_autobuilds b where (b.created_at at time zone 'Australia/Melbourne')::date = (now() at time zone 'Australia/Melbourne')::date);
    v_cap := coalesce((security.firecrawl_setting('autobuild_per_day') #>> '{}')::int, 25);
    if v_today >= v_cap then raise exception 'the automatic builds for today are used (% of %). It is a setting under Adapter builder', v_today, v_cap; end if;
    insert into pipeline.adapter_autobuilds(provider_id, credits_cap, requested_by, reason, note)
    values (v_pid, coalesce((security.firecrawl_setting('autobuild_credits') #>> '{}')::int, 150), auth.uid(), v_reason, 'Waiting to start (within 2 minutes).')
    returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_autobuild_start', v_pid::text, jsonb_build_object('build_id', v_id, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'build_id', v_id);
  elsif p_action = 'stop' then
    update pipeline.adapter_autobuilds set status = 'stopped', note = 'Stopped by a Platform Admin: ' || v_reason, updated_at = now()
     where provider_id = v_pid and status not in ('done', 'failed', 'stopped') returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_autobuild_stop', v_pid::text, jsonb_build_object('build_id', v_id, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', v_id is not null);
  end if;
  raise exception 'unknown action';
end $$;


ALTER FUNCTION "public"."admin_adapter_autobuild"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapter_builder"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_reason text := btrim(coalesce(p_args->>'reason', ''));
        v_id uuid; v_d pipeline.uni_adapter_drafts%rowtype; v_n int; v_b jsonb; v_samples jsonb; v_m jsonb; v_s jsonb; v_cid uuid; v_code text;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  if p_action = 'read' then
    return jsonb_build_object('budget', security.adapter_builder_budget(), 'can_manage', v_rank >= 6,
      'model', security.adapter_builder_model_for_v1(v_pid), 'models', case when v_rank >= 6 then security.adapter_builder_models_v1() else '[]'::jsonb end,
      'max_samples', 10,
      'pages', case when v_rank >= 6 then coalesce((select jsonb_agg(jsonb_build_object('course', x.title, 'code', x.code, 'url', x.url, 'read', x.read_status = 'read') order by x.title) from (
                 select distinct on (pg.url) coalesce(c.display_title, c.canonical_title) title, pg.url, pg.read_status,
                        (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = pg.course_id and lower(cr.scheme) = 'cricos' limit 1) code
                   from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id
                  where pg.provider_id = v_pid and pg.url is not null limit 600) x), '[]'::jsonb) else '[]'::jsonb end,
      'drafts', coalesce((select jsonb_agg(to_jsonb(d) order by d.created_at desc) from (select * from pipeline.uni_adapter_drafts where provider_id = v_pid order by created_at desc limit 3) d), '[]'::jsonb));
  end if;
  if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'model' then
    if not exists (select 1 from catalogue.providers where id = v_pid) then raise exception 'unknown provider'; end if;
    v_code := nullif(btrim(coalesce(p_args->>'profile_code', '')), '');
    if v_code is null then
      delete from pipeline.uni_adapter_models where provider_id = v_pid;
    else
      if not exists (select 1 from jsonb_array_elements(security.adapter_builder_models_v1()) x where x->>'code' = v_code) then
        raise exception 'that model is not enabled and qualified for intake work (Models & services)';
      end if;
      insert into pipeline.uni_adapter_models(provider_id, profile_code, set_by, reason) values (v_pid, v_code, auth.uid(), v_reason)
        on conflict (provider_id) do update set profile_code = excluded.profile_code, set_by = excluded.set_by, set_at = now(), reason = excluded.reason;
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_builder_model', v_pid::text, jsonb_build_object('profile_code', v_code, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'model', security.adapter_builder_model_for_v1(v_pid));
  end if;
  if p_action = 'start' then
    v_n := least(greatest(coalesce((security.firecrawl_setting('builder_samples') #>> '{}')::int, 6), 1), 10);
    select coalesce(jsonb_agg(jsonb_build_object('course_id', x.course_id, 'course', x.title, 'code', x.code, 'url', x.url, 'kind', x.kind) order by x.kr, x.kind), '[]'::jsonb) into v_samples from (
      select q.*, row_number() over (partition by q.kind order by random()) kr from (
        select distinct on (pg.url) pg.course_id, coalesce(c.display_title, c.canonical_title) title, (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = pg.course_id and lower(cr.scheme) = 'cricos' limit 1) code, pg.url,
               case when coalesce(c.display_title, c.canonical_title) ~* '/|, bachelor|and bachelor|double' then 'double'
                    when coalesce(c.display_title, c.canonical_title) ~* 'master|graduate|doctor|postgrad' then 'postgraduate'
                    when coalesce(c.display_title, c.canonical_title) ~* 'certificate|diploma' then 'certificate or diploma'
                    else 'undergraduate' end kind
          from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id and c.lifecycle_status in ('active', 'inactive')
         where pg.provider_id = v_pid and pg.read_status = 'read' and pg.url is not null) q
      order by kr, kind limit v_n) x;
    if jsonb_array_length(coalesce(v_samples, '[]'::jsonb)) = 0 then raise exception 'no confirmed course page for this university yet - find pages first'; end if;
    insert into pipeline.uni_adapter_drafts(provider_id, samples, reason, created_by) values (v_pid, v_samples, v_reason, auth.uid()) returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_builder_start', v_pid::text, jsonb_build_object('draft_id', v_id, 'samples', v_samples, 'reason', v_reason), auth.uid());
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_capture', 'draft_id', v_id));
    return jsonb_build_object('ok', true, 'draft_id', v_id);
  end if;
  if p_action = 'add_sample' then
    v_cid := nullif(p_args->>'course_id', '')::uuid;
    select jsonb_build_object('course_id', pg.course_id, 'course', coalesce(c.display_title, c.canonical_title),
             'code', (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = pg.course_id and lower(cr.scheme) = 'cricos' limit 1),
             'url', pg.url, 'kind', 'chosen'), pg.provider_id
      into v_s, v_pid
      from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id
     where pg.url is not null and (pg.course_id = v_cid or (v_cid is null and pg.provider_id = v_pid and pg.url = nullif(p_args->>'url', '')))
     order by (pg.read_status = 'read') desc limit 1;
    if v_s is null then raise exception 'this course has no stored page to sample'; end if;
    select * into v_d from pipeline.uni_adapter_drafts where provider_id = v_pid order by created_at desc limit 1;
    if v_d.id is not null and v_d.status in ('capturing', 'proposing') then raise exception 'the current samples are still being captured or proposed; try again in a minute'; end if;
    if v_d.id is null then
      insert into pipeline.uni_adapter_drafts(provider_id, samples, reason, created_by) values (v_pid, jsonb_build_array(v_s), v_reason, auth.uid()) returning id into v_id;
    else
      if exists (select 1 from jsonb_array_elements(v_d.samples) x where x->>'url' = v_s->>'url') then raise exception 'this page is already a sample'; end if;
      if jsonb_array_length(v_d.samples) >= 10 then raise exception 'a draft holds at most 10 samples: capture new samples to start again'; end if;
      update pipeline.uni_adapter_drafts set samples = samples || jsonb_build_array(v_s), status = 'capturing', updated_at = now() where id = v_d.id;
      v_id := v_d.id;
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_builder_add_sample', v_pid::text, jsonb_build_object('draft_id', v_id, 'sample', v_s, 'reason', v_reason), auth.uid());
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_capture', 'draft_id', v_id));
    return jsonb_build_object('ok', true, 'draft_id', v_id);
  end if;
  select * into v_d from pipeline.uni_adapter_drafts where id = (p_args->>'draft_id')::uuid;
  if v_d.id is null then raise exception 'unknown draft'; end if;
  if p_action = 'marks' then
    if jsonb_typeof(coalesce(p_args->'marks', '[]'::jsonb)) <> 'array' then raise exception 'marks must be a list'; end if;
    update pipeline.uni_adapter_drafts set marks = coalesce(p_args->'marks', '[]'::jsonb), comments = left(coalesce(p_args->>'comments', ''), 4000), updated_at = now() where id = v_d.id;
    return jsonb_build_object('ok', true);
  elsif p_action = 'propose' then
    if jsonb_array_length(v_d.captures) = 0 then raise exception 'capture the sample pages first'; end if;
    v_b := security.adapter_builder_budget();
    if (v_b->>'used_usd')::numeric >= (v_b->>'limit_usd')::numeric then raise exception 'the AI allowance for today is used (US$ % of %). It is a setting under Adapter builder', v_b->>'used_usd', v_b->>'limit_usd'; end if;
    if (v_b->>'proposals')::int >= (v_b->>'limit_proposals')::int then raise exception 'the proposals for today are used (% of %). It is a setting under Adapter builder', v_b->>'proposals', v_b->>'limit_proposals'; end if;
    v_m := security.adapter_builder_model_for_v1(v_d.provider_id);
    update pipeline.uni_adapter_drafts set status = 'proposing', marks = coalesce(p_args->'marks', marks), comments = coalesce(left(p_args->>'comments', 4000), comments), model = v_m->>'model', model_profile = v_m->>'code', updated_at = now() where id = v_d.id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_builder_propose', v_d.provider_id::text, jsonb_build_object('draft_id', v_d.id, 'budget', v_b, 'model', v_m), auth.uid());
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_propose', 'draft_id', v_d.id));
    return jsonb_build_object('ok', true);
  end if;
  raise exception 'unknown action';
end $_$;


ALTER FUNCTION "public"."admin_adapter_builder"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapter_builder_basics"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_pid uuid; v_q text; v jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'PIM Operator or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'search' then
    v_q := btrim(coalesce(p_args->>'q', ''));
    if length(v_q) < 2 then return jsonb_build_object('providers', '[]'::jsonb); end if;
    select coalesce(jsonb_agg(x order by x->>'name'), '[]'::jsonb) into v from (
      select jsonb_build_object('provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'website', p.website,
               'country', (select k.iso_alpha2 from ref.countries k where k.id = p.country_id),
               'courses', (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active'),
               'adapter', (select case when not u.enabled then 'off' when u.admit then 'admitting' else 'testing' end from pipeline.uni_adapters u where u.provider_id = p.id)) x
        from catalogue.providers p
       where p.lifecycle_status = 'active' and (coalesce(p.display_name, p.canonical_name) ilike '%' || v_q || '%' or p.website ilike '%' || v_q || '%')
       order by (exists (select 1 from pipeline.uni_adapters u where u.provider_id = p.id)) desc, coalesce(p.display_name, p.canonical_name) limit 20) s;
    return jsonb_build_object('providers', v);
  end if;
  if p_action <> 'basics' then raise exception 'unknown action'; end if;
  v_pid := nullif(p_args->>'provider_id', '')::uuid;
  if not exists (select 1 from catalogue.providers where id = v_pid) then raise exception 'unknown provider'; end if;
  select jsonb_build_object(
    'provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'website', p.website,
    'country', (select k.iso_alpha2 from ref.countries k where k.id = p.country_id),
    'courses', (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active'),
    'pages', (select jsonb_build_object('stored', count(*), 'read', count(*) filter (where pg.read_status = 'read'),
                                        'needs_render', count(*) filter (where pg.read_status in ('needs_render', 'blocked')))
                from pipeline.coverage_course_pages pg where pg.provider_id = p.id),
    'adapter', (select jsonb_build_object('enabled', u.enabled, 'admit', u.admit, 'admit_fields', u.admit_fields, 'notes', left(coalesce(u.notes, ''), 600),
                                          'updated_at', u.updated_at, 'patterns', (select count(*) from jsonb_object_keys(coalesce(u.patterns, '{}'::jsonb))),
                                          'json_paths', (select count(*) from jsonb_object_keys(coalesce(u.json_paths, '{}'::jsonb))))
                  from pipeline.uni_adapters u where u.provider_id = p.id),
    'qualify', case when exists (select 1 from pipeline.uni_adapters u where u.provider_id = p.id) then security.adapter_qualify_one_v1(p.id, 0.5, 0.9) end,
    'central', (select coalesce(jsonb_agg(jsonb_build_object('kind', f.kind, 'url', f.url, 'status', f.status, 'found_via', f.found_via,
                         'decision', f.decision) order by f.kind, f.rank, f.updated_at desc), '[]'::jsonb)
                  from pipeline.provider_fact_sources f where f.provider_id = p.id and f.status not in ('failed', 'no_values')),
    'suggested', (select coalesce(jsonb_agg(jsonb_build_object('kind', s.kind, 'url', s.url, 'title', s.title)), '[]'::jsonb) from (
                    select k.kind, u.url, u.title, row_number() over (partition by k.kind order by length(u.url)) rn
                      from pipeline.coverage_provider_urls u
                      cross join lateral (select case
                               when u.url ~* '(key-?dates|academic-?calendar|semester-?dates|term-?dates|important-?dates|principal-?dates)' then 'intake_calendar'
                               when u.url ~* '(international.*(fee|tuition)|(fee|tuition).*international|fee-?schedule|tuition-?fees)' then 'fee_schedule'
                               when u.url ~* '(english-?language-?requirement|english-?requirement|english-?proficiency)' then 'english_policy' end kind) k
                     where u.provider_id = p.id and k.kind is not null
                       and not exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = p.id and f.kind = k.kind and f.url = u.url)) s where s.rn <= 3),
    'can_manage', v_rank >= 6)
    into v from catalogue.providers p where p.id = v_pid;
  return v;
end $$;


ALTER FUNCTION "public"."admin_adapter_builder_basics"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapter_evaluation"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_np numeric; v_ur numeric; v_fs numeric;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  v_np := coalesce((security.firecrawl_setting('eval_no_page_share') #>> '{}')::numeric, 0.3);
  v_ur := coalesce((security.firecrawl_setting('eval_unreadable_share') #>> '{}')::numeric, 0.2);
  v_fs := coalesce((security.firecrawl_setting('eval_field_share') #>> '{}')::numeric, 0.5);
  return jsonb_build_object('settings', jsonb_build_object('no_page_share', v_np, 'unreadable_share', v_ur, 'field_share', v_fs),
    'universities', coalesce((select jsonb_agg(x order by (x->>'gap')::int desc) from (
      select jsonb_build_object('provider_id', c.provider_id, 'name', c.name, 'country', c.country, 'courses', s.courses, 'confirmed', s.confirmed, 'no_page', s.no_page, 'unreadable', s.unreadable,
               'intakes', s.intakes, 'english', s.english,
               'adapter', case when a.provider_id is null then 'none' when a.admit then 'admitting' when a.enabled then 'testing' else 'off' end,
               'gap', greatest(s.courses - s.intakes, 0) + greatest(s.courses - s.english, 0),
               'next', case when a.admit and a.enabled then 'admitting'
                            when s.courses > 0 and s.no_page::numeric / s.courses >= v_np then 'find_pages'
                            when s.courses > 0 and s.unreadable::numeric / s.courses >= v_ur then 'adapter_page_data'
                            when s.confirmed > 0 and s.intakes::numeric / s.confirmed < v_fs then 'adapter_intakes'
                            when s.confirmed > 0 and s.english::numeric / s.confirmed < v_fs then 'adapter_english'
                            else 'admit_as_is' end) x
      from pipeline.firecrawl_target_cache c
      cross join lateral (select coalesce((c.stats->>'courses')::int, 0) courses, coalesce((c.stats->>'confirmed')::int, 0) confirmed, coalesce((c.stats->>'no_page')::int, 0) no_page,
                                 coalesce((c.stats->>'unreadable')::int, 0) unreadable, coalesce((c.stats->>'intakes')::int, 0) intakes, coalesce((c.stats->>'english')::int, 0) english) s
      left join pipeline.uni_adapters a on a.provider_id = c.provider_id
      where c.included) q), '[]'::jsonb),
    'figures_at', (select max(c.stats_at) from pipeline.firecrawl_target_cache c));
end $$;


ALTER FUNCTION "public"."admin_adapter_evaluation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapter_measures"("p_provider_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if current_user <> 'postgres' and (auth.uid() is null or coalesce(v_rank, 0) < 5) then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(x order by x->>'name') from (
    select jsonb_build_object('provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'country', security.coverage_country(p.id),
      'adapter', (select case when not u.enabled then 'off' when u.admit then 'admitting' else 'testing' end from pipeline.uni_adapters u where u.provider_id = p.id),
      'pages_read', count(*),
      'intakes', count(*) filter (where q.ia), 'intakes_agree', count(*) filter (where q.ia and q.held_itk = q.ad_itk), 'intakes_differ', count(*) filter (where q.ia and q.held_itk is not null and q.held_itk <> q.ad_itk), 'intakes_new', count(*) filter (where q.ia and q.held_itk is null),
      'fees', count(*) filter (where q.fa), 'fees_equal', count(*) filter (where q.fa and q.fee_held), 'fees_differ', count(*) filter (where q.fa and not q.fee_held and q.any_fee), 'fees_new', count(*) filter (where q.fa and not q.any_fee),
      'ielts', count(*) filter (where q.ea), 'extra', count(*) filter (where q.xa)) x
    from catalogue.providers p
    join lateral (
      select pg.candidates->>'intakes_by' = 'adapter' ia, pg.candidates->>'fee_by' = 'adapter' fa, pg.candidates->>'english_by' = 'adapter' ea, pg.candidates ? 'adapter_extra' xa,
             (select array_agg(distinct m order by m) from jsonb_array_elements_text(coalesce(pg.candidates->'intakes', '[]'::jsonb)) m) ad_itk,
             (select array_agg(distinct i.intake_label order by i.intake_label) from catalogue.course_intakes i where i.course_id = pg.course_id and i.status = 'active') held_itk,
             exists (select 1 from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and f.amount = nullif(pg.candidates->'fee'->>'value', '')::numeric) fee_held,
             exists (select 1 from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international') any_fee
        from pipeline.coverage_course_pages pg where pg.provider_id = p.id and pg.read_status = 'read') q on true
    where p.id = any (p_provider_ids)
    group by p.id) s), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."admin_adapter_measures"("p_provider_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapter_shadow"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_before jsonb; v_after jsonb; v_reason text := btrim(coalesce(p_args->>'reason', ''));
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'summary' then return security.adapter_shadow_summary_v1(); end if;
  if p_action = 'providers' then
    return coalesce((select jsonb_agg(x order by x->>'agreement' nulls last) from (
      select jsonb_build_object('provider_id', d.provider_id, 'provider', pr.name, 'task', d.task, 'compared', count(*),
             'both_found', count(*) filter (where d.shadow_found and d.layer3_found),
             'agreement', round(count(*) filter (where d.agree)::numeric / nullif(count(*) filter (where d.shadow_found and d.layer3_found), 0), 4),
             'shadow_found', count(*) filter (where d.shadow_found), 'layer3_found', count(*) filter (where d.layer3_found)) x
        from pipeline.adapter_shadow_reads d left join catalogue.providers pr on pr.id = d.provider_id
       where d.status = 'done' and (p_args->>'task' is null or d.task = p_args->>'task')
       group by d.provider_id, pr.name, d.task having count(*) >= 5) q), '[]'::jsonb);
  end if;
  if p_action = 'settings' then
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    select to_jsonb(s) into v_before from pipeline.adapter_shadow_settings s where id = 1;
    update pipeline.adapter_shadow_settings set
      enabled = coalesce((p_args->>'enabled')::boolean, enabled),
      daily_usd_max = coalesce((p_args->>'daily_usd_max')::numeric, daily_usd_max),
      daily_reads_max = coalesce((p_args->>'daily_reads_max')::int, daily_reads_max),
      reason = v_reason, updated_by = auth.uid(), updated_at = now()
    where id = 1 returning to_jsonb(adapter_shadow_settings) into v_after;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('adapter_shadow', 'settings', 'phase3', jsonb_build_object('before', v_before, 'after', v_after, 'reason', v_reason), auth.uid());
    return v_after;
  end if;
  raise exception 'action must be summary, providers or settings';
end $$;


ALTER FUNCTION "public"."admin_adapter_shadow"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapters"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid; v_ids uuid[]; v_on boolean; v_days int; v_n int;
        v_pat text := coalesce(security.firecrawl_setting('target_name_pattern') #>> '{}', '(^|[^a-z])universit(y|ies)([^a-z]|$)');
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Operator or above required' using errcode = '42501'; end if;
  if p_action = 'list' then
    return jsonb_build_object('as_at', now(), 'can_manage', v_rank >= 6, 'can_qualify', v_rank >= 5,
      'settings', jsonb_build_object('read_cycle_default', 90, 'read_cycle_min', 7, 'read_cycle_max', 365,
                                     'min_read_share', coalesce(security.firecrawl_setting('eval_field_share'), '0.5'::jsonb), 'min_agree_share', coalesce(security.firecrawl_setting('qualify_agree_share'), '0.9'::jsonb)),
      'adapters', coalesce((
        with t as (select * from security.firecrawl_targets_fast()),
             ids as (select a.provider_id from pipeline.uni_adapters a union select t.provider_id from t where t.included),
             pg as (select g.provider_id, count(*) pages, count(*) filter (where g.read_status = 'read') pages_read, min(g.next_read_at) filter (where g.read_status in ('read', 'identity_mismatch')) next_read, max(g.read_at) last_read
                      from pipeline.coverage_course_pages g where g.provider_id in (select ids.provider_id from ids) group by g.provider_id),
             q as (select distinct on (x.provider_id) x.provider_id, x.job_id, x.measured_at, x.passing, x.pages_read
                     from pipeline.adapter_qualifications x join pipeline.admin_jobs j on j.id = x.job_id and j.kind = 'qualify_adapters' and j.state = 'done'
                    order by x.provider_id, x.measured_at desc)
        select jsonb_agg(jsonb_build_object(
                 'provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'country', k.iso_alpha2, 'state', s.code,
                 'university', coalesce(p.display_name, p.canonical_name) ~* v_pat,
                 'adapter', case when a.provider_id is null then null else jsonb_build_object('state', case when not a.enabled then 'off' when a.admit then 'admitting' else 'testing' end,
                              'fields', case when a.admit then to_jsonb(coalesce(a.admit_fields, '{}')) else '[]'::jsonb end, 'read_cycle_days', a.read_cycle_days, 'updated_at', a.updated_at, 'admit_changed_at', a.admit_changed_at) end,
                 'target', case when t.provider_id is null then null else jsonb_build_object('included', t.included, 'rule_match', t.rule_match, 'override_reason', t.override_reason) end,
                 'pages', coalesce(pg.pages, 0), 'pages_read', coalesce(pg.pages_read, 0), 'next_read', pg.next_read, 'last_read', pg.last_read,
                 'qualify', case when q.provider_id is null then null else jsonb_build_object('job_id', q.job_id, 'at', q.measured_at, 'passing', to_jsonb(q.passing), 'pages_read', q.pages_read) end)
               order by coalesce(p.display_name, p.canonical_name))
          from ids join catalogue.providers p on p.id = ids.provider_id
          left join ref.countries k on k.id = p.country_id left join ref.subdivisions s on s.id = p.subdivision_id
          left join pipeline.uni_adapters a on a.provider_id = p.id left join t on t.provider_id = p.id
          left join pg on pg.provider_id = p.id left join q on q.provider_id = p.id), '[]'::jsonb));
  end if;
  if p_action = 'detail' then
    v_pid := (p_args->>'provider_id')::uuid;
    if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
    return (select jsonb_build_object(
      'provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'country', k.iso_alpha2, 'state', s.code, 'website', p.website,
      'can_manage', v_rank >= 6, 'can_qualify', v_rank >= 5,
      'english_policy', (select jsonb_build_object('status', pp.status, 'style', pp.style, 'url', pp.url, 'decided_at', pp.decided_at)
                         from pipeline.provider_policy_proposals pp where pp.provider_id = p.id and pp.kind = 'english_policy' and pp.status in ('approved', 'proposed', 'no_values')
                         order by (pp.status = 'approved') desc, (pp.status = 'proposed') desc, pp.updated_at desc limit 1),
      'calendar', (select jsonb_build_object('status', pp.status, 'style', pp.style, 'url', pp.url, 'decided_at', pp.decided_at)
                   from pipeline.provider_policy_proposals pp where pp.provider_id = p.id and pp.kind = 'intake_calendar' and pp.status in ('approved', 'proposed', 'no_values')
                   order by (pp.status = 'approved') desc, (pp.status = 'proposed') desc, pp.updated_at desc limit 1),
      'central_pages', (select coalesce(jsonb_agg(jsonb_build_object('kind', x.kind, 'url', x.url, 'status', x.status, 'read_at', x.read_at, 'evidence_id', x.evidence_id) order by x.kind, x.rank desc), '[]'::jsonb)
                        from pipeline.provider_fact_sources x where x.provider_id = p.id and x.found_via = 'manual' and x.kind in ('english_policy', 'intake_calendar')),
      'courses', m.courses, 'pages_read', m.pages_read,
      'intakes', jsonb_build_object('held', m.i_held, 'adapter', m.i_adapter, 'central', m.i_central, 'reader', m.i_reader, 'excluded', m.i_x),
      'english', jsonb_build_object('held', m.e_held, 'adapter', m.e_adapter, 'central', m.e_central, 'reader', m.e_reader, 'excluded', m.e_x),
      'fee', jsonb_build_object('held', m.f_held, 'adapter', m.f_adapter, 'reader', m.f_reader, 'excluded', m.f_x),
      'schedule', (select jsonb_build_object('read_cycle_days', (select a.read_cycle_days from pipeline.uni_adapters a where a.provider_id = p.id), 'read_cycle_default', 90,
                     'next_read', min(g.next_read_at) filter (where g.read_status in ('read', 'identity_mismatch')), 'last_read', max(g.read_at),
                     'due_7_days', count(*) filter (where g.next_read_at < now() + interval '7 days'), 'due_30_days', count(*) filter (where g.next_read_at < now() + interval '30 days'),
                     'by_status', (select coalesce(jsonb_object_agg(z.st, z.n), '{}'::jsonb) from (select coalesce(g2.read_status, 'not_read') st, count(*) n from pipeline.coverage_course_pages g2 where g2.provider_id = p.id group by 1) z))
                   from pipeline.coverage_course_pages g where g.provider_id = p.id),
      'qualifications', (select coalesce(jsonb_agg(jsonb_build_object('job_id', x.job_id, 'title', j.title, 'at', x.measured_at, 'pages_read', x.pages_read, 'fields', x.fields, 'passing', to_jsonb(x.passing)) order by x.measured_at desc), '[]'::jsonb)
                         from (select * from pipeline.adapter_qualifications x where x.provider_id = p.id order by x.measured_at desc limit 5) x join pipeline.admin_jobs j on j.id = x.job_id),
      'tasks', (select coalesce(jsonb_agg(jsonb_build_object('id', j.id, 'kind', j.kind, 'state', j.state, 'title', j.title, 'created_at', j.created_at, 'finished_at', j.finished_at, 'result', j.result, 'error', j.error) order by j.created_at desc), '[]'::jsonb)
                from (select * from pipeline.admin_jobs j where j.scope = p.id::text or coalesce(j.args->'providers', '[]'::jsonb) ? p.id::text or coalesce(j.args->'provider_ids', '[]'::jsonb) ? p.id::text order by j.created_at desc limit 20) j),
      'log', (select coalesce(jsonb_agg(jsonb_build_object('at', e.created_at, 'area', e.area, 'action', e.action, 'detail', e.detail - 'courses', 'by', (select u.email from auth.users u where u.id = e.actor)) order by e.created_at desc), '[]'::jsonb)
              from (select * from pipeline.admin_control_events e where e.target = p.id::text order by e.created_at desc limit 30) e))
      from catalogue.providers p left join ref.countries k on k.id = p.country_id left join ref.subdivisions s on s.id = p.subdivision_id
      cross join lateral (select count(*) courses, count(*) filter (where cf.read_status = 'read') pages_read,
                                 count(*) filter (where cf.intakes_src <> 'missing') i_held, count(*) filter (where cf.intakes_src = 'adapter') i_adapter,
                                 count(*) filter (where cf.intakes_src = 'central') i_central, count(*) filter (where cf.intakes_src = 'reader') i_reader, count(*) filter (where cf.intakes_x) i_x,
                                 count(*) filter (where cf.english_src <> 'missing') e_held, count(*) filter (where cf.english_src = 'adapter') e_adapter,
                                 count(*) filter (where cf.english_src = 'central') e_central, count(*) filter (where cf.english_src = 'reader') e_reader, count(*) filter (where cf.english_x) e_x,
                                 count(*) filter (where cf.fee_src <> 'missing') f_held, count(*) filter (where cf.fee_src = 'adapter') f_adapter,
                                 count(*) filter (where cf.fee_src = 'reader') f_reader, count(*) filter (where cf.fee_x) f_x
                          from security.university_course_fields_v1(p.id) cf) m
     where p.id = v_pid);
  end if;
  if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  v_ids := array(select distinct (x)::uuid from jsonb_array_elements_text(case when jsonb_typeof(p_args->'provider_ids') = 'array' then p_args->'provider_ids' else '[]'::jsonb end) x);
  if cardinality(v_ids) = 0 then raise exception 'choose at least one adapter'; end if;
  if cardinality(v_ids) > 2000 then raise exception 'choose 2000 adapters or fewer at a time'; end if;
  if p_action = 'set_on' then
    v_on := (p_args->>'on')::boolean;
    if v_on is null then raise exception 'say on or off'; end if;
    v_ids := array(select a.provider_id from pipeline.uni_adapters a where a.provider_id = any (v_ids) and a.enabled is distinct from v_on);
    update pipeline.uni_adapters set enabled = v_on, updated_at = now(), updated_by = auth.uid() where provider_id = any (v_ids);
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
      select 'toolsets', 'uni_adapter_switch', x::text, jsonb_build_object('on', v_on, 'reason', v_reason, 'together_with', cardinality(v_ids)), auth.uid() from unnest(v_ids) x;
    return jsonb_build_object('ok', true, 'changed', cardinality(v_ids), 'on', v_on);
  elsif p_action = 'set_cycle' then
    v_days := nullif(p_args->>'days', '')::int;
    if v_days is not null and (v_days < 7 or v_days > 365) then raise exception 'the read cycle is 7 to 365 days, or empty for the default'; end if;
    v_ids := array(select a.provider_id from pipeline.uni_adapters a where a.provider_id = any (v_ids));
    if cardinality(v_ids) = 0 then raise exception 'none of those universities has an adapter'; end if;
    update pipeline.uni_adapters set read_cycle_days = v_days, updated_at = now(), updated_by = auth.uid() where provider_id = any (v_ids);
    update pipeline.coverage_course_pages set next_read_at = read_at + make_interval(days => coalesce(v_days, 90)) where provider_id = any (v_ids) and read_status in ('read', 'identity_mismatch') and read_at is not null and leased_until is null;
    get diagnostics v_n = row_count;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
      select 'toolsets', 'uni_adapter_read_cycle', x::text, jsonb_build_object('days', v_days, 'reason', v_reason, 'together_with', cardinality(v_ids)), auth.uid() from unnest(v_ids) x;
    return jsonb_build_object('ok', true, 'changed', cardinality(v_ids), 'pages_rescheduled', v_n, 'days', v_days);
  end if;
  raise exception 'unknown action';
end $_$;


ALTER FUNCTION "public"."admin_adapters"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_admission_lifecycle_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank() < 5 then raise exception 'PIM Admin role is required' using errcode='42501'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
    'data_type',p.data_type,'label',p.label,'layer',p.layer,'cycle_days',p.cycle_days,'check_days',p.check_days,
    'window_months',p.window_months,'on_demand',p.on_demand,'rationale',p.rationale,
    'profiles', case when p.layer='L2' then (select count(*) from pipeline.layer2_source_profiles sp where sp.enabled
        and sp.domain = case p.data_type when 'course_facts' then 'course_facts' when 'scholarships' then 'scholarship' when 'provider_assets' then 'provider_asset' end) end,
    'aligned', case when p.layer='L2' then (select count(*) from pipeline.layer2_source_profiles sp where sp.enabled and sp.freshness_sla_hours=p.cycle_days*24
        and sp.domain = case p.data_type when 'course_facts' then 'course_facts' when 'scholarships' then 'scholarship' when 'provider_assets' then 'provider_asset' end) end,
    'next_due', case when p.layer='L1' then (select min(o.next_ingestion_at) from pipeline.layer1_source_operations o join pipeline.sources s on s.id=o.source_id
        where (p.data_type='regulatory_register' and (s.label ilike 'CRICOS%' or s.label ilike 'NZQA%')) or (p.data_type='qilt' and s.label ilike 'QILT%')
           or (p.data_type='prisms' and s.label ilike '%PRISMS%') or (p.data_type='rankings' and (s.label ilike 'QS %' or s.label ilike 'Times Higher%'))) end
  ) order by p.layer, p.data_type),'[]'::jsonb) from pipeline.admission_lifecycle_policy p);
end $$;


