CREATE OR REPLACE FUNCTION "public"."admin_campus_create"("p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_p catalogue.providers%rowtype; v_id uuid; v_src uuid;
        v_name text := nullif(btrim(coalesce(p_args->>'name','')),'');
begin
  if auth.uid() is null or v_rank < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
  select * into v_p from catalogue.providers where id = nullif(p_args->>'provider_id','')::uuid;
  if v_p.id is null then raise exception 'choose the university this campus belongs to'; end if;
  if v_name is null then raise exception 'a campus needs a name'; end if;
  if exists (select 1 from catalogue.campuses where provider_id = v_p.id and lower(name) = lower(v_name) and status = 'active') then raise exception 'this university already has a campus with that name'; end if;
  perform set_config('cf.manual_edit', 'on', true);
  select id into v_src from pipeline.sources where source_type = 'manual_entry' limit 1;
  insert into catalogue.campuses(stable_key, provider_id, name, country_id, subdivision_id, city, address_line1, postcode, status, source_id)
  values ('manual:campus:' || extensions.gen_random_uuid(), v_p.id, v_name, v_p.country_id, v_p.subdivision_id,
          nullif(btrim(coalesce(p_args->>'city','')),''), nullif(btrim(coalesce(p_args->>'address_line1','')),''),
          nullif(btrim(coalesce(p_args->>'postcode','')),''), 'active', v_src)
  returning id into v_id;
  perform security.manual_lock_set('campus', v_id, 'name', 'value');
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('campus', v_id, null, 'create', null, p_args, nullif(btrim(coalesce(p_args->>'reason','')),''), auth.uid());
  return jsonb_build_object('id', v_id);
end $$;


ALTER FUNCTION "public"."admin_campus_create"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_campus_edit"("p_campus_id" "uuid", "p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_c catalogue.campuses%rowtype; v_field text := p_args->>'field';
        v_val jsonb := p_args->'value'; v_before jsonb; v_after jsonb; v_src uuid;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  select * into v_c from catalogue.campuses where id = p_campus_id;
  if v_c.id is null then raise exception 'campus not found'; end if;
  perform set_config('cf.manual_edit', 'on', true);
  if p_action = 'set_core' then
    if v_field is null or v_field not in ('name','address_line1','address_line2','city','postcode','phone','website') then raise exception 'this field cannot be edited here'; end if;
    if jsonb_typeof(v_val) = 'string' then v_val := to_jsonb(nullif(btrim(v_val #>> '{}'), '')); end if;
    if v_field = 'name' and (v_val is null or v_val = 'null'::jsonb) then raise exception 'a campus needs a name'; end if;
    if v_field = 'website' and v_val is not null and v_val <> 'null'::jsonb and (v_val #>> '{}') !~* '^https?://[^[:space:]]+\.[^[:space:]]+$' then raise exception 'enter the full address, starting with https://'; end if;
    v_before := to_jsonb(v_c)->v_field;
    select id into v_src from pipeline.sources where source_type = 'manual_entry' limit 1;
    update catalogue.campuses c set name = r.name, address_line1 = r.address_line1, address_line2 = r.address_line2, city = r.city,
           postcode = r.postcode, phone = r.phone, website = r.website, updated_at = now()
      from (select (jsonb_populate_record(x0, jsonb_build_object(v_field, v_val))).* from catalogue.campuses x0 where x0.id = p_campus_id) r
     where c.id = p_campus_id;
    perform security.manual_lock_set('campus', p_campus_id, v_field, 'value');
    v_after := v_val;
  elsif p_action = 'release' then
    select to_jsonb(l) into v_before from pipeline.manual_locks l where entity = 'campus' and entity_id = p_campus_id and field = v_field;
    if v_before is null then raise exception 'nothing to release'; end if;
    delete from pipeline.manual_locks where entity = 'campus' and entity_id = p_campus_id and field = v_field;
  else
    raise exception 'unknown action %', p_action;
  end if;
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('campus', p_campus_id, v_field, p_action, v_before, v_after, nullif(btrim(coalesce(p_args->>'reason','')),''), auth.uid());
  return (select to_jsonb(c) - 'latitude' - 'longitude' || jsonb_build_object('locks',
            (select coalesce(jsonb_object_agg(k.field, k.mode), '{}'::jsonb) from pipeline.manual_locks k where k.entity = 'campus' and k.entity_id = c.id))
            from catalogue.campuses c where c.id = p_campus_id);
end $_$;


ALTER FUNCTION "public"."admin_campus_edit"("p_campus_id" "uuid", "p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalogue_edit_rows"("p_type" "text", "p_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  if coalesce(array_length(p_ids, 1), 0) > 100 then raise exception 'at most 100 rows at a time'; end if;
  if p_type = 'course' then
    return jsonb_build_object('can_edit', v_rank >= 3,
      'english_tests', (select coalesce(jsonb_agg(jsonb_build_object('code', t.code, 'name', t.name) order by t.code), '[]'::jsonb)
                          from ref.english_tests t where t.status = 'active'),
      'rows', (select coalesce(jsonb_object_agg(c.id, jsonb_build_object(
        'display_title', coalesce(c.display_title, c.canonical_title),
        'duration_value', c.duration_value, 'duration_unit', c.duration_unit, 'delivery_mode', c.delivery_mode,
        'official_url', coalesce((select l.url from catalogue.course_links l where l.course_id = c.id and l.link_type = 'official_course'
                                    and l.status = 'active' order by l.is_primary desc, l.updated_at desc limit 1), c.course_url),
        'tuition', (select jsonb_build_object('amount', f.amount, 'fee_year', f.fee_year, 'basis', f.basis, 'currency', f.currency_code)
                      from catalogue.course_fees f where f.course_id = c.id and f.fee_type = 'provider_current_tuition' and f.status = 'active'
                     order by f.fee_year desc nulls last, f.updated_at desc limit 1),
        'intakes', (select coalesce(jsonb_agg(jsonb_build_object('label', i.intake_label, 'year', i.intake_year, 'start_date', i.start_date)
                                     order by i.intake_year nulls last, i.start_date nulls last, i.intake_label), '[]'::jsonb)
                      from catalogue.course_intakes i where i.course_id = c.id and i.status = 'active'),
        'english', (select coalesce(jsonb_agg(jsonb_build_object('test', t.code, 'overall', e.overall_score, 'components', e.component_scores)
                                     order by t.code), '[]'::jsonb)
                      from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id
                     where e.course_id = c.id and e.status = 'active'),
        'locks', (select coalesce(jsonb_object_agg(k.field, k.mode), '{}'::jsonb) from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id))), '{}'::jsonb)
      from catalogue.courses c where c.id = any(p_ids)));
  elsif p_type = 'provider' then
    return jsonb_build_object('can_edit', v_rank >= 3, 'rows', (select coalesce(jsonb_object_agg(p.id, jsonb_build_object(
        'display_name', coalesce(p.display_name, p.canonical_name), 'primary_city', p.primary_city, 'website', p.website,
        'phone', p.phone, 'email', p.email,
        'locks', (select coalesce(jsonb_object_agg(k.field, k.mode), '{}'::jsonb) from pipeline.manual_locks k where k.entity = 'provider' and k.entity_id = p.id))), '{}'::jsonb)
      from catalogue.providers p where p.id = any(p_ids)));
  elsif p_type = 'campus' then
    return jsonb_build_object('can_edit', v_rank >= 3, 'rows', (select coalesce(jsonb_object_agg(c.id, jsonb_build_object(
        'name', c.name, 'address_line1', c.address_line1, 'city', c.city, 'postcode', c.postcode, 'phone', c.phone, 'website', c.website,
        'locks', (select coalesce(jsonb_object_agg(k.field, k.mode), '{}'::jsonb) from pipeline.manual_locks k where k.entity = 'campus' and k.entity_id = c.id))), '{}'::jsonb)
      from catalogue.campuses c where c.id = any(p_ids)));
  elsif p_type = 'scholarship' then
    return jsonb_build_object('can_edit', v_rank >= 3, 'rows', (select coalesce(jsonb_object_agg(s.id, jsonb_build_object(
        'name', s.name, 'award_value_text', s.award_value_text, 'award_amount', s.award_amount, 'award_percentage', s.award_percentage,
        'application_open_date', s.application_open_date, 'application_close_date', s.application_close_date, 'source_url', s.source_url,
        'locks', (select coalesce(jsonb_object_agg(k.field, k.mode), '{}'::jsonb) from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id))), '{}'::jsonb)
      from scholarship.scholarships s where s.id = any(p_ids)));
  end if;
  raise exception 'unknown list %', p_type;
end $$;


ALTER FUNCTION "public"."admin_catalogue_edit_rows"("p_type" "text", "p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_course_applicants_edit"("p_course_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); c catalogue.courses%rowtype; f text; v_reason text := nullif(btrim(coalesce(p_args->>'reason', '')), '');
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  select * into c from catalogue.courses where id = p_course_id;
  if c.id is null then raise exception 'course not found'; end if;
  perform set_config('cf.manual_edit', 'on', true);
  if coalesce(p_args->>'action', 'set') = 'release' then
    delete from pipeline.manual_locks where entity = 'course' and entity_id = p_course_id and field in ('open_to_international','open_to_domestic');
    insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
    values ('course', p_course_id, 'applicants', 'release', jsonb_build_object('international', c.open_to_international, 'domestic', c.open_to_domestic), null, v_reason, auth.uid());
    return public.admin_course_links_read(p_course_id);
  end if;
  foreach f in array array['open_to_international','open_to_domestic'] loop
    if p_args ? f and jsonb_typeof(p_args->f) not in ('boolean','null') then raise exception 'choose yes, no or not known'; end if;
  end loop;
  update catalogue.courses set
    open_to_international = case when p_args ? 'open_to_international' then (p_args->>'open_to_international')::boolean else open_to_international end,
    open_to_domestic = case when p_args ? 'open_to_domestic' then (p_args->>'open_to_domestic')::boolean else open_to_domestic end,
    applicant_basis = 'Set by hand', updated_at = now()
   where id = p_course_id;
  foreach f in array array['open_to_international','open_to_domestic'] loop
    if p_args ? f then perform security.manual_lock_set('course', p_course_id, f, 'value'); end if;
  end loop;
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('course', p_course_id, 'applicants', 'set_applicants', jsonb_build_object('international', c.open_to_international, 'domestic', c.open_to_domestic),
          p_args - 'reason', v_reason, auth.uid());
  perform search.refresh_course_enrichment_scoped_v1(array[p_course_id], true);
  return public.admin_course_links_read(p_course_id);
end $$;


ALTER FUNCTION "public"."admin_course_applicants_edit"("p_course_id" "uuid", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_course_create"("p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid := gen_random_uuid(); v_title text := nullif(btrim(coalesce(p_args->>'title', '')), ''); v_code text := upper(nullif(btrim(coalesce(p_args->>'course_code', '')), ''));
        v_pid uuid := nullif(p_args->>'provider_id', '')::uuid;
begin
  if auth.uid() is null or security.current_role_rank() < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
  if v_pid is null or not exists (select 1 from catalogue.providers where id = v_pid) then raise exception 'choose the provider'; end if;
  if v_title is null then raise exception 'enter the course title'; end if;
  if v_code is not null and exists (select 1 from catalogue.courses where provider_id = v_pid and course_code = v_code and lifecycle_status = 'active') then
    raise exception 'this provider already has an active course with code %', v_code;
  end if;
  perform set_config('cf.manual_edit', 'on', true);
  insert into catalogue.courses(id, stable_key, provider_id, canonical_title, display_title, course_code, description, duration_value, duration_unit, delivery_mode, lifecycle_status)
  values (v_id, 'manual:' || v_id, v_pid, v_title, v_title, v_code, nullif(btrim(coalesce(p_args->>'description', '')), ''),
          nullif(p_args->>'duration_value', '')::numeric, nullif(p_args->>'duration_unit', ''), nullif(p_args->>'delivery_mode', ''), 'active');
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, after, reason, actor)
  values ('course', v_id, null, 'create', p_args, nullif(btrim(coalesce(p_args->>'reason', '')), ''), auth.uid());
  perform search.refresh_course_enrichment_scoped_v1(array[v_id], true);
  return public.admin_course_edit_read(v_id);
end $$;


ALTER FUNCTION "public"."admin_course_create"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_course_edit"("p_course_id" "uuid", "p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_src uuid; v_c catalogue.courses%rowtype; v_field text; v_before jsonb; v_after jsonb;
        v_reason text := nullif(btrim(coalesce(p_args->>'reason', '')), ''); v_url text; x jsonb; v_test uuid; v_amount numeric; v_val jsonb;
        v_keep uuid[] := '{}'; v_n int;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  select * into v_c from catalogue.courses where id = p_course_id;
  if v_c.id is null then raise exception 'course not found'; end if;
  if p_action in ('archive','restore') and v_rank < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
  perform set_config('cf.manual_edit', 'on', true);
  select id into v_src from pipeline.sources where source_type = 'manual_entry' limit 1;

  if p_action = 'set_core' then
    v_field := p_args->>'field';
    if v_field is null or v_field not in ('display_title','description','duration_value','duration_unit','delivery_mode') then raise exception 'this field cannot be edited here'; end if;
    v_val := p_args->'value';
    if jsonb_typeof(v_val) = 'string' then v_val := to_jsonb(nullif(btrim(v_val #>> '{}'), '')); end if;
    if v_field = 'duration_value' and v_val is not null and v_val <> 'null'::jsonb and not ((v_val #>> '{}') ~ '^[0-9]+(\.[0-9]+)?$') then raise exception 'duration must be a number'; end if;
    v_before := to_jsonb(v_c)->v_field;
    update catalogue.courses c set display_title = r.display_title, description = r.description, duration_value = r.duration_value,
           duration_unit = r.duration_unit, delivery_mode = r.delivery_mode, updated_at = now()
      from (select (jsonb_populate_record(x0, jsonb_build_object(v_field, v_val))).* from catalogue.courses x0 where x0.id = p_course_id) r
     where c.id = p_course_id;
    perform security.manual_lock_set('course', p_course_id, v_field, 'value');
    v_after := v_val;

  elsif p_action = 'set_official_url' then
    v_field := 'official_url'; v_url := btrim(coalesce(p_args->>'url', ''));
    if v_url !~* '^https?://[^\s/]+\.[^\s]+$' then raise exception 'enter a full web address starting with https://'; end if;
    select jsonb_agg(url) into v_before from catalogue.course_links where course_id = p_course_id and link_type = 'official_course' and status = 'active';
    update catalogue.course_links set status = 'inactive', is_primary = false, updated_at = now()
     where course_id = p_course_id and link_type = 'official_course' and status = 'active' and url <> v_url;
    insert into catalogue.course_links(course_id, link_type, url, label, is_primary, status, source_id, confidence, last_verified_at)
    values (p_course_id, 'official_course', v_url, 'Official course page', true, 'active', v_src, 1, now())
    on conflict (course_id, link_type, url) do update set status = 'active', is_primary = true, source_id = v_src, confidence = 1,
           last_verified_at = now(), updated_at = now(), evidence_id = null;
    update catalogue.courses set course_url = v_url, updated_at = now() where id = p_course_id;
    insert into pipeline.coverage_course_pages(course_id, provider_id, url, basis, status, bound_at, next_read_at, read_attempts)
    values (p_course_id, v_c.provider_id, v_url, 'manual', 'bound', now(), now(), 0)
    on conflict (course_id) do update set url = excluded.url, basis = 'manual', status = 'bound', bound_at = now(), score = null, runner_up = null,
           read_status = null, read_at = null, http_status = null, fetched_via = null, identity_basis = null, evidence_id = null, candidates = null,
           leased_until = null, read_attempts = 0, next_read_at = now();
    update pipeline.course_link_search set state = 'verified', bound_url = v_url, done_at = now() where course_id = p_course_id;
    perform security.manual_lock_set('course', p_course_id, 'official_url', 'value');
    perform security.manual_lock_set('course', p_course_id, 'course_url', 'value');
    v_after := to_jsonb(v_url);

  elsif p_action = 'remove_official_url' then
    v_field := 'official_url';
    select jsonb_agg(url) into v_before from catalogue.course_links where course_id = p_course_id and link_type = 'official_course' and status = 'active';
    update catalogue.course_links set status = 'inactive', is_primary = false, updated_at = now()
     where course_id = p_course_id and link_type = 'official_course' and status = 'active';
    update catalogue.courses set course_url = null, updated_at = now() where id = p_course_id;
    update pipeline.coverage_course_pages set status = 'mismatch', basis = 'manual', leased_until = null where course_id = p_course_id;
    delete from pipeline.course_link_search where course_id = p_course_id;
    perform security.manual_lock_set('course', p_course_id, 'official_url', 'removed');
    perform security.manual_lock_set('course', p_course_id, 'course_url', 'removed');

  elsif p_action = 'set_intakes' then
    v_field := 'intakes';
    if jsonb_typeof(p_args->'intakes') <> 'array' or jsonb_array_length(p_args->'intakes') = 0 then raise exception 'add at least one intake'; end if;
    select jsonb_agg(jsonb_build_object('label', intake_label, 'year', intake_year, 'start_date', start_date)) into v_before
      from catalogue.course_intakes where course_id = p_course_id and status = 'active';
    update catalogue.course_intakes set status = 'inactive' where course_id = p_course_id and status = 'active';
    for x in select * from jsonb_array_elements(p_args->'intakes') loop
      if nullif(btrim(coalesce(x->>'label', '')), '') is null then raise exception 'each intake needs a name, for example February'; end if;
      insert into catalogue.course_intakes(course_id, intake_year, intake_label, start_date, status, source_id, confidence, source_intake_key)
      values (p_course_id, nullif(x->>'year', '')::int, btrim(x->>'label'), nullif(x->>'start_date', '')::date, 'active', v_src, 1,
              'manual:' || lower(btrim(x->>'label')) || ':' || coalesce(nullif(x->>'year', ''), '') || ':' || coalesce(nullif(x->>'start_date', ''), ''))
      on conflict (course_id, source_id, source_intake_key) where source_id is not null and source_intake_key is not null
      do update set status = 'active', intake_year = excluded.intake_year, start_date = excluded.start_date, confidence = 1;
    end loop;
    perform security.manual_lock_set('course', p_course_id, 'intakes', 'value');
    v_after := p_args->'intakes';

  elsif p_action = 'remove_intakes' then
    v_field := 'intakes';
    select jsonb_agg(jsonb_build_object('label', intake_label, 'year', intake_year)) into v_before from catalogue.course_intakes where course_id = p_course_id and status = 'active';
    update catalogue.course_intakes set status = 'inactive' where course_id = p_course_id and status = 'active';
    perform security.manual_lock_set('course', p_course_id, 'intakes', 'removed');

  elsif p_action = 'set_english' then
    v_field := 'english';
    if jsonb_typeof(p_args->'tests') <> 'array' or jsonb_array_length(p_args->'tests') = 0 then raise exception 'add at least one English test score'; end if;
    select jsonb_agg(jsonb_build_object('test', t.code, 'overall', e.overall_score, 'components', e.component_scores)) into v_before
      from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id where e.course_id = p_course_id and e.status = 'active';
    for x in select * from jsonb_array_elements(p_args->'tests') loop
      select id into v_test from ref.english_tests where code = x->>'test';
      if v_test is null then raise exception 'unknown English test %', x->>'test'; end if;
      if (x->>'overall') is null or (x->>'overall') !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'enter an overall score for %', x->>'test'; end if;
      insert into catalogue.course_english_requirements(course_id, english_test_id, overall_score, component_scores, notes, source_id, evidence_id, confidence, source_requirement_key, status, last_verified_at)
      values (p_course_id, v_test, (x->>'overall')::numeric, coalesce(x->'components', '{}'::jsonb), 'Manual entry', v_src, null, 1, 'manual:' || lower(x->>'test'), 'active', now())
      on conflict (course_id, english_test_id) do update set overall_score = excluded.overall_score, component_scores = excluded.component_scores,
             notes = 'Manual entry', source_id = v_src, evidence_id = null, confidence = 1, source_requirement_key = excluded.source_requirement_key,
             status = 'active', last_verified_at = now();
      v_keep := v_keep || v_test;
    end loop;
    update catalogue.course_english_requirements set status = 'inactive' where course_id = p_course_id and status = 'active' and not (english_test_id = any(v_keep));
    perform security.manual_lock_set('course', p_course_id, 'english', 'value');
    v_after := p_args->'tests';

  elsif p_action = 'remove_english' then
    v_field := 'english';
    select jsonb_agg(jsonb_build_object('test', t.code, 'overall', e.overall_score)) into v_before
      from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id where e.course_id = p_course_id and e.status = 'active';
    update catalogue.course_english_requirements set status = 'inactive' where course_id = p_course_id and status = 'active';
    perform security.manual_lock_set('course', p_course_id, 'english', 'removed');

  elsif p_action = 'set_tuition' then
    v_field := 'tuition';
    if coalesce(p_args->>'amount', '') !~ '^[0-9]+(\.[0-9]+)?$' or (p_args->>'amount')::numeric < 100 then raise exception 'enter the fee as a number, for example 45000'; end if;
    if coalesce(p_args->>'basis', 'annual') not in ('annual','total_indicative','per_semester','per_trimester') then raise exception 'choose per year, per semester, per trimester or whole course'; end if;
    v_amount := (p_args->>'amount')::numeric;
    select jsonb_agg(jsonb_build_object('amount', amount, 'year', fee_year, 'basis', basis)) into v_before
      from catalogue.course_fees where course_id = p_course_id and fee_type = 'provider_current_tuition' and status = 'active';
    update catalogue.course_fees set status = 'superseded', updated_at = now(),
           notes = coalesce(notes, '') || ' | superseded by a manual entry ' || to_char(now(), 'YYYY-MM-DD')
     where course_id = p_course_id and fee_type = 'provider_current_tuition' and status = 'active';
    insert into catalogue.course_fees(course_id, fee_year, audience, fee_type, amount, currency_code, basis, notes, source_id, confidence, source_fee_key, status, last_verified_at)
    values (p_course_id, nullif(p_args->>'fee_year', '')::int, 'international', 'provider_current_tuition', v_amount, coalesce(nullif(p_args->>'currency', ''), (select k.default_currency_code::text from catalogue.providers pv join ref.countries k on k.id = pv.country_id where pv.id = v_c.provider_id), 'AUD'),
            coalesce(p_args->>'basis', 'annual'), 'Manual entry', v_src, 1, 'manual:' || extract(epoch from clock_timestamp())::bigint, 'active', now());
    perform security.manual_lock_set('course', p_course_id, 'tuition', 'value');
    v_after := jsonb_build_object('amount', v_amount, 'year', nullif(p_args->>'fee_year', ''), 'basis', coalesce(p_args->>'basis', 'annual'), 'currency', coalesce(nullif(p_args->>'currency', ''), (select k.default_currency_code::text from catalogue.providers pv join ref.countries k on k.id = pv.country_id where pv.id = v_c.provider_id), 'AUD'));

  elsif p_action = 'remove_tuition' then
    v_field := 'tuition';
    select jsonb_agg(jsonb_build_object('amount', amount, 'year', fee_year, 'basis', basis)) into v_before
      from catalogue.course_fees where course_id = p_course_id and fee_type = 'provider_current_tuition' and status = 'active';
    update catalogue.course_fees set status = 'inactive', updated_at = now(), notes = coalesce(notes, '') || ' | removed by hand ' || to_char(now(), 'YYYY-MM-DD')
     where course_id = p_course_id and fee_type = 'provider_current_tuition' and status = 'active';
    perform security.manual_lock_set('course', p_course_id, 'tuition', 'removed');

  elsif p_action = 'release' then
    v_field := p_args->>'field';
    select to_jsonb(l) into v_before from pipeline.manual_locks l where entity = 'course' and entity_id = p_course_id and field = v_field;
    if v_before is null then raise exception 'nothing to release'; end if;
    delete from pipeline.manual_locks where entity = 'course' and entity_id = p_course_id and (field = v_field or (v_field = 'official_url' and field = 'course_url'));
    if v_field = 'official_url' then
      update pipeline.coverage_course_pages set basis = 'released' where course_id = p_course_id and basis = 'manual';
    end if;

  elsif p_action in ('archive','restore') then
    v_field := 'lifecycle_status'; v_before := to_jsonb(v_c.lifecycle_status);
    update catalogue.courses set lifecycle_status = case p_action when 'archive' then 'inactive' else 'active' end, updated_at = now() where id = p_course_id;
    perform security.manual_lock_set('course', p_course_id, 'lifecycle_status', 'value');
    v_after := to_jsonb(case p_action when 'archive' then 'inactive' else 'active' end);

  else
    raise exception 'unknown action %', p_action;
  end if;

  if v_field in ('official_url','intakes','english','tuition') and p_action <> 'release' then
    perform security.manual_close_layer4(p_course_id, v_field);
  end if;
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('course', p_course_id, v_field, p_action, v_before, v_after, v_reason, auth.uid());
  perform search.refresh_course_enrichment_scoped_v1(array[p_course_id], true);
  return public.admin_course_edit_read(p_course_id);
end $_$;


ALTER FUNCTION "public"."admin_course_edit"("p_course_id" "uuid", "p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_course_edit_read"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  if not exists (select 1 from catalogue.courses where id = p_course_id) then raise exception 'course not found'; end if;
  return (select jsonb_build_object(
    'course', jsonb_build_object('id', c.id, 'provider_id', c.provider_id, 'provider', coalesce(p.display_name, p.canonical_name), 'course_code', c.course_code,
               'canonical_title', c.canonical_title, 'display_title', c.display_title, 'description', c.description, 'duration_value', c.duration_value,
               'duration_unit', c.duration_unit, 'delivery_mode', c.delivery_mode, 'lifecycle_status', c.lifecycle_status, 'course_url', c.course_url,
               'manual_course', c.stable_key like 'manual:%'),
    'official_links', (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'url', l.url, 'is_primary', l.is_primary, 'source', s.label,
               'manual', s.source_type = 'manual_entry', 'updated_at', l.updated_at) order by l.is_primary desc, l.updated_at desc), '[]'::jsonb)
               from catalogue.course_links l left join pipeline.sources s on s.id = l.source_id
              where l.course_id = c.id and l.link_type = 'official_course' and l.status = 'active'),
    'intakes', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'label', i.intake_label, 'year', i.intake_year, 'start_date', i.start_date,
               'source', s.label, 'manual', s.source_type = 'manual_entry') order by i.start_date nulls last, i.intake_label), '[]'::jsonb)
               from catalogue.course_intakes i left join pipeline.sources s on s.id = i.source_id where i.course_id = c.id and i.status = 'active'),
    'english', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'test', t.code, 'test_name', t.name, 'overall', e.overall_score,
               'components', e.component_scores, 'source', s.label, 'manual', s.source_type = 'manual_entry') order by t.name), '[]'::jsonb)
               from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id left join pipeline.sources s on s.id = e.source_id
              where e.course_id = c.id and e.status = 'active'),
    'tuition', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'amount', f.amount, 'currency', f.currency_code, 'fee_year', f.fee_year,
               'basis', f.basis, 'source', s.label, 'manual', s.source_type = 'manual_entry') order by f.updated_at desc), '[]'::jsonb)
               from catalogue.course_fees f left join pipeline.sources s on s.id = f.source_id
              where f.course_id = c.id and f.fee_type = 'provider_current_tuition' and f.status = 'active'),
    'locks', (select coalesce(jsonb_object_agg(l.field, jsonb_build_object('mode', l.mode, 'at', l.set_at)), '{}'::jsonb)
               from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = c.id),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('at', h.at, 'field', h.field, 'action', h.action, 'before', h.before, 'after', h.after,
               'reason', h.reason, 'by', u.email) order by h.at desc), '[]'::jsonb)
               from (select * from pipeline.manual_edit_log where entity = 'course' and entity_id = c.id order by at desc limit 20) h left join auth.users u on u.id = h.actor),
    'english_tests', (select jsonb_agg(jsonb_build_object('code', code, 'name', name) order by name) from ref.english_tests),
    'can_edit', v_rank >= 3, 'can_manage', v_rank >= 5)
   from catalogue.courses c left join catalogue.providers p on p.id = c.provider_id where c.id = p_course_id);
end $$;


ALTER FUNCTION "public"."admin_course_edit_read"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_course_link_edit"("p_course_id" "uuid", "p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_src uuid; v_type text := nullif(btrim(coalesce(p_args->>'link_type', '')), '');
        v_url text := nullif(btrim(coalesce(p_args->>'url', '')), ''); v_label text := nullif(btrim(coalesce(p_args->>'label', '')), '');
        v_reason text := nullif(btrim(coalesce(p_args->>'reason', '')), ''); l catalogue.course_links%rowtype; v_before jsonb; v_after jsonb; v_left int;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if not exists (select 1 from catalogue.courses where id = p_course_id) then raise exception 'course not found'; end if;
  if p_action in ('change','remove') then
    select * into l from catalogue.course_links where id = nullif(p_args->>'link_id', '')::uuid and course_id = p_course_id;
    if l.id is null then raise exception 'link not found on this course'; end if;
    v_type := l.link_type;
  end if;
  if v_type is null or not exists (select 1 from ref.course_link_types where code = v_type and status = 'active') then raise exception 'choose a link type'; end if;
  if p_action in ('add','change') and (v_url is null or v_url !~* '^https?://[^\s/]+\.[^\s]+$') then raise exception 'enter a full web address starting with https://'; end if;

  -- The official page keeps its own edit path (page search, reader and Layer 4 stay in step).
  if v_type = 'official_course' then
    if p_action in ('add','change') then
      perform public.admin_course_edit(p_course_id, 'set_official_url', jsonb_build_object('url', v_url, 'reason', v_reason));
    elsif p_action = 'remove' then
      select count(*) into v_left from catalogue.course_links where course_id = p_course_id and link_type = 'official_course' and status = 'active' and id <> l.id;
      if v_left = 0 then
        perform public.admin_course_edit(p_course_id, 'remove_official_url', jsonb_build_object('reason', v_reason));
      else
        perform set_config('cf.manual_edit', 'on', true);
        update catalogue.course_links set status = 'inactive', is_primary = false, updated_at = now() where id = l.id;
        perform security.manual_lock_set('course', p_course_id, 'official_url', 'value');
        insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
        values ('course', p_course_id, 'official_url', 'remove_link', to_jsonb(l.url), null, v_reason, auth.uid());
      end if;
    elsif p_action = 'release' then
      perform public.admin_course_edit(p_course_id, 'release', jsonb_build_object('field', 'official_url'));
    else raise exception 'unknown action %', p_action; end if;
    return public.admin_course_links_read(p_course_id);
  end if;

  perform set_config('cf.manual_edit', 'on', true);
  select id into v_src from pipeline.sources where source_type = 'manual_entry' limit 1;
  if p_action = 'add' then
    insert into catalogue.course_links(course_id, link_type, url, label, audience, is_primary, status, source_id, confidence, last_verified_at)
    values (p_course_id, v_type, v_url, coalesce(v_label, (select label from ref.course_link_types where code = v_type)), nullif(p_args->>'audience', ''),
            not exists (select 1 from catalogue.course_links x where x.course_id = p_course_id and x.link_type = v_type and x.status = 'active'),
            'active', v_src, 1, now())
    on conflict (course_id, link_type, url) do update set status = 'active', label = coalesce(v_label, catalogue.course_links.label),
           source_id = v_src, confidence = 1, last_verified_at = now(), updated_at = now();
    perform security.manual_lock_set('course', p_course_id, 'link:' || v_type, 'value');
    v_after := jsonb_build_object('url', v_url, 'label', v_label);
  elsif p_action = 'change' then
    v_before := jsonb_build_object('url', l.url, 'label', l.label, 'status', l.status);
    update catalogue.course_links set url = v_url, label = coalesce(v_label, label), audience = coalesce(nullif(p_args->>'audience', ''), audience),
           status = 'active', source_id = v_src, confidence = 1, last_verified_at = now(), updated_at = now()
     where id = l.id;
    perform security.manual_lock_set('course', p_course_id, 'link:' || v_type, 'value');
    v_after := jsonb_build_object('url', v_url, 'label', v_label);
  elsif p_action = 'remove' then
    v_before := jsonb_build_object('url', l.url, 'label', l.label);
    update catalogue.course_links set status = 'inactive', is_primary = false, updated_at = now() where id = l.id;
    select count(*) into v_left from catalogue.course_links where course_id = p_course_id and link_type = v_type and status = 'active';
    perform security.manual_lock_set('course', p_course_id, 'link:' || v_type, case when v_left = 0 then 'removed' else 'value' end);
  elsif p_action = 'release' then
    select to_jsonb(k) into v_before from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = p_course_id and k.field = 'link:' || v_type;
    if v_before is null then raise exception 'nothing to release'; end if;
    delete from pipeline.manual_locks where entity = 'course' and entity_id = p_course_id and field = 'link:' || v_type;
  else raise exception 'unknown action %', p_action; end if;
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('course', p_course_id, 'link:' || v_type, p_action || '_link', v_before, v_after, v_reason, auth.uid());
  perform search.refresh_course_enrichment_scoped_v1(array[p_course_id], true);
  return public.admin_course_links_read(p_course_id);
end $_$;


ALTER FUNCTION "public"."admin_course_link_edit"("p_course_id" "uuid", "p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_course_link_search_settings"("p_monthly_credit_cap" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_old int;
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
  if p_monthly_credit_cap is not null then
    if security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
    if p_monthly_credit_cap < 1000 or p_monthly_credit_cap > 500000 then raise exception 'the cap must be between 1,000 and 500,000 credits'; end if;
    select monthly_credit_cap into v_old from pipeline.course_link_search_settings where id = 1 for update;
    update pipeline.course_link_search_settings set monthly_credit_cap = p_monthly_credit_cap, updated_at = now(), updated_by = auth.uid() where id = 1;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('course_link_search', 'set_cap', 'monthly credit cap', jsonb_build_object('from', v_old, 'to', p_monthly_credit_cap), auth.uid());
  end if;
  return (select jsonb_build_object('enabled', s.enabled, 'monthly_credit_cap', s.monthly_credit_cap, 'updated_at', s.updated_at,
           'used_this_month', (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.purpose = 'course_link_search' and u.at >= date_trunc('month', now())),
           'queued', (select count(*) from pipeline.course_link_search q where q.state = 'queued'),
           'can_change', security.current_role_rank() >= 6)
            from pipeline.course_link_search_settings s where s.id = 1);
end $$;


ALTER FUNCTION "public"."admin_course_link_search_settings"("p_monthly_credit_cap" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_course_links_read"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); c record;
begin
  if auth.uid() is null or v_rank < 1 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  select co.id, co.open_to_international, co.open_to_domestic, co.applicant_basis, p.enrols_international, p.enrols_international_basis,
         coalesce(p.display_name, p.canonical_name) provider_name, k.iso_alpha2::text country_code
    into c from catalogue.courses co join catalogue.providers p on p.id = co.provider_id left join ref.countries k on k.id = p.country_id
   where co.id = p_course_id;
  if c.id is null then raise exception 'course not found'; end if;
  return jsonb_build_object(
    'can_edit', v_rank >= 3,
    'types', (select coalesce(jsonb_agg(jsonb_build_object('code', t.code, 'label', t.label, 'description', t.description, 'applicant', t.applicant) order by t.sort), '[]'::jsonb)
                from ref.course_link_types t where t.status = 'active'),
    'links', (select coalesce(jsonb_agg(jsonb_build_object(
                 'id', l.id, 'link_type', l.link_type, 'type_label', t.label, 'url', l.url, 'label', l.label, 'audience', l.audience,
                 'status', l.status, 'is_primary', l.is_primary, 'confidence', l.confidence, 'last_verified_at', l.last_verified_at,
                 'updated_at', l.updated_at, 'source', s.label, 'source_type', s.source_type,
                 'by_hand', s.source_type = 'manual_entry') order by t.sort, (l.status = 'active') desc, l.is_primary desc, l.updated_at desc), '[]'::jsonb)
                from catalogue.course_links l join ref.course_link_types t on t.code = l.link_type left join pipeline.sources s on s.id = l.source_id
               where l.course_id = p_course_id),
    'locks', (select coalesce(jsonb_object_agg(k.field, k.mode), '{}'::jsonb) from pipeline.manual_locks k
               where k.entity = 'course' and k.entity_id = p_course_id and (k.field like 'link:%' or k.field in ('official_url','open_to_international','open_to_domestic'))),
    'applicants', jsonb_build_object('open_to_international', c.open_to_international, 'open_to_domestic', c.open_to_domestic, 'basis', c.applicant_basis,
                    'provider_enrols_international', c.enrols_international, 'provider_basis', c.enrols_international_basis,
                    'english_expected', c.open_to_international is true, 'provider', c.provider_name, 'country', c.country_code));
end $$;


ALTER FUNCTION "public"."admin_course_links_read"("p_course_id" "uuid") OWNER TO "postgres";


