CREATE OR REPLACE FUNCTION "public"."admin_exit_awards"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid := (p_args->>'provider_id')::uuid; v_res jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Layer 4 reviewer or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'read' and p_args->>'scope' = 'settings' then
    return (select to_jsonb(s) - 'id' from pipeline.award_link_settings s where s.id = 1);
  end if;
  if p_action = 'read' then
    return coalesce((select jsonb_agg(jsonb_build_object('child_course_id', x.child_course_id, 'child', ch.canonical_title, 'child_code', ch.course_code, 'parent_course_id', x.parent_course_id, 'parent', pc.canonical_title,
                     'years', x.exit_years, 'page_url', x.page_url, 'printed', x.printed, 'active', x.active, 'set_by', x.set_by, 'link_type', x.link_type, 'register_check', x.register_check, 'check_detail', x.check_detail,
                     'annual_fee', x.annual_fee, 'fee_year', x.fee_year, 'total_fee', x.total_fee, 'applied_at', x.applied_at) order by pc.canonical_title, x.exit_years)
                     from pipeline.course_exit_awards x join catalogue.courses ch on ch.id = x.child_course_id join catalogue.courses pc on pc.id = x.parent_course_id where x.provider_id = v_pid), '[]'::jsonb);
  end if;
  if coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'detect' then
    v_res := jsonb_build_object('found', security.exit_awards_detect_v2(v_pid));
  elsif p_action = 'apply' then
    v_res := security.exit_awards_apply_v2(v_pid);
  elsif p_action = 'set' then
    if not exists (select 1 from catalogue.courses c where c.id = (p_args->>'child_course_id')::uuid and c.provider_id = v_pid)
       or not exists (select 1 from catalogue.courses c where c.id = (p_args->>'parent_course_id')::uuid and c.provider_id = v_pid) then
      raise exception 'both courses must belong to this university';
    end if;
    if coalesce((p_args->>'years')::numeric, 0) not between 0.5 and 8 then raise exception 'years must be from 0.5 to 8'; end if;
    if security.is_double_degree_title((select c.canonical_title from catalogue.courses c where c.id = (p_args->>'parent_course_id')::uuid)) then raise exception 'the parent must be a single degree, not a double degree'; end if;
    insert into pipeline.course_exit_awards(child_course_id, parent_course_id, provider_id, exit_years, page_url, evidence_id, printed, set_by, reason, link_type)
      select (p_args->>'child_course_id')::uuid, pg.course_id, v_pid, (p_args->>'years')::numeric, coalesce(nullif(btrim(p_args->>'page_url'), ''), pg.url), pg.evidence_id, left(p_args->>'printed', 300), 'hand', v_reason, coalesce(nullif(p_args->>'link_type', ''), 'exit_award')
      from pipeline.coverage_course_pages pg where pg.course_id = (p_args->>'parent_course_id')::uuid
    on conflict (child_course_id) do update set parent_course_id = excluded.parent_course_id, exit_years = excluded.exit_years, page_url = excluded.page_url, evidence_id = excluded.evidence_id, printed = excluded.printed, set_by = 'hand', reason = excluded.reason, active = true, link_type = excluded.link_type, set_at = now() where pipeline.course_exit_awards.child_course_id = excluded.child_course_id;
    update pipeline.course_exit_awards x set register_check = c.v[1], check_detail = c.v[2] from (select security.award_register_check((p_args->>'child_course_id')::uuid, (p_args->>'parent_course_id')::uuid) v) c where x.child_course_id = (p_args->>'child_course_id')::uuid;
    v_res := jsonb_build_object('ok', true);
  elsif p_action = 'settings' then
    update pipeline.award_link_settings set same_year_tolerance = coalesce((p_args->>'same_year_tolerance')::numeric, same_year_tolerance), lagged_tolerance = coalesce((p_args->>'lagged_tolerance')::numeric, lagged_tolerance), updated_by = auth.uid(), updated_at = now(), reason = v_reason where id = 1;
    update pipeline.course_exit_awards x set register_check = (security.award_register_check(x.child_course_id, x.parent_course_id))[1], check_detail = (security.award_register_check(x.child_course_id, x.parent_course_id))[2] where x.active;
    update pipeline.course_host_pages h set register_check = (security.award_register_check(h.course_id, h.host_course_id))[1], check_detail = (security.award_register_check(h.course_id, h.host_course_id))[2] where h.active and h.link_type = 'shared_page';
    v_res := jsonb_build_object('ok', true, 'links', (select count(*) from pipeline.course_exit_awards where active), 'passing', (select count(*) from pipeline.course_exit_awards where active and register_check = 'pass'));
  elsif p_action in ('off', 'on') then
    update pipeline.course_exit_awards set active = (p_action = 'on'), set_by = 'hand', reason = v_reason, set_at = now() where child_course_id = (p_args->>'child_course_id')::uuid;
    v_res := jsonb_build_object('ok', true);
  else
    raise exception 'unknown action';
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'exit_awards_' || p_action, coalesce(v_pid::text, p_args->>'child_course_id'), jsonb_build_object('result', v_res, 'args', p_args), auth.uid());
  return v_res;
end $$;


ALTER FUNCTION "public"."admin_exit_awards"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fc_extract_report"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('run_label', run_label, 'task_class', task_class, 'cases', n, 'right', ok, 'wrong_admitted', wrong, 'missed', missed, 'errors', errs,
                   'credits', credits, 'pass_80_rule', (n >= 30 and ok::numeric / n >= 0.80 and wrong = 0), 'last', last) order by last desc), '[]'::jsonb)
    from (select run_label, task_class, count(*) n, count(*) filter (where outcome in ('exact', 'exact_not_stated')) ok, count(*) filter (where outcome = 'wrong_admitted') wrong,
                 count(*) filter (where outcome = 'missed') missed, count(*) filter (where outcome = 'error') errs, sum(credits) credits, max(created_at) last
            from pipeline.fc_extract_results group by 1, 2) s);
end $$;


ALTER FUNCTION "public"."admin_fc_extract_report"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fee_rule_control"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_id bigint := nullif(p_args->>'id', '')::bigint; r pipeline.fee_wording_rules%rowtype; v_res jsonb;
begin
  if auth.uid() is null or v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
  if p_action in ('approve','run','pause','resume') and v_rank < 5 then raise exception 'PIM Operator role or above required to approve or run a rule' using errcode = '42501'; end if;
  if p_action = 'create' then
    if nullif(p_args->>'provider_id', '') is null or not exists (select 1 from catalogue.providers where id = (p_args->>'provider_id')::uuid) then raise exception 'choose the university'; end if;
    if length(btrim(coalesce(p_args->>'phrase', ''))) < 6 then raise exception 'type at least 6 characters of the words that come before the fee'; end if;
    if coalesce(p_args->>'basis', '') not in ('annual','total_indicative','per_semester','per_trimester') then raise exception 'choose the fee period'; end if;
    insert into pipeline.fee_wording_rules(provider_id, label, phrase, basis, url_pattern, note, created_by)
    values ((p_args->>'provider_id')::uuid, coalesce(nullif(btrim(coalesce(p_args->>'label', '')), ''), left(btrim(p_args->>'phrase'), 60)), btrim(p_args->>'phrase'),
            p_args->>'basis', nullif(btrim(coalesce(p_args->>'url_pattern', '')), ''), nullif(btrim(coalesce(p_args->>'note', '')), ''), auth.uid())
    returning * into r;
  else
    select * into r from pipeline.fee_wording_rules where id = v_id;
    if r.id is null then raise exception 'rule not found'; end if;
    if p_action = 'approve' then
      if r.status <> 'draft' then raise exception 'only a draft can be approved'; end if;
      update pipeline.fee_wording_rules set status = 'active', approved_by = auth.uid(), approved_at = now() where id = r.id;
      v_res := security.fee_rule_run_v1(r.id, true, auth.uid());
    elsif p_action = 'run' then
      if r.status <> 'active' then raise exception 'only an active rule can be run'; end if;
      v_res := security.fee_rule_run_v1(r.id, true, auth.uid());
    elsif p_action = 'pause' then update pipeline.fee_wording_rules set status = 'paused' where id = r.id;
    elsif p_action = 'resume' then update pipeline.fee_wording_rules set status = 'active' where id = r.id;
    elsif p_action = 'delete' then
      if r.status <> 'draft' then raise exception 'only a draft can be deleted; pause an approved rule instead'; end if;
      delete from pipeline.fee_wording_rules where id = r.id;
    else raise exception 'unknown action %', p_action; end if;
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fee_rules', p_action, coalesce(r.label, v_id::text), p_args || jsonb_build_object('rule_id', r.id) || coalesce(jsonb_build_object('result', v_res), '{}'::jsonb), auth.uid());
  return public.admin_fee_rules_read() || jsonb_build_object('result', v_res, 'rule_id', r.id);
end $$;


ALTER FUNCTION "public"."admin_fee_rule_control"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fee_rule_preview"("p_provider_id" "uuid", "p_phrase" "text", "p_url_pattern" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_phrase, ''))) < 6 then raise exception 'type at least 6 characters of the words that come before the fee'; end if;
  return (select jsonb_build_object(
      'would_admit', count(*) filter (where amounts = 1 and not has_fee and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = m.course_id and l.field = 'tuition')),
      'ambiguous', count(*) filter (where amounts > 1), 'already_had_fee', count(*) filter (where amounts = 1 and has_fee),
      'amount_range', jsonb_build_object('min', min(amount), 'max', max(amount)),
      'samples', (select coalesce(jsonb_agg(s), '[]'::jsonb) from (
          select jsonb_build_object('course_id', m2.course_id, 'course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'amount', m2.amount,
                 'fee_year', m2.fee_year, 'text', m2.matched_text, 'url', m2.url, 'has_fee', m2.has_fee, 'amounts', m2.amounts) s
            from security.fee_rule_matches(p_provider_id, p_phrase, nullif(btrim(coalesce(p_url_pattern, '')), '')) m2 join catalogue.courses c on c.id = m2.course_id
           order by m2.amounts desc, m2.amount limit 15) z))
    from security.fee_rule_matches(p_provider_id, p_phrase, nullif(btrim(coalesce(p_url_pattern, '')), '')) m);
end $$;


ALTER FUNCTION "public"."admin_fee_rule_preview"("p_provider_id" "uuid", "p_phrase" "text", "p_url_pattern" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fee_rules_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  return jsonb_build_object(
    'can_create', v_rank >= 4, 'can_approve', v_rank >= 5,
    'rules', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'provider_id', r.provider_id, 'provider', coalesce(p.display_name, p.canonical_name),
                'label', r.label, 'phrase', r.phrase, 'basis', r.basis, 'url_pattern', r.url_pattern, 'status', r.status, 'admitted', r.admitted,
                'created_at', r.created_at, 'created_by', cu.email, 'approved_at', r.approved_at, 'approved_by', au.email, 'last_run_at', r.last_run_at, 'note', r.note)
                order by r.status = 'active' desc, r.created_at desc), '[]'::jsonb)
                from pipeline.fee_wording_rules r left join catalogue.providers p on p.id = r.provider_id
                left join auth.users cu on cu.id = r.created_by left join auth.users au on au.id = r.approved_by),
    'suggestions', (select coalesce(jsonb_agg(s order by (s->>'pages')::int desc), '[]'::jsonb) from (
       select jsonb_build_object('provider_id', w.provider_id, 'provider', coalesce(p.display_name, p.canonical_name), 'phrase', w.phrase,
              'pages', count(distinct w.course_id), 'example', min(w.example),
              'has_rule', exists (select 1 from pipeline.fee_wording_rules r where r.provider_id = w.provider_id and lower(r.phrase) = lower(w.phrase))) s
         from (select g.provider_id, g.course_id, security.fee_suggest_phrase(c->>'context', (c->>'amount')::numeric) phrase, left(c->>'context', 240) example
                 from pipeline.coverage_course_pages g
                 join pipeline.provider_priority pp on pp.provider_id = g.provider_id and pp.rank <= 100
                 cross join lateral jsonb_array_elements(coalesce(g.candidates->'fee'->'candidates', '[]'::jsonb)) c
                where g.read_status = 'read' and g.identity_basis in ('cricos_code','manual') and coalesce(g.candidates->'fee'->>'safe', 'false') <> 'true'
                  and coalesce((c->>'domestic')::boolean, false) = false
                  and not exists (select 1 from catalogue.course_fees f where f.course_id = g.course_id and f.fee_type = 'provider_current_tuition' and f.status = 'active')) w
         join catalogue.providers p on p.id = w.provider_id
        where w.phrase is not null
        group by w.provider_id, p.display_name, p.canonical_name, w.phrase
       having count(distinct w.course_id) >= 10
        order by count(distinct w.course_id) desc limit 25) z),
    'recent', (select coalesce(jsonb_agg(jsonb_build_object('at', a.admitted_at, 'rule_id', a.rule_id, 'course_id', a.course_id,
                'course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'amount', a.amount, 'fee_year', a.fee_year, 'basis', a.basis, 'text', a.matched_text)
                order by a.admitted_at desc), '[]'::jsonb)
                from (select * from pipeline.fee_rule_admissions order by admitted_at desc limit 30) a join catalogue.courses c on c.id = a.course_id));
end $$;


ALTER FUNCTION "public"."admin_fee_rules_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fee_rules_report"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tol numeric := coalesce((p_args->>'tolerance')::numeric, 0.05); v_year int := coalesce((p_args->>'year')::int, extract(year from now())::int); v_out jsonb;
  v_hosts text[] := security.l4_shared_hosts_v1();
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 4 then raise exception 'Operator or above required' using errcode = '42501'; end if;
  with pg as (
    select distinct on (f.course_id) f.course_id, f.amount pa, f.fee_year, f.evidence_id, substring(ea.source_url from '^https?://(?:www\.)?([^/:?#]+)') h
      from catalogue.course_fees f left join pipeline.evidence_artifacts ea on ea.id = f.evidence_id
     where f.fee_type = 'provider_current_tuition' and f.audience = 'international' and f.status = 'active' and f.amount > 0
       and f.basis in ('annual', 'indicative_annual', 'current indicative annual international tuition')
     order by f.course_id, f.fee_year desc nulls last, f.created_at desc),
  cr as (select distinct on (course_id) course_id, amount ca from catalogue.course_fees where fee_type = 'tuition' and audience = 'international' and status = 'active' and basis = 'registered_total_course' and amount > 0 order by course_id, created_at desc),
  j as (
    select c.id course_id, c.display_title, p.id provider_id, p.display_name provider, k.iso_alpha2 country, pg.pa, pg.fee_year,
           cr.ca / greatest(case c.duration_unit when 'weeks' then c.duration_value / 52.0 when 'years' then c.duration_value when 'months' then c.duration_value / 12.0 end, 1) ann,
           exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = c.id and m.field in ('tuition', 'fee', 'fees')) locked,
           (pg.evidence_id is not null and exists (select 1 from pipeline.evidence_artifacts ea where ea.id = pg.evidence_id)) has_ev,
           (pg.h = any(v_hosts) and not coalesce(pg.h = substring(p.website from '^https?://(?:www\.)?([^/:?#]+)') or pg.h like '%.' || substring(p.website from '^https?://(?:www\.)?([^/:?#]+)'), false)) shared
      from pg join cr using (course_id) join catalogue.courses c on c.id = pg.course_id
      join catalogue.providers p on p.id = c.provider_id left join ref.countries k on k.id = p.country_id
     where c.duration_value > 0 and c.duration_unit in ('weeks', 'years', 'months')),
  m as (select j.*, abs(pa - ann) / ann gap, (abs(pa - ann) / ann > v_tol) differs, (ann > 0 and abs(pa / ann - 0.5) < 0.03) half from j),
  w as (select m.*, (differs and not locked and has_ev and not shared) chg from m)
  select jsonb_build_object(
    'as_at', now(), 'tolerance', v_tol, 'year', v_year, 'rule', 'rule_2',
    'compared', (select count(*) from w),
    'agree', (select count(*) from w where not differs),
    'differ', (select count(*) from w where differs),
    'would_change', (select count(*) from w where chg),
    'suspected_half', (select count(*) from w where chg and half),
    'suspected_half_sample', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (select jsonb_build_object('course_id', course_id, 'title', display_title, 'provider', provider, 'page_fee', pa, 'cricos_per_year', round(ann, 0)) x from w where chg and half order by provider, display_title limit 40) t),
    'protected_by_hand', (select count(*) from w where differs and locked),
    'kept_no_evidence', (select count(*) from w where differs and not locked and not has_ev),
    'kept_other_site', (select count(*) from w where differs and not locked and has_ev and shared),
    'page_higher', (select count(*) from w where chg and pa > ann),
    'page_lower', (select count(*) from w where chg and pa < ann),
    'gap_over_20', (select count(*) from w where chg and gap > 0.2),
    'by_country', (select coalesce(jsonb_agg(x order by x->>'country'), '[]'::jsonb) from (select jsonb_build_object('country', country, 'compared', count(*), 'would_change', count(*) filter (where chg)) x from w group by country) t),
    'by_provider', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (select jsonb_build_object('provider_id', provider_id, 'provider', provider, 'country', country, 'compared', count(*), 'would_change', count(*) filter (where chg)) x from w group by provider_id, provider, country order by count(*) filter (where chg) desc limit 25) t),
    'sample', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (select jsonb_build_object('course_id', course_id, 'title', display_title, 'provider', provider, 'page_fee', pa, 'page_year', fee_year, 'cricos_per_year', round(ann, 0), 'gap', round(gap, 2)) x from w where chg order by gap desc limit 20) t)
  ) into v_out;
  return v_out;
end $$;


ALTER FUNCTION "public"."admin_fee_rules_report"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_firecrawl_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_fc uuid; v_obs record; v_fig record;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  select p.id into v_fc from pipeline.layer2_acquisition_providers p where p.provider_key = 'firecrawl';
  select o.* into v_obs from pipeline.vendor_credit_observations o where o.provider_id = v_fc order by o.observed_at desc limit 1;
  select f.* into v_fig from pipeline.firecrawl_panel_figures f where f.id = 1;
  return jsonb_build_object(
    'can_manage', coalesce(v_rank, 0) >= 6,
    'figures_at', v_fig.refreshed_at,
    'plan', jsonb_build_object('budget', security.layer2_provider_budget_status(v_fc, 1), 'vendor', case when v_obs.provider_id is null then null else jsonb_build_object('observed_at', v_obs.observed_at, 'plan_credits', v_obs.plan_units, 'remaining', v_obs.remaining_units, 'period_start', v_obs.raw->>'billing_period_start', 'period_end', v_obs.period_end) end),
    'targets', coalesce((select jsonb_agg(jsonb_build_object('provider_id', t.provider_id, 'country', t.country, 'name', t.name, 'domain', t.domain, 'rule_match', t.rule_match, 'included', t.included, 'override_reason', t.override_reason)
                 || coalesce(t.stats, jsonb_build_object('courses', t.courses))
                 || jsonb_build_object('adapter', case when a.provider_id is null then 'none' when a.admit then 'admitting' when a.enabled then 'testing' else 'off' end,
                                       'requests_open', (select count(*) from pipeline.uni_adapter_requests r where r.provider_id = t.provider_id and r.status = 'open'))
               order by (a.provider_id is not null) desc, t.included desc, t.country, coalesce(t.courses, 0) desc)
               from pipeline.firecrawl_target_cache t left join pipeline.uni_adapters a on a.provider_id = t.provider_id where t.name is not null), '[]'::jsonb),
    'backlog', coalesce(v_fig.backlog, '{}'::jsonb),
    'runs', coalesce((select jsonb_agg(to_jsonb(r) - 'settings' order by r.created_at desc) from (select * from pipeline.firecrawl_runs order by created_at desc limit 12) r), '[]'::jsonb),
    'spend', coalesce((select jsonb_agg(jsonb_build_object('purpose', s.purpose, 'target', s.target, 'units', s.units) order by s.units desc) from (
               select u.purpose, coalesce(tc.included, false) target, sum(u.units) units
               from pipeline.coverage_vendor_usage u left join pipeline.firecrawl_target_cache tc on tc.provider_id = u.provider_id
               where u.acquisition_provider_id = v_fc and u.at >= coalesce((v_obs.raw->>'billing_period_start')::timestamptz, date_trunc('month', now()))
               group by 1, 2) s), '[]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."admin_firecrawl_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_firecrawl_report"("p_since" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_since timestamptz := coalesce(p_since, now() - interval '7 days'); v_fc uuid; v_obs record;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  select p.id into v_fc from pipeline.layer2_acquisition_providers p where p.provider_key = 'firecrawl';
  select o.* into v_obs from pipeline.vendor_credit_observations o where o.provider_id = v_fc order by o.observed_at desc limit 1;
  return jsonb_build_object(
    'since', v_since, 'generated_at', now(),
    'account', case when v_obs.provider_id is null then null else jsonb_build_object('plan_credits', v_obs.plan_units, 'remaining', v_obs.remaining_units, 'period_start', v_obs.raw->>'billing_period_start', 'period_end', v_obs.period_end, 'observed_at', v_obs.observed_at) end,
    'totals', (select jsonb_build_object('calls', count(*), 'succeeded', count(*) filter (where success), 'failed', count(*) filter (where not success), 'credits', coalesce(sum(credits_used), 0),
                 'api_errors', count(*) filter (where http is null or http >= 400), 'timeouts', count(*) filter (where outcome = 'timeout' or error ~* 'timed? ?out'),
                 'rate_limited', count(*) filter (where http = 429), 'stealth_used', count(*) filter (where proxy_used ~* 'stealth|enhanced'), 'median_ms', percentile_disc(0.5) within group (order by duration_ms))
               from pipeline.firecrawl_calls where at >= v_since),
    'by_endpoint', coalesce((select jsonb_agg(x order by x->>'endpoint') from (select jsonb_build_object('endpoint', endpoint, 'use_case', use_case, 'calls', count(*), 'succeeded', count(*) filter (where success), 'credits', coalesce(sum(credits_used), 0)) x
               from pipeline.firecrawl_calls where at >= v_since group by endpoint, use_case) q), '[]'::jsonb),
    'by_outcome', coalesce((select jsonb_object_agg(coalesce(outcome, 'unknown'), n) from (select outcome, count(*) n from pipeline.firecrawl_calls where at >= v_since group by 1) q), '{}'::jsonb),
    'by_site', coalesce((select jsonb_agg(x order by (x->>'failed')::int desc, (x->>'calls')::int desc) from (
        select jsonb_build_object('site', h, 'calls', count(*), 'failed', count(*) filter (where not success),
               'page_statuses', (select jsonb_object_agg(coalesce(s2.ps::text, 'none'), s2.n) from (select page_status ps, count(*) n from pipeline.firecrawl_calls k2 where k2.at >= v_since and regexp_replace(lower(substring(k2.url from '^https?://([^/?#]+)')), '^www\.', '') = q.h group by 1) s2),
               'errors', (select jsonb_agg(distinct left(k3.error, 160)) from pipeline.firecrawl_calls k3 where k3.at >= v_since and k3.error is not null and regexp_replace(lower(substring(k3.url from '^https?://([^/?#]+)')), '^www\.', '') = q.h),
               'proxies', (select jsonb_agg(distinct k4.proxy_used) from pipeline.firecrawl_calls k4 where k4.at >= v_since and k4.proxy_used is not null and regexp_replace(lower(substring(k4.url from '^https?://([^/?#]+)')), '^www\.', '') = q.h),
               'samples', (select jsonb_agg(jsonb_build_object('url', k5.url, 'scrape_id', k5.scrape_id, 'http', k5.http, 'page_status', k5.page_status, 'error', left(k5.error, 200), 'at', k5.at)) from (
                   select * from pipeline.firecrawl_calls k5 where k5.at >= v_since and not k5.success and regexp_replace(lower(substring(k5.url from '^https?://([^/?#]+)')), '^www\.', '') = q.h order by k5.at desc limit 5) k5)) x
        from (select regexp_replace(lower(substring(url from '^https?://([^/?#]+)')), '^www\.', '') h, success from pipeline.firecrawl_calls where at >= v_since and endpoint = 'scrape' and url ~ '^https?://') q
        group by h having count(*) filter (where not success) > 0) z), '[]'::jsonb),
    'errors', coalesce((select jsonb_agg(x order by (x->>'calls')::int desc) from (
        select jsonb_build_object('error', e, 'calls', count(*), 'first_at', min(at), 'last_at', max(at), 'sample_scrape_id', (array_agg(scrape_id order by at desc) filter (where scrape_id is not null))[1], 'sample_url', (array_agg(url order by at desc))[1]) x
        from (select coalesce(left(error, 200), 'HTTP ' || coalesce(http::text, 'none') || ', page status ' || coalesce(page_status::text, 'none')) e, at, scrape_id, url from pipeline.firecrawl_calls where at >= v_since and not success) q group by e) z), '[]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."admin_firecrawl_report"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_firecrawl_write"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_uc text := p_args->>'use_case';
        v_run uuid; v_n int; v_settings jsonb; v_cap numeric; v_budget jsonb; v_pid uuid; v_inc boolean; v_r pipeline.firecrawl_runs%rowtype;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'target' then
    v_pid := (p_args->>'provider_id')::uuid;
    if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
    if p_args->'included' is null or jsonb_typeof(p_args->'included') = 'null' then
      update pipeline.firecrawl_targets set included = (select t.rule_match from security.firecrawl_targets_v1() t where t.provider_id = v_pid), reason = 'back to the rule: ' || v_reason, set_by = auth.uid(), set_at = now() where provider_id = v_pid;
    else
      v_inc := (p_args->>'included')::boolean;
      insert into pipeline.firecrawl_targets(provider_id, included, reason, set_by, set_at) values (v_pid, v_inc, v_reason, auth.uid(), now())
        on conflict (provider_id) do update set included = excluded.included, reason = excluded.reason, set_by = excluded.set_by, set_at = now() where pipeline.firecrawl_targets.provider_id = excluded.provider_id;
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'firecrawl_target', v_pid::text, jsonb_build_object('included', p_args->'included', 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true);
  elsif p_action = 'start' then
    if v_uc not in ('read_page', 'find_page') then raise exception 'use case must be read_page or find_page'; end if;
    if exists (select 1 from pipeline.firecrawl_runs r where r.use_case = v_uc and r.status = 'running') then raise exception 'a run of this use case is still open. Let it finish or stop it first'; end if;
    v_budget := security.layer2_provider_budget_status((select p.id from pipeline.layer2_acquisition_providers p where p.provider_key = 'firecrawl'), 1);
    if not coalesce((v_budget->>'allowed')::boolean, false) then raise exception 'Firecrawl is at its reserve. Check the plan on this page first'; end if;
    select coalesce(jsonb_object_agg(s.key, s.value), '{}'::jsonb) into v_settings from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl';
    v_cap := (v_settings->>(case when v_uc = 'read_page' then 'read_credits_per_run' else 'find_credits_per_run' end))::numeric;
    insert into pipeline.firecrawl_runs(use_case, settings, reason, requested_by, credits_cap) values (v_uc, v_settings, v_reason, auth.uid(), v_cap) returning id into v_run;
    insert into pipeline.firecrawl_run_items(run_id, course_id, provider_id, country, url, input)
      select v_run, b.course_id, b.provider_id, b.country, b.url, b.input from (select distinct on (b0.course_id) b0.* from security.firecrawl_backlog_v1(v_uc) b0 order by b0.course_id) b
      order by b.provider_id, b.course_id;
    get diagnostics v_n = row_count;
    update pipeline.firecrawl_runs set items = v_n, status = case when v_n = 0 then 'done' else 'running' end, finished_at = case when v_n = 0 then now() end where id = v_run;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'firecrawl_run_start', v_uc, jsonb_build_object('run_id', v_run, 'items', v_n, 'credits_cap', v_cap, 'reason', v_reason), auth.uid());
    if v_n > 0 then perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'fc_run', 'run_id', v_run)); end if;
    return jsonb_build_object('ok', true, 'run_id', v_run, 'items', v_n, 'credits_cap', v_cap);
  elsif p_action in ('stop', 'continue') then
    select * into v_r from pipeline.firecrawl_runs where id = (p_args->>'run_id')::uuid;
    if v_r.id is null then raise exception 'unknown run'; end if;
    if p_action = 'stop' then
      update pipeline.firecrawl_runs set status = 'stopped', finished_at = now() where id = v_r.id and status = 'running';
    else
      if v_r.status not in ('running', 'stopped_credit_cap', 'stopped_plan_reserve', 'stopped') then raise exception 'only an open or stopped run can be continued'; end if;
      if p_args ? 'add_credits' then update pipeline.firecrawl_runs set credits_cap = credits_cap + greatest((p_args->>'add_credits')::numeric, 0) where id = v_r.id; end if;
      update pipeline.firecrawl_runs set status = 'running', finished_at = null where id = v_r.id;
      perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'fc_run', 'run_id', v_r.id));
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'firecrawl_run_' || p_action, v_r.id::text, jsonb_build_object('add_credits', p_args->'add_credits', 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true);
  end if;
  raise exception 'unknown action';
end $$;


ALTER FUNCTION "public"."admin_firecrawl_write"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_host_pages"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_cid uuid := nullif(p_args->>'course_id', '')::uuid; v_res jsonb; v_h pipeline.course_host_pages%rowtype;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Layer 4 reviewer or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'read' then
    return coalesce((select jsonb_agg(jsonb_build_object('course_id', h.course_id, 'course', ch.canonical_title, 'code', ch.course_code, 'link_type', h.link_type, 'host_course_id', h.host_course_id, 'host', hc.canonical_title,
                     'host_url', h.host_url, 'basis', h.basis, 'printed', h.printed, 'register_check', h.register_check, 'check_detail', h.check_detail, 'active', h.active, 'set_by', h.set_by, 'applied_at', h.applied_at, 'set_at', h.set_at) order by h.link_type, ch.canonical_title)
                     from pipeline.course_host_pages h join catalogue.courses ch on ch.id = h.course_id left join catalogue.courses hc on hc.id = h.host_course_id where h.provider_id = v_pid), '[]'::jsonb);
  end if;
  if coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'detect' then
    v_res := security.host_pages_detect_v1(v_pid);
  elsif p_action = 'apply' then
    v_res := security.host_pages_apply_v1(v_pid);
  elsif p_action = 'confirm_page' then
    select * into v_h from pipeline.course_host_pages h where h.course_id = v_cid;
    if v_h.course_id is null or v_h.link_type = 'no_public_page' then raise exception 'no page to confirm for this course'; end if;
    update pipeline.coverage_course_pages pg set read_status = 'read', identity_basis = 'host_page' where pg.course_id = v_cid and pg.url = v_h.host_url and pg.read_status = 'identity_mismatch';
    update pipeline.course_host_pages set set_by = 'hand', reason = v_reason, applied_at = now(), set_at = now() where course_id = v_cid;
    v_res := jsonb_build_object('ok', true);
  elsif p_action = 'no_page' then
    v_res := public.admin_course_edit(v_cid, 'remove_official_url', jsonb_build_object('reason', v_reason));
    update pipeline.course_host_pages set set_by = 'hand', reason = v_reason, applied_at = now(), set_at = now() where course_id = v_cid;
    v_res := jsonb_build_object('ok', true);
  elsif p_action in ('off', 'on') then
    update pipeline.course_host_pages set active = (p_action = 'on'), set_by = 'hand', reason = v_reason, set_at = now() where course_id = v_cid;
    v_res := jsonb_build_object('ok', true);
  else
    raise exception 'unknown action';
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'host_pages_' || p_action, coalesce(v_pid::text, v_cid::text), jsonb_build_object('result', v_res, 'args', p_args), auth.uid());
  return v_res;
end $$;


ALTER FUNCTION "public"."admin_host_pages"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_jobs"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_id uuid; v_kind text; v_ids uuid[]; v_j pipeline.admin_jobs%rowtype;
        v_q pipeline.admin_jobs%rowtype; v_fields text[]; v_title text; v_n int; v_res jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Operator or above required' using errcode = '42501'; end if;
  if p_action = 'read' then
    return jsonb_build_object(
      'jobs', coalesce((select jsonb_agg(to_jsonb(j) - 'args' || jsonb_build_object('args', j.args - 'providers', 'providers', coalesce(jsonb_array_length(j.args->'providers'), 0), 'requested_by_name', (select coalesce(u.email, j.requested_by::text) from auth.users u where u.id = j.requested_by)) order by j.created_at desc)
                         from (select * from pipeline.admin_jobs where state in ('queued', 'running', 'paused') or (p_args->>'all')::boolean order by created_at desc limit greatest(1, least(coalesce((p_args->>'limit')::int, 50), 200))) j), '[]'::jsonb),
      'match', case when p_args ? 'kind' then (select to_jsonb(j) - 'args' || jsonb_build_object('providers', coalesce(jsonb_array_length(j.args->'providers'), 0)) from pipeline.admin_jobs j
                      where j.kind = p_args->>'kind' and j.scope is not distinct from nullif(p_args->>'scope', '') and j.state in ('queued', 'running', 'paused') order by j.created_at desc limit 1) end,
      'job', case when p_args ? 'id' then (select to_jsonb(j) - 'args' || jsonb_build_object('args', j.args - 'providers', 'providers', coalesce(jsonb_array_length(j.args->'providers'), 0),
                    'requested_by_name', (select coalesce(u.email, j.requested_by::text) from auth.users u where u.id = j.requested_by),
                    'events', coalesce((select jsonb_agg(jsonb_build_object('at', e.at, 'note', e.note, 'detail', e.detail) order by e.id desc) from (select * from pipeline.admin_job_events e where e.job_id = j.id order by e.id desc limit 200) e), '[]'::jsonb),
                    'qualifications', coalesce((select jsonb_agg(jsonb_build_object('provider_id', q.provider_id, 'name', coalesce(p.display_name, p.canonical_name), 'country', security.coverage_country(p.id), 'pages_read', q.pages_read, 'fields', q.fields, 'passing', q.passing, 'adapter', (select case when not u.enabled then 'off' when u.admit then 'admitting' else 'testing' end from pipeline.uni_adapters u where u.provider_id = q.provider_id), 'admitted', (select to_jsonb(u.admit_fields) from pipeline.uni_adapters u where u.provider_id = q.provider_id and u.admit)) order by coalesce(p.display_name, p.canonical_name))
                                       from pipeline.adapter_qualifications q join catalogue.providers p on p.id = q.provider_id where (q.job_id = coalesce(j.args->>'qualification_job_id', j.id::text)::uuid or q.job_id::text = j.args->'qual_jobs'->>q.provider_id::text)), '[]'::jsonb))
                  from pipeline.admin_jobs j where j.id = (p_args->>'id')::uuid) end,
      'settings', jsonb_build_object('min_read_share', coalesce(security.firecrawl_setting('eval_field_share'), '0.5'::jsonb), 'min_agree_share', coalesce(security.firecrawl_setting('qualify_agree_share'), '0.9'::jsonb)),
      'countries', coalesce((select jsonb_agg(jsonb_build_object('code', k.iso_alpha2, 'name', k.name, 'adapters', n.n) order by k.name) from ref.countries k join (select p.country_id, count(*) n from pipeline.uni_adapters u join catalogue.providers p on p.id = u.provider_id group by p.country_id) n on n.country_id = k.id), '[]'::jsonb),
      'states', coalesce((select jsonb_agg(jsonb_build_object('code', s.code, 'name', s.name, 'country', k.iso_alpha2, 'adapters', n.n) order by s.code) from ref.subdivisions s join ref.countries k on k.id = s.country_id join (select p.subdivision_id, count(*) n from pipeline.uni_adapters u join catalogue.providers p on p.id = u.provider_id group by p.subdivision_id) n on n.subdivision_id = s.id), '[]'::jsonb),
      'can_admit', v_rank >= 6);
  end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'start' then
    v_kind := p_args->>'kind';
    if v_kind = 'qualify_adapters' then
      if v_rank < 5 then raise exception 'Operator (adapters) or above required' using errcode = '42501'; end if;
      v_ids := security.admin_jobs_resolve_adapters_v1(coalesce(p_args->'args', '{}'::jsonb));
      if coalesce(array_length(v_ids, 1), 0) = 0 then raise exception 'no adapters match that choice'; end if;
      v_title := 'Qualify ' || array_length(v_ids, 1) || ' adapter(s)' || coalesce(' in ' || nullif(btrim(coalesce(p_args->'args'->>'state', p_args->'args'->>'country', '')), ''), '');
      insert into pipeline.admin_jobs(kind, lane, title, args, progress, requested_by, reason, scope)
        values (v_kind, 'adapters', v_title, coalesce(p_args->'args', '{}'::jsonb) || jsonb_build_object('providers', to_jsonb(v_ids)), jsonb_build_object('done', 0, 'total', array_length(v_ids, 1)), auth.uid(), v_reason,
                coalesce(nullif(p_args->'args'->>'scope', ''), nullif(p_args->'args'->>'state', ''), nullif(p_args->'args'->>'country', '')))
        returning * into v_j;
    elsif v_kind = 'admit_qualified' and not (coalesce(p_args->'args', '{}'::jsonb) ? 'qualification_job_id') then
      -- 6 Oct (Layer 2 › Adapters): admit the ticked adapters, each from its own latest finished Qualify
      if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
      v_fields := case when p_args->'args' ? 'fields' then array(select x from jsonb_array_elements_text(p_args->'args'->'fields') x where x in ('intakes', 'english', 'fee', 'delivery')) else array['intakes', 'english', 'fee', 'delivery'] end;
      select coalesce(jsonb_object_agg(z.provider_id, z.job_id), '{}'::jsonb), coalesce(array_agg(z.provider_id order by z.provider_id), '{}') into v_res, v_ids
        from (select distinct on (x.provider_id) x.provider_id, x.job_id, x.passing from pipeline.adapter_qualifications x join pipeline.admin_jobs qj on qj.id = x.job_id and qj.kind = 'qualify_adapters' and qj.state = 'done'
               where x.provider_id = any (array(select (y)::uuid from jsonb_array_elements_text(coalesce(p_args->'args'->'provider_ids', '[]'::jsonb)) y))
               order by x.provider_id, x.measured_at desc) z
       where z.passing && v_fields and exists (select 1 from pipeline.uni_adapters u where u.provider_id = z.provider_id and u.enabled);
      if coalesce(array_length(v_ids, 1), 0) = 0 then raise exception 'no ticked adapter passed for those fields in its latest Qualify (or it is switched off)'; end if;
      v_title := 'Admit the passing fields of ' || case when array_length(v_ids, 1) = 1 then coalesce((select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = v_ids[1]), '1 adapter') else array_length(v_ids, 1) || ' adapters' end || ' (latest Qualify of each)';
      insert into pipeline.admin_jobs(kind, lane, title, args, progress, requested_by, reason, scope)
        values (v_kind, 'adapters', v_title, jsonb_build_object('qual_jobs', v_res, 'fields', to_jsonb(v_fields), 'providers', to_jsonb(v_ids)), jsonb_build_object('done', 0, 'total', array_length(v_ids, 1)), auth.uid(), v_reason,
                coalesce(nullif(p_args->'args'->>'scope', ''), case when array_length(v_ids, 1) = 1 then v_ids[1]::text else 'adapters' end))
        returning * into v_j;
      v_res := null;
    elsif v_kind = 'admit_qualified' then
      if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
      select * into v_q from pipeline.admin_jobs q where q.id = (p_args->'args'->>'qualification_job_id')::uuid;
      if v_q.id is null or v_q.kind <> 'qualify_adapters' or v_q.state <> 'done' then raise exception 'choose a finished Qualify job'; end if;
      v_fields := case when p_args->'args' ? 'fields' then array(select x from jsonb_array_elements_text(p_args->'args'->'fields') x where x in ('intakes', 'english', 'fee', 'delivery')) else array['intakes', 'english', 'fee', 'delivery'] end;
      v_ids := array(select q.provider_id from pipeline.adapter_qualifications q where q.job_id = v_q.id and q.passing && v_fields
                      and exists (select 1 from pipeline.uni_adapters u where u.provider_id = q.provider_id and u.enabled)
                      order by q.provider_id);
      if coalesce(array_length(v_ids, 1), 0) = 0 then raise exception 'no adapter passed for those fields'; end if;
      v_title := 'Admit the passing fields of ' || array_length(v_ids, 1) || ' adapter(s) (from ' || v_q.title || ')';
      insert into pipeline.admin_jobs(kind, lane, title, args, progress, requested_by, reason, scope)
        values (v_kind, 'adapters', v_title, jsonb_build_object('qualification_job_id', v_q.id, 'fields', to_jsonb(v_fields), 'providers', to_jsonb(v_ids)), jsonb_build_object('done', 0, 'total', array_length(v_ids, 1)), auth.uid(), v_reason, v_q.id::text)
        returning * into v_j;
    elsif v_kind = 'reread_pages' then
      v_res := public.admin_university_reread('queue', coalesce(p_args->'args', '{}'::jsonb) || jsonb_build_object('reason', v_reason));
      v_ids := array(select distinct (x)::uuid from jsonb_array_elements_text(coalesce(p_args->'args'->'provider_ids', '[]'::jsonb)) x);
      v_title := 'Read pages again: ' || case when cardinality(v_ids) = 1 then coalesce((select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = v_ids[1]), '1 university') else cardinality(v_ids) || ' universities' end
                 || case when coalesce(p_args->'args'->>'which', 'all') = 'not_confirmed' then ' (pages not confirmed)' else '' end || case when coalesce((p_args->'args'->>'central')::boolean, false) then ' with central pages' else '' end;
      insert into pipeline.admin_jobs(kind, lane, title, args, progress, requested_by, reason, scope)
        values (v_kind, 'reads', v_title, jsonb_build_object('request_id', v_res->>'request_id', 'provider_ids', to_jsonb(v_ids), 'which', coalesce(p_args->'args'->>'which', 'all'), 'central', coalesce((p_args->'args'->>'central')::boolean, false)),
                jsonb_build_object('done', 0, 'total', cardinality(v_ids), 'phase', 'sending'), auth.uid(), v_reason, case when cardinality(v_ids) = 1 then v_ids[1]::text else coalesce(nullif(p_args->'args'->>'scope', ''), 'universities') end)
        returning * into v_j;
    elsif v_kind = 'firecrawl_run' then
      v_res := public.admin_firecrawl_write('start', jsonb_build_object('use_case', p_args->'args'->>'use_case', 'reason', v_reason));
      v_title := 'Firecrawl run: ' || replace(coalesce(p_args->'args'->>'use_case', ''), '_', ' ') || ' (' || coalesce(v_res->>'items', '0') || ' pages, cap ' || coalesce(v_res->>'credits_cap', '-') || ' credits)';
      insert into pipeline.admin_jobs(kind, lane, title, args, progress, requested_by, reason, scope)
        values (v_kind, 'firecrawl', v_title, jsonb_build_object('run_id', v_res->>'run_id', 'use_case', p_args->'args'->>'use_case', 'items', (v_res->>'items')::int), jsonb_build_object('done', 0, 'total', coalesce((v_res->>'items')::int, 0)), auth.uid(), v_reason, p_args->'args'->>'use_case')
        returning * into v_j;
      v_ids := '{}';
    elsif v_kind = 'adapter_apply' then
      v_res := public.admin_uni_adapter_write('apply', jsonb_build_object('provider_id', p_args->'args'->>'provider_id', 'reason', v_reason));
      v_title := 'Apply the adapter: ' || coalesce((select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = (p_args->'args'->>'provider_id')::uuid), '') || ' (' || coalesce(v_res->>'pages_read_again', '0') || ' pages)';
      insert into pipeline.admin_jobs(kind, lane, title, args, progress, requested_by, reason, scope)
        values (v_kind, 'reads', v_title, jsonb_build_object('provider_id', p_args->'args'->>'provider_id', 'pages', coalesce((v_res->>'pages_read_again')::int, 0), 'providers', jsonb_build_array(p_args->'args'->>'provider_id')), jsonb_build_object('done', 0, 'total', coalesce((v_res->>'pages_read_again')::int, 0)), auth.uid(), v_reason, p_args->'args'->>'provider_id')
        returning * into v_j;
      v_ids := array[(p_args->'args'->>'provider_id')::uuid];
    elsif v_kind = 'central_page_read' then
      v_res := public.admin_provider_central_page(coalesce(nullif(p_args->'args'->>'action', ''), 'add'), jsonb_build_object('provider_id', p_args->'args'->>'provider_id', 'kind', p_args->'args'->>'kind', 'url', p_args->'args'->>'url', 'title', p_args->'args'->>'title', 'reason', v_reason));
      v_title := 'Read a central page: ' || replace(coalesce(p_args->'args'->>'kind', ''), '_', ' ') || ' for ' || coalesce((select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = (p_args->'args'->>'provider_id')::uuid), '');
      insert into pipeline.admin_jobs(kind, lane, title, args, progress, requested_by, reason, scope)
        values (v_kind, 'reads', v_title, jsonb_build_object('source_id', v_res->>'source_id', 'provider_id', p_args->'args'->>'provider_id', 'kind', p_args->'args'->>'kind', 'url', p_args->'args'->>'url', 'providers', jsonb_build_array(p_args->'args'->>'provider_id')), jsonb_build_object('done', 0, 'total', 1), auth.uid(), v_reason, p_args->'args'->>'provider_id')
        returning * into v_j;
      v_ids := array[(p_args->'args'->>'provider_id')::uuid];
    else
      raise exception 'unknown job kind';
    end if;
    insert into pipeline.admin_job_events(job_id, note, detail) values (v_j.id, 'queued by ' || coalesce((select u.email from auth.users u where u.id = auth.uid()), auth.uid()::text), jsonb_build_object('reason', v_reason));
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('jobs', 'job_start', v_j.id::text, jsonb_build_object('kind', v_kind, 'title', v_j.title, 'providers', array_length(v_ids, 1), 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'id', v_j.id, 'title', v_j.title, 'providers', array_length(v_ids, 1));
  end if;
  v_id := (p_args->>'id')::uuid;
  select * into v_j from pipeline.admin_jobs j where j.id = v_id;
  if v_j.id is null then raise exception 'unknown job'; end if;
  if v_rank < 5 and v_j.requested_by <> auth.uid() then raise exception 'only the person who started it, or an Operator, may change this job' using errcode = '42501'; end if;
  if p_action = 'cancel' then
    if v_j.state in ('done', 'failed', 'cancelled') then raise exception 'the job has already finished'; end if;
    if v_j.kind = 'reread_pages' then
      update pipeline.university_reread_requests set status = 'cancelled', finished_at = now() where id = (v_j.args->>'request_id')::uuid and status in ('waiting', 'sending');
    elsif v_j.kind = 'firecrawl_run' then
      perform public.admin_firecrawl_write('stop', jsonb_build_object('run_id', v_j.args->>'run_id', 'reason', v_reason));
    end if;
    if v_j.state in ('queued', 'paused') then
      update pipeline.admin_jobs set state = 'cancelled', finished_at = now(), updated_at = now(), cancel_requested = true where id = v_id;
      perform security.admin_job_close_v1(v_id);
    else
      update pipeline.admin_jobs set cancel_requested = true, updated_at = now() where id = v_id;
    end if;
  elsif p_action = 'pause' then
    if v_j.state not in ('queued', 'running') then raise exception 'only a queued or running job can be paused'; end if;
    if v_j.kind in ('reread_pages', 'adapter_apply', 'central_page_read') then raise exception 'this task cannot be paused, only cancelled'; end if;
    if v_j.kind = 'firecrawl_run' then perform public.admin_firecrawl_write('stop', jsonb_build_object('run_id', v_j.args->>'run_id', 'reason', v_reason)); end if;
    if v_j.state = 'queued' then
      update pipeline.admin_jobs set state = 'paused', updated_at = now() where id = v_id;
    else
      update pipeline.admin_jobs set pause_requested = true, updated_at = now() where id = v_id;
    end if;
  elsif p_action = 'resume' then
    if v_j.state <> 'paused' then raise exception 'only a paused job can be resumed'; end if;
    if v_j.kind = 'firecrawl_run' then perform public.admin_firecrawl_write('continue', jsonb_build_object('run_id', v_j.args->>'run_id', 'reason', v_reason)); end if;
    update pipeline.admin_jobs set state = 'queued', pause_requested = false, updated_at = now() where id = v_id;
  else
    raise exception 'unknown action';
  end if;
  insert into pipeline.admin_job_events(job_id, note, detail) values (v_id, p_action || ' requested by ' || coalesce((select u.email from auth.users u where u.id = auth.uid()), auth.uid()::text), jsonb_build_object('reason', v_reason));
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('jobs', 'job_' || p_action, v_id::text, jsonb_build_object('title', v_j.title, 'reason', v_reason), auth.uid());
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;


ALTER FUNCTION "public"."admin_jobs"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_key_date_action"("p_id" "uuid", "p_action" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v pipeline.important_dates%rowtype;
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if p_action not in ('cancel', 'restore') then raise exception 'unknown action %', p_action; end if;
  update pipeline.important_dates set status = case when p_action = 'cancel' then 'cancelled' else 'active' end, updated_by = auth.uid(), updated_at = now()
   where id = p_id returning * into v;
  if not found then raise exception 'date not found'; end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('key_dates', p_action, v.title, jsonb_build_object('id', p_id), auth.uid());
  return public.admin_key_dates_read();
end $$;


ALTER FUNCTION "public"."admin_key_date_action"("p_id" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_key_date_save"("p_id" "uuid", "p_fields" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_old pipeline.important_dates%rowtype; v_new pipeline.important_dates%rowtype; v_keys text[];
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if p_fields is null or jsonb_typeof(p_fields) <> 'object' then raise exception 'nothing to save'; end if;
  select array_agg(k) into v_keys from jsonb_object_keys(p_fields) k;
  if exists (select 1 from unnest(v_keys) k where k not in ('country','event_type','title','source_url','precision','starts_on','ends_on','wording','warning_days','scope','refresh_layer','entity_type','entity_id')) then
    raise exception 'unknown field'; end if;
  if p_fields ? 'source_url' and coalesce(p_fields->>'source_url', '') !~* '^https?://' then raise exception 'the source address must start with http:// or https://'; end if;
  if p_id is null then
    insert into pipeline.important_dates(country_code, event_type, title, source_url, scope_type, entity_type, entity_id, date_precision, starts_on, ends_on,
      timezone, source_wording, warning_window, refresh_layer, status, change_control_ref, created_by, updated_by)
    values (upper(coalesce(nullif(btrim(p_fields->>'country'), ''), 'AU')), coalesce(p_fields->>'event_type', 'national_education_event'), btrim(coalesce(p_fields->>'title', '')),
      btrim(coalesce(p_fields->>'source_url', '')), coalesce(nullif(p_fields->>'scope', ''), 'country_reference'), nullif(p_fields->>'entity_type', ''), nullif(p_fields->>'entity_id', '')::uuid,
      coalesce(p_fields->>'precision', 'exact'), nullif(p_fields->>'starts_on', '')::date, nullif(p_fields->>'ends_on', '')::date, 'Australia/Melbourne',
      nullif(btrim(coalesce(p_fields->>'wording', '')), ''), make_interval(days => coalesce(nullif(p_fields->>'warning_days', '')::int, 14)),
      nullif(p_fields->>'refresh_layer', '')::smallint, 'active', 'CF-CHG-20260915-247', auth.uid(), auth.uid())
    returning * into v_new;
    if length(v_new.title) < 3 then raise exception 'give the date a title'; end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('key_dates', 'add', v_new.title, jsonb_build_object('id', v_new.id), auth.uid());
    return public.admin_key_dates_read() || jsonb_build_object('saved', v_new.id);
  end if;
  select * into v_old from pipeline.important_dates where id = p_id for update;
  if not found then raise exception 'date not found'; end if;
  update pipeline.important_dates set
    country_code = case when p_fields ? 'country' then upper(btrim(p_fields->>'country')) else country_code end,
    event_type = case when p_fields ? 'event_type' then p_fields->>'event_type' else event_type end,
    title = case when p_fields ? 'title' then btrim(p_fields->>'title') else title end,
    source_url = case when p_fields ? 'source_url' then btrim(p_fields->>'source_url') else source_url end,
    date_precision = case when p_fields ? 'precision' then p_fields->>'precision' else date_precision end,
    starts_on = case when p_fields ? 'starts_on' then nullif(p_fields->>'starts_on', '')::date else starts_on end,
    starts_at = case when p_fields ? 'starts_on' then null else starts_at end,
    ends_on = case when p_fields ? 'ends_on' then nullif(p_fields->>'ends_on', '')::date else ends_on end,
    ends_at = case when p_fields ? 'ends_on' then null else ends_at end,
    source_wording = case when p_fields ? 'wording' then nullif(btrim(coalesce(p_fields->>'wording', '')), '') else source_wording end,
    warning_window = case when p_fields ? 'warning_days' then make_interval(days => (p_fields->>'warning_days')::int) else warning_window end,
    updated_by = auth.uid(), updated_at = now()
  where id = p_id returning * into v_new;
  if length(coalesce(v_new.title, '')) < 3 then raise exception 'give the date a title'; end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('key_dates', 'change', v_new.title, jsonb_build_object('id', p_id, 'fields', to_jsonb(v_keys),
          'before', jsonb_build_object('title', v_old.title, 'source_url', v_old.source_url, 'precision', v_old.date_precision, 'starts_on', v_old.starts_on,
                    'starts_at', v_old.starts_at, 'ends_on', v_old.ends_on, 'wording', v_old.source_wording, 'event_type', v_old.event_type, 'country', v_old.country_code)), auth.uid());
  return public.admin_key_dates_read() || jsonb_build_object('saved', p_id);
exception
  when check_violation then
    raise exception '%', case
      when sqlerrm like '%important_dates_check1%' then 'a vague date needs the wording from the source'
      when sqlerrm like '%exact_source_value%' then 'an exact date needs a date'
      when sqlerrm like '%bounded_scope%' then 'a date tied to a source, provider, course or scholarship needs which one'
      when sqlerrm like '%event_type%' then 'unknown kind of date'
      when sqlerrm like '%date_precision%' then 'unknown precision'
      else sqlerrm end;
end $$;


ALTER FUNCTION "public"."admin_key_date_save"("p_id" "uuid", "p_fields" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_key_dates_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 2 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  return jsonb_build_object('can_edit', v_rank >= 3,
    'items', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'country', d.country_code, 'event_type', d.event_type, 'title', d.title,
                'source_url', d.source_url, 'precision', d.date_precision, 'starts_on', coalesce(d.starts_on, (d.starts_at at time zone coalesce(d.timezone, 'Australia/Melbourne'))::date),
                'ends_on', coalesce(d.ends_on, (d.ends_at at time zone coalesce(d.timezone, 'Australia/Melbourne'))::date), 'wording', d.source_wording,
                'warning_days', extract(day from d.warning_window)::int, 'scope', d.scope_type, 'refresh_layer', d.refresh_layer, 'status', d.status, 'updated_at', d.updated_at)
              order by d.status <> 'active', coalesce(d.starts_on, d.starts_at::date) nulls last, d.title), '[]'::jsonb) from pipeline.important_dates d),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('at', e.created_at, 'action', e.action, 'target', e.target, 'by', u.email) order by e.created_at desc), '[]'::jsonb)
               from (select * from pipeline.admin_control_events where area = 'key_dates' order by created_at desc limit 15) e left join auth.users u on u.id = e.actor));
end $$;


ALTER FUNCTION "public"."admin_key_dates_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_layer1_schedule"("p_source_id" "uuid", "p_schedule" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_days int; v_auto boolean; v_before jsonb; v_after jsonb;
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_reason, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  select case p_schedule when 'daily' then 1 when 'weekly' then 7 when 'monthly' then 30 when 'quarterly' then 91 when 'yearly' then 365 when 'manual' then 30 end,
         p_schedule <> 'manual' into v_days, v_auto;
  if v_days is null then raise exception 'schedule must be daily, weekly, monthly, quarterly, yearly or manual'; end if;
  select jsonb_build_object('verification_cadence_days', verification_cadence_days, 'ingestion_cadence_days', ingestion_cadence_days, 'auto_ingest', auto_ingest)
    into v_before from pipeline.layer1_source_operations where source_id = p_source_id for update;
  if v_before is null then raise exception 'not a Layer 1 source'; end if;
  update pipeline.layer1_source_operations
     set verification_cadence_days = v_days, ingestion_cadence_days = case when p_schedule = 'manual' then ingestion_cadence_days else v_days end,
         auto_ingest = v_auto, next_verification_at = least(coalesce(next_verification_at, now() + make_interval(days => v_days)), now() + make_interval(days => v_days)),
         change_reason = left(p_reason, 500), updated_by = auth.uid(), updated_at = now()
   where source_id = p_source_id
  returning jsonb_build_object('verification_cadence_days', verification_cadence_days, 'ingestion_cadence_days', ingestion_cadence_days, 'auto_ingest', auto_ingest) into v_after;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer1', 'layer1_schedule_set', p_source_id::text, jsonb_build_object('schedule', p_schedule, 'before', v_before, 'after', v_after, 'reason', left(p_reason, 500)), auth.uid());
  return jsonb_build_object('ok', true, 'schedule', p_schedule) || v_after;
end $$;


ALTER FUNCTION "public"."admin_layer1_schedule"("p_source_id" "uuid", "p_schedule" "text", "p_reason" "text") OWNER TO "postgres";


