CREATE OR REPLACE FUNCTION "public"."admin_link_refresh_edit"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_country uuid; v_days int;
begin
  if auth.uid() is null or v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
  if p_action in ('save_policy') then
    v_days := nullif(p_args->>'every_days', '')::int;
    if v_days is null or v_days not between 1 and 365 then raise exception 'choose a number of days from 1 to 365'; end if;
    if not exists (select 1 from ref.course_link_types where code = p_args->>'link_type' and status = 'active') then raise exception 'choose a link type'; end if;
    if nullif(p_args->>'country', '') is not null then
      select id into v_country from ref.countries where iso_alpha2 = upper(p_args->>'country');
      if v_country is null then raise exception 'unknown country %', p_args->>'country'; end if;
    end if;
    if nullif(p_args->>'id', '') is not null then
      update pipeline.link_refresh_policies set every_days = v_days, active = coalesce((p_args->>'active')::boolean, active),
             notes = coalesce(nullif(p_args->>'notes', ''), notes), updated_at = now(), updated_by = auth.uid()
       where id = (p_args->>'id')::uuid;
    else
      insert into pipeline.link_refresh_policies(country_id, provider_id, link_type, every_days, active, notes, updated_by)
      values (v_country, nullif(p_args->>'provider_id', '')::uuid, p_args->>'link_type', v_days, coalesce((p_args->>'active')::boolean, true),
              nullif(p_args->>'notes', ''), auth.uid())
      on conflict on constraint link_refresh_policies_scope_key do update set every_days = excluded.every_days, active = excluded.active,
             notes = coalesce(excluded.notes, pipeline.link_refresh_policies.notes), updated_at = now(), updated_by = auth.uid();
    end if;
  elsif p_action = 'remove_policy' then
    delete from pipeline.link_refresh_policies where id = (p_args->>'id')::uuid and (country_id is not null or provider_id is not null);
    if not found then raise exception 'the all-countries policies stay; switch them off instead'; end if;
  elsif p_action = 'portal' then
    update pipeline.link_portals set active = coalesce((p_args->>'active')::boolean, active),
           every_days = coalesce(nullif(p_args->>'every_days', '')::int, every_days), updated_at = now()
     where code = p_args->>'code';
    if not found then raise exception 'unknown portal'; end if;
  else raise exception 'unknown action %', p_action; end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('link_refresh', p_action, coalesce(p_args->>'id', p_args->>'code', p_args->>'link_type'), p_args, auth.uid());
  return public.admin_link_refresh_read();
end $$;


ALTER FUNCTION "public"."admin_link_refresh_edit"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_link_refresh_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 1 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  return jsonb_build_object(
    'can_edit', v_rank >= 4,
    'policies', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'country', k.iso_alpha2, 'country_name', k.name, 'provider_id', r.provider_id,
                   'provider', coalesce(p.display_name, p.canonical_name), 'link_type', r.link_type, 'type_label', t.label, 'every_days', r.every_days,
                   'active', r.active, 'notes', r.notes, 'last_run_at', r.last_run_at, 'last_result', r.last_result)
                   order by t.sort, k.iso_alpha2 nulls first, p.canonical_name nulls first), '[]'::jsonb)
                   from pipeline.link_refresh_policies r join ref.course_link_types t on t.code = r.link_type
                   left join ref.countries k on k.id = r.country_id left join catalogue.providers p on p.id = r.provider_id),
    'portals', (select coalesce(jsonb_agg(jsonb_build_object('code', lp.code, 'label', lp.label, 'country', k.iso_alpha2, 'kind', lp.kind,
                   'link_type', lp.link_type, 'base_url', lp.base_url, 'applicant', lp.applicant, 'active', lp.active, 'every_days', lp.every_days,
                   'last_run_at', lp.last_run_at, 'last_result', lp.last_result, 'notes', lp.notes) order by k.iso_alpha2, lp.code), '[]'::jsonb)
                  from pipeline.link_portals lp left join ref.countries k on k.id = lp.country_id),
    'types', (select coalesce(jsonb_agg(jsonb_build_object('code', code, 'label', label) order by sort), '[]'::jsonb) from ref.course_link_types where status = 'active'),
    'countries', (select coalesce(jsonb_agg(distinct k.iso_alpha2), '[]'::jsonb) from catalogue.providers p join ref.countries k on k.id = p.country_id));
end $$;


ALTER FUNCTION "public"."admin_link_refresh_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_live_error_ack"("p_function" "text", "p_status" integer, "p_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline operator or admin role required' using errcode = '42501'; end if;
  insert into pipeline.live_error_acks(function_name, status_code, message_md5, acked_at, acked_by)
  values (coalesce(p_function, ''), coalesce(p_status, -1), md5(coalesce(p_message, '')), now(), auth.uid())
  on conflict (function_name, status_code, message_md5) do update set acked_at = now(), acked_by = auth.uid(), note = null;
  return security.admin_live_activity_v1();
end $$;


ALTER FUNCTION "public"."admin_live_error_ack"("p_function" "text", "p_status" integer, "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_pipeline_settings_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_fc record;
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
  select billing_config into v_fc from pipeline.layer2_acquisition_providers where provider_key = 'firecrawl';
  return jsonb_build_object(
    'can_change', security.current_role_rank() >= 6,
    'course_pages', jsonb_build_object(
      'matcher_prepare_universities', (select (regexp_match(command, 'prepare_v1\((\d+),'))[1]::int from cron.job where jobname = 'coverage-ai-match-prepare'),
      'matcher_prepare_courses', (select (regexp_match(command, 'prepare_v1\(\d+,\s*(\d+)\)'))[1]::int from cron.job where jobname = 'coverage-ai-match-prepare'),
      'matcher_items_per_minute', (select (substring(command from ',''(\{.*\})''::jsonb')::jsonb->>'limit')::int from cron.job where jobname = 'coverage-ai-match'),
      'matcher_concurrency', (select (substring(command from ',''(\{.*\})''::jsonb')::jsonb->>'concurrency')::int from cron.job where jobname = 'coverage-ai-match'),
      'search_per_minute', (select (substring(command from ',''(\{.*\})''::jsonb')::jsonb->>'limit')::int from cron.job where jobname = 'course-link-search-worker'),
      'search_monthly_credit_cap', (select monthly_credit_cap from pipeline.course_link_search_settings limit 1),
      'queued', jsonb_build_object('matcher_ready', (select count(*) from pipeline.coverage_ai_match where state = 'ready'),
                                   'matcher_never_offered', (select count(*) from pipeline.coverage_ai_match where state = 'none'),
                                   'searches_queued', (select count(*) from pipeline.course_link_search where state = 'queued')),
      'priority_countries', (select coalesce(jsonb_agg(k.iso_alpha2 order by p.sort), '[]'::jsonb) from pipeline.priority_pins p join ref.countries k on k.id = p.target_id where p.kind = 'country')),
    'reading', jsonb_build_object(
      'read_batch_per_30s', (select (substring(command from ',''(\{.*\})''::jsonb')::jsonb->>'limit')::int from cron.job where jobname = 'coverage-read'),
      'pages_waiting', (select count(*) from pipeline.coverage_course_pages where status = 'bound' and read_status is null)),
    'identity', (select jsonb_object_agg(k.iso_alpha2, jsonb_build_object('active', c.active, 'currency', c.currency_code, 'identities', c.identities, 'approved_ref', c.approved_ref))
                   from pipeline.coverage_admission_countries c join ref.countries k on k.id = c.country_id),
    'layer3', jsonb_build_object(
      'budgets', (select jsonb_agg(jsonb_build_object('task_class', task_class, 'daily_usd_max', daily_usd_max, 'credit_floor_usd', credit_floor_usd, 'route_mode', route_mode) order by task_class) from pipeline.layer3_route_budget),
      'route_limit', (select (substring(command from ',''(\{.*\})''::jsonb')::jsonb->>'limit')::int from cron.job where jobname = 'layer3-intake-route'),
      'route_concurrency', (select (substring(command from ',''(\{.*\})''::jsonb')::jsonb->>'concurrency')::int from cron.job where jobname = 'layer3-intake-route'),
      'requests_per_day', (select min(requests_per_day) from pipeline.layer3_model_profiles where enabled and retired_at is null and code ~ '^openrouter-(intake|english)-l3[cr]-'),
      'profiles', (select coalesce(jsonb_agg(jsonb_build_object('code', p.code, 'model', p.model_identifier, 'tasks', p.allowed_task_classes, 'prompt_version', p.prompt_profile_version,
                       'prompt_hash', md5(coalesce(p.prompt_system, '')), 'prompt_chars', length(coalesce(p.prompt_system, '')), 'requests_per_day', p.requests_per_day,
                       'enabled', p.enabled, 'paused', p.paused, 'holdout', p.holdout_qualification,
                       'tiers', (select jsonb_agg(jsonb_build_object('task', t.task_class, 'tier', t.tier_no, 'active', t.active, 'final', t.is_final) order by t.task_class, t.tier_no) from pipeline.layer3_route_tiers t where t.profile_id = p.id)) order by p.code), '[]'::jsonb)
                     from pipeline.layer3_model_profiles p where p.retired_at is null),
      'spent_today_usd', (select jsonb_object_agg(task_class, round(usd, 3)) from (select task_class, sum(estimated_cost_usd) usd from pipeline.layer3_interpretations where created_at >= date_trunc('day', now() at time zone 'UTC') at time zone 'UTC' group by 1) z)),
    'budgets', jsonb_build_object(
      'firecrawl_monthly_limit', (v_fc.billing_config->>'monthly_vendor_units_limit')::int,
      'firecrawl_stop_at_remaining', (v_fc.billing_config->>'stop_at_vendor_units_remaining')::int,
      'firecrawl_used_this_month', (select coalesce(sum(units), 0) from pipeline.coverage_vendor_usage where at >= date_trunc('month', now())),
      'firecrawl_by_purpose', (select jsonb_object_agg(purpose, u) from (select purpose, sum(units) u from pipeline.coverage_vendor_usage where at >= date_trunc('month', now()) group by 1) z),
      'openrouter', (select jsonb_build_object('remaining_usd', remaining_usd, 'observed_at', observed_at) from pipeline.layer3_openrouter_observations where kind = 'credits' order by observed_at desc limit 1)),
    'recent_changes', (select coalesce(jsonb_agg(jsonb_build_object('at', created_at, 'area', area, 'action', action, 'target', target) order by created_at desc), '[]'::jsonb)
                         from (select * from pipeline.admin_control_events where area in ('settings', 'layer3', 'automations', 'course_link_search', 'requeue') order by created_at desc limit 20) e));
end $$;


ALTER FUNCTION "public"."admin_pipeline_settings_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_pipeline_settings_write"("p_key" "text", "p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v int; v_n numeric; v_txt text; v_before jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  v_before := public.admin_pipeline_settings_read();
  case p_key
    when 'course_pages.matcher_prepare_universities' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 500 then raise exception 'between 1 and 500'; end if;
      perform cron.alter_job(job_id := (select jobid from cron.job where jobname = 'coverage-ai-match-prepare'),
        command := format('select security.coverage_ai_match_prepare_v1(%s, %s)', v, coalesce((v_before#>>'{course_pages,matcher_prepare_courses}')::int, 1000)));
    when 'course_pages.matcher_prepare_courses' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 5000 then raise exception 'between 1 and 5,000'; end if;
      perform cron.alter_job(job_id := (select jobid from cron.job where jobname = 'coverage-ai-match-prepare'),
        command := format('select security.coverage_ai_match_prepare_v1(%s, %s)', coalesce((v_before#>>'{course_pages,matcher_prepare_universities}')::int, 200), v));
    when 'course_pages.matcher_items_per_minute' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 200 then raise exception 'between 1 and 200'; end if;
      perform security.pipeline_setting_cron_arg('coverage-ai-match', 'limit', v);
    when 'course_pages.matcher_concurrency' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 24 then raise exception 'between 1 and 24'; end if;
      perform security.pipeline_setting_cron_arg('coverage-ai-match', 'concurrency', v);
    when 'course_pages.search_per_minute' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 120 then raise exception 'between 1 and 120'; end if;
      perform security.pipeline_setting_cron_arg('course-link-search-worker', 'limit', v);
    when 'course_pages.search_monthly_credit_cap' then
      perform public.admin_course_link_search_settings((p_value#>>'{}')::int);
    when 'reading.read_batch_per_30s' then
      v := (p_value#>>'{}')::int; if v < 10 or v > 200 then raise exception 'between 10 and 200'; end if;
      perform security.pipeline_setting_cron_arg('coverage-read', 'limit', v);
    when 'layer3.route_limit' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 200 then raise exception 'between 1 and 200'; end if;
      perform security.pipeline_setting_cron_arg('layer3-intake-route', 'limit', v);
      perform security.pipeline_setting_cron_arg('layer3-english-route', 'limit', v);
    when 'layer3.route_concurrency' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 16 then raise exception 'between 1 and 16'; end if;
      perform security.pipeline_setting_cron_arg('layer3-intake-route', 'concurrency', v);
      perform security.pipeline_setting_cron_arg('layer3-english-route', 'concurrency', v);
    when 'layer3.requests_per_day' then
      v := (p_value#>>'{}')::int; if v < 1000 or v > 100000 then raise exception 'between 1,000 and 100,000'; end if;
      update pipeline.layer3_model_profiles set requests_per_day = v, updated_at = now()
       where enabled and retired_at is null and code ~ '^openrouter-(intake|english)-l3[cr]-';
    when 'layer3.daily_usd_max' then
      v_txt := p_value->>'task_class'; v_n := (p_value->>'value')::numeric;
      if v_n < 0 or v_n > 200 then raise exception 'between 0 and 200 USD'; end if;
      update pipeline.layer3_route_budget set daily_usd_max = v_n, updated_at = now() where task_class = v_txt;
      if not found then raise exception 'task % not found', v_txt; end if;
    when 'layer3.credit_floor_usd' then
      v_n := (p_value#>>'{}')::numeric; if v_n < 0 or v_n > 100 then raise exception 'between 0 and 100 USD'; end if;
      update pipeline.layer3_route_budget set credit_floor_usd = v_n, updated_at = now() where task_class in ('provider_intake_validation', 'provider_english_validation', 'provider_current_tuition_validation');
    when 'identity.attribute' then
      if not (p_value->>'attribute') in ('official_url', 'english', 'intakes', 'tuition') then raise exception 'attribute must be official_url, english, intakes or tuition'; end if;
      if exists (select 1 from jsonb_array_elements_text(p_value->'identities') x where x not in ('cricos_code', 'nzqa_code', 'exact_title', 'title_level', 'field_award', 'degree_name')) then raise exception 'unknown identity'; end if;
      update pipeline.coverage_admission_countries c
         set identities = jsonb_set(c.identities, array[p_value->>'attribute'], coalesce(p_value->'identities', '[]'::jsonb), true), updated_at = now(),
             approved_ref = c.approved_ref || format('; Settings page, Platform Admin %s (%s: %s)', to_char(now() at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI'), p_value->>'attribute', p_value->'identities')
        from ref.countries k where k.id = c.country_id and k.iso_alpha2 = p_value->>'country';
      if not found then raise exception 'country % not found', p_value->>'country'; end if;
    else raise exception 'unknown setting %', p_key;
  end case;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('settings', 'change', p_key, jsonb_build_object('value', p_value, 'before', v_before #> string_to_array(p_key, '.')), auth.uid());
  return public.admin_pipeline_settings_read();
end $$;


ALTER FUNCTION "public"."admin_pipeline_settings_write"("p_key" "text", "p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_platform_cost_model_save_v1"("p_item_key" "text", "p_monthly_usd" numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank() < 6 then raise exception 'Platform Admin role is required' using errcode='42501'; end if;
  if p_monthly_usd is null or p_monthly_usd < -100000 or p_monthly_usd > 100000 then raise exception 'monthly amount out of range' using errcode='22023'; end if;
  update pipeline.platform_cost_model set monthly_usd=p_monthly_usd, notes=coalesce(p_notes,notes), updated_by=auth.uid(), updated_at=now()
   where item_key=p_item_key and basis<>'usage_actual';
  if not found then raise exception 'unknown or usage-based cost item' using errcode='22023'; end if;
  return public.admin_platform_resources_read_v1(30);
end $$;


ALTER FUNCTION "public"."admin_platform_cost_model_save_v1"("p_item_key" "text", "p_monthly_usd" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_platform_notices_read"("p_layer" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  v := security.platform_notices_v1() || coalesce(security.toolset_sample_notices_v1(), '[]'::jsonb);
  return jsonb_build_object('can_manage', v_rank >= 6, 'generated_at', now(),
    'notices', coalesce((select jsonb_agg(n || jsonb_build_object('acknowledged', a.acknowledged_at is not null and a.acknowledged_at >= (n->>'last_at')::timestamptz,
                                                                   'acknowledged_at', a.acknowledged_at, 'ack_reason', a.reason)
                                          order by case n->>'severity' when 'high' then 0 when 'warning' then 1 else 2 end, (n->>'last_at') desc)
                         from jsonb_array_elements(v) n left join pipeline.platform_notice_acks a on a.notice_key = n->>'key'
                         where p_layer is null or (n->>'layer')::int = p_layer), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."admin_platform_notices_read"("p_layer" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_platform_resources_read_v1"("p_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$
declare v jsonb; d int := greatest(7,least(coalesce(p_days,30),180)); cp pipeline.platform_compute_profile%rowtype; growth numeric; latest pipeline.platform_resource_observations%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank() < 5 then raise exception 'PIM Admin role is required' using errcode='42501'; end if;
  select * into cp from pipeline.platform_compute_profile where id=1;
  select * into latest from pipeline.platform_resource_observations order by observed_at desc limit 1;
  with daily as (select date_trunc('day',observed_at) dd, max(db_bytes) b from pipeline.platform_resource_observations where observed_at >= now()-make_interval(days=>d) group by 1)
  select regr_slope(b, extract(epoch from dd)/86400.0) into growth from daily;
  select jsonb_build_object(
    'compute', to_jsonb(cp) - 'updated_by',
    'latest', to_jsonb(latest),
    'memory_ratio', round(latest.db_bytes::numeric/nullif(cp.memory_bytes,0),2),
    'growth_bytes_per_day', round(coalesce(growth,0)),
    'days_until_memory', case when coalesce(growth,0) > 0 and latest.db_bytes < cp.memory_bytes then floor((cp.memory_bytes-latest.db_bytes)/growth) end,
    'thresholds', (select to_jsonb(p) - 'notification_target' from pipeline.platform_capacity_policy p where environment='pilot'),
    'daily', coalesce((select jsonb_agg(x order by x->>'day') from (
        select jsonb_build_object('day',date_trunc('day',observed_at)::date,'db_bytes',max(db_bytes),'cache_hit_pct',min(cache_hit_pct),
          'cron_failures',sum(cron_failures),'cron_max_seconds',max(cron_max_seconds),'cron_max_concurrent',max(cron_max_concurrent),
          'acquisition_units',sum(coalesce((select sum((a->>'units')::numeric) from jsonb_array_elements(acquisition) a),0)),
          'ai_cost_usd',sum(ai_cost_usd)) x
        from pipeline.platform_resource_observations where observed_at >= now()-make_interval(days=>d) group by date_trunc('day',observed_at)) z),'[]'::jsonb),
    'storage', (select jsonb_build_object('evidence_object_bytes',evidence_object_bytes,'evidence_objects',evidence_object_count,'orphans',orphan_object_count,'observed_at',observed_at)
                from pipeline.platform_capacity_observations order by observed_at desc limit 1),
    'costs', (select jsonb_build_object(
        'items', coalesce(jsonb_agg(jsonb_build_object('key',item_key,'label',label,'category',category,'basis',basis,
                 'monthly_usd', case when basis='usage_actual' and category='ai' then coalesce(latest.ai_cost_mtd_usd,0) else monthly_usd end,'notes',notes) order by category, item_key),'[]'::jsonb),
        'total_monthly_usd', sum(case when basis='usage_actual' and category='ai' then coalesce(latest.ai_cost_mtd_usd,0) else monthly_usd end),
        'acquisition_units_mtd', latest.acquisition_units_mtd, 'acquisition_cost_mtd_usd', latest.acquisition_cost_mtd_usd)
      from pipeline.platform_cost_model),
    'can_edit', security.current_role_rank() >= 6)
  into v;
  return v;
end $$;


ALTER FUNCTION "public"."admin_platform_resources_read_v1"("p_days" integer) OWNER TO "postgres";


