CREATE OR REPLACE FUNCTION "public"."admin_provider_applicants_edit"("p_provider_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); p catalogue.providers%rowtype; v_val boolean; v_n int := 0;
        v_reason text := nullif(btrim(coalesce(p_args->>'reason', '')), '');
begin
  if auth.uid() is null or v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
  select * into p from catalogue.providers where id = p_provider_id;
  if p.id is null then raise exception 'provider not found'; end if;
  if not (p_args ? 'enrols_international') or jsonb_typeof(p_args->'enrols_international') not in ('boolean','null') then raise exception 'choose yes, no or not known'; end if;
  v_val := (p_args->>'enrols_international')::boolean;
  perform set_config('cf.manual_edit', 'on', true);
  update catalogue.providers set enrols_international = v_val, enrols_international_basis = 'Set by hand', updated_at = now() where id = p_provider_id;
  perform security.manual_lock_set('provider', p_provider_id, 'enrols_international', 'value');
  if coalesce((p_args->>'apply_to_courses')::boolean, true) then
    update catalogue.courses c set open_to_international = v_val, applicant_basis = 'Provider setting', updated_at = now()
     where c.provider_id = p_provider_id and c.open_to_international is distinct from v_val
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field = 'open_to_international');
    get diagnostics v_n = row_count;
  end if;
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('provider', p_provider_id, 'enrols_international', 'set', to_jsonb(p.enrols_international),
          jsonb_build_object('value', v_val, 'courses_changed', v_n), v_reason, auth.uid());
  return jsonb_build_object('provider_id', p_provider_id, 'enrols_international', v_val, 'courses_changed', v_n);
end $$;


ALTER FUNCTION "public"."admin_provider_applicants_edit"("p_provider_id" "uuid", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_applicants_read"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); p record;
begin
  if auth.uid() is null or v_rank < 1 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  select pr.id, pr.enrols_international, pr.enrols_international_basis, k.iso_alpha2::text country into p
    from catalogue.providers pr left join ref.countries k on k.id = pr.country_id where pr.id = p_provider_id;
  if p.id is null then raise exception 'provider not found'; end if;
  return jsonb_build_object(
    'can_edit', v_rank >= 4,
    'enrols_international', p.enrols_international,
    'basis', p.enrols_international_basis,
    'country', p.country,
    'locked', exists (select 1 from pipeline.manual_locks k where k.entity = 'provider' and k.entity_id = p_provider_id and k.field = 'enrols_international'),
    'courses', (select jsonb_build_object(
                  'open_to_international', count(*) filter (where c.open_to_international is true),
                  'domestic_only', count(*) filter (where c.open_to_international is false),
                  'not_known', count(*) filter (where c.open_to_international is null),
                  'set_by_hand', count(*) filter (where exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field = 'open_to_international')))
                  from catalogue.courses c where c.provider_id = p_provider_id and c.lifecycle_status = 'active'));
end $$;


ALTER FUNCTION "public"."admin_provider_applicants_read"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_calendar_set"("p_provider_id" "uuid", "p_periods" "jsonb", "p_url" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_id uuid; v_src uuid; v_clean jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if not exists (select 1 from catalogue.providers where id = p_provider_id) then raise exception 'provider not found'; end if;
  if coalesce(btrim(p_url), '') !~* '^https?://' then raise exception 'the calendar page address is required'; end if;
  select jsonb_agg(jsonb_build_object('period', lower(btrim(e->>'period')), 'months', jsonb_build_array((e->>'month')::int)))
    into v_clean
    from jsonb_array_elements(coalesce(p_periods, '[]'::jsonb)) e
   where lower(btrim(e->>'period')) ~ '^(semester|trimester|term|session|study_period|teaching_period) [1-6]$' and (e->>'month') ~ '^([1-9]|1[0-2])$';
  if v_clean is null then raise exception 'give at least one period (for example semester 1) with a month from 1 to 12'; end if;
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, found_via, status)
  values (p_provider_id, 'intake_calendar', btrim(p_url), 'Calendar page given by a Platform Admin', 9, 'manual', 'found')
  on conflict on constraint provider_fact_sources_key do nothing;
  select id into v_src from pipeline.provider_fact_sources where provider_id = p_provider_id and kind = 'intake_calendar' and url = btrim(p_url);
  insert into pipeline.provider_policy_proposals(provider_id, fact_source_id, kind, parser, url, style, proposal, status, decided_by, decided_at, decision_note)
  values (p_provider_id, v_src, 'intake_calendar', 'set by hand', btrim(p_url), 'by_hand', jsonb_build_object('periods', v_clean), 'approved', auth.uid(), now(), left(p_note, 500))
  returning id into v_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('policies', 'calendar_set', btrim(p_url), jsonb_build_object('decision', 'Decision 228', 'proposal_id', v_id, 'provider_id', p_provider_id, 'periods', v_clean), auth.uid());
  return jsonb_build_object('id', v_id, 'to_answer', (select count(*) from security.semester_intake_plan_v1(p_provider_id) r where r.outcome = 'answer'));
end $_$;


ALTER FUNCTION "public"."admin_provider_calendar_set"("p_provider_id" "uuid", "p_periods" "jsonb", "p_url" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_central_page"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid := (p_args->>'provider_id')::uuid;
        v_kind text := p_args->>'kind'; v_url text := btrim(coalesce(p_args->>'url', '')); v_id uuid;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if p_action not in ('add', 'read_again') then raise exception 'unknown action'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
  if coalesce(v_kind, '') not in ('english_policy', 'intake_calendar', 'fee_schedule') then raise exception 'kind must be english_policy, intake_calendar or fee_schedule'; end if;
  if v_url !~ '^https?://[^ ]+$' or length(v_url) not between 12 and 500 then raise exception 'give the full page address (http or https)'; end if;
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, found_via, status)
    values (v_pid, v_kind, v_url, nullif(btrim(coalesce(p_args->>'title', '')), ''), 9, 'manual', 'found')
  on conflict (provider_id, kind, url) do update set status = 'found', attempts = 0, rank = 9, found_via = 'manual', updated_at = now() where pipeline.provider_fact_sources.provider_id = excluded.provider_id
  returning id into v_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('toolsets', 'central_page_' || p_action, v_pid::text, jsonb_build_object('source_id', v_id, 'kind', v_kind, 'url', v_url, 'reason', v_reason), auth.uid());
  return jsonb_build_object('ok', true, 'source_id', v_id, 'note', 'The page is read through Firecrawl by the provider-facts job within about 10 minutes, then parsed into a proposal for approval in Layer 4 Review › Attributes.');
end $_$;


ALTER FUNCTION "public"."admin_provider_central_page"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_create"("p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_id uuid := gen_random_uuid(); v_name text := nullif(btrim(coalesce(p_args->>'name', '')), ''); v_country uuid := nullif(p_args->>'country_id', '')::uuid;
        v_web text := nullif(btrim(coalesce(p_args->>'website', '')), '');
begin
  if auth.uid() is null or security.current_role_rank() < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
  if v_name is null then raise exception 'enter the provider name'; end if;
  if v_country is null or not exists (select 1 from ref.countries where id = v_country) then raise exception 'choose the country'; end if;
  if v_web is not null and v_web !~* '^https?://[^\s/]+\.[^\s]+$' then raise exception 'enter a full web address starting with https://'; end if;
  if exists (select 1 from catalogue.providers where lower(canonical_name) = lower(v_name) and country_id = v_country) then raise exception 'a provider with this name already exists in that country'; end if;
  perform set_config('cf.manual_edit', 'on', true);
  insert into catalogue.providers(id, stable_key, canonical_name, display_name, country_id, subdivision_id, website, primary_city, lifecycle_status)
  values (v_id, 'manual:' || v_id, v_name, v_name, v_country, nullif(p_args->>'subdivision_id', '')::uuid, v_web, nullif(btrim(coalesce(p_args->>'city', '')), ''), 'active');
  if v_web is not null then
    insert into pipeline.coverage_provider_discovery(provider_id, website, status, attempts, next_due_at, updated_at) values (v_id, v_web, 'pending', 0, now(), now())
    on conflict (provider_id) do nothing;
  end if;
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, after, reason, actor)
  values ('provider', v_id, null, 'create', p_args, nullif(btrim(coalesce(p_args->>'reason', '')), ''), auth.uid());
  return public.admin_provider_edit_read(v_id);
end $_$;


ALTER FUNCTION "public"."admin_provider_create"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_credit_fee"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid; v_id uuid; v_ids uuid[]; v_src uuid; v_res jsonb; v_ev uuid;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'read' then
    return coalesce((select jsonb_agg(to_jsonb(x) - 'course_ids' || jsonb_build_object('courses', cardinality(x.course_ids)) order by x.set_at desc) from pipeline.provider_credit_fees x where x.provider_id = (p_args->>'provider_id')::uuid), '[]'::jsonb);
  elsif p_action = 'add' then
    v_pid := (p_args->>'provider_id')::uuid;
    if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
    if jsonb_typeof(p_args->'course_ids') <> 'array' or jsonb_array_length(p_args->'course_ids') = 0 then raise exception 'give the courses the rate applies to'; end if;
    v_ids := array(select distinct x::uuid from jsonb_array_elements_text(p_args->'course_ids') x);
    if exists (select 1 from unnest(v_ids) x where not exists (select 1 from catalogue.courses co where co.id = x and co.provider_id = v_pid)) then raise exception 'every course must belong to this university'; end if;
    if coalesce(p_args->>'source_url', '') !~ '^https?://[^ ]+$' then raise exception 'give the page that prints the rate'; end if;
    select s.id into v_src from pipeline.provider_fact_sources s where s.provider_id = v_pid and s.url = btrim(p_args->>'source_url') order by s.updated_at desc limit 1;
    if v_src is null then
      select pg.evidence_id into v_ev from pipeline.coverage_course_pages pg
       where pg.provider_id = v_pid and pg.read_status = 'read' and pg.evidence_id is not null and pg.candidates->>'final_url' = btrim(p_args->>'source_url') limit 1;
    end if;
    if v_src is null and v_ev is null then raise exception 'attach the rate page as a central page first, or give a course page read in the international view, so it is read with evidence'; end if;
    insert into pipeline.provider_credit_fees(provider_id, label, course_ids, rate, rate_credits, annual_credits, fee_year, currency_code, source_url, fact_source_id, evidence_id, reason, set_by)
      values (v_pid, btrim(coalesce(p_args->>'label', 'per-credit rate')), v_ids, (p_args->>'rate')::numeric, (p_args->>'rate_credits')::numeric, (p_args->>'annual_credits')::numeric,
              (p_args->>'fee_year')::int, upper(btrim(p_args->>'currency_code')), btrim(p_args->>'source_url'), v_src, v_ev, v_reason, auth.uid())
      returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'credit_fee_add', v_pid::text, jsonb_build_object('rule_id', v_id, 'args', p_args - 'course_ids', 'courses', cardinality(v_ids), 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'id', v_id, 'annual_fee', round((p_args->>'rate')::numeric / (p_args->>'rate_credits')::numeric * (p_args->>'annual_credits')::numeric, 2));
  elsif p_action = 'apply' then
    v_id := (p_args->>'id')::uuid;
    v_res := security.provider_credit_fee_apply_v1(v_id);
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'credit_fee_apply', v_id::text, jsonb_build_object('result', v_res, 'reason', v_reason), auth.uid());
    return v_res;
  elsif p_action = 'off' then
    v_id := (p_args->>'id')::uuid;
    update pipeline.provider_credit_fees set active = false, reason = v_reason, set_by = auth.uid(), set_at = now() where id = v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'credit_fee_off', v_id::text, jsonb_build_object('reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true);
  end if;
  raise exception 'unknown action';
end $_$;


ALTER FUNCTION "public"."admin_provider_credit_fee"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_edit"("p_provider_id" "uuid", "p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_p catalogue.providers%rowtype; v_field text; v_before jsonb; v_after jsonb; v_val jsonb; v_url text;
        v_reason text := nullif(btrim(coalesce(p_args->>'reason', '')), '');
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  select * into v_p from catalogue.providers where id = p_provider_id;
  if v_p.id is null then raise exception 'provider not found'; end if;
  if p_action in ('archive','restore') and v_rank < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
  perform set_config('cf.manual_edit', 'on', true);

  if p_action = 'set_core' then
    v_field := p_args->>'field';
    if v_field is null or v_field not in ('display_name','short_name','website','phone','email','description','primary_city','address_line1','postcode') then raise exception 'this field cannot be edited here'; end if;
    v_val := p_args->'value';
    if jsonb_typeof(v_val) = 'string' then v_val := to_jsonb(nullif(btrim(v_val #>> '{}'), '')); end if;
    if v_field = 'website' and v_val is not null and v_val <> 'null'::jsonb and (v_val #>> '{}') !~* '^https?://[^\s/]+\.[^\s]+$' then raise exception 'enter a full web address starting with https://'; end if;
    if v_field = 'email' and v_val is not null and v_val <> 'null'::jsonb and (v_val #>> '{}') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'enter a valid email address'; end if;
    v_before := to_jsonb(v_p)->v_field;
    update catalogue.providers p set display_name = r.display_name, short_name = r.short_name, website = r.website, phone = r.phone, email = r.email,
           description = r.description, primary_city = r.primary_city, address_line1 = r.address_line1, postcode = r.postcode, updated_at = now()
      from (select (jsonb_populate_record(x0, jsonb_build_object(v_field, v_val))).* from catalogue.providers x0 where x0.id = p_provider_id) r
     where p.id = p_provider_id;
    perform security.manual_lock_set('provider', p_provider_id, v_field, 'value');
    v_after := v_val;

  elsif p_action = 'set_course_finder' then
    v_field := 'course_finder'; v_url := btrim(coalesce(p_args->>'url', ''));
    if v_url !~* '^https?://[^\s/]+\.[^\s]+$' then raise exception 'enter a full web address starting with https://'; end if;
    select to_jsonb(d.website) into v_before from pipeline.coverage_provider_discovery d where d.provider_id = p_provider_id;
    insert into pipeline.coverage_provider_discovery(provider_id, website, status, attempts, next_due_at, updated_at)
    values (p_provider_id, v_url, 'pending', 0, now(), now())
    on conflict (provider_id) do update set website = excluded.website, status = 'pending', attempts = 0, next_due_at = now(), leased_until = null,
           last_error = null, updated_at = now();
    v_after := to_jsonb(v_url);

  elsif p_action = 'release' then
    v_field := p_args->>'field';
    select to_jsonb(l) into v_before from pipeline.manual_locks l where entity = 'provider' and entity_id = p_provider_id and field = v_field;
    if v_before is null then raise exception 'nothing to release'; end if;
    delete from pipeline.manual_locks where entity = 'provider' and entity_id = p_provider_id and field = v_field;

  elsif p_action in ('archive','restore') then
    v_field := 'lifecycle_status'; v_before := to_jsonb(v_p.lifecycle_status);
    update catalogue.providers set lifecycle_status = case p_action when 'archive' then 'inactive' else 'active' end, updated_at = now() where id = p_provider_id;
    perform security.manual_lock_set('provider', p_provider_id, 'lifecycle_status', 'value');
    v_after := to_jsonb(case p_action when 'archive' then 'inactive' else 'active' end);

  else
    raise exception 'unknown action %', p_action;
  end if;

  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('provider', p_provider_id, v_field, p_action, v_before, v_after, v_reason, auth.uid());
  return public.admin_provider_edit_read(p_provider_id);
end $_$;


ALTER FUNCTION "public"."admin_provider_edit"("p_provider_id" "uuid", "p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_edit_read"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  if not exists (select 1 from catalogue.providers where id = p_provider_id) then raise exception 'provider not found'; end if;
  return (select jsonb_build_object(
    'provider', jsonb_build_object('id', p.id, 'canonical_name', p.canonical_name, 'display_name', p.display_name, 'short_name', p.short_name,
               'website', p.website, 'phone', p.phone, 'email', p.email, 'description', p.description, 'primary_city', p.primary_city,
               'address_line1', p.address_line1, 'postcode', p.postcode, 'lifecycle_status', p.lifecycle_status, 'country', k.name, 'state', s.name,
               'manual_provider', p.stable_key like 'manual:%',
               'active_courses', (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')),
    'course_finder', (select jsonb_build_object('address', d.website, 'status', d.status, 'pages_found', d.kept_count, 'mapped_at', d.mapped_at)
                        from pipeline.coverage_provider_discovery d where d.provider_id = p.id),
    'link_recipe', (select jsonb_build_object('search_domain', r.search_domain, 'patterns', r.patterns, 'active', r.active)
                      from pipeline.course_link_recipes r where r.provider_id = p.id),
    'locks', (select coalesce(jsonb_object_agg(l.field, jsonb_build_object('mode', l.mode, 'at', l.set_at)), '{}'::jsonb)
               from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = p.id),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('at', h.at, 'field', h.field, 'action', h.action, 'before', h.before, 'after', h.after,
               'reason', h.reason, 'by', u.email) order by h.at desc), '[]'::jsonb)
               from (select * from pipeline.manual_edit_log where entity = 'provider' and entity_id = p.id order by at desc limit 20) h left join auth.users u on u.id = h.actor),
    'can_edit', v_rank >= 3, 'can_manage', v_rank >= 5)
   from catalogue.providers p left join ref.countries k on k.id = p.country_id left join ref.subdivisions s on s.id = p.subdivision_id where p.id = p_provider_id);
end $$;


ALTER FUNCTION "public"."admin_provider_edit_read"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_english_propose"("p_provider_id" "uuid", "p_rule" "jsonb", "p_url" "text", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_id uuid; v_src uuid; v_ev uuid; v_defaults jsonb := '{}'::jsonb; v_ex jsonb := '[]'::jsonb; v_prop jsonb; k text; r jsonb; v_note text := btrim(coalesce(p_note, ''));
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if not exists (select 1 from catalogue.providers where id = p_provider_id) then raise exception 'provider not found'; end if;
  if coalesce(btrim(p_url), '') !~* '^https?://' then raise exception 'the central English page address is required'; end if;
  if length(v_note) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  -- one requirement: IELTS overall from 4 to 9 in halves, optional lowest band
  for k in select x from unnest(array['undergraduate', 'postgraduate']) x loop
    r := p_rule->k;
    continue when r is null;
    if (r->>'overall') !~ '^[4-9](\.[05])?$' or coalesce(r->>'min_band', '5') !~ '^[3-9](\.[05])?$' then raise exception 'the % rule needs an IELTS overall (and lowest band) from 4 to 9 in halves', k; end if;
    v_defaults := v_defaults || jsonb_build_object(k, jsonb_build_array(jsonb_build_object('test_code', 'IELTS', 'overall_score', (r->>'overall')::numeric,
                    'component_scores', case when r ? 'min_band' then jsonb_build_object('listening', (r->>'min_band')::numeric, 'reading', (r->>'min_band')::numeric, 'writing', (r->>'min_band')::numeric, 'speaking', (r->>'min_band')::numeric) else '{}'::jsonb end,
                    'quote', left(coalesce(r->>'quote', ''), 400))));
  end loop;
  for r in select e from jsonb_array_elements(coalesce(p_rule->'named', '[]'::jsonb)) e loop
    if length(btrim(coalesce(r->>'name', ''))) < 4 or (r->>'overall') !~ '^[4-9](\.[05])?$' or coalesce(r->>'min_band', '5') !~ '^[3-9](\.[05])?$' then raise exception 'each named course needs a name and an IELTS overall (and lowest band) from 4 to 9 in halves'; end if;
    v_ex := v_ex || jsonb_build_array(jsonb_build_object('name', btrim(r->>'name'), 'level', null, 'reqs', jsonb_build_array(jsonb_build_object('test_code', 'IELTS', 'overall_score', (r->>'overall')::numeric,
              'component_scores', case when r ? 'min_band' then jsonb_build_object('listening', (r->>'min_band')::numeric, 'reading', (r->>'min_band')::numeric, 'writing', (r->>'min_band')::numeric, 'speaking', (r->>'min_band')::numeric) else '{}'::jsonb end,
              'quote', left(coalesce(r->>'quote', ''), 400)))));
  end loop;
  if v_defaults = '{}'::jsonb and jsonb_array_length(v_ex) = 0 then raise exception 'give at least one level rule or named course'; end if;
  v_prop := jsonb_build_object('parser', 'written out from the central page', 'style', case when v_defaults = '{}'::jsonb then 'named_courses' else 'level_default' end,
                               'defaults', v_defaults, 'exceptions', v_ex, 'named', '[]'::jsonb, 'caveats', '[]'::jsonb, 'signals', '[]'::jsonb, 'conflicts', '[]'::jsonb);
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, found_via, status)
  values (p_provider_id, 'english_policy', btrim(p_url), 'Central English page given by a Platform Admin', 9, 'manual', 'found')
  on conflict on constraint provider_fact_sources_key do nothing;
  select id, evidence_id into v_src, v_ev from pipeline.provider_fact_sources where provider_id = p_provider_id and kind = 'english_policy' and url = btrim(p_url);
  insert into pipeline.provider_policy_proposals(provider_id, fact_source_id, kind, parser, content_hash, evidence_id, url, style, proposal, status, decision_note)
  values (p_provider_id, v_src, 'english_policy', 'written out from the central page', md5(v_prop::text), v_ev, btrim(p_url), v_prop->>'style', v_prop, 'proposed', left(v_note, 500))
  on conflict (fact_source_id, parser, content_hash) do nothing
  returning id into v_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('policies', 'english_rule_proposed', btrim(p_url), jsonb_build_object('decision', 'Decision 254', 'proposal_id', v_id, 'provider_id', p_provider_id, 'rule', p_rule, 'note', v_note), auth.uid());
  return jsonb_build_object('id', v_id, 'note', 'Approve or reject it in Layer 4 Review › Attributes.');
end $_$;


ALTER FUNCTION "public"."admin_provider_english_propose"("p_provider_id" "uuid", "p_rule" "jsonb", "p_url" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_newer_year"("p_action" "text", "p_source_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f pipeline.provider_fact_sources%rowtype; x record; v_src uuid; v_n int := 0; v_err int := 0; v_last text; v_rows jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('preview', 'apply') then raise exception 'action must be preview or apply'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_source_id for update;
  if f.id is null or f.kind <> 'fee_schedule' or f.status <> 'parsed' or f.decision is distinct from 'approved' then raise exception 'not an approved parsed fee schedule'; end if;
  if p_action = 'preview' then
    select coalesce(jsonb_agg(jsonb_build_object('course_code', course_code, 'title', course_title, 'schedule_amount', amount, 'schedule_year', fee_year, 'current_amount', current_amount, 'current_year', cur_year) order by course_title), '[]'::jsonb) into v_rows from (select o.*, cf.fee_year cur_year from security.provider_fee_proposal_rows(p_source_id) o
    join lateral (select y.fee_year from catalogue.course_fees y where y.course_id = o.course_id and y.fee_type = 'provider_current_tuition' and y.status = 'active' and y.audience = 'international'
                   order by y.fee_year desc nulls last limit 1) cf on true
   where o.outcome = 'differs' and o.fee_year is not null and cf.fee_year is not null and o.fee_year > cf.fee_year) ny;
    return jsonb_build_object('rows', v_rows, 'count', jsonb_array_length(v_rows));
  end if;
  if length(btrim(coalesce(p_note, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if f.evidence_id is null or f.content_hash is null then raise exception 'the document has no stored evidence; read it again first'; end if;
  v_src := security.coverage_sweep_source(f.provider_id);
  for x in select o.*, cf.fee_year cur_year from security.provider_fee_proposal_rows(p_source_id) o
    join lateral (select y.fee_year from catalogue.course_fees y where y.course_id = o.course_id and y.fee_type = 'provider_current_tuition' and y.status = 'active' and y.audience = 'international'
                   order by y.fee_year desc nulls last limit 1) cf on true
   where o.outcome = 'differs' and o.fee_year is not null and cf.fee_year is not null and o.fee_year > cf.fee_year loop
    begin
      perform security.coverage_apply_course_v1(x.course_id, v_src, f.evidence_id, f.url, f.content_hash,
        jsonb_build_object('fee_amount', x.amount, 'currency_code', x.currency_code, 'fee_year', x.fee_year, 'fee_basis', x.basis,
          'fee_notes', 'Later-year fee from the provider''s international fee schedule; approved by a Platform Admin'));
      v_n := v_n + 1;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fees', 'newer_year_fees_applied', f.url, jsonb_build_object('source_id', f.id, 'provider_id', f.provider_id, 'written', v_n, 'refused', v_err, 'last_error', v_last, 'reason', left(p_note, 500)), auth.uid());
  return jsonb_build_object('written', v_n, 'refused', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "public"."admin_provider_fee_newer_year"("p_action" "text", "p_source_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_range"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', ''));
  v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_res jsonb; v_r catalogue.provider_fee_ranges%rowtype;
  v_low numeric; v_high numeric; v_levels text[];
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Layer 4 reviewer or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'read' then
    if v_pid is null then
      return jsonb_build_object('settings', (select to_jsonb(s) - 'id' from pipeline.provider_fee_range_settings s where s.id = 1),
               'levels', (select jsonb_agg(jsonb_build_object('code', l.code, 'name', l.name) order by l.sort_order) from ref.study_levels l where l.status = 'active'),
               'ranges', coalesce((select jsonb_agg(security.provider_fee_range_json_v1(r.provider_id)) from catalogue.provider_fee_ranges r
                                    where p_args->>'scope' = 'all' or exists (select 1 from pipeline.uni_adapters a where a.provider_id = r.provider_id)), '[]'::jsonb));
    end if;
    return jsonb_build_object('range', security.provider_fee_range_json_v1(v_pid),
             'courses', coalesce((select jsonb_agg(to_jsonb(w) order by w.skip nulls first, w.whole_fee) from (select * from security.provider_course_whole_fees_v1(v_pid) limit 2000) w), '[]'::jsonb));
  end if;
  if coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'refresh' then
    v_res := security.provider_fee_ranges_refresh_v1(v_pid);
  elsif p_action = 'publish' then
    select * into v_r from catalogue.provider_fee_ranges r where r.provider_id = v_pid;
    if v_r.provider_id is null then raise exception 'no range for this provider yet (refresh first)'; end if;
    if coalesce(v_r.manual_low, v_r.low_amount) is null or coalesce(v_r.manual_high, v_r.high_amount) is null then raise exception 'no range to publish'; end if;
    if not v_r.meets_minimum and v_r.manual_low is null and v_r.manual_high is null then raise exception 'fewer courses than the minimum in the settings: set the range by hand or lower the minimum'; end if;
    update catalogue.provider_fee_ranges set published = true, published_by = auth.uid(), published_at = now(), publish_reason = v_reason where provider_id = v_pid;
    v_res := jsonb_build_object('ok', true, 'published', true);
  elsif p_action = 'unpublish' then
    update catalogue.provider_fee_ranges set published = false, published_by = auth.uid(), published_at = now(), publish_reason = v_reason where provider_id = v_pid;
    v_res := jsonb_build_object('ok', true, 'published', false);
  elsif p_action = 'set' then
    v_low := nullif(p_args->>'low', '')::numeric; v_high := nullif(p_args->>'high', '')::numeric;
    if v_low is null or v_high is null or v_low <= 0 or v_high < v_low then raise exception 'give a lowest and a highest amount (lowest no more than highest)'; end if;
    insert into catalogue.provider_fee_ranges(provider_id) values (v_pid) on conflict (provider_id) do nothing;
    update catalogue.provider_fee_ranges set manual_low = v_low, manual_high = v_high, manual_note = nullif(btrim(coalesce(p_args->>'note', '')), ''), manual_by = auth.uid(), manual_at = now() where provider_id = v_pid;
    v_res := jsonb_build_object('ok', true);
  elsif p_action = 'release' then
    update catalogue.provider_fee_ranges set manual_low = null, manual_high = null, manual_note = null, manual_by = auth.uid(), manual_at = now() where provider_id = v_pid;
    v_res := jsonb_build_object('ok', true);
  elsif p_action = 'settings' then
    select array_agg(x) into v_levels from jsonb_array_elements_text(coalesce(p_args->'excluded_level_codes', '[]'::jsonb)) x;
    if exists (select 1 from unnest(coalesce(v_levels, '{}')) x where x not in (select l.code from ref.study_levels l)) then raise exception 'unknown study level'; end if;
    update pipeline.provider_fee_range_settings set include_under_one_year = coalesce((p_args->>'include_under_one_year')::boolean, include_under_one_year), min_courses = coalesce((p_args->>'min_courses')::int, min_courses), min_fee_year = coalesce((p_args->>'min_fee_year')::int, min_fee_year), min_whole_fee = coalesce((p_args->>'min_whole_fee')::numeric, min_whole_fee), excluded_level_codes = coalesce(v_levels, excluded_level_codes), updated_by = auth.uid(), updated_at = now(), reason = v_reason where id = 1;
    v_res := security.provider_fee_ranges_refresh_v1(null);
  else
    raise exception 'unknown action';
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('coverage', 'fee_range_' || p_action, coalesce(v_pid::text, 'all'), jsonb_build_object('result', v_res, 'args', p_args), auth.uid());
  return v_res;
end $$;


ALTER FUNCTION "public"."admin_provider_fee_range"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_schedule_decide"("p_source_id" "uuid", "p_action" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f pipeline.provider_fact_sources%rowtype; x record; v_src uuid; v_n int := 0; v_err int := 0; v_sum jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('approve','reject') then raise exception 'action must be approve or reject'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_source_id for update;
  if f.id is null or f.kind <> 'fee_schedule' or f.status <> 'parsed' then raise exception 'not a parsed fee schedule'; end if;
  if f.decision is not null then raise exception 'already decided (%)', f.decision; end if;
  if p_action = 'reject' then
    update pipeline.provider_fact_sources set decision = 'rejected', decided_by = auth.uid(), decided_at = now(), decision_note = left(p_note, 500), updated_at = now() where id = p_source_id;
    return jsonb_build_object('decision', 'rejected');
  end if;
  if f.evidence_id is null or f.content_hash is null then raise exception 'the document has no stored evidence; read it again first'; end if;
  v_src := security.coverage_sweep_source(f.provider_id);
  -- what the document proposed, counted before anything is written
  select jsonb_object_agg(o, n) into v_sum from (select outcome o, count(*) n from security.provider_fee_proposal_rows(p_source_id) group by 1) s;
  for x in select * from security.provider_fee_proposal_rows(p_source_id) where outcome = 'new' loop
    begin
      perform security.coverage_apply_course_v1(x.course_id, v_src, f.evidence_id, f.url, f.content_hash,
        jsonb_build_object('fee_amount', x.amount, 'currency_code', x.currency_code, 'fee_year', x.fee_year, 'fee_basis', x.basis,
                           'fee_notes', 'From the provider''s international fee schedule; approved by a Platform Admin'));
      v_n := v_n + 1;
    exception when others then v_err := v_err + 1;
    end;
  end loop;
  v_sum := coalesce(v_sum, '{}'::jsonb) || jsonb_build_object('written', v_n, 'refused', v_err) || jsonb_build_object('flags', security.fee_schedule_settle_flags_v1(p_source_id));
  update pipeline.provider_fact_sources set decision = 'approved', decided_by = auth.uid(), decided_at = now(), decision_note = left(p_note, 500),
         apply_summary = v_sum, updated_at = now() where id = p_source_id;
  return jsonb_build_object('decision', 'approved') || v_sum;
end $$;


ALTER FUNCTION "public"."admin_provider_fee_schedule_decide"("p_source_id" "uuid", "p_action" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_schedule_refile"("p_source_id" "uuid", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f pipeline.provider_fact_sources%rowtype; x record; v_src uuid; v_n int := 0; v_err int := 0; v_last text;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_source_id for update;
  if f.id is null or f.kind <> 'fee_schedule' or f.status <> 'parsed' or f.decision is distinct from 'approved' then raise exception 'not an approved parsed fee schedule'; end if;
  if length(btrim(coalesce(p_note, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if f.evidence_id is null or f.content_hash is null then raise exception 'the document has no stored evidence; read it again first'; end if;
  v_src := security.coverage_sweep_source(f.provider_id);
  for x in select * from security.provider_fee_proposal_rows(p_source_id) where outcome = 'new' loop
    begin
      perform security.coverage_apply_course_v1(x.course_id, v_src, f.evidence_id, f.url, f.content_hash,
        jsonb_build_object('fee_amount', x.amount, 'currency_code', x.currency_code, 'fee_year', x.fee_year, 'fee_basis', x.basis,
                           'fee_notes', 'From the provider''s international fee schedule; refiled by a Platform Admin'));
      v_n := v_n + 1;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fees', 'fee_schedule_refiled', f.url, jsonb_build_object('source_id', f.id, 'provider_id', f.provider_id, 'written', v_n, 'refused', v_err, 'last_error', v_last, 'reason', left(p_note, 500)), auth.uid());
  return jsonb_build_object('written', v_n, 'refused', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "public"."admin_provider_fee_schedule_refile"("p_source_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_schedules_read"("p_source_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 4 then raise exception 'pipeline operator role required' using errcode = '42501'; end if;
  if p_source_id is not null then
    return jsonb_build_object('can_decide', v_rank >= 6, 'rows', coalesce((select jsonb_agg(to_jsonb(x) order by x.outcome, x.course_code)
             from security.provider_fee_proposal_rows(p_source_id) x), '[]'::jsonb));
  end if;
  return jsonb_build_object(
    'can_decide', v_rank >= 6,
    'totals', (select jsonb_build_object(
        'documents_found', count(*) filter (where f.kind = 'fee_schedule'),
        'documents_read', count(*) filter (where f.kind = 'fee_schedule' and f.status in ('parsed','no_values')),
        'with_fee_rows', count(*) filter (where f.status = 'parsed'),
        'awaiting_decision', count(*) filter (where f.status = 'parsed' and f.decision is null),
        'providers_searched', (select count(distinct s.provider_id) from pipeline.provider_fact_search s where s.kind = 'fee_schedule' and s.state <> 'queued'),
        'providers_queued', (select count(*) from pipeline.provider_fact_search s where s.kind = 'fee_schedule' and s.state = 'queued'))
        from pipeline.provider_fact_sources f),
    'documents', coalesce((select jsonb_agg(d order by d->>'decided_at' desc nulls first, (d->>'new')::int desc) from (
        select jsonb_build_object('id', f.id, 'provider_id', f.provider_id, 'provider', coalesce(p.display_name, p.canonical_name), 'country', security.coverage_country(f.provider_id), 'url', f.url, 'fee_year', f.parse_summary->>'fee_year',
               'read_at', f.read_at, 'decision', f.decision, 'decided_at', f.decided_at, 'apply_summary', f.apply_summary,
               'rows', (select count(*) from security.provider_fee_proposal_rows(f.id)),
               'new', (select count(*) from security.provider_fee_proposal_rows(f.id) x where x.outcome = 'new'),
               'same', (select count(*) from security.provider_fee_proposal_rows(f.id) x where x.outcome = 'same'),
               'differs', (select count(*) from security.provider_fee_proposal_rows(f.id) x where x.outcome = 'differs'),
               'no_course', (select count(*) from security.provider_fee_proposal_rows(f.id) x where x.outcome = 'no_course')) d
          from pipeline.provider_fact_sources f join catalogue.providers p on p.id = f.provider_id
         where f.status = 'parsed' order by (f.decision is null) desc, f.read_at desc limit greatest(1, least(coalesce(p_limit, 50), 300))) q), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."admin_provider_fee_schedules_read"("p_source_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_year_relabel"("p_action" "text", "p_source_later" "uuid", "p_source_earlier" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare fl pipeline.provider_fact_sources%rowtype; fe pipeline.provider_fact_sources%rowtype; v_rows jsonb; v_all jsonb; x jsonb; v_src uuid; v_n int := 0; v_err int := 0; v_last text;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('preview', 'apply') then raise exception 'action must be preview or apply'; end if;
  select * into fl from pipeline.provider_fact_sources where id = p_source_later for update;
  select * into fe from pipeline.provider_fact_sources where id = p_source_earlier for update;
  if fl.id is null or fe.id is null or fl.provider_id <> fe.provider_id or fl.kind <> 'fee_schedule' or fe.kind <> 'fee_schedule'
     or fl.decision is distinct from 'approved' or fe.decision is distinct from 'approved' or fl.status <> 'parsed' or fe.status <> 'parsed' then
    raise exception 'two approved parsed fee schedules of one provider are required'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('course_id', l.course_id, 'title', l.course_title, 'later_amount', l.amount, 'later_year', l.fee_year, 'later_basis', l.basis, 'later_currency', l.currency_code,
         'earlier_amount', e.amount, 'earlier_year', e.fee_year, 'earlier_basis', e.basis, 'earlier_currency', e.currency_code) order by l.course_title), '[]'::jsonb) into v_all
    from security.provider_fee_proposal_rows(p_source_later) l
    join security.provider_fee_proposal_rows(p_source_earlier) e on e.course_id = l.course_id
   where l.fee_year is not null and e.fee_year is not null and l.fee_year > e.fee_year and l.course_id is not null and l.basis = 'annual' and e.basis = 'annual'
     and exists (select 1 from catalogue.course_fees y where y.course_id = l.course_id and y.fee_type = 'provider_current_tuition' and y.status = 'active' and y.audience = 'international'
                 and y.fee_year = e.fee_year and abs(y.amount - l.amount) < 1)
     and abs(e.amount - l.amount) >= 1
     and not exists (select 1 from catalogue.course_fees y where y.course_id = l.course_id and y.fee_type = 'provider_current_tuition' and y.status = 'active' and y.audience = 'international' and y.fee_year = l.fee_year);
  select coalesce(jsonb_agg(el - 'course_id'), '[]'::jsonb) into v_rows from jsonb_array_elements(v_all) el;
  if p_action = 'preview' then return jsonb_build_object('count', jsonb_array_length(v_all), 'rows', v_rows); end if;
  if length(btrim(coalesce(p_note, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if fl.evidence_id is null or fe.evidence_id is null or fl.content_hash is null or fe.content_hash is null then raise exception 'both documents need stored evidence'; end if;
  v_src := security.coverage_sweep_source(fl.provider_id);
  for x in select el from jsonb_array_elements(v_all) el loop
    begin
      perform security.coverage_apply_course_v1((x->>'course_id')::uuid, v_src, fe.evidence_id, fe.url, fe.content_hash,
        jsonb_build_object('fee_amount', (x->>'earlier_amount')::numeric, 'currency_code', x->>'earlier_currency', 'fee_year', (x->>'earlier_year')::int, 'fee_basis', x->>'earlier_basis',
          'fee_notes', 'Earlier-year fee from the provider''s international fee schedule; the page figure was the later year; approved by a Platform Admin'));
      perform security.coverage_apply_course_v1((x->>'course_id')::uuid, v_src, fl.evidence_id, fl.url, fl.content_hash,
        jsonb_build_object('fee_amount', (x->>'later_amount')::numeric, 'currency_code', x->>'later_currency', 'fee_year', (x->>'later_year')::int, 'fee_basis', x->>'later_basis',
          'fee_notes', 'Later-year fee from the provider''s international fee schedule; matches the course page; approved by a Platform Admin'));
      v_n := v_n + 1;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fees', 'fee_year_relabelled', fl.url, jsonb_build_object('later_source', fl.id, 'earlier_source', fe.id, 'provider_id', fl.provider_id, 'courses', v_n, 'refused', v_err, 'last_error', v_last, 'reason', left(p_note, 500)), auth.uid());
  return jsonb_build_object('courses', v_n, 'refused', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "public"."admin_provider_fee_year_relabel"("p_action" "text", "p_source_later" "uuid", "p_source_earlier" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_policies_read"("p_kind" "text" DEFAULT 'english_policy'::"text", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
  if p_kind not in ('english_policy', 'intake_calendar') then raise exception 'kind must be english_policy or intake_calendar'; end if;
  if p_id is not null then
    select jsonb_build_object('proposal', to_jsonb(x) - 'content_hash', 'provider', coalesce(p.display_name, p.canonical_name),
             'rows', case when x.kind = 'english_policy' then (select coalesce(jsonb_agg(jsonb_build_object('course_id', r.course_id, 'title', r.title, 'study_level', r.study_level,
                   'plan', r.plan, 'reason', r.reason, 'outcome', r.outcome, 'existing', r.existing,
                   'ielts', (select q->'overall_score' from jsonb_array_elements(r.requirements) q where q->>'test_code' = 'IELTS' limit 1))
                   order by case r.outcome when 'write' then 0 when 'differs' then 1 when 'agrees' then 2 else 3 end, r.title), '[]'::jsonb)
                   from security.provider_english_plan_v1(x.id) r) end)
      into v from pipeline.provider_policy_proposals x join catalogue.providers p on p.id = x.provider_id
     where x.id = p_id and x.kind = p_kind;
    if v is null then raise exception 'proposal not found'; end if;
    return v;
  end if;
  select jsonb_build_object(
    'can_decide', security.current_role_rank() >= 6,
    'totals', jsonb_build_object(
      'documents_found', (select count(*) from pipeline.provider_fact_sources f where f.kind = p_kind),
      'documents_read', (select count(*) from pipeline.provider_fact_sources f where f.kind = p_kind and f.status in ('read', 'parsed', 'no_values')),
      'providers_found', (select count(distinct f.provider_id) from pipeline.provider_fact_sources f where f.kind = p_kind),
      'no_values_by_style', (select coalesce(jsonb_object_agg(coalesce(style, 'none'), n), '{}'::jsonb) from (select style, count(*) n from pipeline.provider_policy_proposals
                               where kind = p_kind and status = 'no_values' group by 1) s)),
    'proposals', (select coalesce(jsonb_agg(jsonb_build_object(
         'id', x.id, 'provider_id', x.provider_id, 'provider', coalesce(p.display_name, p.canonical_name), 'country', k.iso_alpha2,
         'url', x.url, 'style', x.style, 'status', x.status, 'parser', x.parser, 'created_at', x.created_at,
         'decided_at', x.decided_at, 'decision_note', x.decision_note, 'apply_summary', x.apply_summary,
         'caveats', x.proposal->'caveats', 'conflicts', x.proposal->'conflicts',
         'defaults', x.proposal->'defaults', 'periods', x.proposal->'periods',
         'named_requirements', (select count(*) from jsonb_array_elements(coalesce(x.proposal->'exceptions', '[]'::jsonb)) e where jsonb_typeof(e->'reqs') = 'array' and jsonb_array_length(e->'reqs') > 0),
         'named_courses', jsonb_array_length(coalesce(x.proposal->'named', '[]'::jsonb)),
         'plan', x.plan_summary, 'plan_at', x.plan_at)
       order by (x.status = 'proposed') desc, coalesce(p.display_name, p.canonical_name)), '[]'::jsonb)
       from pipeline.provider_policy_proposals x join catalogue.providers p on p.id = x.provider_id left join ref.countries k on k.id = p.country_id
      where x.kind = p_kind and x.status in ('proposed', 'approved', 'rejected'))) into v;
  return v;
end $$;


ALTER FUNCTION "public"."admin_provider_policies_read"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_policy_decide"("p_id" "uuid", "p_action" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare x pipeline.provider_policy_proposals%rowtype; v jsonb := '{}'::jsonb; v_ag int := 0; v_df int := 0; v_sum jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('approve', 'reject') then raise exception 'action must be approve or reject'; end if;
  select * into x from pipeline.provider_policy_proposals where id = p_id for update;
  if x.id is null then raise exception 'proposal not found'; end if;
  if x.status <> 'proposed' then raise exception 'already decided or not a proposal (%)', x.status; end if;
  if p_action = 'approve' and x.kind = 'english_policy' then
    v_sum := security.provider_policy_refresh_one_v1(p_id);
    v_ag := coalesce((v_sum->>'agrees')::int, 0); v_df := coalesce((v_sum->>'differs')::int, 0);
    if v_ag + v_df >= 10 and v_df > v_ag then
      raise exception 'This default does not match most course pages (% agree, % differ), so it cannot be approved', v_ag, v_df;
    end if;
  end if;
  update pipeline.provider_policy_proposals set status = case when p_action = 'approve' then 'approved' else 'rejected' end,
         decided_by = auth.uid(), decided_at = now(), decision_note = left(p_note, 500), updated_at = now() where id = p_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('policies', p_action, x.kind || ': ' || x.url, jsonb_build_object('decision', 'Decision 227', 'proposal_id', x.id, 'provider_id', x.provider_id), auth.uid());
  -- one approved document per university and kind: its other waiting documents are closed
  if p_action = 'approve' then
    update pipeline.provider_policy_proposals
       set status = 'superseded', decided_at = now(), updated_at = now(),
           decision_note = 'Closed: another document for this university was approved (' || x.url || ')'
     where provider_id = x.provider_id and kind = x.kind and status = 'proposed' and id <> x.id;
  end if;
  if p_action = 'approve' and x.kind = 'english_policy' then v := jsonb_build_object('to_fill', coalesce((v_sum->>'write')::int, 0)); end if;
  if p_action = 'approve' and x.kind = 'intake_calendar' then
    v := jsonb_build_object('to_answer', (select count(*) from security.semester_intake_plan_v1(x.provider_id) r where r.outcome = 'answer'));
  end if;
  return jsonb_build_object('status', case when p_action = 'approve' then 'approved' else 'rejected' end) || v;
end $$;


ALTER FUNCTION "public"."admin_provider_policy_decide"("p_id" "uuid", "p_action" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_policy_decide_bulk"("p_ids" "uuid"[], "p_action" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid; v_ok int := 0; v_fill int := 0; v_skip jsonb := '[]'::jsonb; r jsonb; v_status text;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('approve', 'reject') then raise exception 'action must be approve or reject'; end if;
  if coalesce(cardinality(p_ids), 0) = 0 or cardinality(p_ids) > 200 then raise exception 'choose between 1 and 200 documents'; end if;
  foreach v_id in array p_ids loop
    -- a document closed earlier in this same action (another of its university was approved) is skipped
    select status into v_status from pipeline.provider_policy_proposals where id = v_id;
    if v_status is distinct from 'proposed' then
      v_skip := v_skip || jsonb_build_object('id', v_id, 'reason', case when v_status = 'superseded' then 'another document for this university was approved' else 'already decided' end);
      continue;
    end if;
    begin
      r := public.admin_provider_policy_decide(v_id, p_action, p_note);
      v_ok := v_ok + 1; v_fill := v_fill + coalesce((r->>'to_fill')::int, 0);
    exception when others then
      v_skip := v_skip || jsonb_build_object('id', v_id, 'reason', sqlerrm);
    end;
  end loop;
  return jsonb_build_object('done', v_ok, 'to_fill', v_fill, 'skipped', v_skip);
end $$;


ALTER FUNCTION "public"."admin_provider_policy_decide_bulk"("p_ids" "uuid"[], "p_action" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_website_set"("p_provider_id" "uuid", "p_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_url text := btrim(coalesce(p_url, '')); v_dom text;
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if v_url !~* '^https?://[^\s/]+\.[^\s]+$' then raise exception 'enter a full web address starting with https://'; end if;
  -- recorded as entered by hand (locked, logged) through the provider editor
  perform public.admin_provider_edit(p_provider_id, 'set_core', jsonb_build_object('field', 'website', 'value', v_url));
  perform public.admin_provider_edit(p_provider_id, 'set_course_finder', jsonb_build_object('url', v_url));
  update pipeline.coverage_provider_discovery set site_source = 'manual', site_searched_at = now(), updated_at = now() where provider_id = p_provider_id;
  v_dom := lower(regexp_replace(substring(v_url from '^(?:https?://)?([^/:?#]+)'), '^www\.', ''));
  if v_dom ~ '^[a-z0-9.-]+\.[a-z]{2,}$' then
    insert into pipeline.course_link_recipes(provider_id, search_domain, patterns, active, notes, updated_at)
    select p_provider_id, v_dom,
           jsonb_build_array(jsonb_build_object(
             're', '(?i)^https?://([a-z0-9-]+\.)*' || regexp_replace(v_dom, '\.', '\\.', 'g')
                   || '/(?!.*\.(pdf|docx?|xlsx?|pptx?|jpe?g|png|gif|svg|zip)$)(?!(.*/)?(news|events?|blog|staff|people|media|search|tags?|category)(/|$)).+$',
             'rep', '\&')),
           true, 'Generic recipe: any page on the provider''s own site, from a website entered by a person; used only when the reader proves the page is the course''s (Decision 222, 2 Oct 2026)', now()
     where not exists (select 1 from pipeline.course_link_recipes x where x.provider_id = p_provider_id);
    insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at)
    select c.id, c.provider_id, case when c.course_code ~ '^[0-9]{6}[0-9A-Z]$' then 'cricos' else 'title' end, 'queued', now()
      from catalogue.courses c
     where c.provider_id = p_provider_id and c.lifecycle_status = 'active'
       and exists (select 1 from pipeline.course_link_recipes x where x.provider_id = p_provider_id and x.active)
       and not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c.id)
    on conflict (course_id) do nothing;
  end if;
  return public.admin_provider_websites('{}'::jsonb);
end $_$;


ALTER FUNCTION "public"."admin_provider_website_set"("p_provider_id" "uuid", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_websites"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_country text := upper(nullif(p_args->>'country', '')); v_lim int := least(greatest(coalesce((p_args->>'limit')::int, 50), 1), 200);
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  return (with q as (
    select p.id, coalesce(p.display_name, p.canonical_name) name, k.iso_alpha2::text country, d.site_searched_at, d.site_evidence,
           (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active') courses,
           (select min(upper(r.registration_code)) from catalogue.provider_registrations r where r.provider_id = p.id and lower(r.registration_scheme) = 'cricos') cricos,
           (select min(upper(r.registration_code)) from catalogue.provider_registrations r where r.provider_id = p.id and lower(r.registration_scheme) = 'ircc_dli') dli
      from pipeline.coverage_provider_discovery d join catalogue.providers p on p.id = d.provider_id join ref.countries k on k.id = p.country_id
     where d.status = 'no_website' and d.site_searched_at is not null and (v_country is null or k.iso_alpha2 = v_country))
    select jsonb_build_object('total', (select count(*) from q), 'can_edit', true,
      'countries', coalesce((select jsonb_object_agg(country, n) from (select country, count(*) n from q group by 1) c), '{}'::jsonb),
      'items', coalesce((select jsonb_agg(jsonb_build_object('provider_id', id, 'name', name, 'country', country, 'courses', courses, 'cricos', cricos, 'dli', dli,
                 'searched_at', site_searched_at, 'query', site_evidence->>'query', 'note', site_evidence->>'note',
                 'tried', coalesce((select jsonb_agg(t->>'page') from jsonb_array_elements(coalesce(site_evidence->'tried', '[]'::jsonb)) t where t->>'page' is not null), '[]'::jsonb))
               order by courses desc, name) from (select * from q order by courses desc, name limit v_lim) z), '[]'::jsonb)));
end $$;


ALTER FUNCTION "public"."admin_provider_websites"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_ranking_link"("p_publisher_institution_id" "uuid", "p_action" "text", "p_provider_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_cid uuid; v_n int;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role required' using errcode = '42501'; end if;
  if p_action = 'run_rules' then
    if v_rank < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
    return security.ranking_link_auto_v1();
  end if;
  if p_action not in ('link', 'reject') or p_provider_id is null then raise exception 'action must be link or reject, with a provider'; end if;
  select security.ranking_country_id(country_text) into v_cid from ranking.publisher_institutions where id = p_publisher_institution_id;
  if not found then raise exception 'publisher institution not found'; end if;
  if p_action = 'reject' then
    update ranking.provider_mappings set status = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(), note = coalesce(left(p_note, 300), note)
     where publisher_institution_id = p_publisher_institution_id and provider_id = p_provider_id and status = 'candidate';
    return jsonb_build_object('rejected', true);
  end if;
  if not exists (select 1 from catalogue.providers p where p.id = p_provider_id and p.lifecycle_status = 'active' and (v_cid is null or p.country_id = v_cid)) then
    raise exception 'the provider must be active and in the same country as the ranked university';
  end if;
  v_n := security.ranking_link_apply_v1(p_publisher_institution_id, p_provider_id, 'manual_person', left(coalesce(p_note, 'Linked by a person'), 300), auth.uid());
  return jsonb_build_object('linked', true, 'observations_linked', v_n);
end $$;


ALTER FUNCTION "public"."admin_ranking_link"("p_publisher_institution_id" "uuid", "p_action" "text", "p_provider_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'security'
    AS $$
declare v_result jsonb;v_id uuid;
begin
 if p_operation='platform_health' then return security.admin_platform_health_v1(p_args); end if;
 if p_operation='live_activity' then return security.admin_live_activity_v1(); end if;
 if p_operation in ('course_coverage','course_coverage_courses','course_coverage_providers') then return security.admin_course_coverage_read(p_operation,p_args); end if;
 if p_operation='scholarship_ai' then return security.scholarship_ai_control_read_impl(coalesce(nullif(p_args->>'country_code',''),'AU')); end if;
 if p_operation='layer3_queue_status' then return security.layer3_queue_status_read_v1(); end if;
 if p_operation='admin_filter_option_page' then return security.admin_filter_option_page(p_args); end if;
 if p_operation='dashboard' then return security.admin_dashboard_maturity(); end if;
 if p_operation='layer_status_summary' then return security.admin_layer_status_summary(); end if;
 if p_operation='catalogue_filter_page' then return security.admin_catalogue_filter_page(p_args); end if;
 if p_operation in ('provider_filters','course_filters') then return security.admin_catalogue_filter_options(p_operation,p_args); end if;
 if p_operation='evidence_page' then return security.admin_evidence_page(p_args); end if;
 if p_operation in ('evidence_filters','evidence_detail','evidence_observations','evidence_entities') then return security.admin_evidence_read(p_operation,p_args); end if;
 if p_operation='courses_page' then return security.admin_course_page_fast(p_args); end if;
 if p_operation='campuses_page' then return security.admin_campus_page_fast(p_args); end if;
 if p_operation in ('providers_page','scholarships_page') then return security.admin_catalogue_page(p_operation,p_args); end if;
 if p_operation in ('qilt_outcomes','qilt_filters','prisms_student_flow','prisms_filters') then return security.admin_insights_read(p_operation,p_args); end if;
 if p_operation='ranking_imports' then return security.admin_ranking_imports_read(p_args); end if;
 if p_operation in ('ranking_summary','ranking_filters','ranking_observations') then return security.admin_ranking_read(p_operation,p_args); end if;
 if p_operation in ('ranking_filter_options','ranking_link_candidates','ranking_provider_search','provider_ranking_history') then return security.admin_ranking_links_read(p_operation,p_args); end if;
 if p_operation in ('provider_asset_summary','provider_asset_coverage','provider_asset_context') then return security.admin_provider_asset_read(p_operation,p_args); end if;
 if p_operation in ('provider_contacts_page','provider_contact_detail','provider_contact_imports','provider_contact_import_detail') then return security.admin_provider_contact_read(p_operation,p_args); end if;
 if p_operation='contextual_compare' then return security.admin_contextual_compare(p_args); end if;
 if p_operation='reviews_page' then return security.admin_operational_page(p_operation,p_args); end if;
 if p_operation='layer2_dispatcher_tuning' then return security.admin_layer2_dispatcher_tuning_read_v1(p_args); end if;
 if p_operation='enrichment_operations' then return security.admin_enrichment_operations_read(p_args); end if;
 if p_operation='jobs_runtime' then return security.admin_jobs_runtime_read_v1(p_args); end if;
 if p_operation in ('reviews','jobs','sources') then return security.admin_operations_read(p_operation,p_args); end if;
 if p_operation='layer1_operations' then return security.admin_layer1_operations_read(p_args); end if;
 if p_operation='layer2_ops_alerts' then return security.layer2_operational_alerts_read(); end if;
 if p_operation='layer2_parent_runs' then return security.admin_layer2_parent_runs(coalesce(nullif(p_args->>'limit','')::integer,10)); end if;
 if p_operation='layer2_ops_overview' then return security.admin_layer2_ops_read('layer2_ops_overview',p_args); end if;
 if p_operation='layer2_ops_run_detail' then return security.admin_layer2_ops_read(p_operation,p_args); end if;
 if p_operation in ('layer2_acquisition_providers','layer2_provider_attempts') then return security.admin_layer2_provider_read(p_operation,p_args); end if;
 if p_operation='attributes' then return security.admin_pim_governance_read(p_args); end if;
 if p_operation in ('pipeline_overview','pipeline_jobs_page','pipeline_job_detail','pipeline_sources_page','pipeline_filters') then v_result:=security.admin_pipeline_ops_read(p_operation,p_args);return security.admin_pipeline_ops_sanitise_result(p_operation,v_result);end if;
 if p_operation in ('data_quality_overview','data_quality_exceptions','data_quality_quarantine') then return security.admin_data_quality_read(p_operation,p_args); end if;
 if p_operation in ('platform_readiness','platform_capacity','platform_environment_gates','platform_uat_catalogue','platform_workloads','platform_retention','platform_active_blocks') then return security.admin_platform_maturity_read(p_operation,p_args); end if;
 if p_operation='publication_overview' then return security.admin_publication_overview(); end if;
 if p_operation='provider_insights' then v_id:=nullif(p_args->>'id','')::uuid;return jsonb_build_object('contextual_insights',security.admin_contextual_insights_v2('provider',v_id));end if;
 if p_operation='provider_detail' then v_id:=nullif(p_args->>'id','')::uuid;return security.admin_provider_detail(v_id)-'courses'-'courses_page'-'evidence'-'evidence_page'-'sources'-'history';end if;
 if p_operation='campus_detail' then v_id:=nullif(p_args->>'id','')::uuid;return security.admin_campus_detail(v_id);end if;
 if p_operation='course_insights' then v_id:=nullif(p_args->>'id','')::uuid;return jsonb_build_object('contextual_insights',security.admin_contextual_insights_v2('course',v_id));end if;
 v_result:=security.admin_read_impl(p_operation,p_args);
 if p_operation='course_detail' then v_id:=nullif(p_args->>'id','')::uuid;return v_result||jsonb_build_object('fee_summary',security.admin_course_fee_summary(v_id))||jsonb_build_object('entry_summary',security.admin_course_entry_summary(v_id));end if;
 if p_operation='scholarship_detail' then v_id:=nullif(p_args->>'id','')::uuid;return v_result||jsonb_build_object('semantic_summary',security.admin_scholarship_semantic_summary(v_id));end if;
 return v_result;
end $$;


