CREATE OR REPLACE FUNCTION "public"."admin_retention"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_cat text := btrim(coalesce(p_args->>'category', '')); v_reason text := btrim(coalesce(p_args->>'reason', ''));
        v_c jsonb; v_id uuid; v_e jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'read' then
    return jsonb_build_object(
      'database_bytes', pg_database_size(current_database()),
      'categories', (select jsonb_agg(c || jsonb_build_object(
          'estimate', (select to_jsonb(e) - 'category' from pipeline.retention_estimates e where e.category = c->>'key'),
          'active', (select to_jsonb(r) from pipeline.retention_runs r where r.category = c->>'key' and r.status in ('queued', 'running') limit 1),
          'last', (select to_jsonb(r) from pipeline.retention_runs r where r.category = c->>'key' and r.status not in ('queued', 'running') order by r.created_at desc limit 1)))
        from jsonb_array_elements(security.retention_catalogue_v1()) c),
      'runs', coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at desc) from (select * from pipeline.retention_runs order by created_at desc limit 15) r), '[]'::jsonb));
  end if;
  select c into v_c from jsonb_array_elements(security.retention_catalogue_v1()) c where c->>'key' = v_cat;
  if v_c is null then raise exception 'unknown category'; end if;
  if p_action = 'preview' then
    select to_jsonb(e) into v_e from pipeline.retention_estimates e where e.category = v_cat;
    return jsonb_build_object('category', v_c, 'estimate', v_e, 'note', 'Counts are measured in the background (hourly) and at the start of each purge; nothing is changed by a preview.');
  end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'purge' then
    if not (v_c->>'purge')::boolean and v_cat <> 'evidence_audit' then raise exception 'this category cannot be purged'; end if;
    if v_cat <> 'evidence_audit' and coalesce(p_args->>'confirm', '') <> v_cat then raise exception 'type the category name (%) to confirm', v_cat; end if;
    if exists (select 1 from pipeline.retention_runs r where r.category = v_cat and r.status in ('queued', 'running')) then raise exception 'a run for this category is already in progress'; end if;
    insert into pipeline.retention_runs(category, requested_by, reason, estimate, note)
    values (v_cat, auth.uid(), v_reason, (select to_jsonb(e) from pipeline.retention_estimates e where e.category = v_cat),
            case when v_cat = 'evidence_audit' then 'Audit queued: counts references in the background; nothing is deleted.' else 'Queued: starts within 2 minutes and runs in small batches.' end)
    returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('retention', case when v_cat = 'evidence_audit' then 'retention_audit' else 'retention_purge' end, v_cat, jsonb_build_object('run_id', v_id, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'run_id', v_id);
  elsif p_action = 'stop' then
    update pipeline.retention_runs set status = 'stopped', note = 'Stopped by a Platform Admin: ' || v_reason, finished_at = now(), updated_at = now()
     where category = v_cat and status in ('queued', 'running') returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('retention', 'retention_stop', v_cat, jsonb_build_object('run_id', v_id, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', v_id is not null);
  end if;
  raise exception 'unknown action';
end $$;


ALTER FUNCTION "public"."admin_retention"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scholarship_countries"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 5 then raise exception 'insufficient role' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x)) from security.scholarship_country_readiness_v1() x), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."admin_scholarship_countries"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scholarship_country"("p_country_code" "text", "p_on" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_refill jsonb; v_cc text := upper(btrim(coalesce(p_country_code, '')));
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_reason, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  select * into r from security.scholarship_country_readiness_v1() x where x.country_code = v_cc;
  if r.country_code is null then raise exception 'country % has no onboarding entry, courses or switch', v_cc; end if;
  if p_on and not r.ready then raise exception 'country % is not ready: %', v_cc, array_to_string(r.missing, '; '); end if;
  update ref.countries set scholarship_ingestion_enabled = p_on where iso_alpha2 = v_cc;
  update scholarship.country_onboarding set status = case when p_on then 'enabled' else 'watch' end, decided_by = auth.uid(), decided_at = now(),
         reason = left(p_reason, 500), updated_at = now() where country_code = v_cc;
  if p_on then v_refill := security.scholarship_discovery_refill_v1(30 + coalesce(r.universities, 0)::int); end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('scholarships', case when p_on then 'scholarship_country_on' else 'scholarship_country_off' end, v_cc,
          jsonb_build_object('reason', left(p_reason, 500), 'readiness', to_jsonb(r), 'discovery', v_refill), auth.uid());
  perform security.scholarship_country_watch_v1();
  return jsonb_build_object('ok', true, 'country', v_cc, 'switched_on', p_on, 'discovery', v_refill);
end $$;


ALTER FUNCTION "public"."admin_scholarship_country"("p_country_code" "text", "p_on" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scholarship_edit"("p_scholarship_id" "uuid", "p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_s scholarship.scholarships%rowtype; v_field text := p_args->>'field';
        v_val jsonb := p_args->'value'; v_txt text; v_before jsonb; v_after jsonb; v_locks text[];
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  select * into v_s from scholarship.scholarships where id = p_scholarship_id;
  if v_s.id is null then raise exception 'scholarship not found'; end if;
  perform set_config('cf.manual_edit', 'on', true);
  if p_action = 'set_core' then
    if v_field is null or v_field not in ('name','description','award_value_text','award_amount','award_percentage','application_open_date','application_close_date','source_url') then
      raise exception 'this field cannot be edited here'; end if;
    if jsonb_typeof(v_val) = 'string' then v_val := to_jsonb(nullif(btrim(v_val #>> '{}'), '')); end if;
    v_txt := case when v_val is null or v_val = 'null'::jsonb then null else v_val #>> '{}' end;
    if v_field = 'name' and v_txt is null then raise exception 'a scholarship needs a name'; end if;
    if v_field = 'award_amount' and v_txt is not null and (v_txt !~ '^[0-9]+(\.[0-9]+)?$' or v_txt::numeric <= 0) then raise exception 'enter the award as a number, for example 5000'; end if;
    if v_field = 'award_percentage' and v_txt is not null and (v_txt !~ '^[0-9]+(\.[0-9]+)?$' or v_txt::numeric <= 0 or v_txt::numeric > 100) then raise exception 'enter a percentage between 1 and 100'; end if;
    if v_field in ('application_open_date','application_close_date') and v_txt is not null and v_txt !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'enter the date as dd/mm/yyyy'; end if;
    if v_field = 'source_url' and v_txt is not null and v_txt !~* '^https?://[^[:space:]]+\.[^[:space:]]+$' then raise exception 'enter the full address, starting with https://'; end if;
    v_before := to_jsonb(v_s)->v_field;
    if v_field = 'award_amount' then
      update scholarship.scholarships set award_amount = v_txt::numeric,
             award_value_type = case when v_txt is not null then 'fixed_amount' when award_percentage is not null then 'percentage' else award_value_type end,
             award_percentage = case when v_txt is not null then null else award_percentage end,
             award_currency_code = case when v_txt is not null then coalesce(award_currency_code, scholarship.provider_currency(provider_id)) else award_currency_code end, updated_at = now()
       where id = p_scholarship_id;
      v_locks := array['award_amount','award_percentage','award_value_type','award_currency_code'];
    elsif v_field = 'award_percentage' then
      update scholarship.scholarships set award_percentage = v_txt::numeric,
             award_value_type = case when v_txt is not null then 'percentage' when award_amount is not null then 'fixed_amount' else award_value_type end,
             award_amount = case when v_txt is not null then null else award_amount end, updated_at = now()
       where id = p_scholarship_id;
      v_locks := array['award_amount','award_percentage','award_value_type'];
    else
      update scholarship.scholarships s set name = r.name, description = r.description, award_value_text = r.award_value_text,
             application_open_date = r.application_open_date, application_close_date = r.application_close_date, source_url = r.source_url, updated_at = now()
        from (select (jsonb_populate_record(x0, jsonb_build_object(v_field, v_val))).* from scholarship.scholarships x0 where x0.id = p_scholarship_id) r
       where s.id = p_scholarship_id;
      v_locks := array[v_field];
    end if;
    perform security.manual_lock_set('scholarship', p_scholarship_id, f, 'value') from unnest(v_locks) f;
    v_after := v_val;
  elsif p_action = 'set_audience' then
    v_field := 'audience';
    v_txt := btrim(coalesce(p_args->>'value', ''));
    if v_txt not in ('international', 'domestic', 'international_and_domestic', 'not_stated') then raise exception 'choose who the scholarship is for'; end if;
    v_before := to_jsonb(v_s.audience);
    update scholarship.scholarships set audience = v_txt, updated_at = now() where id = p_scholarship_id;
    perform security.manual_lock_set('scholarship', p_scholarship_id, 'audience', 'value');
    v_after := to_jsonb(v_txt);
  elsif p_action = 'set_nationalities' then
    v_field := 'nationalities';
    if jsonb_typeof(p_args->'value') is distinct from 'array' then raise exception 'give a list of nationalities'; end if;
    if exists (select 1 from jsonb_array_elements_text(p_args->'value') c where not exists (select 1 from ref.nationality_terms t where t.code = c)) then raise exception 'unknown nationality'; end if;
    v_before := to_jsonb(v_s.nationalities);
    update scholarship.scholarships set nationalities = coalesce((select array_agg(distinct c order by c) from jsonb_array_elements_text(p_args->'value') c), '{}'), updated_at = now() where id = p_scholarship_id;
    perform security.manual_lock_set('scholarship', p_scholarship_id, 'nationalities', 'value');
    v_after := p_args->'value';
  elsif p_action = 'release' then
    select to_jsonb(l) into v_before from pipeline.manual_locks l where entity = 'scholarship' and entity_id = p_scholarship_id and field = v_field;
    if v_before is null then raise exception 'nothing to release'; end if;
    delete from pipeline.manual_locks where entity = 'scholarship' and entity_id = p_scholarship_id
       and (field = v_field or (v_field in ('award_amount','award_percentage') and field in ('award_amount','award_percentage','award_value_type','award_currency_code')));
  else
    raise exception 'unknown action %', p_action;
  end if;
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('scholarship', p_scholarship_id, v_field, p_action, v_before, v_after, nullif(btrim(coalesce(p_args->>'reason','')),''), auth.uid());
  return (select jsonb_build_object('id', s.id, 'name', s.name, 'award_value_text', s.award_value_text, 'award_amount', s.award_amount,
            'award_percentage', s.award_percentage, 'application_open_date', s.application_open_date, 'application_close_date', s.application_close_date,
            'source_url', s.source_url, 'audience', s.audience, 'nationalities', s.nationalities, 'value_label', scholarship.value_label(s.id), 'locks', (select coalesce(jsonb_object_agg(k.field, k.mode), '{}'::jsonb) from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id))
            from scholarship.scholarships s where s.id = p_scholarship_id);
end $_$;


ALTER FUNCTION "public"."admin_scholarship_edit"("p_scholarship_id" "uuid", "p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scholarship_layer_read"("p_layer" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  v := jsonb_build_object('layer', p_layer, 'can_manage', v_rank >= 6,
    'settings', (select coalesce(jsonb_agg(jsonb_build_object('key', s.key, 'label', s.label, 'help', s.help, 'value', s.value, 'min', s.min_value, 'max', s.max_value, 'unit', s.unit, 'updated_at', s.updated_at, 'reason', s.reason) order by s.key), '[]'::jsonb)
                   from pipeline.scholarship_layer_settings s where s.layer = p_layer),
    'jobs', (select coalesce(jsonb_agg(jsonb_build_object('jobname', j.jobname, 'label', j.label, 'what', j.what, 'settings', j.setting_keys, 'schedule', c.schedule, 'active', c.active,
                     'runs_7d', (select count(*) from cron.job_run_details d where d.jobid = c.jobid and d.start_time > now() - interval '7 days'),
                     'failed_7d', (select count(*) from cron.job_run_details d where d.jobid = c.jobid and d.start_time > now() - interval '7 days' and d.status <> 'succeeded'),
                     'last_run', (select max(d.start_time) from cron.job_run_details d where d.jobid = c.jobid),
                     'last_failure', (select left(d.return_message, 200) from cron.job_run_details d where d.jobid = c.jobid and d.status <> 'succeeded' order by d.start_time desc limit 1)) order by j.sort), '[]'::jsonb)
               from pipeline.scholarship_jobs j left join cron.job c on c.jobname = j.jobname where j.layer = p_layer));
  if p_layer = 1 then
    v := v || jsonb_build_object(
      'countries', (select coalesce(jsonb_agg(jsonb_build_object('code', k.iso_alpha2, 'name', k.name, 'enabled', k.scholarship_ingestion_enabled, 'currency', k.default_currency_code,
                       'providers', (select count(*) from catalogue.providers p where p.country_id = k.id),
                       'universities_queued', (select count(*) from pipeline.scholarship_discovery_providers d join catalogue.providers p on p.id = d.provider_id where p.country_id = k.id),
                       'scholarships', (select count(*) from scholarship.scholarships s join catalogue.providers p on p.id = s.provider_id where p.country_id = k.id and s.lifecycle_status = 'active'),
                       'published', (select count(*) from scholarship.scholarships s join catalogue.providers p on p.id = s.provider_id where p.country_id = k.id and s.lifecycle_status = 'active' and s.publication_status = 'published'),
                       'detail_sources', (select count(*) from pipeline.sources x where x.country_id = k.id and x.source_type = 'scholarship_detail')) order by k.iso_alpha2), '[]'::jsonb)
                     from ref.countries k where k.iso_alpha2 in ('AU', 'NZ', 'CA', 'GB', 'US')),
      'sources', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'country', coalesce(k.iso_alpha2, 'ALL'), 'type', x.source_type, 'role', coalesce(x.metadata->>'scholarship_role', 'reference'),
                     'label', x.label, 'url', x.url, 'status', x.status, 'use', x.metadata->>'use', 'ingestion', x.metadata->>'ingestion', 'reader', x.metadata->>'reader',
                     'qualification', (select q.qualification_status from pipeline.scholarship_source_qualifications q where q.source_key = x.metadata->>'scholarship_source_key' limit 1),
                     'records', (select count(*) from scholarship.scholarships s where s.source_id = x.id and s.lifecycle_status = 'active'),
                     'feed', (select jsonb_build_object('feed', e.feed, 'enabled', e.enabled, 'cadence_hours', e.cadence_hours, 'last_dispatched_at', e.last_dispatched_at, 'next_due_at', e.next_due_at, 'last_error', e.last_error)
                                from pipeline.scholarship_etl_schedules e where e.source_key = x.metadata->>'scholarship_source_key' limit 1))
                     order by coalesce(k.iso_alpha2, 'ZZ'), case coalesce(x.metadata->>'scholarship_role', 'reference') when 'ingest' then 1 when 'provider_pages' then 2 when 'validation' then 3 else 4 end, x.label), '[]'::jsonb)
                   from pipeline.sources x left join ref.countries k on k.id = x.country_id
                  where x.source_type in ('government_scholarship_program', 'scholarship_catalogue', 'scholarship_reference')));
  elsif p_layer = 2 then
    v := v || jsonb_build_object('countries', (
      select coalesce(jsonb_agg(jsonb_build_object('code', k.iso_alpha2,
        'discovery', (select coalesce(jsonb_object_agg(z.status, z.n), '{}'::jsonb) from (select d.status, count(*) n from pipeline.scholarship_discovery_providers d join catalogue.providers p on p.id = d.provider_id where p.country_id = k.id group by 1) z),
        'pages_found', (select count(*) from pipeline.scholarship_page_candidates c join catalogue.providers p on p.id = c.provider_id where p.country_id = k.id),
        'page_reads', (select coalesce(jsonb_object_agg(z.st, z.n), '{}'::jsonb) from (select coalesce(c.read_status, 'waiting') st, count(*) n from pipeline.scholarship_page_candidates c join catalogue.providers p on p.id = c.provider_id where p.country_id = k.id group by 1) z),
        'outcomes', (select coalesce(jsonb_object_agg(z.st, z.n), '{}'::jsonb) from (select coalesce(c.admit_status, case when c.matched_scholarship_id is not null then 'matched_existing' when c.read_status is null then 'waiting' else 'not_decided' end) st, count(*) n from pipeline.scholarship_page_candidates c join catalogue.providers p on p.id = c.provider_id where p.country_id = k.id group by 1) z),
        'refusals', (select coalesce(jsonb_agg(jsonb_build_object('reason', z.r, 'pages', z.n) order by z.n desc), '[]'::jsonb) from (select r, count(*) n from pipeline.scholarship_page_candidates c join catalogue.providers p on p.id = c.provider_id cross join unnest(c.admit_reasons) r where p.country_id = k.id and c.admit_status = 'rejected' group by 1 order by 2 desc limit 6) z),
        'rereads', (select coalesce(jsonb_object_agg(z.st, z.n), '{}'::jsonb) from (select coalesce(sp.read_status, 'waiting') st, count(*) n from pipeline.scholarship_pages sp join scholarship.scholarships s on s.id = sp.scholarship_id join catalogue.providers p on p.id = s.provider_id where p.country_id = k.id group by 1) z)
      ) order by case k.iso_alpha2 when 'AU' then 1 when 'NZ' then 2 when 'CA' then 3 else 4 end), '[]'::jsonb)
      from ref.countries k where k.scholarship_ingestion_enabled and exists (select 1 from catalogue.providers p where p.country_id = k.id)),
      'firecrawl', jsonb_build_object(
        'used', (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.purpose in ('sch_map', 'sch_search', 'sch_scrape')),
        'cap', (select s.value from pipeline.scholarship_layer_settings s where s.key = 'firecrawl_cap'),
        'reserve', (select s.value from pipeline.scholarship_layer_settings s where s.key = 'firecrawl_reserve'),
        'by_purpose', (select coalesce(jsonb_object_agg(z.purpose, jsonb_build_object('all', z.n, 'last_7_days', z.n7)), '{}'::jsonb)
                         from (select u.purpose, sum(u.units) n, coalesce(sum(u.units) filter (where u.at > now() - interval '7 days'), 0) n7 from pipeline.coverage_vendor_usage u where u.purpose in ('sch_map', 'sch_search', 'sch_scrape') group by 1) z)),
      'worker', (select coalesce(jsonb_agg(jsonb_build_object('mode', z.mode, 'sent', z.sent, 'answered', z.answered, 'ok', z.ok, 'failed', z.failed, 'last_failure', z.lf)), '[]'::jsonb) from (
        select l.mode, count(*) sent, count(r.id) answered, count(*) filter (where r.status_code between 200 and 299) ok,
               count(*) filter (where r.status_code >= 300 or r.timed_out or r.error_msg is not null) failed,
               (select left(coalesce(r2.error_msg, r2.content::text), 200) from pipeline.edge_request_log l2 join net._http_response r2 on r2.id = l2.request_id where l2.mode = l.mode and (r2.status_code >= 300 or r2.timed_out or r2.error_msg is not null) order by l2.created_at desc limit 1) lf
          from pipeline.edge_request_log l left join net._http_response r on r.id = l.request_id
         where l.mode like 'scholarship%' and l.created_at > now() - interval '6 hours' group by l.mode) z));
  elsif p_layer = 3 then
    v := v || jsonb_build_object(
      'ai', (select coalesce(jsonb_agg(jsonb_build_object('country', a.country_code, 'enabled', a.enabled, 'state', a.metadata->>'state', 'profile', (select p.code from pipeline.layer3_model_profiles p where p.id = a.default_profile_id),
                 'task', a.default_task_class, 'budget_usd', a.daily_budget_usd, 'max_records', a.max_records_per_run, 'on_change', a.schedule_on_change,
                 'runs', (select count(*) from pipeline.scholarship_ai_runs r where r.country_code = a.country_code)) order by a.country_code), '[]'::jsonb) from pipeline.scholarship_ai_settings a),
      'profiles', (select coalesce(jsonb_agg(jsonb_build_object('code', p.code, 'model', p.model_identifier, 'enabled', p.enabled, 'paused', p.paused, 'benchmark_pass', coalesce((p.quality_benchmark->>'pass')::boolean, false)) order by p.code), '[]'::jsonb)
                     from pipeline.layer3_model_profiles p where p.code like '%scholarship%' and p.retired_at is null));
  end if;
  return v;
end $$;


ALTER FUNCTION "public"."admin_scholarship_layer_read"("p_layer" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scholarship_layer_write"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_set pipeline.scholarship_layer_settings%rowtype;
        v_num numeric; v_job bigint; v_cc text; v_role text; v_url text; v_id uuid; v_before jsonb; v_after jsonb; v_target text;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'setting' then
    select * into v_set from pipeline.scholarship_layer_settings where key = p_args->>'key';
    if v_set.key is null then raise exception 'unknown setting'; end if;
    if coalesce(p_args->>'value', '') !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'enter a number'; end if;
    v_num := (p_args->>'value')::numeric;
    if v_num < v_set.min_value or v_num > v_set.max_value then raise exception 'enter a value from % to %', v_set.min_value, v_set.max_value; end if;
    v_before := to_jsonb(v_set.value); v_after := to_jsonb(v_num); v_target := v_set.label;
    update pipeline.scholarship_layer_settings set value = v_num, updated_at = now(), updated_by = auth.uid(), reason = v_reason where key = v_set.key;
  elsif p_action = 'job' then
    if not exists (select 1 from pipeline.scholarship_jobs j where j.jobname = p_args->>'jobname') then raise exception 'unknown job'; end if;
    select jobid, to_jsonb(active) into v_job, v_before from cron.job where jobname = p_args->>'jobname';
    if v_job is null then raise exception 'the job is not scheduled'; end if;
    perform cron.alter_job(v_job, active := (p_args->>'active')::boolean);
    v_after := to_jsonb((p_args->>'active')::boolean); v_target := p_args->>'jobname';
  elsif p_action = 'country' then
    v_cc := upper(coalesce(p_args->>'code', ''));
    select to_jsonb(scholarship_ingestion_enabled) into v_before from ref.countries where iso_alpha2 = v_cc;
    if v_before is null then raise exception 'unknown country'; end if;
    update ref.countries set scholarship_ingestion_enabled = (p_args->>'enabled')::boolean, updated_at = now() where iso_alpha2 = v_cc;
    v_after := to_jsonb((p_args->>'enabled')::boolean); v_target := v_cc;
  elsif p_action = 'feed' then
    select to_jsonb(e) into v_before from pipeline.scholarship_etl_schedules e where e.feed = p_args->>'feed';
    if v_before is null then raise exception 'unknown feed'; end if;
    if p_args ? 'cadence_hours' and ((p_args->>'cadence_hours') !~ '^[0-9]+$' or (p_args->>'cadence_hours')::int not between 24 and 2160) then raise exception 'enter a cadence from 24 to 2160 hours'; end if;
    update pipeline.scholarship_etl_schedules set enabled = coalesce((p_args->>'enabled')::boolean, enabled), cadence_hours = coalesce((p_args->>'cadence_hours')::int, cadence_hours), updated_at = now() where feed = p_args->>'feed';
    select to_jsonb(e) into v_after from pipeline.scholarship_etl_schedules e where e.feed = p_args->>'feed'; v_target := p_args->>'feed';
  elsif p_action = 'source_add' then
    v_role := p_args->>'role'; v_url := btrim(coalesce(p_args->>'url', '')); v_cc := upper(coalesce(p_args->>'country', 'ALL'));
    if v_role not in ('ingest', 'provider_pages', 'reference', 'validation') then raise exception 'choose how the source is used'; end if;
    if v_url !~* '^https?://[^[:space:]]+\.[^[:space:]]+$' then raise exception 'enter the full address, starting with https://'; end if;
    if coalesce(btrim(p_args->>'label'), '') = '' then raise exception 'give the source a name'; end if;
    if v_cc <> 'ALL' and not exists (select 1 from ref.countries where iso_alpha2 = v_cc) then raise exception 'unknown country'; end if;
    if exists (select 1 from pipeline.sources where url = v_url) then raise exception 'this address is already registered'; end if;
    insert into pipeline.sources(source_type, country_id, url, label, trust_rank, status, metadata)
    values (case when v_role in ('reference', 'validation') then 'scholarship_reference' else 'scholarship_catalogue' end,
            (select id from ref.countries where iso_alpha2 = v_cc), v_url, btrim(p_args->>'label'), case when v_role in ('reference', 'validation') then 30 else 80 end,
            case when v_role in ('reference', 'validation') then 'active' else 'registered' end,
            jsonb_build_object('domain', 'scholarship', 'scholarship_role', v_role, 'reader', 'none', 'use', nullif(btrim(coalesce(p_args->>'use', '')), ''), 'added_by', auth.uid(), 'decision', 'Decision 251'))
    returning id into v_id;
    v_after := jsonb_build_object('id', v_id, 'url', v_url, 'role', v_role, 'country', v_cc); v_target := btrim(p_args->>'label');
  elsif p_action in ('source_role', 'source_status') then
    v_id := (p_args->>'id')::uuid;
    select jsonb_build_object('role', metadata->>'scholarship_role', 'status', status), label into v_before, v_target from pipeline.sources where id = v_id and source_type in ('government_scholarship_program', 'scholarship_catalogue', 'scholarship_reference');
    if v_before is null then raise exception 'unknown scholarship source'; end if;
    if p_action = 'source_role' then
      if p_args->>'role' not in ('ingest', 'provider_pages', 'reference', 'validation') then raise exception 'choose how the source is used'; end if;
      update pipeline.sources set metadata = metadata || jsonb_build_object('scholarship_role', p_args->>'role'), updated_at = now() where id = v_id;
    else
      if p_args->>'status' not in ('active', 'paused') then raise exception 'choose on or paused'; end if;
      if v_before->>'status' = 'registered' and p_args->>'status' = 'active' and not exists (select 1 from pipeline.scholarship_etl_schedules e join pipeline.sources x on x.metadata->>'scholarship_source_key' = e.source_key where x.id = v_id) and (select metadata->>'scholarship_role' from pipeline.sources where id = v_id) in ('ingest', 'provider_pages') then
        raise exception 'no reader exists for this source yet; it stays registered';
      end if;
      update pipeline.sources set status = p_args->>'status', updated_at = now() where id = v_id;
      update pipeline.scholarship_etl_schedules e set enabled = (p_args->>'status' = 'active'), updated_at = now() from pipeline.sources x where x.id = v_id and e.source_key = x.metadata->>'scholarship_source_key';
    end if;
    select jsonb_build_object('role', metadata->>'scholarship_role', 'status', status) into v_after from pipeline.sources where id = v_id;
  else
    raise exception 'unknown action';
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('scholarships', 'layer_' || p_action, v_target, jsonb_build_object('before', v_before, 'after', v_after, 'reason', v_reason, 'decision', 'Decision 251'), auth.uid());
  return jsonb_build_object('ok', true, 'action', p_action, 'target', v_target, 'after', v_after);
end $_$;


ALTER FUNCTION "public"."admin_scholarship_layer_write"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scholarship_links_decide"("p_scholarship_id" "uuid", "p_decision" "text", "p_filter" "jsonb" DEFAULT '{}'::"jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_res jsonb; v_before jsonb; v_f jsonb := coalesce(p_filter, '{}'::jsonb);
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
  if p_decision not in ('all','filter','none') then raise exception 'choose all courses, only matching courses, or no courses'; end if;
  if p_decision = 'filter' and jsonb_array_length(coalesce(v_f->'levels', '[]'::jsonb)) = 0 and jsonb_array_length(coalesce(v_f->'fields', '[]'::jsonb)) = 0
     and nullif(btrim(coalesce(v_f->>'title', '')), '') is null and jsonb_array_length(coalesce(v_f->'courses', '[]'::jsonb)) = 0 then
    raise exception 'choose at least one study level, field, title word or course';
  end if;
  if not exists (select 1 from scholarship.course_mapping_candidates where scholarship_id = p_scholarship_id) then raise exception 'this scholarship has no proposed course links'; end if;
  select to_jsonb(d) into v_before from pipeline.scholarship_scope_decisions d where scholarship_id = p_scholarship_id;
  insert into pipeline.scholarship_scope_decisions(scholarship_id, decision, filter, reason, decided_by, decided_at)
  values (p_scholarship_id, p_decision, case when p_decision = 'filter' then v_f else '{}'::jsonb end, nullif(btrim(coalesce(p_reason, '')), ''), auth.uid(), now())
  on conflict (scholarship_id) do update set decision = excluded.decision, filter = excluded.filter, reason = excluded.reason,
         decided_by = excluded.decided_by, decided_at = now();
  v_res := security.scholarship_scope_apply_v1(p_scholarship_id, auth.uid());
  insert into pipeline.layer4_mass_operations(target_kind, action, actor_id, group_key, reason, before_count, affected_count, result, change_control_ref)
  values ('scholarship_course_scope', 'scope_decision_' || p_decision, auth.uid(), jsonb_build_object('scholarship_id', p_scholarship_id, 'filter', v_f, 'previous', v_before),
          coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Scholarship course links decided on the Course links screen'),
          coalesce((v_res->>'accepted')::int, 0) + coalesce((v_res->>'rejected')::int, 0), coalesce((v_res->>'accepted')::int, 0), v_res, 'CF-CHG-20260915-247');
  return public.admin_scholarship_links_detail(p_scholarship_id) || jsonb_build_object('result', v_res);
end $$;


ALTER FUNCTION "public"."admin_scholarship_links_decide"("p_scholarship_id" "uuid", "p_decision" "text", "p_filter" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scholarship_links_detail"("p_scholarship_id" "uuid", "p_decision" "text" DEFAULT NULL::"text", "p_filter" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_s scholarship.scholarships%rowtype; v_dec text; v_f jsonb;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  select * into v_s from scholarship.scholarships where id = p_scholarship_id;
  if v_s.id is null then raise exception 'scholarship not found'; end if;
  select coalesce(p_decision, d.decision, sg->>'decision'), coalesce(p_filter, d.filter, sg->'filter') into v_dec, v_f
    from (select security.scholarship_scope_suggest(p_scholarship_id) sg) z left join pipeline.scholarship_scope_decisions d on d.scholarship_id = p_scholarship_id;
  return (with cc as (select c.id candidate_id, c.status, co.id course_id, coalesce(co.display_title, co.canonical_title) title, co.course_code,
                             co.study_level_id, security.broad_field_id(co.primary_field_id) field_id,
                             security.scholarship_scope_match(co.id, v_dec, v_f) ok
                        from scholarship.course_mapping_candidates c join catalogue.courses co on co.id = c.course_id
                       where c.scholarship_id = p_scholarship_id)
    select jsonb_build_object(
      'scholarship', jsonb_build_object('id', v_s.id, 'name', v_s.name, 'award', v_s.award_value_text, 'award_type', v_s.award_value_type,
                     'award_percentage', v_s.award_percentage, 'award_amount', v_s.award_amount, 'currency', v_s.award_currency_code,
                     'source_url', v_s.source_url, 'audience', v_s.audience, 'academic_year', v_s.academic_year,
                     'provider', (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = v_s.provider_id)),
      'proposed', (select count(*) from cc), 'waiting', (select count(*) from cc where status = 'needs_review'),
      'levels', (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'count', n) order by l.sort_order), '[]'::jsonb)
                   from (select study_level_id, count(*) n from cc group by 1) g join ref.study_levels l on l.id = g.study_level_id),
      'fields', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'name', f.name, 'count', n) order by n desc), '[]'::jsonb)
                   from (select field_id, count(*) n from cc group by 1) g join ref.fields_of_study f on f.id = g.field_id),
      'suggestion', security.scholarship_scope_suggest(p_scholarship_id),
      'decision', (select jsonb_build_object('decision', d.decision, 'filter', d.filter, 'reason', d.reason, 'at', d.decided_at, 'by', u.email,
                          'accepted', d.accepted, 'rejected', d.rejected)
                     from pipeline.scholarship_scope_decisions d left join auth.users u on u.id = d.decided_by where d.scholarship_id = p_scholarship_id),
      'preview', jsonb_build_object('decision', v_dec, 'filter', v_f,
                   'matched', (select count(*) from cc where ok), 'not_matched', (select count(*) from cc where not ok),
                   'sample_matched', (select coalesce(jsonb_agg(jsonb_build_object('id', course_id, 'title', title, 'code', course_code)), '[]'::jsonb) from (select * from cc where ok order by title limit 12) a),
                   'sample_not_matched', (select coalesce(jsonb_agg(jsonb_build_object('id', course_id, 'title', title, 'code', course_code)), '[]'::jsonb) from (select * from cc where not ok order by title limit 8) b)),
      'can_decide', v_rank >= 4));
end $$;


ALTER FUNCTION "public"."admin_scholarship_links_detail"("p_scholarship_id" "uuid", "p_decision" "text", "p_filter" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scholarship_links_read"("p_view" "text" DEFAULT 'waiting'::"text", "p_q" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  return jsonb_build_object(
    'can_decide', v_rank >= 4,
    'summary', (select jsonb_build_object('waiting_links', count(*) filter (where c.status = 'needs_review'),
                   'waiting_scholarships', count(distinct c.scholarship_id) filter (where c.status = 'needs_review'),
                   'decided_scholarships', (select count(*) from pipeline.scholarship_scope_decisions),
                   'accepted_links', count(*) filter (where c.status = 'accepted'), 'rejected_links', count(*) filter (where c.status = 'rejected'))
                  from scholarship.course_mapping_candidates c),
    'items', (select coalesce(jsonb_agg(x order by (x->>'waiting')::int desc, x->>'name'), '[]'::jsonb) from (
       select jsonb_build_object('scholarship_id', s.id, 'name', s.name, 'provider', coalesce(p.display_name, p.canonical_name),
              'award_type', s.award_value_type, 'award', coalesce(s.award_value_text, case when s.award_percentage is not null then s.award_percentage || '%' end,
                        case when s.award_amount is not null then s.award_currency_code || ' ' || s.award_amount end),
              'source_url', s.source_url, 'waiting', count(*) filter (where c.status = 'needs_review'), 'proposed', count(*),
              'accepted', count(*) filter (where c.status = 'accepted'),
              'decision', (select jsonb_build_object('decision', d.decision, 'at', d.decided_at, 'by', u.email, 'accepted', d.accepted, 'rejected', d.rejected)
                             from pipeline.scholarship_scope_decisions d left join auth.users u on u.id = d.decided_by where d.scholarship_id = s.id),
              'suggestion', security.scholarship_scope_suggest(s.id)) x
         from scholarship.course_mapping_candidates c join scholarship.scholarships s on s.id = c.scholarship_id
         left join catalogue.providers p on p.id = s.provider_id
        where (p_q is null or s.name ilike '%' || p_q || '%' or coalesce(p.display_name, p.canonical_name) ilike '%' || p_q || '%')
        group by s.id, s.name, p.display_name, p.canonical_name
       having case coalesce(p_view, 'waiting') when 'waiting' then count(*) filter (where c.status = 'needs_review') > 0
                                                 when 'decided' then exists (select 1 from pipeline.scholarship_scope_decisions d where d.scholarship_id = s.id)
                                                 else true end
        limit 300) y));
end $$;


