CREATE OR REPLACE FUNCTION "public"."admin_scholarship_record_read"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 1 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  return (
    with pub as (select * from security.scholarship_publishability_v1() x where x.scholarship_id = p_id)
    select jsonb_build_object(
      'id', s.id, 'name', s.name, 'provider_id', s.provider_id, 'provider', coalesce(pr.display_name, pr.canonical_name),
      'can_edit', v_rank >= 3,
      'status', case when s.lifecycle_status <> 'active' then 'inactive' when s.publication_status = 'published' then 'published' when coalesce((select publishable from pub), false) then 'ready' else 'held' end,
      'held_reasons', coalesce((select missing from pub), '{}'::text[]),
      'publication_status', s.publication_status, 'lifecycle_status', s.lifecycle_status,
      'value_label', scholarship.value_label(s.id), 'page_words', s.award_value_text,
      'award_amount', s.award_amount, 'award_percentage', s.award_percentage, 'award_value_type', s.award_value_type, 'is_maximum', s.award_value_is_maximum,
      'tiers', (select coalesce(jsonb_agg(jsonb_build_object('label', t.label, 'percentage', t.percentage, 'amount', t.amount, 'currency', t.currency_code) order by t.display_order), '[]'::jsonb) from scholarship.award_tiers t where t.scholarship_id = s.id),
      'audience', s.audience,
      'audience_phrase', (select coalesce(a.phrase_both, nullif(concat_ws(' + ', a.phrase_international, a.phrase_domestic), '')) from scholarship.audience_readings a where a.scholarship_id = s.id),
      'nationalities', s.nationalities,
      'nationality_phrases', (select r.phrases from scholarship.nationality_readings r where r.scholarship_id = s.id),
      'nationality_terms', (select jsonb_agg(jsonb_build_object('code', t.code, 'name', split_part(t.names, '|', 1)) order by t.region, split_part(t.names, '|', 1)) from ref.nationality_terms t),
      'duration_basis', s.award_duration_basis,
      'application_required', s.application_required, 'application_open_date', s.application_open_date, 'application_close_date', s.application_close_date,
      'page', s.source_url,
      'page_read_at', (select sp.read_at from pipeline.scholarship_pages sp where sp.scholarship_id = s.id),
      'courses', (select count(*) from scholarship.course_mappings m where m.scholarship_id = s.id and m.mapping_state = 'mapped'),
      'course_list', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'title', x.title, 'level', x.level, 'code', x.course_code) order by x.so, x.title), '[]'::jsonb)
                        from (select co.id, coalesce(co.display_title, co.canonical_title) title, sl.name level, coalesce(sl.sort_order, 99) so, co.course_code
                                from scholarship.course_mappings m join catalogue.courses co on co.id = m.course_id left join ref.study_levels sl on sl.id = co.study_level_id
                               where m.scholarship_id = s.id and m.mapping_state = 'mapped' and co.lifecycle_status = 'active'
                               order by coalesce(sl.sort_order, 99), coalesce(co.display_title, co.canonical_title) limit 200) x),
      'course_levels', (select coalesce(jsonb_agg(jsonb_build_object('level', y.level, 'courses', y.n) order by y.so), '[]'::jsonb)
                          from (select coalesce(sl.name, 'Other') level, min(coalesce(sl.sort_order, 99)) so, count(*) n
                                  from scholarship.course_mappings m join catalogue.courses co on co.id = m.course_id left join ref.study_levels sl on sl.id = co.study_level_id
                                 where m.scholarship_id = s.id and m.mapping_state = 'mapped' and co.lifecycle_status = 'active' group by 1) y),
      'criteria', (select coalesce(jsonb_agg(to_jsonb(cr) order by cr.criterion_type), '[]'::jsonb) from scholarship.criteria cr where cr.scholarship_id = s.id and cr.status = 'active'),
      'locks', (select coalesce(jsonb_object_agg(k.field, k.mode), '{}'::jsonb) from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id),
      'history', (select coalesce(jsonb_agg(jsonb_build_object('at', h.at, 'field', h.field, 'action', h.action, 'reason', h.reason) order by h.at desc), '[]'::jsonb)
                    from (select * from pipeline.manual_edit_log l where l.entity = 'scholarship' and l.entity_id = s.id order by l.at desc limit 10) h))
    from scholarship.scholarships s left join catalogue.providers pr on pr.id = s.provider_id where s.id = p_id);
end $$;


ALTER FUNCTION "public"."admin_scholarship_record_read"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scholarship_register_institutions"("p_register" "text", "p_provider_ids" "uuid"[], "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r scholarship.registers; v_bad int; v_out jsonb;
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_reason, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  select * into r from scholarship.registers where code = p_register and role = 'record';
  if r.code is null then raise exception 'not a record register: %', p_register; end if;
  select count(*) into v_bad from unnest(coalesce(p_provider_ids,'{}')) x
   where not exists (select 1 from catalogue.providers p join ref.countries c on c.id = p.country_id where p.id = x and c.iso_alpha2 = r.country_code and p.lifecycle_status = 'active');
  if v_bad > 0 then raise exception '% provider(s) are not active providers in %', v_bad, r.country_code; end if;
  update scholarship.registers set provider_ids = (select array_agg(distinct x) from unnest(r.provider_ids || coalesce(p_provider_ids,'{}')) x), updated_at = now()
   where code = p_register;
  v_out := public.svc_scholarship_register_record_profile(p_register);
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('scholarships', 'register_institutions_set', p_register, jsonb_build_object('added', to_jsonb(p_provider_ids), 'reason', left(p_reason, 500), 'profile', v_out), auth.uid());
  return v_out;
end $$;


ALTER FUNCTION "public"."admin_scholarship_register_institutions"("p_register" "text", "p_provider_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scholarship_registers"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 5 then raise exception 'insufficient role' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'code', r.code, 'country', r.country_code, 'name', r.name, 'role', r.role, 'status', r.status, 'url', r.url,
      'listings', (select count(*) from scholarship.register_listings l where l.register_code = r.code and l.departed_at is null),
      'matched', (select count(*) from scholarship.register_listings l where l.register_code = r.code and l.departed_at is null and l.scholarship_id is not null),
      'handed_to_page_reader', (select count(*) from scholarship.register_listings l where l.register_code = r.code and l.departed_at is null and l.handoff_status = 'handed_to_page_reader'),
      'off_provider_site', (select count(*) from scholarship.register_listings l where l.register_code = r.code and l.departed_at is null and l.handoff_status = 'provider_page_off_provider_site'),
      'provider_unknown', (select count(*) from scholarship.register_listings l where l.register_code = r.code and l.departed_at is null and l.scholarship_id is null and l.provider_id is null and l.detail_read_at is not null),
      'departed', (select count(*) from scholarship.register_listings l where l.register_code = r.code and l.departed_at is not null),
      'records', (select count(*) from scholarship.scholarships s where s.source_id = r.source_id and s.lifecycle_status = 'active'),
      'last_seen_at', (select max(last_seen_at) from scholarship.register_listings l where l.register_code = r.code)
    ) order by r.country_code, r.code) from scholarship.registers r), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."admin_scholarship_registers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_pass_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  return jsonb_build_object('can_manage', v_rank >= 6,
    'runs', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'status', r.status, 'status_note', r.status_note, 'credits_used', r.credits_used, 'created_at', r.created_at, 'reason', r.reason,
               'courses', (select count(*) from pipeline.toolset_sample_items i where i.run_id = r.id), 'done', (select count(*) from pipeline.toolset_sample_items i where i.run_id = r.id and i.status = 'done')) order by r.created_at desc), '[]'::jsonb)
             from pipeline.toolset_sample_runs r where r.applies),
    'links', (select coalesce(jsonb_agg(jsonb_build_object('country', z.cc, 'refind', z.refind, 'state', z.state, 'n', z.n)), '[]'::jsonb)
              from (select k.iso_alpha2 cc, l.refind, l.state, count(*) n from pipeline.search_pass_links l join catalogue.providers p on p.id = l.provider_id join ref.countries k on k.id = p.country_id group by 1, 2, 3) z),
    'reading', (select coalesce(jsonb_agg(jsonb_build_object('read_status', z.rs, 'n', z.n)), '[]'::jsonb)
                from (select coalesce(p.read_status, 'waiting') rs, count(*) n from pipeline.search_pass_links l join pipeline.coverage_course_pages p on p.course_id = l.course_id and p.url = l.bound_url where l.state = 'found' group by 1) z),
    'repairs', (select coalesce(jsonb_agg(jsonb_build_object('reason', z.reason, 'n', z.n, 'last_at', z.last_at)), '[]'::jsonb)
                from (select reason, count(*) n, max(at) last_at from pipeline.page_link_repairs group by 1) z));
end $$;


ALTER FUNCTION "public"."admin_search_pass_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_pass_start"("p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_reason, '')); v_settings jsonb; v_countries text[];
        v_run uuid; v_cc text; v_n int; v_added int := 0; v_plan jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if not exists (select 1 from pipeline.layer2_acquisition_providers p where p.provider_key = 'serper' and p.vault_secret_id is not null) then
    raise exception 'save the Serper key on Platform settings › Environment & integrations first'; end if;
  v_plan := security.toolset_plan_status('serper');
  if (v_plan->>'at_reserve')::boolean then raise exception 'the Serper key''s plan is at its reserve. Replace the key or raise the plan limits first'; end if;
  if exists (select 1 from pipeline.toolset_sample_runs r where r.toolset_key = 'serper' and r.status in ('ready', 'running', 'paused_time_limit')) then
    raise exception 'a Serper run is still open. Finish or stop it first'; end if;
  select coalesce(jsonb_object_agg(s.key, s.value), '{}'::jsonb) into v_settings from pipeline.platform_toolset_settings s where s.toolset_key = 'serper';
  v_settings := v_settings || jsonb_build_object('sample_credits_per_run', v_settings->'pass_credits_per_run');
  select array_agg(x) into v_countries from jsonb_array_elements_text(v_settings->'sample_countries') x;
  insert into pipeline.toolset_sample_runs(toolset_key, purpose, countries, settings, reason, requested_by, applies)
    values ('serper', 'find_course_page', coalesce(v_countries, '{}'), v_settings, v_reason, auth.uid(), true) returning id into v_run;
  foreach v_cc in array coalesce(v_countries, '{}') loop
    v_n := (v_settings->>'pass_cases_per_country')::int;
    insert into pipeline.toolset_sample_items(run_id, country, subject_key, course_id, provider_id, input)
    select v_run, v_cc, b.subject_key, b.course_id, b.provider_id, b.input
    from (select distinct on (b0.subject_key) b0.* from security.toolset_pass_backlog(v_cc) b0 order by b0.subject_key) b
    where not exists (select 1 from pipeline.toolset_sample_items i join pipeline.toolset_sample_runs r on r.id = i.run_id
                      where i.subject_key = b.subject_key and r.applies and i.status = 'done')
    order by md5(b.subject_key || v_run::text) limit v_n;
    get diagnostics v_n = row_count; v_added := v_added + v_n;
  end loop;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'search_pass_start', 'serper', jsonb_build_object('run_id', v_run, 'courses', v_added, 'reason', v_reason), auth.uid());
  perform pipeline.svc_pilot_submit_nonce('toolset-runner', jsonb_build_object('action', 'run', 'run_id', v_run));
  return jsonb_build_object('ok', true, 'run_id', v_run, 'courses', v_added);
end $$;


ALTER FUNCTION "public"."admin_search_pass_start"("p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_semester_intakes_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
  return (with pl as materialized (select * from security.semester_intake_plan_v1(null)),
          bo as (select pl.provider_id, jsonb_object_agg(pl.outcome, pl.n) o from (select provider_id, outcome, count(*) n from pl group by 1, 2) pl group by 1),
          pe as (select pl.provider_id, array_agg(distinct x order by x) per from pl, unnest(pl.periods) x group by 1)
    select jsonb_build_object('can_set', security.current_role_rank() >= 6,
      'providers', coalesce(jsonb_agg(x order by (x->>'reviews')::int desc), '[]'::jsonb)) from (
      select jsonb_build_object('provider_id', pl.provider_id, 'provider', coalesce(pv.display_name, pv.canonical_name),
               'reviews', count(*), 'answerable', count(*) filter (where pl.outcome = 'answer'),
               'by_outcome', (select bo.o from bo where bo.provider_id = pl.provider_id),
               'periods', (select pe.per from pe where pe.provider_id = pl.provider_id),
               'months', security.calendar_period_months(pl.provider_id),
               'calendar_url', (select f.url from pipeline.provider_fact_sources f where f.provider_id = pl.provider_id and f.kind = 'intake_calendar' order by f.rank limit 1),
               'sample', min(pl.quotes)) x
        from pl join catalogue.providers pv on pv.id = pl.provider_id
       group by pl.provider_id, pv.display_name, pv.canonical_name) s);
end $$;


ALTER FUNCTION "public"."admin_semester_intakes_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_services_control"("p_kind" "text", "p_id" "uuid", "p_enabled" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_label text; v_steps int := 0;
begin
  if auth.uid() is null or security.current_role_rank() < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
  if p_kind = 'model' then
    select model_identifier into v_label from pipeline.layer3_model_profiles where id = p_id;
    if v_label is null then raise exception 'model not found'; end if;
    if p_enabled and exists (select 1 from pipeline.layer3_model_profiles where id = p_id and retired_at is not null) then
      raise exception 'this model was retired after failing its tests and cannot be switched on here';
    end if;
    if p_enabled and not exists (select 1 from pipeline.layer3_model_profiles m where m.id = p_id
        and (coalesce((m.quality_benchmark->>'pass')::boolean, false)
             or exists (select 1 from unnest(m.allowed_task_classes) t where coalesce((security.layer3_tier_evidence(t, m.id)->>'eligible')::boolean, false)))) then
      raise exception 'this model has not passed its tests for any task yet, so it cannot be switched on';
    end if;
    update pipeline.layer3_model_profiles set enabled = p_enabled, paused = not p_enabled, updated_at = now() where id = p_id;
    if not p_enabled then
      update pipeline.layer3_route_tiers set active = false, updated_at = now() where profile_id = p_id and active;
      get diagnostics v_steps = row_count;
    end if;
  elsif p_kind = 'service' then
    select display_name into v_label from pipeline.layer2_acquisition_providers where id = p_id;
    if v_label is null then raise exception 'service not found'; end if;
    update pipeline.layer2_acquisition_providers set enabled = p_enabled, updated_at = now() where id = p_id;
  else
    raise exception 'unknown kind %', p_kind;
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('services', case when p_enabled then 'switch_on' else 'switch_off' end, v_label,
          jsonb_build_object('kind', p_kind, 'id', p_id, 'steps_switched_off', v_steps, 'reason', nullif(btrim(coalesce(p_reason, '')), '')), auth.uid());
  return public.admin_services_read() || jsonb_build_object('steps_switched_off', v_steps);
end $$;


ALTER FUNCTION "public"."admin_services_control"("p_kind" "text", "p_id" "uuid", "p_enabled" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_services_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
  return jsonb_build_object(
    'can_control', v_rank >= 5,
    'models', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'code', p.code, 'model', p.model_identifier, 'provider', p.aggregator_provider,
                 'tasks', to_jsonb(p.allowed_task_classes), 'enabled', p.enabled and not p.paused, 'retired', p.retired_at is not null,
                 'retired_reason', p.retired_reason, 'qualified', coalesce((p.quality_benchmark->>'pass')::boolean, false) or exists (select 1 from unnest(p.allowed_task_classes) t where coalesce((security.layer3_tier_evidence(t, p.id)->>'eligible')::boolean, false)),
                 'steps', (select coalesce(jsonb_agg(jsonb_build_object('task', t.task_class, 'step', t.tier_no, 'active', t.active) order by t.task_class, t.tier_no), '[]'::jsonb)
                             from pipeline.layer3_route_tiers t where t.profile_id = p.id),
                 'calls_7d', (select count(*) from pipeline.layer3_interpretations i where i.profile_id = p.id and i.created_at >= now() - interval '7 days'),
                 'cost_7d_usd', (select round(coalesce(sum(i.estimated_cost_usd), 0), 4) from pipeline.layer3_interpretations i where i.profile_id = p.id and i.created_at >= now() - interval '7 days'))
               order by p.retired_at is not null, (p.enabled and not p.paused) desc, p.allowed_task_classes[1], p.model_identifier), '[]'::jsonb)
               from pipeline.layer3_model_profiles p),
    'services', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'key', a.provider_key, 'name', a.display_name, 'type', a.adapter_type,
                 'enabled', a.enabled, 'credential', a.vault_secret_id is not null,
                 'routes', (select count(*) from pipeline.layer2_profile_provider_routes r where r.acquisition_provider_id = a.id and r.enabled),
                 'last_test', jsonb_build_object('at', a.last_tested_at, 'status', a.last_test_status))
               order by a.enabled desc, a.priority, a.display_name), '[]'::jsonb)
               from pipeline.layer2_acquisition_providers a),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('at', e.created_at, 'action', e.action, 'target', e.target, 'by', u.email) order by e.created_at desc), '[]'::jsonb)
               from (select * from pipeline.admin_control_events where area = 'services' order by created_at desc limit 15) e left join auth.users u on u.id = e.actor));
end $$;


