CREATE OR REPLACE FUNCTION "public"."admin_toolset_sample_write"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', ''));
        v_toolset text := p_args->>'toolset'; v_purpose text := p_args->>'purpose'; v_settings jsonb; v_countries text[]; v_n int;
        v_run uuid; v_cc text; v_added int := 0; v_r pipeline.toolset_sample_runs%rowtype; v_plan jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'start' then
    if not ((v_toolset = 'serper' and v_purpose in ('find_course_page', 'find_provider_site')) or (v_toolset = 'scrapingbee' and v_purpose = 'render_page')) then
      raise exception 'this service does not run that kind of sample'; end if;
    if not exists (select 1 from pipeline.layer2_acquisition_providers p where p.provider_key = v_toolset and p.vault_secret_id is not null) then
      raise exception 'save the % key on Platform settings › Environment & integrations first', v_toolset; end if;
    v_plan := security.toolset_plan_status(v_toolset);
    if (v_plan->>'at_reserve')::boolean then
      raise exception 'the % key''s plan has % credits left, at or below its reserve of %. Replace the key or raise the plan limits first', v_toolset, v_plan->>'left', v_plan->>'reserve'; end if;
    if exists (select 1 from pipeline.toolset_sample_runs r where r.toolset_key = v_toolset and r.status in ('ready', 'running', 'paused_time_limit')) then
      raise exception 'a % sample run is still open. Finish or stop it first', v_toolset; end if;
    select coalesce(jsonb_object_agg(s.key, s.value), '{}'::jsonb) into v_settings from pipeline.platform_toolset_settings s where s.toolset_key = v_toolset;
    select array_agg(x) into v_countries from jsonb_array_elements_text(v_settings->'sample_countries') x;
    insert into pipeline.toolset_sample_runs(toolset_key, purpose, countries, settings, reason, requested_by)
      values (v_toolset, v_purpose, coalesce(v_countries, '{}'), v_settings, v_reason, auth.uid()) returning id into v_run;
    foreach v_cc in array coalesce(v_countries, '{}') loop
      v_n := (v_settings->>'sample_cases_per_country')::int;
      insert into pipeline.toolset_sample_items(run_id, country, subject_key, course_id, provider_id, input)
      select v_run, v_cc, b.subject_key, b.course_id, b.provider_id, b.input
      from security.toolset_backlog(v_purpose, v_cc) b
      where not exists (select 1 from pipeline.toolset_sample_items i join pipeline.toolset_sample_runs r on r.id = i.run_id
                        where i.subject_key = b.subject_key and r.purpose = v_purpose and i.status = 'done')
      order by md5(b.subject_key || v_run::text) limit v_n;
      get diagnostics v_n = row_count; v_added := v_added + v_n;
    end loop;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'sample_start', v_toolset || ':' || v_purpose, jsonb_build_object('run_id', v_run, 'cases', v_added, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'run_id', v_run, 'cases', v_added);
  elsif p_action = 'stop' then
    select * into v_r from pipeline.toolset_sample_runs where id = (p_args->>'run_id')::uuid;
    if v_r.id is null then raise exception 'unknown run'; end if;
    update pipeline.toolset_sample_runs set status = 'stopped', status_note = v_reason, updated_at = now(), finished_at = now() where id = v_r.id and status in ('ready', 'running', 'paused_time_limit');
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'sample_stop', v_r.id::text, jsonb_build_object('reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true);
  end if;
  raise exception 'unknown action %', p_action;
end $$;


ALTER FUNCTION "public"."admin_toolset_sample_write"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_toolset_samples_read"("p_run_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  return jsonb_build_object('can_manage', v_rank >= 6,
    'runs', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'toolset', r.toolset_key, 'purpose', r.purpose, 'countries', r.countries, 'status', r.status, 'status_note', r.status_note,
                'credits_used', r.credits_used, 'reason', r.reason, 'created_at', r.created_at, 'finished_at', r.finished_at,
                'cases', (select count(*) from pipeline.toolset_sample_items i where i.run_id = r.id),
                'done', (select count(*) from pipeline.toolset_sample_items i where i.run_id = r.id and i.status = 'done'),
                'usd_per_1k_credits', r.settings->'usd_per_1k_credits', 'plan_name', r.settings->'plan_name') order by r.created_at desc), '[]'::jsonb)
             from (select * from pipeline.toolset_sample_runs order by created_at desc limit 30) r),
    'summary', (select coalesce(jsonb_agg(jsonb_build_object('toolset', z.toolset_key, 'purpose', z.purpose, 'country', z.country, 'outcome', z.outcome, 'n', z.n,
                    'credits', z.credits, 'avg_latency_ms', z.lat) order by z.toolset_key, z.purpose, z.country, z.n desc), '[]'::jsonb)
                from (select r.toolset_key, r.purpose, i.country, i.outcome, count(*) n, sum(i.credits) credits, round(avg(i.latency_ms)) lat
                      from pipeline.toolset_sample_items i join pipeline.toolset_sample_runs r on r.id = i.run_id
                      where i.status = 'done' and (p_run_id is null or r.id = p_run_id) group by 1, 2, 3, 4) z),
    'backlog', (select coalesce(jsonb_agg(jsonb_build_object('toolset', t.toolset, 'purpose', t.purpose, 'country', c.cc, 'n', (select count(*) from security.toolset_backlog(t.purpose, c.cc)))), '[]'::jsonb)
                from (values ('serper', 'find_course_page'), ('serper', 'find_provider_site'), ('scrapingbee', 'render_page')) t(toolset, purpose)
                cross join lateral (select jsonb_array_elements_text(coalesce(security.toolset_setting(t.toolset, 'sample_countries'), '[]'::jsonb)) cc) c),
    'items', (select coalesce(jsonb_agg(jsonb_build_object('country', i.country, 'input', i.input, 'outcome', i.outcome, 'http_status', i.http_status, 'credits', i.credits,
                 'latency_ms', i.latency_ms, 'result', i.result, 'done_at', i.done_at) order by i.country, i.outcome, i.done_at), '[]'::jsonb)
              from pipeline.toolset_sample_items i where p_run_id is not null and i.run_id = p_run_id and i.status = 'done'));
end $$;


ALTER FUNCTION "public"."admin_toolset_samples_read"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_toolsets_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  return jsonb_build_object('can_manage', v_rank >= 6,
    'toolsets', (select coalesce(jsonb_agg(jsonb_build_object('key', t.key, 'label', t.label, 'kind', t.kind, 'layers', t.layers, 'enforcement', t.enforcement, 'help', t.help,
        'updated_at', t.updated_at, 'reason', t.reason,
        'key_saved', (select p.vault_secret_id is not null from pipeline.layer2_acquisition_providers p where p.provider_key = t.provider_key),
        'switched_on', (select p.enabled from pipeline.layer2_acquisition_providers p where p.provider_key = t.provider_key),
        'plan', case when exists (select 1 from pipeline.platform_toolset_settings s where s.toolset_key = t.key and s.key = 'plan_credits') then security.toolset_plan_status(t.key) end,
        'settings', (select coalesce(jsonb_agg(jsonb_build_object('key', s.key, 'label', s.label, 'help', s.help, 'kind', s.kind, 'value', s.value, 'min', s.min_value, 'max', s.max_value,
                        'unit', s.unit, 'section', s.section, 'updated_at', s.updated_at, 'reason', s.reason) order by s.sort, s.key), '[]'::jsonb)
                     from pipeline.platform_toolset_settings s where s.toolset_key = t.key)) order by t.sort), '[]'::jsonb)
      from pipeline.platform_toolsets t),
    'openrouter', jsonb_build_object(
      'balance', (select jsonb_build_object('remaining_usd', o.remaining_usd, 'observed_at', o.observed_at, 'total_credits', o.payload->'total_credits', 'total_usage', o.payload->'total_usage')
                  from pipeline.layer3_openrouter_observations o where o.kind = 'credits' order by o.observed_at desc limit 1),
      'guards', (select coalesce(jsonb_agg(jsonb_build_object('task_class', b.task_class, 'daily_usd_max', b.daily_usd_max, 'credit_floor_usd', b.credit_floor_usd,
                    'spent_today', (select coalesce(sum(i.estimated_cost_usd), 0) from pipeline.layer3_interpretations i where i.task_class = b.task_class
                                    and i.created_at >= date_trunc('day', now() at time zone 'UTC') at time zone 'UTC')) order by b.task_class), '[]'::jsonb)
                 from pipeline.layer3_route_budget b),
      'spend_by_day', (select coalesce(jsonb_agg(jsonb_build_object('day', d.day, 'usd', d.usd, 'calls', d.calls) order by d.day), '[]'::jsonb)
                       from (select (i.created_at at time zone 'UTC')::date as day, round(sum(i.estimated_cost_usd), 4) usd, count(*) calls
                             from pipeline.layer3_interpretations i where i.created_at > now() - interval '14 days' group by 1) d)),
    'job_layers', (select coalesce(jsonb_object_agg(l.jobname, l.layer), '{}'::jsonb) from pipeline.platform_job_layers l));
end $$;


ALTER FUNCTION "public"."admin_toolsets_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_toolsets_write"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', ''));
        v_set pipeline.platform_toolset_settings%rowtype; v_val jsonb; v_num numeric; v_before jsonb; v_t pipeline.platform_toolsets%rowtype;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'setting' then
    select * into v_set from pipeline.platform_toolset_settings where toolset_key = p_args->>'toolset' and key = p_args->>'key';
    if v_set.key is null then raise exception 'unknown setting'; end if;
    v_val := p_args->'value';
    if v_set.kind = 'number' then
      v_num := (v_val #>> '{}')::numeric;
      if v_num is null or (v_set.min_value is not null and v_num < v_set.min_value) or (v_set.max_value is not null and v_num > v_set.max_value) then
        raise exception 'value must be between % and %', v_set.min_value, v_set.max_value; end if;
      v_val := to_jsonb(v_num);
    elsif v_set.kind = 'boolean' then v_val := to_jsonb((v_val #>> '{}')::boolean);
    elsif v_set.kind = 'list' then
      if jsonb_typeof(v_val) <> 'array' then raise exception 'a list is needed'; end if;
    else v_val := to_jsonb(btrim(v_val #>> '{}'));
      if length(v_val #>> '{}') = 0 then raise exception 'text cannot be empty'; end if;
    end if;
    v_before := v_set.value;
    update pipeline.platform_toolset_settings set value = v_val, reason = v_reason, updated_by = auth.uid(), updated_at = now() where toolset_key = v_set.toolset_key and key = v_set.key;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'setting', v_set.toolset_key || '.' || v_set.key, jsonb_build_object('before', v_before, 'after', v_val, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'toolset', v_set.toolset_key, 'key', v_set.key, 'value', v_val);
  elsif p_action = 'enforcement' then
    select * into v_t from pipeline.platform_toolsets where key = p_args->>'toolset';
    if v_t.key is null or v_t.enforcement is null then raise exception 'this toolset has no enforcement mode'; end if;
    if p_args->>'enforcement' not in ('observe', 'stop') then raise exception 'enforcement must be observe or stop'; end if;
    update pipeline.platform_toolsets set enforcement = p_args->>'enforcement', reason = v_reason, updated_by = auth.uid(), updated_at = now() where key = v_t.key;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'enforcement', v_t.key, jsonb_build_object('before', v_t.enforcement, 'after', p_args->>'enforcement', 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'toolset', v_t.key, 'enforcement', p_args->>'enforcement');
  elsif p_action = 'job_layer' then
    if not exists (select 1 from cron.job where jobname = p_args->>'jobname') then raise exception 'unknown job'; end if;
    if (p_args->>'layer')::int not between 0 and 4 then raise exception 'layer must be 0 to 4'; end if;
    insert into pipeline.platform_job_layers(jobname, layer, updated_at) values (p_args->>'jobname', (p_args->>'layer')::int, now())
      on conflict (jobname) do update set layer = excluded.layer, updated_at = now();
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'job_layer', p_args->>'jobname', jsonb_build_object('layer', p_args->'layer', 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true);
  elsif p_action = 'ack' then
    if coalesce(p_args->>'notice_key', '') = '' then raise exception 'notice_key required'; end if;
    insert into pipeline.platform_notice_acks(notice_key, acknowledged_at, acknowledged_by, reason) values (p_args->>'notice_key', now(), auth.uid(), v_reason)
      on conflict (notice_key) do update set acknowledged_at = now(), acknowledged_by = auth.uid(), reason = v_reason;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'ack', p_args->>'notice_key', jsonb_build_object('reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true);
  end if;
  raise exception 'unknown action %', p_action;
end $$;


ALTER FUNCTION "public"."admin_toolsets_write"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_uni_adapter_control"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid := (p_args->>'provider_id')::uuid; v_id bigint;
        v_field text := p_args->>'field'; v_on boolean := coalesce((p_args->>'exclude')::boolean, true); v_courses uuid[];
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'admit' then
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    if not exists (select 1 from pipeline.uni_adapters u where u.provider_id = v_pid and u.enabled) then raise exception 'save the adapter switched on first'; end if;
    if p_args ? 'fields' and (jsonb_typeof(p_args->'fields') <> 'array' or exists (select 1 from jsonb_array_elements_text(p_args->'fields') f where f not in ('intakes', 'english', 'fee', 'delivery', 'exit_awards', 'host_pages'))) then raise exception 'fields must be a list of intakes, english, fee, delivery, exit_awards and host_pages'; end if;
    update pipeline.uni_adapters set admit = coalesce((p_args->>'admit')::boolean, false), admit_fields = case when p_args ? 'fields' then array(select distinct f from jsonb_array_elements_text(p_args->'fields') f order by f) else admit_fields end, admit_reason = v_reason, admit_changed_at = now() where provider_id = v_pid;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'uni_adapter_admit', v_pid::text, jsonb_build_object('admit', p_args->'admit', 'fields', (select to_jsonb(u.admit_fields) from pipeline.uni_adapters u where u.provider_id = v_pid), 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'fields', (select to_jsonb(u.admit_fields) from pipeline.uni_adapters u where u.provider_id = v_pid));
  elsif p_action = 'exclude' then
    -- 5 Oct: a course and field the adapter must not admit (its page reading is wrong). Switched off with exclude false.
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    if coalesce(v_field, '') not in ('intakes', 'english', 'fee', 'delivery') then raise exception 'field must be intakes, english, fee or delivery'; end if;
    v_courses := array(select distinct pg.course_id from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id
                        where pg.provider_id = v_pid and (pg.course_id::text = p_args->>'course_id' or (coalesce(p_args->>'code', '') <> '' and c.course_code = p_args->>'code') or (coalesce(p_args->>'url', '') <> '' and pg.url = p_args->>'url')));
    if cardinality(v_courses) = 0 then raise exception 'no course of this university has that course id, code or page'; end if;
    insert into pipeline.uni_adapter_exclusions(course_id, field, provider_id, active, reason, set_by, set_at)
      select x, v_field, v_pid, v_on, v_reason, auth.uid(), now() from unnest(v_courses) x where v_field <> 'delivery'
    on conflict (course_id, field) do update set active = excluded.active, reason = excluded.reason, set_by = excluded.set_by, set_at = now() where pipeline.uni_adapter_exclusions.course_id = excluded.course_id;
    if v_on and v_field = 'intakes' then update pipeline.coverage_course_pages pg set candidates = pg.candidates - 'intakes' - 'intake_context' - 'intakes_by' where pg.course_id = any (v_courses) and pg.candidates->>'intakes_by' = 'adapter'; end if;
    insert into pipeline.uni_adapter_delivery_exclusions(course_id, provider_id, active, reason, set_by, set_at) select x, v_pid, v_on, v_reason, auth.uid(), now() from unnest(v_courses) x where v_field = 'delivery' on conflict (course_id) do update set active = excluded.active, reason = excluded.reason, set_by = excluded.set_by, set_at = now() where pipeline.uni_adapter_delivery_exclusions.course_id = excluded.course_id;
    -- 5 Oct 15:40: an exclusion also withdraws what the excluded reading put in the catalogue (coverage source only)
    update catalogue.course_fees set status = 'superseded', updated_at = now() where course_id = any (v_courses) and v_on and v_field = 'fee' and status = 'active' and fee_type = 'provider_current_tuition' and audience = 'international' and source_id = security.coverage_sweep_source(v_pid) and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = course_id and k.field in ('tuition', 'fee', 'fees'));
    update catalogue.course_intakes set status = 'withdrawn' where course_id = any (v_courses) and v_on and v_field = 'intakes' and status = 'active' and source_id = security.coverage_sweep_source(v_pid) and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = course_id and k.field in ('intakes', 'intake'));
    update catalogue.course_english_requirements set status = 'withdrawn' where course_id = any (v_courses) and v_on and v_field = 'english' and status = 'active' and source_id = security.coverage_sweep_source(v_pid) and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = course_id and k.field in ('english', 'english_requirements'));
    update catalogue.courses c set delivery_mode = null, updated_at = now() where c.id = any (v_courses) and v_on and v_field = 'delivery' and exists (select 1 from pipeline.adapter_overwrite_changes x where x.course_id = c.id and x.field = 'delivery' and x.after = to_jsonb(c.delivery_mode)) and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field in ('delivery_mode', 'delivery'));
    if v_on then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;
    if v_on and v_field = 'fee' then update pipeline.coverage_course_pages pg set candidates = pg.candidates - 'fee' - 'fee_by' where pg.course_id = any (v_courses) and pg.candidates->>'fee_by' = 'adapter'; end if;
    if v_on and v_field = 'english' then update pipeline.coverage_course_pages pg set candidates = pg.candidates - 'english' - 'english_by' where pg.course_id = any (v_courses) and pg.candidates->>'english_by' = 'adapter'; end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'uni_adapter_exclude', v_pid::text, jsonb_build_object('courses', to_jsonb(v_courses), 'field', v_field, 'exclude', v_on, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'courses', cardinality(v_courses));
  elsif p_action = 'request' then
    if length(btrim(coalesce(p_args->>'request', ''))) < 4 then raise exception 'write the improvement you want'; end if;
    if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
    insert into pipeline.uni_adapter_requests(provider_id, request, requested_by) values (v_pid, btrim(p_args->>'request'), auth.uid()) returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'uni_adapter_request', v_pid::text, jsonb_build_object('request_id', v_id, 'request', p_args->>'request'), auth.uid());
    return jsonb_build_object('ok', true, 'id', v_id);
  elsif p_action = 'answer' then
    if p_args->>'status' not in ('done', 'declined', 'open') then raise exception 'status must be done, declined or open'; end if;
    update pipeline.uni_adapter_requests set status = p_args->>'status', answer = nullif(btrim(coalesce(p_args->>'answer', '')), ''), answered_at = now() where id = (p_args->>'id')::bigint;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'uni_adapter_request_answer', p_args->>'id', jsonb_build_object('status', p_args->>'status', 'answer', p_args->>'answer'), auth.uid());
    return jsonb_build_object('ok', true);
  end if;
  raise exception 'unknown action';
end $$;


ALTER FUNCTION "public"."admin_uni_adapter_control"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_uni_adapter_fee_year"("p_provider_id" "uuid", "p_year" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_reason, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_year is not null and p_year not between extract(year from now() at time zone 'Australia/Melbourne')::int and extract(year from now() at time zone 'Australia/Melbourne')::int + 1 then
    raise exception 'the fee year must be this year or next year'; end if;
  select reading into v_before from pipeline.uni_adapters where provider_id = p_provider_id for update;
  if not found then raise exception 'no adapter for this provider'; end if;
  update pipeline.uni_adapters
     set reading = case when p_year is null then coalesce(reading, '{}'::jsonb) - 'fee_year' else coalesce(reading, '{}'::jsonb) || jsonb_build_object('fee_year', p_year) end,
         reason = left(p_reason, 500), updated_by = auth.uid(), updated_at = now()
   where provider_id = p_provider_id returning reading into v_after;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('adapters', 'adapter_fee_year_set', p_provider_id::text, jsonb_build_object('provider_id', p_provider_id, 'before', v_before, 'after', v_after, 'reason', left(p_reason, 500)), auth.uid());
  return jsonb_build_object('ok', true, 'reading', v_after);
end $$;


ALTER FUNCTION "public"."admin_uni_adapter_fee_year"("p_provider_id" "uuid", "p_year" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_uni_adapter_read"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  return jsonb_build_object(
    'can_manage', coalesce(v_rank, 0) >= 6,
    'provider', (select jsonb_build_object('id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'website', p.website) from catalogue.providers p where p.id = p_provider_id),
    'adapter', security.uni_adapter_json(p_provider_id),
    'pages', (select jsonb_object_agg(coalesce(s, 'none'), n) from (select pg.read_status s, count(*) n from pipeline.coverage_course_pages pg where pg.provider_id = p_provider_id group by 1) x),
    'previews', coalesce((select jsonb_agg(jsonb_build_object('id', v.id, 'created_at', v.created_at, 'done_at', v.done_at, 'adapter', v.adapter, 'result', v.result) order by v.created_at desc) from (select * from pipeline.uni_adapter_previews v where v.provider_id = p_provider_id order by created_at desc limit 3) v), '[]'::jsonb),
    'applied', coalesce((select jsonb_agg(jsonb_build_object('identity', r.identity, 'before', r.before_read_status, 'n', r.n, 'last_at', r.last_at)) from (select identity, before_read_status, count(*) n, max(at) last_at from pipeline.uni_adapter_results where provider_id = p_provider_id group by 1, 2) r), '[]'::jsonb),
    'allowed', (select jsonb_agg(jsonb_build_object('country', k.iso_alpha2::text, 'identities', c.identities)) from pipeline.coverage_admission_countries c join ref.countries k on k.id = c.country_id)
  );
end $$;


ALTER FUNCTION "public"."admin_uni_adapter_read"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_uni_adapter_review"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  return jsonb_build_object(
    'admit', (select jsonb_build_object('on', u.admit, 'fields', to_jsonb(u.admit_fields), 'reason', u.admit_reason, 'changed_at', u.admit_changed_at) from pipeline.uni_adapters u where u.provider_id = p_provider_id),
    'exclusions', (select coalesce(jsonb_agg(jsonb_build_object('course_id', x.course_id, 'course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'field', x.field, 'reason', x.reason, 'set_at', x.set_at) order by x.set_at desc), '[]'::jsonb)
                     from pipeline.uni_adapter_exclusions x join catalogue.courses c on c.id = x.course_id where x.provider_id = p_provider_id and x.active),
    'confirmed', coalesce((select jsonb_agg(x) from (
        select jsonb_build_object('course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'url', pg.url, 'identity', pg.identity_basis,
                                  'intakes', pg.candidates->'intakes', 'ielts', pg.candidates->'english'->'ielts_overall', 'english_context', left(pg.candidates->'english'->>'context', 160),
                                  'link_admitted', exists (select 1 from catalogue.course_links l where l.course_id = c.id and l.url = pg.url and l.status = 'active'),
                                  'english_admitted', exists (select 1 from catalogue.course_english_requirements e where e.course_id = c.id and e.evidence_id = pg.evidence_id and coalesce(e.status, 'active') = 'active')) x
        from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id
        where pg.provider_id = p_provider_id and pg.identity_basis in ('adapter_code', 'adapter_title') and pg.read_status = 'read'
        order by pg.read_at desc nulls last limit 40) q), '[]'::jsonb),
    'confirmed_total', (select count(*) from pipeline.coverage_course_pages pg where pg.provider_id = p_provider_id and pg.identity_basis in ('adapter_code', 'adapter_title') and pg.read_status = 'read'),
    -- v0.16.0: what the adapter read on pages confirmed another way (CRICOS code on the page): its own readings and the
    -- extra fields, and whether an intake would be admitted (only with the admit switch on)
    'readings', coalesce((select jsonb_agg(x) from (
        select jsonb_build_object('course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'url', pg.url, 'identity', pg.identity_basis,
                                  'intakes', pg.candidates->'intakes', 'intakes_by', pg.candidates->>'intakes_by', 'intake_context', pg.candidates->'intake_context'->>0,
                                  'fee', pg.candidates->'fee'->'value', 'fee_by', pg.candidates->>'fee_by', 'ielts', pg.candidates->'english'->'ielts_overall', 'english_by', pg.candidates->>'english_by',
                                  'extra', pg.candidates->'adapter_extra',
                                  'intakes_now', (select jsonb_agg(i.intake_label) from catalogue.course_intakes i where i.course_id = c.id and coalesce(i.status, 'active') = 'active')) x
        from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id
        where pg.provider_id = p_provider_id and pg.read_status = 'read' and (pg.candidates ? 'intakes_by' or pg.candidates ? 'adapter_extra' or pg.candidates ? 'fee_by' or pg.candidates ? 'english_by')
        order by pg.read_at desc nulls last limit 60) q), '[]'::jsonb),
    'readings_total', (select count(*) from pipeline.coverage_course_pages pg where pg.provider_id = p_provider_id and pg.read_status = 'read' and (pg.candidates ? 'intakes_by' or pg.candidates ? 'adapter_extra' or pg.candidates ? 'fee_by' or pg.candidates ? 'english_by')),
    'intakes_by_adapter', (select count(*) from pipeline.coverage_course_pages pg where pg.provider_id = p_provider_id and pg.read_status = 'read' and pg.candidates->>'intakes_by' = 'adapter'),
    'requests', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'request', r.request, 'status', r.status, 'answer', r.answer, 'requested_at', r.requested_at, 'answered_at', r.answered_at) order by r.requested_at desc) from pipeline.uni_adapter_requests r where r.provider_id = p_provider_id), '[]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."admin_uni_adapter_review"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_uni_adapter_write"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid := (p_args->>'provider_id')::uuid; v_a jsonb := coalesce(p_args->'adapter', '{}'::jsonb);
        v_id uuid; k text; v text; v_before jsonb; v_n int;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
  if p_action in ('save', 'preview') then
    if jsonb_typeof(coalesce(v_a->'json_paths', '{}'::jsonb)) <> 'object' or jsonb_typeof(coalesce(v_a->'sections', '{}'::jsonb)) <> 'object' then raise exception 'json_paths and sections must be field to text maps'; end if;
    for k, v in select x.key, x.value from jsonb_each_text(coalesce(v_a->'sections', '{}'::jsonb)) x union all select 'title_strip', v_a->>'title_strip' union all select 'course_title_strip', v_a->>'course_title_strip' loop
      if not security.uni_adapter_pattern_ok(v) then raise exception 'the pattern for % cannot be read: %', k, v; end if;
    end loop;
    if jsonb_typeof(coalesce(v_a->'patterns', '{}'::jsonb)) <> 'object' or jsonb_typeof(coalesce(v_a->'pick', '{}'::jsonb)) <> 'object' then raise exception 'patterns and pick must be field to text maps'; end if;
    for k, v in select x.key, x.value from jsonb_each_text(coalesce(v_a->'patterns', '{}'::jsonb)) x loop
      if k <> all (security.uni_adapter_pattern_fields()) then raise exception 'a pattern can only be set for: %', array_to_string(security.uni_adapter_pattern_fields(), ', '); end if;
      if not security.uni_adapter_pattern_ok(v) then raise exception 'the pattern for % cannot be read: %', k, v; end if;
    end loop;
    for k, v in select x.key, x.value from jsonb_each_text(coalesce(v_a->'pick', '{}'::jsonb)) x loop
      if v not in ('first', 'last', 'all') then raise exception 'pick for % must be first, last or all', k; end if;
    end loop;
    if jsonb_typeof(coalesce(v_a->'term_months', '{}'::jsonb)) <> 'object' then raise exception 'term_months must be a term to month map'; end if;
    for k, v in select x.key, x.value from jsonb_each_text(coalesce(v_a->'term_months', '{}'::jsonb)) x loop
      if length(btrim(k)) < 3 or length(k) > 40 then raise exception 'a term name must be 3 to 40 characters: %', k; end if;
      if v !~ '^(January|February|March|April|May|June|July|August|September|October|November|December)( (January|February|March|April|May|June|July|August|September|October|November|December))*$' then raise exception 'the months for % must be month names separated by spaces: %', k, v; end if;
    end loop;
    if jsonb_typeof(coalesce(v_a->'page_view', '{}'::jsonb)) <> 'object' or coalesce(v_a->'page_view'->>'suffix', '') !~ '^([#?&][^ <>]{1,250})?$'
       or coalesce(v_a->'page_view'->>'wait_ms', '0') !~ '^[0-9]{1,4}$' or coalesce((v_a->'page_view'->>'wait_ms')::int, 0) > 8000
       or coalesce(v_a->'page_view'->>'render', 'false') not in ('true', 'false') or not security.uni_adapter_pattern_ok(v_a->'page_view'->>'url_pattern') then
      raise exception 'page_view must hold render (true or false), suffix (starting with # ? or &), wait_ms (0 to 8000) and a readable url_pattern';
    end if;
    if coalesce(v_a->>'json_source', '') !~ '^[A-Za-z0-9_-]*$' then raise exception 'the JSON script id may only hold letters, digits, _ and -'; end if;
    if jsonb_typeof(coalesce(v_a->'reading', '{}'::jsonb)) <> 'object'
       or exists (select 1 from jsonb_each(coalesce(v_a->'reading', '{}'::jsonb)) r where r.key not in ('numeric_dates', 'upper_dates', 'academic_year', 'fee_year') or (r.key <> 'fee_year' and jsonb_typeof(r.value) <> 'boolean') or (r.key = 'fee_year' and r.value::text !~ '^20[2-9][0-9]$')) then
      raise exception 'reading may only hold numeric_dates, upper_dates and academic_year (each true or false) and fee_year (a year)'; end if;
  end if;
  if p_action = 'save' then
    v_before := security.uni_adapter_json(v_pid);
    insert into pipeline.uni_adapters(provider_id, enabled, title_strip, course_title_strip, json_source, json_paths, sections, patterns, pick, term_months, page_view, reading, section_chars, notes, reason, updated_by, updated_at)
      values (v_pid, coalesce((v_a->>'enabled')::boolean, false), nullif(btrim(v_a->>'title_strip'), ''), nullif(btrim(v_a->>'course_title_strip'), ''), nullif(btrim(v_a->>'json_source'), ''),
              coalesce(v_a->'json_paths', '{}'::jsonb), coalesce(v_a->'sections', '{}'::jsonb), coalesce(v_a->'patterns', '{}'::jsonb), coalesce(v_a->'pick', '{}'::jsonb), coalesce(v_a->'term_months', '{}'::jsonb), coalesce(v_a->'page_view', '{}'::jsonb), coalesce(v_a->'reading', '{}'::jsonb), greatest(200, least(coalesce((v_a->>'section_chars')::int, 2000), 10000)), v_a->>'notes', v_reason, auth.uid(), now())
    on conflict (provider_id) do update set enabled = excluded.enabled, title_strip = excluded.title_strip, course_title_strip = excluded.course_title_strip, json_source = excluded.json_source, json_paths = excluded.json_paths, sections = excluded.sections, patterns = excluded.patterns, pick = excluded.pick, term_months = excluded.term_months, page_view = excluded.page_view, reading = excluded.reading, section_chars = excluded.section_chars, notes = excluded.notes, reason = excluded.reason, updated_by = excluded.updated_by, updated_at = now() where pipeline.uni_adapters.provider_id = excluded.provider_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'uni_adapter_save', v_pid::text, jsonb_build_object('before', v_before, 'after', security.uni_adapter_json(v_pid), 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'adapter', security.uni_adapter_json(v_pid));
  elsif p_action = 'preview' then
    insert into pipeline.uni_adapter_previews(provider_id, adapter, requested_by) values (v_pid, v_a, auth.uid()) returning id into v_id;
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_preview', 'preview_id', v_id));
    return jsonb_build_object('ok', true, 'preview_id', v_id);
  elsif p_action = 'read_view' then
    v_n := security.uni_adapter_view_requeue_v2(v_pid, v_reason, coalesce((p_args->>'limit')::int, 600), p_args->>'only');
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'uni_adapter_read_view', v_pid::text, jsonb_build_object('page_view', security.uni_adapter_json(v_pid)->'page_view', 'pages_read_again', v_n, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'pages_read_again', v_n);
  elsif p_action = 'apply' then
    if not exists (select 1 from pipeline.uni_adapters a where a.provider_id = v_pid and a.enabled) then raise exception 'save the adapter switched on first'; end if;
    v_n := security.uni_adapter_requeue_v1(v_pid, v_reason);
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'uni_adapter_apply', v_pid::text, jsonb_build_object('adapter', security.uni_adapter_json(v_pid), 'pages_read_again', v_n, 'reason', v_reason), auth.uid());
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_apply', 'provider_id', v_pid));
    return jsonb_build_object('ok', true, 'pages_read_again', v_n);
  end if;
  raise exception 'unknown action';
end $_$;


ALTER FUNCTION "public"."admin_uni_adapter_write"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_universities_read"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_country text := nullif(upper(btrim(coalesce(p_args->>'country', ''))), ''); v_q text := nullif(btrim(coalesce(p_args->>'query', '')), '');
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Layer 4 reviewer or Platform Admin required' using errcode = '42501'; end if;
  return jsonb_build_object('as_at', now(), 'universities', coalesce((
    select jsonb_agg(u order by u->>'name') from (
      select jsonb_build_object(
        'provider_id', t.provider_id, 'name', t.name, 'country', t.country, 'domain', t.domain,
        'adapter', (select jsonb_build_object('state', case when a.enabled and a.admit then 'admitting' when a.enabled then 'testing' else 'off' end,
                                              'fields', to_jsonb(a.admit_fields), 'admit_changed_at', a.admit_changed_at,
                                              'exclusions', (select count(*) from pipeline.uni_adapter_exclusions x where x.provider_id = a.provider_id and x.active))
                    from pipeline.uni_adapters a where a.provider_id = t.provider_id),
        'english_policy', (select jsonb_build_object('status', pp.status, 'style', pp.style, 'url', pp.url, 'decided_at', pp.decided_at)
                           from pipeline.provider_policy_proposals pp where pp.provider_id = t.provider_id and pp.kind = 'english_policy' and pp.status in ('approved', 'proposed', 'no_values')
                           order by (pp.status = 'approved') desc, (pp.status = 'proposed') desc, pp.updated_at desc limit 1),
        'calendar', (select jsonb_build_object('status', pp.status, 'style', pp.style, 'url', pp.url, 'decided_at', pp.decided_at)
                     from pipeline.provider_policy_proposals pp where pp.provider_id = t.provider_id and pp.kind = 'intake_calendar' and pp.status in ('approved', 'proposed', 'no_values')
                     order by (pp.status = 'approved') desc, (pp.status = 'proposed') desc, pp.updated_at desc limit 1),
        'central_pages', (select coalesce(jsonb_agg(jsonb_build_object('kind', s.kind, 'url', s.url, 'status', s.status, 'read_at', s.read_at, 'evidence_id', s.evidence_id) order by s.kind, s.rank desc), '[]'::jsonb)
                          from pipeline.provider_fact_sources s where s.provider_id = t.provider_id and s.found_via = 'manual' and s.kind in ('english_policy', 'intake_calendar')),
        'courses', m.courses, 'pages_read', m.pages_read,
        'intakes', jsonb_build_object('held', m.i_held, 'adapter', m.i_adapter, 'central', m.i_central, 'reader', m.i_reader, 'excluded', m.i_x),
        'english', jsonb_build_object('held', m.e_held, 'adapter', m.e_adapter, 'central', m.e_central, 'reader', m.e_reader, 'excluded', m.e_x),
        'fee', jsonb_build_object('held', m.f_held, 'adapter', m.f_adapter, 'reader', m.f_reader, 'excluded', m.f_x)) u
      from security.firecrawl_targets_fast() t
      cross join lateral (select count(*) courses, count(*) filter (where cf.read_status = 'read') pages_read,
                                 count(*) filter (where cf.intakes_src <> 'missing') i_held, count(*) filter (where cf.intakes_src = 'adapter') i_adapter,
                                 count(*) filter (where cf.intakes_src = 'central') i_central, count(*) filter (where cf.intakes_src = 'reader') i_reader, count(*) filter (where cf.intakes_x) i_x,
                                 count(*) filter (where cf.english_src <> 'missing') e_held, count(*) filter (where cf.english_src = 'adapter') e_adapter,
                                 count(*) filter (where cf.english_src = 'central') e_central, count(*) filter (where cf.english_src = 'reader') e_reader, count(*) filter (where cf.english_x) e_x,
                                 count(*) filter (where cf.fee_src <> 'missing') f_held, count(*) filter (where cf.fee_src = 'adapter') f_adapter,
                                 count(*) filter (where cf.fee_src = 'reader') f_reader, count(*) filter (where cf.fee_x) f_x
                          from security.university_course_fields_v1(t.provider_id) cf) m
      where (t.included or exists (select 1 from pipeline.uni_adapters a where a.provider_id = t.provider_id))
        and (v_country is null or t.country = v_country)
        and (v_q is null or t.name ilike '%' || v_q || '%')) z), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."admin_universities_read"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_university_courses_read"("p_provider_id" "uuid", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_show text := coalesce(p_args->>'show', 'all');
        v_limit int := greatest(1, least(coalesce((p_args->>'limit')::int, 100), 500)); v_offset int := greatest(0, coalesce((p_args->>'offset')::int, 0));
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Layer 4 reviewer or Platform Admin required' using errcode = '42501'; end if;
  if v_show not in ('all', 'missing', 'excluded', 'adapter', 'central') then raise exception 'show must be all, missing, excluded, adapter or central'; end if;
  return (with cf as (select * from security.university_course_fields_v1(p_provider_id) x
                       where v_show = 'all'
                          or (v_show = 'missing' and 'missing' in (x.intakes_src, x.english_src, x.fee_src))
                          or (v_show = 'excluded' and (x.intakes_x or x.english_x or x.fee_x))
                          or (v_show = 'adapter' and 'adapter' in (x.intakes_src, x.english_src, x.fee_src))
                          or (v_show = 'central' and 'central' in (x.intakes_src, x.english_src)))
    select jsonb_build_object('total', (select count(*) from cf), 'offset', v_offset, 'limit', v_limit,
      'courses', coalesce((select jsonb_agg(jsonb_build_object('course_id', y.course_id, 'course', y.course, 'code', y.code, 'level', y.level, 'url', y.url, 'read_status', y.read_status, 'evidence_id', y.evidence_id,
                                     'intakes', jsonb_build_object('value', to_jsonb(y.intakes), 'source', y.intakes_src, 'excluded', y.intakes_x),
                                     'english', jsonb_build_object('value', y.ielts, 'source', y.english_src, 'excluded', y.english_x),
                                     'fee', jsonb_build_object('value', y.fee, 'year', y.fee_year, 'currency', y.fee_currency, 'source', y.fee_src, 'excluded', y.fee_x), 'delivery', security.university_course_delivery_v1(y.course_id), 'location', security.university_course_location_v1(y.course_id), 'requirement', security.university_course_requirement_v1(y.course_id), 'host', security.university_course_host_v1(y.course_id)) order by y.course)
                           from (select * from cf order by cf.course limit v_limit offset v_offset) y), '[]'::jsonb)));
end $$;


ALTER FUNCTION "public"."admin_university_courses_read"("p_provider_id" "uuid", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_university_reread"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', ''));
  v_ids uuid[]; v_which text := coalesce(nullif(p_args->>'which', ''), 'all'); v_central boolean := coalesce((p_args->>'central')::boolean, false);
  v_res jsonb; v_id uuid;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Layer 4 reviewer or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'requests' then
    return coalesce((select jsonb_agg(jsonb_build_object('id', q.id, 'universities', cardinality(q.provider_ids), 'done', cardinality(q.done_ids), 'which', q.which, 'central', q.central,
                       'pages', q.pages, 'central_pages', q.central_pages, 'status', q.status, 'last_error', q.last_error, 'requested_at', q.requested_at, 'finished_at', q.finished_at, 'reason', q.reason) order by q.requested_at desc)
                       from (select * from pipeline.university_reread_requests order by requested_at desc limit 10) q), '[]'::jsonb);
  end if;
  if v_which not in ('all', 'not_confirmed') then raise exception 'which must be all or not_confirmed'; end if;
  v_ids := array(select distinct (x)::uuid from jsonb_array_elements_text(coalesce(p_args->'provider_ids', '[]'::jsonb)) x);
  if cardinality(v_ids) = 0 then raise exception 'choose at least one university'; end if;
  if p_action = 'preview' then
    return jsonb_build_object('which', v_which, 'central', v_central,
      'universities', coalesce((
        with pages as materialized (select r.provider_id, count(*) n, count(*) filter (where r.firecrawl_likely) fc from security.university_reread_pages_v1(v_ids, v_which) r group by r.provider_id),
             cent as materialized (select fs.provider_id, count(*) n from pipeline.provider_fact_sources fs where v_central and fs.provider_id = any (v_ids) and fs.kind in ('english_policy', 'intake_calendar') group by fs.provider_id)
        select jsonb_agg(jsonb_build_object('provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'pages', coalesce(pages.n, 0), 'firecrawl_likely', coalesce(pages.fc, 0), 'central_pages', coalesce(cent.n, 0))
                         order by coalesce(p.display_name, p.canonical_name))
          from catalogue.providers p left join pages on pages.provider_id = p.id left join cent on cent.provider_id = p.id where p.id = any (v_ids)), '[]'::jsonb));
  end if;
  if coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action <> 'queue' then raise exception 'unknown action'; end if;
  insert into pipeline.university_reread_requests(provider_ids, which, central, reason, requested_by) values (v_ids, v_which, v_central, v_reason, auth.uid()) returning id into v_id;
  v_res := jsonb_build_object('ok', true, 'request_id', v_id, 'universities', cardinality(v_ids), 'status', 'waiting');
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('coverage', 'university_reread', array_to_string(v_ids, ','), jsonb_build_object('result', v_res, 'args', p_args), auth.uid());
  return v_res;
end $$;


ALTER FUNCTION "public"."admin_university_reread"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_value_note_add"("p_course_id" "uuid", "p_field" "text", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid; v_field text := lower(btrim(coalesce(p_field, 'other')));
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  if v_field not in ('official_url', 'intakes', 'english', 'tuition', 'scholarship', 'title', 'duration', 'delivery', 'description', 'other') then raise exception 'unknown field %', p_field; end if;
  if length(btrim(coalesce(p_note, ''))) < 3 then raise exception 'a note is required'; end if;
  if not exists (select 1 from catalogue.courses where id = p_course_id) then raise exception 'course not found'; end if;
  insert into pipeline.data_flags(entity_type, entity_id, field_code, flag_code, detail, status, change_control_ref)
  values ('course', p_course_id, v_field, 'note',
          jsonb_build_object('note', left(btrim(p_note), 1000), 'source', 'admin', 'by', auth.uid(), 'quotes', jsonb_build_array(left(btrim(p_note), 1000))),
          'open', 'CF-247')
  returning id into v_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('notes', 'add', v_field, jsonb_build_object('course_id', p_course_id, 'flag_id', v_id), auth.uid());
  return jsonb_build_object('flag_id', v_id);
end $$;


