begin
 if auth.uid() is null and auth.role() <> 'service_role' then raise exception 'authentication required'; end if;
 select security.admin_course_decision_context(p_course_id) into v_ctx;
 return coalesce(v_ctx,jsonb_build_object('course_id',p_course_id,'qilt','[]'::jsonb,'prisms_provider','[]'::jsonb,'prisms_state','[]'::jsonb));
