CREATE OR REPLACE FUNCTION "public"."coursefinder_runtime_automation_key"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'vault'
    AS $$
declare v_integration text;v_secret_name text;v_value text;
begin
 select trim(both '"' from setting_value::text) into v_integration
 from pipeline.environment_settings
 where setting_key='runtime_automation_integration_key';

 select secret_name into v_secret_name
 from pipeline.integration_secret_registry
 where integration_key=v_integration;

 if v_secret_name is null then return null; end if;
 select decrypted_secret into v_value from vault.decrypted_secrets where name=v_secret_name limit 1;
 return v_value;
end $$;


