CREATE OR REPLACE FUNCTION "public"."important_date_upsert"("p_id" "uuid", "p_country_code" "text", "p_event_type" "text", "p_title" "text", "p_source_url" "text", "p_evidence_id" "uuid", "p_scope_type" "text", "p_source_profile_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_date_precision" "text", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text", "p_source_wording" "text", "p_warning_days" integer, "p_expires_at" timestamp with time zone, "p_refresh_layer" smallint) RETURNS "uuid"
    LANGUAGE "sql"
