CREATE OR REPLACE FUNCTION "public"."layer2_completeness_trial_create"("p_country_code" "text", "p_provider_id" "uuid", "p_batch_size" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pipeline', 'catalogue', 'ref'
    AS $$
declare
 v_country uuid; v_profile uuid; v_trial uuid; v_batch integer:=greatest(1,least(coalesce(p_batch_size,10),100)); v_controls integer;
begin
 if auth.role() <> 'service_role' then raise exception 'service_role required'; end if;
 select id into v_country from ref.countries where trim(iso_alpha2)=upper(trim(p_country_code)) limit 1;
 if v_country is null then raise exception 'country not found'; end if;
 if not exists(select 1 from catalogue.providers p where p.id=p_provider_id and p.country_id=v_country) then raise exception 'provider not in requested country'; end if;
 select id into v_profile from pipeline.layer2_country_completeness_profiles where country_id=v_country and active order by version_no desc limit 1;
 if v_profile is null then raise exception 'no active completeness profile'; end if;
 v_controls := case when v_batch>=10 then 2 when v_batch>=5 then 1 else 0 end;
 insert into pipeline.layer2_completeness_trials(country_id,completeness_profile_id,provider_id,requested_batch_size,status,started_at)
 values(v_country,v_profile,p_provider_id,v_batch,'running',now()) returning id into v_trial;
 with scored as (
   select c.id,c.provider_id,c.stable_key,
     ((pipeline.layer2_course_factual_snapshot(c.id)->>'course_url' <> 'present')::int +
      (pipeline.layer2_course_factual_snapshot(c.id)->>'provider_current_tuition' <> 'present')::int +
      (pipeline.layer2_course_factual_snapshot(c.id)->>'intakes' <> 'present')::int +
      (pipeline.layer2_course_factual_snapshot(c.id)->>'english_requirements' <> 'present')::int +
      (pipeline.layer2_course_factual_snapshot(c.id)->>'description' <> 'present')::int) miss
   from catalogue.courses c where c.provider_id=p_provider_id
 ), controls as (
   select *,'control_known_coverage'::text reason from scored order by miss asc,stable_key limit v_controls
 ), gaps as (
   select s.*,'gap_learning_sample'::text reason from scored s where not exists(select 1 from controls x where x.id=s.id) order by miss desc,stable_key limit greatest(0,v_batch-v_controls)
 ), chosen as (
   select * from controls union all select * from gaps
 ), ranked as (
   select *,row_number() over(order by case reason when 'control_known_coverage' then 0 else 1 end, miss asc, stable_key) sample_rank from chosen
 )
 insert into pipeline.layer2_completeness_trial_courses(trial_id,course_id,provider_id,sample_rank,selection_reason,baseline_factual,baseline_context)
 select v_trial,id,provider_id,sample_rank,reason,pipeline.layer2_course_factual_snapshot(id),pipeline.layer2_course_decision_context_snapshot(id) from ranked order by sample_rank;
 update pipeline.layer2_completeness_trials t set baseline_summary=(select jsonb_build_object('selected_courses',count(*),'batch_size',v_batch,'control_courses',count(*) filter(where selection_reason='control_known_coverage'),'gap_courses',count(*) filter(where selection_reason='gap_learning_sample')) from pipeline.layer2_completeness_trial_courses tc where tc.trial_id=v_trial) where t.id=v_trial;
 return jsonb_build_object('trial_id',v_trial,'country_code',upper(trim(p_country_code)),'provider_id',p_provider_id,'selected_courses',(select count(*) from pipeline.layer2_completeness_trial_courses where trial_id=v_trial),'sampling','controls_plus_gap_learning');
end$$;


ALTER FUNCTION "public"."layer2_completeness_trial_create"("p_country_code" "text", "p_provider_id" "uuid", "p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_completeness_trial_finalize"("p_trial_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pipeline'
    AS $$
declare v_summary jsonb; v_result jsonb;
begin
 if auth.role()<>'service_role' then raise exception 'service_role required'; end if;
 select pipeline.layer2_provider_trial_summary(p_trial_id) into v_summary;
 select jsonb_build_object(
   'course_count',count(*),
   'resolved',count(*) filter(where status='resolved'),
   'layer3_required',count(*) filter(where status='layer3_required'),
   'layer4_required',count(*) filter(where status='layer4_required'),
   'blocked',count(*) filter(where status='blocked'),
   'provider_summary',v_summary
 ) into v_result from pipeline.layer2_completeness_trial_courses where trial_id=p_trial_id;
 update pipeline.layer2_completeness_trials set status=case when exists(select 1 from pipeline.layer2_completeness_trial_courses where trial_id=p_trial_id and status in ('selected','acquiring')) then 'blocked' else 'completed' end,result_summary=v_result,completed_at=now() where id=p_trial_id;
 return v_result;
end$$;


ALTER FUNCTION "public"."layer2_completeness_trial_finalize"("p_trial_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_config_control"("p_actor" "uuid", "p_action" "text", "p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline'
    AS $$
declare
  v_rank integer:=0;
  v_version pipeline.layer2_source_profile_versions%rowtype;
  v_validation jsonb;
begin
  if p_actor is null then raise exception 'actor required' using errcode='42501'; end if;
  select coalesce(max(r.rank),0) into v_rank from security.user_roles ur join security.roles r on r.code=ur.role_code where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
  if v_rank < 6 then raise exception 'platform_admin role required' using errcode='42501'; end if;
  if p_action='validate' then
    select v.* into v_version from pipeline.layer2_source_profiles p join pipeline.layer2_source_profile_versions v on v.id=p.current_version_id where p.id=p_profile_id for update of v;
    if v_version.id is null then raise exception 'profile/current version not found' using errcode='22023'; end if;
    v_validation:=security.layer2_validate_profile_config(v_version.configuration);
    update pipeline.layer2_source_profile_versions set validation_result=v_validation, validation_status=case when (v_validation->>'valid')::boolean then 'valid' else 'invalid' end where id=v_version.id;
  elsif p_action='pause' then update pipeline.layer2_source_profiles set paused=true,updated_at=now() where id=p_profile_id;
  elsif p_action='resume' then update pipeline.layer2_source_profiles set paused=false,updated_at=now() where id=p_profile_id;
  elsif p_action='disable' then update pipeline.layer2_source_profiles set enabled=false,paused=true,updated_at=now() where id=p_profile_id;
  elsif p_action='enable' then update pipeline.layer2_source_profiles set enabled=true,paused=false,updated_at=now() where id=p_profile_id;
  else raise exception 'unsupported action' using errcode='22023';
  end if;
  if not found and p_action<>'validate' then raise exception 'profile not found' using errcode='22023'; end if;
  return jsonb_build_object('ok',true,'profile_id',p_profile_id,'action',p_action,'validation',v_validation);
end
$$;


ALTER FUNCTION "public"."layer2_config_control"("p_actor" "uuid", "p_action" "text", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_course_candidate_record"("p_source_id" "uuid", "p_source_record_id" "text", "p_source_url" "text", "p_course_cricos" "text", "p_content_hash" "text", "p_evidence_id" "uuid", "p_payload" "jsonb", "p_status" "text", "p_error" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare v_id uuid;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 insert into pipeline.course_fact_source_records(source_id,source_record_id,source_url,provider_cricos,course_cricos,content_hash,evidence_id,parsed_payload,status,observed_at,error_text)
 values(p_source_id,p_source_record_id,p_source_url,null,p_course_cricos,p_content_hash,p_evidence_id,p_payload,p_status,now(),p_error)
 on conflict do nothing returning id into v_id;
 if v_id is null then select id into v_id from pipeline.course_fact_source_records where source_id=p_source_id and source_record_id=p_source_record_id order by observed_at desc limit 1; end if;
 return v_id;
end $$;


