CREATE OR REPLACE FUNCTION "public"."layer2_create_profile_version"("p_actor" "uuid", "p_profile_id" "uuid", "p_configuration" "jsonb", "p_change_control_ref" "text", "p_uat_ref" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'extensions'
    AS $$
declare
  v_rank integer:=0;
  v_profile pipeline.layer2_source_profiles%rowtype;
  v_validation jsonb;
  v_hash text;
  v_next integer;
  v_id uuid;
  v_old uuid;
begin
  if p_actor is null then raise exception 'actor required' using errcode='42501'; end if;
  select coalesce(max(r.rank),0) into v_rank
  from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
  if v_rank < 5 then raise exception 'pim_admin role required' using errcode='42501'; end if;
  if p_configuration is null or jsonb_typeof(p_configuration)<>'object' then raise exception 'configuration object required' using errcode='22023'; end if;
  if coalesce(nullif(trim(p_change_control_ref),''),'')='' then raise exception 'change_control_ref required' using errcode='22023'; end if;

  select * into v_profile from pipeline.layer2_source_profiles where id=p_profile_id for update;
  if not found then raise exception 'profile not found' using errcode='22023'; end if;
  if coalesce(p_configuration->>'acquisition_method','')<>v_profile.acquisition_method then raise exception 'acquisition_method must match stable profile; create a new profile for method changes' using errcode='22023'; end if;
  if coalesce(p_configuration->>'target_entity_type','')<>v_profile.target_entity_type then raise exception 'target_entity_type must match stable profile; create a new profile for target changes' using errcode='22023'; end if;

  v_validation:=security.layer2_validate_profile_config(p_configuration);
  if not coalesce((v_validation->>'valid')::boolean,false) then
    raise exception 'configuration validation failed: %',coalesce(v_validation->'errors','[]'::jsonb)::text using errcode='22023';
  end if;

  v_hash:=encode(extensions.digest(p_configuration::text,'sha256'),'hex');
  select coalesce(max(version_no),0)+1 into v_next from pipeline.layer2_source_profile_versions where profile_id=p_profile_id;
  v_old:=v_profile.current_version_id;

  insert into pipeline.layer2_source_profile_versions(profile_id,version_no,configuration,configuration_hash,validation_status,validation_result,change_control_ref,uat_ref,created_by)
  values(p_profile_id,v_next,p_configuration,v_hash,'valid',v_validation,trim(p_change_control_ref),nullif(trim(coalesce(p_uat_ref,'')),''),p_actor)
  returning id into v_id;

  if v_old is not null then
    update pipeline.layer2_source_profile_versions set validation_status='superseded' where id=v_old and validation_status='valid';
  end if;

  update pipeline.layer2_source_profiles
  set current_version_id=v_id,
      freshness_sla_hours=case when p_configuration ? 'freshness_sla_hours' then nullif(p_configuration->>'freshness_sla_hours','')::integer else freshness_sla_hours end,
      schedule_text=coalesce(nullif(p_configuration->>'schedule',''),schedule_text),
      updated_at=now()
  where id=p_profile_id;

  return jsonb_build_object('ok',true,'profile_id',p_profile_id,'version_id',v_id,'version_no',v_next,'configuration_hash',v_hash,'validation',v_validation);
exception when unique_violation then
  raise exception 'configuration already exists for this profile' using errcode='23505';
end
$$;


ALTER FUNCTION "public"."layer2_create_profile_version"("p_actor" "uuid", "p_profile_id" "uuid", "p_configuration" "jsonb", "p_change_control_ref" "text", "p_uat_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_discovery_candidates_write"("p_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'public'
    AS $$
declare v_count integer:=0;
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  if p_rows is null or jsonb_typeof(p_rows)<>'array' then raise exception 'rows array required' using errcode='22023'; end if;
  if jsonb_array_length(p_rows)<1 or jsonb_array_length(p_rows)>20 then raise exception 'candidate row count must be 1..20' using errcode='22023'; end if;
  insert into pipeline.layer2_course_discovery_candidates(
    trial_course_id,course_id,source_profile_version_id,provider_attempt_id,evidence_id,
    discovered_url,discovered_title,discovered_regulatory_code,match_score,match_basis,status,selected,blocker
  )
  select x.trial_course_id,x.course_id,x.source_profile_version_id,x.provider_attempt_id,x.evidence_id,
         x.discovered_url,x.discovered_title,x.discovered_regulatory_code,x.match_score,
         coalesce(x.match_basis,'{}'::jsonb),x.status,coalesce(x.selected,false),x.blocker
  from jsonb_to_recordset(p_rows) as x(
    trial_course_id uuid,course_id uuid,source_profile_version_id uuid,provider_attempt_id uuid,evidence_id uuid,
    discovered_url text,discovered_title text,discovered_regulatory_code text,match_score numeric,
    match_basis jsonb,status text,selected boolean,blocker text
  );
  get diagnostics v_count=row_count;
  return v_count;
end
$$;


ALTER FUNCTION "public"."layer2_discovery_candidates_write"("p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_discovery_context"("p_profile_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'public'
    AS $$
declare v_ctx jsonb; v_provider uuid; v_direct uuid; v_courses jsonb;
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  select public.layer2_runtime_context(p_profile_id) into v_ctx;
  if v_ctx is null or v_ctx->>'domain'<>'course_facts' then raise exception 'course_facts profile required' using errcode='22023'; end if;
  select s.provider_id into v_provider from pipeline.sources s where s.id=(v_ctx->>'source_id')::uuid;
  if v_provider is null then raise exception 'profile source is not bound to a canonical provider' using errcode='22023'; end if;
  select id into v_direct from pipeline.layer2_acquisition_providers where provider_key='direct-http' and enabled=true;
  if v_direct is null then raise exception 'direct-http acquisition provider unavailable'; end if;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.canonical_title,x.id),'[]'::jsonb) into v_courses
  from (
    select c.id,c.canonical_title,c.display_title,c.course_code
    from catalogue.courses c
    where c.provider_id=v_provider
      and not exists(
        select 1
        from pipeline.layer2_course_discovery_candidates dc
        where dc.course_id=c.id
          and dc.source_profile_version_id=(v_ctx->>'version_id')::uuid
          and dc.status in ('exact_match','likely_match','ambiguous','identity_mismatch','current_page_not_found')
      )
    order by c.canonical_title,c.id
    limit least(greatest(coalesce(p_limit,10),1),50)
  ) x;
  return jsonb_build_object('runtime',v_ctx,'canonical_provider_id',v_provider,'direct_provider_id',v_direct,'courses',v_courses);
end $$;


ALTER FUNCTION "public"."layer2_discovery_context"("p_profile_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_discovery_context_scope"("p_profile_id" "uuid", "p_course_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'public', 'security'
    AS $$
declare v_ctx jsonb; v_provider uuid; v_courses jsonb; v_binding pipeline.scheduler_workflow_async_bindings%rowtype; v_bound boolean:=false; v_requested uuid[];
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 select public.layer2_runtime_context(p_profile_id) into v_ctx;
 if v_ctx is null or v_ctx->>'domain'<>'course_facts' then raise exception 'course_facts profile required' using errcode='22023'; end if;
 select s.provider_id into v_provider from pipeline.sources s where s.id=(v_ctx->>'source_id')::uuid;
 if v_provider is null then raise exception 'profile source is not bound to a canonical provider' using errcode='22023'; end if;
 select coalesce(array_agg(distinct x order by x),'{}'::uuid[]) into v_requested from unnest(coalesce(p_course_ids,'{}'::uuid[])) x;
 select * into v_binding from pipeline.scheduler_workflow_async_bindings b where b.profile_id=p_profile_id and b.status='active' and b.execution_expires_at>now() order by b.activated_at desc limit 1;
 v_bound:=found;
 if v_bound then
  if nullif(v_ctx->>'version_id','')::uuid<>v_binding.profile_version_id then raise exception 'scheduler bound profile version changed' using errcode='22023'; end if;
  if cardinality(v_requested)=0 then raise exception 'scheduler bound discovery requires explicit course_ids' using errcode='22023'; end if;
  if not (v_binding.discovery_course_ids @> v_requested) then raise exception 'discovery chunk is outside active scheduler binding' using errcode='22023'; end if;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.canonical_title,x.id),'[]'::jsonb) into v_courses from (
    select c.id,c.canonical_title,c.display_title,c.course_code from catalogue.courses c
    where c.provider_id=v_provider and c.id=any(v_requested)
      and not exists(select 1 from pipeline.layer2_course_discovery_candidates dc where dc.course_id=c.id and dc.source_profile_version_id=v_binding.profile_version_id and dc.selected=true and nullif(dc.discovered_url,'') is not null and dc.created_at>=v_binding.activated_at)
    order by c.canonical_title,c.id limit least(greatest(coalesce(p_limit,50),1),50)
  ) x;
  return jsonb_build_object('runtime',v_ctx,'canonical_provider_id',v_provider,'courses',v_courses,'scheduler_preview_token',v_binding.preview_token,'scheduler_bound_retry',true,'historical_dispositions_preserved',true);
 end if;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.canonical_title,x.id),'[]'::jsonb) into v_courses from (
  select c.id,c.canonical_title,c.display_title,c.course_code from catalogue.courses c
  where c.provider_id=v_provider and (p_course_ids is null or c.id=any(p_course_ids))
    and not exists(select 1 from pipeline.layer2_course_discovery_candidates dc where dc.course_id=c.id and dc.source_profile_version_id=(v_ctx->>'version_id')::uuid and dc.status in ('exact_match','likely_match','ambiguous','identity_mismatch','current_page_not_found'))
  order by c.canonical_title,c.id limit least(greatest(coalesce(p_limit,50),1),50)
 ) x;
 return jsonb_build_object('runtime',v_ctx,'canonical_provider_id',v_provider,'courses',v_courses);
end
$$;


ALTER FUNCTION "public"."layer2_discovery_context_scope"("p_profile_id" "uuid", "p_course_ids" "uuid"[], "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_evidence_capacity_status"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'storage'
    AS $$ with usage as (select count(*)::bigint objects, coalesce(sum((metadata->>'size')::bigint),0)::bigint bytes from storage.objects where bucket_id='evidence'), p as (select * from pipeline.evidence_capacity_policy where id=true), x as (select u.objects,u.bytes,p.planning_capacity_bytes,p.warn_pct,p.high_pct,p.critical_pct,p.capacity_basis, case when p.planning_capacity_bytes=0 then 0 else (u.bytes::numeric*100/p.planning_capacity_bytes) end pct from usage u cross join p) select jsonb_build_object('objects',objects,'bytes',bytes,'planning_capacity_bytes',planning_capacity_bytes,'used_pct',round(pct,2),'warn_pct',warn_pct,'high_pct',high_pct,'critical_pct',critical_pct,'state',case when pct>=critical_pct then 'critical' when pct>=high_pct then 'high' when pct>=warn_pct then 'warn' else 'normal' end,'capacity_basis',capacity_basis) from x; $$;


ALTER FUNCTION "public"."layer2_evidence_capacity_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_evidence_capture"("p_source_id" "uuid", "p_job_id" "uuid", "p_evidence_type" "text", "p_source_url" "text", "p_storage_path" "text", "p_content_hash" "text", "p_mime_type" "text", "p_profile_version_id" "uuid", "p_group_key" "text", "p_retention_class" "text", "p_retain_until" timestamp with time zone, "p_metadata" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $_$ declare prev pipeline.evidence_artifacts%rowtype; v_id uuid; v_cap integer; v_changed boolean; v_now timestamptz:=now(); v_path text:=p_storage_path; v_reused text; v_meta jsonb; begin if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; select * into prev from pipeline.evidence_artifacts where evidence_group_key=p_group_key order by capture_version desc limit 1 for update; if prev.id is not null and prev.content_hash is not distinct from p_content_hash then return jsonb_build_object('evidence_id',prev.id,'capture_version',prev.capture_version,'content_changed',false,'supersedes_evidence_id',prev.supersedes_evidence_id,'storage_path',prev.storage_path,'duplicate_upload_path',p_storage_path); end if;
 -- R26: reuse an identical stored file of the same provider source (screenshots and HTML snapshots).
 if p_evidence_type in ('layer2_screenshot','layer2_html_snapshot') and p_content_hash ~ '^[0-9a-f]{64}$' and p_source_id is not null then
   select e.storage_path into v_reused from pipeline.evidence_artifacts e
     join storage.objects o on o.bucket_id='evidence' and o.name=e.storage_path
    where e.source_id=p_source_id and e.content_hash=p_content_hash and e.evidence_type=p_evidence_type
      and e.storage_path is not null and e.storage_path<>p_storage_path
    order by e.created_at, e.storage_path limit 1;
   if v_reused is not null then v_path:=v_reused; end if;
 end if;
 v_cap:=coalesce(prev.capture_version,0)+1; v_changed:=true; if prev.id is not null then update pipeline.evidence_artifacts set valid_to=v_now where id=prev.id; end if;
 v_meta:=coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('content_changed',v_changed);
 if v_reused is not null then v_meta:=v_meta||jsonb_build_object('storage_reused_identical_file',true,'storage_upload_path',p_storage_path); end if;
 insert into pipeline.evidence_artifacts(source_id,job_id,evidence_type,source_url,storage_path,content_hash,mime_type,captured_at,valid_from,supersedes_evidence_id,source_profile_version_id,retention_class,retain_until,review_state,capture_version,evidence_group_key,metadata) values(p_source_id,p_job_id,p_evidence_type,p_source_url,v_path,p_content_hash,p_mime_type,v_now,v_now,prev.id,p_profile_version_id,coalesce(p_retention_class,'standard_365'),p_retain_until,'unreviewed',v_cap,p_group_key,v_meta) returning id into v_id;
 if v_reused is not null then
   insert into pipeline.evidence_storage_dedupe_log(path,keeper_path,content_hash,bytes,source_id,scope,repointed_rows)
   values(p_storage_path,v_reused,p_content_hash,null,p_source_id,'layer2_capture',1) on conflict (path) do nothing;
 end if;
 return jsonb_build_object('evidence_id',v_id,'capture_version',v_cap,'content_changed',v_changed,'supersedes_evidence_id',prev.id,'storage_path',v_path,'duplicate_upload_path',case when v_reused is not null then p_storage_path end,'storage_reused',v_reused is not null); end $_$;


ALTER FUNCTION "public"."layer2_evidence_capture"("p_source_id" "uuid", "p_job_id" "uuid", "p_evidence_type" "text", "p_source_url" "text", "p_storage_path" "text", "p_content_hash" "text", "p_mime_type" "text", "p_profile_version_id" "uuid", "p_group_key" "text", "p_retention_class" "text", "p_retain_until" timestamp with time zone, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_execution_policy_service"("p_actor" "uuid", "p_action" "text", "p_patch" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'security'
    AS $$
declare
 v_rank integer:=0;
 v_policy pipeline.layer2_execution_policy%rowtype;
 v_firecrawl pipeline.layer2_acquisition_providers%rowtype;
 v_budget jsonb:='{}'::jsonb;
begin
 if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 select coalesce(max(r.rank),0) into v_rank
 from security.user_roles ur join security.roles r on r.code=ur.role_code
 where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
 if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;

 if p_action='update' then
   if v_rank<5 then raise exception 'pim_admin role required' using errcode='42501'; end if;
   update pipeline.layer2_execution_policy p set
     qualification_provider_wave_size=least(greatest(coalesce(nullif(p_patch->>'qualification_provider_wave_size','')::integer,p.qualification_provider_wave_size),1),500),
     qualification_provider_wave_max=least(greatest(coalesce(nullif(p_patch->>'qualification_provider_wave_max','')::integer,p.qualification_provider_wave_max),1),500),
     qualification_sample_size=least(greatest(coalesce(nullif(p_patch->>'qualification_sample_size','')::integer,p.qualification_sample_size),1),50),
     qualification_retry_hours=least(greatest(coalesce(nullif(p_patch->>'qualification_retry_hours','')::integer,p.qualification_retry_hours),1),2160),
     qualification_finalizer_run_limit=least(greatest(coalesce(nullif(p_patch->>'qualification_finalizer_run_limit','')::integer,p.qualification_finalizer_run_limit),1),10),
     qualification_pattern_provider_limit=least(greatest(coalesce(nullif(p_patch->>'qualification_pattern_provider_limit','')::integer,p.qualification_pattern_provider_limit),1),5),
     production_target_wave_size=least(greatest(coalesce(nullif(p_patch->>'production_target_wave_size','')::integer,p.production_target_wave_size),1),5000),
     production_max_wave_size=least(greatest(coalesce(nullif(p_patch->>'production_max_wave_size','')::integer,p.production_max_wave_size),1),5000),
     schedule_remaining=coalesce((p_patch->>'schedule_remaining')::boolean,p.schedule_remaining),
     route_mode=case when p_patch->>'route_mode' in('scraper_first','managed') then p_patch->>'route_mode' else p.route_mode end,
     updated_by=p_actor,updated_at=now(),change_control_ref='CF-CHG-20260830-048'
   where p.policy_key='default';
 end if;

 select * into v_policy from pipeline.layer2_execution_policy where policy_key='default';
 select * into v_firecrawl from pipeline.layer2_acquisition_providers where provider_key='firecrawl' limit 1;
 if v_firecrawl.id is not null then
   v_budget:=security.layer2_provider_budget_status(
     v_firecrawl.id,
     coalesce(nullif(v_firecrawl.request_template->>'fixed_credit_units','')::numeric,1)
   );
 end if;

 return jsonb_build_object(
  'policy',to_jsonb(v_policy)-'updated_by',
  'firecrawl',jsonb_build_object(
    'provider_id',v_firecrawl.id,'provider_key',v_firecrawl.provider_key,'display_name',v_firecrawl.display_name,
    'enabled',v_firecrawl.enabled,'credential_configured',v_firecrawl.vault_secret_id is not null,
    'rate_limit_per_minute',v_firecrawl.rate_limit_per_minute,'concurrency',v_firecrawl.concurrency,
    'timeout_seconds',v_firecrawl.timeout_seconds,'billing_config',v_firecrawl.billing_config,
    'budget_status',v_budget
  ),
  'qualification_note','Course samples are identity checks against one acquired Provider seed page; they are not separate production scrapes.',
  'finalizer_note','Deterministic 3-of-3 source-pattern controls are finalised in policy-bounded background slices; unresolved outcomes are queued to governed Layer 3 or Layer 4 without autonomous Layer 3 AI execution.',
  'production_note','Production Course waves are queued in the background and clamped by the Firecrawl entitlement/reserve.'
 );
end
$$;


ALTER FUNCTION "public"."layer2_execution_policy_service"("p_actor" "uuid", "p_action" "text", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_extraction_context"("p_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare a pipeline.layer2_provider_attempts%rowtype; p pipeline.layer2_acquisition_providers%rowtype; e pipeline.evidence_artifacts%rowtype; v_eid uuid;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 select * into a from pipeline.layer2_provider_attempts where id=p_attempt_id;
 if not found then return null; end if;
 select * into p from pipeline.layer2_acquisition_providers where id=a.acquisition_provider_id;
 v_eid:=coalesce(a.raw_evidence_id,a.html_evidence_id,a.screenshot_evidence_id);
 if v_eid is null then return jsonb_build_object('attempt_id',a.id,'no_evidence',true); end if;
 select * into e from pipeline.evidence_artifacts where id=v_eid;
 return jsonb_build_object(
  'attempt_id',a.id,'job_id',a.job_id,'profile_version_id',a.profile_version_id,'provider_id',a.acquisition_provider_id,'provider_key',p.provider_key,'request_template',p.request_template,
  'raw_evidence_id',a.raw_evidence_id,'html_evidence_id',a.html_evidence_id,'screenshot_evidence_id',a.screenshot_evidence_id,
  'evidence_id',e.id,'source_id',e.source_id,'storage_path',e.storage_path,'mime_type',e.mime_type,'source_url',e.source_url,'source_profile_version_id',e.source_profile_version_id,'content_hash',e.content_hash,'retention_class',e.retention_class,'retain_until',e.retain_until
 );
end $$;


ALTER FUNCTION "public"."layer2_extraction_context"("p_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_hotcourses_directory_apply"("p_evidence_id" "uuid", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'ref', 'ranking', 'public'
    AS $$
declare
 v_source uuid;
 v_country text;
 v_row jsonb;
 v_provider uuid;
 v_inserted integer:=0;
 v_matched integer:=0;
 v_candidates integer:=0;
 v_dir_id text;
 v_norm text;
begin
 select e.source_id,c.iso_alpha2 into v_source,v_country
 from pipeline.evidence_artifacts e
 join pipeline.sources s on s.id=e.source_id
 left join ref.countries c on c.id=s.country_id
 where e.id=p_evidence_id
   and s.source_type='third_party_directory'
   and s.metadata->>'directory'='hotcourses_abroad';
 if v_source is null then raise exception 'hotcourses_directory_evidence_required' using errcode='22023'; end if;
 if jsonb_typeof(coalesce(p_rows,'[]'::jsonb))<>'array' then raise exception 'rows must be array' using errcode='22023'; end if;

 for v_row in select value from jsonb_array_elements(coalesce(p_rows,'[]'::jsonb))
 loop
   v_provider:=null;
   v_norm:=regexp_replace(regexp_replace(lower(coalesce(v_row->>'name','')),'^the\s+','','g'),'[^a-z0-9]+','','g');

   -- 1. Exact canonical/display match inside the same country after harmless leading-The normalisation.
   select p.id into v_provider
   from catalogue.providers p
   join ref.countries c on c.id=p.country_id
   where c.iso_alpha2=v_country
     and coalesce(p.lifecycle_status,'active')='active'
     and regexp_replace(regexp_replace(lower(coalesce(p.display_name,p.canonical_name,'')),'^the\s+','','g'),'[^a-z0-9]+','','g')=v_norm
   order by p.id limit 1;

   -- 2. Exact governed alias match, still constrained to the same country.
   if v_provider is null then
     select p.id into v_provider
     from catalogue.provider_aliases a
     join catalogue.providers p on p.id=a.provider_id
     join ref.countries c on c.id=p.country_id
     where c.iso_alpha2=v_country
       and coalesce(p.lifecycle_status,'active')='active'
       and regexp_replace(regexp_replace(lower(a.alias),'^the\s+','','g'),'[^a-z0-9]+','','g')=v_norm
     order by p.id limit 1;
   end if;

   v_dir_id:=coalesce(v_row->>'directory_id',
     substring(coalesce(v_row->>'institution_url','') from '/([0-9]+)/international(?:\.html)?'));

   insert into pipeline.provider_directory_observations(
     source_id,evidence_id,directory_name,directory_id,observed_name,country_code,
     institution_url,logo_url,matched_provider_id,match_method,match_confidence,metadata
   ) values(
     v_source,p_evidence_id,'hotcourses_abroad',nullif(v_dir_id,''),
     v_row->>'name',v_country,nullif(v_row->>'institution_url',''),nullif(v_row->>'logo_url',''),
     v_provider,
     case when v_provider is not null then 'country_exact_name_or_governed_alias' else 'unmatched' end,
     case when v_provider is not null then 1.0 else null end,
     jsonb_build_object(
       'parser_version','hotcourses-directory-v1.1',
       'change_control_ref','CF-CHG-20260904-102',
       'canonical_identity_mutation',false,
       'logo_candidate_policy','review_only_if_primary_missing'
     )
   )
   on conflict(source_id,evidence_id,observed_name,institution_url) do update set
     directory_id=excluded.directory_id,logo_url=excluded.logo_url,matched_provider_id=excluded.matched_provider_id,
     match_method=excluded.match_method,match_confidence=excluded.match_confidence,metadata=excluded.metadata,observed_at=now();

   v_inserted:=v_inserted+1;
   if v_provider is not null then
     v_matched:=v_matched+1;

     insert into pipeline.sources(source_type,provider_id,country_id,url,label,trust_rank,status,metadata)
     select 'third_party_directory',v_provider,p.country_id,nullif(v_row->>'institution_url',''),
       coalesce(p.display_name,p.canonical_name)||' — Hotcourses Abroad reconciliation',30,'active',
       jsonb_build_object(
         'directory','hotcourses_abroad','directory_id',nullif(v_dir_id,''),
         'purpose','provider_logo_discovery_and_reconciliation_only',
         'canonical_asset_authority',false,'operator_fallback_reuse_approved',true,
         'rights_owner_basis','university_provider_mark',
         'source_host_role','aggregator_transport_copy',
         'change_control_ref','CF-CHG-20260904-102'
       )
     from catalogue.providers p where p.id=v_provider
     on conflict do nothing;

     -- Feed the existing Provider Asset workflow only for ranked AU/NZ university Providers
     -- that do not already have an approved primary logo. Never replace an approved primary.
     if nullif(v_row->>'logo_url','') is not null
        and exists(
          select 1 from (
            select provider_id from ranking.observations where provider_id=v_provider
            union all
            select provider_id from ranking.observation_provider_links where provider_id=v_provider
          ) z
        )
        and not exists(
          select 1 from catalogue.provider_assets a
          where a.provider_id=v_provider and a.is_primary and a.status='approved'
            and a.asset_type in('logo','logo_light','logo_dark')
        )
     then
       insert into pipeline.provider_asset_candidates(
         provider_id,profile_id,source_url,asset_url,asset_type,evidence_id,
         confidence,status,metadata
       )
       select v_provider,
         (select sp.id from pipeline.layer2_source_profiles sp
          join pipeline.sources s on s.id=sp.source_id
          where s.provider_id=v_provider and sp.domain='provider_asset'
          order by sp.updated_at desc limit 1),
         nullif(v_row->>'institution_url',''),v_row->>'logo_url','logo',p_evidence_id,
         0.85,'needs_review',
         jsonb_build_object(
           'mapping_method','hotcourses_country_directory_exact_provider_match',
           'directory_id',nullif(v_dir_id,''),
           'rights_owner_basis','university_provider_mark',
           'source_host_role','aggregator_transport_copy',
           'operator_fallback_reuse_approved',true,
           'candidate_policy','review_before_promotion',
           'change_control_ref','CF-CHG-20260904-102',
           'canonical_mutation_authorised',false
         )
       on conflict(provider_id,asset_url) do update set
         source_url=excluded.source_url,evidence_id=excluded.evidence_id,
         confidence=excluded.confidence,status=case
           when pipeline.provider_asset_candidates.status='accepted' then 'accepted'
           else 'needs_review' end,
         metadata=coalesce(pipeline.provider_asset_candidates.metadata,'{}'::jsonb)||excluded.metadata,
         discovered_at=now();
       v_candidates:=v_candidates+1;
     end if;
   end if;
 end loop;

 return jsonb_build_object(
   'evidence_id',p_evidence_id,'country_code',v_country,
   'rows',v_inserted,'matched',v_matched,'unmatched',v_inserted-v_matched,
   'provider_asset_review_candidates',v_candidates
 );
end $$;


ALTER FUNCTION "public"."layer2_hotcourses_directory_apply"("p_evidence_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_mark_extraction_blocked"("p_attempt_id" "uuid", "p_blocker" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'public'
    AS $$
declare v_job uuid;begin
 update pipeline.layer2_provider_attempts
 set status='extraction_failed',extraction_status='blocked',blocker=coalesce(nullif(trim(p_blocker),''),'extraction failed'),completed_at=coalesce(completed_at,now())
 where id=p_attempt_id returning job_id into v_job;
 if v_job is null then raise exception 'attempt not found' using errcode='22023';end if;
 return jsonb_build_object('ok',true,'job_id',v_job,'attempt_id',p_attempt_id);
end$$;


