CREATE OR REPLACE FUNCTION "public"."layer2_ops_policy_update"("p_actor" "uuid", "p_profile_id" "uuid", "p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline'
    AS $$
declare v_rank integer:=0;v_row pipeline.layer2_execution_policies%rowtype;v_before jsonb;v_after jsonb;v_reason text:=nullif(btrim(coalesce(p_patch->>'_governance_reason','')),'');v_changed text[];
begin
 if p_actor is null or p_actor<>auth.uid() then raise exception 'actor mismatch' using errcode='42501'; end if;
 select coalesce(max(r.rank),0) into v_rank from security.user_roles ur join security.roles r on r.code=ur.role_code where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
 if v_rank<5 then raise exception 'pim_admin role required' using errcode='42501'; end if;
 if v_reason is null or length(v_reason)<5 then raise exception 'governance reason required' using errcode='22023'; end if;
 if not exists(select 1 from pipeline.layer2_source_profiles where id=p_profile_id and domain in ('course_facts','scholarship')) then raise exception 'layer2 enrichment profile required' using errcode='22023'; end if;
 insert into pipeline.layer2_execution_policies(profile_id) values(p_profile_id) on conflict(profile_id) do nothing;
 select to_jsonb(ep)-'updated_by' into v_before from pipeline.layer2_execution_policies ep where ep.profile_id=p_profile_id for update;
 update pipeline.layer2_execution_policies set schedule_mode=coalesce(nullif(p_patch->>'schedule_mode',''),schedule_mode),scheduled_hour_utc=case when p_patch ? 'scheduled_hour_utc' then nullif(p_patch->>'scheduled_hour_utc','')::smallint else scheduled_hour_utc end,batch_size=case when p_patch ? 'batch_size' then (p_patch->>'batch_size')::integer else batch_size end,routing_strategy=coalesce(nullif(p_patch->>'routing_strategy',''),routing_strategy),max_paid_attempts_per_entity=case when p_patch ? 'max_paid_attempts_per_entity' then (p_patch->>'max_paid_attempts_per_entity')::smallint else max_paid_attempts_per_entity end,max_vendor_units_per_entity=case when p_patch ? 'max_vendor_units_per_entity' then nullif(p_patch->>'max_vendor_units_per_entity','')::numeric else max_vendor_units_per_entity end,max_cost_usd_per_entity=case when p_patch ? 'max_cost_usd_per_entity' then nullif(p_patch->>'max_cost_usd_per_entity','')::numeric else max_cost_usd_per_entity end,max_concurrency=case when p_patch ? 'max_concurrency' then (p_patch->>'max_concurrency')::smallint else max_concurrency end,stale_after_minutes=case when p_patch ? 'stale_after_minutes' then (p_patch->>'stale_after_minutes')::integer else stale_after_minutes end,auto_handoff_layer3=case when p_patch ? 'auto_handoff_layer3' then (p_patch->>'auto_handoff_layer3')::boolean else auto_handoff_layer3 end,stop_on_identity_mismatch=case when p_patch ? 'stop_on_identity_mismatch' then (p_patch->>'stop_on_identity_mismatch')::boolean else stop_on_identity_mismatch end,updated_by=p_actor,updated_at=now() where profile_id=p_profile_id returning * into v_row;
 v_after:=to_jsonb(v_row)-'updated_by';
 select coalesce(array_agg(k order by k),'{}'::text[]) into v_changed from jsonb_object_keys(v_after) k where k not in ('updated_at','created_at') and v_before->k is distinct from v_after->k;
 insert into pipeline.layer2_tuning_events(profile_id,actor_id,governance_reason,changed_fields,before_policy,after_policy) values(p_profile_id,p_actor,v_reason,v_changed,v_before,v_after);
 return jsonb_build_object('ok',true,'policy',v_after,'changed_fields',v_changed,'audit_recorded',true);
end $$;


ALTER FUNCTION "public"."layer2_ops_policy_update"("p_actor" "uuid", "p_profile_id" "uuid", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_prepare_job"("p_actor" "uuid", "p_profile_id" "uuid", "p_job_type" "text" DEFAULT 'layer2_acquisition'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline'
    AS $$
declare
  v_rank integer:=0;
  v_source_id uuid;
  v_provider_id uuid;
  v_domain text;
  v_version_id uuid;
  v_job_id uuid;
begin
  if p_actor is null then raise exception 'actor required' using errcode='42501'; end if;
  select coalesce(max(r.rank),0) into v_rank from security.user_roles ur join security.roles r on r.code=ur.role_code where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
  if v_rank < 4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
  v_version_id:=security.layer2_assert_profile_executable(p_profile_id);
  select p.source_id,s.provider_id,p.domain into v_source_id,v_provider_id,v_domain from pipeline.layer2_source_profiles p join pipeline.sources s on s.id=p.source_id where p.id=p_profile_id;
  insert into pipeline.jobs(job_type,domain,source_id,provider_id,status,requested_by,payload,source_profile_version_id)
  values(coalesce(nullif(p_job_type,''),'layer2_acquisition'),v_domain,v_source_id,v_provider_id,'queued',p_actor,jsonb_build_object('layer','2','profile_id',p_profile_id,'configuration_version_id',v_version_id,'canonical_mutation_authorised',false),v_version_id)
  returning id into v_job_id;
  return jsonb_build_object('job_id',v_job_id,'source_id',v_source_id,'source_profile_version_id',v_version_id,'status','queued');
end
$$;


ALTER FUNCTION "public"."layer2_prepare_job"("p_actor" "uuid", "p_profile_id" "uuid", "p_job_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_provider_asset_fetch_routes"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',p.id,
    'provider_key',p.provider_key,
    'priority',p.priority
  ) order by p.priority,p.provider_key),'[]'::jsonb)
  from pipeline.layer2_acquisition_providers p
  where p.enabled
    and p.provider_key in ('scrape-do','scraperapi','zenrows')
$$;


