CREATE OR REPLACE FUNCTION "public"."layer2_provider_attempt_finish"("p_attempt_id" "uuid", "p_status" "text", "p_http_status" integer, "p_mime" "text", "p_raw_evidence" "uuid", "p_html_evidence" "uuid", "p_screenshot_evidence" "uuid", "p_extraction_status" "text", "p_blocker" "text", "p_metrics" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'public'
    AS $$begin
 if p_status not in ('succeeded','failed','blocked','extraction_failed') then raise exception 'invalid attempt status' using errcode='22023';end if;
 update pipeline.layer2_provider_attempts set status=p_status,response_http_status=p_http_status,response_mime_type=p_mime,raw_evidence_id=p_raw_evidence,html_evidence_id=p_html_evidence,screenshot_evidence_id=p_screenshot_evidence,extraction_status=p_extraction_status,blocker=p_blocker,metrics=coalesce(p_metrics,'{}'::jsonb),completed_at=now() where id=p_attempt_id;
end$$;


ALTER FUNCTION "public"."layer2_provider_attempt_finish"("p_attempt_id" "uuid", "p_status" "text", "p_http_status" integer, "p_mime" "text", "p_raw_evidence" "uuid", "p_html_evidence" "uuid", "p_screenshot_evidence" "uuid", "p_extraction_status" "text", "p_blocker" "text", "p_metrics" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_provider_control"("p_actor" "uuid", "p_action" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'vault'
    AS $$declare v_rank int:=0;v_id uuid;v_secret_id uuid;v_profile uuid;v_provider uuid;begin
 select coalesce(max(r.rank),0) into v_rank from security.user_roles ur join security.roles r on r.code=ur.role_code where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
 if p_action in ('create_provider','update_provider','set_secret') and v_rank<6 then raise exception 'platform_admin role required' using errcode='42501'; end if;
 if p_action='upsert_route' and v_rank<5 then raise exception 'pim_admin role required' using errcode='42501'; end if;
 if p_action in ('create_provider','update_provider') and (security.layer2_provider_has_secret_keys(p_payload->'capabilities') or security.layer2_provider_has_secret_keys(p_payload->'request_template') or security.layer2_provider_has_secret_keys(p_payload->'billing_config')) then raise exception 'provider configuration contains secret-like keys; use credential control' using errcode='22023';end if;
 if p_action='upsert_route' and (security.layer2_provider_has_secret_keys(p_payload->'request_overrides') or security.layer2_provider_has_secret_keys(p_payload->'required_capabilities')) then raise exception 'route configuration contains secret-like keys' using errcode='22023';end if;
 if p_action='create_provider' then
   if coalesce(trim(p_payload->>'provider_key'),'')='' or coalesce(trim(p_payload->>'display_name'),'')='' then raise exception 'provider key and display name required' using errcode='22023';end if;
   insert into pipeline.layer2_acquisition_providers(provider_key,display_name,adapter_type,base_url,auth_scheme,auth_field_name,capabilities,request_template,billing_config,enabled,priority,rate_limit_per_minute,concurrency,timeout_seconds,operational_owner,change_control_ref)
   values(trim(p_payload->>'provider_key'),trim(p_payload->>'display_name'),p_payload->>'adapter_type',nullif(trim(p_payload->>'base_url'),''),coalesce(nullif(p_payload->>'auth_scheme',''),'none'),nullif(trim(p_payload->>'auth_field_name'),''),coalesce(p_payload->'capabilities','{}'::jsonb),coalesce(p_payload->'request_template','{}'::jsonb),coalesce(p_payload->'billing_config','{}'::jsonb),coalesce((p_payload->>'enabled')::boolean,true),coalesce((p_payload->>'priority')::int,100),nullif(p_payload->>'rate_limit_per_minute','')::int,coalesce((p_payload->>'concurrency')::int,1),coalesce((p_payload->>'timeout_seconds')::int,30),nullif(trim(p_payload->>'operational_owner'),''),coalesce(nullif(trim(p_payload->>'change_control_ref'),''),'CF-CHG-20260823-029')) returning id into v_id; return jsonb_build_object('ok',true,'id',v_id);
 elsif p_action='update_provider' then
   v_id:=(p_payload->>'id')::uuid; update pipeline.layer2_acquisition_providers set display_name=coalesce(nullif(trim(p_payload->>'display_name'),''),display_name),base_url=case when p_payload?'base_url' then nullif(trim(p_payload->>'base_url'),'') else base_url end,auth_scheme=coalesce(nullif(p_payload->>'auth_scheme',''),auth_scheme),auth_field_name=case when p_payload?'auth_field_name' then nullif(trim(p_payload->>'auth_field_name'),'') else auth_field_name end,capabilities=coalesce(p_payload->'capabilities',capabilities),request_template=coalesce(p_payload->'request_template',request_template),billing_config=coalesce(p_payload->'billing_config',billing_config),enabled=coalesce((p_payload->>'enabled')::boolean,enabled),priority=coalesce((p_payload->>'priority')::int,priority),rate_limit_per_minute=case when p_payload?'rate_limit_per_minute' then nullif(p_payload->>'rate_limit_per_minute','')::int else rate_limit_per_minute end,concurrency=coalesce((p_payload->>'concurrency')::int,concurrency),timeout_seconds=coalesce((p_payload->>'timeout_seconds')::int,timeout_seconds),operational_owner=case when p_payload?'operational_owner' then nullif(trim(p_payload->>'operational_owner'),'') else operational_owner end,updated_at=now() where id=v_id; if not found then raise exception 'provider not found' using errcode='22023';end if;return jsonb_build_object('ok',true,'id',v_id);
 elsif p_action='set_secret' then
   v_id:=(p_payload->>'id')::uuid;if coalesce(p_payload->>'secret','')='' then raise exception 'secret required' using errcode='22023';end if;select vault_secret_id into v_secret_id from pipeline.layer2_acquisition_providers where id=v_id for update;if not found then raise exception 'provider not found' using errcode='22023';end if;if v_secret_id is null then select vault.create_secret(p_payload->>'secret','coursefinder_l2_provider_'||v_id::text,'CourseFinder Layer 2 provider credential',null) into v_secret_id;update pipeline.layer2_acquisition_providers set vault_secret_id=v_secret_id,updated_at=now() where id=v_id;else perform vault.update_secret(v_secret_id,p_payload->>'secret',null,null,null);end if;return jsonb_build_object('ok',true,'id',v_id,'credential_configured',true);
 elsif p_action='upsert_route' then
   v_profile:=(p_payload->>'profile_id')::uuid;v_provider:=(p_payload->>'provider_id')::uuid;
   insert into pipeline.layer2_profile_provider_routes(profile_id,acquisition_provider_id,priority,enabled,required_capabilities,request_overrides,evidence_policy,fallback_on,change_control_ref) values(v_profile,v_provider,coalesce((p_payload->>'priority')::int,100),coalesce((p_payload->>'enabled')::boolean,true),coalesce(p_payload->'required_capabilities','{}'::jsonb),coalesce(p_payload->'request_overrides','{}'::jsonb),coalesce(p_payload->'evidence_policy','{"capture_raw":true,"capture_html":true,"capture_screenshot_on_failure":true}'::jsonb),coalesce(p_payload->'fallback_on','["blocked","timeout","403","429","5xx","extraction_failed"]'::jsonb),coalesce(nullif(trim(p_payload->>'change_control_ref'),''),'CF-CHG-20260823-029')) on conflict(profile_id,acquisition_provider_id) do update set priority=excluded.priority,enabled=excluded.enabled,required_capabilities=excluded.required_capabilities,request_overrides=excluded.request_overrides,evidence_policy=excluded.evidence_policy,fallback_on=excluded.fallback_on,updated_at=now();return jsonb_build_object('ok',true);
 end if;raise exception 'unsupported provider action' using errcode='22023';
end$$;


ALTER FUNCTION "public"."layer2_provider_control"("p_actor" "uuid", "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_provider_onboarding_queue_v1"("p_country" "text" DEFAULT 'AU'::"text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'public'
    AS $$
declare v jsonb; v_cc text := upper(coalesce(p_country,'AU'));
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank() < 3 then raise exception 'Curator role is required' using errcode='42501'; end if;
  with t as (
    select s.*, p.canonical_name, p.website from pipeline.layer2_onboarding_snapshot s join catalogue.providers p on p.id=s.provider_id
    where s.country_code=v_cc order by s.rank_no limit greatest(1,least(coalesce(p_limit,50),200))),
  e as (
    select t.*,
      exists(select 1 from pipeline.layer2_source_profiles sp join pipeline.sources so on so.id=sp.source_id where so.provider_id=t.provider_id and sp.authority_class='qualification_candidate' and sp.domain='course_facts' and sp.enabled and not sp.paused) has_candidate_profile,
      (select jsonb_object_agg(st,n) from (select qi.status st, count(*) n from pipeline.layer2_scale_qualification_items qi where qi.provider_id=t.provider_id group by 1) z) item_states,
      (select jsonb_build_object('status',a.status,'url',a.candidate_url,'score',a.score,'evidence_id',a.evidence_id,'at',a.created_at,'resolved_at',a.resolved_at,'reason',a.detail->>'reason','error',a.detail->>'error')
         from pipeline.layer2_auto_discovery_attempts a where a.provider_id=t.provider_id order by a.created_at desc limit 1) auto_latest,
      (select count(*) from pipeline.layer2_auto_discovery_attempts a where a.provider_id=t.provider_id and a.status in ('failed','error')) auto_failed,
      (select jsonb_build_object('url',x.catalogue_url,'at',x.created_at,'dry_run',x.dry_run,'origin',x.origin) from pipeline.layer2_provider_catalogue_submissions x where x.provider_id=t.provider_id order by x.created_at desc limit 1) last_submission
    from t)
  select jsonb_build_object('country',v_cc,
    'providers_waiting',(select count(*) from pipeline.layer2_onboarding_snapshot where country_code=v_cc),
    'courses_waiting',(select coalesce(sum(courses_waiting),0) from pipeline.layer2_onboarding_snapshot where country_code=v_cc),
    'computed_at',(select max(computed_at) from pipeline.layer2_onboarding_snapshot where country_code=v_cc),
    'items',coalesce((select jsonb_agg(jsonb_build_object('provider_id',provider_id,'provider',canonical_name,'website',website,'courses_waiting',courses_waiting,
        'state',case when (item_states ? 'profile_qualified') or auto_latest->>'status'='passed' then 'qualified'
                     when (item_states ? 'source_pattern_candidate') then 'identity_check_running'
                     when auto_latest->>'status'='needs_person' then 'needs_person'
                     when (item_states ? 'layer3_required') or (item_states ? 'layer4_required') then 'needs_catalogue_page'
                     when (item_states ? 'source_limited') then 'site_limited'
                     when item_states is null then 'not_yet_assessed' else 'in_progress' end,
        'ready_for_submission',has_candidate_profile and ((item_states ? 'layer3_required') or (item_states ? 'layer4_required')),
        'suggested_start',coalesce(regexp_replace(candidates->0->>'url','^http://','https://'),website),
        'candidates',(select coalesce(jsonb_agg(c),'[]'::jsonb) from (select c from jsonb_array_elements(candidates) c limit 3) cc),
        'auto_latest',auto_latest,'auto_failed',auto_failed,'last_submission',last_submission) order by rank_no) from e),'[]'::jsonb))
  into v;
  return v;
end $$;


ALTER FUNCTION "public"."layer2_provider_onboarding_queue_v1"("p_country" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_provider_probe_record_service"("p_provider_id" "uuid", "p_status" "text", "p_http_status" integer DEFAULT NULL::integer, "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  update pipeline.layer2_acquisition_providers
  set last_tested_at=now(),last_test_status=left(coalesce(nullif(p_status,''),'failed'),30),
      last_test_http_status=p_http_status,last_test_error=nullif(left(coalesce(p_error,''),1000),''),updated_at=now()
  where id=p_provider_id;
  if not found then raise exception 'provider not found' using errcode='22023'; end if;
end
$$;


ALTER FUNCTION "public"."layer2_provider_probe_record_service"("p_provider_id" "uuid", "p_status" "text", "p_http_status" integer, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_provider_profile_options_service"("p_actor" "uuid", "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'catalogue', 'ref'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(p_limit,10),1),10);
  v_offset integer:=greatest(coalesce(p_offset,0),0);
  v_query text:=nullif(trim(coalesce(p_query,'')),'');
  v_total bigint:=0;
  v_items jsonb:='[]'::jsonb;
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  select coalesce(max(r.rank),0) into v_rank
  from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;

  with base as (
    select p.id profile_id,p.profile_key,p.domain,p.target_entity_type,p.enabled,p.paused,
           s.label source_label,c.iso_alpha2 country_code,cp.canonical_name affected_provider_name,
           v.validation_status
    from pipeline.layer2_source_profiles p
    join pipeline.sources s on s.id=p.source_id
    left join ref.countries c on c.id=s.country_id
    left join catalogue.providers cp on cp.id=s.provider_id
    left join pipeline.layer2_source_profile_versions v on v.id=p.current_version_id
    where p.domain in ('course_facts','scholarship')
      and p.target_entity_type in ('course_fact','scholarship')
      and (
        v_query is null or
        p.profile_key ilike '%'||v_query||'%' or
        s.label ilike '%'||v_query||'%' or
        coalesce(cp.canonical_name,'') ilike '%'||v_query||'%' or
        coalesce(c.iso_alpha2,'') ilike '%'||v_query||'%'
      )
  )
  select count(*) into v_total from base;

  with base as (
    select p.id profile_id,p.profile_key,p.domain,p.target_entity_type,p.enabled,p.paused,
           s.label source_label,c.iso_alpha2 country_code,cp.canonical_name affected_provider_name,
           v.validation_status
    from pipeline.layer2_source_profiles p
    join pipeline.sources s on s.id=p.source_id
    left join ref.countries c on c.id=s.country_id
    left join catalogue.providers cp on cp.id=s.provider_id
    left join pipeline.layer2_source_profile_versions v on v.id=p.current_version_id
    where p.domain in ('course_facts','scholarship')
      and p.target_entity_type in ('course_fact','scholarship')
      and (
        v_query is null or
        p.profile_key ilike '%'||v_query||'%' or
        s.label ilike '%'||v_query||'%' or
        coalesce(cp.canonical_name,'') ilike '%'||v_query||'%' or
        coalesce(c.iso_alpha2,'') ilike '%'||v_query||'%'
      )
    order by lower(s.label),p.profile_key
    limit v_limit offset v_offset
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'profile_id',profile_id,'profile_key',profile_key,'source_label',source_label,
    'country_code',country_code,'domain',domain,'target_entity_type',target_entity_type,
    'affected_provider_name',affected_provider_name,'enabled',enabled,'paused',paused,
    'validation_status',validation_status
  )),'[]'::jsonb) into v_items from base;

  return jsonb_build_object('items',v_items,'total',v_total,'limit',v_limit,'offset',v_offset,'has_more',v_offset+v_limit<v_total);
end
$$;


ALTER FUNCTION "public"."layer2_provider_profile_options_service"("p_actor" "uuid", "p_query" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_provider_runtime_config"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'vault', 'security'
    AS $$
select jsonb_build_object(
  'id',p.id,'provider_key',p.provider_key,'display_name',p.display_name,'adapter_type',p.adapter_type,'base_url',p.base_url,
  'auth_scheme',p.auth_scheme,'auth_field_name',p.auth_field_name,'secret',ds.decrypted_secret,'capabilities',p.capabilities,
  'request_template',p.request_template,'billing_config',p.billing_config,
  'budget_status',security.layer2_provider_budget_status(p.id,coalesce(nullif(p.request_template->>'fixed_credit_units','')::numeric,1)),
  'estimated_request_cost_usd',security.layer2_provider_effective_cost_usd(p.billing_config,1),'enabled',p.enabled,
  'rate_limit_per_minute',p.rate_limit_per_minute,'concurrency',p.concurrency,'timeout_seconds',p.timeout_seconds
)
from pipeline.layer2_acquisition_providers p
left join vault.decrypted_secrets ds on ds.id=p.vault_secret_id
where p.id=p_provider_id
$$;


