CREATE OR REPLACE FUNCTION "public"."layer2_provider_trial_record"("p_trial_course_id" "uuid", "p_acquisition_provider_id" "uuid", "p_domain_key" "text", "p_provider_attempt_id" "uuid" DEFAULT NULL::"uuid", "p_acquisition_success" boolean DEFAULT NULL::boolean, "p_gatekeeping_bypassed" boolean DEFAULT NULL::boolean, "p_javascript_rendered" boolean DEFAULT NULL::boolean, "p_evidence_quality_score" numeric DEFAULT NULL::numeric, "p_deterministic_extraction_success" boolean DEFAULT NULL::boolean, "p_correctness_status" "text" DEFAULT 'unverified'::"text", "p_latency_ms" integer DEFAULT NULL::integer, "p_request_count" integer DEFAULT 1, "p_vendor_cost_usd" numeric DEFAULT NULL::numeric, "p_fields_targeted" integer DEFAULT 0, "p_fields_resolved" integer DEFAULT 0, "p_layer3_required" boolean DEFAULT false, "p_layer4_required" boolean DEFAULT false, "p_blocker" "text" DEFAULT NULL::"text", "p_metrics" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pipeline', 'security'
    AS $$declare v_trial uuid;v_id uuid;v_cost numeric;v_requests integer:=greatest(coalesce(p_request_count,1),0);v_units numeric;begin
 if auth.role()<>'service_role' then raise exception 'service_role required';end if;
 select trial_id into v_trial from pipeline.layer2_completeness_trial_courses where id=p_trial_course_id;
 if v_trial is null then raise exception 'trial course not found';end if;
 begin v_units:=nullif(p_metrics->>'vendor_units','')::numeric;exception when invalid_text_representation then v_units:=null;end;
 if v_units is null then v_units:=v_requests;end if;
 v_cost:=p_vendor_cost_usd;
 if v_cost is null then select security.layer2_provider_effective_cost_usd(p.billing_config,v_units) into v_cost from pipeline.layer2_acquisition_providers p where p.id=p_acquisition_provider_id;end if;
 insert into pipeline.layer2_provider_trial_results(trial_id,trial_course_id,acquisition_provider_id,provider_attempt_id,domain_key,acquisition_success,gatekeeping_bypassed,javascript_rendered,evidence_quality_score,deterministic_extraction_success,correctness_status,latency_ms,request_count,vendor_units,vendor_cost_usd,fields_targeted,fields_resolved,layer3_required,layer4_required,blocker,metrics)
 values(v_trial,p_trial_course_id,p_acquisition_provider_id,p_provider_attempt_id,p_domain_key,p_acquisition_success,p_gatekeeping_bypassed,p_javascript_rendered,p_evidence_quality_score,p_deterministic_extraction_success,p_correctness_status,p_latency_ms,v_requests,v_units,v_cost,coalesce(p_fields_targeted,0),coalesce(p_fields_resolved,0),coalesce(p_layer3_required,false),coalesce(p_layer4_required,false),p_blocker,coalesce(p_metrics,'{}'::jsonb)||jsonb_build_object('estimated_vendor_cost',p_vendor_cost_usd is null,'effective_cost_usd',v_cost,'vendor_units',v_units)) returning id into v_id;
 return v_id;
end$$;


ALTER FUNCTION "public"."layer2_provider_trial_record"("p_trial_course_id" "uuid", "p_acquisition_provider_id" "uuid", "p_domain_key" "text", "p_provider_attempt_id" "uuid", "p_acquisition_success" boolean, "p_gatekeeping_bypassed" boolean, "p_javascript_rendered" boolean, "p_evidence_quality_score" numeric, "p_deterministic_extraction_success" boolean, "p_correctness_status" "text", "p_latency_ms" integer, "p_request_count" integer, "p_vendor_cost_usd" numeric, "p_fields_targeted" integer, "p_fields_resolved" integer, "p_layer3_required" boolean, "p_layer4_required" boolean, "p_blocker" "text", "p_metrics" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_record_course_trial_result"("p_course_id" "uuid", "p_attempt_id" "uuid", "p_fields_targeted" integer, "p_fields_resolved" integer, "p_correctness_status" "text", "p_layer3_required" boolean, "p_blocker" "text", "p_metrics" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare tc record;a pipeline.layer2_provider_attempts%rowtype;ap pipeline.layer2_acquisition_providers%rowtype;v_id uuid;v_units numeric;v_latency integer;v_cost numeric;v_correctness text;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 select c.id as trial_course_id,c.trial_id into tc from pipeline.layer2_completeness_trial_courses c join pipeline.layer2_completeness_trials t on t.id=c.trial_id where c.course_id=p_course_id and t.status='running' order by t.started_at desc limit 1;
 if not found then return null; end if;
 select * into a from pipeline.layer2_provider_attempts where id=p_attempt_id; if not found then return null; end if;
 select * into ap from pipeline.layer2_acquisition_providers where id=a.acquisition_provider_id;
 v_latency:=nullif(a.metrics->>'latency_ms','')::integer;
 v_units:=case when nullif(a.metrics#>>'{provider_telemetry,scrape.do-request-cost}','') is not null then (a.metrics#>>'{provider_telemetry,scrape.do-request-cost}')::numeric when nullif(ap.request_template->>'fixed_credit_units','') is not null then (ap.request_template->>'fixed_credit_units')::numeric when ap.adapter_type='direct_http' then 0 else null end;
 v_cost:=case when coalesce(ap.billing_config->>'plan_tier','')='free' then 0 when nullif(ap.billing_config->>'unit_cost_usd','') is not null and v_units is not null then (ap.billing_config->>'unit_cost_usd')::numeric*v_units else null end;
 v_correctness:=case when p_correctness_status in ('unverified','correct','incorrect','ambiguous') then p_correctness_status when p_correctness_status='identity_mismatch' then 'incorrect' else 'unverified' end;
 insert into pipeline.layer2_provider_trial_results(trial_id,trial_course_id,acquisition_provider_id,provider_attempt_id,domain_key,acquisition_success,gatekeeping_bypassed,javascript_rendered,evidence_quality_score,deterministic_extraction_success,correctness_status,latency_ms,request_count,vendor_cost_usd,fields_targeted,fields_resolved,layer3_required,layer4_required,blocker,metrics,vendor_units)
 values(tc.trial_id,tc.trial_course_id,a.acquisition_provider_id,a.id,'course_facts',a.status='succeeded',false,coalesce((ap.capabilities->>'javascript')::boolean,false),case when a.status='succeeded' then 1 else 0 end,p_fields_resolved>0,v_correctness,v_latency,1,v_cost,p_fields_targeted,p_fields_resolved,p_layer3_required,false,p_blocker,coalesce(p_metrics,'{}'::jsonb)||jsonb_build_object('pricing_mode',coalesce(ap.billing_config->>'plan_tier','unknown'),'extraction_correctness_semantic',p_correctness_status),v_units)
 returning id into v_id;
 return v_id;
end $$;


