CREATE OR REPLACE FUNCTION "public"."layer2_run_batch_context"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $_$ select jsonb_build_object('batch',jsonb_build_object('id',b.id,'profile_id',b.profile_id,'profile_version_id',b.profile_version_id,'trigger_type',b.trigger_type,'status',b.status,'started_at',b.started_at,'policy_snapshot',b.policy_snapshot),'profile',jsonb_build_object('id',p.id,'domain',p.domain,'profile_key',p.profile_key,'enabled',p.enabled,'paused',p.paused),'items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'entity_type',i.entity_type,'entity_id',i.entity_id,'source_url',i.source_url,'status',i.status,'selected_provider_id',i.selected_provider_id,'provider_key',ap.provider_key,'provider_enabled',ap.enabled,'unit_cost_usd',case when (ap.billing_config->>'unit_cost_usd') ~ '^-?[0-9]+(\.[0-9]+)?$' then (ap.billing_config->>'unit_cost_usd')::numeric else null end) order by i.created_at) from pipeline.layer2_run_items i left join pipeline.layer2_acquisition_providers ap on ap.id=i.selected_provider_id where i.batch_id=b.id),'[]'::jsonb)) from pipeline.layer2_run_batches b join pipeline.layer2_source_profiles p on p.id=b.profile_id where b.id=p_batch_id; $_$;


ALTER FUNCTION "public"."layer2_run_batch_context"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_run_batch_create"("p_profile_id" "uuid", "p_trigger_type" "text", "p_requested_by" "uuid", "p_items" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare
  v_profile pipeline.layer2_source_profiles%rowtype;
  v_policy pipeline.layer2_execution_policies%rowtype;
  v_batch uuid:=gen_random_uuid();
  v_count integer;
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  if p_trigger_type not in ('manual','schedule','trial','resume') then raise exception 'invalid trigger_type'; end if;
  if jsonb_typeof(p_items)<>'array' then raise exception 'items must be array'; end if;
  v_count:=jsonb_array_length(p_items);
  if v_count<1 or v_count>1000 then raise exception 'batch item count must be 1..1000'; end if;
  select * into v_profile from pipeline.layer2_source_profiles where id=p_profile_id;
  if not found then raise exception 'profile not found'; end if;
  if not v_profile.enabled or v_profile.paused then raise exception 'profile not executable'; end if;
  if v_profile.current_version_id is null then raise exception 'profile has no current version'; end if;
  select * into v_policy from pipeline.layer2_execution_policies where profile_id=p_profile_id;
  if not found then raise exception 'execution policy missing'; end if;
  insert into pipeline.layer2_run_batches(id,profile_id,profile_version_id,trigger_type,status,requested_by,policy_snapshot,target_count)
  values(v_batch,p_profile_id,v_profile.current_version_id,p_trigger_type,'queued',p_requested_by,
    jsonb_build_object('schedule_mode',v_policy.schedule_mode,'batch_size',v_policy.batch_size,'routing_strategy',v_policy.routing_strategy,
    'max_paid_attempts_per_entity',v_policy.max_paid_attempts_per_entity,'max_vendor_units_per_entity',v_policy.max_vendor_units_per_entity,
    'max_cost_usd_per_entity',v_policy.max_cost_usd_per_entity,'auto_handoff_layer3',v_policy.auto_handoff_layer3,
    'stop_on_identity_mismatch',v_policy.stop_on_identity_mismatch,'max_concurrency',v_policy.max_concurrency),v_count);
  insert into pipeline.layer2_run_items(id,batch_id,entity_type,entity_id,source_url,status,selected_provider_id)
  select gen_random_uuid(),v_batch,lower(x->>'entity_type'),(x->>'entity_id')::uuid,x->>'source_url','queued',nullif(x->>'provider_id','')::uuid
  from jsonb_array_elements(p_items) x;
  if exists(select 1 from pipeline.layer2_run_items where batch_id=v_batch and (entity_type not in ('course','scholarship') or entity_id is null or nullif(source_url,'') is null))
  then raise exception 'each item requires valid entity_type, entity_id and source_url'; end if;
  if exists(select 1 from pipeline.layer2_run_items i left join pipeline.layer2_acquisition_providers p on p.id=i.selected_provider_id
            where i.batch_id=v_batch and i.selected_provider_id is not null and (p.id is null or not p.enabled))
  then raise exception 'selected provider invalid or disabled'; end if;
  return v_batch;
end $$;


