CREATE OR REPLACE FUNCTION "public"."layer2_run_batch_reconcile"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare
  v_total int; v_processed int; v_resolved int; v_l3 int; v_blocked int;
  v_units numeric; v_cost numeric; v_status text; v_existing text;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  select status into v_existing
  from pipeline.layer2_run_batches
  where id=p_batch_id
  for update;

  if v_existing is null then
    raise exception 'batch not found' using errcode='22023';
  end if;

  select count(*),
         count(*) filter(where status not in ('queued','discovering','acquiring','extracting')),
         count(*) filter(where status='resolved_l2'),
         count(*) filter(where status='layer3_required'),
         count(*) filter(where status='blocked'),
         coalesce(sum(vendor_units),0),
         coalesce(sum(vendor_cost_usd),0)
  into v_total,v_processed,v_resolved,v_l3,v_blocked,v_units,v_cost
  from pipeline.layer2_run_items
  where batch_id=p_batch_id;

  if v_existing='cancelled' then
    v_status:='cancelled';
  else
    v_status:=case
      when v_total=0 then 'failed'
      when v_processed<v_total then 'running'
      when v_blocked=v_total then 'failed'
      when v_blocked>0 or v_l3>0 then 'partial'
      else 'completed'
    end;
  end if;

  update pipeline.layer2_run_batches
  set status=v_status,
      processed_count=v_processed,
      resolved_l2_count=v_resolved,
      escalated_l3_count=v_l3,
      blocked_count=v_blocked,
      vendor_units=v_units,
      vendor_cost_usd=v_cost,
      started_at=coalesce(started_at,case when v_status<>'queued' then now() end),
      completed_at=case
        when v_status='cancelled' then coalesce(completed_at,now())
        when v_processed=v_total then coalesce(completed_at,now())
        else null
      end,
      heartbeat_at=case when v_status='cancelled' then coalesce(heartbeat_at,now()) else heartbeat_at end,
      updated_at=now()
  where id=p_batch_id;

  return public.layer2_run_batch_summary(p_batch_id);
end $$;


ALTER FUNCTION "public"."layer2_run_batch_reconcile"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_run_batch_recover_stale"("p_batch_id" "uuid", "p_stale_after_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare
  r record;
  v_job uuid;
  v_recovered integer:=0;
  v_requeued integer:=0;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  for r in
    select i.id,i.source_url,i.selected_provider_id,i.last_attempt_at
    from pipeline.layer2_run_items i
    where i.batch_id=p_batch_id
      and i.status='acquiring'
      and i.updated_at < now() - make_interval(secs=>greatest(30,coalesce(p_stale_after_seconds,120)))
    for update
  loop
    select j.id into v_job
    from pipeline.jobs j
    where j.status='succeeded'
      and j.created_at >= coalesce(r.last_attempt_at,now()-interval '10 minutes') - interval '5 seconds'
      and j.payload->>'target_url'=r.source_url
      and nullif(j.result->>'provider_id','')::uuid is not distinct from r.selected_provider_id
      and nullif(j.result->>'attempt_id','') is not null
      and nullif(j.result->>'evidence_id','') is not null
    order by j.completed_at desc nulls last,j.created_at desc
    limit 1;

    if v_job is not null then
      update pipeline.layer2_run_items
      set status='extracting',
          job_id=v_job,
          evidence_count=greatest(evidence_count,1),
          blocker=null,
          updated_at=now()
      where id=r.id;
      v_recovered:=v_recovered+1;
    else
      update pipeline.layer2_run_items
      set status='queued',
          blocker='requeued_after_stale_acquisition',
          completed_at=null,
          updated_at=now()
      where id=r.id;
      v_requeued:=v_requeued+1;
    end if;
  end loop;

  if v_recovered+v_requeued>0 then
    update pipeline.layer2_run_batches
    set heartbeat_at=now(),updated_at=now()
    where id=p_batch_id and status in('queued','running');
  end if;

  return jsonb_build_object(
    'batch_id',p_batch_id,
    'recovered_acquisitions',v_recovered,
    'requeued_items',v_requeued
  );
end $$;


ALTER FUNCTION "public"."layer2_run_batch_recover_stale"("p_batch_id" "uuid", "p_stale_after_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_run_batch_recover_stuck"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_stale integer; v_requeued integer;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  select coalesce(ep.stale_after_minutes,30) into v_stale
  from pipeline.layer2_run_batches b
  join pipeline.layer2_execution_policies ep on ep.profile_id=b.profile_id
  where b.id=p_batch_id;
  if v_stale is null then raise exception 'batch not found'; end if;
  if not exists(
    select 1 from pipeline.layer2_run_batches
    where id=p_batch_id and status='running'
      and coalesce(heartbeat_at,updated_at,started_at,created_at) < now()-make_interval(mins=>v_stale)
  ) then raise exception 'batch is not stale'; end if;
  update pipeline.layer2_run_items
  set status='queued',failure_class='stale_recovery',blocker=null,completed_at=null,updated_at=now()
  where batch_id=p_batch_id and status in ('discovering','acquiring','extracting');
  get diagnostics v_requeued=row_count;
  update pipeline.layer2_run_batches
  set status='queued',heartbeat_at=null,completed_at=null,updated_at=now()
  where id=p_batch_id;
  return jsonb_build_object('batch_id',p_batch_id,'requeued_items',v_requeued,'stale_after_minutes',v_stale);
end $$;


ALTER FUNCTION "public"."layer2_run_batch_recover_stuck"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_run_batch_resume"("p_batch_id" "uuid", "p_max_attempts" integer DEFAULT 2) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$ declare v_n integer; begin if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; if p_max_attempts<1 or p_max_attempts>5 then raise exception 'max attempts out of range'; end if; update pipeline.layer2_run_items set status='queued',blocker=null,completed_at=null where batch_id=p_batch_id and status='blocked' and retry_count<p_max_attempts and blocker ~* '(providers_exhausted|connection|timeout|fetch|network|temporar)'; get diagnostics v_n=row_count; if v_n>0 then update pipeline.layer2_run_batches set status='queued',completed_at=null where id=p_batch_id; end if; return jsonb_build_object('batch_id',p_batch_id,'requeued',v_n,'max_attempts',p_max_attempts); end $$;


