    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$ select jsonb_build_object('batch_id',b.id,'status',b.status,'trigger_type',b.trigger_type,'profile_id',b.profile_id,'profile_version_id',b.profile_version_id,'target_count',b.target_count,'processed_count',b.processed_count,'resolved_l2_count',b.resolved_l2_count,'escalated_l3_count',b.escalated_l3_count,'blocked_count',b.blocked_count,'vendor_units',b.vendor_units,'vendor_cost_usd',b.vendor_cost_usd,'policy_snapshot',b.policy_snapshot,'items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'entity_type',i.entity_type,'entity_id',i.entity_id,'source_url',i.source_url,'status',i.status,'provider_id',i.selected_provider_id,'evidence_count',i.evidence_count,'fields_targeted',i.fields_targeted,'fields_resolved',i.fields_resolved,'vendor_units',i.vendor_units,'vendor_cost_usd',i.vendor_cost_usd,'blocker',i.blocker) order by i.created_at) from pipeline.layer2_run_items i where i.batch_id=b.id),'[]'::jsonb)) from pipeline.layer2_run_batches b where b.id=p_batch_id; $$;


