CREATE OR REPLACE FUNCTION "public"."layer2_run_item_mark"("p_item_id" "uuid", "p_status" "text", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_evidence_count" integer DEFAULT NULL::integer, "p_vendor_units" numeric DEFAULT NULL::numeric, "p_vendor_cost_usd" numeric DEFAULT NULL::numeric, "p_fields_targeted" integer DEFAULT NULL::integer, "p_fields_resolved" integer DEFAULT NULL::integer, "p_blocker" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_batch uuid;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  if p_status not in ('queued','discovering','acquiring','extracting','resolved_l2','layer3_required','blocked','cancelled') then
    raise exception 'invalid item status';
  end if;

  update pipeline.layer2_run_items
  set status=p_status,
      job_id=coalesce(p_job_id,job_id),
      evidence_count=coalesce(p_evidence_count,evidence_count),
      vendor_units=coalesce(p_vendor_units,vendor_units),
      vendor_cost_usd=coalesce(p_vendor_cost_usd,vendor_cost_usd),
      fields_targeted=coalesce(p_fields_targeted,fields_targeted),
      fields_resolved=coalesce(p_fields_resolved,fields_resolved),
      blocker=p_blocker,
      started_at=case when p_status in ('acquiring','extracting') then coalesce(started_at,now()) else started_at end,
      retry_count=case when p_status='acquiring' and last_attempt_at is not null then retry_count+1 else retry_count end,
      last_attempt_at=case when p_status='acquiring' then now() else last_attempt_at end,
      completed_at=case when p_status in ('resolved_l2','layer3_required','blocked','cancelled') then now() else null end,
      updated_at=now()
  where id=p_item_id
  returning batch_id into v_batch;

  if v_batch is not null then
    update pipeline.layer2_run_batches
    set heartbeat_at=now(),updated_at=now()
    where id=v_batch and status in('queued','running');
  end if;

  return v_batch is not null;
end $$;


ALTER FUNCTION "public"."layer2_run_item_mark"("p_item_id" "uuid", "p_status" "text", "p_job_id" "uuid", "p_evidence_count" integer, "p_vendor_units" numeric, "p_vendor_cost_usd" numeric, "p_fields_targeted" integer, "p_fields_resolved" integer, "p_blocker" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_run_item_metrics_mark"("p_item_id" "uuid", "p_response_ms" integer DEFAULT NULL::integer, "p_extraction_ms" integer DEFAULT NULL::integer, "p_evidence_bytes" bigint DEFAULT NULL::bigint, "p_outcome_code" "text" DEFAULT NULL::"text", "p_failure_class" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  update pipeline.layer2_run_items
  set response_ms=coalesce(p_response_ms,response_ms),
      extraction_ms=coalesce(p_extraction_ms,extraction_ms),
      evidence_bytes=coalesce(p_evidence_bytes,evidence_bytes),
      outcome_code=coalesce(p_outcome_code,outcome_code),
      failure_class=coalesce(p_failure_class,failure_class),
      updated_at=now()
  where id=p_item_id;
  return found;
end $$;


ALTER FUNCTION "public"."layer2_run_item_metrics_mark"("p_item_id" "uuid", "p_response_ms" integer, "p_extraction_ms" integer, "p_evidence_bytes" bigint, "p_outcome_code" "text", "p_failure_class" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_run_item_resume_context"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_result jsonb;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  select jsonb_build_object(
    'item_id',i.id,
    'batch_id',i.batch_id,
    'job_id',j.id,
    'attempt_id',nullif(j.result->>'attempt_id','')::uuid,
    'evidence_id',nullif(j.result->>'evidence_id','')::uuid,
    'provider_id',nullif(j.result->>'provider_id','')::uuid,
    'provider_key',j.result->>'provider_key',
    'content_changed',coalesce((j.result->>'content_changed')::boolean,true),
    'estimated_request_cost_usd',coalesce((j.result->>'estimated_request_cost_usd')::numeric,0)
  )
  into v_result
  from pipeline.layer2_run_items i
  join pipeline.jobs j on j.id=i.job_id
  where i.id=p_item_id
    and i.status='extracting'
    and j.status='succeeded'
    and nullif(j.result->>'attempt_id','') is not null
    and nullif(j.result->>'evidence_id','') is not null;

  return v_result;
end $$;


ALTER FUNCTION "public"."layer2_run_item_resume_context"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_runtime_context"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline'
    AS $$
declare v pipeline.layer2_source_profiles%rowtype;vv pipeline.layer2_source_profile_versions%rowtype;vr jsonb;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501';end if;
 select * into v from pipeline.layer2_source_profiles where id=p_profile_id;
 if not found or not v.enabled or v.paused or v.domain not in ('course_facts','scholarship','provider_asset') then return null;end if;
 select * into vv from pipeline.layer2_source_profile_versions where id=v.current_version_id;
 if not found or vv.validation_status<>'valid' then return null;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'provider_id',r.acquisition_provider_id,'priority',r.priority,'required_capabilities',r.required_capabilities,'request_overrides',r.request_overrides,'evidence_policy',r.evidence_policy,'fallback_on',r.fallback_on) order by r.priority),'[]'::jsonb)
 into vr from pipeline.layer2_profile_provider_routes r where r.profile_id=v.id and r.enabled;
 return jsonb_build_object('profile_id',v.id,'profile_key',v.profile_key,'domain',v.domain,'source_id',v.source_id,'version_id',vv.id,'version_no',vv.version_no,'configuration',vv.configuration,'routes',vr);
end $$;


ALTER FUNCTION "public"."layer2_runtime_context"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_runtime_job_mark"("p_job_id" "uuid", "p_status" "text", "p_payload" "jsonb" DEFAULT NULL::"jsonb", "p_result" "jsonb" DEFAULT NULL::"jsonb", "p_error" "text" DEFAULT NULL::"text", "p_attempt_count" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 update pipeline.jobs set status=p_status,
   started_at=case when p_status='running' then coalesce(started_at,now()) else started_at end,
   completed_at=case when p_status in ('succeeded','failed','cancelled') then now() else completed_at end,
   payload=coalesce(p_payload,payload),result=coalesce(p_result,result),error_text=p_error,
   attempt_count=coalesce(p_attempt_count,attempt_count)
 where id=p_job_id;
end $$;


ALTER FUNCTION "public"."layer2_runtime_job_mark"("p_job_id" "uuid", "p_status" "text", "p_payload" "jsonb", "p_result" "jsonb", "p_error" "text", "p_attempt_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scale_cross_layer_handoff"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'ref'
    AS $$
declare
  v_l3 integer:=0;
  v_l4 integer:=0;
  v_l3_profile uuid;
  v_l3_ready boolean:=false;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  if not exists(select 1 from pipeline.layer2_scale_qualification_runs where id=p_run_id) then
    raise exception 'qualification run not found' using errcode='22023';
  end if;

  select p.id into v_l3_profile
  from pipeline.layer3_model_profiles p
  where p.code='openrouter-source-pattern-v1'
    and p.enabled and not p.paused
    and coalesce((p.quality_benchmark->>'pass')::boolean,false)
  limit 1;
  v_l3_ready:=v_l3_profile is not null;

  with targets as (
    select distinct
      qi.provider_id,
      qi.evidence_id,
      nullif(qi.outcome->>'qualification_source_id','')::uuid source_id,
      nullif(qi.outcome->>'qualification_profile_id','')::uuid source_profile_id,
      co.iso_alpha2::text country_code,
      qr.requested_by,
      'A23-SOURCE-PATTERN:'||p_run_id::text||':'||qi.provider_id::text revalidation_ref
    from pipeline.layer2_scale_qualification_items qi
    join pipeline.layer2_scale_qualification_runs qr on qr.id=qi.run_id
    join ref.countries co on co.id=qr.country_id
    where qi.run_id=p_run_id
      and qi.status='layer3_required'
      and qi.evidence_id is not null
  ), ins as (
    insert into pipeline.refresh_requests(
      requested_layer,country_code,source_id,source_profile_id,entity_type,entity_id,
      evidence_id,layer3_profile_id,revalidation_ref,reason,trigger_type,status,
      requested_by,change_control_ref,schedule_error
    )
    select
      3,t.country_code,t.source_id,t.source_profile_id,'provider',t.provider_id,
      t.evidence_id,v_l3_profile,t.revalidation_ref,
      'Interpret first-party Course discovery/source pattern from governed Layer 2 Evidence. Do not infer or change Layer 1 identity. Return any candidate to Layer 2 strict identity control before promotion.',
      'manual_governed','cancelled',
      t.requested_by,'CF-CHG-20260830-048',
      'retired (Decision 213): course pages are found by the course-link search'
    from targets t
    where not exists(
      select 1 from pipeline.refresh_requests rr
      where rr.revalidation_ref=t.revalidation_ref
    )
    returning 1
  )
  select count(*) into v_l3 from ins;

  with targets as (
    select distinct
      qi.provider_id,
      co.iso_alpha2::text country_code,
      qr.requested_by,
      coalesce(qi.outcome->>'reason',
        case qi.status when 'blocked' then 'qualification_blocked'
                       when 'layer4_required' then 'layer4_resolution_required'
                       else 'missing_or_invalid_first_party_source_seed' end) reason,
      'A23-SOURCE-RESOLUTION:'||p_run_id::text||':'||qi.provider_id::text revalidation_ref
    from pipeline.layer2_scale_qualification_items qi
    join pipeline.layer2_scale_qualification_runs qr on qr.id=qi.run_id
    join ref.countries co on co.id=qr.country_id
    where qi.run_id=p_run_id
      and qi.status in ('source_limited','blocked','layer4_required')
  ), ins as (
    insert into pipeline.refresh_requests(
      requested_layer,country_code,entity_type,entity_id,revalidation_ref,
      reason,trigger_type,status,requested_by,change_control_ref,schedule_error
    )
    select
      4,t.country_code,'provider',t.provider_id,t.revalidation_ref,
      'Resolve/verify the first-party Provider Course source before Layer 2 qualification can continue. Reason: '||t.reason,
      'manual_governed','queued',t.requested_by,'CF-CHG-20260830-048',
      'provider_source_resolution_required'
    from targets t
    where not exists(
      select 1 from pipeline.refresh_requests rr
      where rr.revalidation_ref=t.revalidation_ref
    )
    returning 1
  )
  select count(*) into v_l4 from ins;

  update pipeline.layer2_scale_qualification_runs
  set result_summary=coalesce(result_summary,'{}'::jsonb)||jsonb_build_object(
    'cross_layer_handoff_at',now(),
    'layer3_source_pattern_requests_created',v_l3,
    'layer3_profile_id',v_l3_profile,
    'layer3_execution_state',case when v_l3_ready then 'queued_for_governed_operator_execution' else 'blocked_profile_not_executable' end,
    'layer4_source_resolution_requests_created',v_l4,
    'canonical_mutation_authorised',false,
    'search_mutation_authorised',false,
    'publication_mutation_authorised',false
  )
  where id=p_run_id;

  return jsonb_build_object(
    'ok',true,'run_id',p_run_id,
    'layer3_source_pattern_requests_created',v_l3,
    'layer3_profile_id',v_l3_profile,
    'layer3_execution_state',case when v_l3_ready then 'queued_for_governed_operator_execution' else 'blocked_profile_not_executable' end,
    'layer4_source_resolution_requests_created',v_l4,
    'canonical_mutation_authorised',false,
    'search_mutation_authorised',false,
    'publication_mutation_authorised',false
  );
end
$$;


ALTER FUNCTION "public"."layer2_scale_cross_layer_handoff"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scale_pattern_reconcile"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue'
    AS $$
declare
  r record;
  v_version uuid;
  v_ids uuid[];
  v_terminal integer;
  v_selected integer;
  v_required integer;
  v_dispatched_at timestamptz;
  v_profile uuid;
  v_provider_result jsonb;
  v_results jsonb:='[]'::jsonb;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  for r in
    select distinct qi.provider_id,
      nullif(qi.outcome->>'pattern_dispatch_version_id','')::uuid version_id
    from pipeline.layer2_scale_qualification_items qi
    where qi.run_id=p_run_id
      and qi.status='source_pattern_candidate'
      and nullif(qi.outcome->>'pattern_dispatch_version_id','') is not null
  loop
    v_version:=r.version_id;
    select array_agg((x)::uuid)
    into v_ids
    from jsonb_array_elements_text((
      select qi.outcome->'control_course_ids'
      from pipeline.layer2_scale_qualification_items qi
      where qi.run_id=p_run_id and qi.provider_id=r.provider_id
      limit 1
    )) x;

    v_required:=coalesce(array_length(v_ids,1),0);
    select created_at into v_dispatched_at
    from pipeline.layer2_source_profile_versions
    where id=v_version;

    select count(distinct dc.course_id),
           count(distinct dc.course_id) filter(where dc.selected=true)
    into v_terminal,v_selected
    from pipeline.layer2_course_discovery_candidates dc
    where dc.source_profile_version_id=v_version
      and dc.course_id=any(v_ids)
      and dc.status in ('exact_match','likely_match','ambiguous','identity_mismatch','current_page_not_found');

    if v_terminal<v_required then
      if v_dispatched_at is not null and v_dispatched_at<=now()-interval '30 minutes' then
        update pipeline.layer2_scale_qualification_items
        set status='layer3_required',
            outcome=outcome||jsonb_build_object(
              'provider_pattern_qualified',false,
              'pattern_control_status','incomplete_timeout',
              'pattern_control_dispatched_at',v_dispatched_at,
              'identity_controls_terminal',coalesce(v_terminal,0),
              'identity_controls_missing',greatest(v_required-coalesce(v_terminal,0),0),
              'identity_controls_required',v_required,
              'reason','pattern_control_incomplete_timeout',
              'handoff','layer3_source_pattern_interpretation',
              'canonical_mutation_authorised',false,
              'search_mutation_authorised',false,
              'publication_mutation_authorised',false
            )
        where run_id=p_run_id and provider_id=r.provider_id and status='source_pattern_candidate';
        v_provider_result:=jsonb_build_object(
          'provider_id',r.provider_id,
          'status','layer3_required',
          'reason','pattern_control_incomplete_timeout',
          'controls_terminal',coalesce(v_terminal,0),
          'controls_required',v_required
        );
        v_results:=v_results||jsonb_build_array(v_provider_result);
      end if;
      continue;
    end if;

    select lp.id into v_profile
    from pipeline.layer2_source_profiles lp
    join pipeline.sources s on s.id=lp.source_id
    where s.provider_id=r.provider_id
      and lp.current_version_id=v_version
      and lp.authority_class='qualification_candidate'
    limit 1;

    if v_selected=coalesce(array_length(v_ids,1),0) and v_selected>=3 then
      update pipeline.layer2_source_profiles
      set authority_class='first_party_qualified',updated_at=now()
      where id=v_profile;

      update pipeline.sources
      set metadata=metadata||jsonb_build_object(
        'qualification_status','first_party_pattern_qualified',
        'qualification_run_id',p_run_id,
        'qualification_profile_version_id',v_version,
        'identity_controls_verified',v_selected,
        'qualified_at',now(),
        'canonical_mutation_authorised',false
      ),updated_at=now()
      where id=(select source_id from pipeline.layer2_source_profiles where id=v_profile);

      update pipeline.layer2_scale_qualification_items
      set status='profile_qualified',
          outcome=outcome||jsonb_build_object(
            'provider_pattern_qualified',true,
            'identity_controls_verified',v_selected,
            'identity_controls_required',array_length(v_ids,1),
            'qualified_profile_id',v_profile,
            'qualified_profile_version_id',v_version,
            'next_step','full_scope_discovery_wave',
            'canonical_mutation_authorised',false,
            'search_mutation_authorised',false,
            'publication_mutation_authorised',false
          )
      where run_id=p_run_id and provider_id=r.provider_id and status='source_pattern_candidate';
      v_provider_result:=jsonb_build_object('provider_id',r.provider_id,'status','profile_qualified','controls_verified',v_selected);
    else
      update pipeline.layer2_scale_qualification_items
      set status='layer3_required',
          outcome=outcome||jsonb_build_object(
            'provider_pattern_qualified',false,
            'identity_controls_verified',v_selected,
            'identity_controls_required',array_length(v_ids,1),
            'handoff','layer3_source_pattern_interpretation',
            'canonical_mutation_authorised',false,
            'search_mutation_authorised',false,
            'publication_mutation_authorised',false
          )
      where run_id=p_run_id and provider_id=r.provider_id and status='source_pattern_candidate';
      v_provider_result:=jsonb_build_object('provider_id',r.provider_id,'status','layer3_required','controls_verified',v_selected);
    end if;
    v_results:=v_results||jsonb_build_array(v_provider_result);
  end loop;

  update pipeline.layer2_scale_qualification_runs
  set result_summary=result_summary||jsonb_build_object(
    'pattern_control_reconciled_at',now(),
    'profile_qualified_providers',(
      select count(distinct provider_id) from pipeline.layer2_scale_qualification_items
      where run_id=p_run_id and status='profile_qualified'
    ),
    'layer3_required_providers',(
      select count(distinct provider_id) from pipeline.layer2_scale_qualification_items
      where run_id=p_run_id and status='layer3_required'
    ),
    'source_limited_providers',(
      select count(distinct provider_id) from pipeline.layer2_scale_qualification_items
      where run_id=p_run_id and status='source_limited'
    )
  )
  where id=p_run_id;

  return jsonb_build_object('ok',true,'run_id',p_run_id,'reconciled',v_results);
end $$;


ALTER FUNCTION "public"."layer2_scale_pattern_reconcile"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scale_qualification_context"("p_run_id" "uuid", "p_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'ref', 'public'
    AS $$
  select jsonb_build_object(
    'run_id',r.id,
    'country_code',co.iso_alpha2::text,
    'providers',coalesce((
      select jsonb_agg(jsonb_build_object(
        'provider_id',x.provider_id,
        'provider_name',x.canonical_name,
        'website',x.website,
        'profile_id',x.profile_id,
        'items',x.items
      ) order by x.canonical_name)
      from (
        select p.id provider_id,p.canonical_name,p.website,lp.id profile_id,
          jsonb_agg(jsonb_build_object(
            'item_id',qi.id,'course_id',qi.course_id,'sample_rank',qi.sample_rank,
            'course_title',c.canonical_title,'course_code',c.course_code
          ) order by qi.sample_rank) items
        from pipeline.layer2_scale_qualification_items qi
        join catalogue.providers p on p.id=qi.provider_id
        join catalogue.courses c on c.id=qi.course_id
        join pipeline.sources s on s.provider_id=p.id
        join pipeline.layer2_source_profiles lp on lp.source_id=s.id
          and lp.authority_class='qualification_candidate'
          and lp.domain='course_facts'
          and lp.enabled and not lp.paused
        where qi.run_id=r.id and qi.status='qualifying'
        group by p.id,p.canonical_name,p.website,lp.id
        order by p.canonical_name
        limit least(greatest(coalesce(p_limit,5),1),10)
      ) x
    ),'[]'::jsonb)
  )
  from pipeline.layer2_scale_qualification_runs r
  join ref.countries co on co.id=r.country_id
  where r.id=p_run_id
$$;


ALTER FUNCTION "public"."layer2_scale_qualification_context"("p_run_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scale_qualification_prepare"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'catalogue', 'ref', 'security'
    AS $_$
declare
  v_run pipeline.layer2_scale_qualification_runs%rowtype;
  r record;
  v_source uuid;
  v_profile uuid;
  v_version uuid;
  v_cfg jsonb;
  v_hash text;
  v_validation jsonb;
  v_country text;
  v_profiles jsonb:='[]'::jsonb;
  v_ready integer:=0;
  v_limited integer:=0;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  select * into v_run from pipeline.layer2_scale_qualification_runs where id=p_run_id for update;
  if not found then raise exception 'qualification run not found' using errcode='22023'; end if;
  if v_run.status in ('completed','cancelled') then
    return jsonb_build_object('ok',true,'status',v_run.status,'run_id',p_run_id);
  end if;

  select iso_alpha2::text into v_country from ref.countries where id=v_run.country_id;

  for r in
    select distinct qi.provider_id,p.canonical_name,p.website,p.country_id
    from pipeline.layer2_scale_qualification_items qi
    join catalogue.providers p on p.id=qi.provider_id
    where qi.run_id=p_run_id
      and qi.status in ('selected','qualifying')
    order by p.canonical_name
  loop
    if r.website is null
       or btrim(r.website)=''
       or r.website !~* '^https?://[^[:space:]]+$'
       or lower(r.website) like 'https://https://%'
       or lower(r.website) like 'http://http://%'
    then
      update pipeline.layer2_scale_qualification_items
      set status='source_limited',
          outcome=coalesce(outcome,'{}'::jsonb)||jsonb_build_object(
            'stage','source_seed_qualification',
            'outcome','source_limited',
            'reason','missing_or_invalid_layer1_provider_website',
            'layer1_provider_website',r.website,
            'handoff','layer4_source_resolution',
            'canonical_mutation_authorised',false,
            'search_mutation_authorised',false,
            'publication_mutation_authorised',false
          )
      where run_id=p_run_id and provider_id=r.provider_id;
      v_limited:=v_limited+1;
      continue;
    end if;

    select lp.id,s.id into v_profile,v_source
    from pipeline.layer2_source_profiles lp
    join pipeline.sources s on s.id=lp.source_id
    where s.provider_id=r.provider_id
      and lp.authority_class='qualification_candidate'
      and lp.domain='course_facts'
    order by lp.created_at desc
    limit 1;

    if v_profile is null then
      insert into pipeline.sources(
        source_type,provider_id,country_id,url,label,trust_rank,status,metadata
      ) values(
        'web_catalogue',r.provider_id,r.country_id,btrim(r.website),
        'A11 qualification — '||r.canonical_name,60,'active',
        jsonb_build_object(
          'layer',2,
          'qualification_candidate',true,
          'qualification_run_id',p_run_id,
          'change_control_ref','CF-CHG-20260830-048',
          'canonical_mutation_authorised',false
        )
      ) returning id into v_source;

      insert into pipeline.layer2_source_profiles(
        source_id,profile_key,domain,acquisition_method,target_entity_type,
        authority_class,enabled,paused,operational_owner,freshness_sla_hours,schedule_text
      ) values(
        v_source,
        'qualification-'||lower(v_country)||'-'||left(replace(r.provider_id::text,'-',''),16),
        'course_facts','website','course_fact','qualification_candidate',
        true,false,'PIM/Data Operations',168,'qualification_only'
      ) returning id into v_profile;

      v_cfg:=jsonb_build_object(
        'acquisition_method','website',
        'base_domain',btrim(r.website),
        'discovery_url',btrim(r.website),
        'url_patterns',jsonb_build_array(btrim(r.website)),
        'inclusion_rules',jsonb_build_array(),
        'exclusion_rules',jsonb_build_array(),
        'headers',jsonb_build_object('user_agent','CourseFinder Layer2 Qualification/1.0'),
        'authentication',jsonb_build_object('mechanism','none'),
        'rate_limit_per_minute',30,
        'concurrency',1,
        'timeout_seconds',30,
        'retry',jsonb_build_object('max_attempts',2,'backoff','exponential'),
        'robots_policy','respect',
        'allowed_mime_types',jsonb_build_array('text/html','application/json'),
        'max_payload_mb',10,
        'parser_profile','generic-first-party-source-qualification-v1',
        'target_entity_type','course_fact',
        'mapping_strategy','qualification_only_no_canonical_mutation',
        'stable_identifier_strategy','layer1_provider_id_plus_first_party_host',
        'regulatory_code_extraction',jsonb_build_object('cricos',null,'nzqa',null),
        'evidence_required',true,
        'freshness_sla_hours',168,
        'schedule','qualification_only',
        'content_change_policy','evidence_only_never_direct_canonical_mutation',
        'source_authority','first_party_candidate_unqualified',
        'operational_owner','PIM/Data Operations',
        'change_control_ref','CF-CHG-20260830-048'
      );
      v_hash:=encode(extensions.digest(v_cfg::text,'sha256'),'hex');
      v_validation:=security.layer2_validate_profile_config(v_cfg);

      insert into pipeline.layer2_source_profile_versions(
        profile_id,version_no,configuration,configuration_hash,
        validation_status,validation_result,change_control_ref,uat_ref
      ) values(
        v_profile,1,v_cfg,v_hash,
        case when (v_validation->>'valid')::boolean then 'valid' else 'invalid' end,
        v_validation,'CF-CHG-20260830-048','M2.4.2-A11-source-qualification'
      ) returning id into v_version;

      update pipeline.layer2_source_profiles set current_version_id=v_version where id=v_profile;

      insert into pipeline.layer2_profile_provider_routes(
        profile_id,acquisition_provider_id,priority,enabled,
        required_capabilities,request_overrides,evidence_policy,fallback_on,change_control_ref
      )
      select
        v_profile,ap.id,
        case ap.provider_key
          when 'firecrawl' then 5
          when 'direct-http' then 20
          when 'scrape-do' then 80
          when 'scraperapi' then 90
          when 'zenrows' then 100
          else 120
        end,
        case when ap.provider_key in ('firecrawl','direct-http') then true else false end,'{}'::jsonb,'{}'::jsonb,
        '{"capture_raw":true,"capture_html":true,"capture_screenshot_on_failure":false}'::jsonb,
        '["blocked","timeout","403","429","5xx","extraction_failed"]'::jsonb,
        'CF-CHG-20260830-048'
      from pipeline.layer2_acquisition_providers ap
      where ap.enabled
      on conflict do nothing;
    end if;

    update pipeline.layer2_scale_qualification_items
    set status='qualifying',
        outcome=coalesce(outcome,'{}'::jsonb)||jsonb_build_object(
          'stage','source_seed_qualification',
          'qualification_profile_id',v_profile,
          'qualification_source_id',v_source,
          'layer1_provider_website',r.website,
          'canonical_mutation_authorised',false,
          'search_mutation_authorised',false,
          'publication_mutation_authorised',false
        )
    where run_id=p_run_id and provider_id=r.provider_id and status in ('selected','qualifying');

    v_profiles:=v_profiles||jsonb_build_array(jsonb_build_object(
      'provider_id',r.provider_id,'provider_name',r.canonical_name,
      'website',r.website,'profile_id',v_profile,'source_id',v_source
    ));
    v_ready:=v_ready+1;
  end loop;

  update pipeline.layer2_scale_qualification_runs
  set status=case when v_ready>0 then 'running' else 'completed' end,
      result_summary=coalesce(result_summary,'{}'::jsonb)||jsonb_build_object(
        'stage','source_seed_qualification',
        'providers_ready_for_acquisition',v_ready,
        'providers_source_limited',v_limited,
        'identity_safety_required',true,
        'canonical_mutation_authorised',false,
        'search_mutation_authorised',false,
        'publication_mutation_authorised',false
      ),
      completed_at=case when v_ready=0 then now() else null end
  where id=p_run_id;

  return jsonb_build_object(
    'ok',true,'run_id',p_run_id,
    'providers_ready_for_acquisition',v_ready,
    'providers_source_limited',v_limited,
    'profiles',v_profiles,
    'canonical_mutation_authorised',false,
    'search_mutation_authorised',false,
    'publication_mutation_authorised',false
  );
end $_$;


ALTER FUNCTION "public"."layer2_scale_qualification_prepare"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scale_qualification_provider_finish"("p_run_id" "uuid", "p_provider_id" "uuid", "p_evidence_id" "uuid", "p_status" "text", "p_outcome" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare
  v_status text:=lower(coalesce(nullif(trim(p_status),''),'blocked'));
  v_remaining integer;
  v_summary jsonb;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  if v_status not in ('source_pattern_candidate','source_limited','blocked','layer3_required','layer4_required') then
    raise exception 'invalid qualification provider status' using errcode='22023';
  end if;

  update pipeline.layer2_scale_qualification_items
  set status=v_status,
      evidence_id=coalesce(p_evidence_id,evidence_id),
      outcome=coalesce(outcome,'{}'::jsonb)||coalesce(p_outcome,'{}'::jsonb)||
        jsonb_build_object(
          'canonical_mutation_authorised',false,
          'search_mutation_authorised',false,
          'publication_mutation_authorised',false
        )
  where run_id=p_run_id and provider_id=p_provider_id and status='qualifying';

  select count(*) into v_remaining
  from pipeline.layer2_scale_qualification_items
  where run_id=p_run_id and status in ('selected','qualifying');

  if v_remaining=0 then
    select jsonb_build_object(
      'source_pattern_candidate',count(distinct provider_id) filter(where status='source_pattern_candidate'),
      'source_limited',count(distinct provider_id) filter(where status='source_limited'),
      'layer3_required',count(distinct provider_id) filter(where status='layer3_required'),
      'layer4_required',count(distinct provider_id) filter(where status='layer4_required'),
      'blocked',count(distinct provider_id) filter(where status='blocked'),
      'course_samples',count(*),
      'evidence_backed_samples',count(*) filter(where evidence_id is not null)
    ) into v_summary
    from pipeline.layer2_scale_qualification_items
    where run_id=p_run_id;

    update pipeline.layer2_scale_qualification_runs
    set status=case when coalesce((v_summary->>'blocked')::integer,0)>0 then 'partial' else 'completed' end,
        completed_at=now(),
        result_summary=coalesce(result_summary,'{}'::jsonb)||jsonb_build_object(
          'source_seed_results',v_summary,
          'next_step','course_page_source_pattern_validation',
          'canonical_mutation_authorised',false,
          'search_mutation_authorised',false,
          'publication_mutation_authorised',false
        )
    where id=p_run_id;
  end if;

  return jsonb_build_object('ok',true,'run_id',p_run_id,'provider_id',p_provider_id,'status',v_status,'remaining',v_remaining);
end $$;


ALTER FUNCTION "public"."layer2_scale_qualification_provider_finish"("p_run_id" "uuid", "p_provider_id" "uuid", "p_evidence_id" "uuid", "p_status" "text", "p_outcome" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scale_scope_service"("p_actor" "uuid", "p_action" "text", "p_country_code" "text", "p_scope_type" "text" DEFAULT 'country'::"text", "p_scope_id" "uuid" DEFAULT NULL::"uuid", "p_wave_size" integer DEFAULT 0, "p_sample_size" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'catalogue', 'ref', 'security'
    AS $$
declare
  v_rank integer:=0;
  v_country_id uuid;
  v_scope text:=lower(coalesce(nullif(trim(p_scope_type),''),'country'));
  v_policy pipeline.layer2_execution_policy%rowtype;
  v_wave integer;
  v_sample integer;
  v_retry_hours integer;
  v_run uuid;
  v_provider_count integer:=0;
  v_course_count integer:=0;
  v_payload jsonb;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 if p_actor is null then raise exception 'actor required' using errcode='42501'; end if;
 select coalesce(max(role.rank),0) into v_rank
 from security.user_roles ur join security.roles role on role.code=ur.role_code
 where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and role.status='active';
 if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
 if v_scope not in ('country','state','university') then raise exception 'invalid scope type' using errcode='22023'; end if;
 if v_scope in ('state','university') and p_scope_id is null then raise exception 'scope id required' using errcode='22023'; end if;

 select * into v_policy from pipeline.layer2_execution_policy where policy_key='default' and enabled;
 if not found then raise exception 'Layer 2 execution policy missing' using errcode='55000'; end if;
 v_wave:=least(greatest(coalesce(nullif(p_wave_size,0),v_policy.qualification_provider_wave_size),1),v_policy.qualification_provider_wave_max);
 v_sample:=least(greatest(coalesce(nullif(p_sample_size,0),v_policy.qualification_sample_size),1),50);
 v_retry_hours:=v_policy.qualification_retry_hours;

 select id into v_country_id from ref.countries where upper(iso_alpha2::text)=upper(trim(p_country_code)) limit 1;
 if v_country_id is null then raise exception 'country not found' using errcode='22023'; end if;

 if p_action='preview' then
   with providers as (
     select p.id
     from catalogue.providers p
     where p.country_id=v_country_id
       and exists(select 1 from catalogue.courses c where c.provider_id=p.id)
       and (
         v_scope='country'
         or (v_scope='university' and p.id=p_scope_id)
         or (v_scope='state' and (
           p.subdivision_id=p_scope_id
           or exists(
             select 1 from catalogue.courses c
             join catalogue.course_campuses cc on cc.course_id=c.id
             join catalogue.campuses cam on cam.id=cc.campus_id
             where c.provider_id=p.id and cam.subdivision_id=p_scope_id
           )
         ))
       )
   ), status as (
     select p.id,
       exists(
         select 1 from pipeline.layer2_source_profiles lp
         join pipeline.sources s on s.id=lp.source_id
         join pipeline.layer2_source_profile_versions pv on pv.id=lp.current_version_id
         where s.provider_id=p.id and lp.domain='course_facts'
           and lp.authority_class<>'qualification_candidate'
           and lp.enabled and not lp.paused and pv.validation_status='valid'
       ) qualified,
       (select count(*) from catalogue.courses c where c.provider_id=p.id)::integer courses
     from providers p
   )
   select jsonb_build_object(
     'ok',true,'scope_source','layer1_catalogue','country_code',upper(trim(p_country_code)),
     'scope_type',v_scope,'scope_id',p_scope_id,
     'university_count',count(*)::integer,
     'catalogue_count',coalesce(sum(courses),0)::integer,
     'qualified_provider_count',count(*) filter(where qualified)::integer,
     'qualification_required_count',count(*) filter(where not qualified)::integer,
     'executable_course_count',coalesce(sum(courses) filter(where qualified),0)::integer,
     'qualification_course_count',coalesce(sum(courses) filter(where not qualified),0)::integer,
     'queueable_count',(
       select count(distinct c.id)::integer
       from providers pp join catalogue.courses c on c.provider_id=pp.id
       where exists(
         select 1 from pipeline.layer2_source_profiles lp
         join pipeline.sources s on s.id=lp.source_id
         join pipeline.layer2_source_profile_versions pv on pv.id=lp.current_version_id
         where s.provider_id=pp.id and lp.domain='course_facts'
           and lp.enabled and not lp.paused and pv.validation_status='valid'
       )
       and (
         nullif(c.course_url,'') is not null
         or exists(
           select 1 from pipeline.layer2_course_discovery_candidates dc
           join pipeline.layer2_source_profiles lp2 on lp2.current_version_id=dc.source_profile_version_id
           join pipeline.sources s2 on s2.id=lp2.source_id
           where dc.course_id=c.id and dc.selected and nullif(dc.discovered_url,'') is not null and s2.provider_id=pp.id
         )
       )
     ),
     'needs_discovery_count',(
       select count(distinct c.id)::integer
       from providers pp join catalogue.courses c on c.provider_id=pp.id
       where exists(
         select 1 from pipeline.layer2_source_profiles lp
         join pipeline.sources s on s.id=lp.source_id
         join pipeline.layer2_source_profile_versions pv on pv.id=lp.current_version_id
         where s.provider_id=pp.id and lp.domain='course_facts'
           and lp.enabled and not lp.paused and pv.validation_status='valid'
       )
       and nullif(c.course_url,'') is null
       and not exists(
         select 1 from pipeline.layer2_course_discovery_candidates dc
         join pipeline.layer2_source_profiles lp2 on lp2.current_version_id=dc.source_profile_version_id
         join pipeline.sources s2 on s2.id=lp2.source_id
         where dc.course_id=c.id and dc.selected and nullif(dc.discovered_url,'') is not null and s2.provider_id=pp.id
       )
     ),
     'active_run_count',(
       select count(*)::integer from pipeline.layer2_run_batches b
       join pipeline.layer2_source_profiles lp on lp.id=b.profile_id
       join pipeline.sources s on s.id=lp.source_id
       where b.status in ('queued','running')
         and s.provider_id in (select id from providers)
     ),
     'recommended_action',case when count(*) filter(where not qualified)>0 then 'qualify_wave' else 'sync' end,
     'wave_size',v_wave,'sample_size',v_sample
   ) into v_payload
   from status;
   return v_payload;
 end if;

 if p_action='qualify_wave' then
   insert into pipeline.layer2_scale_qualification_runs(
     country_id,scope_type,scope_id,requested_by,wave_size,sample_size,status,change_control_ref
   ) values(v_country_id,v_scope,p_scope_id,p_actor,v_wave,v_sample,'planned','CF-CHG-20260830-048')
   returning id into v_run;

   with eligible as (
     select p.id,p.canonical_name,(select count(*) from catalogue.courses c where c.provider_id=p.id) course_count
     from catalogue.providers p
     where p.country_id=v_country_id
       and exists(select 1 from catalogue.courses c where c.provider_id=p.id)
       and (
         v_scope='country'
         or (v_scope='university' and p.id=p_scope_id)
         or (v_scope='state' and (
           p.subdivision_id=p_scope_id
           or exists(
             select 1 from catalogue.courses c
             join catalogue.course_campuses cc on cc.course_id=c.id
             join catalogue.campuses cam on cam.id=cc.campus_id
             where c.provider_id=p.id and cam.subdivision_id=p_scope_id
           )
         ))
       )
       and not exists(
         select 1 from pipeline.layer2_source_profiles lp
         join pipeline.sources s on s.id=lp.source_id
         join pipeline.layer2_source_profile_versions pv on pv.id=lp.current_version_id
         where s.provider_id=p.id and lp.domain='course_facts'
           and lp.authority_class<>'qualification_candidate'
           and lp.enabled and not lp.paused and pv.validation_status='valid'
       )
       and not exists(
         select 1
         from pipeline.layer2_scale_qualification_items qi
         join pipeline.layer2_scale_qualification_runs qr on qr.id=qi.run_id
         where qi.provider_id=p.id
           and qr.status in ('planned','running')
       )
       and not exists(
         select 1
         from pipeline.layer2_scale_qualification_items qi2
         join pipeline.layer2_scale_qualification_runs qr2 on qr2.id=qi2.run_id
         where qi2.provider_id=p.id
           and qi2.status in ('source_pattern_candidate','source_limited','blocked','layer3_required','layer4_required')
           and qr2.created_at > now()-make_interval(hours=>v_retry_hours)
       )
     order by course_count desc,p.canonical_name,p.id
     limit v_wave
   ), samples as (
     select e.id provider_id,c.id course_id,
            row_number() over(partition by e.id order by
              case when nullif(c.course_url,'') is null then 0 else 1 end,
              c.stable_key,c.id
            )::integer sample_rank
     from eligible e
     join catalogue.courses c on c.provider_id=e.id
   )
   insert into pipeline.layer2_scale_qualification_items(run_id,provider_id,course_id,sample_rank,selection_reason)
   select v_run,provider_id,course_id,sample_rank,
          case when sample_rank<=greatest(1,least(2,v_sample)) then 'gap_first_control_mix' else 'layer1_gap_sample' end
   from samples where sample_rank<=v_sample
   order by provider_id,sample_rank;

   select count(distinct provider_id),count(*) into v_provider_count,v_course_count
   from pipeline.layer2_scale_qualification_items where run_id=v_run;

   if v_provider_count=0 then
     update pipeline.layer2_scale_qualification_runs
     set status='completed',completed_at=now(),result_summary=jsonb_build_object('outcome','nothing_to_qualify','background_scheduler_authorized',true,'auto_progress_scope',true,'qualification_identity_sample_only',true,'route_mode',v_policy.route_mode,'production_target_wave_size',v_policy.production_target_wave_size)
     where id=v_run;
   else
     update pipeline.layer2_scale_qualification_runs
     set provider_count=v_provider_count,course_sample_count=v_course_count,
         result_summary=jsonb_build_object(
           'outcome','sample_selected',
           'next_step','deterministic_source_qualification',
           'identity_safety_required',true,
           'background_scheduler_authorized',true,
           'auto_progress_scope',true,
           'qualification_identity_sample_only',true,
           'route_mode',v_policy.route_mode,
           'production_target_wave_size',v_policy.production_target_wave_size,
           'canonical_mutation_authorised',false,
           'search_mutation_authorised',false,
           'publication_mutation_authorised',false
         )
     where id=v_run;
   end if;

   return jsonb_build_object(
     'ok',true,'status',case when v_provider_count=0 then 'nothing_to_qualify' else 'qualification_wave_planned' end,
     'qualification_run_id',v_run,'provider_count',v_provider_count,'course_sample_count',v_course_count,
     'wave_size',v_wave,'sample_size',v_sample,'background_scheduled',true,'identity_sample_only',true,
     'canonical_mutation_authorised',false,'search_mutation_authorised',false,'publication_mutation_authorised',false
   );
 end if;

 raise exception 'unsupported action' using errcode='22023';
end $$;


ALTER FUNCTION "public"."layer2_scale_scope_service"("p_actor" "uuid", "p_action" "text", "p_country_code" "text", "p_scope_type" "text", "p_scope_id" "uuid", "p_wave_size" integer, "p_sample_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scholarship_catalogue_apply"("p_evidence_id" "uuid", "p_links" "jsonb" DEFAULT '[]'::"jsonb", "p_status" "text" DEFAULT 'captured'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'catalogue'
    AS $$
declare
  v_ctx jsonb;
  v_link jsonb;
  v_inserted integer:=0;
  v_total integer:=0;
  v_duplicates integer:=0;
  v_parent_candidate uuid;
  v_run uuid;
begin
  v_ctx:=public.layer2_scholarship_extraction_context(p_evidence_id);
  if v_ctx is null or v_ctx='null'::jsonb then raise exception 'evidence_not_found' using errcode='P0002'; end if;
  if v_ctx->>'evidence_type'<>'layer2_extraction_input' then raise exception 'layer2_extraction_input_required' using errcode='23514'; end if;
  if p_status not in('captured','complete','partial','needs_review','failed') then raise exception 'invalid_catalogue_status' using errcode='23514'; end if;

  for v_link in select value from jsonb_array_elements(coalesce(p_links,'[]'::jsonb))
  loop
    v_total:=v_total+1;
    insert into pipeline.layer2_scholarship_discovery_candidates(
      source_id,evidence_id,source_profile_version_id,scholarship_url,observed_title,status
    ) values(
      (v_ctx->>'source_id')::uuid,
      p_evidence_id,
      nullif(v_ctx->>'source_profile_version_id','')::uuid,
      v_link->>'url',
      nullif(v_link->>'title',''),
      'discovered'
    )
    on conflict(evidence_id,scholarship_url) do nothing;
    if found then v_inserted:=v_inserted+1; else v_duplicates:=v_duplicates+1; end if;
  end loop;

  insert into pipeline.scholarship_catalogue_runs(
    source_id,evidence_id,source_profile_version_id,provider_id,content_hash,
    discovered_count,unique_candidate_count,duplicate_count,status,metadata
  ) values(
    (v_ctx->>'source_id')::uuid,
    p_evidence_id,
    nullif(v_ctx->>'source_profile_version_id','')::uuid,
    nullif(v_ctx->>'provider_id','')::uuid,
    v_ctx->>'content_hash',
    v_total,v_inserted,v_duplicates,p_status,
    coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object(
      'source_url',v_ctx->>'source_url',
      'source_label',v_ctx->>'source_label',
      'change_control_ref','CF-CHG-20260903-083'
    )
  )
  on conflict(source_id,evidence_id) do update set
    discovered_count=excluded.discovered_count,
    unique_candidate_count=excluded.unique_candidate_count,
    duplicate_count=excluded.duplicate_count,
    status=excluded.status,
    metadata=excluded.metadata,
    observed_at=now()
  returning id into v_run;

  begin
    v_parent_candidate:=nullif(v_ctx->'source_metadata'->>'candidate_id','')::uuid;
  exception when others then v_parent_candidate:=null; end;

  if v_parent_candidate is not null then
    update pipeline.layer2_scholarship_discovery_candidates
    set status='acquired'
    where id=v_parent_candidate and status='discovered';
  end if;

  return jsonb_build_object(
    'run_id',v_run,
    'provider_id',v_ctx->>'provider_id',
    'source_id',v_ctx->>'source_id',
    'discovered_count',v_total,
    'inserted_count',v_inserted,
    'duplicate_count',v_duplicates,
    'status',p_status
  );
end $$;


ALTER FUNCTION "public"."layer2_scholarship_catalogue_apply"("p_evidence_id" "uuid", "p_links" "jsonb", "p_status" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scholarship_discovery_record"("p_evidence_id" "uuid", "p_urls" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare e pipeline.evidence_artifacts%rowtype;x jsonb;n integer:=0;v_url text;v_title text;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 select * into e from pipeline.evidence_artifacts where id=p_evidence_id;if not found then raise exception 'evidence not found';end if;
 for x in select * from jsonb_array_elements(coalesce(p_urls,'[]'::jsonb)) loop
  v_url:=nullif(x->>'url','');v_title:=nullif(x->>'title','');if v_url is null then continue;end if;
  insert into pipeline.layer2_scholarship_discovery_candidates(source_id,evidence_id,source_profile_version_id,scholarship_url,observed_title)
  values(e.source_id,e.id,e.source_profile_version_id,v_url,v_title) on conflict(evidence_id,scholarship_url) do nothing;
  if found then n:=n+1;end if;
 end loop;return n;
end $$;


ALTER FUNCTION "public"."layer2_scholarship_discovery_record"("p_evidence_id" "uuid", "p_urls" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scholarship_extraction_context"("p_evidence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'catalogue'
    AS $$
 select jsonb_build_object(
   'id',e.id,
   'source_id',e.source_id,
   'job_id',e.job_id,
   'evidence_type',e.evidence_type,
   'source_url',e.source_url,
   'storage_path',e.storage_path,
   'content_hash',e.content_hash,
   'mime_type',e.mime_type,
   'source_profile_version_id',e.source_profile_version_id,
   'metadata',e.metadata,
   'provider_id',s.provider_id,
   'provider_name',p.canonical_name,
   'source_type',s.source_type,
   'source_label',s.label,
   'source_metadata',s.metadata
 )
 from pipeline.evidence_artifacts e
 join pipeline.sources s on s.id=e.source_id
 left join catalogue.providers p on p.id=s.provider_id
 where e.id=p_evidence_id
$$;


ALTER FUNCTION "public"."layer2_scholarship_extraction_context"("p_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scope_countries_service"("p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref', 'security'
    AS $$
declare v_rank integer:=0; v_items jsonb;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 if p_actor is null then raise exception 'actor required' using errcode='42501'; end if;
 select coalesce(max(role.rank),0) into v_rank
 from security.user_roles ur join security.roles role on role.code=ur.role_code
 where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and role.status='active';
 if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;

 select coalesce(jsonb_agg(jsonb_build_object(
   'code',x.code,'name',x.name,'providers',x.providers,'courses',x.courses
 ) order by x.name),'[]'::jsonb)
 into v_items
 from (
   select co.iso_alpha2::text code,co.name,
          count(distinct p.id)::integer providers,
          count(distinct c.id)::integer courses
   from catalogue.providers p
   join catalogue.courses c on c.provider_id=p.id
   join ref.countries co on co.id=p.country_id
   group by co.iso_alpha2,co.name
 ) x;
 return jsonb_build_object('countries',v_items,'scope_source','layer1_catalogue');
end $$;


ALTER FUNCTION "public"."layer2_scope_countries_service"("p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scope_courses"("p_country_code" "text", "p_scope_type" "text", "p_scope_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("profile_id" "uuid", "profile_key" "text", "provider_id" "uuid", "provider_name" "text", "course_id" "uuid", "source_url" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'ref'
    AS $$
  select lp.id,lp.profile_key,cp.id,cp.canonical_name,c.id,
         coalesce(nullif(dc.discovered_url,''),nullif(c.course_url,'')) as source_url
  from pipeline.layer2_source_profiles lp
  join pipeline.sources s on s.id=lp.source_id
  join ref.countries country on country.id=s.country_id
  join catalogue.providers cp on cp.id=s.provider_id
  join catalogue.courses c on c.provider_id=cp.id
  left join lateral (
    select d.discovered_url
    from pipeline.layer2_course_discovery_candidates d
    where d.course_id=c.id
      and d.source_profile_version_id=lp.current_version_id
      and d.selected=true
      and nullif(d.discovered_url,'') is not null
    order by d.created_at desc
    limit 1
  ) dc on true
  where lp.domain='course_facts'
    and lp.enabled and not lp.paused
    and upper(country.iso_alpha2::text)=upper(p_country_code)
    and (
      lower(p_scope_type)='country'
      or (lower(p_scope_type)='university' and cp.id=p_scope_id)
      or (lower(p_scope_type)='state' and exists(
        select 1
        from catalogue.course_campuses ccx
        join catalogue.campuses cam on cam.id=ccx.campus_id
        where ccx.course_id=c.id and cam.subdivision_id=p_scope_id
      ))
    )
$$;


ALTER FUNCTION "public"."layer2_scope_courses"("p_country_code" "text", "p_scope_type" "text", "p_scope_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_scope_options_page_service"("p_actor" "uuid", "p_country_code" "text", "p_kind" "text", "p_state_id" "uuid" DEFAULT NULL::"uuid", "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'catalogue', 'ref', 'security'
    AS $$
declare
  v_rank integer:=0;
  v_kind text:=lower(coalesce(nullif(trim(p_kind),''),''));
  v_country text:=upper(coalesce(nullif(trim(p_country_code),''),''));
  v_query text:=lower(nullif(trim(coalesce(p_query,'')),''));
  v_limit integer:=least(greatest(coalesce(p_limit,10),1),10);
  v_offset integer:=greatest(coalesce(p_offset,0),0);
  v_items jsonb:='[]'::jsonb;
  v_total integer:=0;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 if p_actor is null then raise exception 'actor required' using errcode='42501'; end if;
 select coalesce(max(role.rank),0) into v_rank
 from security.user_roles ur join security.roles role on role.code=ur.role_code
 where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and role.status='active';
 if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
 if v_country='' then raise exception 'country required' using errcode='22023'; end if;

 if v_kind='state' then
   with q as (
     select sd.id::text value,sd.name label,sd.code meta
     from ref.subdivisions sd
     join ref.countries co on co.id=sd.country_id
     where upper(co.iso_alpha2::text)=v_country
       and (v_query is null or lower(sd.name||' '||coalesce(sd.code,'')) like '%'||v_query||'%')
       and exists (
         select 1
         from catalogue.providers p
         join catalogue.courses c on c.provider_id=p.id
         where p.country_id=co.id
           and (
             p.subdivision_id=sd.id
             or exists (
               select 1 from catalogue.course_campuses cc
               join catalogue.campuses cam on cam.id=cc.campus_id
               where cc.course_id=c.id and cam.subdivision_id=sd.id
             )
           )
       )
   ), n as (select count(*) total from q),
   page as (select * from q order by lower(label),value limit v_limit offset v_offset)
   select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta) order by lower(label),value) from page),'[]'::jsonb),
          coalesce((select total from n),0)
   into v_items,v_total;

 elsif v_kind='university' then
   with q as (
     select p.id::text value,p.canonical_name label,
            case when exists(
              select 1 from pipeline.layer2_source_profiles lp
              join pipeline.sources s on s.id=lp.source_id
              left join pipeline.layer2_source_profile_versions pv on pv.id=lp.current_version_id
              where s.provider_id=p.id and lp.domain='course_facts'
                and lp.enabled and not lp.paused and pv.validation_status='valid'
            ) then 'Qualified for Layer 2' else 'Needs Layer 2 qualification' end meta
     from catalogue.providers p
     join ref.countries co on co.id=p.country_id
     where upper(co.iso_alpha2::text)=v_country
       and exists(select 1 from catalogue.courses c where c.provider_id=p.id)
       and (
         p_state_id is null
         or p.subdivision_id=p_state_id
         or exists(
           select 1 from catalogue.courses c
           join catalogue.course_campuses cc on cc.course_id=c.id
           join catalogue.campuses cam on cam.id=cc.campus_id
           where c.provider_id=p.id and cam.subdivision_id=p_state_id
         )
       )
       and (v_query is null or lower(coalesce(p.canonical_name,'')||' '||coalesce(p.display_name,'')) like '%'||v_query||'%')
   ), n as (select count(*) total from q),
   page as (select * from q order by lower(label),value limit v_limit offset v_offset)
   select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta) order by lower(label),value) from page),'[]'::jsonb),
          coalesce((select total from n),0)
   into v_items,v_total;
 else
   raise exception 'unsupported scope option kind' using errcode='22023';
 end if;

 return jsonb_build_object('items',v_items,'total',v_total,'limit',v_limit,'offset',v_offset,'has_more',(v_offset+jsonb_array_length(v_items))<v_total,'scope_source','layer1_catalogue');
end $$;


ALTER FUNCTION "public"."layer2_scope_options_page_service"("p_actor" "uuid", "p_country_code" "text", "p_kind" "text", "p_state_id" "uuid", "p_query" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_screenshot_backfill_attach"("p_attempt_id" "uuid", "p_screenshot_evidence_id" "uuid", "p_metrics" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 update pipeline.layer2_provider_attempts
 set screenshot_evidence_id=p_screenshot_evidence_id,
     metrics=coalesce(metrics,'{}'::jsonb)||coalesce(p_metrics,'{}'::jsonb)
 where id=p_attempt_id;
end $$;


ALTER FUNCTION "public"."layer2_screenshot_backfill_attach"("p_attempt_id" "uuid", "p_screenshot_evidence_id" "uuid", "p_metrics" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_screenshot_backfill_context"("p_evidence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v jsonb;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 select jsonb_build_object(
   'evidence_id',e.id,
   'source_id',e.source_id,
   'source_url',e.source_url,
   'job_id',e.job_id,
   'profile_version_id',e.source_profile_version_id,
   'attempt_id',pa.id,
   'existing_screenshot_evidence_id',pa.screenshot_evidence_id
 ) into v
 from pipeline.evidence_artifacts e
 join pipeline.layer2_provider_attempts pa
   on e.id in (pa.raw_evidence_id,pa.html_evidence_id)
   or pa.id::text=coalesce(e.metadata->>'attempt_id','')
 where e.id=p_evidence_id
 order by pa.completed_at desc nulls last
 limit 1;
 return coalesce(v,'{}'::jsonb);
end $$;


ALTER FUNCTION "public"."layer2_screenshot_backfill_context"("p_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer2_shared_fetch_fanout_context"("p_shared_fetch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'catalogue'
    AS $$
 select jsonb_build_object(
   'shared_fetch_id',f.id,
   'source_url',f.source_url,
   'evidence_id',e.id,
   'storage_path',e.storage_path,
   'mime_type',coalesce(e.mime_type,f.mime_type),
   'content_hash',coalesce(e.content_hash,f.content_hash),
   'source_id',e.source_id,
   'provider_id',s.provider_id,
   'provider_name',p.canonical_name,
   'logo_profile_id',(select lp.id from pipeline.layer2_source_profiles lp where lp.source_id=e.source_id and lp.domain='provider_asset' and lp.enabled and not lp.paused order by lp.updated_at desc limit 1),
   'scholarship_profile_id',(select sp.id from pipeline.layer2_source_profiles sp where sp.source_id=e.source_id and sp.domain='scholarship' and sp.enabled and not sp.paused order by sp.updated_at desc limit 1),
   'scholarship_profile_version_id',(select sp.current_version_id from pipeline.layer2_source_profiles sp where sp.source_id=e.source_id and sp.domain='scholarship' and sp.enabled and not sp.paused order by sp.updated_at desc limit 1)
 )
 from pipeline.layer2_shared_fetches f
 join pipeline.evidence_artifacts e on e.id=f.evidence_id
 join pipeline.sources s on s.id=e.source_id
 join catalogue.providers p on p.id=s.provider_id
 where f.id=p_shared_fetch_id
$$;


