CREATE OR REPLACE FUNCTION "public"."layer3_authorize_corrective_retry_service"("p_work_item_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$ declare v_caller text; v_ok boolean; begin v_caller:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.role',true),''),session_user); if v_caller not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; if nullif(trim(p_reason),'') is null then raise exception 'corrective retry reason required'; end if; update pipeline.layer3_work_items set corrective_retry_count=corrective_retry_count+1,corrective_retry_reason=left(trim(p_reason),2000),corrective_retry_authorized_at=now(),status='pending',available_at=now(),completed_at=null,reserved_at=null,reserved_by=null,last_error=null,updated_at=now() where id=p_work_item_id and status in ('layer4_required','parked','pending') and attempt_count>=5 and corrective_retry_count=0; v_ok:=found; return jsonb_build_object('ok',v_ok,'work_item_id',p_work_item_id,'attempt_count',(select attempt_count from pipeline.layer3_work_items where id=p_work_item_id),'corrective_retry_count',(select corrective_retry_count from pipeline.layer3_work_items where id=p_work_item_id)); end $$;


