  where id=p.id;
  return jsonb_build_object('ok',true,'pass',v_pass,'run_id',v_run,'profile_paused',true,'provider_cases_pass',v_provider_ok,'controls_pass',v_controls_ok,'model_exact',v_model_ok,'cost_pass',v_cost_ok);
