COMMENT ON FUNCTION "public"."layer3_contact_benchmark_record_service"("p_pass" boolean, "p_provider_cases" "jsonb", "p_control_cases" "jsonb", "p_returned_models" "text"[], "p_external_call_count" integer, "p_input_tokens" integer, "p_output_tokens" integer, "p_estimated_cost_usd" numeric, "p_max_latency_ms" integer, "p_evidence_ids" "uuid"[], "p_summary" "text") IS 'A16 contact-specific quality gate. Profile becomes executable only when real first-party Evidence cases, anti-hallucination controls, exact-model and cost checks all pass.';



CREATE OR REPLACE FUNCTION "public"."layer3_contract_freeze_record_service"("p_task_class" "text", "p_version" "text", "p_fingerprint" "text", "p_components" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v pipeline.layer3_task_contract_freezes%rowtype;
begin
  perform public.layer3_routing_service_guard();
  insert into pipeline.layer3_task_contract_freezes(task_class,contract_version,fingerprint,components) values (p_task_class,p_version,p_fingerprint,coalesce(p_components,'{}'))
  on conflict (task_class,contract_version) do nothing;
  select * into v from pipeline.layer3_task_contract_freezes where task_class=p_task_class and contract_version=p_version;
  return jsonb_build_object('task_class',v.task_class,'contract_version',v.contract_version,'fingerprint',v.fingerprint,'frozen_at',v.frozen_at,'matches',v.fingerprint=p_fingerprint);
end $$;


