CREATE OR REPLACE FUNCTION "public"."layer3_fail_interpretation_service"("p_interpretation_id" "uuid", "p_error" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin update pipeline.layer3_interpretations set status='provider_error',validator_result=jsonb_build_object('provider_error',left(coalesce(p_error,'unknown'),2000)),call_completed_at=now() where id=p_interpretation_id and status in ('reserved','calling'); end $$;


ALTER FUNCTION "public"."layer3_fail_interpretation_service"("p_interpretation_id" "uuid", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer3_fail_interpretation_service"("p_interpretation_id" "uuid", "p_error" "text", "p_external_call_count" integer, "p_call_latency_ms" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_profile uuid; v_hash text; v_run text;
begin
  if p_external_call_count is not null and p_external_call_count<0 then raise exception 'invalid external call count'; end if;
  if p_call_latency_ms is not null and p_call_latency_ms<0 then raise exception 'invalid call latency'; end if;
  update pipeline.layer3_interpretations
  set status='provider_error',
      validator_result=jsonb_build_object('provider_error',left(coalesce(p_error,'unknown'),2000)),
      external_call_count=p_external_call_count,
      call_latency_ms=p_call_latency_ms,
      call_completed_at=now()
  where id=p_interpretation_id and status in ('reserved','calling');
  -- CF-247: a binding mismatch means the deployed code or profile no longer matches
  -- what was qualified. Execution already refuses; pause the profile so its state
  -- never shows "active" while it is refusing every item.
  if coalesce(p_error,'') ilike '%binding hash does not match%' then
    select profile_id into v_profile from pipeline.layer3_interpretations where id=p_interpretation_id;
    if v_profile is not null then
      update pipeline.layer3_model_profiles
      set paused=true,
          last_validation_result=coalesce(last_validation_result,'{}'::jsonb)||jsonb_build_object('auto_paused_at',now(),'auto_pause_reason','binding hash drift detected at execution'),
          updated_at=now()
      where id=v_profile and not paused
      returning quality_benchmark->>'binding_hash', quality_benchmark->>'run_id' into v_hash, v_run;
      if found then
        insert into pipeline.layer3_profile_activation_events(profile_id, action, reason, binding_hash, benchmark_run_id, checks)
        values (v_profile, 'auto_paused_binding_drift', 'binding hash drift detected at execution', v_hash, v_run,
                jsonb_build_object('interpretation_id', p_interpretation_id, 'error', left(p_error,500)));
      end if;
    end if;
  end if;
end $$;


ALTER FUNCTION "public"."layer3_fail_interpretation_service"("p_interpretation_id" "uuid", "p_error" "text", "p_external_call_count" integer, "p_call_latency_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer3_fallback_profile_service"("p_profile_id" "uuid", "p_task_class" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_f pipeline.layer3_model_profiles%rowtype;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  select f.* into v_f
  from pipeline.layer3_model_profiles p
  join pipeline.layer3_model_profiles f on f.id=p.fallback_profile_id
  where p.id=p_profile_id
    and f.enabled and not f.paused
    and p_task_class=any(f.allowed_task_classes)
    and coalesce((f.quality_benchmark->>'pass')::boolean,false) is true;
  if not found then return null; end if;
  return jsonb_build_object(
    'id',v_f.id,'aggregator_provider',v_f.aggregator_provider,'base_url',v_f.base_url,
    'model_identifier',v_f.model_identifier,'secret_env_key',v_f.secret_env_key,
    'prompt_profile_version',v_f.prompt_profile_version,'prompt_system',v_f.prompt_system,
    'validators',v_f.deterministic_validators,'max_output_tokens',v_f.max_output_tokens,
    'retry_ceiling',v_f.retry_ceiling,'timeout_ms',v_f.timeout_ms,'cost_ceiling_usd',v_f.cost_ceiling_usd
  );
end $$;


