CREATE OR REPLACE FUNCTION "public"."layer3_reserve_interpretation_service"("p_actor" "uuid", "p_evidence_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_task_class" "text", "p_profile_id" "uuid", "p_layer2_state" "jsonb" DEFAULT '{}'::"jsonb", "p_revalidation_ref" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare
  v_rank int:=0; v_ev pipeline.evidence_artifacts%rowtype; v_p pipeline.layer3_model_profiles%rowtype;
  v_prev pipeline.layer3_interpretations%rowtype; v_active pipeline.layer3_interpretations%rowtype; v_reason text; v_id uuid; v_selection text;
begin
  if p_actor is null then raise exception 'actor required' using errcode='42501'; end if;
  select coalesce(max(r.rank),0) into v_rank
  from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=p_actor and r.status='active' and (ur.expires_at is null or ur.expires_at>now());
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
  if security.layer4_entity_or_parent_blocked(lower(p_entity_type),p_entity_id,'operational') then
    return jsonb_build_object('call_required',false,'reason','layer4_operational_block','entity_type',lower(p_entity_type),'entity_id',p_entity_id);
  end if;

  select * into v_ev from pipeline.evidence_artifacts where id=p_evidence_id;
  if not found or v_ev.content_hash is null then raise exception 'governed evidence with content hash required'; end if;

  select * into v_p from pipeline.layer3_model_profiles where id=p_profile_id;
  if not found then raise exception 'model profile not found'; end if;
  if not v_p.enabled or v_p.paused then raise exception 'model profile not executable'; end if;
  if coalesce((v_p.quality_benchmark->>'pass')::boolean,false) is not true then
    raise exception 'model profile quality benchmark not passed';
  end if;
  if not (p_task_class=any(v_p.allowed_task_classes)) then raise exception 'task class not allowed by profile'; end if;

  if coalesce(p_layer2_state->>'status','')='resolved_l2' then
    return jsonb_build_object('call_required',false,'reason','layer2_resolved','evidence_hash',v_ev.content_hash);
  end if;

  perform pg_advisory_xact_lock(hashtext(lower(p_entity_type)||':'||p_entity_id::text||':'||p_task_class||':'||p_profile_id::text));
  select * into v_active
  from pipeline.layer3_interpretations
  where entity_type=lower(p_entity_type) and entity_id=p_entity_id and task_class=p_task_class
    and profile_id=p_profile_id and status in ('reserved','calling')
  order by created_at desc limit 1;
  if found then
    return jsonb_build_object('call_required',false,'reason','in_flight','prior_interpretation_id',v_active.id,'evidence_hash',v_active.evidence_hash);
  end if;

  select * into v_prev
  from pipeline.layer3_interpretations
  where entity_type=lower(p_entity_type) and entity_id=p_entity_id and task_class=p_task_class
    and profile_id=p_profile_id and status in ('validated','low_confidence','no_candidate')
  order by created_at desc limit 1;

  if p_revalidation_ref is not null then
    if length(trim(p_revalidation_ref))<5 then raise exception 'governed revalidation reference required'; end if;
    v_reason:='governed_revalidation';
  elsif found and v_prev.evidence_hash=v_ev.content_hash
        and (v_prev.interpretation_expires_at is null or v_prev.interpretation_expires_at>now()) then
    return jsonb_build_object(
      'call_required',false,'reason','unchanged_evidence',
      'prior_interpretation_id',v_prev.id,'evidence_hash',v_ev.content_hash
    );
  elsif found and v_prev.evidence_hash<>v_ev.content_hash then v_reason:='changed_evidence';
  elsif found and v_prev.interpretation_expires_at is not null and v_prev.interpretation_expires_at<=now() then v_reason:='freshness_expired';
  elsif coalesce(p_layer2_state->>'status','') in ('unresolved','blocked','partial','escalated_l3','layer3_required') then v_reason:='layer2_unresolved';
  else v_reason:='new_evidence';
  end if;

  v_selection:=nullif(p_layer2_state->>'evidence_selection_reason','');

  insert into pipeline.layer3_interpretations(
    evidence_id,evidence_hash,entity_type,entity_id,task_class,profile_id,prompt_profile_version,
    eligibility_reason,revalidation_ref,layer2_state,requested_by,selected_evidence_reason,
    change_control_ref,uat_ref
  ) values(
    p_evidence_id,v_ev.content_hash,lower(p_entity_type),p_entity_id,p_task_class,p_profile_id,
    v_p.prompt_profile_version,v_reason,p_revalidation_ref,coalesce(p_layer2_state,'{}'::jsonb),
    p_actor,v_selection,'CF-CHG-20260829-047','M2.4.3-layer3-operations'
  ) returning id into v_id;

  return jsonb_build_object(
    'call_required',true,'interpretation_id',v_id,'eligibility_reason',v_reason,
    'evidence_hash',v_ev.content_hash,'selected_evidence_reason',v_selection,
    'profile',jsonb_build_object(
      'id',v_p.id,'aggregator_provider',v_p.aggregator_provider,'base_url',v_p.base_url,
      'model_identifier',v_p.model_identifier,'secret_env_key',v_p.secret_env_key,
      'prompt_profile_version',v_p.prompt_profile_version,'prompt_system',v_p.prompt_system,
      'schema',v_p.structured_output_schema,'validators',v_p.deterministic_validators,
      'max_input_tokens',v_p.max_input_tokens,'max_output_tokens',v_p.max_output_tokens,
      'requests_per_minute',v_p.requests_per_minute,'requests_per_day',v_p.requests_per_day,
      'retry_ceiling',v_p.retry_ceiling,'timeout_ms',v_p.timeout_ms,
      'cost_ceiling_usd',v_p.cost_ceiling_usd,'fallback_profile_id',v_p.fallback_profile_id
    )
  );
end $$;


ALTER FUNCTION "public"."layer3_reserve_interpretation_service"("p_actor" "uuid", "p_evidence_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_task_class" "text", "p_profile_id" "uuid", "p_layer2_state" "jsonb", "p_revalidation_ref" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."layer3_reserve_interpretation_service"("p_actor" "uuid", "p_evidence_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_task_class" "text", "p_profile_id" "uuid", "p_layer2_state" "jsonb", "p_revalidation_ref" "text") IS 'M2.4.3 governed reservation. A16 contact profiles remain non-executable until their task-specific quality_benchmark.pass=true; no unrelated benchmark may qualify international_contact.';



CREATE OR REPLACE FUNCTION "public"."layer3_reserve_scoped_work_service"("p_worker" "text", "p_task_class" "text", "p_profile_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_result jsonb; v_caller text; v_p pipeline.layer3_model_profiles%rowtype;
begin
  v_caller:=coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.role',true),''),
    nullif((nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role'),''),
    session_user
  );
  if v_caller not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  if nullif(trim(p_worker),'') is null then raise exception 'worker required'; end if;
  if nullif(trim(p_task_class),'') is null then raise exception 'task class required'; end if;
  if p_profile_id is null then raise exception 'profile id required'; end if;

  select * into v_p from pipeline.layer3_model_profiles where id=p_profile_id for update;
  if not found then raise exception 'model profile not found'; end if;
  if not v_p.enabled or v_p.paused then raise exception 'model profile not executable'; end if;
  if coalesce((v_p.quality_benchmark->>'pass')::boolean,false) is not true then
    raise exception 'model profile quality benchmark not passed';
  end if;
  if not (trim(p_task_class)=any(v_p.allowed_task_classes)) then
    raise exception 'task class not allowed by profile';
  end if;

  update pipeline.layer3_work_items
  set status=case when attempt_count>=5 and corrective_retry_authorized_at is null then 'parked' else 'pending' end,
      available_at=case when attempt_count>=5 and corrective_retry_authorized_at is null then available_at else now() end,
      completed_at=case when attempt_count>=5 and corrective_retry_authorized_at is null then now() else null end,
      last_error=case when attempt_count>=5 and corrective_retry_authorized_at is null then 'reservation lease expired after maximum attempts' else 'reservation lease expired; requeued' end,
      reserved_at=null,reserved_by=null,updated_at=now()
  where status='reserved' and reserved_at < now()-interval '15 minutes'
    and task_class=trim(p_task_class) and profile_id=p_profile_id;

  with picked as (
    select w.id
    from pipeline.layer3_work_items w
    where w.status in ('pending','failed') and w.available_at<=now()
      and w.task_class=trim(p_task_class) and w.profile_id=p_profile_id
      and (w.attempt_count<5 or (w.corrective_retry_count=1 and w.corrective_retry_authorized_at is not null))
    order by w.created_at,w.id
    for update of w skip locked
    limit least(greatest(coalesce(p_limit,10),1),50)
  ), reserved as (
    update pipeline.layer3_work_items w set status='reserved',reserved_at=now(),reserved_by=trim(p_worker),attempt_count=w.attempt_count+1,
      corrective_retry_authorized_at=null,updated_at=now()
    from picked where w.id=picked.id
    returning w.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'layer2_run_item_id',layer2_run_item_id,'evidence_id',evidence_id,'entity_type',entity_type,'entity_id',entity_id,
    'task_class',task_class,'profile_id',profile_id,'attempt_count',attempt_count,'reason',reason,'policy_version',policy_version,
    'corrective_retry_count',corrective_retry_count,'corrective_retry_reason',corrective_retry_reason
  ) order by created_at,id),'[]'::jsonb) into v_result from reserved;
  return v_result;
end $$;


ALTER FUNCTION "public"."layer3_reserve_scoped_work_service"("p_worker" "text", "p_task_class" "text", "p_profile_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer3_reserve_work_interpretation_service"("p_work_item_id" "uuid", "p_worker" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare
  v_caller text;
  v_work pipeline.layer3_work_items%rowtype;
  v_ev pipeline.evidence_artifacts%rowtype;
  v_p pipeline.layer3_model_profiles%rowtype;
  v_interpretation_id uuid;
begin
  v_caller:=coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role',
    auth.role(),
    session_user
  );
  if v_caller not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  if p_work_item_id is null then raise exception 'work_item_id required'; end if;
  if nullif(trim(p_worker),'') is null then raise exception 'worker required'; end if;

  select * into v_work
  from pipeline.layer3_work_items
  where id=p_work_item_id
  for update;
  if not found then raise exception 'Layer 3 work item not found'; end if;
  if v_work.status<>'reserved' then raise exception 'Layer 3 work item must be reserved'; end if;
  if coalesce(v_work.reserved_by,'')<>trim(p_worker) then raise exception 'Layer 3 work reservation owner mismatch'; end if;
  if v_work.profile_id is null then raise exception 'Layer 3 work item profile required'; end if;
  if coalesce(jsonb_typeof(v_work.candidate_context),'null')<>'object' or v_work.candidate_context='{}'::jsonb then
    raise exception 'persisted candidate_context required';
  end if;

  select * into v_ev from pipeline.evidence_artifacts where id=v_work.evidence_id;
  if not found or v_ev.content_hash is null or v_ev.storage_path is null then
    raise exception 'retained governed Evidence required';
  end if;

  select * into v_p from pipeline.layer3_model_profiles where id=v_work.profile_id;
  if not found then raise exception 'model profile not found'; end if;
  if not v_p.enabled or v_p.paused then raise exception 'model profile not executable'; end if;
  if coalesce((v_p.quality_benchmark->>'pass')::boolean,false) is not true then
    raise exception 'model profile quality benchmark not passed';
  end if;
  if not (v_work.task_class=any(v_p.allowed_task_classes)) then
    raise exception 'task class not allowed by profile';
  end if;

  insert into pipeline.layer3_interpretations(
    evidence_id,evidence_hash,entity_type,entity_id,task_class,profile_id,
    prompt_profile_version,eligibility_reason,revalidation_ref,layer2_state,
    requested_by,selected_evidence_reason,change_control_ref,uat_ref
  ) values(
    v_work.evidence_id,v_ev.content_hash,v_work.entity_type,v_work.entity_id,
    v_work.task_class,v_work.profile_id,v_p.prompt_profile_version,
    'layer2_unresolved',null,
    jsonb_build_object(
      'status','layer3_required',
      'layer2_run_item_id',v_work.layer2_run_item_id,
      'work_item_id',v_work.id,
      'reason',v_work.reason,
      'candidate_context',v_work.candidate_context,
      'policy_version',v_work.policy_version
    ),
    null,v_work.reason,'CF-CHG-20260915-247','M2.4.7-layer3-work-dispatch'
  ) returning id into v_interpretation_id;

  update pipeline.layer3_work_items
  set status='interpreting',interpretation_id=v_interpretation_id,updated_at=now()
  where id=v_work.id and status='reserved' and reserved_by=trim(p_worker);
  if not found then raise exception 'Layer 3 work transition to interpreting failed'; end if;

  return jsonb_build_object(
    'call_required',true,
    'work_item_id',v_work.id,
    'interpretation_id',v_interpretation_id,
    'evidence_id',v_work.evidence_id,
    'attempt_count',v_work.attempt_count,
    'entity_type',v_work.entity_type,
    'entity_id',v_work.entity_id,
    'task_class',v_work.task_class,
    'candidate_context',v_work.candidate_context,
    'evidence',jsonb_build_object(
      'id',v_ev.id,
      'storage_path',v_ev.storage_path,
      'mime_type',v_ev.mime_type,
      'content_hash',v_ev.content_hash,
      'source_url',v_ev.source_url
    ),
    'profile',jsonb_build_object(
      'id',v_p.id,'aggregator_provider',v_p.aggregator_provider,'base_url',v_p.base_url,
      'model_identifier',v_p.model_identifier,'secret_env_key',v_p.secret_env_key,
      'prompt_profile_version',v_p.prompt_profile_version,'prompt_system',v_p.prompt_system,
      'schema',v_p.structured_output_schema,'validators',v_p.deterministic_validators,
      'max_input_tokens',v_p.max_input_tokens,'max_output_tokens',v_p.max_output_tokens,
      'requests_per_minute',v_p.requests_per_minute,'requests_per_day',v_p.requests_per_day,
      'retry_ceiling',v_p.retry_ceiling,'timeout_ms',v_p.timeout_ms,
      'cost_ceiling_usd',v_p.cost_ceiling_usd,'fallback_profile_id',v_p.fallback_profile_id,
      'quality_benchmark',v_p.quality_benchmark
    )
  );
end $$;


