CREATE OR REPLACE FUNCTION "public"."layer3_usage_window_service"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
with live as (
  select
    coalesce(sum(external_call_count) filter(where created_at>=now()-interval '1 minute' and status<>'cancelled'),0)::integer minute_calls,
    coalesce(sum(external_call_count) filter(where created_at>=date_trunc('day',now()) and status<>'cancelled'),0)::integer day_calls,
    coalesce(sum(estimated_cost_usd) filter(where created_at>=date_trunc('day',now())),0)::numeric day_cost_usd,
    coalesce(sum(input_tokens) filter(where created_at>=date_trunc('day',now())),0)::bigint day_input_tokens,
    coalesce(sum(output_tokens) filter(where created_at>=date_trunc('day',now())),0)::bigint day_output_tokens
  from pipeline.layer3_interpretations
  where profile_id=p_profile_id
),
bench as (
  select
    coalesce(sum(external_call_count) filter(where created_at>=now()-interval '1 minute'),0)::integer minute_calls,
    coalesce(sum(external_call_count) filter(where created_at>=date_trunc('day',now())),0)::integer day_calls,
    coalesce(sum(estimated_cost_usd) filter(where created_at>=date_trunc('day',now())),0)::numeric day_cost_usd,
    coalesce(sum(input_tokens) filter(where created_at>=date_trunc('day',now())),0)::bigint day_input_tokens,
    coalesce(sum(output_tokens) filter(where created_at>=date_trunc('day',now())),0)::bigint day_output_tokens
  from pipeline.layer3_quality_benchmark_runs
  where profile_id=p_profile_id
)
select jsonb_build_object(
  'minute_calls',live.minute_calls+bench.minute_calls,
  'day_calls',live.day_calls+bench.day_calls,
  'day_cost_usd',live.day_cost_usd+bench.day_cost_usd,
  'day_input_tokens',live.day_input_tokens+bench.day_input_tokens,
  'day_output_tokens',live.day_output_tokens+bench.day_output_tokens,
  'live_day_calls',live.day_calls,
  'benchmark_day_calls',bench.day_calls
)
from live,bench
$$;


ALTER FUNCTION "public"."layer3_usage_window_service"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer3_work_item_transition_service"("p_work_item_id" "uuid", "p_from_status" "text", "p_to_status" "text", "p_interpretation_id" "uuid" DEFAULT NULL::"uuid", "p_error" "text" DEFAULT NULL::"text", "p_retry_after_seconds" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_ok boolean; v_caller text;
begin
  v_caller:=coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role',
    auth.role(),
    session_user
  );
  if v_caller not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  if p_to_status not in ('pending','reserved','interpreting','validated','no_candidate','rejected','admission_pending','layer4_required','admitted','parked','failed') then raise exception 'invalid target status'; end if;
  update pipeline.layer3_work_items set
    status=case when p_to_status='failed' and attempt_count>=5 then 'parked' else p_to_status end,
    interpretation_id=coalesce(p_interpretation_id,interpretation_id),
    last_error=case when p_to_status in ('failed','parked','rejected') then nullif(left(coalesce(p_error,''),2000),'') else null end,
    available_at=case when p_to_status='failed' and attempt_count<5 then now()+make_interval(secs=>least(greatest(coalesce(p_retry_after_seconds,60),1),86400)) else available_at end,
    completed_at=case when p_to_status in ('validated','no_candidate','rejected','layer4_required','admitted','parked') or (p_to_status='failed' and attempt_count>=5) then now() else null end,
    reserved_at=case when p_to_status in ('reserved','interpreting') then reserved_at else null end,
    reserved_by=case when p_to_status in ('reserved','interpreting') then reserved_by else null end,
    updated_at=now()
  where id=p_work_item_id and status=p_from_status;
  v_ok:=found;
  return jsonb_build_object('ok',v_ok,'work_item_id',p_work_item_id,'status',case when v_ok then (select status from pipeline.layer3_work_items where id=p_work_item_id) else null end);
end $$;


