CREATE OR REPLACE FUNCTION "public"."provider_contact_profile_reconcile_service"("p_profile_id" "uuid", "p_seen_identity_hashes" "text"[], "p_pages_fetched" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare
  v_provider_id uuid;
  v_removed integer:=0;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  if coalesce(p_pages_fetched,0)<=0 then
    raise exception 'complete scan with at least one fetched page required' using errcode='22023';
  end if;

  select provider_id into v_provider_id
  from pipeline.provider_contact_profiles
  where id=p_profile_id;
  if v_provider_id is null then raise exception 'contact profile not found'; end if;

  with removed as (
    update pipeline.provider_contact_observations o set
      verification_state='stale',
      is_current=false,
      valid_to=coalesce(valid_to,now()),
      metadata=o.metadata||jsonb_build_object(
        'a15_last_scraper_absent_at',now(),
        'a15_removal_scan_pages',p_pages_fetched
      ),
      updated_at=now()
    where o.profile_id=p_profile_id
      and o.provider_id=v_provider_id
      and o.source_class='first_party'
      and o.is_current=true
      and o.verification_state<>'rejected'
      and not (o.identity_hash=any(coalesce(p_seen_identity_hashes,'{}'::text[])))
    returning o.*
  )
  insert into pipeline.provider_contact_watch_events(
    provider_id,observation_id,event_type,source_class,before_state,after_state,metadata
  )
  select
    r.provider_id,r.id,'contact_removed',r.source_class,
    jsonb_build_object(
      'job_title',r.job_title,'territory_text',r.territory_text,
      'work_email',r.work_email,'work_phone',r.work_phone,
      'professional_profile_url',r.professional_profile_url
    ),
    null,
    jsonb_build_object('scan_complete',true,'pages_fetched',p_pages_fetched,'reviewed',r.metadata ? 'a15_quality_review_at')
  from removed r;
  get diagnostics v_removed=row_count;

  return jsonb_build_object(
    'ok',true,'profile_id',p_profile_id,'provider_id',v_provider_id,
    'seen',coalesce(cardinality(p_seen_identity_hashes),0),
    'removed',v_removed,'pages_fetched',p_pages_fetched,'scan_complete',true
  );
end $$;


ALTER FUNCTION "public"."provider_contact_profile_reconcile_service"("p_profile_id" "uuid", "p_seen_identity_hashes" "text"[], "p_pages_fetched" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."provider_contact_profiles_claim_service"("p_provider_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 2, "p_lease_seconds" integer DEFAULT 1800) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'catalogue', 'ref', 'extensions'
    AS $_$
declare
  v jsonb;
  v_limit integer:=greatest(1,least(coalesce(p_limit,2),5));
  v_lease integer:=greatest(60,least(coalesce(p_lease_seconds,1800),3600));
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  with candidate_ids as (
    select pcp.id
    from pipeline.provider_contact_profiles pcp
    join catalogue.providers p on p.id=pcp.provider_id
    where pcp.enabled=true
      and pcp.paused=false
      and (p_provider_id is null or pcp.provider_id=p_provider_id)
      and (pcp.claim_until is null or pcp.claim_until<=now())
    order by pcp.last_run_at nulls first,lower(p.canonical_name),pcp.id
    for update of pcp skip locked
    limit v_limit
  ), claimed as (
    update pipeline.provider_contact_profiles pcp
    set claim_token=extensions.gen_random_uuid(),
        claimed_at=now(),
        claim_until=now()+make_interval(secs=>v_lease),
        last_run_at=now(),
        updated_at=now()
    from candidate_ids c
    where pcp.id=c.id
    returning pcp.*
  ), base as (
    select
      pcp.*,
      p.canonical_name provider_name,
      (
        select coalesce(jsonb_agg(x.origin order by x.origin),'[]'::jsonb)
        from (
          select distinct
            case
              when s.url ~* '^https?://'
              then regexp_replace(s.url,'^(https?://[^/]+).*$','\1','i')
              else null
            end origin
          from pipeline.sources s
          where s.provider_id=pcp.provider_id
            and s.url is not null
            and s.status='active'
        ) x
        where x.origin is not null
      ) governed_origins
    from claimed pcp
    join catalogue.providers p on p.id=pcp.provider_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,
    'provider_id',provider_id,
    'country_id',country_id,
    'base_url',base_url,
    'domain',domain,
    'enabled',enabled,
    'paused',paused,
    'title_terms',title_terms,
    'last_run_at',last_run_at,
    'last_success_at',last_success_at,
    'provider_name',provider_name,
    'claim_token',claim_token,
    'claim_until',claim_until,
    'governed_origins',
      case
        when governed_origins @> jsonb_build_array(regexp_replace(base_url,'^(https?://[^/]+).*$','\1','i'))
        then governed_origins
        else governed_origins || jsonb_build_array(regexp_replace(base_url,'^(https?://[^/]+).*$','\1','i'))
      end
  ) order by last_run_at,id),'[]'::jsonb)
  into v
  from base;

  return v;
end
$_$;


ALTER FUNCTION "public"."provider_contact_profiles_claim_service"("p_provider_id" "uuid", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."provider_contact_profiles_service"("p_provider_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 2) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'catalogue', 'ref'
    AS $_$
declare v jsonb;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  with base as (
    select
      pcp.*,
      p.canonical_name provider_name,
      (
        select coalesce(jsonb_agg(x.origin order by x.origin),'[]'::jsonb)
        from (
          select distinct
            case
              when s.url ~* '^https?://'
              then regexp_replace(s.url,'^(https?://[^/]+).*$','\1','i')
              else null
            end origin
          from pipeline.sources s
          where s.provider_id=pcp.provider_id
            and s.url is not null
            and s.status='active'
        ) x
        where x.origin is not null
      ) governed_origins
    from pipeline.provider_contact_profiles pcp
    join catalogue.providers p on p.id=pcp.provider_id
    where pcp.enabled=true and pcp.paused=false
      and (p_provider_id is null or pcp.provider_id=p_provider_id)
    order by pcp.last_run_at nulls first, lower(p.canonical_name)
    limit greatest(1,least(coalesce(p_limit,2),5))
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'provider_id',provider_id,'country_id',country_id,
    'base_url',base_url,'domain',domain,'enabled',enabled,'paused',paused,
    'title_terms',title_terms,'last_run_at',last_run_at,'last_success_at',last_success_at,
    'provider_name',provider_name,
    'governed_origins',
      case
        when governed_origins @> jsonb_build_array(regexp_replace(base_url,'^(https?://[^/]+).*$','\1','i'))
        then governed_origins
        else governed_origins || jsonb_build_array(regexp_replace(base_url,'^(https?://[^/]+).*$','\1','i'))
      end
  )),'[]'::jsonb) into v
  from base;

  return v;
end $_$;


