    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_run uuid; v_final text;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 if p_status not in ('validated','needs_review','no_candidate','failed','skipped_unchanged','cancelled') then raise exception 'invalid item status'; end if;
 update pipeline.scholarship_ai_run_items set status=p_status,result_status=p_result_status,interpretation_id=p_interpretation_id,error_text=p_error_text,api_calls=greatest(coalesce(p_api_calls,0),0),input_tokens=greatest(coalesce(p_input_tokens,0),0),output_tokens=greatest(coalesce(p_output_tokens,0),0),cost_usd=greatest(coalesce(p_cost_usd,0),0),completed_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb),result_payload=p_result_payload where id=p_item_id returning run_id into v_run;
 if v_run is null then raise exception 'item not found'; end if;
 update pipeline.scholarship_ai_runs r set processed_items=(select count(*) from pipeline.scholarship_ai_run_items i where i.run_id=v_run and i.status not in ('queued','running')),validated_items=(select count(*) from pipeline.scholarship_ai_run_items i where i.run_id=v_run and i.status='validated'),review_items=(select count(*) from pipeline.scholarship_ai_run_items i where i.run_id=v_run and i.status='needs_review'),no_candidate_items=(select count(*) from pipeline.scholarship_ai_run_items i where i.run_id=v_run and i.status='no_candidate'),failed_items=(select count(*) from pipeline.scholarship_ai_run_items i where i.run_id=v_run and i.status='failed'),skipped_unchanged_items=(select count(*) from pipeline.scholarship_ai_run_items i where i.run_id=v_run and i.status='skipped_unchanged'),api_calls=(select coalesce(sum(i.api_calls),0) from pipeline.scholarship_ai_run_items i where i.run_id=v_run),input_tokens=(select coalesce(sum(i.input_tokens),0) from pipeline.scholarship_ai_run_items i where i.run_id=v_run),output_tokens=(select coalesce(sum(i.output_tokens),0) from pipeline.scholarship_ai_run_items i where i.run_id=v_run),cost_usd=(select coalesce(sum(i.cost_usd),0) from pipeline.scholarship_ai_run_items i where i.run_id=v_run) where r.id=v_run;
 if not exists(select 1 from pipeline.scholarship_ai_run_items where run_id=v_run and status in ('queued','running')) then update pipeline.scholarship_ai_runs set status=case when failed_items>0 then 'completed_with_errors' else 'completed' end,completed_at=now() where id=v_run; end if;
 select status into v_final from pipeline.scholarship_ai_runs where id=v_run; return jsonb_build_object('ok',true,'run_id',v_run,'run_status',v_final);
end $$;


ALTER FUNCTION "public"."scholarship_ai_item_finish_service"("p_item_id" "uuid", "p_status" "text", "p_result_status" "text", "p_interpretation_id" "uuid", "p_error_text" "text", "p_api_calls" integer, "p_input_tokens" integer, "p_output_tokens" integer, "p_cost_usd" numeric, "p_metadata" "jsonb", "p_result_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scholarship_ai_next_item_service"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_i pipeline.scholarship_ai_run_items%rowtype; v_r pipeline.scholarship_ai_runs%rowtype; v_e pipeline.evidence_artifacts%rowtype; v_c pipeline.layer2_scholarship_discovery_candidates%rowtype;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 select * into v_r from pipeline.scholarship_ai_runs where id=p_run_id for update;
 if not found then raise exception 'run not found'; end if;
 if v_r.status in ('completed','completed_with_errors','failed','cancelled') then return jsonb_build_object('done',true,'status',v_r.status,'country_code',v_r.country_code); end if;
 select * into v_i from pipeline.scholarship_ai_run_items where run_id=p_run_id and status='queued' order by created_at,id limit 1 for update skip locked;
 if not found then update pipeline.scholarship_ai_runs set status=case when failed_items>0 then 'completed_with_errors' else 'completed' end,completed_at=now() where id=p_run_id; return jsonb_build_object('done',true,'status',case when v_r.failed_items>0 then 'completed_with_errors' else 'completed' end,'country_code',v_r.country_code); end if;
 update pipeline.scholarship_ai_run_items set status='running',started_at=now() where id=v_i.id;
 update pipeline.scholarship_ai_runs set status='running',started_at=coalesce(started_at,now()) where id=p_run_id;
 select * into v_e from pipeline.evidence_artifacts where id=v_i.evidence_id;
 select * into v_c from pipeline.layer2_scholarship_discovery_candidates where id=v_i.candidate_id;
 return jsonb_build_object('done',false,'item_id',v_i.id,'candidate_id',v_i.candidate_id,'evidence_id',v_i.evidence_id,'evidence_hash',v_i.evidence_hash,'storage_path',v_e.storage_path,'mime_type',v_e.mime_type,'source_url',v_e.source_url,'task_class',v_r.task_class,'profile_id',v_r.profile_id,'trigger_mode',v_r.trigger_mode,'requested_by',v_r.requested_by,'country_code',v_r.country_code,'observed_title',v_c.observed_title,'scholarship_url',v_c.scholarship_url,'classification',v_c.classification);
end $$;


ALTER FUNCTION "public"."scholarship_ai_next_item_service"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scholarship_ai_profile_service"("p_profile_id" "uuid", "p_allow_benchmark_pending" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare p pipeline.layer3_model_profiles%rowtype;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 select * into p from pipeline.layer3_model_profiles where id=p_profile_id;
 if not found then raise exception 'profile not found'; end if;
 if not p.enabled then raise exception 'profile disabled'; end if;
 if not p_allow_benchmark_pending and (p.paused or coalesce((p.quality_benchmark->>'pass')::boolean,false) is not true) then raise exception 'profile not qualified'; end if;
 return jsonb_build_object('id',p.id,'code',p.code,'aggregator_provider',p.aggregator_provider,'base_url',p.base_url,'model_identifier',p.model_identifier,'secret_env_key',p.secret_env_key,'prompt_profile_version',p.prompt_profile_version,'prompt_system',p.prompt_system,'validators',p.deterministic_validators,'max_input_tokens',p.max_input_tokens,'max_output_tokens',p.max_output_tokens,'retry_ceiling',p.retry_ceiling,'timeout_ms',p.timeout_ms,'cost_ceiling_usd',p.cost_ceiling_usd,'benchmark_pass',coalesce((p.quality_benchmark->>'pass')::boolean,false),'paused',p.paused);
end $$;


