CREATE OR REPLACE FUNCTION "public"."scholarship_candidate_mark_catalogue"("p_job_id" "uuid", "p_reason" "text" DEFAULT 'catalogue_enumeration_required'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare v_candidate uuid;v_count integer:=0;
begin
 if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501';end if;
 select nullif(payload->>'candidate_id','')::uuid into v_candidate from pipeline.jobs where id=p_job_id and domain='scholarship';
 if v_candidate is null then return jsonb_build_object('ok',false,'reason','candidate_missing');end if;
 update pipeline.layer2_scholarship_discovery_candidates
 set classification='catalogue_or_filter',classification_reason=coalesce(p_reason,'catalogue_enumeration_required')||'; retained as catalogue Evidence, not individual Scholarship',classified_at=now()
 where id=v_candidate;
 get diagnostics v_count=row_count;
 return jsonb_build_object('ok',true,'candidate_id',v_candidate,'updated',v_count);
end
$$;


ALTER FUNCTION "public"."scholarship_candidate_mark_catalogue"("p_job_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scholarship_course_fill_service"("p_actor" "uuid", "p_action" "text", "p_country_code" "text" DEFAULT NULL::"text", "p_provider_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'scholarship', 'catalogue', 'ref', 'pipeline'
    AS $$
declare v_rank integer:=0; v_courses integer:=0; v_scholarships integer:=0; v_pairs integer:=0; v_candidates integer:=0; v_written integer:=0;
begin
 if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 select coalesce(max(r.rank),0) into v_rank from security.user_roles ur join security.roles r on r.code=ur.role_code
 where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
 if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
 if p_action not in('preview','fill','queue_review') then raise exception 'unsupported action' using errcode='22023'; end if;

 with scoped_courses as(
   select c.id,c.provider_id
   from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
   where (p_provider_id is null or c.provider_id=p_provider_id)
     and (p_country_code is null or upper(co.iso_alpha2::text)=upper(p_country_code))
 ), deterministic as(
   select distinct s.id scholarship_id,c.id course_id,sc.id scope_id,coalesce(sc.evidence_id,s.evidence_id) evidence_id,
     case when sc.scope_type='course' then 'explicit_course_scope' else 'explicit_provider_scope' end basis
   from scholarship.scholarships s
   join scholarship.scopes sc on sc.scholarship_id=s.id and sc.include_exclude='include'
   join scoped_courses c on (sc.scope_type='course' and sc.course_id=c.id) or (sc.scope_type='provider' and sc.provider_id=c.provider_id)
   where not exists(
     select 1 from scholarship.scopes ex
     where ex.scholarship_id=s.id and ex.include_exclude='exclude'
       and ((ex.scope_type='course' and ex.course_id=c.id) or (ex.scope_type='provider' and ex.provider_id=c.provider_id))
   )
 ), provider_candidates as(
   select distinct s.id scholarship_id,c.id course_id,coalesce(s.evidence_id,null) evidence_id
   from scholarship.scholarships s join scoped_courses c on c.provider_id=s.provider_id
   where s.provider_id is not null
     and not exists(select 1 from deterministic d where d.scholarship_id=s.id and d.course_id=c.id)
     and not exists(select 1 from scholarship.scopes sc where sc.scholarship_id=s.id and sc.include_exclude='include' and sc.scope_type in('course','provider'))
 )
 select (select count(*) from scoped_courses),
        (select count(distinct s.id) from scholarship.scholarships s where
          exists(select 1 from scoped_courses c where c.provider_id=s.provider_id) or exists(select 1 from deterministic d where d.scholarship_id=s.id)),
        (select count(*) from deterministic),
        (select count(*) from provider_candidates)
 into v_courses,v_scholarships,v_pairs,v_candidates;

 if p_action='preview' then
   return jsonb_build_object('ok',true,'courses',v_courses,'scholarships',v_scholarships,'deterministic_mappings',v_pairs,
     'provider_level_candidates',v_candidates,'existing_mappings',(select count(*) from scholarship.course_mappings m where exists(
       select 1 from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
       where c.id=m.course_id and (p_provider_id is null or c.provider_id=p_provider_id) and (p_country_code is null or upper(co.iso_alpha2::text)=upper(p_country_code))
     )),
     'rule','Only explicit course/provider include scopes are materialised. Provider ownership without explicit scope remains review-only.');
 end if;

 if p_action='fill' then
   with scoped_courses as(
     select c.id,c.provider_id from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
     where (p_provider_id is null or c.provider_id=p_provider_id) and (p_country_code is null or upper(co.iso_alpha2::text)=upper(p_country_code))
   ), deterministic as(
     select distinct s.id scholarship_id,c.id course_id,sc.id scope_id,coalesce(sc.evidence_id,s.evidence_id) evidence_id,
       case when sc.scope_type='course' then 'explicit_course_scope' else 'explicit_provider_scope' end basis
     from scholarship.scholarships s join scholarship.scopes sc on sc.scholarship_id=s.id and sc.include_exclude='include'
     join scoped_courses c on (sc.scope_type='course' and sc.course_id=c.id) or (sc.scope_type='provider' and sc.provider_id=c.provider_id)
     where not exists(select 1 from scholarship.scopes ex where ex.scholarship_id=s.id and ex.include_exclude='exclude'
       and ((ex.scope_type='course' and ex.course_id=c.id) or (ex.scope_type='provider' and ex.provider_id=c.provider_id)))
   ), ins as(
     insert into scholarship.course_mappings(scholarship_id,course_id,mapping_state,mapping_basis,source_scope_id,evidence_id,mapped_by)
     select scholarship_id,course_id,'mapped',basis,scope_id,evidence_id,p_actor from deterministic
     on conflict(scholarship_id,course_id) do update
       set mapping_state='mapped',mapping_basis=excluded.mapping_basis,source_scope_id=excluded.source_scope_id,
           evidence_id=excluded.evidence_id,mapped_by=excluded.mapped_by,updated_at=now()
     returning 1
   ) select count(*) into v_written from ins;
   return jsonb_build_object('ok',true,'status','filled','written_or_refreshed',v_written,'deterministic_mappings',v_pairs,
     'canonical_course_fields_changed',false,'publication_changed',false);
 end if;

 with scoped_courses as(
   select c.id,c.provider_id from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
   where (p_provider_id is null or c.provider_id=p_provider_id) and (p_country_code is null or upper(co.iso_alpha2::text)=upper(p_country_code))
 ), candidates as(
   select distinct s.id scholarship_id,c.id course_id,s.evidence_id
   from scholarship.scholarships s join scoped_courses c on c.provider_id=s.provider_id
   where s.provider_id is not null
     and not exists(select 1 from scholarship.scopes sc where sc.scholarship_id=s.id and sc.include_exclude='include' and sc.scope_type in('course','provider'))
 )
 insert into scholarship.course_mapping_candidates(scholarship_id,course_id,candidate_reason,evidence_id)
 select scholarship_id,course_id,'provider_owned_but_no_explicit_course_or_provider_scope',evidence_id from candidates
 on conflict(scholarship_id,course_id) do update set updated_at=now(),status=case when scholarship.course_mapping_candidates.status='superseded' then 'superseded' else 'needs_review' end;
 get diagnostics v_written=row_count;
 return jsonb_build_object('ok',true,'status','review_candidates_queued','written_or_refreshed',v_written,
   'publication_changed',false,'eligibility_manufactured',false);
end $$;


ALTER FUNCTION "public"."scholarship_course_fill_service"("p_actor" "uuid", "p_action" "text", "p_country_code" "text", "p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scholarship_detail_extraction_context"("p_job_id" "uuid", "p_evidence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare
  v_job record;
  v_e record;
  v_candidate uuid;
  v_classification text;
  v_url text;
  v_eligible boolean:=false;
  v_normalized uuid;
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  select * into v_job from pipeline.jobs where id=p_job_id and domain='scholarship' and job_type='scholarship_scope_acquisition';
  if not found then return null; end if;
  select id,evidence_type,source_url,metadata into v_e from pipeline.evidence_artifacts where id=p_evidence_id;
  if not found then return null; end if;
  begin v_candidate:=nullif(v_job.payload->>'candidate_id','')::uuid; exception when others then v_candidate:=null; end;
  if v_candidate is not null then
    select classification,coalesce(nullif(detail_target_url,''),nullif(scholarship_url,'')) into v_classification,v_url
    from pipeline.layer2_scholarship_discovery_candidates where id=v_candidate;
  end if;
  v_eligible:=coalesce(v_classification,'')='detail_ready'
    and coalesce(v_url,v_e.source_url,'') !~* '/search\?'
    and coalesce(v_url,v_e.source_url,'') !~* '[?&](query|collection|form|num_ranks|f\.)=';
  select id into v_normalized
  from pipeline.evidence_artifacts
  where evidence_type='layer2_extraction_input'
    and metadata->>'source_evidence_id'=p_evidence_id::text
  order by created_at desc limit 1;
  return jsonb_build_object(
    'job_id',v_job.id,'candidate_id',v_candidate,'classification',v_classification,'eligible',v_eligible,
    'evidence_id',v_e.id,'evidence_type',v_e.evidence_type,'source_url',v_e.source_url,
    'attempt_id',v_e.metadata->>'attempt_id','existing_normalized_evidence_id',v_normalized,
    'reason',case when v_eligible then 'detail_ready' else 'candidate_not_current_detail_ready_or_filter_page' end
  );
end
$$;


ALTER FUNCTION "public"."scholarship_detail_extraction_context"("p_job_id" "uuid", "p_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scholarship_operations_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'scholarship', 'auth'
    AS $$
declare v_rank integer;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
  return jsonb_build_object(
    'schedules',(select coalesce(jsonb_agg(jsonb_build_object('feed',feed,'enabled',enabled,'cadence_hours',cadence_hours,'mode',mode,'max_records',max_records,'page_start',page_start,'page_end',page_end,'next_due_at',next_due_at,'last_dispatched_at',last_dispatched_at,'last_request_id',last_request_id,'last_error',last_error) order by feed),'[]'::jsonb) from pipeline.scholarship_etl_schedules),
    'qualifications',(select coalesce(jsonb_agg(jsonb_build_object('source_key',source_key,'authority_name',authority_name,'qualification_status',qualification_status,'source_url',source_url,'updated_at',updated_at) order by source_key),'[]'::jsonb) from pipeline.scholarship_source_qualifications),
    'source_records',(select jsonb_build_object('total',count(*),'applied',count(*) filter(where status='applied' and applied_at is not null),'unapplied',count(*) filter(where status<>'applied' or applied_at is null),'stale_45d',count(*) filter(where observed_at<now()-interval '45 days'),'latest_observed_at',max(observed_at)) from pipeline.scholarship_source_records),
    'discovery_candidates',(select jsonb_build_object('discovered',count(*) filter(where status='discovered'),'detail_ready',count(*) filter(where status='discovered' and classification='detail_ready'),'needs_review',count(*) filter(where status='discovered' and classification='needs_review'),'rejected',count(*) filter(where status='rejected'),'acquired',count(*) filter(where status='acquired'),'total',count(*)) from pipeline.layer2_scholarship_discovery_candidates),
    'course_mapping',(select jsonb_build_object('mapped',count(*) filter(where mapping_state='mapped'),'needs_review',(select count(*) from scholarship.course_mapping_candidates where status='needs_review')) from scholarship.course_mappings),
    'provider_stats',(select coalesce(jsonb_agg(to_jsonb(s) order by s.canonical_total desc,s.provider_name),'[]'::jsonb) from pipeline.scholarship_provider_stats s),
    'provider_stats_summary',(select jsonb_build_object('providers',count(*),'canonical_total',coalesce(sum(canonical_total),0),'published_total',coalesce(sum(published_total),0),'unpublished_total',coalesce(sum(unpublished_total),0),'first_party_verified_total',coalesce(sum(first_party_verified_total),0),'evidence_acquired_total',coalesce(sum(evidence_acquired_total),0),'candidate_total',coalesce(sum(candidate_total),0),'detail_ready_total',coalesce(sum(detail_ready_total),0),'candidate_needs_review_total',coalesce(sum(candidate_needs_review_total),0),'candidate_rejected_total',coalesce(sum(candidate_rejected_total),0),'candidate_acquired_total',coalesce(sum(candidate_acquired_total),0),'layer4_linked_total',coalesce(sum(layer4_linked_total),0),'canonical_linked_total',coalesce(sum(canonical_linked_total),0),'publication_decision_linked_total',coalesce(sum(publication_decision_linked_total),0),'benchmarked_providers',count(*) filter(where landscape_benchmark_total is not null),'last_trace_update',max(trace_last_updated_at),'last_candidate_classification',max(candidate_last_classified_at)) from pipeline.scholarship_provider_stats),
    'latest_maintenance',(select to_jsonb(x) from (select id,started_at,completed_at,status,deterministic_mappings,mapping_candidates,source_records,unapplied_source_records,discovery_candidates,stale_source_records,evidence_deleted,source_records_deleted from pipeline.scholarship_maintenance_runs order by started_at desc limit 1) x)
  );
end
$$;


ALTER FUNCTION "public"."scholarship_operations_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scholarship_scope_failed_job_requeue"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare v_job record;
begin
 if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 select * into v_job from pipeline.jobs where id=p_job_id and domain='scholarship' and job_type='scholarship_scope_acquisition';
 if not found then return jsonb_build_object('ok',false,'reason','job_not_found'); end if;
 if v_job.status<>'failed' then return jsonb_build_object('ok',false,'reason','job_not_failed','status',v_job.status); end if;
 update pipeline.jobs set status='queued',started_at=null,completed_at=null,error_text=null,result='{}'::jsonb where id=p_job_id;
 return jsonb_build_object('ok',true,'job_id',p_job_id,'status','queued');
end $$;


ALTER FUNCTION "public"."scholarship_scope_failed_job_requeue"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scholarship_scope_job_execution_context"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'catalogue'
    AS $$
declare
  v_job record;
  v_profile record;
  v_requested_profile uuid;
  v_requested_url text;
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  select * into v_job from pipeline.jobs where id=p_job_id and job_type='scholarship_scope_acquisition' and domain='scholarship';
  if not found then return null; end if;
  begin v_requested_profile:=nullif(v_job.payload->>'profile_id','')::uuid; exception when others then v_requested_profile:=null; end;
  v_requested_url:=nullif(v_job.payload->>'target_url','');
  if v_requested_profile is not null then
    select sp.id profile_id,sp.current_version_id,sp.profile_key,sp.source_id,coalesce(v_requested_url,s.url) target_url,s.trust_rank into v_profile
    from pipeline.layer2_source_profiles sp join pipeline.sources s on s.id=sp.source_id
    where sp.id=v_requested_profile and s.provider_id=v_job.provider_id and s.status='active' and sp.domain='scholarship' and sp.enabled and not sp.paused and sp.current_version_id is not null limit 1;
  else
    select sp.id profile_id,sp.current_version_id,sp.profile_key,sp.source_id,s.url target_url,s.trust_rank into v_profile
    from pipeline.layer2_source_profiles sp join pipeline.sources s on s.id=sp.source_id
    where s.provider_id=v_job.provider_id and s.status='active' and sp.domain='scholarship' and sp.acquisition_method='scholarship_catalogue' and sp.enabled and not sp.paused and sp.current_version_id is not null
    order by case when sp.profile_key like 'au-scholarship-entry-%' then 0 else 1 end,s.trust_rank desc nulls last,sp.updated_at desc limit 1;
  end if;
  return jsonb_build_object('job_id',v_job.id,'provider_id',v_job.provider_id,'status',v_job.status,'payload',coalesce(v_job.payload,'{}'::jsonb),'result',coalesce(v_job.result,'{}'::jsonb),'profile_id',v_profile.profile_id,'profile_version_id',v_profile.current_version_id,'profile_key',v_profile.profile_key,'source_id',v_profile.source_id,'target_url',v_profile.target_url);
end
$$;


ALTER FUNCTION "public"."scholarship_scope_job_execution_context"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scholarship_scope_job_mark"("p_job_id" "uuid", "p_status" "text", "p_result" "jsonb" DEFAULT NULL::"jsonb", "p_error" "text" DEFAULT NULL::"text", "p_execution" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare v_request_id uuid;v_remaining integer:=0;v_failed integer:=0;
begin
 if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501';end if;
 if p_status not in('running','succeeded','failed') then raise exception 'invalid status' using errcode='22023';end if;
 update pipeline.jobs set status=p_status,
   started_at=case when p_status='running' then coalesce(started_at,now()) else started_at end,
   completed_at=case when p_status in('succeeded','failed') then now() else null end,
   result=case when p_result is null then result else p_result end,
   error_text=p_error,
   source_id=coalesce(nullif(p_execution->>'source_id','')::uuid,source_id),
   source_profile_version_id=coalesce(nullif(p_execution->>'profile_version_id','')::uuid,source_profile_version_id),
   payload=coalesce(payload,'{}'::jsonb)||coalesce(p_execution,'{}'::jsonb)
 where id=p_job_id and job_type='scholarship_scope_acquisition' and domain='scholarship'
 returning nullif(payload->>'request_id','')::uuid into v_request_id;
 if not found then raise exception 'scope job not found' using errcode='P0002';end if;
 if p_status in('succeeded','failed') and v_request_id is not null then
   select count(*) filter(where status in('queued','running')),count(*) filter(where status='failed') into v_remaining,v_failed
   from pipeline.jobs where domain='scholarship' and job_type='scholarship_scope_acquisition' and payload->>'request_id'=v_request_id::text;
   if v_remaining=0 then
     update pipeline.scholarship_scope_acquisition_requests
     set status=case when v_failed>0 then 'completed_with_errors' else 'completed' end,completed_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('failed_jobs',v_failed,'rollup_completed_at',now())
     where id=v_request_id;
   end if;
 end if;
 return jsonb_build_object('ok',true,'job_id',p_job_id,'status',p_status,'request_id',v_request_id);
end $$;


ALTER FUNCTION "public"."scholarship_scope_job_mark"("p_job_id" "uuid", "p_status" "text", "p_result" "jsonb", "p_error" "text", "p_execution" "jsonb") OWNER TO "postgres";


