CREATE OR REPLACE FUNCTION "public"."svc_adapter_shadow_claim"("p_task" "text", "p_limit" integer, "p_worker" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s pipeline.adapter_shadow_settings; v_spent numeric; v_reads int; v_task_reads int; v_cap int; v_limit int;
        v_class text; v_items jsonb := '[]'::jsonb; r record; v_prof jsonb; v_esc jsonb; v_tp jsonb; v_id uuid; v_l3 jsonb; v_l3_found boolean;
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
  if p_task not in ('intake','english','tuition') then raise exception 'task must be intake, english or tuition'; end if;
  v_class := case p_task when 'intake' then 'provider_intake_validation' when 'english' then 'provider_english_validation' else 'provider_current_tuition_validation' end;
  select * into s from pipeline.adapter_shadow_settings where id = 1;
  if not coalesce(s.enabled, false) then return jsonb_build_object('items', v_items, 'reason', 'shadow run switched off'); end if;
  perform pg_advisory_xact_lock(hashtext('adapter-shadow-claim'));
  -- a claim left by a lost worker is closed as an error after 30 minutes
  update pipeline.adapter_shadow_reads set status = 'error', errors = '["stale claim released"]'::jsonb, completed_at = now()
   where status = 'claimed' and claimed_at < now() - interval '30 minutes';
  -- spend counts every round today; the read limit counts the current round only
  select coalesce(sum(cost_usd), 0) into v_spent
    from pipeline.adapter_shadow_reads where claimed_at >= date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
  select count(*), count(*) filter (where task = p_task) into v_reads, v_task_reads
    from pipeline.adapter_shadow_reads where round = s.round and claimed_at >= date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
  if v_spent >= s.daily_usd_max then return jsonb_build_object('items', v_items, 'reason', format('daily spend limit: %s of %s USD', round(v_spent, 4), s.daily_usd_max)); end if;
  v_cap := s.daily_reads_max / 3;
  if v_task_reads >= v_cap or v_reads >= s.daily_reads_max then return jsonb_build_object('items', v_items, 'reason', format('daily read limit: %s of %s for %s', v_task_reads, v_cap, p_task)); end if;
  v_limit := greatest(1, least(coalesce(p_limit, 3), 10, v_cap - v_task_reads));
  -- tuition: the tuition task's own contract (prompt, checks, input length) with the adapter's model
  if p_task = 'tuition' then
    v_tp := (select to_jsonb(p) from pipeline.layer3_routed_profile(v_class) p where p.id is not null);
    if v_tp is null then return jsonb_build_object('items', v_items, 'reason', 'no routed tuition profile for the task contract'); end if;
  end if;
  for r in
    select w.id work_item_id, w.status l3_status, w.candidate_context, co.id course_id, co.provider_id, i.evidence_id, e.storage_path,
           e.source_url, e.mime_type, i.candidate_value, i.status i_status, i.estimated_cost_usd, to_jsonb(ua) adapter
      from pipeline.layer3_work_items w
      join pipeline.layer3_interpretations i on i.id = w.interpretation_id
      join pipeline.evidence_artifacts e on e.id = i.evidence_id and e.storage_path is not null
      join catalogue.courses co on co.id = w.entity_id
      join pipeline.uni_adapters ua on ua.provider_id = co.provider_id and ua.enabled
     where w.task_class = v_class and w.entity_type = 'course'
       and w.status in ('admitted','no_candidate','layer4_required','validated')
       and w.completed_at > now() - interval '30 days'
       and not exists (select 1 from pipeline.adapter_shadow_reads x where x.work_item_id = w.id)
     order by w.completed_at desc
     limit v_limit
  loop
    v_prof := (select to_jsonb(p) - 'prompt_system' - 'structured_output_schema' - 'deterministic_validators' - 'quality_benchmark' - 'holdout_qualification' - 'last_validation_result'
                 from pipeline.layer3_model_profiles p
                where p.code = coalesce(s.model_profile_code, security.adapter_builder_model_for_v1(r.provider_id)->>'code')
                  and p.enabled and not p.paused and p.retired_at is null);
    if v_prof is null then continue; end if;
    -- round 3: one stronger model, asked once only when the first model found nothing and the page clearly shows the field
    v_esc := (select to_jsonb(p) - 'prompt_system' - 'structured_output_schema' - 'deterministic_validators' - 'quality_benchmark' - 'holdout_qualification' - 'last_validation_result'
                from pipeline.layer3_model_profiles p
               where p.code = s.escalation_profile_code and p.enabled and not p.paused and p.retired_at is null);
    if p_task = 'tuition' then
      -- the adapter's model and credential; the tuition task's prompt, checks and limits
      v_prof := v_tp - 'quality_benchmark' - 'holdout_qualification' - 'last_validation_result'
                || jsonb_build_object('id', v_prof->'id', 'code', v_prof->'code', 'model_identifier', v_prof->'model_identifier',
                                      'base_url', v_prof->'base_url', 'secret_env_key', v_prof->'secret_env_key', 'task_contract_profile', v_tp->'code');
      if v_esc is not null then
        v_esc := v_tp - 'quality_benchmark' - 'holdout_qualification' - 'last_validation_result'
                 || jsonb_build_object('id', v_esc->'id', 'code', v_esc->'code', 'model_identifier', v_esc->'model_identifier',
                                       'base_url', v_esc->'base_url', 'secret_env_key', v_esc->'secret_env_key', 'task_contract_profile', v_tp->'code');
      end if;
      v_l3 := case when r.i_status <> 'provider_error' and security.adapter_shadow_found_v1('tuition', r.candidate_value) then r.candidate_value end;
      v_l3_found := v_l3 is not null;
    else
      v_l3 := case when r.i_status = 'validated' then r.candidate_value end;
      v_l3_found := r.i_status = 'validated' and security.adapter_shadow_found_v1(p_task, r.candidate_value);
    end if;
    insert into pipeline.adapter_shadow_reads(task, work_item_id, course_id, provider_id, evidence_id, profile_code, model, layer3_status,
           layer3_value, layer3_found, layer3_cost_usd, round)
    values (p_task, r.work_item_id, r.course_id, r.provider_id, r.evidence_id, v_prof->>'code', v_prof->>'model_identifier', r.l3_status,
           v_l3, v_l3_found, r.estimated_cost_usd, s.round)
    returning id into v_id;
    v_items := v_items || jsonb_build_object('shadow_id', v_id, 'course_id', r.course_id, 'provider_id', r.provider_id,
      'storage_path', r.storage_path, 'source_url', r.source_url, 'mime_type', r.mime_type,
      'context', case when p_task = 'tuition' then r.candidate_context end,
      'adapter', r.adapter - 'notes' - 'reason' - 'updated_by' - 'admit_reason', 'profile', v_prof, 'escalation', v_esc);
  end loop;
  return jsonb_build_object('items', v_items, 'round', s.round, 'spent_today_usd', v_spent, 'reads_today', v_reads, 'worker', p_worker);
end $$;


ALTER FUNCTION "public"."svc_adapter_shadow_claim"("p_task" "text", "p_limit" integer, "p_worker" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_adapter_shadow_complete"("p_id" "uuid", "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v pipeline.adapter_shadow_reads; v_found boolean;
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into v from pipeline.adapter_shadow_reads where id = p_id for update;
  if v.id is null or v.status <> 'claimed' then return jsonb_build_object('ok', false, 'reason', 'not an open shadow claim'); end if;
  -- tuition: the pick counts as found whatever its checks said, as for Layer 3; intake and English: a checked value
  v_found := case when v.task = 'tuition' then not (p_result ? 'worker_error') and security.adapter_shadow_found_v1(v.task, p_result->'admitted')
                  else coalesce((p_result->>'valid')::boolean, false) and security.adapter_shadow_found_v1(v.task, p_result->'admitted') end;
  update pipeline.adapter_shadow_reads set
    status = case when p_result ? 'worker_error' then 'error' else 'done' end,
    input_basis = p_result->>'input_basis', input_chars = (p_result->>'input_chars')::int,
    shadow_status = p_result->>'status', shadow_valid = (p_result->>'valid')::boolean,
    shadow_value = case when v_found then p_result->'admitted' end, shadow_found = v_found,
    agree = case when v_found and v.layer3_found then security.adapter_shadow_same_v1(v.task, p_result->'admitted', v.layer3_value) end,
    cost_usd = coalesce((p_result->>'cost_usd')::numeric, 0), input_tokens = (p_result->>'input_tokens')::int,
    output_tokens = (p_result->>'output_tokens')::int, latency_ms = (p_result->>'latency_ms')::int,
    errors = p_result->'errors', worker_version = p_result->>'worker_version', completed_at = now(),
    escalated = coalesce((p_result->>'escalated')::boolean, false)
  where id = p_id returning * into v;
  return jsonb_build_object('ok', true, 'status', v.status, 'shadow_found', v.shadow_found, 'layer3_found', v.layer3_found, 'agree', v.agree);
end $$;


ALTER FUNCTION "public"."svc_adapter_shadow_complete"("p_id" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_admin_access_guard_disable"("p_actor_user_id" "uuid", "p_target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$
declare v_other_platform_admins integer := 0;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'service role required' using errcode='42501';
  end if;

  if not exists (
    select 1
    from security.user_roles ur
    join security.roles r on r.code=ur.role_code
    join auth.users u on u.id=ur.user_id
    where ur.user_id=p_actor_user_id
      and r.code='platform_admin' and r.status='active'
      and (ur.expires_at is null or ur.expires_at>now())
      and u.deleted_at is null
      and (u.banned_until is null or u.banned_until<=now())
  ) then
    raise exception 'active platform admin actor required' using errcode='42501';
  end if;

  if p_actor_user_id=p_target_user_id then
    raise exception 'platform admin cannot disable own account' using errcode='42501';
  end if;

  if not exists (select 1 from auth.users where id=p_target_user_id and deleted_at is null) then
    raise exception 'target user not found' using errcode='22023';
  end if;

  if exists (
    select 1 from security.user_roles ur
    where ur.user_id=p_target_user_id and ur.role_code='platform_admin'
      and (ur.expires_at is null or ur.expires_at>now())
  ) then
    select count(distinct ur.user_id)::integer into v_other_platform_admins
    from security.user_roles ur
    join security.roles r on r.code=ur.role_code
    join auth.users u on u.id=ur.user_id
    where ur.user_id<>p_target_user_id
      and ur.role_code='platform_admin' and r.status='active'
      and (ur.expires_at is null or ur.expires_at>now())
      and u.deleted_at is null
      and (u.banned_until is null or u.banned_until<=now());
    if v_other_platform_admins=0 then
      raise exception 'cannot disable the last active platform admin' using errcode='42501';
    end if;
  end if;

  return jsonb_build_object('allowed',true,'target_user_id',p_target_user_id);
end
$$;


ALTER FUNCTION "public"."svc_admin_access_guard_disable"("p_actor_user_id" "uuid", "p_target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_admin_access_log_event"("p_actor_user_id" "uuid", "p_target_user_id" "uuid", "p_action" "text", "p_before_state" "jsonb" DEFAULT '{}'::"jsonb", "p_after_state" "jsonb" DEFAULT '{}'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$
declare v_id uuid;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'service role required' using errcode='42501';
  end if;

  if not exists (
    select 1
    from security.user_roles ur
    join security.roles r on r.code=ur.role_code
    join auth.users u on u.id=ur.user_id
    where ur.user_id=p_actor_user_id
      and r.code='platform_admin' and r.status='active'
      and (ur.expires_at is null or ur.expires_at>now())
      and u.deleted_at is null
      and (u.banned_until is null or u.banned_until<=now())
  ) then
    raise exception 'active platform admin actor required' using errcode='42501';
  end if;

  if p_action not in ('user_created','user_invited','roles_replaced','user_disabled','user_enabled') then
    raise exception 'unsupported access audit action' using errcode='22023';
  end if;

  insert into security.user_access_events(actor_user_id,target_user_id,action,before_state,after_state,metadata)
  values(
    p_actor_user_id,p_target_user_id,p_action,
    coalesce(p_before_state,'{}'::jsonb),coalesce(p_after_state,'{}'::jsonb),
    (coalesce(p_metadata,'{}'::jsonb) - 'password' - 'token' - 'access_token' - 'refresh_token')
  ) returning id into v_id;
  return v_id;
end
$$;


ALTER FUNCTION "public"."svc_admin_access_log_event"("p_actor_user_id" "uuid", "p_target_user_id" "uuid", "p_action" "text", "p_before_state" "jsonb", "p_after_state" "jsonb", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_admin_access_replace_roles"("p_actor_user_id" "uuid", "p_target_user_id" "uuid", "p_role_codes" "text"[], "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$
declare
  v_roles text[];
  v_before jsonb;
  v_after jsonb;
  v_other_platform_admins integer := 0;
  v_target_is_platform_admin boolean := false;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'service role required' using errcode='42501';
  end if;

  if not exists (
    select 1
    from security.user_roles ur
    join security.roles r on r.code=ur.role_code
    join auth.users u on u.id=ur.user_id
    where ur.user_id=p_actor_user_id
      and r.code='platform_admin' and r.status='active'
      and (ur.expires_at is null or ur.expires_at>now())
      and u.deleted_at is null
      and (u.banned_until is null or u.banned_until<=now())
  ) then
    raise exception 'active platform admin actor required' using errcode='42501';
  end if;

  if not exists (select 1 from auth.users where id=p_target_user_id and deleted_at is null) then
    raise exception 'target user not found' using errcode='22023';
  end if;

  select coalesce(array_agg(distinct btrim(x) order by btrim(x)), '{}'::text[])
  into v_roles
  from unnest(coalesce(p_role_codes,'{}'::text[])) x
  where btrim(coalesce(x,''))<>'';

  if cardinality(v_roles)=0 then
    raise exception 'at least one CourseFinder role is required' using errcode='22023';
  end if;

  if exists (
    select 1 from unnest(v_roles) x
    left join security.roles r on r.code=x and r.status='active'
    where r.code is null
  ) then
    raise exception 'unknown or inactive role code' using errcode='22023';
  end if;

  if p_actor_user_id=p_target_user_id and not ('platform_admin'=any(v_roles)) then
    raise exception 'platform admin cannot remove own platform_admin role' using errcode='42501';
  end if;

  if 'platform_admin'=any(v_roles) and p_expires_at is not null then
    raise exception 'platform_admin assignment cannot expire' using errcode='22023';
  end if;

  select exists (
    select 1 from security.user_roles ur
    where ur.user_id=p_target_user_id and ur.role_code='platform_admin'
      and (ur.expires_at is null or ur.expires_at>now())
  ) into v_target_is_platform_admin;

  if v_target_is_platform_admin and not ('platform_admin'=any(v_roles)) then
    select count(distinct ur.user_id)::integer into v_other_platform_admins
    from security.user_roles ur
    join security.roles r on r.code=ur.role_code
    join auth.users u on u.id=ur.user_id
    where ur.user_id<>p_target_user_id
      and ur.role_code='platform_admin' and r.status='active'
      and (ur.expires_at is null or ur.expires_at>now())
      and u.deleted_at is null
      and (u.banned_until is null or u.banned_until<=now());
    if v_other_platform_admins=0 then
      raise exception 'cannot remove the last active platform admin' using errcode='42501';
    end if;
  end if;

  select jsonb_build_object(
    'roles',coalesce(jsonb_agg(jsonb_build_object('code',ur.role_code,'expires_at',ur.expires_at) order by r.rank),'[]'::jsonb)
  ) into v_before
  from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=p_target_user_id;
  v_before:=coalesce(v_before,jsonb_build_object('roles','[]'::jsonb));

  delete from security.user_roles where user_id=p_target_user_id;

  insert into security.user_roles(user_id,role_code,granted_by,expires_at)
  select p_target_user_id,x,p_actor_user_id,p_expires_at
  from unnest(v_roles) x;

  select jsonb_build_object(
    'roles',coalesce(jsonb_agg(jsonb_build_object('code',ur.role_code,'expires_at',ur.expires_at) order by r.rank),'[]'::jsonb)
  ) into v_after
  from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=p_target_user_id;
  v_after:=coalesce(v_after,jsonb_build_object('roles','[]'::jsonb));

  insert into security.user_access_events(actor_user_id,target_user_id,action,before_state,after_state)
  values(p_actor_user_id,p_target_user_id,'roles_replaced',v_before,v_after);

  return v_after;
end
$$;


ALTER FUNCTION "public"."svc_admin_access_replace_roles"("p_actor_user_id" "uuid", "p_target_user_id" "uuid", "p_role_codes" "text"[], "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_admin_access_snapshot"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$
declare v_result jsonb;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'service role required' using errcode='42501';
  end if;

  select jsonb_build_object(
    'roles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'code',r.code,'name',r.name,'rank',r.rank,'description',r.description,'status',r.status
      ) order by r.rank)
      from security.roles r
      where r.status='active'
    ), '[]'::jsonb),
    'assignments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id',ur.user_id,'role_code',ur.role_code,'role_name',r.name,'rank',r.rank,
        'granted_at',ur.granted_at,'granted_by',ur.granted_by,'expires_at',ur.expires_at
      ) order by ur.user_id,r.rank)
      from security.user_roles ur
      join security.roles r on r.code=ur.role_code
    ), '[]'::jsonb),
    'events', coalesce((
      select jsonb_agg(to_jsonb(e) order by e.created_at desc)
      from (
        select id,actor_user_id,target_user_id,action,before_state,after_state,metadata,created_at
        from security.user_access_events
        order by created_at desc
        limit 100
      ) e
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end
$$;


ALTER FUNCTION "public"."svc_admin_access_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_admin_evidence_access_descriptor"("p_evidence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'storage', 'auth'
    AS $$
declare v_result jsonb;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'service role required' using errcode='42501'; end if;
  select jsonb_build_object(
    'evidence_id',e.id,
    'storage_path',e.storage_path,
    'mime_type',e.mime_type,
    'available',o.id is not null
  ) into v_result
  from pipeline.evidence_artifacts e
  left join storage.objects o on o.bucket_id='evidence' and o.name=e.storage_path
  where e.id=p_evidence_id;
  return coalesce(v_result,'{}'::jsonb);
end
$$;


ALTER FUNCTION "public"."svc_admin_evidence_access_descriptor"("p_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_cf245_capture_coverage_snapshot"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'search', 'ref', 'catalogue'
    AS $$
declare v_hour timestamptz:=date_trunc('hour',now()); v_rows integer:=0;
begin
  if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  with countries as (
    select trim(c.iso_alpha2)::text country_code,count(*)::bigint total_courses
    from search.course_documents d join ref.countries c on c.id=d.country_id
    where trim(c.iso_alpha2) in('AU','NZ') group by 1
  ), coverage as (
    select trim(c.iso_alpha2)::text country_code,'official_course_url'::text field_key,count(*) filter(where d.official_course_url is not null)::bigint covered_count
    from search.course_documents d join ref.countries c on c.id=d.country_id where trim(c.iso_alpha2) in('AU','NZ') group by 1
    union all
    select trim(c.iso_alpha2)::text,'intake_availability',count(*) filter(where jsonb_array_length(coalesce(d.intake_options,'[]'::jsonb))>0)::bigint
    from search.course_documents d join ref.countries c on c.id=d.country_id where trim(c.iso_alpha2) in('AU','NZ') group by 1
    union all
    select trim(c.iso_alpha2)::text,'english_requirements',count(*) filter(where jsonb_array_length(coalesce(d.english_requirement_options,'[]'::jsonb))>0)::bigint
    from search.course_documents d join ref.countries c on c.id=d.country_id where trim(c.iso_alpha2) in('AU','NZ') group by 1
    union all
    select trim(c.iso_alpha2)::text,'provider_current_international_tuition',count(*) filter(where d.has_provider_current_tuition)::bigint
    from search.course_documents d join ref.countries c on c.id=d.country_id where trim(c.iso_alpha2) in('AU','NZ') group by 1
    union all
    select trim(c.iso_alpha2)::text,'scholarship',count(*) filter(where jsonb_array_length(coalesce(d.scholarship_options,'[]'::jsonb))>0)::bigint
    from search.course_documents d join ref.countries c on c.id=d.country_id where trim(c.iso_alpha2) in('AU','NZ') group by 1
  ), backlog as (
    select country_code,field_key,
      count(*) filter(where backlog_state='queueable')::bigint queueable_count,
      count(*) filter(where backlog_state='blocked')::bigint blocked_count,
      count(*) filter(where backlog_state='awaiting_source_profile_qualification')::bigint awaiting_count
    from pipeline.au_nz_enrichment_backlog_v1 group by country_code,field_key
  )
  insert into pipeline.enrichment_coverage_snapshots(snapshot_hour,country_code,field_key,covered_count,total_courses,queueable_count,blocked_count,awaiting_qualification_count,not_applicable_count)
  select v_hour,cv.country_code,cv.field_key,cv.covered_count,co.total_courses,coalesce(b.queueable_count,0),coalesce(b.blocked_count,0),coalesce(b.awaiting_count,0),0
  from coverage cv join countries co using(country_code) left join backlog b using(country_code,field_key)
  on conflict(snapshot_hour,country_code,field_key) do update set covered_count=excluded.covered_count,total_courses=excluded.total_courses,queueable_count=excluded.queueable_count,blocked_count=excluded.blocked_count,awaiting_qualification_count=excluded.awaiting_qualification_count,not_applicable_count=excluded.not_applicable_count,observed_at=now();
  get diagnostics v_rows=row_count;
  return jsonb_build_object('ok',true,'snapshot_hour',v_hour,'rows',v_rows,'change_control_ref','CF-CHG-20260915-245');
end $$;


ALTER FUNCTION "public"."svc_cf245_capture_coverage_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_cf245_refresh_hourly_admin_cache"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare
  v_rows integer:=0;
begin
  if current_user not in('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  delete from pipeline.layer2_enrichment_hourly_admin_cache_v1
  where hour_utc < date_trunc('hour',now())-interval '8 days';

  delete from pipeline.layer2_enrichment_hourly_admin_cache_v1
  where hour_utc >= date_trunc('hour',now())-interval '168 hours';

  insert into pipeline.layer2_enrichment_hourly_admin_cache_v1
  select *
  from pipeline.layer2_enrichment_hourly_v1
  where hour_utc >= date_trunc('hour',now())-interval '168 hours';

  get diagnostics v_rows=row_count;
  return jsonb_build_object(
    'ok',true,
    'rows',v_rows,
    'observed_at',now(),
    'change_control_ref','CF-CHG-20260915-245'
  );
end $$;


ALTER FUNCTION "public"."svc_cf245_refresh_hourly_admin_cache"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_cf245_replay_observed_coursefacts"("p_limit" integer DEFAULT 100, "p_apply" boolean DEFAULT false, "p_source_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'ref', 'security'
    AS $$
declare
  v_limit integer:=least(greatest(coalesce(p_limit,100),1),500);
  v_intake_courses integer:=0;
  v_english_courses integer:=0;
  v_intake_rows integer:=0;
  v_english_rows integer:=0;
  v_fee_backlog integer:=0;
begin
  if current_user not in ('postgres','service_role') and coalesce(auth.role(),'')<>'service_role' then
    raise exception 'service_role required' using errcode='42501';
  end if;

  create temporary table if not exists pg_temp.cf245_replay_candidates(
    source_record_id uuid primary key,
    source_id uuid not null,
    evidence_id uuid not null,
    course_id uuid not null,
    provider_cricos text not null,
    course_cricos text not null,
    source_url text not null,
    parsed_payload jsonb not null,
    search_admitted boolean not null,
    intake_safe boolean not null,
    english_safe boolean not null,
    intake_missing_before boolean not null,
    english_missing_before boolean not null,
    fee_requires_layer3 boolean not null
  ) on commit drop;
  truncate pg_temp.cf245_replay_candidates;

  insert into pg_temp.cf245_replay_candidates
  with ranked as (
    select r.*,q.admitted_domains,q.metadata qualification_metadata,
           row_number() over(partition by r.source_id,r.course_cricos order by r.observed_at desc,r.id desc) rn
    from pipeline.course_fact_source_records r
    join pipeline.course_fact_source_qualifications q
      on q.source_id=r.source_id
     and upper(btrim(q.provider_cricos))=upper(btrim(r.provider_cricos))
     and q.qualification_status in ('qualified','bounded')
     and coalesce((q.metadata->>'apply_admitted')::boolean,false)
    where r.status='observed'
      and r.evidence_id is not null
      and (p_source_id is null or r.source_id=p_source_id)
      and coalesce((r.parsed_payload->>'identity_match')::boolean,false)
      and coalesce((r.parsed_payload->>'regulatory_code_seen')::boolean,false)
      and nullif(r.parsed_payload->>'course_id','') is not null
  ), resolved as (
    select r.*,(r.parsed_payload->>'course_id')::uuid course_id,
      exists(select 1 from catalogue.course_intakes ci where ci.course_id=(r.parsed_payload->>'course_id')::uuid and coalesce(ci.status,'active')='active') intake_exists,
      exists(select 1 from catalogue.course_english_requirements ce where ce.course_id=(r.parsed_payload->>'course_id')::uuid and coalesce(ce.status,'active')='active') english_exists,
      coalesce((r.qualification_metadata->>'search_admitted')::boolean,false) search_admitted
    from ranked r
    where r.rn=1
      and exists(
        select 1 from catalogue.courses c
        where c.id=(r.parsed_payload->>'course_id')::uuid
          and exists(select 1 from catalogue.course_registrations cr where cr.course_id=c.id and lower(cr.scheme)='cricos' and upper(btrim(cr.registration_code))=upper(btrim(r.course_cricos)))
          and exists(select 1 from catalogue.provider_registrations pr where pr.provider_id=c.provider_id and lower(pr.registration_scheme)='cricos' and upper(btrim(pr.registration_code))=upper(btrim(r.provider_cricos)) and coalesce(pr.status,'active') not in ('inactive','cancelled','archived'))
      )
      and not security.layer4_entity_or_parent_blocked('course',(r.parsed_payload->>'course_id')::uuid,'operational')
  )
  select id,source_id,evidence_id,course_id,provider_cricos,course_cricos,source_url,parsed_payload,search_admitted,
    coalesce(
      ('intake'=any(admitted_domains))
      and jsonb_typeof(coalesce(parsed_payload->'intakes','[]'::jsonb))='array'
      and exists(
        select 1 from jsonb_array_elements(coalesce(parsed_payload->'intakes','[]'::jsonb)) x(v)
        where jsonb_typeof(x.v)='string'
          and lower(trim(both '"' from x.v::text)) in ('january','february','march','april','may','june','july','august','september','october','november','december')
      ),false) as intake_safe,
    coalesce(('english_requirement'=any(admitted_domains)) and (
      nullif(parsed_payload->'english_requirements'->>'ielts_overall','')::numeric between 1 and 9
      or nullif(parsed_payload->'english_requirements'->>'pte_overall','')::numeric between 10 and 90
      or nullif(parsed_payload->'english_requirements'->>'toefl_overall','')::numeric between 1 and 120
    ),false) as english_safe,
    coalesce(not intake_exists,false),
    coalesce(not english_exists,false),
    coalesce(('international_fee'=any(admitted_domains))
      and coalesce((parsed_payload->>'fee_safe')::boolean,false)
      and nullif(parsed_payload->'provider_current_tuition'->>'amount','')::numeric>0
      and coalesce(parsed_payload->'provider_current_tuition'->>'basis','')='annual_or_indicative_requires_validation',false) as fee_requires_layer3
  from resolved
  where (not intake_exists or not english_exists or (
      ('international_fee'=any(admitted_domains))
      and coalesce((parsed_payload->>'fee_safe')::boolean,false)
      and parsed_payload->'provider_current_tuition' is not null
    ))
  order by (not intake_exists)::int+(not english_exists)::int desc, observed_at desc
  limit v_limit;

  select count(*) filter(where intake_safe and intake_missing_before),
         count(*) filter(where english_safe and english_missing_before),
         count(*) filter(where fee_requires_layer3)
    into v_intake_courses,v_english_courses,v_fee_backlog
  from pg_temp.cf245_replay_candidates;

  if not p_apply then
    return jsonb_build_object('apply',false,'selected_records',(select count(*) from pg_temp.cf245_replay_candidates),'intake_courses',v_intake_courses,'english_courses',v_english_courses,'fee_candidates_for_layer3',v_fee_backlog,'change_control_ref','CF-CHG-20260915-245');
  end if;

  with rows as (
    select c.*,initcap(lower(trim(both '"' from x.v::text))) intake_label
    from pg_temp.cf245_replay_candidates c
    cross join lateral jsonb_array_elements(coalesce(c.parsed_payload->'intakes','[]'::jsonb)) x(v)
    where c.intake_safe and c.intake_missing_before and jsonb_typeof(x.v)='string'
      and lower(trim(both '"' from x.v::text)) in ('january','february','march','april','may','june','july','august','september','october','november','december')
  ), ins as (
    insert into catalogue.course_intakes(course_id,intake_year,intake_label,start_date,application_deadline,campus_id,status,source_id,evidence_id,confidence,source_intake_key)
    select course_id,null,intake_label,null,null,null,'active',source_id,evidence_id,1,'cf245:'||lower(course_cricos)||':month:'||lower(intake_label)
    from rows
    on conflict(course_id,source_id,source_intake_key) where source_id is not null and source_intake_key is not null do nothing
    returning 1
  ) select count(*) into v_intake_rows from ins;

  with e as (
    select c.*,x.test_code,x.score
    from pg_temp.cf245_replay_candidates c
    cross join lateral (
      values
        ('IELTS'::text,nullif(c.parsed_payload->'english_requirements'->>'ielts_overall','')::numeric),
        ('PTE'::text,nullif(c.parsed_payload->'english_requirements'->>'pte_overall','')::numeric),
        ('TOEFL_IBT'::text,nullif(c.parsed_payload->'english_requirements'->>'toefl_overall','')::numeric)
    ) x(test_code,score)
    where c.english_safe and c.english_missing_before
      and ((x.test_code='IELTS' and x.score between 1 and 9) or (x.test_code='PTE' and x.score between 10 and 90) or (x.test_code='TOEFL_IBT' and x.score between 1 and 120))
  ), ins as (
    insert into catalogue.course_english_requirements(course_id,english_test_id,overall_score,component_scores,notes,source_id,evidence_id,confidence,source_requirement_key,status,valid_from,valid_to,last_verified_at)
    select e.course_id,t.id,e.score,'{}'::jsonb,'CF-245 deterministic replay from qualified first-party Evidence',e.source_id,e.evidence_id,1,'cf245:'||lower(e.course_cricos)||':'||lower(e.test_code),'active',null,null,now()
    from e join ref.english_tests t on t.code=e.test_code
    on conflict(course_id,english_test_id) do nothing
    returning 1
  ) select count(*) into v_english_rows from ins;

  insert into pipeline.layer2_field_admissions(source_record_id,course_id,source_id,evidence_id,field_key,status,reason_code,candidate_payload,canonical_changed,search_admission_eligible,change_control_ref,decided_at)
  select c.source_record_id,c.course_id,c.source_id,c.evidence_id,'intake_availability','admitted','deterministic_observed_replay',c.parsed_payload->'intakes',true,c.search_admitted,'CF-CHG-20260915-245',now()
  from pg_temp.cf245_replay_candidates c
  where c.intake_safe and c.intake_missing_before and exists(select 1 from catalogue.course_intakes ci where ci.course_id=c.course_id and ci.source_id=c.source_id and ci.evidence_id=c.evidence_id)
  on conflict(source_record_id,field_key) do nothing;

  insert into pipeline.layer2_field_admissions(source_record_id,course_id,source_id,evidence_id,field_key,status,reason_code,candidate_payload,canonical_changed,search_admission_eligible,change_control_ref,decided_at)
  select c.source_record_id,c.course_id,c.source_id,c.evidence_id,'english_requirements','admitted','deterministic_observed_replay',c.parsed_payload->'english_requirements',true,c.search_admitted,'CF-CHG-20260915-245',now()
  from pg_temp.cf245_replay_candidates c
  where c.english_safe and c.english_missing_before and exists(select 1 from catalogue.course_english_requirements ce where ce.course_id=c.course_id and ce.source_id=c.source_id and ce.evidence_id=c.evidence_id)
  on conflict(source_record_id,field_key) do nothing;

  return jsonb_build_object('apply',true,'selected_records',(select count(*) from pg_temp.cf245_replay_candidates),'intake_courses_targeted',v_intake_courses,'intake_rows_inserted',v_intake_rows,'english_courses_targeted',v_english_courses,'english_rows_inserted',v_english_rows,'fee_candidates_for_layer3',v_fee_backlog,'change_control_ref','CF-CHG-20260915-245');
end $$;


ALTER FUNCTION "public"."svc_cf245_replay_observed_coursefacts"("p_limit" integer, "p_apply" boolean, "p_source_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_cf245_run_tuition_benchmark"("p_case_limit" integer DEFAULT 4) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'net', 'public', 'extensions'
    AS $$
declare v_nonce uuid:=extensions.gen_random_uuid();v_request_id bigint;v_base text;
begin
  if current_user not in ('postgres','service_role') and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
  insert into pipeline.pilot_edge_nonces(id,function_name,expires_at) values(v_nonce,'layer3-cf245-tuition-benchmark',now()+interval '5 minutes');
  v_base:=public.coursefinder_runtime_edge_base_url();if v_base is null then raise exception 'runtime Edge base URL missing';end if;
  select net.http_post(url:=rtrim(v_base,'/')||'/layer3-cf245-tuition-benchmark',headers:=jsonb_build_object('content-type','application/json','x-cf-run-nonce',v_nonce::text),body:=jsonb_build_object('case_limit',least(greatest(coalesce(p_case_limit,4),3),6)),timeout_milliseconds:=120000) into v_request_id;
  return jsonb_build_object('request_id',v_request_id,'nonce',v_nonce,'case_limit',least(greatest(coalesce(p_case_limit,4),3),6));
end $$;


ALTER FUNCTION "public"."svc_cf245_run_tuition_benchmark"("p_case_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_cf245_run_tuition_benchmark"("p_case_limit" integer) IS 'CF-245 Pilot-only one-shot fee-specific Layer 3 benchmark dispatcher. Benchmark cannot mutate canonical fees; PASS only unpauses the dedicated validation profile.';



CREATE OR REPLACE FUNCTION "public"."svc_cf247_dispatch_layer3"("p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'net', 'public', 'extensions'
    AS $$
declare
  v_nonce uuid:=extensions.gen_random_uuid();
  v_request_id bigint;
  v_base text;
  v_limit integer:=least(greatest(coalesce(p_limit,10),1),25);
begin
  if current_user not in ('postgres','service_role')
     and coalesce(auth.role(),'')<>'service_role' then
    raise exception 'service_role required' using errcode='42501';
  end if;

  insert into pipeline.pilot_edge_nonces(id,function_name,expires_at)
  values(v_nonce,'layer3-work-dispatch',now()+interval '5 minutes');

  v_base:=public.coursefinder_runtime_edge_base_url();
  if v_base is null then raise exception 'runtime Edge base URL missing'; end if;

  select net.http_post(
    url:=rtrim(v_base,'/')||'/layer3-work-dispatch',
    headers:=jsonb_build_object(
      'content-type','application/json',
      'x-cf-run-nonce',v_nonce::text
    ),
    body:=jsonb_build_object(
      'limit',v_limit,
      'worker','cf247-manual-bounded'
    ),
    timeout_milliseconds:=120000
  ) into v_request_id;

  return jsonb_build_object(
    'request_id',v_request_id,
    'nonce',v_nonce,
    'limit',v_limit
  );
end $$;


ALTER FUNCTION "public"."svc_cf247_dispatch_layer3"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_course_link_search_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_on boolean; v_cap numeric; v_used numeric; v_lim int := greatest(1, least(coalesce(p_limit, 40), 200)); v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select enabled, monthly_credit_cap into v_on, v_cap from pipeline.course_link_search_settings where id = 1;
  select coalesce(sum(units), 0) into v_used from pipeline.coverage_vendor_usage where purpose = 'course_link_search' and at >= date_trunc('month', now());
  if not coalesce(v_on, false) or v_used + 2 * v_lim > v_cap then return '[]'::jsonb; end if;
  with pick as (
    select s.course_id, s.provider_id, s.stage, c.course_code, c.canonical_title, rc.search_domain
      from pipeline.course_link_search s join catalogue.courses c on c.id = s.course_id
      join pipeline.course_link_recipes rc on rc.provider_id = s.provider_id and rc.active
      left join pipeline.provider_priority pp on pp.provider_id = s.provider_id
     where s.state = 'queued'
     order by (s.stage <> 'cricos'), coalesce(pp.rank, 100000), md5(s.course_id::text || to_char(now(), 'YYYYMMDDHH24MI'))
     limit v_lim
     for update of s skip locked),
  upd as (
    update pipeline.course_link_search s set state = 'sent', sent_at = now(), req_id = null,
           query = case p.stage when 'cricos' then '"' || p.course_code || '" site:' || p.search_domain
                                else case when security.coverage_country(p.provider_id) = 'CA'
                                     then trim(regexp_replace(regexp_replace(regexp_replace(p.canonical_title, '\s*\([^)]*\)', ' ', 'g'), '\s+-\s+(UBCV|UBCO|Major|Honours|Open Learning)\M.*$', '', 'i'), '[:"]+', ' ', 'g')) || ' site:' || p.search_domain
                                     else '"' || replace(regexp_replace(p.canonical_title, '\s*\(\s*Level\s+\d{1,2}\s*\)\s*$', '', 'i'), '"', '') || '" site:' || p.search_domain end end
      from pick p where s.course_id = p.course_id
    returning s.course_id, s.provider_id, s.stage, s.query)
  select coalesce(jsonb_agg(jsonb_build_object('course_id', course_id, 'provider_id', provider_id, 'stage', stage, 'query', query)), '[]'::jsonb) into v from upd;
  return v;
end $_$;


ALTER FUNCTION "public"."svc_course_link_search_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_course_link_search_record"("p_course_id" "uuid", "p_http" integer, "p_urls" "text"[], "p_error" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.course_link_search%rowtype; v_c text[];
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into r from pipeline.course_link_search where course_id = p_course_id and state = 'sent' for update;
  if r.course_id is null then return 'not_sent'; end if;
  -- the worker ran out of time or credits before searching: back in the queue, no attempt counted
  if p_error in ('time budget', 'credit budget') then
    update pipeline.course_link_search set state = 'queued' where course_id = p_course_id;
    return 'requeued';
  end if;
  if p_http = 200 then
    v_c := security.course_link_pick_v1(r.provider_id, coalesce(p_urls, '{}'));
    if cardinality(v_c) > 0 then
      update pipeline.course_link_search set state = 'found', results = to_jsonb(p_urls), candidates = to_jsonb(v_c), cand_idx = 1,
             bound_url = v_c[1], done_at = now() where course_id = p_course_id;
      perform security.course_link_bind_v1(p_course_id, r.provider_id, v_c[1], case r.stage when 'cricos' then 'cricos_search' else 'title_search' end);
      return 'found';
    elsif r.stage = 'cricos' then
      update pipeline.course_link_search set stage = 'title', state = 'queued', results = to_jsonb(p_urls), attempts = 0 where course_id = p_course_id;
      return 'title_next';
    else
      update pipeline.course_link_search set state = 'none', results = to_jsonb(p_urls), done_at = now() where course_id = p_course_id;
      return 'none';
    end if;
  end if;
  update pipeline.course_link_search set attempts = attempts + 1, state = case when attempts + 1 >= 3 then 'error' else 'queued' end,
         results = jsonb_build_object('http_status', p_http, 'body', left(coalesce(p_error, ''), 300))
   where course_id = p_course_id;
  return 'failed';
end $$;


ALTER FUNCTION "public"."svc_course_link_search_record"("p_course_id" "uuid", "p_http" integer, "p_urls" "text"[], "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coursefacts_apply_record"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_provider_cricos" "text", "p_course_cricos" "text", "p_source_record_id" "text", "p_source_url" "text", "p_content_hash" "text", "p_payload" "jsonb", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 v_provider uuid;v_course uuid;v_record uuid;v_test uuid;r jsonb;
 v_fee_year int;v_amount numeric;v_currency text;v_basis text;v_fee_key text;v_audience text;
 v_links int:=0;v_fees int:=0;v_intakes int:=0;v_english int:=0;
begin
 if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required';end if;
 select pr.provider_id into v_provider from catalogue.provider_registrations pr join catalogue.providers p on p.id=pr.provider_id join ref.countries c on c.id=p.country_id where c.iso_alpha2='AU' and lower(pr.registration_scheme)='cricos' and upper(btrim(pr.registration_code))=upper(btrim(p_provider_cricos)) and coalesce(pr.status,'active') not in ('inactive','cancelled','archived') order by pr.checked_at desc nulls last limit 1;
 if v_provider is null then raise exception 'provider CRICOS not resolved';end if;
 select cr.course_id into v_course from catalogue.course_registrations cr join catalogue.courses c on c.id=cr.course_id where c.provider_id=v_provider and lower(cr.scheme)='cricos' and upper(btrim(cr.registration_code))=upper(btrim(p_course_cricos)) limit 1;
 if v_course is null then raise exception 'course CRICOS not resolved';end if;
 if p_apply and security.layer4_entity_or_parent_blocked('course',v_course,'operational') then raise exception 'course operationally blocked by Layer 4' using errcode='42501'; end if;
 if coalesce(btrim(p_source_record_id),'')='' or coalesce(btrim(p_source_url),'')='' or coalesce(btrim(p_content_hash),'')='' then raise exception 'source identity/evidence fields required';end if;
 if not exists(select 1 from pipeline.course_fact_source_qualifications q where q.source_id=p_source_id and q.provider_cricos=upper(btrim(p_provider_cricos)) and q.qualification_status in ('qualified','bounded')) then raise exception 'source not qualified for AU course facts';end if;
 if not p_apply then return jsonb_build_object('resolved',true,'provider_id',v_provider,'course_id',v_course,'would_apply_link',nullif(btrim(p_payload->>'course_url'),'') is not null,'would_apply_fee',p_payload ? 'fee_amount','would_apply_intakes',coalesce(jsonb_array_length(coalesce(p_payload->'intakes','[]'::jsonb)),0),'would_apply_english',coalesce(jsonb_array_length(coalesce(p_payload->'english_requirements','[]'::jsonb)),0));end if;
 insert into pipeline.course_fact_source_records(source_id,source_record_id,source_url,provider_cricos,course_cricos,content_hash,evidence_id,parsed_payload,status,observed_at)
 values(p_source_id,p_source_record_id,p_source_url,upper(btrim(p_provider_cricos)),upper(btrim(p_course_cricos)),p_content_hash,p_evidence_id,p_payload,'observed',now())
 on conflict(source_id,source_record_id,content_hash) do update set evidence_id=coalesce(excluded.evidence_id,pipeline.course_fact_source_records.evidence_id),parsed_payload=excluded.parsed_payload,observed_at=now(),error_text=null returning id into v_record;
 if nullif(btrim(p_payload->>'course_url'),'') is not null then
   insert into catalogue.course_links(course_id,link_type,url,audience,label,is_primary,status,source_id,evidence_id,confidence,last_verified_at,updated_at)
   values(v_course,coalesce(nullif(btrim(p_payload->>'link_type'),''),'official_course'),btrim(p_payload->>'course_url'),coalesce(nullif(btrim(p_payload->>'audience'),''),'international'),'Official provider course page',false,'active',p_source_id,p_evidence_id,1,now(),now())
   on conflict(course_id,link_type,url) do update set audience=excluded.audience,label=excluded.label,status='active',source_id=excluded.source_id,evidence_id=excluded.evidence_id,confidence=1,last_verified_at=now(),updated_at=now();
   v_links:=1;
 end if;
 if p_payload ? 'fee_amount' then
   v_fee_year:=nullif(p_payload->>'fee_year','')::int;v_amount:=nullif(p_payload->>'fee_amount','')::numeric;v_currency:=coalesce(nullif(btrim(p_payload->>'currency_code'),''),'AUD');v_basis:=nullif(btrim(p_payload->>'fee_basis'),'');v_audience:=coalesce(nullif(btrim(p_payload->>'audience'),''),'international');v_fee_key:=coalesce(nullif(btrim(p_payload->>'fee_key'),''),lower(upper(btrim(p_course_cricos))||':'||v_audience||':'||coalesce(v_fee_year::text,'current')||':'||coalesce(v_basis,'tuition')));
   if v_amount is null or v_amount<=0 then raise exception 'positive fee amount required';end if;
   if not exists(select 1 from ref.currencies where code=v_currency) then raise exception 'currency not seeded: %',v_currency;end if;
   insert into catalogue.course_fees(course_id,fee_year,audience,fee_type,amount,currency_code,basis,notes,source_id,evidence_id,confidence,campus_id,source_fee_key,status,last_verified_at,source_snapshot_at,updated_at)
   values(v_course,v_fee_year,v_audience,'provider_current_tuition',v_amount,v_currency,v_basis,p_payload->>'fee_notes',p_source_id,p_evidence_id,1,null,v_fee_key,'active',now(),now(),now())
   on conflict(course_id,source_id,source_fee_key) where source_id is not null and source_fee_key is not null do update set fee_year=excluded.fee_year,audience=excluded.audience,fee_type=excluded.fee_type,amount=excluded.amount,currency_code=excluded.currency_code,basis=excluded.basis,notes=excluded.notes,evidence_id=excluded.evidence_id,confidence=1,status='active',last_verified_at=now(),source_snapshot_at=now(),updated_at=now();
   v_fees:=1;
 end if;
 for r in select value from jsonb_array_elements(coalesce(p_payload->'intakes','[]'::jsonb)) loop
   if nullif(btrim(r->>'intake_label'),'') is null then raise exception 'intake_label required';end if;
   insert into catalogue.course_intakes(course_id,intake_year,intake_label,start_date,application_deadline,campus_id,status,source_id,evidence_id,confidence,source_intake_key)
   values(v_course,nullif(r->>'intake_year','')::int,r->>'intake_label',nullif(r->>'start_date','')::date,nullif(r->>'application_deadline','')::date,null,coalesce(nullif(r->>'status',''),'active'),p_source_id,p_evidence_id,1,coalesce(nullif(r->>'source_intake_key',''),lower(upper(btrim(p_course_cricos))||':'||coalesce((r->>'intake_year'),'current')||':'||(r->>'intake_label'))))
   on conflict(course_id,source_id,source_intake_key) where source_id is not null and source_intake_key is not null do update set intake_year=excluded.intake_year,intake_label=excluded.intake_label,start_date=excluded.start_date,application_deadline=excluded.application_deadline,status=excluded.status,evidence_id=excluded.evidence_id,confidence=1;
   v_intakes:=v_intakes+1;
 end loop;
 for r in select value from jsonb_array_elements(coalesce(p_payload->'english_requirements','[]'::jsonb)) loop
   select id into v_test from ref.english_tests where code=upper(btrim(r->>'test_code')) limit 1;
   if v_test is null then raise exception 'english test not seeded: %',r->>'test_code';end if;
   insert into catalogue.course_english_requirements(course_id,english_test_id,overall_score,component_scores,notes,source_id,evidence_id,confidence,source_requirement_key,status,valid_from,valid_to,last_verified_at)
   values(v_course,v_test,nullif(r->>'overall_score','')::numeric,coalesce(r->'component_scores','{}'::jsonb),r->>'notes',p_source_id,p_evidence_id,1,coalesce(nullif(r->>'source_requirement_key',''),lower(upper(btrim(p_course_cricos))||':'||upper(btrim(r->>'test_code')))),coalesce(nullif(r->>'status',''),'active'),nullif(r->>'valid_from','')::date,nullif(r->>'valid_to','')::date,now())
   on conflict(course_id,english_test_id) do update set overall_score=excluded.overall_score,component_scores=excluded.component_scores,notes=excluded.notes,source_id=excluded.source_id,evidence_id=excluded.evidence_id,confidence=1,source_requirement_key=excluded.source_requirement_key,status=excluded.status,valid_from=excluded.valid_from,valid_to=excluded.valid_to,last_verified_at=now();
   v_english:=v_english+1;
 end loop;
 update pipeline.course_fact_source_records set status='applied',applied_at=now() where id=v_record;
 return jsonb_build_object('resolved',true,'provider_id',v_provider,'course_id',v_course,'links_applied',v_links,'fees_applied',v_fees,'intakes_applied',v_intakes,'english_applied',v_english,'source_record_id',v_record);
end $$;


ALTER FUNCTION "public"."svc_coursefacts_apply_record"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_provider_cricos" "text", "p_course_cricos" "text", "p_source_record_id" "text", "p_source_url" "text", "p_content_hash" "text", "p_payload" "jsonb", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coursefacts_register_evidence"("p_source_id" "uuid", "p_source_url" "text", "p_storage_path" "text", "p_content_hash" "text", "p_mime_type" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pipeline'
    AS $$
declare v_id uuid;begin
 if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required';end if;
 insert into pipeline.evidence_artifacts(source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata)
 values(p_source_id,'source_snapshot',p_source_url,p_storage_path,p_content_hash,p_mime_type,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
 return v_id;end $$;


ALTER FUNCTION "public"."svc_coursefacts_register_evidence"("p_source_id" "uuid", "p_source_url" "text", "p_storage_path" "text", "p_content_hash" "text", "p_mime_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coursefacts_resolve_source"("p_system_code" "text", "p_provider_cricos" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pipeline', 'integration', 'catalogue', 'ref'
    AS $$
 select case when current_user='postgres' or coalesce(auth.role(),'')='service_role' then (
  select jsonb_build_object('source_id',s.id,'provider_id',s.provider_id,'system_code',sys.code,'country_code',c.iso_alpha2::text)
  from pipeline.sources s join integration.systems sys on sys.id=s.system_id join catalogue.providers p on p.id=s.provider_id join ref.countries c on c.id=p.country_id
  where sys.code=p_system_code and exists(select 1 from catalogue.provider_registrations pr where pr.provider_id=p.id and lower(pr.registration_scheme)='cricos' and pr.registration_code=upper(trim(p_provider_cricos))) and s.status='active' limit 1
 ) else null end $$;


ALTER FUNCTION "public"."svc_coursefacts_resolve_source"("p_system_code" "text", "p_provider_cricos" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coverage_ai_match_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select q.id from pipeline.coverage_ai_match q
      left join pipeline.course_priority cp on cp.course_id = q.course_id
      left join pipeline.provider_priority pp on pp.provider_id = q.provider_id
     where q.state = 'ready' or (q.state = 'leased' and q.leased_until < now())
     order by (q.state = 'leased'), coalesce(cp.sort, 1000000), coalesce(pp.rank, 100000), q.id
     limit greatest(1, least(coalesce(p_limit, 20), 80)) for update of q skip locked),
  upd as (update pipeline.coverage_ai_match q set state = 'leased', leased_until = now() + interval '10 minutes' from pick where q.id = pick.id returning q.*)
  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'course_id', u.course_id, 'provider_id', u.provider_id, 'title', co.canonical_title,
           'code', case when co.course_code ~ '^[0-9a-f]{8}-' then null else co.course_code end,
           'level', (select sl.name from ref.study_levels sl where sl.id = co.study_level_id),
           'provider', coalesce(pr.display_name, pr.canonical_name), 'country', security.coverage_country(u.provider_id),
           'candidates', u.candidates)), '[]'::jsonb)
    into v from upd u join catalogue.courses co on co.id = u.course_id join catalogue.providers pr on pr.id = u.provider_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_coverage_ai_match_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coverage_ai_match_record"("p_id" bigint, "p_url" "text", "p_answer" "jsonb", "p_model" "text", "p_cost" numeric, "p_error" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
declare q pipeline.coverage_ai_match%rowtype; v_state text;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into q from pipeline.coverage_ai_match where id = p_id for update;
  if q.id is null or q.state <> 'leased' then return 'not_leased'; end if;
  if p_error ~ '^HTTP (401|402|403|429)\M' or p_error = 'time budget' then
    update pipeline.coverage_ai_match set state = 'ready', leased_until = null where id = p_id;
    return 'released';
  end if;
  if p_error is not null then
    v_state := 'error';
  elsif p_url is null then
    v_state := 'none';
  elsif not exists (select 1 from jsonb_array_elements(q.candidates) x where x->>'url' = p_url) then
    v_state := 'error'; p_answer := coalesce(p_answer, '{}'::jsonb) || jsonb_build_object('refused', 'chosen address is not one of the candidates');
  else
    v_state := 'chosen';
    insert into pipeline.coverage_course_pages(course_id, provider_id, url, score, runner_up, basis, status, bound_at, next_read_at, read_attempts)
    values (q.course_id, q.provider_id, p_url, null, null, 'ai_match', 'bound', now(), now(), 0)
    on conflict (course_id) do update set url = excluded.url, score = null, runner_up = null, basis = 'ai_match', status = 'bound', bound_at = now(),
           next_read_at = now(), read_attempts = 0, read_status = null, identity_basis = null, leased_until = null
     where (pipeline.coverage_course_pages.status = 'mismatch' or pipeline.coverage_course_pages.basis = 'ai_match')
       and coalesce(pipeline.coverage_course_pages.basis, '') <> 'manual';
  end if;
  update pipeline.coverage_ai_match set state = v_state, chosen_url = case when v_state = 'chosen' then p_url end, answer = coalesce(p_answer, '{}'::jsonb) || case when p_error is not null then jsonb_build_object('error', left(p_error, 300)) else '{}'::jsonb end,
         model = p_model, cost_usd = p_cost, decided_at = now(), leased_until = null
   where id = p_id;
  return v_state;
end $$;


