CREATE OR REPLACE FUNCTION "public"."svc_coverage_read_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  with due as (
    select p.course_id, p.provider_id, p.status st, coalesce(pp.rank,100000) prank, coalesce(cp.sort,1000000) csort, row_number() over (partition by p.provider_id order by (p.status<>'bound'), p.next_read_at) rk
      from pipeline.coverage_course_pages p left join pipeline.provider_priority pp on pp.provider_id=p.provider_id left join pipeline.course_priority cp on cp.course_id=p.course_id
     where p.status in ('bound','ambiguous') and coalesce(p.next_read_at,now())<=now() and coalesce(p.leased_until,'-infinity')<now() and p.read_attempts<3),
  pick as (select course_id from due where rk<=8 order by csort, least(prank,101), (st<>'bound'), rk, random() limit greatest(1,least(coalesce(p_limit,20),60))),
  upd as (update pipeline.coverage_course_pages p set leased_until=now()+interval '10 minutes', read_attempts=p.read_attempts+1
            from pick where p.course_id=pick.course_id returning p.course_id, p.provider_id, p.url, p.status, p.basis)
  select coalesce(jsonb_agg(jsonb_build_object('course_id',u.course_id,'provider_id',u.provider_id,'url',u.url,'title',c.canonical_title,'code',c.course_code,'country',security.coverage_country(u.provider_id),'status',u.status,'basis',u.basis,'manual',coalesce(u.basis='manual',false),'rendered_before',(exists (select 1 from pipeline.coverage_course_pages q where q.course_id=u.course_id and q.fetched_via='firecrawl') or exists (select 1 from pipeline.page_link_repairs x where x.course_id=u.course_id and x.reason like 'university adapter: international view read%')),'priority',coalesce((select pp.rank<=100 from pipeline.provider_priority pp where pp.provider_id=u.provider_id),false) or exists (select 1 from pipeline.course_priority cp where cp.course_id=u.course_id))),'[]'::jsonb)
    into v from upd u join catalogue.courses c on c.id=u.course_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_coverage_read_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coverage_read_record"("p_course_id" "uuid", "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_identity_basis" "text", "p_storage_path" "text", "p_sha256" "text", "p_candidates" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'security'
    AS $_$
declare v_row pipeline.coverage_course_pages%rowtype; v_ev uuid; v_src uuid;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  select * into v_row from pipeline.coverage_course_pages where course_id=p_course_id;
  if v_row.course_id is null then raise exception 'course page not bound'; end if;
  -- night run: a page read and confirmed before keeps its reading when a later read fails for a passing reason
  if p_read_status in ('fetch_failed', 'blocked', 'needs_render', 'too_thin', 'not_html') and v_row.read_status = 'read' and v_row.identity_basis is not null and v_row.evidence_id is not null then
    update pipeline.coverage_course_pages set http_status = p_http_status, leased_until = null, next_read_at = case when p_read_status = 'needs_render' then date_trunc('month', now()) + interval '1 month 1 hour' else now() + interval '7 days' end where course_id = p_course_id;
    return jsonb_build_object('evidence_id', null, 'kept_previous_read', true, 'failed_as', p_read_status);
  end if;
  if p_storage_path is not null and p_sha256 ~ '^[0-9a-f]{64}$' then
    v_src:=security.coverage_sweep_source(v_row.provider_id);
    select id into v_ev from pipeline.evidence_artifacts where source_id=v_src and content_hash=p_sha256 and source_url=v_row.url limit 1;
    if v_ev is null then
      v_ev:=public.svc_coursefacts_register_evidence(v_src, v_row.url, p_storage_path, p_sha256, 'text/html',
        jsonb_build_object('layer',2,'kind','provider_course_page','worker','coverage-sweep','course_id',p_course_id,'identity_basis',p_identity_basis,'fetched_via',p_fetched_via,'gzip',true));
    end if;
  end if;
  update pipeline.coverage_course_pages set read_status=p_read_status, read_at=now(), http_status=p_http_status, fetched_via=p_fetched_via,
         identity_basis=p_identity_basis, evidence_id=coalesce(v_ev,evidence_id), candidates=p_candidates, leased_until=null,
         next_read_at=case when p_read_status in ('read','identity_mismatch') then now()+make_interval(days => coalesce((select a.read_cycle_days from pipeline.uni_adapters a where a.provider_id=v_row.provider_id), 90)) when p_read_status='needs_render' then date_trunc('month',now())+interval '1 month 1 hour' else now()+interval '6 hours' end,
         read_attempts=case when p_read_status='needs_render' then greatest(read_attempts-1,0) else read_attempts end,
         status=case when p_read_status='identity_mismatch' then 'mismatch' when status='ambiguous' and p_identity_basis='cricos_code' then 'bound' else status end,
         basis=case when status='ambiguous' and p_identity_basis='cricos_code' then 'cricos_code_on_page' else basis end
   where course_id=p_course_id;
  return jsonb_build_object('evidence_id',v_ev);
end $_$;


ALTER FUNCTION "public"."svc_coverage_read_record"("p_course_id" "uuid", "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_identity_basis" "text", "p_storage_path" "text", "p_sha256" "text", "p_candidates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coverage_reextract_next"("p_limit" integer, "p_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('course_id',cp.course_id,'storage_path',e.storage_path,'title',c.canonical_title,'code',c.course_code,'status',cp.status,'url',cp.url,'country',security.coverage_country(cp.provider_id))),'[]'::jsonb)
    into v
    from (select * from pipeline.coverage_course_pages cp0
           where cp0.read_status='read' and cp0.identity_basis is not null and cp0.evidence_id is not null
             and coalesce(cp0.candidates->>'extractor','')<>p_version
           order by exists (select 1 from pipeline.layer4_review_items r4 where r4.entity_id = cp0.course_id and r4.status = 'pending'
                          and r4.field_code = 'provider_current_tuition_validation') desc, cp0.read_at limit greatest(1,least(coalesce(p_limit,50),200))) cp
    join pipeline.evidence_artifacts e on e.id=cp.evidence_id join catalogue.courses c on c.id=cp.course_id;
  return v;
end $$;


