  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.coverage_vendor_usage(acquisition_provider_id,units,purpose,provider_id,url)
  select id, p_units, p_purpose, p_provider_id, left(p_url,500) from pipeline.layer2_acquisition_providers where provider_key='firecrawl';
end $$;


ALTER FUNCTION "public"."svc_coverage_usage"("p_units" numeric, "p_purpose" "text", "p_provider_id" "uuid", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_directory_anchor_hints"("p_site" "text", "p_country" "text", "p_page_id" bigint, "p_page_url" "text", "p_anchors" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
declare v_n int;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.directory_institutions(site, country_code, directory_id, name, profile_url, website_hint, first_seen_page)
  select distinct on (h) p_site, p_country, h, left(a->>'text', 200), p_page_url, a->>'href', p_page_id
    from jsonb_array_elements(coalesce(p_anchors, '[]'::jsonb)) a
    cross join lateral (select lower(regexp_replace(substring(a->>'href' from '^https?://([^/:?#]+)'), '^www\.', '')) h) x
   where p_country is not null and x.h is not null and length(coalesce(a->>'text', '')) >= 3
   order by h
  on conflict (site, country_code, directory_id) do update set name = excluded.name, website_hint = excluded.website_hint, updated_at = now();
  get diagnostics v_n = row_count;
  return jsonb_build_object('hints', v_n, 'match', security.directory_match_v1(p_site));
end $$;


ALTER FUNCTION "public"."svc_directory_anchor_hints"("p_site" "text", "p_country" "text", "p_page_id" bigint, "p_page_url" "text", "p_anchors" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_directory_page_record"("p_site" "text", "p_country" "text", "p_url" "text", "p_final_url" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_title" "text", "p_links" "jsonb", "p_text" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_id bigint;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.directory_pages(site, country_code, url, final_url, http_status, storage_path, sha256, title, links, page_text)
  values (p_site, p_country, p_url, p_final_url, p_http, p_storage_path, p_sha256, left(p_title, 300), coalesce(p_links, '[]'::jsonb), left(p_text, 20000))
  returning id into v_id;
  -- Hotcourses institution profile links: /study/<country>/school-college-university/<slug>/<id>/international.html
  if p_site = 'hotcourses' then
    insert into pipeline.directory_institutions(site, country_code, directory_id, name, profile_url, first_seen_page)
    select distinct on (x.m[2]) 'hotcourses', p_country, x.m[2], initcap(replace(x.m[1], '-', ' ')), split_part(l, '#', 1), v_id
      from jsonb_array_elements_text(coalesce(p_links, '[]'::jsonb)) l
      cross join lateral (select regexp_match(l, '/study/[a-z-]+/school-college-university/([a-z0-9-]+)/([0-9]+)/international\.html') m) x
     where p_country is not null and x.m is not null
     order by x.m[2]
    on conflict (site, country_code, directory_id) do nothing;
  end if;
  return v_id;
end $$;


ALTER FUNCTION "public"."svc_directory_page_record"("p_site" "text", "p_country" "text", "p_url" "text", "p_final_url" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_title" "text", "p_links" "jsonb", "p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_english_table_apply"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb", "p_table1" "jsonb", "p_table3" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'security', 'search'
    AS $_$
declare v_source uuid; v_e1 uuid; v_e3 uuid; r record; v_ok int:=0; v_skipped jsonb:='[]'::jsonb; v_courses uuid[]:='{}'; v_doc jsonb; v_ev uuid; v_res jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  -- only courses with no English requirement are written; existing course-page values are never overwritten
  if jsonb_array_length(coalesce(p_programs,'[]'::jsonb))<30 then raise exception 'too few Table 1 programs; apply refused'; end if;
  if not exists(select 1 from jsonb_array_elements(p_minimum) q where q->>'test_code'='IELTS') then raise exception 'minimum IELTS requirement missing; apply refused'; end if;
  select s.id into v_source from pipeline.sources s where s.source_type='provider_english_requirements' and s.metadata->>'provider_cricos'=upper(btrim(p_provider_cricos))
     and exists(select 1 from pipeline.course_fact_source_qualifications q where q.source_id=s.id and q.qualification_status='qualified' and 'english_requirement'=any(q.admitted_domains));
  if v_source is null then raise exception 'no qualified English requirements source for provider %', p_provider_cricos; end if;
  foreach v_doc in array array[p_table1,p_table3] loop
    if coalesce(v_doc->>'storage_path','')='' or coalesce(v_doc->>'sha256','') !~ '^[0-9a-f]{64}$' then raise exception 'stored table file and its SHA-256 are required'; end if;
    select e.id into v_ev from pipeline.evidence_artifacts e where e.source_id=v_source and e.content_hash=v_doc->>'sha256' limit 1;
    if v_ev is null then
      v_ev:=public.svc_coursefacts_register_evidence(v_source,v_doc->>'url',v_doc->>'storage_path',v_doc->>'sha256','application/pdf',
        jsonb_build_object('layer',2,'kind','provider_english_requirements','document',v_doc->>'document','worker','fee-schedule-etl','decision','Decision 162 step 4'));
    end if;
    if v_doc is not distinct from p_table1 then v_e1:=v_ev; else v_e3:=v_ev; end if;
  end loop;
  for r in select * from security.english_table_plan_v1(p_provider_cricos,p_programs,p_minimum)
            where plan in ('table1','minimum') and comparison='none' and course_cricos is not null loop
    begin
      v_res:=public.svc_coursefacts_apply_record(v_source, case when r.plan='table1' then v_e1 else v_e3 end, p_provider_cricos, r.course_cricos,
        'uq-elp:'||r.plan||':'||r.course_cricos, case when r.plan='table1' then p_table1->>'url' else p_table3->>'url' end,
        case when r.plan='table1' then p_table1->>'sha256' else p_table3->>'sha256' end,
        jsonb_build_object('english_requirements',(select jsonb_agg(jsonb_build_object('test_code',q->>'test_code','overall_score',q->'overall_score','component_scores',coalesce(q->'component_scores','{}'::jsonb),
            'source_requirement_key','d162-elp:'||lower(r.course_cricos)||':'||lower(q->>'test_code'),
            'notes',case when r.reason like 'double degree:%' then 'Decision 162: UQ '||r.reason when r.plan='table1' then 'Decision 162: UQ ELP Table 1 (higher-than-minimum) - '||r.program else 'Decision 162: UQ minimum ELP (Procedure cl. 10-11; Table 3)' end))
          from jsonb_array_elements(r.requirements) q),'extraction_worker','fee-schedule-etl','plan',r.plan,'table1_program',r.program), true);
      v_ok:=v_ok+1; v_courses:=v_courses||r.course_id;
    exception when others then v_skipped:=v_skipped||jsonb_build_object('course',r.title,'reason',left(sqlerrm,200));
    end;
  end loop;
  if cardinality(v_courses)>0 then perform search.refresh_course_enrichment_scoped_v1(v_courses,true); end if;
  return jsonb_build_object('applied',v_ok,'skipped',jsonb_array_length(v_skipped),'skipped_detail',v_skipped,'source_id',v_source,'table1_evidence',v_e1,'table3_evidence',v_e3);
end $_$;


ALTER FUNCTION "public"."svc_english_table_apply"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb", "p_table1" "jsonb", "p_table3" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_english_table_preview"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  with pl as (select * from security.english_table_plan_v1(p_provider_cricos,p_programs,p_minimum)),
       t1 as (select e->>'name' name, e->>'section' section from jsonb_array_elements(p_programs) e)
  select jsonb_build_object(
    'courses',(select count(*) from pl),
    'by_plan',(select jsonb_object_agg(plan,n) from (select plan,count(*) n from pl group by 1) x),
    'by_comparison',(select jsonb_object_agg(plan||':'||comparison,n) from (select plan,comparison,count(*) n from pl where comparison is not null group by 1,2) x),
    'would_write',(select count(*) from pl where plan in ('table1','minimum') and comparison='none' and course_cricos is not null),
    'held_by_reason',(select jsonb_object_agg(reason,n) from (select reason,count(*) n from pl where plan='held' group by 1) x),
    'table1_programs',(select jsonb_agg(jsonb_build_object('program',t1.name,'section',t1.section,
         'courses',(select count(*) from pl where pl.program=t1.name)) order by t1.name) from t1),
    'table1_not_in_catalogue',(select jsonb_agg(t1.name order by t1.name) from t1 where not exists(select 1 from pl where pl.program=t1.name)),
    'differs',(select jsonb_agg(jsonb_build_object('title',title,'plan',plan,'program',program,'planned',(select jsonb_object_agg(q->>'test_code',q->'overall_score') from jsonb_array_elements(requirements) q),'existing',existing) order by title) from pl where comparison='differs'),
    'held',(select jsonb_agg(jsonb_build_object('title',title,'reason',reason,'existing',existing) order by reason,title) from pl where plan='held'),
    'written_sample',(select jsonb_agg(x) from (select jsonb_build_object('title',title,'plan',plan,'ielts',(select q->'overall_score' from jsonb_array_elements(requirements) q where q->>'test_code'='IELTS')) x from pl where plan in ('table1','minimum') and comparison='none' order by plan desc,title limit 12) s)
  ) into v;
  return v;
end $$;


ALTER FUNCTION "public"."svc_english_table_preview"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_evidence_dedupe_mark"("p_paths" "text"[], "p_ok" boolean, "p_error" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  with u as (update pipeline.evidence_storage_dedupe_log set status=case when p_ok then 'deleted' else 'failed' end,
             deleted_at=case when p_ok then now() end, error=left(p_error,500) where path=any(p_paths) and status='repointed' returning 1)
  select count(*)::int from u
$$;


ALTER FUNCTION "public"."svc_evidence_dedupe_mark"("p_paths" "text"[], "p_ok" boolean, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_evidence_dedupe_next"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select coalesce(jsonb_agg(l.path),'[]'::jsonb) from (
    select l.path from pipeline.evidence_storage_dedupe_log l
     where l.status='repointed'
       and not exists (select 1 from pipeline.evidence_artifacts e where e.storage_path=l.path)
       and not exists (select 1 from pipeline.evidence_lineage_reconciliations r where r.storage_path=l.path)
       and not exists (select 1 from ranking.manual_imports m where m.storage_path=l.path)
       and not exists (select 1 from catalogue.provider_assets a where a.storage_path=l.path)
       and not exists (select 1 from pipeline.provider_contact_import_batches b where b.storage_path=l.path)
     order by l.id limit greatest(1,least(coalesce(p_limit,100),500))) l
$$;


ALTER FUNCTION "public"."svc_evidence_dedupe_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_evidence_dedupe_sample"("p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('path',path,'keeper_path',keeper_path,'content_hash',content_hash)),'[]'::jsonb)
  from (select path, keeper_path, content_hash from pipeline.evidence_storage_dedupe_log where status='repointed' order by random() limit greatest(1,least(coalesce(p_limit,10),30))) s
$$;


ALTER FUNCTION "public"."svc_evidence_dedupe_sample"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_evidence_link_index_next_v1"("p_limit" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'path',x.storage_path,'mime',x.mime_type,'url',x.source_url,'type',x.evidence_type)),'[]'::jsonb)
  from (select e.id, e.storage_path, e.mime_type, e.source_url, e.evidence_type
        from pipeline.evidence_artifacts e
        left join pipeline.evidence_link_index_state st on st.evidence_id=e.id
        join pipeline.sources s on s.id=e.source_id
        join pipeline.layer2_onboarding_snapshot o on o.provider_id=s.provider_id
        where e.storage_path is not null and e.storage_path !~ '^[a-z-]+://'
          and e.evidence_type in ('layer2_html_snapshot','layer2_extraction_input','source_snapshot','provider_contact_html_snapshot')
          and (e.mime_type ilike '%html%' or e.mime_type ilike '%json%')
          and (st.evidence_id is null or (st.status='error' and st.indexed_at < now()-interval '6 hours'))
        order by o.rank_no, e.captured_at desc nulls last
        limit greatest(1,least(coalesce(p_limit,60),200))) x
$$;


ALTER FUNCTION "public"."svc_evidence_link_index_next_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_evidence_link_index_record_v1"("p_evidence_id" "uuid", "p_status" "text", "p_links" "jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $_$
declare v_n int := 0; v_provider uuid;
begin
  select s.provider_id into v_provider from pipeline.evidence_artifacts e join pipeline.sources s on s.id=e.source_id where e.id=p_evidence_id;
  if p_status='indexed' and jsonb_typeof(p_links)='array' and v_provider is not null then
    insert into pipeline.provider_discovery_links as d(provider_id,url,anchor_text,pages,evidence_id,score_text,first_seen_at,last_seen_at)
    select v_provider, url, txt, 1, p_evidence_id, lower(coalesce(txt,'')), now(), now()
    from (select distinct on (left(l->>'url',1000)) left(l->>'url',1000) url, nullif(left(l->>'text',200),'') txt, ord
            from jsonb_array_elements(p_links) with ordinality t(l,ord)
           where l->>'url' ~ '^https?://' and coalesce(l->>'host','')<>'' and coalesce((l->>'same_site')::boolean,false)
             and (lower(l->>'url')||' '||lower(coalesce(l->>'text','')))
                 ~ '(study|course|degree|program|programme|handbook|undergrad|postgrad|find|search|explore|browse)'
             and lower(l->>'url') !~ '\.(pdf|jpg|jpeg|png|gif|svg|webp|mp4|docx?|xlsx?|zip)(\?|$)'
           order by left(l->>'url',1000), ord) x
    order by ord
    limit 200
    on conflict (provider_id,url) do update set
      pages=d.pages+1,
      anchor_text=case when length(coalesce(excluded.anchor_text,''))>length(coalesce(d.anchor_text,'')) then excluded.anchor_text else d.anchor_text end,
      score_text=greatest(d.score_text,excluded.score_text),
      last_seen_at=now();
    get diagnostics v_n = row_count;
  end if;
  insert into pipeline.evidence_link_index_state(evidence_id,status,link_count,error,indexed_at)
  values (p_evidence_id, case when p_status='indexed' and v_n=0 then 'no_links' else p_status end, v_n, left(p_error,500), now())
  on conflict (evidence_id) do update set status=excluded.status, link_count=excluded.link_count, error=excluded.error, indexed_at=excluded.indexed_at;
  return v_n;
end $_$;


ALTER FUNCTION "public"."svc_evidence_link_index_record_v1"("p_evidence_id" "uuid", "p_status" "text", "p_links" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_fc_call_log"("p" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.firecrawl_calls(run_id, item_id, use_case, endpoint, provider_id, course_id, url, request, http, success, error, scrape_id, credits_used, proxy_used, page_status, duration_ms, outcome, meta)
  values ((p->>'run_id')::uuid, (p->>'item_id')::uuid, coalesce(p->>'use_case', 'unknown'), coalesce(p->>'endpoint', 'unknown'), (p->>'provider_id')::uuid, (p->>'course_id')::uuid,
          left(p->>'url', 2000), coalesce(p->'request', '{}'::jsonb), (p->>'http')::int, coalesce((p->>'success')::boolean, false), left(p->>'error', 1000), left(p->>'scrape_id', 200),
          (p->>'credits_used')::numeric, left(p->>'proxy_used', 40), (p->>'page_status')::int, (p->>'duration_ms')::int, left(p->>'outcome', 60), coalesce(p->'meta', '{}'::jsonb));
end $$;


ALTER FUNCTION "public"."svc_fc_call_log"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_fc_extract_cases"("p_task_class" "text", "p_offset" integer, "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('case_id', c.id, 'task_class', c.task_class, 'url', c.source_url, 'gold', c.gold) order by c.case_key), '[]'::jsonb) into v
    from (select * from pipeline.layer3_holdout_cases where task_class = p_task_class order by case_key offset greatest(0, coalesce(p_offset, 0)) limit greatest(1, least(coalesce(p_limit, 50), 100))) c;
  return v;
end $$;


ALTER FUNCTION "public"."svc_fc_extract_cases"("p_task_class" "text", "p_offset" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_fc_extract_result"("p_run_label" "text", "p_case_id" "uuid", "p_task_class" "text", "p_answer" "jsonb", "p_outcome" "text", "p_quote_in_page" boolean, "p_credits" integer, "p_http" integer, "p_error" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.fc_extract_results(run_label, case_id, task_class, answer, outcome, quote_in_page, credits, http, error)
  values (p_run_label, p_case_id, p_task_class, p_answer, p_outcome, p_quote_in_page, coalesce(p_credits, 0), p_http, left(p_error, 300))
  on conflict (run_label, case_id) do update set answer = excluded.answer, outcome = excluded.outcome, quote_in_page = excluded.quote_in_page,
    credits = excluded.credits, http = excluded.http, error = excluded.error, created_at = now();
end $$;


ALTER FUNCTION "public"."svc_fc_extract_result"("p_run_label" "text", "p_case_id" "uuid", "p_task_class" "text", "p_answer" "jsonb", "p_outcome" "text", "p_quote_in_page" boolean, "p_credits" integer, "p_http" integer, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_fc_find_bind"("p_item_id" "uuid", "p_candidates" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_i pipeline.firecrawl_run_items%rowtype; v_c jsonb := coalesce(p_candidates, '[]'::jsonb); v_url text; v_pg pipeline.coverage_course_pages%rowtype; v_up boolean; v_pat text;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into v_i from pipeline.firecrawl_run_items where id = p_item_id;
  if v_i.id is null or v_i.course_id is null then return 'no_course'; end if;
  if jsonb_typeof(v_c) <> 'array' or jsonb_array_length(v_c) = 0 then return 'no_candidate'; end if;
  if exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = v_i.course_id and k.field = 'official_url') then return 'entered_by_hand'; end if;
  select * into v_pg from pipeline.coverage_course_pages where course_id = v_i.course_id;
  -- Decision 253 (Platform Admin 22:43): a better page for a course whose page is confirmed but lacks the fields (the
  -- university adapter reads them on another kind of page). Only a result matching the run's page pattern is taken.
  v_up := coalesce((v_i.input->>'upgrade')::boolean, false) and coalesce(v_i.input->>'upgrade_pattern', '') <> '';
  if v_up then
    v_pat := v_i.input->>'upgrade_pattern';
    select x.u into v_url from jsonb_array_elements_text(v_c) with ordinality x(u, n) where x.u ~* v_pat order by x.n limit 1;
    if v_url is null then return 'no_better_page'; end if;
    if v_pg.course_id is not null and v_pg.url = v_url then return 'same_page'; end if;
    insert into pipeline.page_link_repairs(course_id, provider_id, old_url, new_url, reason, run_id)
      values (v_i.course_id, v_i.provider_id, v_pg.url, v_url, 'firecrawl search: page with the fields the adapter reads', v_i.run_id);
    insert into pipeline.coverage_course_pages(course_id, provider_id, url, basis, status, bound_at, next_read_at, read_attempts)
      values (v_i.course_id, v_i.provider_id, v_url, 'firecrawl_upgrade', 'bound', now(), now(), 0)
    on conflict (course_id) do update set url = excluded.url, basis = excluded.basis, status = 'bound', bound_at = now(), score = null, runner_up = null, read_status = null, read_at = null, http_status = null, fetched_via = null, identity_basis = null, evidence_id = null, candidates = null, leased_until = null, read_attempts = 0, next_read_at = now() where pipeline.coverage_course_pages.course_id = excluded.course_id;
    insert into pipeline.search_pass_links(course_id, provider_id, run_id, candidates, cand_idx, bound_url, refind, state, updated_at, engine)
      values (v_i.course_id, v_i.provider_id, v_i.run_id, v_c, 1, v_url, true, 'found', now(), 'firecrawl')
    on conflict (course_id) do update set run_id = excluded.run_id, candidates = excluded.candidates, cand_idx = excluded.cand_idx, bound_url = excluded.bound_url, refind = excluded.refind, state = 'found', updated_at = now(), engine = 'firecrawl' where pipeline.search_pass_links.course_id = excluded.course_id;
    return 'bound';
  end if;
  if v_pg.course_id is not null and v_pg.status in ('bound', 'ambiguous') and not (v_pg.evidence_id is null and v_pg.read_status in ('needs_render', 'blocked', 'fetch_failed', 'too_thin') and coalesce((v_i.input->>'refind')::boolean, false)) then return 'page_already_bound'; end if;
  v_url := v_c->>0;
  if v_pg.course_id is not null and v_pg.url = v_url then
    if jsonb_array_length(v_c) < 2 then return 'already_refused'; end if;
    v_url := v_c->>1;
  end if;
  insert into pipeline.page_link_repairs(course_id, provider_id, old_url, new_url, reason, run_id)
    values (v_i.course_id, v_i.provider_id, v_pg.url, v_url, case when coalesce((v_i.input->>'refind')::boolean, false) then 'firecrawl search: better page for an unreadable one' else 'firecrawl search: page found' end, v_i.run_id);
  insert into pipeline.coverage_course_pages(course_id, provider_id, url, basis, status, bound_at, next_read_at, read_attempts)
    values (v_i.course_id, v_i.provider_id, v_url, 'firecrawl_search', 'bound', now(), now(), 0)
  on conflict (course_id) do update set url = excluded.url, basis = excluded.basis, status = 'bound', bound_at = now(), score = null, runner_up = null, read_status = null, read_at = null, http_status = null, fetched_via = null, identity_basis = null, evidence_id = null, candidates = null, leased_until = null, read_attempts = 0, next_read_at = now() where pipeline.coverage_course_pages.status not in ('bound', 'ambiguous') or (pipeline.coverage_course_pages.evidence_id is null and pipeline.coverage_course_pages.read_status in ('needs_render', 'blocked', 'fetch_failed', 'too_thin'));
  insert into pipeline.search_pass_links(course_id, provider_id, run_id, candidates, cand_idx, bound_url, refind, state, updated_at, engine)
    values (v_i.course_id, v_i.provider_id, v_i.run_id, v_c, case when v_url = v_c->>0 then 1 else 2 end, v_url, coalesce((v_i.input->>'refind')::boolean, false), 'found', now(), 'firecrawl')
  on conflict (course_id) do update set run_id = excluded.run_id, candidates = excluded.candidates, cand_idx = excluded.cand_idx, bound_url = excluded.bound_url, refind = excluded.refind, state = 'found', updated_at = now(), engine = 'firecrawl' where pipeline.search_pass_links.course_id = excluded.course_id;
  return 'bound';
end $$;


ALTER FUNCTION "public"."svc_fc_find_bind"("p_item_id" "uuid", "p_candidates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_fc_run_next"("p_run_id" "uuid", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_r pipeline.firecrawl_runs%rowtype; v_items jsonb; v_left int; v_budget jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into v_r from pipeline.firecrawl_runs where id = p_run_id for update;
  if v_r.id is null or v_r.status <> 'running' then return jsonb_build_object('run', to_jsonb(v_r) - 'settings', 'items', '[]'::jsonb); end if;
  if v_r.credits_used >= v_r.credits_cap then
    update pipeline.firecrawl_runs set status = 'stopped_credit_cap', finished_at = now() where id = v_r.id;
    return jsonb_build_object('run', jsonb_build_object('id', v_r.id, 'status', 'stopped_credit_cap'), 'items', '[]'::jsonb);
  end if;
  v_budget := security.layer2_provider_budget_status((select p.id from pipeline.layer2_acquisition_providers p where p.provider_key = 'firecrawl'), 5);
  if not coalesce((v_budget->>'allowed')::boolean, false) then
    update pipeline.firecrawl_runs set status = 'stopped_plan_reserve', finished_at = now() where id = v_r.id;
    return jsonb_build_object('run', jsonb_build_object('id', v_r.id, 'status', 'stopped_plan_reserve'), 'items', '[]'::jsonb);
  end if;
  if coalesce(p_limit, 0) <= 0 then
    return jsonb_build_object('run', jsonb_build_object('id', v_r.id, 'use_case', v_r.use_case, 'status', v_r.status, 'settings', v_r.settings, 'credits_left', v_r.credits_cap - v_r.credits_used), 'items', '[]'::jsonb);
  end if;
  with picked as (
    select i.id from pipeline.firecrawl_run_items i
    where i.run_id = v_r.id and (i.state = 'queued' or (i.state = 'leased' and i.leased_until < now()))
    order by i.state desc, i.provider_id, i.id limit greatest(1, least(coalesce(p_limit, 40), 200)) for update skip locked
  ), upd as (
    update pipeline.firecrawl_run_items i set state = 'leased', leased_until = now() + interval '5 minutes' from picked where i.id = picked.id
    returning i.id, i.course_id, i.provider_id, i.country, i.url, i.input, i.result
  )
  select coalesce(jsonb_agg(to_jsonb(upd)), '[]'::jsonb) into v_items from upd;
  if v_r.use_case = 'read_page' then
    update pipeline.coverage_course_pages pg set leased_until = now() + interval '5 minutes' where pg.course_id in (select (e->>'course_id')::uuid from jsonb_array_elements(v_items) e);
  end if;
  if jsonb_array_length(v_items) = 0 then
    select count(*) into v_left from pipeline.firecrawl_run_items i where i.run_id = v_r.id and i.state <> 'done';
    if v_left = 0 then update pipeline.firecrawl_runs set status = 'done', finished_at = now() where id = v_r.id; end if;
  end if;
  update pipeline.firecrawl_runs set last_call_at = now() where id = v_r.id;
  return jsonb_build_object('run', jsonb_build_object('id', v_r.id, 'use_case', v_r.use_case, 'status', v_r.status, 'settings', v_r.settings, 'credits_left', v_r.credits_cap - v_r.credits_used), 'items', v_items);
end $$;


ALTER FUNCTION "public"."svc_fc_run_next"("p_run_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_fc_run_record"("p_item_id" "uuid", "p_outcome" "text", "p_result" "jsonb", "p_credits" numeric) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_i pipeline.firecrawl_run_items%rowtype;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into v_i from pipeline.firecrawl_run_items where id = p_item_id for update;
  if v_i.id is null then return 'unknown'; end if;
  if v_i.state = 'done' then return 'already_done'; end if;
  if p_outcome = 'retry' then
    update pipeline.firecrawl_run_items set state = 'queued', leased_until = null, credits = coalesce(credits, 0) + coalesce(p_credits, 0), result = p_result where id = v_i.id;
  else
    update pipeline.firecrawl_run_items set state = 'done', leased_until = null, outcome = p_outcome, result = p_result, credits = coalesce(credits, 0) + coalesce(p_credits, 0), done_at = now() where id = v_i.id;
  end if;
  update pipeline.firecrawl_runs r set credits_used = r.credits_used + coalesce(p_credits, 0), done = r.done + case when p_outcome = 'retry' then 0 else 1 end, outcomes = case when p_outcome = 'retry' then r.outcomes else jsonb_set(r.outcomes, array[p_outcome], to_jsonb(coalesce((r.outcomes->>p_outcome)::int, 0) + 1)) end where r.id = v_i.run_id;
  update pipeline.coverage_course_pages set leased_until = null where course_id = v_i.course_id and leased_until is not null and v_i.url is not null;
  return 'ok';
end $$;


ALTER FUNCTION "public"."svc_fc_run_record"("p_item_id" "uuid", "p_outcome" "text", "p_result" "jsonb", "p_credits" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_fc_targets"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if not exists (select 1 from pipeline.firecrawl_target_cache c where c.refreshed_at > now() - interval '5 minutes') then perform security.firecrawl_targets_refresh_v1(); end if;
  return jsonb_build_object('target_only', coalesce((security.firecrawl_setting('target_only') #>> '{}')::boolean, true),
                            'ids', coalesce((select jsonb_agg(c.provider_id) from pipeline.firecrawl_target_cache c where c.included), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."svc_fc_targets"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_fee_schedule_apply"("p_provider_cricos" "text", "p_fee_year" integer, "p_storage_path" "text", "p_url" "text", "p_sha256" "text", "p_schedule" "text", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'public', 'search'
    AS $_$
declare v_source uuid; v_provider uuid; p_evidence_id uuid; r record; v_res jsonb; v_applied int:=0; v_super int:=0; v_skipped jsonb:='[]'::jsonb; v_courses uuid[]:=array[]::uuid[]; v_n int;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  select s.id, s.provider_id into v_source, v_provider from pipeline.sources s
   where s.source_type='provider_fee_schedule' and s.metadata->>'provider_cricos'=upper(btrim(p_provider_cricos))
     and exists(select 1 from pipeline.course_fact_source_qualifications q where q.source_id=s.id and q.qualification_status='qualified' and 'international_fee'=any(q.admitted_domains));
  if v_source is null then raise exception 'no qualified fee schedule source for provider %', p_provider_cricos; end if;
  if coalesce(btrim(p_storage_path),'')='' or p_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'stored schedule file and its SHA-256 are required'; end if;
  select e.id into p_evidence_id from pipeline.evidence_artifacts e where e.source_id=v_source and e.content_hash=p_sha256 limit 1;
  if p_evidence_id is null then
    p_evidence_id:=public.svc_coursefacts_register_evidence(v_source,p_url,p_storage_path,p_sha256,'application/pdf',
      jsonb_build_object('layer',2,'kind','provider_fee_schedule','schedule',p_schedule,'fee_year',p_fee_year,'worker','fee-schedule-etl','decision','Decision 162'));
  end if;
  for r in
    with x as (select upper(btrim(e->>'course_cricos')) code, e->>'title' title, (e->>'amount')::numeric amount from jsonb_array_elements(p_rows) e),
         g as (select code, min(title) title, min(amount) amount, count(distinct amount) amounts from x group by code)
    select g.*, cr.course_id, (select jsonb_build_object('amount',f.amount,'fee_year',f.fee_year) from catalogue.course_fees f
            where f.course_id=cr.course_id and f.fee_type='provider_current_tuition' and coalesce(f.status,'active')='active' order by f.fee_year desc nulls last limit 1) cur
      from g left join catalogue.course_registrations cr on lower(cr.scheme)='cricos' and upper(btrim(cr.registration_code))=g.code
           and exists(select 1 from catalogue.courses c where c.id=cr.course_id and c.provider_id=v_provider and c.lifecycle_status='active')
  loop
    if r.course_id is null then v_skipped:=v_skipped||jsonb_build_object('code',r.code,'reason','not bound'); continue; end if;
    if r.amounts>1 then v_skipped:=v_skipped||jsonb_build_object('code',r.code,'reason','listed twice with different fees'); continue; end if;
    if r.cur is not null and (r.cur->>'fee_year')::int > p_fee_year then v_skipped:=v_skipped||jsonb_build_object('code',r.code,'reason','newer fee year already current'); continue; end if;
    if r.cur is not null and (r.cur->>'fee_year')::int = p_fee_year and (r.cur->>'amount')::numeric<>r.amount then
      v_skipped:=v_skipped||jsonb_build_object('code',r.code,'reason','same fee year, different amount (Layer 4)','schedule',r.amount,'current',r.cur); continue; end if;
    begin
    v_res:=public.svc_coursefacts_apply_record(v_source,p_evidence_id,p_provider_cricos,r.code,p_schedule||':'||r.code||':'||p_fee_year,p_url,p_sha256,
      jsonb_build_object('fee_amount',r.amount,'fee_year',p_fee_year,'fee_basis','annual','currency_code','AUD','audience','international',
        'fee_key',lower(r.code)||':international:'||p_fee_year||':annual','fee_notes','Decision 162 provider fee schedule '||p_schedule||'; annual fee for one full-time year',
        'identity_match',true,'extraction_worker','fee-schedule-etl','course_title_in_schedule',r.title),true);
    exception when others then
      v_skipped:=v_skipped||jsonb_build_object('code',r.code,'reason',left(sqlerrm,200)); continue;
    end;
    v_applied:=v_applied+1; v_courses:=v_courses||r.course_id;
    update catalogue.course_fees f set status='superseded', updated_at=now(),
           notes=coalesce(f.notes,'')||' | superseded by the '||p_fee_year||' provider fee schedule (Decision 132/162) '||to_char(now(),'YYYY-MM-DD')
     where f.course_id=r.course_id and f.fee_type='provider_current_tuition' and coalesce(f.status,'active')='active'
       and f.source_id is distinct from v_source and coalesce(f.fee_year,0)<p_fee_year;
    get diagnostics v_n=row_count; v_super:=v_super+v_n;
  end loop;
  if cardinality(v_courses)>0 then perform search.refresh_course_enrichment_scoped_v1(v_courses,true); end if;
  return jsonb_build_object('applied',v_applied,'superseded_older',v_super,'skipped',jsonb_array_length(v_skipped),'skipped_detail',v_skipped,'source_id',v_source,'evidence_id',p_evidence_id);
end $_$;


ALTER FUNCTION "public"."svc_fee_schedule_apply"("p_provider_cricos" "text", "p_fee_year" integer, "p_storage_path" "text", "p_url" "text", "p_sha256" "text", "p_schedule" "text", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_fee_schedule_preview"("p_provider_cricos" "text", "p_fee_year" integer, "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'ref'
    AS $$
declare v_provider uuid; v_out jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>3000 then raise exception 'rows must be an array of at most 3000'; end if;
  select pr.provider_id into v_provider from catalogue.provider_registrations pr join catalogue.providers p on p.id=pr.provider_id join ref.countries c on c.id=p.country_id
   where c.iso_alpha2='AU' and lower(pr.registration_scheme)='cricos' and upper(btrim(pr.registration_code))=upper(btrim(p_provider_cricos)) limit 1;
  if v_provider is null then raise exception 'provider CRICOS not resolved'; end if;
  with r as (
    select upper(btrim(x->>'course_cricos')) code, x->>'title' title, (x->>'amount')::numeric amount, ord
      from jsonb_array_elements(p_rows) with ordinality z(x,ord)
  ), b as (
    select r.*, cr.course_id, c.canonical_title, c.lifecycle_status,
           (select jsonb_build_object('amount',f.amount,'fee_year',f.fee_year,'basis',f.basis) from catalogue.course_fees f
             where f.course_id=cr.course_id and f.fee_type='provider_current_tuition' and coalesce(f.status,'active')='active'
             order by f.fee_year desc nulls last limit 1) cur,
           (select f.amount from catalogue.course_fees f where f.course_id=cr.course_id and f.fee_type='tuition' and f.basis='registered_total_course' and coalesce(f.status,'active')='active' limit 1) cricos_total
      from r left join catalogue.course_registrations cr on lower(cr.scheme)='cricos' and upper(btrim(cr.registration_code))=r.code
                  and exists(select 1 from catalogue.courses c2 where c2.id=cr.course_id and c2.provider_id=v_provider)
      left join catalogue.courses c on c.id=cr.course_id
  ), d as (
    select b.*, case
      when course_id is null then 'unbound'
      when lifecycle_status<>'active' then 'course_not_active'
      when cur is null then 'insert'
      when (cur->>'fee_year')::int is null or (cur->>'fee_year')::int < p_fee_year then 'replace_older_year'
      when (cur->>'fee_year')::int > p_fee_year then 'newer_exists'
      when (cur->>'amount')::numeric = amount then 'same'
      else 'conflict_same_year' end action
    from b
  )
  select jsonb_build_object(
    'provider_id',v_provider,'fee_year',p_fee_year,'rows',(select count(*) from d),
    'bound',(select count(*) from d where course_id is not null),
    'actions',(select jsonb_object_agg(action,n) from (select action,count(*) n from d group by 1) a),
    'duplicate_codes',(select count(*) from (select code from d group by code having count(*)>1) q),
    'provider_active_courses',(select count(*) from catalogue.courses c where c.provider_id=v_provider and c.lifecycle_status='active'),
    'amount_range',(select jsonb_build_object('min',min(amount),'max',max(amount)) from d),
    'annual_vs_cricos_total_ratio',(select jsonb_build_object('min',round(min(cricos_total/nullif(amount,0)),2),'max',round(max(cricos_total/nullif(amount,0)),2)) from d where cricos_total is not null),
    'unbound_sample',(select coalesce(jsonb_agg(jsonb_build_object('code',code,'title',title)),'[]'::jsonb) from (select * from d where action='unbound' order by ord limit 10) u),
    'conflict_sample',(select coalesce(jsonb_agg(jsonb_build_object('code',code,'schedule',amount,'current',cur)),'[]'::jsonb) from (select * from d where action in ('conflict_same_year','newer_exists') order by ord limit 10) u),
    'sample',(select coalesce(jsonb_agg(jsonb_build_object('code',code,'title',title,'amount',amount,'action',action,'catalogue_title',canonical_title)),'[]'::jsonb) from (select * from d order by ord limit 8) u)
  ) into v_out;
  return v_out;
end $$;


ALTER FUNCTION "public"."svc_fee_schedule_preview"("p_provider_cricos" "text", "p_fee_year" integer, "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_apply_ca_ircc_providers"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_records" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'pim', 'ref', 'pipeline'
    AS $_$
declare
 r jsonb; v_country uuid; v_provider uuid; v_family_provider uuid; v_subdivision uuid;
 v_pcode text; v_pname text; v_province text; v_city text; v_provider_key text;
 v_provider_created int:=0; v_provider_existing int:=0; v_conflicts int:=0; v_geography_mapped int:=0; v_geography_unmapped int:=0;
begin
 select id into v_country from ref.countries where upper(iso_alpha2::text)='CA';
 if v_country is null then raise exception 'country seed missing: CA'; end if;
 select id into v_family_provider from pim.attribute_families where entity_type='provider' and status='active' order by case when code='provider_default' then 0 else 1 end limit 1;
 for r in select value from jsonb_array_elements(coalesce(p_records,'[]'::jsonb)) loop
  v_pcode:=upper(nullif(trim(r->>'provider_code'),'')); v_pname:=nullif(trim(r->>'provider_name'),''); v_province:=nullif(trim(r->>'province'),'');
  v_city:=nullif(trim(coalesce(r->'cities'->>0,r->>'primary_city')),'');
  if v_pcode is null or v_pname is null or v_pcode !~ '^O[0-9]{10,15}$' then v_conflicts:=v_conflicts+1; continue; end if;
  v_subdivision:=null;
  if v_province is not null then
   select s.id into v_subdivision from ref.subdivisions s where s.country_id=v_country and lower(regexp_replace(s.name,'[^a-z]','','g'))=lower(regexp_replace(v_province,'[^a-z]','','g')) limit 1;
   if v_subdivision is null and lower(v_province) in ('québec','quebec') then select s.id into v_subdivision from ref.subdivisions s where s.code='CA-QC'; end if;
  end if;
  if v_subdivision is null then v_geography_unmapped:=v_geography_unmapped+1; else v_geography_mapped:=v_geography_mapped+1; end if;
  v_provider_key:='provider:ca:ircc_dli:'||lower(v_pcode); v_provider:=null;
  select pi.provider_id into v_provider from catalogue.provider_identifiers pi where pi.country_id=v_country and lower(pi.scheme)='ircc_dli' and upper(pi.identifier)=v_pcode order by pi.is_primary desc,pi.verified_at desc nulls last limit 1;
  if v_provider is null then select id into v_provider from catalogue.providers where stable_key=v_provider_key limit 1; end if;
  if v_provider is null then
    insert into pim.entity_registry(entity_type,stable_key,family_id) values('provider',v_provider_key,v_family_provider) returning id into v_provider;
    insert into catalogue.providers(id,stable_key,canonical_name,display_name,country_id,subdivision_id,primary_city,lifecycle_status,publication_status,canonical_source_id,last_verified_at)
    values(v_provider,v_provider_key,v_pname,v_pname,v_country,v_subdivision,v_city,'active','unpublished',p_source_id,now());
    v_provider_created:=v_provider_created+1;
  else
    update catalogue.providers set canonical_name=v_pname,display_name=v_pname,subdivision_id=coalesce(v_subdivision,subdivision_id),primary_city=coalesce(v_city,primary_city),canonical_source_id=p_source_id,last_verified_at=now(),updated_at=now() where id=v_provider;
    v_provider_existing:=v_provider_existing+1;
  end if;
  insert into catalogue.provider_identifiers(provider_id,scheme,identifier,country_id,issuing_authority,is_primary,source_id,evidence_id,verified_at)
   values(v_provider,'ircc_dli',v_pcode,v_country,'IRCC',true,p_source_id,p_evidence_id,now())
   on conflict (provider_id,scheme,identifier) do update set source_id=excluded.source_id,evidence_id=excluded.evidence_id,verified_at=excluded.verified_at,is_primary=true;
  insert into catalogue.provider_registrations(provider_id,source_id,registration_scheme,registration_code,status,checked_at,evidence_id)
   values(v_provider,p_source_id,'ircc_dli',v_pcode,'active',now(),p_evidence_id) on conflict do nothing;
 end loop;
 return jsonb_build_object('records',jsonb_array_length(coalesce(p_records,'[]'::jsonb)),'provider_created',v_provider_created,'provider_existing',v_provider_existing,'conflicts',v_conflicts,'geography_mapped',v_geography_mapped,'geography_unmapped',v_geography_unmapped,'course_writes',0,'identity_contract','provider=IRCC_DLI_only; subdivision=IRCC descriptive authority mapped to ISO-3166-2 CA seed');
end $_$;


ALTER FUNCTION "public"."svc_layer1_apply_ca_ircc_providers"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_records" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_apply_course_regulatory_facts"("p_country_code" "text", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_registration_scheme" "text", "p_source_snapshot_at" timestamp with time zone, "p_records" "jsonb", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'pipeline', 'extensions', 'pg_temp'
    AS $_$
declare
  v_country uuid;
  v_scheme text;
  v_snapshot_key text;
  v_records int := 0;
  v_matched int := 0;
  v_course_missing int := 0;
  v_fact_created int := 0;
  v_fact_updated int := 0;
  v_fact_unchanged int := 0;
  v_fact_superseded int := 0;
  v_fee_observations int := 0;
  v_fee_created int := 0;
  v_fee_updated int := 0;
  v_fee_unchanged int := 0;
  v_fee_superseded int := 0;
  v_secondary_field_mapped int := 0;
  v_secondary_field_unmapped int := 0;
  v_invalid_boolean int := 0;
  v_invalid_number int := 0;
  v_invalid_fee int := 0;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'service_role required';
  end if;
  v_scheme := lower(nullif(trim(p_registration_scheme),''));
  if v_scheme is null then raise exception 'registration scheme required'; end if;
  if p_source_id is null then raise exception 'source_id required'; end if;
  if p_evidence_id is null then raise exception 'evidence_id required'; end if;
  if p_source_snapshot_at is null then raise exception 'source_snapshot_at required'; end if;

  select id into v_country from ref.countries
  where upper(trim(iso_alpha2::text))=upper(trim(p_country_code)) limit 1;
  if v_country is null then raise exception 'country seed missing: %',p_country_code; end if;
  if not exists(select 1 from pipeline.sources where id=p_source_id) then raise exception 'source missing: %',p_source_id; end if;
  if not exists(select 1 from pipeline.evidence_artifacts where id=p_evidence_id and source_id=p_source_id) then raise exception 'evidence/source mismatch'; end if;

  v_snapshot_key := to_char(p_source_snapshot_at at time zone 'UTC','YYYYMMDD"T"HH24MISS.US"Z"');

  drop table if exists pg_temp.cf_cricos_fact_raw;
  drop table if exists pg_temp.cf_cricos_fact_resolved;
  drop table if exists pg_temp.cf_cricos_fee_grid;

  create temp table cf_cricos_fact_raw on commit drop as
  select
    ord::int as ord,
    upper(nullif(trim(value->>'provider_code'),'')) as provider_code,
    upper(nullif(trim(value->>'course_code'),'')) as course_code,
    nullif(trim(value->>'vet_national_code'),'') as vet_national_code,
    nullif(trim(value->>'dual_qualification'),'') as dual_raw,
    nullif(trim(value->>'foundation_studies'),'') as foundation_raw,
    nullif(trim(value->>'work_component'),'') as work_raw,
    nullif(trim(value->>'work_component_hours_per_week'),'') as work_hours_raw,
    nullif(trim(value->>'work_component_weeks'),'') as work_weeks_raw,
    nullif(trim(value->>'work_component_total_hours'),'') as work_total_raw,
    nullif(trim(value->>'course_language'),'') as course_language,
    nullif(trim(value->>'secondary_field_code'),'') as secondary_field_code,
    nullif(trim(value->>'secondary_field_name'),'') as secondary_field_name,
    nullif(trim(value->>'tuition_fee'),'') as tuition_raw,
    nullif(trim(value->>'non_tuition_fee'),'') as non_tuition_raw,
    nullif(trim(value->>'estimated_total_course_cost'),'') as total_cost_raw
  from jsonb_array_elements(coalesce(p_records,'[]'::jsonb)) with ordinality as x(value,ord);

  create temp table cf_cricos_fact_resolved on commit drop as
  select
    i.*,
    p.id as provider_id,
    c.id as course_id,
    case lower(coalesce(i.dual_raw,''))
      when 'yes' then true when 'true' then true when 'y' then true when '1' then true
      when 'no' then false when 'false' then false when 'n' then false when '0' then false else null end as dual_qualification,
    case lower(coalesce(i.foundation_raw,''))
      when 'yes' then true when 'true' then true when 'y' then true when '1' then true
      when 'no' then false when 'false' then false when 'n' then false when '0' then false else null end as foundation_studies,
    case lower(coalesce(i.work_raw,''))
      when 'yes' then true when 'true' then true when 'y' then true when '1' then true
      when 'no' then false when 'false' then false when 'n' then false when '0' then false else null end as work_component,
    case when i.work_hours_raw ~ '^[0-9]+(\.[0-9]+)?$' then i.work_hours_raw::numeric end as work_component_hours_per_week,
    case when i.work_weeks_raw ~ '^[0-9]+(\.[0-9]+)?$' then i.work_weeks_raw::numeric end as work_component_weeks,
    case when i.work_total_raw ~ '^[0-9]+(\.[0-9]+)?$' then i.work_total_raw::numeric end as work_component_total_hours
  from cf_cricos_fact_raw i
  left join catalogue.provider_registrations pr
    on lower(pr.registration_scheme)=v_scheme and upper(pr.registration_code)=i.provider_code
  left join catalogue.providers p
    on p.id=pr.provider_id and p.country_id=v_country
  left join catalogue.course_registrations cr
    on lower(cr.scheme)=v_scheme and upper(cr.registration_code)=i.course_code
    and (cr.country_id is null or cr.country_id=v_country)
  left join catalogue.courses c
    on c.id=cr.course_id and c.provider_id=p.id;

  alter table cf_cricos_fact_resolved add column fact_hash text;
  update cf_cricos_fact_resolved r
  set fact_hash=encode(extensions.digest(jsonb_build_object(
    'vet_national_code',r.vet_national_code,
    'dual_qualification',r.dual_qualification,
    'foundation_studies',r.foundation_studies,
    'work_component',r.work_component,
    'work_component_hours_per_week',r.work_component_hours_per_week,
    'work_component_weeks',r.work_component_weeks,
    'work_component_total_hours',r.work_component_total_hours,
    'course_language',r.course_language
  )::text,'sha256'),'hex')
  where true;

  select count(*),count(*) filter(where course_id is not null),count(*) filter(where course_id is null)
  into v_records,v_matched,v_course_missing from cf_cricos_fact_resolved;

  select
    count(*) filter(where dual_raw is not null and lower(dual_raw) not in ('yes','true','y','1','no','false','n','0')) +
    count(*) filter(where foundation_raw is not null and lower(foundation_raw) not in ('yes','true','y','1','no','false','n','0')) +
    count(*) filter(where work_raw is not null and lower(work_raw) not in ('yes','true','y','1','no','false','n','0')),
    count(*) filter(where work_hours_raw is not null and work_hours_raw !~ '^[0-9]+(\.[0-9]+)?$') +
    count(*) filter(where work_weeks_raw is not null and work_weeks_raw !~ '^[0-9]+(\.[0-9]+)?$') +
    count(*) filter(where work_total_raw is not null and work_total_raw !~ '^[0-9]+(\.[0-9]+)?$')
  into v_invalid_boolean,v_invalid_number
  from cf_cricos_fact_resolved;

  select
    count(*) filter(where o.id is null),
    count(*) filter(where o.id is not null and (o.content_hash is distinct from r.fact_hash or o.status<>'current')),
    count(*) filter(where o.id is not null and o.content_hash is not distinct from r.fact_hash and o.status='current')
  into v_fact_created,v_fact_updated,v_fact_unchanged
  from cf_cricos_fact_resolved r
  left join catalogue.course_regulatory_observations o
    on o.course_id=r.course_id and o.source_id=p_source_id and o.scheme=v_scheme
    and o.registration_code=r.course_code and o.source_snapshot_at=p_source_snapshot_at
  where r.course_id is not null;

  select count(*) into v_fact_superseded
  from catalogue.course_regulatory_observations o
  join cf_cricos_fact_resolved r on r.course_id=o.course_id and r.course_code=o.registration_code
  where r.course_id is not null and o.source_id=p_source_id and o.scheme=v_scheme
    and o.source_snapshot_at<>p_source_snapshot_at and o.status='current';

  select
    count(*) filter(where (r.secondary_field_code is not null or r.secondary_field_name is not null)
      and r.secondary_field_code ~ '^[0-9]{4}$' and r.secondary_field_name is not null and b.id is not null),
    count(*) filter(where (r.secondary_field_code is not null or r.secondary_field_name is not null)
      and not (r.secondary_field_code ~ '^[0-9]{4}$' and r.secondary_field_name is not null and b.id is not null))
  into v_secondary_field_mapped,v_secondary_field_unmapped
  from cf_cricos_fact_resolved r
  left join ref.fields_of_study b on b.code='asced-'||left(r.secondary_field_code,2)
  where r.course_id is not null;

  create temp table cf_cricos_fee_grid on commit drop as
  select
    r.course_id,r.course_code,x.fee_type,x.raw_value,
    regexp_replace(coalesce(x.raw_value,''),'[^0-9.-]','','g') as clean_value,
    case
      when x.raw_value is null then true
      when regexp_replace(x.raw_value,'[^0-9.-]','','g') ~ '^-?[0-9]+(\.[0-9]+)?$' then true
      else false end as is_valid,
    case
      when x.raw_value is not null and regexp_replace(x.raw_value,'[^0-9.-]','','g') ~ '^-?[0-9]+(\.[0-9]+)?$'
      then regexp_replace(x.raw_value,'[^0-9.-]','','g')::numeric
      else null end as amount,
    v_scheme||':'||lower(r.course_code)||':'||x.fee_type||':'||v_snapshot_key as source_fee_key
  from cf_cricos_fact_resolved r
  cross join lateral (values
    ('tuition'::text,r.tuition_raw),
    ('non_tuition'::text,r.non_tuition_raw),
    ('estimated_total_course_cost'::text,r.total_cost_raw)
  ) x(fee_type,raw_value)
  where r.course_id is not null;

  select count(*) filter(where raw_value is not null and is_valid),
         count(*) filter(where raw_value is not null and not is_valid)
  into v_fee_observations,v_invalid_fee
  from cf_cricos_fee_grid;

  select
    count(*) filter(where f.id is null),
    count(*) filter(where f.id is not null and (f.amount is distinct from g.amount or f.status<>'active')),
    count(*) filter(where f.id is not null and f.amount is not distinct from g.amount and f.status='active')
  into v_fee_created,v_fee_updated,v_fee_unchanged
  from cf_cricos_fee_grid g
  left join catalogue.course_fees f
    on f.course_id=g.course_id and f.source_id=p_source_id and f.source_fee_key=g.source_fee_key
  where g.raw_value is not null and g.is_valid;

  select count(distinct f.id) into v_fee_superseded
  from catalogue.course_fees f
  join cf_cricos_fee_grid g on g.course_id=f.course_id and g.fee_type=f.fee_type
  where f.source_id=p_source_id and f.basis='registered_total_course'
    and f.source_snapshot_at is distinct from p_source_snapshot_at and f.status='active';

  if p_apply then
    update catalogue.course_regulatory_observations o
    set status='superseded',valid_to=p_source_snapshot_at,updated_at=now()
    from cf_cricos_fact_resolved r
    where r.course_id=o.course_id and r.course_code=o.registration_code
      and r.course_id is not null and o.source_id=p_source_id and o.scheme=v_scheme
      and o.source_snapshot_at<>p_source_snapshot_at and o.status='current';

    insert into catalogue.course_regulatory_observations(
      course_id,scheme,registration_code,vet_national_code,dual_qualification,foundation_studies,
      work_component,work_component_hours_per_week,work_component_weeks,work_component_total_hours,
      course_language,source_id,evidence_id,source_snapshot_at,content_hash,status,valid_from,valid_to,
      observed_at,last_verified_at
    )
    select
      r.course_id,v_scheme,r.course_code,r.vet_national_code,r.dual_qualification,r.foundation_studies,
      r.work_component,r.work_component_hours_per_week,r.work_component_weeks,r.work_component_total_hours,
      r.course_language,p_source_id,p_evidence_id,p_source_snapshot_at,r.fact_hash,'current',p_source_snapshot_at,null,
      now(),now()
    from cf_cricos_fact_resolved r where r.course_id is not null
    on conflict on constraint course_regulatory_observations_snapshot_uq do update
      set vet_national_code=excluded.vet_national_code,
          dual_qualification=excluded.dual_qualification,
          foundation_studies=excluded.foundation_studies,
          work_component=excluded.work_component,
          work_component_hours_per_week=excluded.work_component_hours_per_week,
          work_component_weeks=excluded.work_component_weeks,
          work_component_total_hours=excluded.work_component_total_hours,
          course_language=excluded.course_language,
          evidence_id=excluded.evidence_id,
          content_hash=excluded.content_hash,
          status='current',valid_from=excluded.valid_from,valid_to=null,
          observed_at=now(),last_verified_at=now(),updated_at=now();

    insert into ref.fields_of_study(code,name,parent_id,path,depth,status)
    select distinct 'asced-'||r.secondary_field_code,r.secondary_field_name,b.id,
      'asced/'||left(r.secondary_field_code,2)||'/'||r.secondary_field_code,1,'active'
    from cf_cricos_fact_resolved r
    join ref.fields_of_study b on b.code='asced-'||left(r.secondary_field_code,2)
    where r.course_id is not null and r.secondary_field_code ~ '^[0-9]{4}$' and r.secondary_field_name is not null
    on conflict(code) do update set name=excluded.name,parent_id=excluded.parent_id,path=excluded.path,status='active',updated_at=now();

    insert into catalogue.course_field_observations(
      course_id,field_id,source_id,evidence_id,source_field_code,source_field_name,is_primary,status,observed_at,updated_at
    )
    select r.course_id,f.id,p_source_id,p_evidence_id,r.secondary_field_code,r.secondary_field_name,false,'current',now(),now()
    from cf_cricos_fact_resolved r
    join ref.fields_of_study f on f.code='asced-'||r.secondary_field_code
    where r.course_id is not null and r.secondary_field_code ~ '^[0-9]{4}$' and r.secondary_field_name is not null
    on conflict(course_id,source_id,source_field_code) do update
      set field_id=excluded.field_id,evidence_id=excluded.evidence_id,source_field_name=excluded.source_field_name,
          is_primary=(catalogue.course_field_observations.is_primary or excluded.is_primary),status='current',observed_at=now(),updated_at=now();

    update catalogue.course_fees f
    set status='superseded',valid_to=p_source_snapshot_at::date,updated_at=now()
    from cf_cricos_fee_grid g
    where g.course_id=f.course_id and g.fee_type=f.fee_type
      and f.source_id=p_source_id and f.basis='registered_total_course'
      and f.source_snapshot_at is distinct from p_source_snapshot_at and f.status='active';

    insert into catalogue.course_fees(
      course_id,fee_year,audience,fee_type,amount,currency_code,basis,notes,valid_from,valid_to,
      source_id,evidence_id,confidence,source_fee_key,status,last_verified_at,source_snapshot_at
    )
    select
      g.course_id,null,'international',g.fee_type,g.amount,'AUD','registered_total_course',
      'CRICOS registered total-course amount; source value='||g.raw_value||'; not annualised.',
      p_source_snapshot_at::date,null,p_source_id,p_evidence_id,1.0,g.source_fee_key,'active',now(),p_source_snapshot_at
    from cf_cricos_fee_grid g
    where g.raw_value is not null and g.is_valid
    on conflict (course_id,source_id,source_fee_key)
      where source_id is not null and source_fee_key is not null
    do update set amount=excluded.amount,currency_code='AUD',audience='international',fee_year=null,
      basis='registered_total_course',notes=excluded.notes,valid_from=excluded.valid_from,valid_to=null,
      evidence_id=excluded.evidence_id,confidence=1.0,status='active',last_verified_at=now(),
      source_snapshot_at=excluded.source_snapshot_at,updated_at=now();
  end if;

  return jsonb_build_object(
    'apply',p_apply,'records',v_records,'matched',v_matched,'course_missing',v_course_missing,
    'fact_created',v_fact_created,'fact_updated',v_fact_updated,'fact_unchanged',v_fact_unchanged,'fact_superseded',v_fact_superseded,
    'fee_observations',v_fee_observations,'fee_created',v_fee_created,'fee_updated',v_fee_updated,'fee_unchanged',v_fee_unchanged,'fee_superseded',v_fee_superseded,
    'secondary_field_mapped',v_secondary_field_mapped,'secondary_field_unmapped',v_secondary_field_unmapped,
    'invalid_boolean_values',v_invalid_boolean,'invalid_numeric_values',v_invalid_number,'invalid_fee_values',v_invalid_fee,
    'source_snapshot_at',p_source_snapshot_at
  );
end
$_$;


ALTER FUNCTION "public"."svc_layer1_apply_course_regulatory_facts"("p_country_code" "text", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_registration_scheme" "text", "p_source_snapshot_at" timestamp with time zone, "p_records" "jsonb", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_apply_course_scope"("p_source_id" "uuid", "p_scope_tag" "text", "p_course_scheme" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'pipeline', 'ref'
    AS $$
DECLARE
  v_in_scope int := 0;
  v_retired int := 0;
  v_levelled int := 0;
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pipeline.ca_course_scope_keys sk
    LEFT JOIN ref.study_levels sl ON sl.code = sk.study_level_code
    WHERE sk.source_id = p_source_id
      AND sk.scope_tag = p_scope_tag
      AND sk.course_scheme = p_course_scheme
      AND sl.id IS NULL
  ) THEN
    RAISE EXCEPTION 'course scope contains unsupported study level';
  END IF;

  UPDATE catalogue.courses c
     SET lifecycle_status = 'inactive',
         publication_status = 'unpublished',
         updated_at = now()
   WHERE c.canonical_source_id = p_source_id
     AND (c.lifecycle_status IS DISTINCT FROM 'inactive'
          OR c.publication_status IS DISTINCT FROM 'unpublished')
     AND EXISTS (
       SELECT 1
       FROM catalogue.course_identifiers ci
       WHERE ci.course_id = c.id
         AND ci.source_id = p_source_id
         AND ci.scheme = p_course_scheme
     )
     AND NOT EXISTS (
       SELECT 1
       FROM catalogue.course_identifiers ci
       JOIN pipeline.ca_course_scope_keys sk
         ON sk.source_id = p_source_id
        AND sk.scope_tag = p_scope_tag
        AND sk.provider_id = ci.provider_id
        AND sk.course_scheme = ci.scheme
        AND sk.identifier = ci.identifier
       WHERE ci.course_id = c.id
         AND ci.source_id = p_source_id
         AND ci.scheme = p_course_scheme
     );
  GET DIAGNOSTICS v_retired = ROW_COUNT;

  UPDATE catalogue.courses c
     SET lifecycle_status = 'active',
         publication_status = 'unpublished',
         study_level_id = sl.id,
         updated_at = now()
    FROM catalogue.course_identifiers ci
    JOIN pipeline.ca_course_scope_keys sk
      ON sk.source_id = p_source_id
     AND sk.scope_tag = p_scope_tag
     AND sk.course_scheme = ci.scheme
     AND sk.provider_id = ci.provider_id
     AND sk.identifier = ci.identifier
    JOIN ref.study_levels sl
      ON sl.code = sk.study_level_code
   WHERE ci.course_id = c.id
     AND ci.source_id = p_source_id
     AND ci.scheme = p_course_scheme
     AND (c.lifecycle_status IS DISTINCT FROM 'active'
          OR c.publication_status IS DISTINCT FROM 'unpublished'
          OR c.study_level_id IS DISTINCT FROM sl.id);

  SELECT count(*)
    INTO v_in_scope
    FROM catalogue.courses c
    JOIN catalogue.course_identifiers ci ON ci.course_id = c.id
    JOIN pipeline.ca_course_scope_keys sk
      ON sk.source_id = p_source_id
     AND sk.scope_tag = p_scope_tag
     AND sk.provider_id = ci.provider_id
     AND sk.course_scheme = ci.scheme
     AND sk.identifier = ci.identifier
   WHERE ci.source_id = p_source_id
     AND ci.scheme = p_course_scheme;

  SELECT count(*)
    INTO v_levelled
    FROM catalogue.courses c
    JOIN catalogue.course_identifiers ci ON ci.course_id = c.id
    JOIN pipeline.ca_course_scope_keys sk
      ON sk.source_id = p_source_id
     AND sk.scope_tag = p_scope_tag
     AND sk.provider_id = ci.provider_id
     AND sk.course_scheme = ci.scheme
     AND sk.identifier = ci.identifier
   WHERE ci.source_id = p_source_id
     AND ci.scheme = p_course_scheme
     AND c.study_level_id IS NOT NULL;

  RETURN jsonb_build_object(
    'scope_tag', p_scope_tag,
    'in_scope', v_in_scope,
    'retired', v_retired,
    'levelled', v_levelled
  );
END
$$;


ALTER FUNCTION "public"."svc_layer1_apply_course_scope"("p_source_id" "uuid", "p_scope_tag" "text", "p_course_scheme" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_apply_course_study_levels"("p_country_code" "text", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_registration_scheme" "text", "p_source_snapshot_at" timestamp with time zone, "p_records" "jsonb", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'pipeline', 'extensions', 'pg_temp'
    AS $$
declare
 v_country uuid; v_scheme text; v_records int:=0; v_matched int:=0; v_course_missing int:=0; v_source_absent int:=0; v_mapped int:=0; v_review int:=0; v_unmapped int:=0; v_observation_created int:=0; v_observation_updated int:=0; v_observation_unchanged int:=0; v_observation_superseded int:=0; v_course_level_changed int:=0;
begin
 if coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
 v_scheme:=lower(nullif(trim(p_registration_scheme),'')); if v_scheme is null then raise exception 'registration scheme required'; end if;
 if p_source_id is null or p_evidence_id is null or p_source_snapshot_at is null then raise exception 'source/evidence/snapshot required'; end if;
 select id into v_country from ref.countries where upper(trim(iso_alpha2::text))=upper(trim(p_country_code)) limit 1; if v_country is null then raise exception 'country seed missing: %',p_country_code; end if;
 if not exists(select 1 from pipeline.sources where id=p_source_id) then raise exception 'source missing: %',p_source_id; end if;
 if not exists(select 1 from pipeline.evidence_artifacts where id=p_evidence_id and source_id=p_source_id) then raise exception 'evidence/source mismatch'; end if;
 drop table if exists pg_temp.cf_level_raw; drop table if exists pg_temp.cf_level_resolved;
 create temp table cf_level_raw on commit drop as
 select ord::int ord,upper(nullif(trim(value->>'provider_code'),'')) provider_code,upper(nullif(trim(value->>'course_code'),'')) course_code,nullif(trim(value->>'course_level_raw'),'') source_value
 from jsonb_array_elements(coalesce(p_records,'[]'::jsonb)) with ordinality x(value,ord);
 create temp table cf_level_resolved on commit drop as
 select i.*,p.id provider_id,c.id course_id,m.study_level_id,m.mapping_status,sl.code study_level_code,
 encode(extensions.digest(jsonb_build_object('source_value',i.source_value,'study_level_code',sl.code,'mapping_status',coalesce(m.mapping_status,case when i.source_value is null then 'source_absent' else 'review_required' end))::text,'sha256'),'hex') content_hash
 from cf_level_raw i
 left join catalogue.provider_registrations pr on lower(pr.registration_scheme)=v_scheme and upper(pr.registration_code)=i.provider_code
 left join catalogue.providers p on p.id=pr.provider_id and p.country_id=v_country
 left join catalogue.course_registrations cr on lower(cr.scheme)=v_scheme and upper(cr.registration_code)=i.course_code and (cr.country_id is null or cr.country_id=v_country)
 left join catalogue.courses c on c.id=cr.course_id and c.provider_id=p.id
 left join ref.study_level_source_mappings m on m.source_id=p_source_id and m.source_value=i.source_value
 left join ref.study_levels sl on sl.id=m.study_level_id;
 select count(*),count(*) filter(where course_id is not null),count(*) filter(where course_id is null),count(*) filter(where source_value is null),count(*) filter(where source_value is not null and mapping_status='mapped' and study_level_id is not null),count(*) filter(where source_value is not null and mapping_status='review_required'),count(*) filter(where source_value is not null and mapping_status is null)
 into v_records,v_matched,v_course_missing,v_source_absent,v_mapped,v_review,v_unmapped from cf_level_resolved;
 select count(*) filter(where o.id is null),count(*) filter(where o.id is not null and (o.study_level_id is distinct from r.study_level_id or o.source_value is distinct from r.source_value or o.mapping_status is distinct from coalesce(r.mapping_status,'review_required') or o.content_hash is distinct from r.content_hash or o.status<>'current')),count(*) filter(where o.id is not null and o.study_level_id is not distinct from r.study_level_id and o.source_value is not distinct from r.source_value and o.mapping_status is not distinct from coalesce(r.mapping_status,'review_required') and o.content_hash is not distinct from r.content_hash and o.status='current')
 into v_observation_created,v_observation_updated,v_observation_unchanged
 from cf_level_resolved r left join catalogue.course_study_level_observations o on o.course_id=r.course_id and o.source_id=p_source_id and o.scheme=v_scheme and o.registration_code=r.course_code and o.source_snapshot_at=p_source_snapshot_at
 where r.course_id is not null and r.source_value is not null;
 select count(*) into v_observation_superseded from catalogue.course_study_level_observations o join cf_level_resolved r on r.course_id=o.course_id and r.course_code=o.registration_code where r.course_id is not null and o.source_id=p_source_id and o.scheme=v_scheme and o.source_snapshot_at<>p_source_snapshot_at and o.status='current';
 select count(*) into v_course_level_changed from cf_level_resolved r join catalogue.courses c on c.id=r.course_id where r.mapping_status='mapped' and r.study_level_id is not null and c.study_level_id is distinct from r.study_level_id;
 if p_apply then
  update catalogue.course_study_level_observations o set status='superseded',valid_to=p_source_snapshot_at,updated_at=now() from cf_level_resolved r where r.course_id=o.course_id and r.course_code=o.registration_code and r.course_id is not null and o.source_id=p_source_id and o.scheme=v_scheme and o.source_snapshot_at<>p_source_snapshot_at and o.status='current';
  insert into catalogue.course_study_level_observations(course_id,study_level_id,source_id,evidence_id,scheme,registration_code,source_value,mapping_status,source_snapshot_at,content_hash,status,valid_from,valid_to,observed_at,last_verified_at)
  select r.course_id,r.study_level_id,p_source_id,p_evidence_id,v_scheme,r.course_code,r.source_value,coalesce(r.mapping_status,'review_required'),p_source_snapshot_at,r.content_hash,'current',p_source_snapshot_at,null,now(),now() from cf_level_resolved r where r.course_id is not null and r.source_value is not null
  on conflict on constraint course_study_level_observations_snapshot_uq do update set study_level_id=excluded.study_level_id,evidence_id=excluded.evidence_id,source_value=excluded.source_value,mapping_status=excluded.mapping_status,content_hash=excluded.content_hash,status='current',valid_from=excluded.valid_from,valid_to=null,observed_at=now(),last_verified_at=now(),updated_at=now();
  update catalogue.courses c set study_level_id=r.study_level_id,last_verified_at=now(),updated_at=now() from cf_level_resolved r where c.id=r.course_id and r.mapping_status='mapped' and r.study_level_id is not null and c.study_level_id is distinct from r.study_level_id;
 end if;
 return jsonb_build_object('apply',p_apply,'records',v_records,'matched',v_matched,'course_missing',v_course_missing,'source_absent',v_source_absent,'mapped',v_mapped,'review_required',v_review,'unmapped',v_unmapped,'observation_created',v_observation_created,'observation_updated',v_observation_updated,'observation_unchanged',v_observation_unchanged,'observation_superseded',v_observation_superseded,'course_level_changed',v_course_level_changed,'source_snapshot_at',p_source_snapshot_at);
end $$;


ALTER FUNCTION "public"."svc_layer1_apply_course_study_levels"("p_country_code" "text", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_registration_scheme" "text", "p_source_snapshot_at" timestamp with time zone, "p_records" "jsonb", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_apply_cricos_records"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_records" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'pim', 'ref', 'pipeline'
    AS $_$
declare
  r jsonb; v_country uuid; v_provider uuid; v_course uuid; v_family_provider uuid; v_family_course uuid; v_level uuid;
  v_pmatches int; v_cmatches int; v_provider_created int:=0; v_course_created int:=0; v_provider_linked int:=0; v_course_linked int:=0; v_conflicts int:=0;
  v_pcode text; v_ccode text; v_pname text; v_cname text; v_level_name text; v_weeks numeric;
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
  select id into v_country from ref.countries where iso_alpha2='AU';
  select id into v_family_provider from pim.attribute_families where entity_type='provider' and status='active' order by case when code='provider_default' then 0 else 1 end limit 1;
  select id into v_family_course from pim.attribute_families where entity_type='course' and status='active' order by case when code='course_default' then 0 else 1 end limit 1;
  if v_country is null then raise exception 'AU country seed missing'; end if;

  for r in select value from jsonb_array_elements(coalesce(p_records,'[]'::jsonb)) loop
    v_pcode:=upper(nullif(trim(r->>'provider_code'),'')); v_ccode:=upper(nullif(trim(r->>'course_code'),''));
    v_pname:=nullif(trim(r->>'provider_name'),''); v_cname:=nullif(trim(r->>'course_name'),''); v_level_name:=coalesce(r->>'course_level','');
    v_weeks:=case when (r->>'duration_weeks') ~ '^[0-9]+(\.[0-9]+)?$' then (r->>'duration_weeks')::numeric else null end;
    if v_pcode is null or v_pname is null then v_conflicts:=v_conflicts+1; continue; end if;

    select pr.provider_id into v_provider from catalogue.provider_registrations pr where lower(pr.registration_scheme)='cricos' and upper(pr.registration_code)=v_pcode order by pr.checked_at desc nulls last limit 1;
    if v_provider is null then
      select count(*), (array_agg(p.id order by p.id))[1]
      into v_pmatches,v_provider
      from catalogue.providers p
      where p.country_id=v_country and lower(regexp_replace(p.canonical_name,'[^a-z0-9]+','','g'))=lower(regexp_replace(v_pname,'[^a-z0-9]+','','g'));
      if v_pmatches=1 then
        insert into catalogue.provider_registrations(provider_id,source_id,registration_scheme,registration_code,status,checked_at,evidence_id)
        values(v_provider,p_source_id,'CRICOS',v_pcode,'active',now(),p_evidence_id) on conflict do nothing;
        update catalogue.providers set canonical_source_id=p_source_id,last_verified_at=now(),updated_at=now() where id=v_provider;
        v_provider_linked:=v_provider_linked+1;
      elsif v_pmatches=0 then
        insert into pim.entity_registry(entity_type,stable_key,family_id) values('provider','provider:cricos:'||lower(v_pcode),v_family_provider) returning id into v_provider;
        insert into catalogue.providers(id,stable_key,canonical_name,display_name,country_id,lifecycle_status,publication_status,canonical_source_id,last_verified_at)
        values(v_provider,'provider:cricos:'||lower(v_pcode),v_pname,v_pname,v_country,'active','unpublished',p_source_id,now());
        insert into catalogue.provider_registrations(provider_id,source_id,registration_scheme,registration_code,status,checked_at,evidence_id)
        values(v_provider,p_source_id,'CRICOS',v_pcode,'active',now(),p_evidence_id);
        v_provider_created:=v_provider_created+1;
      else v_conflicts:=v_conflicts+1; v_provider:=null; end if;
    else
      update catalogue.provider_registrations set source_id=p_source_id,status='active',checked_at=now(),evidence_id=p_evidence_id where provider_id=v_provider and lower(registration_scheme)='cricos' and upper(registration_code)=v_pcode;
      update catalogue.providers set canonical_source_id=p_source_id,last_verified_at=now(),updated_at=now() where id=v_provider;
    end if;

    if v_provider is null or v_ccode is null or v_cname is null then continue; end if;
    v_course:=null;
    select cr.course_id into v_course from catalogue.course_registrations cr where lower(cr.scheme)='cricos' and upper(cr.registration_code)=v_ccode order by cr.id limit 1;
    if v_course is null then
      select count(*), (array_agg(c.id order by c.id))[1]
      into v_cmatches,v_course
      from catalogue.courses c
      where c.provider_id=v_provider and lower(regexp_replace(c.canonical_title,'[^a-z0-9]+','','g'))=lower(regexp_replace(v_cname,'[^a-z0-9]+','','g'));
      if v_cmatches=1 then
        insert into catalogue.course_registrations(course_id,scheme,registration_code,country_id,status,source_id,evidence_id)
        values(v_course,'CRICOS',v_ccode,v_country,'active',p_source_id,p_evidence_id) on conflict do nothing;
        v_course_linked:=v_course_linked+1;
      elsif v_cmatches=0 then
        insert into pim.entity_registry(entity_type,stable_key,family_id) values('course','course:cricos:'||lower(v_ccode),v_family_course) returning id into v_course;
        insert into catalogue.courses(id,stable_key,provider_id,canonical_title,display_title,course_code,duration_value,duration_unit,lifecycle_status,publication_status,canonical_source_id,last_verified_at)
        values(v_course,'course:cricos:'||lower(v_ccode),v_provider,v_cname,v_cname,v_ccode,v_weeks,case when v_weeks is not null then 'weeks' end,'active','unpublished',p_source_id,now());
        insert into catalogue.course_registrations(course_id,scheme,registration_code,country_id,status,source_id,evidence_id)
        values(v_course,'CRICOS',v_ccode,v_country,'active',p_source_id,p_evidence_id);
        v_course_created:=v_course_created+1;
      else v_conflicts:=v_conflicts+1; v_course:=null; end if;
    end if;
    if v_course is not null then
      select id into v_level from ref.study_levels where code=case
        when lower(v_level_name) like '%doctor%' or lower(v_level_name) like '%phd%' then 'doctorate'
        when lower(v_level_name) like '%master%' then 'masters'
        when lower(v_level_name) like '%graduate certificate%' then 'graduate_certificate'
        when lower(v_level_name) like '%graduate diploma%' then 'graduate_diploma'
        when lower(v_level_name) like '%bachelor%' then 'bachelor'
        when lower(v_level_name) like '%associate%' then 'associate_degree'
        when lower(v_level_name) like '%diploma%' then 'diploma'
        when lower(v_level_name) like '%certificate%' then 'certificate'
        when lower(v_level_name) like '%foundation%' then 'foundation' else null end;
      update catalogue.courses set study_level_id=coalesce(v_level,study_level_id), duration_value=coalesce(v_weeks,duration_value), duration_unit=case when v_weeks is not null then 'weeks' else duration_unit end, canonical_source_id=p_source_id,last_verified_at=now(),updated_at=now() where id=v_course and (study_level_id is distinct from coalesce(v_level,study_level_id) or duration_value is distinct from coalesce(v_weeks,duration_value) or (v_weeks is not null and duration_unit is distinct from 'weeks') or canonical_source_id is distinct from p_source_id or last_verified_at is null or last_verified_at < now() - interval '30 days');
      update catalogue.course_registrations set source_id=p_source_id,status='active',evidence_id=p_evidence_id where course_id=v_course and lower(scheme)='cricos' and upper(registration_code)=v_ccode and (source_id is distinct from p_source_id or status is distinct from 'active' or evidence_id is null or not exists (select 1 from pipeline.evidence_artifacts ea where ea.id = catalogue.course_registrations.evidence_id and ea.captured_at >= now() - interval '30 days'));
    end if;
  end loop;
  return jsonb_build_object('provider_created',v_provider_created,'provider_linked',v_provider_linked,'course_created',v_course_created,'course_linked',v_course_linked,'conflicts',v_conflicts,'records',jsonb_array_length(coalesce(p_records,'[]'::jsonb)));
end $_$;


ALTER FUNCTION "public"."svc_layer1_apply_cricos_records"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_records" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_apply_location_records"("p_country_code" "text", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_registration_scheme" "text", "p_records" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'pipeline'
    AS $$
declare
  r jsonb;
  v_country uuid;
  v_provider uuid;
  v_course uuid;
  v_campus uuid;
  v_subdivision uuid;
  v_scheme text;
  v_pcode text;
  v_ccode text;
  v_lcode text;
  v_lname text;
  v_city text;
  v_state text;
  v_delivery text;
  v_stable text;
  v_campus_created int := 0;
  v_campus_existing int := 0;
  v_link_created int := 0;
  v_link_existing int := 0;
  v_provider_missing int := 0;
  v_course_missing int := 0;
  v_campus_missing int := 0;
  v_conflicts int := 0;
  v_unmapped_subdivision int := 0;
  v_location_records int := 0;
  v_course_location_records int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'service_role required';
  end if;
  v_scheme := lower(nullif(trim(p_registration_scheme),''));
  if v_scheme is null then raise exception 'registration scheme required'; end if;
  select id into v_country from ref.countries where upper(iso_alpha2::text)=upper(p_country_code);
  if v_country is null then raise exception 'country seed missing: %',p_country_code; end if;

  for r in select value from jsonb_array_elements(coalesce(p_records,'[]'::jsonb)) loop
    v_provider := null; v_course := null; v_campus := null; v_subdivision := null;
    v_pcode := upper(nullif(trim(r->>'provider_code'),''));
    v_ccode := upper(nullif(trim(r->>'course_code'),''));
    v_lcode := upper(nullif(trim(r->>'location_code'),''));
    v_lname := nullif(trim(r->>'location_name'),'');
    v_city := nullif(trim(r->>'city'),'');
    v_state := nullif(trim(r->>'state'),'');
    v_delivery := coalesce(nullif(trim(r->>'delivery_mode'),''),'on_campus');
    if v_pcode is null or v_lcode is null then v_conflicts:=v_conflicts+1; continue; end if;

    select pr.provider_id into v_provider
    from catalogue.provider_registrations pr
    join catalogue.providers p on p.id=pr.provider_id
    where p.country_id=v_country
      and lower(pr.registration_scheme)=v_scheme
      and upper(pr.registration_code)=v_pcode
    order by pr.checked_at desc nulls last, pr.id limit 1;
    if v_provider is null then v_provider_missing:=v_provider_missing+1; continue; end if;

    v_stable := 'campus:'||v_scheme||':'||lower(regexp_replace(v_pcode,'[^a-zA-Z0-9]+','-','g'))||':'||lower(regexp_replace(v_lcode,'[^a-zA-Z0-9]+','-','g'));
    select id into v_campus from catalogue.campuses where stable_key=v_stable limit 1;

    if v_ccode is null then
      v_location_records:=v_location_records+1;
      if v_state is not null then
        v_subdivision := ref.resolve_subdivision_exact(v_country,v_state);
        if v_subdivision is null then v_unmapped_subdivision:=v_unmapped_subdivision+1; end if;
      end if;
      if v_campus is null then
        insert into catalogue.campuses(stable_key,provider_id,name,campus_code,country_id,subdivision_id,city,address_line1,address_line2,postcode,status,publication_status,source_id,evidence_id,last_verified_at)
        values(v_stable,v_provider,coalesce(v_lname,v_lcode),v_lcode,v_country,v_subdivision,v_city,nullif(trim(r->>'address_line1'),''),nullif(trim(r->>'address_line2'),''),nullif(trim(r->>'postcode'),''),'active','unpublished',p_source_id,p_evidence_id,now())
        returning id into v_campus;
        v_campus_created:=v_campus_created+1;
      else
        update catalogue.campuses set
          name=coalesce(v_lname,name), subdivision_id=coalesce(v_subdivision,subdivision_id), city=coalesce(v_city,city),
          address_line1=coalesce(nullif(trim(r->>'address_line1'),''),address_line1),
          address_line2=coalesce(nullif(trim(r->>'address_line2'),''),address_line2),
          postcode=coalesce(nullif(trim(r->>'postcode'),''),postcode), status='active', source_id=p_source_id,
          evidence_id=coalesce(p_evidence_id,evidence_id), last_verified_at=now(), updated_at=now()
        where id=v_campus;
        v_campus_existing:=v_campus_existing+1;
      end if;
    else
      v_course_location_records:=v_course_location_records+1;
      if v_campus is null then v_campus_missing:=v_campus_missing+1; continue; end if;
      select cr.course_id into v_course
      from catalogue.course_registrations cr
      join catalogue.courses c on c.id=cr.course_id
      where c.provider_id=v_provider and lower(cr.scheme)=v_scheme and upper(cr.registration_code)=v_ccode
      order by cr.id limit 1;
      if v_course is null then v_course_missing:=v_course_missing+1; continue; end if;
      if exists(select 1 from catalogue.course_campuses where course_id=v_course and campus_id=v_campus and delivery_mode=v_delivery) then
        update catalogue.course_campuses set source_id=p_source_id,evidence_id=coalesce(p_evidence_id,evidence_id)
        where course_id=v_course and campus_id=v_campus and delivery_mode=v_delivery;
        v_link_existing:=v_link_existing+1;
      else
        insert into catalogue.course_campuses(course_id,campus_id,delivery_mode,is_primary,source_id,evidence_id)
        values(v_course,v_campus,v_delivery,false,p_source_id,p_evidence_id);
        v_link_created:=v_link_created+1;
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'location_records',v_location_records,'course_location_records',v_course_location_records,
    'campuses_created',v_campus_created,'campuses_existing',v_campus_existing,
    'course_links_created',v_link_created,'course_links_existing',v_link_existing,
    'provider_missing',v_provider_missing,'course_missing',v_course_missing,'campus_missing',v_campus_missing,
    'unmapped_subdivision',v_unmapped_subdivision,'conflicts',v_conflicts
  );
end $$;


ALTER FUNCTION "public"."svc_layer1_apply_location_records"("p_country_code" "text", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_registration_scheme" "text", "p_records" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_apply_register_records"("p_country_code" "text", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_registration_scheme" "text", "p_records" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'pim', 'ref', 'pipeline'
    AS $_$
declare
  r jsonb; v_country uuid; v_provider uuid; v_course uuid; v_family_provider uuid; v_family_course uuid; v_level uuid; v_subdivision uuid; v_field uuid; v_broad_field uuid;
  v_provider_created int:=0; v_provider_linked int:=0; v_provider_existing int:=0; v_course_created int:=0; v_course_linked int:=0; v_course_existing int:=0; v_conflicts int:=0; v_provider_unmapped_subdivision int:=0; v_field_mapped int:=0; v_field_unmapped int:=0;
  v_pcode text; v_ccode text; v_pname text; v_cname text; v_level_name text; v_weeks numeric; v_scheme text; v_website text; v_city text; v_state text; v_address1 text; v_address2 text; v_postcode text; v_provider_key text; v_course_key text; v_field_code text; v_field_name text; v_broad_code text; v_track boolean:=false;
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
  v_scheme:=lower(nullif(trim(p_registration_scheme),'')); if v_scheme is null then raise exception 'registration scheme required'; end if; select o.seen_tracking_since is not null into v_track from pipeline.layer1_source_operations o where o.source_id=p_source_id; v_track:=coalesce(v_track,false);
  select id into v_country from ref.countries where upper(iso_alpha2::text)=upper(p_country_code);
  select id into v_family_provider from pim.attribute_families where entity_type='provider' and status='active' order by case when code='provider_default' then 0 else 1 end limit 1;
  select id into v_family_course from pim.attribute_families where entity_type='course' and status='active' order by case when code='course_default' then 0 else 1 end limit 1;
  if v_country is null then raise exception 'country seed missing: %',p_country_code; end if;
  for r in select value from jsonb_array_elements(coalesce(p_records,'[]'::jsonb)) loop
    v_provider:=null; v_course:=null; v_level:=null; v_subdivision:=null; v_field:=null; v_broad_field:=null;
    v_pcode:=upper(nullif(trim(r->>'provider_code'),'')); v_ccode:=upper(nullif(trim(r->>'course_code'),'')); v_pname:=nullif(trim(r->>'provider_name'),''); v_cname:=nullif(trim(r->>'course_name'),'');
    v_level_name:=lower(coalesce(r->>'course_level','')); v_website:=nullif(trim(r->>'website'),''); v_city:=nullif(trim(r->>'city'),''); v_state:=nullif(trim(r->>'state'),''); v_address1:=nullif(trim(r->>'address_line1'),''); v_address2:=nullif(trim(r->>'address_line2'),''); v_postcode:=nullif(trim(r->>'postcode'),'');
    v_field_code:=nullif(trim(r->>'field_code'),''); v_field_name:=nullif(trim(r->>'field_name'),'');
    v_weeks:=case when (r->>'duration_weeks') ~ '^[0-9]+(\.[0-9]+)?$' then (r->>'duration_weeks')::numeric else null end;
    if v_pcode is null or v_pname is null then v_conflicts:=v_conflicts+1; continue; end if;
    if v_state is not null then v_subdivision:=ref.resolve_subdivision_exact(v_country,v_state); if v_subdivision is null then v_provider_unmapped_subdivision:=v_provider_unmapped_subdivision+1; end if; end if;
    v_provider_key := 'provider:'||v_scheme||':'||lower(regexp_replace(v_pcode,'[^a-zA-Z0-9]+','-','g'));
    select pr.provider_id into v_provider from catalogue.provider_registrations pr join catalogue.providers p on p.id=pr.provider_id where p.country_id=v_country and lower(pr.registration_scheme)=v_scheme and upper(pr.registration_code)=v_pcode order by pr.checked_at desc nulls last,pr.id limit 1;
    if v_provider is null then
      select p.id into v_provider from catalogue.providers p where p.country_id=v_country and p.stable_key=v_provider_key limit 1;
      if v_provider is null then
        insert into pim.entity_registry(entity_type,stable_key,family_id) values('provider',v_provider_key,v_family_provider) returning id into v_provider;
        insert into catalogue.providers(id,stable_key,canonical_name,display_name,country_id,subdivision_id,website,primary_city,address_line1,address_line2,postcode,lifecycle_status,publication_status,canonical_source_id,last_verified_at)
        values(v_provider,v_provider_key,v_pname,v_pname,v_country,v_subdivision,v_website,v_city,v_address1,v_address2,v_postcode,'active','unpublished',p_source_id,now()); v_provider_created:=v_provider_created+1;
      else v_provider_linked:=v_provider_linked+1; end if;
      insert into catalogue.provider_registrations(provider_id,source_id,registration_scheme,registration_code,status,checked_at,evidence_id) values(v_provider,p_source_id,v_scheme,v_pcode,'active',now(),p_evidence_id) on conflict do nothing;
    else v_provider_existing:=v_provider_existing+1; end if;
    update catalogue.provider_registrations set source_id=p_source_id,status='active',checked_at=now(),evidence_id=coalesce(p_evidence_id,evidence_id) where provider_id=v_provider and lower(registration_scheme)=v_scheme and upper(registration_code)=v_pcode;
    update catalogue.providers set canonical_source_id=p_source_id,last_verified_at=now(),website=coalesce(website,v_website),primary_city=coalesce(primary_city,v_city),subdivision_id=coalesce(v_subdivision,subdivision_id),address_line1=coalesce(address_line1,v_address1),address_line2=coalesce(address_line2,v_address2),postcode=coalesce(postcode,v_postcode),updated_at=now() where id=v_provider;
    if v_ccode is null or v_cname is null then continue; end if;
    v_course_key := 'course:'||v_scheme||':'||lower(regexp_replace(v_pcode,'[^a-zA-Z0-9]+','-','g'))||':'||lower(regexp_replace(v_ccode,'[^a-zA-Z0-9]+','-','g'));
    select cr.course_id into v_course from catalogue.course_registrations cr join catalogue.courses c on c.id=cr.course_id where c.provider_id=v_provider and lower(cr.scheme)=v_scheme and upper(cr.registration_code)=v_ccode order by cr.id limit 1;
    if v_course is null then
      select c.id into v_course from catalogue.courses c where c.provider_id=v_provider and c.stable_key=v_course_key limit 1;
      if v_course is null then
        insert into pim.entity_registry(entity_type,stable_key,family_id) values('course',v_course_key,v_family_course) returning id into v_course;
        insert into catalogue.courses(id,stable_key,provider_id,canonical_title,display_title,course_code,duration_value,duration_unit,lifecycle_status,publication_status,canonical_source_id,last_verified_at) values(v_course,v_course_key,v_provider,v_cname,v_cname,v_ccode,v_weeks,case when v_weeks is not null then 'weeks' end,'active','unpublished',p_source_id,now()); v_course_created:=v_course_created+1;
      else v_course_linked:=v_course_linked+1; end if;
      insert into catalogue.course_registrations(course_id,scheme,registration_code,country_id,status,source_id,evidence_id) values(v_course,v_scheme,v_ccode,v_country,'active',p_source_id,p_evidence_id) on conflict do nothing;
    else v_course_existing:=v_course_existing+1; end if;
    select id into v_level from ref.study_levels where code=case when v_level_name like '%doctor%' or v_level_name like '%phd%' then 'doctorate' when v_level_name like '%master%' then 'masters' when v_level_name like '%graduate certificate%' then 'graduate_certificate' when v_level_name like '%graduate diploma%' then 'graduate_diploma' when v_level_name like '%bachelor%' then 'bachelor' when v_level_name like '%associate%' then 'associate_degree' when v_level_name like '%diploma%' then 'diploma' when v_level_name like '%certificate%' then 'certificate' when v_level_name like '%foundation%' then 'foundation' else null end;
    if v_field_code is not null and v_field_name is not null and v_field_code ~ '^[0-9]{4}$' then
      v_broad_code:=left(v_field_code,2);
      select id into v_broad_field from ref.fields_of_study where code='asced-'||v_broad_code;
      if v_broad_field is not null then
        insert into ref.fields_of_study(code,name,parent_id,path,depth,status) values('asced-'||v_field_code,v_field_name,v_broad_field,'asced/'||v_broad_code||'/'||v_field_code,1,'active') on conflict(code) do update set name=excluded.name,parent_id=excluded.parent_id,path=excluded.path,status='active',updated_at=now() returning id into v_field;
        insert into catalogue.course_field_observations(course_id,field_id,source_id,evidence_id,source_field_code,source_field_name,is_primary,status,observed_at,updated_at)
        values(v_course,v_field,p_source_id,p_evidence_id,v_field_code,v_field_name,true,'current',now(),now()) on conflict(course_id,source_id,source_field_code) do update set field_id=excluded.field_id,evidence_id=coalesce(excluded.evidence_id,catalogue.course_field_observations.evidence_id),source_field_name=excluded.source_field_name,status='current',observed_at=now(),updated_at=now();
        v_field_mapped:=v_field_mapped+1;
      else v_field_unmapped:=v_field_unmapped+1; end if;
    elsif v_field_code is not null or v_field_name is not null then v_field_unmapped:=v_field_unmapped+1; end if;
    update catalogue.courses set study_level_id=coalesce(v_level,study_level_id),primary_field_id=coalesce(v_field,primary_field_id),duration_value=coalesce(v_weeks,duration_value),duration_unit=case when v_weeks is not null then 'weeks' else duration_unit end,canonical_source_id=p_source_id,last_verified_at=now(),updated_at=now() where id=v_course and (study_level_id is distinct from coalesce(v_level,study_level_id) or primary_field_id is distinct from coalesce(v_field,primary_field_id) or duration_value is distinct from coalesce(v_weeks,duration_value) or (v_weeks is not null and duration_unit is distinct from 'weeks') or canonical_source_id is distinct from p_source_id or last_verified_at is null or last_verified_at < now() - interval '30 days');
    update catalogue.course_registrations set source_id=p_source_id,status='active',evidence_id=coalesce(p_evidence_id,evidence_id) where course_id=v_course and lower(scheme)=v_scheme and upper(registration_code)=v_ccode and (source_id is distinct from p_source_id or status is distinct from 'active' or evidence_id is null or not exists (select 1 from pipeline.evidence_artifacts ea where ea.id = catalogue.course_registrations.evidence_id and ea.captured_at >= now() - interval '30 days'));
  if v_track then insert into pipeline.layer1_register_row_state(source_id,record_key,fingerprint,applied_run_id,applied_at,seen_at) values(p_source_id,v_pcode||'|'||v_ccode,'seen',null,now(),now()) on conflict (source_id,record_key) do update set seen_at=now() where pipeline.layer1_register_row_state.seen_at < now()-interval '1 day'; end if; end loop;
  return jsonb_build_object('provider_created',v_provider_created,'provider_linked',v_provider_linked,'provider_existing',v_provider_existing,'course_created',v_course_created,'course_linked',v_course_linked,'course_existing',v_course_existing,'provider_unmapped_subdivision',v_provider_unmapped_subdivision,'field_mapped',v_field_mapped,'field_unmapped',v_field_unmapped,'conflicts',v_conflicts,'records',jsonb_array_length(coalesce(p_records,'[]'::jsonb)));
end $_$;


ALTER FUNCTION "public"."svc_layer1_apply_register_records"("p_country_code" "text", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_registration_scheme" "text", "p_records" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_apply_scoped_course_records"("p_country_code" "text", "p_provider_source_id" "uuid", "p_course_source_id" "uuid", "p_evidence_id" "uuid", "p_provider_scheme" "text", "p_course_scheme" "text", "p_records" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'pim', 'ref', 'pipeline', 'extensions'
    AS $_$
declare
  r jsonb;
  v_country uuid;
  v_provider uuid;
  v_course uuid;
  v_family_provider uuid;
  v_family_course uuid;
  v_pcode text;
  v_ccode text;
  v_pname text;
  v_cname text;
  v_provider_key text;
  v_course_key text;
  v_course_identity_name text;
  v_provider_created int:=0;
  v_provider_existing int:=0;
  v_course_created int:=0;
  v_course_existing int:=0;
  v_conflicts int:=0;
  v_reg_scheme text;
  v_reg_code text;
  v_lifecycle text;
  v_active int:=0;
  v_suspended int:=0;
  v_inactive int:=0;
  v_unknown int:=0;
  v_is_ca_aps boolean:=false;
  v_aps_source_ok boolean:=false;
  v_aps_mapping_ok boolean:=false;
begin
  if nullif(trim(p_provider_scheme),'') is null or nullif(trim(p_course_scheme),'') is null then
    raise exception 'provider and course identity schemes are required';
  end if;
  if upper(p_country_code)='CA' and lower(trim(p_provider_scheme)) <> 'ircc_dli' then
    raise exception 'Canada Provider identity must use IRCC DLI';
  end if;

  v_is_ca_aps := upper(p_country_code)='CA' and lower(trim(p_course_scheme))='on_aps';
  if v_is_ca_aps then
    select exists(
      select 1
      from pipeline.sources s
      join integration.systems i on i.id=s.system_id
      where s.id=p_course_source_id
        and i.code='ca_on_public_college_programs'
        and s.status='active'
        and i.status='active'
    ) into v_aps_source_ok;
    if not v_aps_source_ok then
      raise exception 'Ontario APS Course identity is restricted to the active Ontario government public-college programme source';
    end if;
  elsif upper(p_country_code)='CA' and lower(trim(p_course_scheme)) in ('aps','mtcu','cip','cip_2021') then
    raise exception 'Canada provincial/classification identifiers are not general base Course identities; only guarded Ontario on_aps mappings are permitted';
  end if;

  select id into v_country from ref.countries where upper(iso_alpha2::text)=upper(p_country_code);
  if v_country is null then raise exception 'country seed missing: %', p_country_code; end if;
  select id into v_family_provider from pim.attribute_families where entity_type='provider' and status='active' order by case when code='provider_default' then 0 else 1 end limit 1;
  select id into v_family_course from pim.attribute_families where entity_type='course' and status='active' order by case when code='course_default' then 0 else 1 end limit 1;

  for r in select value from jsonb_array_elements(coalesce(p_records,'[]'::jsonb)) loop
    v_pcode:=upper(nullif(trim(r->>'provider_code'),''));
    v_ccode:=nullif(trim(coalesce(r->>'local_program_id',r->>'course_code')),'');
    v_pname:=nullif(trim(r->>'provider_name'),'');
    v_cname:=nullif(trim(coalesce(r->>'course_title',r->>'course_name')),'');
    v_reg_scheme:=lower(nullif(trim(r->>'regional_reg_scheme'),''));
    v_reg_code:=nullif(trim(r->>'regional_reg_code'),'');
    v_lifecycle:=lower(coalesce(nullif(trim(r->>'lifecycle_status'),''),'active'));
    if v_lifecycle not in ('active','suspended','inactive','unknown') then v_conflicts:=v_conflicts+1; continue; end if;
    if v_pcode is null or v_pname is null or v_ccode is null or v_cname is null then v_conflicts:=v_conflicts+1; continue; end if;

    if v_is_ca_aps then
      if v_ccode !~ '^[0-9]{5}$' then raise exception 'Ontario APS identity must be a five-digit code: %',v_ccode; end if;
      select exists(
        select 1
        from pipeline.source_provider_mappings spm
        where spm.source_id=p_course_source_id
          and spm.status='verified'
          and upper(spm.metadata->>'ircc_dli')=v_pcode
          and coalesce((spm.metadata->>'identity_write_allowed')::boolean,false)=true
          and spm.metadata->>'course_identity_scheme'='on_aps'
      ) into v_aps_mapping_ok;
      if not v_aps_mapping_ok then
        raise exception 'Ontario APS Course identity is not approved for Provider DLI %',v_pcode;
      end if;
    end if;

    v_provider_key:='provider:'||lower(p_country_code)||':'||lower(p_provider_scheme)||':'||lower(regexp_replace(v_pcode,'[^a-zA-Z0-9]+','-','g'));
    select pi.provider_id into v_provider from catalogue.provider_identifiers pi where pi.country_id=v_country and lower(pi.scheme)=lower(p_provider_scheme) and upper(pi.identifier)=v_pcode order by pi.is_primary desc, pi.verified_at desc nulls last limit 1;
    if v_provider is null then select id into v_provider from catalogue.providers where stable_key=v_provider_key limit 1; end if;
    if v_provider is null then
      insert into pim.entity_registry(entity_type,stable_key,family_id) values('provider',v_provider_key,v_family_provider) returning id into v_provider;
      insert into catalogue.providers(id,stable_key,canonical_name,display_name,country_id,lifecycle_status,publication_status,canonical_source_id,last_verified_at)
      values(v_provider,v_provider_key,v_pname,v_pname,v_country,'active','unpublished',p_provider_source_id,now());
      v_provider_created:=v_provider_created+1;
    else
      update catalogue.providers set canonical_name=v_pname,display_name=v_pname,canonical_source_id=p_provider_source_id,last_verified_at=now(),updated_at=now() where id=v_provider;
      v_provider_existing:=v_provider_existing+1;
    end if;
    insert into catalogue.provider_identifiers(provider_id,scheme,identifier,country_id,issuing_authority,is_primary,source_id,evidence_id,verified_at)
    values(v_provider,lower(p_provider_scheme),v_pcode,v_country,'IRCC',true,p_provider_source_id,p_evidence_id,now())
    on conflict (provider_id,scheme,identifier) do update set source_id=excluded.source_id,evidence_id=excluded.evidence_id,verified_at=excluded.verified_at,is_primary=true;
    insert into catalogue.provider_registrations(provider_id,source_id,registration_scheme,registration_code,status,checked_at,evidence_id)
    values(v_provider,p_provider_source_id,lower(p_provider_scheme),v_pcode,'active',now(),p_evidence_id) on conflict do nothing;

    v_course_key:='course:'||lower(p_country_code)||':'||lower(p_provider_scheme)||':'||lower(regexp_replace(v_pcode,'[^a-zA-Z0-9]+','-','g'))||':'||lower(p_course_scheme)||':'||lower(regexp_replace(v_ccode,'[^a-zA-Z0-9]+','-','g'));
    v_course_identity_name:='coursefinder:'||lower(p_country_code)||':'||lower(v_pcode)||':'||lower(p_course_scheme)||':'||lower(v_ccode);
    select ci.course_id into v_course from catalogue.course_identifiers ci where ci.provider_id=v_provider and lower(ci.scheme)=lower(p_course_scheme) and ci.identifier=v_ccode limit 1;
    if v_course is null then select id into v_course from catalogue.courses where stable_key=v_course_key limit 1; end if;
    if v_course is null then
      if upper(p_country_code)='CA' then
        v_course:=extensions.uuid_generate_v5(extensions.uuid_ns_url(),v_course_identity_name);
        insert into pim.entity_registry(id,entity_type,stable_key,family_id) values(v_course,'course',v_course_key,v_family_course);
      else
        insert into pim.entity_registry(entity_type,stable_key,family_id) values('course',v_course_key,v_family_course) returning id into v_course;
      end if;
      insert into catalogue.courses(id,stable_key,provider_id,canonical_title,display_title,course_code,lifecycle_status,publication_status,canonical_source_id,last_verified_at)
      values(v_course,v_course_key,v_provider,v_cname,v_cname,v_ccode,v_lifecycle,'unpublished',p_course_source_id,now());
      v_course_created:=v_course_created+1;
    else
      update catalogue.courses set canonical_title=v_cname,display_title=v_cname,course_code=v_ccode,lifecycle_status=v_lifecycle,canonical_source_id=p_course_source_id,last_verified_at=now(),updated_at=now() where id=v_course and (canonical_title is distinct from v_cname or display_title is distinct from v_cname or course_code is distinct from v_ccode or lifecycle_status is distinct from v_lifecycle or canonical_source_id is distinct from p_course_source_id or last_verified_at is null or last_verified_at < now() - interval '30 days');
      v_course_existing:=v_course_existing+1;
    end if;
    insert into catalogue.course_identifiers(course_id,provider_id,scheme,identifier,country_id,issuing_authority,is_primary,source_id,evidence_id,verified_at)
    values(v_course,v_provider,lower(p_course_scheme),v_ccode,v_country,coalesce(nullif(trim(r->>'issuing_authority'),''),'Authoritative local course source'),true,p_course_source_id,p_evidence_id,now())
    on conflict (provider_id,scheme,identifier) do update set course_id=excluded.course_id,source_id=excluded.source_id,evidence_id=excluded.evidence_id,verified_at=excluded.verified_at,is_primary=true;
    if v_reg_scheme is not null and v_reg_code is not null then
      insert into catalogue.course_registrations(course_id,scheme,registration_code,country_id,status,source_id,evidence_id)
      values(v_course,v_reg_scheme,v_reg_code,v_country,'active',p_course_source_id,p_evidence_id) on conflict do nothing;
    end if;
    case v_lifecycle when 'active' then v_active:=v_active+1; when 'suspended' then v_suspended:=v_suspended+1; when 'inactive' then v_inactive:=v_inactive+1; else v_unknown:=v_unknown+1; end case;
  end loop;
  return jsonb_build_object(
    'provider_created',v_provider_created,'provider_existing',v_provider_existing,
    'course_created',v_course_created,'course_existing',v_course_existing,'conflicts',v_conflicts,
    'records',jsonb_array_length(coalesce(p_records,'[]'::jsonb)),
    'lifecycle',jsonb_build_object('active',v_active,'suspended',v_suspended,'inactive',v_inactive,'unknown',v_unknown),
    'identity_contract',case when upper(p_country_code)='CA' and lower(trim(p_course_scheme))='on_aps' then 'provider=IRCC_DLI; course=UUIDv5(DLI+Ontario_APS); APS permission=government-source+verified-provider-mapping; title=mutable; current table membership=regulatory currentness' when upper(p_country_code)='CA' then 'provider=IRCC_DLI; course=UUIDv5(DLI+local_source_key); title=mutable; lifecycle=source_normalized' else 'country_scoped' end
  );
end $_$;


ALTER FUNCTION "public"."svc_layer1_apply_scoped_course_records"("p_country_code" "text", "p_provider_source_id" "uuid", "p_course_source_id" "uuid", "p_evidence_id" "uuid", "p_provider_scheme" "text", "p_course_scheme" "text", "p_records" "jsonb") OWNER TO "postgres";


