    SET "search_path" TO 'public', 'pipeline', 'pg_temp'
    AS $$ declare v jsonb; begin if coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if; select jsonb_build_object('id',e.id,'source_id',e.source_id,'storage_path',e.storage_path,'content_hash',e.content_hash,'mime_type',e.mime_type,'metadata',e.metadata,'captured_at',e.captured_at) into v from pipeline.evidence_artifacts e where e.id=p_evidence_id and e.source_id=p_source_id; if v is null then raise exception 'evidence/source mismatch'; end if; return v; end $$;


