CREATE OR REPLACE FUNCTION "public"."svc_layer1_plan_slice"("p_run_id" "uuid", "p_offset" integer, "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select jsonb_build_object(
    'exists', p.run_id is not null,
    'to_apply', jsonb_array_length(p.items),
    'register_total', p.register_total,
    'keys', coalesce((select jsonb_agg(i->0 order by o) from jsonb_array_elements(p.items) with ordinality x(i,o)
                       where o>greatest(p_offset,0) and o<=greatest(p_offset,0)+greatest(least(p_limit,500),1)),'[]'::jsonb),
    'zip_evidence_id', p.zip_evidence_id, 'zip_path', z.storage_path, 'zip_hash', z.content_hash, 'zip_url', z.source_url, 'zip_meta', z.metadata,
    'course_evidence_id', p.course_evidence_id, 'course_path', c.storage_path, 'course_hash', p.course_hash, 'course_url', c.source_url, 'course_meta', c.metadata)
  from pipeline.layer1_run_plans p
  left join pipeline.evidence_artifacts z on z.id=p.zip_evidence_id
  left join pipeline.evidence_artifacts c on c.id=p.course_evidence_id
  where p.run_id=p_run_id
$$;


ALTER FUNCTION "public"."svc_layer1_plan_slice"("p_run_id" "uuid", "p_offset" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_put_seed_snapshot"("p_country_code" "text", "p_snapshot" "jsonb", "p_seed_source" "text" DEFAULT 'coursefinder-demo-layer1-core'::"text", "p_seed_version" "text" DEFAULT '2026-08-11'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pipeline', 'extensions'
    AS $$
declare v_providers int; v_courses int; v_hash text;
begin
 if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
 v_providers:=jsonb_array_length(coalesce(p_snapshot,'[]'::jsonb));
 select coalesce(sum(jsonb_array_length(coalesce(x->'q','[]'::jsonb))),0)::int into v_courses from jsonb_array_elements(coalesce(p_snapshot,'[]'::jsonb)) x;
 v_hash:=encode(extensions.digest(convert_to(coalesce(p_snapshot,'[]'::jsonb)::text,'UTF8'),'sha256'),'hex');
 insert into pipeline.layer1_seed_snapshots(country_code,snapshot,seed_source,seed_version,provider_count,course_count,content_hash,updated_at)
 values(upper(p_country_code),coalesce(p_snapshot,'[]'::jsonb),p_seed_source,p_seed_version,v_providers,v_courses,v_hash,now())
 on conflict(country_code) do update set snapshot=excluded.snapshot,seed_source=excluded.seed_source,seed_version=excluded.seed_version,provider_count=excluded.provider_count,course_count=excluded.course_count,content_hash=excluded.content_hash,updated_at=now();
 return jsonb_build_object('country',upper(p_country_code),'providers',v_providers,'courses',v_courses,'content_hash',v_hash);
end $$;


ALTER FUNCTION "public"."svc_layer1_put_seed_snapshot"("p_country_code" "text", "p_snapshot" "jsonb", "p_seed_source" "text", "p_seed_version" "text") OWNER TO "postgres";


