CREATE OR REPLACE FUNCTION "public"."svc_layer1_record_validation"("p_source_id" "uuid", "p_success" boolean, "p_expected_count" bigint, "p_source_hash" "text", "p_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_prev bigint; v_warn numeric; v_block numeric; v_min bigint; v_max bigint; v_var numeric; v_dec text; v_status text; v_next timestamptz;
begin
  select previous_accepted_count,variance_warn_percent,variance_block_percent,min_expected_records,max_expected_records into v_prev,v_warn,v_block,v_min,v_max from pipeline.layer1_source_operations where source_id=p_source_id for update;
  if not found then raise exception 'source operations profile missing'; end if;
  if p_success and p_expected_count is not null and p_expected_count<0 then raise exception 'expected count invalid'; end if;
  if p_success and v_prev is not null and v_prev>0 and p_expected_count is not null then v_var:=round(((p_expected_count-v_prev)::numeric/v_prev::numeric)*100,4); else v_var:=null; end if;
  if not p_success then v_dec:='block'; v_status:='failed';
  elsif p_expected_count is null then v_dec:='warn'; v_status:='warning';
  elsif v_min is not null and p_expected_count<v_min then v_dec:='block'; v_status:='blocked';
  elsif v_max is not null and p_expected_count>v_max then v_dec:='block'; v_status:='blocked';
  elsif v_var is not null and abs(v_var)>=v_block then v_dec:='block'; v_status:='blocked';
  elsif v_var is not null and abs(v_var)>=v_warn then v_dec:='warn'; v_status:='warning';
  else v_dec:='pass'; v_status:='passed'; end if;
  select now()+make_interval(days=>verification_cadence_days) into v_next from pipeline.layer1_source_operations where source_id=p_source_id;
  update pipeline.layer1_source_operations set last_verified_at=now(),verification_status=v_status,verification_message=left(coalesce(p_message,case when p_success then 'Source verified' else 'Source validation failed' end),1000),last_expected_count=p_expected_count,last_source_hash=coalesce(p_source_hash,last_source_hash),variance_percent=v_var,variance_decision=v_dec,next_verification_at=v_next,consecutive_failures=case when p_success then 0 else consecutive_failures+1 end,updated_at=now() where source_id=p_source_id;
  update pipeline.sources set last_checked_at=now(),last_success_at=case when p_success then now() else last_success_at end,last_failure_at=case when p_success then last_failure_at else now() end,last_error=case when p_success then null else left(coalesce(p_message,'validation failed'),1000) end,updated_at=now() where id=p_source_id;
  return jsonb_build_object('source_id',p_source_id,'verification_status',v_status,'expected_count',p_expected_count,'previous_accepted_count',v_prev,'variance_percent',v_var,'variance_decision',v_dec,'next_verification_at',v_next);
end $$;


ALTER FUNCTION "public"."svc_layer1_record_validation"("p_source_id" "uuid", "p_success" boolean, "p_expected_count" bigint, "p_source_hash" "text", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_replace_source_inventory"("p_country_code" "text", "p_source_id" "uuid", "p_provider_id" "uuid", "p_inventory_hash" "text", "p_records" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pipeline', 'ref'
    AS $$
declare v_country uuid; v_count int:=0; r jsonb;
begin
  select id into v_country from ref.countries where upper(iso_alpha2::text)=upper(p_country_code);
  if v_country is null then raise exception 'country missing'; end if;
  if nullif(trim(p_inventory_hash),'') is null then raise exception 'inventory hash required'; end if;
  delete from pipeline.source_record_staging where source_id=p_source_id and provider_id=p_provider_id;
  for r in select value from jsonb_array_elements(coalesce(p_records,'[]'::jsonb)) loop
    insert into pipeline.source_record_staging(country_id,source_id,provider_id,source_record_id,raw_payload,content_hash,status,ingested_at)
    values(v_country,p_source_id,p_provider_id,lower(trim(r->>'guid')),r,p_inventory_hash,'pending',now());
    v_count:=v_count+1;
  end loop;
  return jsonb_build_object('staged',v_count,'inventory_hash',p_inventory_hash);
end $$;


ALTER FUNCTION "public"."svc_layer1_replace_source_inventory"("p_country_code" "text", "p_source_id" "uuid", "p_provider_id" "uuid", "p_inventory_hash" "text", "p_records" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_reset_au_uat"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'pim', 'ref', 'pipeline', 'workflow', 'scholarship', 'search', 'publishing', 'integration'
    AS $$
declare
  v_deleted_registry bigint := 0;
  v_deleted_jobs bigint := 0;
  v_deleted_evidence bigint := 0;
  v_deleted_reviews bigint := 0;
  v_deleted_scholarships bigint := 0;
  v_search_generation bigint := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;

  delete from workflow.review_actions where true;
  delete from workflow.review_queue where true; get diagnostics v_deleted_reviews = row_count;
  delete from workflow.suggestions where true;
  delete from workflow.import_errors where true;
  delete from workflow.import_rows where true;
  delete from workflow.import_jobs where true;
  delete from workflow.export_jobs where true;
  delete from workflow.reconciliation_checks where true;
  delete from workflow.migration_entity_map where true;
  delete from workflow.migration_runs where true;
  delete from workflow.handover_events where true;

  delete from search.embedding_jobs where true;
  delete from search.course_embeddings where true;
  delete from search.course_documents where true;
  delete from search.query_embedding_cache where true;
  update search.projection_state set generation=0,row_count=0,rebuilt_at=now() where projection_code='courses';

  delete from publishing.entity_states where true;

  delete from scholarship.coverage where true;
  delete from scholarship.criteria where true;
  delete from scholarship.scopes where true;
  delete from scholarship.award_tiers where true;
  delete from scholarship.scholarships where true; get diagnostics v_deleted_scholarships = row_count;

  delete from pipeline.claims where true;
  delete from pipeline.evidence_artifacts where true; get diagnostics v_deleted_evidence = row_count;
  delete from pipeline.jobs where true; get diagnostics v_deleted_jobs = row_count;

  delete from integration.extraction_profiles where provider_id is not null;
  delete from pipeline.acquisition_policies where provider_id is not null;
  update pipeline.sources set provider_id=null where provider_id is not null;
  update pipeline.sources
     set last_checked_at=null,last_success_at=null,last_failure_at=null,last_error=null,
         metadata=coalesce(metadata,'{}'::jsonb)-'worker_version'-'latest_job_id'-'institution_hash'-'course_hash'-'parsed_records'-'resource_updated',
         updated_at=now();

  delete from pim.attribute_values where true;
  delete from pim.entity_categories where true;
  delete from pim.entity_registry where true; get diagnostics v_deleted_registry = row_count;

  perform search.rebuild_course_documents();
  select generation into v_search_generation from search.projection_state where projection_code='courses';

  return jsonb_build_object(
    'status','reset','baseline','layer1_execution_seed',
    'providers',(select count(*) from catalogue.providers),
    'courses',(select count(*) from catalogue.courses),
    'scholarships',(select count(*) from scholarship.scholarships),
    'search_documents',(select count(*) from search.course_documents),
    'search_generation',coalesce(v_search_generation,0),
    'pipeline_jobs',(select count(*) from pipeline.jobs),
    'evidence_metadata',(select count(*) from pipeline.evidence_artifacts),
    'review_queue',(select count(*) from workflow.review_queue),
    'cricos_course_registrations',(select count(*) from catalogue.course_registrations where lower(scheme)='cricos'),
    'cricos_provider_registrations',(select count(*) from catalogue.provider_registrations where lower(registration_scheme)='cricos'),
    'deleted_entity_registry',v_deleted_registry,'deleted_jobs',v_deleted_jobs,
    'deleted_evidence_metadata',v_deleted_evidence,'deleted_reviews',v_deleted_reviews,
    'deleted_scholarships',v_deleted_scholarships
  );
end;
$$;


ALTER FUNCTION "public"."svc_layer1_reset_au_uat"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_reset_database"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'pim', 'ref', 'pipeline', 'workflow', 'scholarship', 'search', 'publishing', 'integration'
    AS $$
declare
 v_deleted_registry bigint:=0; v_deleted_jobs bigint:=0; v_deleted_evidence bigint:=0; v_deleted_reviews bigint:=0; v_search_generation bigint:=0;
begin
 if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
 delete from workflow.review_actions where id is not null;
 delete from workflow.review_queue where id is not null; get diagnostics v_deleted_reviews=row_count;
 delete from workflow.suggestions where id is not null;
 delete from workflow.import_errors where id is not null;
 delete from workflow.import_rows where id is not null;
 delete from workflow.import_jobs where id is not null;
 delete from workflow.export_jobs where id is not null;
 delete from workflow.reconciliation_checks where id is not null;
 delete from workflow.migration_entity_map where id is not null;
 delete from workflow.migration_runs where id is not null;
 delete from workflow.handover_events where id is not null;
 delete from search.embedding_jobs where id is not null;
 delete from search.course_embeddings where course_id is not null;
 delete from search.course_documents where course_id is not null;
 delete from search.query_embedding_cache where cache_key is not null;
 update search.projection_state set generation=0,row_count=0,rebuilt_at=now() where projection_code='courses';
 delete from publishing.entity_states where entity_id is not null;
 delete from scholarship.coverage where id is not null;
 delete from scholarship.criteria where id is not null;
 delete from scholarship.scopes where id is not null;
 delete from scholarship.award_tiers where id is not null;
 delete from scholarship.scholarships where id is not null;
 delete from integration.extraction_profiles where provider_id is not null;
 delete from pipeline.acquisition_policies where provider_id is not null;
 update pipeline.sources set provider_id=null where provider_id is not null;
 delete from pim.attribute_values where id is not null;
 delete from pim.entity_categories where entity_id is not null;
 delete from pim.entity_registry where id is not null; get diagnostics v_deleted_registry=row_count;
 delete from pipeline.claims where id is not null;
 delete from pipeline.evidence_artifacts where id is not null; get diagnostics v_deleted_evidence=row_count;
 delete from pipeline.jobs where id is not null; get diagnostics v_deleted_jobs=row_count;
 update pipeline.sources set last_checked_at=null,last_success_at=null,last_failure_at=null,last_error=null,
   metadata=coalesce(metadata,'{}'::jsonb)-'worker_version'-'latest_job_id'-'institution_hash'-'course_hash'-'location_hash'-'course_location_hash'-'parsed_records'-'parsed_locations'-'parsed_course_locations'-'resource_updated'-'last_run_mode'-'last_run_records',updated_at=now()
 where id is not null;
 perform search.rebuild_course_documents();
 select generation into v_search_generation from search.projection_state where projection_code='courses';
 return jsonb_build_object('status','reset','baseline','layer1_execution_seed','providers',(select count(*) from catalogue.providers),'courses',(select count(*) from catalogue.courses),'campuses',(select count(*) from catalogue.campuses),'course_campus_links',(select count(*) from catalogue.course_campuses),'scholarships',(select count(*) from scholarship.scholarships),'search_documents',(select count(*) from search.course_documents),'search_generation',coalesce(v_search_generation,0),'pipeline_jobs',(select count(*) from pipeline.jobs),'evidence_metadata',(select count(*) from pipeline.evidence_artifacts),'review_queue',(select count(*) from workflow.review_queue),'deleted_entity_registry',v_deleted_registry,'deleted_jobs',v_deleted_jobs,'deleted_evidence_metadata',v_deleted_evidence,'deleted_reviews',v_deleted_reviews);
end $$;


ALTER FUNCTION "public"."svc_layer1_reset_database"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_layer1_resolve_provider_by_identifier"("p_country_code" "text", "p_scheme" "text", "p_identifier" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'catalogue', 'ref'
    AS $$
  select to_jsonb(x) from (
    select p.id as provider_id,p.canonical_name,p.display_name,pi.identifier,c.iso_alpha2::text as country_code
    from catalogue.provider_identifiers pi
    join catalogue.providers p on p.id=pi.provider_id
    join ref.countries c on c.id=pi.country_id
    where upper(c.iso_alpha2::text)=upper(p_country_code)
      and lower(pi.scheme)=lower(p_scheme)
      and upper(pi.identifier)=upper(p_identifier)
    order by pi.is_primary desc,pi.verified_at desc nulls last
    limit 1
  ) x;
$$;


