CREATE OR REPLACE FUNCTION "public"."svc_layer1_run_progress"("p_run_id" "uuid", "p_status" "text", "p_stage" "text", "p_processed" bigint DEFAULT NULL::bigint, "p_created" bigint DEFAULT NULL::bigint, "p_updated" bigint DEFAULT NULL::bigint, "p_unchanged" bigint DEFAULT NULL::bigint, "p_rejected" bigint DEFAULT NULL::bigint, "p_conflicted" bigint DEFAULT NULL::bigint, "p_failed" bigint DEFAULT NULL::bigint, "p_actual_job_id" "uuid" DEFAULT NULL::"uuid", "p_result" "jsonb" DEFAULT NULL::"jsonb", "p_error" "text" DEFAULT NULL::"text", "p_source_hash" "text" DEFAULT NULL::"text", "p_resume_cursor" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$ declare v_source uuid; v_mode text; v_expected bigint; begin if p_status not in ('queued','running','completed','failed','cancelled','blocked','no_change') then raise exception 'invalid status'; end if; update pipeline.layer1_run_queue set status=p_status,current_stage=coalesce(nullif(p_stage,''),current_stage),heartbeat_at=now(),started_at=case when p_status='running' then coalesce(started_at,now()) else started_at end,completed_at=case when p_status in ('completed','failed','cancelled','blocked','no_change') then coalesce(completed_at,now()) else completed_at end,processed_count=coalesce(p_processed,processed_count),created_count=case when p_created is null then created_count else created_count+p_created end,updated_count=case when p_updated is null then updated_count else updated_count+p_updated end,unchanged_count=case when p_unchanged is null then unchanged_count else unchanged_count+p_unchanged end,rejected_count=case when p_rejected is null then rejected_count else rejected_count+p_rejected end,conflicted_count=case when p_conflicted is null then conflicted_count else conflicted_count+p_conflicted end,failed_count=case when p_failed is null then failed_count else failed_count+p_failed end,actual_job_id=coalesce(p_actual_job_id,actual_job_id),result=case when p_result is null then result else result||p_result end,error_text=case when p_error is null then error_text else left(p_error,1800) end,source_hash=coalesce(p_source_hash,source_hash),resume_cursor=coalesce(p_resume_cursor,resume_cursor),updated_at=now() where id=p_run_id returning source_id,mode,expected_count into v_source,v_mode,v_expected; if not found then raise exception 'run not found'; end if; if p_status in ('completed','no_change') and v_mode='apply' then update pipeline.layer1_source_operations set previous_accepted_count=coalesce(v_expected,previous_accepted_count),previous_accepted_hash=coalesce(p_source_hash,previous_accepted_hash),last_source_hash=coalesce(p_source_hash,last_source_hash),next_ingestion_at=case when ingestion_cadence_days is null then null else now()+make_interval(days=>ingestion_cadence_days) end,last_schedule_status=p_status,last_schedule_error=null,updated_at=now() where source_id=v_source; elsif p_status in ('failed','blocked') then update pipeline.layer1_source_operations set last_schedule_status=p_status,last_schedule_error=left(coalesce(p_error,p_status),1000),consecutive_failures=consecutive_failures+1,updated_at=now() where source_id=v_source; end if; return jsonb_build_object('run_id',p_run_id,'status',p_status,'stage',p_stage); end $$;


ALTER FUNCTION "public"."svc_layer1_run_progress"("p_run_id" "uuid", "p_status" "text", "p_stage" "text", "p_processed" bigint, "p_created" bigint, "p_updated" bigint, "p_unchanged" bigint, "p_rejected" bigint, "p_conflicted" bigint, "p_failed" bigint, "p_actual_job_id" "uuid", "p_result" "jsonb", "p_error" "text", "p_source_hash" "text", "p_resume_cursor" bigint) OWNER TO "postgres";


