CREATE OR REPLACE FUNCTION "public"."svc_layer1_source_health"("p_source_id" "uuid", "p_success" boolean, "p_error" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pipeline'
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
  update pipeline.sources
  set last_checked_at=now(),
      last_success_at=case when p_success then now() else last_success_at end,
      last_failure_at=case when not p_success then now() else last_failure_at end,
      last_error=case when p_success then null else left(p_error,4000) end,
      metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb),
      updated_at=now()
  where id=p_source_id;
end $$;


