  insert into pipeline.jobs(job_type,domain,source_id,status,started_at,attempt_count,payload)
  values('regulatory_sync','regulatory',p_source_id,'running',now(),1,coalesce(p_payload,'{}'::jsonb)||jsonb_build_object('country_code',upper(p_country_code)))
  returning id into v_job;
  return v_job;
end $$;


