CREATE OR REPLACE FUNCTION "public"."svc_pilot_automation_authorize"("p_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'extensions'
    AS $$
  select coalesce((
    select k.enabled
      and (k.expires_at is null or k.expires_at > now())
      and k.key_hash = encode(extensions.digest(convert_to(coalesce(p_key,''),'UTF8'),'sha256'),'hex')
    from pipeline.pilot_automation_keys k
    where k.name='coursefinder_pilot_automation'
  ), false);
$$;


