CREATE OR REPLACE FUNCTION "public"."svc_pilot_consume_nonce"("p_function" "text", "p_nonce" "uuid") RETURNS boolean
    LANGUAGE "sql"
    SET "search_path" TO 'pipeline', 'public'
    AS $$
  with consumed as (
    update pipeline.pilot_edge_nonces
       set used_at=now()
     where id=p_nonce
       and function_name=p_function
       and used_at is null
       and expires_at>now()
     returning id
  )
  select exists(select 1 from consumed);
$$;


