CREATE OR REPLACE FUNCTION "public"."svc_provider_asset_access_descriptor"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'public'
    AS $$
  select coalesce((
    select jsonb_build_object(
      'provider_id',a.provider_id,
      'provider_asset_id',a.id,
      'asset_type',a.asset_type,
      'storage_path',a.storage_path,
      'mime_type',a.mime_type,
      'content_hash',a.content_hash,
      'verified_at',a.verified_at,
      'source_url',a.source_url
    )
    from catalogue.provider_assets a
    where a.provider_id=p_provider_id
      and a.is_primary
      and a.status='approved'
      and a.asset_type in('logo','logo_dark','logo_light')
      and a.storage_path is not null
    order by
      case a.asset_type when 'logo' then 0 when 'logo_light' then 1 else 2 end,
      a.verified_at desc nulls last,
      a.id
    limit 1
  ),'{}'::jsonb)
$$;


ALTER FUNCTION "public"."svc_provider_asset_access_descriptor"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_asset_access_descriptors"("p_stable_keys" "text"[]) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'public'
    AS $$
  with requested as (
    select distinct nullif(btrim(x),'') stable_key from unnest(coalesce(p_stable_keys,array[]::text[])) x
  ), matched as (
    select p.stable_key,p.id provider_id,a.id provider_asset_id,a.asset_type,a.storage_path,a.mime_type,a.content_hash,a.verified_at,a.source_url
    from requested r
    join catalogue.providers p on p.stable_key=r.stable_key
    left join lateral (
      select x.* from catalogue.provider_assets x
      where x.provider_id=p.id and x.is_primary and x.status='approved'
        and x.asset_type in('logo','logo_dark','logo_light') and x.storage_path is not null
      order by case x.asset_type when 'logo' then 0 when 'logo_light' then 1 else 2 end,
               x.verified_at desc nulls last,x.id
      limit 1
    ) a on true
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'stable_key',stable_key,'provider_id',provider_id,'provider_asset_id',provider_asset_id,
    'asset_type',asset_type,'storage_path',storage_path,'mime_type',mime_type,'content_hash',content_hash,
    'verified_at',verified_at,'source_url',source_url
  ) order by stable_key),'[]'::jsonb) from matched
$$;


ALTER FUNCTION "public"."svc_provider_asset_access_descriptors"("p_stable_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_asset_manual_upload_apply"("p_provider_id" "uuid", "p_storage_path" "text", "p_mime_type" "text", "p_content_hash" "text", "p_actor_id" "uuid", "p_source_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'security', 'public'
    AS $$
declare v_asset_id uuid;v_source_url text;v_source_class text;
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  if not exists(select 1 from catalogue.providers p where p.id=p_provider_id) then raise exception 'provider_not_found' using errcode='P0002'; end if;
  if nullif(p_storage_path,'') is null or nullif(p_content_hash,'') is null then raise exception 'stored_asset_hash_required' using errcode='23514'; end if;
  if p_mime_type not in ('image/svg+xml','image/png','image/jpeg','image/webp') then raise exception 'unsupported_asset_mime' using errcode='23514'; end if;
  v_source_url:=coalesce(nullif(btrim(p_source_url),''),'manual-upload://provider/'||p_provider_id::text||'/logo/'||p_content_hash);
  v_source_class:=case when nullif(btrim(p_source_url),'') is null then 'manual_admin_upload' else 'manual_admin_url_import' end;
  update catalogue.provider_assets set is_primary=false,status=case when status='approved' then 'superseded' else status end
   where provider_id=p_provider_id and is_primary and asset_type in ('logo','logo_dark','logo_light');
  select id into v_asset_id from catalogue.provider_assets
   where provider_id=p_provider_id and asset_type='logo' and coalesce(content_hash,'')=p_content_hash and source_url=v_source_url
   order by verified_at desc nulls last,id limit 1;
  if v_asset_id is null then
    insert into catalogue.provider_assets(provider_id,asset_type,source_url,evidence_id,storage_path,mime_type,width,height,content_hash,is_primary,status,observed_at,verified_at,metadata)
    values(p_provider_id,'logo',v_source_url,null,p_storage_path,p_mime_type,null,null,p_content_hash,true,'approved',now(),now(),jsonb_build_object('source_class',v_source_class,'uploaded_by',p_actor_id,'uploaded_at',now(),'change_control_ref','CF-CHG-20260904-103','managed_storage',true,'source_url',nullif(btrim(p_source_url),'')))
    returning id into v_asset_id;
  else
    update catalogue.provider_assets set storage_path=p_storage_path,mime_type=p_mime_type,is_primary=true,status='approved',verified_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('source_class',v_source_class,'uploaded_by',p_actor_id,'uploaded_at',now(),'change_control_ref','CF-CHG-20260904-103','managed_storage',true,'source_url',nullif(btrim(p_source_url),''))
    where id=v_asset_id;
  end if;
  return jsonb_build_object('provider_id',p_provider_id,'provider_asset_id',v_asset_id,'storage_path',p_storage_path,'content_hash',p_content_hash,'source_url',v_source_url,'primary',true,'status','approved');
end
$$;


ALTER FUNCTION "public"."svc_provider_asset_manual_upload_apply"("p_provider_id" "uuid", "p_storage_path" "text", "p_mime_type" "text", "p_content_hash" "text", "p_actor_id" "uuid", "p_source_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_import_apply"("p_batch_id" "uuid", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline'
    AS $$
declare
 v_batch pipeline.provider_contact_import_batches%rowtype;r pipeline.provider_contact_import_rows%rowtype;v_contact pipeline.provider_contacts%rowtype;
 v_contact_id uuid;v_version_id uuid;v_old_version uuid;v_identity text;v_current_core text;v_row_core text;
 v_created int:=0;v_updated int:=0;v_restored int:=0;v_unchanged int:=0;v_skipped int:=0;v_failed int:=0;v_error text;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service role required' using errcode='42501'; end if;
 if p_actor is null then raise exception 'actor required' using errcode='22023'; end if;
 select * into v_batch from pipeline.provider_contact_import_batches where id=p_batch_id for update;
 if not found then raise exception 'Provider Contact import not found' using errcode='P0002'; end if;
 if v_batch.status='uploaded' then raise exception 'validate import before apply' using errcode='22023'; end if;
 if v_batch.status='applied' then return jsonb_build_object('ok',true,'batch_id',p_batch_id,'unchanged',true,'summary',v_batch.apply_summary); end if;

 for r in select * from pipeline.provider_contact_import_rows where batch_id=p_batch_id order by row_number loop
  if r.applied_action is not null then continue; end if;
  if r.proposed_action='unchanged' then update pipeline.provider_contact_import_rows set applied_action='unchanged',applied_at=now() where id=r.id;v_unchanged:=v_unchanged+1;continue;
  elsif r.proposed_action in ('duplicate','provider_unmatched','provider_ambiguous','invalid','conflict') then update pipeline.provider_contact_import_rows set applied_action='skipped',applied_at=now() where id=r.id;v_skipped:=v_skipped+1;continue;
  end if;

  begin
   v_contact_id:=r.matched_contact_id;v_identity:=split_part(coalesce(r.logical_key,''),'|',2);
   if r.proposed_action='create' then
    insert into pipeline.provider_contacts(provider_id,record_type,lifecycle_status,identity_key,created_by,updated_by,metadata)
    values(r.mapped_provider_id,coalesce(nullif(r.source_payload->>'contact_record_type',''),'named_staff'),'active',v_identity,p_actor,p_actor,
     jsonb_build_object('origin','import','import_batch_id',p_batch_id,'change_control','CF-CHG-20260902-080'))
    on conflict(provider_id,identity_key) where identity_key is not null do nothing returning id into v_contact_id;
    if v_contact_id is null then select id into v_contact_id from pipeline.provider_contacts where provider_id=r.mapped_provider_id and identity_key=v_identity limit 1;
     if v_contact_id is null then raise exception 'concurrent contact identity conflict'; end if;
    end if;
    v_version_id:=security.provider_contact_append_version(v_contact_id,p_actor,r.normalized_payload,'import','first_party','Provider Contact CSV import create',p_batch_id,r.id,v_batch.evidence_artifact_id,null);
    insert into pipeline.provider_contact_audit_events(contact_id,batch_id,event_type,actor_id,reason,after_version_id,metadata)
    values(v_contact_id,p_batch_id,'import_create',p_actor,'Provider Contact CSV import create',v_version_id,jsonb_build_object('import_row_id',r.id,'change_control','CF-CHG-20260902-080'));
    update pipeline.provider_contact_import_rows set matched_contact_id=v_contact_id,applied_action='create',applied_at=now() where id=r.id;v_created:=v_created+1;

   elsif r.proposed_action='update' then
    select * into v_contact from pipeline.provider_contacts where id=v_contact_id for update;
    if not found then raise exception 'matched contact disappeared'; end if;if v_contact.lifecycle_status='deleted' then raise exception 'contact became deleted after validation'; end if;
    v_old_version:=v_contact.current_version_id;
    v_version_id:=security.provider_contact_append_version(v_contact_id,p_actor,r.normalized_payload,'import','first_party','Provider Contact CSV import update',p_batch_id,r.id,v_batch.evidence_artifact_id,null);
    insert into pipeline.provider_contact_audit_events(contact_id,batch_id,event_type,actor_id,reason,before_version_id,after_version_id,metadata)
    values(v_contact_id,p_batch_id,'import_update',p_actor,'Provider Contact CSV import update',v_old_version,v_version_id,jsonb_build_object('import_row_id',r.id,'change_control','CF-CHG-20260902-080'));
    update pipeline.provider_contact_import_rows set applied_action='update',applied_at=now() where id=r.id;v_updated:=v_updated+1;

   elsif r.proposed_action='restore' then
    select * into v_contact from pipeline.provider_contacts where id=v_contact_id for update;if not found then raise exception 'matched contact disappeared'; end if;
    v_old_version:=v_contact.current_version_id;
    select security.provider_contact_core_hash(jsonb_build_object('full_name',cv.full_name,'team_name',cv.team_name,'job_title',cv.job_title,'functional_area',cv.functional_area,
     'region_scope',cv.region_scope,'countries_or_markets',cv.countries_or_markets,'work_email',cv.work_email,'work_phone',cv.work_phone,'staff_location',cv.staff_location,
     'verification_state',cv.verification_state,'verified_on',case when cv.verified_on is null then null else cv.verified_on::text end,'source_url',cv.source_url))
    into v_current_core from pipeline.provider_contact_versions cv where cv.id=v_contact.current_version_id;
    v_row_core:=security.provider_contact_core_hash(r.normalized_payload);
    update pipeline.provider_contacts set lifecycle_status='active',deleted_at=null,deleted_by=null,delete_reason=null,restored_at=now(),restored_by=p_actor,updated_at=now(),updated_by=p_actor where id=v_contact_id;
    if v_current_core is distinct from v_row_core then
     v_version_id:=security.provider_contact_append_version(v_contact_id,p_actor,r.normalized_payload,'import','first_party','Provider Contact CSV import restore/update',p_batch_id,r.id,v_batch.evidence_artifact_id,null);
    else v_version_id:=v_old_version;end if;
    insert into pipeline.provider_contact_audit_events(contact_id,batch_id,event_type,actor_id,reason,before_version_id,after_version_id,metadata)
    values(v_contact_id,p_batch_id,'restore',p_actor,'Provider Contact CSV import restore',v_old_version,v_version_id,jsonb_build_object('import_row_id',r.id,'change_control','CF-CHG-20260902-080'));
    update pipeline.provider_contact_import_rows set applied_action='restore',applied_at=now() where id=r.id;v_restored:=v_restored+1;
   else raise exception 'unsupported proposed action %',r.proposed_action;
   end if;
  exception when others then
   get stacked diagnostics v_error=message_text;
   update pipeline.provider_contact_import_rows set applied_action='failed',applied_at=now(),conflict_detail=coalesce(conflict_detail,'{}'::jsonb)||jsonb_build_object('apply_error',v_error) where id=r.id;
   v_failed:=v_failed+1;
  end;
 end loop;

 update pipeline.provider_contact_import_batches set status=case when v_failed>0 then 'partial' else 'applied' end,applied_at=now(),
 apply_summary=jsonb_build_object('created',v_created,'updated',v_updated,'restored',v_restored,'unchanged',v_unchanged,'skipped',v_skipped,'failed',v_failed,'applied_by',p_actor,'applied_at',now())
 where id=p_batch_id;
 insert into pipeline.provider_contact_audit_events(batch_id,event_type,actor_id,reason,metadata)
 values(p_batch_id,'import_apply',p_actor,'Provider Contact CSV batch apply',jsonb_build_object('created',v_created,'updated',v_updated,'restored',v_restored,'unchanged',v_unchanged,'skipped',v_skipped,'failed',v_failed,'change_control','CF-CHG-20260902-080'));
 return jsonb_build_object('ok',v_failed=0,'batch_id',p_batch_id,'summary',jsonb_build_object('created',v_created,'updated',v_updated,'restored',v_restored,'unchanged',v_unchanged,'skipped',v_skipped,'failed',v_failed));
end $$;


ALTER FUNCTION "public"."svc_provider_contact_import_apply"("p_batch_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_import_finalize_review_state"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare
  v_pending int:=0;
  v_resolved int:=0;
  v_status text;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;

  select count(*) filter(where l.status='pending'),
         count(*) filter(where l.status<>'pending')
  into v_pending,v_resolved
  from pipeline.provider_contact_import_rows r
  join pipeline.layer4_review_items l on l.id=r.layer4_review_item_id
  where r.batch_id=p_batch_id;

  update pipeline.provider_contact_import_rows r
  set applied_action='parked_layer4',applied_at=coalesce(applied_at,now())
  from pipeline.layer4_review_items l
  where r.batch_id=p_batch_id
    and l.id=r.layer4_review_item_id
    and l.status='pending'
    and coalesce(r.applied_action,'') in ('','skipped');

  update pipeline.provider_contact_import_batches
  set status=case
        when status='partial' then 'partial'
        when v_pending>0 then 'applied_with_review_pending'
        else 'applied'
      end,
      apply_summary=coalesce(apply_summary,'{}'::jsonb)||
        jsonb_build_object('layer4_review_pending',v_pending,'layer4_resolved',v_resolved)
  where id=p_batch_id
  returning status into v_status;

  return jsonb_build_object('ok',true,'batch_id',p_batch_id,'status',v_status,'layer4_review_pending',v_pending,'layer4_resolved',v_resolved);
end $$;


ALTER FUNCTION "public"."svc_provider_contact_import_finalize_review_state"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_import_park_layer4"("p_batch_id" "uuid", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'catalogue'
    AS $$
declare
  v_batch pipeline.provider_contact_import_batches%rowtype;
  r pipeline.provider_contact_import_rows%rowtype;
  v_prior pipeline.provider_contact_import_rows%rowtype;
  v_review_id uuid;
  v_before jsonb;
  v_layer2 jsonb;
  v_candidates jsonb;
  v_reason text;
  v_count int:=0;
  v_actions jsonb;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;
  if p_actor is null then raise exception 'actor required' using errcode='22023'; end if;

  select * into v_batch from pipeline.provider_contact_import_batches where id=p_batch_id for update;
  if not found then raise exception 'Provider Contact import not found' using errcode='P0002'; end if;
  if v_batch.status not in ('validated','uploaded') then
    return jsonb_build_object('ok',true,'batch_id',p_batch_id,'unchanged',true,'status',v_batch.status);
  end if;

  -- A repeated logical key is auto-skip only when it is the same source row semantics.
  -- Legacy/merged labels or differing payloads are judgement calls and move to L4.
  for r in
    select *
    from pipeline.provider_contact_import_rows
    where batch_id=p_batch_id
      and proposed_action in ('duplicate','provider_ambiguous','conflict')
    order by row_number
  loop
    if r.layer4_review_item_id is not null then continue; end if;

    v_before:=null;
    v_candidates:='[]'::jsonb;
    v_reason:=null;

    if r.proposed_action='duplicate' then
      select * into v_prior
      from pipeline.provider_contact_import_rows
      where batch_id=p_batch_id
        and logical_key=r.logical_key
        and row_number<r.row_number
      order by row_number
      limit 1;

      if not found then continue; end if;

      -- Exact repeat remains deterministic skip. Different legacy/source label or payload parks for human resolution.
      if coalesce(v_prior.source_institution_name,'')=coalesce(r.source_institution_name,'')
         and v_prior.normalized_payload=r.normalized_payload then
        continue;
      end if;

      v_before:=jsonb_build_object(
        'prior_import_row_id',v_prior.id,
        'prior_row_number',v_prior.row_number,
        'source_institution_name',v_prior.source_institution_name,
        'current_institution_name',v_prior.current_institution_name,
        'normalized_payload',v_prior.normalized_payload
      );
      v_reason:='duplicate_candidate_requires_human_resolution';

    elsif r.proposed_action='conflict' then
      select jsonb_build_object(
        'contact_id',c.id,'provider_id',c.provider_id,'record_type',c.record_type,'lifecycle_status',c.lifecycle_status,
        'version_id',v.id,'version_no',v.version_no,'full_name',v.full_name,'team_name',v.team_name,'job_title',v.job_title,
        'functional_area',v.functional_area,'region_scope',v.region_scope,'countries_or_markets',v.countries_or_markets,
        'work_email',v.work_email,'work_phone',v.work_phone,'staff_location',v.staff_location,
        'verification_state',v.verification_state,'verified_on',v.verified_on,'source_class',v.source_class,
        'source_authority',v.source_authority,'source_url',v.source_url,'source_page_title',v.source_page_title
      ) into v_before
      from pipeline.provider_contacts c
      left join pipeline.provider_contact_versions v on v.id=c.current_version_id
      where c.id=r.matched_contact_id;
      v_reason:='manual_current_version_conflicts_with_import';

    elsif r.proposed_action='provider_ambiguous' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'provider_id',p.id,'stable_key',p.stable_key,'provider_name',p.canonical_name
      ) order by p.canonical_name,p.stable_key),'[]'::jsonb)
      into v_candidates
      from catalogue.providers p
      where p.id in (
        select value::uuid
        from jsonb_array_elements_text(
          coalesce(r.conflict_detail#>'{provider_mapping,candidate_provider_ids}','[]'::jsonb)
        )
      );
      v_before:=jsonb_build_object('candidate_providers',v_candidates);
      v_reason:='provider_mapping_ambiguous';
    end if;

    v_layer2:=jsonb_strip_nulls(jsonb_build_object(
      'domain','provider_contact_import',
      'import_batch_id',p_batch_id,
      'import_row_id',r.id,
      'row_number',r.row_number,
      'classification',r.proposed_action,
      'logical_key',r.logical_key,
      'source_institution_name',r.source_institution_name,
      'current_institution_name',r.current_institution_name,
      'mapped_provider_id',r.mapped_provider_id,
      'matched_contact_id',r.matched_contact_id,
      'candidate_providers',v_candidates,
      'validation_errors',r.validation_errors,
      'conflict_detail',r.conflict_detail
    ));

    insert into pipeline.layer4_review_items(
      entity_type,entity_id,field_code,evidence_id,before_value,proposed_value,
      layer2_state,layer3_state,status,escalation_reason,change_control_ref
    ) values (
      'provider_contact_import_row',r.id,'provider_contact_reconciliation',v_batch.evidence_artifact_id,
      v_before,r.normalized_payload,v_layer2,
      jsonb_build_object('source','provider-contact-csv-v1','human_review_reason',v_reason),
      'pending',v_reason,'CF-CHG-20260902-080'
    )
    returning id into v_review_id;

    update pipeline.provider_contact_import_rows
    set layer4_review_item_id=v_review_id,
        conflict_detail=coalesce(conflict_detail,'{}'::jsonb)||
          jsonb_build_object('layer4_review_item_id',v_review_id,'layer4_reason',v_reason)
    where id=r.id;

    v_count:=v_count+1;
  end loop;

  select jsonb_object_agg(proposed_action,n) into v_actions
  from (
    select proposed_action,count(*) n
    from pipeline.provider_contact_import_rows
    where batch_id=p_batch_id
    group by proposed_action
  ) s;

  update pipeline.provider_contact_import_batches
  set status='validated',
      dry_run_summary=jsonb_build_object(
        'rows',(select count(*) from pipeline.provider_contact_import_rows where batch_id=p_batch_id),
        'actions',coalesce(v_actions,'{}'::jsonb),
        'layer4_review_pending',(select count(*) from pipeline.provider_contact_import_rows rr
          join pipeline.layer4_review_items l on l.id=rr.layer4_review_item_id
          where rr.batch_id=p_batch_id and l.status='pending'),
        'parser_version',parser_version,
        'validated_by',p_actor,
        'validated_at',coalesce(validated_at,now())
      )
  where id=p_batch_id;

  return jsonb_build_object(
    'ok',true,'batch_id',p_batch_id,'layer4_created',v_count,
    'layer4_review_pending',(select count(*) from pipeline.provider_contact_import_rows rr
      join pipeline.layer4_review_items l on l.id=rr.layer4_review_item_id
      where rr.batch_id=p_batch_id and l.status='pending'),
    'actions',coalesce(v_actions,'{}'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."svc_provider_contact_import_park_layer4"("p_batch_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_import_register"("p_country_code" "text", "p_original_filename" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_path" "text", "p_uploaded_by" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $_$
declare v_existing uuid;v_evidence uuid;v_batch uuid;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service role required' using errcode='42501'; end if;
 if upper(coalesce(p_country_code,'')) !~ '^[A-Z]{2}$' then raise exception 'valid country code required' using errcode='22023'; end if;
 if coalesce(btrim(p_original_filename),'')='' then raise exception 'original filename required' using errcode='22023'; end if;
 if p_byte_size is null or p_byte_size<=0 then raise exception 'positive byte size required' using errcode='22023'; end if;
 if coalesce(btrim(p_content_hash),'')='' then raise exception 'content hash required' using errcode='22023'; end if;
 if coalesce(btrim(p_storage_path),'')='' then raise exception 'storage path required' using errcode='22023'; end if;
 if p_uploaded_by is null then raise exception 'uploader required' using errcode='22023'; end if;

 select id into v_existing from pipeline.provider_contact_import_batches where content_hash=p_content_hash limit 1;
 if v_existing is not null then return jsonb_build_object('duplicate',true,'batch_id',v_existing); end if;

 insert into pipeline.evidence_artifacts(evidence_type,storage_path,content_hash,mime_type,captured_at,metadata,retention_class,review_state,capture_version,evidence_group_key)
 values('provider_contact_import_file',p_storage_path,p_content_hash,p_mime_type,now(),
  jsonb_build_object('country_code',upper(p_country_code),'original_filename',p_original_filename,'byte_size',p_byte_size,'uploaded_by',p_uploaded_by,
   'manual_upload',true,'parser_contract','provider-contact-csv-v1','change_control','CF-CHG-20260902-080'),
  'source_evidence','pending_review',1,'provider_contacts:'||upper(p_country_code))
 returning id into v_evidence;

 insert into pipeline.provider_contact_import_batches(country_code,evidence_artifact_id,original_filename,mime_type,byte_size,content_hash,storage_path,uploaded_by,metadata)
 values(upper(p_country_code),v_evidence,p_original_filename,p_mime_type,p_byte_size,p_content_hash,p_storage_path,p_uploaded_by,jsonb_build_object('change_control','CF-CHG-20260902-080'))
 returning id into v_batch;

 return jsonb_build_object('duplicate',false,'batch_id',v_batch,'evidence_id',v_evidence,'status','uploaded');
end $_$;


ALTER FUNCTION "public"."svc_provider_contact_import_register"("p_country_code" "text", "p_original_filename" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_path" "text", "p_uploaded_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_import_validate"("p_batch_id" "uuid", "p_rows" "jsonb", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'catalogue'
    AS $_$
declare
 v_batch pipeline.provider_contact_import_batches%rowtype;v_row jsonb;v_ord bigint;v_map jsonb;v_provider uuid;v_mapping_state text;
 v_record_type text;v_full_name text;v_job_title text;v_function text;v_region text;v_markets text;v_email text;v_phone text;v_location text;
 v_verify text;v_verified text;v_source_url text;v_source_title text;v_notes text;v_identity text;v_logical text;v_errors jsonb;v_action text;
 v_matched uuid;v_lifecycle text;v_current_source text;v_current_core text;v_row_core text;v_norm_payload jsonb;v_counts jsonb;v_domain text;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service role required' using errcode='42501'; end if;
 if p_actor is null then raise exception 'actor required' using errcode='22023'; end if;
 if jsonb_typeof(p_rows)<>'array' then raise exception 'rows array required' using errcode='22023'; end if;
 select * into v_batch from pipeline.provider_contact_import_batches where id=p_batch_id for update;
 if not found then raise exception 'Provider Contact import not found' using errcode='P0002'; end if;
 if v_batch.status in ('applied','partial') then raise exception 'applied import cannot be revalidated' using errcode='22023'; end if;

 delete from pipeline.provider_contact_import_rows where batch_id=p_batch_id;
 for v_row,v_ord in select value,ordinality from jsonb_array_elements(p_rows) with ordinality loop
  v_errors:='[]'::jsonb;v_provider:=null;v_matched:=null;v_lifecycle:=null;v_current_source:=null;v_current_core:=null;
  v_record_type:=lower(btrim(coalesce(v_row->>'contact_record_type','')));
  v_full_name:=nullif(btrim(coalesce(v_row->>'staff_name','')),'');v_job_title:=nullif(btrim(coalesce(v_row->>'job_title','')),'');
  v_function:=nullif(btrim(coalesce(v_row->>'functional_area','')),'');v_region:=nullif(btrim(coalesce(v_row->>'region_scope','')),'');
  v_markets:=nullif(btrim(coalesce(v_row->>'countries_or_markets','')),'');v_email:=nullif(lower(btrim(coalesce(v_row->>'email',''))),'');
  v_phone:=nullif(btrim(coalesce(v_row->>'phone','')),'');v_location:=nullif(btrim(coalesce(v_row->>'staff_location','')),'');
  v_verify:=nullif(lower(btrim(coalesce(v_row->>'verification_status',''))),'');v_verified:=nullif(btrim(coalesce(v_row->>'verified_on','')),'');
  v_source_url:=nullif(btrim(coalesce(v_row->>'official_source_url','')),'');v_source_title:=nullif(btrim(coalesce(v_row->>'source_page_title','')),'');
  v_notes:=nullif(btrim(coalesce(v_row->>'notes','')),'');

  if v_record_type not in ('named_staff','team_contact') then v_errors:=v_errors||jsonb_build_array('invalid_contact_record_type'); end if;
  if v_record_type='named_staff' and v_full_name is null then v_errors:=v_errors||jsonb_build_array('named_staff_requires_staff_name'); end if;
  if coalesce(v_email,v_phone,v_job_title,v_function,v_region,v_source_url) is null then v_errors:=v_errors||jsonb_build_array('meaningful_assignment_contact_or_source_required'); end if;
  if v_email is not null then
   if v_email !~* '^[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}$' then v_errors:=v_errors||jsonb_build_array('invalid_professional_email');
   else v_domain:=split_part(v_email,'@',2);
    if v_domain in ('gmail.com','googlemail.com','yahoo.com','yahoo.com.au','hotmail.com','outlook.com','live.com','icloud.com','proton.me','protonmail.com') then
     v_errors:=v_errors||jsonb_build_array('personal_free_mail_not_permitted');
    end if;
   end if;
  end if;
  if v_source_url is not null and v_source_url !~* '^https?://' then v_errors:=v_errors||jsonb_build_array('invalid_official_source_url'); end if;
  if v_verified is not null and v_verified !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then v_errors:=v_errors||jsonb_build_array('verified_on_must_be_iso_date'); end if;

  v_map:=security.provider_contact_provider_map(v_batch.country_code,v_row->>'current_institution_name');
  v_mapping_state:=coalesce(v_map->>'state','unmatched');
  if v_mapping_state='mapped' then v_provider:=(v_map->>'provider_id')::uuid; end if;
  v_identity:=case when v_mapping_state='mapped' then security.provider_contact_identity_key(v_record_type,v_full_name,v_job_title,v_region,v_email,v_source_url) else null end;
  if v_mapping_state='mapped' and v_identity is null then v_errors:=v_errors||jsonb_build_array('insufficient_contact_identity'); end if;

  v_norm_payload:=jsonb_strip_nulls(jsonb_build_object(
   'full_name',v_full_name,'team_name',case when v_record_type='team_contact' then coalesce(v_full_name,v_function,v_job_title) else null end,
   'job_title',v_job_title,'functional_area',v_function,'region_scope',v_region,'countries_or_markets',v_markets,'work_email',v_email,'work_phone',v_phone,
   'staff_location',v_location,'verification_state',v_verify,'verified_on',v_verified,'source_class','import','source_authority','first_party',
   'source_url',v_source_url,'source_page_title',v_source_title,'source_notes',v_notes));
  v_row_core:=security.provider_contact_core_hash(v_norm_payload);
  v_logical:=case when v_provider is null or v_identity is null then null else v_provider::text||'|'||v_identity end;

  if jsonb_array_length(v_errors)>0 then v_action:='invalid';
  elsif v_mapping_state='unmatched' then v_action:='provider_unmatched';
  elsif v_mapping_state='ambiguous' then v_action:='provider_ambiguous';
  elsif exists(select 1 from pipeline.provider_contact_import_rows rr where rr.batch_id=p_batch_id and rr.logical_key=v_logical) then v_action:='duplicate';
  else
   select c.id,c.lifecycle_status,cv.source_class,security.provider_contact_core_hash(jsonb_build_object(
    'full_name',cv.full_name,'team_name',cv.team_name,'job_title',cv.job_title,'functional_area',cv.functional_area,'region_scope',cv.region_scope,
    'countries_or_markets',cv.countries_or_markets,'work_email',cv.work_email,'work_phone',cv.work_phone,'staff_location',cv.staff_location,
    'verification_state',cv.verification_state,'verified_on',case when cv.verified_on is null then null else cv.verified_on::text end,'source_url',cv.source_url))
   into v_matched,v_lifecycle,v_current_source,v_current_core
   from pipeline.provider_contacts c left join pipeline.provider_contact_versions cv on cv.id=c.current_version_id
   where c.provider_id=v_provider and c.identity_key=v_identity limit 1;

   if v_matched is null then v_action:='create';
   elsif v_current_core=v_row_core then v_action:=case when v_lifecycle='deleted' then 'restore' else 'unchanged' end;
   elsif v_current_source='manual' then v_action:='conflict';
   elsif v_lifecycle='deleted' then v_action:='restore';
   else v_action:='update';
   end if;
  end if;

  insert into pipeline.provider_contact_import_rows(batch_id,row_number,row_hash,logical_key,source_payload,normalized_payload,source_institution_name,current_institution_name,
   mapped_provider_id,mapping_state,matched_contact_id,proposed_action,validation_errors,conflict_detail)
  values(p_batch_id,v_ord::int,md5(v_row::text),v_logical,v_row,v_norm_payload,nullif(btrim(v_row->>'gug_2026_university_name'),''),
   nullif(btrim(v_row->>'current_institution_name'),''),v_provider,v_mapping_state,v_matched,v_action,v_errors,
   case when v_mapping_state='ambiguous' then jsonb_build_object('provider_mapping',v_map)
    when v_action='conflict' then jsonb_build_object('reason','manual_current_version_differs','current_contact_id',v_matched)
    when v_action='duplicate' then jsonb_build_object('reason','duplicate_logical_contact_within_batch') else '{}'::jsonb end);
 end loop;

 select jsonb_object_agg(proposed_action,n) into v_counts from (
  select proposed_action,count(*) n from pipeline.provider_contact_import_rows where batch_id=p_batch_id group by proposed_action)s;
 update pipeline.provider_contact_import_batches set status='validated',validated_at=now(),dry_run_summary=jsonb_build_object(
  'rows',jsonb_array_length(p_rows),'actions',coalesce(v_counts,'{}'::jsonb),'parser_version',parser_version,'validated_by',p_actor,'validated_at',now())
 where id=p_batch_id;
 return jsonb_build_object('ok',true,'batch_id',p_batch_id,'rows',jsonb_array_length(p_rows),'actions',coalesce(v_counts,'{}'::jsonb));
end $_$;


ALTER FUNCTION "public"."svc_provider_contact_import_validate"("p_batch_id" "uuid", "p_rows" "jsonb", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_document_check_record"("p_doc_key" "text", "p_url" "text", "p_sha256" "text", "p_http_status" integer, "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_prev text; v_applied text; v_changed boolean;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  select sha256 into v_prev from pipeline.provider_document_checks where doc_key=p_doc_key and sha256 is not null order by checked_at desc limit 1;
  select e.content_hash into v_applied from pipeline.evidence_artifacts e where e.source_url=p_url order by e.captured_at desc nulls last limit 1;
  v_changed:=p_sha256 is not null and ((v_prev is not null and v_prev<>p_sha256) or (v_prev is null and v_applied is not null and v_applied<>p_sha256));
  insert into pipeline.provider_document_checks(doc_key,url,sha256,http_status,changed,applied_sha256,note)
  values (p_doc_key,p_url,p_sha256,p_http_status,v_changed,v_applied,left(p_note,300));
  return jsonb_build_object('changed',v_changed,'previous',v_prev,'applied',v_applied);
end $$;


ALTER FUNCTION "public"."svc_provider_document_check_record"("p_doc_key" "text", "p_url" "text", "p_sha256" "text", "p_http_status" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_docs"("p_ids" "uuid"[], "p_kind" "text", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return coalesce((select jsonb_agg(x) from (
    select jsonb_build_object('id', f.id, 'provider_id', f.provider_id, 'kind', f.kind, 'url', f.url, 'rank', f.rank,
             'provider', p.canonical_name, 'country', k.iso_alpha2, 'storage_path', e.storage_path, 'sha256', f.content_hash) x
      from pipeline.provider_fact_sources f
      join pipeline.evidence_artifacts e on e.id = f.evidence_id
      join catalogue.providers p on p.id = f.provider_id
      left join ref.countries k on k.id = p.country_id
     where f.status in ('read', 'parsed', 'no_values') and e.storage_path is not null
       and (p_ids is null or cardinality(p_ids) = 0 or f.id = any(p_ids))
       and (p_kind is null or f.kind = p_kind)
     order by f.read_at desc nulls last
     limit greatest(1, least(coalesce(p_limit, 20), 400))) s), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."svc_provider_facts_docs"("p_ids" "uuid"[], "p_kind" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_read_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select f.id from pipeline.provider_fact_sources f
     where ((f.kind = 'fee_schedule' and security.tuition_chase_enabled(f.provider_id))
            or f.kind in ('english_policy', 'intake_calendar'))
       and (f.status = 'found' or (f.status = 'reading' and f.updated_at < now() - interval '20 minutes')) and f.attempts < 3
     order by (f.linked_from is null), f.rank,
              (select count(*) from catalogue.courses c where c.provider_id = f.provider_id and c.lifecycle_status = 'active') desc, f.created_at limit greatest(1, least(coalesce(p_limit, 10), 30))
     for update skip locked),
  upd as (update pipeline.provider_fact_sources f set status = 'reading', attempts = f.attempts + 1, updated_at = now() from pick where f.id = pick.id
          returning f.id, f.provider_id, f.kind, f.url)
  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'provider_id', u.provider_id, 'kind', u.kind, 'url', u.url,
           'country', (select k.iso_alpha2 from catalogue.providers p join ref.countries k on k.id = p.country_id where p.id = u.provider_id),
           'currency', (select a.currency_code from catalogue.providers p join pipeline.coverage_admission_countries a on a.country_id = p.country_id where p.id = u.provider_id))), '[]'::jsonb)
    into v from upd u;
  return v;
end $$;


ALTER FUNCTION "public"."svc_provider_facts_read_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_read_record"("p_id" "uuid", "p_status" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_mime" "text", "p_rows" "jsonb", "p_summary" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare f pipeline.provider_fact_sources%rowtype; v_src uuid; v_ev uuid; v_cur text; v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_id for update;
  if f.id is null then raise exception 'source not found'; end if;
  if p_status not in ('read','failed') then raise exception 'status must be read or failed'; end if;
  if p_status = 'failed' then
    update pipeline.provider_fact_sources set status = case when attempts >= 3 then 'failed' else 'found' end, http_status = p_http,
           parse_summary = p_summary, updated_at = now() where id = p_id;
    return jsonb_build_object('status', 'failed');
  end if;
  if p_storage_path is not null and p_sha256 ~ '^[0-9a-f]{64}$' then
    v_src := security.coverage_sweep_source(f.provider_id);
    select id into v_ev from pipeline.evidence_artifacts where source_id = v_src and content_hash = p_sha256 and source_url = f.url limit 1;
    if v_ev is null then
      v_ev := public.svc_coursefacts_register_evidence(v_src, f.url, p_storage_path, p_sha256, coalesce(p_mime, 'text/markdown'),
                jsonb_build_object('layer', 2, 'kind', 'provider_' || f.kind, 'worker', 'coverage-sweep', 'provider_fact_source_id', f.id));
    end if;
  end if;
  select a.currency_code into v_cur from catalogue.providers p join pipeline.coverage_admission_countries a on a.country_id = p.country_id where p.id = f.provider_id;
  -- a re-read replaces the rows parsed before (kept, marked not current, for the record)
  update pipeline.provider_fee_rows set current = false where source_id = p_id and current;
  if f.kind = 'fee_schedule' and v_cur is not null then
    insert into pipeline.provider_fee_rows(source_id, provider_id, course_code, amount, currency_code, basis, fee_year, column_label, row_text)
    select p_id, f.provider_id, upper(btrim(r->>'course_code')), (r->>'amount')::numeric, v_cur, nullif(r->>'basis', ''), nullif(r->>'fee_year', '')::int,
           left(r->>'column_label', 120), left(r->>'row_text', 500)
      from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) r
     where coalesce(r->>'course_code', '') ~ '^[0-9A-Za-z]{4,12}$' and coalesce(r->>'amount', '') ~ '^[0-9]+(\.[0-9]+)?$'
       and (r->>'amount')::numeric between 1000 and 200000
       and coalesce(nullif(r->>'basis', ''), 'annual') in ('annual','per_semester','per_trimester','total_indicative')
    on conflict on constraint provider_fee_rows_key do update set current = true, fee_year = excluded.fee_year, column_label = excluded.column_label, row_text = excluded.row_text;
    get diagnostics v_n = row_count;
  end if;
  update pipeline.provider_fact_sources set status = case when f.kind <> 'fee_schedule' then 'read' when v_n > 0 then 'parsed' else 'no_values' end,
         http_status = p_http, evidence_id = coalesce(v_ev, evidence_id), content_hash = coalesce(p_sha256, content_hash), read_at = now(),
         parse_summary = coalesce(p_summary, '{}'::jsonb) || jsonb_build_object('fee_rows', v_n), updated_at = now()
   where id = p_id;
  return jsonb_build_object('status', 'read', 'fee_rows', v_n, 'evidence_id', v_ev);
end $_$;


ALTER FUNCTION "public"."svc_provider_facts_read_record"("p_id" "uuid", "p_status" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_mime" "text", "p_rows" "jsonb", "p_summary" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_read_record_v2"("p_id" "uuid", "p_status" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_mime" "text", "p_rows" "jsonb", "p_summary" "jsonb", "p_links" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare f pipeline.provider_fact_sources%rowtype; v_dom text; v jsonb; v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  v := public.svc_provider_facts_read_record(p_id, p_status, p_http, p_storage_path, p_sha256, p_mime, p_rows, p_summary);
  select * into f from pipeline.provider_fact_sources where id = p_id;
  if p_status = 'read' and f.kind = 'fee_schedule' and f.linked_from is null and jsonb_typeof(p_links) = 'array' then
    select r.search_domain into v_dom from pipeline.course_link_recipes r where r.provider_id = f.provider_id;
    insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, linked_from)
    select f.provider_id, 'fee_schedule', left(x.url, 2000), 'Linked from ' || left(f.url, 200), x.rk, f.id
      from (select e->>'url' url, row_number() over (order by coalesce(nullif(e->>'year', '')::int, 0) desc) rk
              from jsonb_array_elements(p_links) e
             where (e->>'url') ~* ('^https?://([a-z0-9-]+\.)*' || regexp_replace(coalesce(v_dom, '#'), '([.-])', '\\\1', 'g') || '(/|$)')) x
     where x.rk <= 4
    on conflict (provider_id, kind, url) do nothing;
    get diagnostics v_n = row_count;
  end if;
  return v || jsonb_build_object('linked', v_n);
end $_$;


ALTER FUNCTION "public"."svc_provider_facts_read_record_v2"("p_id" "uuid", "p_status" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_mime" "text", "p_rows" "jsonb", "p_summary" "jsonb", "p_links" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_search_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select s.provider_id, s.kind, r.search_domain
      from pipeline.provider_fact_search s join pipeline.course_link_recipes r on r.provider_id = s.provider_id and r.active
     where (s.state = 'queued' or (s.state = 'sent' and s.sent_at < now() - interval '20 minutes' and s.attempts < 3))
       and (s.kind <> 'fee_schedule' or security.tuition_chase_enabled(s.provider_id))
     order by (s.kind <> 'fee_schedule'), s.queued_at, s.provider_id limit greatest(1, least(coalesce(p_limit, 20), 60))
     for update of s skip locked),
  upd as (
    update pipeline.provider_fact_search s set state = 'sent', sent_at = now(), attempts = s.attempts + 1,
           query = case p.kind when 'fee_schedule' then 'international student tuition fees site:' || p.search_domain
                               when 'english_policy' then 'English language requirements international students site:' || p.search_domain
                               else 'academic calendar key dates intakes site:' || p.search_domain end
      from pick p where s.provider_id = p.provider_id and s.kind = p.kind
    returning s.provider_id, s.kind, s.query)
  select coalesce(jsonb_agg(jsonb_build_object('provider_id', provider_id, 'kind', kind, 'query', query)), '[]'::jsonb) into v from upd;
  return v;
end $$;


ALTER FUNCTION "public"."svc_provider_facts_search_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_search_record"("p_provider_id" "uuid", "p_kind" "text", "p_http" integer, "p_results" "jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_dom text; v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select r.search_domain into v_dom from pipeline.course_link_recipes r where r.provider_id = p_provider_id;
  if p_http <> 200 then
    update pipeline.provider_fact_search set state = case when attempts >= 3 then 'error' else 'queued' end where provider_id = p_provider_id and kind = p_kind;
    return 0;
  end if;
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank)
  select p_provider_id, p_kind, x.url, left(x.title, 300), x.rk
    from (select e->>'url' url, e->>'title' title, row_number() over () rk
            from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) e
           where (e->>'url') ~* ('^https?://([a-z0-9-]+\.)*' || regexp_replace(coalesce(v_dom, '#'), '([.-])', '\\\1', 'g') || '(/|$)')) x
   where x.rk <= 3
  on conflict (provider_id, kind, url) do nothing;
  get diagnostics v_n = row_count;
  update pipeline.provider_fact_search set state = case when v_n > 0 or exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = p_provider_id and f.kind = p_kind) then 'done' else 'none' end,
         done_at = now() where provider_id = p_provider_id and kind = p_kind;
  return v_n;
end $_$;


ALTER FUNCTION "public"."svc_provider_facts_search_record"("p_provider_id" "uuid", "p_kind" "text", "p_http" integer, "p_results" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_policy_record"("p_source_id" "uuid", "p_parsed" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f pipeline.provider_fact_sources%rowtype; v_id uuid; v_status text; v_parser text := coalesce(p_parsed->>'parser', 'unknown');
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_source_id;
  if f.id is null or f.kind not in ('english_policy', 'intake_calendar') then raise exception 'not an English policy or calendar document'; end if;
  if jsonb_typeof(p_parsed) <> 'object' then raise exception 'parsed result must be an object'; end if;
  v_status := case
    when f.kind = 'english_policy' and (coalesce(p_parsed->'defaults', '{}'::jsonb) <> '{}'::jsonb
           or exists (select 1 from jsonb_array_elements(coalesce(p_parsed->'exceptions', '[]'::jsonb)) e
                       where jsonb_typeof(e->'reqs') = 'array' and jsonb_array_length(e->'reqs') > 0)) then 'proposed'
    when f.kind = 'intake_calendar' and jsonb_array_length(coalesce(p_parsed->'periods', '[]'::jsonb)) > 0 then 'proposed'
    else 'no_values' end;
  insert into pipeline.provider_policy_proposals(provider_id, fact_source_id, kind, parser, content_hash, evidence_id, url, style, proposal, status)
  values (f.provider_id, f.id, f.kind, v_parser, f.content_hash, f.evidence_id, f.url, left(p_parsed->>'style', 40), p_parsed, v_status)
  on conflict on constraint provider_policy_proposals_key do update
     set proposal = excluded.proposal, style = excluded.style, evidence_id = excluded.evidence_id,
         status = case when pipeline.provider_policy_proposals.status in ('proposed', 'no_values') then excluded.status else pipeline.provider_policy_proposals.status end,
         updated_at = now()
  returning id, status into v_id, v_status;
  update pipeline.provider_policy_proposals set status = 'superseded', updated_at = now()
   where fact_source_id = f.id and id <> v_id and status in ('proposed', 'no_values') and parser <> 'written out from the central page';
  return jsonb_build_object('id', v_id, 'status', v_status);
end $$;


ALTER FUNCTION "public"."svc_provider_policy_record"("p_source_id" "uuid", "p_parsed" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_qilt_apply_observations"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'public'
    AS $$ select pipeline.svc_qilt_apply_observations(p_rows); $$;


ALTER FUNCTION "public"."svc_qilt_apply_observations"("p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_qilt_context"("p_survey_code" "text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'catalogue', 'ref', 'public', 'extensions'
    AS $$
with survey as (
 select id,code from ref.outcome_surveys where code=p_survey_code and source_family='QILT' and status='active'
), metrics as (
 select coalesce(jsonb_object_agg(m.code,m.id),'{}'::jsonb) j
 from ref.outcome_metrics m join survey s on s.id=m.survey_id where m.status='active'
), au as (
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'stable_key',p.stable_key,'canonical_name',p.canonical_name,'display_name',p.display_name) order by p.stable_key),'[]'::jsonb) j
 from catalogue.providers p join ref.countries c on c.id=p.country_id where c.iso_alpha2='AU'
)
select jsonb_build_object('survey_id',(select id from survey),'metric_ids',(select j from metrics),'providers',(select j from au));
$$;


ALTER FUNCTION "public"."svc_qilt_context"("p_survey_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_qilt_prepare_source"("p_survey_code" "text", "p_label" "text", "p_url" "text", "p_collection_version" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'ref', 'public', 'extensions'
    AS $$
declare v_id uuid; v_country uuid;
begin
 if not exists(select 1 from ref.outcome_surveys where code=p_survey_code and source_family='QILT') then raise exception 'invalid QILT survey'; end if;
 select id into v_country from ref.countries where iso_alpha2='AU';
 select id into v_id from pipeline.sources where label=p_label and url=p_url limit 1;
 if v_id is null then
  insert into pipeline.sources(source_type,country_id,url,label,trust_rank,status,metadata)
  values('structured_outcomes',v_country,p_url,p_label,95,'active',jsonb_build_object('layer','2A','publisher','QILT','survey_code',p_survey_code,'collection_version',p_collection_version,'identity_authority',false))
  returning id into v_id;
 else
  update pipeline.sources set source_type='structured_outcomes',country_id=v_country,trust_rank=95,status='active',
   metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('layer','2A','publisher','QILT','survey_code',p_survey_code,'collection_version',p_collection_version,'identity_authority',false),updated_at=now()
  where id=v_id;
 end if;
 return v_id;
end $$;


ALTER FUNCTION "public"."svc_qilt_prepare_source"("p_survey_code" "text", "p_label" "text", "p_url" "text", "p_collection_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_qilt_register_evidence"("p_source_id" "uuid", "p_source_url" "text", "p_storage_path" "text", "p_content_hash" "text", "p_survey_code" "text", "p_collection_version" integer, "p_worker_version" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'public', 'extensions'
    AS $$
declare v_id uuid;
begin
 select id into v_id from pipeline.evidence_artifacts
 where source_id=p_source_id and evidence_type='qilt_source_workbook' and content_hash=p_content_hash
 order by captured_at desc limit 1;
 if v_id is null then
  insert into pipeline.evidence_artifacts(source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata)
  values(p_source_id,'qilt_source_workbook',p_source_url,p_storage_path,p_content_hash,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
   jsonb_build_object('layer','2A','publisher','QILT','survey_code',p_survey_code,'collection_version',p_collection_version,'worker_version',p_worker_version,'source_container','official_qilt_zip','identity_authority',false))
  returning id into v_id;
 end if;
 return v_id;
end $$;


