CREATE OR REPLACE FUNCTION "public"."svc_qilt_touch_source"("p_source_id" "uuid", "p_ok" boolean, "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'public'
    AS $$
begin
 update pipeline.sources set last_checked_at=now(),last_success_at=case when p_ok then now() else last_success_at end,
  last_failure_at=case when not p_ok then now() else last_failure_at end,last_error=case when p_ok then null else p_error end,updated_at=now()
 where id=p_source_id;
end $$;


ALTER FUNCTION "public"."svc_qilt_touch_source"("p_source_id" "uuid", "p_ok" boolean, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_qilt_upsert_mappings"("p_source_id" "uuid", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pipeline', 'catalogue', 'ref', 'public', 'extensions'
    AS $$
declare r jsonb; v_seen int:=0; v_changed int:=0; v_rc int;
begin
 if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>3000 then raise exception 'bounded mapping array required'; end if;
 for r in select value from jsonb_array_elements(p_rows) loop
  if nullif(r->>'provider_id','') is not null and not exists(
   select 1 from catalogue.providers p join ref.countries c on c.id=p.country_id
   where p.id=(r->>'provider_id')::uuid and c.iso_alpha2='AU'
  ) then raise exception 'mapping target must be existing AU CRICOS provider'; end if;
  insert into pipeline.source_provider_mappings(source_id,source_entity_key,source_entity_name,provider_id,match_method,match_confidence,status,verified_at,metadata)
  values(p_source_id,r->>'source_entity_key',r->>'source_entity_name',nullif(r->>'provider_id','')::uuid,
   coalesce(nullif(r->>'match_method',''),'unmatched'),nullif(r->>'match_confidence','')::numeric,
   coalesce(nullif(r->>'status',''),'unmatched'),nullif(r->>'verified_at','')::timestamptz,coalesce(r->'metadata','{}'::jsonb))
  on conflict(source_id,source_entity_key) do update set
   source_entity_name=excluded.source_entity_name,provider_id=excluded.provider_id,match_method=excluded.match_method,
   match_confidence=excluded.match_confidence,status=excluded.status,
   verified_at=case when pipeline.source_provider_mappings.provider_id is not distinct from excluded.provider_id
                         and pipeline.source_provider_mappings.status=excluded.status
                    then pipeline.source_provider_mappings.verified_at else excluded.verified_at end,
   metadata=excluded.metadata,updated_at=now()
  where (pipeline.source_provider_mappings.source_entity_name,pipeline.source_provider_mappings.provider_id,
         pipeline.source_provider_mappings.match_method,pipeline.source_provider_mappings.match_confidence,
         pipeline.source_provider_mappings.status,pipeline.source_provider_mappings.metadata)
    is distinct from
        (excluded.source_entity_name,excluded.provider_id,excluded.match_method,excluded.match_confidence,
         excluded.status,excluded.metadata);
  get diagnostics v_rc=row_count;
  v_seen:=v_seen+1; v_changed:=v_changed+v_rc;
 end loop;
 return jsonb_build_object('seen',v_seen,'changed',v_changed);
end $$;


ALTER FUNCTION "public"."svc_qilt_upsert_mappings"("p_source_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_qs_official_compact_apply"("p_edition_year" integer, "p_source_artifact_id" "uuid", "p_source_url" "text", "p_source_hash" "text", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'ranking'
    AS $$
declare v_full jsonb; v_result jsonb;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service role required' using errcode='42501'; end if;
 if jsonb_typeof(coalesce(p_rows,'[]'::jsonb))<>'array' then raise exception 'rows must be array' using errcode='22023'; end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'institution_name',r->>'n','country_text',nullif(r->>'c',''),'location_text',nullif(r->>'l',''),
   'rank_display',nullif(r->>'r',''),'rank_exact',r->'x','rank_low',r->'lo','rank_high',r->'hi','is_tied',coalesce((r->>'t')::boolean,false),'rank_status',coalesce(r->>'s','unknown'),
   'overall_score',r->'o','overall_score_display',case when r->'o' is null or r->'o'='null'::jsonb then null else trim(both '"' from (r->'o')::text) end,
   'overall_score_low',null,'overall_score_high',null,'source_row_ordinal',nullif(r->>'q','')::integer,
   'publisher_institution_id',null,'profile_url',null,
   'indicators',coalesce((select jsonb_object_agg(e.key,jsonb_build_object(
      'label',case e.key when 'academic_reputation' then 'Academic Reputation' when 'employer_reputation' then 'Employer Reputation' when 'faculty_student_ratio' then 'Faculty Student Ratio' when 'citations_per_faculty' then 'Citations per Faculty' when 'international_faculty_ratio' then 'International Faculty Ratio' when 'international_student_ratio' then 'International Student Ratio' when 'international_student_diversity' then 'International Student Diversity' when 'international_research_network' then 'International Research Network' when 'employment_outcomes' then 'Employment Outcomes' when 'sustainability' then 'Sustainability' else e.key end,
      'value_numeric',e.value->0,'value_display',case when e.value->0 is null or e.value->0='null'::jsonb then null else trim(both '"' from (e.value->0)::text) end,'unit','score','methodology_version',p_edition_year::text
   )) from jsonb_each(coalesce(r->'i','{}'::jsonb)) e),'{}'::jsonb),
   'source_row_payload',jsonb_build_object('qs_official_workbook',true,'previous_rank',r->'p','indicator_rank',coalesce(r->'ir','{}'::jsonb),'classification',coalesce(r->'cl','{}'::jsonb))
  ) order by ord),'[]'::jsonb)
 into v_full
 from jsonb_array_elements(p_rows) with ordinality a(r,ord);
 select public.svc_ranking_ingest_apply('qs_wur',p_edition_year,p_source_url,null,p_source_artifact_id,p_source_hash,'official_qs_xlsx',v_full) into v_result;
 return v_result;
end $$;


ALTER FUNCTION "public"."svc_qs_official_compact_apply"("p_edition_year" integer, "p_source_artifact_id" "uuid", "p_source_url" "text", "p_source_hash" "text", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_applied_import_for_source"("p_source_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'ranking'
    AS $$
  select jsonb_build_object('import_id',m.id,'content_hash',m.content_hash,'original_filename',m.original_filename,'edition_year',m.edition_year)
    from pipeline.sources s
    join ranking.systems sy on sy.code=s.metadata->>'ranking_system_code'
    join ranking.manual_imports m on m.system_id=sy.id and m.edition_year=(s.metadata->>'edition_year')::int and m.status='applied'
   where s.id=p_source_id
   order by m.updated_at desc limit 1
$$;


ALTER FUNCTION "public"."svc_ranking_applied_import_for_source"("p_source_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_import_control_context"("p_import_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking', 'pipeline'
    AS $$
 with x as (
   select mi.*,rs.code system_code,
          case rs.code
            when 'the_wur' then 'THE'
            when 'qs_wur' then 'QS'
            when 'arwu' then 'ARWU'
            else upper(rs.code)
          end source_system
   from ranking.manual_imports mi
   join ranking.systems rs on rs.id=mi.system_id
   where mi.id=p_import_id
 )
 select jsonb_build_object(
   'id',x.id,
   'system_id',x.system_id,
   'system_code',x.system_code,
   'edition_year',x.edition_year,
   'original_filename',x.original_filename,
   'mime_type',x.mime_type,
   'byte_size',x.byte_size,
   'status',x.status,
   'evidence_artifact_id',x.evidence_artifact_id,
   'storage_path',x.storage_path,
   'source_url',x.source_url,
   'methodology_url',x.methodology_url,
   'content_hash',x.content_hash,
   'validation_summary',x.validation_summary,
   'parse_summary',x.parse_summary,
   'inline_payload_gzip_base64',case when x.storage_path like 'inline://%' then (
     select ea.metadata->>'cf212_stage_1'
     from pipeline.evidence_artifacts ea
     where ea.id=x.evidence_artifact_id
   ) else null end,
   'source_id',(
     select s.id
     from pipeline.sources s
     where upper(coalesce(s.metadata->>'source_system',''))=x.source_system
     order by
       case when nullif(s.metadata->>'edition_year','')::integer=x.edition_year then 0
            when coalesce((s.metadata->>'multi_year_family')::boolean,false) then 1
            else 2 end,
       s.updated_at desc
     limit 1
   )
 )
 from x
$$;


ALTER FUNCTION "public"."svc_ranking_import_control_context"("p_import_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_import_recovery_context"("p_import_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking'
    AS $$
declare
  v jsonb;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;
  select jsonb_build_object(
    'id',mi.id,
    'system_code',s.code,
    'edition_year',mi.edition_year,
    'status',mi.status,
    'content_hash',mi.content_hash,
    'evidence_artifact_id',mi.evidence_artifact_id,
    'storage_path',mi.storage_path,
    'original_filename',mi.original_filename
  ) into v
  from ranking.manual_imports mi
  join ranking.systems s on s.id=mi.system_id
  where mi.id=p_import_id;
  if v is null then raise exception 'ranking import not found' using errcode='P0002'; end if;
  return v;
end
$$;


ALTER FUNCTION "public"."svc_ranking_import_recovery_context"("p_import_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_import_storage_restore"("p_import_id" "uuid", "p_storage_path" "text", "p_content_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking', 'pipeline'
    AS $$
declare
  v_import ranking.manual_imports%rowtype;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;
  if coalesce(btrim(p_storage_path),'')='' or p_storage_path like 'inline://%' then
    raise exception 'valid storage path required' using errcode='22023';
  end if;
  select * into v_import from ranking.manual_imports where id=p_import_id;
  if v_import.id is null then raise exception 'ranking import not found' using errcode='P0002'; end if;
  if lower(coalesce(v_import.content_hash,''))<>lower(coalesce(p_content_hash,'')) then
    raise exception 'content hash mismatch' using errcode='22023';
  end if;

  update pipeline.evidence_artifacts
     set storage_path=p_storage_path,
         metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
           'publisher_file_restored_at',now(),
           'publisher_file_restored',true,
           'publisher_file_restore_hash',p_content_hash
         )
   where id=v_import.evidence_artifact_id;

  update ranking.manual_imports
     set storage_path=p_storage_path,
         updated_at=now()
   where id=p_import_id;

  return jsonb_build_object('ok',true,'import_id',p_import_id,'evidence_id',v_import.evidence_artifact_id,'storage_path',p_storage_path);
end
$$;


ALTER FUNCTION "public"."svc_ranking_import_storage_restore"("p_import_id" "uuid", "p_storage_path" "text", "p_content_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_import_validation_update"("p_import_id" "uuid", "p_status" "text", "p_validation_summary" "jsonb", "p_parse_summary" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking'
    AS $$
begin
 if current_user not in ('service_role','postgres') then
   raise exception 'service role required' using errcode='42501';
 end if;
 if p_status not in ('uploaded','validated','parsed','reconciled','needs_review','applied','rejected') then
   raise exception 'invalid ranking import status' using errcode='22023';
 end if;
 update ranking.manual_imports
 set status=p_status,
     validation_summary=coalesce(p_validation_summary,'{}'::jsonb),
     parse_summary=coalesce(p_parse_summary,'{}'::jsonb),
     updated_at=now()
 where id=p_import_id;
 return found;
end
$$;


ALTER FUNCTION "public"."svc_ranking_import_validation_update"("p_import_id" "uuid", "p_status" "text", "p_validation_summary" "jsonb", "p_parse_summary" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_ingest_apply"("p_system_code" "text", "p_edition_year" integer, "p_source_url" "text", "p_methodology_url" "text", "p_source_artifact_id" "uuid", "p_source_fingerprint" "text", "p_source_revision" "text", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking', 'catalogue', 'ref', 'pipeline', 'public'
    AS $$
declare
 v_system_id uuid; v_edition_id uuid; v_mapped integer:=0; v_unmapped integer:=0; v_equiv_fanout integer:=0;
 v_row jsonb; v_pub_id uuid; v_provider_id uuid; v_country text; v_name text;
 v_rank_display text; v_rank_exact integer; v_rank_low integer; v_rank_high integer;
 v_score numeric; v_score_display text; v_score_low numeric; v_score_high numeric; v_status text;
 v_observation_id uuid; v_alias_type text; v_candidate_ids uuid[]; v_equiv_ids uuid[]; v_pid uuid; v_indicator record;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service role required' using errcode='42501'; end if;
 if jsonb_typeof(coalesce(p_rows,'[]'::jsonb))<>'array' then raise exception 'rows must be array' using errcode='22023'; end if;
 select id into v_system_id from ranking.systems where code=p_system_code and active;
 if v_system_id is null then raise exception 'unsupported ranking system' using errcode='22023'; end if;
 v_alias_type:=p_system_code||'_publisher_name';

 insert into ranking.editions(system_id,edition_year,methodology_url,source_url,source_artifact_id,retrieved_at,source_fingerprint,source_revision,access_status,licensing_note,status)
 values(v_system_id,p_edition_year,nullif(p_methodology_url,''),p_source_url,p_source_artifact_id,now(),p_source_fingerprint,coalesce(nullif(p_source_revision,''),'initial'),'licensed_upload','Authorised publisher artifact registered through governed Layer 1 Evidence flow','accepted')
 on conflict(system_id,edition_year,source_revision) do update set methodology_url=excluded.methodology_url,source_url=excluded.source_url,source_artifact_id=excluded.source_artifact_id,retrieved_at=excluded.retrieved_at,source_fingerprint=excluded.source_fingerprint,access_status='licensed_upload',status='accepted',updated_at=now()
 returning id into v_edition_id;

 for v_row in select value from jsonb_array_elements(p_rows) loop
  v_name:=nullif(btrim(v_row->>'institution_name'),''); if v_name is null then continue; end if;
  v_country:=nullif(btrim(v_row->>'country_text'),'');
  v_rank_display:=nullif(btrim(v_row->>'rank_display'),'');
  v_rank_exact:=nullif(v_row->>'rank_exact','')::integer; v_rank_low:=nullif(v_row->>'rank_low','')::integer; v_rank_high:=nullif(v_row->>'rank_high','')::integer;
  v_score:=nullif(v_row->>'overall_score','')::numeric; v_score_display:=nullif(btrim(v_row->>'overall_score_display'),'');
  v_score_low:=nullif(v_row->>'overall_score_low','')::numeric; v_score_high:=nullif(v_row->>'overall_score_high','')::numeric;
  v_status:=coalesce(nullif(v_row->>'rank_status',''),'unknown');

  v_pub_id:=null;
  if nullif(v_row->>'publisher_institution_id','') is not null then
   select id into v_pub_id from ranking.publisher_institutions
   where system_id=v_system_id and publisher_institution_id=nullif(v_row->>'publisher_institution_id','')
   limit 1;
  end if;
  if v_pub_id is null then
   select id into v_pub_id from ranking.publisher_institutions
   where system_id=v_system_id and lower(institution_name)=lower(v_name)
     and lower(coalesce(country_text,''))=lower(coalesce(v_country,''))
   limit 1;
  end if;
  if v_pub_id is null then
   insert into ranking.publisher_institutions(system_id,publisher_institution_id,profile_url,institution_name,country_text,location_text,first_seen_edition,last_seen_edition)
   values(v_system_id,nullif(v_row->>'publisher_institution_id',''),nullif(v_row->>'profile_url',''),v_name,v_country,nullif(v_row->>'location_text',''),p_edition_year,p_edition_year)
   returning id into v_pub_id;
  else
   update ranking.publisher_institutions set publisher_institution_id=coalesce(publisher_institution_id,nullif(v_row->>'publisher_institution_id','')),profile_url=coalesce(profile_url,nullif(v_row->>'profile_url','')),first_seen_edition=least(coalesce(first_seen_edition,p_edition_year),p_edition_year),last_seen_edition=greatest(coalesce(last_seen_edition,p_edition_year),p_edition_year),updated_at=now() where id=v_pub_id;
  end if;

  v_provider_id:=null; v_equiv_ids:=null;
  select pm.provider_id into v_provider_id from ranking.provider_mappings pm where pm.publisher_institution_id=v_pub_id and pm.status='accepted' and pm.valid_to is null order by pm.valid_from desc limit 1;
  if v_provider_id is null then
   select array_agg(distinct pa.provider_id order by pa.provider_id) into v_candidate_ids
   from catalogue.provider_aliases pa join catalogue.providers p on p.id=pa.provider_id left join ref.countries c on c.id=p.country_id
   where lower(pa.alias)=lower(v_name) and (pa.alias_type=v_alias_type or pa.alias_type='ranking_publisher_name' or pa.alias_type like '%_wur_publisher_name') and pa.valid_to is null
     and (v_country is null or lower(c.name)=lower(v_country) or lower(c.iso_alpha2::text)=lower(v_country) or lower(c.iso_alpha3::text)=lower(v_country));
   if coalesce(array_length(v_candidate_ids,1),0)=1 then v_provider_id:=v_candidate_ids[1]; end if;
  end if;
  if v_provider_id is null then
   select array_agg(p.id order by p.id) into v_candidate_ids
   from catalogue.providers p left join ref.countries c on c.id=p.country_id
   where lower(regexp_replace(coalesce(p.display_name,p.canonical_name),'[^a-z0-9]+','','g'))=lower(regexp_replace(v_name,'[^a-z0-9]+','','g'))
     and (v_country is null or lower(c.name)=lower(v_country) or lower(c.iso_alpha2::text)=lower(v_country) or lower(c.iso_alpha3::text)=lower(v_country));
   if coalesce(array_length(v_candidate_ids,1),0)>=1 then v_provider_id:=v_candidate_ids[1]; v_equiv_ids:=v_candidate_ids; end if;
  end if;
  if v_provider_id is not null and v_equiv_ids is null then v_equiv_ids:=public.svc_statistical_equivalent_provider_ids(v_provider_id); end if;
  if v_provider_id is not null and not exists(select 1 from ranking.provider_mappings pm where pm.publisher_institution_id=v_pub_id and pm.provider_id=v_provider_id and pm.status='accepted' and pm.valid_to is null) then
   insert into ranking.provider_mappings(publisher_institution_id,provider_id,mapping_method,confidence,status,evidence_artifact_id,reviewed_at,note)
   values(v_pub_id,v_provider_id,case when coalesce(array_length(v_equiv_ids,1),0)>1 then 'exact_equivalent_provider_fanout' when exists(select 1 from catalogue.provider_aliases pa where pa.provider_id=v_provider_id and lower(pa.alias)=lower(v_name) and (pa.alias_type=v_alias_type or pa.alias_type='ranking_publisher_name' or pa.alias_type like '%_wur_publisher_name') and pa.valid_to is null) then 'accepted_alias_country' else 'exact_canonical_name_country' end,1.0,'accepted',p_source_artifact_id,now(),case when coalesce(array_length(v_equiv_ids,1),0)>1 then 'Deterministic statistical-equivalence exception: exact provider name and/or identifier duplicates fan out; no identity merge performed.' else 'Deterministic unique Provider reconciliation during governed ranking ingestion' end);
  end if;

  insert into ranking.observations(edition_id,publisher_institution_id,provider_id,rank_display,rank_exact,rank_low,rank_high,is_tied,rank_status,overall_score,overall_score_display,overall_score_low,overall_score_high,source_row_ordinal,source_row_payload,evidence_artifact_id)
  values(v_edition_id,v_pub_id,v_provider_id,v_rank_display,v_rank_exact,v_rank_low,v_rank_high,coalesce((v_row->>'is_tied')::boolean,false),v_status,v_score,v_score_display,v_score_low,v_score_high,nullif(v_row->>'source_row_ordinal','')::integer,v_row,p_source_artifact_id)
  on conflict(edition_id,publisher_institution_id) do update set provider_id=excluded.provider_id,rank_display=excluded.rank_display,rank_exact=excluded.rank_exact,rank_low=excluded.rank_low,rank_high=excluded.rank_high,is_tied=excluded.is_tied,rank_status=excluded.rank_status,overall_score=excluded.overall_score,overall_score_display=excluded.overall_score_display,overall_score_low=excluded.overall_score_low,overall_score_high=excluded.overall_score_high,source_row_ordinal=excluded.source_row_ordinal,source_row_payload=excluded.source_row_payload,evidence_artifact_id=excluded.evidence_artifact_id
  returning id into v_observation_id;
  delete from ranking.observation_provider_links where observation_id=v_observation_id;
  if v_provider_id is not null then
    foreach v_pid in array coalesce(v_equiv_ids,array[v_provider_id]::uuid[]) loop
      insert into ranking.observation_provider_links(observation_id,provider_id,link_method,is_primary) values(v_observation_id,v_pid,case when v_pid=v_provider_id then 'primary_exact' else 'equivalent_exact_name_or_identifier' end,v_pid=v_provider_id) on conflict do nothing;
    end loop;
    v_equiv_fanout:=v_equiv_fanout+greatest(coalesce(array_length(v_equiv_ids,1),1)-1,0);
  end if;

  if jsonb_typeof(v_row->'indicators')='object' then
   for v_indicator in select key,value from jsonb_each(v_row->'indicators') loop
    insert into ranking.indicator_observations(observation_id,indicator_code,indicator_label,value_numeric,value_display,unit,methodology_version,indicator_group,rank_display,rank_exact,rank_low,rank_high,is_tied,rank_status)
    values(v_observation_id,v_indicator.key,nullif(v_indicator.value->>'label',''),
      case when jsonb_typeof(v_indicator.value)='object' then nullif(v_indicator.value->>'value_numeric','')::numeric else nullif(trim(both '"' from v_indicator.value::text),'')::numeric end,
      case when jsonb_typeof(v_indicator.value)='object' then nullif(v_indicator.value->>'value_display','') else trim(both '"' from v_indicator.value::text) end,
      case when jsonb_typeof(v_indicator.value)='object' then nullif(v_indicator.value->>'unit','') else null end,
      case when jsonb_typeof(v_indicator.value)='object' then nullif(v_indicator.value->>'methodology_version','') else null end,
      case when jsonb_typeof(v_indicator.value)='object' then nullif(v_indicator.value->>'group','') else null end,
      case when jsonb_typeof(v_indicator.value)='object' then nullif(v_indicator.value->>'rank_display','') else null end,
      case when jsonb_typeof(v_indicator.value)='object' then nullif(v_indicator.value->>'rank_exact','')::integer else null end,
      case when jsonb_typeof(v_indicator.value)='object' then nullif(v_indicator.value->>'rank_low','')::integer else null end,
      case when jsonb_typeof(v_indicator.value)='object' then nullif(v_indicator.value->>'rank_high','')::integer else null end,
      case when jsonb_typeof(v_indicator.value)='object' then coalesce((v_indicator.value->>'is_tied')::boolean,false) else false end,
      case when jsonb_typeof(v_indicator.value)='object' then nullif(v_indicator.value->>'rank_status','') else null end)
    on conflict(observation_id,indicator_code) do update set indicator_label=excluded.indicator_label,value_numeric=excluded.value_numeric,value_display=excluded.value_display,unit=excluded.unit,methodology_version=excluded.methodology_version,indicator_group=excluded.indicator_group,rank_display=excluded.rank_display,rank_exact=excluded.rank_exact,rank_low=excluded.rank_low,rank_high=excluded.rank_high,is_tied=excluded.is_tied,rank_status=excluded.rank_status;
   end loop;
  end if;
  if v_provider_id is null then v_unmapped:=v_unmapped+1; else v_mapped:=v_mapped+1; end if;
 end loop;
 update ranking.manual_imports set status=case when v_unmapped>0 then 'needs_review' else 'applied' end,parse_summary=jsonb_build_object('rows',jsonb_array_length(p_rows),'mapped',v_mapped,'unmapped',v_unmapped,'equivalent_provider_fanout_links',v_equiv_fanout),updated_at=now() where evidence_artifact_id=p_source_artifact_id;
 return jsonb_build_object('edition_id',v_edition_id,'rows',jsonb_array_length(p_rows),'mapped',v_mapped,'unmapped',v_unmapped,'equivalent_provider_fanout_links',v_equiv_fanout,'status',case when v_unmapped>0 then 'needs_review' else 'applied' end);
end $$;


ALTER FUNCTION "public"."svc_ranking_ingest_apply"("p_system_code" "text", "p_edition_year" integer, "p_source_url" "text", "p_methodology_url" "text", "p_source_artifact_id" "uuid", "p_source_fingerprint" "text", "p_source_revision" "text", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_ingest_finalize"("p_system_code" "text", "p_edition_year" integer, "p_source_artifact_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking', 'catalogue', 'ref'
    AS $$
declare
  v_system_id uuid;
  v_edition_id uuid;
  v_rows bigint:=0;
  v_mapped bigint:=0;
  v_global_unmapped bigint:=0;
  v_supported_scope_unmapped bigint:=0;
  v_equivalent_links bigint:=0;
  v_status text;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;

  select id into v_system_id from ranking.systems where code=p_system_code and active;
  if v_system_id is null then raise exception 'unsupported ranking system' using errcode='22023'; end if;

  select e.id into v_edition_id
  from ranking.editions e
  where e.system_id=v_system_id
    and e.edition_year=p_edition_year
    and e.source_artifact_id=p_source_artifact_id
  order by e.updated_at desc
  limit 1;
  if v_edition_id is null then raise exception 'ranking edition not found for source artifact' using errcode='22023'; end if;

  select count(*),
         count(*) filter(where o.provider_id is not null or exists(
           select 1 from ranking.observation_provider_links opl
           where opl.observation_id=o.id
         )),
         count(*) filter(where o.provider_id is null and not exists(
           select 1 from ranking.observation_provider_links opl
           where opl.observation_id=o.id
         ))
  into v_rows,v_mapped,v_global_unmapped
  from ranking.observations o
  where o.edition_id=v_edition_id;

  select count(*) into v_supported_scope_unmapped
  from ranking.observations o
  join ranking.publisher_institutions pi on pi.id=o.publisher_institution_id
  where o.edition_id=v_edition_id
    and o.provider_id is null
    and not exists(select 1 from ranking.observation_provider_links opl where opl.observation_id=o.id)
    and exists(
      select 1
      from ref.countries c
      where (lower(c.name)=lower(coalesce(pi.country_text,''))
          or lower(c.iso_alpha2::text)=lower(coalesce(pi.country_text,''))
          or lower(c.iso_alpha3::text)=lower(coalesce(pi.country_text,'')))
        and exists(select 1 from catalogue.providers p where p.country_id=c.id)
    );

  select count(*) into v_equivalent_links
  from ranking.observation_provider_links opl
  join ranking.observations o on o.id=opl.observation_id
  where o.edition_id=v_edition_id and opl.is_primary=false;

  v_status:=case when v_supported_scope_unmapped>0 then 'needs_review' else 'applied' end;

  update ranking.manual_imports
  set status=v_status,
      parse_summary=jsonb_build_object(
        'rows',v_rows,
        'mapped',v_mapped,
        'global_unmapped',v_global_unmapped,
        'supported_scope_unmapped',v_supported_scope_unmapped,
        'equivalent_provider_fanout_links',v_equivalent_links,
        'finalized_at',now()
      ),
      updated_at=now()
  where evidence_artifact_id=p_source_artifact_id;

  return jsonb_build_object(
    'edition_id',v_edition_id,
    'rows',v_rows,
    'mapped',v_mapped,
    'global_unmapped',v_global_unmapped,
    'supported_scope_unmapped',v_supported_scope_unmapped,
    'equivalent_provider_fanout_links',v_equivalent_links,
    'status',v_status
  );
end
$$;


ALTER FUNCTION "public"."svc_ranking_ingest_finalize"("p_system_code" "text", "p_edition_year" integer, "p_source_artifact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_inline_evidence_payload_get"("p_evidence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'ranking'
    AS $$
declare
  v_payload pipeline.ranking_inline_evidence_payloads%rowtype;
  v_import ranking.manual_imports%rowtype;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;
  select * into v_payload from pipeline.ranking_inline_evidence_payloads where evidence_id=p_evidence_id;
  if v_payload.evidence_id is null then raise exception 'inline ranking evidence not found' using errcode='P0002'; end if;
  select * into v_import from ranking.manual_imports where evidence_artifact_id=p_evidence_id limit 1;
  if v_import.id is null then raise exception 'ranking import not found for evidence' using errcode='P0002'; end if;
  return jsonb_build_object(
    'evidence_id',v_payload.evidence_id,
    'import_id',v_import.id,
    'edition_year',v_import.edition_year,
    'original_filename',v_payload.original_filename,
    'mime_type',v_payload.mime_type,
    'byte_size',v_payload.byte_size,
    'content_hash',v_payload.content_hash,
    'payload_base64',encode(v_payload.payload,'base64')
  );
end
$$;


ALTER FUNCTION "public"."svc_ranking_inline_evidence_payload_get"("p_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_inline_evidence_promote"("p_evidence_id" "uuid", "p_storage_path" "text", "p_delete_inline" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'ranking'
    AS $$
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;
  if coalesce(btrim(p_storage_path),'')='' or p_storage_path like 'inline://%' then
    raise exception 'valid storage path required' using errcode='22023';
  end if;
  if not exists(select 1 from pipeline.ranking_inline_evidence_payloads where evidence_id=p_evidence_id) then
    raise exception 'inline ranking evidence not found' using errcode='P0002';
  end if;
  update pipeline.evidence_artifacts
     set storage_path=p_storage_path,
         metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('inline_payload_promoted_at',now(),'inline_payload_promoted',true)
   where id=p_evidence_id;
  update ranking.manual_imports
     set storage_path=p_storage_path, updated_at=now()
   where evidence_artifact_id=p_evidence_id;
  if p_delete_inline then
    delete from pipeline.ranking_inline_evidence_payloads where evidence_id=p_evidence_id;
  end if;
end
$$;


ALTER FUNCTION "public"."svc_ranking_inline_evidence_promote"("p_evidence_id" "uuid", "p_storage_path" "text", "p_delete_inline" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_job_finish"("p_job_id" "uuid", "p_status" "text", "p_result" "jsonb" DEFAULT '{}'::"jsonb", "p_error_text" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'public'
    AS $$
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;
  if p_status not in ('completed','failed') then
    raise exception 'invalid ranking job terminal status' using errcode='22023';
  end if;
  update pipeline.jobs
  set status=p_status,completed_at=now(),result=coalesce(p_result,'{}'::jsonb),error_text=p_error_text
  where id=p_job_id and domain='ranking';
end $$;


ALTER FUNCTION "public"."svc_ranking_job_finish"("p_job_id" "uuid", "p_status" "text", "p_result" "jsonb", "p_error_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_job_start"("p_job_type" "text", "p_source_id" "uuid", "p_requested_by" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'public'
    AS $$
declare v_id uuid;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;
  insert into pipeline.jobs(job_type,domain,source_id,status,requested_by,started_at,attempt_count,payload)
  values(p_job_type,'ranking',p_source_id,'running',p_requested_by,now(),1,coalesce(p_payload,'{}'::jsonb))
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."svc_ranking_job_start"("p_job_type" "text", "p_source_id" "uuid", "p_requested_by" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_latest_import"("p_system_code" "text", "p_edition_year" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking'
    AS $$
declare v jsonb;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service role required' using errcode='42501'; end if;
 select jsonb_build_object(
   'id',mi.id,'edition_year',mi.edition_year,'source_url',mi.source_url,'methodology_url',mi.methodology_url,
   'revision_note',mi.revision_note,'original_filename',mi.original_filename,'mime_type',mi.mime_type,'byte_size',mi.byte_size,
   'content_hash',mi.content_hash,'storage_path',mi.storage_path,'evidence_artifact_id',mi.evidence_artifact_id,'status',mi.status
 ) into v
 from ranking.manual_imports mi join ranking.systems s on s.id=mi.system_id
 where s.code=p_system_code and mi.edition_year=p_edition_year and mi.status in ('uploaded','validated','parsed','needs_review','reconciled','applied')
 order by mi.uploaded_at desc limit 1;
 return coalesce(v,'{}'::jsonb);
end
$$;


ALTER FUNCTION "public"."svc_ranking_latest_import"("p_system_code" "text", "p_edition_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_manual_import_mark_applied"("p_import_id" "uuid", "p_validation_summary" "jsonb" DEFAULT '{}'::"jsonb", "p_parse_summary" "jsonb" DEFAULT '{}'::"jsonb", "p_supersede_inline" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking'
    AS $$
DECLARE
  v_system_id uuid;
  v_year integer;
  v_purged integer:=0;
BEGIN
  IF current_user NOT IN ('service_role','postgres') THEN
    raise exception 'service role required' using errcode='42501';
  END IF;
  SELECT system_id,edition_year INTO v_system_id,v_year FROM ranking.manual_imports WHERE id=p_import_id;
  IF v_system_id IS NULL THEN raise exception 'ranking import not found' using errcode='P0002'; END IF;

  UPDATE ranking.manual_imports
  SET status='applied', validation_summary=coalesce(p_validation_summary,'{}'::jsonb), parse_summary=coalesce(p_parse_summary,'{}'::jsonb), updated_at=now()
  WHERE id=p_import_id;

  IF p_supersede_inline THEN
    DELETE FROM ranking.manual_imports
    WHERE system_id=v_system_id
      AND edition_year=v_year
      AND id<>p_import_id
      AND storage_path LIKE 'inline://%';
    GET DIAGNOSTICS v_purged=ROW_COUNT;
  END IF;

  RETURN jsonb_build_object('ok',true,'import_id',p_import_id,'superseded_inline',v_purged,'purged_operational_rows',v_purged);
END
$$;


ALTER FUNCTION "public"."svc_ranking_manual_import_mark_applied"("p_import_id" "uuid", "p_validation_summary" "jsonb", "p_parse_summary" "jsonb", "p_supersede_inline" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_manual_import_register"("p_system_code" "text", "p_edition_year" integer, "p_publisher_name" "text", "p_source_url" "text", "p_methodology_url" "text", "p_licensing_note" "text", "p_revision_note" "text", "p_original_filename" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_path" "text", "p_uploaded_by" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking', 'pipeline', 'auth'
    AS $$
declare
  v_system ranking.systems%rowtype;
  v_evidence_id uuid;
  v_import_id uuid;
  v_existing ranking.manual_imports%rowtype;
  v_group_key text;
  v_capture_version integer;
begin
  if current_user not in ('service_role','postgres') then raise exception 'service role required' using errcode='42501'; end if;
  select * into v_system from ranking.systems where code=p_system_code and active;
  if v_system.id is null then raise exception 'unsupported ranking system' using errcode='22023'; end if;
  if p_edition_year<2000 or p_edition_year>2100 then raise exception 'invalid edition year' using errcode='22023'; end if;
  if coalesce(btrim(p_source_url),'')='' then raise exception 'source url required' using errcode='22023'; end if;
  if coalesce(btrim(p_licensing_note),'')='' then raise exception 'licensing note required' using errcode='22023'; end if;
  if coalesce(btrim(p_content_hash),'')='' then raise exception 'content hash required' using errcode='22023'; end if;

  select * into v_existing
  from ranking.manual_imports
  where system_id=v_system.id and edition_year=p_edition_year and content_hash=p_content_hash
  order by uploaded_at desc nulls last,id desc
  limit 1
  for update;

  if v_existing.id is not null then
    if v_existing.status <> 'rejected'
       and v_existing.evidence_artifact_id is not null
       and exists (select 1 from pipeline.evidence_artifacts ea where ea.id=v_existing.evidence_artifact_id)
       and (coalesce(v_existing.storage_path,'')='' or v_existing.storage_path like 'inline://%')
       and not exists (select 1 from pipeline.ranking_inline_evidence_payloads iep where iep.evidence_id=v_existing.evidence_artifact_id) then
      update pipeline.evidence_artifacts
         set storage_path=p_storage_path,
             metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
               'publisher_file_restored_at',now(),
               'publisher_file_restored',true,
               'publisher_file_restore_hash',p_content_hash,
               'publisher_file_restore_reason','byte_identical_reupload_missing_retained_payload')
       where id=v_existing.evidence_artifact_id;
      update ranking.manual_imports set storage_path=p_storage_path,updated_at=now() where id=v_existing.id;
      return jsonb_build_object('duplicate',false,'recovered_duplicate',true,'import_id',v_existing.id,
        'evidence_id',v_existing.evidence_artifact_id,'status',v_existing.status,'storage_path',p_storage_path);
    end if;
    return jsonb_build_object('duplicate',true,'import_id',v_existing.id,'evidence_id',v_existing.evidence_artifact_id);
  end if;

  v_group_key:='ranking:'||p_system_code||':'||p_edition_year::text;
  select coalesce(max(capture_version),0)+1 into v_capture_version from pipeline.evidence_artifacts where evidence_group_key=v_group_key;
  insert into pipeline.evidence_artifacts(evidence_type,source_url,storage_path,content_hash,mime_type,captured_at,metadata,retention_class,review_state,capture_version,evidence_group_key)
  values ('ranking_publisher_file',p_source_url,p_storage_path,p_content_hash,p_mime_type,now(),
    jsonb_strip_nulls(jsonb_build_object('ranking_system',p_system_code,'edition_year',p_edition_year,'publisher_name',p_publisher_name,
      'methodology_url',p_methodology_url,'licensing_note',p_licensing_note,'revision_note',p_revision_note,'original_filename',p_original_filename,
      'byte_size',p_byte_size,'uploaded_by',p_uploaded_by,'manual_upload',true)),
    'source_evidence','pending_review',v_capture_version,v_group_key) returning id into v_evidence_id;
  insert into ranking.manual_imports(system_id,edition_year,publisher_name,source_url,methodology_url,licensing_note,revision_note,original_filename,mime_type,byte_size,content_hash,storage_path,evidence_artifact_id,status,uploaded_by)
  values (v_system.id,p_edition_year,p_publisher_name,p_source_url,nullif(p_methodology_url,''),p_licensing_note,nullif(p_revision_note,''),p_original_filename,p_mime_type,p_byte_size,p_content_hash,p_storage_path,v_evidence_id,'uploaded',p_uploaded_by)
  returning id into v_import_id;
  return jsonb_build_object('duplicate',false,'import_id',v_import_id,'evidence_id',v_evidence_id,'status','uploaded','capture_version',v_capture_version);
end
$$;


ALTER FUNCTION "public"."svc_ranking_manual_import_register"("p_system_code" "text", "p_edition_year" integer, "p_publisher_name" "text", "p_source_url" "text", "p_methodology_url" "text", "p_licensing_note" "text", "p_revision_note" "text", "p_original_filename" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_path" "text", "p_uploaded_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_raw_evidence_register"("p_system_code" "text", "p_edition_year" integer, "p_source_url" "text", "p_storage_path" "text", "p_content_hash" "text", "p_mime_type" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking', 'pipeline'
    AS $$
declare
  v_id uuid;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;
  if not exists (select 1 from ranking.systems where code=p_system_code and active) then
    raise exception 'unsupported ranking system' using errcode='22023';
  end if;
  if p_edition_year<2000 or p_edition_year>2100 then
    raise exception 'invalid edition year' using errcode='22023';
  end if;
  if coalesce(btrim(p_storage_path),'')='' or coalesce(btrim(p_content_hash),'')='' then
    raise exception 'storage path and content hash required' using errcode='22023';
  end if;

  select id into v_id from pipeline.evidence_artifacts where storage_path=p_storage_path limit 1;
  if v_id is not null then return v_id; end if;

  insert into pipeline.evidence_artifacts(
    evidence_type,source_url,storage_path,content_hash,mime_type,captured_at,metadata,
    retention_class,review_state,capture_version,evidence_group_key
  ) values (
    'ranking_publisher_raw',p_source_url,p_storage_path,p_content_hash,p_mime_type,now(),
    jsonb_strip_nulls(coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('ranking_system',p_system_code,'edition_year',p_edition_year)),
    'source_evidence','pending_review',1,
    'ranking:'||p_system_code||':'||p_edition_year::text||':raw:'||left(p_content_hash,16)
  ) returning id into v_id;
  return v_id;
end
$$;


ALTER FUNCTION "public"."svc_ranking_raw_evidence_register"("p_system_code" "text", "p_edition_year" integer, "p_source_url" "text", "p_storage_path" "text", "p_content_hash" "text", "p_mime_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_reconciliation_preview"("p_rows" "jsonb", "p_country_code" "text" DEFAULT 'AU'::"text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref'
    AS $$
with input as (
  select row_number() over ()::int ordinal,
    nullif(btrim(x->>'institution_name'),'') institution_name,
    nullif(btrim(x->>'country_text'),'') country_text,
    nullif(btrim(x->>'rank_display'),'') rank_display,
    x
  from jsonb_array_elements(coalesce(p_rows,'[]'::jsonb)) x
),
target as (
  select * from input
  where institution_name is not null
    and lower(coalesce(country_text,'')) in (
      select lower(name) from ref.countries where iso_alpha2=p_country_code
      union all select lower(iso_alpha2::text) from ref.countries where iso_alpha2=p_country_code
      union all select lower(iso_alpha3::text) from ref.countries where iso_alpha2=p_country_code
    )
),
matches as (
  select t.*,
    array(
      select distinct pa.provider_id
      from catalogue.provider_aliases pa
      join catalogue.providers p on p.id=pa.provider_id
      join ref.countries c on c.id=p.country_id
      where c.iso_alpha2=p_country_code
        and lower(pa.alias)=lower(t.institution_name)
        and pa.alias_type='qs_wur_publisher_name'
        and pa.valid_to is null
      order by pa.provider_id
    ) alias_ids,
    array(
      select p.id
      from catalogue.providers p join ref.countries c on c.id=p.country_id
      where c.iso_alpha2=p_country_code
        and lower(coalesce(p.display_name,p.canonical_name))=lower(t.institution_name)
      order by p.id
    ) exact_ids
  from target t
),
classified as (
 select *,
   coalesce(array_length(alias_ids,1),0) alias_count,
   coalesce(array_length(exact_ids,1),0) exact_count,
   case when coalesce(array_length(alias_ids,1),0)=1 then alias_ids
        when coalesce(array_length(alias_ids,1),0)=0 then exact_ids
        else alias_ids end chosen_ids,
   case when coalesce(array_length(alias_ids,1),0)=1 then 'accepted_alias_country'
        when coalesce(array_length(alias_ids,1),0)>1 then 'alias_ambiguous'
        when coalesce(array_length(exact_ids,1),0)=1 then 'exact_canonical_name_country'
        when coalesce(array_length(exact_ids,1),0)>1 then 'exact_ambiguous'
        else 'unmatched' end mapping_method
 from matches
)
select jsonb_build_object(
  'country_code',p_country_code,
  'source_rows',jsonb_array_length(coalesce(p_rows,'[]'::jsonb)),
  'country_rows',(select count(*) from target),
  'alias_unique',(select count(*) from classified where mapping_method='accepted_alias_country'),
  'exact_unique',(select count(*) from classified where mapping_method='exact_canonical_name_country'),
  'mapped_unique',(select count(*) from classified where mapping_method in ('accepted_alias_country','exact_canonical_name_country')),
  'alias_ambiguous',(select count(*) from classified where mapping_method='alias_ambiguous'),
  'exact_ambiguous',(select count(*) from classified where mapping_method='exact_ambiguous'),
  'unmatched',(select count(*) from classified where mapping_method='unmatched'),
  'mapped_rate',round(coalesce((select count(*)::numeric from classified where mapping_method in ('accepted_alias_country','exact_canonical_name_country'))/nullif((select count(*) from target),0),0)*100,2),
  'unmatched_sample',coalesce((select jsonb_agg(jsonb_build_object('institution_name',institution_name,'rank_display',rank_display) order by ordinal) from (select * from classified where mapping_method='unmatched' order by ordinal limit 25) s),'[]'::jsonb),
  'ambiguous_sample',coalesce((select jsonb_agg(jsonb_build_object('institution_name',institution_name,'rank_display',rank_display,'mapping_method',mapping_method,'candidate_provider_ids',to_jsonb(chosen_ids)) order by ordinal) from (select * from classified where mapping_method in ('alias_ambiguous','exact_ambiguous') order by ordinal limit 25) s),'[]'::jsonb)
)
$$;


ALTER FUNCTION "public"."svc_ranking_reconciliation_preview"("p_rows" "jsonb", "p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ranking_reconciliation_preview_system"("p_rows" "jsonb", "p_country_code" "text", "p_system_code" "text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref'
    AS $$
with input as (
 select row_number() over ()::int ordinal,nullif(btrim(x->>'institution_name'),'') institution_name,
  nullif(btrim(x->>'country_text'),'') country_text,nullif(btrim(x->>'rank_display'),'') rank_display
 from jsonb_array_elements(coalesce(p_rows,'[]'::jsonb)) x
), target as (
 select * from input where institution_name is not null and lower(coalesce(country_text,'')) in (
  select lower(name) from ref.countries where iso_alpha2=p_country_code
  union all select lower(iso_alpha2::text) from ref.countries where iso_alpha2=p_country_code
  union all select lower(iso_alpha3::text) from ref.countries where iso_alpha2=p_country_code
 )
), matches as (
 select t.*,
  array(select distinct pa.provider_id from catalogue.provider_aliases pa
   join catalogue.providers p on p.id=pa.provider_id join ref.countries c on c.id=p.country_id
   where c.iso_alpha2=p_country_code and lower(pa.alias)=lower(t.institution_name) and pa.valid_to is null
    and (pa.alias_type='ranking_publisher_name' or pa.alias_type like '%_wur_publisher_name') order by pa.provider_id) alias_ids,
  array(select p.id from catalogue.providers p join ref.countries c on c.id=p.country_id
   where c.iso_alpha2=p_country_code and lower(regexp_replace(coalesce(p.display_name,p.canonical_name),'[^a-z0-9]+','','g'))=
   lower(regexp_replace(t.institution_name,'[^a-z0-9]+','','g')) order by p.id) exact_ids
 from target t
), classified as (
 select *,
  case when coalesce(array_length(alias_ids,1),0)=1 then alias_ids
       when coalesce(array_length(alias_ids,1),0)=0 then exact_ids else alias_ids end chosen_ids,
  case when coalesce(array_length(alias_ids,1),0)=1 then 'accepted_alias_country'
       when coalesce(array_length(alias_ids,1),0)>1 and coalesce(array_length(exact_ids,1),0)>0 then 'equivalent_exact_name_fanout'
       when coalesce(array_length(alias_ids,1),0)>1 then 'alias_ambiguous'
       when coalesce(array_length(exact_ids,1),0)=1 then 'exact_canonical_name_country'
       when coalesce(array_length(exact_ids,1),0)>1 then 'equivalent_exact_name_fanout'
       else 'unmatched' end mapping_method
 from matches
)
select jsonb_build_object(
 'system_code',p_system_code,'country_code',p_country_code,'country_rows',(select count(*) from target),
 'alias_unique',(select count(*) from classified where mapping_method='accepted_alias_country'),
 'exact_unique',(select count(*) from classified where mapping_method='exact_canonical_name_country'),
 'equivalent_fanout',(select count(*) from classified where mapping_method='equivalent_exact_name_fanout'),
 'mapped_unique',(select count(*) from classified where mapping_method in ('accepted_alias_country','exact_canonical_name_country','equivalent_exact_name_fanout')),
 'alias_ambiguous',(select count(*) from classified where mapping_method='alias_ambiguous'),
 'exact_ambiguous',0,
 'unmatched',(select count(*) from classified where mapping_method='unmatched'),
 'mapped_rate',round(coalesce((select count(*)::numeric from classified where mapping_method in ('accepted_alias_country','exact_canonical_name_country','equivalent_exact_name_fanout'))/nullif((select count(*) from target),0),0)*100,2),
 'unmatched_sample',coalesce((select jsonb_agg(jsonb_build_object('institution_name',institution_name,'rank_display',rank_display) order by ordinal) from (select * from classified where mapping_method='unmatched' order by ordinal limit 50)s),'[]'::jsonb),
 'ambiguous_sample',coalesce((select jsonb_agg(jsonb_build_object('institution_name',institution_name,'rank_display',rank_display,'mapping_method',mapping_method,'candidate_provider_ids',to_jsonb(chosen_ids)) order by ordinal) from (select * from classified where mapping_method='alias_ambiguous' order by ordinal limit 50)s),'[]'::jsonb),
 'equivalent_sample',coalesce((select jsonb_agg(jsonb_build_object('institution_name',institution_name,'rank_display',rank_display,'mapping_method',mapping_method,'provider_ids',to_jsonb(exact_ids)) order by ordinal) from (select * from classified where mapping_method='equivalent_exact_name_fanout' order by ordinal limit 50)s),'[]'::jsonb)
) $$;


