  update pipeline.register_replay_runs set lease_until = null where id = p_run_id;
end $$;


ALTER FUNCTION "public"."svc_register_replay_release"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_register_replay_save"("p_run_id" "uuid", "p_engine" "text", "p_rows" "jsonb", "p_final" boolean, "p_error" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if p_error is not null then
    update pipeline.register_replay_runs set error = p_engine || ': ' || left(p_error, 300), done_at = now() where id = p_run_id;
    return 0;
  end if;
  insert into pipeline.register_replay_keys(run_id, engine, record_key, fingerprint, fields_hash, fields)
  select p_run_id, p_engine, x->>'k', x->>'f', x->>'h', x->'x' from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) x
  on conflict (run_id, engine, record_key) do update set fingerprint = excluded.fingerprint, fields_hash = excluded.fields_hash, fields = excluded.fields,
         dup = pipeline.register_replay_keys.dup + 1;
  get diagnostics n = row_count;
  if p_final then
    update pipeline.register_replay_runs
       set reference_done = reference_done or p_engine = 'reference', adapter_done = adapter_done or p_engine = 'adapter',
           reference_records = case when p_engine = 'reference' then (select count(*) from pipeline.register_replay_keys k where k.run_id = p_run_id and k.engine = 'reference') else reference_records end,
           adapter_records = case when p_engine = 'adapter' then (select count(*) from pipeline.register_replay_keys k where k.run_id = p_run_id and k.engine = 'adapter') else adapter_records end
     where id = p_run_id;
    perform security.register_replay_compare_v1(p_run_id);
  end if;
  return n;
end $$;


ALTER FUNCTION "public"."svc_register_replay_save"("p_run_id" "uuid", "p_engine" "text", "p_rows" "jsonb", "p_final" boolean, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_register_replay_save_v2"("p_run_id" "uuid", "p_engine" "text", "p_rows" "jsonb", "p_pos" integer, "p_final" boolean, "p_error" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if p_error is not null then
    update pipeline.register_replay_runs set error = p_engine || ': ' || left(p_error, 300), done_at = now() where id = p_run_id;
    return 0;
  end if;
  insert into pipeline.register_replay_keys(run_id, engine, record_key, fingerprint, fields_hash, fields)
  select p_run_id, p_engine, x->>'k', x->>'f', x->>'h', x->'x' from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) x
  on conflict (run_id, engine, record_key) do update set fingerprint = excluded.fingerprint, fields_hash = excluded.fields_hash, fields = excluded.fields,
         dup = pipeline.register_replay_keys.dup + 1;
  get diagnostics n = row_count;
  update pipeline.register_replay_runs
     set reference_pos = case when p_engine = 'reference' and p_pos is not null then p_pos else reference_pos end,
         adapter_pos = case when p_engine = 'adapter' and p_pos is not null then p_pos else adapter_pos end
   where id = p_run_id;
  if p_final then
    update pipeline.register_replay_runs
       set reference_done = reference_done or p_engine = 'reference', adapter_done = adapter_done or p_engine = 'adapter',
           reference_records = case when p_engine = 'reference' then (select count(*) from pipeline.register_replay_keys k where k.run_id = p_run_id and k.engine = 'reference') else reference_records end,
           adapter_records = case when p_engine = 'adapter' then (select count(*) from pipeline.register_replay_keys k where k.run_id = p_run_id and k.engine = 'adapter') else adapter_records end
     where id = p_run_id;
    perform security.register_replay_compare_v1(p_run_id);
  end if;
  return n;
end $$;


ALTER FUNCTION "public"."svc_register_replay_save_v2"("p_run_id" "uuid", "p_engine" "text", "p_rows" "jsonb", "p_pos" integer, "p_final" boolean, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_retention_files_done"("p_run_id" "uuid", "p_removed" integer, "p_bytes" bigint, "p_finished" boolean, "p_error" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cat text;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select category into v_cat from pipeline.retention_runs where id = p_run_id;
  if v_cat = 'evidence_unreferenced' then
    -- records are counted by the background worker when they are removed; here only file bytes and the queue are updated, and the run
    -- stays running until no candidate is left (the background worker finishes it)
    if p_error is null then
      update pipeline.retention_file_queue set status = 'removed' where run_id = p_run_id and status = 'handed';
    end if;
    update pipeline.retention_runs
       set bytes = bytes + greatest(coalesce(p_bytes, 0), 0), updated_at = now(),
           status = case when p_error is not null then 'failed' else status end,
           error = coalesce(left(p_error, 500), error),
           finished_at = case when p_error is not null then now() else finished_at end,
           note = case when p_error is not null then 'Failed while removing evidence files.'
                       else format('Running: %s records removed, %s MB of files so far.', removed, round((bytes + greatest(coalesce(p_bytes, 0), 0)) / 1e6)) end
     where id = p_run_id and status = 'running';
    return 'ok';
  end if;
  update pipeline.retention_runs
     set removed = removed + greatest(coalesce(p_removed, 0), 0), bytes = bytes + greatest(coalesce(p_bytes, 0), 0), updated_at = now(),
         status = case when p_error is not null then 'failed' when p_finished then 'done' else status end,
         error = coalesce(left(p_error, 500), error),
         finished_at = case when p_error is not null or p_finished then now() else finished_at end,
         note = case when p_error is not null then 'Failed while removing files.' when p_finished then format('Done: %s files removed (%s MB).', removed + greatest(coalesce(p_removed, 0), 0), round((bytes + greatest(coalesce(p_bytes, 0), 0)) / 1e6))
                     else format('Removing files: %s so far (%s MB).', removed + greatest(coalesce(p_removed, 0), 0), round((bytes + greatest(coalesce(p_bytes, 0), 0)) / 1e6)) end
   where id = p_run_id and status = 'running';
  if p_finished then perform security.retention_estimate_v1('adapter_screenshots'); end if;
  return 'ok';
end $$;


ALTER FUNCTION "public"."svc_retention_files_done"("p_run_id" "uuid", "p_removed" integer, "p_bytes" bigint, "p_finished" boolean, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_retention_files_next"("p_run_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cat text; v_out jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select category into v_cat from pipeline.retention_runs where id = p_run_id and status = 'running';
  if v_cat = 'adapter_screenshots' then
    return coalesce((select jsonb_agg(jsonb_build_object('name', o.name, 'size', (o.metadata->>'size')::bigint, 'bucket', 'adapter-captures'))
                       from (select name, metadata from storage.objects where bucket_id = 'adapter-captures' and created_at < now() - interval '7 days' order by created_at limit least(greatest(p_limit, 1), 200)) o), '[]'::jsonb);
  elsif v_cat = 'evidence_unreferenced' then
    with h as (
      update pipeline.retention_file_queue q set status = 'handed', handed_at = now()
       where q.id in (select id from pipeline.retention_file_queue where run_id = p_run_id and status = 'queued' order by id limit least(greatest(p_limit, 1), 200))
      returning q.name, q.size, q.bucket)
    select coalesce(jsonb_agg(jsonb_build_object('name', name, 'size', size, 'bucket', bucket)), '[]'::jsonb) into v_out from h;
    return v_out;
  end if;
  return '[]'::jsonb;
end $$;


ALTER FUNCTION "public"."svc_retention_files_next"("p_run_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_rule6_done"("p_results" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  update pipeline.rule6_page_checks c
     set codes = coalesce(array(select jsonb_array_elements_text(x->'codes')), '{}'), error = left(x->>'error', 300), checked_at = now(),
         found = case when x->>'error' is null then c.course_code is not null and upper(c.course_code) = any(array(select upper(jsonb_array_elements_text(x->'codes')))) end
    from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) x
   where c.course_id = (x->>'course_id')::uuid;
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "public"."svc_rule6_done"("p_results" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_rule6_next"("p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('course_id', course_id, 'storage_path', storage_path))
                     from (select course_id, storage_path from pipeline.rule6_page_checks where checked_at is null and storage_path is not null
                            order by listed_at, course_id limit least(greatest(p_limit, 1), 50)) x), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."svc_rule6_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_apply_records"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_records" "jsonb", "p_mode" "text" DEFAULT 'apply'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r jsonb;
  cyc jsonb;
  win jsonb;
  sc jsonb;
  grp jsonb;
  crt jsonb;
  tier jsonb;
  cov jsonb;
  v_source_key text;
  v_identifier_scheme text;
  v_source_record_id text;
  v_stable_key text;
  v_entity_id uuid;
  v_scholarship_id uuid;
  v_provider_id uuid;
  v_cycle_id uuid;
  v_group_id uuid;
  v_parent_group_id uuid;
  v_target_id uuid;
  v_country_id uuid;
  v_seen int := 0;
  v_changed int := 0;
  v_unmapped int := 0;
  v_cycles int := 0;
  v_windows int := 0;
  v_scopes int := 0;
  v_groups int := 0;
  v_criteria int := 0;
  v_tiers int := 0;
  v_coverage int := 0;
begin
  if auth.role() <> 'service_role' then raise exception 'service_role required'; end if;
  if p_mode not in ('dry_run','apply') then raise exception 'mode must be dry_run or apply'; end if;
  if jsonb_typeof(p_records) <> 'array' then raise exception 'records must be JSON array'; end if;

  select metadata->>'scholarship_source_key' into v_source_key
  from pipeline.sources where id=p_source_id;
  if nullif(v_source_key,'') is null then raise exception 'scholarship source not prepared'; end if;

  for r in select value from jsonb_array_elements(p_records)
  loop
    v_seen := v_seen + 1;
    v_source_record_id := nullif(btrim(r->>'source_record_id'),'');
    v_identifier_scheme := coalesce(nullif(btrim(r->>'identifier_scheme'),''), v_source_key || '_id');
    if v_source_record_id is null then raise exception 'source_record_id required'; end if;
    if nullif(btrim(r->>'name'),'') is null then raise exception 'scholarship name required for %',v_source_record_id; end if;

    v_provider_id := null;
    if nullif(btrim(r->>'provider_cricos'),'') is not null then
      select public.svc_scholarship_resolve_au_provider(r->>'provider_cricos') into v_provider_id;
      if v_provider_id is null then v_unmapped := v_unmapped + 1; end if;
    end if;

    if p_mode='dry_run' then
      continue;
    end if;

    select scholarship_id into v_scholarship_id
    from scholarship.identifiers
    where source_id=p_source_id and scheme=v_identifier_scheme and identifier_value=v_source_record_id
    limit 1;

    if v_scholarship_id is null then
      v_stable_key := 'scholarship:AU:' || v_source_key || ':' || lower(v_source_record_id);
      v_entity_id := scholarship.deterministic_uuid(v_stable_key);

      insert into pim.entity_registry(id,entity_type,stable_key,lifecycle_status)
      values(v_entity_id,'scholarship',v_stable_key,'active')
      on conflict(stable_key) do update set updated_at=now()
      returning id into v_scholarship_id;
    else
      select stable_key into v_stable_key from scholarship.scholarships where id=v_scholarship_id;
      if v_stable_key is null then v_stable_key := 'scholarship:AU:' || v_source_key || ':' || lower(v_source_record_id); end if;
      update pim.entity_registry set lifecycle_status='active',updated_at=now() where id=v_scholarship_id;
    end if;

    insert into scholarship.scholarships(
      id,stable_key,provider_id,name,scholarship_type,description,audience,award_value_text,
      application_required,application_open_date,application_close_date,academic_year,source_url,
      lifecycle_status,publication_status,source_id,evidence_id,confidence,updated_at
    ) values (
      v_scholarship_id,v_stable_key,v_provider_id,r->>'name',r->>'scholarship_type',r->>'description',
      r->>'audience',r->>'award_value_text',coalesce((r->>'application_required')::boolean,true),
      nullif(r->>'application_open_date','')::date,nullif(r->>'application_close_date','')::date,
      nullif(r->>'academic_year','')::int,r->>'source_url','active','unpublished',p_source_id,p_evidence_id,
      coalesce(nullif(r->>'confidence','')::numeric,1.0),now()
    )
    on conflict(id) do update set
      provider_id=excluded.provider_id,
      name=excluded.name,
      scholarship_type=excluded.scholarship_type,
      description=excluded.description,
      audience=excluded.audience,
      award_value_text=excluded.award_value_text,
      application_required=excluded.application_required,
      application_open_date=excluded.application_open_date,
      application_close_date=excluded.application_close_date,
      academic_year=excluded.academic_year,
      source_url=excluded.source_url,
      lifecycle_status='active',
      source_id=excluded.source_id,
      evidence_id=excluded.evidence_id,
      confidence=excluded.confidence,
      updated_at=now();

    insert into scholarship.identifiers(id,scholarship_id,scheme,identifier_value,source_id,evidence_id,is_primary,status)
    values(
      scholarship.deterministic_uuid(v_stable_key || ':identifier:' || v_identifier_scheme || ':' || v_source_record_id),
      v_scholarship_id,v_identifier_scheme,v_source_record_id,p_source_id,p_evidence_id,true,'active'
    )
    on conflict(source_id,scheme,identifier_value) do update set
      scholarship_id=excluded.scholarship_id,evidence_id=excluded.evidence_id,is_primary=true,status='active';

    for cyc in select value from jsonb_array_elements(coalesce(r->'cycles','[]'::jsonb))
    loop
      if nullif(btrim(cyc->>'cycle_code'),'') is null then raise exception 'cycle_code required'; end if;
      v_cycle_id := scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code'));
      insert into scholarship.offering_cycles(
        id,scholarship_id,cycle_code,academic_year,intake_label,valid_from,valid_to,status,source_id,evidence_id,metadata
      ) values (
        v_cycle_id,v_scholarship_id,cyc->>'cycle_code',nullif(cyc->>'academic_year','')::int,cyc->>'intake_label',
        nullif(cyc->>'valid_from','')::date,nullif(cyc->>'valid_to','')::date,coalesce(cyc->>'status','active'),
        p_source_id,p_evidence_id,coalesce(cyc->'metadata','{}'::jsonb)
      )
      on conflict(scholarship_id,cycle_code) do update set
        academic_year=excluded.academic_year,intake_label=excluded.intake_label,valid_from=excluded.valid_from,
        valid_to=excluded.valid_to,status=excluded.status,source_id=excluded.source_id,evidence_id=excluded.evidence_id,
        metadata=excluded.metadata;
      v_cycles := v_cycles + 1;

      for win in select value from jsonb_array_elements(coalesce(cyc->'windows','[]'::jsonb))
      loop
        if nullif(btrim(win->>'window_key'),'') is null then raise exception 'window_key required'; end if;
        insert into scholarship.application_windows(
          id,scholarship_id,cycle_id,round_code,label,opens_at,closes_at,application_method,application_url,status,
          source_id,evidence_id,metadata
        ) values (
          scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':window:' || (win->>'window_key')),
          v_scholarship_id,v_cycle_id,win->>'round_code',win->>'label',nullif(win->>'opens_at','')::timestamptz,
          nullif(win->>'closes_at','')::timestamptz,win->>'application_method',win->>'application_url',
          coalesce(win->>'status','unknown'),p_source_id,p_evidence_id,coalesce(win->'metadata','{}'::jsonb)
        )
        on conflict(id) do update set
          round_code=excluded.round_code,label=excluded.label,opens_at=excluded.opens_at,closes_at=excluded.closes_at,
          application_method=excluded.application_method,application_url=excluded.application_url,status=excluded.status,
          source_id=excluded.source_id,evidence_id=excluded.evidence_id,metadata=excluded.metadata;
        v_windows := v_windows + 1;
      end loop;

      for sc in select value from jsonb_array_elements(coalesce(cyc->'scopes','[]'::jsonb))
      loop
        if nullif(btrim(sc->>'scope_key'),'') is null then raise exception 'scope_key required'; end if;
        v_target_id := null;
        if sc->>'scope_type'='provider' then
          if nullif(sc->>'target_code','') is not null then
            select public.svc_scholarship_resolve_au_provider(sc->>'target_code') into v_target_id;
          else v_target_id := v_provider_id;
          end if;
        elsif sc->>'scope_type'='study_level' then
          select id into v_target_id from ref.study_levels where code=sc->>'target_code' and status='active' limit 1;
        elsif sc->>'scope_type'='country' then
          select id into v_target_id from ref.countries where iso_alpha2=upper(sc->>'target_code') limit 1;
        elsif sc->>'scope_type' <> 'global' then
          raise exception 'unsupported v1 scope type %',sc->>'scope_type';
        end if;
        if sc->>'scope_type' <> 'global' and v_target_id is null then
          raise exception 'unresolved scope % target %',sc->>'scope_type',sc->>'target_code';
        end if;

        insert into scholarship.scopes(
          id,scholarship_id,scope_type,provider_id,study_level_id,country_id,include_exclude,source_id,evidence_id,cycle_id
        ) values (
          scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':scope:' || (sc->>'scope_key')),
          v_scholarship_id,sc->>'scope_type',case when sc->>'scope_type'='provider' then v_target_id end,
          case when sc->>'scope_type'='study_level' then v_target_id end,
          case when sc->>'scope_type'='country' then v_target_id end,
          coalesce(sc->>'include_exclude','include'),p_source_id,p_evidence_id,v_cycle_id
        ) on conflict(id) do update set
          provider_id=excluded.provider_id,study_level_id=excluded.study_level_id,country_id=excluded.country_id,
          include_exclude=excluded.include_exclude,source_id=excluded.source_id,evidence_id=excluded.evidence_id,cycle_id=excluded.cycle_id;
        v_scopes := v_scopes + 1;
      end loop;

      for grp in select value from jsonb_array_elements(coalesce(cyc->'criterion_groups','[]'::jsonb))
      loop
        if nullif(btrim(grp->>'group_code'),'') is null then raise exception 'group_code required'; end if;
        v_parent_group_id := null;
        if nullif(btrim(grp->>'parent_group_code'),'') is not null then
          v_parent_group_id := scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':group:' || (grp->>'parent_group_code'));
        end if;
        v_group_id := scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':group:' || (grp->>'group_code'));
        insert into scholarship.criterion_groups(
          id,scholarship_id,cycle_id,parent_group_id,group_code,label,conjunction,is_mandatory,display_order,source_id,evidence_id
        ) values (
          v_group_id,v_scholarship_id,v_cycle_id,v_parent_group_id,grp->>'group_code',grp->>'label',
          coalesce(grp->>'conjunction','all'),coalesce((grp->>'is_mandatory')::boolean,true),
          coalesce(nullif(grp->>'display_order','')::int,0),p_source_id,p_evidence_id
        )
        on conflict(scholarship_id,group_code) do update set
          cycle_id=excluded.cycle_id,parent_group_id=excluded.parent_group_id,label=excluded.label,
          conjunction=excluded.conjunction,is_mandatory=excluded.is_mandatory,display_order=excluded.display_order,
          source_id=excluded.source_id,evidence_id=excluded.evidence_id;
        v_groups := v_groups + 1;
      end loop;

      for crt in select value from jsonb_array_elements(coalesce(cyc->'criteria','[]'::jsonb))
      loop
        if nullif(btrim(crt->>'criterion_key'),'') is null then raise exception 'criterion_key required'; end if;
        v_group_id := null;
        if nullif(btrim(crt->>'group_code'),'') is not null then
          v_group_id := scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':group:' || (crt->>'group_code'));
        end if;
        insert into scholarship.criteria(
          id,scholarship_id,criterion_type,operator,value_text,value_number,value_codes,value_json,human_text,
          is_mandatory,machine_evaluable,status,source_id,evidence_id,confidence,cycle_id,criterion_group_id
        ) values (
          scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':criterion:' || (crt->>'criterion_key')),
          v_scholarship_id,crt->>'criterion_type',crt->>'operator',crt->>'value_text',nullif(crt->>'value_number','')::numeric,
          case when jsonb_typeof(crt->'value_codes')='array' then array(select jsonb_array_elements_text(crt->'value_codes')) else null end,
          crt->'value_json',crt->>'human_text',coalesce((crt->>'is_mandatory')::boolean,true),
          coalesce((crt->>'machine_evaluable')::boolean,false),coalesce(crt->>'status','active'),p_source_id,p_evidence_id,
          coalesce(nullif(crt->>'confidence','')::numeric,1.0),v_cycle_id,v_group_id
        ) on conflict(id) do update set
          criterion_type=excluded.criterion_type,operator=excluded.operator,value_text=excluded.value_text,
          value_number=excluded.value_number,value_codes=excluded.value_codes,value_json=excluded.value_json,
          human_text=excluded.human_text,is_mandatory=excluded.is_mandatory,machine_evaluable=excluded.machine_evaluable,
          status=excluded.status,source_id=excluded.source_id,evidence_id=excluded.evidence_id,confidence=excluded.confidence,
          cycle_id=excluded.cycle_id,criterion_group_id=excluded.criterion_group_id;
        v_criteria := v_criteria + 1;
      end loop;

      for tier in select value from jsonb_array_elements(coalesce(cyc->'award_tiers','[]'::jsonb))
      loop
        if nullif(btrim(tier->>'tier_code'),'') is null then raise exception 'tier_code required'; end if;
        insert into scholarship.award_tiers(
          id,scholarship_id,tier_code,label,amount,currency_code,percentage,basis,maximum_amount,notes,display_order,
          cycle_id,source_id,evidence_id
        ) values (
          scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':tier:' || (tier->>'tier_code')),
          v_scholarship_id,tier->>'tier_code',tier->>'label',nullif(tier->>'amount','')::numeric,tier->>'currency_code',
          nullif(tier->>'percentage','')::numeric,tier->>'basis',nullif(tier->>'maximum_amount','')::numeric,tier->>'notes',
          coalesce(nullif(tier->>'display_order','')::int,0),v_cycle_id,p_source_id,p_evidence_id
        ) on conflict(id) do update set
          label=excluded.label,amount=excluded.amount,currency_code=excluded.currency_code,percentage=excluded.percentage,
          basis=excluded.basis,maximum_amount=excluded.maximum_amount,notes=excluded.notes,display_order=excluded.display_order,
          cycle_id=excluded.cycle_id,source_id=excluded.source_id,evidence_id=excluded.evidence_id;
        v_tiers := v_tiers + 1;
      end loop;

      for cov in select value from jsonb_array_elements(coalesce(cyc->'coverage','[]'::jsonb))
      loop
        if nullif(btrim(cov->>'coverage_key'),'') is null then raise exception 'coverage_key required'; end if;
        insert into scholarship.coverage(
          id,scholarship_id,coverage_type,percentage,amount,currency_code,duration_value,duration_unit,notes,
          source_id,evidence_id,cycle_id
        ) values (
          scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':coverage:' || (cov->>'coverage_key')),
          v_scholarship_id,cov->>'coverage_type',nullif(cov->>'percentage','')::numeric,nullif(cov->>'amount','')::numeric,
          cov->>'currency_code',nullif(cov->>'duration_value','')::numeric,cov->>'duration_unit',cov->>'notes',
          p_source_id,p_evidence_id,v_cycle_id
        ) on conflict(id) do update set
          coverage_type=excluded.coverage_type,percentage=excluded.percentage,amount=excluded.amount,
          currency_code=excluded.currency_code,duration_value=excluded.duration_value,duration_unit=excluded.duration_unit,
          notes=excluded.notes,source_id=excluded.source_id,evidence_id=excluded.evidence_id,cycle_id=excluded.cycle_id;
        v_coverage := v_coverage + 1;
      end loop;
    end loop;

    v_changed := v_changed + 1;
  end loop;

  return jsonb_build_object(
    'mode',p_mode,'seen',v_seen,'changed',v_changed,'unmappedProviders',v_unmapped,
    'cycles',v_cycles,'windows',v_windows,'scopes',v_scopes,'criterionGroups',v_groups,
    'criteria',v_criteria,'awardTiers',v_tiers,'coverage',v_coverage
  );
end
$$;


ALTER FUNCTION "public"."svc_scholarship_apply_records"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_records" "jsonb", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_candidate_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  with ranked as (
    select c.id, d.priority, row_number() over (partition by c.provider_id order by (c.url ~* 'international') desc, c.found_at, c.id) rn
      from pipeline.scholarship_page_candidates c join pipeline.scholarship_discovery_providers d on d.provider_id=c.provider_id and d.priority in (0,1,3,4)
     where c.matched_scholarship_id is null and c.admit_status is null and c.next_read_at<=now() and coalesce(c.leased_until,'-infinity')<now() and c.attempts<3),
  pick as (
    select c.id from pipeline.scholarship_page_candidates c join ranked r on r.id=c.id
     -- re-checked on the locked row, so concurrent readers never take the same page
     where coalesce(c.leased_until,'-infinity')<now() and c.admit_status is null and c.matched_scholarship_id is null and c.next_read_at<=now()
     order by r.rn, (r.priority not in (0,3)), c.id
     limit greatest(1,least(coalesce(p_limit,30),60)) for update of c skip locked),
  upd as (update pipeline.scholarship_page_candidates c set leased_until=now()+interval '5 minutes', attempts=c.attempts+1 from pick where c.id=pick.id
          returning c.id, c.url, c.provider_id)
  select coalesce(jsonb_agg(jsonb_build_object('candidate_id',u.id,'url',u.url,'provider_id',u.provider_id,'currency',scholarship.provider_currency(u.provider_id),
           'site',(select coalesce(site_origin,website) from pipeline.scholarship_discovery_providers d where d.provider_id=u.provider_id),
           'hosts',(select to_jsonb(allowed_hosts) from pipeline.scholarship_discovery_providers d where d.provider_id=u.provider_id))),'[]'::jsonb)
    into v from upd u;
  return v;
end $$;


ALTER FUNCTION "public"."svc_scholarship_candidate_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_candidate_record"("p_candidate_id" bigint, "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_final_url" "text", "p_storage_path" "text", "p_sha256" "text", "p_facts" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare r jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  if p_read_status='deferred' then -- out of time in this run: back to the queue unchanged
    update pipeline.scholarship_page_candidates set leased_until=null, attempts=greatest(0,attempts-1) where id=p_candidate_id;
    return jsonb_build_object('admitted',false,'deferred',true);
  end if;
  update pipeline.scholarship_page_candidates set read_status=p_read_status, http_status=p_http_status, fetched_via=p_fetched_via, final_url=p_final_url,
         read_at=now(), leased_until=null, storage_path=coalesce(p_storage_path,storage_path), content_hash=coalesce(p_sha256,content_hash), facts=coalesce(p_facts,facts),
         next_read_at=case when p_read_status in ('read','robots_disallowed','gone') then now()+interval '90 days' else now()+interval '6 hours' end,
         admit_status=case when p_read_status='read' and coalesce((p_facts->'admission'->>'admit')::boolean,false) is not true then 'rejected' else admit_status end,
         admit_reasons=case when p_read_status='read' and coalesce((p_facts->'admission'->>'admit')::boolean,false) is not true
                            then array(select jsonb_array_elements_text(coalesce(p_facts->'admission'->'reasons','[]'))) else admit_reasons end
   where id=p_candidate_id;
  if p_read_status='read' and coalesce((p_facts->'admission'->>'admit')::boolean,false) then r:=security.scholarship_admit_from_provider_page_v1(p_candidate_id); end if;
  return coalesce(r, jsonb_build_object('admitted',false));
end $$;


ALTER FUNCTION "public"."svc_scholarship_candidate_record"("p_candidate_id" bigint, "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_final_url" "text", "p_storage_path" "text", "p_sha256" "text", "p_facts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_discover_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select d.provider_id from pipeline.scholarship_discovery_providers d
     where d.status='pending' and coalesce(d.leased_until,'-infinity')<now() and d.attempts<3
     order by d.priority, d.provider_id limit greatest(1,least(coalesce(p_limit,3),6)) for update skip locked),
  upd as (update pipeline.scholarship_discovery_providers d set leased_until=now()+interval '5 minutes', attempts=d.attempts+1, updated_at=now()
            from pick where d.provider_id=pick.provider_id returning d.provider_id, d.website, d.reason, d.allowed_hosts)
  select coalesce(jsonb_agg(jsonb_build_object('provider_id',u.provider_id,'website',u.website,'reason',u.reason,'hosts',to_jsonb(u.allowed_hosts),
           'names',security.provider_name_list(u.provider_id),'held',security.scholarship_held_without_page(u.provider_id))),'[]'::jsonb) into v from upd u;
  return v;
end $$;


ALTER FUNCTION "public"."svc_scholarship_discover_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_discover_record"("p_provider_id" "uuid", "p_status" "text", "p_site_origin" "text", "p_method" "text", "p_url_count" integer, "p_candidates" "jsonb", "p_matches" "jsonb", "p_error" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_kept int; v_matched int:=0; m jsonb; r jsonb; v_cid bigint;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.scholarship_page_candidates(provider_id,url,url_norm,title,source)
  select p_provider_id, c->>'url', security.scholarship_url_norm(c->>'url'), nullif(left(c->>'title',300),''), coalesce(c->>'source','sitemap')
    from jsonb_array_elements(coalesce(p_candidates,'[]')) c
   where coalesce(c->>'url','') ~* '^https?://' and (security.url_on_provider_sites(c->>'url', p_provider_id) or security.url_on_provider_site(c->>'url', p_site_origin))
  on conflict (provider_id,url_norm) do update set title=coalesce(pipeline.scholarship_page_candidates.title, excluded.title);
  select count(*) into v_kept from pipeline.scholarship_page_candidates where provider_id=p_provider_id;
  update pipeline.scholarship_discovery_providers set status=p_status, site_origin=coalesce(p_site_origin,site_origin), method=p_method, url_count=p_url_count,
         kept_count=v_kept, discovered_at=now(), leased_until=null, last_error=p_error, updated_at=now() where provider_id=p_provider_id;
  for m in select * from jsonb_array_elements(coalesce(p_matches,'[]')) loop
    select id into v_cid from pipeline.scholarship_page_candidates where provider_id=p_provider_id and url_norm=security.scholarship_url_norm(m->>'url');
    if v_cid is null then continue; end if;
    if (select provider_id from scholarship.scholarships where id=(m->>'scholarship_id')::uuid) is distinct from p_provider_id then continue; end if;
    r:=security.scholarship_page_match_v1((m->>'scholarship_id')::uuid, m->>'url', m->>'basis', v_cid);
    if (r->>'matched')::boolean then v_matched:=v_matched+1; end if;
  end loop;
  update pipeline.scholarship_discovery_providers set matched_count=coalesce(matched_count,0)+v_matched where provider_id=p_provider_id;
  return jsonb_build_object('kept',v_kept,'matched',v_matched);
end $$;


