CREATE OR REPLACE FUNCTION "public"."svc_scholarship_prepare_source"("p_source_key" "text", "p_label" "text", "p_url" "text", "p_source_type" "text" DEFAULT 'scholarship_catalogue'::"text", "p_trust_rank" smallint DEFAULT 95, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_country uuid;
  v_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role required';
  end if;
  if nullif(btrim(p_source_key),'') is null or nullif(btrim(p_url),'') is null then
    raise exception 'source key and url required';
  end if;

  select id into v_country from ref.countries where iso_alpha2='AU';
  if v_country is null then raise exception 'AU country missing'; end if;

  select id into v_id
  from pipeline.sources
  where metadata->>'scholarship_source_key'=p_source_key
  limit 1;

  if v_id is null then
    insert into pipeline.sources(source_type,country_id,url,label,trust_rank,status,metadata)
    values (
      p_source_type,v_country,p_url,p_label,p_trust_rank,'active',
      coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object(
        'layer','2A',
        'domain','scholarship',
        'scholarship_source_key',p_source_key,
        'identity_authority',false
      )
    )
    returning id into v_id;
  else
    update pipeline.sources
       set source_type=p_source_type,
           url=p_url,
           label=p_label,
           trust_rank=p_trust_rank,
           status='active',
           metadata=metadata || coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object(
             'layer','2A','domain','scholarship','scholarship_source_key',p_source_key,'identity_authority',false
           ),
           updated_at=now()
     where id=v_id;
  end if;
  return v_id;
end
$$;


ALTER FUNCTION "public"."svc_scholarship_prepare_source"("p_source_key" "text", "p_label" "text", "p_url" "text", "p_source_type" "text", "p_trust_rank" smallint, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_read_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select p.scholarship_id from pipeline.scholarship_pages p join scholarship.scholarships s on s.id=p.scholarship_id and s.lifecycle_status='active'
     where p.next_read_at<=now() and coalesce(p.leased_until,'-infinity')<now() and p.attempts<5
     order by p.read_at nulls first limit greatest(1,least(coalesce(p_limit,20),40)) for update of p skip locked),
  upd as (update pipeline.scholarship_pages p set leased_until=now()+interval '10 minutes', attempts=p.attempts+1 from pick where p.scholarship_id=pick.scholarship_id
          returning p.scholarship_id, p.url, p.url_source)
  select coalesce(jsonb_agg(jsonb_build_object('scholarship_id',u.scholarship_id,'url',u.url,'name',s.name,'provider_id',s.provider_id,'currency',scholarship.provider_currency(s.provider_id),'url_source',u.url_source,'names',security.provider_name_list(s.provider_id))),'[]'::jsonb) into v
    from upd u join scholarship.scholarships s on s.id=u.scholarship_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_scholarship_read_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_read_record"("p_scholarship_id" "uuid", "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_final_url" "text", "p_storage_path" "text", "p_sha256" "text", "p_facts" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare v_ev uuid; v_src uuid; v_pid uuid; v_url text; r jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  select s.provider_id, p.url into v_pid, v_url from scholarship.scholarships s join pipeline.scholarship_pages p on p.scholarship_id=s.id where s.id=p_scholarship_id;
  if p_storage_path is not null and p_read_status='read' then
    v_src:=security.coverage_sweep_source(v_pid);
    -- unchanged page: reuse its evidence; changed page: next capture version, superseding the previous one
    select e.id into v_ev from pipeline.evidence_artifacts e where e.evidence_group_key='scholarship:'||p_scholarship_id and e.content_hash=p_sha256 order by e.capture_version desc limit 1;
    if v_ev is null then
      insert into pipeline.evidence_artifacts(entity_id,source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata,capture_version,evidence_group_key,supersedes_evidence_id)
      select p_scholarship_id, v_src, 'scholarship_page', coalesce(p_final_url,v_url), p_storage_path, p_sha256, 'application/gzip',
             jsonb_build_object('worker','coverage-sweep scholarship_read','decision','Decision 139 sweep'),
             coalesce((select max(e.capture_version) from pipeline.evidence_artifacts e where e.evidence_group_key='scholarship:'||p_scholarship_id),0)+1,
             'scholarship:'||p_scholarship_id,
             (select e.id from pipeline.evidence_artifacts e where e.evidence_group_key='scholarship:'||p_scholarship_id order by e.capture_version desc limit 1)
      returning id into v_ev;
    end if;
  end if;
  update pipeline.scholarship_pages set read_status=p_read_status, http_status=p_http_status, fetched_via=p_fetched_via, final_url=p_final_url,
         read_at=now(), leased_until=null, evidence_id=case when p_read_status='read' then coalesce(v_ev,evidence_id) else evidence_id end,
         facts=case when p_read_status='read' then coalesce(p_facts,facts) else facts end,
         name_check=case when p_facts ? 'name_check' then p_facts->'name_check' else name_check end,
         next_read_at=case when p_read_status='read' then now()+interval '90 days' when p_read_status in ('robots_disallowed','blocked','name_mismatch') then now()+interval '30 days' else now()+interval '6 hours' end,
         attempts=case when p_read_status='read' then 0 else attempts end
   where scholarship_id=p_scholarship_id;
  -- an admitted page that no longer meets the admission rules is withdrawn, not applied
  if p_read_status='read' and p_facts ? 'admission' and coalesce((p_facts->'admission'->>'admit')::boolean,true) is false
     and exists (select 1 from pipeline.scholarship_pages where scholarship_id=p_scholarship_id and url_source='admitted') then
    r:=security.scholarship_admission_withdraw_v1(p_scholarship_id, jsonb_build_object('reasons',p_facts->'admission'->'reasons','extractor',p_facts->>'extractor'));
  elsif p_read_status='read' then r:=security.scholarship_sweep_apply_v1(p_scholarship_id); end if;
  -- a discovered page that does not name the scholarship: the match is released (logged) so another page can be tried
  if p_read_status='name_mismatch' then
    update pipeline.scholarship_page_candidates c set match_basis='rejected_name_mismatch', matched_scholarship_id=null
      from pipeline.scholarship_pages sp where sp.scholarship_id=p_scholarship_id and sp.url_source='discovered' and c.id=sp.candidate_id;
    insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value)
    select p_scholarship_id,'provider_page_rejected',jsonb_build_object('url',sp.url,'url_source',sp.url_source),p_facts->'name_check' from pipeline.scholarship_pages sp where sp.scholarship_id=p_scholarship_id;
  end if;
  return coalesce(r,jsonb_build_object('applied',false));
end $$;


ALTER FUNCTION "public"."svc_scholarship_read_record"("p_scholarship_id" "uuid", "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_final_url" "text", "p_storage_path" "text", "p_sha256" "text", "p_facts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_reextract_next"("p_limit" integer, "p_version" "text") RETURNS TABLE("scholarship_id" "uuid", "storage_path" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return query
    select sp.scholarship_id, e.storage_path
      from pipeline.scholarship_pages sp
      join scholarship.scholarships s on s.id = sp.scholarship_id and s.lifecycle_status = 'active'
      join pipeline.evidence_artifacts e on e.id = sp.evidence_id and e.storage_path is not null
     where sp.read_status = 'read' and sp.facts is not null
       and coalesce(sp.facts->>'criteria_extractor', '') is distinct from p_version
       and coalesce(sp.facts->>'extractor', '') is distinct from p_version
     order by s.publication_status = 'published' desc, sp.scholarship_id
     limit greatest(1, least(p_limit, 300));
end $$;


ALTER FUNCTION "public"."svc_scholarship_reextract_next"("p_limit" integer, "p_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_reextract_record"("p_scholarship_id" "uuid", "p_facts" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v text[];
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  update pipeline.scholarship_pages
     set facts = facts || jsonb_build_object('criteria', coalesce(p_facts->'criteria', '[]'), 'award_scope', p_facts->'award_scope', 'criteria_extractor', p_facts->>'criteria_extractor')
   where scholarship_id = p_scholarship_id and read_status = 'read' and facts is not null;
  v := security.scholarship_criteria_apply_v1(p_scholarship_id);
  return jsonb_build_object('changes', to_jsonb(v));
end $$;


ALTER FUNCTION "public"."svc_scholarship_reextract_record"("p_scholarship_id" "uuid", "p_facts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_register_detail_next"("p_register" "text", "p_limit" integer DEFAULT 40) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then null else
  jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object('id', x.listing_id, 'url', x.url, 'provider_ref', x.provider_ref,
                 'known_cricos', (select max(o.provider_cricos) from scholarship.register_listings o
                                   where o.register_code = x.register_code and o.provider_ref = x.provider_ref and o.provider_cricos is not null)))
               from (select l.* from scholarship.register_listings l
                      where l.register_code = p_register and l.departed_at is null
                        and (l.detail_read_at is null or l.detail_hash is distinct from l.content_hash)
                      order by (l.scholarship_id is not null), l.first_seen_at, l.listing_id
                      limit greatest(1, least(coalesce(p_limit, 40), 100))) x), '[]'::jsonb),
    'remaining', (select count(*) from scholarship.register_listings l
                   where l.register_code = p_register and l.departed_at is null
                     and (l.detail_read_at is null or l.detail_hash is distinct from l.content_hash))) end
$$;


ALTER FUNCTION "public"."svc_scholarship_register_detail_next"("p_register" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_register_detail_save"("p_register" "text", "p_evidence_id" "uuid", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_saved int := 0; v_remaining bigint; v_match jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
  update scholarship.register_listings l
     set website_url = case when nullif(x->>'error','') is null then nullif(x->>'website_url','') else l.website_url end,
         detail_error = nullif(left(x->>'error', 300),''),
         provider_cricos = coalesce(upper(nullif(x->>'provider_cricos','')), l.provider_cricos),
         provider_id = coalesce(public.svc_scholarship_resolve_au_provider(coalesce(upper(nullif(x->>'provider_cricos','')), l.provider_cricos)), l.provider_id),
         detail_read_at = now(), detail_hash = l.content_hash, detail_evidence_id = p_evidence_id
    from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) x
   where l.register_code = p_register and l.listing_id = x->>'id';
  get diagnostics v_saved = row_count;
  v_match := public.svc_scholarship_register_match(p_register);
  select count(*) into v_remaining from scholarship.register_listings l
   where l.register_code = p_register and l.departed_at is null and (l.detail_read_at is null or l.detail_hash is distinct from l.content_hash);
  return jsonb_build_object('saved', v_saved, 'remaining', v_remaining, 'match', v_match);
end $$;


ALTER FUNCTION "public"."svc_scholarship_register_detail_save"("p_register" "text", "p_evidence_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_register_evidence"("p_source_id" "uuid", "p_source_url" "text", "p_storage_path" "text", "p_content_hash" "text", "p_mime_type" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  if auth.role() <> 'service_role' then raise exception 'service_role required'; end if;
  select id into v_id
  from pipeline.evidence_artifacts
  where source_id=p_source_id
    and content_hash=p_content_hash
    and coalesce(source_url,'')=coalesce(p_source_url,'')
  order by captured_at desc limit 1;

  if v_id is null then
    insert into pipeline.evidence_artifacts(
      source_id,evidence_type,source_url,storage_path,content_hash,mime_type,captured_at,metadata
    ) values (
      p_source_id,'source_snapshot',p_source_url,p_storage_path,p_content_hash,p_mime_type,now(),
      coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('layer','2A','domain','scholarship')
    ) returning id into v_id;
  end if;
  return v_id;
end
$$;


ALTER FUNCTION "public"."svc_scholarship_register_evidence"("p_source_id" "uuid", "p_source_url" "text", "p_storage_path" "text", "p_content_hash" "text", "p_mime_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_register_match"("p_register" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id int := 0; v_page int := 0; v_name int := 0; v_handed int := 0; v_offsite int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
  update scholarship.register_listings l set scholarship_id = s.id, match_basis = 'register_id_in_source_url'
    from scholarship.scholarships s
   where l.register_code = p_register and l.scholarship_id is null
     and strpos(s.source_url, l.listing_id) > 0;
  get diagnostics v_id = row_count;
  update scholarship.register_listings l set scholarship_id = m.sid, match_basis = 'provider_page_address'
    from (select distinct on (l2.listing_id) l2.listing_id, coalesce(p.scholarship_id, s.id) sid
            from scholarship.register_listings l2
            left join pipeline.scholarship_pages p on security.scholarship_url_norm(coalesce(p.final_url, p.url)) = security.scholarship_url_norm(l2.website_url)
            left join scholarship.scholarships s on security.scholarship_url_norm(s.source_url) = security.scholarship_url_norm(l2.website_url)
           where l2.register_code = p_register and l2.scholarship_id is null and l2.website_url is not null
             and coalesce(p.scholarship_id, s.id) is not null) m
   where l.register_code = p_register and l.listing_id = m.listing_id;
  get diagnostics v_page = row_count;
  update scholarship.register_listings l set scholarship_id = m.sid, match_basis = 'provider_and_name'
    from (select l2.listing_id, min(s.id::text)::uuid sid
            from scholarship.register_listings l2
            join scholarship.scholarships s on s.provider_id = l2.provider_id
             and lower(regexp_replace(s.name, '[^[:alnum:]]+', ' ', 'g')) = lower(regexp_replace(l2.name, '[^[:alnum:]]+', ' ', 'g'))
           where l2.register_code = p_register and l2.scholarship_id is null and l2.provider_id is not null
           group by l2.listing_id having count(distinct s.id) = 1) m
   where l.register_code = p_register and l.listing_id = m.listing_id;
  get diagnostics v_name = row_count;

  with todo as (
    select l.listing_id, l.provider_id, l.website_url, l.name,
           security.url_on_provider_sites(l.website_url, l.provider_id) on_site
      from scholarship.register_listings l
      join scholarship.registers r on r.code = l.register_code and r.role = 'index'
     where l.register_code = p_register and l.scholarship_id is null and l.departed_at is null
       and l.provider_id is not null and l.website_url ~* '^https?://' and l.candidate_id is null
  ), ins as (
    insert into pipeline.scholarship_page_candidates(provider_id, url, url_norm, title, source)
    select distinct on (t.provider_id, security.scholarship_url_norm(t.website_url))
           t.provider_id, t.website_url, security.scholarship_url_norm(t.website_url), left(t.name, 300), 'register'
      from todo t where t.on_site
     order by t.provider_id, security.scholarship_url_norm(t.website_url), t.listing_id
    on conflict (provider_id, url_norm) do update set title = coalesce(pipeline.scholarship_page_candidates.title, excluded.title)
    returning id, provider_id, url_norm
  ), mark as (
    update scholarship.register_listings l
       set candidate_id = i.id, handoff_status = 'handed_to_page_reader'
      from ins i
     where l.register_code = p_register and l.provider_id = i.provider_id
       and security.scholarship_url_norm(l.website_url) = i.url_norm and l.candidate_id is null
    returning 1
  ) select count(*) into v_handed from mark;
  update scholarship.register_listings l set handoff_status = 'provider_page_off_provider_site'
   where l.register_code = p_register and l.scholarship_id is null and l.candidate_id is null and l.provider_id is not null
     and l.website_url ~* '^https?://' and not security.url_on_provider_sites(l.website_url, l.provider_id)
     and l.handoff_status is distinct from 'provider_page_off_provider_site';
  get diagnostics v_offsite = row_count;
  update scholarship.register_listings l set handoff_status = 'matched'
   where l.register_code = p_register and l.scholarship_id is not null and l.handoff_status is distinct from 'matched';
  return jsonb_build_object('by_register_id', v_id, 'by_provider_page', v_page, 'by_provider_and_name', v_name,
                            'handed_to_page_reader', v_handed, 'off_provider_site', v_offsite);
end $$;


ALTER FUNCTION "public"."svc_scholarship_register_match"("p_register" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_register_record_profile"("p_register" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r scholarship.registers; v_sid uuid; v_ev uuid; v_payload jsonb; v_names text[]; v_codes text[]; v_unmapped text[];
        v_inst jsonb; v_resolved jsonb := '[]'; v_unresolved jsonb := '[]'; v_providers uuid[]; v_country uuid;
        v_scopes int := 0; v_maps int := 0; v_courses int := 0; i jsonb; v_pid uuid; v_n int; v_out jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into r from scholarship.registers where code = p_register and role = 'record';
  if r.code is null then raise exception 'not a record register: %', p_register; end if;
  select count(*) into v_n from scholarship.scholarships where source_id = r.source_id and lifecycle_status = 'active';
  if v_n <> 1 then raise exception 'register % has % active records; expected 1', p_register, v_n; end if;
  select id, evidence_id into v_sid, v_ev from scholarship.scholarships where source_id = r.source_id and lifecycle_status = 'active';
  select payload into v_payload from pipeline.scholarship_source_records
   where source_id = r.source_id and status = 'applied' order by observed_at desc nulls last, created_at desc limit 1;
  if v_payload is null then raise exception 'register % has no applied source record', p_register; end if;
  select id into v_country from ref.countries where iso_alpha2 = r.country_code;

  -- nationalities: every country the register lists (objects carry "country"; plain lists are text)
  select array_agg(distinct btrim(n)) into v_names from (
    select case when jsonb_typeof(c) = 'object' then c->>'country' else c #>> '{}' end n
      from jsonb_array_elements(v_payload->'cycles'->0->'criteria') cr, jsonb_array_elements(coalesce(cr->'value_json'->'countries','[]')) c
     where cr->>'criterion_type' = 'citizenship_and_residency'
    union all
    select cr->>'value_text' from jsonb_array_elements(v_payload->'cycles'->0->'criteria') cr
     where cr->>'criterion_type' = 'citizenship_and_residency' and cr->>'operator' = 'equals_source_country') q where coalesce(btrim(n),'') <> '';
  select array_agg(distinct x.code order by x.code) into v_codes
    from unnest(coalesce(v_names,'{}')) n join ref.nationality_terms x on not x.region and n ~* ('^(?:the )?(?:' || x.names || ')$');
  select array_agg(n order by n) into v_unmapped from unnest(coalesce(v_names,'{}')) n
   where not exists (select 1 from ref.nationality_terms x where not x.region and n ~* ('^(?:the )?(?:' || x.names || ')$'));
  if coalesce(cardinality(v_names),0) = 0 then raise exception 'register % lists no countries', p_register; end if;
  if coalesce(cardinality(v_unmapped),0) > 0 then raise exception 'register % lists countries without a nationality code: %', p_register, array_to_string(v_unmapped, ', '); end if;
  update scholarship.scholarships set nationalities = v_codes, audience = 'international', updated_at = now()
   where id = v_sid and (nationalities is distinct from v_codes or audience is distinct from 'international');
  insert into scholarship.nationality_readings(scholarship_id, codes, phrases, reader_version, read_at)
  values (v_sid, v_codes, jsonb_build_object('register', p_register, 'countries', to_jsonb(v_names)), 'register:' || p_register, now())
  on conflict (scholarship_id) do update set codes = excluded.codes, phrases = excluded.phrases, reader_version = excluded.reader_version, read_at = now();

  -- institutions named on the register (matched by official website or the site it redirects to), plus any a person picked
  select cr->'value_json' into v_inst from jsonb_array_elements(v_payload->'cycles'->0->'criteria') cr where cr->>'criterion_key' = 'approved_institution' limit 1;
  for i in select x from jsonb_array_elements(coalesce(v_inst->'universities','[]') || coalesce(v_inst->'institutes_of_technology','[]')) x loop
    select array_agg(distinct p.id) into v_providers from catalogue.providers p
     where p.country_id = v_country and p.lifecycle_status = 'active' and p.website is not null
       and security.url_base_host(p.website) in (security.url_base_host(i->>'website'), security.url_base_host(i->>'final_website'));
    if coalesce(cardinality(v_providers),0) = 1 then v_resolved := v_resolved || jsonb_build_object('name', i->>'name', 'provider_id', v_providers[1], 'basis', 'official website');
    else v_unresolved := v_unresolved || jsonb_build_object('name', i->>'name', 'website', i->>'website', 'final_website', i->>'final_website', 'matches', coalesce(cardinality(v_providers),0)); end if;
  end loop;
  select array_agg(distinct pid) into v_providers from (
    select (x->>'provider_id')::uuid pid from jsonb_array_elements(v_resolved) x union select unnest(r.provider_ids)) q;

  with eligible as (
    select c.id course_id from catalogue.courses c left join ref.study_levels sl on sl.id = c.study_level_id
     where c.provider_id = any(coalesce(v_providers,'{}')) and c.lifecycle_status = 'active'
       and (sl.code in ('bachelor','masters','doctorate') or (sl.code in ('diploma','certificate') and c.canonical_title ~* '\mpost ?graduate\M'))),
  sc as (
    insert into scholarship.scopes(scholarship_id, scope_type, course_id, include_exclude, source_id, evidence_id)
    select v_sid, 'course', e.course_id, 'include', r.source_id, v_ev from eligible e
     where not exists (select 1 from scholarship.scopes x where x.scholarship_id = v_sid and x.scope_type = 'course' and x.course_id = e.course_id)
    returning 1),
  mp as (
    insert into scholarship.course_mappings(scholarship_id, course_id, mapping_state, mapping_basis, evidence_id)
    select v_sid, e.course_id, 'mapped', 'explicit_course_scope', v_ev from eligible e
    on conflict (scholarship_id, course_id) do nothing
    returning 1)
  select (select count(*) from eligible), (select count(*) from sc), (select count(*) from mp) into v_courses, v_scopes, v_maps;

  v_out := jsonb_build_object('register', p_register, 'scholarship_id', v_sid, 'nationalities', to_jsonb(v_codes), 'countries', cardinality(v_names),
                              'institutions_resolved', v_resolved, 'institutions_unresolved', v_unresolved, 'picked_providers', to_jsonb(r.provider_ids),
                              'eligible_courses', v_courses, 'course_scopes_added', v_scopes, 'course_links_added', v_maps, 'at', now());
  update scholarship.registers set profile = v_out, updated_at = now() where code = p_register;
  return v_out;
end $_$;


ALTER FUNCTION "public"."svc_scholarship_register_record_profile"("p_register" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_register_save"("p_register" "text", "p_run_id" "uuid", "p_evidence_id" "uuid", "p_listings" "jsonb", "p_final" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_country char(2); v_created int := 0; v_updated int := 0; v_unchanged int := 0; v_departed int := 0; v_match jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if;
  select country_code into v_country from scholarship.registers where code = p_register;
  if v_country is null then raise exception 'unknown register %', p_register; end if;
  with src as (
    select x->>'id' listing_id, x->>'url' url, x->>'name' name, x->>'provider_ref' provider_ref, x->>'provider_name' provider_name,
           nullif(x->>'level','') level_text, nullif(x->>'award','') award_text, nullif(x->>'closing','') closing_text, nullif(x->>'nationality','') nationality_text,
           md5(concat_ws('|', x->>'name', x->>'provider_ref', x->>'provider_name', x->>'level', x->>'award', x->>'closing', x->>'nationality')) h
      from jsonb_array_elements(coalesce(p_listings,'[]'::jsonb)) x
     where coalesce(x->>'id','') <> '' and coalesce(x->>'name','') <> '' and coalesce(x->>'url','') <> ''
  ), up as (
    insert into scholarship.register_listings as l(register_code, listing_id, country_code, url, name, provider_ref, provider_name,
           level_text, award_text, closing_text, nationality_text, content_hash, evidence_id, last_run_id)
    select p_register, s.listing_id, v_country, s.url, s.name, s.provider_ref, s.provider_name, s.level_text, s.award_text, s.closing_text,
           s.nationality_text, s.h, p_evidence_id, p_run_id from src s
    on conflict (register_code, listing_id) do update
       set url = excluded.url, name = excluded.name, provider_ref = excluded.provider_ref, provider_name = excluded.provider_name,
           level_text = excluded.level_text, award_text = excluded.award_text, closing_text = excluded.closing_text, nationality_text = excluded.nationality_text,
           content_hash = excluded.content_hash, evidence_id = excluded.evidence_id, last_run_id = excluded.last_run_id,
           last_seen_at = now(), departed_at = null
    returning (xmax = 0) ins, (l.content_hash) h
  ) select count(*) filter (where ins), 0, count(*) filter (where not ins) into v_created, v_updated, v_unchanged from up;
  if p_final then
    update scholarship.register_listings set departed_at = now()
     where register_code = p_register and departed_at is null and last_run_id is distinct from p_run_id;
    get diagnostics v_departed = row_count;
    v_match := public.svc_scholarship_register_match(p_register);
  end if;
  return jsonb_build_object('created', v_created, 'seen_again', v_unchanged, 'departed', v_departed, 'match', v_match);
end $$;


ALTER FUNCTION "public"."svc_scholarship_register_save"("p_register" "text", "p_run_id" "uuid", "p_evidence_id" "uuid", "p_listings" "jsonb", "p_final" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_resolve_au_provider"("p_cricos" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select pr.provider_id
  from catalogue.provider_registrations pr
  join catalogue.providers p on p.id=pr.provider_id
  join ref.countries c on c.id=p.country_id
  where c.iso_alpha2='AU'
    and pr.registration_scheme='cricos'
    and upper(btrim(pr.registration_code))=upper(btrim(p_cricos))
    and coalesce(pr.status,'active') not in ('inactive','cancelled','archived')
  order by pr.valid_to nulls first, pr.checked_at desc nulls last
  limit 1
$$;


ALTER FUNCTION "public"."svc_scholarship_resolve_au_provider"("p_cricos" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_search_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'scholarship', 'security'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select s.id, s.name, s.provider_id, coalesce(d.site_origin,d.website) site, d.allowed_hosts from scholarship.scholarships s
      join pipeline.scholarship_discovery_providers d on d.provider_id=s.provider_id and d.status in ('mapped','empty','failed')
     where s.lifecycle_status='active' and security.reference_url_has_use(s.source_url, 'scholarship_placeholder')
       and not exists (select 1 from pipeline.scholarship_pages sp where sp.scholarship_id=s.id and not (sp.url_source='discovered' and sp.read_status in ('name_mismatch','robots_disallowed','gone')))
       and not exists (select 1 from pipeline.scholarship_page_searches q where q.scholarship_id=s.id)
     order by d.priority, s.provider_id, s.name limit greatest(1,least(coalesce(p_limit,5),20))),
  ins as (insert into pipeline.scholarship_page_searches(scholarship_id,status) select id,'leased' from pick on conflict do nothing returning scholarship_id)
  select coalesce(jsonb_agg(jsonb_build_object('scholarship_id',p.id,'name',p.name,'provider_id',p.provider_id,'site',p.site,'hosts',to_jsonb(p.allowed_hosts),'names',security.provider_name_list(p.provider_id))),'[]'::jsonb)
    into v from pick p join ins on ins.scholarship_id=p.id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_scholarship_search_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_search_record"("p_scholarship_id" "uuid", "p_query" "text", "p_status" "text", "p_results" "jsonb", "p_match" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'scholarship', 'security'
    AS $$
declare v_pid uuid; v_site text; v_cid bigint; r jsonb:=jsonb_build_object('matched',false);
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  select s.provider_id, coalesce(d.site_origin,d.website) into v_pid, v_site from scholarship.scholarships s join pipeline.scholarship_discovery_providers d on d.provider_id=s.provider_id where s.id=p_scholarship_id;
  update pipeline.scholarship_page_searches set query=p_query, status=p_status, results=p_results, matched_url=p_match->>'url', searched_at=now() where scholarship_id=p_scholarship_id;
  insert into pipeline.scholarship_page_candidates(provider_id,url,url_norm,title,source)
  select v_pid, x->>'url', security.scholarship_url_norm(x->>'url'), nullif(left(x->>'title',300),''), 'search'
    from jsonb_array_elements(coalesce(p_results,'[]')) x where x->>'kept'='true' and security.url_on_provider_sites(x->>'url', v_pid)
  on conflict (provider_id,url_norm) do update set title=coalesce(pipeline.scholarship_page_candidates.title, excluded.title);
  if p_match ? 'url' then
    select id into v_cid from pipeline.scholarship_page_candidates where provider_id=v_pid and url_norm=security.scholarship_url_norm(p_match->>'url');
    if v_cid is not null then r:=security.scholarship_page_match_v1(p_scholarship_id, p_match->>'url', p_match->>'basis', v_cid); end if;
  end if;
  return r;
end $$;


ALTER FUNCTION "public"."svc_scholarship_search_record"("p_scholarship_id" "uuid", "p_query" "text", "p_status" "text", "p_results" "jsonb", "p_match" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_source_record"("p_source_id" "uuid", "p_source_record_id" "text", "p_source_record_url" "text", "p_source_provider_id" "text", "p_source_provider_cricos" "text", "p_source_provider_name" "text", "p_content_hash" "text", "p_evidence_id" "uuid", "p_payload" "jsonb", "p_status" "text" DEFAULT 'captured'::"text", "p_error_text" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  if auth.role() <> 'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.scholarship_source_records(
    source_id,source_record_id,source_record_url,source_provider_id,source_provider_cricos,source_provider_name,
    content_hash,evidence_id,payload,status,error_text,observed_at,applied_at
  ) values (
    p_source_id,p_source_record_id,p_source_record_url,p_source_provider_id,p_source_provider_cricos,p_source_provider_name,
    p_content_hash,p_evidence_id,p_payload,p_status,p_error_text,now(),case when p_status='applied' then now() end
  )
  on conflict(source_id,source_record_id,content_hash) do update set
    evidence_id=excluded.evidence_id,payload=excluded.payload,source_record_url=excluded.source_record_url,
    source_provider_id=excluded.source_provider_id,source_provider_cricos=excluded.source_provider_cricos,
    source_provider_name=excluded.source_provider_name,status=excluded.status,error_text=excluded.error_text,
    observed_at=now(),applied_at=case when excluded.status='applied' then now() else pipeline.scholarship_source_records.applied_at end
  returning id into v_id;
  return v_id;
end
$$;


ALTER FUNCTION "public"."svc_scholarship_source_record"("p_source_id" "uuid", "p_source_record_id" "text", "p_source_record_url" "text", "p_source_provider_id" "text", "p_source_provider_cricos" "text", "p_source_provider_name" "text", "p_content_hash" "text", "p_evidence_id" "uuid", "p_payload" "jsonb", "p_status" "text", "p_error_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_search_pass_bind"("p_item_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_i pipeline.toolset_sample_items%rowtype; v_c jsonb; v_url text; v_pg pipeline.coverage_course_pages%rowtype;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into v_i from pipeline.toolset_sample_items where id = p_item_id;
  if v_i.id is null or v_i.course_id is null then return 'no_course'; end if;
  if not exists (select 1 from pipeline.toolset_sample_runs r where r.id = v_i.run_id and r.applies) then return 'not_a_pass'; end if;
  v_c := coalesce(v_i.result->'candidates', '[]'::jsonb);
  if jsonb_array_length(v_c) = 0 then return 'no_candidate'; end if;
  if exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = v_i.course_id and k.field = 'official_url') then return 'entered_by_hand'; end if;
  select * into v_pg from pipeline.coverage_course_pages where course_id = v_i.course_id;
  if v_pg.course_id is not null and v_pg.status = 'bound' and (v_pg.read_status = 'read' or v_pg.identity_basis is not null) then return 'already_confirmed'; end if;
  v_url := v_c->>0;
  if v_pg.course_id is not null and v_pg.url = v_url and v_pg.status = 'mismatch' then
    if jsonb_array_length(v_c) < 2 then return 'already_refused'; end if;
    v_url := v_c->>1;
  end if;
  insert into pipeline.page_link_repairs(course_id, provider_id, old_url, new_url, reason, run_id)
    values (v_i.course_id, v_i.provider_id, v_pg.url, v_url, case when (v_i.input->>'refind')::boolean then 'search pass: better page for an unreadable one' else 'search pass: page found' end, v_i.run_id);
  insert into pipeline.coverage_course_pages(course_id, provider_id, url, basis, status, bound_at, next_read_at, read_attempts)
    values (v_i.course_id, v_i.provider_id, v_url, 'serper_search', 'bound', now(), now(), 0)
  on conflict (course_id) do update set url = excluded.url, basis = excluded.basis, status = 'bound', bound_at = now(), score = null, runner_up = null, read_status = null, read_at = null, http_status = null, fetched_via = null, identity_basis = null, evidence_id = null, candidates = null, leased_until = null, read_attempts = 0, next_read_at = now() where pipeline.coverage_course_pages.status <> 'bound' or (pipeline.coverage_course_pages.read_status in ('needs_render', 'blocked', 'fetch_failed') and pipeline.coverage_course_pages.evidence_id is null);
  insert into pipeline.search_pass_links(course_id, provider_id, run_id, candidates, cand_idx, bound_url, refind, state, updated_at)
    values (v_i.course_id, v_i.provider_id, v_i.run_id, v_c, case when v_url = v_c->>0 then 1 else 2 end, v_url, coalesce((v_i.input->>'refind')::boolean, false), 'found', now())
  on conflict (course_id) do update set run_id = excluded.run_id, candidates = excluded.candidates, cand_idx = excluded.cand_idx, bound_url = excluded.bound_url, refind = excluded.refind, state = 'found', updated_at = now();
  return 'bound';
end $$;


ALTER FUNCTION "public"."svc_search_pass_bind"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_site_hint_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with hints as (
    select r.provider_id, u url, 'hipo' via from pipeline.reference_institutions r, unnest(r.web_pages) u where r.provider_id is not null
    union select d.provider_id, d.website_hint, d.site from pipeline.directory_institutions d where d.provider_id is not null and d.website_hint is not null),
  todo as (
    select h.provider_id, jsonb_agg(distinct jsonb_build_object('url', h.url, 'via', h.via)) urls
      from hints h
      left join pipeline.coverage_provider_discovery d on d.provider_id = h.provider_id
     where (d.provider_id is null or d.status in ('no_website', 'failed') or d.website is null)
       and exists (select 1 from catalogue.courses co where co.provider_id = h.provider_id and co.lifecycle_status = 'active')
       and not exists (select 1 from pipeline.site_hint_checks c where c.provider_id = h.provider_id and c.url = h.url
                         and (c.accepted or coalesce(c.evidence->>'worker', '') not in ('coverage-sweep-worker-v0.10.0', 'coverage-sweep-worker-v0.10.1', 'coverage-sweep-worker-v0.10.2', 'coverage-sweep-worker-v0.10.3')))
     group by 1 limit greatest(1, least(coalesce(p_limit, 20), 60)))
  select coalesce(jsonb_agg(jsonb_build_object('provider_id', t.provider_id, 'name', coalesce(pr.display_name, pr.canonical_name), 'country', security.coverage_country(t.provider_id),
           'cricos', (select i.identifier from catalogue.provider_identifiers i where i.provider_id = t.provider_id and i.scheme = 'cricos' limit 1),
           'dli', (select i.identifier from catalogue.provider_identifiers i where i.provider_id = t.provider_id and i.scheme = 'ircc_dli' limit 1),
           'urls', t.urls)), '[]'::jsonb)
    into v from todo t join catalogue.providers pr on pr.id = t.provider_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_site_hint_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_site_hint_record"("p_provider_id" "uuid", "p_url" "text", "p_accepted" boolean, "p_basis" "text", "p_evidence" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'public'
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.site_hint_checks(provider_id, url, accepted, basis, evidence) values (p_provider_id, p_url, p_accepted, p_basis, p_evidence)
  on conflict (provider_id, url) do update set accepted = excluded.accepted, basis = excluded.basis, evidence = excluded.evidence, checked_at = now();
  if not p_accepted then return 'rejected'; end if;
  insert into pipeline.coverage_provider_discovery(provider_id, status, attempts, updated_at) values (p_provider_id, 'no_website', 0, now())
  on conflict (provider_id) do nothing;
  perform public.svc_coverage_site_record(p_provider_id, p_url, coalesce(p_evidence, '{}'::jsonb) || jsonb_build_object('basis', 'hint_' || coalesce(p_basis, 'verified')));
  return 'accepted';
end $$;


ALTER FUNCTION "public"."svc_site_hint_record"("p_provider_id" "uuid", "p_url" "text", "p_accepted" boolean, "p_basis" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_statistical_equivalent_provider_ids"("p_provider_id" "uuid") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'public'
    AS $$
with seed as (
  select p.id,p.country_id,
    lower(regexp_replace(coalesce(p.display_name,p.canonical_name),'[^a-z0-9]+','','g')) norm_name
  from catalogue.providers p where p.id=p_provider_id
), same_identifier as (
  select distinct pi2.provider_id id
  from catalogue.provider_identifiers pi1
  join catalogue.provider_identifiers pi2
    on lower(pi2.scheme)=lower(pi1.scheme)
   and lower(pi2.identifier)=lower(pi1.identifier)
   and pi2.valid_to is null
  join seed s on s.id=pi1.provider_id
  where pi1.valid_to is null
), same_name as (
  select p.id
  from catalogue.providers p join seed s on s.country_id=p.country_id
  where lower(regexp_replace(coalesce(p.display_name,p.canonical_name),'[^a-z0-9]+','','g'))=s.norm_name
)
select coalesce(array_agg(distinct id order by id),array[p_provider_id]::uuid[])
from (select id from same_identifier union select id from same_name union select p_provider_id) q;
$$;


ALTER FUNCTION "public"."svc_statistical_equivalent_provider_ids"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_statistics_candidate_applied"("p_candidate_id" bigint, "p_actor" "uuid", "p_result" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare c pipeline.statistics_edition_candidates; r pipeline.statistics_edition_rules; f pipeline.layer1_dataset_families;
        v_source uuid; v_old uuid; v_key text; v_year int; v_rows bigint;
begin
  select * into c from pipeline.statistics_edition_candidates where id=p_candidate_id for update;
  if not found then raise exception 'candidate not found'; end if;
  select * into r from pipeline.statistics_edition_rules where member_code=c.member_code for update;
  select * into f from pipeline.layer1_dataset_families where family_code=r.family_code for update;
  v_source:=nullif(p_result->>'sourceId','')::uuid; v_old:=r.current_source_id;
  v_key:=coalesce(nullif(p_result->>'collectionVersion',''), c.edition_year::text);
  v_year:=coalesce(c.edition_year, nullif(left(coalesce(p_result->>'collectionVersion',''),4),'')::int);
  v_rows:=nullif(p_result->>'candidateObservations','')::bigint;
  update pipeline.statistics_edition_candidates set status='applied', applied_at=now(), applied_by=p_actor, applied_source_id=v_source,
         check_result=coalesce(check_result,'{}'::jsonb)||jsonb_build_object('apply',p_result) where id=p_candidate_id;
  if v_source is null or v_source=v_old then return; end if;

  update pipeline.sources s set metadata=coalesce((select o.metadata from pipeline.sources o where o.id=v_old),'{}'::jsonb) || coalesce(s.metadata,'{}'::jsonb)
         || jsonb_build_object('edition_year',v_year,'edition_key',v_key,'edition_status','current','collection_version',v_key), updated_at=now()
   where s.id=v_source;
  update pipeline.sources set metadata=metadata||jsonb_build_object('edition_status','retained'), updated_at=now() where id=v_old;

  insert into pipeline.layer1_source_operations(source_id,authority_name,authority_domains,expected_format,expected_count_kind,active,paused,verification_cadence_days,
         ingestion_cadence_days,variance_warn_percent,variance_block_percent,min_expected_records,max_expected_records,last_expected_count,verification_status,
         verification_message,next_verification_at,change_reason,updated_by,updated_at)
  select v_source,o.authority_name,o.authority_domains,o.expected_format,o.expected_count_kind,true,false,o.verification_cadence_days,
         o.ingestion_cadence_days,o.variance_warn_percent,o.variance_block_percent,null,null,v_rows,'passed',
         'New edition applied from the statistics discovery candidate',now()+make_interval(days=>o.verification_cadence_days),
         'Decision 134 new edition',p_actor,now()
    from pipeline.layer1_source_operations o where o.source_id=v_old
  on conflict (source_id) do nothing;
  update pipeline.layer1_source_operations set next_verification_at=null, change_reason='Retained edition (replaced by a newer edition)', updated_at=now() where source_id=v_old;

  if f.id is not null then
    update pipeline.layer1_dataset_editions set status='retained' where family_id=f.id and status='current';
    insert into pipeline.layer1_dataset_editions(family_id,source_id,edition_key,edition_year,status,observation_count,first_seen_at,last_verified_at,metadata)
    values(f.id,v_source,v_key,v_year,'current',v_rows,now(),now(),jsonb_build_object('candidate_id',p_candidate_id,'file_url',c.file_url))
    on conflict (source_id) do update set status='current', edition_key=excluded.edition_key, observation_count=excluded.observation_count, last_verified_at=now();
    update pipeline.layer1_dataset_families set current_source_id=v_source, updated_at=now() where id=f.id;
  end if;
  update pipeline.statistics_edition_rules set current_source_id=v_source where member_code=r.member_code;
end $$;


ALTER FUNCTION "public"."svc_statistics_candidate_applied"("p_candidate_id" bigint, "p_actor" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_statistics_candidate_context"("p_candidate_id" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select jsonb_build_object('id',c.id,'member_code',c.member_code,'file_url',c.file_url,'edition_year',c.edition_year,'status',c.status,
         'worker',r.worker,'worker_member',r.worker_member,'authority_domain',r.authority_domain)
    from pipeline.statistics_edition_candidates c join pipeline.statistics_edition_rules r on r.member_code=c.member_code where c.id=p_candidate_id
$$;


ALTER FUNCTION "public"."svc_statistics_candidate_context"("p_candidate_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_statistics_candidate_record"("p_member_code" "text", "p_file_url" "text", "p_edition_year" integer, "p_status" "text", "p_check" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_id bigint;
begin
  if p_status not in ('found','checked','check_failed') then raise exception 'invalid status'; end if;
  insert into pipeline.statistics_edition_candidates(member_code,file_url,edition_year,status,check_result,checked_at)
  values(p_member_code,p_file_url,p_edition_year,p_status,p_check,case when p_status<>'found' then now() end)
  on conflict (member_code,file_url) do update set status=excluded.status, check_result=excluded.check_result, checked_at=excluded.checked_at,
     edition_year=coalesce(excluded.edition_year,pipeline.statistics_edition_candidates.edition_year)
   where pipeline.statistics_edition_candidates.status in ('found','checked','check_failed')
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."svc_statistics_candidate_record"("p_member_code" "text", "p_file_url" "text", "p_edition_year" integer, "p_status" "text", "p_check" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_statistics_edition_rules"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('member_code',r.member_code,'worker',r.worker,'worker_member',r.worker_member,'listing_url',r.listing_url,
         'file_pattern',r.file_pattern,'year_group',r.year_group,'authority_domain',r.authority_domain,
         'known',(select coalesce(jsonb_agg(c.file_url),'[]'::jsonb) from pipeline.statistics_edition_candidates c where c.member_code=r.member_code))),'[]'::jsonb)
    from pipeline.statistics_edition_rules r where r.active
$$;


ALTER FUNCTION "public"."svc_statistics_edition_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_toolset_sample_close"("p_run_id" "uuid", "p_timed_out" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_left int; v_new text;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  perform public.svc_toolset_sample_release(p_run_id);
  v_left := public.svc_toolset_sample_left(p_run_id);
  v_new := case when v_left = 0 then 'done' when p_timed_out then 'paused_time_limit' else null end;
  if v_new = 'done' then
    update pipeline.toolset_sample_runs set status = 'done', finished_at = now(), updated_at = now() where id = p_run_id and status = 'running';
  elsif v_new = 'paused_time_limit' then
    update pipeline.toolset_sample_runs set status = 'paused_time_limit', status_note = format('%s cases left. The worker reached its time per call. Press Continue', v_left), updated_at = now() where id = p_run_id and status = 'running';
  end if;
  return jsonb_build_object('left', v_left, 'status', (select status from pipeline.toolset_sample_runs where id = p_run_id));
end $$;


ALTER FUNCTION "public"."svc_toolset_sample_close"("p_run_id" "uuid", "p_timed_out" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_toolset_sample_continue"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_r pipeline.toolset_sample_runs%rowtype;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into v_r from pipeline.toolset_sample_runs where id = p_run_id;
  if v_r.id is null or not v_r.applies or v_r.status <> 'paused_time_limit' then return jsonb_build_object('continued', false); end if;
  if not coalesce((security.toolset_setting(v_r.toolset_key, 'pass_auto_continue') #>> '{}')::boolean, false) then return jsonb_build_object('continued', false, 'why', 'carry on is switched off'); end if;
  return jsonb_build_object('continued', true, 'request', pipeline.svc_pilot_submit_nonce('toolset-runner', jsonb_build_object('action', 'run', 'run_id', p_run_id)));
end $$;


ALTER FUNCTION "public"."svc_toolset_sample_continue"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_toolset_sample_left"("p_run_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select count(*)::int from pipeline.toolset_sample_items where run_id = p_run_id and status <> 'done'
$$;


ALTER FUNCTION "public"."svc_toolset_sample_left"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_toolset_sample_next"("p_run_id" "uuid", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_r pipeline.toolset_sample_runs%rowtype; v_items jsonb; v_ids uuid[]; v_plan jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into v_r from pipeline.toolset_sample_runs where id = p_run_id for update;
  if v_r.id is null or v_r.status not in ('ready', 'running', 'paused_time_limit') then return jsonb_build_object('items', '[]'::jsonb, 'status', v_r.status); end if;
  v_plan := security.toolset_plan_status(v_r.toolset_key);
  if (v_plan->>'at_reserve')::boolean then
    update pipeline.toolset_sample_runs set status = 'stopped_vendor_limit', status_note = format('The key''s plan has %s credits left, at or below its reserve of %s. Replace the key or raise the plan limits', v_plan->>'left', v_plan->>'reserve'), finished_at = now(), updated_at = now() where id = p_run_id;
    return jsonb_build_object('items', '[]'::jsonb, 'status', 'stopped_vendor_limit');
  end if;
  if v_r.credits_used >= coalesce((v_r.settings->>'sample_credits_per_run')::numeric, 0) then
    update pipeline.toolset_sample_runs set status = 'stopped_credit_cap', status_note = 'The run used the credits one run may use', finished_at = now(), updated_at = now() where id = p_run_id;
    return jsonb_build_object('items', '[]'::jsonb, 'status', 'stopped_credit_cap');
  end if;
  update pipeline.toolset_sample_runs set status = 'running', updated_at = now() where id = p_run_id;
  select array_agg(i.id) into v_ids from (
    select i.id from pipeline.toolset_sample_items i
    where i.run_id = p_run_id and (i.status = 'pending' or (i.status = 'leased' and i.leased_until < now()))
    order by i.country, i.id limit greatest(1, least(p_limit, 50)) for update skip locked) i;
  update pipeline.toolset_sample_items set status = 'leased', leased_until = now() + interval '10 minutes' where id = any(coalesce(v_ids, '{}'));
  select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'country', i.country, 'input', i.input)), '[]'::jsonb) into v_items
    from pipeline.toolset_sample_items i where i.id = any(coalesce(v_ids, '{}'));
  return jsonb_build_object('items', v_items, 'status', 'running', 'purpose', v_r.purpose, 'applies', v_r.applies, 'settings', v_r.settings, 'plan', v_plan,
    'provider', (select public.layer2_provider_runtime_config(p.id) from pipeline.layer2_acquisition_providers p where p.provider_key = v_r.toolset_key));
end $$;


ALTER FUNCTION "public"."svc_toolset_sample_next"("p_run_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_toolset_sample_record"("p_item_id" "uuid", "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_i pipeline.toolset_sample_items%rowtype; v_r pipeline.toolset_sample_runs%rowtype; v_credits numeric := coalesce((p_result->>'credits')::numeric, 0); v_cap numeric;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into v_i from pipeline.toolset_sample_items where id = p_item_id;
  if v_i.id is null then raise exception 'unknown item'; end if;
  select * into v_r from pipeline.toolset_sample_runs where id = v_i.run_id;
  v_cap := coalesce((v_r.settings->>'sample_credits_per_run')::numeric, 0);
  if p_result->>'outcome' = 'vendor_limit' then
    update pipeline.toolset_sample_items set leased_until = now() where id = p_item_id;
    update pipeline.toolset_sample_runs set status = 'stopped_vendor_limit', status_note = left(p_result->>'message', 300), finished_at = now(), updated_at = now() where id = v_r.id;
    return jsonb_build_object('continue', false);
  end if;
  update pipeline.toolset_sample_items set status = 'done', outcome = p_result->>'outcome', done_at = now() where id = p_item_id;
  update pipeline.toolset_sample_items set http_status = (p_result->>'http_status')::int, credits = v_credits, latency_ms = (p_result->>'latency_ms')::int where id = p_item_id;
  update pipeline.toolset_sample_items set result = p_result - 'outcome' - 'http_status' - 'credits' - 'latency_ms' where id = p_item_id;
  update pipeline.toolset_sample_runs set credits_used = credits_used + v_credits, updated_at = now() where id = v_r.id;
  if v_credits > 0 then
    insert into pipeline.coverage_vendor_usage(acquisition_provider_id, units, purpose, provider_id, url)
    select p.id, v_credits, 'sample_' || v_r.toolset_key, v_i.provider_id, coalesce(v_i.input->>'url', p_result->>'query')
    from pipeline.layer2_acquisition_providers p where p.provider_key = v_r.toolset_key;
  end if;
  if v_r.credits_used + v_credits >= v_cap then
    update pipeline.toolset_sample_runs set status = 'stopped_credit_cap', status_note = 'The run used the credits one run may use', finished_at = now() where id = v_r.id and status = 'running';
  end if;
  return jsonb_build_object('continue', v_r.credits_used + v_credits < v_cap and not (security.toolset_plan_status(v_r.toolset_key)->>'at_reserve')::boolean
    and (select status = 'running' from pipeline.toolset_sample_runs where id = v_r.id));
end $$;


ALTER FUNCTION "public"."svc_toolset_sample_record"("p_item_id" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_toolset_sample_release"("p_run_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  update pipeline.toolset_sample_items set leased_until = now() where run_id = p_run_id and status = 'leased';
  get diagnostics v_n = row_count;
  return v_n;
end $$;


