    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$ select security.admin_course_field_states(p_course_id) where auth.uid() is not null and security.current_role_rank()>=1 $$;


ALTER FUNCTION "public"."ui_course_field_states"("p_course_id" "uuid") OWNER TO "postgres";


