    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'auth'
    AS $$ select case when auth.uid() is null then null else jsonb_build_object('countries',(select coalesce(jsonb_agg(jsonb_build_object('code',x.iso_alpha2,'name',x.name) order by x.name),'[]'::jsonb) from (select distinct co.iso_alpha2,co.name from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id)x),'levels',(select coalesce(jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.name),'[]'::jsonb) from (select distinct sl.code,sl.name from catalogue.courses c join ref.study_levels sl on sl.id=c.study_level_id where sl.code is not null)x)) end $$;


ALTER FUNCTION "public"."ui_course_filter_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_course_filter_options"("p_country_code" "text" DEFAULT NULL::"text", "p_subdivision_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'auth'
    AS $$
select case when auth.uid() is null then null else jsonb_build_object(
 'countries',coalesce((select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.name) from (
   select distinct co.iso_alpha2::text code,co.name from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
 )x),'[]'::jsonb),
 'subdivisions',coalesce((select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name,'type',x.subdivision_type) order by x.name) from (
   select distinct s.code,s.name,s.subdivision_type
   from catalogue.courses c
   join catalogue.providers p on p.id=c.provider_id
   join ref.countries co on co.id=p.country_id
   join catalogue.course_campuses cc on cc.course_id=c.id
   join catalogue.campuses cp on cp.id=cc.campus_id
   join ref.subdivisions s on s.id=cp.subdivision_id
   where nullif(trim(coalesce(p_country_code,'')),'') is null or co.iso_alpha2::text=upper(trim(p_country_code))
 )x),'[]'::jsonb),
 'providers',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'stable_key',x.stable_key) order by x.name) from (
   select distinct p.id,coalesce(p.display_name,p.canonical_name) name,p.stable_key
   from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
   where (nullif(trim(coalesce(p_country_code,'')),'') is null or co.iso_alpha2::text=upper(trim(p_country_code)))
     and (nullif(trim(coalesce(p_subdivision_code,'')),'') is null or exists(
       select 1 from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id join ref.subdivisions s on s.id=cp.subdivision_id
       where cc.course_id=c.id and s.code=upper(trim(p_subdivision_code))))
 )x),'[]'::jsonb),
 'levels',coalesce((select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.sort_order,x.name) from (
   select distinct sl.code,sl.name,sl.sort_order
   from catalogue.courses c join ref.study_levels sl on sl.id=c.study_level_id join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
   where (nullif(trim(coalesce(p_country_code,'')),'') is null or co.iso_alpha2::text=upper(trim(p_country_code)))
     and (nullif(trim(coalesce(p_subdivision_code,'')),'') is null or exists(select 1 from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id join ref.subdivisions s on s.id=cp.subdivision_id where cc.course_id=c.id and s.code=upper(trim(p_subdivision_code))))
 )x),'[]'::jsonb),
 'fields',coalesce((select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.name) from (
   select distinct fos.code,fos.name
   from catalogue.courses c join ref.fields_of_study fos on fos.id=c.primary_field_id join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
   where (nullif(trim(coalesce(p_country_code,'')),'') is null or co.iso_alpha2::text=upper(trim(p_country_code)))
     and (nullif(trim(coalesce(p_subdivision_code,'')),'') is null or exists(select 1 from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id join ref.subdivisions s on s.id=cp.subdivision_id where cc.course_id=c.id and s.code=upper(trim(p_subdivision_code))))
 )x),'[]'::jsonb),
 'delivery_modes',coalesce((select jsonb_agg(jsonb_build_object('code',x.code,'name',x.code) order by x.code) from (
   select distinct cc.delivery_mode code
   from catalogue.course_campuses cc join catalogue.courses c on c.id=cc.course_id join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
   where cc.delivery_mode is not null and btrim(cc.delivery_mode)<>''
     and (nullif(trim(coalesce(p_country_code,'')),'') is null or co.iso_alpha2::text=upper(trim(p_country_code)))
     and (nullif(trim(coalesce(p_subdivision_code,'')),'') is null or exists(select 1 from catalogue.course_campuses cc2 join catalogue.campuses cp2 on cp2.id=cc2.campus_id join ref.subdivisions s2 on s2.id=cp2.subdivision_id where cc2.course_id=c.id and s2.code=upper(trim(p_subdivision_code))))
 )x),'[]'::jsonb)
) end $$;


ALTER FUNCTION "public"."ui_course_filter_options"("p_country_code" "text", "p_subdivision_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_course_related_campuses"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'pipeline', 'auth'
    AS $$
select coalesce(
  jsonb_agg(
    jsonb_build_object(
      'id', ca.id,
      'stable_key', ca.stable_key,
      'name', ca.name,
      'campus_code', ca.campus_code,
      'provider_id', ca.provider_id,
      'country_code', co.iso_alpha2,
      'subdivision_code', sd.code,
      'subdivision_name', sd.name,
      'city', ca.city,
      'address_line1', ca.address_line1,
      'address_line2', ca.address_line2,
      'postcode', ca.postcode,
      'status', ca.status,
      'publication_status', ca.publication_status,
      'valid_from', ca.valid_from,
      'valid_to', ca.valid_to,
      'last_verified_at', ca.last_verified_at,
      'delivery_mode', cc.delivery_mode,
      'is_primary', cc.is_primary,
      'website', ca.website,
      'campus_source', jsonb_build_object(
        'source_id', ca.source_id,
        'source_label', cs.label,
        'source_type', cs.source_type,
        'source_url', cs.url
      ),
      'campus_evidence', case when ce.id is null then null else jsonb_build_object(
        'id', ce.id,
        'type', ce.evidence_type,
        'source_url', ce.source_url,
        'captured_at', ce.captured_at,
        'content_hash', ce.content_hash
      ) end,
      'relationship_source', jsonb_build_object(
        'source_id', cc.source_id,
        'source_label', rs.label,
        'source_type', rs.source_type,
        'source_url', rs.url
      ),
      'relationship_evidence', case when re.id is null then null else jsonb_build_object(
        'id', re.id,
        'type', re.evidence_type,
        'source_url', re.source_url,
        'captured_at', re.captured_at,
        'content_hash', re.content_hash
      ) end
    ) order by cc.is_primary desc nulls last, ca.name
  ),
  '[]'::jsonb
)
from catalogue.course_campuses cc
join catalogue.campuses ca on ca.id=cc.campus_id
join ref.countries co on co.id=ca.country_id
left join ref.subdivisions sd on sd.id=ca.subdivision_id
left join pipeline.sources cs on cs.id=ca.source_id
left join pipeline.evidence_artifacts ce on ce.id=ca.evidence_id
left join pipeline.sources rs on rs.id=cc.source_id
left join pipeline.evidence_artifacts re on re.id=cc.evidence_id
where cc.course_id=p_course_id
  and auth.uid() is not null and security.current_role_rank() >= 1;
$$;


ALTER FUNCTION "public"."ui_course_related_campuses"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_courses_decision_page"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_subdivision_code" "text" DEFAULT NULL::"text", "p_provider_id" "uuid" DEFAULT NULL::"uuid", "p_level_code" "text" DEFAULT NULL::"text", "p_field_code" "text" DEFAULT NULL::"text", "p_delivery_mode" "text" DEFAULT NULL::"text", "p_lifecycle_status" "text" DEFAULT NULL::"text", "p_publication_status" "text" DEFAULT NULL::"text", "p_has_fee" boolean DEFAULT NULL::boolean, "p_has_intake" boolean DEFAULT NULL::boolean, "p_has_english" boolean DEFAULT NULL::boolean, "p_has_scholarship" boolean DEFAULT NULL::boolean, "p_min_completeness" numeric DEFAULT NULL::numeric, "p_freshness" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'course'::"text", "p_direction" "text" DEFAULT 'asc'::"text", "p_has_state" boolean DEFAULT NULL::boolean, "p_has_link" boolean DEFAULT NULL::boolean, "p_university_group" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'catalogue', 'ref', 'scholarship', 'auth'
    AS $$
declare
  v_limit int:=least(greatest(coalesce(p_limit,50),1),200);
  v_offset int:=greatest(coalesce(p_offset,0),0);
  v_sort text:=lower(coalesce(p_sort,'course'));
  v_dir text:=case when lower(coalesce(p_direction,'asc'))='desc' then 'desc' else 'asc' end;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank() < 1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  return (
    with base as (
      select
        c.id,c.stable_key,c.canonical_title,c.display_title,c.course_code,c.course_url,
        c.lifecycle_status,c.publication_status,c.last_verified_at,c.created_at,c.updated_at,c.provider_id,
        coalesce(p.display_name,p.canonical_name) provider_name,
        co.iso_alpha2::text country_code,co.name country_name,co.default_currency_code::text currency_code,
        sl.code level_code,sl.name level_name,fos.code field_code,fos.name field_of_study,
        case when dm.mode_count=1 then dm.single_mode when dm.mode_count>1 then dm.mode_count::text||' modes' else c.delivery_mode end delivery_mode,
        fee.amount fee_amount,fee.currency_code::text fee_currency,
        sig.has_registration,sig.has_structure,sig.has_fee,sig.has_intake,sig.has_english,sig.has_description,
        round(((sig.has_registration::int+sig.has_structure::int+sig.has_fee::int+sig.has_intake::int+sig.has_english::int+sig.has_description::int)*100.0/6.0)::numeric,2) completeness_score_v2,
        round(((sig.has_registration::int+sig.has_structure::int+sig.has_fee::int+sig.has_intake::int+sig.has_english::int+sig.has_description::int)*100.0/6.0)::numeric,2) completeness_score,
        sch.has_scholarship,
        exists(select 1 from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=c.id and l.status='active') has_link,
        coalesce(geo.region_count,0)>0 has_state,
        coalesce(geo.campus_count,0) campus_count,
        case when geo.region_count=1 then geo.single_code else null end subdivision_code,
        case when geo.region_count=1 then geo.single_name when geo.region_count>1 then geo.region_count::text||' regions' else null end subdivision_name,
        coalesce(geo.region_count,0) region_count
      from catalogue.courses c
      join catalogue.providers p on p.id=c.provider_id
      join ref.countries co on co.id=p.country_id
      left join ref.study_levels sl on sl.id=c.study_level_id
      left join ref.fields_of_study fos on fos.id=c.primary_field_id
      left join lateral (
        select cf.amount,cf.currency_code
        from catalogue.course_fees cf
        where cf.course_id=c.id
          and cf.fee_type='tuition'
          and cf.basis='registered_total_course'
          and coalesce(cf.status,'active')='active'
        order by cf.source_snapshot_at desc nulls last,cf.last_verified_at desc nulls last,cf.created_at desc
        limit 1
      ) fee on true
      cross join lateral (
        select
          exists(select 1 from catalogue.course_registrations r where r.course_id=c.id) has_registration,
          (c.duration_value is not null or exists(select 1 from catalogue.course_academic_options a where a.course_id=c.id)) has_structure,
          exists(select 1 from catalogue.course_fees cf where cf.course_id=c.id and coalesce(cf.status,'active')='active') has_fee,
          exists(select 1 from catalogue.course_intakes ci where ci.course_id=c.id and coalesce(ci.status,'active')='active') has_intake,
          exists(select 1 from catalogue.course_english_requirements er where er.course_id=c.id and coalesce(er.status,'active')='active') has_english,
          (c.description is not null and length(trim(c.description))>0) has_description
      ) sig
      cross join lateral (
        select exists(
          select 1 from scholarship.scopes ss
          where coalesce(ss.include_exclude,'include')='include'
            and (ss.course_id=c.id or (ss.scope_type='provider' and ss.provider_id=c.provider_id))
        ) has_scholarship
      ) sch
      left join lateral (
        select count(distinct cc.campus_id)::int campus_count,count(distinct s.id)::int region_count,min(s.code) single_code,min(s.name) single_name
        from catalogue.course_campuses cc
        join catalogue.campuses ca on ca.id=cc.campus_id
        left join ref.subdivisions s on s.id=ca.subdivision_id
        where cc.course_id=c.id
      ) geo on true
      left join lateral (
        select count(distinct cc.delivery_mode)::int mode_count,min(cc.delivery_mode) single_mode
        from catalogue.course_campuses cc
        where cc.course_id=c.id and cc.delivery_mode is not null and btrim(cc.delivery_mode)<>''
      ) dm on true
      where (nullif(trim(coalesce(p_query,'')),'') is null
        or c.canonical_title ilike '%'||trim(p_query)||'%'
        or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_query)||'%'
        or coalesce(c.course_code,'') ilike '%'||trim(p_query)||'%'
        or coalesce(c.stable_key,'') ilike '%'||trim(p_query)||'%')
        and (nullif(trim(coalesce(p_country_code,'')),'') is null or co.iso_alpha2::text=upper(trim(p_country_code)))
        and (nullif(trim(coalesce(p_subdivision_code,'')),'') is null or exists(
          select 1 from catalogue.course_campuses cc join catalogue.campuses ca on ca.id=cc.campus_id join ref.subdivisions s on s.id=ca.subdivision_id
          where cc.course_id=c.id and s.code=upper(trim(p_subdivision_code))))
        and (p_provider_id is null or c.provider_id=p_provider_id)
        and (nullif(trim(coalesce(p_university_group,'')),'') is null or c.provider_id in (select security.university_group_provider_ids(p_university_group)))
        and (nullif(trim(coalesce(p_level_code,'')),'') is null or sl.code=trim(p_level_code))
        and (nullif(trim(coalesce(p_field_code,'')),'') is null or fos.code=trim(p_field_code))
        and (nullif(trim(coalesce(p_delivery_mode,'')),'') is null or coalesce(c.delivery_mode,'')=trim(p_delivery_mode)
          or exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.id and cc.delivery_mode=trim(p_delivery_mode)))
        and (nullif(trim(coalesce(p_lifecycle_status,'')),'') is null or c.lifecycle_status=trim(p_lifecycle_status))
        and (nullif(trim(coalesce(p_publication_status,'')),'') is null or c.publication_status=trim(p_publication_status))
    ), filtered as (
      select * from base
      where (p_has_fee is null or has_fee=p_has_fee)
        and (p_has_intake is null or has_intake=p_has_intake)
        and (p_has_english is null or has_english=p_has_english)
        and (p_has_scholarship is null or has_scholarship=p_has_scholarship)
        and (p_has_state is null or has_state=p_has_state)
        and (p_has_link is null or has_link=p_has_link)
        and (p_min_completeness is null or completeness_score_v2>=p_min_completeness)
        and (nullif(trim(coalesce(p_freshness,'')),'') is null
          or (p_freshness='never_verified' and last_verified_at is null)
          or (p_freshness='modified_7d' and updated_at>=now()-interval '7 days')
          or (p_freshness='modified_30d' and updated_at>=now()-interval '30 days')
          or (p_freshness='stale_180d' and (last_verified_at is null or last_verified_at<now()-interval '180 days')))
    ), numbered as (
      select *,count(*) over() total_count from filtered
    ), ordered as (
      select * from numbered order by
        case when v_sort='course' and v_dir='asc' then lower(canonical_title) end asc,
        case when v_sort='course' and v_dir='desc' then lower(canonical_title) end desc,
        case when v_sort='provider' and v_dir='asc' then lower(provider_name) end asc,
        case when v_sort='provider' and v_dir='desc' then lower(provider_name) end desc,
        case when v_sort='field' and v_dir='asc' then lower(coalesce(field_of_study,'')) end asc,
        case when v_sort='field' and v_dir='desc' then lower(coalesce(field_of_study,'')) end desc,
        case when v_sort='fee' and v_dir='asc' then fee_amount end asc nulls last,
        case when v_sort='fee' and v_dir='desc' then fee_amount end desc nulls last,
        case when v_sort='completeness' and v_dir='asc' then completeness_score_v2 end asc,
        case when v_sort='completeness' and v_dir='desc' then completeness_score_v2 end desc,
        case when v_sort='modified' and v_dir='asc' then updated_at end asc,
        case when v_sort='modified' and v_dir='desc' then updated_at end desc,
        case when v_sort='verified' and v_dir='asc' then last_verified_at end asc nulls first,
        case when v_sort='verified' and v_dir='desc' then last_verified_at end desc nulls last,
        lower(canonical_title),id
      limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'items',coalesce(jsonb_agg((to_jsonb(o)-'total_count')||jsonb_build_object('university_groups',security.provider_university_groups(o.provider_id))),'[]'::jsonb),
      'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir
    ) from ordered o
  );
end
$$;


ALTER FUNCTION "public"."ui_courses_decision_page"("p_limit" integer, "p_offset" integer, "p_query" "text", "p_country_code" "text", "p_subdivision_code" "text", "p_provider_id" "uuid", "p_level_code" "text", "p_field_code" "text", "p_delivery_mode" "text", "p_lifecycle_status" "text", "p_publication_status" "text", "p_has_fee" boolean, "p_has_intake" boolean, "p_has_english" boolean, "p_has_scholarship" boolean, "p_min_completeness" numeric, "p_freshness" "text", "p_sort" "text", "p_direction" "text", "p_has_state" boolean, "p_has_link" boolean, "p_university_group" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_courses_list"("p_limit" integer DEFAULT 1000) RETURNS TABLE("course_id" "uuid", "stable_key" "text", "canonical_title" "text", "provider_id" "uuid", "provider_name" "text", "level_code" "text", "field_of_study" "text", "duration_value" numeric, "duration_unit" "text", "delivery_mode" "text", "publication_status" "text", "has_fee" boolean, "has_intake" boolean, "has_english" boolean, "has_scholarship" boolean, "completeness_score" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'search', 'auth'
    AS $$
select c.id,c.stable_key,c.canonical_title,c.provider_id,coalesce(p.display_name,p.canonical_name),sl.code,fos.name,c.duration_value,c.duration_unit,c.delivery_mode,c.publication_status,
       coalesce(d.has_fee,false),coalesce(d.has_intake,false),coalesce(d.has_english,false),coalesce(d.has_scholarship,false),d.completeness_score
from catalogue.courses c join catalogue.providers p on p.id=c.provider_id
left join ref.study_levels sl on sl.id=c.study_level_id
left join ref.fields_of_study fos on fos.id=c.primary_field_id
left join search.course_documents d on d.course_id=c.id
where auth.uid() is not null
order by coalesce(p.display_name,p.canonical_name),c.canonical_title
limit least(greatest(coalesce(p_limit,1000),1),2000)
$$;


ALTER FUNCTION "public"."ui_courses_list"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_courses_page"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_level_code" "text" DEFAULT NULL::"text", "p_lifecycle_status" "text" DEFAULT NULL::"text", "p_publication_status" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'course'::"text", "p_direction" "text" DEFAULT 'asc'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'search', 'auth'
    AS $$ declare v_limit int:=least(greatest(coalesce(p_limit,50),1),200); v_offset int:=greatest(coalesce(p_offset,0),0); v_sort text:=lower(coalesce(p_sort,'course')); v_dir text:=case when lower(coalesce(p_direction,'asc'))='desc' then 'desc' else 'asc' end; begin if auth.uid() is null then raise exception 'authentication required'; end if; return (with base as (select c.id,c.stable_key,c.canonical_title,c.display_title,c.course_code,c.course_url,c.lifecycle_status,c.publication_status,c.last_verified_at,c.created_at,c.updated_at,c.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,co.iso_alpha2::text country_code,co.name country_name,co.default_currency_code::text currency_code,sl.code level_code,fos.name field_of_study,c.delivery_mode,coalesce(d.completeness_score,0) completeness_score,coalesce(d.has_fee,false) has_fee,coalesce(d.has_intake,false) has_intake,coalesce(d.has_english,false) has_english,coalesce(d.has_scholarship,false) has_scholarship from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id left join ref.study_levels sl on sl.id=c.study_level_id left join ref.fields_of_study fos on fos.id=c.primary_field_id left join search.course_documents d on d.course_id=c.id where (nullif(trim(coalesce(p_query,'')),'') is null or c.canonical_title ilike '%'||trim(p_query)||'%' or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_query)||'%' or coalesce(c.course_code,'') ilike '%'||trim(p_query)||'%' or coalesce(c.stable_key,'') ilike '%'||trim(p_query)||'%') and (nullif(trim(coalesce(p_country_code,'')),'') is null or co.iso_alpha2::text=upper(trim(p_country_code))) and (nullif(trim(coalesce(p_level_code,'')),'') is null or sl.code=trim(p_level_code)) and (nullif(trim(coalesce(p_lifecycle_status,'')),'') is null or c.lifecycle_status=trim(p_lifecycle_status)) and (nullif(trim(coalesce(p_publication_status,'')),'') is null or c.publication_status=trim(p_publication_status))), numbered as (select *,count(*) over() total_count from base), ordered as (select * from numbered order by case when v_sort='course' and v_dir='asc' then lower(canonical_title) end asc,case when v_sort='course' and v_dir='desc' then lower(canonical_title) end desc,case when v_sort='provider' and v_dir='asc' then lower(provider_name) end asc,case when v_sort='provider' and v_dir='desc' then lower(provider_name) end desc,case when v_sort='country' and v_dir='asc' then country_code end asc,case when v_sort='country' and v_dir='desc' then country_code end desc,case when v_sort='level' and v_dir='asc' then level_code end asc,case when v_sort='level' and v_dir='desc' then level_code end desc,case when v_sort='verified' and v_dir='asc' then last_verified_at end asc nulls first,case when v_sort='verified' and v_dir='desc' then last_verified_at end desc nulls last,case when v_sort='completeness' and v_dir='asc' then completeness_score end asc,case when v_sort='completeness' and v_dir='desc' then completeness_score end desc,lower(canonical_title),id limit v_limit offset v_offset) select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir) from ordered o); end $$;


ALTER FUNCTION "public"."ui_courses_page"("p_limit" integer, "p_offset" integer, "p_query" "text", "p_country_code" "text", "p_level_code" "text", "p_lifecycle_status" "text", "p_publication_status" "text", "p_sort" "text", "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_courses_page"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_subdivision_code" "text" DEFAULT NULL::"text", "p_provider_id" "uuid" DEFAULT NULL::"uuid", "p_level_code" "text" DEFAULT NULL::"text", "p_field_code" "text" DEFAULT NULL::"text", "p_delivery_mode" "text" DEFAULT NULL::"text", "p_lifecycle_status" "text" DEFAULT NULL::"text", "p_publication_status" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'course'::"text", "p_direction" "text" DEFAULT 'asc'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'search', 'auth'
    AS $$
declare v_limit int:=least(greatest(coalesce(p_limit,50),1),200); v_offset int:=greatest(coalesce(p_offset,0),0); v_sort text:=lower(coalesce(p_sort,'course')); v_dir text:=case when lower(coalesce(p_direction,'asc'))='desc' then 'desc' else 'asc' end;
begin
 if auth.uid() is null then raise exception 'authentication required'; end if;
 return (
 with base as (
   select c.id,c.stable_key,c.canonical_title,c.display_title,c.course_code,c.course_url,c.lifecycle_status,c.publication_status,c.last_verified_at,c.created_at,c.updated_at,c.provider_id,
     coalesce(p.display_name,p.canonical_name) provider_name,co.iso_alpha2::text country_code,co.name country_name,co.default_currency_code::text currency_code,
     coalesce(ps.code,geo.subdivision_code) subdivision_code,coalesce(ps.name,geo.subdivision_name) subdivision_name,
     sl.code level_code,sl.name level_name,fos.code field_code,fos.name field_of_study,c.delivery_mode,
     coalesce(d.completeness_score,0) completeness_score,coalesce(d.has_fee,false) has_fee,coalesce(d.has_intake,false) has_intake,coalesce(d.has_english,false) has_english,coalesce(d.has_scholarship,false) has_scholarship
   from catalogue.courses c
   join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
   left join ref.subdivisions ps on ps.id=p.subdivision_id
   left join lateral (
     select case when count(distinct s.id)=1 then min(s.code) end subdivision_code,
            case when count(distinct s.id)=1 then min(s.name) when count(distinct s.id)>1 then count(distinct s.id)::text||' regions' end subdivision_name
     from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id left join ref.subdivisions s on s.id=cp.subdivision_id where cc.course_id=c.id
   ) geo on true
   left join ref.study_levels sl on sl.id=c.study_level_id left join ref.fields_of_study fos on fos.id=c.primary_field_id left join search.course_documents d on d.course_id=c.id
   where (nullif(trim(coalesce(p_query,'')),'') is null or c.canonical_title ilike '%'||trim(p_query)||'%' or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_query)||'%' or coalesce(c.course_code,'') ilike '%'||trim(p_query)||'%' or coalesce(c.stable_key,'') ilike '%'||trim(p_query)||'%' or coalesce(fos.name,'') ilike '%'||trim(p_query)||'%')
     and (nullif(trim(coalesce(p_country_code,'')),'') is null or co.iso_alpha2::text=upper(trim(p_country_code)))
     and (nullif(trim(coalesce(p_subdivision_code,'')),'') is null or ps.code=upper(trim(p_subdivision_code)) or exists(select 1 from catalogue.course_campuses cc2 join catalogue.campuses cp2 on cp2.id=cc2.campus_id join ref.subdivisions s2 on s2.id=cp2.subdivision_id where cc2.course_id=c.id and s2.code=upper(trim(p_subdivision_code))))
     and (p_provider_id is null or c.provider_id=p_provider_id)
     and (nullif(trim(coalesce(p_level_code,'')),'') is null or sl.code=trim(p_level_code))
     and (nullif(trim(coalesce(p_field_code,'')),'') is null or fos.code=trim(p_field_code))
     and (nullif(trim(coalesce(p_delivery_mode,'')),'') is null or c.delivery_mode=trim(p_delivery_mode))
     and (nullif(trim(coalesce(p_lifecycle_status,'')),'') is null or c.lifecycle_status=trim(p_lifecycle_status))
     and (nullif(trim(coalesce(p_publication_status,'')),'') is null or c.publication_status=trim(p_publication_status))
 ), numbered as (select *,count(*) over() total_count from base), ordered as (
   select * from numbered order by
   case when v_sort='course' and v_dir='asc' then lower(canonical_title) end asc,
   case when v_sort='course' and v_dir='desc' then lower(canonical_title) end desc,
   case when v_sort='provider' and v_dir='asc' then lower(provider_name) end asc,
   case when v_sort='provider' and v_dir='desc' then lower(provider_name) end desc,
   case when v_sort='country' and v_dir='asc' then country_code end asc,
   case when v_sort='country' and v_dir='desc' then country_code end desc,
   case when v_sort='subdivision' and v_dir='asc' then lower(coalesce(subdivision_name,'')) end asc,
   case when v_sort='subdivision' and v_dir='desc' then lower(coalesce(subdivision_name,'')) end desc,
   case when v_sort='level' and v_dir='asc' then level_code end asc,
   case when v_sort='level' and v_dir='desc' then level_code end desc,
   case when v_sort='field' and v_dir='asc' then lower(coalesce(field_of_study,'')) end asc,
   case when v_sort='field' and v_dir='desc' then lower(coalesce(field_of_study,'')) end desc,
   case when v_sort='verified' and v_dir='asc' then last_verified_at end asc nulls first,
   case when v_sort='verified' and v_dir='desc' then last_verified_at end desc nulls last,
   case when v_sort='completeness' and v_dir='asc' then completeness_score end asc,
   case when v_sort='completeness' and v_dir='desc' then completeness_score end desc,
   lower(canonical_title),id limit v_limit offset v_offset)
 select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir) from ordered o);
end $$;


ALTER FUNCTION "public"."ui_courses_page"("p_limit" integer, "p_offset" integer, "p_query" "text", "p_country_code" "text", "p_subdivision_code" "text", "p_provider_id" "uuid", "p_level_code" "text", "p_field_code" "text", "p_delivery_mode" "text", "p_lifecycle_status" "text", "p_publication_status" "text", "p_sort" "text", "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_dashboard"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'scholarship', 'pipeline', 'workflow', 'pim', 'search', 'auth'
    AS $$
select case when auth.uid() is null then '{}'::jsonb else jsonb_build_object(
 'providers',(select count(*) from catalogue.providers),
 'courses',(select count(*) from catalogue.courses),
 'campuses',(select count(*) from catalogue.campuses),
 'course_campus_links',(select count(*) from catalogue.course_campuses),
 'scholarships',(select count(*) from scholarship.scholarships),
 'jobs',(select count(*) from pipeline.jobs),
 'open_reviews',(select count(*) from workflow.review_queue where status in ('open','in_review')),
 'evidence',(select count(*) from pipeline.evidence_artifacts),
 'attributes',(select count(*) from pim.attribute_definitions),
 'search_documents',(select count(*) from search.course_documents),
 'search_generation',(select generation from search.projection_state where projection_code='courses')
) end
$$;


ALTER FUNCTION "public"."ui_dashboard"() OWNER TO "postgres";


