CREATE OR REPLACE FUNCTION "public"."ui_evidence_page"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text", "p_evidence_type" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'captured'::"text", "p_direction" "text" DEFAULT 'desc'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pipeline', 'auth'
    AS $$ declare v_limit int:=least(greatest(coalesce(p_limit,50),1),200);v_offset int:=greatest(coalesce(p_offset,0),0);v_dir text:=case when lower(coalesce(p_direction,'desc'))='asc' then 'asc' else 'desc' end; begin if auth.uid() is null then raise exception 'authentication required'; end if; return (with base as (select e.id,e.entity_id,e.evidence_type,s.label source_label,s.source_type,e.source_url,e.content_hash,e.mime_type,e.captured_at,e.valid_from,e.valid_to,e.supersedes_evidence_id from pipeline.evidence_artifacts e left join pipeline.sources s on s.id=e.source_id where (nullif(trim(coalesce(p_query,'')),'') is null or coalesce(e.evidence_type,'') ilike '%'||trim(p_query)||'%' or coalesce(s.label,'') ilike '%'||trim(p_query)||'%' or coalesce(e.source_url,'') ilike '%'||trim(p_query)||'%' or coalesce(e.content_hash,'') ilike '%'||trim(p_query)||'%') and (nullif(trim(coalesce(p_evidence_type,'')),'') is null or e.evidence_type=trim(p_evidence_type))),numbered as(select *,count(*) over() total_count from base),ordered as(select * from numbered order by case when v_dir='asc' then captured_at end asc nulls first,case when v_dir='desc' then captured_at end desc nulls last,id limit v_limit offset v_offset) select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset) from ordered o); end $$;


