CREATE OR REPLACE FUNCTION "public"."ui_international_student_observations"("p_period_end" "date" DEFAULT NULL::"date", "p_subdivision_code" "text" DEFAULT NULL::"text", "p_sector" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 1000) RETURNS TABLE("observation_id" "uuid", "host_country_code" "text", "subdivision_code" "text", "subdivision_name" "text", "survey_code" "text", "metric_code" "text", "metric_name" "text", "unit" "text", "audience" "text", "period_start" "date", "period_end" "date", "period_type" "text", "source_geography_type" "text", "source_geography_key" "text", "source_geography_name" "text", "source_remoteness_area" "text", "source_sector_code" "text", "source_study_area_code" "text", "source_study_area_name" "text", "canonical_field_code" "text", "canonical_field_name" "text", "metric_value" bigint, "is_suppressed" boolean, "suppression_code" "text", "source_label" "text", "source_url" "text", "collection_version" "text", "evidence_hash" "text", "evidence_storage_path" "text", "provider_id" "uuid", "course_id" "uuid", "status" "text", "metadata" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'pipeline', 'auth'
    AS $$
select
  o.id,
  trim(c.iso_alpha2)::text,
  s.code,
  s.name,
  os.code,
  m.code,
  m.name,
  m.unit,
  o.audience,
  o.period_start,
  o.period_end,
  o.period_type,
  o.source_geography_type,
  o.source_geography_key,
  o.source_geography_name,
  o.source_remoteness_area,
  o.source_sector_code,
  o.source_study_area_code,
  o.source_study_area_name,
  f.code,
  f.name,
  o.metric_value,
  o.is_suppressed,
  o.suppression_code,
  ps.label,
  ps.url,
  ps.metadata->>'collection_version',
  ea.content_hash,
  ea.storage_path,
  o.provider_id,
  o.course_id,
  o.status,
  o.metadata
from catalogue.student_flow_observations o
join ref.countries c on c.id=o.host_country_id
join ref.outcome_surveys os on os.id=o.survey_id
join ref.outcome_metrics m on m.id=o.metric_id
join pipeline.sources ps on ps.id=o.source_id
join pipeline.evidence_artifacts ea on ea.id=o.evidence_id
left join ref.subdivisions s on s.id=o.subdivision_id
left join ref.fields_of_study f on f.id=o.field_of_study_id
where auth.uid() is not null
  and os.source_family='PRISMS'
  and (p_period_end is null or o.period_end=p_period_end)
  and (p_subdivision_code is null or s.code=p_subdivision_code)
  and (p_sector is null or o.source_sector_code=p_sector)
order by o.period_end desc,s.code,o.source_geography_name,o.source_sector_code,o.source_study_area_code,m.code
limit least(greatest(coalesce(p_limit,1000),1),5000);
$$;


ALTER FUNCTION "public"."ui_international_student_observations"("p_period_end" "date", "p_subdivision_code" "text", "p_sector" "text", "p_limit" integer) OWNER TO "postgres";


