CREATE OR REPLACE FUNCTION "public"."ui_layer1_job"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'security', 'pipeline'
    AS $$
declare
  v_rank int;
  v_job pipeline.jobs%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  select coalesce(max(r.rank),0) into v_rank
  from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=auth.uid() and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
  if v_rank < 6 then raise exception 'platform_admin required'; end if;

  select * into v_job from pipeline.jobs where id=p_job_id and job_type='regulatory_sync';
  if not found then return null; end if;
  return jsonb_build_object(
    'jobId',v_job.id,'status',v_job.status,'createdAt',v_job.created_at,'startedAt',v_job.started_at,
    'completedAt',v_job.completed_at,'error',v_job.error_text,'payload',v_job.payload,'result',v_job.result
  );
end $$;


ALTER FUNCTION "public"."ui_layer1_job"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_layer1_latest_job"("p_country_code" "text" DEFAULT 'AU'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'security', 'pipeline'
    AS $$
declare
  v_rank int;
  v_job pipeline.jobs%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  select coalesce(max(r.rank),0) into v_rank
  from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=auth.uid() and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
  if v_rank < 6 then raise exception 'platform_admin required'; end if;

  select * into v_job from pipeline.jobs
  where job_type='regulatory_sync' and upper(coalesce(payload->>'country_code',''))=upper(p_country_code)
  order by created_at desc limit 1;
  if not found then return null; end if;
  return jsonb_build_object(
    'jobId',v_job.id,'status',v_job.status,'createdAt',v_job.created_at,'startedAt',v_job.started_at,
    'completedAt',v_job.completed_at,'error',v_job.error_text,'payload',v_job.payload,'result',v_job.result
  );
end $$;


ALTER FUNCTION "public"."ui_layer1_latest_job"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_prisms_filter_options"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'auth'
    AS $$
  select case when auth.uid() is null or security.current_role_rank() < 1 then null else jsonb_build_object(
    'subdivisions',coalesce((select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name,'count',x.cnt) order by x.name) from (select sub.code,sub.name,count(*)::bigint cnt from catalogue.student_flow_observations sfo join ref.outcome_surveys os on os.id=sfo.survey_id left join ref.subdivisions sub on sub.id=sfo.subdivision_id where os.code='prisms_international_students' and sub.id is not null group by sub.code,sub.name)x),'[]'::jsonb),
    'study_areas','[]'::jsonb,
    'sectors',coalesce((select jsonb_agg(jsonb_build_object('code',x.code,'name',initcap(replace(x.code,'_',' ')),'count',x.cnt) order by x.code) from (select source_sector_code code,count(*)::bigint cnt from catalogue.student_flow_observations sfo join ref.outcome_surveys os on os.id=sfo.survey_id where os.code='prisms_international_students' and source_sector_code is not null group by source_sector_code)x),'[]'::jsonb),
    'remoteness',coalesce((select jsonb_agg(jsonb_build_object('code',x.name,'name',x.name,'count',x.cnt) order by x.name) from (select source_remoteness_area name,count(*)::bigint cnt from catalogue.student_flow_observations sfo join ref.outcome_surveys os on os.id=sfo.survey_id where os.code='prisms_international_students' and source_remoteness_area is not null group by source_remoteness_area)x),'[]'::jsonb)
  ) end
$$;


ALTER FUNCTION "public"."ui_prisms_filter_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_prisms_student_flow_page"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text", "p_subdivision_code" "text" DEFAULT NULL::"text", "p_study_area_code" "text" DEFAULT NULL::"text", "p_sector_code" "text" DEFAULT NULL::"text", "p_remoteness_area" "text" DEFAULT NULL::"text", "p_suppressed" boolean DEFAULT NULL::boolean, "p_sort" "text" DEFAULT 'geography'::"text", "p_direction" "text" DEFAULT 'asc'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'pipeline', 'auth'
    AS $$
declare
  v_limit integer:=least(greatest(coalesce(p_limit,50),1),200);
  v_offset integer:=greatest(coalesce(p_offset,0),0);
  v_sort text:=lower(coalesce(p_sort,'geography'));
  v_dir text:=case when lower(coalesce(p_direction,'asc'))='desc' then 'desc' else 'asc' end;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank() < 1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  return (
    with raw as (
      select sfo.*,om.code metric_code,sub.code subdivision_code,sub.name subdivision_name,
        src.label source_label,src.url source_url,e.source_url evidence_url,e.captured_at evidence_captured_at,
        nullif(sfo.metadata->>'source_row','')::integer source_row
      from catalogue.student_flow_observations sfo
      join ref.outcome_surveys os on os.id=sfo.survey_id and os.code='prisms_international_students'
      join ref.outcome_metrics om on om.id=sfo.metric_id
      left join ref.subdivisions sub on sub.id=sfo.subdivision_id
      left join pipeline.sources src on src.id=sfo.source_id
      left join pipeline.evidence_artifacts e on e.id=sfo.evidence_id
      where (nullif(trim(coalesce(p_query,'')),'') is null
        or coalesce(sfo.source_geography_name,'') ilike '%'||trim(p_query)||'%'
        or coalesce(sfo.source_study_area_name,'') ilike '%'||trim(p_query)||'%'
        or coalesce(sfo.source_sector_code,'') ilike '%'||trim(p_query)||'%'
        or coalesce(sfo.source_remoteness_area,'') ilike '%'||trim(p_query)||'%')
        and (nullif(trim(coalesce(p_subdivision_code,'')),'') is null or sub.code=upper(trim(p_subdivision_code)))
        and (nullif(trim(coalesce(p_study_area_code,'')),'') is null or sfo.source_study_area_code=trim(p_study_area_code))
        and (nullif(trim(coalesce(p_sector_code,'')),'') is null or sfo.source_sector_code=trim(p_sector_code))
        and (nullif(trim(coalesce(p_remoteness_area,'')),'') is null or sfo.source_remoteness_area=trim(p_remoteness_area))
        and (p_suppressed is null or sfo.is_suppressed=p_suppressed)
    ), paired as (
      select md5(concat_ws('|',coalesce(source_row::text,''),coalesce(source_geography_key,''),coalesce(source_study_area_code,''),coalesce(source_sector_code,''),coalesce(source_remoteness_area,''),coalesce(period_start::text,''),coalesce(period_end::text,''))) id,
        source_row,subdivision_code,subdivision_name,source_geography_key,source_geography_name,source_geography_type,
        source_study_area_code,source_study_area_name,source_sector_code,source_remoteness_area,period_start,period_end,period_type,audience,
        max(metric_value) filter(where metric_code='enrolments') enrolments,
        max(metric_value) filter(where metric_code='commencements') commencements,
        bool_or(is_suppressed) suppressed,
        string_agg(distinct suppression_code,', ' order by suppression_code) filter(where suppression_code is not null) suppression_codes,
        count(distinct evidence_id)::bigint evidence_count,
        max(evidence_captured_at) evidence_captured_at,max(evidence_url) evidence_url,max(source_label) source_label,max(source_url) source_url,
        max(updated_at) updated_at
      from raw
      group by source_row,subdivision_code,subdivision_name,source_geography_key,source_geography_name,source_geography_type,source_study_area_code,source_study_area_name,source_sector_code,source_remoteness_area,period_start,period_end,period_type,audience,source_nationality_code,source_provider_type
    ), numbered as (select *,count(*) over()::bigint total_count from paired), ordered as (
      select * from numbered order by
        case when v_sort='geography' and v_dir='asc' then lower(source_geography_name) end asc,
        case when v_sort='geography' and v_dir='desc' then lower(source_geography_name) end desc,
        case when v_sort='state' and v_dir='asc' then subdivision_code end asc,
        case when v_sort='state' and v_dir='desc' then subdivision_code end desc,
        case when v_sort='study_area' and v_dir='asc' then lower(source_study_area_name) end asc,
        case when v_sort='study_area' and v_dir='desc' then lower(source_study_area_name) end desc,
        case when v_sort='enrolments' and v_dir='asc' then enrolments end asc nulls first,
        case when v_sort='enrolments' and v_dir='desc' then enrolments end desc nulls last,
        case when v_sort='commencements' and v_dir='asc' then commencements end asc nulls first,
        case when v_sort='commencements' and v_dir='desc' then commencements end desc nulls last,
        case when v_sort='period' and v_dir='asc' then period_end end asc,
        case when v_sort='period' and v_dir='desc' then period_end end desc,
        lower(source_geography_name),lower(source_study_area_name),source_sector_code,source_row,id
      limit v_limit offset v_offset
    )
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir) from ordered o
  );
end $$;


ALTER FUNCTION "public"."ui_prisms_student_flow_page"("p_limit" integer, "p_offset" integer, "p_query" "text", "p_subdivision_code" "text", "p_study_area_code" "text", "p_sector_code" "text", "p_remoteness_area" "text", "p_suppressed" boolean, "p_sort" "text", "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_provider_detail"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'pipeline', 'integration', 'ref', 'search', 'auth'
    AS $$
select case when p.id is null then null else jsonb_build_object(
'id',p.id,'stable_key',p.stable_key,'canonical_name',p.canonical_name,'display_name',p.display_name,'country_code',c.iso_alpha2,'currency_code',c.default_currency_code,'city',p.primary_city,'website',p.website,'description',p.description,'lifecycle_status',p.lifecycle_status,'publication_status',p.publication_status,'last_verified_at',p.last_verified_at,
'identifiers',coalesce((select jsonb_agg(jsonb_build_object('scheme',i.scheme,'identifier',i.identifier,'authority',i.issuing_authority,'primary',i.is_primary,'valid_from',i.valid_from,'valid_to',i.valid_to,'source_id',i.source_id,'evidence_id',i.evidence_id,'verified_at',i.verified_at) order by i.is_primary desc,i.scheme) from catalogue.provider_identifiers i where i.provider_id=p.id),'[]'::jsonb),
'registrations',coalesce((select jsonb_agg(jsonb_build_object('scheme',r.registration_scheme,'code',r.registration_code,'classification',r.provider_classification,'status',r.status,'valid_from',r.valid_from,'valid_to',r.valid_to,'source_id',r.source_id,'evidence_id',r.evidence_id,'checked_at',r.checked_at) order by r.registration_scheme) from catalogue.provider_registrations r where r.provider_id=p.id),'[]'::jsonb),
'sources',coalesce((select jsonb_agg(distinct jsonb_build_object('id',s.id,'label',s.label,'type',s.source_type,'url',s.url,'status',s.status,'trust_rank',s.trust_rank)) from pipeline.sources s where s.provider_id=p.id or s.id=p.canonical_source_id),'[]'::jsonb),
'evidence',coalesce((with ids as (
 select e.id from pipeline.evidence_artifacts e where e.entity_id=p.id
 union select i.evidence_id from catalogue.provider_identifiers i where i.provider_id=p.id and i.evidence_id is not null
 union select r.evidence_id from catalogue.provider_registrations r where r.provider_id=p.id and r.evidence_id is not null
) select jsonb_agg(jsonb_build_object('id',e.id,'type',e.evidence_type,'source_url',e.source_url,'hash',e.content_hash,'captured_at',e.captured_at,'source_id',e.source_id) order by e.captured_at desc) from ids join pipeline.evidence_artifacts e using(id)),'[]'::jsonb),
'course_count',(select count(*) from catalogue.courses cc where cc.provider_id=p.id),
'projected_course_count',(select count(*) from search.course_documents d where d.provider_id=p.id),
'search_status',case when exists(select 1 from search.course_documents d where d.provider_id=p.id) then 'projected' else 'not_projected' end
) end from catalogue.providers p join ref.countries c on c.id=p.country_id where p.id=p_provider_id and auth.uid() is not null;
$$;


ALTER FUNCTION "public"."ui_provider_detail"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_provider_filter_options"("p_country_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'ref', 'catalogue', 'auth'
    AS $$
begin
 if auth.uid() is null then raise exception 'authentication required'; end if;
 return jsonb_build_object(
 'countries',(select coalesce(jsonb_agg(jsonb_build_object('code',c.iso_alpha2::text,'name',c.name) order by c.name),'[]'::jsonb) from ref.countries c where exists(select 1 from catalogue.providers p where p.country_id=c.id)),
 'subdivisions',(select coalesce(jsonb_agg(jsonb_build_object('code',x.code,'name',x.name,'type',x.subdivision_type) order by x.name),'[]'::jsonb) from (
   select distinct s.code,s.name,s.subdivision_type from ref.subdivisions s join ref.countries c on c.id=s.country_id where (nullif(trim(coalesce(p_country_code,'')),'') is null or c.iso_alpha2::text=upper(trim(p_country_code))) and (exists(select 1 from catalogue.providers p where p.subdivision_id=s.id) or exists(select 1 from catalogue.campuses cp where cp.subdivision_id=s.id))
 ) x));
end $$;


