CREATE OR REPLACE FUNCTION "public"."ui_provider_outcomes"("p_provider_id" "uuid", "p_limit" integer DEFAULT 500) RETURNS TABLE("provider_id" "uuid", "survey_code" "text", "survey_name" "text", "metric_code" "text", "metric_name" "text", "metric_category" "text", "unit" "text", "source_cohort_code" "text", "audience" "text", "collection_year_from" smallint, "collection_year_to" smallint, "metric_value" numeric, "response_count" integer, "confidence_low" numeric, "confidence_high" numeric, "national_benchmark" numeric, "source_label" "text", "source_url" "text", "collection_version" integer, "evidence_hash" "text", "evidence_storage_path" "text", "source_institution_key" "text", "source_study_area_code" "text", "source_metric_code" "text", "observed_at" timestamp with time zone, "status" "text", "metadata" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'pipeline', 'auth'
    AS $$
  select
    po.provider_id,
    os.code,
    os.name,
    om.code,
    om.name,
    om.category,
    om.unit,
    po.source_cohort_code,
    po.audience,
    po.collection_year_from,
    po.collection_year_to,
    po.metric_value,
    po.response_count,
    po.confidence_low,
    po.confidence_high,
    po.national_benchmark,
    ps.label,
    ps.url,
    nullif(ps.metadata->>'collection_version','')::integer,
    ea.content_hash,
    ea.storage_path,
    po.source_institution_key,
    po.source_study_area_code,
    po.source_metric_code,
    po.observed_at,
    po.status,
    po.metadata
  from catalogue.provider_outcomes po
  join ref.outcome_surveys os on os.id=po.survey_id
  join ref.outcome_metrics om on om.id=po.metric_id
  join pipeline.sources ps on ps.id=po.source_id
  left join pipeline.evidence_artifacts ea on ea.id=po.evidence_id
  where po.provider_id=p_provider_id
    and os.source_family='QILT'
    and auth.uid() is not null
  order by po.collection_year_to desc, os.code, po.source_cohort_code, om.category, om.code
  limit least(greatest(coalesce(p_limit,500),1),1000)
$$;


ALTER FUNCTION "public"."ui_provider_outcomes"("p_provider_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_provider_related_courses"("p_provider_id" "uuid", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text", "p_lifecycle_status" "text" DEFAULT NULL::"text", "p_publication_status" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'auth'
    AS $$
with base as (
  select c.id,c.stable_key,c.canonical_title,c.display_title,c.course_code,c.course_url,c.delivery_mode,c.lifecycle_status,c.publication_status,c.last_verified_at,c.created_at,c.updated_at
  from catalogue.courses c
  where auth.uid() is not null and c.provider_id=p_provider_id
    and (nullif(trim(coalesce(p_query,'')),'') is null or coalesce(c.display_title,c.canonical_title,'') ilike '%'||trim(p_query)||'%' or coalesce(c.course_code,'') ilike '%'||trim(p_query)||'%' or coalesce(c.stable_key,'') ilike '%'||trim(p_query)||'%')
    and (nullif(trim(coalesce(p_lifecycle_status,'')),'') is null or c.lifecycle_status=trim(p_lifecycle_status))
    and (nullif(trim(coalesce(p_publication_status,'')),'') is null or c.publication_status=trim(p_publication_status))
), numbered as (select *,count(*) over() total_count from base)
select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(x)-'total_count' order by lower(coalesce(x.display_title,x.canonical_title))),'[]'::jsonb),'total',coalesce(max(x.total_count),0),'limit',least(greatest(coalesce(p_limit,25),1),100),'offset',greatest(coalesce(p_offset,0),0))
from (select * from numbered order by lower(coalesce(display_title,canonical_title)) limit least(greatest(coalesce(p_limit,25),1),100) offset greatest(coalesce(p_offset,0),0)) x;
$$;


ALTER FUNCTION "public"."ui_provider_related_courses"("p_provider_id" "uuid", "p_limit" integer, "p_offset" integer, "p_query" "text", "p_lifecycle_status" "text", "p_publication_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_provider_related_evidence"("p_provider_id" "uuid", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text", "p_evidence_type" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'pipeline', 'auth'
    AS $$
with ids as (
  select e.id from pipeline.evidence_artifacts e where e.entity_id=p_provider_id
  union select pi.evidence_id from catalogue.provider_identifiers pi where pi.provider_id=p_provider_id and pi.evidence_id is not null
  union select pr.evidence_id from catalogue.provider_registrations pr where pr.provider_id=p_provider_id and pr.evidence_id is not null
), base as (
  select e.id,e.evidence_type,e.source_url,e.content_hash,e.mime_type,e.captured_at,e.valid_from,e.valid_to,e.supersedes_evidence_id,s.label source_label,s.source_type
  from ids i join pipeline.evidence_artifacts e on e.id=i.id left join pipeline.sources s on s.id=e.source_id
  where auth.uid() is not null
    and (nullif(trim(coalesce(p_query,'')),'') is null or coalesce(e.evidence_type,'') ilike '%'||trim(p_query)||'%' or coalesce(s.label,'') ilike '%'||trim(p_query)||'%' or coalesce(e.source_url,'') ilike '%'||trim(p_query)||'%' or coalesce(e.content_hash,'') ilike '%'||trim(p_query)||'%')
    and (nullif(trim(coalesce(p_evidence_type,'')),'') is null or e.evidence_type=trim(p_evidence_type))
), numbered as (select *,count(*) over() total_count from base)
select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(x)-'total_count' order by x.captured_at desc nulls last),'[]'::jsonb),'total',coalesce(max(x.total_count),0),'limit',least(greatest(coalesce(p_limit,25),1),100),'offset',greatest(coalesce(p_offset,0),0))
from (select * from numbered order by captured_at desc nulls last limit least(greatest(coalesce(p_limit,25),1),100) offset greatest(coalesce(p_offset,0),0)) x;
$$;


ALTER FUNCTION "public"."ui_provider_related_evidence"("p_provider_id" "uuid", "p_limit" integer, "p_offset" integer, "p_query" "text", "p_evidence_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_providers_list"("p_limit" integer DEFAULT 500) RETURNS TABLE("id" "uuid", "stable_key" "text", "canonical_name" "text", "display_name" "text", "country_code" character, "city" "text", "website" "text", "lifecycle_status" "text", "publication_status" "text", "course_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'auth'
    AS $$
select p.id,p.stable_key,p.canonical_name,p.display_name,c.iso_alpha2,p.primary_city,p.website,p.lifecycle_status,p.publication_status,count(cr.id)::bigint
from catalogue.providers p join ref.countries c on c.id=p.country_id left join catalogue.courses cr on cr.provider_id=p.id
where auth.uid() is not null
group by p.id,c.iso_alpha2
order by coalesce(p.display_name,p.canonical_name)
limit least(greatest(coalesce(p_limit,500),1),1000)
$$;


ALTER FUNCTION "public"."ui_providers_list"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_qilt_filter_options"("p_survey_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'auth'
    AS $$
  select case when auth.uid() is null or security.current_role_rank() < 1 then null else jsonb_build_object(
    'surveys',coalesce((select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name,'count',x.cnt) order by x.name) from (select os.code,os.name,count(*)::bigint cnt from catalogue.provider_outcomes po join ref.outcome_surveys os on os.id=po.survey_id where os.code like 'qilt_%' group by os.code,os.name)x),'[]'::jsonb),
    'metrics','[]'::jsonb,
    'providers','[]'::jsonb,
    'statuses',coalesce((select jsonb_agg(jsonb_build_object('code',x.status,'name',initcap(replace(x.status,'_',' ')),'count',x.cnt) order by x.status) from (select po.status,count(*)::bigint cnt from catalogue.provider_outcomes po join ref.outcome_surveys os on os.id=po.survey_id where os.code like 'qilt_%' group by po.status)x),'[]'::jsonb),
    'years',coalesce((select jsonb_agg(jsonb_build_object('value',x.y,'label',x.y::text,'count',x.cnt) order by x.y desc) from (select collection_year_to y,count(*)::bigint cnt from catalogue.provider_outcomes po join ref.outcome_surveys os on os.id=po.survey_id where os.code like 'qilt_%' and collection_year_to is not null group by collection_year_to)x),'[]'::jsonb)
  ) end
$$;


ALTER FUNCTION "public"."ui_qilt_filter_options"("p_survey_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_qilt_outcomes_page"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text", "p_survey_code" "text" DEFAULT NULL::"text", "p_metric_code" "text" DEFAULT NULL::"text", "p_provider_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text", "p_year" integer DEFAULT NULL::integer, "p_sort" "text" DEFAULT 'provider'::"text", "p_direction" "text" DEFAULT 'asc'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'catalogue', 'ref', 'pipeline', 'auth'
    AS $$
declare
  v_limit integer:=least(greatest(coalesce(p_limit,50),1),200);
  v_offset integer:=greatest(coalesce(p_offset,0),0);
  v_sort text:=lower(coalesce(p_sort,'provider'));
  v_dir text:=case when lower(coalesce(p_direction,'asc'))='desc' then 'desc' else 'asc' end;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank() < 1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  return (
    with base as (
      select po.id,po.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,
        c.iso_alpha2::text country_code,c.name country_name,
        os.code survey_code,os.name survey_name,om.code metric_code,om.name metric_name,om.unit metric_unit,om.category metric_category,
        po.metric_value,po.national_benchmark,po.response_count,po.audience,po.collection_year_from,po.collection_year_to,
        po.observed_at,po.status,po.source_institution_key,po.source_cohort_code,po.updated_at,
        po.evidence_id,e.source_url evidence_url,e.captured_at evidence_captured_at,
        po.source_id,s.label source_label,s.url source_url
      from catalogue.provider_outcomes po
      join catalogue.providers p on p.id=po.provider_id
      join ref.countries c on c.id=p.country_id
      join ref.outcome_surveys os on os.id=po.survey_id and os.code like 'qilt_%'
      join ref.outcome_metrics om on om.id=po.metric_id
      left join pipeline.evidence_artifacts e on e.id=po.evidence_id
      left join pipeline.sources s on s.id=po.source_id
      where (nullif(trim(coalesce(p_query,'')),'') is null
          or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_query)||'%'
          or os.name ilike '%'||trim(p_query)||'%'
          or om.name ilike '%'||trim(p_query)||'%'
          or coalesce(po.source_institution_key,'') ilike '%'||trim(p_query)||'%')
        and (nullif(trim(coalesce(p_survey_code,'')),'') is null or os.code=trim(p_survey_code))
        and (nullif(trim(coalesce(p_metric_code,'')),'') is null or om.code=trim(p_metric_code))
        and (p_provider_id is null or po.provider_id=p_provider_id)
        and (nullif(trim(coalesce(p_status,'')),'') is null or po.status=trim(p_status))
        and (p_year is null or p_year between coalesce(po.collection_year_from,p_year) and coalesce(po.collection_year_to,p_year))
    ), numbered as (select *,count(*) over()::bigint total_count from base), ordered as (
      select * from numbered order by
        case when v_sort='provider' and v_dir='asc' then lower(provider_name) end asc,
        case when v_sort='provider' and v_dir='desc' then lower(provider_name) end desc,
        case when v_sort='survey' and v_dir='asc' then survey_code end asc,
        case when v_sort='survey' and v_dir='desc' then survey_code end desc,
        case when v_sort='metric' and v_dir='asc' then metric_code end asc,
        case when v_sort='metric' and v_dir='desc' then metric_code end desc,
        case when v_sort='value' and v_dir='asc' then metric_value end asc nulls first,
        case when v_sort='value' and v_dir='desc' then metric_value end desc nulls last,
        case when v_sort='benchmark' and v_dir='asc' then national_benchmark end asc nulls first,
        case when v_sort='benchmark' and v_dir='desc' then national_benchmark end desc nulls last,
        case when v_sort='responses' and v_dir='asc' then response_count end asc nulls first,
        case when v_sort='responses' and v_dir='desc' then response_count end desc nulls last,
        case when v_sort='year' and v_dir='asc' then collection_year_to end asc nulls first,
        case when v_sort='year' and v_dir='desc' then collection_year_to end desc nulls last,
        lower(provider_name),survey_code,metric_code,id
      limit v_limit offset v_offset
    )
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir) from ordered o
  );
end $$;


ALTER FUNCTION "public"."ui_qilt_outcomes_page"("p_limit" integer, "p_offset" integer, "p_query" "text", "p_survey_code" "text", "p_metric_code" "text", "p_provider_id" "uuid", "p_status" "text", "p_year" integer, "p_sort" "text", "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_regulatory_sources_list"() RETURNS TABLE("country_id" "uuid", "country_code" "text", "country_name" "text", "catalogue_status" "text", "provider_ingestion_enabled" boolean, "course_ingestion_enabled" boolean, "source_id" "uuid", "source_type" "text", "source_label" "text", "source_url" "text", "trust_rank" smallint, "source_status" "text", "last_checked_at" timestamp with time zone, "last_success_at" timestamp with time zone, "last_failure_at" timestamp with time zone, "last_error" "text", "source_metadata" "jsonb", "system_code" "text", "system_name" "text", "system_type" "text", "system_base_url" "text", "system_status" "text", "system_config" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'ref', 'pipeline', 'integration', 'security'
    AS $$
declare
  v_rank integer;
begin
  select max(r.rank)
    into v_rank
  from security.user_roles ur
  join security.roles r on r.code = ur.role_code
  where ur.user_id = auth.uid()
    and (ur.expires_at is null or ur.expires_at > now());

  if coalesce(v_rank, 0) < 6 then
    raise exception 'platform_admin role required' using errcode = '42501';
  end if;

  return query
  select
    c.id,
    c.iso_alpha2::text,
    c.name,
    c.catalogue_status,
    c.provider_ingestion_enabled,
    c.course_ingestion_enabled,
    s.id,
    s.source_type,
    s.label,
    s.url,
    s.trust_rank,
    s.status,
    s.last_checked_at,
    s.last_success_at,
    s.last_failure_at,
    s.last_error,
    s.metadata,
    i.code,
    i.name,
    i.system_type,
    i.base_url,
    i.status,
    i.config
  from ref.countries c
  left join pipeline.sources s on s.country_id = c.id and s.provider_id is null
  left join integration.systems i on i.id = s.system_id
  where c.catalogue_status in ('pilot','active')
     or c.provider_ingestion_enabled
     or c.course_ingestion_enabled
  order by c.name, s.trust_rank nulls last, s.label nulls last;
end;
$$;


