    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'api'
    AS $$ select api.website_integration_auth_v1(p_token_sha256); $$;


ALTER FUNCTION "public"."website_edge_auth_v1"("p_token_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_edge_course_search_v1"("p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'search', 'catalogue', 'ref', 'security', 'api'
    AS $_$
declare
  f jsonb := coalesce(p_filters,'{}'::jsonb);
  v_page int := coalesce(p_page,1);
  v_size int := coalesce(p_page_size,20);
  v_kw text := nullif(btrim(coalesce(f->>'keyword','')),'');
  v_countries text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(coalesce(f->'country_codes',f->'country_code'))) x);
  v_areas text[] := api.website_text_array(f->'study_area_codes');
  v_levels text[] := api.website_text_array(f->'study_level_codes');
  v_subdivs text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(f->'subdivision_codes')) x);
  v_cities text[] := (select array_agg(lower(x)) from unnest(api.website_text_array(coalesce(f->'cities',f->'city'))) x);
  v_postcodes text[] := api.website_text_array(f->'postcodes');
  v_providers text[] := api.website_text_array(f->'provider_ids');
  v_groups text[] := (select array_agg(lower(regexp_replace(btrim(x),'^au_','','i'))) from unnest(api.website_text_array(coalesce(f->'university_groups',f->'university_group'))) x);
  v_modes text[] := api.website_text_array(f->'delivery_modes');
  v_min numeric := nullif(f->>'tuition_annual_min','')::numeric;
  v_max numeric := nullif(f->>'tuition_annual_max','')::numeric;
  v_result jsonb;
begin
  if v_page < 1 then raise exception 'INVALID_INPUT: page must be >= 1' using errcode='22023'; end if;
  if v_size < 1 or v_size > 50 then raise exception 'INVALID_INPUT: page_size must be 1-50' using errcode='22023'; end if;
  if (v_min is not null and v_min < 0) or (v_max is not null and v_max < 0) then raise exception 'INVALID_INPUT: tuition bounds must be >= 0' using errcode='22023'; end if;

  with base as (
    select d.*,
      round(c.duration_value * case lower(coalesce(c.duration_unit,'')) when 'weeks' then 12.0/52 when 'months' then 1 when 'years' then 12 else null end)::int as duration_months,
      case lower(coalesce(c.duration_unit,'')) when 'weeks' then c.duration_value when 'months' then c.duration_value*52/12 when 'years' then c.duration_value*52 end as duration_weeks
    from search.course_documents d
    left join catalogue.courses c on c.id = d.course_id
    where not exists (select 1 from security.layer4_search_blocked_courses b where b.course_id = d.course_id)
      and (v_kw is null
           or d.search_tsv @@ websearch_to_tsquery('english', v_kw)
           or d.course_title ilike '%'||v_kw||'%'
           or d.provider_name ilike '%'||v_kw||'%'
           or lower(d.course_code) = lower(v_kw)
           or lower(d.course_stable_key) = lower(v_kw))
      and (v_countries is null or d.country_code = any(v_countries))
      and (v_areas is null or d.primary_field_code = any(v_areas))
      and (v_levels is null or d.study_level_code = any(v_levels))
      and (v_subdivs is null or d.subdivision_codes && v_subdivs)
      and (v_providers is null or d.provider_stable_key = any(v_providers))
      and (v_groups is null or exists (select 1 from catalogue.provider_collection_memberships gm join ref.institution_collections gic on gic.id=gm.collection_id
            where gm.provider_id=d.provider_id and gm.status='active' and (gm.valid_to is null or gm.valid_to>=current_date)
              and gic.collection_type='university_group' and gic.status='active' and replace(gic.code,'au_','') = any(v_groups)))
      and (v_modes is null or d.delivery_modes && v_modes)
      and (not coalesce((f->>'has_intake')::boolean,false) or d.has_intake)
      and (not coalesce((f->>'has_english')::boolean,false) or d.has_english)
      and (not coalesce((f->>'has_official_url')::boolean,false) or d.has_link)
      and (v_cities is null and v_postcodes is null or exists (
            select 1 from catalogue.course_campuses cc join catalogue.campuses k on k.id = cc.campus_id left join pipeline.campus_regional_class rc on rc.campus_id = k.id
            where cc.course_id = d.course_id
              and (v_cities is null or lower(btrim(k.city)) = any(v_cities) or lower(rc.metro_area) = any(v_cities))
              and (v_postcodes is null or btrim(k.postcode) = any(v_postcodes))))
  ), priced as (
    select b.*, t.*
    from base b
    cross join lateral (
      select
        case when pt.amount is not null then pt.amount else b.regulatory_tuition_amount end as t_amount,
        case when pt.amount is not null then pt.currency else b.regulatory_tuition_currency end as t_currency,
        case when pt.amount is not null then
               case when pt.basis ~* 'total|course' and pt.basis !~* 'annual' then 'course_total'
                    when pt.basis ~* 'indicative' then 'indicative_annual'
                    when pt.basis ~* 'annual|per.?year|yearly' then 'annual'
                    else 'unspecified' end
             when b.regulatory_tuition_amount is not null then 'course_total' end as t_basis,
        case when pt.amount is not null then 'provider_current' when b.regulatory_tuition_amount is not null then 'regulatory_registered' end as t_source,
        pt.basis as t_basis_label
      from (select (o->>'amount')::numeric amount, o->>'currency' currency, o->>'basis' basis
            from jsonb_array_elements(coalesce(b.provider_tuition_options,'[]'::jsonb)) o
            where (o->>'amount') is not null
            order by (o->>'fee_year') desc nulls last limit 1) pt
      right join (select 1) one on true
    ) t
  ), annualised as (
    select p.*,
      case when p.t_basis in ('annual','indicative_annual') then p.t_amount
           when p.t_basis = 'course_total' and p.duration_weeks >= 52 then round(p.t_amount / (p.duration_weeks/52.0))
      end as annual_amount,
      (p.t_basis = 'course_total' and p.duration_weeks >= 52) as annual_is_derived
    from priced p
  ), filtered as (
    select * from annualised a
    where (not coalesce((f->>'has_tuition')::boolean,false) or a.t_amount is not null)
      and (v_min is null or a.annual_amount >= v_min)
      and (v_max is null or a.annual_amount <= v_max)
  ), counted as (select count(*) total from filtered),
  paged as (
    select * from filtered order by lower(course_title), course_stable_key
    limit v_size offset (v_page-1)*v_size
  )
  select jsonb_build_object(
    'contract_version','website-search-v1',
    'total',(select total from counted),
    'page',v_page,'page_size',v_size,'sort','title_asc',
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'course_id',p.course_stable_key,
      'course_code',p.course_code,
      'title',p.course_title,
      'provider',jsonb_build_object('provider_id',p.provider_stable_key,'name',security.provider_presentable_name(p.provider_name),'legal_name',p.provider_name,'university_groups',security.provider_university_groups(p.provider_id)),
      'campus_city',(select security.place_presentable(k.city) from catalogue.course_campuses cc join catalogue.campuses k on k.id=cc.campus_id left join pipeline.campus_regional_class rc on rc.campus_id=k.id
                     where cc.course_id=p.course_id and nullif(btrim(k.city),'') is not null
                     order by (v_cities is not null and (lower(btrim(k.city)) = any(v_cities) or lower(rc.metro_area) = any(v_cities))) desc, (v_postcodes is not null and btrim(k.postcode) = any(v_postcodes)) desc, cc.is_primary desc nulls last, k.city limit 1),
      'campus_metro_area',(select rc.metro_area from catalogue.course_campuses cc join catalogue.campuses k on k.id=cc.campus_id left join pipeline.campus_regional_class rc on rc.campus_id=k.id
                     where cc.course_id=p.course_id and nullif(btrim(k.city),'') is not null
                     order by (v_cities is not null and (lower(btrim(k.city)) = any(v_cities) or lower(rc.metro_area) = any(v_cities))) desc, (v_postcodes is not null and btrim(k.postcode) = any(v_postcodes)) desc, cc.is_primary desc nulls last, k.city limit 1),
      'campuses',coalesce((select jsonb_agg(jsonb_build_object('city',security.place_presentable(k.city),'postcode',k.postcode,'subdivision_code',s.code,'is_primary',coalesce(cc.is_primary,false),'metro_area',rc.metro_area,'regional_category',rc.category,'regional_category_name',rc.category_name)
                           order by (v_cities is not null and (lower(btrim(k.city)) = any(v_cities) or lower(rc.metro_area) = any(v_cities))) desc, cc.is_primary desc nulls last, k.city)
                           from catalogue.course_campuses cc join catalogue.campuses k on k.id=cc.campus_id
                           left join ref.subdivisions s on s.id=k.subdivision_id left join pipeline.campus_regional_class rc on rc.campus_id=k.id
                           where cc.course_id=p.course_id),'[]'::jsonb),
      'study_level',jsonb_build_object('code',p.study_level_code,'name',(select sl.name from ref.study_levels sl where sl.code=p.study_level_code limit 1)),
      'study_area',jsonb_build_object('code',p.primary_field_code,'name',p.primary_field_name),
      'duration_months',p.duration_months,
      'tuition',case when p.t_amount is null then null else jsonb_build_object(
          'amount',p.t_amount,'currency',p.t_currency,'basis',p.t_basis,'basis_label',p.t_basis_label,'source',p.t_source,
          'annual_amount',p.annual_amount,'annual_is_derived',coalesce(p.annual_is_derived,false)) end,
      'intakes',coalesce((select jsonb_agg(distinct jsonb_build_object('label',i->>'label','year',i->'year','start_date',i->'start_date','application_deadline',i->'application_deadline'))
                          from jsonb_array_elements(coalesce(p.intake_options,'[]'::jsonb)) i where nullif(i->>'label','') is not null),'[]'::jsonb),
      'english_requirements',coalesce((select jsonb_agg(jsonb_build_object('test_code',e->>'test_code','test_name',e->>'test_name','min_overall_score',e->'overall_score','min_band_score',(select min(z.v::numeric) from jsonb_each_text(case when jsonb_typeof(e->'component_scores')='object' then e->'component_scores' else '{}'::jsonb end) z(k2,v) where z.v ~ '^[0-9]+(\.[0-9]+)?$')))
                          from jsonb_array_elements(coalesce(p.english_requirement_options,'[]'::jsonb)) e),'[]'::jsonb),
      'entry_requirements',jsonb_build_object('summary',(select 'English: '||string_agg(
                   case e->>'test_code' when 'IELTS' then 'IELTS '||to_char((e->>'overall_score')::numeric,'FM90.0')
                          ||coalesce(' (no band below '||to_char((select min(z.v::numeric) from jsonb_each_text(case when jsonb_typeof(e->'component_scores')='object' then e->'component_scores' else '{}'::jsonb end) z(k2,v) where z.v ~ '^[0-9]+(\.[0-9]+)?$'),'FM90.0')||')','')
                        when 'PTE' then 'PTE Academic '||trim(to_char((e->>'overall_score')::numeric,'FM999'))
                        when 'TOEFL_IBT' then 'TOEFL iBT '||trim(to_char((e->>'overall_score')::numeric,'FM999'))
                        else coalesce(e->>'test_name',e->>'test_code')||' '||(e->>'overall_score') end, ', '
                   order by case e->>'test_code' when 'IELTS' then 1 when 'PTE' then 2 when 'TOEFL_IBT' then 3 else 4 end)
                 from jsonb_array_elements(coalesce(p.english_requirement_options,'[]'::jsonb)) e where (e->>'overall_score') ~ '^[0-9]+(\.[0-9]+)?$'),
                 'basis',case when jsonb_array_length(coalesce(p.english_requirement_options,'[]'::jsonb))>0 then 'english_only' end),
      'official_url',p.official_course_url,
      'delivery_modes',to_jsonb(p.delivery_modes),
      'subdivision_codes',to_jsonb(p.subdivision_codes),
      'publication_status',p.publication_status,
      'freshness',jsonb_build_object('projection_updated_at',p.updated_at,'source_updated_at',p.source_updated_at)
    ) order by lower(p.course_title), p.course_stable_key) from paged p),'[]'::jsonb)
  ) into v_result;
  return v_result;
end $_$;


ALTER FUNCTION "public"."website_edge_course_search_v1"("p_filters" "jsonb", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_edge_course_search_v3_1"("p_query" "text" DEFAULT NULL::"text", "p_country_codes" "text"[] DEFAULT NULL::"text"[], "p_provider_ids" "text"[] DEFAULT NULL::"text"[], "p_subdivision_codes" "text"[] DEFAULT NULL::"text"[], "p_study_level_codes" "text"[] DEFAULT NULL::"text"[], "p_primary_field_codes" "text"[] DEFAULT NULL::"text"[], "p_delivery_modes" "text"[] DEFAULT NULL::"text"[], "p_has_scholarship" boolean DEFAULT NULL::boolean, "p_has_intake" boolean DEFAULT NULL::boolean, "p_has_english" boolean DEFAULT NULL::boolean, "p_has_provider_current_tuition" boolean DEFAULT NULL::boolean, "p_has_regulatory_tuition" boolean DEFAULT NULL::boolean, "p_has_link" boolean DEFAULT NULL::boolean, "p_intake_years" integer[] DEFAULT NULL::integer[], "p_intake_labels" "text"[] DEFAULT NULL::"text"[], "p_english_test_codes" "text"[] DEFAULT NULL::"text"[], "p_min_provider_annual_tuition" numeric DEFAULT NULL::numeric, "p_max_provider_annual_tuition" numeric DEFAULT NULL::numeric, "p_min_regulatory_total_tuition" numeric DEFAULT NULL::numeric, "p_max_regulatory_total_tuition" numeric DEFAULT NULL::numeric, "p_publication_statuses" "text"[] DEFAULT NULL::"text"[], "p_changed_since" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 12, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'api', 'search'
    AS $$
declare v_base jsonb; v_items jsonb;
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  v_base:=public.zoho_edge_course_search_v2(
    p_query,p_country_codes,p_provider_ids,p_subdivision_codes,p_study_level_codes,p_primary_field_codes,p_delivery_modes,
    p_has_scholarship,p_has_intake,p_has_english,p_has_provider_current_tuition,p_has_regulatory_tuition,p_has_link,
    p_intake_years,p_intake_labels,p_english_test_codes,p_min_provider_annual_tuition,p_max_provider_annual_tuition,
    p_min_regulatory_total_tuition,p_max_regulatory_total_tuition,p_publication_statuses,p_changed_since,p_limit,p_offset
  );

  select coalesce(jsonb_agg(
    i.item || jsonb_build_object(
      'intake_summary',case when coalesce((i.item->>'has_intake')::boolean,false) then coalesce((select jsonb_agg(jsonb_build_object(
        'year',x->'year','label',x->'label','start_date',x->'start_date','application_deadline',x->'application_deadline'
      )) from (select x from jsonb_array_elements(coalesce(d.intake_options,'[]'::jsonb)) x limit 3) q),'[]'::jsonb) else '[]'::jsonb end,
      'english_summary',case when coalesce((i.item->>'has_english')::boolean,false) then coalesce((select jsonb_agg(jsonb_build_object(
        'test_code',x->'test_code','test_name',x->'test_name','overall_score',x->'overall_score','component_scores',coalesce(x->'component_scores','{}'::jsonb),'valid_from',x->'valid_from','valid_to',x->'valid_to'
      )) from (select x from jsonb_array_elements(coalesce(d.english_requirement_options,'[]'::jsonb)) x limit 3) q),'[]'::jsonb) else '[]'::jsonb end
    ) order by i.ord
  ),'[]'::jsonb) into v_items
  from jsonb_array_elements(coalesce(v_base->'items','[]'::jsonb)) with ordinality i(item,ord)
  left join search.course_documents d on d.course_stable_key=i.item->>'course_id';

  return jsonb_set(jsonb_set(v_base,'{items}',v_items,true),'{contract_version}','"website-integration-v3.1-pilot"'::jsonb,true)
    || jsonb_build_object(
      'card_enrichment',jsonb_build_object(
        'intake_summary_max_items',3,
        'english_summary_max_items',3,
        'full_detail_action','lookup',
        'null_semantics','summary arrays are empty when no admitted value is present; missing scalar values remain null'
      )
    );
end $$;


ALTER FUNCTION "public"."website_edge_course_search_v3_1"("p_query" "text", "p_country_codes" "text"[], "p_provider_ids" "text"[], "p_subdivision_codes" "text"[], "p_study_level_codes" "text"[], "p_primary_field_codes" "text"[], "p_delivery_modes" "text"[], "p_has_scholarship" boolean, "p_has_intake" boolean, "p_has_english" boolean, "p_has_provider_current_tuition" boolean, "p_has_regulatory_tuition" boolean, "p_has_link" boolean, "p_intake_years" integer[], "p_intake_labels" "text"[], "p_english_test_codes" "text"[], "p_min_provider_annual_tuition" numeric, "p_max_provider_annual_tuition" numeric, "p_min_regulatory_total_tuition" numeric, "p_max_regulatory_total_tuition" numeric, "p_publication_statuses" "text"[], "p_changed_since" timestamp with time zone, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."website_edge_course_search_v3_1"("p_query" "text", "p_country_codes" "text"[], "p_provider_ids" "text"[], "p_subdivision_codes" "text"[], "p_study_level_codes" "text"[], "p_primary_field_codes" "text"[], "p_delivery_modes" "text"[], "p_has_scholarship" boolean, "p_has_intake" boolean, "p_has_english" boolean, "p_has_provider_current_tuition" boolean, "p_has_regulatory_tuition" boolean, "p_has_link" boolean, "p_intake_years" integer[], "p_intake_labels" "text"[], "p_english_test_codes" "text"[], "p_min_provider_annual_tuition" numeric, "p_max_provider_annual_tuition" numeric, "p_min_regulatory_total_tuition" numeric, "p_max_regulatory_total_tuition" numeric, "p_publication_statuses" "text"[], "p_changed_since" timestamp with time zone, "p_limit" integer, "p_offset" integer) IS 'CF-245 website-only additive search card enrichment. Preserves Zoho v2 search/filter semantics; exposes compact admitted intake/English values only and no internal Evidence/security metadata.';



CREATE OR REPLACE FUNCTION "public"."website_edge_rate_check_v1"("p_identity" "text", "p_resource" "text", "p_limit" integer, "p_window_seconds" integer) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'api'
    AS $$ select api.website_integration_rate_check_v1(p_identity,p_resource,p_limit,p_window_seconds); $$;


ALTER FUNCTION "public"."website_edge_rate_check_v1"("p_identity" "text", "p_resource" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_edge_scholarship_search_v1"("p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'catalogue', 'ref', 'security', 'api'
    AS $$
declare
  f jsonb := coalesce(p_filters,'{}'::jsonb);
  v_page int := coalesce(p_page,1);
  v_size int := coalesce(p_page_size,20);
  v_kw text := nullif(btrim(coalesce(f->>'keyword','')),'');
  v_providers text[] := api.website_text_array(f->'provider_ids');
  v_cities text[] := (select array_agg(lower(x)) from unnest(api.website_text_array(coalesce(f->'cities',f->'city'))) x);
  v_levels text[] := api.website_text_array(f->'study_level_codes');
  v_types text[] := api.website_text_array(f->'amount_types');
  v_open boolean := coalesce((f->>'open_only')::boolean,false);
  v_published boolean := coalesce((f->>'published_only')::boolean,false);
  v_groups text[] := (select array_agg(lower(regexp_replace(btrim(x),'^au_','','i'))) from unnest(api.website_text_array(coalesce(f->'university_groups',f->'university_group'))) x);
  v_not_applied text[] := '{}';
  v_result jsonb;
begin
  if v_page < 1 then raise exception 'INVALID_INPUT: page must be >= 1' using errcode='22023'; end if;
  if v_size < 1 or v_size > 50 then raise exception 'INVALID_INPUT: page_size must be 1-50' using errcode='22023'; end if;
  if api.website_text_array(f->'study_area_codes') is not null then v_not_applied := array_append(v_not_applied,'study_area_codes'); end if;
  if f ? 'min_academic_score' then v_not_applied := array_append(v_not_applied,'min_academic_score'); end if;
  if f ? 'citizenship' then v_not_applied := array_append(v_not_applied,'citizenship'); end if;

  with base as (
    select s.*, pr.stable_key provider_key, security.provider_presentable_name(coalesce(nullif(pr.display_name,''), pr.canonical_name)) provider_name,
      case when s.award_value_type='percentage' and s.award_percentage >= 100 and coalesce(s.award_applies_to_fee_type,s.award_fee_basis)='tuition_fee' then 'full_tuition'
           when s.award_value_type='percentage' and coalesce(s.award_applies_to_fee_type,s.award_fee_basis)='tuition_fee' then 'percentage_tuition'
           when s.award_value_type='percentage' then 'percentage'
           when s.award_value_type='fixed_amount' then 'fixed_amount' end as amount_type,
      case when s.application_close_date is null then 'unknown'
           when s.application_close_date < current_date then 'closed' else 'open' end as deadline_status
    from scholarship.scholarships s
    left join catalogue.providers pr on pr.id = s.provider_id
    where s.lifecycle_status = 'active'
      and not exists (select 1 from security.layer4_search_blocked_scholarships b where b.scholarship_id = s.id)
      and not exists (select 1 from security.layer4_search_blocked_providers b where b.provider_id = s.provider_id)
      and (v_kw is null or s.name ilike '%'||v_kw||'%' or pr.canonical_name ilike '%'||v_kw||'%' or pr.display_name ilike '%'||v_kw||'%'
           or exists (select 1 from scholarship.criteria c where c.scholarship_id=s.id and c.human_text ilike '%'||v_kw||'%'))
      and (v_providers is null or pr.stable_key = any(v_providers))
      and (not v_published or s.publication_status='published')
      and (v_groups is null or exists (select 1 from catalogue.provider_collection_memberships gm join ref.institution_collections gic on gic.id=gm.collection_id
            where gm.provider_id=s.provider_id and gm.status='active' and (gm.valid_to is null or gm.valid_to>=current_date)
              and gic.collection_type='university_group' and gic.status='active' and replace(gic.code,'au_','') = any(v_groups)))
      and (v_cities is null or exists (select 1 from catalogue.campuses k where k.provider_id = s.provider_id and lower(btrim(k.city)) = any(v_cities)))
      -- excluded only when a level restriction is stated and none matches
      and (v_levels is null or not exists (select 1 from scholarship.scopes sc where sc.scholarship_id=s.id and sc.study_level_id is not null and sc.include_exclude='include')
           or exists (select 1 from scholarship.scopes sc join ref.study_levels sl on sl.id=sc.study_level_id
                      where sc.scholarship_id=s.id and sc.include_exclude='include' and sl.code = any(v_levels)))
  ), filtered as (
    select * from base b
    where (not v_open or b.deadline_status <> 'closed')
      and (v_types is null or b.amount_type = any(v_types))
  ), counted as (select count(*) total from filtered),
  paged as (
    select * from filtered
    order by (deadline_status='open') desc, application_close_date nulls last, lower(name), stable_key
    limit v_size offset (v_page-1)*v_size
  )
  select jsonb_build_object(
    'contract_version','website-scholarship-search-v1',
    'total',(select total from counted),
    'page',v_page,'page_size',v_size,'sort','open_deadline_first',
    'filters_not_applied',to_jsonb(v_not_applied),
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'scholarship_id',p.stable_key,
      'reference_code',(select i.identifier_value from scholarship.identifiers i where i.scholarship_id=p.id and i.scheme='study_australia_scholarship_id' and i.status is distinct from 'retired' order by i.is_primary desc limit 1),
      'name',p.name,
      'provider',jsonb_build_object('provider_id',p.provider_key,'name',p.provider_name,'university_groups',security.provider_university_groups(p.provider_id)),
      'campus_city',null,
      'provider_cities',coalesce((select jsonb_agg(distinct k.city order by k.city) from catalogue.campuses k where k.provider_id=p.provider_id and nullif(btrim(k.city),'') is not null),'[]'::jsonb),
      'amount_type',p.amount_type,
      'amount_value',case p.amount_type when 'fixed_amount' then p.award_amount when 'full_tuition' then 100 when 'percentage_tuition' then p.award_percentage when 'percentage' then p.award_percentage end,
      'amount_currency',case when p.amount_type='fixed_amount' then p.award_currency_code end,
      'amount_note',p.award_value_text,
      'amount_is_maximum',p.award_value_is_maximum,
      'renewable',case when p.award_duration_basis in ('annual_program_duration','program_duration') then true end,
      'coverage_duration',p.award_duration_basis,
      'study_levels',null,
      'study_area_codes',null,
      'min_academic_score',null,
      'age_min',(select c.value_number from scholarship.criteria c where c.scholarship_id=p.id and c.criterion_type='minimum_age' and c.machine_evaluable limit 1),
      'age_max',null,
      'citizenship_eligibility',null,
      'eligibility_summary',(select left(c.human_text,1200) from scholarship.criteria c where c.scholarship_id=p.id and c.criterion_type='published_eligibility_narrative' limit 1),
      'application_open_date',p.application_open_date,
      'application_deadline',p.application_close_date,
      'deadline_status',p.deadline_status,
      'deadline_is_rolling',null,
      'official_url',coalesce((select i.identifier_value from scholarship.identifiers i where i.scholarship_id=p.id and i.scheme='first_party_detail_url' order by i.is_primary desc limit 1), p.source_url),
      'official_url_source',case when exists(select 1 from scholarship.identifiers i where i.scholarship_id=p.id and i.scheme='first_party_detail_url') then 'first_party' else 'study_australia' end,
      'academic_year',p.academic_year,
      'publication_status',p.publication_status,
      'freshness',jsonb_build_object('updated_at',p.updated_at)
    ) order by (p.deadline_status='open') desc, p.application_close_date nulls last, lower(p.name), p.stable_key) from paged p),'[]'::jsonb)
  ) into v_result;
  return v_result;
end $$;


ALTER FUNCTION "public"."website_edge_scholarship_search_v1"("p_filters" "jsonb", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_v2_course"("p_identifier" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'search', 'catalogue', 'ref', 'scholarship', 'security', 'api'
    AS $$
declare v_id uuid; v_matches int; v jsonb; v_outcomes_ok boolean;
begin
  if nullif(btrim(coalesce(p_identifier,'')),'') is null then raise exception 'INVALID_INPUT: course_id or course_code required' using errcode='22023'; end if;
  select count(*) into v_matches from search.course_documents d where lower(d.course_stable_key)=lower(btrim(p_identifier)) or lower(d.course_code)=lower(btrim(p_identifier));
  select d.course_id into v_id from search.course_documents d
   where lower(d.course_stable_key)=lower(btrim(p_identifier)) or lower(d.course_code)=lower(btrim(p_identifier))
   order by (lower(d.course_stable_key)=lower(btrim(p_identifier))) desc, d.course_stable_key limit 1;
  if v_id is null then return jsonb_build_object('contract_version','website-search-v2','error',jsonb_build_object('code','NOT_FOUND')); end if;
  v := api.website_v2_course_item(v_id);
  select exists (select 1 from search.enrichment_gates g where g.projection_code='courses' and g.domain_code='provider_outcomes' and g.gate_status='approved') into v_outcomes_ok;
  v := v || jsonb_build_object(
    'description', (select c.description from catalogue.courses c where c.id=v_id),
    'english_note', (select string_agg(distinct e->>'notes', ' | ') from search.course_documents d, jsonb_array_elements(coalesce(d.english_requirement_options,'[]'::jsonb)) e
                      where d.course_id=v_id and e->>'notes' ~* 'check the course page'),
    'tuition_history', coalesce((select jsonb_agg(jsonb_build_object('year', f.fee_year, 'amount', f.amount, 'currency', f.currency_code, 'basis', f.basis,
                          'source', case f.fee_type when 'tuition' then 'regulatory_registered' when 'provider_current_tuition' then 'provider_current' else f.fee_type end)
                          order by f.fee_year desc nulls last, f.fee_type)
                        from catalogue.course_fees f where f.course_id=v_id and f.status='active' and f.audience in ('international','all') and f.fee_type in ('tuition','provider_current_tuition')), '[]'::jsonb),
    'scholarships', coalesce((select jsonb_agg(jsonb_build_object('scholarship_id', s->>'scholarship_key', 'name', s->>'name', 'amount_note', s->>'award_value_text',
                          'amount_is_maximum', s->'is_maximum', 'saving_per_year', s->'saving_per_year', 'saving_currency', s->'saving_currency',
                          'application_deadline', s->'application_close_date', 'official_url', s->>'source_url'))
                        from search.course_documents d, jsonb_array_elements(coalesce(d.scholarship_options,'[]'::jsonb)) s where d.course_id=v_id), '[]'::jsonb),
    'provider_outcomes_state', case when v_outcomes_ok then 'admitted' else 'not_admitted' end,
    'provider_outcomes', case when v_outcomes_ok then coalesce((select jsonb_agg(jsonb_build_object('survey', sv.code, 'metric_code', m.code, 'metric_name', m.name,
                          'study_level', o.source_cohort_code, 'value', o.metric_value, 'unit', m.unit, 'ci_low', o.confidence_low, 'ci_high', o.confidence_high,
                          'reference_year', o.collection_year_to, 'responses', o.response_count, 'grain', 'provider'))
                        from catalogue.provider_outcomes o join ref.outcome_metrics m on m.id=o.metric_id join ref.outcome_surveys sv on sv.id=o.survey_id
                        join search.course_documents d on d.provider_id=o.provider_id and d.course_id=v_id
                        where o.status in ('active','accepted') and o.external_study_area_id is null), '[]'::jsonb) else '[]'::jsonb end,
    'other_matches', greatest(v_matches - 1, 0));
  return jsonb_build_object('contract_version','website-search-v2','item',v);
end $$;


ALTER FUNCTION "public"."website_v2_course"("p_identifier" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_v2_course_search"("p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_sort" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'search', 'catalogue', 'ref', 'pipeline', 'security', 'api'
    AS $_$
declare
  f jsonb := coalesce(p_filters,'{}'::jsonb);
  v_page int := coalesce(p_page,1);
  v_size int := coalesce(p_page_size,20);
  v_kw text := nullif(btrim(coalesce(f->>'keyword','')),'');
  v_q tsquery;
  v_countries text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(coalesce(f->'country_codes',f->'country_code'))) x);
  v_areas text[] := api.website_text_array(f->'study_area_codes');
  v_levels text[] := api.website_text_array(f->'study_level_codes');
  v_subdivs text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(f->'subdivision_codes')) x);
  v_cities text[] := (select array_agg(lower(x)) from unnest(api.website_text_array(coalesce(f->'cities',f->'city'))) x);
  v_postcodes text[] := api.website_text_array(f->'postcodes');
  v_regional int[] := (select array_agg(x::int) from unnest(api.website_text_array(f->'regional_categories')) x where x ~ '^[1-3]$');
  v_providers text[] := api.website_text_array(f->'provider_ids');
  v_groups text[] := (select array_agg(lower(regexp_replace(btrim(x),'^au_','','i'))) from unnest(api.website_text_array(coalesce(f->'university_groups',f->'university_group'))) x);
  v_modes text[] := api.website_text_array(f->'delivery_modes');
  v_months int[] := (select array_agg(x::int) from unnest(api.website_text_array(f->'intake_months')) x where x ~ '^([1-9]|1[0-2])$');
  v_tests text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(f->'english_test_codes')) x);
  v_score_max numeric := nullif(f->>'english_score_max','')::numeric;
  v_min numeric := nullif(f->>'tuition_annual_min','')::numeric;
  v_max numeric := nullif(f->>'tuition_annual_max','')::numeric;
  v_changed timestamptz := nullif(f->>'changed_since','')::timestamptz;
  v_sort text := coalesce(nullif(p_sort,''), case when nullif(btrim(coalesce(f->>'keyword','')),'') is not null then 'relevance' else 'title_asc' end);
  v_known text[] := array['keyword','country_codes','country_code','study_area_codes','study_level_codes','subdivision_codes','cities','city','postcodes','regional_categories',
                          'provider_ids','university_groups','university_group','delivery_modes','intake_months','english_test_codes','english_score_max',
                          'tuition_annual_min','tuition_annual_max','has_intake','has_english','has_official_url','has_scholarship','has_tuition','changed_since'];
  v_not_applied jsonb;
  v_total bigint; v_ids uuid[];
  v_need_fee boolean;
begin
  if v_page < 1 then raise exception 'INVALID_INPUT: page must be >= 1' using errcode='22023'; end if;
  if v_size < 1 or v_size > 50 then raise exception 'INVALID_INPUT: page_size must be 1-50' using errcode='22023'; end if;
  if v_sort not in ('relevance','title_asc','tuition_annual_asc','tuition_annual_desc','duration_asc','updated_asc') then raise exception 'INVALID_INPUT: unknown sort' using errcode='22023'; end if;
  if v_score_max is not null and coalesce(cardinality(v_tests),0) <> 1 then raise exception 'INVALID_INPUT: english_score_max needs exactly one english_test_codes value' using errcode='22023'; end if;
  if v_kw is not null then v_q := websearch_to_tsquery('english', v_kw); end if;
  v_need_fee := (v_min is not null or v_max is not null or coalesce((f->>'has_tuition')::boolean,false) or v_sort in ('tuition_annual_asc','tuition_annual_desc'));
  select coalesce(jsonb_agg(k),'[]'::jsonb) into v_not_applied from jsonb_object_keys(f) k where k <> all(v_known);

  with base as (
    select d.course_id, d.course_title, d.course_stable_key, d.updated_at, d.provider_name,
      case when not v_need_fee then null
           when pt.amt is not null then
             case when pt.bas ~* 'total|course' and pt.bas !~* 'annual' then case when w.wk >= 52 then round(pt.amt / (w.wk/52.0)) end
                  when pt.bas ~* 'session|semester|trimester|unit|credit' then null
                  when pt.bas ~* 'indicative|annual|per.?year|yearly' then pt.amt end
           when d.regulatory_tuition_amount >= 1000 and w.wk >= 52 then round(d.regulatory_tuition_amount / (w.wk/52.0)) end ann,
      case when v_need_fee then (pt.amt is not null or coalesce(d.regulatory_tuition_amount,0) >= 1000) end has_fee,
      w.wk * 12.0 / 52 dur_months,
      case when v_kw is null then 0 else
        ts_rank(d.search_tsv, v_q) + case when d.course_title ilike '%'||v_kw||'%' then 1 else 0 end
          + case when d.course_title ilike v_kw||'%' then 0.5 else 0 end + case when lower(d.course_code) = lower(v_kw) then 2 else 0 end end rel
    from search.course_documents d
    left join catalogue.courses c on c.id = d.course_id
    cross join lateral (select case lower(coalesce(c.duration_unit,'')) when 'weeks' then c.duration_value when 'months' then c.duration_value*52/12.0 when 'years' then c.duration_value*52 end wk) w
    left join lateral (select (o->>'amount')::numeric amt, o->>'basis' bas
                       from jsonb_array_elements(coalesce(d.provider_tuition_options,'[]'::jsonb)) o
                       where (o->>'amount') ~ '^[0-9]+(\.[0-9]+)?$' and (o->>'amount')::numeric >= 1000
                       order by nullif(o->>'fee_year','')::int desc nulls last limit 1) pt on v_need_fee
    where not exists (select 1 from security.layer4_search_blocked_courses b where b.course_id = d.course_id)
      and (v_kw is null or d.search_tsv @@ v_q or d.course_title ilike '%'||v_kw||'%' or d.provider_name ilike '%'||v_kw||'%'
           or lower(d.course_code) = lower(v_kw) or lower(d.course_stable_key) = lower(v_kw))
      and (v_countries is null or d.country_code = any(v_countries))
      and (v_areas is null or d.primary_field_code = any(v_areas))
      and (v_levels is null or d.study_level_code = any(v_levels))
      and (v_subdivs is null or d.subdivision_codes && v_subdivs)
      and (v_providers is null or d.provider_stable_key = any(v_providers))
      and (v_groups is null or exists (select 1 from catalogue.provider_collection_memberships gm join ref.institution_collections gic on gic.id=gm.collection_id
            where gm.provider_id=d.provider_id and gm.status='active' and (gm.valid_to is null or gm.valid_to>=current_date)
              and gic.collection_type='university_group' and gic.status='active' and replace(gic.code,'au_','') = any(v_groups)))
      and (v_modes is null or d.delivery_modes && v_modes)
      and (not coalesce((f->>'has_intake')::boolean,false) or d.has_intake)
      and (not coalesce((f->>'has_english')::boolean,false) or d.has_english)
      and (not coalesce((f->>'has_official_url')::boolean,false) or d.has_link)
      and (not coalesce((f->>'has_scholarship')::boolean,false) or d.has_scholarship)
      and (v_changed is null or greatest(d.updated_at, d.source_updated_at) >= v_changed)
      and (v_months is null or exists (select 1 from jsonb_array_elements(coalesce(d.intake_options,'[]'::jsonb)) i where api.website_v2_label_month(i->>'label') = any(v_months)))
      and (v_tests is null or exists (select 1 from jsonb_array_elements(coalesce(d.english_requirement_options,'[]'::jsonb)) e
            where upper(e->>'test_code') = any(v_tests) and (v_score_max is null or ((e->>'overall_score') ~ '^[0-9]+(\.[0-9]+)?$' and (e->>'overall_score')::numeric <= v_score_max))))
      and ((v_cities is null and v_postcodes is null and v_regional is null) or exists (
            select 1 from catalogue.course_campuses cc join catalogue.campuses k on k.id = cc.campus_id left join pipeline.campus_regional_class rc on rc.campus_id = k.id
            where cc.course_id = d.course_id
              and (v_cities is null or lower(btrim(k.city)) = any(v_cities) or lower(rc.metro_area) = any(v_cities))
              and (v_postcodes is null or btrim(k.postcode) = any(v_postcodes))
              and (v_regional is null or rc.category = any(v_regional))))
  ), filtered as (
    select * from base b
    where (not coalesce((f->>'has_tuition')::boolean,false) or b.has_fee)
      and (v_min is null or b.ann >= v_min)
      and (v_max is null or b.ann <= v_max)
  ), ordered as (
    select course_id, count(*) over () total,
      row_number() over (order by
        case when v_sort='relevance' then rel end desc nulls last,
        case when v_sort='tuition_annual_asc' then ann end asc nulls last,
        case when v_sort='tuition_annual_desc' then ann end desc nulls last,
        case when v_sort='duration_asc' then dur_months end asc nulls last,
        case when v_sort='updated_asc' then updated_at end asc,
        lower(course_title), course_stable_key) rn
    from filtered
  )
  select coalesce(max(total),0), array_agg(course_id order by rn) filter (where rn > (v_page-1)*v_size and rn <= v_page*v_size)
    into v_total, v_ids from ordered;

  return jsonb_build_object(
    'contract_version','website-search-v2',
    'total', v_total, 'page', v_page, 'page_size', v_size, 'sort', v_sort,
    'filters_not_applied', v_not_applied,
    'items', coalesce((select jsonb_agg(api.website_v2_course_item(x.id, v_cities, v_postcodes) order by x.ord) from unnest(v_ids) with ordinality x(id, ord)), '[]'::jsonb));
end $_$;


ALTER FUNCTION "public"."website_v2_course_search"("p_filters" "jsonb", "p_page" integer, "p_page_size" integer, "p_sort" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_v2_provider"("p_provider_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'search', 'catalogue', 'ref', 'security', 'api'
    AS $$
declare v_pid uuid; v jsonb; v_outcomes_ok boolean;
begin
  if nullif(btrim(coalesce(p_provider_id,'')),'') is null then raise exception 'INVALID_INPUT: provider_id required' using errcode='22023'; end if;
  select p.id into v_pid from catalogue.providers p where lower(p.stable_key)=lower(btrim(p_provider_id)) limit 1;
  if v_pid is null then return jsonb_build_object('contract_version','website-search-v2','error',jsonb_build_object('code','NOT_FOUND')); end if;
  v := (public.website_v2_providers(jsonb_build_object('provider_ids', jsonb_build_array(btrim(p_provider_id))),1,1))->'items'->0;
  if v is null then return jsonb_build_object('contract_version','website-search-v2','error',jsonb_build_object('code','NOT_FOUND')); end if;
  select exists (select 1 from search.enrichment_gates g where g.projection_code='courses' and g.domain_code='provider_outcomes' and g.gate_status='approved') into v_outcomes_ok;
  v := v || jsonb_build_object(
    'description', (select p.description from catalogue.providers p where p.id=v_pid),
    'rankings', public.website_v2_provider_rankings(v_pid),
    'outcomes_state', case when v_outcomes_ok then 'admitted' else 'not_admitted' end,
    'outcomes', case when v_outcomes_ok then coalesce((select jsonb_agg(jsonb_build_object('survey', sv.code, 'metric_code', m.code, 'metric_name', m.name,
                   'study_level', o.source_cohort_code, 'value', o.metric_value, 'unit', m.unit, 'ci_low', o.confidence_low, 'ci_high', o.confidence_high,
                   'reference_year', o.collection_year_to, 'responses', o.response_count, 'grain', 'provider'))
                 from catalogue.provider_outcomes o join ref.outcome_metrics m on m.id=o.metric_id join ref.outcome_surveys sv on sv.id=o.survey_id
                 where o.provider_id=v_pid and o.external_study_area_id is null), '[]'::jsonb) else '[]'::jsonb end);
  return jsonb_build_object('contract_version','website-search-v2','item',v);
end $$;


ALTER FUNCTION "public"."website_v2_provider"("p_provider_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_v2_provider_rankings"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'system_code', s.code, 'system_name', s.ranking_name, 'publisher', s.publisher_name, 'edition_year', e.edition_year,
      'rank_display', o.rank_display, 'rank_low', coalesce(o.rank_low,o.rank_exact), 'rank_high', coalesce(o.rank_high,o.rank_exact), 'is_tied', coalesce(o.is_tied,false),
      'overall_score_display', o.overall_score_display,
      'indicators', (select coalesce(jsonb_agg(jsonb_build_object('code', io.indicator_code, 'label', io.indicator_label, 'value_display', io.value_display, 'rank_display', io.rank_display) order by io.indicator_code), '[]'::jsonb)
                     from ranking.indicator_observations io where io.observation_id=o.id),
      'methodology_url', e.methodology_url, 'source_url', coalesce(e.source_url, s.official_url),
      'attribution', s.publisher_name || ', ' || s.ranking_name || ' ' || e.edition_year,
      'terms_status', 'management_decision_pending')
    order by s.code, e.edition_year desc), '[]'::jsonb)
  from (select distinct on (o2.edition_id) o2.* from ranking.observation_provider_links l join ranking.observations o2 on o2.id=l.observation_id
        where l.provider_id=p_provider_id order by o2.edition_id, l.is_primary desc nulls last) o
  join ranking.editions e on e.id=o.edition_id and e.status='accepted' join ranking.systems s on s.id=e.system_id
$$;


ALTER FUNCTION "public"."website_v2_provider_rankings"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_v2_providers"("p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_sort" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'search', 'catalogue', 'ref', 'pipeline', 'ranking', 'security', 'api'
    AS $_$
declare
  f jsonb := coalesce(p_filters,'{}'::jsonb);
  v_page int := coalesce(p_page,1);
  v_size int := coalesce(p_page_size,20);
  v_kw text := nullif(btrim(coalesce(f->>'keyword','')),'');
  v_countries text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(coalesce(f->'country_codes',f->'country_code'))) x);
  v_subdivs text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(f->'subdivision_codes')) x);
  v_cities text[] := (select array_agg(lower(x)) from unnest(api.website_text_array(coalesce(f->'cities',f->'city'))) x);
  v_regional int[] := (select array_agg(x::int) from unnest(api.website_text_array(f->'regional_categories')) x where x ~ '^[1-3]$');
  v_groups text[] := (select array_agg(lower(regexp_replace(btrim(x),'^au_','','i'))) from unnest(api.website_text_array(coalesce(f->'university_groups',f->'university_group'))) x);
  v_levels text[] := api.website_text_array(f->'study_level_codes');
  v_areas text[] := api.website_text_array(f->'study_area_codes');
  v_ranked text[] := api.website_text_array(f->'ranked_in');
  v_qs_max int := nullif(f->>'qs_rank_max','')::int;
  v_the_max int := nullif(f->>'the_rank_max','')::int;
  v_sort text := coalesce(nullif(p_sort,''),'name_asc');
  v_known text[] := array['keyword','country_codes','country_code','subdivision_codes','cities','city','regional_categories','university_groups','university_group',
                          'study_level_codes','study_area_codes','has_scholarship','ranked_in','qs_rank_max','the_rank_max','has_logo','provider_ids'];
  v_providers text[] := api.website_text_array(f->'provider_ids');
  v_not_applied jsonb; v_total bigint; v_items jsonb;
begin
  if v_page < 1 or v_size < 1 or v_size > 50 then raise exception 'INVALID_INPUT: page must be >= 1 and page_size 1-50' using errcode='22023'; end if;
  if v_sort not in ('name_asc','qs_rank_asc','the_rank_asc','course_count_desc') then raise exception 'INVALID_INPUT: unknown sort' using errcode='22023'; end if;
  select coalesce(jsonb_agg(k),'[]'::jsonb) into v_not_applied from jsonb_object_keys(f) k where k <> all(v_known);

  with agg as (
    select d.provider_id, min(d.provider_stable_key) provider_stable_key, min(d.provider_name) provider_name, min(d.country_code) country_code,
      count(*) course_count, bool_or(d.has_scholarship) any_scholarship,
      array_agg(distinct d.study_level_code) levels, array_agg(distinct d.primary_field_code) areas
    from search.course_documents d group by d.provider_id
  ), rk as (
    select l.provider_id,
      min(case when s.code='qs_wur' and e.edition_year = (select max(e2.edition_year) from ranking.editions e2 where e2.system_id=s.id and e2.status='accepted') then coalesce(o.rank_low,o.rank_exact) end) qs_rank,
      min(case when s.code='the_wur' and e.edition_year = (select max(e2.edition_year) from ranking.editions e2 where e2.system_id=s.id and e2.status='accepted') then coalesce(o.rank_low,o.rank_exact) end) the_rank,
      array_agg(distinct s.code) systems
    from ranking.observation_provider_links l join ranking.observations o on o.id=l.observation_id
    join ranking.editions e on e.id=o.edition_id and e.status='accepted' join ranking.systems s on s.id=e.system_id
    group by l.provider_id
  ), base as (
    select a.*, p.website, rk.qs_rank, rk.the_rank, rk.systems,
      exists (select 1 from catalogue.provider_assets pa where pa.provider_id=a.provider_id and pa.asset_type='logo' and pa.status='approved' and pa.is_primary) has_logo,
      (select count(*) from scholarship.scholarships sc where sc.provider_id=a.provider_id and sc.lifecycle_status='active' and sc.publication_status='published') sch_count
    from agg a join catalogue.providers p on p.id=a.provider_id
    left join rk on rk.provider_id=a.provider_id
    where (v_kw is null or a.provider_name ilike '%'||v_kw||'%' or security.provider_presentable_name(a.provider_name) ilike '%'||v_kw||'%')
      and (v_countries is null or a.country_code = any(v_countries))
      and (v_providers is null or a.provider_stable_key = any(v_providers))
      and (v_subdivs is null or exists (select 1 from search.course_documents d2 where d2.provider_id=a.provider_id and d2.subdivision_codes && v_subdivs))
      and (v_levels is null or a.levels && v_levels)
      and (v_areas is null or a.areas && v_areas)
      and (v_groups is null or exists (select 1 from catalogue.provider_collection_memberships gm join ref.institution_collections gic on gic.id=gm.collection_id
            where gm.provider_id=a.provider_id and gm.status='active' and (gm.valid_to is null or gm.valid_to>=current_date)
              and gic.collection_type='university_group' and gic.status='active' and replace(gic.code,'au_','') = any(v_groups)))
      and ((v_cities is null and v_regional is null) or exists (select 1 from catalogue.campuses k left join pipeline.campus_regional_class rc on rc.campus_id=k.id
            where k.provider_id=a.provider_id and (v_cities is null or lower(btrim(k.city)) = any(v_cities) or lower(rc.metro_area) = any(v_cities))
              and (v_regional is null or rc.category = any(v_regional))))
      and (v_ranked is null or rk.systems && v_ranked)
      and (v_qs_max is null or rk.qs_rank <= v_qs_max)
      and (v_the_max is null or rk.the_rank <= v_the_max)
  ), filtered as (
    select * from base
    where (not coalesce((f->>'has_scholarship')::boolean,false) or sch_count > 0)
      and (not coalesce((f->>'has_logo')::boolean,false) or has_logo)
  ), ordered as (
    select *, count(*) over () total, row_number() over (order by
      case when v_sort='qs_rank_asc' then qs_rank end asc nulls last,
      case when v_sort='the_rank_asc' then the_rank end asc nulls last,
      case when v_sort='course_count_desc' then course_count end desc,
      lower(security.provider_presentable_name(provider_name)), provider_stable_key) rn
    from filtered
  )
  select coalesce(max(total),0),
    coalesce(jsonb_agg(jsonb_build_object(
      'provider_id', o.provider_stable_key,
      'name', security.provider_presentable_name(o.provider_name),
      'legal_name', o.provider_name,
      'website', o.website,
      'country_code', o.country_code,
      'campuses', api.website_v2_provider_campuses(o.provider_id),
      'course_count', o.course_count,
      'study_levels_offered', (select jsonb_agg(jsonb_build_object('code', x.code, 'name', (select sl.name from ref.study_levels sl where sl.code=x.code limit 1), 'courses', x.n) order by x.n desc)
                               from (select d.study_level_code code, count(*) n from search.course_documents d where d.provider_id=o.provider_id and d.study_level_code is not null group by 1) x),
      'study_areas_offered', (select jsonb_agg(jsonb_build_object('code', x.code, 'name', x.name, 'courses', x.n) order by x.n desc)
                               from (select d.primary_field_code code, min(d.primary_field_name) name, count(*) n from search.course_documents d where d.provider_id=o.provider_id and d.primary_field_code is not null group by 1) x),
      'university_groups', security.provider_university_groups(o.provider_id),
      'scholarship_count', o.sch_count,
      'ranking_summary', api.website_v2_ranking_summary(o.provider_id),
      'logo', api.website_v2_provider_logo(o.provider_id),
      'publication_status', (select p.publication_status from catalogue.providers p where p.id=o.provider_id)
    ) order by o.rn) filter (where o.rn > (v_page-1)*v_size and o.rn <= v_page*v_size), '[]'::jsonb)
  into v_total, v_items
  from ordered o;

  return jsonb_build_object('contract_version','website-search-v2','total',v_total,'page',v_page,'page_size',v_size,'sort',v_sort,
                            'filters_not_applied',v_not_applied,'items',v_items);
end $_$;


ALTER FUNCTION "public"."website_v2_providers"("p_filters" "jsonb", "p_page" integer, "p_page_size" integer, "p_sort" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_v2_rankings"("p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'ranking', 'catalogue', 'ref', 'search', 'security', 'api'
    AS $$
declare
  f jsonb := coalesce(p_filters,'{}'::jsonb);
  v_page int := coalesce(p_page,1); v_size int := coalesce(p_page_size,20);
  v_systems text[] := coalesce(api.website_text_array(f->'system_codes'), array['qs_wur','the_wur']);
  v_year int := nullif(f->>'edition_year','')::int;
  v_countries text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(coalesce(f->'country_codes',f->'country_code'))) x);
  v_providers text[] := api.website_text_array(f->'provider_ids');
  v_rank_max int := nullif(f->>'rank_max','')::int;
  v_known text[] := array['system_codes','edition_year','country_codes','country_code','provider_ids','rank_max'];
  v_not_applied jsonb; v_total bigint; v_items jsonb;
begin
  if v_page < 1 or v_size < 1 or v_size > 50 then raise exception 'INVALID_INPUT: page must be >= 1 and page_size 1-50' using errcode='22023'; end if;
  select coalesce(jsonb_agg(k),'[]'::jsonb) into v_not_applied from jsonb_object_keys(f) k where k <> all(v_known);
  with ed as (
    select e.id, e.edition_year, s.code, s.ranking_name, s.publisher_name, e.methodology_url, coalesce(e.source_url, s.official_url) source_url
    from ranking.editions e join ranking.systems s on s.id=e.system_id
    where e.status='accepted' and s.code = any(v_systems)
      and e.edition_year = coalesce(v_year, (select max(e2.edition_year) from ranking.editions e2 where e2.system_id=s.id and e2.status='accepted'))
  ), rows as (
    select distinct on (ed.id, l.provider_id) ed.*, o.id obs_id, o.rank_display, coalesce(o.rank_low,o.rank_exact) rank_low, coalesce(o.rank_high,o.rank_exact) rank_high,
           coalesce(o.is_tied,false) is_tied, o.overall_score_display, l.provider_id, p.stable_key provider_stable_key, coalesce(p.display_name,p.canonical_name) provider_name, c.iso_alpha2 country_code
    from ed join ranking.observations o on o.edition_id=ed.id
    join ranking.observation_provider_links l on l.observation_id=o.id
    join catalogue.providers p on p.id=l.provider_id join ref.countries c on c.id=p.country_id
    where (v_countries is null or trim(c.iso_alpha2::text) = any(v_countries))
      and (v_providers is null or p.stable_key = any(v_providers))
      and (v_rank_max is null or coalesce(o.rank_low,o.rank_exact) <= v_rank_max)
    order by ed.id, l.provider_id, l.is_primary desc nulls last
  ), ordered as (select *, count(*) over () total, row_number() over (order by code, rank_low nulls last, provider_name) rn from rows)
  select coalesce(max(total),0), coalesce(jsonb_agg(jsonb_build_object(
      'provider', jsonb_build_object('provider_id', o.provider_stable_key, 'name', security.provider_presentable_name(o.provider_name), 'country_code', trim(o.country_code::text), 'logo', api.website_v2_provider_logo(o.provider_id)),
      'system_code', o.code, 'system_name', o.ranking_name, 'publisher', o.publisher_name, 'edition_year', o.edition_year,
      'rank_display', o.rank_display, 'rank_low', o.rank_low, 'rank_high', o.rank_high, 'is_tied', o.is_tied, 'overall_score_display', o.overall_score_display,
      'indicators', (select coalesce(jsonb_agg(jsonb_build_object('code', io.indicator_code, 'label', io.indicator_label, 'value_display', io.value_display, 'rank_display', io.rank_display) order by io.indicator_code), '[]'::jsonb)
                     from ranking.indicator_observations io where io.observation_id=o.obs_id),
      'methodology_url', o.methodology_url, 'source_url', o.source_url,
      'attribution', o.publisher_name || ', ' || o.ranking_name || ' ' || o.edition_year,
      'terms_status', 'management_decision_pending') order by o.rn) filter (where o.rn > (v_page-1)*v_size and o.rn <= v_page*v_size), '[]'::jsonb)
  into v_total, v_items from ordered o;
  return jsonb_build_object('contract_version','website-search-v2','total',v_total,'page',v_page,'page_size',v_size,'filters_not_applied',v_not_applied,'items',v_items);
end $$;


ALTER FUNCTION "public"."website_v2_rankings"("p_filters" "jsonb", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_v2_reference"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'search', 'ref', 'catalogue', 'scholarship', 'security', 'api'
    AS $$
  select jsonb_build_object(
    'contract_version','website-search-v2',
    'countries', (select jsonb_agg(jsonb_build_object(
        'country_code', c.country_code, 'courses', c.n,
        'study_levels', (select jsonb_agg(jsonb_build_object('code', x.code, 'name', (select sl.name from ref.study_levels sl where sl.code=x.code limit 1), 'courses', x.n) order by x.n desc)
                         from (select study_level_code code, count(*) n from search.course_documents where country_code=c.country_code and study_level_code is not null group by 1) x),
        'study_areas', (select jsonb_agg(jsonb_build_object('code', x.code, 'name', x.name, 'courses', x.n) order by x.n desc)
                        from (select primary_field_code code, min(primary_field_name) name, count(*) n from search.course_documents where country_code=c.country_code and primary_field_code is not null group by 1) x),
        'subdivisions', (select jsonb_agg(jsonb_build_object('code', x.code, 'courses', x.n) order by x.code)
                         from (select s code, count(*) n from search.course_documents d, unnest(d.subdivision_codes) s where d.country_code=c.country_code group by 1) x),
        'cities', (select jsonb_agg(jsonb_build_object('city', x.city, 'metro_area', x.metro, 'courses', x.n) order by x.n desc)
                   from (select security.place_presentable(k.city) city, min(rc.metro_area) metro, count(distinct cc.course_id) n
                         from search.course_documents d join catalogue.course_campuses cc on cc.course_id=d.course_id join catalogue.campuses k on k.id=cc.campus_id
                         left join pipeline.campus_regional_class rc on rc.campus_id=k.id
                         where d.country_code=c.country_code and nullif(btrim(k.city),'') is not null group by 1 having count(distinct cc.course_id) >= 5) x),
        'intake_months', (select jsonb_agg(jsonb_build_object('month', x.m, 'courses', x.n) order by x.m)
                          from (select api.website_v2_label_month(i->>'label') m, count(distinct d.course_id) n from search.course_documents d, jsonb_array_elements(coalesce(d.intake_options,'[]'::jsonb)) i
                                where d.country_code=c.country_code and api.website_v2_label_month(i->>'label') is not null group by 1) x),
        'english_tests', (select jsonb_agg(jsonb_build_object('code', x.code, 'courses', x.n) order by x.n desc)
                          from (select upper(e->>'test_code') code, count(distinct d.course_id) n from search.course_documents d, jsonb_array_elements(coalesce(d.english_requirement_options,'[]'::jsonb)) e
                                where d.country_code=c.country_code and e->>'test_code' is not null group by 1) x)
      ) order by c.n desc) from (select country_code, count(*) n from search.course_documents group by 1) c),
    'regional_categories', jsonb_build_array(jsonb_build_object('code',1,'name','Major city'), jsonb_build_object('code',2,'name','City or major regional centre'), jsonb_build_object('code',3,'name','Regional centre or other regional area')),
    'university_groups', (select jsonb_agg(jsonb_build_object('code', replace(gic.code,'au_',''), 'name', gic.name,
                           'members', (select count(*) from catalogue.provider_collection_memberships gm where gm.collection_id=gic.id and gm.status='active')))
                          from ref.institution_collections gic where gic.collection_type='university_group' and gic.status='active'),
    'ranking_systems', (select jsonb_agg(jsonb_build_object('code', s.code, 'name', s.ranking_name, 'publisher', s.publisher_name,
                         'editions', (select jsonb_agg(e.edition_year order by e.edition_year desc) from ranking.editions e where e.system_id=s.id and e.status='accepted'),
                         'terms_status', 'management_decision_pending')) from ranking.systems s where exists (select 1 from ranking.editions e where e.system_id=s.id and e.status='accepted')),
    'scholarship_amount_types', jsonb_build_array('percentage_tuition','fixed_amount','full_tuition'),
    'scholarship_study_stages', jsonb_build_array('commencing','current'),
    'scholarship_student_types', jsonb_build_array('international','domestic','both'),
    'course_sorts', jsonb_build_array('relevance','title_asc','tuition_annual_asc','tuition_annual_desc','duration_asc','updated_asc'),
    'provider_sorts', jsonb_build_array('name_asc','qs_rank_asc','the_rank_asc','course_count_desc'),
    'generated_at', now())
$$;


ALTER FUNCTION "public"."website_v2_reference"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_v2_scholarship"("p_scholarship_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'catalogue', 'search', 'security', 'api'
    AS $$
declare v_id uuid; v jsonb;
begin
  if nullif(btrim(coalesce(p_scholarship_id,'')),'') is null then raise exception 'INVALID_INPUT: scholarship_id required' using errcode='22023'; end if;
  select s.id into v_id from scholarship.scholarships s where s.stable_key = btrim(p_scholarship_id) limit 1;
  if v_id is null then return jsonb_build_object('contract_version','website-search-v2','error',jsonb_build_object('code','NOT_FOUND')); end if;
  v := api.website_v2_scholarship_item(v_id);
  v := v || jsonb_build_object(
    'description', (select s.description from scholarship.scholarships s where s.id=v_id),
    'award_tiers', coalesce((select jsonb_agg(jsonb_build_object('label', t.label, 'amount', t.amount, 'currency', t.currency_code, 'percentage', t.percentage, 'basis', t.basis, 'maximum_amount', t.maximum_amount, 'notes', t.notes) order by t.display_order)
                             from scholarship.award_tiers t where t.scholarship_id=v_id), '[]'::jsonb),
    'linked_courses', coalesce((select jsonb_agg(x.j order by x.t) from (
         select d.course_title t, jsonb_build_object('course_id', d.course_stable_key, 'course_code', d.course_code, 'title', d.course_title,
                  'saving_per_year', (select fc.scholarship_saving_amount from scholarship.course_financial_calculations fc where fc.scholarship_id=v_id and fc.course_id=d.course_id and fc.calculation_status='calculated' order by fc.fee_year desc nulls last limit 1),
                  'saving_currency', (select fc.currency_code from scholarship.course_financial_calculations fc where fc.scholarship_id=v_id and fc.course_id=d.course_id and fc.calculation_status='calculated' order by fc.fee_year desc nulls last limit 1),
                  'saving_basis', (select fc.fee_basis from scholarship.course_financial_calculations fc where fc.scholarship_id=v_id and fc.course_id=d.course_id and fc.calculation_status='calculated' order by fc.fee_year desc nulls last limit 1)) j
         from scholarship.course_mappings m join search.course_documents d on d.course_id=m.course_id
         where m.scholarship_id=v_id and m.mapping_state='mapped' order by d.course_title limit 200) x), '[]'::jsonb),
    'linked_courses_truncated', (select count(*) > 200 from scholarship.course_mappings m where m.scholarship_id=v_id and m.mapping_state='mapped'));
  return jsonb_build_object('contract_version','website-search-v2','item',v);
end $$;


ALTER FUNCTION "public"."website_v2_scholarship"("p_scholarship_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_v2_scholarships"("p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'catalogue', 'search', 'ref', 'pipeline', 'security', 'api'
    AS $$
declare
  f jsonb := coalesce(p_filters,'{}'::jsonb);
  v_page int := coalesce(p_page,1); v_size int := coalesce(p_page_size,20);
  v_kw text := nullif(btrim(coalesce(f->>'keyword','')),'');
  v_countries text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(coalesce(f->'country_codes',f->'country_code'))) x);
  v_providers text[] := api.website_text_array(f->'provider_ids');
  v_cities text[] := (select array_agg(lower(x)) from unnest(api.website_text_array(coalesce(f->'cities',f->'city'))) x);
  v_subdivs text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(f->'subdivision_codes')) x);
  v_groups text[] := (select array_agg(lower(regexp_replace(btrim(x),'^au_','','i'))) from unnest(api.website_text_array(coalesce(f->'university_groups',f->'university_group'))) x);
  v_types text[] := api.website_text_array(f->'amount_types');
  v_levels text[] := api.website_text_array(f->'study_level_codes');
  v_areas text[] := api.website_text_array(f->'study_area_codes');
  v_student text[] := api.website_text_array(f->'student_types');
  v_stages text[] := api.website_text_array(f->'study_stages');
  v_nat text[] := (select array_agg(upper(x)) from unnest(api.website_text_array(f->'nationality_codes')) x);
  v_course text := nullif(btrim(coalesce(f->>'course_id','')),'');
  v_known text[] := array['keyword','country_codes','country_code','provider_ids','cities','city','subdivision_codes','university_groups','university_group','amount_types',
                          'open_only','published_only','study_level_codes','study_area_codes','student_types','study_stages','automatic_consideration','nationality_codes','course_id'];
  v_not_applied jsonb; v_total bigint; v_ids uuid[];
begin
  if v_page < 1 or v_size < 1 or v_size > 50 then raise exception 'INVALID_INPUT: page must be >= 1 and page_size 1-50' using errcode='22023'; end if;
  select coalesce(jsonb_agg(k),'[]'::jsonb) into v_not_applied from jsonb_object_keys(f) k where k <> all(v_known);
  with base as (
    select s.id, s.name, s.stable_key
    from scholarship.scholarships s join catalogue.providers p on p.id=s.provider_id join ref.countries c on c.id=p.country_id
    where s.lifecycle_status='active'
      and (not coalesce((f->>'published_only')::boolean,false) or s.publication_status='published')
      and (not coalesce((f->>'open_only')::boolean,false) or (s.application_close_date >= current_date and (s.application_open_date is null or s.application_open_date <= current_date)))
      and (v_kw is null or s.name ilike '%'||v_kw||'%' or coalesce(p.display_name,p.canonical_name) ilike '%'||v_kw||'%')
      and (v_countries is null or trim(c.iso_alpha2::text) = any(v_countries))
      and (v_providers is null or p.stable_key = any(v_providers))
      and (v_cities is null or exists (select 1 from catalogue.campuses k left join pipeline.campus_regional_class rc on rc.campus_id=k.id where k.provider_id=p.id and (lower(btrim(k.city)) = any(v_cities) or lower(rc.metro_area) = any(v_cities))))
      and (v_subdivs is null or exists (select 1 from catalogue.campuses k join ref.subdivisions sd on sd.id=k.subdivision_id where k.provider_id=p.id and sd.code = any(v_subdivs)))
      and (v_groups is null or exists (select 1 from catalogue.provider_collection_memberships gm join ref.institution_collections gic on gic.id=gm.collection_id
            where gm.provider_id=p.id and gm.status='active' and gic.collection_type='university_group' and gic.status='active' and replace(gic.code,'au_','') = any(v_groups)))
      and (v_types is null or (case when s.award_value_type='fixed_amount' then 'fixed_amount' when s.award_value_type='percentage' and s.award_percentage >= 100 then 'full_tuition'
                                    when s.award_value_type='percentage' then 'percentage_tuition' end) = any(v_types) or s.award_value_type = any(v_types))
      and (v_levels is null or exists (select 1 from scholarship.course_mappings m join search.course_documents d on d.course_id=m.course_id where m.scholarship_id=s.id and m.mapping_state='mapped' and d.study_level_code = any(v_levels)))
      and (v_areas is null or exists (select 1 from scholarship.course_mappings m join search.course_documents d on d.course_id=m.course_id where m.scholarship_id=s.id and m.mapping_state='mapped' and d.primary_field_code = any(v_areas)))
      and (v_stages is null or exists (select 1 from scholarship.criteria cr where cr.scholarship_id=s.id and cr.criterion_type='study_stage' and cr.value_text = any(v_stages)))
      and (v_student is null or exists (select 1 from scholarship.criteria cr where cr.scholarship_id=s.id and cr.criterion_type='student_type'
            and (('international' = any(v_student) and 'international' = any(cr.value_codes)) or ('domestic' = any(v_student) and 'domestic' = any(cr.value_codes))
                 or ('both' = any(v_student) and 'international' = any(cr.value_codes) and 'domestic' = any(cr.value_codes)))))
      and ((f->>'automatic_consideration') is null or (case when exists (select 1 from scholarship.criteria cr where cr.scholarship_id=s.id and cr.criterion_type='application_method' and cr.value_text='automatic') then true
                                                             when s.application_required then false end) = (f->>'automatic_consideration')::boolean)
      and (v_nat is null or exists (select 1 from scholarship.nationality_readings nr where nr.scholarship_id=s.id and nr.codes && v_nat))
      and (v_course is null or exists (select 1 from scholarship.course_mappings m join search.course_documents d on d.course_id=m.course_id where m.scholarship_id=s.id and m.mapping_state='mapped'
            and (lower(d.course_stable_key) = lower(v_course) or lower(d.course_code) = lower(v_course))))
  ), ordered as (select id, count(*) over () total, row_number() over (order by lower(name), stable_key) rn from base)
  select coalesce(max(total),0), array_agg(id order by rn) filter (where rn > (v_page-1)*v_size and rn <= v_page*v_size) into v_total, v_ids from ordered;
  return jsonb_build_object('contract_version','website-search-v2','total',v_total,'page',v_page,'page_size',v_size,'filters_not_applied',v_not_applied,
    'items', coalesce((select jsonb_agg(api.website_v2_scholarship_item(x.id) order by x.ord) from unnest(v_ids) with ordinality x(id, ord)), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."website_v2_scholarships"("p_filters" "jsonb", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


