CREATE OR REPLACE FUNCTION "public"."zoho_edge_course_lookup_v1"("p_identifier" "text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'api'
    AS $$
