CREATE OR REPLACE FUNCTION "public"."zoho_edge_report_v1"("p_course" "text", "p_field" "text", "p_note" "text", "p_reporter" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_course uuid; v_id uuid; v_field text := lower(btrim(coalesce(p_field, 'other')));
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if v_field not in ('official_url', 'intakes', 'english', 'tuition', 'scholarship', 'title', 'duration', 'delivery', 'other') then v_field := 'other'; end if;
  if length(btrim(coalesce(p_note, ''))) < 3 then return jsonb_build_object('error', 'NOTE_REQUIRED'); end if;
  select c.id into v_course from catalogue.courses c where c.id::text = p_course or c.stable_key = p_course limit 1;
  if v_course is null then return jsonb_build_object('error', 'NOT_FOUND'); end if;
  insert into pipeline.data_flags(entity_type, entity_id, field_code, flag_code, detail, status, change_control_ref)
  values ('course', v_course, v_field, 'reported',
          jsonb_build_object('note', left(btrim(p_note), 1000), 'source', 'zoho', 'reporter', coalesce(p_reporter, '{}'::jsonb), 'quotes', jsonb_build_array(left(btrim(p_note), 1000))),
          'open', 'CF-247')
  returning id into v_id;
  return jsonb_build_object('flag_id', v_id, 'course_id', v_course, 'field', v_field, 'status', 'open');
end $$;


ALTER FUNCTION "public"."zoho_edge_report_v1"("p_course" "text", "p_field" "text", "p_note" "text", "p_reporter" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."zoho_edge_scholarships_v1"("p_course" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_course uuid; v_sel jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select c.id into v_course from catalogue.courses c where c.id::text = p_course or c.stable_key = p_course limit 1;
  if v_course is null then return jsonb_build_object('error', 'NOT_FOUND'); end if;
  v_sel := security.scholarship_selection_for_course_impl(v_course);
  return jsonb_build_object(
    'course_id', v_course,
    'audience_filter', 'international',
    'scholarships', coalesce((
      select jsonb_agg(jsonb_build_object(
          'scholarship_id', s.id, 'stable_key', s.stable_key, 'name', s.name, 'provider', coalesce(p.display_name, p.canonical_name),
          'audience', s.audience, 'nationalities', s.nationalities,
          'value', jsonb_build_object('text', scholarship.value_label(s.id), 'type', s.award_value_type, 'percentage', s.award_percentage, 'amount', s.award_amount, 'currency', s.award_currency_code, 'is_maximum', s.award_value_is_maximum,
                                      'tiers', (select jsonb_agg(jsonb_build_object('label', t.label, 'percentage', t.percentage, 'amount', t.amount, 'currency', t.currency_code, 'basis', t.basis) order by t.display_order) from scholarship.award_tiers t where t.scholarship_id = s.id)),
          'saving', (select jsonb_build_object('year', fc.fee_year, 'currency', fc.currency_code, 'tuition', fc.fee_amount, 'saving', fc.scholarship_saving_amount, 'net', fc.net_fee_amount, 'basis', fc.fee_basis, 'estimate', fc.fee_basis = 'estimated_annual_from_registered_total')
                       from scholarship.course_financial_calculations fc where fc.scholarship_id = s.id and fc.course_id = v_course and fc.calculation_status = 'calculated' order by fc.fee_year desc nulls last limit 1),
          'who_qualifies', (select jsonb_agg(jsonb_build_object('type', cr.criterion_type, 'text', cr.human_text, 'mandatory', cr.is_mandatory) order by cr.created_at) from scholarship.criteria cr where cr.scholarship_id = s.id and cr.status = 'active'),
          'application', jsonb_build_object('required', s.application_required, 'opens', s.application_open_date, 'closes', s.application_close_date, 'academic_year', s.academic_year),
          'page', s.source_url,
          'match', e->'derived_score', 'selection_state', e->'selection_state', 'eligibility_state', e->'eligibility_state'))
        from jsonb_array_elements(coalesce(v_sel->'candidates', '[]'::jsonb)) e
        join scholarship.scholarships s on s.id = (e->>'scholarship_id')::uuid
        left join catalogue.providers p on p.id = s.provider_id
       where s.lifecycle_status = 'active' and s.publication_status = 'published'), '[]'::jsonb),
    'read_at', now());
end $$;


ALTER FUNCTION "public"."zoho_edge_scholarships_v1"("p_course" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "publishing"."course_publication_readiness_v1"("p_course_id" "uuid", "p_profile_code" "text" DEFAULT 'pilot-course-positive-v1'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'publishing', 'catalogue', 'search', 'ref', 'pipeline', 'pg_temp'
    AS $$
declare v_profile_active boolean:=false; v_approved boolean:=false; v_active boolean:=false; v_country text; v_course_key text; v_provider_key text; v_course_code text; v_title text; v_projected boolean:=false; v_evidence bigint:=0; v_blockers text[]:='{}'::text[]; v_exists boolean:=false; v_layer4_publication_blocked boolean:=false;
begin
select exists(select 1 from publishing.publication_profiles pp where pp.profile_code=p_profile_code and pp.entity_type='course' and pp.profile_status='active') into v_profile_active;
select true,c.lifecycle_status='active',trim(co.iso_alpha2::text),c.stable_key,p.stable_key,c.course_code,c.canonical_title,exists(select 1 from search.course_documents d where d.course_id=c.id)
into v_exists,v_active,v_country,v_course_key,v_provider_key,v_course_code,v_title,v_projected from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id where c.id=p_course_id;
if not coalesce(v_exists,false) then return jsonb_build_object('eligible',false,'profile_code',p_profile_code,'course_id',p_course_id,'blockers',jsonb_build_array('course_not_found')); end if;
select exists(select 1 from publishing.publication_approvals pa where pa.profile_code=p_profile_code and pa.entity_id=p_course_id and pa.approval_status='approved') into v_approved;
select coalesce(sum(el.link_count),0)::bigint into v_evidence from pipeline.evidence_entity_links el where el.entity_type='course' and el.entity_id=p_course_id;
select security.layer4_entity_or_parent_blocked('course',p_course_id,'publication') into v_layer4_publication_blocked;
if v_layer4_publication_blocked then v_blockers:=array_append(v_blockers,'layer4_publication_block'); end if;
if not v_profile_active then v_blockers:=array_append(v_blockers,'profile_not_active'); end if;
if not v_approved then v_blockers:=array_append(v_blockers,'not_explicitly_approved'); end if;
if not v_active then v_blockers:=array_append(v_blockers,'lifecycle_not_active'); end if;
if v_country is null or v_country not in ('AU','NZ') then v_blockers:=array_append(v_blockers,'country_out_of_scope'); end if;
if nullif(trim(v_course_key),'') is null then v_blockers:=array_append(v_blockers,'course_stable_key_missing'); end if;
if nullif(trim(v_provider_key),'') is null then v_blockers:=array_append(v_blockers,'provider_stable_key_missing'); end if;
if nullif(trim(v_course_code),'') is null then v_blockers:=array_append(v_blockers,'course_code_missing'); end if;
if nullif(trim(v_title),'') is null then v_blockers:=array_append(v_blockers,'course_title_missing'); end if;
if not v_projected then v_blockers:=array_append(v_blockers,'search_not_projected'); end if;
if v_evidence<1 then v_blockers:=array_append(v_blockers,'governed_evidence_missing'); end if;
return jsonb_build_object('eligible',cardinality(v_blockers)=0,'profile_code',p_profile_code,'course_id',p_course_id,'country',v_country,'signals',jsonb_build_object('layer4_publication_blocked',v_layer4_publication_blocked,'profile_active',v_profile_active,'explicitly_approved',v_approved,'lifecycle_active',v_active,'stable_course_identity',nullif(trim(v_course_key),'') is not null,'stable_provider_identity',nullif(trim(v_provider_key),'') is not null,'course_code_present',nullif(trim(v_course_code),'') is not null,'course_title_present',nullif(trim(v_title),'') is not null,'search_projected',v_projected,'governed_evidence_links',v_evidence),'blockers',to_jsonb(v_blockers));
end $$;


ALTER FUNCTION "publishing"."course_publication_readiness_v1"("p_course_id" "uuid", "p_profile_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "publishing"."course_publication_readiness_v1"("p_course_id" "uuid", "p_profile_code" "text") IS 'CF-CHG-20260823-024: explicit controlled publication readiness; Search presence alone is insufficient.';



CREATE OR REPLACE FUNCTION "publishing"."refresh_course_publication_search_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'publishing', 'search', 'pg_temp'
    AS $$
declare v_refresh jsonb; v_published bigint; v_internal bigint;
begin v_refresh:=search.refresh_course_documents_v3(true); select count(*) filter(where publication_status='published'),count(*) filter(where publication_status='internal') into v_published,v_internal from search.course_documents; return jsonb_build_object('refresh',v_refresh,'search_published',v_published,'search_internal',v_internal,'refreshed_at',now()); end $$;


ALTER FUNCTION "publishing"."refresh_course_publication_search_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "publishing"."refresh_course_publication_search_v1"() IS 'CF-CHG-20260823-024: explicit Search refresh after bounded publication state changes.';



CREATE OR REPLACE FUNCTION "publishing"."set_course_publication_v1"("p_course_id" "uuid", "p_target_status" "text", "p_profile_code" "text" DEFAULT 'pilot-course-positive-v1'::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'publishing', 'catalogue', 'ref', 'pg_temp'
    AS $$
declare v_target text:=lower(trim(coalesce(p_target_status,''))); v_prior text; v_country text; v_locale text; v_ready jsonb; v_canonical_changed integer:=0; v_website_changed integer:=0; v_zoho_changed integer:=0; v_website_status text; v_zoho_status text; v_changed boolean;
begin
if v_target not in ('published','internal','unpublished','blocked') then raise exception 'unsupported publication status: %',p_target_status using errcode='22023'; end if;
select c.publication_status,trim(co.iso_alpha2::text) into v_prior,v_country from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id where c.id=p_course_id for update of c;
if not found then raise exception 'course not found: %',p_course_id using errcode='P0002'; end if;
v_ready:=publishing.course_publication_readiness_v1(p_course_id,p_profile_code);
if v_target in ('published','internal') and not coalesce((v_ready->>'eligible')::boolean,false) then raise exception 'publication profile blocked: %',v_ready::text using errcode='42501'; end if;
v_locale:=case v_country when 'AU' then 'en-AU' when 'NZ' then 'en-NZ' else 'en' end;
v_website_status:=case v_target when 'published' then 'published' when 'blocked' then 'blocked' else 'unpublished' end;
v_zoho_status:=case v_target when 'published' then 'published' when 'internal' then 'internal' when 'blocked' then 'blocked' else 'unpublished' end;
update catalogue.courses set publication_status=v_target,updated_at=now() where id=p_course_id and publication_status is distinct from v_target; get diagnostics v_canonical_changed=row_count;
insert into publishing.entity_states(entity_id,channel_code,locale,publication_status,published_at,unpublished_at,last_checked_at,updated_at) values(p_course_id,'website',v_locale,v_website_status,case when v_website_status='published' then now() end,case when v_website_status in ('unpublished','blocked') then now() end,now(),now())
on conflict(entity_id,channel_code,locale) do update set publication_status=excluded.publication_status,published_at=case when excluded.publication_status='published' then excluded.published_at else publishing.entity_states.published_at end,unpublished_at=case when excluded.publication_status in ('unpublished','blocked') then excluded.unpublished_at else publishing.entity_states.unpublished_at end,last_checked_at=now(),updated_at=now() where publishing.entity_states.publication_status is distinct from excluded.publication_status; get diagnostics v_website_changed=row_count;
insert into publishing.entity_states(entity_id,channel_code,locale,publication_status,published_at,unpublished_at,last_checked_at,updated_at) values(p_course_id,'zoho',v_locale,v_zoho_status,case when v_zoho_status='published' then now() end,case when v_zoho_status in ('unpublished','blocked') then now() end,now(),now())
on conflict(entity_id,channel_code,locale) do update set publication_status=excluded.publication_status,published_at=case when excluded.publication_status='published' then excluded.published_at else publishing.entity_states.published_at end,unpublished_at=case when excluded.publication_status in ('unpublished','blocked') then excluded.unpublished_at else publishing.entity_states.unpublished_at end,last_checked_at=now(),updated_at=now() where publishing.entity_states.publication_status is distinct from excluded.publication_status; get diagnostics v_zoho_changed=row_count;
v_changed:=(v_canonical_changed+v_website_changed+v_zoho_changed)>0;
if v_changed then insert into publishing.publication_events(entity_id,profile_code,prior_status,target_status,changed,reason,readiness,change_control_ref) values(p_course_id,p_profile_code,v_prior,v_target,true,p_reason,v_ready,'CF-CHG-20260823-024'); end if;
return jsonb_build_object('course_id',p_course_id,'profile_code',p_profile_code,'prior_status',v_prior,'target_status',v_target,'changed',v_changed,'canonical_changed',v_canonical_changed=1,'website_channel',v_website_status,'website_changed',v_website_changed=1,'zoho_channel',v_zoho_status,'zoho_changed',v_zoho_changed=1,'search_refresh_required',v_canonical_changed=1,'readiness',v_ready);
end $$;


ALTER FUNCTION "publishing"."set_course_publication_v1"("p_course_id" "uuid", "p_target_status" "text", "p_profile_code" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "publishing"."set_course_publication_v1"("p_course_id" "uuid", "p_target_status" "text", "p_profile_code" "text", "p_reason" "text") IS 'CF-CHG-20260823-024: service-only bounded Course publication mutation; requires profile readiness for internal/published.';



CREATE OR REPLACE FUNCTION "ref"."resolve_subdivision_exact"("p_country_id" "uuid", "p_source_state" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'ref'
    AS $$
  select s.id
  from ref.subdivisions s
  where s.country_id = p_country_id
    and nullif(btrim(p_source_state),'') is not null
    and (
      upper(s.code) = upper(btrim(p_source_state))
      or lower(s.name) = lower(btrim(p_source_state))
      or upper(regexp_replace(s.code, '^.*-', '')) = upper(btrim(p_source_state))
    )
  order by case
    when upper(s.code) = upper(btrim(p_source_state)) then 0
    when lower(s.name) = lower(btrim(p_source_state)) then 1
    else 2
  end, s.id
  limit 1
$$;


ALTER FUNCTION "ref"."resolve_subdivision_exact"("p_country_id" "uuid", "p_source_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."decode_entities"("p" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v text := p; m text[];
begin
  if v is null then return null; end if;
  for m in select regexp_matches(v, '&#[xX]([0-9a-fA-F]{1,6});', 'g') loop
    v := replace(v, '&#x' || m[1] || ';', chr(('x' || lpad(m[1], 8, '0'))::bit(32)::int));
    v := replace(v, '&#X' || m[1] || ';', chr(('x' || lpad(m[1], 8, '0'))::bit(32)::int));
  end loop;
  for m in select regexp_matches(v, '&#([0-9]{1,7});', 'g') loop
    v := replace(v, '&#' || m[1] || ';', chr(m[1]::int));
  end loop;
  return replace(replace(v, '&apos;', ''''), '&amp;', '&');
end $$;


ALTER FUNCTION "scholarship"."decode_entities"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."deterministic_uuid"("p_key" "text") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select (
    substr(md5(p_key),1,8) || '-' ||
    substr(md5(p_key),9,4) || '-' ||
    '5' || substr(md5(p_key),14,3) || '-' ||
    'a' || substr(md5(p_key),18,3) || '-' ||
    substr(md5(p_key),21,12)
  )::uuid
$$;


ALTER FUNCTION "scholarship"."deterministic_uuid"("p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."money_prefix"("p_currency" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case upper(coalesce(p_currency, 'AUD')) when 'AUD' then 'A$' when 'NZD' then 'NZ$' when 'CAD' then 'C$' when 'USD' then 'US$' when 'GBP' then '£' else upper(p_currency) || ' ' end
$_$;


ALTER FUNCTION "scholarship"."money_prefix"("p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."normalise_first_party_url"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select nullif(lower(regexp_replace(split_part(replace(coalesce(p_url,''),'&amp;','&'),'#',1),'/+$','')),'');
$_$;


ALTER FUNCTION "scholarship"."normalise_first_party_url"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."normalise_title"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select nullif(lower(regexp_replace(trim(coalesce(p_text,'')),'[^a-z0-9]+','','g')),'');
$$;


ALTER FUNCTION "scholarship"."normalise_title"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."provider_currency"("p_provider_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select k.default_currency_code from catalogue.providers p join ref.countries k on k.id = p.country_id where p.id = p_provider_id), 'AUD')
$$;


ALTER FUNCTION "scholarship"."provider_currency"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "scholarship"."course_financial_calculations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "mapping_id" "uuid" NOT NULL,
    "scholarship_id" "uuid" NOT NULL,
    "course_id" "uuid" NOT NULL,
    "course_fee_id" "uuid",
    "calculation_status" "text" NOT NULL,
    "award_value_type" "text",
    "award_percentage" numeric(7,4),
    "award_amount" numeric(14,2),
    "currency_code" character(3),
    "fee_amount" numeric(14,2),
    "fee_type" "text",
    "fee_basis" "text",
    "fee_year" integer,
    "scholarship_saving_amount" numeric(14,2),
    "net_fee_amount" numeric(14,2),
    "calculation_formula" "text",
    "calculation_reason" "text",
    "scholarship_evidence_id" "uuid",
    "fee_evidence_id" "uuid",
    "calculated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "course_financial_calculations_status_check" CHECK (("calculation_status" = ANY (ARRAY['calculated'::"text", 'award_not_structured'::"text", 'award_scope_unresolved'::"text", 'fee_not_found'::"text", 'fee_ambiguous'::"text", 'currency_mismatch'::"text", 'not_applicable'::"text"])))
);


ALTER TABLE "scholarship"."course_financial_calculations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."refresh_course_financial_calculation"("p_mapping_id" "uuid") RETURNS "scholarship"."course_financial_calculations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'catalogue', 'pipeline'
    AS $$
declare
  v_map scholarship.course_mappings%rowtype;
  v_s scholarship.scholarships%rowtype;
  v_fee catalogue.course_fees%rowtype;
  v_status text;
  v_reason text;
  v_saving numeric(14,2);
  v_net numeric(14,2);
  v_formula text;
  v_result scholarship.course_financial_calculations%rowtype;
  v_years numeric;
  v_est numeric(14,2);
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  select * into v_map from scholarship.course_mappings where id=p_mapping_id;
  if not found then raise exception 'mapping not found' using errcode='22023'; end if;
  select * into v_s from scholarship.scholarships where id=v_map.scholarship_id;

  if v_s.award_value_type is distinct from 'percentage' or v_s.award_percentage is null then
    v_status:='award_not_structured'; v_reason:='Percentage calculation requires a structured award_percentage.';
  elsif v_s.award_value_is_maximum then
    v_status:='award_not_structured'; v_reason:='The award is a maximum ("up to"); no saving is worked out.';
  elsif v_s.award_applies_to_fee_type is distinct from 'tuition_fee' then
    v_status:='award_scope_unresolved'; v_reason:='The provider page does not say the percentage is off tuition fees.';
  else
    -- Decision 212: the provider's annual international tuition fee for the course; the scholarship's year when it
    -- states one, otherwise the latest year recorded
    select f.* into v_fee from catalogue.course_fees f
     where f.course_id=v_map.course_id and f.audience='international' and f.fee_type='provider_current_tuition'
       and f.basis in ('annual','indicative_annual','current indicative annual international tuition')
       and f.amount > 0 and coalesce(f.status,'active') not in ('inactive','retired','superseded')
       and (v_s.academic_year is null or f.fee_year is null or f.fee_year=v_s.academic_year)
     order by (f.fee_year is not distinct from v_s.academic_year) desc, f.fee_year desc nulls last, f.updated_at desc nulls last
     limit 1;
    if v_fee.id is null then
      -- Decision 247: no annual fee from the provider; estimate one from the registered CRICOS course cost
      select f.* into v_fee from catalogue.course_fees f join pipeline.sources src on src.id = f.source_id
       where f.course_id = v_map.course_id and f.audience in ('international', 'all') and f.fee_type = 'tuition' and f.basis = 'registered_total_course'
         and src.label = 'CRICOS Providers, Courses and Locations' and f.amount > 0 and coalesce(f.status, 'active') = 'active'
       order by f.updated_at desc nulls last, f.id limit 1;
      select case c.duration_unit when 'weeks' then c.duration_value / 52.0 when 'months' then c.duration_value / 12.0 when 'years' then c.duration_value end
        into v_years from catalogue.courses c where c.id = v_map.course_id;
      if v_fee.id is null or coalesce(v_years, 0) <= 0 then
        v_fee := null; v_status:='fee_not_found'; v_reason:='No annual international tuition fee is recorded for this course, and no registered course cost and duration to estimate one.';
      elsif v_s.award_currency_code is not null and v_s.award_currency_code <> v_fee.currency_code then
        v_status:='currency_mismatch'; v_reason:='Scholarship and Course fee currencies differ.';
      else
        v_est := round(v_fee.amount / greatest(v_years, 1), 2);
        v_saving := round(v_est * (v_s.award_percentage / 100.0), 2);
        v_net := round(v_est - v_saving, 2);
        v_formula := 'estimated annual tuition = registered total course tuition / registered duration in years (at least 1); saving = estimate * (award_percentage / 100), per year';
        v_status := 'calculated';
        v_reason := 'Estimated from the registered CRICOS course cost (Decision 247); replaced by the provider''s annual fee when one is recorded.';
      end if;
    elsif exists (select 1 from catalogue.course_fees f where f.course_id=v_map.course_id and f.id<>v_fee.id and f.audience='international'
                    and f.fee_type='provider_current_tuition' and f.basis in ('annual','indicative_annual','current indicative annual international tuition')
                    and f.amount > 0 and coalesce(f.status,'active') not in ('inactive','retired','superseded')
                    and f.fee_year is not distinct from v_fee.fee_year and f.amount<>v_fee.amount) then
      v_fee:=null; v_status:='fee_ambiguous'; v_reason:='More than one annual tuition fee is recorded for the same year; a person must settle which applies.';
    elsif v_s.award_currency_code is not null and v_s.award_currency_code<>v_fee.currency_code then
      v_status:='currency_mismatch'; v_reason:='Scholarship and Course fee currencies differ.';
    else
      v_saving:=round(v_fee.amount*(v_s.award_percentage/100.0),2);
      v_net:=round(v_fee.amount-v_saving,2);
      v_formula:='annual tuition fee * (award_percentage / 100), per year';
      v_status:='calculated';
      v_reason:='Per-year saving from the provider''s annual international tuition fee'||coalesce(' for '||v_fee.fee_year,'')||'.';
    end if;
  end if;

  insert into scholarship.course_financial_calculations(
    mapping_id,scholarship_id,course_id,course_fee_id,calculation_status,
    award_value_type,award_percentage,award_amount,currency_code,fee_amount,fee_type,fee_basis,fee_year,
    scholarship_saving_amount,net_fee_amount,calculation_formula,calculation_reason,
    scholarship_evidence_id,fee_evidence_id,calculated_at,metadata)
  values(
    v_map.id,v_s.id,v_map.course_id,v_fee.id,v_status,
    v_s.award_value_type,v_s.award_percentage,v_s.award_amount,coalesce(v_s.award_currency_code,v_fee.currency_code),coalesce(v_est,v_fee.amount),v_fee.fee_type,
    case when v_est is not null then 'estimated_annual_from_registered_total' when v_fee.id is not null then 'annual' end,v_fee.fee_year,
    v_saving,v_net,v_formula,v_reason,coalesce(v_map.evidence_id,v_s.evidence_id),v_fee.evidence_id,now(),
    jsonb_build_object('award_duration_basis',v_s.award_duration_basis,'academic_year',v_s.academic_year,'fee_basis_recorded',v_fee.basis,'decision','Decision 212'))
  on conflict(mapping_id) do update set
    scholarship_id=excluded.scholarship_id,course_id=excluded.course_id,course_fee_id=excluded.course_fee_id,
    calculation_status=excluded.calculation_status,award_value_type=excluded.award_value_type,
    award_percentage=excluded.award_percentage,award_amount=excluded.award_amount,currency_code=excluded.currency_code,
    fee_amount=excluded.fee_amount,fee_type=excluded.fee_type,fee_basis=excluded.fee_basis,fee_year=excluded.fee_year,
    scholarship_saving_amount=excluded.scholarship_saving_amount,net_fee_amount=excluded.net_fee_amount,
    calculation_formula=excluded.calculation_formula,calculation_reason=excluded.calculation_reason,
    scholarship_evidence_id=excluded.scholarship_evidence_id,fee_evidence_id=excluded.fee_evidence_id,
    calculated_at=excluded.calculated_at,metadata=excluded.metadata
  returning * into v_result;
  return v_result;
end $$;


ALTER FUNCTION "scholarship"."refresh_course_financial_calculation"("p_mapping_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."refresh_course_financial_calculations"("p_course_id" "uuid" DEFAULT NULL::"uuid", "p_scholarship_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'catalogue'
    AS $$
declare
  r record;
  v_total integer:=0;
  v_calculated integer:=0;
  v_unresolved integer:=0;
  v_status text;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  for r in
    select m.id
    from scholarship.course_mappings m
    join scholarship.scholarships s on s.id=m.scholarship_id
    where m.mapping_state='mapped'
      and (p_course_id is null or m.course_id=p_course_id)
      and (p_scholarship_id is null or m.scholarship_id=p_scholarship_id)
      and (s.award_value_type='percentage' or exists(select 1 from scholarship.course_financial_calculations fc where fc.mapping_id=m.id))
  loop
    select (scholarship.refresh_course_financial_calculation(r.id)).calculation_status into v_status;
    v_total:=v_total+1;
    if v_status='calculated' then v_calculated:=v_calculated+1; else v_unresolved:=v_unresolved+1; end if;
  end loop;
  return jsonb_build_object('ok',true,'refreshed',v_total,'calculated',v_calculated,'unresolved',v_unresolved);
end $$;


ALTER FUNCTION "scholarship"."refresh_course_financial_calculations"("p_course_id" "uuid", "p_scholarship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."value_label"("p_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship'
    AS $$
  select case
    when s.award_value_type = 'percentage' and s.award_percentage is not null then
      case when s.award_value_is_maximum then 'Up to ' else '' end
      || trim(to_char(s.award_percentage, 'FM990.##'), '.') || '%'
      || case when s.award_applies_to_fee_type = 'tuition_fee' then ' of tuition fees' else ' off fees' end
      || case s.award_duration_basis when 'program_duration' then ' for the course' when 'annual_program_duration' then ' for the course' when 'per_semester' then ' a semester' when 'one_off' then ', one-off' else '' end
    when s.award_value_type = 'fixed_amount' and s.award_amount is not null then
      case when s.award_value_is_maximum then 'Up to ' else '' end
      || scholarship.money_prefix(coalesce(s.award_currency_code, 'AUD'))
      || to_char(s.award_amount, 'FM999,999,999')
      || case s.award_duration_basis when 'annual' then ' a year' when 'annual_program_duration' then ' a year for the course' when 'one_off' then ' one-off' when 'per_semester' then ' a semester' when 'program_duration' then ' for the course' else '' end
    when exists (select 1 from scholarship.award_tiers t where t.scholarship_id = s.id and t.tier_code like 'page_tier_%') then s.award_value_text
    else null end
  from scholarship.scholarships s where s.id = p_id
$$;


ALTER FUNCTION "scholarship"."value_label"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."course_candidates_v1"("p_query" "text" DEFAULT NULL::"text", "p_query_embedding" "extensions"."vector" DEFAULT NULL::"extensions"."vector", "p_embedding_model" "text" DEFAULT NULL::"text", "p_profile_code" "text" DEFAULT 'website-default'::"text", "p_mode" "text" DEFAULT 'keyword'::"text", "p_country_codes" "text"[] DEFAULT NULL::"text"[], "p_subdivision_codes" "text"[] DEFAULT NULL::"text"[], "p_level_codes" "text"[] DEFAULT NULL::"text"[], "p_field_codes" "text"[] DEFAULT NULL::"text"[], "p_delivery_modes" "text"[] DEFAULT NULL::"text"[], "p_has_fee" boolean DEFAULT NULL::boolean, "p_has_scholarship" boolean DEFAULT NULL::boolean, "p_publication_statuses" "text"[] DEFAULT ARRAY['published'::"text", 'internal'::"text"], "p_limit" integer DEFAULT 20) RETURNS TABLE("course_id" "uuid", "fts_rank" real, "vector_similarity" real, "fused_score" double precision, "mode_used" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'search', 'extensions'
    AS $$
declare
  v_profile_id uuid;
  v_rrf_k integer := 60;
  v_fts_weight double precision := 1.0;
  v_vector_weight double precision := 0.55;
  v_limit integer := greatest(1,least(coalesce(p_limit,20),100));
  v_candidate_limit integer;
  v_has_vectors boolean := false;
begin
  select id,
         coalesce((config->>'rrf_k')::integer,60),
         coalesce((config->>'fts_weight')::double precision,1.0),
         coalesce((config->>'vector_weight')::double precision,0.55)
  into v_profile_id,v_rrf_k,v_fts_weight,v_vector_weight
  from search.profiles
  where code=p_profile_code and status='active'
  limit 1;

  if v_profile_id is null then
    return;
  end if;

  v_candidate_limit := greatest(200,least(v_limit*20,2000));

  if p_mode in ('hybrid','vector') and p_query_embedding is not null and p_embedding_model is not null then
    select exists(
      select 1 from search.course_embeddings e
      where e.profile_id=v_profile_id and e.model_name=p_embedding_model
      limit 1
    ) into v_has_vectors;
  end if;

  if p_mode='keyword' or (p_mode='hybrid' and not v_has_vectors) then
    return query
    with q as (
      select websearch_to_tsquery('english',coalesce(nullif(trim(p_query),''),'')) as tsq
    ), base as (
      select d.course_id,
        case when coalesce(trim(p_query),'')='' then 0::real else ts_rank_cd(d.search_tsv,(select tsq from q))::real end as score
      from search.course_documents d
      where (p_country_codes is null or d.country_code=any(p_country_codes))
        and (p_subdivision_codes is null or d.subdivision_codes && p_subdivision_codes)
        and (p_level_codes is null or d.study_level_code=any(p_level_codes))
        and (p_field_codes is null or d.primary_field_code=any(p_field_codes))
        and (p_delivery_modes is null or d.delivery_modes && p_delivery_modes)
        and (p_has_fee is null or d.has_fee=p_has_fee)
        and (p_has_scholarship is null or d.has_scholarship=p_has_scholarship)
        and (p_publication_statuses is null or d.publication_status=any(p_publication_statuses))
        and (coalesce(trim(p_query),'')='' or d.search_tsv @@ (select tsq from q))
      order by score desc,d.course_title,d.course_id
      limit v_limit
    ), ranked as (
      select b.*,row_number() over(order by b.score desc,b.course_id) as pos from base b
    )
    select r.course_id,r.score,null::real,
      (v_fts_weight/(v_rrf_k+r.pos))::double precision,
      case when p_mode='hybrid' then 'fts_fallback' else 'keyword' end::text
    from ranked r
    order by r.pos;
    return;
  end if;

  if p_mode='vector' and not v_has_vectors then
    return;
  end if;

  return query
  with q as (
    select websearch_to_tsquery('english',coalesce(nullif(trim(p_query),''),'')) as tsq
  ), fts_base as (
    select d.course_id,
      case when coalesce(trim(p_query),'')='' then 0::real else ts_rank_cd(d.search_tsv,(select tsq from q))::real end as score
    from search.course_documents d
    where p_mode='hybrid'
      and (p_country_codes is null or d.country_code=any(p_country_codes))
      and (p_subdivision_codes is null or d.subdivision_codes && p_subdivision_codes)
      and (p_level_codes is null or d.study_level_code=any(p_level_codes))
      and (p_field_codes is null or d.primary_field_code=any(p_field_codes))
      and (p_delivery_modes is null or d.delivery_modes && p_delivery_modes)
      and (p_has_fee is null or d.has_fee=p_has_fee)
      and (p_has_scholarship is null or d.has_scholarship=p_has_scholarship)
      and (p_publication_statuses is null or d.publication_status=any(p_publication_statuses))
      and (coalesce(trim(p_query),'')='' or d.search_tsv @@ (select tsq from q))
    order by score desc,d.course_title,d.course_id
    limit v_candidate_limit
  ), fts as (
    select course_id,score,row_number() over(order by score desc,course_id) as pos from fts_base
  ), vec_base as (
    select d.course_id,(1-(e.embedding <=> p_query_embedding))::real as similarity
    from search.course_embeddings e
    join search.course_documents d on d.course_id=e.course_id
    where e.profile_id=v_profile_id
      and e.model_name=p_embedding_model
      and e.content_hash=d.semantic_content_hash
      and (p_country_codes is null or d.country_code=any(p_country_codes))
      and (p_subdivision_codes is null or d.subdivision_codes && p_subdivision_codes)
      and (p_level_codes is null or d.study_level_code=any(p_level_codes))
      and (p_field_codes is null or d.primary_field_code=any(p_field_codes))
      and (p_delivery_modes is null or d.delivery_modes && p_delivery_modes)
      and (p_has_fee is null or d.has_fee=p_has_fee)
      and (p_has_scholarship is null or d.has_scholarship=p_has_scholarship)
      and (p_publication_statuses is null or d.publication_status=any(p_publication_statuses))
    order by e.embedding <=> p_query_embedding
    limit v_candidate_limit
  ), vec as (
    select course_id,similarity,row_number() over(order by similarity desc,course_id) as pos from vec_base
  ), merged as (
    select coalesce(f.course_id,v.course_id) as course_id,
           f.score as fts_rank,v.similarity as vector_similarity,
           f.pos as fts_pos,v.pos as vec_pos
    from fts f full outer join vec v using(course_id)
  )
  select m.course_id,m.fts_rank,m.vector_similarity,
    (case when m.fts_pos is null then 0 else v_fts_weight/(v_rrf_k+m.fts_pos) end
     + case when m.vec_pos is null then 0 else v_vector_weight/(v_rrf_k+m.vec_pos) end)::double precision,
    case when p_mode='vector' then 'vector' else 'hybrid' end::text
  from merged m
  order by 4 desc,m.fts_rank desc nulls last,m.vector_similarity desc nulls last,m.course_id
  limit v_limit;
end
$$;


ALTER FUNCTION "search"."course_candidates_v1"("p_query" "text", "p_query_embedding" "extensions"."vector", "p_embedding_model" "text", "p_profile_code" "text", "p_mode" "text", "p_country_codes" "text"[], "p_subdivision_codes" "text"[], "p_level_codes" "text"[], "p_field_codes" "text"[], "p_delivery_modes" "text"[], "p_has_fee" boolean, "p_has_scholarship" boolean, "p_publication_statuses" "text"[], "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."rebuild_course_documents"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search'
    AS $$
declare v_result jsonb;
begin
  v_result := search.refresh_course_documents_v3(true);
  return (v_result->'base'->>'stage_count')::bigint;
end $$;


ALTER FUNCTION "search"."rebuild_course_documents"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_base_v3"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'catalogue', 'publishing', 'ref', 'pipeline', 'extensions', 'pg_temp'
    AS $$
declare
  v_generation bigint;
  v_current_generation bigint;
  v_stage_count bigint;
  v_new bigint;
  v_changed bigint;
  v_unchanged bigint;
  v_removed bigint;
  v_applied bigint := 0;
  v_stage_hash text;
  v_country_counts jsonb;
  v_coverage jsonb;
begin
  drop table if exists pg_temp.cf_search_course_base_v3_stage;

  create temp table cf_search_course_base_v3_stage on commit drop as
  with gates as (
    select g.country_id
    from search.projection_country_gates g
    where g.projection_code='courses' and g.gate_status='approved'
  )
  select
    c.id as course_id,
    c.provider_id,
    p.country_id,
    c.study_level_id,
    c.primary_field_id,
    c.stable_key as course_stable_key,
    p.stable_key as provider_stable_key,
    c.course_code,
    trim(co.iso_alpha2::text) as country_code,
    sl.code as study_level_code,
    fos.code as primary_field_code,
    fos.name as primary_field_name,
    coalesce(p.display_name,p.canonical_name) as provider_name,
    c.canonical_title as course_title,
    coalesce(coll.collection_names,'{}'::text[]) as collection_names,
    coalesce(acad.academic_option_names,'{}'::text[]) as academic_option_names,
    c.description,
    coalesce(geo.subdivision_codes,'{}'::text[]) as subdivision_codes,
    coalesce(geo.delivery_modes,'{}'::text[]) as delivery_modes,
    cardinality(coalesce(geo.subdivision_codes,'{}'::text[])) > 0 as has_state,
    c.publication_status,
    (select max(es.completeness_score) from publishing.entity_states es where es.entity_id=c.id) as completeness_score,
    greatest(c.updated_at,p.updated_at,coalesce(geo.geo_updated_at,'epoch'::timestamptz),coalesce(fos.updated_at,'epoch'::timestamptz)) as source_updated_at,
    concat_ws(' ',c.canonical_title,coalesce(p.display_name,p.canonical_name),coalesce(c.course_code,''),coalesce(sl.name,''),coalesce(fos.name,''),coalesce(array_to_string(coll.collection_names,' '),''),coalesce(array_to_string(acad.academic_option_names,' '),''),coalesce(c.description,'')) as base_search_text,
    setweight(to_tsvector('english',coalesce(c.canonical_title,'')),'A') ||
    setweight(to_tsvector('english',coalesce(p.display_name,p.canonical_name,'')),'B') ||
    setweight(to_tsvector('english',concat_ws(' ',coalesce(c.course_code,''),coalesce(sl.name,''),coalesce(fos.name,''),coalesce(array_to_string(coll.collection_names,' '),''),coalesce(array_to_string(acad.academic_option_names,' '),''))),'B') ||
    setweight(to_tsvector('english',coalesce(c.description,'')),'C') as base_search_tsv
  from catalogue.courses c
  join catalogue.providers p on p.id=c.provider_id
  join gates g on g.country_id=p.country_id
  join ref.countries co on co.id=p.country_id
  left join ref.study_levels sl on sl.id=c.study_level_id
  left join ref.fields_of_study fos on fos.id=c.primary_field_id
  left join lateral (
    select
      coalesce(array_agg(distinct sd.code order by sd.code) filter (where sd.code is not null),'{}'::text[]) as subdivision_codes,
      coalesce(array_agg(distinct cc.delivery_mode order by cc.delivery_mode) filter (where nullif(trim(cc.delivery_mode),'') is not null),'{}'::text[]) as delivery_modes,
      max(cp.updated_at) as geo_updated_at
    from catalogue.course_campuses cc
    join catalogue.campuses cp on cp.id=cc.campus_id
    left join ref.subdivisions sd on sd.id=cp.subdivision_id
    where cc.course_id=c.id
  ) geo on true
  left join lateral (
    select array_agg(distinct cl.name order by cl.name) as collection_names
    from catalogue.course_collection_memberships cm
    join catalogue.course_collections cl on cl.id=cm.collection_id
    where cm.course_id=c.id
  ) coll on true
  left join lateral (
    select array_agg(distinct ao.name order by ao.name) as academic_option_names
    from catalogue.course_academic_options ao
    where ao.course_id=c.id and ao.status='active'
  ) acad on true
  where c.lifecycle_status='active';

  alter table cf_search_course_base_v3_stage
    add column projection_version text not null default 'course-v3',
    add column generated_at timestamptz not null default now(),
    add column content_hash text,
    add column semantic_content_hash text;

  update cf_search_course_base_v3_stage s
  set semantic_content_hash=encode(extensions.digest(jsonb_build_object(
      'course',s.course_stable_key,'provider',s.provider_name,'title',s.course_title,'code',s.course_code,
      'level',s.study_level_code,'field',s.primary_field_code,'collections',s.collection_names,
      'academic_options',s.academic_option_names,'description',s.description
    )::text,'sha256'),'hex'),
      content_hash=encode(extensions.digest(jsonb_build_object(
      'course',s.course_stable_key,'provider',s.provider_stable_key,'country',s.country_code,
      'level',s.study_level_code,'field',s.primary_field_code,'states',s.subdivision_codes,
      'delivery',s.delivery_modes,'has_state',s.has_state,'publication',s.publication_status,
      'semantic',encode(extensions.digest(jsonb_build_object(
        'course',s.course_stable_key,'provider',s.provider_name,'title',s.course_title,'code',s.course_code,
        'level',s.study_level_code,'field',s.primary_field_code,'collections',s.collection_names,
        'academic_options',s.academic_option_names,'description',s.description
      )::text,'sha256'),'hex')
    )::text,'sha256'),'hex') where true;

  select count(*) into v_stage_count from cf_search_course_base_v3_stage;
  select coalesce(jsonb_object_agg(country_code,cnt),'{}'::jsonb) into v_country_counts
  from (select country_code,count(*) cnt from cf_search_course_base_v3_stage group by country_code order by country_code) x;
  select jsonb_build_object(
    'with_field',count(*) filter(where primary_field_id is not null),
    'with_state',count(*) filter(where has_state),
    'with_delivery',count(*) filter(where cardinality(delivery_modes)>0)
  ) into v_coverage from cf_search_course_base_v3_stage;

  select count(*) into v_new from cf_search_course_base_v3_stage s left join search.course_documents d using(course_id) where d.course_id is null;
  select count(*) into v_changed from cf_search_course_base_v3_stage s join search.course_documents d using(course_id)
   where d.content_hash is distinct from s.content_hash or d.projection_version is distinct from 'course-v3';
  select count(*) into v_unchanged from cf_search_course_base_v3_stage s join search.course_documents d using(course_id)
   where d.content_hash is not distinct from s.content_hash and d.projection_version='course-v3';
  select count(*) into v_removed from search.course_documents d left join cf_search_course_base_v3_stage s using(course_id) where s.course_id is null;

  select generation into v_current_generation from search.projection_state where projection_code='courses' for update;
  if v_current_generation is null then
    insert into search.projection_state(projection_code,generation,row_count,metadata) values('courses',1,0,'{}'::jsonb)
    returning generation into v_current_generation;
  end if;

  select encode(extensions.digest(coalesce(string_agg(course_id::text||':'||content_hash,'|' order by course_id::text),''),'sha256'),'hex') into v_stage_hash from cf_search_course_base_v3_stage;

  if p_apply then
    v_generation:=v_current_generation+1;
    insert into search.course_documents(
      course_id,provider_id,country_id,study_level_id,primary_field_id,course_stable_key,provider_stable_key,course_code,country_code,study_level_code,primary_field_code,primary_field_name,
      provider_name,course_title,collection_names,academic_option_names,description,search_text,search_tsv,subdivision_codes,delivery_modes,has_state,
      publication_status,completeness_score,catalogue_generation,projection_version,source_updated_at,generated_at,content_hash,semantic_content_hash,updated_at
    )
    select course_id,provider_id,country_id,study_level_id,primary_field_id,course_stable_key,provider_stable_key,course_code,country_code,study_level_code,primary_field_code,primary_field_name,
      provider_name,course_title,collection_names,academic_option_names,description,base_search_text,base_search_tsv,subdivision_codes,delivery_modes,has_state,
      publication_status,completeness_score,v_generation,'course-v3',source_updated_at,generated_at,content_hash,semantic_content_hash,now()
    from cf_search_course_base_v3_stage
    on conflict(course_id) do update set
      provider_id=excluded.provider_id,country_id=excluded.country_id,study_level_id=excluded.study_level_id,primary_field_id=excluded.primary_field_id,
      course_stable_key=excluded.course_stable_key,provider_stable_key=excluded.provider_stable_key,course_code=excluded.course_code,country_code=excluded.country_code,
      study_level_code=excluded.study_level_code,primary_field_code=excluded.primary_field_code,primary_field_name=excluded.primary_field_name,provider_name=excluded.provider_name,
      course_title=excluded.course_title,collection_names=excluded.collection_names,academic_option_names=excluded.academic_option_names,description=excluded.description,
      subdivision_codes=excluded.subdivision_codes,delivery_modes=excluded.delivery_modes,has_state=excluded.has_state,publication_status=excluded.publication_status,
      completeness_score=excluded.completeness_score,catalogue_generation=excluded.catalogue_generation,projection_version='course-v3',source_updated_at=excluded.source_updated_at,
      generated_at=excluded.generated_at,content_hash=excluded.content_hash,semantic_content_hash=case when nullif(trim(search.course_documents.enrichment_semantic_text),'') is null then excluded.semantic_content_hash else encode(extensions.digest(jsonb_build_object('base',excluded.course_stable_key,'provider',excluded.provider_name,'title',excluded.course_title,'code',excluded.course_code,'level',excluded.study_level_code,'field',excluded.primary_field_code,'collections',excluded.collection_names,'academic_options',excluded.academic_option_names,'description',excluded.description,'enrichment',nullif(trim(search.course_documents.enrichment_semantic_text),''))::text,'sha256'),'hex') end,updated_at=now()
    where search.course_documents.content_hash is distinct from excluded.content_hash
       or search.course_documents.projection_version is distinct from 'course-v3';
    get diagnostics v_applied=row_count;
    delete from search.course_documents d where not exists(select 1 from cf_search_course_base_v3_stage s where s.course_id=d.course_id);
  else
    v_generation:=v_current_generation;
  end if;

  return jsonb_build_object('apply',p_apply,'projection','courses','projection_version','course-v3','generation',v_generation,
    'stage_count',v_stage_count,'new',v_new,'changed',v_changed,'unchanged',v_unchanged,'removed',v_removed,'applied_rows',v_applied,
    'countries',v_country_counts,'coverage',v_coverage,'base_content_hash',v_stage_hash);
end
$$;


ALTER FUNCTION "search"."refresh_course_base_v3"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_documents_v2"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'catalogue', 'scholarship', 'publishing', 'ref', 'pipeline', 'extensions', 'pg_temp'
    AS $$
declare
  v_generation bigint;
  v_current_generation bigint;
  v_stage_count bigint;
  v_new bigint;
  v_changed bigint;
  v_unchanged bigint;
  v_removed bigint;
  v_applied bigint := 0;
  v_stage_hash text;
  v_country_counts jsonb;
  v_coverage jsonb;
begin
  drop table if exists pg_temp.cf_search_course_stage;

  create temp table cf_search_course_stage on commit drop as
  with gates as (
    select g.country_id
    from search.projection_country_gates g
    where g.projection_code='courses' and g.gate_status='approved'
  ),
  eg as (
    select
      bool_or(domain_code='scholarship' and gate_status='approved') as scholarship_ok,
      bool_or(domain_code='course_link' and gate_status='approved') as link_ok,
      bool_or(domain_code='course_fee' and gate_status='approved') as fee_ok,
      bool_or(domain_code='course_intake' and gate_status='approved') as intake_ok,
      bool_or(domain_code='course_english' and gate_status='approved') as english_ok
    from search.enrichment_gates
    where projection_code='courses'
  )
  select
    c.id as course_id,
    c.provider_id,
    p.country_id,
    c.study_level_id,
    c.primary_field_id,
    c.stable_key as course_stable_key,
    p.stable_key as provider_stable_key,
    c.course_code,
    trim(co.iso_alpha2::text) as country_code,
    sl.code as study_level_code,
    fos.code as primary_field_code,
    fos.name as primary_field_name,
    coalesce(p.display_name,p.canonical_name) as provider_name,
    c.canonical_title as course_title,
    coalesce(coll.collection_names,'{}'::text[]) as collection_names,
    coalesce(acad.academic_option_names,'{}'::text[]) as academic_option_names,
    c.description,
    coalesce(geo.subdivision_codes,'{}'::text[]) as subdivision_codes,
    coalesce(geo.delivery_modes,'{}'::text[]) as delivery_modes,
    cardinality(coalesce(geo.subdivision_codes,'{}'::text[])) > 0 as has_state,
    (select link_ok from eg) and exists(
      select 1 from catalogue.course_links l
      where l.link_type = 'official_course' and l.course_id=c.id and l.status='active'
        and (l.valid_from is null or l.valid_from<=current_date)
        and (l.valid_to is null or l.valid_to>=current_date)
    ) as has_link,
    (select fee_ok from eg) and exists(
      select 1 from catalogue.course_fees f
      where f.course_id=c.id and f.status='active'
        and f.audience in ('international','all')
        and (f.valid_from is null or f.valid_from<=current_date)
        and (f.valid_to is null or f.valid_to>=current_date)
    ) as has_fee,
    (select intake_ok from eg) and exists(
      select 1 from catalogue.course_intakes i
      where i.course_id=c.id and i.status='active'
    ) as has_intake,
    (select english_ok from eg) and exists(
      select 1 from catalogue.course_english_requirements er
      where er.course_id=c.id
    ) as has_english,
    (select scholarship_ok from eg) and exists(
      select 1
      from scholarship.scopes ss
      join scholarship.scholarships s on s.id=ss.scholarship_id
      where s.lifecycle_status='active'
        and s.publication_status in ('published','internal')
        and ((ss.scope_type='course' and ss.course_id=c.id)
          or (ss.scope_type='provider' and ss.provider_id=c.provider_id))
    ) as has_scholarship,
    c.publication_status,
    (select max(es.completeness_score) from publishing.entity_states es where es.entity_id=c.id) as completeness_score,
    greatest(c.updated_at,p.updated_at,coalesce(geo.geo_updated_at,'epoch'::timestamptz),coalesce(fos.updated_at,'epoch'::timestamptz)) as source_updated_at,
    concat_ws(' ',
      c.canonical_title,
      coalesce(p.display_name,p.canonical_name),
      coalesce(c.course_code,''),
      coalesce(sl.name,''),
      coalesce(fos.name,''),
      coalesce(array_to_string(coll.collection_names,' '),''),
      coalesce(array_to_string(acad.academic_option_names,' '),''),
      coalesce(c.description,'')
    ) as search_text,
    setweight(to_tsvector('english',coalesce(c.canonical_title,'')),'A') ||
    setweight(to_tsvector('english',coalesce(p.display_name,p.canonical_name,'')),'B') ||
    setweight(to_tsvector('english',concat_ws(' ',coalesce(c.course_code,''),coalesce(sl.name,''),coalesce(fos.name,''),coalesce(array_to_string(coll.collection_names,' '),''),coalesce(array_to_string(acad.academic_option_names,' '),''))),'B') ||
    setweight(to_tsvector('english',coalesce(c.description,'')),'C') as search_tsv
  from catalogue.courses c
  join catalogue.providers p on p.id=c.provider_id
  join gates g on g.country_id=p.country_id
  join ref.countries co on co.id=p.country_id
  left join ref.study_levels sl on sl.id=c.study_level_id
  left join ref.fields_of_study fos on fos.id=c.primary_field_id
  left join lateral (
    select
      coalesce(array_agg(distinct sd.code order by sd.code) filter (where sd.code is not null),'{}'::text[]) as subdivision_codes,
      coalesce(array_agg(distinct cc.delivery_mode order by cc.delivery_mode) filter (where nullif(trim(cc.delivery_mode),'') is not null),'{}'::text[]) as delivery_modes,
      max(cp.updated_at) as geo_updated_at
    from catalogue.course_campuses cc
    join catalogue.campuses cp on cp.id=cc.campus_id
    left join ref.subdivisions sd on sd.id=cp.subdivision_id
    where cc.course_id=c.id
  ) geo on true
  left join lateral (
    select array_agg(distinct cl.name order by cl.name) as collection_names
    from catalogue.course_collection_memberships cm
    join catalogue.course_collections cl on cl.id=cm.collection_id
    where cm.course_id=c.id
  ) coll on true
  left join lateral (
    select array_agg(distinct ao.name order by ao.name) as academic_option_names
    from catalogue.course_academic_options ao
    where ao.course_id=c.id and ao.status='active'
  ) acad on true
  where c.lifecycle_status='active';

  alter table cf_search_course_stage
    add column projection_version text not null default 'course-v2',
    add column generated_at timestamptz not null default now(),
    add column content_hash text,
    add column semantic_content_hash text;

  update cf_search_course_stage s
  set semantic_content_hash=encode(extensions.digest(jsonb_build_object(
      'course',s.course_stable_key,
      'provider',s.provider_name,
      'title',s.course_title,
      'code',s.course_code,
      'level',s.study_level_code,
      'field',s.primary_field_code,
      'collections',s.collection_names,
      'academic_options',s.academic_option_names,
      'description',s.description
    )::text,'sha256'),'hex'),
      content_hash=encode(extensions.digest(jsonb_build_object(
      'course',s.course_stable_key,
      'provider',s.provider_stable_key,
      'country',s.country_code,
      'level',s.study_level_code,
      'field',s.primary_field_code,
      'states',s.subdivision_codes,
      'delivery',s.delivery_modes,
      'has_state',s.has_state,
      'has_link',s.has_link,
      'has_fee',s.has_fee,
      'has_intake',s.has_intake,
      'has_english',s.has_english,
      'has_scholarship',s.has_scholarship,
      'publication',s.publication_status,
      'semantic',encode(extensions.digest(jsonb_build_object(
        'course',s.course_stable_key,'provider',s.provider_name,'title',s.course_title,'code',s.course_code,
        'level',s.study_level_code,'field',s.primary_field_code,'collections',s.collection_names,
        'academic_options',s.academic_option_names,'description',s.description
      )::text,'sha256'),'hex')
    )::text,'sha256'),'hex') where true;

  select count(*) into v_stage_count from cf_search_course_stage;
  select coalesce(jsonb_object_agg(country_code,cnt),'{}'::jsonb)
  into v_country_counts
  from (select country_code,count(*) cnt from cf_search_course_stage group by country_code order by country_code) x;

  select jsonb_build_object(
    'with_field',count(*) filter(where primary_field_id is not null),
    'with_state',count(*) filter(where has_state),
    'with_delivery',count(*) filter(where cardinality(delivery_modes)>0),
    'with_link',count(*) filter(where has_link),
    'with_fee',count(*) filter(where has_fee),
    'with_intake',count(*) filter(where has_intake),
    'with_english',count(*) filter(where has_english),
    'with_scholarship',count(*) filter(where has_scholarship)
  ) into v_coverage from cf_search_course_stage;

  select count(*) into v_new
  from cf_search_course_stage s left join search.course_documents d using(course_id)
  where d.course_id is null;

  select count(*) into v_changed
  from cf_search_course_stage s join search.course_documents d using(course_id)
  where d.content_hash is distinct from s.content_hash or d.projection_version is distinct from s.projection_version;

  select count(*) into v_unchanged
  from cf_search_course_stage s join search.course_documents d using(course_id)
  where d.content_hash is not distinct from s.content_hash and d.projection_version is not distinct from s.projection_version;

  select count(*) into v_removed
  from search.course_documents d left join cf_search_course_stage s using(course_id)
  where s.course_id is null;

  select generation into v_current_generation from search.projection_state where projection_code='courses' for update;
  if v_current_generation is null then
    insert into search.projection_state(projection_code,generation,row_count,metadata) values('courses',1,0,'{}'::jsonb)
    returning generation into v_current_generation;
  end if;

  select encode(extensions.digest(coalesce(string_agg(course_id::text||':'||content_hash,'|' order by course_id::text),''),'sha256'),'hex')
  into v_stage_hash from cf_search_course_stage;

  if p_apply then
    v_generation := v_current_generation + 1;

    insert into search.course_documents(
      course_id,provider_id,country_id,study_level_id,primary_field_id,
      course_stable_key,provider_stable_key,course_code,country_code,study_level_code,primary_field_code,primary_field_name,
      provider_name,course_title,collection_names,academic_option_names,description,search_text,search_tsv,
      subdivision_codes,delivery_modes,has_state,has_link,has_fee,has_intake,has_english,has_scholarship,
      publication_status,completeness_score,catalogue_generation,projection_version,source_updated_at,generated_at,content_hash,semantic_content_hash,updated_at
    )
    select
      course_id,provider_id,country_id,study_level_id,primary_field_id,
      course_stable_key,provider_stable_key,course_code,country_code,study_level_code,primary_field_code,primary_field_name,
      provider_name,course_title,collection_names,academic_option_names,description,search_text,search_tsv,
      subdivision_codes,delivery_modes,has_state,has_link,has_fee,has_intake,has_english,has_scholarship,
      publication_status,completeness_score,v_generation,projection_version,source_updated_at,generated_at,content_hash,semantic_content_hash,now()
    from cf_search_course_stage
    on conflict(course_id) do update set
      provider_id=excluded.provider_id,
      country_id=excluded.country_id,
      study_level_id=excluded.study_level_id,
      primary_field_id=excluded.primary_field_id,
      course_stable_key=excluded.course_stable_key,
      provider_stable_key=excluded.provider_stable_key,
      course_code=excluded.course_code,
      country_code=excluded.country_code,
      study_level_code=excluded.study_level_code,
      primary_field_code=excluded.primary_field_code,
      primary_field_name=excluded.primary_field_name,
      provider_name=excluded.provider_name,
      course_title=excluded.course_title,
      collection_names=excluded.collection_names,
      academic_option_names=excluded.academic_option_names,
      description=excluded.description,
      search_text=excluded.search_text,
      search_tsv=excluded.search_tsv,
      subdivision_codes=excluded.subdivision_codes,
      delivery_modes=excluded.delivery_modes,
      has_state=excluded.has_state,
      has_link=excluded.has_link,
      has_fee=excluded.has_fee,
      has_intake=excluded.has_intake,
      has_english=excluded.has_english,
      has_scholarship=excluded.has_scholarship,
      publication_status=excluded.publication_status,
      completeness_score=excluded.completeness_score,
      catalogue_generation=excluded.catalogue_generation,
      projection_version=excluded.projection_version,
      source_updated_at=excluded.source_updated_at,
      generated_at=excluded.generated_at,
      content_hash=excluded.content_hash,
      semantic_content_hash=excluded.semantic_content_hash,
      updated_at=now()
    where search.course_documents.content_hash is distinct from excluded.content_hash
       or search.course_documents.projection_version is distinct from excluded.projection_version;

    get diagnostics v_applied=row_count;

    delete from search.course_documents d
    where not exists(select 1 from cf_search_course_stage s where s.course_id=d.course_id);

    update search.projection_state
    set generation=v_generation,
        rebuilt_at=now(),
        row_count=v_stage_count,
        content_hash=v_stage_hash,
        metadata=jsonb_build_object(
          'projection_version','course-v2',
          'countries',v_country_counts,
          'coverage',v_coverage,
          'country_gate','explicit',
          'enrichment_gate','explicit'
        )
    where projection_code='courses';
  else
    v_generation := v_current_generation;
  end if;

  return jsonb_build_object(
    'apply',p_apply,
    'projection','courses',
    'projection_version','course-v2',
    'generation',v_generation,
    'stage_count',v_stage_count,
    'new',v_new,
    'changed',v_changed,
    'unchanged',v_unchanged,
    'removed',v_removed,
    'applied_rows',v_applied,
    'countries',v_country_counts,
    'coverage',v_coverage,
    'content_hash',v_stage_hash
  );
end
$$;


ALTER FUNCTION "search"."refresh_course_documents_v2"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_documents_v3"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'extensions', 'pg_temp'
    AS $$
declare
  v_base jsonb;
  v_enrichment_dry jsonb;
  v_enrichment jsonb;
  v_full_hash text;
  v_coverage jsonb;
  v_generation bigint;
  v_enrichment_changed bigint;
  v_base_new bigint;
begin
  v_base:=search.refresh_course_base_v3(p_apply);
  v_enrichment_dry:=search.refresh_course_enrichment_v1(false);
  v_enrichment_changed:=coalesce((v_enrichment_dry->>'changed')::bigint,0);
  v_base_new:=coalesce((v_base->>'new')::bigint,0);

  if p_apply and (v_enrichment_changed>0 or v_base_new>0) then
    v_enrichment:=search.refresh_course_enrichment_v1(true);
  else
    v_enrichment:=v_enrichment_dry;
  end if;

  if p_apply then
    select encode(extensions.digest(coalesce(string_agg(course_id::text||':'||coalesce(content_hash,'')||':'||coalesce(enrichment_content_hash,''),'|' order by course_id::text),''),'sha256'),'hex')
      into v_full_hash from search.course_documents;
    select jsonb_build_object(
      'with_field',count(*) filter(where primary_field_id is not null),
      'with_state',count(*) filter(where has_state),
      'with_delivery',count(*) filter(where cardinality(delivery_modes)>0),
      'with_regulatory_tuition',count(*) filter(where has_regulatory_tuition),
      'with_provider_current_tuition',count(*) filter(where has_provider_current_tuition),
      'with_official_url',count(*) filter(where official_course_url is not null),
      'with_intake',count(*) filter(where has_intake),
      'with_english',count(*) filter(where has_english),
      'with_scholarship',count(*) filter(where has_scholarship)
    ) into v_coverage from search.course_documents;
    update search.projection_state
      set generation=generation+1,rebuilt_at=now(),row_count=(select count(*) from search.course_documents),content_hash=v_full_hash,
          metadata=jsonb_build_object(
            'projection_version','course-v3','countries',v_base->'countries','coverage',v_coverage,
            'country_gate','explicit','enrichment_gate','domain_and_source_explicit',
            'base_content_hash',v_base->>'base_content_hash','enrichment_stage_hash',v_enrichment->>'stage_hash',
            'refresh_function','search.refresh_course_documents_v3'
          )
      where projection_code='courses'
      returning generation into v_generation;
  else
    select generation into v_generation from search.projection_state where projection_code='courses';
  end if;

  return jsonb_build_object('apply',p_apply,'projection','courses','projection_version','course-v3','generation',v_generation,
    'base',v_base,'enrichment',v_enrichment,'full_content_hash',v_full_hash);
end
$$;


ALTER FUNCTION "search"."refresh_course_documents_v3"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_enrichment_core_scoped_v1"("p_course_ids" "uuid"[], "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'catalogue', 'scholarship', 'pipeline', 'ref', 'extensions', 'pg_temp'
    AS $$
declare
  v_rows bigint;
  v_changed bigint;
  v_unchanged bigint;
  v_stage_hash text;
  v_coverage jsonb;
begin
  drop table if exists pg_temp.cf_search_enrichment_stage;
  create temp table cf_search_enrichment_stage on commit drop as
  with global_gates as (
    select
      bool_or(domain_code='regulatory_tuition' and gate_status='approved') regulatory_ok,
      bool_or(domain_code='provider_current_tuition' and gate_status='approved') provider_fee_ok,
      bool_or(domain_code='official_course_url' and gate_status='approved') link_ok,
      bool_or(domain_code='course_intake' and gate_status='approved') intake_ok,
      bool_or(domain_code='course_english' and gate_status='approved') english_ok,
      bool_or(domain_code='scholarship' and gate_status='approved') scholarship_ok
    from search.enrichment_gates where projection_code='courses'
  )
  select d.course_id,
    case
      when d.country_code='NZ' then 'not_applicable'
      when not (select regulatory_ok from global_gates) then 'not_admitted'
      when rf.fee_id is null then 'source_null'
      when rf.amount=0 then 'zero'
      else 'present'
    end as regulatory_tuition_state,
    ((select regulatory_ok from global_gates) and rf.fee_id is not null) as has_regulatory_tuition,
    case when (select regulatory_ok from global_gates) then rf.amount end as regulatory_tuition_amount,
    case when (select regulatory_ok from global_gates) then rf.currency_code end as regulatory_tuition_currency,
    case when (select regulatory_ok from global_gates) then rf.basis end as regulatory_tuition_basis,
    ((select provider_fee_ok from global_gates) and pf.option_count>0) as has_provider_current_tuition,
    case when (select provider_fee_ok from global_gates) then pf.annual_amount end as provider_annual_tuition_amount,
    case when (select provider_fee_ok from global_gates) then pf.annual_currency end as provider_annual_tuition_currency,
    case when (select provider_fee_ok from global_gates) then coalesce(pf.options,'[]'::jsonb) else '[]'::jsonb end as provider_tuition_options,
    case when (select link_ok from global_gates) then lk.url end as official_course_url,
    case when (select intake_ok from global_gates) then coalesce(it.options,'[]'::jsonb) else '[]'::jsonb end as intake_options,
    case when (select intake_ok from global_gates) then it.earliest_date end as earliest_intake_date,
    case when (select english_ok from global_gates) then coalesce(en.options,'[]'::jsonb) else '[]'::jsonb end as english_requirement_options,
    case when (select scholarship_ok from global_gates) then coalesce(sc.options,'[]'::jsonb) else '[]'::jsonb end as scholarship_options,
    concat_ws(' ',
      case when (select intake_ok from global_gates) then it.semantic_text end,
      case when (select english_ok from global_gates) then en.semantic_text end,
      case when (select scholarship_ok from global_gates) then sc.semantic_text end
    ) as enrichment_semantic_text
  from search.course_documents d
  left join lateral (
    select f.id fee_id,f.amount,f.currency_code,f.basis
    from catalogue.course_fees f join pipeline.sources s on s.id=f.source_id
    where f.course_id=d.course_id and f.status='active' and f.audience in ('international','all')
      and f.fee_type='tuition' and f.basis='registered_total_course'
      and s.label='CRICOS Providers, Courses and Locations'
    order by f.updated_at desc nulls last,f.id limit 1
  ) rf on true
  left join lateral (
    select count(*) option_count,
      min(f.amount) filter(where f.basis in ('annual','indicative_annual')) annual_amount,
      min(f.currency_code) filter(where f.basis in ('annual','indicative_annual')) annual_currency,
      jsonb_agg(jsonb_build_object('fee_year',f.fee_year,'amount',f.amount,'currency',trim(f.currency_code),'basis',f.basis,'load_basis',f.load_basis,'campus_id',f.campus_id,'valid_from',f.valid_from,'valid_to',f.valid_to,'last_verified_at',f.last_verified_at) order by f.fee_year desc nulls last,f.basis,f.amount,f.id) options
    from catalogue.course_fees f
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='provider_current_tuition' and sg.source_id=f.source_id and sg.gate_status='approved'
    where f.course_id=d.course_id and f.status='active' and f.audience in ('international','all') and f.fee_type='provider_current_tuition'
      and (f.valid_from is null or f.valid_from<=current_date) and (f.valid_to is null or f.valid_to>=current_date)
  ) pf on true
  left join lateral (
    select l.url
    from catalogue.course_links l
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='official_course_url' and sg.source_id=l.source_id and sg.gate_status='approved'
    where l.course_id=d.course_id and l.status='active'
      and (l.valid_from is null or l.valid_from<=current_date) and (l.valid_to is null or l.valid_to>=current_date)
    order by l.is_primary desc,l.last_verified_at desc nulls last,l.updated_at desc nulls last,l.id limit 1
  ) lk on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('year',i.intake_year,'label',i.intake_label,'start_date',i.start_date,'application_deadline',i.application_deadline,'campus_id',i.campus_id) order by i.start_date nulls last,i.intake_year,i.intake_label,i.id) options,
      min(i.start_date) filter(where i.start_date>=current_date) earliest_date,
      string_agg(distinct concat_ws(' ',i.intake_year::text,i.intake_label), ' ' order by concat_ws(' ',i.intake_year::text,i.intake_label)) semantic_text
    from catalogue.course_intakes i
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='course_intake' and sg.source_id=i.source_id and sg.gate_status='approved'
    where i.course_id=d.course_id and i.status='active'
  ) it on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('test_code',t.code,'test_name',t.name,'overall_score',er.overall_score,'component_scores',er.component_scores,'notes',er.notes,'valid_from',er.valid_from,'valid_to',er.valid_to,'last_verified_at',er.last_verified_at) order by t.code,er.overall_score,er.id) options,
      string_agg(distinct concat_ws(' ',t.name,t.code,er.overall_score::text), ' ' order by concat_ws(' ',t.name,t.code,er.overall_score::text)) semantic_text
    from catalogue.course_english_requirements er
    join ref.english_tests t on t.id=er.english_test_id
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='course_english' and sg.source_id=er.source_id and sg.gate_status='approved'
    where er.course_id=d.course_id and er.status='active'
      and (er.valid_from is null or er.valid_from<=current_date) and (er.valid_to is null or er.valid_to>=current_date)
  ) en on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('scholarship_key',s.stable_key,'name',s.name,'award_value_text',scholarship.value_label(s.id),'academic_year',s.academic_year,'application_close_date',s.application_close_date,'source_url',s.source_url,
             'audience',s.audience,'nationalities',s.nationalities,'is_maximum',s.award_value_is_maximum,
             'saving_per_year',fc.scholarship_saving_amount,'saving_currency',fc.currency_code,'saving_basis',fc.fee_basis)
             order by fc.scholarship_saving_amount desc nulls last, s.name) options,
      string_agg(s.name,' ' order by s.name) semantic_text
    from scholarship.course_mappings cm join scholarship.scholarships s on s.id=cm.scholarship_id
    left join scholarship.course_financial_calculations fc on fc.mapping_id=cm.id and fc.calculation_status='calculated'
    where cm.course_id=d.course_id and cm.mapping_state='mapped'
      and s.lifecycle_status='active' and s.publication_status in ('published','internal')
      and s.audience in ('international','international_and_domestic')
  ) sc on true
  where d.course_id = any(p_course_ids);

  alter table cf_search_enrichment_stage add column enrichment_content_hash text;
  update cf_search_enrichment_stage s set enrichment_content_hash=encode(extensions.digest(jsonb_build_object(
    'regulatory_state',s.regulatory_tuition_state,'regulatory_amount',s.regulatory_tuition_amount,'regulatory_currency',s.regulatory_tuition_currency,'regulatory_basis',s.regulatory_tuition_basis,
    'has_provider_current_tuition',s.has_provider_current_tuition,'provider_annual_amount',s.provider_annual_tuition_amount,'provider_annual_currency',s.provider_annual_tuition_currency,'provider_options',s.provider_tuition_options,
    'official_url',s.official_course_url,'intakes',s.intake_options,'english',s.english_requirement_options,'scholarships',s.scholarship_options,'semantic_text',s.enrichment_semantic_text
  )::text,'sha256'),'hex')
  where s.course_id is not null;

  select count(*) into v_rows from cf_search_enrichment_stage;
  select count(*) into v_changed from cf_search_enrichment_stage s join search.course_documents d using(course_id) where d.enrichment_content_hash is distinct from s.enrichment_content_hash;
  select count(*) into v_unchanged from cf_search_enrichment_stage s join search.course_documents d using(course_id) where d.enrichment_content_hash is not distinct from s.enrichment_content_hash;
  select encode(extensions.digest(coalesce(string_agg(course_id::text||':'||enrichment_content_hash,'|' order by course_id::text),''),'sha256'),'hex') into v_stage_hash from cf_search_enrichment_stage;
  select jsonb_build_object(
    'regulatory_present',count(*) filter(where regulatory_tuition_state='present'),
    'regulatory_zero',count(*) filter(where regulatory_tuition_state='zero'),
    'regulatory_source_null',count(*) filter(where regulatory_tuition_state='source_null'),
    'regulatory_not_applicable',count(*) filter(where regulatory_tuition_state='not_applicable'),
    'with_provider_current_tuition',count(*) filter(where has_provider_current_tuition),
    'with_provider_annual_tuition',count(*) filter(where provider_annual_tuition_amount is not null),
    'with_official_url',count(*) filter(where official_course_url is not null),
    'with_intake',count(*) filter(where jsonb_array_length(intake_options)>0),
    'with_english',count(*) filter(where jsonb_array_length(english_requirement_options)>0),
    'with_scholarship',count(*) filter(where jsonb_array_length(scholarship_options)>0)
  ) into v_coverage from cf_search_enrichment_stage;

  if p_apply then
    update search.course_documents d set
      regulatory_tuition_state=s.regulatory_tuition_state,
      has_regulatory_tuition=s.has_regulatory_tuition,
      regulatory_tuition_amount=s.regulatory_tuition_amount,
      regulatory_tuition_currency=s.regulatory_tuition_currency,
      regulatory_tuition_basis=s.regulatory_tuition_basis,
      has_provider_current_tuition=s.has_provider_current_tuition,
      has_fee=s.has_provider_current_tuition,
      provider_annual_tuition_amount=s.provider_annual_tuition_amount,
      provider_annual_tuition_currency=s.provider_annual_tuition_currency,
      provider_tuition_options=s.provider_tuition_options,
      official_course_url=s.official_course_url,
      has_link=(s.official_course_url is not null),
      intake_options=s.intake_options,
      earliest_intake_date=s.earliest_intake_date,
      has_intake=(jsonb_array_length(s.intake_options)>0),
      english_requirement_options=s.english_requirement_options,
      has_english=(jsonb_array_length(s.english_requirement_options)>0),
      scholarship_options=s.scholarship_options,
      has_scholarship=(jsonb_array_length(s.scholarship_options)>0),
      enrichment_semantic_text=nullif(trim(s.enrichment_semantic_text),''),
      enrichment_content_hash=s.enrichment_content_hash,
      search_text=concat_ws(' ',d.course_title,d.provider_name,d.course_code,d.study_level_code,d.primary_field_name,array_to_string(d.collection_names,' '),array_to_string(d.academic_option_names,' '),d.description,nullif(trim(s.enrichment_semantic_text),'')),
      search_tsv=setweight(to_tsvector('english',coalesce(d.course_title,'')),'A') || setweight(to_tsvector('english',coalesce(d.provider_name,'')),'B') || setweight(to_tsvector('english',concat_ws(' ',coalesce(d.course_code,''),coalesce(d.study_level_code,''),coalesce(d.primary_field_name,''),coalesce(array_to_string(d.collection_names,' '),''),coalesce(array_to_string(d.academic_option_names,' '),''))),'B') || setweight(to_tsvector('english',concat_ws(' ',coalesce(d.description,''),coalesce(s.enrichment_semantic_text,''))),'C'),
      semantic_content_hash=encode(extensions.digest(jsonb_build_object('base',d.course_stable_key,'provider',d.provider_name,'title',d.course_title,'code',d.course_code,'level',d.study_level_code,'field',d.primary_field_code,'collections',d.collection_names,'academic_options',d.academic_option_names,'description',d.description,'enrichment',nullif(trim(s.enrichment_semantic_text),''))::text,'sha256'),'hex'),
      projection_version='course-v3',
      generated_at=now(),
      updated_at=now()
    from cf_search_enrichment_stage s where d.course_id=s.course_id;
  end if;

  return jsonb_build_object('projection_version','course-v3','scope','courses','requested_courses',coalesce(cardinality(p_course_ids),0),'apply',p_apply,'rows',v_rows,'changed',v_changed,'unchanged',v_unchanged,'stage_hash',v_stage_hash,'coverage',v_coverage);
end
$$;


ALTER FUNCTION "search"."refresh_course_enrichment_core_scoped_v1"("p_course_ids" "uuid"[], "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_enrichment_core_v1"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'catalogue', 'scholarship', 'pipeline', 'ref', 'extensions', 'pg_temp'
    AS $$
declare
  v_rows bigint;
  v_changed bigint;
  v_unchanged bigint;
  v_stage_hash text;
  v_coverage jsonb;
begin
  drop table if exists pg_temp.cf_search_enrichment_stage;
  create temp table cf_search_enrichment_stage on commit drop as
  with global_gates as (
    select
      bool_or(domain_code='regulatory_tuition' and gate_status='approved') regulatory_ok,
      bool_or(domain_code='provider_current_tuition' and gate_status='approved') provider_fee_ok,
      bool_or(domain_code='official_course_url' and gate_status='approved') link_ok,
      bool_or(domain_code='course_intake' and gate_status='approved') intake_ok,
      bool_or(domain_code='course_english' and gate_status='approved') english_ok,
      bool_or(domain_code='scholarship' and gate_status='approved') scholarship_ok
    from search.enrichment_gates where projection_code='courses'
  )
  select d.course_id,
    case
      when d.country_code='NZ' then 'not_applicable'
      when not (select regulatory_ok from global_gates) then 'not_admitted'
      when rf.fee_id is null then 'source_null'
      when rf.amount=0 then 'zero'
      else 'present'
    end as regulatory_tuition_state,
    ((select regulatory_ok from global_gates) and rf.fee_id is not null) as has_regulatory_tuition,
    case when (select regulatory_ok from global_gates) then rf.amount end as regulatory_tuition_amount,
    case when (select regulatory_ok from global_gates) then rf.currency_code end as regulatory_tuition_currency,
    case when (select regulatory_ok from global_gates) then rf.basis end as regulatory_tuition_basis,
    ((select provider_fee_ok from global_gates) and pf.option_count>0) as has_provider_current_tuition,
    case when (select provider_fee_ok from global_gates) then pf.annual_amount end as provider_annual_tuition_amount,
    case when (select provider_fee_ok from global_gates) then pf.annual_currency end as provider_annual_tuition_currency,
    case when (select provider_fee_ok from global_gates) then coalesce(pf.options,'[]'::jsonb) else '[]'::jsonb end as provider_tuition_options,
    case when (select link_ok from global_gates) then lk.url end as official_course_url,
    case when (select intake_ok from global_gates) then coalesce(it.options,'[]'::jsonb) else '[]'::jsonb end as intake_options,
    case when (select intake_ok from global_gates) then it.earliest_date end as earliest_intake_date,
    case when (select english_ok from global_gates) then coalesce(en.options,'[]'::jsonb) else '[]'::jsonb end as english_requirement_options,
    case when (select scholarship_ok from global_gates) then coalesce(sc.options,'[]'::jsonb) else '[]'::jsonb end as scholarship_options,
    concat_ws(' ',
      case when (select intake_ok from global_gates) then it.semantic_text end,
      case when (select english_ok from global_gates) then en.semantic_text end,
      case when (select scholarship_ok from global_gates) then sc.semantic_text end
    ) as enrichment_semantic_text
  from search.course_documents d
  left join lateral (
    select f.id fee_id,f.amount,f.currency_code,f.basis
    from catalogue.course_fees f join pipeline.sources s on s.id=f.source_id
    where f.course_id=d.course_id and f.status='active' and f.audience in ('international','all')
      and f.fee_type='tuition' and f.basis='registered_total_course'
      and s.label='CRICOS Providers, Courses and Locations'
    order by f.updated_at desc nulls last,f.id limit 1
  ) rf on true
  left join lateral (
    select count(*) option_count,
      min(f.amount) filter(where f.basis in ('annual','indicative_annual')) annual_amount,
      min(f.currency_code) filter(where f.basis in ('annual','indicative_annual')) annual_currency,
      jsonb_agg(jsonb_build_object('fee_year',f.fee_year,'amount',f.amount,'currency',trim(f.currency_code),'basis',f.basis,'load_basis',f.load_basis,'campus_id',f.campus_id,'valid_from',f.valid_from,'valid_to',f.valid_to,'last_verified_at',f.last_verified_at) order by f.fee_year desc nulls last,f.basis,f.amount,f.id) options
    from catalogue.course_fees f
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='provider_current_tuition' and sg.source_id=f.source_id and sg.gate_status='approved'
    where f.course_id=d.course_id and f.status='active' and f.audience in ('international','all') and f.fee_type='provider_current_tuition'
      and (f.valid_from is null or f.valid_from<=current_date) and (f.valid_to is null or f.valid_to>=current_date)
  ) pf on true
  left join lateral (
    select l.url
    from catalogue.course_links l
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='official_course_url' and sg.source_id=l.source_id and sg.gate_status='approved'
    where l.course_id=d.course_id and l.status='active'
      and (l.valid_from is null or l.valid_from<=current_date) and (l.valid_to is null or l.valid_to>=current_date)
    order by l.is_primary desc,l.last_verified_at desc nulls last,l.updated_at desc nulls last,l.id limit 1
  ) lk on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('year',i.intake_year,'label',i.intake_label,'start_date',i.start_date,'application_deadline',i.application_deadline,'campus_id',i.campus_id) order by i.start_date nulls last,i.intake_year,i.intake_label,i.id) options,
      min(i.start_date) filter(where i.start_date>=current_date) earliest_date,
      string_agg(distinct concat_ws(' ',i.intake_year::text,i.intake_label), ' ' order by concat_ws(' ',i.intake_year::text,i.intake_label)) semantic_text
    from catalogue.course_intakes i
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='course_intake' and sg.source_id=i.source_id and sg.gate_status='approved'
    where i.course_id=d.course_id and i.status='active'
  ) it on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('test_code',t.code,'test_name',t.name,'overall_score',er.overall_score,'component_scores',er.component_scores,'notes',er.notes,'valid_from',er.valid_from,'valid_to',er.valid_to,'last_verified_at',er.last_verified_at) order by t.code,er.overall_score,er.id) options,
      string_agg(distinct concat_ws(' ',t.name,t.code,er.overall_score::text), ' ' order by concat_ws(' ',t.name,t.code,er.overall_score::text)) semantic_text
    from catalogue.course_english_requirements er
    join ref.english_tests t on t.id=er.english_test_id
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='course_english' and sg.source_id=er.source_id and sg.gate_status='approved'
    where er.course_id=d.course_id and er.status='active'
      and (er.valid_from is null or er.valid_from<=current_date) and (er.valid_to is null or er.valid_to>=current_date)
  ) en on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('scholarship_key',s.stable_key,'name',s.name,'award_value_text',scholarship.value_label(s.id),'academic_year',s.academic_year,'application_close_date',s.application_close_date,'source_url',s.source_url,
             'audience',s.audience,'nationalities',s.nationalities,'is_maximum',s.award_value_is_maximum,
             'saving_per_year',fc.scholarship_saving_amount,'saving_currency',fc.currency_code,'saving_basis',fc.fee_basis)
             order by fc.scholarship_saving_amount desc nulls last, s.name) options,
      string_agg(s.name,' ' order by s.name) semantic_text
    from scholarship.course_mappings cm join scholarship.scholarships s on s.id=cm.scholarship_id
    left join scholarship.course_financial_calculations fc on fc.mapping_id=cm.id and fc.calculation_status='calculated'
    where cm.course_id=d.course_id and cm.mapping_state='mapped'
      and s.lifecycle_status='active' and s.publication_status in ('published','internal')
      and s.audience in ('international','international_and_domestic')
  ) sc on true;

  alter table cf_search_enrichment_stage add column enrichment_content_hash text;
  update cf_search_enrichment_stage s set enrichment_content_hash=encode(extensions.digest(jsonb_build_object(
    'regulatory_state',s.regulatory_tuition_state,'regulatory_amount',s.regulatory_tuition_amount,'regulatory_currency',s.regulatory_tuition_currency,'regulatory_basis',s.regulatory_tuition_basis,
    'has_provider_current_tuition',s.has_provider_current_tuition,'provider_annual_amount',s.provider_annual_tuition_amount,'provider_annual_currency',s.provider_annual_tuition_currency,'provider_options',s.provider_tuition_options,
    'official_url',s.official_course_url,'intakes',s.intake_options,'english',s.english_requirement_options,'scholarships',s.scholarship_options,'semantic_text',s.enrichment_semantic_text
  )::text,'sha256'),'hex') where true;

  select count(*) into v_rows from cf_search_enrichment_stage;
  select count(*) into v_changed from cf_search_enrichment_stage s join search.course_documents d using(course_id) where d.enrichment_content_hash is distinct from s.enrichment_content_hash;
  select count(*) into v_unchanged from cf_search_enrichment_stage s join search.course_documents d using(course_id) where d.enrichment_content_hash is not distinct from s.enrichment_content_hash;
  select encode(extensions.digest(coalesce(string_agg(course_id::text||':'||enrichment_content_hash,'|' order by course_id::text),''),'sha256'),'hex') into v_stage_hash from cf_search_enrichment_stage;
  select jsonb_build_object(
    'regulatory_present',count(*) filter(where regulatory_tuition_state='present'),
    'regulatory_zero',count(*) filter(where regulatory_tuition_state='zero'),
    'regulatory_source_null',count(*) filter(where regulatory_tuition_state='source_null'),
    'regulatory_not_applicable',count(*) filter(where regulatory_tuition_state='not_applicable'),
    'with_provider_current_tuition',count(*) filter(where has_provider_current_tuition),
    'with_provider_annual_tuition',count(*) filter(where provider_annual_tuition_amount is not null),
    'with_official_url',count(*) filter(where official_course_url is not null),
    'with_intake',count(*) filter(where jsonb_array_length(intake_options)>0),
    'with_english',count(*) filter(where jsonb_array_length(english_requirement_options)>0),
    'with_scholarship',count(*) filter(where jsonb_array_length(scholarship_options)>0)
  ) into v_coverage from cf_search_enrichment_stage;

  if p_apply then
    update search.course_documents d set
      regulatory_tuition_state=s.regulatory_tuition_state,
      has_regulatory_tuition=s.has_regulatory_tuition,
      regulatory_tuition_amount=s.regulatory_tuition_amount,
      regulatory_tuition_currency=s.regulatory_tuition_currency,
      regulatory_tuition_basis=s.regulatory_tuition_basis,
      has_provider_current_tuition=s.has_provider_current_tuition,
      has_fee=s.has_provider_current_tuition,
      provider_annual_tuition_amount=s.provider_annual_tuition_amount,
      provider_annual_tuition_currency=s.provider_annual_tuition_currency,
      provider_tuition_options=s.provider_tuition_options,
      official_course_url=s.official_course_url,
      has_link=(s.official_course_url is not null),
      intake_options=s.intake_options,
      earliest_intake_date=s.earliest_intake_date,
      has_intake=(jsonb_array_length(s.intake_options)>0),
      english_requirement_options=s.english_requirement_options,
      has_english=(jsonb_array_length(s.english_requirement_options)>0),
      scholarship_options=s.scholarship_options,
      has_scholarship=(jsonb_array_length(s.scholarship_options)>0),
      enrichment_semantic_text=nullif(trim(s.enrichment_semantic_text),''),
      enrichment_content_hash=s.enrichment_content_hash,
      search_text=concat_ws(' ',d.course_title,d.provider_name,d.course_code,d.study_level_code,d.primary_field_name,array_to_string(d.collection_names,' '),array_to_string(d.academic_option_names,' '),d.description,nullif(trim(s.enrichment_semantic_text),'')),
      search_tsv=setweight(to_tsvector('english',coalesce(d.course_title,'')),'A') || setweight(to_tsvector('english',coalesce(d.provider_name,'')),'B') || setweight(to_tsvector('english',concat_ws(' ',coalesce(d.course_code,''),coalesce(d.study_level_code,''),coalesce(d.primary_field_name,''),coalesce(array_to_string(d.collection_names,' '),''),coalesce(array_to_string(d.academic_option_names,' '),''))),'B') || setweight(to_tsvector('english',concat_ws(' ',coalesce(d.description,''),coalesce(s.enrichment_semantic_text,''))),'C'),
      semantic_content_hash=encode(extensions.digest(jsonb_build_object('base',d.course_stable_key,'provider',d.provider_name,'title',d.course_title,'code',d.course_code,'level',d.study_level_code,'field',d.primary_field_code,'collections',d.collection_names,'academic_options',d.academic_option_names,'description',d.description,'enrichment',nullif(trim(s.enrichment_semantic_text),''))::text,'sha256'),'hex'),
      projection_version='course-v3',
      generated_at=now(),
      updated_at=now()
    from cf_search_enrichment_stage s where d.course_id=s.course_id and (d.enrichment_content_hash is distinct from s.enrichment_content_hash or d.projection_version is distinct from 'course-v3' or d.updated_at = now());
  end if;

  return jsonb_build_object('projection_version','course-v3','apply',p_apply,'rows',v_rows,'changed',v_changed,'unchanged',v_unchanged,'stage_hash',v_stage_hash,'coverage',v_coverage);
end
$$;


ALTER FUNCTION "search"."refresh_course_enrichment_core_v1"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_enrichment_scoped_v1"("p_course_ids" "uuid"[], "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'catalogue', 'scholarship', 'pipeline', 'ref', 'extensions', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if p_course_ids is null or cardinality(p_course_ids) = 0 then
    return jsonb_build_object('projection_version','course-v3','scope','courses','requested_courses',0,'apply',p_apply,'rows',0,'changed',0,'unchanged',0);
  end if;
  v_result := search.refresh_course_enrichment_core_scoped_v1(p_course_ids, p_apply);
  if p_apply then
    update search.course_documents d
    set semantic_content_hash=encode(extensions.digest(jsonb_build_object(
      'course',d.course_stable_key,
      'provider',d.provider_name,
      'title',d.course_title,
      'code',d.course_code,
      'level',d.study_level_code,
      'field',d.primary_field_code,
      'collections',d.collection_names,
      'academic_options',d.academic_option_names,
      'description',d.description
    )::text,'sha256'),'hex')
    where d.enrichment_semantic_text is null and d.course_id = any(p_course_ids);
  end if;
  return v_result;
end
$$;


ALTER FUNCTION "search"."refresh_course_enrichment_scoped_v1"("p_course_ids" "uuid"[], "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_enrichment_v1"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'extensions', 'pg_temp'
    AS $$
declare
  v_result jsonb;
begin
  v_result:=search.refresh_course_enrichment_core_v1(p_apply);
  if p_apply then
    update search.course_documents d
    set semantic_content_hash=encode(extensions.digest(jsonb_build_object(
      'course',d.course_stable_key,
      'provider',d.provider_name,
      'title',d.course_title,
      'code',d.course_code,
      'level',d.study_level_code,
      'field',d.primary_field_code,
      'collections',d.collection_names,
      'academic_options',d.academic_option_names,
      'description',d.description
    )::text,'sha256'),'hex')
    where d.enrichment_semantic_text is null;
  end if;
  return v_result;
end
$$;


ALTER FUNCTION "search"."refresh_course_enrichment_v1"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_autobuild_state_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'adapter', (select case when not u.enabled then 'off' when u.admit then 'admitting' else 'testing' end from pipeline.uni_adapters u where u.provider_id = p_provider_id),
    'admit_fields', (select u.admit_fields from pipeline.uni_adapters u where u.provider_id = p_provider_id),
    'build', (select jsonb_build_object('id', b.id, 'status', b.status, 'note', b.note, 'error', b.error, 'result', b.result, 'created_at', b.created_at, 'updated_at', b.updated_at)
                from pipeline.adapter_autobuilds b where b.provider_id = p_provider_id order by b.created_at desc limit 1))
$$;


ALTER FUNCTION "security"."adapter_autobuild_state_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_builder_budget"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with today as (select (now() at time zone 'Australia/Melbourne')::date d),
  rounds as (select (p->>'cost')::numeric cost from pipeline.uni_adapter_drafts dr cross join lateral jsonb_array_elements(dr.proposals) p, today
             where ((p->>'at')::timestamptz at time zone 'Australia/Melbourne')::date = today.d)
  select jsonb_build_object('used_usd', coalesce((select sum(cost) from rounds), 0), 'proposals', (select count(*) from rounds),
                            'limit_usd', coalesce((security.firecrawl_setting('builder_ai_daily_usd') #>> '{}')::numeric, 0.5),
                            'limit_proposals', coalesce((security.firecrawl_setting('builder_proposals_per_day') #>> '{}')::int, 30),
                            'model', security.firecrawl_setting('builder_model') #>> '{}')
$$;


ALTER FUNCTION "security"."adapter_builder_budget"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_builder_model_for_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (select jsonb_build_object('code', m.code, 'model', m.model_identifier, 'chosen', true, 'set_at', a.set_at, 'reason', a.reason)
       from pipeline.uni_adapter_models a join pipeline.layer3_model_profiles m on m.code = a.profile_code
      where a.provider_id = p_provider_id and m.enabled and not m.paused and m.retired_at is null),
    jsonb_build_object('code', security.firecrawl_setting('builder_model_profile') #>> '{}', 'model', security.firecrawl_setting('builder_model') #>> '{}', 'chosen', false))
$$;


ALTER FUNCTION "security"."adapter_builder_model_for_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_builder_models_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('code', m.code, 'model', m.model_identifier, 'max_output_tokens', m.max_output_tokens) order by m.model_identifier), '[]'::jsonb)
    from pipeline.layer3_model_profiles m
   where m.enabled and not m.paused and m.retired_at is null and m.aggregator_provider = 'openrouter'
     and 'provider_intake_validation' = any(m.allowed_task_classes)
$$;


ALTER FUNCTION "security"."adapter_builder_models_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_fee_year_setting"("p_reading" "jsonb") RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  select case when coalesce(p_reading->>'fee_year', '') ~ '^20[2-9][0-9]$'
               and (p_reading->>'fee_year')::int between extract(year from now() at time zone 'Australia/Melbourne')::int
                                                     and extract(year from now() at time zone 'Australia/Melbourne')::int + 1
              then (p_reading->>'fee_year')::int end
$_$;


ALTER FUNCTION "security"."adapter_fee_year_setting"("p_reading" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_overwrite_v1"("p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v_src uuid; v_ok int := 0; v_err int := 0; v_last text; v_courses uuid[] := '{}'; v_payload jsonb; v_itk text[]; v_ielts numeric; v_band numeric; v_fee numeric; v_fy int; v_cur text; v_mode_n int := 0;
begin
  for r in
    select pg.course_id, pg.provider_id, pg.url, pg.evidence_id, e.content_hash, pg.candidates c, pg.identity_basis ib, u.admit_fields af, u.reading rd, co.delivery_mode cur_mode, coalesce(security.delivery_mode_from_text(pg.candidates->'adapter_extra'->>'mode'), security.delivery_mode_from_location(coalesce(pg.candidates->'adapter_extra'->>'location', pg.candidates->'adapter_extra'->>'campus'))) new_mode,
           (select pr.registration_code from catalogue.provider_registrations pr where pr.provider_id = pg.provider_id and lower(pr.registration_scheme) = 'cricos' and coalesce(pr.status, 'active') not in ('inactive', 'cancelled', 'archived') order by pr.checked_at desc nulls last limit 1) pc,
           (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = pg.course_id and lower(cr.scheme) = 'cricos' limit 1) cc,
           (select array_agg(distinct i.intake_label order by i.intake_label) from catalogue.course_intakes i where i.course_id = pg.course_id and i.status = 'active') cur_itk,
           (select r2.overall_score from catalogue.course_english_requirements r2 join ref.english_tests t on t.id = r2.english_test_id where r2.course_id = pg.course_id and t.code = 'IELTS' and coalesce(r2.status, 'active') = 'active' limit 1) cur_ielts,
           (select f.amount from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' order by f.fee_year desc nulls last limit 1) cur_fee,
           u.admit adm,
           (select (select array_agg(distinct z::int order by z::int) from jsonb_array_elements_text(l.cv->'months') z)
                   = (select array_agg(distinct extract(month from to_date(i.intake_label, 'Month'))::int order by extract(month from to_date(i.intake_label, 'Month'))::int)
                        from catalogue.course_intakes i where i.course_id = pg.course_id and i.status = 'active' and i.intake_label ~ '^(January|February|March|April|May|June|July|August|September|October|November|December)$')
              from (select x.candidate_value cv from pipeline.layer3_interpretations x where x.entity_type = 'course' and x.entity_id = pg.course_id and x.status = 'validated'
                       and x.task_class = 'provider_intake_validation' and jsonb_typeof(x.candidate_value->'months') = 'array' order by x.created_at desc limit 1) l) r5_itk,
           (select (select (t->>'overall')::numeric from jsonb_array_elements(l.cv->'tests') t where t->>'test' = 'IELTS' limit 1)
                   = (select r3.overall_score from catalogue.course_english_requirements r3 join ref.english_tests t3 on t3.id = r3.english_test_id where r3.course_id = pg.course_id and t3.code = 'IELTS' and coalesce(r3.status, 'active') = 'active' limit 1)
              from (select x.candidate_value cv from pipeline.layer3_interpretations x where x.entity_type = 'course' and x.entity_id = pg.course_id and x.status = 'validated'
                       and x.task_class = 'provider_english_validation' and jsonb_typeof(x.candidate_value->'tests') = 'array' order by x.created_at desc limit 1) l) r5_eng,
           (select abs((l.cv->>'amount')::numeric - (select f.amount from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' order by f.fee_year desc nulls last limit 1))
                   <= 0.01 * (l.cv->>'amount')::numeric
              from (select x.candidate_value cv from pipeline.layer3_interpretations x where x.entity_type = 'course' and x.entity_id = pg.course_id and x.status = 'validated'
                       and x.task_class = 'provider_current_tuition_validation' and (x.candidate_value->>'amount') ~ '^[0-9]+(\.[0-9]+)?$' order by x.created_at desc limit 1) l) r5_fee
      from pipeline.coverage_course_pages pg
      join pipeline.evidence_artifacts e on e.id = pg.evidence_id
      join catalogue.courses co on co.id = pg.course_id and co.lifecycle_status = 'active'
      join pipeline.uni_adapters u on u.provider_id = pg.provider_id and u.enabled
       and (u.admit or exists (select 1 from pipeline.layer3_interpretations l3 where l3.entity_type = 'course' and l3.entity_id = pg.course_id and l3.status = 'validated'
                                and l3.task_class in ('provider_intake_validation', 'provider_english_validation', 'provider_current_tuition_validation')))
     where pg.read_status = 'read' and pg.identity_basis is not null
       and (pg.candidates->>'intakes_by' = 'adapter' or pg.candidates->>'english_by' = 'adapter' or pg.candidates->>'fee_by' = 'adapter' or pg.candidates->'adapter_extra' ? 'mode' or pg.candidates->'adapter_extra' ? 'campus' or pg.candidates->'adapter_extra' ? 'location')
       and security.coverage_identity_allowed(pg.provider_id, pg.identity_basis, null)
       and not security.layer4_entity_or_parent_blocked('course', pg.course_id, 'operational')
  loop
    exit when v_ok >= greatest(1, least(coalesce(p_limit, 200), 1000));
    v_payload := '{}'::jsonb;
    v_itk := (select array_agg(distinct m order by m) from jsonb_array_elements_text(coalesce(r.c->'intakes', '[]'::jsonb)) m);
    if r.c->>'intakes_by' = 'adapter' and v_itk is not null and r.cur_itk is distinct from v_itk
       and security.coverage_identity_allowed(r.provider_id, r.ib, 'intakes') and (('intakes' = any (r.af) and r.adm) or coalesce(r.r5_itk, false)) and not security.uni_adapter_excluded(r.course_id, 'intakes')
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('intakes', 'intake')) then
      v_payload := v_payload || jsonb_build_object('intakes', (select jsonb_agg(jsonb_build_object('intake_label', m, 'source_intake_key', lower(coalesce(r.cc, r.course_id::text)) || ':current:' || lower(m))) from unnest(v_itk) m));
    end if;
    v_ielts := nullif(r.c->'english'->>'ielts_overall', '')::numeric;
    v_band := nullif(r.c->'english'->>'ielts_min_band', '')::numeric;
    if r.c->>'english_by' = 'adapter' and v_ielts is not null and r.cur_ielts is distinct from v_ielts
       and security.coverage_identity_allowed(r.provider_id, r.ib, 'english') and (('english' = any (r.af) and r.adm) or coalesce(r.r5_eng, false)) and not security.uni_adapter_excluded(r.course_id, 'english')
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('english', 'english_requirements')) then
      v_payload := v_payload || jsonb_build_object('english_requirements', jsonb_build_array(jsonb_build_object('test_code', 'IELTS', 'overall_score', v_ielts,
                      'component_scores', case when v_band is null then '{}'::jsonb else jsonb_build_object('listening', v_band, 'reading', v_band, 'writing', v_band, 'speaking', v_band) end,
                      'notes', 'University adapter reading of the course page')));
    end if;
    -- v0.17 (Platform Admin 23:41, decision 4): the international annual fee the adapter read is admitted too
    v_fee := nullif(r.c->'fee'->>'value', '')::numeric;
    v_fy := coalesce(nullif(r.c->'fee'->>'fee_year', '')::int, security.adapter_fee_year_setting(r.rd), extract(year from now() at time zone 'Australia/Melbourne')::int);
    v_cur := coalesce(nullif(r.c->'fee'->>'currency', ''), case security.coverage_country(r.provider_id) when 'NZ' then 'NZD' when 'CA' then 'CAD' else 'AUD' end);
    if r.c->>'fee_by' = 'adapter' and v_fee is not null and v_fee between 1000 and 500000 and (select f.amount from catalogue.course_fees f where f.course_id = r.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and coalesce(f.fee_year, 0) = coalesce(v_fy, 0) order by f.updated_at desc nulls last limit 1) is distinct from v_fee
       and (('fee' = any (r.af) and r.adm) or coalesce(r.r5_fee, false)) and not security.uni_adapter_excluded(r.course_id, 'fee') and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('tuition', 'fee', 'fees')) then
      v_payload := v_payload || jsonb_build_object('fee_amount', v_fee, 'fee_year', v_fy, 'currency_code', v_cur, 'fee_basis', 'annual', 'audience', 'international',
                     'fee_notes', 'University adapter reading of the course page (international annual fee)',
                     'fee_key', lower(coalesce(r.cc, r.course_id::text)) || ':international:' || coalesce(v_fy::text, 'current') || ':annual');
    end if;
    -- 5 Oct (Platform Admin 11:48): delivery read from the international view of the course page
    if r.new_mode is not null and r.cur_mode is distinct from r.new_mode and ('delivery' = any (r.af) and r.adm) and not security.uni_adapter_excluded(r.course_id, 'delivery')
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('delivery_mode', 'delivery')) then
      begin
        update catalogue.courses set delivery_mode = r.new_mode, updated_at = now() where id = r.course_id;
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url) values (r.course_id, r.provider_id, 'delivery', to_jsonb(r.cur_mode), to_jsonb(r.new_mode), r.evidence_id, r.url);
        v_mode_n := v_mode_n + 1; v_courses := v_courses || r.course_id;
      exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
      end;
    end if;
    continue when v_payload = '{}'::jsonb;
    begin
      v_src := security.coverage_sweep_source(r.provider_id);
      insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
        select 'courses', d, v_src, 'approved', 'CF-CHG-20260915-247, Decision 253, Platform Admin 4 Oct 2026 22:43 (adapter readings replace held values)', now(), now(), now()
        from unnest(array_remove(array[case when v_payload ? 'intakes' then 'course_intake' end, case when v_payload ? 'english_requirements' then 'course_english' end, case when v_payload ? 'fee_amount' then 'provider_current_tuition' end], null)) d
        where not exists (select 1 from search.enrichment_source_gates g where g.projection_code = 'courses' and g.domain_code = d and g.source_id = v_src);
      if v_payload ? 'intakes' then
        update catalogue.course_intakes set status = 'withdrawn' where course_id = r.course_id and status = 'active' and source_id is not null and intake_label <> all (v_itk);
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url) values (r.course_id, r.provider_id, 'intakes', to_jsonb(r.cur_itk), to_jsonb(v_itk), r.evidence_id, r.url);
      end if;
      if v_payload ? 'english_requirements' then
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url) values (r.course_id, r.provider_id, 'english_ielts', to_jsonb(r.cur_ielts), to_jsonb(v_ielts), r.evidence_id, r.url);
      end if;
      if v_payload ? 'fee_amount' then
        update catalogue.course_fees set status = 'superseded', updated_at = now() where course_id = r.course_id and status = 'active' and fee_type = 'provider_current_tuition' and audience = 'international' and source_id is not null and coalesce(fee_year, 0) = coalesce(v_fy, 0) and amount <> v_fee;
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url) values (r.course_id, r.provider_id, 'fee', to_jsonb(r.cur_fee), jsonb_build_object('amount', v_fee, 'year', v_fy, 'currency', v_cur), r.evidence_id, r.url);
      end if;
      if r.pc is null or r.cc is null then
        perform security.coverage_apply_course_v1(r.course_id, v_src, r.evidence_id, r.url, r.content_hash, v_payload);
      else
        perform public.svc_coursefacts_apply_record(v_src, r.evidence_id, r.pc, r.cc, 'coverage:' || r.course_id, r.url, r.content_hash, v_payload, true);
      end if;
      update pipeline.layer4_review_items set status = 'superseded', decided_at = now() where entity_type = 'course' and entity_id = r.course_id and status = 'pending' and field_code in (case when v_payload ? 'intakes' then 'course_intake' end, case when v_payload ? 'english_requirements' then 'course_english' end, case when v_payload ? 'fee_amount' then 'course_tuition' end);
      v_ok := v_ok + 1; v_courses := v_courses || r.course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if cardinality(v_courses) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;
  return jsonb_build_object('delivery', v_mode_n, 'replaced', v_ok, 'errors', v_err, 'last_error', v_last);
end $_$;


ALTER FUNCTION "security"."adapter_overwrite_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_qualify_one_v1"("p_provider_id" "uuid", "p_min_read" numeric, "p_min_agree" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_pages int; v_fields jsonb := '{}'::jsonb; v_pass text[] := '{}'; r record; v_f jsonb; v_share numeric; v_agree_share numeric; v_ok boolean; v_why text;
begin
  select count(*) into v_pages from pipeline.coverage_course_pages pg where pg.provider_id = p_provider_id and pg.read_status = 'read' and pg.identity_basis is not null;
  for r in
    with pg as (
      select pg.course_id, pg.candidates c from pipeline.coverage_course_pages pg
       where pg.provider_id = p_provider_id and pg.read_status = 'read' and pg.identity_basis is not null),
    m as (
      select 'intakes' field,
             count(*) filter (where x.rd and not x.ex) rd, count(*) filter (where x.rd and not x.ex and x.held and x.eq) ag, count(*) filter (where x.rd and not x.ex and x.held and not x.eq) df, count(*) filter (where x.rd and not x.ex and not x.held) nw, count(*) filter (where x.ex) ex, 0 un
        from (select (pg.c->>'intakes_by' = 'adapter') rd, security.uni_adapter_excluded(pg.course_id, 'intakes') ex,
                     h.itk is not null held, (h.itk = a.itk) eq
                from pg
                cross join lateral (select array_agg(distinct m order by m) itk from jsonb_array_elements_text(coalesce(pg.c->'intakes', '[]'::jsonb)) m) a
                cross join lateral (select array_agg(distinct i.intake_label order by i.intake_label) itk from catalogue.course_intakes i where i.course_id = pg.course_id and i.status = 'active') h) x
      union all
      select 'fee',
             count(*) filter (where x.rd and not x.ex), count(*) filter (where x.rd and not x.ex and x.held and x.eq), count(*) filter (where x.rd and not x.ex and x.held and not x.eq), count(*) filter (where x.rd and not x.ex and not x.held), count(*) filter (where x.ex), 0
        from (select (pg.c->>'fee_by' = 'adapter' and nullif(pg.c->'fee'->>'value', '') is not null) rd, security.uni_adapter_excluded(pg.course_id, 'fee') ex,
                     exists (select 1 from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international') held,
                     exists (select 1 from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and f.amount = nullif(pg.c->'fee'->>'value', '')::numeric) eq
                from pg) x
      union all
      select 'english',
             count(*) filter (where x.rd and not x.ex), count(*) filter (where x.rd and not x.ex and x.held and x.eq), count(*) filter (where x.rd and not x.ex and x.held and not x.eq), count(*) filter (where x.rd and not x.ex and not x.held), count(*) filter (where x.ex), 0
        from (select (pg.c->>'english_by' = 'adapter' and nullif(pg.c->'english'->>'ielts_overall', '') is not null) rd, security.uni_adapter_excluded(pg.course_id, 'english') ex,
                     h.score is not null held, (h.score = nullif(pg.c->'english'->>'ielts_overall', '')::numeric) eq
                from pg
                cross join lateral (select max(e.overall_score) score from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id and t.code = 'IELTS' where e.course_id = pg.course_id and e.status = 'active') h) x
      union all
      select 'delivery',
             count(*) filter (where x.rd and not x.ex), count(*) filter (where x.rd and not x.ex and x.held and x.eq), count(*) filter (where x.rd and not x.ex and x.held and not x.eq), count(*) filter (where x.rd and not x.ex and not x.held), count(*) filter (where x.ex), count(*) filter (where x.un and not x.ex)
        from (select (x0.mode is not null and x0.mode <> 'on_campus_and_online') rd, (x0.mode = 'on_campus_and_online') un, security.uni_adapter_excluded(pg.course_id, 'delivery') ex,
                     co.delivery_mode is not null held, (co.delivery_mode = x0.mode) eq
                from pg join catalogue.courses co on co.id = pg.course_id
                cross join lateral (select security.delivery_mode_from_text(pg.c->'adapter_extra'->>'mode') mode) x0) x)
    select * from m
  loop
    v_share := case when (v_pages - r.ex) > 0 then round(r.rd::numeric / (v_pages - r.ex), 3) else 0 end;
    v_agree_share := case when (r.ag + r.df) > 0 then round(r.ag::numeric / (r.ag + r.df), 3) else null end;
    v_ok := r.rd > 0 and v_share >= p_min_read and (v_agree_share is null or v_agree_share >= p_min_agree);
    v_why := case when r.rd = 0 then 'not read by the adapter'
                  when v_share < p_min_read then 'read on ' || r.rd || ' of ' || (v_pages - r.ex) || ' pages, under the share needed'
                  when v_agree_share is not null and v_agree_share < p_min_agree then r.df || ' of ' || (r.ag + r.df) || ' readings differ from the catalogue'
                  when r.un > 0 then 'passes, but ' || r.un || ' page(s) print a required mix the reader did not understand'
                  else 'passes' end;
    v_f := jsonb_build_object('read', r.rd, 'agree', r.ag, 'differ', r.df, 'new', r.nw, 'excluded', r.ex, 'unclear', r.un, 'read_share', v_share, 'agree_share', v_agree_share, 'pass', v_ok, 'why', v_why);
    v_fields := v_fields || jsonb_build_object(r.field, v_f);
    if v_ok then v_pass := v_pass || r.field; end if;
  end loop;
  return jsonb_build_object('pages_read', v_pages, 'fields', v_fields, 'passing', to_jsonb(v_pass));
end $$;


ALTER FUNCTION "security"."adapter_qualify_one_v1"("p_provider_id" "uuid", "p_min_read" numeric, "p_min_agree" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_shadow_found_v1"("p_task" "text", "v" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case when v is null or jsonb_typeof(v) <> 'object' then false
              when p_task = 'intake' then jsonb_typeof(v->'months') = 'array' and jsonb_array_length(v->'months') > 0
              when p_task = 'tuition' then jsonb_typeof(v->'amount') = 'number' or (v->>'amount') ~ '^[0-9]+(\.[0-9]+)?$'
              else jsonb_typeof(v->'tests') = 'array' and jsonb_array_length(v->'tests') > 0 end
$_$;


ALTER FUNCTION "security"."adapter_shadow_found_v1"("p_task" "text", "v" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_shadow_same_v1"("p_task" "text", "a" "jsonb", "b" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when a is null or b is null then null
    when p_task = 'intake' then
      coalesce((select array_agg(distinct (m)::int order by (m)::int) from jsonb_array_elements_text(a->'months') m), '{}')
      = coalesce((select array_agg(distinct (m)::int order by (m)::int) from jsonb_array_elements_text(b->'months') m), '{}')
    when p_task = 'tuition' then
      round((a->>'amount')::numeric) = round((b->>'amount')::numeric)
      and nullif(substring(a->>'fee_year' from '[0-9]{4}'), '') is not distinct from nullif(substring(b->>'fee_year' from '[0-9]{4}'), '')
      and lower(coalesce(a->>'audience', '')) = lower(coalesce(b->>'audience', ''))
    else
      coalesce((select array_agg(distinct (t->>'test') || ':' || trim_scale((t->>'overall')::numeric)::text order by (t->>'test') || ':' || trim_scale((t->>'overall')::numeric)::text) from jsonb_array_elements(a->'tests') t), '{}')
      = coalesce((select array_agg(distinct (t->>'test') || ':' || trim_scale((t->>'overall')::numeric)::text order by (t->>'test') || ':' || trim_scale((t->>'overall')::numeric)::text) from jsonb_array_elements(b->'tests') t), '{}')
  end
$$;


ALTER FUNCTION "security"."adapter_shadow_same_v1"("p_task" "text", "a" "jsonb", "b" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_shadow_summary_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with s as (select * from pipeline.adapter_shadow_settings where id = 1),
  d as (select * from pipeline.adapter_shadow_reads where status = 'done'),
  t as (
    select d.round, d.task, count(*) compared,
           count(*) filter (where d.shadow_found and d.layer3_found) both_found,
           count(*) filter (where d.agree) agree_n,
           count(*) filter (where d.shadow_found) shadow_found_n,
           count(*) filter (where d.layer3_found) layer3_found_n,
           count(*) filter (where d.shadow_found and not d.layer3_found) shadow_only,
           count(*) filter (where d.layer3_found and not d.shadow_found) layer3_only,
           round(sum(d.cost_usd), 4) shadow_cost_usd, round(sum(d.layer3_cost_usd), 4) layer3_cost_usd,
           round(avg(d.input_chars)) avg_input_chars,
           count(*) filter (where d.input_basis <> 'page') adapter_input_n
      from d group by d.round, d.task)
  select jsonb_build_object(
    'settings', (select to_jsonb(s) from s),
    'round', (select s.round from s),
    'today', (select jsonb_build_object('reads', count(*), 'cost_usd', round(coalesce(sum(cost_usd), 0), 4), 'errors', count(*) filter (where status = 'error'))
                from pipeline.adapter_shadow_reads where claimed_at >= date_trunc('day', now() at time zone 'UTC') at time zone 'UTC'),
    'fields', coalesce((select jsonb_agg(jsonb_build_object(
        'task', t.task, 'compared', t.compared, 'both_found', t.both_found, 'agree_n', t.agree_n,
        'agreement', case when t.both_found > 0 then round(t.agree_n::numeric / t.both_found, 4) end,
        'shadow_found_rate', round(t.shadow_found_n::numeric / nullif(t.compared, 0), 4),
        'layer3_found_rate', round(t.layer3_found_n::numeric / nullif(t.compared, 0), 4),
        'shadow_only', t.shadow_only, 'layer3_only', t.layer3_only,
        'shadow_cost_usd', t.shadow_cost_usd, 'layer3_cost_usd', t.layer3_cost_usd,
        'avg_input_chars', t.avg_input_chars, 'adapter_input_n', t.adapter_input_n,
        'eligible_to_retire', t.compared >= s.min_compared and t.both_found > 0
            and t.agree_n::numeric / t.both_found >= s.retire_match and t.shadow_found_n >= t.layer3_found_n) order by t.task)
      from t, s where t.round = s.round), '[]'::jsonb),
    'earlier_rounds', coalesce((select jsonb_agg(jsonb_build_object('round', t.round, 'task', t.task, 'compared', t.compared, 'both_found', t.both_found,
        'agreement', case when t.both_found > 0 then round(t.agree_n::numeric / t.both_found, 4) end,
        'shadow_found_rate', round(t.shadow_found_n::numeric / nullif(t.compared, 0), 4),
        'layer3_found_rate', round(t.layer3_found_n::numeric / nullif(t.compared, 0), 4), 'shadow_cost_usd', t.shadow_cost_usd) order by t.round, t.task)
      from t, s where t.round < s.round), '[]'::jsonb))
$$;


ALTER FUNCTION "security"."adapter_shadow_summary_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adjust_evidence_entity_link"("p_evidence_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_provider_id" "uuid", "p_delta" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin
  if p_evidence_id is null or p_entity_id is null or p_entity_type is null then return; end if;
  insert into pipeline.evidence_entity_links(evidence_id,entity_type,entity_id,provider_id,link_count,updated_at)
  values(p_evidence_id,p_entity_type,p_entity_id,p_provider_id,greatest(p_delta,0),now())
  on conflict(evidence_id,entity_type,entity_id) do update set provider_id=coalesce(excluded.provider_id,pipeline.evidence_entity_links.provider_id),link_count=greatest(0,pipeline.evidence_entity_links.link_count+p_delta),updated_at=now();
  delete from pipeline.evidence_entity_links where evidence_id=p_evidence_id and entity_type=p_entity_type and entity_id=p_entity_id and link_count=0;
end $$;


ALTER FUNCTION "security"."adjust_evidence_entity_link"("p_evidence_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_provider_id" "uuid", "p_delta" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adjust_evidence_lineage_stats"("p_evidence_id" "uuid", "p_observation_delta" bigint, "p_source_null_delta" bigint, "p_rejected_delta" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin
  if p_evidence_id is null then return; end if;
  insert into pipeline.evidence_lineage_stats(evidence_id,observation_count,source_null_count,rejected_count,updated_at)
  values(p_evidence_id,greatest(p_observation_delta,0),greatest(p_source_null_delta,0),greatest(p_rejected_delta,0),now())
  on conflict(evidence_id) do update set
    observation_count=greatest(0,pipeline.evidence_lineage_stats.observation_count+p_observation_delta),
    source_null_count=greatest(0,pipeline.evidence_lineage_stats.source_null_count+p_source_null_delta),
    rejected_count=greatest(0,pipeline.evidence_lineage_stats.rejected_count+p_rejected_delta),
    updated_at=now();
end
$$;


ALTER FUNCTION "security"."adjust_evidence_lineage_stats"("p_evidence_id" "uuid", "p_observation_delta" bigint, "p_source_null_delta" bigint, "p_rejected_delta" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."adjust_evidence_lineage_stats"("p_evidence_id" "uuid", "p_observation_delta" bigint, "p_source_null_delta" bigint, "p_rejected_delta" bigint) IS 'Internal CF-241 Evidence lineage counter mutator. Direct browser execution revoked; maintained through governed trigger path only.';



CREATE OR REPLACE FUNCTION "security"."admin_a15_acceptance_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref', 'search', 'publishing', 'public', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_metrics jsonb;
  v_key_contacts jsonb;
  v_watch jsonb;
  v_security jsonb;
  v_authority jsonb;
  v_ok boolean;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;

  v_metrics:=jsonb_build_object(
    'profile_total',(select count(*) from pipeline.provider_contact_profiles),
    'profile_au',(select count(*) from pipeline.provider_contact_profiles p join ref.countries c on c.id=p.country_id where c.iso_alpha2='AU'),
    'profile_nz',(select count(*) from pipeline.provider_contact_profiles p join ref.countries c on c.id=p.country_id where c.iso_alpha2='NZ'),
    'profile_success',(select count(*) from pipeline.provider_contact_profiles where last_success_at is not null and last_error is null),
    'profile_errors',(select count(*) from pipeline.provider_contact_profiles where last_error is not null),
    'current_contacts',(select count(*) from pipeline.provider_contact_observations where is_current and verification_state<>'rejected'),
    'contact_providers',(select count(distinct provider_id) from pipeline.provider_contact_observations where is_current and verification_state<>'rejected'),
    'territory_contacts',(select count(*) from pipeline.provider_contact_observations where is_current and verification_state<>'rejected' and nullif(trim(territory_text),'') is not null),
    'rejected_contacts',(select count(*) from pipeline.provider_contact_observations where verification_state='rejected'),
    'email_contacts',(select count(*) from pipeline.provider_contact_observations where is_current and verification_state<>'rejected' and nullif(trim(work_email),'') is not null),
    'phone_contacts',(select count(*) from pipeline.provider_contact_observations where is_current and verification_state<>'rejected' and nullif(trim(work_phone),'') is not null),
    'reviewed_rejection_violations',(
      select count(*) from pipeline.provider_contact_observations
      where metadata ? 'a15_quality_review_at'
        and metadata ? 'a15_quality_disposition'
        and not (metadata ? 'a15_quality_reconciliation')
        and (verification_state<>'rejected' or is_current)
    )
  );

  v_key_contacts:=jsonb_build_object(
    'uow',(
      select count(*)=5
      from pipeline.provider_contact_observations o
      join catalogue.providers p on p.id=o.provider_id
      where lower(p.canonical_name)='university of wollongong'
        and o.is_current and o.verification_state='current'
        and o.metadata->>'a15_quality_reconciliation'='uow_first_party_regional_experts'
    ),
    'vu',(
      select count(*)=2
      from pipeline.provider_contact_observations o
      join catalogue.providers p on p.id=o.provider_id
      where lower(p.canonical_name)='victoria university'
        and o.is_current and o.verification_state='current'
        and o.full_name is null and o.job_title='International Student Enquiries'
        and o.team_name='VU International' and o.work_email='international@vu.edu.au'
        and o.work_phone='+61 3 9919 1164'
        and o.metadata->>'a15_quality_reconciliation'='vu_final_preferred_contact'
    ),
    'wellington',exists(
      select 1
      from pipeline.provider_contact_observations o
      join catalogue.providers p on p.id=o.provider_id
      where lower(p.canonical_name)='victoria university of wellington'
        and o.is_current and o.verification_state='current' and o.full_name is null
        and o.job_title='International Student Experience' and o.team_name='International Student Experience'
        and o.work_email='international-support@vuw.ac.nz' and o.work_phone='+64 4 463 5350'
        and o.metadata->>'a15_quality_reconciliation'='wellington_international_student_experience'
    ),
    'sydney',(
      select count(*)=4
      from pipeline.provider_contact_observations o
      join catalogue.providers p on p.id=o.provider_id
      where lower(p.canonical_name)='the university of sydney'
        and o.is_current and o.verification_state='current'
        and o.team_name='International Recruitment'
        and o.source_url='https://www.sydney.edu.au/study/applying/how-to-apply/international-students/contact-our-regional-experts.html'
        and o.metadata->>'a15_quality_reconciliation'='sydney_first_party_regional_experts'
        and (o.full_name,o.job_title,o.territory_text,o.work_email) in (
          ('Chris Lawrance','Regional Manager','Americas and Europe','chris.lawrance@sydney.edu.au'),
          ('Nishant Jadhav','Senior Regional Manager','Central Asia, South Asia, Middle East and Africa','nishant.jadhav@sydney.edu.au'),
          ('Sean Lee','Senior Regional Manager','Asia (excluding China, Hong Kong and Macau)','sean.lee@sydney.edu.au'),
          ('Sherrie Huan','Senior Regional Manager','China, Hong Kong and Macau','sherrie.huan@sydney.edu.au')
        )
    ),
    'otago',exists(
      select 1 from pipeline.provider_contact_observations o join catalogue.providers p on p.id=o.provider_id
      where lower(p.canonical_name)='university of otago'
        and o.is_current and o.verification_state='current' and o.full_name is null
        and o.job_title='International Marketing and Recruitment'
        and o.team_name='International Marketing and Recruitment'
        and o.metadata->>'a15_quality_reconciliation'='otago_team_contact'
    )
  );

  v_watch:=jsonb_build_object(
    'contact_removed_count',(select count(*) from pipeline.provider_contact_watch_events where event_type='contact_removed'),
    'contact_restored_count',(select count(*) from pipeline.provider_contact_watch_events where event_type='contact_restored'),
    'removal_supported',position('contact_removed' in pg_get_functiondef('public.provider_contact_profile_reconcile_service(uuid,text[],integer)'::regprocedure))>0,
    'restoration_supported',position('contact_restored' in pg_get_functiondef('public.provider_contact_observation_upsert_service(jsonb)'::regprocedure))>0
  );

  v_security:=jsonb_build_object(
    'rls_enabled',(
      select bool_and(c.relrowsecurity)
      from pg_class c join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='pipeline' and c.relname in (
        'provider_contact_profiles','provider_contact_observations',
        'provider_contact_watch_events','provider_contact_enrichment_attempts'
      )
    ),
    'no_direct_table_grants',not exists(
      select 1 from information_schema.role_table_grants
      where table_schema='pipeline'
        and table_name in (
          'provider_contact_profiles','provider_contact_observations',
          'provider_contact_watch_events','provider_contact_enrichment_attempts'
        )
        and grantee in ('anon','authenticated','PUBLIC')
    ),
    'service_upsert_private',
      not has_function_privilege('anon','public.provider_contact_observation_upsert_service(jsonb)','execute')
      and not has_function_privilege('authenticated','public.provider_contact_observation_upsert_service(jsonb)','execute'),
    'service_reconcile_private',
      not has_function_privilege('anon','public.provider_contact_profile_reconcile_service(uuid,text[],integer)','execute')
      and not has_function_privilege('authenticated','public.provider_contact_profile_reconcile_service(uuid,text[],integer)','execute')
  );

  v_authority:=jsonb_build_object(
    'providers',(select count(*) from catalogue.providers),
    'courses',(select count(*) from catalogue.courses),
    'search_documents',(select count(*) from search.course_documents),
    'publication_entity_states',(select count(*) from publishing.entity_states),
    'publication_events',(select count(*) from publishing.publication_events),
    'publication_approvals',(select count(*) from publishing.publication_approvals),
    'expected',jsonb_build_object(
      'providers',3085,'courses',43461,'search_documents',33105,
      'publication_entity_states',0,'publication_events',9,'publication_approvals',2
    )
  );

  v_ok:=v_metrics @> jsonb_build_object(
      'profile_total',60,'profile_au',52,'profile_nz',8,'profile_success',60,'profile_errors',0,
      'current_contacts',31,'contact_providers',11,'territory_contacts',17,'rejected_contacts',45,
      'email_contacts',30,'phone_contacts',18,'reviewed_rejection_violations',0
    )
    and coalesce((v_key_contacts->>'uow')::boolean,false)
    and coalesce((v_key_contacts->>'vu')::boolean,false)
    and coalesce((v_key_contacts->>'wellington')::boolean,false)
    and coalesce((v_key_contacts->>'sydney')::boolean,false)
    and coalesce((v_key_contacts->>'otago')::boolean,false)
    and coalesce((v_watch->>'removal_supported')::boolean,false)
    and coalesce((v_watch->>'restoration_supported')::boolean,false)
    and coalesce((v_watch->>'contact_removed_count')::integer,0)>0
    and coalesce((v_security->>'rls_enabled')::boolean,false)
    and coalesce((v_security->>'no_direct_table_grants')::boolean,false)
    and coalesce((v_security->>'service_upsert_private')::boolean,false)
    and coalesce((v_security->>'service_reconcile_private')::boolean,false)
    and (v_authority-'expected')=(v_authority->'expected');

  return jsonb_build_object(
    'ok',v_ok,
    'change_control','CF-CHG-20260829-046',
    'frozen_baseline','A15-60-profile-first-party-v1',
    'metrics',v_metrics,
    'key_contacts',v_key_contacts,
    'watch_events',v_watch,
    'security',v_security,
    'authority',v_authority,
    'canonical_mutation_authorised',false,
    'search_mutation_authorised',false,
    'publication_mutation_authorised',false
  );
end $$;


ALTER FUNCTION "security"."admin_a15_acceptance_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_automation_control_v1"("p_job" "text", "p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'cron', 'security'
    SET "statement_timeout" TO '100s'
    AS $$
declare j cron.job%rowtype; c pipeline.automation_catalogue%rowtype; v_rank int:=security.current_role_rank(); v_n int; v_every int; v_sched text; v_cmd text; r record;
begin
  if auth.uid() is null or v_rank<5 then raise exception 'Platform Admin role required' using errcode='42501'; end if;
  if p_action in ('pause_area','resume_area') then
    for r in select j2.jobid, j2.jobname from cron.job j2 join pipeline.automation_catalogue c2 on c2.jobname=j2.jobname where c2.area=p_args->>'area' and c2.control_rank<=v_rank loop
      perform cron.alter_job(r.jobid, active => p_action='resume_area');
    end loop;
    insert into pipeline.admin_control_events(area,action,target,detail,actor) values ('automations',p_action,p_args->>'area',p_args,auth.uid());
    return security.admin_automations_read_v1();
  end if;
  select * into j from cron.job where jobname=p_job;
  if j.jobid is null then raise exception 'unknown automation'; end if;
  select * into c from pipeline.automation_catalogue where jobname=p_job;
  if v_rank<coalesce(c.control_rank,6) then raise exception 'this automation needs a higher role to change' using errcode='42501'; end if;
  if p_action in ('pause','resume') then
    perform cron.alter_job(j.jobid, active => p_action='resume');
  elsif p_action='run_now' then
    execute j.command;
  elsif p_action='set_every' then
    v_every:=(p_args->>'minutes')::int;
    if v_every not in (1,2,3,5,10,15,20,30,60,120,360,1440) then raise exception 'choose 1, 2, 3, 5, 10, 15, 20, 30 or 60 minutes, or 2, 6 or 24 hours'; end if;
    v_sched:=case when v_every=1 then '* * * * *'
                  when v_every<60 then (abs(hashtext(p_job))%v_every)::text||'-59/'||v_every||' * * * *'
                  when v_every=60 then (abs(hashtext(p_job))%60)::text||' * * * *'
                  when v_every=1440 then (abs(hashtext(p_job))%60)::text||' '||(abs(hashtext(p_job||'h'))%24)::text||' * * *'
                  else (abs(hashtext(p_job))%60)::text||' */'||(v_every/60)||' * * *' end;
    perform cron.alter_job(j.jobid, schedule => v_sched);
  elsif p_action='set_batch' then
    if not coalesce(c.batch_editable,false) then raise exception 'batch size cannot be changed for this automation'; end if;
    v_n:=(p_args->>'batch')::int;
    if v_n is null or v_n<1 or v_n>500 then raise exception 'batch size must be 1-500'; end if;
    v_cmd:=case when j.command ~ '"limit"\s*:\s*\d+' then regexp_replace(j.command,'"limit"\s*:\s*\d+','"limit":'||v_n)
                else regexp_replace(j.command,'\(\s*\d+\s*\)','('||v_n||')') end;
    perform cron.alter_job(j.jobid, command => v_cmd);
  else raise exception 'unknown action'; end if;
  insert into pipeline.admin_control_events(area,action,target,detail,actor) values ('automations',p_action,p_job,p_args,auth.uid());
  return security.admin_automations_read_v1();
end $$;


ALTER FUNCTION "security"."admin_automation_control_v1"("p_job" "text", "p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_automations_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'cron', 'security'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  return jsonb_build_object('generated_at',now(),'rank',security.current_role_rank(),
    'jobs',(select coalesce(jsonb_agg(jsonb_build_object(
        'job',j.jobname,'area',coalesce(c.area,'Other'),'sort',coalesce(c.sort,999),'label',coalesce(c.label,j.jobname),'description',coalesce(c.description,''),
        'schedule',j.schedule,'active',j.active,'control_rank',coalesce(c.control_rank,6),
        'batch',case when coalesce(c.batch_editable,false) then security.automation_batch(j.command) end,
        'last',(select jsonb_build_object('at',d.start_time,'status',d.status,'seconds',round(extract(epoch from (d.end_time-d.start_time))::numeric,1),'message',case when d.status<>'succeeded' then left(d.return_message,200) end)
                  from cron.job_run_details d where d.jobid=j.jobid order by d.start_time desc limit 1),
        'runs_24h',(select count(*) from cron.job_run_details d where d.jobid=j.jobid and d.start_time>=now()-interval '24 hours'),
        'failed_24h',(select count(*) from cron.job_run_details d where d.jobid=j.jobid and d.start_time>=now()-interval '24 hours' and d.status='failed')
      ) order by coalesce(c.area,'Other'), coalesce(c.sort,999), j.jobname),'[]'::jsonb) from cron.job j left join pipeline.automation_catalogue c on c.jobname=j.jobname),
    'events',(select coalesce(jsonb_agg(jsonb_build_object('at',e.created_at,'action',e.action,'target',e.target,'detail',e.detail) order by e.created_at desc),'[]'::jsonb)
                from (select * from pipeline.admin_control_events where area='automations' order by created_at desc limit 15) e));
end $$;


ALTER FUNCTION "security"."admin_automations_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_campus_detail"("p_campus_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'pipeline', 'ref', 'scholarship', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;

  select jsonb_build_object(
    'id',ca.id,'stable_key',ca.stable_key,'name',ca.name,'campus_code',ca.campus_code,
    'provider_id',ca.provider_id,'provider_name',coalesce(p.display_name,p.canonical_name),
    'country_code',co.iso_alpha2,'country_name',co.name,'subdivision_code',sd.code,'subdivision_name',sd.name,
    'city',ca.city,'address_line1',ca.address_line1,'address_line2',ca.address_line2,'postcode',ca.postcode,
    'latitude',ca.latitude,'longitude',ca.longitude,'phone',ca.phone,'website',ca.website,
    'status',ca.status,'publication_status',ca.publication_status,'valid_from',ca.valid_from,'valid_to',ca.valid_to,
    'last_verified_at',ca.last_verified_at,'created_at',ca.created_at,'updated_at',ca.updated_at,
    'source',jsonb_build_object('source_id',ca.source_id,'source_label',s.label,'source_type',s.source_type,'source_url',s.url),
    'evidence',case when e.id is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('id',e.id,'type',e.evidence_type,'source_url',e.source_url,'storage_path',e.storage_path,'content_hash',e.content_hash,'captured_at',e.captured_at)) end,
    'courses_page',coalesce((
      with base as (
        select c.id,c.stable_key,c.canonical_title,c.course_code,c.lifecycle_status,c.publication_status,cc.delivery_mode,cc.is_primary
        from catalogue.course_campuses cc join catalogue.courses c on c.id=cc.course_id
        where cc.campus_id=ca.id
      ), numbered as (select *,count(*) over() total_count from base), ordered as (
        select * from numbered order by lower(canonical_title),id limit 25
      )
      select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',25,'offset',0) from ordered o
    ),jsonb_build_object('items','[]'::jsonb,'total',0,'limit',25,'offset',0)),
    'scholarship_count',(select count(distinct ss.scholarship_id) from scholarship.scopes ss where ss.campus_id=ca.id and coalesce(ss.include_exclude,'include')='include')
  ) into v_result
  from catalogue.campuses ca
  join catalogue.providers p on p.id=ca.provider_id
  join ref.countries co on co.id=ca.country_id
  left join ref.subdivisions sd on sd.id=ca.subdivision_id
  left join pipeline.sources s on s.id=ca.source_id
  left join pipeline.evidence_artifacts e on e.id=ca.evidence_id
  where ca.id=p_campus_id;

  return coalesce(v_result,'{}'::jsonb);
end
$$;


ALTER FUNCTION "security"."admin_campus_detail"("p_campus_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_campus_page_fast"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'public', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_sort text:=lower(coalesce(nullif(p_args->>'sort',''),'name'));
  v_dir text:=lower(coalesce(nullif(p_args->>'direction',''),'asc'));
  v_simple boolean;
  v_total bigint:=0;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode='42501';
  end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then
    raise exception 'assigned CourseFinder role required' using errcode='42501';
  end if;

  v_simple :=
    nullif(trim(coalesce(p_args->>'query','')),'') is null
    and nullif(p_args->>'country_code','') is null
    and nullif(p_args->>'subdivision_code','') is null
    and nullif(p_args->>'provider_id','') is null
    and nullif(p_args->>'status','') is null
    and nullif(p_args->>'publication_status','') is null
    and v_sort in ('name','campus')
    and v_dir='asc';

  if not v_simple then
    return security.admin_catalogue_page('campuses_page',p_args);
  end if;

  select count(*) into v_total from catalogue.campuses;

  with paged as (
    select
      ca.id,ca.stable_key,ca.name,ca.campus_code,ca.provider_id,
      ca.subdivision_id,ca.city,ca.status,ca.publication_status,
      ca.last_verified_at,ca.created_at,ca.updated_at
    from catalogue.campuses ca
    order by lower(ca.name),ca.id
    limit v_limit offset v_offset
  ), enriched as (
    select
      pg.id,pg.stable_key,pg.name,pg.campus_code,pg.provider_id,
      coalesce(p.display_name,p.canonical_name) provider_name,
      co.iso_alpha2::text country_code,co.name country_name,
      sd.code subdivision_code,sd.name subdivision_name,
      pg.city,pg.status,pg.publication_status,pg.last_verified_at,pg.created_at,pg.updated_at,
      coalesce(cc.course_count,0)::int course_count
    from paged pg
    join catalogue.providers p on p.id=pg.provider_id
    join ref.countries co on co.id=p.country_id
    left join ref.subdivisions sd on sd.id=pg.subdivision_id
    left join lateral (
      select count(*)::int course_count
      from catalogue.course_campuses cc
      where cc.campus_id=pg.id
    ) cc on true
  )
  select jsonb_build_object(
    'items',coalesce(jsonb_agg(to_jsonb(e)),'[]'::jsonb),
    'total',v_total,
    'limit',v_limit,
    'offset',v_offset,
    'sort','name',
    'direction','asc',
    'execution_profile','page_first_unfiltered_v1'
  )
  into v_result
  from enriched e;

  return v_result;
end $$;


ALTER FUNCTION "security"."admin_campus_page_fast"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_catalogue_filter_options"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'auth'
    AS $$
declare
  v_rank integer := 0;
  v_country text := upper(nullif(trim(coalesce(p_args->>'country_code','')),''));
  v_subdivision text := upper(nullif(trim(coalesce(p_args->>'subdivision_code','')),''));
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode='42501';
  end if;
  select security.current_role_rank() into v_rank;
  if v_rank < 1 then
    raise exception 'assigned CourseFinder role required' using errcode='42501';
  end if;

  if p_operation='provider_filters' then
    return jsonb_build_object(
      'countries',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.name)
        from (
          select distinct c.iso_alpha2::text code,c.name
          from ref.countries c
          where exists(select 1 from catalogue.providers p where p.country_id=c.id)
        ) x
      ),'[]'::jsonb),
      'subdivisions',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name,'type',x.subdivision_type) order by x.name)
        from (
          select distinct s.code,s.name,s.subdivision_type
          from ref.subdivisions s
          join ref.countries c on c.id=s.country_id
          where (v_country is null or c.iso_alpha2::text=v_country)
            and (
              exists(select 1 from catalogue.providers p where p.subdivision_id=s.id)
              or exists(select 1 from catalogue.campuses cp where cp.subdivision_id=s.id)
            )
        ) x
      ),'[]'::jsonb)
    );
  elsif p_operation='course_filters' then
    return jsonb_build_object(
      'countries',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.name)
        from (
          select distinct co.iso_alpha2::text code,co.name
          from catalogue.courses c
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
        ) x
      ),'[]'::jsonb),
      'subdivisions',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name,'type',x.subdivision_type) order by x.name)
        from (
          select distinct s.code,s.name,s.subdivision_type
          from catalogue.courses c
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
          join catalogue.course_campuses cc on cc.course_id=c.id
          join catalogue.campuses cp on cp.id=cc.campus_id
          join ref.subdivisions s on s.id=cp.subdivision_id
          where (v_country is null or co.iso_alpha2::text=v_country)
        ) x
      ),'[]'::jsonb),
      'providers',coalesce((
        select jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'stable_key',x.stable_key) order by x.name)
        from (
          select distinct p.id,coalesce(p.display_name,p.canonical_name) name,p.stable_key
          from catalogue.courses c
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
          where (v_country is null or co.iso_alpha2::text=v_country)
            and (v_subdivision is null or exists(
              select 1
              from catalogue.course_campuses cc
              join catalogue.campuses cp on cp.id=cc.campus_id
              join ref.subdivisions s on s.id=cp.subdivision_id
              where cc.course_id=c.id and s.code=v_subdivision
            ))
        ) x
      ),'[]'::jsonb),
      'levels',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.sort_order,x.name)
        from (
          select distinct sl.code,sl.name,sl.sort_order
          from catalogue.courses c
          join ref.study_levels sl on sl.id=c.study_level_id
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
          where (v_country is null or co.iso_alpha2::text=v_country)
            and (v_subdivision is null or exists(
              select 1 from catalogue.course_campuses cc
              join catalogue.campuses cp on cp.id=cc.campus_id
              join ref.subdivisions s on s.id=cp.subdivision_id
              where cc.course_id=c.id and s.code=v_subdivision
            ))
        ) x
      ),'[]'::jsonb),
      'fields',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.name)
        from (
          select distinct fos.code,fos.name
          from catalogue.courses c
          join ref.fields_of_study fos on fos.id=c.primary_field_id
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
          where (v_country is null or co.iso_alpha2::text=v_country)
            and (v_subdivision is null or exists(
              select 1 from catalogue.course_campuses cc
              join catalogue.campuses cp on cp.id=cc.campus_id
              join ref.subdivisions s on s.id=cp.subdivision_id
              where cc.course_id=c.id and s.code=v_subdivision
            ))
        ) x
      ),'[]'::jsonb),
      'delivery_modes',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.code) order by x.code)
        from (
          select distinct cc.delivery_mode code
          from catalogue.course_campuses cc
          join catalogue.courses c on c.id=cc.course_id
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
          where cc.delivery_mode is not null and btrim(cc.delivery_mode)<>''
            and (v_country is null or co.iso_alpha2::text=v_country)
            and (v_subdivision is null or exists(
              select 1 from catalogue.course_campuses cc2
              join catalogue.campuses cp2 on cp2.id=cc2.campus_id
              join ref.subdivisions s2 on s2.id=cp2.subdivision_id
              where cc2.course_id=c.id and s2.code=v_subdivision
            ))
        ) x
      ),'[]'::jsonb)
    );
  end if;

  raise exception 'unsupported catalogue filter operation: %',p_operation using errcode='22023';
end
$$;


ALTER FUNCTION "security"."admin_catalogue_filter_options"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


