CREATE OR REPLACE FUNCTION "security"."admin_course_scholarships"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'scholarship', 'catalogue', 'auth'
    AS $$
declare v_rank integer; v_items jsonb; v_candidates integer;
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank(); if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'mapping_id',m.id,'scholarship_id',s.id,'name',s.name,'audience',s.audience,
   'value_label',scholarship.value_label(s.id),'nationalities',s.nationalities,'publication_status',s.publication_status,
   'lifecycle_status',s.lifecycle_status,'application_close_date',s.application_close_date,
   'award_value_text',case when fc.calculation_status='calculated' then
      concat_ws(' · ',s.award_value_text,
        concat('Saving ',trim(fc.currency_code::text),' ',to_char(fc.scholarship_saving_amount,'FM999G999G999G990D00'),case when fc.fee_basis='annual' then ' a year'||coalesce(' ('||fc.fee_year||' fee)','') end),
        concat('Net fee ',trim(fc.currency_code::text),' ',to_char(fc.net_fee_amount,'FM999G999G999G990D00'),case when fc.fee_basis='annual' then ' a year' end))
      else s.award_value_text end,
   'published_award_value_text',s.award_value_text,
   'award_value_type',s.award_value_type,'award_percentage',s.award_percentage,'award_amount',s.award_amount,
   'award_currency_code',s.award_currency_code,'award_applies_to_fee_type',s.award_applies_to_fee_type,
   'award_fee_basis',s.award_fee_basis,'award_duration_basis',s.award_duration_basis,
   'academic_year',s.academic_year,'source_url',s.source_url,'evidence_id',coalesce(m.evidence_id,s.evidence_id),
   'mapping_basis',m.mapping_basis,'mapping_state',m.mapping_state,'mapped_at',m.mapped_at,
   'calculation',case when fc.id is null then null else jsonb_build_object(
      'status',fc.calculation_status,'course_fee_id',fc.course_fee_id,'fee_amount',fc.fee_amount,
      'fee_type',fc.fee_type,'fee_basis',fc.fee_basis,'fee_year',fc.fee_year,'currency_code',fc.currency_code,
      'scholarship_saving_amount',fc.scholarship_saving_amount,'net_fee_amount',fc.net_fee_amount,
      'formula',fc.calculation_formula,'reason',fc.calculation_reason,'calculated_at',fc.calculated_at,
      'fee_evidence_id',fc.fee_evidence_id,'scholarship_evidence_id',fc.scholarship_evidence_id
   ) end
 ) order by s.name),'[]'::jsonb)
 into v_items
 from scholarship.course_mappings m join scholarship.scholarships s on s.id=m.scholarship_id
 left join scholarship.course_financial_calculations fc on fc.mapping_id=m.id
 where m.course_id=p_course_id and m.mapping_state='mapped';
 select count(*) into v_candidates from scholarship.course_mapping_candidates where course_id=p_course_id and status='needs_review';
 return jsonb_build_object('items',v_items,'mapped_count',jsonb_array_length(v_items),'needs_review_count',v_candidates,
   'state',case when jsonb_array_length(v_items)>0 then 'mapped' when v_candidates>0 then 'needs_review' else 'not_mapped' end);
end $$;


ALTER FUNCTION "security"."admin_course_scholarships"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_course_state_summary"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'publishing', 'search', 'scholarship', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_stable_key text;
  v_lifecycle text;
  v_publication text;
  v_verified timestamptz;
  v_has_registration boolean:=false;
  v_has_structure boolean:=false;
  v_has_fee boolean:=false;
  v_has_intake boolean:=false;
  v_has_english boolean:=false;
  v_has_description boolean:=false;
  v_has_scholarship boolean:=false;
  v_score numeric:=0;
  v_channels jsonb;
  v_search jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;

  select c.stable_key,c.lifecycle_status,c.publication_status,c.last_verified_at,
         exists(select 1 from catalogue.course_registrations r where r.course_id=c.id),
         (c.duration_value is not null or exists(select 1 from catalogue.course_academic_options a where a.course_id=c.id)),
         exists(select 1 from catalogue.course_fees cf where cf.course_id=c.id and coalesce(cf.status,'active')='active'),
         exists(select 1 from catalogue.course_intakes ci where ci.course_id=c.id and coalesce(ci.status,'active')='active'),
         exists(select 1 from catalogue.course_english_requirements er where er.course_id=c.id and coalesce(er.status,'active')='active'),
         (c.description is not null and length(trim(c.description))>0),
         exists(
           select 1 from scholarship.scopes ss
           where coalesce(ss.include_exclude,'include')='include'
             and (ss.course_id=c.id or (ss.scope_type='provider' and ss.provider_id=c.provider_id))
         )
  into v_stable_key,v_lifecycle,v_publication,v_verified,
       v_has_registration,v_has_structure,v_has_fee,v_has_intake,v_has_english,v_has_description,v_has_scholarship
  from catalogue.courses c
  where c.id=p_course_id;

  if v_stable_key is null then return '{}'::jsonb; end if;

  v_score:=round(((v_has_registration::int+v_has_structure::int+v_has_fee::int+v_has_intake::int+v_has_english::int+v_has_description::int)*100.0/6.0)::numeric,2);

  select coalesce(jsonb_agg(jsonb_build_object(
    'channel_code',es.channel_code,'channel_name',ch.name,'audience',ch.audience,
    'locale',es.locale,'publication_status',es.publication_status,
    'published_at',es.published_at,'unpublished_at',es.unpublished_at,
    'completeness_score',es.completeness_score,'last_checked_at',es.last_checked_at,'updated_at',es.updated_at
  ) order by es.channel_code,es.locale),'[]'::jsonb)
  into v_channels
  from publishing.entity_states es
  left join publishing.channels ch on ch.code=es.channel_code
  where es.entity_id=p_course_id;

  select jsonb_build_object(
    'projected',d.course_id is not null,
    'publication_status',d.publication_status,
    'completeness_score',d.completeness_score,
    'projection_version',d.projection_version,
    'catalogue_generation',d.catalogue_generation,
    'updated_at',d.updated_at,'generated_at',d.generated_at,'source_updated_at',d.source_updated_at,
    'has_fee',d.has_fee,'has_intake',d.has_intake,'has_english',d.has_english,'has_scholarship',d.has_scholarship,
    'global_projection',case when ps.projection_code is null then null else jsonb_build_object(
      'projection_code',ps.projection_code,'generation',ps.generation,'row_count',ps.row_count,
      'rebuilt_at',ps.rebuilt_at,'content_hash',ps.content_hash,'metadata',ps.metadata
    ) end
  )
  into v_search
  from (select 1) x
  left join search.course_documents d on d.course_id=p_course_id
  left join search.projection_state ps on ps.projection_code='courses';

  return jsonb_build_object(
    'canonical',jsonb_build_object(
      'lifecycle_status',v_lifecycle,'publication_status',v_publication,'last_verified_at',v_verified
    ),
    'canonical_presence',jsonb_build_object('scholarship',v_has_scholarship),
    'admin_readiness',jsonb_build_object(
      'score',v_score,
      'signals',jsonb_build_object(
        'registration',v_has_registration,'structure',v_has_structure,'fee',v_has_fee,
        'intake',v_has_intake,'english',v_has_english,'description',v_has_description
      ),
      'definition','display-only six-signal canonical presence readiness; not truth, approval, freshness or publication'
    ),
    'consumer_channels',v_channels,
    'search',coalesce(v_search,'{}'::jsonb)
  );
end $$;


ALTER FUNCTION "security"."admin_course_state_summary"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_course_taxonomy_summary"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'pipeline'
    AS $$
declare
  v_rank integer;
begin
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0) < 1 then
    raise exception 'assigned CourseFinder role required' using errcode='42501';
  end if;

  return jsonb_build_object(
    'study_level_observations', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', o.id,
          'scheme', o.scheme,
          'registration_code', o.registration_code,
          'source_value', o.source_value,
          'mapping_status', o.mapping_status,
          'canonical_level', jsonb_build_object(
            'id', sl.id,
            'code', sl.code,
            'name', sl.name
          ),
          'status', o.status,
          'valid_from', o.valid_from,
          'valid_to', o.valid_to,
          'source_snapshot_at', o.source_snapshot_at,
          'observed_at', o.observed_at,
          'last_verified_at', o.last_verified_at,
          'content_hash', o.content_hash,
          'source', jsonb_build_object(
            'source_id', o.source_id,
            'source_label', s.label,
            'source_type', s.source_type,
            'source_url', s.url
          ),
          'evidence', case when e.id is null then null else jsonb_build_object(
            'id', e.id,
            'type', e.evidence_type,
            'source_url', e.source_url,
            'captured_at', e.captured_at,
            'content_hash', e.content_hash
          ) end
        ) order by o.observed_at desc nulls last
      )
      from catalogue.course_study_level_observations o
      join ref.study_levels sl on sl.id=o.study_level_id
      left join pipeline.sources s on s.id=o.source_id
      left join pipeline.evidence_artifacts e on e.id=o.evidence_id
      where o.course_id=p_course_id
    ), '[]'::jsonb),
    'field_observations', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', o.id,
          'source_field_code', o.source_field_code,
          'source_field_name', o.source_field_name,
          'canonical_field', jsonb_build_object(
            'id', f.id,
            'code', f.code,
            'name', f.name
          ),
          'is_primary', o.is_primary,
          'status', o.status,
          'observed_at', o.observed_at,
          'source', jsonb_build_object(
            'source_id', o.source_id,
            'source_label', s.label,
            'source_type', s.source_type,
            'source_url', s.url
          ),
          'evidence', case when e.id is null then null else jsonb_build_object(
            'id', e.id,
            'type', e.evidence_type,
            'source_url', e.source_url,
            'captured_at', e.captured_at,
            'content_hash', e.content_hash
          ) end
        ) order by o.is_primary desc, o.observed_at desc nulls last
      )
      from catalogue.course_field_observations o
      join ref.fields_of_study f on f.id=o.field_id
      left join pipeline.sources s on s.id=o.source_id
      left join pipeline.evidence_artifacts e on e.id=o.evidence_id
      where o.course_id=p_course_id
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "security"."admin_course_taxonomy_summary"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_dashboard_maturity"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$
declare v_rank integer := 0; v_payload jsonb; v_at timestamptz;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank < 1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  select payload, computed_at into v_payload, v_at from security.admin_summary_snapshots
  where snapshot_key='dashboard' and computed_at > now() - interval '10 minutes';
  if v_payload is not null then
    return v_payload || jsonb_build_object('snapshot_at', v_at, 'snapshot_source', 'snapshot');
  end if;
  return security.admin_dashboard_maturity_compute() || jsonb_build_object('snapshot_at', now(), 'snapshot_source', 'live');
end $$;


ALTER FUNCTION "security"."admin_dashboard_maturity"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_dashboard_maturity"() IS 'CF-CHG-20260820-015 role-checked operational Dashboard summary and bounded recent activity for Admin browser UX.';



CREATE OR REPLACE FUNCTION "security"."admin_dashboard_maturity_compute"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'scholarship', 'pipeline', 'workflow', 'pim', 'search', 'auth'
    AS $$
declare
  v_activity jsonb := '[]'::jsonb;
  v_search_generation bigint;
  v_search_rows bigint;
  v_search_rebuilt_at timestamptz;
begin
  select generation,row_count,rebuilt_at into v_search_generation,v_search_rows,v_search_rebuilt_at
  from search.projection_state where projection_code='courses';

  with activity as (
    select * from (
      select 'job'::text kind,j.id,initcap(replace(coalesce(j.job_type,'job'),'_',' ')) title,
        coalesce(j.domain,'Pipeline') detail,coalesce(j.status,'unknown') status,
        coalesce(j.completed_at,j.started_at,j.created_at) occurred_at
      from pipeline.jobs j
      where coalesce(j.completed_at,j.started_at,j.created_at) is not null
      order by coalesce(j.completed_at,j.started_at,j.created_at) desc limit 10
    ) jobs
    union all
    select * from (
      select 'review'::text kind,r.id,'Review · '||initcap(replace(coalesce(r.field_code,'review'),'_',' ')) title,
        'Layer 4 human resolution'::text detail,coalesce(r.status,'unknown') status,
        coalesce(r.decided_at,r.created_at) occurred_at
      from pipeline.layer4_review_items r
      where coalesce(r.decided_at,r.created_at) is not null
      order by coalesce(r.decided_at,r.created_at) desc limit 10
    ) reviews
    union all
    select * from (
      select 'evidence'::text kind,e.id,initcap(replace(coalesce(e.evidence_type,'evidence'),'_',' ')) title,
        'Evidence captured'::text detail,'captured'::text status,coalesce(e.captured_at,e.created_at) occurred_at
      from pipeline.evidence_artifacts e
      where coalesce(e.captured_at,e.created_at) is not null
      order by coalesce(e.captured_at,e.created_at) desc limit 10
    ) evidence
  ), recent as (select * from activity order by occurred_at desc limit 10)
  select coalesce(jsonb_agg(to_jsonb(recent) order by occurred_at desc),'[]'::jsonb) into v_activity from recent;

  return jsonb_build_object(
    'providers',(select count(*) from catalogue.providers),'courses',(select count(*) from catalogue.courses),
    'campuses',(select count(*) from catalogue.campuses),'course_campus_links',(select count(*) from catalogue.course_campuses),
    'scholarships',(select count(*) from scholarship.scholarships),'jobs',(select count(*) from pipeline.jobs),
    'open_reviews',(select count(*) from pipeline.layer4_review_items where status='pending'),
    'evidence',(select count(*) from pipeline.evidence_artifacts),'attributes',(select count(*) from pim.attribute_definitions),
    'search_documents',(select count(*) from search.course_documents),'search_generation',v_search_generation,
    'operational',jsonb_build_object(
      'running_jobs',(select count(*) from pipeline.jobs where status in ('queued','pending','running','processing')),
      'failed_jobs_24h',(select count(*) from pipeline.jobs where status in ('failed','error') and coalesce(completed_at,created_at)>=now()-interval '24 hours'),
      'completed_jobs_24h',(select count(*) from pipeline.jobs where status in ('completed','succeeded') and coalesce(completed_at,created_at)>=now()-interval '24 hours'),
      'evidence_24h',(select count(*) from pipeline.evidence_artifacts where coalesce(captured_at,created_at)>=now()-interval '24 hours'),
      'latest_job_at',(select max(coalesce(completed_at,started_at,created_at)) from pipeline.jobs),
      'latest_evidence_at',(select max(coalesce(captured_at,created_at)) from pipeline.evidence_artifacts),
      'search_rebuilt_at',v_search_rebuilt_at,'search_row_count',v_search_rows),
    'recent_activity',v_activity);
end
$$;


ALTER FUNCTION "security"."admin_dashboard_maturity_compute"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_data_flag_resolve_v1"("p_flag_id" "uuid", "p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'security', 'search'
    AS $$
declare f pipeline.data_flags%rowtype; fe catalogue.course_fees%rowtype; v_amount numeric:=nullif(p_args->>'amount','')::numeric; v_basis text:=nullif(p_args->>'basis','');
begin
  if auth.uid() is null or security.current_role_rank()<4 then raise exception 'Pipeline operator or admin role required' using errcode='42501'; end if;
  select * into f from pipeline.data_flags where id=p_flag_id for update;
  if f.id is null then raise exception 'flag not found'; end if;
  if f.status<>'open' then raise exception 'flag already resolved'; end if;
  select * into fe from catalogue.course_fees where id=f.record_id for update;
  if p_action='confirm' then
    update catalogue.course_fees set notes=coalesce(notes,'')||format(' | period confirmed per year by an operator %s',to_char(now(),'DD Mon YYYY')), last_verified_at=now(), updated_at=now() where id=fe.id;
    update pipeline.data_flags set status='confirmed', resolved_at=now(), resolved_by=auth.uid(), resolution=jsonb_build_object('action','confirm','note',p_args->>'note') where id=f.id;
  elsif p_action='correct' then
    if v_amount is null or v_amount<=0 or v_amount>1000000 then raise exception 'enter a positive amount'; end if;
    if v_basis not in ('annual','total_indicative') then raise exception 'period must be per year or whole course'; end if;
    update catalogue.course_fees set amount=v_amount, basis=v_basis, updated_at=now(), last_verified_at=now(),
           notes=coalesce(notes,'')||format(' | corrected by an operator %s: was %s %s',to_char(now(),'DD Mon YYYY'),fe.amount,fe.basis) where id=fe.id;
    update pipeline.data_flags set status='corrected', resolved_at=now(), resolved_by=auth.uid(),
           resolution=jsonb_build_object('action','correct','before',jsonb_build_object('amount',fe.amount,'basis',fe.basis),'after',jsonb_build_object('amount',v_amount,'basis',v_basis),'note',p_args->>'note') where id=f.id;
  elsif p_action='remove' then
    update catalogue.course_fees set status='inactive', updated_at=now(), notes=coalesce(notes,'')||format(' | removed by an operator %s',to_char(now(),'DD Mon YYYY')) where id=fe.id;
    update pipeline.data_flags set status='removed', resolved_at=now(), resolved_by=auth.uid(), resolution=jsonb_build_object('action','remove','note',p_args->>'note') where id=f.id;
  else raise exception 'action must be confirm, correct or remove'; end if;
  perform search.refresh_course_enrichment_scoped_v1(array[f.entity_id],true);
  return security.admin_data_flags_read_v1('{}'::jsonb);
end $$;


ALTER FUNCTION "security"."admin_data_flag_resolve_v1"("p_flag_id" "uuid", "p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_data_flags_read_v1"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'security'
    AS $$
declare v_status text:=coalesce(nullif(p_args->>'status',''),'open'); v_limit int:=least(greatest(coalesce((p_args->>'limit')::int,100),1),500);
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  return jsonb_build_object(
    'can_edit', security.current_role_rank()>=4,
    'counts', (select jsonb_object_agg(status,n) from (select status,count(*) n from pipeline.data_flags group by 1) x),
    'items', coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'flag',f.flag_code,'status',f.status,'created_at',f.created_at,'resolved_at',f.resolved_at,'resolution',f.resolution,
        'course_id',f.entity_id,'course',coalesce(c.display_title,c.canonical_title),'course_code',c.course_code,
        'provider',coalesce(pv.display_name,pv.canonical_name),'amount',fe.amount,'currency',fe.currency_code,'basis',fe.basis,'fee_status',fe.status,
        'page_url',f.detail->>'page_url','quotes',f.detail->'quotes',
        'schedule',(select jsonb_build_object('amount',fr.amount,'year',fr.fee_year,'url',sr.url) from pipeline.provider_fee_rows fr join pipeline.provider_fact_sources sr on sr.id=fr.source_id
                     where sr.decision='approved' and fr.current and fr.basis='annual' and fr.provider_id=c.provider_id and fr.course_code=upper(btrim(c.course_code))
                     order by fr.fee_year desc nulls last, sr.decided_at desc limit 1)) order by f.created_at desc)
      from (select * from pipeline.data_flags where status=v_status or v_status='all' order by created_at desc limit v_limit) f
      left join catalogue.courses c on c.id=f.entity_id left join catalogue.providers pv on pv.id=c.provider_id
      left join catalogue.course_fees fe on fe.id=f.record_id),'[]'::jsonb));
end $$;


ALTER FUNCTION "security"."admin_data_flags_read_v1"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_data_quality_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$
declare v_rank int:=0;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  if p_operation='data_quality_overview' then return security.data_quality_overview_cached(p_args); end if;
  if p_operation='data_quality_exceptions' then return security.data_quality_exceptions_impl(p_args); end if;
  if p_operation='data_quality_quarantine' then
    if v_rank<3 then raise exception 'curator role required for quarantine details' using errcode='42501'; end if;
    return security.data_quality_quarantine_impl(p_args);
  end if;
  raise exception 'unsupported data quality operation: %',p_operation using errcode='22023';
end
$$;


ALTER FUNCTION "security"."admin_data_quality_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_enrichment_operations_read"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'search', 'catalogue', 'ref'
    AS $$
declare
  v_rank integer:=security.current_role_rank();
  v_country text:=upper(nullif(btrim(coalesce(p_args->>'country_code','')),''));
  v_hours integer:=least(greatest(coalesce(nullif(p_args->>'hours','')::integer,24),1),168);
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,30),1),100);
  v_result jsonb;
begin
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
  if v_country is not null and v_country not in('AU','NZ') then raise exception 'unsupported country' using errcode='22023'; end if;

  with current_cov as (
    select country_code,field_key,max(covered_count)::bigint covered_count,max(total_courses)::bigint total_courses,
           max(queueable_count)::bigint queueable_count,max(blocked_count)::bigint blocked_count,
           max(awaiting_qualification_count)::bigint awaiting_count,max(snapshot_hour) snapshot_hour
    from pipeline.enrichment_coverage_snapshots s
    where s.snapshot_hour=(select max(s2.snapshot_hour) from pipeline.enrichment_coverage_snapshots s2)
      and (v_country is null or s.country_code=v_country)
    group by country_code,field_key
  ), prior_hour as (
    select distinct on(country_code,field_key) country_code,field_key,covered_count,snapshot_hour
    from pipeline.enrichment_coverage_snapshots
    where snapshot_hour < date_trunc('hour',now()) and (v_country is null or country_code=v_country)
    order by country_code,field_key,snapshot_hour desc
  ), prior_day as (
    select distinct on(country_code,field_key) country_code,field_key,covered_count,snapshot_hour
    from pipeline.enrichment_coverage_snapshots
    where snapshot_hour <= date_trunc('hour',now())-interval '24 hours' and (v_country is null or country_code=v_country)
    order by country_code,field_key,snapshot_hour desc
  ), coverage_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'country_code',c.country_code,'field_key',c.field_key,'current',c.covered_count,'total',c.total_courses,
      'coverage_pct',case when c.total_courses>0 then round((100*c.covered_count::numeric/c.total_courses),2) else 0 end,
      'remaining',greatest(c.total_courses-c.covered_count,0),
      'added_hour',case when ph.covered_count is null then null else c.covered_count-ph.covered_count end,
      'added_day',case when pd.covered_count is null then null else c.covered_count-pd.covered_count end,
      'queueable',c.queueable_count,'blocked',c.blocked_count,'awaiting_qualification',c.awaiting_count,
      'snapshot_hour',c.snapshot_hour,'hour_baseline_at',ph.snapshot_hour,'day_baseline_at',pd.snapshot_hour
    ) order by c.country_code,c.field_key),'[]'::jsonb) value
    from current_cov c left join prior_hour ph using(country_code,field_key) left join prior_day pd using(country_code,field_key)
  ), scoped_recent_items as (
    select ri.*
    from pipeline.layer2_run_items ri
    join catalogue.courses c on ri.entity_type='course' and c.id=ri.entity_id
    join catalogue.providers p on p.id=c.provider_id
    join ref.countries co on co.id=p.country_id
    where (v_country is null or trim(co.iso_alpha2)=v_country)
  ), work as (
    select jsonb_build_object(
      'queued',(select count(*) from scoped_recent_items where status='queued'),
      'processing',(select count(*) from scoped_recent_items where status in('running','discovering','acquiring','extracting')),
      'fetched',(select count(*) from pipeline.layer2_provider_attempts pa where pa.status in('completed','success','succeeded') and coalesce(pa.completed_at,pa.started_at,pa.created_at)>=now()-interval '24 hours'),
      'fetch_failures',(select count(*) from pipeline.layer2_provider_attempts pa where pa.status in('failed','error','blocked') and coalesce(pa.completed_at,pa.started_at,pa.created_at)>=now()-interval '24 hours'),
      'evidence_24h',(select count(*) from pipeline.evidence_artifacts e where e.job_id is not null and e.captured_at>=now()-interval '24 hours' and exists(select 1 from pipeline.layer2_run_items x where x.job_id=e.job_id)),
      'layer3_24h',(select count(*) from scoped_recent_items where status='layer3_required' and coalesce(completed_at,updated_at,created_at)>=now()-interval '24 hours'),
      'admitted_source_records_24h',(select count(*) from pipeline.course_fact_source_records sr where sr.applied_at>=now()-interval '24 hours'),
      'http_429_24h',(select count(*) from pipeline.layer2_provider_attempts pa where pa.response_http_status=429 and coalesce(pa.completed_at,pa.started_at,pa.created_at)>=now()-interval '24 hours'),
      'http_5xx_24h',(select count(*) from pipeline.layer2_provider_attempts pa where pa.response_http_status>=500 and coalesce(pa.completed_at,pa.started_at,pa.created_at)>=now()-interval '24 hours'),
      'vendor_units_24h',(select coalesce(sum(coalesce((nullif(pa.metrics->>'vendor_units',''))::numeric,0)),0) from pipeline.layer2_provider_attempts pa where coalesce(pa.completed_at,pa.started_at,pa.created_at)>=now()-interval '24 hours'),
      'vendor_cost_usd_24h',(select coalesce(sum(coalesce((nullif(pa.metrics->>'estimated_request_cost_usd',''))::numeric,0)),0) from pipeline.layer2_provider_attempts pa where coalesce(pa.completed_at,pa.started_at,pa.created_at)>=now()-interval '24 hours')
    ) value
  ), hourly as (
    select coalesce(jsonb_agg(to_jsonb(h) order by h.hour_utc),'[]'::jsonb) value
    from (select * from pipeline.layer2_enrichment_hourly_admin_cache_v1
          where hour_utc>=date_trunc('hour',now())-(v_hours||' hours')::interval
            and (v_country is null or country_code=v_country)
          order by hour_utc desc limit v_hours*4) h
  ), blockers as (
    select coalesce(jsonb_agg(x order by (x->>'courses')::bigint desc,x->>'country_code',x->>'field_key'),'[]'::jsonb) value
    from (
      select jsonb_build_object('country_code',country_code,'field_key',field_key,'state','queueable','reason','ready_under_current_qualified_scope','courses',queueable_count) x from current_cov where queueable_count>0
      union all
      select jsonb_build_object('country_code',country_code,'field_key',field_key,'state','blocked','reason','blocked_under_current_scope','courses',blocked_count) from current_cov where blocked_count>0
      union all
      select jsonb_build_object('country_code',country_code,'field_key',field_key,'state','awaiting_source_profile_qualification','reason','source_profile_qualification_required','courses',awaiting_count) from current_cov where awaiting_count>0
    ) b
  ), reasons as (
    select coalesce(jsonb_agg(jsonb_build_object('reason',reason,'items',items,'fields_targeted',fields_targeted,'fields_resolved',fields_resolved) order by items desc),'[]'::jsonb) value
    from (
      select case when status='blocked' then coalesce(nullif(failure_class,''),'runtime_blocked') when status='layer3_required' then 'layer3_required' when status='resolved_l2' then 'resolved_l2' else coalesce(nullif(outcome_code,''),status,'unknown') end reason,
             count(*)::bigint items,sum(coalesce(fields_targeted,0))::bigint fields_targeted,sum(coalesce(fields_resolved,0))::bigint fields_resolved
      from scoped_recent_items
      where coalesce(completed_at,updated_at,created_at)>=now()-interval '7 days'
      group by 1 order by items desc limit 30
    ) q
  ), providers as (
    select coalesce(jsonb_agg(jsonb_build_object('provider',provider_key,'attempts',attempts,'succeeded',succeeded,'failed',failed,'vendor_units',vendor_units,'cost_usd',cost_usd,'p50_ms',p50_ms,'p95_ms',p95_ms,'retries',retries) order by attempts desc),'[]'::jsonb) value
    from (
      select coalesce(ap.provider_key,'unknown') provider_key,count(*)::bigint attempts,
        count(*) filter(where pa.status in('completed','success','succeeded'))::bigint succeeded,
        count(*) filter(where pa.status in('failed','error','blocked'))::bigint failed,
        coalesce(sum(coalesce((nullif(pa.metrics->>'vendor_units',''))::numeric,0)),0)::numeric vendor_units,
        coalesce(sum(coalesce((nullif(pa.metrics->>'estimated_request_cost_usd',''))::numeric,0)),0)::numeric cost_usd,
        percentile_cont(.5) within group(order by extract(epoch from (pa.completed_at-pa.started_at))*1000) filter(where pa.completed_at is not null and pa.started_at is not null) p50_ms,
        percentile_cont(.95) within group(order by extract(epoch from (pa.completed_at-pa.started_at))*1000) filter(where pa.completed_at is not null and pa.started_at is not null) p95_ms,
        0::bigint retries
      from pipeline.layer2_provider_attempts pa left join pipeline.layer2_acquisition_providers ap on ap.id=pa.acquisition_provider_id
      where coalesce(pa.completed_at,pa.started_at,pa.created_at)>=now()-interval '7 days'
      group by ap.provider_key order by attempts desc limit 20
    ) q
  ), admissions as (
    select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'course_id',a.course_id,'field_key',a.field_key,'status',a.status,'reason_code',a.reason_code,'canonical_changed',a.canonical_changed,'search_admission_eligible',a.search_admission_eligible,'evidence_id',a.evidence_id,'decided_at',a.decided_at,'provider_name',p.display_name,'course_title',c.display_title) order by a.decided_at desc),'[]'::jsonb) value
    from (select * from pipeline.layer2_field_admissions order by decided_at desc limit v_limit) a join catalogue.courses c on c.id=a.course_id join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id where v_country is null or trim(co.iso_alpha2)=v_country
  ), recent_items as (
    select coalesce(jsonb_agg(jsonb_build_object('run_item_id',r.id,'job_id',r.job_id,'course_id',c.id,'course_code',c.course_code,'provider_name',p.display_name,'country_code',trim(co.iso_alpha2),'status',r.status,'stop_reason',case when r.status='blocked' then coalesce(nullif(r.failure_class,''),'runtime_blocked') when r.status='layer3_required' then 'layer3_required' when r.status='resolved_l2' then 'resolved_l2' else coalesce(nullif(r.outcome_code,''),r.status,'unknown') end,'fields_targeted',r.fields_targeted,'fields_resolved',r.fields_resolved,'evidence_count',(select count(*) from pipeline.evidence_artifacts e where e.job_id=r.job_id),'source_record_id',null,'evidence_id',(select e.id from pipeline.evidence_artifacts e where e.job_id=r.job_id order by e.captured_at desc limit 1),'event_at',coalesce(r.completed_at,r.updated_at,r.created_at)) order by coalesce(r.completed_at,r.updated_at,r.created_at) desc),'[]'::jsonb) value
    from (select * from scoped_recent_items order by coalesce(completed_at,updated_at,created_at) desc nulls last limit v_limit) r
    join catalogue.courses c on c.id=r.entity_id join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
  )
  select jsonb_build_object('observed_at',now(),'country_code',v_country,'coverage',(select value from coverage_json),'work',(select value from work),'hourly',(select value from hourly),'blockers',(select value from blockers),'stop_reasons',(select value from reasons),'providers',(select value from providers),'admissions',(select value from admissions),'recent_items',(select value from recent_items),'authority_note','Acquisition, admission and Search/publication are measured separately. Metrics do not authorise mutation.','metrics_note','Current work, stop reasons and provider summaries are bounded from persisted Layer 2 base tables; hourly historical funnel remains the governed CF-245 operational ledger projection.','change_control_ref','CF-CHG-20260915-245') into v_result;
  return v_result;
end $$;


