COMMENT ON FUNCTION "security"."admin_enrichment_operations_read"("p_args" "jsonb") IS 'CF-245 rank-gated Enrichment Operations read bundle. Observability only; does not grant Layer 2, Layer 3, Layer 4, Search or Publication mutation authority.';



CREATE OR REPLACE FUNCTION "security"."admin_evidence_acquisition_provenance"("p_evidence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $_$
  with artifact as (
    select e.id,e.storage_path,e.metadata,e.job_id,
           case when coalesce(e.metadata->>'source_evidence_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                then (e.metadata->>'source_evidence_id')::uuid end as source_evidence_id
    from pipeline.evidence_artifacts e where e.id=p_evidence_id
  ), origin as (
    select a.*,coalesce(src.id,a.id) origin_evidence_id,
           coalesce(src.storage_path,a.storage_path) origin_storage_path,
           coalesce(src.metadata,a.metadata) origin_metadata
    from artifact a left join pipeline.evidence_artifacts src on src.id=a.source_evidence_id
  ), sf as (
    select o.*,f.id shared_fetch_id,f.reuse_count,f.last_reused_at,f.reusable_until,
           ap.provider_key,ap.display_name,ap.adapter_type
    from origin o
    left join pipeline.layer2_shared_fetches f on f.evidence_id=o.origin_evidence_id
    left join pipeline.layer2_acquisition_providers ap on ap.id=coalesce(
      f.acquisition_provider_id,
      case when coalesce(o.origin_metadata->>'provider_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           then (o.origin_metadata->>'provider_id')::uuid end
    )
  )
  select jsonb_strip_nulls(jsonb_build_object(
    'mode',case when source_evidence_id is not null then 'stored_evidence_derived' when coalesce(reuse_count,0)>0 then 'live_capture_with_storage_reuse' else 'live_acquisition' end,
    'mode_label',case when source_evidence_id is not null then 'Derived from stored Evidence' when coalesce(reuse_count,0)>0 then 'Live capture · reused from shared Evidence storage' else 'Live acquisition' end,
    'provider_key',coalesce(provider_key,origin_metadata->>'provider_key'),
    'provider_name',coalesce(display_name,origin_metadata->>'provider_key'),
    'adapter_type',adapter_type,'origin_evidence_id',origin_evidence_id,'source_evidence_id',source_evidence_id,
    'origin_storage_path',origin_storage_path,'shared_fetch_id',shared_fetch_id,'reuse_count',coalesce(reuse_count,0),
    'last_reused_at',last_reused_at,'reusable_until',reusable_until,'storage_reused',coalesce(reuse_count,0)>0,
    'runtime_version',origin_metadata->>'runtime_version','response_adapter',origin_metadata->>'response_adapter'
  )) from sf;
$_$;


ALTER FUNCTION "security"."admin_evidence_acquisition_provenance"("p_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_evidence_detail"("p_evidence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'workflow', 'ref', 'auth', 'storage'
    AS $$
declare
  v_rank integer:=0;
  v_result jsonb;
  v_observation_count bigint:=0;
  v_verification_at timestamptz;
  v_has_source_null boolean:=false;
  v_operational_status text;
  v_unresolved_conflict boolean:=false;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;

  v_observation_count:=security.admin_evidence_observation_count(p_evidence_id);
  v_verification_at:=security.admin_evidence_verification_at(p_evidence_id);
  v_has_source_null:=security.admin_evidence_has_source_null(p_evidence_id);
  v_operational_status:=security.admin_evidence_operational_status(p_evidence_id);
  v_unresolved_conflict:=security.admin_evidence_has_unresolved_conflict(p_evidence_id);

  select jsonb_build_object(
    'artifact',jsonb_build_object(
      'id',e.id,'evidence_type',e.evidence_type,
      'layer',security.admin_evidence_layer(e.storage_path,e.evidence_type,e.metadata,s.source_type),
      'source_url',e.source_url,'captured_at',e.captured_at,
      'snapshot_version',coalesce(e.metadata->>'snapshot_version',e.metadata->>'source_version',e.metadata->>'worker_version',e.metadata->>'version'),
      'content_hash',e.content_hash,'mime_type',e.mime_type,'valid_from',e.valid_from,'valid_to',e.valid_to,
      'verification_at',v_verification_at,
      'extraction_state',case when exists(select 1 from pipeline.claims cl where cl.evidence_id=e.id and lower(coalesce(cl.status,''))='rejected') and v_observation_count=0 then 'rejected' when v_observation_count>0 then 'extracted' else 'missing_extraction' end,
      'observation_count',v_observation_count,'has_source_null',v_has_source_null,'status',v_operational_status,
      'freshness_state',case when lower(coalesce(e.metadata->>'freshness_state',''))='stale' or lower(coalesce(e.metadata->>'stale','false'))='true' then 'stale' when e.valid_to is not null and e.valid_to<now() then 'expired' when e.valid_to is not null then 'current' else 'no_policy' end,
      'metadata',security.admin_redact_json(e.metadata)
    ),
    'acquisition_provenance',security.admin_evidence_acquisition_provenance(e.id),
    'related_visual',security.admin_evidence_related_visual(e.id),
    'source',case when s.id is null then null else jsonb_build_object('id',s.id,'label',s.label,'source_type',s.source_type,'authority_url',s.url,'status',s.status,'trust_rank',s.trust_rank,'country_code',co.iso_alpha2,'last_checked_at',s.last_checked_at,'last_success_at',s.last_success_at,'last_failure_at',s.last_failure_at,'metadata',security.admin_redact_json(s.metadata)) end,
    'job',case when j.id is null then null else jsonb_build_object('id',j.id,'job_type',j.job_type,'domain',j.domain,'status',j.status,'started_at',j.started_at,'completed_at',j.completed_at,'attempt_count',j.attempt_count) end,
    'storage',jsonb_build_object('available',o.id is not null,'size_bytes',case when jsonb_typeof(o.metadata->'size')='number' then o.metadata->'size' else null end,'content_type',coalesce(o.metadata->>'mimetype',e.mime_type),'object_created_at',o.created_at,'object_updated_at',o.updated_at,'preview_allowed',(o.id is not null and lower(coalesce(e.mime_type,'')) in ('application/pdf','image/png','image/jpeg','text/plain','application/json')),'download_allowed',(o.id is not null)),
    'supersession',jsonb_build_object('predecessor',case when prev.id is null then null else jsonb_build_object('id',prev.id,'captured_at',prev.captured_at,'content_hash',prev.content_hash) end,'successors',coalesce((select jsonb_agg(jsonb_build_object('id',n.id,'captured_at',n.captured_at,'content_hash',n.content_hash) order by n.captured_at) from pipeline.evidence_artifacts n where n.supersedes_evidence_id=e.id),'[]'::jsonb)),
    'claims',coalesce((select jsonb_agg(jsonb_build_object('id',cl.id,'entity_id',cl.entity_id,'field_code',cl.field_code,'value',security.admin_redact_json(cl.value_json),'layer',cl.layer,'confidence',cl.confidence,'status',cl.status,'created_at',cl.created_at) order by cl.created_at desc) from pipeline.claims cl where cl.evidence_id=e.id),'[]'::jsonb),
    'reviews',coalesce((select jsonb_agg(jsonb_build_object('id',rq.id,'entity_id',rq.entity_id,'domain',rq.domain,'field_code',rq.field_code,'priority',rq.priority,'status',rq.status,'created_at',rq.created_at,'updated_at',rq.updated_at,'closed_at',rq.closed_at) order by rq.created_at desc) from workflow.review_queue rq join pipeline.claims cl on cl.id=rq.candidate_claim_id where cl.evidence_id=e.id),'[]'::jsonb),
    'review_actions',coalesce((select jsonb_agg(jsonb_build_object('id',ra.id,'review_id',ra.review_id,'action',ra.action,'reason',ra.reason,'created_at',ra.created_at) order by ra.created_at desc) from workflow.review_actions ra where ra.evidence_id=e.id),'[]'::jsonb),
    'change_control_ids',case when jsonb_typeof(e.metadata->'change_control_ids')='array' then e.metadata->'change_control_ids' when e.metadata ? 'change_control_id' then jsonb_build_array(e.metadata->>'change_control_id') else '[]'::jsonb end,
    'unresolved_conflict',v_unresolved_conflict
  ) into v_result
  from pipeline.evidence_artifacts e
  left join pipeline.sources s on s.id=e.source_id
  left join ref.countries co on co.id=s.country_id
  left join pipeline.jobs j on j.id=e.job_id
  left join pipeline.evidence_artifacts prev on prev.id=e.supersedes_evidence_id
  left join storage.objects o on o.bucket_id='evidence' and o.name=e.storage_path
  where e.id=p_evidence_id;
  return coalesce(v_result,'{}'::jsonb);
end
$$;


ALTER FUNCTION "security"."admin_evidence_detail"("p_evidence_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_evidence_detail"("p_evidence_id" "uuid") IS 'M2.1 deployed UAT hardening: computes expensive Evidence metrics once per detail read while preserving the M1 Evidence response contract.';



CREATE OR REPLACE FUNCTION "security"."admin_evidence_entities"("p_evidence_id" "uuid", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'scholarship', 'search', 'publishing', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce((p_args->>'limit')::integer,50),1),200);
  v_offset integer:=greatest(coalesce((p_args->>'offset')::integer,0),0);
  v_type text:=lower(nullif(trim(coalesce(p_args->>'entity_type','')), ''));
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;

  with page_links as materialized (
    select el.entity_type,el.entity_id,el.provider_id,el.link_count
    from pipeline.evidence_entity_links el
    where el.evidence_id=p_evidence_id
      and (v_type is null or el.entity_type=v_type)
    order by el.entity_type,el.entity_id
    limit v_limit offset v_offset
  ),
  resolved as (
    select l.entity_type,l.entity_id,l.link_count,
      coalesce(c.canonical_title,p.canonical_name,ca.name,s.name) entity_label,
      coalesce(c.course_code,c.stable_key,p.stable_key,ca.stable_key,s.stable_key) entity_code,
      coalesce(l.provider_id,c.provider_id,ca.provider_id,s.provider_id,case when l.entity_type='provider' then p.id end) provider_id,
      coalesce(cp.canonical_name,cap.canonical_name,sp.canonical_name,p.canonical_name) provider_label,
      coalesce(c.publication_status,p.publication_status,ca.publication_status,s.publication_status) canonical_publication_status,
      d.course_id is not null search_projected,d.publication_status search_publication_status,
      d.has_fee search_has_fee,d.has_intake search_has_intake,d.has_english search_has_english,d.has_scholarship search_has_scholarship,
      coalesce((select jsonb_agg(jsonb_build_object('channel_code',es.channel_code,'locale',es.locale,'publication_status',es.publication_status,'updated_at',es.updated_at) order by es.channel_code,es.locale) from publishing.entity_states es where es.entity_id=l.entity_id),'[]'::jsonb) consumer_publication
    from page_links l
    left join catalogue.courses c on l.entity_type='course' and c.id=l.entity_id
    left join catalogue.providers cp on cp.id=coalesce(l.provider_id,c.provider_id)
    left join catalogue.providers p on l.entity_type='provider' and p.id=l.entity_id
    left join catalogue.campuses ca on l.entity_type='campus' and ca.id=l.entity_id
    left join catalogue.providers cap on cap.id=ca.provider_id
    left join scholarship.scholarships s on l.entity_type='scholarship' and s.id=l.entity_id
    left join catalogue.providers sp on sp.id=s.provider_id
    left join search.course_documents d on l.entity_type='course' and d.course_id=l.entity_id
  )
  select jsonb_build_object(
    'items',coalesce((select jsonb_agg(to_jsonb(x) order by x.entity_type,x.entity_id) from resolved x),'[]'::jsonb),
    'total',(select count(*) from pipeline.evidence_entity_links el where el.evidence_id=p_evidence_id and (v_type is null or el.entity_type=v_type)),
    'limit',v_limit,
    'offset',v_offset,
    'sort_basis','stable_entity_id',
    'consequence_note','Downstream Search/publication fields show the current state of related canonical entities; they are not asserted as causal consequences of this evidence unless a separate governed admission record exists.'
  ) into v_result;
  return v_result;
end
$$;


ALTER FUNCTION "security"."admin_evidence_entities"("p_evidence_id" "uuid", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_evidence_filter_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$
declare v_rank integer:=0; v_payload jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
  select payload into v_payload from security.admin_summary_snapshots
  where snapshot_key='evidence_filters' and computed_at > now() - interval '150 minutes';
  if v_payload is not null then return v_payload; end if;
  return security.admin_evidence_filter_options_compute();
end $$;


ALTER FUNCTION "security"."admin_evidence_filter_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_evidence_filter_options_compute"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'ref', 'auth'
    AS $$
declare v_rank integer:=0; v_result jsonb;
begin
  select jsonb_build_object(
    'countries',coalesce((select jsonb_agg(x order by x->>'code') from (
      select jsonb_build_object('code',co.iso_alpha2,'name',co.name) x
      from pipeline.evidence_artifacts e join pipeline.sources s on s.id=e.source_id join ref.countries co on co.id=s.country_id
      group by co.iso_alpha2,co.name) q),'[]'::jsonb),
    'sources','[]'::jsonb,
    'layers',coalesce((select jsonb_agg(x order by x->>'code') from (
      select jsonb_build_object('code',security.admin_evidence_layer(e.storage_path,e.evidence_type,e.metadata,s.source_type),'name',security.admin_evidence_layer(e.storage_path,e.evidence_type,e.metadata,s.source_type)) x
      from pipeline.evidence_artifacts e left join pipeline.sources s on s.id=e.source_id
      group by 1) q),'[]'::jsonb),
    'entity_types',jsonb_build_array(
      jsonb_build_object('code','provider','name','Provider'),
      jsonb_build_object('code','course','name','Course'),
      jsonb_build_object('code','campus','name','Campus'),
      jsonb_build_object('code','scholarship','name','Scholarship')
    ),
    'evidence_types',coalesce((select jsonb_agg(jsonb_build_object('code',evidence_type,'name',evidence_type) order by evidence_type) from (select distinct evidence_type from pipeline.evidence_artifacts where evidence_type is not null) q),'[]'::jsonb),
    'mimes',coalesce((select jsonb_agg(jsonb_build_object('code',mime_type,'name',mime_type) order by mime_type) from (select distinct mime_type from pipeline.evidence_artifacts where mime_type is not null) q),'[]'::jsonb),
    'job_statuses',coalesce((select jsonb_agg(jsonb_build_object('code',status,'name',status) order by status) from (select distinct j.status from pipeline.evidence_artifacts e join pipeline.jobs j on j.id=e.job_id where j.status is not null) q),'[]'::jsonb),
    'statuses',jsonb_build_array(
      jsonb_build_object('code','current','name','Current'),
      jsonb_build_object('code','missing_extraction','name','Missing extraction'),
      jsonb_build_object('code','source_null','name','Source-null value'),
      jsonb_build_object('code','stale','name','Stale'),
      jsonb_build_object('code','conflict','name','Unresolved conflict'),
      jsonb_build_object('code','rejected','name','Rejected'),
      jsonb_build_object('code','superseded','name','Superseded')
    ),
    'extraction_states',jsonb_build_array(
      jsonb_build_object('code','extracted','name','Extracted / linked'),
      jsonb_build_object('code','missing_extraction','name','Missing extraction'),
      jsonb_build_object('code','rejected','name','Rejected')
    ),
    'freshness_states',jsonb_build_array(
      jsonb_build_object('code','stale','name','Stale (policy-backed only)'),
      jsonb_build_object('code','expired','name','Expired validity'),
      jsonb_build_object('code','current','name','Within validity'),
      jsonb_build_object('code','no_policy','name','No freshness policy')
    )
  ) into v_result;
  return v_result;
end $$;


ALTER FUNCTION "security"."admin_evidence_filter_options_compute"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_evidence_filter_options_refresh"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare v_caller text; t timestamptz; v jsonb; ms int;
begin
  v_caller := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.role',true),''),session_user);
  if v_caller not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  t := clock_timestamp(); v := security.admin_evidence_filter_options_compute(); ms := round(extract(epoch from clock_timestamp()-t)*1000);
  insert into security.admin_summary_snapshots(snapshot_key,payload,computed_at,compute_ms) values('evidence_filters',v,now(),ms)
  on conflict(snapshot_key) do update set payload=excluded.payload, computed_at=excluded.computed_at, compute_ms=excluded.compute_ms;
  return jsonb_build_object('ok',true,'compute_ms',ms);
end $$;


