CREATE OR REPLACE FUNCTION "security"."admin_evidence_layer"("p_storage_path" "text", "p_evidence_type" "text", "p_metadata" "jsonb", "p_source_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select case
    when coalesce(p_metadata->>'layer','') ~ '^[1-4]$' then 'L'||(p_metadata->>'layer')
    when lower(coalesce(p_storage_path,'')) like 'layer2%' then 'L2'
    when lower(coalesce(p_evidence_type,'')) in ('qilt_source_workbook','prisms_published_workbook','layer2a_source_file','source_snapshot')
         and lower(coalesce(p_source_type,'')) not in ('regulatory_register','regulatory') then 'L2'
    when lower(coalesce(p_storage_path,'')) like 'regulatory%'
      or lower(coalesce(p_evidence_type,''))='regulatory_snapshot' then 'L1'
    when lower(coalesce(p_storage_path,'')) like 'layer3%' then 'L3'
    when lower(coalesce(p_storage_path,'')) like 'layer4%' then 'L4'
    else 'Unclassified'
  end
$_$;


ALTER FUNCTION "security"."admin_evidence_layer"("p_storage_path" "text", "p_evidence_type" "text", "p_metadata" "jsonb", "p_source_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_evidence_layer"("p_storage_path" "text", "p_evidence_type" "text", "p_metadata" "jsonb", "p_source_type" "text") IS 'Governed Evidence layer classifier restored to migration history by CF-241.';



CREATE OR REPLACE FUNCTION "security"."admin_evidence_matches_entity"("p_evidence_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select case
    when nullif(trim(coalesce(p_entity_type,'')),'') is null
      and p_entity_id is null
      and p_provider_id is null then true
    else exists(
      select 1
      from pipeline.evidence_entity_links el
      where el.evidence_id=p_evidence_id
        and (nullif(trim(coalesce(p_entity_type,'')),'') is null or el.entity_type=lower(trim(p_entity_type)))
        and (p_entity_id is null or el.entity_id=p_entity_id)
        and (p_provider_id is null or el.provider_id=p_provider_id)
    )
  end
$$;


ALTER FUNCTION "security"."admin_evidence_matches_entity"("p_evidence_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_provider_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_evidence_matches_entity"("p_evidence_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_provider_id" "uuid") IS 'Governed Evidence entity matcher restored to migration history by CF-241.';



CREATE OR REPLACE FUNCTION "security"."admin_evidence_observation_count"("p_evidence_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'catalogue', 'scholarship', 'pipeline'
    AS $$
  select
    (select count(*) from catalogue.course_fees where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.course_intakes where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.course_english_requirements where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.course_links where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.course_registrations where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.course_regulatory_observations where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.course_study_level_observations where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.course_field_observations where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.course_campuses where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.campuses where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.provider_outcomes where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.student_flow_observations where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.provider_registrations where evidence_id=p_evidence_id)
   +(select count(*) from catalogue.provider_identifiers where evidence_id=p_evidence_id)
   +(select count(*) from scholarship.scholarships where evidence_id=p_evidence_id)
   +(select count(*) from scholarship.offering_cycles where evidence_id=p_evidence_id)
   +(select count(*) from scholarship.application_windows where evidence_id=p_evidence_id)
   +(select count(*) from scholarship.scopes where evidence_id=p_evidence_id)
   +(select count(*) from scholarship.criterion_groups where evidence_id=p_evidence_id)
   +(select count(*) from scholarship.criteria where evidence_id=p_evidence_id)
   +(select count(*) from scholarship.award_tiers where evidence_id=p_evidence_id)
   +(select count(*) from scholarship.coverage where evidence_id=p_evidence_id)
   +(select count(*) from scholarship.identifiers where evidence_id=p_evidence_id)
$$;


ALTER FUNCTION "security"."admin_evidence_observation_count"("p_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_evidence_observations"("p_evidence_id" "uuid", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'scholarship', 'ref', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce((p_args->>'limit')::integer,50),1),200);
  v_offset integer:=greatest(coalesce((p_args->>'offset')::integer,0),0);
  v_entity_type text:=lower(nullif(trim(coalesce(p_args->>'entity_type','')), ''));
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;

  with obs as (
    select 'course_fee'::text observation_type,cf.id observation_id,'course'::text entity_type,c.id entity_id,
      c.canonical_title entity_label,c.course_code entity_code,c.provider_id,p.canonical_name provider_label,
      coalesce(cf.fee_type,'fee') field_code,
      security.admin_redact_json(to_jsonb(cf)-'source_id'-'evidence_id') value_json,
      cf.status,
      case when lower(coalesce(cf.status,''))='rejected' then 'rejected'
           when cf.amount is null then 'source_null'
           when cf.valid_to is not null and cf.valid_to<now() then 'superseded'
           else 'current' end value_state,
      cf.created_at observed_at,cf.last_verified_at verified_at,cf.valid_from::timestamptz valid_from,cf.valid_to::timestamptz valid_to
    from catalogue.course_fees cf join catalogue.courses c on c.id=cf.course_id join catalogue.providers p on p.id=c.provider_id
    where cf.evidence_id=p_evidence_id

    union all
    select 'course_intake',ci.id,'course',c.id,c.canonical_title,c.course_code,c.provider_id,p.canonical_name,
      'intake',
      security.admin_redact_json(to_jsonb(ci)-'source_id'-'evidence_id'),
      ci.status,
      case when lower(coalesce(ci.status,''))='rejected' then 'rejected'
           when ci.intake_label is null and ci.intake_year is null and ci.start_date is null then 'source_null'
           else 'current' end,
      null::timestamptz,null::timestamptz,null::timestamptz,null::timestamptz
    from catalogue.course_intakes ci join catalogue.courses c on c.id=ci.course_id join catalogue.providers p on p.id=c.provider_id
    where ci.evidence_id=p_evidence_id

    union all
    select 'course_english',ce.id,'course',c.id,c.canonical_title,c.course_code,c.provider_id,p.canonical_name,
      'english_requirement',
      security.admin_redact_json(to_jsonb(ce)-'source_id'-'evidence_id'),
      ce.status,
      case when lower(coalesce(ce.status,''))='rejected' then 'rejected'
           when ce.overall_score is null and coalesce(ce.component_scores,'{}'::jsonb)='{}'::jsonb then 'source_null'
           when ce.valid_to is not null and ce.valid_to<now() then 'superseded'
           else 'current' end,
      null::timestamptz,ce.last_verified_at,ce.valid_from::timestamptz,ce.valid_to::timestamptz
    from catalogue.course_english_requirements ce join catalogue.courses c on c.id=ce.course_id join catalogue.providers p on p.id=c.provider_id
    where ce.evidence_id=p_evidence_id

    union all
    select 'course_link',cl.id,'course',c.id,c.canonical_title,c.course_code,c.provider_id,p.canonical_name,
      coalesce('link:'||cl.link_type,'link'),
      security.admin_redact_json(to_jsonb(cl)-'source_id'-'evidence_id'),
      cl.status,
      case when lower(coalesce(cl.status,''))='rejected' then 'rejected'
           when cl.url is null then 'source_null'
           when cl.valid_to is not null and cl.valid_to<now() then 'superseded'
           else 'current' end,
      cl.created_at,cl.last_verified_at,cl.valid_from::timestamptz,cl.valid_to::timestamptz
    from catalogue.course_links cl join catalogue.courses c on c.id=cl.course_id join catalogue.providers p on p.id=c.provider_id
    where cl.evidence_id=p_evidence_id

    union all
    select 'course_registration',cr.id,'course',c.id,c.canonical_title,c.course_code,c.provider_id,p.canonical_name,
      coalesce('registration:'||cr.scheme,'registration'),
      security.admin_redact_json(to_jsonb(cr)-'source_id'-'evidence_id'),
      cr.status,
      case when lower(coalesce(cr.status,''))='rejected' then 'rejected'
           when cr.registration_code is null then 'source_null'
           when cr.valid_to is not null and cr.valid_to<now() then 'superseded'
           else 'current' end,
      null::timestamptz,null::timestamptz,cr.valid_from::timestamptz,cr.valid_to::timestamptz
    from catalogue.course_registrations cr join catalogue.courses c on c.id=cr.course_id join catalogue.providers p on p.id=c.provider_id
    where cr.evidence_id=p_evidence_id

    union all
    select 'course_regulatory',cro.id,'course',c.id,c.canonical_title,c.course_code,c.provider_id,p.canonical_name,
      'regulatory_facts',
      security.admin_redact_json(to_jsonb(cro)-'source_id'-'evidence_id'),
      cro.status,
      case when lower(coalesce(cro.status,''))='rejected' then 'rejected'
           when cro.valid_to is not null and cro.valid_to<now() then 'superseded'
           else 'current' end,
      cro.observed_at,cro.last_verified_at,cro.valid_from::timestamptz,cro.valid_to::timestamptz
    from catalogue.course_regulatory_observations cro join catalogue.courses c on c.id=cro.course_id join catalogue.providers p on p.id=c.provider_id
    where cro.evidence_id=p_evidence_id

    union all
    select 'course_study_level',sl.id,'course',c.id,c.canonical_title,c.course_code,c.provider_id,p.canonical_name,
      'study_level',
      security.admin_redact_json(to_jsonb(sl)-'source_id'-'evidence_id'),
      sl.status,
      case when lower(coalesce(sl.status,''))='rejected' then 'rejected'
           when sl.source_value is null then 'source_null'
           when sl.valid_to is not null and sl.valid_to<now() then 'superseded'
           else 'current' end,
      sl.observed_at,sl.last_verified_at,sl.valid_from::timestamptz,sl.valid_to::timestamptz
    from catalogue.course_study_level_observations sl join catalogue.courses c on c.id=sl.course_id join catalogue.providers p on p.id=c.provider_id
    where sl.evidence_id=p_evidence_id

    union all
    select 'course_field',fo.id,'course',c.id,c.canonical_title,c.course_code,c.provider_id,p.canonical_name,
      'field_of_study',
      security.admin_redact_json(to_jsonb(fo)-'source_id'-'evidence_id'),
      fo.status,
      case when lower(coalesce(fo.status,''))='rejected' then 'rejected'
           when fo.source_field_code is null and fo.source_field_name is null then 'source_null'
           else 'current' end,
      fo.observed_at,null::timestamptz,null::timestamptz,null::timestamptz
    from catalogue.course_field_observations fo join catalogue.courses c on c.id=fo.course_id join catalogue.providers p on p.id=c.provider_id
    where fo.evidence_id=p_evidence_id

    union all
    select 'provider_outcome',po.id,'provider',p.id,p.canonical_name,null::text,p.id,p.canonical_name,
      'outcome:'||po.metric_id::text,
      security.admin_redact_json(to_jsonb(po)-'source_id'-'evidence_id'),
      po.status,
      case when lower(coalesce(po.status,''))='rejected' then 'rejected'
           when po.metric_value is null then 'source_null' else 'current' end,
      po.observed_at,null::timestamptz,null::timestamptz,null::timestamptz
    from catalogue.provider_outcomes po join catalogue.providers p on p.id=po.provider_id
    where po.evidence_id=p_evidence_id

    union all
    select 'student_flow',sf.id,
      case when sf.course_id is not null then 'course' when sf.provider_id is not null then 'provider' else 'aggregate' end,
      coalesce(sf.course_id,sf.provider_id),coalesce(c.canonical_title,p.canonical_name,sf.source_geography_name),
      c.course_code,coalesce(c.provider_id,sf.provider_id),coalesce(cp.canonical_name,p.canonical_name),
      'student_flow:'||sf.metric_id::text,
      security.admin_redact_json(to_jsonb(sf)-'source_id'-'evidence_id'),
      sf.status,
      case when sf.is_suppressed then 'suppressed'
           when lower(coalesce(sf.status,''))='rejected' then 'rejected'
           when sf.metric_value is null then 'source_null' else 'current' end,
      sf.observed_at,null::timestamptz,null::timestamptz,null::timestamptz
    from catalogue.student_flow_observations sf
    left join catalogue.courses c on c.id=sf.course_id
    left join catalogue.providers cp on cp.id=c.provider_id
    left join catalogue.providers p on p.id=sf.provider_id
    where sf.evidence_id=p_evidence_id

    union all
    select 'scholarship',s.id,'scholarship',s.id,s.name,s.stable_key,s.provider_id,p.canonical_name,
      'scholarship',
      security.admin_redact_json(to_jsonb(s)-'source_id'-'evidence_id'),
      s.lifecycle_status,
      case when lower(coalesce(s.lifecycle_status,''))='rejected' then 'rejected' else 'current' end,
      s.created_at,null::timestamptz,null::timestamptz,null::timestamptz
    from scholarship.scholarships s join catalogue.providers p on p.id=s.provider_id
    where s.evidence_id=p_evidence_id

    union all
    select 'scholarship_cycle',oc.id,'scholarship',s.id,s.name,s.stable_key,s.provider_id,p.canonical_name,
      'offering_cycle',
      security.admin_redact_json(to_jsonb(oc)-'source_id'-'evidence_id'),
      oc.status,
      case when lower(coalesce(oc.status,''))='rejected' then 'rejected'
           when oc.valid_to is not null and oc.valid_to<now() then 'superseded' else 'current' end,
      oc.created_at,null::timestamptz,oc.valid_from::timestamptz,oc.valid_to::timestamptz
    from scholarship.offering_cycles oc join scholarship.scholarships s on s.id=oc.scholarship_id join catalogue.providers p on p.id=s.provider_id
    where oc.evidence_id=p_evidence_id

    union all
    select 'scholarship_window',aw.id,'scholarship',s.id,s.name,s.stable_key,s.provider_id,p.canonical_name,
      'application_window',
      security.admin_redact_json(to_jsonb(aw)-'source_id'-'evidence_id'),
      aw.status,
      case when lower(coalesce(aw.status,''))='rejected' then 'rejected' else 'current' end,
      aw.created_at,null::timestamptz,null::timestamptz,null::timestamptz
    from scholarship.application_windows aw join scholarship.scholarships s on s.id=aw.scholarship_id join catalogue.providers p on p.id=s.provider_id
    where aw.evidence_id=p_evidence_id

    union all
    select 'scholarship_criterion',sc.id,'scholarship',s.id,s.name,s.stable_key,s.provider_id,p.canonical_name,
      'criterion:'||coalesce(sc.criterion_type,'unknown'),
      security.admin_redact_json(to_jsonb(sc)-'source_id'-'evidence_id'),
      sc.status,
      case when lower(coalesce(sc.status,''))='rejected' then 'rejected'
           when sc.value_text is null and sc.value_number is null and sc.value_codes is null and sc.value_json is null then 'source_null'
           else 'current' end,
      sc.created_at,null::timestamptz,null::timestamptz,null::timestamptz
    from scholarship.criteria sc join scholarship.scholarships s on s.id=sc.scholarship_id join catalogue.providers p on p.id=s.provider_id
    where sc.evidence_id=p_evidence_id

    union all
    select 'scholarship_award',at.id,'scholarship',s.id,s.name,s.stable_key,s.provider_id,p.canonical_name,
      'award_tier',
      security.admin_redact_json(to_jsonb(at)-'source_id'-'evidence_id'),
      null::text,
      case when at.amount is null and at.percentage is null and at.maximum_amount is null then 'source_null' else 'current' end,
      null::timestamptz,null::timestamptz,null::timestamptz,null::timestamptz
    from scholarship.award_tiers at join scholarship.scholarships s on s.id=at.scholarship_id join catalogue.providers p on p.id=s.provider_id
    where at.evidence_id=p_evidence_id
  ),
  filtered as materialized (
    select * from obs where v_entity_type is null or entity_type=v_entity_type
  ),
  page as (
    select * from filtered
    order by coalesce(verified_at,observed_at) desc nulls last,observation_type,entity_label,observation_id
    limit v_limit offset v_offset
  )
  select jsonb_build_object(
    'items',coalesce((select jsonb_agg(to_jsonb(x) order by coalesce(x.verified_at,x.observed_at) desc nulls last,x.observation_type,x.entity_label) from page x),'[]'::jsonb),
    'total',(select count(*) from filtered),
    'limit',v_limit,'offset',v_offset
  ) into v_result;
  return v_result;
end
$$;


ALTER FUNCTION "security"."admin_evidence_observations"("p_evidence_id" "uuid", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_evidence_operational_status"("p_evidence_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare
  e pipeline.evidence_artifacts%rowtype;
begin
  select * into e from pipeline.evidence_artifacts where id=p_evidence_id;
  if e.id is null then return 'not_found'; end if;
  if security.admin_evidence_has_unresolved_conflict(p_evidence_id) then return 'conflict'; end if;
  if exists(select 1 from pipeline.claims cl where cl.evidence_id=p_evidence_id and lower(coalesce(cl.status,''))='rejected') then return 'rejected'; end if;
  if not security.admin_evidence_has_extraction(p_evidence_id) then return 'missing_extraction'; end if;
  if security.admin_evidence_has_source_null(p_evidence_id) then return 'source_null'; end if;
  if lower(coalesce(e.metadata->>'freshness_state',''))='stale' or lower(coalesce(e.metadata->>'stale','false'))='true' then return 'stale'; end if;
  if e.valid_to is not null and e.valid_to<now() then return 'superseded'; end if;
  if exists(select 1 from pipeline.evidence_artifacts n where n.supersedes_evidence_id=p_evidence_id) then return 'superseded'; end if;
  return 'current';
end
$$;


ALTER FUNCTION "security"."admin_evidence_operational_status"("p_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_evidence_page"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'ref', 'auth', 'storage'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce((p_args->>'limit')::integer,50),1),200);
  v_offset integer:=greatest(coalesce((p_args->>'offset')::integer,0),0);
  v_query text:=nullif(trim(coalesce(p_args->>'query','')),'');
  v_country text:=upper(nullif(trim(coalesce(p_args->>'country','')),''));
  v_source_id uuid:=nullif(p_args->>'source_id','')::uuid;
  v_layer text:=upper(nullif(trim(coalesce(p_args->>'layer','')),''));
  v_entity_type text:=nullif(trim(coalesce(p_args->>'entity_type','')),'');
  v_entity_id uuid:=nullif(p_args->>'entity_id','')::uuid;
  v_provider_id uuid:=nullif(p_args->>'provider_id','')::uuid;
  v_job_id uuid:=nullif(p_args->>'job_id','')::uuid;
  v_evidence_type text:=nullif(trim(coalesce(p_args->>'evidence_type','')),'');
  v_mime text:=nullif(trim(coalesce(p_args->>'mime','')),'');
  v_hash text:=lower(nullif(trim(coalesce(p_args->>'hash','')),''));
  v_job_status text:=nullif(trim(coalesce(p_args->>'job_status','')),'');
  v_status text:=lower(nullif(trim(coalesce(p_args->>'status','')),''));
  v_extraction_state text:=nullif(trim(coalesce(p_args->>'extraction_state','')),'');
  v_freshness text:=lower(nullif(trim(coalesce(p_args->>'freshness','')),''));
  v_verified_from timestamptz:=nullif(p_args->>'verified_from','')::timestamptz;
  v_verified_to timestamptz:=nullif(p_args->>'verified_to','')::timestamptz;
  v_conflicts boolean:=case when p_args ? 'unresolved_conflicts' then (p_args->>'unresolved_conflicts')::boolean else null end;
  v_sort text:=lower(coalesce(p_args->>'sort','captured'));
  v_direction text:=case when lower(coalesce(p_args->>'direction','desc'))='asc' then 'asc' else 'desc' end;
  v_result jsonb;
  v_fast boolean;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;

  -- Default view (no filters, newest first): only the rows that can appear on the requested page are classified.
  v_fast:=v_query is null and v_country is null and v_source_id is null and v_layer is null and v_entity_type is null and v_entity_id is null and v_provider_id is null and v_job_id is null and v_evidence_type is null and v_mime is null and v_hash is null and v_job_status is null and v_status is null and v_extraction_state is null and v_freshness is null and v_verified_from is null and v_verified_to is null and v_conflicts is null and v_sort='captured' and v_direction='desc';

  with conflicts as materialized (
    select distinct cl.evidence_id
    from workflow.review_queue rq join pipeline.claims cl on cl.id=rq.candidate_claim_id
    where cl.evidence_id is not null and lower(coalesce(rq.status,'open')) not in ('closed','resolved','accepted','rejected')
  ),
  successors as materialized (
    select distinct supersedes_evidence_id evidence_id
    from pipeline.evidence_artifacts where supersedes_evidence_id is not null
  ),
  base as materialized (
    select e.id,e.source_id,e.job_id,e.evidence_type,e.source_url,e.content_hash,e.mime_type,e.captured_at,
      e.valid_from,e.valid_to,e.supersedes_evidence_id,
      s.label source_label,s.source_type,s.status source_status,s.url authority_url,
      co.iso_alpha2 country_code,j.job_type,j.domain job_domain,j.status job_status,
      security.admin_evidence_layer(e.storage_path,e.evidence_type,e.metadata,s.source_type) layer_code,
      (lower(coalesce(e.metadata->>'freshness_state',''))='stale' or lower(coalesce(e.metadata->>'stale','false'))='true') explicit_stale,
      coalesce(ls.observation_count,0) observation_count,coalesce(ls.source_null_count,0) source_null_count,
      coalesce(ls.rejected_count,0) rejected_count,(cf.evidence_id is not null) unresolved_conflict,(su.evidence_id is not null) is_superseded
    from pipeline.evidence_artifacts e
    left join pipeline.sources s on s.id=e.source_id
    left join ref.countries co on co.id=s.country_id
    left join pipeline.jobs j on j.id=e.job_id
    left join pipeline.evidence_lineage_stats ls on ls.evidence_id=e.id
    left join conflicts cf on cf.evidence_id=e.id
    left join successors su on su.evidence_id=e.id
    where
      (not v_fast or e.id in (select c.id from pipeline.evidence_artifacts c order by c.captured_at desc nulls last,c.id limit v_limit+v_offset)) and
      (v_query is null or e.id::text ilike '%'||v_query||'%' or coalesce(s.label,'') ilike '%'||v_query||'%' or
       coalesce(s.source_type,'') ilike '%'||v_query||'%' or coalesce(s.url,'') ilike '%'||v_query||'%' or
       coalesce(e.source_url,'') ilike '%'||v_query||'%' or coalesce(e.content_hash,'') ilike '%'||v_query||'%' or
       coalesce(j.job_type,'') ilike '%'||v_query||'%' or coalesce(j.domain,'') ilike '%'||v_query||'%' or
       coalesce(e.metadata::text,'') ilike '%'||v_query||'%' or coalesce(e.storage_path,'') ilike '%'||v_query||'%')
      and (v_country is null or co.iso_alpha2=v_country)
      and (v_source_id is null or e.source_id=v_source_id)
      and (v_layer is null or security.admin_evidence_layer(e.storage_path,e.evidence_type,e.metadata,s.source_type)=v_layer)
      and (v_job_id is null or e.job_id=v_job_id)
      and (v_evidence_type is null or e.evidence_type=v_evidence_type)
      and (v_mime is null or e.mime_type=v_mime)
      and (v_hash is null or lower(coalesce(e.content_hash,'')) like v_hash||'%')
      and (v_job_status is null or j.status=v_job_status)
      and ((v_entity_type is null and v_entity_id is null and v_provider_id is null) or security.admin_evidence_matches_entity(e.id,v_entity_type,v_entity_id,v_provider_id))
      and (v_conflicts is null or (cf.evidence_id is not null)=v_conflicts)
      and (v_freshness is null
        or (v_freshness='stale' and (lower(coalesce(e.metadata->>'freshness_state',''))='stale' or lower(coalesce(e.metadata->>'stale','false'))='true'))
        or (v_freshness='expired' and lower(coalesce(e.metadata->>'freshness_state',''))<>'stale' and lower(coalesce(e.metadata->>'stale','false'))<>'true' and e.valid_to is not null and e.valid_to<now())
        or (v_freshness='current' and lower(coalesce(e.metadata->>'freshness_state',''))<>'stale' and lower(coalesce(e.metadata->>'stale','false'))<>'true' and e.valid_to is not null and e.valid_to>=now())
        or (v_freshness='no_policy' and lower(coalesce(e.metadata->>'freshness_state',''))<>'stale' and lower(coalesce(e.metadata->>'stale','false'))<>'true' and e.valid_to is null))
      and (v_verified_from is null or security.admin_evidence_verification_at(e.id)>=v_verified_from)
      and (v_verified_to is null or security.admin_evidence_verification_at(e.id)<v_verified_to)
  ),
  classified as materialized (
    select b.*,case when b.unresolved_conflict then 'conflict' when b.rejected_count>0 then 'rejected'
      when b.observation_count=0 then 'missing_extraction' when b.source_null_count>0 then 'source_null'
      when b.explicit_stale then 'stale' when (b.valid_to is not null and b.valid_to<now()) or b.is_superseded then 'superseded'
      else 'current' end operational_status
    from base b
  ),
  filtered as materialized (
    select * from classified where (v_status is null or operational_status=v_status)
      and (v_extraction_state is null or (v_extraction_state='extracted' and observation_count>0 and rejected_count=0)
        or (v_extraction_state='missing_extraction' and observation_count=0)
        or (v_extraction_state='rejected' and rejected_count>0))
  ),
  page as materialized (
    select * from filtered order by
      case when v_sort='source' and v_direction='asc' then source_label end asc nulls last,
      case when v_sort='source' and v_direction='desc' then source_label end desc nulls last,
      case when v_sort='type' and v_direction='asc' then evidence_type end asc nulls last,
      case when v_sort='type' and v_direction='desc' then evidence_type end desc nulls last,
      case when v_sort='layer' and v_direction='asc' then layer_code end asc nulls last,
      case when v_sort='layer' and v_direction='desc' then layer_code end desc nulls last,
      case when v_sort='captured' and v_direction='asc' then captured_at end asc nulls last,
      case when v_sort='captured' and v_direction='desc' then captured_at end desc nulls last,
      captured_at desc nulls last,id limit v_limit offset v_offset
  ),
  final_page as materialized (
    select p.*,exists(select 1 from storage.objects o join pipeline.evidence_artifacts ee on ee.id=p.id where o.bucket_id='evidence' and o.name=ee.storage_path) storage_available from page p
  )
  select jsonb_build_object(
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'id',x.id,'country_code',x.country_code,'source_id',x.source_id,'source_label',x.source_label,'source_type',x.source_type,
      'source_status',x.source_status,'authority_url',x.authority_url,'layer',x.layer_code,'job_id',x.job_id,'job_type',x.job_type,
      'job_domain',x.job_domain,'job_status',x.job_status,'evidence_type',x.evidence_type,'mime_type',x.mime_type,'captured_at',x.captured_at,
      'valid_from',x.valid_from,'valid_to',x.valid_to,'content_hash',x.content_hash,
      'extraction_state',case when x.rejected_count>0 then 'rejected' when x.observation_count>0 then 'extracted' else 'missing_extraction' end,
      'observation_count',x.observation_count,'has_source_null',x.source_null_count>0,'status',x.operational_status,
      'freshness_state',case when x.explicit_stale then 'stale' when x.valid_to is not null and x.valid_to<now() then 'expired' when x.valid_to is not null then 'current' else 'no_policy' end,
      'unresolved_conflict',x.unresolved_conflict,'history_state',case when x.is_superseded then 'superseded' when x.supersedes_evidence_id is not null then 'superseding_snapshot' else 'current_or_unversioned' end,
      'storage_available',x.storage_available
    ) order by
      case when v_sort='source' and v_direction='asc' then x.source_label end asc nulls last,
      case when v_sort='source' and v_direction='desc' then x.source_label end desc nulls last,
      case when v_sort='type' and v_direction='asc' then x.evidence_type end asc nulls last,
      case when v_sort='type' and v_direction='desc' then x.evidence_type end desc nulls last,
      case when v_sort='layer' and v_direction='asc' then x.layer_code end asc nulls last,
      case when v_sort='layer' and v_direction='desc' then x.layer_code end desc nulls last,
      case when v_sort='captured' and v_direction='asc' then x.captured_at end asc nulls last,
      case when v_sort='captured' and v_direction='desc' then x.captured_at end desc nulls last,x.captured_at desc nulls last,x.id)
      from final_page x),'[]'::jsonb),
    'total',case when v_fast then (select count(*) from pipeline.evidence_artifacts) else (select count(*) from filtered) end,'limit',v_limit,'offset',v_offset
  ) into v_result;
  return v_result;
end
$$;


ALTER FUNCTION "security"."admin_evidence_page"("p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_evidence_page"("p_args" "jsonb") IS 'Governed Evidence catalogue page implementation restored to migration history by CF-241 from current accepted Pilot runtime truth.';



CREATE OR REPLACE FUNCTION "security"."admin_evidence_page_default_fast"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'workflow', 'ref', 'auth', 'storage'
    AS $$
declare v_rank integer:=0; v_limit integer:=least(greatest(coalesce((p_args->>'limit')::integer,50),1),200); v_offset integer:=greatest(coalesce((p_args->>'offset')::integer,0),0); v_result jsonb;
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
 select security.current_role_rank() into v_rank;
 if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
 if nullif(trim(coalesce(p_args->>'query','')),'') is not null or nullif(trim(coalesce(p_args->>'country','')),'') is not null or nullif(trim(coalesce(p_args->>'source_id','')),'') is not null or nullif(trim(coalesce(p_args->>'layer','')),'') is not null or nullif(trim(coalesce(p_args->>'entity_type','')),'') is not null or nullif(trim(coalesce(p_args->>'entity_id','')),'') is not null or nullif(trim(coalesce(p_args->>'provider_id','')),'') is not null or nullif(trim(coalesce(p_args->>'job_id','')),'') is not null or nullif(trim(coalesce(p_args->>'evidence_type','')),'') is not null or nullif(trim(coalesce(p_args->>'mime','')),'') is not null or nullif(trim(coalesce(p_args->>'hash','')),'') is not null or nullif(trim(coalesce(p_args->>'job_status','')),'') is not null or nullif(trim(coalesce(p_args->>'status','')),'') is not null or nullif(trim(coalesce(p_args->>'extraction_state','')),'') is not null or nullif(trim(coalesce(p_args->>'freshness','')),'') is not null or nullif(trim(coalesce(p_args->>'verified_from','')),'') is not null or nullif(trim(coalesce(p_args->>'verified_to','')),'') is not null or p_args ? 'unresolved_conflicts' or lower(coalesce(p_args->>'sort','captured')) <> 'captured' or lower(coalesce(p_args->>'direction','desc')) <> 'desc' then return security.admin_evidence_page(p_args); end if;
 with page_ids as materialized (select e.id,e.captured_at from pipeline.evidence_artifacts e order by e.captured_at desc nulls last,e.id limit v_limit offset v_offset),
 page_rows as materialized (
  select e.id,e.source_id,e.job_id,e.evidence_type,e.source_url,e.content_hash,e.mime_type,e.captured_at,e.valid_from,e.valid_to,e.supersedes_evidence_id,e.storage_path,e.metadata,s.label source_label,s.source_type,s.status source_status,s.url authority_url,co.iso_alpha2 country_code,j.job_type,j.domain job_domain,j.status job_status,security.admin_evidence_layer(e.storage_path,e.evidence_type,e.metadata,s.source_type) layer_code,(lower(coalesce(e.metadata->>'freshness_state',''))='stale' or lower(coalesce(e.metadata->>'stale','false'))='true') explicit_stale,coalesce(ls.observation_count,0) observation_count,coalesce(ls.source_null_count,0) source_null_count,coalesce(ls.rejected_count,0) rejected_count,
  exists(select 1 from workflow.review_queue rq join pipeline.claims cl on cl.id=rq.candidate_claim_id where cl.evidence_id=e.id and lower(coalesce(rq.status,'open')) not in ('closed','resolved','accepted','rejected')) unresolved_conflict,
  exists(select 1 from pipeline.evidence_artifacts su where su.supersedes_evidence_id=e.id) is_superseded,
  exists(select 1 from storage.objects o where o.bucket_id='evidence' and o.name=e.storage_path) storage_available
  from page_ids p join pipeline.evidence_artifacts e on e.id=p.id left join pipeline.sources s on s.id=e.source_id left join ref.countries co on co.id=s.country_id left join pipeline.jobs j on j.id=e.job_id left join pipeline.evidence_lineage_stats ls on ls.evidence_id=e.id
 ), classified as (
  select r.*,case when r.unresolved_conflict then 'conflict' when r.rejected_count>0 then 'rejected' when r.observation_count=0 then 'missing_extraction' when r.source_null_count>0 then 'source_null' when r.explicit_stale then 'stale' when (r.valid_to is not null and r.valid_to<now()) or r.is_superseded then 'superseded' else 'current' end operational_status from page_rows r
 )
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'country_code',x.country_code,'source_id',x.source_id,'source_label',x.source_label,'source_type',x.source_type,'source_status',x.source_status,'authority_url',x.authority_url,'layer',x.layer_code,'job_id',x.job_id,'job_type',x.job_type,'job_domain',x.job_domain,'job_status',x.job_status,'evidence_type',x.evidence_type,'mime_type',x.mime_type,'captured_at',x.captured_at,'valid_from',x.valid_from,'valid_to',x.valid_to,'content_hash',x.content_hash,'extraction_state',case when x.rejected_count>0 and x.observation_count=0 then 'rejected' when x.observation_count>0 then 'extracted' else 'missing_extraction' end,'observation_count',x.observation_count,'has_source_null',x.source_null_count>0,'status',x.operational_status,'freshness_state',case when x.explicit_stale then 'stale' when x.valid_to is not null and x.valid_to<now() then 'expired' when x.valid_to is not null then 'current' else 'no_policy' end,'unresolved_conflict',x.unresolved_conflict,'history_state',case when x.is_superseded then 'superseded' when x.supersedes_evidence_id is not null then 'superseding_snapshot' else 'current_or_unversioned' end,'storage_available',x.storage_available) order by x.captured_at desc nulls last,x.id) from classified x),'[]'::jsonb),'total',(select count(*) from pipeline.evidence_artifacts),'limit',v_limit,'offset',v_offset) into v_result;
 return v_result;
end $$;


ALTER FUNCTION "security"."admin_evidence_page_default_fast"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_evidence_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$
declare v_id uuid;
begin
  if p_operation='evidence_page' then return security.admin_evidence_page(p_args); end if;
  if p_operation='evidence_filters' then return security.admin_evidence_filter_options(); end if;
  if p_operation='evidence_detail' then
    v_id:=nullif(p_args->>'id','')::uuid;
    return security.admin_evidence_detail(v_id);
  end if;
  if p_operation='evidence_observations' then
    v_id:=nullif(p_args->>'id','')::uuid;
    return security.admin_evidence_observations(v_id,p_args);
  end if;
  if p_operation='evidence_entities' then
    v_id:=nullif(p_args->>'id','')::uuid;
    return security.admin_evidence_entities(v_id,p_args);
  end if;
  raise exception 'unsupported evidence read operation: %',p_operation using errcode='22023';
end
$$;


ALTER FUNCTION "security"."admin_evidence_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_evidence_related_visual"("p_evidence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'storage'
    AS $$
  select case when se.id is null then null else jsonb_build_object(
    'id',se.id,
    'evidence_type',se.evidence_type,
    'mime_type',se.mime_type,
    'captured_at',se.captured_at,
    'content_hash',se.content_hash,
    'storage_available',so.id is not null,
    'preview_allowed',(so.id is not null and lower(coalesce(se.mime_type,'')) in ('image/png','image/jpeg','image/webp')),
    'source_url',se.source_url,
    'attempt_id',pa.id
  ) end
  from pipeline.evidence_artifacts cur
  join pipeline.layer2_provider_attempts pa
    on pa.screenshot_evidence_id is not null
   and lower(coalesce(cur.mime_type,'')) in ('text/html','application/xhtml+xml')
   and (
     pa.raw_evidence_id=cur.id
     or pa.html_evidence_id=cur.id
   )
  join pipeline.evidence_artifacts se on se.id=pa.screenshot_evidence_id
  left join storage.objects so on so.bucket_id='evidence' and so.name=se.storage_path
  where cur.id=p_evidence_id
  order by pa.completed_at desc nulls last
  limit 1
$$;


ALTER FUNCTION "security"."admin_evidence_related_visual"("p_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_evidence_verification_at"("p_evidence_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'catalogue'
    AS $$
  select max(v) from (
    select max(last_verified_at) v from catalogue.course_fees where evidence_id=p_evidence_id
    union all select max(last_verified_at) from catalogue.course_english_requirements where evidence_id=p_evidence_id
    union all select max(last_verified_at) from catalogue.course_links where evidence_id=p_evidence_id
    union all select max(last_verified_at) from catalogue.course_regulatory_observations where evidence_id=p_evidence_id
    union all select max(last_verified_at) from catalogue.course_study_level_observations where evidence_id=p_evidence_id
    union all select max(verified_at) from catalogue.course_identifiers where evidence_id=p_evidence_id
    union all select max(last_verified_at) from catalogue.campuses where evidence_id=p_evidence_id
    union all select max(verified_at) from catalogue.provider_identifiers where evidence_id=p_evidence_id
    union all select max(verified_at) from catalogue.provider_rankings where evidence_id=p_evidence_id
    union all select max(verified_at) from catalogue.provider_collection_memberships where evidence_id=p_evidence_id
    union all select max(checked_at) from catalogue.provider_registrations where evidence_id=p_evidence_id
  ) q
$$;


ALTER FUNCTION "security"."admin_evidence_verification_at"("p_evidence_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_evidence_verification_at"("p_evidence_id" "uuid") IS 'Governed Evidence verification timestamp helper restored to migration history by CF-241.';



CREATE OR REPLACE FUNCTION "security"."admin_filter_option_page"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_kind text:=lower(nullif(trim(coalesce(p_args->>'kind','')),''));
  v_query text:=lower(nullif(trim(coalesce(p_args->>'query','')),''));
  v_country text:=upper(nullif(trim(coalesce(p_args->>'country_code','')),''));
  v_survey text:=nullif(trim(coalesce(p_args->>'survey_code','')),'');
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,10),1),10);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_items jsonb:='[]'::jsonb;
  v_total integer:=0;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;

  if v_kind='evidence_source' then
    if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
    with q as (
      select s.id::text value,s.label label,
             concat_ws(' · ',nullif(s.source_type,''),co.iso_alpha2::text) meta,
             count(*)::bigint cnt
      from pipeline.evidence_artifacts e
      join pipeline.sources s on s.id=e.source_id
      left join ref.countries co on co.id=s.country_id
      where (v_country is null or upper(co.iso_alpha2::text)=v_country)
        and (v_query is null or lower(s.label||' '||coalesce(s.source_type,'')||' '||coalesce(co.iso_alpha2::text,'')) like '%'||v_query||'%')
      group by s.id,s.label,s.source_type,co.iso_alpha2
    ), n as (select count(*) total from q),
    page as (select * from q order by lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta,'count',cnt) order by lower(label),value) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;

  elsif v_kind='qilt_provider' then
    if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
    with q as (
      select p.id::text value,coalesce(p.display_name,p.canonical_name) label,p.stable_key meta,count(*)::bigint cnt
      from catalogue.provider_outcomes po
      join catalogue.providers p on p.id=po.provider_id
      join ref.outcome_surveys os on os.id=po.survey_id
      where os.code like 'qilt_%'
        and (v_survey is null or os.code=v_survey)
        and (v_query is null or lower(coalesce(p.display_name,p.canonical_name)||' '||coalesce(p.stable_key,'')) like '%'||v_query||'%')
      group by p.id,p.display_name,p.canonical_name,p.stable_key
    ), n as (select count(*) total from q),
    page as (select * from q order by lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta,'count',cnt) order by lower(label),value) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;

  elsif v_kind='qilt_metric' then
    if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
    with q as (
      select om.code value,om.name label,concat_ws(' · ',om.unit,om.code) meta,count(*)::bigint cnt
      from catalogue.provider_outcomes po
      join ref.outcome_surveys os on os.id=po.survey_id
      join ref.outcome_metrics om on om.id=po.metric_id
      where os.code like 'qilt_%'
        and (v_survey is null or os.code=v_survey)
        and (v_query is null or lower(om.name||' '||om.code||' '||coalesce(om.unit,'')) like '%'||v_query||'%')
      group by om.code,om.name,om.unit
    ), n as (select count(*) total from q),
    page as (select * from q order by lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta,'count',cnt) order by lower(label),value) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;

  elsif v_kind='prisms_study_area' then
    if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
    with q as (
      select sfo.source_study_area_code value,sfo.source_study_area_name label,sfo.source_study_area_code meta,count(*)::bigint cnt
      from catalogue.student_flow_observations sfo
      join ref.outcome_surveys os on os.id=sfo.survey_id
      where os.code='prisms_international_students'
        and sfo.source_study_area_code is not null
        and (v_query is null or lower(coalesce(sfo.source_study_area_name,'')||' '||sfo.source_study_area_code) like '%'||v_query||'%')
      group by sfo.source_study_area_code,sfo.source_study_area_name
    ), n as (select count(*) total from q),
    page as (select * from q order by lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta,'count',cnt) order by lower(label),value) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;
  else
    raise exception 'unsupported filter option kind: %',coalesce(v_kind,'') using errcode='22023';
  end if;

  return jsonb_build_object(
    'items',v_items,'total',v_total,'limit',v_limit,'offset',v_offset,
    'has_more',(v_offset+jsonb_array_length(v_items))<v_total
  );
end $$;


ALTER FUNCTION "security"."admin_filter_option_page"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_insights_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'auth'
    AS $$
declare
  v_rank integer := 0;
  v_limit integer := least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer := greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_provider_id uuid;
  v_year integer;
  v_suppressed boolean;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode='42501';
  end if;

  select security.current_role_rank() into v_rank;
  if v_rank < 1 then
    raise exception 'assigned CourseFinder role required' using errcode='42501';
  end if;

  v_provider_id := nullif(p_args->>'provider_id','')::uuid;
  v_year := nullif(p_args->>'year','')::integer;
  v_suppressed := case
    when nullif(p_args->>'suppressed','') is null then null
    else (p_args->>'suppressed')::boolean
  end;

  if p_operation='qilt_outcomes' then
    return public.ui_qilt_outcomes_page(
      v_limit,
      v_offset,
      nullif(p_args->>'query',''),
      nullif(p_args->>'survey_code',''),
      nullif(p_args->>'metric_code',''),
      v_provider_id,
      nullif(p_args->>'status',''),
      v_year,
      coalesce(nullif(p_args->>'sort',''),'provider'),
      coalesce(nullif(p_args->>'direction',''),'asc')
    );
  elsif p_operation='qilt_filters' then
    return public.ui_qilt_filter_options(nullif(p_args->>'survey_code',''));
  elsif p_operation='prisms_student_flow' then
    return public.ui_prisms_student_flow_page(
      v_limit,
      v_offset,
      nullif(p_args->>'query',''),
      nullif(p_args->>'subdivision_code',''),
      nullif(p_args->>'study_area_code',''),
      nullif(p_args->>'sector_code',''),
      nullif(p_args->>'remoteness_area',''),
      v_suppressed,
      coalesce(nullif(p_args->>'sort',''),'geography'),
      coalesce(nullif(p_args->>'direction',''),'asc')
    );
  elsif p_operation='prisms_filters' then
    return public.ui_prisms_filter_options();
  else
    raise exception 'unsupported insights read operation: %',p_operation using errcode='22023';
  end if;
end
$$;


ALTER FUNCTION "security"."admin_insights_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_insights_read"("p_operation" "text", "p_args" "jsonb") IS 'CF-CHG-20260820-005 private role-checked dispatcher for accepted QILT Provider outcomes and PRISMS source-grain Student Flow Admin reads.';



CREATE OR REPLACE FUNCTION "security"."admin_job_close_v1"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_j pipeline.admin_jobs%rowtype; v_pid uuid;
begin
  select * into v_j from pipeline.admin_jobs j where j.id = p_id;
  if v_j.id is null or v_j.state not in ('done', 'failed', 'cancelled') then return; end if;
  if exists (select 1 from pipeline.jobs x where x.job_type = 'layer2_task' and x.payload->>'admin_job_id' = p_id::text) then return; end if;
  v_pid := case when coalesce(jsonb_array_length(v_j.args->'providers'), 0) = 1 then (v_j.args->'providers'->>0)::uuid else null end;
  insert into pipeline.jobs(job_type, domain, status, provider_id, requested_by, started_at, completed_at, attempt_count, payload, result, error_text)
  values ('layer2_task', v_j.kind, case when v_j.state = 'done' then 'completed' else 'failed' end, v_pid, v_j.requested_by, coalesce(v_j.started_at, v_j.created_at), coalesce(v_j.finished_at, now()), 1,
          jsonb_build_object('admin_job_id', v_j.id, 'kind', v_j.kind, 'title', v_j.title, 'scope', v_j.scope, 'reason', v_j.reason, 'args', v_j.args - 'providers', 'providers', coalesce(jsonb_array_length(v_j.args->'providers'), 0),
                             'mode', case when v_j.kind = 'qualify_adapters' then 'qualification' else 'apply' end),
          jsonb_build_object('state', v_j.state, 'progress', v_j.progress) || v_j.result,
          case when v_j.state = 'cancelled' then 'cancelled by a person (work done so far kept)' else v_j.error end);
end $$;


ALTER FUNCTION "security"."admin_job_close_v1"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_job_slice_v1"("p_id" "uuid", "p_items" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_j pipeline.admin_jobs%rowtype; v_next int; v_total int; v_ids uuid[]; v_pid uuid; v_r jsonb; v_min_read numeric; v_min_agree numeric;
        v_done int := 0; v_errs int; v_pass int; v_fields text[]; v_have text[]; v_want text[]; v_claims text; v_res jsonb; v_added text[];
begin
  select * into v_j from pipeline.admin_jobs j where j.id = p_id for update;
  if v_j.kind in ('reread_pages', 'firecrawl_run', 'adapter_apply', 'central_page_read') then return security.admin_job_watch_v1(p_id); end if;
  v_ids := array(select (x)::uuid from jsonb_array_elements_text(v_j.args->'providers') x);
  v_total := coalesce(array_length(v_ids, 1), 0);
  v_next := coalesce((v_j.cursor->>'next')::int, 1);
  v_errs := coalesce((v_j.result->>'errors')::int, 0);
  v_pass := coalesce((v_j.result->>'passing')::int, 0);
  v_min_read := coalesce((security.firecrawl_setting('eval_field_share') #>> '{}')::numeric, 0.5);
  v_min_agree := coalesce((security.firecrawl_setting('qualify_agree_share') #>> '{}')::numeric, 0.9);
  while v_next <= v_total and v_done < p_items loop
    v_pid := v_ids[v_next];
    begin
      if v_j.kind = 'qualify_adapters' then
        v_r := security.adapter_qualify_one_v1(v_pid, v_min_read, v_min_agree);
        insert into pipeline.adapter_qualifications(job_id, provider_id, pages_read, fields, passing)
          values (p_id, v_pid, (v_r->>'pages_read')::int, v_r->'fields', array(select x from jsonb_array_elements_text(v_r->'passing') x))
          on conflict (job_id, provider_id) do update set measured_at = now(), pages_read = excluded.pages_read, fields = excluded.fields, passing = excluded.passing where pipeline.adapter_qualifications.job_id = excluded.job_id and pipeline.adapter_qualifications.provider_id = excluded.provider_id;
        if jsonb_array_length(v_r->'passing') > 0 then v_pass := v_pass + 1; end if;
      elsif v_j.kind = 'admit_qualified' then
        v_want := array(select x from jsonb_array_elements_text(v_j.args->'fields') x);
        select q.passing into v_fields from pipeline.adapter_qualifications q where q.job_id = coalesce((v_j.args->'qual_jobs'->>v_pid::text)::uuid, (v_j.args->>'qualification_job_id')::uuid) and q.provider_id = v_pid;
        select coalesce(u.admit_fields, '{}') into v_have from pipeline.uni_adapters u where u.provider_id = v_pid;
        v_added := array(select f from unnest(v_fields) f where f = any (v_want) and f <> all (v_have));
        if coalesce(array_length(v_added, 1), 0) > 0 then
          -- as the person who started the job, through the ordinary admission control (its checks and its log entry)
          v_claims := jsonb_build_object('sub', v_j.requested_by::text, 'role', 'authenticated')::text;
          perform set_config('request.jwt.claims', v_claims, true);
          v_res := public.admin_uni_adapter_control('admit', jsonb_build_object('provider_id', v_pid, 'admit', true,
                     'fields', to_jsonb(array(select distinct f from unnest(v_have || v_added) f order by f)),
                     'reason', left('Admitted by job ' || p_id::text || ' (' || v_j.title || '): ' || v_j.reason, 400)));
          perform set_config('request.jwt.claims', '', true);
          v_pass := v_pass + 1;
          insert into pipeline.admin_job_events(job_id, note, detail) values (p_id, 'admitted ' || array_to_string(v_added, ', ') || ' for ' || (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = v_pid), jsonb_build_object('provider_id', v_pid, 'fields', v_res->'fields'));
        end if;
      end if;
    exception when others then
      perform set_config('request.jwt.claims', '', true);
      v_errs := v_errs + 1;
      insert into pipeline.admin_job_events(job_id, note, detail) values (p_id, 'error for ' || coalesce((select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = v_pid), v_pid::text) || ': ' || left(sqlerrm, 300), jsonb_build_object('provider_id', v_pid));
    end;
    v_next := v_next + 1; v_done := v_done + 1;
  end loop;
  update pipeline.admin_jobs set cursor = jsonb_build_object('next', v_next), progress = jsonb_build_object('done', v_next - 1, 'total', v_total), result = jsonb_build_object('passing', v_pass, 'errors', v_errs), updated_at = now() where id = p_id;
  return v_next > v_total;
end $$;


ALTER FUNCTION "security"."admin_job_slice_v1"("p_id" "uuid", "p_items" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_job_watch_v1"("p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_j pipeline.admin_jobs%rowtype; v_done int := 0; v_total int := 0; v_fin boolean := false; v_note text := null; v_phase text := null;
        v_last_done int; v_last_at timestamptz; v_stall interval; v_ids uuid[]; r record;
begin
  select * into v_j from pipeline.admin_jobs j where j.id = p_id for update;
  v_last_done := coalesce((v_j.cursor->>'last_done')::int, -1);
  v_last_at := coalesce((v_j.cursor->>'last_change_at')::timestamptz, v_j.started_at, v_j.created_at);
  if v_j.kind = 'reread_pages' then
    v_stall := interval '30 minutes';
    select * into r from pipeline.university_reread_requests q where q.id = (v_j.args->>'request_id')::uuid;
    if r.id is null then v_fin := true; v_note := 'the re-read request is gone';
    elsif r.status = 'cancelled' then v_fin := true; v_note := 'cancelled before every university was sent (' || cardinality(r.done_ids) || ' of ' || cardinality(r.provider_ids) || ' sent)';
    elsif r.status = 'failed' then v_fin := true; v_note := 'the request failed: ' || coalesce(r.last_error, 'no detail');
    elsif r.status in ('waiting', 'sending') then
      v_phase := 'sending'; v_done := cardinality(r.done_ids); v_total := cardinality(r.provider_ids);
    else
      v_phase := 'reading'; v_total := coalesce(r.pages, 0);
      v_ids := r.provider_ids;
      select count(*) into v_done from pipeline.coverage_course_pages pg where pg.provider_id = any (v_ids) and pg.read_at >= coalesce(v_j.started_at, v_j.created_at);
      if v_done >= v_total then v_fin := true; v_note := v_total || ' page(s) sent back and read again'; end if;
    end if;
  elsif v_j.kind = 'firecrawl_run' then
    select * into r from pipeline.firecrawl_runs x where x.id = (v_j.args->>'run_id')::uuid;
    if r.id is null then v_fin := true; v_note := 'the run is gone';
    else
      v_done := coalesce(r.done, 0); v_total := coalesce(r.items, 0);
      if r.status <> 'running' then v_fin := true; v_note := 'run ' || r.status || ': ' || v_done || ' of ' || v_total || ' done, ' || coalesce(r.credits_used, 0) || ' credits'; end if;
    end if;
  elsif v_j.kind = 'adapter_apply' then
    v_stall := interval '20 minutes';
    v_total := coalesce((v_j.args->>'pages')::int, 0);
    select count(*) into v_done from pipeline.coverage_course_pages pg where pg.provider_id = (v_j.args->>'provider_id')::uuid and pg.read_at >= coalesce(v_j.started_at, v_j.created_at);
    if v_done >= v_total then v_fin := true; v_note := v_total || ' page(s) read again with the adapter'; end if;
  elsif v_j.kind = 'central_page_read' then
    v_stall := interval '30 minutes'; v_total := 1;
    select * into r from pipeline.provider_fact_sources s where s.id = (v_j.args->>'source_id')::uuid;
    if r.id is null then v_fin := true; v_note := 'the central page record is gone';
    elsif r.status in ('read', 'parsed', 'no_values', 'failed') and r.updated_at >= coalesce(v_j.started_at, v_j.created_at) - interval '1 minute' then
      v_done := 1; v_fin := true; v_note := 'page ' || r.status || coalesce(': ' || (r.parse_summary->>'error'), '');
    end if;
  end if;
  if v_done <> v_last_done then v_last_done := v_done; v_last_at := now(); end if;
  if not v_fin and v_stall is not null and now() - v_last_at > v_stall then
    v_fin := true; v_note := coalesce(v_note, v_done || ' of ' || v_total || ' done, nothing more for ' || extract(epoch from v_stall)::int / 60 || ' minutes: the rest wait their turn in the reader');
  end if;
  update pipeline.admin_jobs set cursor = jsonb_build_object('last_done', v_last_done, 'last_change_at', v_last_at), progress = jsonb_build_object('done', v_done, 'total', v_total) || coalesce(jsonb_build_object('phase', v_phase), '{}'::jsonb), result = jsonb_build_object('done', v_done, 'total', v_total, 'errors', case when v_note like 'the request failed%' then 1 else 0 end) || coalesce(jsonb_build_object('note', v_note), '{}'::jsonb), updated_at = now() where id = p_id;
  if v_fin and v_note is not null then insert into pipeline.admin_job_events(job_id, note) values (p_id, v_note); end if;
  return v_fin;
end $$;


ALTER FUNCTION "security"."admin_job_watch_v1"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_jobs_resolve_adapters_v1"("p_args" "jsonb") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_country text := upper(nullif(btrim(coalesce(p_args->>'country', '')), '')); v_state text := upper(nullif(btrim(coalesce(p_args->>'state', '')), ''));
        v_kind text := coalesce(nullif(p_args->>'provider_kind', ''), 'any'); v_adapter text := coalesce(nullif(p_args->>'adapter_state', ''), 'enabled');
        v_pat text := coalesce(security.firecrawl_setting('target_name_pattern') #>> '{}', '(^|[^a-z])universit(y|ies)([^a-z]|$)');
        v_ids uuid[];
begin
  if p_args ? 'provider_ids' and jsonb_typeof(p_args->'provider_ids') = 'array' and jsonb_array_length(p_args->'provider_ids') > 0 then
    return array(select distinct (x)::uuid from jsonb_array_elements_text(p_args->'provider_ids') x
                  where exists (select 1 from pipeline.uni_adapters u where u.provider_id = (x)::uuid));
  end if;
  v_ids := array(
    select p.id from catalogue.providers p
      join ref.countries k on k.id = p.country_id
      left join ref.subdivisions s on s.id = p.subdivision_id
      join pipeline.uni_adapters u on u.provider_id = p.id
     where (v_country is null or k.iso_alpha2 = v_country)
       and (v_state is null or upper(s.code) = v_state)
       and (v_kind <> 'university' or coalesce(p.display_name, p.canonical_name) ~* v_pat)
       and (v_adapter = 'any' or (v_adapter = 'enabled' and u.enabled) or (v_adapter = 'testing' and u.enabled and not u.admit) or (v_adapter = 'admitting' and u.enabled and u.admit))
     order by coalesce(p.display_name, p.canonical_name));
  return v_ids;
end $_$;


ALTER FUNCTION "security"."admin_jobs_resolve_adapters_v1"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_jobs_runtime_read_v1"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $_$
declare
  v_rank integer:=0;
  v_limit integer:=case when coalesce(p_args->>'limit','') ~ '^\d{1,9}$'
    then least(greatest((p_args->>'limit')::integer,1),200)
    else 50 end;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;

  with recent as (
    select
      j.id,j.job_type,j.domain,j.status,j.created_at,j.started_at,j.completed_at,j.source_profile_version_id,
      case when coalesce(j.result->>'processed','') ~ '^\d{1,18}$' then (j.result->>'processed')::bigint end processed_count,
      case when coalesce(j.result->>'selected','') ~ '^\d{1,18}$' then (j.result->>'selected')::bigint end selected_count,
      case when coalesce(j.result->>'accepted','') ~ '^\d{1,18}$' then (j.result->>'accepted')::bigint
           when coalesce(j.result->>'applied','') ~ '^\d{1,18}$' then (j.result->>'applied')::bigint end accepted_count,
      case when coalesce(j.result->>'failed','') ~ '^\d{1,18}$' then (j.result->>'failed')::bigint end failed_count,
      case when coalesce(j.result->>'retry_exhausted_count','') ~ '^\d{1,18}$' then (j.result->>'retry_exhausted_count')::bigint
           when coalesce(j.payload->>'retry_exhausted_count','') ~ '^\d{1,18}$' then (j.payload->>'retry_exhausted_count')::bigint end retry_exhausted_count,
      case when j.result ? 'idempotent_replay' and lower(j.result->>'idempotent_replay') in ('true','false') then (j.result->>'idempotent_replay')::boolean end dedupe_replay,
      case
        when j.status<>'failed' then nullif(j.result->>'completion_class','')
        when coalesce(j.error_text,'') ilike '%401%' then 'authentication_401'
        when coalesce(j.error_text,'') ilike '%credential%' then 'credential_unavailable'
        when coalesce(j.error_text,'') ilike '%provider%' and coalesce(j.error_text,'') ilike '%exhaust%' then 'provider_exhausted'
        when coalesce(j.error_text,'') ilike '%budget%' then 'acquisition_budget_exhausted'
        when coalesce(j.error_text,'') ilike '%timeout%' then 'timeout'
        else 'failed'
      end failure_class
    from pipeline.jobs j
    order by j.created_at desc
    limit v_limit
  ), evidence_counts as (
    select e.job_id,
      count(*) evidence_count,
      count(*) filter(where e.review_state in ('verified','verified_source_reference')) verified_evidence_count
    from pipeline.evidence_artifacts e
    where e.job_id in (select id from recent)
    group by e.job_id
  )
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id',j.id,
    'job_type',j.job_type,
    'domain',j.domain,
    'status',j.status,
    'created_at',j.created_at,
    'started_at',j.started_at,
    'completed_at',j.completed_at,
    'source_profile_version_id',j.source_profile_version_id,
    'profile_id',p.id,
    'profile_key',p.profile_key,
    'processed_count',j.processed_count,
    'selected_count',j.selected_count,
    'accepted_count',j.accepted_count,
    'failed_count',j.failed_count,
    'retry_exhausted_count',j.retry_exhausted_count,
    'evidence_count',coalesce(ec.evidence_count,0),
    'verified_evidence_count',coalesce(ec.verified_evidence_count,0),
    'throughput_records_per_min',case when j.processed_count is not null and j.started_at is not null and j.completed_at>j.started_at then round((j.processed_count::numeric/nullif(extract(epoch from (j.completed_at-j.started_at)),0))*60,2) end,
    'dedupe_replay',j.dedupe_replay,
    'failure_class',j.failure_class
  )) order by j.created_at desc),'[]'::jsonb)
  into v_result
  from recent j
  left join pipeline.layer2_source_profile_versions pv on pv.id=j.source_profile_version_id
  left join pipeline.layer2_source_profiles p on p.id=pv.profile_id
  left join evidence_counts ec on ec.job_id=j.id;

  return v_result;
end
$_$;


ALTER FUNCTION "security"."admin_jobs_runtime_read_v1"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_jobs_tick_v1"("p_items" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_lane text; v_j pipeline.admin_jobs%rowtype; v_fin boolean; v_out jsonb := '[]'::jsonb;
begin
  for v_lane in select distinct lane from pipeline.admin_jobs where state in ('queued', 'running') loop
    select * into v_j from pipeline.admin_jobs j where j.lane = v_lane and j.state in ('queued', 'running')
     order by (j.state = 'running') desc, j.created_at limit 1 for update skip locked;
    if v_j.id is null then continue; end if;
    if v_j.cancel_requested then
      update pipeline.admin_jobs set state = 'cancelled', finished_at = now(), updated_at = now() where id = v_j.id;
      insert into pipeline.admin_job_events(job_id, note) values (v_j.id, 'cancelled at a provider boundary, work done so far kept');
      perform security.admin_job_close_v1(v_j.id);
      v_out := v_out || jsonb_build_object('id', v_j.id, 'state', 'cancelled'); continue;
    end if;
    if v_j.pause_requested then
      update pipeline.admin_jobs set state = 'paused', pause_requested = false, updated_at = now() where id = v_j.id;
      insert into pipeline.admin_job_events(job_id, note) values (v_j.id, 'paused at a provider boundary');
      v_out := v_out || jsonb_build_object('id', v_j.id, 'state', 'paused'); continue;
    end if;
    if v_j.state = 'queued' then
      update pipeline.admin_jobs set state = 'running', started_at = now(), updated_at = now() where id = v_j.id;
      insert into pipeline.admin_job_events(job_id, note) values (v_j.id, 'started');
    end if;
    begin
      v_fin := security.admin_job_slice_v1(v_j.id, p_items);
    exception when others then
      update pipeline.admin_jobs set state = 'failed', error = left(sqlerrm, 500), finished_at = now(), updated_at = now() where id = v_j.id;
      insert into pipeline.admin_job_events(job_id, note) values (v_j.id, 'failed: ' || left(sqlerrm, 300));
      perform security.admin_job_close_v1(v_j.id);
      v_out := v_out || jsonb_build_object('id', v_j.id, 'state', 'failed'); continue;
    end;
    if v_fin then
      update pipeline.admin_jobs set state = 'done', finished_at = now(), updated_at = now() where id = v_j.id;
      insert into pipeline.admin_job_events(job_id, note, detail) values (v_j.id, 'finished', (select j.result from pipeline.admin_jobs j where j.id = v_j.id));
      perform security.admin_job_close_v1(v_j.id);
    end if;
    v_out := v_out || jsonb_build_object('id', v_j.id, 'state', case when v_fin then 'done' else 'running' end);
  end loop;
  return v_out;
end $$;


ALTER FUNCTION "security"."admin_jobs_tick_v1"("p_items" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer1_approve_departures_v1"("p_run_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare v_rank int; v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank; if coalesce(v_rank,0)<6 then raise exception 'platform_admin role required' using errcode='42501'; end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'reason required' using errcode='22023'; end if;
  if not exists (select 1 from pipeline.layer1_run_plans where run_id=p_run_id and departures_status='held') then raise exception 'no held departures for this run' using errcode='55000'; end if;
  v_result:=security.layer1_plan_finish_v1(p_run_id,true,auth.uid());
  update pipeline.layer1_run_queue set result=coalesce(result,'{}'::jsonb)||jsonb_build_object('departures',v_result||jsonb_build_object('reason',left(p_reason,300))),updated_at=now() where id=p_run_id;
  return v_result;
end $$;


ALTER FUNCTION "security"."admin_layer1_approve_departures_v1"("p_run_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer1_command"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'ref', 'auth'
    AS $_$
declare v_rank integer; v_source uuid; v_reason text; v_id uuid; v_country text; v_mode text; v_version integer; v_warning boolean; v_url text; v_profile jsonb; v_domains text[];
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if; select security.current_role_rank() into v_rank; if coalesce(v_rank,0)<6 then raise exception 'platform_admin role required' using errcode='42501'; end if; v_source:=nullif(p_args->>'source_id','')::uuid; if v_source is null then raise exception 'source_id required' using errcode='22023'; end if; v_reason:=trim(coalesce(p_args->>'reason','')); if length(v_reason)<5 then raise exception 'governance reason required' using errcode='22023'; end if;
 if p_operation='save_source' then
  select url into v_url from pipeline.sources where id=v_source; if not found then raise exception 'source not found' using errcode='22023'; end if; v_url:=coalesce(nullif(trim(p_args->>'source_url',''),''),v_url); if v_url !~* '^https://[^[:space:]]+$' then raise exception 'https source_url required' using errcode='22023'; end if; select array_agg(lower(trim(x))) into v_domains from jsonb_array_elements_text(coalesce(p_args->'authority_domains','[]'::jsonb)) x where trim(x)<>''; if coalesce(cardinality(v_domains),0)=0 then raise exception 'at least one authority domain required' using errcode='22023'; end if; if length(trim(coalesce(p_args->>'authority_name','')))<3 then raise exception 'authority_name required' using errcode='22023'; end if; if length(trim(coalesce(p_args->>'expected_format','')))<2 then raise exception 'expected_format required' using errcode='22023'; end if;
  update pipeline.sources set url=v_url,updated_at=now() where id=v_source;
  insert into pipeline.layer1_source_operations(source_id,authority_name,authority_domains,expected_format,expected_count_kind,active,paused,verification_cadence_days,ingestion_cadence_days,variance_warn_percent,variance_block_percent,min_expected_records,max_expected_records,verification_status,variance_decision,last_verified_at,verification_message,next_verification_at,change_reason,updated_by,updated_at)
  values(v_source,trim(p_args->>'authority_name'),v_domains,trim(p_args->>'expected_format'),coalesce(nullif(trim(p_args->>'expected_count_kind'),''),'records'),coalesce((p_args->>'active')::boolean,true),coalesce((p_args->>'paused')::boolean,false),coalesce(nullif(p_args->>'verification_cadence_days','')::integer,1),nullif(p_args->>'ingestion_cadence_days','')::integer,coalesce(nullif(p_args->>'variance_warn_percent','')::numeric,5),coalesce(nullif(p_args->>'variance_block_percent','')::numeric,20),nullif(p_args->>'min_expected_records','')::bigint,nullif(p_args->>'max_expected_records','')::bigint,'unverified','unknown',null,'Source configuration changed; source must be revalidated before execution.',now(),v_reason,auth.uid(),now())
  on conflict(source_id) do update set authority_name=excluded.authority_name,authority_domains=excluded.authority_domains,expected_format=excluded.expected_format,expected_count_kind=excluded.expected_count_kind,active=excluded.active,paused=excluded.paused,verification_cadence_days=excluded.verification_cadence_days,ingestion_cadence_days=excluded.ingestion_cadence_days,variance_warn_percent=excluded.variance_warn_percent,variance_block_percent=excluded.variance_block_percent,min_expected_records=excluded.min_expected_records,max_expected_records=excluded.max_expected_records,verification_status='unverified',variance_decision='unknown',last_verified_at=null,verification_message='Source configuration changed; source must be revalidated before execution.',next_verification_at=now(),change_reason=excluded.change_reason,updated_by=auth.uid(),updated_at=now();
  select coalesce(max(version_no),0)+1 into v_version from pipeline.layer1_source_operation_versions where source_id=v_source; select to_jsonb(o)-'updated_by' into v_profile from pipeline.layer1_source_operations o where o.source_id=v_source; insert into pipeline.layer1_source_operation_versions(source_id,version_no,snapshot,changed_by,change_reason) values(v_source,v_version,v_profile,auth.uid(),v_reason); return jsonb_build_object('source_id',v_source,'version_no',v_version,'status','saved_revalidation_required');
 elsif p_operation='set_pause' then update pipeline.layer1_source_operations set paused=coalesce((p_args->>'paused')::boolean,true),change_reason=v_reason,updated_by=auth.uid(),updated_at=now() where source_id=v_source returning to_jsonb(layer1_source_operations)-'updated_by' into v_profile; if not found then raise exception 'source operations profile missing' using errcode='22023'; end if; select coalesce(max(version_no),0)+1 into v_version from pipeline.layer1_source_operation_versions where source_id=v_source; insert into pipeline.layer1_source_operation_versions(source_id,version_no,snapshot,changed_by,change_reason) values(v_source,v_version,v_profile,auth.uid(),v_reason); update pipeline.refresh_policies set enabled=not coalesce((p_args->>'paused')::boolean,true),updated_at=now(),change_control_ref='CF-CHG-20260826-043' where layer=1 and source_id=v_source; return jsonb_build_object('source_id',v_source,'paused',v_profile->'paused','version_no',v_version);
 elsif p_operation='queue_run' then select to_jsonb(o) into v_profile from pipeline.layer1_source_operations o where o.source_id=v_source; if not found then raise exception 'source operations profile missing' using errcode='22023'; end if; select co.iso_alpha2::text into v_country from pipeline.sources s join ref.countries co on co.id=s.country_id where s.id=v_source; v_country:=coalesce(v_country,'GLOBAL'); v_mode:=lower(coalesce(nullif(p_args->>'mode',''),'dry_run')); if v_mode not in ('validate','dry_run','apply','recheck') then raise exception 'invalid mode' using errcode='22023'; end if; if not coalesce((v_profile->>'active')::boolean,false) or coalesce((v_profile->>'paused')::boolean,false) then raise exception 'source is inactive or paused' using errcode='55000'; end if; if v_mode in ('dry_run','apply','recheck') then if coalesce(v_profile->>'verification_status','') not in ('passed','warning') then raise exception 'source verification must pass before run' using errcode='55000'; end if; if nullif(v_profile->>'next_verification_at','')::timestamptz is not null and (v_profile->>'next_verification_at')::timestamptz<now() then raise exception 'source verification is stale' using errcode='55000'; end if; if v_profile->>'variance_decision'='block' then raise exception 'record-count variance is blocked' using errcode='55000'; end if; v_warning:=v_profile->>'variance_decision'='warn'; if v_mode='apply' and v_warning and not coalesce((p_args->>'acknowledge_warning')::boolean,false) then raise exception 'variance warning acknowledgement required for APPLY' using errcode='55000'; end if; end if; insert into pipeline.layer1_run_queue(source_id,country_code,mode,status,idempotency_key,requested_by,expected_count,resume_cursor,source_hash,warning_acknowledged,current_stage,heartbeat_at,retry_of_run_id) values(v_source,v_country,v_mode,'queued',coalesce(nullif(p_args->>'idempotency_key',''),md5(v_source::text||':'||v_mode||':'||coalesce(v_profile->>'last_source_hash','nohash')||':'||coalesce(p_args->>'resume_cursor','0')||':'||current_date::text)),auth.uid(),nullif(v_profile->>'last_expected_count','')::bigint,coalesce(nullif(p_args->>'resume_cursor','')::bigint,0),v_profile->>'last_source_hash',coalesce((p_args->>'acknowledge_warning')::boolean,false),'queued',now(),nullif(p_args->>'retry_of_run_id','')::uuid) returning id into v_id; return jsonb_build_object('run_id',v_id,'status','queued','country_code',v_country,'mode',v_mode);
 elsif p_operation='recover_stuck' then
  v_id:=nullif(p_args->>'run_id','')::uuid; if v_id is null then raise exception 'run_id required' using errcode='22023'; end if;
  update pipeline.layer1_run_queue set status='failed',current_stage='stuck_recovered',completed_at=now(),heartbeat_at=now(),error_text='Recovered by Platform Admin after stale heartbeat: '||v_reason,updated_at=now() where id=v_id and source_id=v_source and status='running' and coalesce(heartbeat_at,started_at,requested_at)<now()-interval '30 minutes';
  if not found then raise exception 'only a running job with heartbeat older than 30 minutes may be recovered' using errcode='55000'; end if;
  update pipeline.layer1_source_operations set last_schedule_status='failed',last_schedule_error='Stuck run recovered: '||left(v_reason,900),consecutive_failures=consecutive_failures+1,updated_at=now() where source_id=v_source;
  return jsonb_build_object('run_id',v_id,'status','failed','stage','stuck_recovered');
 elsif p_operation='cancel_queued' then v_id:=nullif(p_args->>'run_id','')::uuid; update pipeline.layer1_run_queue set status='cancelled',current_stage='cancelled_before_start',completed_at=now(),updated_at=now(),error_text='Cancelled by Platform Admin: '||v_reason where id=v_id and source_id=v_source and status='queued'; if not found then raise exception 'only queued run may be cancelled' using errcode='55000'; end if; return jsonb_build_object('run_id',v_id,'status','cancelled'); else raise exception 'unsupported Layer 1 command: %',p_operation using errcode='22023'; end if;
end $_$;


ALTER FUNCTION "security"."admin_layer1_command"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer1_operations_read"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'ref', 'auth'
    AS $$
declare v_rank integer; v_country text:=upper(nullif(p_args->>'country_code','')); v_result jsonb;
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
 select security.current_role_rank() into v_rank;
 if coalesce(v_rank,0)<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
 with src as (
  select s.id source_id,coalesce(co.iso_alpha2::text,case when s.metadata->>'scope'='global' then 'GLOBAL' end) country_code,
   coalesce(co.name,case when s.metadata->>'scope'='global' then 'Global' end) country_name,
   s.label source_label,s.source_type,s.url source_url,s.status source_status,s.trust_rank,s.last_checked_at,s.last_success_at,s.last_failure_at,s.last_error,
   s.metadata->>'dataset_class' dataset_class,s.metadata->>'source_system' source_system,
   coalesce((s.metadata->>'edition_year')::integer,e.edition_year) edition_year,
   coalesce(s.metadata->>'edition_key',e.edition_key) edition_key,
   coalesce(s.metadata->>'edition_status',e.status) edition_status,
   f.family_code dataset_family_code,f.label dataset_family_label,f.edition_strategy,
   coalesce(f.comparison_enabled,false) comparison_enabled,coalesce(f.retain_all_editions,false) retain_all_editions,
   case when f.id is null then true else f.current_source_id=s.id end edition_is_current,
   coalesce((select count(*) from pipeline.layer1_dataset_editions eh where eh.family_id=f.id),1)::integer retained_edition_count,
   case when f.id is null then '[]'::jsonb else coalesce((
     select jsonb_agg(jsonb_build_object(
       'source_id',eh.source_id,'edition_key',eh.edition_key,'edition_year',eh.edition_year,
       'period_start',eh.period_start,'period_end',eh.period_end,'status',eh.status,
       'observation_count',eh.observation_count,'last_verified_at',eh.last_verified_at,
       'source_label',hs.label,'source_url',hs.url
     ) order by eh.period_end desc nulls last,eh.edition_year desc nulls last,eh.edition_key desc)
     from pipeline.layer1_dataset_editions eh join pipeline.sources hs on hs.id=eh.source_id where eh.family_id=f.id
   ),'[]'::jsonb) end editions,
   s.metadata->>'acquisition_mode' acquisition_mode,s.metadata->>'scope' source_scope,
   o.authority_name,o.authority_domains,o.expected_format,o.expected_count_kind,o.active,o.paused,o.verification_cadence_days,o.ingestion_cadence_days,o.auto_ingest,
   o.variance_warn_percent,o.variance_block_percent,o.min_expected_records,o.max_expected_records,o.previous_accepted_count,o.last_expected_count,
   o.previous_accepted_hash,o.last_source_hash,o.last_verified_at,o.verification_status,o.verification_message,o.variance_percent,o.variance_decision,
   o.next_verification_at,o.next_ingestion_at,o.last_schedule_status,o.last_schedule_error,o.consecutive_failures,o.updated_at,
   coalesce((select max(v.version_no) from pipeline.layer1_source_operation_versions v where v.source_id=s.id),0) source_config_version,
   case when o.last_verified_at is null then 'never_verified' when o.paused then 'paused' when o.verification_status in ('blocked','failed') then 'unhealthy'
        when exists(select 1 from pipeline.layer1_run_queue q where q.source_id=s.id and q.status='running' and coalesce(q.heartbeat_at,q.started_at,q.requested_at)<now()-interval '30 minutes') then 'stuck'
        when o.next_verification_at is not null and o.next_verification_at<now() then 'stale' else 'healthy' end source_health,
   case when o.paused then 'Source processing is paused.'
        when exists(select 1 from pipeline.layer1_run_queue q where q.source_id=s.id and q.status='running' and coalesce(q.heartbeat_at,q.started_at,q.requested_at)<now()-interval '30 minutes') then 'Running job heartbeat is stale; Platform Admin may recover it after confirming the prior worker is no longer active.'
        when o.verification_status='blocked' then 'Resolve source authority/count blocker before run.'
        when o.verification_status='failed' then 'Revalidate source before run.'
        when o.last_verified_at is null then 'Validate source before run.'
        when o.next_verification_at is not null and o.next_verification_at<now() then 'Source verification is stale; recheck before run.'
        when o.variance_decision='warn' then 'Review variance warning; explicit acknowledgement required for APPLY.'
        else 'Source is eligible for governed queueing.' end next_action,
   (select jsonb_build_object('id',q.id,'mode',q.mode,'status',q.status,'requested_at',q.requested_at,'started_at',q.started_at,'completed_at',q.completed_at,
      'current_stage',q.current_stage,'heartbeat_at',q.heartbeat_at,'stuck',q.status='running' and coalesce(q.heartbeat_at,q.started_at,q.requested_at)<now()-interval '30 minutes',
      'expected_count',q.expected_count,'processed_count',q.processed_count,
      'progress_percent',case when q.expected_count is null or q.expected_count=0 then null else round(least(100,(q.processed_count::numeric/q.expected_count::numeric)*100),1) end,
      'queue_position',case when q.status='queued' then 1 else null end,
      'runtime_seconds',case when q.started_at is null then null else greatest(0,round(extract(epoch from (coalesce(q.completed_at,now())-q.started_at))::numeric,1)) end,
      'created_count',q.created_count,'updated_count',q.updated_count,'unchanged_count',q.unchanged_count,'rejected_count',q.rejected_count,'conflicted_count',q.conflicted_count,
      'failed_count',q.failed_count,'resume_cursor',q.resume_cursor,'actual_job_id',q.actual_job_id,'retry_of_run_id',q.retry_of_run_id,'error_text',q.error_text,'result',q.result)
    from pipeline.layer1_run_queue q where q.source_id=s.id order by q.requested_at desc limit 1) latest_run,
   (select count(*)::bigint from pipeline.layer1_run_queue q where q.source_id=s.id and q.status='queued') queue_depth,
   (select count(*)::bigint from pipeline.evidence_artifacts ev where ev.source_id=s.id) evidence_count,
   (select max(ev.captured_at) from pipeline.evidence_artifacts ev where ev.source_id=s.id) latest_evidence_at,
   (select max(j.completed_at) from pipeline.jobs j where j.source_id=s.id and j.status='completed') latest_job_success_at,
   (select count(*)::bigint from pipeline.jobs j where j.source_id=s.id and j.status='running' and j.started_at<now()-interval '30 minutes') stale_running_jobs,
   p.enabled schedule_enabled,p.cadence_interval,p.next_due_at schedule_next_due_at,p.freshness_class schedule_freshness_class,p.hash_sensitive schedule_hash_sensitive,p.updated_at schedule_policy_updated_at
  from pipeline.layer1_source_operations o
  join pipeline.sources s on s.id=o.source_id
  left join ref.countries co on co.id=s.country_id
  left join pipeline.layer1_dataset_editions e on e.source_id=s.id
  left join pipeline.layer1_dataset_families f on f.id=e.family_id
  left join pipeline.refresh_policies p on p.layer=1 and p.source_id=s.id
  where (v_country is null or co.iso_alpha2=v_country or (v_country='GLOBAL' and s.metadata->>'scope'='global'))
 )
 select jsonb_build_object(
   'sources',coalesce(jsonb_agg(to_jsonb(src) order by country_code,coalesce(dataset_family_label,source_label),edition_is_current desc,edition_key desc),'[]'::jsonb),
   'retention',jsonb_build_object('transient_run_queue_days',30,'governed_evidence_deleted_by_housekeeping',false,'source_versions_deleted_by_housekeeping',false,
      'statistical_editions_retained_for_comparison',true),
   'stuck_threshold_minutes',30,
   'alerts',jsonb_build_object('stale_source','next verification overdue','abnormal_variance','configured warn/block thresholds','failed_validation','verification_status failed/blocked',
      'stuck_job','queue heartbeat older than 30 minutes','repeated_failure','consecutive_failures > 1','schedule_failure','source operation schedule error',
      'storage_growth','Evidence count and storage capacity remain governed by Evidence operations'),
   'authority_model','Layer 1 regulatory/authoritative plus governed statistical ingestion; statistical editions retain identity_authority=false.'
 ) into v_result from src;
 return v_result;
end $$;


ALTER FUNCTION "security"."admin_layer1_operations_read"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer2_dispatcher_tuning_read_v1"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank integer:=0;v_profile_id uuid;v_profile_version_id uuid;v_result jsonb;
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
 select security.current_role_rank() into v_rank; if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
 begin v_profile_id:=nullif(p_args->>'profile_id','')::uuid; exception when invalid_text_representation then raise exception 'valid profile_id required' using errcode='22023'; end;
 if v_profile_id is null then raise exception 'profile_id required' using errcode='22023'; end if;
 select pv.id into v_profile_version_id from pipeline.layer2_source_profile_versions pv where pv.profile_id=v_profile_id and pv.validation_status='valid' order by pv.version_no desc limit 1;
 with recent_batches as(select b.* from pipeline.layer2_run_batches b where b.profile_id=v_profile_id order by b.created_at desc limit 12),
 run_metrics as(select b.id,count(i.*) item_count,count(*) filter(where i.status='resolved_l2') resolved_l2,count(*) filter(where i.status='layer3_required') layer3_required,count(*) filter(where i.status='blocked') blocked,count(*) filter(where i.status in ('queued','acquiring','extracting','discovering')) active_items,coalesce(sum(i.retry_count),0) retry_count,round(avg(i.response_ms) filter(where i.response_ms is not null),1) avg_response_ms,round(avg(i.extraction_ms) filter(where i.extraction_ms is not null),1) avg_extraction_ms,coalesce(sum(i.evidence_count),0) evidence_count,coalesce(sum(i.fields_targeted),0) fields_targeted,coalesce(sum(i.fields_resolved),0) fields_resolved,count(*) filter(where i.completed_at>=now()-interval '60 minutes') recent_completed_60m,min(i.completed_at) filter(where i.completed_at>=now()-interval '60 minutes') recent_first_completed_at,max(i.completed_at) filter(where i.completed_at>=now()-interval '60 minutes') recent_last_completed_at from recent_batches b left join pipeline.layer2_run_items i on i.batch_id=b.id group by b.id),
 runs as(select jsonb_build_object('id',b.id,'status',b.status,'trigger_type',b.trigger_type,'created_at',b.created_at,'started_at',b.started_at,'completed_at',b.completed_at,'target_count',b.target_count,'processed_count',b.processed_count,'resolved_l2_count',b.resolved_l2_count,'escalated_l3_count',b.escalated_l3_count,'blocked_count',b.blocked_count,'vendor_units',b.vendor_units,'vendor_cost_usd',b.vendor_cost_usd,'policy_snapshot',jsonb_build_object('batch_size',b.policy_snapshot->'batch_size','max_concurrency',b.policy_snapshot->'max_concurrency','stale_after_minutes',b.policy_snapshot->'stale_after_minutes','max_paid_attempts_per_entity',b.policy_snapshot->'max_paid_attempts_per_entity','routing_strategy',b.policy_snapshot->'routing_strategy'),'runtime_seconds',case when b.started_at is not null then round(extract(epoch from(coalesce(b.completed_at,now())-b.started_at))::numeric,1) end,'wall_throughput_items_per_min',case when b.started_at is not null and b.processed_count>0 and coalesce(b.completed_at,now())>b.started_at then round((b.processed_count::numeric/nullif(extract(epoch from(coalesce(b.completed_at,now())-b.started_at)),0))*60,2) end,'recent_completed_60m',m.recent_completed_60m,'active_window_items_per_min',case when m.recent_completed_60m>=2 and m.recent_last_completed_at>m.recent_first_completed_at then round((m.recent_completed_60m::numeric/nullif(extract(epoch from(m.recent_last_completed_at-m.recent_first_completed_at)),0))*60,2) end,'item_count',m.item_count,'active_items',m.active_items,'retry_count',m.retry_count,'avg_response_ms',m.avg_response_ms,'avg_extraction_ms',m.avg_extraction_ms,'evidence_count',m.evidence_count,'fields_targeted',m.fields_targeted,'fields_resolved',m.fields_resolved,'field_resolution_percent',case when m.fields_targeted>0 then round(100.0*m.fields_resolved/m.fields_targeted,1) end) row_json,b.created_at from recent_batches b join run_metrics m on m.id=b.id),
 provider_metrics as(select jsonb_build_object('provider_key',ap.provider_key,'display_name',ap.display_name,'enabled',ap.enabled,'priority',r.priority,'vendor_concurrency',ap.concurrency,'rate_limit_per_minute',ap.rate_limit_per_minute,'timeout_seconds',ap.timeout_seconds,'attempts_24h',count(pa.*),'success_24h',count(pa.*) filter(where pa.status='succeeded'),'failed_24h',count(pa.*) filter(where pa.status='failed'),'http_429_24h',count(pa.*) filter(where pa.response_http_status=429),'avg_attempt_ms_24h',round(avg(extract(epoch from(pa.completed_at-pa.started_at))*1000) filter(where pa.completed_at is not null and pa.started_at is not null)::numeric,1)) row_json,r.priority from pipeline.layer2_profile_provider_routes r join pipeline.layer2_acquisition_providers ap on ap.id=r.acquisition_provider_id left join pipeline.layer2_provider_attempts pa on pa.acquisition_provider_id=ap.id and pa.profile_version_id=v_profile_version_id and pa.created_at>=now()-interval '24 hours' where r.profile_id=v_profile_id and r.enabled group by ap.id,ap.provider_key,ap.display_name,ap.enabled,ap.priority,ap.concurrency,ap.rate_limit_per_minute,ap.timeout_seconds,r.priority)
 select jsonb_build_object('profile',(select jsonb_build_object('id',p.id,'profile_key',p.profile_key,'source_label',s.label,'country_code',coalesce(cv.configuration->>'country_code',s.metadata->>'country_code'),'domain',p.domain,'enabled',p.enabled,'paused',p.paused) from pipeline.layer2_source_profiles p join pipeline.sources s on s.id=p.source_id left join pipeline.layer2_source_profile_versions cv on cv.id=p.current_version_id where p.id=v_profile_id),'policy',(select to_jsonb(ep)-'updated_by' from pipeline.layer2_execution_policies ep where ep.profile_id=v_profile_id),'system_guardrails',jsonb_build_object('transport_wave_cap',4,'scraper_first_wave_cap',2,'pg_net_timeout_ms',120000,'tuning_mode','manual_governed'),'recent_runs',(select coalesce(jsonb_agg(row_json order by created_at desc),'[]'::jsonb) from runs),'providers',(select coalesce(jsonb_agg(row_json order by priority),'[]'::jsonb) from provider_metrics),'recent_tuning',(select coalesce(jsonb_agg(jsonb_build_object('created_at',e.created_at,'governance_reason',e.governance_reason,'changed_fields',e.changed_fields,'before_policy',e.before_policy,'after_policy',e.after_policy) order by e.created_at desc),'[]'::jsonb) from(select * from pipeline.layer2_tuning_events where profile_id=v_profile_id order by created_at desc limit 10)e)) into v_result;
 return v_result;
end $$;


ALTER FUNCTION "security"."admin_layer2_dispatcher_tuning_read_v1"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer2_ops_overview_fast"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'security'
    SET "jit" TO 'off'
    AS $$
  select security.admin_layer2_ops_read('layer2_ops_overview','{}'::jsonb)
$$;


ALTER FUNCTION "security"."admin_layer2_ops_overview_fast"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer2_ops_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref', 'public'
    AS $$
declare v_rank integer; v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank < 4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
  if p_operation='layer2_ops_overview' then
    select jsonb_build_object(
      'health',jsonb_build_object(
        'enabled_profiles',(select count(*) from pipeline.layer2_source_profiles where enabled and not paused and domain in ('course_facts','scholarship')),
        'active_runs',(select count(*) from pipeline.layer2_run_batches where status in ('queued','running')),
        'stuck_runs',(select count(*) from pipeline.layer2_run_batches b join pipeline.layer2_execution_policies ep on ep.profile_id=b.profile_id where b.status='running' and coalesce(b.heartbeat_at,b.updated_at,b.started_at,b.created_at)<now()-make_interval(mins=>coalesce(ep.stale_after_minutes,30))),
        'layer3_candidates',(select count(*) from pipeline.layer2_run_items where status='layer3_required'),
        'blocked_items',(select count(*) from pipeline.layer2_run_items where status='blocked')
      ),
      'sources','[]'::jsonb,
      'providers',(select coalesce(jsonb_agg(jsonb_build_object(
        'id',ap.id,'provider_key',ap.provider_key,'display_name',ap.display_name,'enabled',ap.enabled,
        'credential_configured',ap.vault_secret_id is not null,'priority',ap.priority,'rate_limit_per_minute',ap.rate_limit_per_minute,
        'concurrency',ap.concurrency,'last_tested_at',ap.last_tested_at,'last_test_status',ap.last_test_status,
        'billing_config',security.layer2_provider_sanitise_json(ap.billing_config),
        'attempts',(select count(*) from pipeline.layer2_provider_attempts a where a.acquisition_provider_id=ap.id),
        'successes',(select count(*) from pipeline.layer2_provider_attempts a where a.acquisition_provider_id=ap.id and a.status in ('completed','success','succeeded')),
        'failures',(select count(*) from pipeline.layer2_provider_attempts a where a.acquisition_provider_id=ap.id and a.status in ('failed','error','blocked')),
        'http_429',(select count(*) from pipeline.layer2_provider_attempts a where a.acquisition_provider_id=ap.id and a.response_http_status=429),
        'avg_response_ms',(select round(avg(extract(epoch from (a.completed_at-a.started_at))*1000)) from pipeline.layer2_provider_attempts a where a.acquisition_provider_id=ap.id and a.completed_at is not null and a.started_at is not null),
        'last_success_at',(select max(a.completed_at) from pipeline.layer2_provider_attempts a where a.acquisition_provider_id=ap.id and a.status in ('completed','success','succeeded')),
        'recent_failure_streak',(select count(*) from (select a.status from pipeline.layer2_provider_attempts a where a.acquisition_provider_id=ap.id order by a.created_at desc limit 10) z where z.status in ('failed','error','blocked'))
      ) order by ap.priority,ap.display_name),'[]'::jsonb) from pipeline.layer2_acquisition_providers ap where ap.enabled=true),
      'recent_runs',(select coalesce(jsonb_agg(jsonb_build_object(
        'id',b.id,'profile_id',b.profile_id,'trigger_type',b.trigger_type,'status',b.status,'target_count',b.target_count,
        'processed_count',b.processed_count,'resolved_l2_count',b.resolved_l2_count,'escalated_l3_count',b.escalated_l3_count,
        'blocked_count',b.blocked_count,'vendor_units',b.vendor_units,'vendor_cost_usd',b.vendor_cost_usd,'created_at',b.created_at,
        'started_at',b.started_at,'completed_at',b.completed_at,'heartbeat_at',b.heartbeat_at,'updated_at',b.updated_at,
        'runtime_seconds',case when b.started_at is null then null else round(extract(epoch from (coalesce(b.completed_at,now())-b.started_at))) end,
        'progress_percent',case when b.target_count>0 then round((100.0*b.processed_count/b.target_count)::numeric,1) else 0 end
      ) order by b.created_at desc),'[]'::jsonb) from (select * from pipeline.layer2_run_batches order by created_at desc limit 20)b),
      'outcomes',(select jsonb_build_object(
        'queued',count(*) filter(where status='queued'),'processing',count(*) filter(where status in ('discovering','acquiring','extracting')),
        'enriched',count(*) filter(where status='resolved_l2'),'unresolved',count(*) filter(where status='layer3_required'),
        'failed',count(*) filter(where status='blocked'),'deferred',count(*) filter(where status='cancelled'),
        'fields_targeted',coalesce(sum(fields_targeted),0),'fields_resolved',coalesce(sum(fields_resolved),0)
      ) from pipeline.layer2_run_items),
      'demo_firecrawl_attempt',(
        select to_jsonb(x)
        from (
          select a.id,a.job_id,ap.provider_key,ap.display_name provider_name,
                 a.attempt_no,a.status,a.request_url,a.response_http_status,
                 a.response_mime_type,
                 coalesce(a.html_evidence_id,a.raw_evidence_id,a.screenshot_evidence_id) evidence_id,
                 a.started_at,a.completed_at,p.profile_key
          from pipeline.layer2_provider_attempts a
          join pipeline.layer2_acquisition_providers ap on ap.id=a.acquisition_provider_id
          join pipeline.layer2_source_profile_versions pv on pv.id=a.profile_version_id
          join pipeline.layer2_source_profiles p on p.id=pv.profile_id
          where ap.provider_key='firecrawl'
            and a.status in ('completed','success','succeeded')
            and p.domain='course_facts'
            and p.enabled and not p.paused
            and exists(
              select 1 from pipeline.refresh_policies rp
              where rp.source_profile_id=p.id and rp.layer=2 and rp.enabled
            )
            and coalesce(a.html_evidence_id,a.raw_evidence_id,a.screenshot_evidence_id) is not null
          order by a.completed_at desc nulls last
          limit 1
        ) x
      ),
      'recent_provider_attempts',(
        select coalesce(jsonb_agg(to_jsonb(x) order by x.completed_at desc nulls last),'[]'::jsonb)
        from (
          select a.id,a.job_id,ap.provider_key,ap.display_name provider_name,
                 a.attempt_no,a.status,a.request_url,a.response_http_status,
                 a.response_mime_type,a.raw_evidence_id,a.html_evidence_id,
                 a.screenshot_evidence_id,
                 coalesce(a.html_evidence_id,a.raw_evidence_id,a.screenshot_evidence_id) evidence_id,
                 a.started_at,a.completed_at
          from pipeline.layer2_provider_attempts a
          join pipeline.layer2_acquisition_providers ap on ap.id=a.acquisition_provider_id
          order by a.completed_at desc nulls last,a.created_at desc
          limit 5
        ) x
      ),
      'evidence_summary',(select jsonb_build_object('count',count(*),'unreviewed',count(*) filter(where review_state='unreviewed'),'retained_until_365',count(*) filter(where retention_class='standard_365'),'held',count(*) filter(where retention_class='hold'),'latest',max(captured_at)) from pipeline.evidence_artifacts where coalesce(metadata->>'layer','')='2'),
      'scope_summary',jsonb_build_object(
        'authorised_country_codes',jsonb_build_array('AU'),
        'nz_layer2_course_status','DEFERRED — source qualification/onboarding required',
        'course_catalogue_total',(select count(*) from catalogue.courses cc join catalogue.providers cp2 on cp2.id=cc.provider_id where cp2.canonical_name in ('Federation University Australia','RMIT University (RMIT)','The University of Queensland')),
        'course_queueable_total',(select count(*) from catalogue.courses cc where exists(select 1 from pipeline.layer2_source_profiles p2 join pipeline.sources s2 on s2.id=p2.source_id where p2.domain='course_facts' and p2.enabled and not p2.paused and s2.provider_id=cc.provider_id) and (nullif(cc.course_url,'') is not null or exists(select 1 from pipeline.layer2_course_discovery_candidates dc where dc.course_id=cc.id and dc.selected and nullif(dc.discovered_url,'') is not null)))
      )
    ) into v_result;
    return v_result;
  end if;
  if p_operation='layer2_ops_run_detail' then
    return (select jsonb_build_object('run',to_jsonb(b),'items',(select coalesce(jsonb_agg(to_jsonb(i) order by i.created_at),'[]'::jsonb) from pipeline.layer2_run_items i where i.batch_id=b.id)) from pipeline.layer2_run_batches b where b.id=nullif(p_args->>'id','')::uuid);
  end if;
  raise exception 'unsupported layer2 ops read operation: %',p_operation using errcode='22023';
end $$;


ALTER FUNCTION "security"."admin_layer2_ops_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer2_parent_runs"("p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank integer:=0; v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;

  with recent as (
    select r.*
    from pipeline.layer2_scope_wave_requests r
    order by r.created_at desc
    limit greatest(1,least(coalesce(p_limit,10),50))
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'parent_run_id',coalesce(r.metadata->>'parent_run_id',r.id::text),
    'scope_wave_request_id',r.id,
    'status',r.status,
    'country_code',r.country_code,
    'scope_type',r.scope_type,
    'scope_id',r.scope_id,
    'route_mode',r.route_mode,
    'total_items',r.total_items,
    'dispatched_items',r.dispatched_items,
    'completed_items',r.completed_items,
    'failed_items',greatest(r.failed_items-coalesce(classify.acceptance_isolation_items,0),0),
    'recorded_failed_items',r.failed_items,
    'rescheduled_items',coalesce(classify.acceptance_isolation_items,0),
    'acceptance_isolation_items',coalesce(classify.acceptance_isolation_items,0),
    'scheduled_remainder',greatest(r.total_items-r.completed_items-r.failed_items,0),
    'last_wave_at',r.last_wave_at,
    'next_wave_not_before',r.next_wave_not_before,
    'created_at',r.created_at,
    'updated_at',r.updated_at,
    'child_batches',coalesce(items.child_batches,0),
    'active_batches',coalesce(items.active_batches,0),
    'cancelled_batches',coalesce(hist.cancelled_batches,0),
    'processed_items',r.completed_items+r.failed_items,
    'resolved_l2',coalesce(items.resolved_l2,0),
    'escalated_l3',coalesce(items.escalated_l3,0),
    'blocked',coalesce(items.blocked,0),
    'vendor_units',coalesce(items.vendor_units,0),
    'vendor_cost_usd',coalesce(items.vendor_cost_usd,0),
    'heartbeat_at',items.heartbeat_at,
    'historical_cancelled_processed',coalesce(hist.historical_cancelled_processed,0),
    'child_jobs',coalesce(items.child_jobs,0),
    'evidence_count',coalesce(ev.evidence_count,0),
    'latest_evidence_at',ev.latest_evidence_at
  ) order by r.created_at desc),'[]'::jsonb)
  into v_result
  from recent r
  left join lateral (
    select
      count(distinct wi.batch_id) filter(where wi.batch_id is not null)::int child_batches,
      count(distinct b.id) filter(where b.status in('queued','running'))::int active_batches,
      count(*) filter(where i.status='resolved_l2')::int resolved_l2,
      count(*) filter(where i.status='layer3_required')::int escalated_l3,
      count(*) filter(where i.status='blocked')::int blocked,
      coalesce(sum(i.vendor_units),0) vendor_units,
      coalesce(sum(i.vendor_cost_usd),0) vendor_cost_usd,
      max(b.heartbeat_at) heartbeat_at,
      count(distinct i.job_id) filter(where i.job_id is not null)::int child_jobs
    from pipeline.layer2_scope_wave_items wi
    left join pipeline.layer2_run_batches b on b.id=wi.batch_id
    left join pipeline.layer2_run_items i
      on i.batch_id=wi.batch_id and i.entity_id=wi.course_id
    where wi.request_id=r.id
      and wi.status in('dispatched','completed','failed')
  ) items on true
  left join lateral (
    select
      count(distinct e.id)::int evidence_count,
      max(e.captured_at) latest_evidence_at
    from pipeline.layer2_scope_wave_items wi
    join pipeline.layer2_run_items i
      on i.batch_id=wi.batch_id and i.entity_id=wi.course_id
    join pipeline.evidence_artifacts e on e.job_id=i.job_id
    where wi.request_id=r.id
      and wi.status in('dispatched','completed','failed')
  ) ev on true
  left join lateral (
    select
      count(*) filter(
        where wi.status='failed'
          and (
            lower(coalesce(wi.blocker,'')) like '%acceptance%isolation%'
            or exists(
              select 1
              from pipeline.layer2_run_items ai
              where ai.batch_id=wi.batch_id
                and lower(coalesce(ai.blocker,'')) like '%acceptance isolation%'
            )
          )
      )::int acceptance_isolation_items
    from pipeline.layer2_scope_wave_items wi
    where wi.request_id=r.id
  ) classify on true
  left join lateral (
    select
      count(*) filter(where b.status='cancelled')::int cancelled_batches,
      coalesce(sum(b.processed_count) filter(where b.status='cancelled'),0)::int historical_cancelled_processed
    from pipeline.layer2_run_batches b
    where b.policy_snapshot->>'scope_wave_request_id'=r.id::text
  ) hist on true;

  return v_result;
end $$;


ALTER FUNCTION "security"."admin_layer2_parent_runs"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer2_provider_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$declare v_rank int;v_id uuid;v_result jsonb;begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501';end if;select security.current_role_rank() into v_rank;if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501';end if;
 if p_operation='layer2_acquisition_providers' then select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'provider_key',p.provider_key,'display_name',p.display_name,'adapter_type',p.adapter_type,'base_url',p.base_url,'auth_scheme',p.auth_scheme,'auth_field_name',p.auth_field_name,'credential_configured',p.vault_secret_id is not null,'capabilities',security.layer2_provider_sanitise_json(p.capabilities),'request_template',security.layer2_provider_sanitise_json(p.request_template),'billing_config',security.layer2_provider_sanitise_json(p.billing_config),'estimated_request_cost_usd',security.layer2_provider_effective_cost_usd(p.billing_config,1),'enabled',p.enabled,'priority',p.priority,'rate_limit_per_minute',p.rate_limit_per_minute,'concurrency',p.concurrency,'timeout_seconds',p.timeout_seconds,'last_tested_at',p.last_tested_at,'last_test_status',p.last_test_status,'last_test_http_status',p.last_test_http_status,'last_test_error',p.last_test_error,'operational_owner',p.operational_owner,'change_control_ref',p.change_control_ref,'route_count',(select count(*) from pipeline.layer2_profile_provider_routes r where r.acquisition_provider_id=p.id)) order by p.priority,p.display_name),'[]'::jsonb) into v_result from pipeline.layer2_acquisition_providers p;return v_result;end if;
 if p_operation='layer2_provider_routes' then v_id:=nullif(p_args->>'profile_id','')::uuid;select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'profile_id',r.profile_id,'provider_id',p.id,'provider_key',p.provider_key,'display_name',p.display_name,'adapter_type',p.adapter_type,'priority',r.priority,'enabled',r.enabled,'credential_configured',p.vault_secret_id is not null,'capabilities',security.layer2_provider_sanitise_json(p.capabilities),'required_capabilities',security.layer2_provider_sanitise_json(r.required_capabilities),'request_overrides',security.layer2_provider_sanitise_json(r.request_overrides),'evidence_policy',r.evidence_policy,'fallback_on',r.fallback_on,'last_test_status',p.last_test_status,'estimated_request_cost_usd',security.layer2_provider_effective_cost_usd(p.billing_config,1)) order by r.priority),'[]'::jsonb) into v_result from pipeline.layer2_profile_provider_routes r join pipeline.layer2_acquisition_providers p on p.id=r.acquisition_provider_id where r.profile_id=v_id;return v_result;end if;
 if p_operation='layer2_provider_attempts' then v_id:=nullif(p_args->>'job_id','')::uuid;select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'job_id',a.job_id,'attempt_no',a.attempt_no,'status',a.status,'provider_key',p.provider_key,'display_name',p.display_name,'response_http_status',a.response_http_status,'response_mime_type',a.response_mime_type,'raw_evidence_id',a.raw_evidence_id,'html_evidence_id',a.html_evidence_id,'screenshot_evidence_id',a.screenshot_evidence_id,'extraction_status',a.extraction_status,'blocker',a.blocker,'metrics',security.layer2_provider_sanitise_json(a.metrics),'started_at',a.started_at,'completed_at',a.completed_at) order by a.attempt_no),'[]'::jsonb) into v_result from pipeline.layer2_provider_attempts a join pipeline.layer2_acquisition_providers p on p.id=a.acquisition_provider_id where a.job_id=v_id;return v_result;end if;
 raise exception 'unsupported Layer 2 provider read operation' using errcode='22023';end$$;


ALTER FUNCTION "security"."admin_layer2_provider_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer3_control_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'cron', 'security'
    AS $$
declare v jsonb;
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  select jsonb_build_object(
    'generated_at', now(),
    'can_control', security.current_role_rank()>=5,
    'credit', (select jsonb_build_object('remaining_usd',round(remaining_usd,2),'observed_at',observed_at) from pipeline.layer3_openrouter_observations where kind='credits' order by observed_at desc limit 1),
    'tasks', (select jsonb_agg(jsonb_build_object(
        'task_class', b.task_class,
        'label', case b.task_class when 'provider_intake_validation' then 'Intakes' when 'provider_english_validation' then 'English requirements' else 'Tuition' end,
        'running', coalesce((select j.active from cron.job j where j.jobname=security.layer3_task_job(b.task_class)),false),
        'cascade', b.route_mode='ladder',
        'daily_usd', b.daily_usd_max,
        'spent_today_usd', round(coalesce((select sum(i.estimated_cost_usd) from pipeline.layer3_interpretations i where i.task_class=b.task_class and i.created_at>=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC'),0),4),
        'last_24h', (select jsonb_build_object('admitted',count(*) filter (where w.status='admitted'),'to_review',count(*) filter (where w.status='layer4_required'),
                       'not_stated',count(*) filter (where w.status='no_candidate'),'retrying',count(*) filter (where w.status in ('failed','pending')))
                       from pipeline.layer3_work_items w where w.task_class=b.task_class and w.updated_at>=now()-interval '24 hours'),
        'in_review', (select count(*) from pipeline.layer4_review_items l where l.status='pending' and l.layer3_interpretation_id is not null
                        and l.field_code=case b.task_class when 'provider_intake_validation' then 'course_intake' when 'provider_english_validation' then 'course_english' else 'provider_current_tuition_validation' end),
        'tiers', case when b.route_mode='ladder' then (select coalesce(jsonb_agg(jsonb_build_object(
              'tier', t.tier_no, 'active', t.active, 'final', t.is_final, 'profile', p.code, 'model', p.model_identifier,
              'cost_per_1000_usd', round(t.cost_per_call_usd*1000,2), 'test_right_pct', round(t.h1_success_rate*100,1), 'test_wrong', t.h1_wrong_admitted,
              'answered_24h', (select count(*) from pipeline.layer3_interpretations i where i.task_class=b.task_class and i.profile_id=t.profile_id and i.created_at>=now()-interval '24 hours' and i.status in ('validated','no_candidate')),
              'passed_up_24h', (select count(*) from pipeline.layer3_interpretations i where i.task_class=b.task_class and i.profile_id=t.profile_id and i.created_at>=now()-interval '24 hours' and i.status='escalated'),
              'cost_24h_usd', (select round(coalesce(sum(i.estimated_cost_usd),0),4) from pipeline.layer3_interpretations i where i.task_class=b.task_class and i.profile_id=t.profile_id and i.created_at>=now()-interval '24 hours'),
              'audits', (select jsonb_build_object('checked',count(*),'disagreed',count(*) filter (where not a.agree)) from pipeline.layer3_tier_audits a where a.profile_id=t.profile_id and a.task_class=b.task_class)
            ) order by t.tier_no),'[]'::jsonb) from pipeline.layer3_route_tiers t join pipeline.layer3_model_profiles p on p.id=t.profile_id where t.task_class=b.task_class and p.enabled and not p.paused and p.retired_at is null)
          else (select coalesce(jsonb_agg(jsonb_build_object('tier',1,'active',true,'final',true,'profile',p.code,'model',p.model_identifier,
              'cost_per_1000_usd', round(coalesce((security.layer3_tier_evidence(b.task_class,p.id)->>'cost_per_call_usd')::numeric,0)*1000,2),
              'test_right_pct', (security.layer3_tier_evidence(b.task_class,p.id)->>'right_pct')::numeric, 'test_wrong', (security.layer3_tier_evidence(b.task_class,p.id)->>'wrong')::int,
              'answered_24h', (select count(*) from pipeline.layer3_interpretations i where i.task_class=b.task_class and i.profile_id=p.id and i.created_at>=now()-interval '24 hours'),
              'passed_up_24h', 0, 'cost_24h_usd', (select round(coalesce(sum(i.estimated_cost_usd),0),4) from pipeline.layer3_interpretations i where i.task_class=b.task_class and i.profile_id=p.id and i.created_at>=now()-interval '24 hours'))),'[]'::jsonb)
              from pipeline.layer3_model_profiles p where b.task_class=any(p.allowed_task_classes) and p.enabled and not p.paused and p.retired_at is null
               and coalesce((p.quality_benchmark->>'pass')::boolean,false)) end,
        'addable', case when b.route_mode='ladder' then (select coalesce(jsonb_agg(jsonb_build_object('profile',p.code,'model',p.model_identifier,
              'test_right_pct',(e->>'right_pct')::numeric,'test_wrong',(e->>'wrong')::int,'cost_per_1000_usd',round((e->>'cost_per_call_usd')::numeric*1000,2)) order by (e->>'cost_per_call_usd')::numeric),'[]'::jsonb)
            from pipeline.layer3_model_profiles p cross join lateral (select security.layer3_tier_evidence(b.task_class,p.id) e) x
           where b.task_class=any(p.allowed_task_classes) and coalesce((e->>'eligible')::boolean,false)
             and not exists (select 1 from pipeline.layer3_route_tiers t where t.task_class=b.task_class and t.profile_id=p.id)) else '[]'::jsonb end
      ) order by case b.task_class when 'provider_intake_validation' then 1 when 'provider_english_validation' then 2 else 3 end)
      from pipeline.layer3_route_budget b),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('at',e.created_at,'kind',e.kind,'detail',e.detail) order by e.created_at desc),'[]'::jsonb)
                 from (select * from pipeline.layer3_route_events order by created_at desc limit 12) e)
  ) into v;
  return v;
end $$;


ALTER FUNCTION "security"."admin_layer3_control_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer3_control_v1"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'cron', 'security'
    AS $_$
declare v_task text:=p_args->>'task'; v_tier int:=nullif(p_args->>'tier','')::int; v_on boolean:=(p_args->>'running')::boolean; t record; n record; p record; e jsonb; v_job text;
begin
  if auth.uid() is null or security.current_role_rank()<5 then raise exception 'Platform Admin role required' using errcode='42501'; end if;
  if v_task is not null and not exists (select 1 from pipeline.layer3_route_budget where task_class=v_task) then raise exception 'unknown task'; end if;
  if p_action='run_task' then
    v_job:=security.layer3_task_job(v_task); perform cron.alter_job(j.jobid, active => v_on) from cron.job j where j.jobname=v_job;
  elsif p_action='run_all' then
    perform cron.alter_job(j.jobid, active => v_on) from cron.job j where j.jobname in ('layer3-intake-route','layer3-english-route','layer3-tuition-dispatch');
  elsif p_action='budget' then
    if (p_args->>'daily_usd')::numeric not between 0 and 100 then raise exception 'daily limit must be US$0-100'; end if;
    update pipeline.layer3_route_budget set daily_usd_max=(p_args->>'daily_usd')::numeric where task_class=v_task;
  elsif p_action in ('tier_active','tier_move','tier_remove') then
    select * into t from pipeline.layer3_route_tiers where task_class=v_task and tier_no=v_tier;
    if t.id is null then raise exception 'no such cascade step'; end if;
    if p_action='tier_active' then
      if not (p_args->>'active')::boolean and (select count(*) from pipeline.layer3_route_tiers where task_class=v_task and active and id<>t.id)=0 then raise exception 'at least one cascade step must stay on'; end if;
      update pipeline.layer3_route_tiers set active=(p_args->>'active')::boolean, updated_at=now() where id=t.id;
    elsif p_action='tier_move' then
      select * into n from pipeline.layer3_route_tiers where task_class=v_task and tier_no=v_tier+case p_args->>'direction' when 'up' then -1 else 1 end;
      if n.id is null then raise exception 'cannot move further'; end if;
      update pipeline.layer3_route_tiers set tier_no=-1 where id=t.id;
      update pipeline.layer3_route_tiers set tier_no=t.tier_no, updated_at=now() where id=n.id;
      update pipeline.layer3_route_tiers set tier_no=n.tier_no, updated_at=now() where id=t.id;
    else
      if (select count(*) from pipeline.layer3_route_tiers where task_class=v_task and active and id<>t.id)=0 then raise exception 'at least one cascade step must stay'; end if;
      delete from pipeline.layer3_route_tiers where id=t.id;
    end if;
    perform security.layer3_renumber_tiers(v_task);
  elsif p_action='tier_add' then
    select * into p from pipeline.layer3_model_profiles where code=p_args->>'profile';
    if p.id is null or not (v_task=any(p.allowed_task_classes)) then raise exception 'model profile not set up for this task'; end if;
    if exists (select 1 from pipeline.layer3_route_tiers where task_class=v_task and profile_id=p.id) then raise exception 'model already in the cascade'; end if;
    if not (p.enabled and not p.paused and p.retired_at is null) then raise exception 'switch this model on in Platform settings › Models & services first'; end if;
    e:=security.layer3_tier_evidence(v_task,p.id);
    if not coalesce((e->>'eligible')::boolean,false) then raise exception 'model has not passed the tier rule (>= 80%% right and 0 wrong on the frozen test pages): %', e; end if;
    insert into pipeline.layer3_route_tiers(task_class,tier_no,profile_id,min_success,cost_per_call_usd,h1_success_rate,h1_wrong_admitted,is_final,qualified_by,active)
    values (v_task,(select coalesce(max(tier_no),0)+1 from pipeline.layer3_route_tiers where task_class=v_task),p.id,0.80,(e->>'cost_per_call_usd')::numeric,
            round((e->>'right')::numeric/(e->>'cases')::numeric,4),(e->>'wrong')::int,false,e||jsonb_build_object('added_by',auth.uid(),'added_at',now()),true);
    perform security.layer3_renumber_tiers(v_task);
  else raise exception 'unknown action %', p_action;
  end if;
  insert into pipeline.layer3_route_events(kind,detail) values ('admin_'||p_action, p_args||jsonb_build_object('by',auth.uid()));
  return security.admin_layer3_control_read_v1();
end $_$;


ALTER FUNCTION "security"."admin_layer3_control_v1"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer3_operations_read_v1"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security', 'auth'
    AS $$
declare
  v_days integer := least(greatest(coalesce(nullif(p_args->>'days','')::integer,14),1),60);
  v_today timestamptz := date_trunc('day', now());
  v_profiles jsonb; v_routing jsonb; v_tests jsonb; v_spend jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 3 then
    raise exception 'curator role required' using errcode='42501';
  end if;

  with p as (
    select pr.*, to_jsonb(pr) as j,
           (to_jsonb(pr)->>'retired_at') is not null
             or coalesce((pr.last_validation_result->>'retired')::boolean,false) as is_retired
      from pipeline.layer3_model_profiles pr
  ), usage as (
    select i.profile_id, sum(coalesce(i.external_call_count,0))::bigint calls, coalesce(sum(i.estimated_cost_usd),0) cost
      from pipeline.layer3_interpretations i
     where i.created_at >= v_today and coalesce(i.status,'') <> 'cancelled'
     group by i.profile_id
  ), last_test as (
    select distinct on (b.profile_id) b.profile_id, b.status, b.summary, b.created_at, b.estimated_cost_usd
      from pipeline.layer3_quality_benchmark_runs b
     order by b.profile_id, b.created_at desc
  )
  select coalesce(jsonb_agg(
           (p.j - 'prompt_system' - 'structured_output_schema' - 'deterministic_validators' - 'secret_env_key')
           || jsonb_build_object(
                'is_retired', p.is_retired,
                'qualified', p.enabled and not p.paused and coalesce((p.quality_benchmark->>'pass')::boolean,false) and not p.is_retired,
                'state', case when p.is_retired then 'retired'
                              when p.enabled and not p.paused and coalesce((p.quality_benchmark->>'pass')::boolean,false) then 'active'
                              else 'candidate' end,
                'fallback_code', (select f.code from pipeline.layer3_model_profiles f where f.id = p.fallback_profile_id),
                'calls_today', coalesce(u.calls,0),
                'spend_today_usd', coalesce(u.cost,0),
                'last_test', case when t.profile_id is null then null else jsonb_build_object('status',t.status,'summary',t.summary,'at',t.created_at,'cost_usd',t.estimated_cost_usd) end)
           order by p.is_retired, p.code), '[]'::jsonb)
    into v_profiles
    from p left join usage u on u.profile_id = p.id left join last_test t on t.profile_id = p.id;

  -- Routing: the profile the dispatcher would use for each task class (same rule as layer3_dispatch_headroom_service).
  with p as (
    select pr.*, (to_jsonb(pr)->>'retired_at') is not null
             or coalesce((pr.last_validation_result->>'retired')::boolean,false) as is_retired
      from pipeline.layer3_model_profiles pr
  ), classes as (
    select distinct unnest(allowed_task_classes) task_class from p
    union select distinct task_class from pipeline.layer3_work_items where task_class is not null
  ), active as (
    select c.task_class, a.*
      from classes c
      left join lateral (
        select p.id, p.code, p.model_identifier, p.fallback_profile_id, p.cost_ceiling_usd, p.requests_per_day
          from p
         where c.task_class = any(p.allowed_task_classes) and p.enabled and not p.paused
           and coalesce((p.quality_benchmark->>'pass')::boolean,false) and not p.is_retired
         order by p.updated_at desc, p.id limit 1) a on true
  ), today as (
    select task_class, sum(coalesce(external_call_count,0))::bigint calls, coalesce(sum(estimated_cost_usd),0) cost
      from pipeline.layer3_interpretations
     where created_at >= v_today and coalesce(status,'') <> 'cancelled'
     group by task_class
  ), queue as (
    select task_class,
           count(*) filter (where status in ('pending','reserved','interpreting','validated','admission_pending')) open_items,
           count(*) filter (where status = 'layer4_required') layer4_items
      from pipeline.layer3_work_items group by task_class
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'task_class', a.task_class,
           'status', case when a.id is null then 'no_qualified_model' else 'active' end,
           'active_profile_id', a.id, 'active_code', a.code, 'active_model', a.model_identifier,
           'fallback_code', (select f.code from pipeline.layer3_model_profiles f where f.id = a.fallback_profile_id),
           'fallback_model', (select f.model_identifier from pipeline.layer3_model_profiles f where f.id = a.fallback_profile_id),
           'candidates', (select count(*) from p where a.task_class = any(p.allowed_task_classes) and not p.is_retired),
           'calls_today', coalesce(t.calls,0), 'spend_today_usd', coalesce(t.cost,0),
           'requests_per_day', a.requests_per_day, 'cost_ceiling_usd', a.cost_ceiling_usd,
           'open_items', coalesce(q.open_items,0), 'layer4_items', coalesce(q.layer4_items,0))
           order by (a.id is null), a.task_class), '[]'::jsonb)
    into v_routing
    from active a left join today t on t.task_class = a.task_class left join queue q on q.task_class = a.task_class;

  -- Test results: the latest benchmark runs, scored the same way for every task class.
  with b as (
    select r.*, case when jsonb_typeof(r.provider_case_results)='array' then r.provider_case_results else '[]'::jsonb end pc,
                case when jsonb_typeof(r.control_case_results)='array' then r.control_case_results else '[]'::jsonb end cc
      from pipeline.layer3_quality_benchmark_runs r
     order by r.created_at desc limit 80
  ), scored as (
    select b.*,
      (select count(*) from jsonb_array_elements(b.pc) x) stated_total,
      (select count(*) from jsonb_array_elements(b.pc) x
        where coalesce((x->>'layer3_exact')::boolean, (x->>'semantic_result')::boolean and (x->>'valid')::boolean, false)) stated_exact,
      (select count(*) from jsonb_array_elements(b.pc) x
        where x->>'layer3_status' = 'not_stated' or (x ? 'candidate_value' and jsonb_typeof(x->'candidate_value') = 'null')) withheld,
      (select count(*) from jsonb_array_elements(b.pc) x
        where coalesce((x->>'layer3_valid')::boolean,(x->>'valid')::boolean,false)
          and not coalesce((x->>'layer3_exact')::boolean, (x->>'semantic_result')::boolean and (x->>'valid')::boolean, false)
          and coalesce(x->>'layer3_status','') <> 'not_stated'
          and not (x ? 'candidate_value' and jsonb_typeof(x->'candidate_value') = 'null'))
      + (select count(*) from jsonb_array_elements(b.cc) x
        where (jsonb_typeof(x->'invented_months')='array' and jsonb_array_length(x->'invented_months') > 0)
           or (coalesce(x->>'expected_outcome','') like '%abstention%' and x ? 'candidate_value' and jsonb_typeof(x->'candidate_value') <> 'null')) wrong_admitted,
      (select count(*) from jsonb_array_elements(b.cc) x) control_total
      from b
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'profile_id', s.profile_id,
           'profile_code', (select m.code from pipeline.layer3_model_profiles m where m.id = s.profile_id),
           'model', s.configured_model, 'status', s.status,
           'stated_total', s.stated_total, 'stated_exact', s.stated_exact, 'withheld', s.withheld,
           'wrong_admitted', s.wrong_admitted, 'control_total', s.control_total,
           'calls', s.external_call_count, 'cost_usd', s.estimated_cost_usd,
           'summary', s.summary, 'at', coalesce(s.completed_at, s.created_at))
           order by s.created_at desc), '[]'::jsonb)
    into v_tests from scored s;

  -- Spend per day and profile: live interpretation calls plus test (benchmark) calls.
  with live as (
    select date_trunc('day', created_at)::date d, profile_id, sum(coalesce(external_call_count,0))::bigint calls, coalesce(sum(estimated_cost_usd),0) cost
      from pipeline.layer3_interpretations
     where created_at >= v_today - make_interval(days => v_days - 1) and coalesce(status,'') <> 'cancelled'
     group by 1,2
  ), test as (
    select date_trunc('day', created_at)::date d, profile_id, sum(coalesce(external_call_count,0))::bigint calls, coalesce(sum(estimated_cost_usd),0) cost
      from pipeline.layer3_quality_benchmark_runs
     where created_at >= v_today - make_interval(days => v_days - 1)
     group by 1,2
  ), keys as (select d, profile_id from live union select d, profile_id from test)
  select coalesce(jsonb_agg(jsonb_build_object(
           'day', k.d, 'profile_id', k.profile_id, 'profile_code', m.code, 'model', m.model_identifier,
           'live_calls', coalesce(l.calls,0), 'live_cost_usd', coalesce(l.cost,0),
           'test_calls', coalesce(t.calls,0), 'test_cost_usd', coalesce(t.cost,0),
           'cost_ceiling_usd', m.cost_ceiling_usd, 'requests_per_day', m.requests_per_day)
           order by k.d desc, m.code), '[]'::jsonb)
    into v_spend
    from keys k
    left join live l on l.d = k.d and l.profile_id is not distinct from k.profile_id
    left join test t on t.d = k.d and t.profile_id is not distinct from k.profile_id
    left join pipeline.layer3_model_profiles m on m.id = k.profile_id;

  return jsonb_build_object('generated_at', now(), 'days', v_days,
    'profiles', v_profiles, 'routing', v_routing, 'tests', v_tests, 'spend', v_spend);
end
$$;


ALTER FUNCTION "security"."admin_layer3_operations_read_v1"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer_status_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$
declare v_rank integer; v_payload jsonb; v_at timestamptz;
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank(); if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
 select payload, computed_at into v_payload, v_at from security.admin_summary_snapshots
 where snapshot_key='layer_status_summary' and computed_at > now() - interval '10 minutes';
 if v_payload is not null then
   return v_payload || jsonb_build_object('snapshot_at', v_at, 'snapshot_source', 'snapshot');
 end if;
 return security.admin_layer_status_summary_compute() || jsonb_build_object('snapshot_at', now(), 'snapshot_source', 'live');
end $$;


ALTER FUNCTION "security"."admin_layer_status_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_layer_status_summary_compute"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'scholarship', 'auth'
    AS $$
begin
 return jsonb_build_object(
  'layer1',jsonb_build_object(
    'active_sources',(select count(*) from pipeline.sources where status='active' and coalesce(metadata->>'layer','')='1'),
    'running_jobs',(select count(*) from pipeline.jobs where job_type='regulatory_sync' and status='running'),
    'failed_24h',(select count(*) from pipeline.jobs where job_type='regulatory_sync' and status='failed' and created_at>now()-interval '24 hours'),
    'latest_activity',(select max(created_at) from pipeline.jobs where job_type='regulatory_sync')
  ),
  'layer2',jsonb_build_object(
    'active_batches',(select count(*) from pipeline.layer2_run_batches where status in('queued','running','partial')),
    'scheduled_wave_requests',(select count(*) from pipeline.layer2_scope_wave_requests where status in('scheduled','running','wave1_dispatched')),
    'wave_pending_courses',(select count(*) from pipeline.layer2_scope_wave_items where status='pending'),
    'processed_24h',(select count(*) from pipeline.layer2_run_items where completed_at>now()-interval '24 hours'),
    'evidence_24h',(select count(*) from pipeline.evidence_artifacts where coalesce(metadata->>'layer','') like '2%' and captured_at>now()-interval '24 hours')
  ),
  'layer3',jsonb_build_object(
    'qualified_profiles',(select count(*) from pipeline.layer3_model_profiles where enabled and not paused and coalesce((quality_benchmark->>'pass')::boolean,false)),
    'pending_evidence_candidates',(
      select count(distinct ri.entity_id)
      from pipeline.layer2_run_items ri
      join pipeline.layer2_provider_attempts pa on pa.job_id=ri.job_id and pa.status='succeeded'
      where ri.entity_type='course' and ri.status='layer3_required'
        and exists (
          select 1 from pipeline.evidence_artifacts e
          where e.id in (pa.raw_evidence_id,pa.html_evidence_id)
            and e.storage_path is not null and e.content_hash is not null
            and (e.valid_to is null or e.valid_to>now())
            and coalesce(e.review_state,'') not in ('rejected','invalid')
            and (e.mime_type is null or e.mime_type like 'text/%' or e.mime_type in ('application/json','application/xml','application/xhtml+xml'))
        )
    ),
    'interpretations_24h',(select count(*) from pipeline.layer3_interpretations where created_at>now()-interval '24 hours'),
    'calls_24h',(select coalesce(sum(external_call_count),0) from pipeline.layer3_interpretations where created_at>now()-interval '24 hours'),
    'tokens_24h',(select coalesce(sum(input_tokens+output_tokens),0) from pipeline.layer3_interpretations where created_at>now()-interval '24 hours'),
    'recorded_cost_24h',(select coalesce(sum(estimated_cost_usd),0) from pipeline.layer3_interpretations where created_at>now()-interval '24 hours')
  ),
  'layer4',jsonb_build_object(
    'pending_reviews',(select count(*) from pipeline.layer4_review_items where status='pending'),
    'active_overrides',(select count(*) from (
      select distinct on(entity_type,entity_id,field_code) event_type
      from pipeline.layer4_override_decisions order by entity_type,entity_id,field_code,created_at desc,id desc
    ) x where event_type<>'revert'),
    'publication_decisions',(select count(*) from pipeline.layer4_publication_decisions)
  ),
  'scholarships',jsonb_build_object(
    'scholarships',(select count(*) from scholarship.scholarships),
    'course_mappings',(select count(*) from scholarship.course_mappings where mapping_state='mapped'),
    'review_candidates',(select count(*) from scholarship.course_mapping_candidates where status='needs_review')
  )
 );
end $$;


ALTER FUNCTION "security"."admin_layer_status_summary_compute"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_live_activity_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 1 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  with runs as (
    select d.jobid, d.start_time, d.end_time, d.status, d.return_message,
           row_number() over (partition by d.jobid order by d.start_time desc) rn
      from cron.job_run_details d where d.start_time > now() - interval '2 days'),
  agg as (
    select jobid,
           count(*) filter (where start_time > now() - interval '24 hours') runs_24h,
           count(*) filter (where start_time > now() - interval '24 hours' and status = 'failed') failed_24h,
           bool_or(status in ('running','starting')) running
      from runs group by jobid),
  -- work left and done in 24 hours, for jobs that work through a queue
  q(jobname, unit, work_left, done_24h) as (
    select 'scholarship-discover', 'providers',
           (select count(*) from pipeline.scholarship_discovery_providers where status = 'pending' and attempts < 3),
           (select count(*) from pipeline.scholarship_discovery_providers where discovered_at > now() - interval '24 hours')
    union all select 'scholarship-read', 'pages',
           (select count(*) from pipeline.scholarship_pages p join scholarship.scholarships s on s.id = p.scholarship_id and s.lifecycle_status = 'active'
             where p.next_read_at <= now() and p.attempts < 5),
           (select count(*) from pipeline.scholarship_pages where read_at > now() - interval '24 hours')
    union all select 'provider-facts', 'searches and documents',
           (select count(*) from pipeline.provider_fact_search where state = 'queued') + (select count(*) from pipeline.provider_fact_sources where status = 'found' and attempts < 3),
           (select count(*) from pipeline.provider_fact_search where done_at > now() - interval '24 hours') + (select count(*) from pipeline.provider_fact_sources where read_at > now() - interval '24 hours')
    union all select 'course-link-search-worker', 'courses',
           (select count(*) from pipeline.course_link_search where state = 'queued'),
           (select count(*) from pipeline.course_link_search where done_at > now() - interval '24 hours')
    union all select 'coverage-read', 'course pages',
           (select count(*) from pipeline.coverage_course_pages where status in ('bound','ambiguous') and coalesce(next_read_at, now()) <= now() and read_attempts < 3),
           (select count(*) from pipeline.coverage_course_pages where read_at > now() - interval '24 hours')
    union all select 'layer3-intake-route', 'AI checks',
           (select count(*) from pipeline.layer3_work_items where task_class = 'provider_intake_validation' and status in ('pending','retry','reserved')),
           (select count(*) from pipeline.layer3_work_items where task_class = 'provider_intake_validation' and completed_at > now() - interval '24 hours')
    union all select 'layer3-english-route', 'AI checks',
           (select count(*) from pipeline.layer3_work_items where task_class = 'provider_english_validation' and status in ('pending','retry','reserved')),
           (select count(*) from pipeline.layer3_work_items where task_class = 'provider_english_validation' and completed_at > now() - interval '24 hours')
    union all select 'layer3-tuition-dispatch', 'AI checks',
           (select count(*) from pipeline.layer3_work_items where task_class = 'provider_current_tuition_validation' and status in ('pending','retry','reserved')),
           (select count(*) from pipeline.layer3_work_items where task_class = 'provider_current_tuition_validation' and completed_at > now() - interval '24 hours')
    union all select 'evidence-link-index', 'pages',
           (select count(*) from pipeline.evidence_artifacts e left join pipeline.evidence_link_index_state st on st.evidence_id = e.id
              join pipeline.sources s on s.id = e.source_id join pipeline.layer2_onboarding_snapshot o on o.provider_id = s.provider_id
             where e.storage_path is not null and e.storage_path !~ '^[a-z-]+://'
               and e.evidence_type in ('layer2_html_snapshot','layer2_extraction_input','source_snapshot','provider_contact_html_snapshot')
               and (e.mime_type ilike '%html%' or e.mime_type ilike '%json%')
               and (st.evidence_id is null or (st.status = 'error' and st.indexed_at < now() - interval '6 hours'))),
           (select count(*) from pipeline.evidence_link_index_state where status in ('indexed','no_links') and indexed_at > now() - interval '24 hours')),
  jobs as (
    select a.jobname, a.area, a.sort, a.label, a.description, j.schedule, j.active,
           coalesce(g.running, false) running, coalesce(g.runs_24h, 0) runs_24h, coalesce(g.failed_24h, 0) failed_24h,
           r.start_time last_start, r.end_time last_end, r.status last_status, left(r.return_message, 240) last_message,
           q.unit, q.work_left, q.done_24h,
           coalesce(substring(j.command from '"mode":"([a-z_]+)"'), case a.jobname when 'evidence-link-index' then 'evidence_link_index' end) worker_mode, substring(j.command from '"task":"([a-z_]+)"') worker_task
      from pipeline.automation_catalogue a join cron.job j on j.jobname = a.jobname
      left join agg g on g.jobid = j.jobid
      left join runs r on r.jobid = j.jobid and r.rn = 1
      left join q on q.jobname = a.jobname),
  -- the latest summary each coverage-sweep worker mode returned (kept a few hours by pg_net)
  worker as (
    select m.mode, m.task, x.content, x.created at
      from (select distinct worker_mode mode, worker_task task from jobs where worker_mode is not null) m
      left join lateral (select h.content, h.created from net._http_response h
                          where h.status_code = 200 and (case when m.mode = 'evidence_link_index' then h.content like '%"processed":%"summary":{"indexed"%' else h.content like '%"mode":"' || m.mode || '"%' end)
                            and (m.task is null or h.content like '%"task":"' || m.task || '"%')
                          order by h.created desc limit 1) x on true),
  pub as (select p.publishable, p.missing, s.publication_status, s.lifecycle_status
            from security.scholarship_publishability_v1() p join scholarship.scholarships s on s.id = p.scholarship_id)
  select jsonb_build_object(
    'now', now(),
    'jobs', (select jsonb_agg(jsonb_build_object(
        'job', j.jobname, 'area', j.area, 'label', j.label, 'description', j.description, 'schedule', j.schedule, 'active', j.active,
        'running', j.running, 'runs_24h', j.runs_24h, 'failed_24h', j.failed_24h,
        'last', jsonb_build_object('start', j.last_start, 'end', j.last_end, 'status', j.last_status, 'message', j.last_message),
        'queue', case when j.unit is null then null else jsonb_build_object('unit', j.unit, 'left', j.work_left, 'done_24h', j.done_24h) end,
        'worker', case when j.worker_mode is null then null else (select jsonb_build_object('mode', w.mode, 'at', w.at,
                   'result', security.live_worker_summary(w.content)) from worker w where w.mode = j.worker_mode and w.task is not distinct from j.worker_task) end)
        order by j.area, j.sort, j.jobname) from jobs j),
    'needs_person', jsonb_build_object(
        'fee_schedules', (select count(*) from pipeline.provider_fact_sources where kind = 'fee_schedule' and status = 'parsed' and decision is null),
        'layer4_reviews', (select count(*) from pipeline.layer4_review_items where status = 'pending'),
        'flagged_values', (select count(*) from pipeline.data_flags where status = 'open'),
        'ranking_links', (select count(*) from ranking.provider_mappings where status = 'candidate'),
        'scholarships_ready', (select count(*) from pub where publishable and coalesce(publication_status, 'unpublished') <> 'published'),
        'scholarships_domestic', (select count(*) from pub where lifecycle_status = 'active' and 'eligibility lists domestic students only' = any(missing))),
    'in_flight', (select count(*) from net.http_request_queue),
    -- Decision 215: replies from workers with an error status (pg_net keeps them a few hours)
    'worker_errors', (select coalesce(jsonb_agg(jsonb_build_object('function', x.fn, 'job', x.job, 'status', x.status_code, 'timed_out', x.timed_out, 'message', x.message, 'count', x.n, 'last', x.last) order by x.last desc), '[]'::jsonb)
                        from (select e.*, (select a.label from pipeline.automation_catalogue a join cron.job j on j.jobname = a.jobname
                                            where e.fn <> '' and j.command like '%''' || e.fn || '''%' and (e.mode is null or j.command like '%"mode":"' || e.mode || '"%')
                                            order by a.sort limit 1) job
                                from (select coalesce(l.function_name, '') fn, l.mode, h.status_code, h.timed_out, left(coalesce(h.error_msg, h.content), 200) message, count(*) n, max(h.created) last
                                        from net._http_response h left join pipeline.edge_request_log l on l.slot = (h.id % 50000)::int and l.request_id = h.id
                                       where h.status_code >= 400 or h.status_code is null
                                       group by 1, 2, 3, 4, 5) e
                               where not exists (select 1 from pipeline.live_error_acks k where k.function_name = e.fn and k.status_code = coalesce(e.status_code, -1)
                                                    and k.message_md5 = md5(e.message) and k.acked_at >= e.last)
                               order by e.last desc limit 10) x)
  ) into v;
  return v;
end $$;


ALTER FUNCTION "security"."admin_live_activity_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_operational_page"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'workflow', 'ref', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_query text:=nullif(trim(coalesce(p_args->>'query','')),'');
  v_sort text:=lower(coalesce(nullif(p_args->>'sort',''),'created'));
  v_dir text:=case when lower(coalesce(nullif(p_args->>'direction',''),'desc'))='asc' then 'asc' else 'desc' end;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;

  if p_operation='evidence_page' then
    if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
    with base as (
      select e.id,e.entity_id,e.source_id,e.job_id,e.evidence_type,
             s.label source_label,s.source_type,e.source_url,e.storage_path,e.content_hash,
             e.mime_type,e.captured_at,e.valid_from,e.valid_to,e.supersedes_evidence_id,e.metadata
      from pipeline.evidence_artifacts e
      left join pipeline.sources s on s.id=e.source_id
      where (v_query is null
        or e.id::text=v_query
        or coalesce(e.entity_id::text,'')=v_query
        or coalesce(e.source_id::text,'')=v_query
        or coalesce(e.job_id::text,'')=v_query
        or coalesce(e.content_hash,'')=v_query
        or coalesce(e.evidence_type,'') ilike '%'||v_query||'%'
        or coalesce(s.label,'') ilike '%'||v_query||'%'
        or coalesce(e.source_url,'') ilike '%'||v_query||'%'
        or coalesce(e.storage_path,'') ilike '%'||v_query||'%')
        and (nullif(p_args->>'source_id','') is null or e.source_id::text=p_args->>'source_id')
        and (nullif(p_args->>'evidence_type','') is null or e.evidence_type=p_args->>'evidence_type')
    ), numbered as (
      select *,count(*) over() total_count from base
    ), ordered as (
      select * from numbered order by
        case when v_sort in ('created','captured') and v_dir='asc' then captured_at end asc nulls last,
        case when v_sort in ('created','captured') and v_dir='desc' then captured_at end desc nulls last,
        case when v_sort='source' and v_dir='asc' then lower(coalesce(source_label,'')) end asc,
        case when v_sort='source' and v_dir='desc' then lower(coalesce(source_label,'')) end desc,
        case when v_sort='type' and v_dir='asc' then lower(coalesce(evidence_type,'')) end asc,
        case when v_sort='type' and v_dir='desc' then lower(coalesce(evidence_type,'')) end desc,
        captured_at desc nulls last,id
      limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),
      'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir,
      'filters',jsonb_build_object(
        'sources',coalesce((select jsonb_agg(jsonb_build_object('id',x.source_id,'name',x.source_label,'count',x.n) order by x.source_label) from (select e2.source_id,coalesce(s2.label,'Unknown source') source_label,count(*) n from pipeline.evidence_artifacts e2 left join pipeline.sources s2 on s2.id=e2.source_id group by e2.source_id,s2.label) x),'[]'::jsonb),
        'evidence_types',coalesce((select jsonb_agg(jsonb_build_object('code',x.evidence_type,'name',initcap(replace(x.evidence_type,'_',' ')),'count',x.n) order by x.evidence_type) from (select evidence_type,count(*) n from pipeline.evidence_artifacts where evidence_type is not null group by evidence_type) x),'[]'::jsonb)
      )
    ) into v_result from ordered o;
    return v_result;

  elsif p_operation='reviews_page' then
    if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
    with base as (
      select r.id,r.entity_id,r.domain,r.field_code,r.candidate_claim_id,r.previous_review_id,
             r.reopen_reason,r.priority,r.status,r.assigned_to,r.created_at,r.updated_at,r.closed_at
      from workflow.review_queue r
      where (v_query is null
        or r.id::text=v_query
        or coalesce(r.entity_id::text,'')=v_query
        or coalesce(r.candidate_claim_id::text,'')=v_query
        or coalesce(r.domain,'') ilike '%'||v_query||'%'
        or coalesce(r.field_code,'') ilike '%'||v_query||'%'
        or coalesce(r.reopen_reason,'') ilike '%'||v_query||'%')
        and (nullif(p_args->>'status','') is null or r.status=p_args->>'status')
        and (nullif(p_args->>'domain','') is null or r.domain=p_args->>'domain')
    ), numbered as (select *,count(*) over() total_count from base), ordered as (
      select * from numbered order by
        case when v_sort='priority' and v_dir='asc' then priority end asc,
        case when v_sort='priority' and v_dir='desc' then priority end desc,
        case when v_sort='status' and v_dir='asc' then lower(coalesce(status,'')) end asc,
        case when v_sort='status' and v_dir='desc' then lower(coalesce(status,'')) end desc,
        case when v_sort in ('created','updated') and v_dir='asc' then (case when v_sort='updated' then updated_at else created_at end) end asc,
        case when v_sort in ('created','updated') and v_dir='desc' then (case when v_sort='updated' then updated_at else created_at end) end desc,
        priority desc nulls last,created_at desc,id
      limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),
      'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir,
      'filters',jsonb_build_object(
        'statuses',coalesce((select jsonb_agg(jsonb_build_object('code',x.status,'name',initcap(replace(x.status,'_',' ')),'count',x.n) order by x.status) from (select status,count(*) n from workflow.review_queue where status is not null group by status) x),'[]'::jsonb),
        'domains',coalesce((select jsonb_agg(jsonb_build_object('code',x.domain,'name',initcap(replace(x.domain,'_',' ')),'count',x.n) order by x.domain) from (select domain,count(*) n from workflow.review_queue where domain is not null group by domain) x),'[]'::jsonb)
      )
    ) into v_result from ordered o;
    return v_result;

  elsif p_operation='jobs_page' then
    if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
    with base as (
      select j.id,j.job_type,j.domain,j.source_id,j.provider_id,j.entity_id,j.status,
             j.attempt_count,j.created_at,j.started_at,j.completed_at,j.error_text
      from pipeline.jobs j
      where (v_query is null
        or j.id::text=v_query
        or coalesce(j.source_id::text,'')=v_query
        or coalesce(j.provider_id::text,'')=v_query
        or coalesce(j.entity_id::text,'')=v_query
        or coalesce(j.job_type,'') ilike '%'||v_query||'%'
        or coalesce(j.domain,'') ilike '%'||v_query||'%'
        or coalesce(j.status,'') ilike '%'||v_query||'%'
        or coalesce(j.error_text,'') ilike '%'||v_query||'%')
        and (nullif(p_args->>'status','') is null or j.status=p_args->>'status')
        and (nullif(p_args->>'domain','') is null or j.domain=p_args->>'domain')
        and (nullif(p_args->>'job_type','') is null or j.job_type=p_args->>'job_type')
    ), numbered as (select *,count(*) over() total_count from base), ordered as (
      select * from numbered order by
        case when v_sort='created' and v_dir='asc' then created_at end asc,
        case when v_sort='created' and v_dir='desc' then created_at end desc,
        case when v_sort='status' and v_dir='asc' then lower(coalesce(status,'')) end asc,
        case when v_sort='status' and v_dir='desc' then lower(coalesce(status,'')) end desc,
        case when v_sort='type' and v_dir='asc' then lower(coalesce(job_type,'')) end asc,
        case when v_sort='type' and v_dir='desc' then lower(coalesce(job_type,'')) end desc,
        case when v_sort='domain' and v_dir='asc' then lower(coalesce(domain,'')) end asc,
        case when v_sort='domain' and v_dir='desc' then lower(coalesce(domain,'')) end desc,
        created_at desc,id
      limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),
      'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir,
      'filters',jsonb_build_object(
        'statuses',coalesce((select jsonb_agg(jsonb_build_object('code',x.status,'name',initcap(replace(x.status,'_',' ')),'count',x.n) order by x.status) from (select status,count(*) n from pipeline.jobs where status is not null group by status) x),'[]'::jsonb),
        'domains',coalesce((select jsonb_agg(jsonb_build_object('code',x.domain,'name',initcap(replace(x.domain,'_',' ')),'count',x.n) order by x.domain) from (select domain,count(*) n from pipeline.jobs where domain is not null group by domain) x),'[]'::jsonb),
        'job_types',coalesce((select jsonb_agg(jsonb_build_object('code',x.job_type,'name',initcap(replace(x.job_type,'_',' ')),'count',x.n) order by x.job_type) from (select job_type,count(*) n from pipeline.jobs where job_type is not null group by job_type) x),'[]'::jsonb)
      )
    ) into v_result from ordered o;
    return v_result;

  elsif p_operation='sources_page' then
    if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
    with base as (
      select s.id source_id,s.label source_label,s.source_type,co.iso_alpha2::text country_code,
             s.url source_url,
             coalesce(to_jsonb(s)->'official_source','false'::jsonb) official_source,
             to_jsonb(s)->'ingestion_enabled' ingestion_enabled,
             to_jsonb(s)->>'validation_status' validation_status,
             to_jsonb(s)->>'validation_message' validation_message,
             coalesce(to_jsonb(s)->>'lifecycle_status',s.status) lifecycle_status,
             to_jsonb(s)->'current_snapshot_at' current_snapshot_at,
             to_jsonb(s)->>'refresh_cadence' refresh_cadence,
             to_jsonb(s)->'priority' priority,
             to_jsonb(s)->'automation_eligible' automation_eligible,
             to_jsonb(s)->'auth_required' auth_required,
             to_jsonb(s)->>'expected_format' expected_format,
             s.last_checked_at,s.last_success_at,s.last_failure_at,s.last_error
      from pipeline.sources s left join ref.countries co on co.id=s.country_id
      where (v_query is null
        or s.id::text=v_query
        or coalesce(s.label,'') ilike '%'||v_query||'%'
        or coalesce(s.source_type,'') ilike '%'||v_query||'%'
        or coalesce(s.url,'') ilike '%'||v_query||'%'
        or coalesce(co.iso_alpha2::text,'') ilike '%'||v_query||'%')
        and (nullif(p_args->>'source_type','') is null or s.source_type=p_args->>'source_type')
        and (nullif(p_args->>'status','') is null or s.status=p_args->>'status')
        and (nullif(p_args->>'country_code','') is null or co.iso_alpha2::text=upper(p_args->>'country_code'))
    ), numbered as (select *,count(*) over() total_count from base), ordered as (
      select * from numbered order by
        case when v_sort in ('source','name') and v_dir='asc' then lower(coalesce(source_label,'')) end asc,
        case when v_sort in ('source','name') and v_dir='desc' then lower(coalesce(source_label,'')) end desc,
        case when v_sort='country' and v_dir='asc' then coalesce(country_code,'') end asc,
        case when v_sort='country' and v_dir='desc' then coalesce(country_code,'') end desc,
        case when v_sort='type' and v_dir='asc' then lower(coalesce(source_type,'')) end asc,
        case when v_sort='type' and v_dir='desc' then lower(coalesce(source_type,'')) end desc,
        case when v_sort='checked' and v_dir='asc' then last_checked_at end asc nulls last,
        case when v_sort='checked' and v_dir='desc' then last_checked_at end desc nulls last,
        lower(coalesce(source_label,'')),source_id
      limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),
      'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir,
      'filters',jsonb_build_object(
        'source_types',coalesce((select jsonb_agg(jsonb_build_object('code',x.source_type,'name',initcap(replace(x.source_type,'_',' ')),'count',x.n) order by x.source_type) from (select source_type,count(*) n from pipeline.sources where source_type is not null group by source_type) x),'[]'::jsonb),
        'statuses',coalesce((select jsonb_agg(jsonb_build_object('code',x.status,'name',initcap(replace(x.status,'_',' ')),'count',x.n) order by x.status) from (select status,count(*) n from pipeline.sources where status is not null group by status) x),'[]'::jsonb),
        'countries',coalesce((select jsonb_agg(jsonb_build_object('code',x.country_code,'name',x.country_code,'count',x.n) order by x.country_code) from (select co2.iso_alpha2::text country_code,count(*) n from pipeline.sources s2 join ref.countries co2 on co2.id=s2.country_id group by co2.iso_alpha2) x),'[]'::jsonb)
      )
    ) into v_result from ordered o;
    return v_result;
  end if;

  raise exception 'unsupported operational page: %',p_operation using errcode='22023';
end
$$;


ALTER FUNCTION "security"."admin_operational_page"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_operations_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'public', 'workflow', 'pipeline', 'ref', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,1000),1),5000);
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;

  if p_operation='reviews' then
    if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
    select coalesce(jsonb_agg(to_jsonb(x) order by x.priority desc,x.created_at desc),'[]'::jsonb)
      into v_result from public.ui_review_queue(v_limit) x;
    return v_result;
  elsif p_operation='jobs' then
    if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
    select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb)
      into v_result from public.ui_jobs_list(v_limit) x;
    return v_result;
  elsif p_operation='sources' then
    if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'source_id',to_jsonb(s)->>'id',
      'source_label',to_jsonb(s)->>'label',
      'source_type',to_jsonb(s)->>'source_type',
      'country_code',co.iso_alpha2,
      'source_url',to_jsonb(s)->>'url',
      'official_source',to_jsonb(s)->'official_source',
      'ingestion_enabled',to_jsonb(s)->'ingestion_enabled',
      'validation_status',to_jsonb(s)->>'validation_status',
      'validation_message',to_jsonb(s)->>'validation_message',
      'lifecycle_status',coalesce(to_jsonb(s)->>'lifecycle_status',to_jsonb(s)->>'status'),
      'current_snapshot_at',to_jsonb(s)->'current_snapshot_at',
      'refresh_cadence',to_jsonb(s)->>'refresh_cadence',
      'priority',to_jsonb(s)->'priority',
      'automation_eligible',to_jsonb(s)->'automation_eligible',
      'auth_required',to_jsonb(s)->'auth_required',
      'expected_format',to_jsonb(s)->>'expected_format'
    )) order by co.iso_alpha2 nulls last,to_jsonb(s)->>'label'),'[]'::jsonb)
      into v_result
      from pipeline.sources s
      left join ref.countries co on co.id=nullif(to_jsonb(s)->>'country_id','')::uuid;
    return v_result;
  end if;

  raise exception 'unsupported operations read: %',p_operation using errcode='22023';
end
$$;


ALTER FUNCTION "security"."admin_operations_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_pim_governance_read"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pim', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,200),1),500);
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<5 then raise exception 'pim_admin role required' using errcode='42501'; end if;

  select jsonb_build_object(
    'families',coalesce((select jsonb_agg(to_jsonb(x) order by x.code) from (select * from pim.attribute_families order by code limit v_limit) x),'[]'::jsonb),
    'groups',coalesce((select jsonb_agg(to_jsonb(x) order by x.display_order nulls last,x.code) from (select * from pim.attribute_groups order by display_order nulls last,code limit v_limit) x),'[]'::jsonb),
    'attributes',coalesce((select jsonb_agg(to_jsonb(x) order by x.display_order nulls last,x.code) from (select * from pim.attribute_definitions order by display_order nulls last,code limit v_limit) x),'[]'::jsonb),
    'options',coalesce((select jsonb_agg(to_jsonb(x) order by x.attribute_id,x.display_order nulls last,x.code) from (select * from pim.attribute_options order by attribute_id,display_order nulls last,code limit v_limit) x),'[]'::jsonb),
    'completeness_profiles',coalesce((select jsonb_agg(to_jsonb(x) order by x.code) from (select * from pim.completeness_profiles order by code limit v_limit) x),'[]'::jsonb),
    'completeness_profile_rules',coalesce((select jsonb_agg(to_jsonb(x) order by x.profile_id,x.requirement_code,x.attribute_code) from (
      select cr.id,cr.profile_id,cr.attribute_id,cr.requirement_code,cr.weight,cr.is_mandatory,cr.rule,cr.created_at,
             ad.code attribute_code,ad.name attribute_name
      from pim.completeness_requirements cr
      left join pim.attribute_definitions ad on ad.id=cr.attribute_id
      order by cr.profile_id,cr.requirement_code,ad.code
      limit v_limit
    ) x),'[]'::jsonb),
    'family_groups',coalesce((select jsonb_agg(to_jsonb(x) order by x.family_id,x.display_order nulls last) from (select * from pim.family_groups order by family_id,display_order nulls last limit v_limit) x),'[]'::jsonb),
    'family_attributes',coalesce((select jsonb_agg(to_jsonb(x) order by x.family_id,x.display_order nulls last) from (select * from pim.family_attributes order by family_id,display_order nulls last limit v_limit) x),'[]'::jsonb),
    'counts',jsonb_build_object(
      'families',(select count(*) from pim.attribute_families),
      'groups',(select count(*) from pim.attribute_groups),
      'attributes',(select count(*) from pim.attribute_definitions),
      'options',(select count(*) from pim.attribute_options),
      'completeness_profiles',(select count(*) from pim.completeness_profiles),
      'completeness_profile_rules',(select count(*) from pim.completeness_requirements)
    ),
    'limit',v_limit
  ) into v_result;
  return v_result;
end
$$;


ALTER FUNCTION "security"."admin_pim_governance_read"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_pipeline_ops_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'pim', 'ref', 'workflow', 'search', 'publishing', 'integration', 'auth'
    AS $_$
declare
  v_rank integer := 0;
  v_limit integer := least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer := greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_sort text := lower(coalesce(nullif(p_args->>'sort',''),'created'));
  v_dir text := case when lower(coalesce(nullif(p_args->>'direction',''),'desc'))='asc' then 'asc' else 'desc' end;
  v_id uuid;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0) < 4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;

  if p_operation='pipeline_jobs_page' then
    with projected as (
      select j.id,j.job_type,j.domain,j.status,j.source_id,s.label source_label,s.source_type,co.iso_alpha2::text country_code,co.name country_name,j.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,j.entity_id,er.entity_type,er.stable_key entity_stable_key,j.started_at,j.completed_at,j.created_at,j.attempt_count,
        case when lower(coalesce(s.metadata->>'layer','')) like '1%' or j.domain='regulatory' or j.job_type='regulatory_sync' then 'L1' when lower(coalesce(s.metadata->>'layer','')) like '2%' or j.job_type like 'layer2%' or s.source_type in ('provider_course_page','structured_outcomes','scholarship_catalogue','government_scholarship_program') then 'L2' when j.job_type ~* '(ai|llm|model|extract)' then 'L3' when j.job_type ~* '(review|resolve)' then 'L4' else 'UNCLASSIFIED' end layer_code,
        case when j.payload ? 'apply' then case when coalesce((j.payload->>'apply')::boolean,false) then 'APPLY' else 'DRY_RUN' end when lower(coalesce(j.result->>'mode',j.payload->>'mode',''))='apply' then 'APPLY' when lower(coalesce(j.result->>'mode',j.payload->>'mode','')) ~ '(dry|inventory|validate|qualification)' then 'DRY_RUN' else upper(nullif(coalesce(j.result->>'mode',j.payload->>'mode',''),'')) end run_mode,
        coalesce(j.payload->>'version',j.result->>'workerVersion',j.result->>'worker_version') worker_version,coalesce(j.payload->>'scope',j.result->>'scope',j.domain) run_scope,
        case when coalesce(j.payload->>'offset','') ~ '^-?[0-9]+$' then (j.payload->>'offset')::bigint else null end cursor_offset,
        case when coalesce(j.payload->>'batch_size','') ~ '^[0-9]+$' then (j.payload->>'batch_size')::integer when coalesce(j.result->>'batchSize','') ~ '^[0-9]+$' then (j.result->>'batchSize')::integer else null end batch_size,
        case when coalesce(j.result->>'nextOffset','') ~ '^-?[0-9]+$' then (j.result->>'nextOffset')::bigint when coalesce(j.result->>'next_offset','') ~ '^-?[0-9]+$' then (j.result->>'next_offset')::bigint else null end next_cursor,
        case when lower(coalesce(j.result->>'hasMore',j.result->>'has_more','')) in ('true','false') then lower(coalesce(j.result->>'hasMore',j.result->>'has_more'))::boolean else null end has_more,
        case when coalesce(j.result->>'sourceRows','') ~ '^[0-9]+$' then (j.result->>'sourceRows')::bigint when coalesce(j.result->>'source_rows','') ~ '^[0-9]+$' then (j.result->>'source_rows')::bigint when coalesce(j.result->>'discoveredRecords','') ~ '^[0-9]+$' then (j.result->>'discoveredRecords')::bigint else null end discovered_count,
        case when coalesce(j.result->>'selectedRecords','') ~ '^[0-9]+$' then (j.result->>'selectedRecords')::bigint when coalesce(j.result->>'selected_records','') ~ '^[0-9]+$' then (j.result->>'selected_records')::bigint when coalesce(j.result#>>'{reconciliation,records}','') ~ '^[0-9]+$' then (j.result#>>'{reconciliation,records}')::bigint else null end selected_count,
        case when coalesce(j.result#>>'{reconciliation,records}','') ~ '^[0-9]+$' then (j.result#>>'{reconciliation,records}')::bigint when coalesce(j.result->>'processedRecords','') ~ '^[0-9]+$' then (j.result->>'processedRecords')::bigint when coalesce(j.result->>'selectedRecords','') ~ '^[0-9]+$' then (j.result->>'selectedRecords')::bigint else null end processed_count,
        case when coalesce(j.result#>>'{reconciliation,mapped}','') ~ '^[0-9]+$' then (j.result#>>'{reconciliation,mapped}')::bigint when coalesce(j.result->>'acceptedRecords','') ~ '^[0-9]+$' then (j.result->>'acceptedRecords')::bigint when coalesce(j.result->>'accepted_records','') ~ '^[0-9]+$' then (j.result->>'accepted_records')::bigint else null end accepted_count,
        (case when coalesce(j.result#>>'{reconciliation,unmapped}','') ~ '^[0-9]+$' then (j.result#>>'{reconciliation,unmapped}')::bigint else 0 end + case when coalesce(j.result#>>'{reconciliation,course_missing}','') ~ '^[0-9]+$' then (j.result#>>'{reconciliation,course_missing}')::bigint else 0 end + case when coalesce(j.result->>'rejectedRecords','') ~ '^[0-9]+$' then (j.result->>'rejectedRecords')::bigint else 0 end) rejected_count,
        case when coalesce(j.result#>>'{reconciliation,review_required}','') ~ '^[0-9]+$' then (j.result#>>'{reconciliation,review_required}')::bigint else 0 end ambiguity_count,
        case when coalesce(j.result#>>'{reconciliation,observation_created}','') ~ '^[0-9]+$' then (j.result#>>'{reconciliation,observation_created}')::bigint when coalesce(j.result->>'created','') ~ '^[0-9]+$' then (j.result->>'created')::bigint else null end creates_count,
        case when coalesce(j.result#>>'{reconciliation,observation_updated}','') ~ '^[0-9]+$' then (j.result#>>'{reconciliation,observation_updated}')::bigint when coalesce(j.result->>'updated','') ~ '^[0-9]+$' then (j.result->>'updated')::bigint else null end updates_count,
        case when coalesce(j.result#>>'{reconciliation,observation_unchanged}','') ~ '^[0-9]+$' then (j.result#>>'{reconciliation,observation_unchanged}')::bigint when coalesce(j.result->>'unchanged','') ~ '^[0-9]+$' then (j.result->>'unchanged')::bigint else null end unchanged_count,
        case when coalesce(j.result#>>'{reconciliation,conflicts}','') ~ '^[0-9]+$' then (j.result#>>'{reconciliation,conflicts}')::bigint when coalesce(j.result->>'conflicts','') ~ '^[0-9]+$' then (j.result->>'conflicts')::bigint else 0 end conflicts_count,
        (select count(*)::bigint from pipeline.evidence_artifacts e where e.job_id=j.id) evidence_count,
        case when j.started_at is not null then (extract(epoch from (coalesce(j.completed_at,now())-j.started_at))*1000)::bigint else null end duration_ms,
        case when j.status='running' and j.started_at < now()-interval '30 minutes' then 'stale_running' when j.status='blocked' then 'blocked' when j.status='failed' then 'incomplete_failure' when lower(coalesce(j.result->>'hasMore',j.result->>'has_more',''))='true' then 'partial_batch' when lower(coalesce(j.result->>'hasMore',j.result->>'has_more',''))='false' then 'source_or_scope_complete' when j.status='completed' then 'completed_scope_unknown' else 'in_progress_or_unknown' end completion_class,
        case when j.status='running' and j.started_at < now()-interval '30 minutes' then 'stale_runtime' when j.status='blocked' then 'governed_blocker' when j.status<>'failed' then null when lower(coalesce(j.error_text,'')) like '%superseded%' then 'historical_superseded' when lower(coalesce(j.error_text,'')) ~ '(inventory unstable|inventory incomplete|coverage blocker|source.*unstable)' then 'source_validation' when lower(coalesce(j.error_text,'')) ~ '(statement timeout|resource limit|compute limit|signal has been aborted|edge worker)' then 'technical_runtime' when lower(coalesce(j.error_text,'')) ~ '(schema cache|not defined|assignment to constant|requires a where clause|cannot insert|does not exist)' then 'technical_defect' when lower(coalesce(j.error_text,'')) like '%rejected%' then 'governed_rejection' else 'technical_failure' end failure_class,
        j.result->>'searchAction' search_action,coalesce(j.payload->>'change_control_ref',j.result->>'change_control_ref') change_control_ref,coalesce(j.payload->>'uat_ref',j.result->>'uat_ref') uat_ref,j.error_text
      from pipeline.jobs j left join pipeline.sources s on s.id=j.source_id left join ref.countries co on co.id=s.country_id left join catalogue.providers p on p.id=j.provider_id left join pim.entity_registry er on er.id=j.entity_id
    ), filtered as (
      select * from projected x where (nullif(trim(coalesce(p_args->>'query','')),'') is null or x.id::text ilike '%'||trim(p_args->>'query')||'%' or coalesce(x.job_type,'') ilike '%'||trim(p_args->>'query')||'%' or coalesce(x.source_label,'') ilike '%'||trim(p_args->>'query')||'%' or coalesce(x.provider_name,'') ilike '%'||trim(p_args->>'query')||'%' or coalesce(x.worker_version,'') ilike '%'||trim(p_args->>'query')||'%' or coalesce(x.error_text,'') ilike '%'||trim(p_args->>'query')||'%') and (nullif(p_args->>'status','') is null or x.status=p_args->>'status') and (nullif(p_args->>'job_type','') is null or x.job_type=p_args->>'job_type') and (nullif(p_args->>'layer','') is null or x.layer_code=upper(p_args->>'layer')) and (nullif(p_args->>'mode','') is null or x.run_mode=upper(p_args->>'mode')) and (nullif(p_args->>'country_code','') is null or x.country_code=upper(p_args->>'country_code')) and (nullif(p_args->>'source_id','') is null or x.source_id=nullif(p_args->>'source_id','')::uuid) and (nullif(p_args->>'failure_class','') is null or x.failure_class=p_args->>'failure_class') and (nullif(p_args->>'completion_class','') is null or x.completion_class=p_args->>'completion_class')
    ), numbered as (select f.*,count(*) over()::bigint total_count from filtered f), ordered as (
      select * from numbered order by case when v_sort='created' and v_dir='asc' then created_at end asc,case when v_sort='created' and v_dir='desc' then created_at end desc,case when v_sort='duration' and v_dir='asc' then duration_ms end asc nulls last,case when v_sort='duration' and v_dir='desc' then duration_ms end desc nulls last,case when v_sort='status' and v_dir='asc' then status end asc,case when v_sort='status' and v_dir='desc' then status end desc,case when v_sort='layer' and v_dir='asc' then layer_code end asc,case when v_sort='layer' and v_dir='desc' then layer_code end desc,created_at desc,id limit v_limit offset v_offset
    ) select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir) into v_result from ordered o; return v_result;
  elsif p_operation='pipeline_job_detail' then
    v_id:=nullif(p_args->>'id','')::uuid; if v_id is null then raise exception 'job id required' using errcode='22023'; end if;
    select jsonb_build_object('job',jsonb_build_object('id',j.id,'job_type',j.job_type,'domain',j.domain,'status',j.status,'source_id',j.source_id,'source_label',s.label,'source_type',s.source_type,'country_code',co.iso_alpha2,'country_name',co.name,'provider_id',j.provider_id,'provider_name',coalesce(p.display_name,p.canonical_name),'entity_id',j.entity_id,'entity_type',er.entity_type,'entity_stable_key',er.stable_key,'requested_by',j.requested_by,'started_at',j.started_at,'completed_at',j.completed_at,'duration_ms',case when j.started_at is null then null else (extract(epoch from (coalesce(j.completed_at,now())-j.started_at))*1000)::bigint end,'attempt_count',j.attempt_count,'created_at',j.created_at,'error_text',j.error_text,'payload',j.payload,'result',j.result),'run_semantics',jsonb_build_object('layer',case when lower(coalesce(s.metadata->>'layer','')) like '1%' or j.domain='regulatory' or j.job_type='regulatory_sync' then 'L1' when lower(coalesce(s.metadata->>'layer','')) like '2%' or j.job_type like 'layer2%' or s.source_type in ('provider_course_page','structured_outcomes','scholarship_catalogue','government_scholarship_program') then 'L2' when j.job_type ~* '(ai|llm|model|extract)' then 'L3' when j.job_type ~* '(review|resolve)' then 'L4' else 'UNCLASSIFIED' end,'authority',case when lower(coalesce(s.metadata->>'layer','')) like '1%' or j.domain='regulatory' or j.job_type='regulatory_sync' then 'regulatory_or_identity_authority' when lower(coalesce(s.metadata->>'layer','')) like '2%' or j.job_type like 'layer2%' then 'deterministic_enrichment_non_identity' when j.job_type ~* '(ai|llm|model|extract)' then 'suggestion_only_no_silent_overwrite' when j.job_type ~* '(review|resolve)' then 'human_resolution_auditable' else 'unclassified' end,'mode',case when j.payload ? 'apply' then case when coalesce((j.payload->>'apply')::boolean,false) then 'APPLY' else 'DRY_RUN' end when lower(coalesce(j.result->>'mode',j.payload->>'mode',''))='apply' then 'APPLY' when lower(coalesce(j.result->>'mode',j.payload->>'mode','')) ~ '(dry|inventory|validate|qualification)' then 'DRY_RUN' else upper(nullif(coalesce(j.result->>'mode',j.payload->>'mode',''),'')) end,'completion_class',case when j.status='running' and j.started_at < now()-interval '30 minutes' then 'stale_running' when j.status='blocked' then 'blocked' when j.status='failed' then 'incomplete_failure' when lower(coalesce(j.result->>'hasMore',j.result->>'has_more',''))='true' then 'partial_batch' when lower(coalesce(j.result->>'hasMore',j.result->>'has_more',''))='false' then 'source_or_scope_complete' when j.status='completed' then 'completed_scope_unknown' else 'in_progress_or_unknown' end,'search_action',j.result->>'searchAction','change_control_ref',coalesce(j.payload->>'change_control_ref',j.result->>'change_control_ref'),'uat_ref',coalesce(j.payload->>'uat_ref',j.result->>'uat_ref')),'source',case when s.id is null then null else jsonb_build_object('id',s.id,'label',s.label,'source_type',s.source_type,'url',s.url,'status',s.status,'trust_rank',s.trust_rank,'last_checked_at',s.last_checked_at,'last_success_at',s.last_success_at,'last_failure_at',s.last_failure_at,'last_error',s.last_error,'metadata',s.metadata) end,'evidence',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'evidence_type',e.evidence_type,'source_url',e.source_url,'storage_path',e.storage_path,'content_hash',e.content_hash,'mime_type',e.mime_type,'captured_at',e.captured_at,'valid_from',e.valid_from,'valid_to',e.valid_to,'supersedes_evidence_id',e.supersedes_evidence_id) order by e.captured_at desc) from pipeline.evidence_artifacts e where e.job_id=j.id),'[]'::jsonb),'entity_impact',jsonb_build_object('direct_entity',case when er.id is null then null else jsonb_build_object('id',er.id,'entity_type',er.entity_type,'stable_key',er.stable_key,'lifecycle_status',er.lifecycle_status) end,'direct_provider',case when p.id is null then null else jsonb_build_object('id',p.id,'stable_key',p.stable_key,'name',coalesce(p.display_name,p.canonical_name)) end,'scope_note',case when j.entity_id is null and j.provider_id is null then 'Batch/source-scoped job: entity-level impact links are not persisted on this job row; use evidence and adapter result counts.' else 'Direct entity/provider reference persisted on the job.' end),'safe_actions',jsonb_build_object('retry',jsonb_build_object('enabled',false,'reason','No generic retry command is exposed. Retry must be adapter-specific and idempotency-governed.'),'replay',jsonb_build_object('enabled',false,'reason','No generic replay command is exposed. Replay requires preserved evidence/hash plus adapter-specific scope validation.'),'reset',jsonb_build_object('enabled',false,'reason','Generic reset is intentionally prohibited. Any destructive reset requires an explicit governed scope and confirmation contract.'))) into v_result from pipeline.jobs j left join pipeline.sources s on s.id=j.source_id left join ref.countries co on co.id=s.country_id left join catalogue.providers p on p.id=j.provider_id left join pim.entity_registry er on er.id=j.entity_id where j.id=v_id; return coalesce(v_result,'{}'::jsonb);
  elsif p_operation='pipeline_sources_page' then
    with base as (select s.id source_id,s.label source_label,s.source_type,s.url source_url,s.status,s.trust_rank,s.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,co.iso_alpha2::text country_code,co.name country_name,case when lower(coalesce(s.metadata->>'layer','')) like '1%' then 'L1' when lower(coalesce(s.metadata->>'layer','')) like '2%' or s.source_type in ('provider_course_page','structured_outcomes','scholarship_catalogue','government_scholarship_program') then 'L2' when lower(coalesce(s.metadata->>'layer','')) like '3%' then 'L3' when lower(coalesce(s.metadata->>'layer','')) like '4%' then 'L4' else case when s.source_type in ('dataset','regulatory_programme','provincial_regulator','provincial_catalogue','institutional_catalogue','first_party_programme','web_catalogue') then 'L1' else 'UNCLASSIFIED' end end layer_code,s.last_checked_at,s.last_success_at,s.last_failure_at,s.last_error,case when s.last_failure_at is not null and (s.last_success_at is null or s.last_failure_at>s.last_success_at) then 'unhealthy' when s.last_success_at is not null then 'healthy' else 'untested' end health,case when s.last_success_at is null then null else round((extract(epoch from (now()-s.last_success_at))/86400.0)::numeric,2) end freshness_age_days,case when s.last_success_at is null then 'never_successful' when nullif(s.metadata->>'refresh_cadence','') is null then 'schedule_not_declared' else 'compare_to_declared_cadence' end freshness_class,s.metadata,(select max(j.completed_at) from pipeline.jobs j where j.source_id=s.id and j.status='completed') last_job_success_at,(select count(*)::bigint from pipeline.jobs j where j.source_id=s.id and j.status='running') running_jobs,(select count(*)::bigint from pipeline.jobs j where j.source_id=s.id and j.status in ('failed','blocked')) problem_jobs,(select count(*)::bigint from pipeline.evidence_artifacts e where e.source_id=s.id) evidence_count from pipeline.sources s left join ref.countries co on co.id=s.country_id left join catalogue.providers p on p.id=s.provider_id), filtered as (select * from base b where (nullif(trim(coalesce(p_args->>'query','')),'') is null or coalesce(b.source_label,'') ilike '%'||trim(p_args->>'query')||'%' or coalesce(b.source_type,'') ilike '%'||trim(p_args->>'query')||'%' or coalesce(b.provider_name,'') ilike '%'||trim(p_args->>'query')||'%' or coalesce(b.source_url,'') ilike '%'||trim(p_args->>'query')||'%') and (nullif(p_args->>'country_code','') is null or b.country_code=upper(p_args->>'country_code')) and (nullif(p_args->>'layer','') is null or b.layer_code=upper(p_args->>'layer')) and (nullif(p_args->>'status','') is null or b.status=p_args->>'status') and (nullif(p_args->>'source_type','') is null or b.source_type=p_args->>'source_type') and (nullif(p_args->>'health','') is null or b.health=p_args->>'health')), numbered as (select f.*,count(*) over()::bigint total_count from filtered f), ordered as (select * from numbered order by case when v_sort in ('source','name') and v_dir='asc' then lower(source_label) end asc,case when v_sort in ('source','name') and v_dir='desc' then lower(source_label) end desc,case when v_sort='country' and v_dir='asc' then country_code end asc nulls last,case when v_sort='country' and v_dir='desc' then country_code end desc nulls last,case when v_sort='health' and v_dir='asc' then health end asc,case when v_sort='health' and v_dir='desc' then health end desc,case when v_sort='freshness' and v_dir='asc' then freshness_age_days end asc nulls last,case when v_sort='freshness' and v_dir='desc' then freshness_age_days end desc nulls last,lower(source_label),source_id limit v_limit offset v_offset) select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir) into v_result from ordered o; return v_result;
  elsif p_operation='pipeline_filters' then
    select jsonb_build_object('countries',coalesce((select jsonb_agg(x order by x->>'code') from (select distinct jsonb_build_object('code',co.iso_alpha2::text,'name',co.name) x from pipeline.sources s join ref.countries co on co.id=s.country_id) q),'[]'::jsonb),'job_types',coalesce((select jsonb_agg(job_type order by job_type) from (select distinct job_type from pipeline.jobs where job_type is not null) q),'[]'::jsonb),'statuses',coalesce((select jsonb_agg(status order by status) from (select distinct status from pipeline.jobs where status is not null) q),'[]'::jsonb),'source_types',coalesce((select jsonb_agg(source_type order by source_type) from (select distinct source_type from pipeline.sources where source_type is not null) q),'[]'::jsonb),'layers',jsonb_build_array('L1','L2','L3','L4','UNCLASSIFIED'),'modes',jsonb_build_array('DRY_RUN','APPLY')) into v_result; return v_result;
  elsif p_operation='pipeline_overview' then
    with job_stage as (select j.*,case when lower(coalesce(s.metadata->>'layer','')) like '1%' or j.domain='regulatory' or j.job_type='regulatory_sync' then 'L1' when lower(coalesce(s.metadata->>'layer','')) like '2%' or j.job_type like 'layer2%' or s.source_type in ('provider_course_page','structured_outcomes','scholarship_catalogue','government_scholarship_program') then 'L2' when j.job_type ~* '(ai|llm|model|extract)' then 'L3' when j.job_type ~* '(review|resolve)' then 'L4' else 'UNCLASSIFIED' end layer_code from pipeline.jobs j left join pipeline.sources s on s.id=j.source_id),source_stage as (select s.*,case when lower(coalesce(s.metadata->>'layer','')) like '1%' then 'L1' when lower(coalesce(s.metadata->>'layer','')) like '2%' or s.source_type in ('provider_course_page','structured_outcomes','scholarship_catalogue','government_scholarship_program') then 'L2' when lower(coalesce(s.metadata->>'layer','')) like '3%' then 'L3' when lower(coalesce(s.metadata->>'layer','')) like '4%' then 'L4' else case when s.source_type in ('dataset','regulatory_programme','provincial_regulator','provincial_catalogue','institutional_catalogue','first_party_programme','web_catalogue') then 'L1' else 'UNCLASSIFIED' end end layer_code from pipeline.sources s),layers as (select 'L1' code,'Layer 1 Regulatory' name,'regulatory_authority' authority,1 seq union all select 'L2','Layer 2 Deterministic / Structured Enrichment','non_identity_structured_enrichment',2 union all select 'L3','Layer 3 AI Suggestions','suggestion_only_no_silent_overwrite',3 union all select 'L4','Layer 4 Human Resolution','auditable_human_decision',4),layer_cards as (select jsonb_build_object('code',l.code,'name',l.name,'authority',l.authority,'source_count',(select count(*)::bigint from source_stage s where s.layer_code=l.code),'job_count',(select count(*)::bigint from job_stage j where j.layer_code=l.code),'running_jobs',(select count(*)::bigint from job_stage j where j.layer_code=l.code and j.status='running'),'stale_running_jobs',(select count(*)::bigint from job_stage j where j.layer_code=l.code and j.status='running' and j.started_at<now()-interval '30 minutes'),'failed_jobs',(select count(*)::bigint from job_stage j where j.layer_code=l.code and j.status='failed'),'blocked_jobs',(select count(*)::bigint from job_stage j where j.layer_code=l.code and j.status='blocked'),'last_success_at',(select max(j.completed_at) from job_stage j where j.layer_code=l.code and j.status='completed'),'current_job',(select jsonb_build_object('id',j.id,'job_type',j.job_type,'status',j.status,'started_at',j.started_at) from job_stage j where j.layer_code=l.code and j.status='running' order by j.started_at desc nulls last limit 1),'evidence_count',(select count(*)::bigint from pipeline.evidence_artifacts e join source_stage s on s.id=e.source_id where s.layer_code=l.code),'next_allowed_action',case when l.code='L3' then 'AI suggestions may be generated only into governed suggestion/claim surfaces; no silent overwrite of L1/L2.' when l.code='L4' then 'Resolve queued ambiguity/conflict through auditable review actions; direct canonical overwrite is not a review action.' when exists(select 1 from job_stage j where j.layer_code=l.code and j.status='running' and j.started_at<now()-interval '30 minutes') then 'Investigate stale running job before any replay.' when exists(select 1 from job_stage j where j.layer_code=l.code and j.status='blocked') then 'Resolve explicit blocker before rerun.' else 'Use adapter-specific dry-run/APPLY runbook; generic replay/reset is not exposed.' end,'blocker',case when exists(select 1 from job_stage j where j.layer_code=l.code and j.status='running' and j.started_at<now()-interval '30 minutes') then 'STALE_RUNNING_JOB' when exists(select 1 from job_stage j where j.layer_code=l.code and j.status='blocked') then 'BLOCKED_JOB_PRESENT' when l.code='L3' and (select count(*) from workflow.suggestions)=0 then 'NOT_OPERATIONAL_NO_SUGGESTIONS' when l.code='L4' and (select count(*) from workflow.review_queue)=0 then null else null end,'governance_ref',null,'uat_ref',null) item,l.seq from layers l) select jsonb_build_object('journey',jsonb_build_array('Layer 1 Regulatory','Layer 2 Deterministic/Structured Enrichment','Layer 3 AI Suggestions','Layer 4 Human Resolution','Search Admission','Publication'),'layers',(select jsonb_agg(item order by seq) from layer_cards),'layer3',jsonb_build_object('suggestions_total',(select count(*)::bigint from workflow.suggestions),'claims_total',(select count(*)::bigint from pipeline.claims where layer=3),'overwrite_policy','Layer 3 is suggestion-only and has no direct authority to overwrite Layer 1/2 facts.'),'layer4',jsonb_build_object('review_queue_total',(select count(*)::bigint from workflow.review_queue),'review_open',(select count(*)::bigint from workflow.review_queue where coalesce(status,'open') not in ('closed','resolved','rejected')),'review_actions_total',(select count(*)::bigint from workflow.review_actions),'audit_policy','Every human resolution must be represented by review_actions with before/after/reason/evidence where applicable.'),'search_admission',jsonb_build_object('documents',(select count(*)::bigint from search.course_documents),'projection',coalesce((select jsonb_build_object('projection_code',ps.projection_code,'generation',ps.generation,'row_count',ps.row_count,'rebuilt_at',ps.rebuilt_at,'content_hash',ps.content_hash,'metadata',ps.metadata) from search.projection_state ps where ps.projection_code='courses' limit 1),'{}'::jsonb),'country_gates',coalesce((select jsonb_agg(jsonb_build_object('projection_code',g.projection_code,'country_code',co.iso_alpha2,'gate_status',g.gate_status,'approval_ref',g.approval_ref,'approved_at',g.approved_at,'updated_at',g.updated_at) order by co.iso_alpha2) from search.projection_country_gates g left join ref.countries co on co.id=g.country_id),'[]'::jsonb),'enrichment_gates',coalesce((select jsonb_agg(to_jsonb(g) order by g.domain_code) from search.enrichment_gates g),'[]'::jsonb),'blocked_enrichment_gates',(select count(*)::bigint from search.enrichment_gates where gate_status<>'approved'),'definition','Ingestion/enrichment completion does not imply Search admission. Search gates are reported independently.'),'publication',jsonb_build_object('entity_states_total',(select count(*)::bigint from publishing.entity_states),'channels',coalesce((select jsonb_agg(to_jsonb(c) order by c.code) from publishing.channels c),'[]'::jsonb),'status_counts',coalesce((select jsonb_object_agg(publication_status,cnt) from (select publication_status,count(*)::bigint cnt from publishing.entity_states group by publication_status) q),'{}'::jsonb),'definition','Publication is a downstream channel state and is not equivalent to successful ingestion or Search projection.'),'guardrails',jsonb_build_object('generic_reset',false,'generic_retry',false,'generic_replay',false,'reason','Destructive/replay operations require adapter-specific governed scope, preserved evidence/hash, explicit confirmation and idempotency semantics.'),'observed_volumes',jsonb_build_object('jobs',(select count(*)::bigint from pipeline.jobs),'sources',(select count(*)::bigint from pipeline.sources),'evidence',(select count(*)::bigint from pipeline.evidence_artifacts),'claims',(select count(*)::bigint from pipeline.claims))) into v_result; return v_result;
  else raise exception 'unsupported pipeline ops read: %',p_operation using errcode='22023'; end if;
end $_$;


ALTER FUNCTION "security"."admin_pipeline_ops_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_pipeline_ops_read"("p_operation" "text", "p_args" "jsonb") IS 'M1-PIPELINE-OPS role-checked operational read model across Layers 1-4, Search admission and Publication. No generic reset/retry/replay mutation is exposed.';



CREATE OR REPLACE FUNCTION "security"."admin_pipeline_ops_sanitise_result"("p_operation" "text", "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare
  v_items jsonb;
begin
  if p_operation='pipeline_sources_page' then
    select coalesce(jsonb_agg(
      jsonb_set(x.item,'{metadata}',security.admin_pipeline_source_metadata_safe(coalesce(x.item->'metadata','{}'::jsonb)),true)
      order by x.ord
    ),'[]'::jsonb)
    into v_items
    from jsonb_array_elements(coalesce(p_result->'items','[]'::jsonb)) with ordinality as x(item,ord);
    return jsonb_set(p_result,'{items}',v_items,true);
  end if;

  if p_operation='pipeline_job_detail' and jsonb_typeof(p_result->'source')='object' then
    return jsonb_set(
      p_result,
      '{source,metadata}',
      security.admin_pipeline_source_metadata_safe(coalesce(p_result#>'{source,metadata}','{}'::jsonb)),
      true
    );
  end if;

  return p_result;
end;
$$;


ALTER FUNCTION "security"."admin_pipeline_ops_sanitise_result"("p_operation" "text", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_pipeline_source_metadata_safe"("p_metadata" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'configured_worker_version', p_metadata->'configured_worker_version',
    'worker_version', p_metadata->'worker_version',
    'scope', p_metadata->'scope',
    'coverage_role', p_metadata->'coverage_role',
    'apply_gate', p_metadata->'apply_gate',
    'apply_enabled', p_metadata->'apply_enabled',
    'identity_scheme', p_metadata->'identity_scheme',
    'course_identity_scheme', p_metadata->'course_identity_scheme',
    'transport', p_metadata->'transport',
    'acquisition_method', p_metadata->'acquisition_method',
    'coverage_complete_for_country', p_metadata->'coverage_complete_for_country'
  ));
$$;


ALTER FUNCTION "security"."admin_pipeline_source_metadata_safe"("p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_platform_health_cf221"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security', 'scholarship'
    AS $$
declare v_rank int:=security.scholarship_ai_role_rank(); v_failed int; v_running int; v_completed int; v_ev24 bigint; v_attempts bigint; v_calls bigint; v_cost numeric; v_sch bigint; v_active_ai bigint;
begin
 if v_rank<1 then raise exception 'authenticated role required' using errcode='42501'; end if;
 select count(*) filter(where status='failed' and created_at>=now()-interval '24 hours'),count(*) filter(where status in ('queued','running')),count(*) filter(where status in ('completed','succeeded') and created_at>=now()-interval '24 hours') into v_failed,v_running,v_completed from pipeline.jobs;
 select count(*) into v_ev24 from pipeline.evidence_artifacts where created_at>=now()-interval '24 hours';
 select count(*) into v_attempts from pipeline.layer2_provider_attempts where created_at>=now()-interval '24 hours';
 select coalesce(sum(external_call_count),0),coalesce(sum(estimated_cost_usd),0) into v_calls,v_cost from pipeline.layer3_interpretations where created_at>=now()-interval '24 hours';
 select count(*) into v_sch from scholarship.scholarships;
 select count(*) into v_active_ai from pipeline.scholarship_ai_runs where status in ('queued','running');
 return jsonb_strip_nulls(jsonb_build_object(
   'overall_status',case when v_failed>0 then 'attention' when v_running>0 then 'active' else 'healthy' end,
   'jobs',jsonb_build_object('running',v_running,'failed_24h',v_failed,'completed_24h',v_completed),
   'data',jsonb_build_object('evidence_fetched_24h',v_ev24,'scholarships',v_sch),
   'edge_runtime',jsonb_build_object('status',case when v_failed>0 then 'attention' else 'healthy' end,'active_workloads',v_running,'completed_24h',v_completed),
   'api_activity',case when v_rank>=4 then jsonb_build_object('layer2_provider_requests_24h',v_attempts,'layer3_external_calls_24h',v_calls,'layer3_cost_24h_usd',v_cost) else null end,
   'scholarship_ai',case when v_rank>=3 then jsonb_build_object('active_runs',v_active_ai,'profiles_staged',(select count(*) from pipeline.layer3_model_profiles where code like 'openrouter-scholarship-%'),'profiles_qualified',(select count(*) from pipeline.layer3_model_profiles where code like 'openrouter-scholarship-%' and coalesce((quality_benchmark->>'pass')::boolean,false))) else null end,
   'security',case when v_rank>=6 then jsonb_build_object('status','reviewed_with_existing_findings','note','Security Advisor remains the authority; no CF-221 finding is asserted by this runtime snapshot.') else null end,
   'observed_at',now()
 ));
end $$;


ALTER FUNCTION "security"."admin_platform_health_cf221"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_platform_health_v1"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_rank int:=security.scholarship_ai_role_rank();
begin
  if v_rank<1 then raise exception 'authenticated role required' using errcode='42501'; end if;
  -- CF-221 keys kept for the existing Dashboard panel; the CF-247 contract keys are added alongside (no key overlap)
  return security.admin_platform_health_cf221() || security.platform_health_state_v1(v_rank>=4);
end $$;


ALTER FUNCTION "security"."admin_platform_health_v1"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_platform_maturity_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'scholarship', 'ref', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_environment text:=lower(coalesce(nullif(btrim(p_args->>'environment'),''),'pilot'));
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,100),1),200);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_scope text:=lower(nullif(btrim(coalesce(p_args->>'environment_scope','')),''));
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
  if v_environment not in ('pilot','production') then raise exception 'invalid environment' using errcode='22023'; end if;

  if p_operation='platform_readiness' then
    return security.m2_5_readiness_snapshot_read();
  end if;

  if p_operation='platform_capacity' then
    return security.platform_capacity_snapshot_read(v_environment);
  end if;

  if p_operation='platform_environment_gates' then
    return jsonb_build_object(
      'environment',v_environment,
      'source_gates',coalesce((
        select jsonb_agg(jsonb_build_object(
          'environment',g.environment,
          'source_id',g.source_id,
          'source_label',coalesce(s.label,g.source_id::text),
          'capability',g.capability,
          'state',g.lifecycle_state,
          'enabled',g.enabled,
          'uat_ref',g.uat_ref,
          'reason',g.reason,
          'change_control_ref',g.change_control_ref,
          'updated_at',g.updated_at
        ) order by coalesce(s.label,''),g.capability)
        from pipeline.environment_source_gates g
        left join pipeline.sources s on s.id=g.source_id
        where g.environment=v_environment
      ),'[]'::jsonb),
      'scraper_gates',coalesce((
        select jsonb_agg(jsonb_build_object(
          'environment',g.environment,
          'provider_id',g.acquisition_provider_id,
          'provider_key',p.provider_key,
          'provider_name',p.display_name,
          'state',g.qualification_state,
          'enabled',g.enabled,
          'uat_ref',g.uat_ref,
          'reason',g.reason,
          'change_control_ref',g.change_control_ref,
          'updated_at',g.updated_at
        ) order by p.provider_key)
        from pipeline.layer2_provider_environment_gates g
        join pipeline.layer2_acquisition_providers p on p.id=g.acquisition_provider_id
        where g.environment=v_environment
      ),'[]'::jsonb),
      'ai_gates',coalesce((
        select jsonb_agg(jsonb_build_object(
          'environment',g.environment,
          'profile_id',g.profile_id,
          'profile_code',p.code,
          'model_identifier',p.model_identifier,
          'state',g.qualification_state,
          'enabled',g.enabled,
          'uat_ref',g.uat_ref,
          'benchmark_ref',g.benchmark_ref,
          'reason',g.reason,
          'change_control_ref',g.change_control_ref,
          'updated_at',g.updated_at
        ) order by p.code)
        from pipeline.layer3_profile_environment_gates g
        join pipeline.layer3_model_profiles p on p.id=g.profile_id
        where g.environment=v_environment
      ),'[]'::jsonb)
    );
  end if;

  if p_operation='platform_uat_catalogue' then
    with base as (
      select test_code,domain,environment_scope,gate_class,status,hard_gate,evidence_ref,
             description,change_control_ref,updated_at
      from pipeline.platform_uat_catalogue
      where v_scope is null
         or environment_scope=v_scope
         or environment_scope='both'
      order by
        case status when 'not_run' then 0 when 'designed' then 1 when 'accepted_baseline' then 2 when 'pass' then 3 else 4 end,
        hard_gate desc,domain,test_code
    ), numbered as (
      select b.*,count(*) over() total_count from base b
    ), page as (
      select * from numbered limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'items',coalesce(jsonb_agg(jsonb_build_object(
        'test_code',test_code,'domain',domain,'environment_scope',environment_scope,
        'gate_class',gate_class,'status',status,'hard_gate',hard_gate,
        'evidence_ref',evidence_ref,'description',description,
        'change_control_ref',change_control_ref,'updated_at',updated_at
      ) order by
        case status when 'not_run' then 0 when 'designed' then 1 when 'accepted_baseline' then 2 when 'pass' then 3 else 4 end,
        hard_gate desc,domain,test_code),'[]'::jsonb),
      'total',coalesce(max(total_count),0),
      'limit',v_limit,'offset',v_offset,'environment_scope',v_scope
    ) into v_result from page;
    return coalesce(v_result,jsonb_build_object('items','[]'::jsonb,'total',0,'limit',v_limit,'offset',v_offset,'environment_scope',v_scope));
  end if;

  if p_operation='platform_workloads' then
    return jsonb_build_object(
      'items',coalesce((
        select jsonb_agg(jsonb_build_object(
          'profile_key',profile_key,
          'workload_class',workload_class,
          'serving_traffic',serving_traffic,
          'background_ingestion',background_ingestion,
          'concurrent_admin_uat',concurrent_admin_uat,
          'rpc_detail_budget_ms',rpc_detail_budget_ms,
          'management_payload_budget_bytes',management_payload_budget_bytes,
          'filter_payload_budget_bytes',filter_payload_budget_bytes,
          'acquisition_on_read_allowed',acquisition_on_read_allowed,
          'sizing_role',sizing_role,
          'notes',notes,
          'updated_at',updated_at
        ) order by workload_class,profile_key)
        from pipeline.performance_workload_profiles
      ),'[]'::jsonb),
      'hard_budgets',jsonb_build_object(
        'rpc_detail_ms',3000,
        'management_payload_bytes',250000,
        'filter_payload_bytes',60000,
        'acquisition_on_read_allowed',false
      )
    );
  end if;

  if p_operation='platform_retention' then
    return jsonb_build_object(
      'dry_run',security.retention_dry_run_read(v_environment),
      'classes',coalesce((
        select jsonb_agg(jsonb_build_object(
          'class_key',class_key,
          'object_scope',object_scope,
          'immutable',immutable,
          'purge_allowed',purge_allowed,
          'default_retention_days',default_retention_days,
          'dry_run_required',dry_run_required,
          'bounded_delete_limit',bounded_delete_limit,
          'post_delete_integrity_required',post_delete_integrity_required,
          'notes',notes,
          'change_control_ref',change_control_ref,
          'updated_at',updated_at
        ) order by immutable desc,class_key)
        from pipeline.retention_class_policies
      ),'[]'::jsonb),
      'destructive_action_authorised',false
    );
  end if;

  if p_operation='platform_active_blocks' then
    with entities as (
      select 'provider'::text entity_type,p.id entity_id,coalesce(p.display_name,p.canonical_name) entity_name,
             p.id provider_id,coalesce(p.display_name,p.canonical_name) provider_name
      from catalogue.providers p
      union all
      select 'course',c.id,coalesce(c.display_title,c.canonical_title),p.id,coalesce(p.display_name,p.canonical_name)
      from catalogue.courses c join catalogue.providers p on p.id=c.provider_id
      union all
      select 'campus',ca.id,ca.name,p.id,coalesce(p.display_name,p.canonical_name)
      from catalogue.campuses ca join catalogue.providers p on p.id=ca.provider_id
      union all
      select 'scholarship',s.id,s.name,p.id,coalesce(p.display_name,p.canonical_name)
      from scholarship.scholarships s left join catalogue.providers p on p.id=s.provider_id
    ), base as (
      select b.id,b.entity_type,b.entity_id,e.entity_name,e.provider_id,e.provider_name,
             b.block_scope,b.reason_code,b.comment,b.expires_at,b.review_at,b.created_at
      from security.layer4_active_blocks b
      left join entities e on e.entity_type=b.entity_type and e.entity_id=b.entity_id
      order by b.created_at desc,b.id desc
    ), numbered as (
      select x.*,count(*) over() total_count from base x
    ), page as (
      select * from numbered limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'items',coalesce(jsonb_agg(jsonb_build_object(
        'decision_id',id,
        'entity_type',entity_type,
        'entity_id',entity_id,
        'entity_name',coalesce(entity_name,entity_id::text),
        'provider_id',provider_id,
        'provider_name',provider_name,
        'scope',block_scope,
        'reason_code',reason_code,
        'comment',comment,
        'expires_at',expires_at,
        'review_at',review_at,
        'created_at',created_at
      ) order by created_at desc,id desc),'[]'::jsonb),
      'total',coalesce(max(total_count),0),
      'limit',v_limit,'offset',v_offset
    ) into v_result from page;
    return coalesce(v_result,jsonb_build_object('items','[]'::jsonb,'total',0,'limit',v_limit,'offset',v_offset));
  end if;

  raise exception 'unsupported platform operation: %',p_operation using errcode='22023';
end
$$;


ALTER FUNCTION "security"."admin_platform_maturity_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_priority_control_v1"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_kind text:=p_args->>'kind'; v_target uuid:=nullif(p_args->>'target_id','')::uuid; v_id bigint:=nullif(p_args->>'id','')::bigint; p pipeline.priority_pins%rowtype; o pipeline.priority_pins%rowtype; v_label jsonb;
begin
  if auth.uid() is null or security.current_role_rank()<5 then raise exception 'Platform Admin role required' using errcode='42501'; end if;
  if p_action='add' then
    if v_kind not in ('provider','state','country','course') or v_target is null then raise exception 'choose a university, state, country or course'; end if;
    v_label:=security.priority_pin_label(v_kind,v_target);
    if v_label is null then raise exception 'not found'; end if;
    insert into pipeline.priority_pins(kind,target_id,sort,note,created_by)
    values (v_kind,v_target,case when coalesce((p_args->>'top')::boolean,false) then coalesce((select min(sort) from pipeline.priority_pins),1)-1 else coalesce((select max(sort) from pipeline.priority_pins),0)+1 end,
            nullif(btrim(coalesce(p_args->>'note','')),''),auth.uid())
    on conflict (kind,target_id) do nothing;
  elsif p_action='remove' then
    select * into p from pipeline.priority_pins where id=v_id; if p.id is null then raise exception 'not found'; end if;
    v_label:=security.priority_pin_label(p.kind,p.target_id); v_kind:=p.kind;
    delete from pipeline.priority_pins where id=v_id;
  elsif p_action='move' then
    select * into p from pipeline.priority_pins where id=v_id; if p.id is null then raise exception 'not found'; end if;
    v_label:=security.priority_pin_label(p.kind,p.target_id); v_kind:=p.kind;
    if p_args->>'direction'='up' then select * into o from pipeline.priority_pins where sort<p.sort order by sort desc limit 1;
    else select * into o from pipeline.priority_pins where sort>p.sort order by sort limit 1; end if;
    if o.id is not null then
      update pipeline.priority_pins set sort=-999999 where id=p.id;
      update pipeline.priority_pins set sort=p.sort where id=o.id;
      update pipeline.priority_pins set sort=o.sort where id=p.id;
    end if;
  else raise exception 'unknown action'; end if;
  perform security.provider_priority_refresh_v1();
  insert into pipeline.admin_control_events(area,action,target,detail,actor)
  values ('priority',p_action,coalesce(v_label->>'label',v_id::text),p_args||jsonb_build_object('kind',v_kind),auth.uid());
  return security.admin_priority_read_v1();
end $$;


ALTER FUNCTION "security"."admin_priority_control_v1"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_priority_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'ref', 'security'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  return jsonb_build_object('can_control',security.current_role_rank()>=5,
    'pins',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'kind',x.kind,'target_id',x.target_id,'sort',x.sort,'note',x.note,'at',x.created_at)||coalesce(security.priority_pin_label(x.kind,x.target_id),'{}'::jsonb) order by x.sort),'[]'::jsonb) from pipeline.priority_pins x),
    'ranking',(select coalesce(jsonb_agg(r order by (r->>'rank')::int),'[]'::jsonb) from (
       select jsonb_build_object('rank',pp.rank,'provider_id',pp.provider_id,'name',coalesce(pr.display_name,pr.canonical_name),'state',s.name,'country',k.iso_alpha2,
         'courses',pp.active_courses,'pinned_by',pp.pinned_by,
         'pages_matched',(select count(*) from pipeline.coverage_course_pages g where g.provider_id=pp.provider_id and g.read_status='read' and g.identity_basis is not null),
         'pages_waiting',(select count(*) from pipeline.coverage_course_pages g where g.provider_id=pp.provider_id and g.status in ('bound','ambiguous') and coalesce(g.read_status,'')<>'read' and g.read_attempts<3)) r
         from pipeline.provider_priority pp join catalogue.providers pr on pr.id=pp.provider_id left join ref.subdivisions s on s.id=pr.subdivision_id left join ref.countries k on k.id=pr.country_id
        where pp.rank<=60) y),
    'states',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'country',k.name) order by k.name,s.name),'[]'::jsonb)
                from ref.subdivisions s join ref.countries k on k.id=s.country_id where exists (select 1 from catalogue.providers pr where pr.subdivision_id=s.id)),
    'countries',(select coalesce(jsonb_agg(jsonb_build_object('id',k.id,'name',k.name) order by k.name),'[]'::jsonb)
                from ref.countries k where exists (select 1 from catalogue.providers pr where pr.country_id=k.id)),
    'events',(select coalesce(jsonb_agg(jsonb_build_object('at',e.created_at,'action',e.action,'target',e.target,'detail',e.detail) order by e.created_at desc),'[]'::jsonb)
                from (select * from pipeline.admin_control_events where area='priority' order by created_at desc limit 12) e));
end $$;


ALTER FUNCTION "security"."admin_priority_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_priority_search_v1"("p_kind" "text", "p_q" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'ref', 'security'
    AS $$
declare q text:='%'||btrim(coalesce(p_q,''))||'%';
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  if length(btrim(coalesce(p_q,'')))<2 then return '[]'::jsonb; end if;
  if p_kind='provider' then
    return (select coalesce(jsonb_agg(x),'[]'::jsonb) from (select jsonb_build_object('id',pr.id,'label',coalesce(pr.display_name,pr.canonical_name),'detail',concat_ws(' · ',s.name,k.name)) x
      from catalogue.providers pr left join ref.subdivisions s on s.id=pr.subdivision_id left join ref.countries k on k.id=pr.country_id
     where pr.display_name ilike q or pr.canonical_name ilike q or pr.short_name ilike q order by (select count(*) from catalogue.courses c where c.provider_id=pr.id and c.lifecycle_status='active') desc, length(coalesce(pr.display_name,pr.canonical_name)) limit 20) y);
  elsif p_kind='course' then
    return (select coalesce(jsonb_agg(x),'[]'::jsonb) from (select jsonb_build_object('id',c.id,'label',coalesce(c.display_title,c.canonical_title),'detail',concat_ws(' · ',c.course_code,coalesce(pr.display_name,pr.canonical_name))) x
      from catalogue.courses c left join catalogue.providers pr on pr.id=c.provider_id
     where c.lifecycle_status='active' and (c.course_code ilike q or c.canonical_title ilike q or c.display_title ilike q) limit 20) y);
  end if;
  raise exception 'search by provider or course';
end $$;


ALTER FUNCTION "security"."admin_priority_search_v1"("p_kind" "text", "p_q" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_provider_asset_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'pipeline', 'ref', 'ranking', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_country text:=upper(nullif(btrim(p_args->>'country_code'),''));
  v_query text:=nullif(btrim(p_args->>'query'),'');
  v_state text:=nullif(btrim(p_args->>'state'),'');
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0)<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;

  if p_operation='provider_asset_summary' then
    return (
      with university_scope as (
        select distinct p.id,p.canonical_name,p.display_name,p.stable_key,c.iso_alpha2 country_code
        from catalogue.providers p
        join ref.countries c on c.id=p.country_id
        join (
          select provider_id from ranking.observations where provider_id is not null
          union
          select provider_id from ranking.observation_provider_links
        ) r on r.provider_id=p.id
        where c.iso_alpha2 in('AU','NZ')
          and coalesce(p.lifecycle_status,'active')='active'
          and (v_country is null or c.iso_alpha2=v_country)
          and (v_query is null or p.canonical_name ilike '%'||v_query||'%' or coalesce(p.display_name,'') ilike '%'||v_query||'%' or coalesce(p.stable_key,'') ilike '%'||v_query||'%')
      ), base as (
        select u.*,
          exists(select 1 from pipeline.provider_asset_candidates pc where pc.provider_id=u.id and pc.asset_type ilike 'logo%') discovered,
          exists(select 1 from pipeline.provider_asset_candidates pc where pc.provider_id=u.id and pc.asset_type ilike 'logo%' and pc.evidence_id is not null) evidence_backed,
          exists(select 1 from pipeline.provider_asset_candidates pc where pc.provider_id=u.id and pc.asset_type ilike 'logo%' and pc.status='accepted') accepted_candidate,
          exists(select 1 from catalogue.provider_assets pa where pa.provider_id=u.id and pa.is_primary and pa.status='approved' and pa.asset_type in ('logo','logo_dark','logo_light')) approved_primary,
          exists(select 1 from pipeline.sources s where s.provider_id=u.id and s.source_type='third_party_directory' and s.metadata->>'directory'='hotcourses_abroad') hotcourses_matched
        from university_scope u
      )
      select jsonb_build_object(
        'scope_basis','AU/NZ canonical university cohort defined by accepted ranking Provider mappings; Hotcourses is discovery/reconciliation only',
        'country_code',v_country,'expected',count(*),'discovered',count(*) filter(where discovered),
        'acquired',count(*) filter(where evidence_backed or approved_primary),'approved',count(*) filter(where approved_primary),
        'blocked',count(*) filter(where accepted_candidate and not approved_primary),'missing',count(*) filter(where not discovered),
        'needs_review',count(*) filter(where discovered and not accepted_candidate and not approved_primary),
        'hotcourses_matched',count(*) filter(where hotcourses_matched),
        'refresh_cadence','quarterly','authority','first_party_provider',
        'third_party_discovery_policy','Exact university-logo copies from Hotcourses may be promoted as operator-approved fallbacks; canonical ownership remains the Provider and Hotcourses provenance is retained'
      ) from base
    );
  elsif p_operation='provider_asset_coverage' then
    return (
      with university_scope as (
        select distinct p.id provider_id,p.stable_key,coalesce(p.display_name,p.canonical_name) provider_name,p.website,p.lifecycle_status,
          c.iso_alpha2 country_code,c.name country_name
        from catalogue.providers p
        join ref.countries c on c.id=p.country_id
        join (
          select provider_id from ranking.observations where provider_id is not null
          union
          select provider_id from ranking.observation_provider_links
        ) r on r.provider_id=p.id
        where c.iso_alpha2 in('AU','NZ')
          and coalesce(p.lifecycle_status,'active')='active'
          and (v_country is null or c.iso_alpha2=v_country)
          and (v_query is null or p.canonical_name ilike '%'||v_query||'%' or coalesce(p.display_name,'') ilike '%'||v_query||'%' or coalesce(p.stable_key,'') ilike '%'||v_query||'%')
      ), base as (
        select u.*,
          (select count(*) from pipeline.provider_asset_candidates pc where pc.provider_id=u.provider_id and pc.asset_type ilike 'logo%') candidate_count,
          (select count(*) from pipeline.provider_asset_candidates pc where pc.provider_id=u.provider_id and pc.asset_type ilike 'logo%' and pc.evidence_id is not null) evidence_candidate_count,
          (select count(*) from pipeline.provider_asset_candidates pc where pc.provider_id=u.provider_id and pc.asset_type ilike 'logo%' and pc.status='accepted') accepted_candidate_count,
          (select count(*) from pipeline.provider_asset_candidates pc where pc.provider_id=u.provider_id and pc.asset_type ilike 'logo%' and pc.status='rejected') rejected_candidate_count,
          (select max(pc.discovered_at) from pipeline.provider_asset_candidates pc where pc.provider_id=u.provider_id and pc.asset_type ilike 'logo%') latest_candidate_at,
          (select s.url from pipeline.sources s where s.provider_id=u.provider_id and s.source_type='third_party_directory' and s.metadata->>'directory'='hotcourses_abroad' order by s.updated_at desc limit 1) hotcourses_url,
          (select s.metadata->>'directory_id' from pipeline.sources s where s.provider_id=u.provider_id and s.source_type='third_party_directory' and s.metadata->>'directory'='hotcourses_abroad' order by s.updated_at desc limit 1) hotcourses_id,
          pa.id primary_asset_id,pa.source_url primary_source_url,pa.evidence_id primary_evidence_id,pa.storage_path primary_storage_path,
          pa.mime_type primary_mime_type,pa.content_hash primary_content_hash,pa.verified_at primary_verified_at,
          case when pa.id is not null then 'approved'
            when exists(select 1 from pipeline.provider_asset_candidates pc where pc.provider_id=u.provider_id and pc.asset_type ilike 'logo%' and pc.status='accepted') then 'blocked'
            when exists(select 1 from pipeline.provider_asset_candidates pc where pc.provider_id=u.provider_id and pc.asset_type ilike 'logo%') then 'needs_review'
            else 'missing' end coverage_state
        from university_scope u
        left join lateral (
          select x.* from catalogue.provider_assets x where x.provider_id=u.provider_id and x.is_primary and x.status='approved'
            and x.asset_type in ('logo','logo_dark','logo_light')
          order by x.verified_at desc nulls last,x.id limit 1
        ) pa on true
      ), filtered as (select * from base where v_state is null or coverage_state=v_state),
      page as (
        select * from filtered order by case coverage_state when 'blocked' then 1 when 'needs_review' then 2 when 'missing' then 3 else 4 end,
          lower(provider_name),provider_id limit v_limit offset v_offset
      )
      select jsonb_build_object('total',(select count(*) from filtered),'limit',v_limit,'offset',v_offset,
        'items',coalesce((select jsonb_agg(to_jsonb(page)) from page),'[]'::jsonb))
    );
  elsif p_operation='provider_asset_context' then
    return (
      select jsonb_build_object(
        'provider_id',p.id,
        'state',case when pa.id is not null then 'approved'
          when exists(select 1 from pipeline.provider_asset_candidates pc where pc.provider_id=p.id and pc.asset_type ilike 'logo%' and pc.status='accepted') then 'blocked'
          when exists(select 1 from pipeline.provider_asset_candidates pc where pc.provider_id=p.id and pc.asset_type ilike 'logo%') then 'needs_review'
          else 'missing' end,
        'primary_asset',case when pa.id is null then null else jsonb_build_object('id',pa.id,'source_url',pa.source_url,'evidence_id',pa.evidence_id,'storage_path',pa.storage_path,'mime_type',pa.mime_type,'content_hash',pa.content_hash,'verified_at',pa.verified_at) end,
        'candidate_count',(select count(*) from pipeline.provider_asset_candidates pc where pc.provider_id=p.id and pc.asset_type ilike 'logo%'),
        'accepted_candidate_count',(select count(*) from pipeline.provider_asset_candidates pc where pc.provider_id=p.id and pc.asset_type ilike 'logo%' and pc.status='accepted'),
        'hotcourses_reference',(select jsonb_build_object('id',s.metadata->>'directory_id','url',s.url,'fallback_reuse_approved',coalesce((s.metadata->>'operator_fallback_reuse_approved')::boolean,false),'rights_owner_basis',s.metadata->>'rights_owner_basis') from pipeline.sources s where s.provider_id=p.id and s.source_type='third_party_directory' and s.metadata->>'directory'='hotcourses_abroad' order by s.updated_at desc limit 1),
        'latest_candidate_at',(select max(pc.discovered_at) from pipeline.provider_asset_candidates pc where pc.provider_id=p.id and pc.asset_type ilike 'logo%'),
        'authority','first_party_provider','refresh_cadence','quarterly')
      from catalogue.providers p
      left join lateral (
        select x.* from catalogue.provider_assets x where x.provider_id=p.id and x.is_primary and x.status='approved'
          and x.asset_type in ('logo','logo_dark','logo_light')
        order by x.verified_at desc nulls last,x.id limit 1
      ) pa on true
      where p.id=nullif(p_args->>'provider_id','')::uuid
    );
  end if;
  raise exception 'unsupported provider asset read operation: %',p_operation using errcode='22023';
end
$$;


ALTER FUNCTION "security"."admin_provider_asset_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_provider_contact_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref', 'auth'
    AS $$
declare
 v_rank int:=0;v_limit int:=least(greatest(coalesce(nullif(p_args->>'limit','')::int,50),1),200);v_offset int:=greatest(coalesce(nullif(p_args->>'offset','')::int,0),0);
 v_query text:=nullif(btrim(coalesce(p_args->>'query','')),'');v_country text:=nullif(upper(btrim(coalesce(p_args->>'country_code',''))),'');
 v_provider uuid:=nullif(p_args->>'provider_id','')::uuid;v_lifecycle text:=nullif(lower(btrim(coalesce(p_args->>'lifecycle_status',''))),'');
 v_record_type text:=nullif(lower(btrim(coalesce(p_args->>'record_type',''))),'');v_source text:=nullif(lower(btrim(coalesce(p_args->>'source_authority',''))),'');
 v_verify text:=nullif(lower(btrim(coalesce(p_args->>'verification_state',''))),'');v_has_email text:=nullif(lower(btrim(coalesce(p_args->>'has_email',''))),'');
 v_has_phone text:=nullif(lower(btrim(coalesce(p_args->>'has_phone',''))),'');v_freshness text:=nullif(lower(btrim(coalesce(p_args->>'freshness',''))),'');
 v_sort text:=lower(coalesce(nullif(p_args->>'sort',''),'provider'));v_direction text:=case when lower(coalesce(p_args->>'direction','asc'))='desc' then 'desc' else 'asc' end;
 v_id uuid;v_items jsonb;v_total bigint:=0;v_result jsonb;
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank();if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;

 if p_operation='provider_contacts_page' then
  with base as (
   select c.id,c.provider_id,p.canonical_name provider_name,p.stable_key provider_stable_key,co.iso_alpha2 country_code,
    c.record_type,c.lifecycle_status,c.identity_key,c.updated_at,c.deleted_at,v.id version_id,v.version_no,v.full_name,v.team_name,
    v.job_title,v.functional_area,v.region_scope,v.countries_or_markets,v.work_email,v.work_phone,v.staff_location,v.verification_state,
    v.verified_on,v.source_class,v.source_authority,v.source_url,v.source_page_title,v.evidence_id,v.source_observation_id,v.created_at version_created_at
   from pipeline.provider_contacts c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
   left join pipeline.provider_contact_versions v on v.id=c.current_version_id
   where (v_country is null or upper(co.iso_alpha2)=v_country) and (v_provider is null or c.provider_id=v_provider)
    and (v_lifecycle is null or c.lifecycle_status=v_lifecycle) and (v_record_type is null or c.record_type=v_record_type)
    and (v_source is null or lower(coalesce(v.source_authority,''))=v_source) and (v_verify is null or lower(coalesce(v.verification_state,''))=v_verify)
    and (v_has_email is null or (v_has_email='true')=(nullif(btrim(coalesce(v.work_email,'')),'') is not null))
    and (v_has_phone is null or (v_has_phone='true')=(nullif(btrim(coalesce(v.work_phone,'')),'') is not null))
    and (v_freshness is null or (v_freshness='stale' and (v.verified_on is null or v.verified_on<current_date-365))
      or (v_freshness='current' and v.verified_on is not null and v.verified_on>=current_date-365) or (v_freshness='unverified' and v.verified_on is null))
    and (v_query is null or position(lower(v_query) in lower(concat_ws(' ',p.canonical_name,p.stable_key,v.full_name,v.team_name,v.job_title,
      v.functional_area,v.region_scope,v.countries_or_markets,v.work_email,v.work_phone,v.staff_location,v.source_page_title,v.source_url)))>0)
  ), numbered as (select base.*,count(*) over() total_count from base), ordered as (
   select * from numbered order by
    case when v_direction='asc' and v_sort='provider' then lower(provider_name) end asc,
    case when v_direction='desc' and v_sort='provider' then lower(provider_name) end desc,
    case when v_direction='asc' and v_sort='contact' then lower(coalesce(full_name,team_name,'')) end asc,
    case when v_direction='desc' and v_sort='contact' then lower(coalesce(full_name,team_name,'')) end desc,
    case when v_direction='asc' and v_sort='title' then lower(coalesce(job_title,'')) end asc,
    case when v_direction='desc' and v_sort='title' then lower(coalesce(job_title,'')) end desc,
    case when v_direction='asc' and v_sort='region' then lower(coalesce(region_scope,'')) end asc,
    case when v_direction='desc' and v_sort='region' then lower(coalesce(region_scope,'')) end desc,
    case when v_direction='asc' and v_sort='verified' then verified_on end asc nulls last,
    case when v_direction='desc' and v_sort='verified' then verified_on end desc nulls last,
    case when v_direction='asc' and v_sort='status' then lifecycle_status end asc,
    case when v_direction='desc' and v_sort='status' then lifecycle_status end desc,
    lower(provider_name),lower(coalesce(full_name,team_name,'')),id limit v_limit offset v_offset
  )
  select coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),coalesce(max(total_count),0) into v_items,v_total from ordered o;
  return jsonb_build_object('items',coalesce(v_items,'[]'::jsonb),'total',v_total,'limit',v_limit,'offset',v_offset,'summary',jsonb_build_object(
   'active',(select count(*) from pipeline.provider_contacts where lifecycle_status='active'),
   'inactive',(select count(*) from pipeline.provider_contacts where lifecycle_status='inactive'),
   'deleted',(select count(*) from pipeline.provider_contacts where lifecycle_status='deleted'),
   'stale',(select count(*) from pipeline.provider_contacts c join pipeline.provider_contact_versions v on v.id=c.current_version_id where v.verified_on is null or v.verified_on<current_date-365),
   'providers',(select count(distinct provider_id) from pipeline.provider_contacts)));
 end if;

 if p_operation='provider_contact_detail' then
  v_id:=nullif(p_args->>'id','')::uuid;if v_id is null then raise exception 'contact id required' using errcode='22023'; end if;
  select jsonb_build_object(
   'contact',jsonb_build_object('id',c.id,'provider_id',c.provider_id,'provider_name',p.canonical_name,'provider_stable_key',p.stable_key,'country_code',co.iso_alpha2,
    'record_type',c.record_type,'lifecycle_status',c.lifecycle_status,'identity_key',c.identity_key,'created_at',c.created_at,'updated_at',c.updated_at,
    'deleted_at',c.deleted_at,'deleted_by',c.deleted_by,'delete_reason',c.delete_reason,'restored_at',c.restored_at,'restored_by',c.restored_by),
   'current',case when v.id is null then '{}'::jsonb else to_jsonb(v) end,
   'versions',coalesce((select jsonb_agg(to_jsonb(h) order by h.version_no desc) from (
    select vv.id,vv.version_no,vv.full_name,vv.team_name,vv.job_title,vv.functional_area,vv.region_scope,vv.countries_or_markets,vv.work_email,vv.work_phone,
     vv.staff_location,vv.verification_state,vv.verified_on,vv.source_class,vv.source_authority,vv.source_url,vv.source_page_title,vv.source_notes,
     vv.source_observation_id,vv.evidence_id,vv.import_batch_id,vv.import_row_id,vv.content_hash,vv.effective_from,vv.effective_to,vv.change_reason,vv.created_at,vv.created_by
    from pipeline.provider_contact_versions vv where vv.contact_id=c.id order by vv.version_no desc limit 100) h),'[]'::jsonb),
   'audit',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from (
    select aa.id,aa.event_type,aa.actor_id,aa.reason,aa.before_version_id,aa.after_version_id,aa.metadata,aa.created_at
    from pipeline.provider_contact_audit_events aa where aa.contact_id=c.id order by aa.created_at desc limit 100) a),'[]'::jsonb),
   'source_observations',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'source_class',o.source_class,'source_provider',o.source_provider,'source_url',o.source_url,
    'full_name',o.full_name,'job_title',o.job_title,'team_name',o.team_name,'territory_text',o.territory_text,'territory_codes',o.territory_codes,
    'work_email',o.work_email,'work_phone',o.work_phone,'professional_profile_url',o.professional_profile_url,'evidence_id',o.evidence_id,
    'verification_state',o.verification_state,'observed_at',o.observed_at,'last_verified_at',o.last_verified_at,'is_current',o.is_current,'confidence',o.confidence)
    order by o.last_verified_at desc) from pipeline.provider_contact_observations o where o.managed_contact_id=c.id),'[]'::jsonb)
  ) into v_result from pipeline.provider_contacts c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
  left join pipeline.provider_contact_versions v on v.id=c.current_version_id where c.id=v_id;
  return coalesce(v_result,'{}'::jsonb);
 end if;

 if p_operation='provider_contact_imports' then
  if v_rank<5 then raise exception 'PIM Operator role required' using errcode='42501'; end if;
  with numbered as (select b.*,count(*) over() total_count from pipeline.provider_contact_import_batches b where v_country is null or upper(b.country_code)=v_country),
  ordered as (select * from numbered order by uploaded_at desc,id desc limit v_limit offset v_offset)
  select coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),coalesce(max(total_count),0) into v_items,v_total from ordered o;
  return jsonb_build_object('items',coalesce(v_items,'[]'::jsonb),'total',v_total,'limit',v_limit,'offset',v_offset);
 end if;

 if p_operation='provider_contact_import_detail' then
  if v_rank<5 then raise exception 'PIM Operator role required' using errcode='42501'; end if;
  v_id:=nullif(p_args->>'id','')::uuid;if v_id is null then raise exception 'import id required' using errcode='22023'; end if;
  select jsonb_build_object('batch',to_jsonb(b),'rows',coalesce((select jsonb_agg(to_jsonb(r) order by r.row_number) from (
   select rr.id,rr.row_number,rr.row_hash,rr.logical_key,rr.source_institution_name,rr.current_institution_name,rr.mapped_provider_id,p.canonical_name mapped_provider_name,
    rr.mapping_state,rr.matched_contact_id,rr.proposed_action,rr.applied_action,rr.validation_errors,rr.conflict_detail,rr.normalized_payload,rr.created_at,rr.applied_at
   from pipeline.provider_contact_import_rows rr left join catalogue.providers p on p.id=rr.mapped_provider_id where rr.batch_id=b.id order by rr.row_number limit 2000) r),'[]'::jsonb))
  into v_result from pipeline.provider_contact_import_batches b where b.id=v_id;
  return coalesce(v_result,'{}'::jsonb);
 end if;

 raise exception 'unsupported provider contact read operation: %',p_operation using errcode='22023';
end $$;


ALTER FUNCTION "security"."admin_provider_contact_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_provider_contacts"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref', 'public', 'auth'
    AS $$
declare v_rank integer:=0;v_profile jsonb;v_items jsonb;v_events jsonb;
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
 select security.current_role_rank() into v_rank;if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
 select jsonb_build_object('profile_id',p.id,'enabled',p.enabled,'paused',p.paused,'base_url',p.base_url,'domain',p.domain,'last_run_at',p.last_run_at,'last_success_at',p.last_success_at,'last_error',p.last_error)
 into v_profile from pipeline.provider_contact_profiles p where p.provider_id=p_provider_id;
 select coalesce(jsonb_agg(row_json order by source_priority,lower(coalesce(row_json->>'territory_text','')),lower(coalesce(row_json->>'job_title','')),lower(coalesce(row_json->>'full_name',''))),'[]'::jsonb)
 into v_items from (
  select case v.source_authority when 'first_party' then 1 when 'manual' then 2 else 3 end source_priority,
  jsonb_build_object('id',c.id,'managed_contact_id',c.id,'source_class',v.source_authority,'managed_source_class',v.source_class,'source_authority',v.source_authority,
   'source_provider',coalesce(v.metadata->>'source_provider',v.source_authority),'full_name',v.full_name,'job_title',v.job_title,'team_name',coalesce(v.team_name,v.functional_area),
   'territory_text',coalesce(v.countries_or_markets,v.region_scope),'territory_codes',coalesce(v.metadata->'territory_codes','[]'::jsonb),'work_email',v.work_email,'work_phone',v.work_phone,
   'professional_profile_url',v.metadata->>'professional_profile_url','source_url',v.source_url,'evidence_id',v.evidence_id,'verification_state',v.verification_state,
   'confidence',v.metadata->'confidence','observed_at',v.effective_from,'last_verified_at',v.verified_on,
   'source_priority',case v.source_authority when 'first_party' then 'preferred' when 'manual' then 'governed_manual' else 'secondary_enrichment' end,
   'record_type',c.record_type,'lifecycle_status',c.lifecycle_status) row_json
  from pipeline.provider_contacts c join pipeline.provider_contact_versions v on v.id=c.current_version_id
  where c.provider_id=p_provider_id and c.lifecycle_status in ('active','inactive') order by 1,v.verified_on desc nulls last limit 100
 ) q;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'event_type',e.event_type,'source_class',e.source_class,'before_state',e.before_state,'after_state',e.after_state,'detected_at',e.detected_at,'acknowledged',e.acknowledged) order by e.detected_at desc),'[]'::jsonb)
 into v_events from (select * from pipeline.provider_contact_watch_events where provider_id=p_provider_id order by detected_at desc limit 20)e;
 return jsonb_build_object('profile',coalesce(v_profile,'{}'::jsonb),'items',coalesce(v_items,'[]'::jsonb),'events',coalesce(v_events,'[]'::jsonb),'summary',jsonb_build_object(
  'current_contacts',(select count(*) from pipeline.provider_contacts where provider_id=p_provider_id and lifecycle_status='active'),
  'first_party_contacts',(select count(*) from pipeline.provider_contacts c join pipeline.provider_contact_versions v on v.id=c.current_version_id where c.provider_id=p_provider_id and c.lifecycle_status='active' and v.source_authority='first_party'),
  'manual_contacts',(select count(*) from pipeline.provider_contacts c join pipeline.provider_contact_versions v on v.id=c.current_version_id where c.provider_id=p_provider_id and c.lifecycle_status='active' and v.source_authority='manual'),
  'enriched_contacts',(select count(*) from pipeline.provider_contacts c join pipeline.provider_contact_versions v on v.id=c.current_version_id where c.provider_id=p_provider_id and c.lifecycle_status='active' and v.source_authority='licensed_enrichment'),
  'unacknowledged_changes',(select count(*) from pipeline.provider_contact_watch_events where provider_id=p_provider_id and acknowledged=false)));
end $$;


ALTER FUNCTION "security"."admin_provider_contacts"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_provider_detail"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'public', 'catalogue', 'pipeline', 'ref', 'search', 'scholarship', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_base jsonb;
  v_courses jsonb;
  v_evidence jsonb;
  v_campuses jsonb;
  v_contacts jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;

  v_base:=public.ui_provider_detail(p_provider_id);
  if v_base is null then return '{}'::jsonb; end if;
  v_courses:=public.ui_provider_related_courses(p_provider_id,25,0,null,null,null);
  v_evidence:=public.ui_provider_related_evidence(p_provider_id,25,0,null,null);
  v_contacts:=security.admin_provider_contacts(p_provider_id);

  with base as (
    select ca.id,ca.stable_key,ca.name,ca.campus_code,ca.city,ca.postcode,ca.status,ca.publication_status,
           sd.code subdivision_code,sd.name subdivision_name,
           (select count(*)::int from catalogue.course_campuses cc where cc.campus_id=ca.id) course_count
    from catalogue.campuses ca left join ref.subdivisions sd on sd.id=ca.subdivision_id
    where ca.provider_id=p_provider_id
  ), numbered as (select *,count(*) over() total_count from base), ordered as (
    select * from numbered order by lower(name),id limit 25
  )
  select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',25,'offset',0)
    into v_campuses from ordered o;

  return v_base || jsonb_build_object(
    'courses_page',coalesce(v_courses,jsonb_build_object('items','[]'::jsonb,'total',0,'limit',25,'offset',0)),
    'evidence_page',coalesce(v_evidence,jsonb_build_object('items','[]'::jsonb,'total',0,'limit',25,'offset',0)),
    'campuses_page',coalesce(v_campuses,jsonb_build_object('items','[]'::jsonb,'total',0,'limit',25,'offset',0)),
    'courses',coalesce(v_courses->'items','[]'::jsonb),
    'evidence',coalesce(v_evidence->'items','[]'::jsonb),
    'international_contacts',coalesce(v_contacts,jsonb_build_object('items','[]'::jsonb,'events','[]'::jsonb,'summary','{}'::jsonb)),
    'scholarship_count',(select count(*) from scholarship.scholarships s where s.provider_id=p_provider_id),
    'university_groups',security.provider_university_groups(p_provider_id),
    'history',jsonb_build_object('created_at',v_base->'created_at','updated_at',v_base->'updated_at','last_verified_at',v_base->'last_verified_at')
  );
end $$;


ALTER FUNCTION "security"."admin_provider_detail"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_provider_identity_quality_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref', 'security', 'auth'
    AS $$
declare v_rank integer:=0;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0)<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  return (select jsonb_build_object(
    'providers',count(*),
    'missing_canonical_name',count(*) filter(where canonical_name is null or btrim(canonical_name)=''),
    'missing_display_name',count(*) filter(where display_name is null or btrim(display_name)=''),
    'generic_name_placeholder',count(*) filter(where lower(btrim(coalesce(display_name,canonical_name,''))) in ('location','campus','city','state','region','country','provider','university')),
    'institution_like_city',count(*) filter(where nullif(primary_city,'') is not null and primary_city ~* '(university|institute|college|school|academy|pty|limited|ltd|education|tafe)'),
    'display_matches_city',count(*) filter(where nullif(primary_city,'') is not null and lower(btrim(coalesce(display_name,'')))=lower(btrim(primary_city))),
    'canonical_matches_city',count(*) filter(where nullif(primary_city,'') is not null and lower(btrim(coalesce(canonical_name,'')))=lower(btrim(primary_city))),
    'display_matches_subdivision',count(*) filter(where exists(select 1 from ref.subdivisions s where lower(btrim(s.name))=lower(btrim(coalesce(display_name,''))))),
    'canonical_matches_subdivision',count(*) filter(where exists(select 1 from ref.subdivisions s where lower(btrim(s.name))=lower(btrim(coalesce(canonical_name,''))))),
    'display_matches_country',count(*) filter(where exists(select 1 from ref.countries c where lower(btrim(c.name))=lower(btrim(coalesce(display_name,''))) or lower(btrim(c.iso_alpha2::text))=lower(btrim(coalesce(display_name,''))))),
    'canonical_matches_country',count(*) filter(where exists(select 1 from ref.countries c where lower(btrim(c.name))=lower(btrim(coalesce(canonical_name,''))) or lower(btrim(c.iso_alpha2::text))=lower(btrim(coalesce(canonical_name,''))))),
    'display_differs_from_canonical',count(*) filter(where nullif(btrim(display_name),'') is not null and lower(btrim(display_name))<>lower(btrim(canonical_name)))
  ) from catalogue.providers);
end
$$;


ALTER FUNCTION "security"."admin_provider_identity_quality_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_provider_rankings"("p_provider_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'ranking', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(p_limit,10),1),10);
  v_result jsonb;
  v_obs uuid[];
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0)<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  -- Find this provider's observations once (direct and linked), each via an index.
  v_obs := array(select o.id from ranking.observations o where o.provider_id=p_provider_id union select opl.observation_id from ranking.observation_provider_links opl where opl.provider_id=p_provider_id);

  select coalesce(jsonb_object_agg(code,payload),'{}'::jsonb)
  into v_result
  from (
    select s.code,
      jsonb_build_object(
        'system_code',s.code,
        'publisher_name',s.publisher_name,
        'ranking_name',s.ranking_name,
        'latest',(
          select jsonb_strip_nulls(jsonb_build_object(
            'edition_year',e.edition_year,
            'rank_display',o.rank_display,
            'rank_exact',o.rank_exact,
            'rank_low',o.rank_low,
            'rank_high',o.rank_high,
            'rank_status',o.rank_status,
            'is_tied',o.is_tied,
            'overall_score',o.overall_score,
            'source_url',e.source_url,
            'methodology_url',e.methodology_url,
            'evidence_artifact_id',o.evidence_artifact_id
          ))
          from ranking.observations o
          join ranking.editions e on e.id=o.edition_id
          where o.id = any(v_obs) and e.system_id=s.id and e.status='accepted'
          order by e.edition_year desc,e.updated_at desc
          limit 1
        ),
        'history',coalesce((
          select jsonb_agg(x order by (x->>'edition_year')::integer desc)
          from (
            select jsonb_strip_nulls(jsonb_build_object(
              'edition_year',e.edition_year,
              'rank_display',o.rank_display,
              'rank_exact',o.rank_exact,
              'rank_low',o.rank_low,
              'rank_high',o.rank_high,
              'rank_status',o.rank_status,
              'is_tied',o.is_tied,
              'overall_score',o.overall_score,
              'methodology_version',e.methodology_version
            )) x
            from ranking.observations o
            join ranking.editions e on e.id=o.edition_id
            where o.id = any(v_obs) and e.system_id=s.id and e.status='accepted'
            order by e.edition_year desc,e.updated_at desc
            limit v_limit
          ) h
        ),'[]'::jsonb)
      ) payload
    from ranking.systems s
    where s.active
  ) z;

  return coalesce(v_result,'{}'::jsonb);
end
$$;


ALTER FUNCTION "security"."admin_provider_rankings"("p_provider_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_provider_scholarships"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'scholarship', 'catalogue', 'auth'
    AS $$
declare v_rank integer; v_items jsonb; v_total integer; v_mapped_courses integer; v_review integer;
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank(); if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'scholarship_id',s.id,'name',s.name,'scholarship_type',s.scholarship_type,'audience',s.audience,
   'award_value_text',s.award_value_text,'award_value_type',s.award_value_type,'award_percentage',s.award_percentage,
   'award_amount',s.award_amount,'award_currency_code',s.award_currency_code,'academic_year',s.academic_year,
   'application_close_date',s.application_close_date,'lifecycle_status',s.lifecycle_status,'publication_status',s.publication_status,
   'source_url',s.source_url,'evidence_id',s.evidence_id,
   'mapped_course_count',(select count(*) from scholarship.course_mappings m where m.scholarship_id=s.id and m.mapping_state='mapped')
 ) order by s.name),'[]'::jsonb),count(*)::int
 into v_items,v_total from scholarship.scholarships s where s.provider_id=p_provider_id;
 select count(distinct m.course_id)::int into v_mapped_courses from scholarship.course_mappings m join scholarship.scholarships s on s.id=m.scholarship_id where s.provider_id=p_provider_id and m.mapping_state='mapped';
 select count(*)::int into v_review from scholarship.course_mapping_candidates c join scholarship.scholarships s on s.id=c.scholarship_id where s.provider_id=p_provider_id and c.status='needs_review';
 return jsonb_build_object('items',v_items,'scholarship_count',coalesce(v_total,0),'mapped_course_count',coalesce(v_mapped_courses,0),'needs_review_count',coalesce(v_review,0));
end $$;


ALTER FUNCTION "security"."admin_provider_scholarships"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_providers_page"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_subdivision_code" "text" DEFAULT NULL::"text", "p_lifecycle_status" "text" DEFAULT NULL::"text", "p_publication_status" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'provider'::"text", "p_direction" "text" DEFAULT 'asc'::"text", "p_university_group" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref', 'pipeline', 'security', 'auth'
    AS $$
declare
  v_limit integer:=least(greatest(coalesce(p_limit,50),1),200);
  v_offset integer:=greatest(coalesce(p_offset,0),0);
  v_sort text:=lower(coalesce(p_sort,'provider'));
  v_dir text:=case when lower(coalesce(p_direction,'asc'))='desc' then 'desc' else 'asc' end;
  v_rank integer:=0;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0)<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;

  return (
    with base as (
      select
        p.id,p.stable_key,p.canonical_name,p.display_name,
        c.iso_alpha2::text country_code,c.name country_name,c.default_currency_code::text currency_code,
        ps.code subdivision_code,ps.name subdivision_name,ps.subdivision_type,
        p.primary_city city,p.website,p.lifecycle_status,p.publication_status,
        p.last_verified_at,p.created_at,p.updated_at,
        (select count(*)::bigint from catalogue.courses cr where cr.provider_id=p.id) course_count,
        (select count(distinct x.evidence_id)::bigint
           from (
             select e.id evidence_id from pipeline.evidence_artifacts e where e.entity_id=p.id
             union all
             select pi.evidence_id from catalogue.provider_identifiers pi where pi.provider_id=p.id and pi.evidence_id is not null
             union all
             select pr.evidence_id from catalogue.provider_registrations pr where pr.provider_id=p.id and pr.evidence_id is not null
           ) x) evidence_count
      from catalogue.providers p
      join ref.countries c on c.id=p.country_id
      left join ref.subdivisions ps on ps.id=p.subdivision_id
      where
        (
          nullif(trim(coalesce(p_query,'')),'') is null
          or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_query)||'%'
          or coalesce(p.stable_key,'') ilike '%'||trim(p_query)||'%'
          or coalesce(p.primary_city,'') ilike '%'||trim(p_query)||'%'
          or coalesce(c.iso_alpha2::text,'') ilike '%'||trim(p_query)||'%'
          or coalesce(c.name,'') ilike '%'||trim(p_query)||'%'
          or coalesce(c.default_currency_code::text,'') ilike '%'||trim(p_query)||'%'
          or coalesce(ps.code,'') ilike '%'||trim(p_query)||'%'
          or coalesce(ps.name,'') ilike '%'||trim(p_query)||'%'
        )
        and (nullif(trim(coalesce(p_country_code,'')),'') is null or c.iso_alpha2::text=upper(trim(p_country_code)))
        and (nullif(trim(coalesce(p_subdivision_code,'')),'') is null or ps.code=upper(trim(p_subdivision_code)))
        and (nullif(trim(coalesce(p_lifecycle_status,'')),'') is null or p.lifecycle_status=trim(p_lifecycle_status))
        and (nullif(trim(coalesce(p_publication_status,'')),'') is null or p.publication_status=trim(p_publication_status))
        and (nullif(trim(coalesce(p_university_group,'')),'') is null or p.id in (select security.university_group_provider_ids(p_university_group)))
    ), numbered as (
      select *,count(*) over()::bigint total_count from base
    ), ordered as (
      select * from numbered
      order by
        case when v_sort='provider' and v_dir='asc' then lower(coalesce(display_name,canonical_name)) end asc,
        case when v_sort='provider' and v_dir='desc' then lower(coalesce(display_name,canonical_name)) end desc,
        case when v_sort='country' and v_dir='asc' then country_code end asc,
        case when v_sort='country' and v_dir='desc' then country_code end desc,
        case when v_sort='currency' and v_dir='asc' then currency_code end asc,
        case when v_sort='currency' and v_dir='desc' then currency_code end desc,
        case when v_sort='subdivision' and v_dir='asc' then lower(coalesce(subdivision_name,'')) end asc,
        case when v_sort='subdivision' and v_dir='desc' then lower(coalesce(subdivision_name,'')) end desc,
        case when v_sort='city' and v_dir='asc' then lower(coalesce(city,'')) end asc,
        case when v_sort='city' and v_dir='desc' then lower(coalesce(city,'')) end desc,
        case when v_sort='courses' and v_dir='asc' then course_count end asc,
        case when v_sort='courses' and v_dir='desc' then course_count end desc,
        case when v_sort='verified' and v_dir='asc' then last_verified_at end asc nulls first,
        case when v_sort='verified' and v_dir='desc' then last_verified_at end desc nulls last,
        lower(coalesce(display_name,canonical_name)),id
      limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'items',coalesce(jsonb_agg((to_jsonb(o)-'total_count')||jsonb_build_object('university_groups',security.provider_university_groups(o.id))),'[]'::jsonb),
      'total',coalesce(max(total_count),0),
      'limit',v_limit,
      'offset',v_offset,
      'sort',v_sort,
      'direction',v_dir
    ) from ordered o
  );
end
$$;


ALTER FUNCTION "security"."admin_providers_page"("p_limit" integer, "p_offset" integer, "p_query" "text", "p_country_code" "text", "p_subdivision_code" "text", "p_lifecycle_status" "text", "p_publication_status" "text", "p_sort" "text", "p_direction" "text", "p_university_group" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_publication_overview"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'search', 'publishing', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;

  select jsonb_build_object(
    'course_documents',jsonb_build_object(
      'total',count(*),
      'published',count(*) filter(where publication_status='published'),
      'unpublished',count(*) filter(where publication_status='unpublished'),
      'has_fee',count(*) filter(where has_fee),
      'has_intake',count(*) filter(where has_intake),
      'has_english',count(*) filter(where has_english),
      'has_scholarship',count(*) filter(where has_scholarship),
      'latest_generated_at',max(generated_at)
    ),
    'projection',coalesce((select jsonb_build_object(
      'projection_code',ps.projection_code,'generation',ps.generation,'rebuilt_at',ps.rebuilt_at,'row_count',ps.row_count,
      'content_hash',ps.content_hash,'projection_version',ps.metadata->>'projection_version','enrichment_gate',ps.metadata->>'enrichment_gate'
    ) from search.projection_state ps where ps.projection_code='courses'),'{}'::jsonb),
    'channels',coalesce((select jsonb_agg(jsonb_build_object(
      'code',ch.code,'name',ch.name,'audience',ch.audience,'status',ch.status,
      'entity_state_count',(select count(*) from publishing.entity_states es where es.channel_code=ch.code),
      'published_count',(select count(*) from publishing.entity_states es where es.channel_code=ch.code and es.publication_status='published')
    ) order by ch.code) from publishing.channels ch),'[]'::jsonb)
  ) into v_result
  from search.course_documents;
  return v_result;
end
$$;


ALTER FUNCTION "security"."admin_publication_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_ranking_imports_read"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'ranking', 'pipeline', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_include_history boolean:=coalesce((p_args->>'include_history')::boolean,false);
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0)<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;

  return (
    with visible_imports as (
      select mi.* from ranking.manual_imports mi
      where v_include_history or mi.status<>'rejected'
    ),
    latest_editions as (
      select distinct on (mi.system_id,mi.edition_year) mi.*
      from visible_imports mi
      order by mi.system_id,mi.edition_year,mi.uploaded_at desc nulls last,mi.id desc
    )
    select jsonb_build_object(
      'total',(select count(*) from latest_editions),'limit',v_limit,'offset',v_offset,
      'items',coalesce((
        select jsonb_agg(to_jsonb(x) order by x.updated_at desc nulls last,x.uploaded_at desc nulls last)
        from (
          select mi.id,s.code system_code,mi.edition_year,mi.publisher_name,mi.source_url,mi.methodology_url,
            mi.licensing_note,mi.revision_note,mi.original_filename,mi.mime_type,mi.byte_size,mi.content_hash,
            mi.storage_path,mi.evidence_artifact_id,mi.status,mi.validation_summary,mi.parse_summary,
            mi.uploaded_at,mi.updated_at,
            coalesce((
              select jsonb_agg(distinct scope_item.value)
              from ranking.manual_imports mi_scope
              join pipeline.jobs j
                on j.domain='ranking'
               and j.payload->>'import_id'=mi_scope.id::text
               and (
                 j.job_type='ranking_import_acquire'
                 or (
                   j.job_type='layer1_ranking_etl'
                   and j.payload->>'action'='acquire'
                   and j.payload->>'acquisition_mode'='manual_file'
                 )
               )
              cross join lateral jsonb_array_elements(
                coalesce(j.result->'detected_scope',j.payload->'detected_scope','[]'::jsonb)
              ) scope_item(value)
              where mi_scope.system_id=mi.system_id and mi_scope.edition_year=mi.edition_year
            ),'[]'::jsonb) detected_scope,
            (select count(*) from ranking.manual_imports mi2
             where mi2.system_id=mi.system_id and mi2.edition_year=mi.edition_year)::integer logical_revision_count,
            (select jsonb_build_object('id',j.id,'job_type',j.job_type,'status',j.status,'created_at',j.created_at,
               'started_at',j.started_at,'completed_at',j.completed_at,'error_text',j.error_text)
             from pipeline.jobs j where j.domain='ranking' and j.payload->>'import_id'=mi.id::text
             order by j.created_at desc limit 1) latest_job,
            (select count(*) from pipeline.jobs j
             where j.domain='ranking' and j.payload->>'import_id'=mi.id::text)::integer job_count
          from latest_editions mi join ranking.systems s on s.id=mi.system_id
          order by mi.updated_at desc nulls last,mi.uploaded_at desc nulls last,mi.id desc
          limit v_limit offset v_offset
        ) x
      ),'[]'::jsonb)
    )
  );
end
$$;


ALTER FUNCTION "security"."admin_ranking_imports_read"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_ranking_links_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_system text := nullif(p_args->>'system_code', ''); v_year int := nullif(p_args->>'edition_year', '')::int;
        v_country text := nullif(p_args->>'country', ''); v_provider uuid := nullif(p_args->>'provider_id', '')::uuid; v_query text := nullif(btrim(p_args->>'query'), '');
begin
  if auth.uid() is null or v_rank < 1 then raise exception 'assigned CourseFinder role required' using errcode = '42501'; end if;
  if p_operation = 'ranking_filter_options' then
    return (with base as (
        select pi.country_text, o.provider_id, coalesce(p.display_name, p.canonical_name) provider_name, sd.code state_code, sd.name state_name
          from ranking.observations o join ranking.editions e on e.id = o.edition_id join ranking.systems s on s.id = e.system_id
          join ranking.publisher_institutions pi on pi.id = o.publisher_institution_id
          left join catalogue.providers p on p.id = o.provider_id left join ref.subdivisions sd on sd.id = p.subdivision_id
         where e.status = 'accepted' and (v_system is null or s.code = v_system) and (v_year is null or e.edition_year = v_year))
      select jsonb_build_object(
        'can_link', v_rank >= 3,
        'countries', coalesce((select jsonb_agg(jsonb_build_object('value', country_text, 'count', n,
                        'in_catalogue', exists (select 1 from catalogue.providers p2 where p2.country_id = security.ranking_country_id(q.country_text) and p2.lifecycle_status = 'active')) order by n desc, country_text)
                        from (select country_text, count(*) n from base where country_text is not null group by 1) q), '[]'::jsonb),
        'states', coalesce((select jsonb_agg(jsonb_build_object('value', state_code, 'label', state_name, 'count', n) order by state_name)
                        from (select state_code, state_name, count(*) n from base where state_code is not null and (v_country is null or country_text = v_country) group by 1, 2) q), '[]'::jsonb),
        'providers', coalesce((select jsonb_agg(jsonb_build_object('value', provider_id, 'label', provider_name) order by provider_name)
                        from (select distinct provider_id, provider_name from base where provider_id is not null and (v_country is null or country_text = v_country)) q), '[]'::jsonb),
        'linked', (select count(*) from base where provider_id is not null and (v_country is null or country_text = v_country)),
        'not_linked', (select count(*) from base where provider_id is null and (v_country is null or country_text = v_country)),
        'not_linked_in_catalogue_countries', (select count(*) from base b where b.provider_id is null and (v_country is null or b.country_text = v_country)
                        and exists (select 1 from catalogue.providers p2 where p2.country_id = security.ranking_country_id(b.country_text) and p2.lifecycle_status = 'active'))));
  elsif p_operation = 'ranking_link_candidates' then
    return jsonb_build_object('can_link', v_rank >= 3, 'items', coalesce((select jsonb_agg(jsonb_build_object('provider_id', m.provider_id,
             'provider_name', coalesce(p.display_name, p.canonical_name), 'state', sd.code, 'confidence', m.confidence) order by m.confidence desc)
             from ranking.provider_mappings m join catalogue.providers p on p.id = m.provider_id left join ref.subdivisions sd on sd.id = p.subdivision_id
            where m.publisher_institution_id = nullif(p_args->>'publisher_institution_id', '')::uuid and m.status = 'candidate'), '[]'::jsonb));
  elsif p_operation = 'ranking_provider_search' then
    if v_query is null or length(v_query) < 3 then return jsonb_build_object('items', '[]'::jsonb); end if;
    return jsonb_build_object('items', coalesce((select jsonb_agg(x) from (
             select jsonb_build_object('provider_id', p.id, 'provider_name', coalesce(p.display_name, p.canonical_name), 'state', sd.code) x
               from catalogue.providers p left join ref.subdivisions sd on sd.id = p.subdivision_id
              where p.lifecycle_status = 'active' and (v_country is null or p.country_id = security.ranking_country_id(v_country))
                and (coalesce(p.display_name, p.canonical_name) ilike '%' || v_query || '%'
                     or exists (select 1 from catalogue.provider_aliases a where a.provider_id = p.id and a.valid_to is null and a.alias ilike '%' || v_query || '%'))
              order by length(coalesce(p.display_name, p.canonical_name)) limit 20) q), '[]'::jsonb));
  elsif p_operation = 'provider_ranking_history' then
    return jsonb_build_object('items', coalesce((select jsonb_agg(jsonb_build_object('system_code', s.code, 'ranking_name', s.ranking_name, 'edition_year', e.edition_year,
             'rank_display', o.rank_display, 'rank_exact', o.rank_exact, 'overall_score', o.overall_score, 'publisher_name', pi.institution_name,
             'evidence_artifact_id', o.evidence_artifact_id) order by s.code, e.edition_year desc)
             from ranking.observation_provider_links l join ranking.observations o on o.id = l.observation_id
             join ranking.editions e on e.id = o.edition_id and e.status = 'accepted' join ranking.systems s on s.id = e.system_id
             join ranking.publisher_institutions pi on pi.id = o.publisher_institution_id
            where l.provider_id = v_provider), '[]'::jsonb));
  end if;
  raise exception 'unsupported ranking link read: %', p_operation using errcode = '22023';
end $$;


ALTER FUNCTION "security"."admin_ranking_links_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_ranking_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'ranking', 'catalogue', 'ref', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_system text:=nullif(p_args->>'system_code','');
  v_year integer:=nullif(p_args->>'edition_year','')::integer;
  v_provider uuid:=nullif(p_args->>'provider_id','')::uuid;
  v_query text:=nullif(btrim(p_args->>'query'),'');
  v_country text:=nullif(p_args->>'country','');
  v_state text:=nullif(p_args->>'state','');
  v_link text:=nullif(p_args->>'link','');
  v_sort text:=case when lower(coalesce(nullif(p_args->>'sort',''),'rank')) in ('institution','provider','rank','score','country','status','edition','system') then lower(coalesce(nullif(p_args->>'sort',''),'rank')) else 'rank' end;
  v_dir text:=case when lower(coalesce(nullif(p_args->>'direction',''),'asc'))='desc' then 'desc' else 'asc' end;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0)<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;

  if p_operation='ranking_summary' then
    return jsonb_build_object('systems',coalesce((select jsonb_agg(jsonb_build_object('code',s.code,'publisher_name',s.publisher_name,'ranking_name',s.ranking_name,'official_url',s.official_url,'latest_edition',(select max(e.edition_year) from ranking.editions e where e.system_id=s.id and e.status='accepted'),'accepted_editions',(select count(*) from ranking.editions e where e.system_id=s.id and e.status='accepted'),'observations',(select count(*) from ranking.observations o join ranking.editions e on e.id=o.edition_id where e.system_id=s.id and e.status='accepted' and e.edition_year=(select max(e2.edition_year) from ranking.editions e2 where e2.system_id=s.id and e2.status='accepted')),'mapped_observations',(select count(*) from ranking.observations o join ranking.editions e on e.id=o.edition_id where e.system_id=s.id and e.status='accepted' and e.edition_year=(select max(e2.edition_year) from ranking.editions e2 where e2.system_id=s.id and e2.status='accepted') and o.provider_id is not null),'unmapped_observations',(select count(*) from ranking.observations o join ranking.editions e on e.id=o.edition_id where e.system_id=s.id and e.status='accepted' and e.edition_year=(select max(e2.edition_year) from ranking.editions e2 where e2.system_id=s.id and e2.status='accepted') and o.provider_id is null),'total_observations',(select count(*) from ranking.observations o join ranking.editions e on e.id=o.edition_id where e.system_id=s.id and e.status='accepted')) order by s.code) from ranking.systems s where s.active),'[]'::jsonb),'manual_imports',case when v_rank>=4 then (select jsonb_build_object('total',count(*),'uploaded',count(*) filter(where status='uploaded'),'needs_review',count(*) filter(where status='needs_review'),'applied',count(*) filter(where status='applied')) from ranking.manual_imports) else null end);
  elsif p_operation='ranking_filters' then
    return jsonb_build_object('systems',coalesce((select jsonb_agg(jsonb_build_object('code',code,'label',ranking_name) order by code) from ranking.systems where active and (v_system is null or code=v_system)),'[]'::jsonb),'years',coalesce((select jsonb_agg(y order by y desc) from (select distinct e.edition_year y from ranking.editions e join ranking.systems s on s.id=e.system_id where e.status='accepted' and (v_system is null or s.code=v_system)) q),'[]'::jsonb),'editions',coalesce((select jsonb_agg(jsonb_build_object('year',q.edition_year,'observations',q.observations,'mapped_observations',q.mapped_observations) order by q.edition_year desc) from (select e.edition_year,count(o.id)::integer observations,count(o.id) filter(where o.provider_id is not null)::integer mapped_observations from ranking.editions e join ranking.systems s on s.id=e.system_id left join ranking.observations o on o.edition_id=e.id where e.status='accepted' and (v_system is null or s.code=v_system) group by e.id,e.edition_year) q),'[]'::jsonb),'statuses',jsonb_build_array('ranked_exact','ranked_band','reporter','unranked','not_eligible','unknown'));
  elsif p_operation='ranking_observations' then
    return (
      with filtered as (
        select o.id,s.code system_code,s.publisher_name,s.ranking_name,e.edition_year,e.methodology_version,e.methodology_url,e.source_url,pi.institution_name publisher_institution_name,pi.country_text,o.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,o.rank_display,o.rank_exact,o.rank_low,o.rank_high,o.is_tied,o.rank_status,o.overall_score,o.evidence_artifact_id,o.publisher_institution_id,sd.code state_code,sd.name state_name
        from ranking.observations o
        join ranking.editions e on e.id=o.edition_id
        join ranking.systems s on s.id=e.system_id
        join ranking.publisher_institutions pi on pi.id=o.publisher_institution_id
        left join catalogue.providers p on p.id=o.provider_id
        left join ref.subdivisions sd on sd.id=p.subdivision_id
        where e.status='accepted'
          and (v_system is null or s.code=v_system)
          and (v_year is null or e.edition_year=v_year)
          and (v_provider is null or o.provider_id=v_provider or exists(select 1 from ranking.observation_provider_links opl where opl.observation_id=o.id and opl.provider_id=v_provider))
          and (v_query is null or pi.institution_name ilike '%'||v_query||'%' or coalesce(p.display_name,p.canonical_name) ilike '%'||v_query||'%')
          and (v_country is null or pi.country_text=v_country)
          and (v_state is null or sd.code=v_state)
          and (v_link is null or (v_link='linked' and o.provider_id is not null) or (v_link='not_linked' and o.provider_id is null))
      ), ordered as (
        select * from filtered order by
          case when v_sort='institution' and v_dir='asc' then lower(publisher_institution_name) end asc,
          case when v_sort='institution' and v_dir='desc' then lower(publisher_institution_name) end desc,
          case when v_sort='provider' and v_dir='asc' then lower(coalesce(provider_name,'')) end asc,
          case when v_sort='provider' and v_dir='desc' then lower(coalesce(provider_name,'')) end desc,
          case when v_sort='rank' and v_dir='asc' then coalesce(rank_exact,rank_low,999999) end asc,
          case when v_sort='rank' and v_dir='desc' then coalesce(rank_exact,rank_low,-1) end desc,
          case when v_sort='score' and v_dir='asc' then overall_score end asc nulls last,
          case when v_sort='score' and v_dir='desc' then overall_score end desc nulls last,
          case when v_sort='country' and v_dir='asc' then lower(coalesce(country_text,'')) end asc,
          case when v_sort='country' and v_dir='desc' then lower(coalesce(country_text,'')) end desc,
          case when v_sort='status' and v_dir='asc' then lower(coalesce(rank_status,'')) end asc,
          case when v_sort='status' and v_dir='desc' then lower(coalesce(rank_status,'')) end desc,
          case when v_sort='edition' and v_dir='asc' then edition_year end asc,
          case when v_sort='edition' and v_dir='desc' then edition_year end desc,
          case when v_sort='system' and v_dir='asc' then system_code end asc,
          case when v_sort='system' and v_dir='desc' then system_code end desc,
          system_code,edition_year desc,coalesce(rank_exact,rank_low,999999),publisher_institution_name,id
        limit v_limit offset v_offset
      )
      select jsonb_build_object('total',(select count(*) from filtered),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir,'items',coalesce((select jsonb_agg(to_jsonb(x)) from ordered x),'[]'::jsonb))
    );
  elsif p_operation='ranking_imports' then
    if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
    return (select jsonb_build_object('total',(select count(*) from ranking.manual_imports),'limit',v_limit,'offset',v_offset,'items',coalesce((select jsonb_agg(to_jsonb(x) order by x.uploaded_at desc) from (select mi.id,s.code system_code,mi.edition_year,mi.publisher_name,mi.source_url,mi.methodology_url,mi.licensing_note,mi.revision_note,mi.original_filename,mi.mime_type,mi.byte_size,mi.content_hash,mi.storage_path,mi.evidence_artifact_id,mi.status,mi.validation_summary,mi.parse_summary,mi.uploaded_at from ranking.manual_imports mi join ranking.systems s on s.id=mi.system_id order by mi.uploaded_at desc limit v_limit offset v_offset) x),'[]'::jsonb)));
  else
    raise exception 'unsupported ranking read operation: %',p_operation using errcode='22023';
  end if;
end
$$;


ALTER FUNCTION "security"."admin_ranking_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_read_impl"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'catalogue', 'ref', 'pim', 'scholarship', 'pipeline', 'workflow', 'integration', 'search', 'publishing', 'auth'
    AS $$
declare
  v_rank integer := 0;
  v_result jsonb;
  v_id uuid;
  v_limit integer := least(greatest(coalesce((p_args->>'limit')::integer,500),1),2000);
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank < 1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  if p_operation='context' then return public.ui_context();
  elsif p_operation='dashboard' then return public.ui_dashboard();
  elsif p_operation='providers' then select coalesce(jsonb_agg(to_jsonb(x) order by x.canonical_name),'[]'::jsonb) into v_result from public.ui_providers_list(v_limit) x; return v_result;
  elsif p_operation='provider_detail' then
    v_id:=nullif(p_args->>'id','')::uuid;
    select coalesce(public.ui_provider_detail(v_id),'{}'::jsonb)||jsonb_build_object('evidence',coalesce(public.ui_provider_related_evidence(v_id,100,0,null,null)->'rows','[]'::jsonb),'courses',coalesce(public.ui_provider_related_courses(v_id,100,0,null,null,null)->'rows','[]'::jsonb)) into v_result; return v_result;
  elsif p_operation='campuses' then select coalesce(jsonb_agg(to_jsonb(x) order by x.provider_name,x.name),'[]'::jsonb) into v_result from public.ui_campuses_list(v_limit) x; return v_result;
  elsif p_operation='campus_detail' then
    v_id:=nullif(p_args->>'id','')::uuid;
    select jsonb_build_object('id',ca.id,'stable_key',ca.stable_key,'name',ca.name,'campus_code',ca.campus_code,'provider_id',ca.provider_id,'provider_name',coalesce(p.display_name,p.canonical_name),'country_code',co.iso_alpha2,'subdivision_code',sd.code,'subdivision_name',sd.name,'city',ca.city,'address_line1',ca.address_line1,'address_line2',ca.address_line2,'postcode',ca.postcode,'latitude',ca.latitude,'longitude',ca.longitude,'phone',ca.phone,'website',ca.website,'status',ca.status,'publication_status',ca.publication_status,'valid_from',ca.valid_from,'valid_to',ca.valid_to,'last_verified_at',ca.last_verified_at,'created_at',ca.created_at,'updated_at',ca.updated_at,'source',jsonb_build_object('source_id',ca.source_id,'source_label',s.label,'source_type',s.source_type,'source_url',s.url),'evidence',case when e.id is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('id',e.id,'type',e.evidence_type,'source_url',e.source_url,'storage_path',e.storage_path,'content_hash',e.content_hash,'captured_at',e.captured_at)) end,'courses',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'title',c.canonical_title,'delivery_mode',cc.delivery_mode,'is_primary',cc.is_primary) order by c.canonical_title) from catalogue.course_campuses cc join catalogue.courses c on c.id=cc.course_id where cc.campus_id=ca.id),'[]'::jsonb)) into v_result from catalogue.campuses ca join catalogue.providers p on p.id=ca.provider_id join ref.countries co on co.id=ca.country_id left join ref.subdivisions sd on sd.id=ca.subdivision_id left join pipeline.sources s on s.id=ca.source_id left join pipeline.evidence_artifacts e on e.id=ca.evidence_id where ca.id=v_id; return coalesce(v_result,'{}'::jsonb);
  elsif p_operation='courses' or p_operation='completeness' then select coalesce(jsonb_agg(to_jsonb(x) order by x.provider_name,x.canonical_title),'[]'::jsonb) into v_result from public.ui_course_completeness_list(v_limit) x; return v_result;
  elsif p_operation='course_detail' then
    v_id:=nullif(p_args->>'id','')::uuid;
    select coalesce(public.ui_course_detail(v_id),'{}'::jsonb)||jsonb_build_object(
      'fee_summary',jsonb_build_object(
        'cricos_registered',coalesce((select jsonb_agg(jsonb_build_object('id',cf.id,'fee_type',cf.fee_type,'amount',cf.amount,'currency',cf.currency_code,'basis',cf.basis,'fee_year',cf.fee_year,'audience',cf.audience,'status',cf.status,'source_snapshot_at',cf.source_snapshot_at,'evidence_id',cf.evidence_id) order by cf.fee_type) from catalogue.course_fees cf where cf.course_id=v_id and cf.basis='registered_total_course' and coalesce(cf.status,'active')='active'),'[]'::jsonb),
        'provider_current',coalesce((select jsonb_agg(jsonb_build_object('id',cf.id,'fee_type',cf.fee_type,'amount',cf.amount,'currency',cf.currency_code,'basis',cf.basis,'fee_year',cf.fee_year,'audience',cf.audience,'status',cf.status,'source_snapshot_at',cf.source_snapshot_at,'source_id',cf.source_id,'evidence_id',cf.evidence_id) order by cf.fee_year desc nulls last,cf.created_at desc) from catalogue.course_fees cf where cf.course_id=v_id and cf.basis is distinct from 'registered_total_course' and coalesce(cf.status,'active')='active'),'[]'::jsonb)
      ),
      'regulatory_facts',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('scheme',o.scheme,'registration_code',o.registration_code,'status',o.status,'course_language',o.course_language,'work_component',o.work_component,'work_component_total_hours',o.work_component_total_hours,'foundation_studies',o.foundation_studies,'dual_qualification',o.dual_qualification,'source_snapshot_at',o.source_snapshot_at,'evidence_id',o.evidence_id)) order by o.source_snapshot_at desc) from catalogue.course_regulatory_observations o where o.course_id=v_id and o.valid_to is null),'[]'::jsonb),
      'campuses',coalesce(public.ui_course_related_campuses(v_id),'[]'::jsonb),
      'evidence',coalesce((select jsonb_agg(distinct jsonb_build_object('id',e.id,'evidence_type',e.evidence_type,'source_url',e.source_url,'storage_path',e.storage_path,'content_hash',e.content_hash,'captured_at',e.captured_at,'valid_from',e.valid_from,'valid_to',e.valid_to)) from pipeline.evidence_artifacts e where e.id in (
        select evidence_id from catalogue.course_fees where course_id=v_id and evidence_id is not null
        union select evidence_id from catalogue.course_registrations where course_id=v_id and evidence_id is not null
        union select evidence_id from catalogue.course_regulatory_observations where course_id=v_id and evidence_id is not null
        union select evidence_id from catalogue.course_links where course_id=v_id and evidence_id is not null
        union select av.evidence_id from pim.attribute_values av join pim.entity_registry er on er.id=av.entity_id where er.entity_type='course' and er.stable_key=(select stable_key from catalogue.courses where id=v_id) and av.evidence_id is not null
      ) or e.entity_id=v_id),'[]'::jsonb)
    ) into v_result;
    return v_result;
  elsif p_operation='scholarships' then select coalesce(jsonb_agg(to_jsonb(x) order by x.provider_name,x.name),'[]'::jsonb) into v_result from public.ui_scholarships_list(v_limit) x; return v_result;
  elsif p_operation='scholarship_detail' then v_id:=nullif(p_args->>'id','')::uuid; return coalesce(public.ui_scholarship_detail(v_id),'{}'::jsonb);
  elsif p_operation='evidence' then if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if; select coalesce(jsonb_agg(to_jsonb(x) order by x.captured_at desc),'[]'::jsonb) into v_result from public.ui_evidence_governance_list(v_limit) x; return v_result;
  elsif p_operation='reviews' then if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if; select coalesce(jsonb_agg(to_jsonb(x) order by x.priority desc,x.created_at desc),'[]'::jsonb) into v_result from public.ui_review_queue(v_limit) x; return v_result;
  elsif p_operation='attributes' then if v_rank<5 then raise exception 'pim_admin role required' using errcode='42501'; end if; select jsonb_build_object('families',coalesce((select jsonb_agg(to_jsonb(x)) from public.ui_attribute_families_list() x),'[]'::jsonb),'groups',coalesce((select jsonb_agg(to_jsonb(x)) from public.ui_attribute_groups_list() x),'[]'::jsonb),'attributes',coalesce((select jsonb_agg(to_jsonb(x)) from public.ui_attributes_list() x),'[]'::jsonb),'options',coalesce((select jsonb_agg(to_jsonb(x)) from public.ui_attribute_options_list(v_limit) x),'[]'::jsonb),'completeness_profiles',coalesce((select jsonb_agg(to_jsonb(x)) from public.ui_completeness_profiles_list() x),'[]'::jsonb)) into v_result; return v_result;
  elsif p_operation='jobs' then if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if; select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) into v_result from public.ui_jobs_list(v_limit) x; return v_result;
  elsif p_operation='sources' then if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if; select coalesce(jsonb_agg(to_jsonb(x) order by x.country_code,x.source_label),'[]'::jsonb) into v_result from public.ui_regulatory_sources_list() x; return v_result;
  else raise exception 'unsupported admin read operation: %',p_operation using errcode='22023';
  end if;
end$$;


ALTER FUNCTION "security"."admin_read_impl"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_redact_json"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare
  v_type text;
  v_result jsonb;
begin
  if p_value is null then return null; end if;
  v_type := jsonb_typeof(p_value);
  if v_type='object' then
    select coalesce(jsonb_object_agg(
      key,
      case
        when key ~* '(secret|token|password|credential|authorization|service.?role|api.?key|private.?key)'
          then '"[redacted]"'::jsonb
        else security.admin_redact_json(value)
      end
    ),'{}'::jsonb)
    into v_result
    from jsonb_each(p_value);
    return v_result;
  elsif v_type='array' then
    select coalesce(jsonb_agg(security.admin_redact_json(value) order by ordinality),'[]'::jsonb)
    into v_result
    from jsonb_array_elements(p_value) with ordinality;
    return v_result;
  end if;
  return p_value;
end
$$;


ALTER FUNCTION "security"."admin_redact_json"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_requeue_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  return jsonb_build_object('can_control',security.current_role_rank()>=5,
    'groups',(select coalesce(jsonb_agg(jsonb_build_object('field',g.field_code,'reason',g.reason,'items',g.n,'oldest',g.oldest) order by g.n desc),'[]'::jsonb)
      from (select l.field_code, security.review_reason_key(l.escalation_reason) reason, count(*) n, min(l.created_at) oldest from pipeline.layer4_review_items l
             where l.status='pending' and l.layer3_interpretation_id is not null and l.before_value is null
               and l.field_code in ('course_intake','course_english','provider_current_tuition_validation') group by 1,2) g),
    'stays_with_person',(select jsonb_object_agg(field_code,n) from (select field_code,count(*) n from pipeline.layer4_review_items where status='pending' and (layer3_interpretation_id is null or before_value is not null) group by 1) x),
    'layer3_failed',(select jsonb_object_agg(task_class,n) from (select task_class,count(*) n from pipeline.layer3_work_items where status in ('failed','parked') and coalesce(last_error,'') not like 'released:%' group by 1) y),
    'layer3_waiting',(select jsonb_object_agg(task_class,n) from (select task_class,count(*) n from (
         select task_class from pipeline.layer3_fact_handoffs where work_item_id is null
         union all select task_class from pipeline.layer3_work_items where status='pending') z group by 1) y),
    'models',jsonb_build_object(
       'course_intake',(select coalesce(jsonb_agg(jsonb_build_object('profile',p.code,'model',p.model_identifier,'in_cascade',t.active,'cost_per_1000_usd',round(t.cost_per_call_usd*1000,2)) order by t.tier_no),'[]'::jsonb)
          from pipeline.layer3_route_tiers t join pipeline.layer3_model_profiles p on p.id=t.profile_id where t.task_class='provider_intake_validation' and p.enabled and not p.paused and p.retired_at is null),
       'course_english',(select coalesce(jsonb_agg(jsonb_build_object('profile',p.code,'model',p.model_identifier,'in_cascade',t.active,'cost_per_1000_usd',round(t.cost_per_call_usd*1000,2)) order by t.tier_no),'[]'::jsonb)
          from pipeline.layer3_route_tiers t join pipeline.layer3_model_profiles p on p.id=t.profile_id where t.task_class='provider_english_validation' and p.enabled and not p.paused and p.retired_at is null),
       'provider_current_tuition_validation',(select coalesce(jsonb_agg(jsonb_build_object('profile',p.code,'model',p.model_identifier,'in_cascade',true,'cost_per_1000_usd',null)),'[]'::jsonb)
          from pipeline.layer3_model_profiles p where 'provider_current_tuition_validation'=any(p.allowed_task_classes) and p.enabled and not p.paused and p.retired_at is null
           and coalesce((p.quality_benchmark->>'pass')::boolean,false))),
    'events',(select coalesce(jsonb_agg(jsonb_build_object('at',e.created_at,'action',e.action,'target',e.target,'detail',e.detail) order by e.created_at desc),'[]'::jsonb)
                from (select * from pipeline.admin_control_events where area='requeue' order by created_at desc limit 10) e));
end $$;


ALTER FUNCTION "security"."admin_requeue_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_requeue_v1"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_field text:=p_args->>'field'; v_reason text:=p_args->>'reason'; v_task text:=p_args->>'task'; v_n int:=0; v_tuition uuid; v_pin uuid; v_code text:=nullif(btrim(coalesce(p_args->>'profile','')),'');
begin
  if auth.uid() is null or security.current_role_rank()<5 then raise exception 'Platform Admin role required' using errcode='42501'; end if;
  if p_action='send_back' then
    if v_field not in ('course_intake','course_english','provider_current_tuition_validation') then raise exception 'unsupported field'; end if;
    select id into v_tuition from pipeline.layer3_model_profiles where 'provider_current_tuition_validation'=any(allowed_task_classes) and enabled and not paused and retired_at is null
       and coalesce((quality_benchmark->>'pass')::boolean,false) order by updated_at desc limit 1;
    -- optional: one named Layer 3 model for these items (any model in the task's cascade, on or off; for tuition a qualified tuition model)
    if v_code is not null then
      if v_field='provider_current_tuition_validation' then
        select id into v_pin from pipeline.layer3_model_profiles where code=v_code and 'provider_current_tuition_validation'=any(allowed_task_classes) and enabled and not paused
           and retired_at is null and coalesce((quality_benchmark->>'pass')::boolean,false);
        v_tuition:=v_pin;
      else
        select p.id into v_pin from pipeline.layer3_route_tiers t join pipeline.layer3_model_profiles p on p.id=t.profile_id
         where t.task_class=case v_field when 'course_intake' then 'provider_intake_validation' else 'provider_english_validation' end
           and p.code=v_code and p.enabled and not p.paused and p.retired_at is null;
      end if;
      if v_pin is null then raise exception 'choose a model from the list for this field'; end if;
    end if;
    with l4 as (
      update pipeline.layer4_review_items l set status='superseded', decided_at=now(),
             escalation_reason='Superseded: sent back to Layer 3 to be retried (Admin control).'
       where l.status='pending' and l.layer3_interpretation_id is not null and l.before_value is null and l.field_code=v_field
         and (v_reason is null or security.review_reason_key(l.escalation_reason)=v_reason)
      returning l.layer3_interpretation_id),
    fact as (
      update pipeline.layer3_work_items w set status='failed', updated_at=now(), last_error='released: sent back to Layer 3 (Admin control)'
        from l4 where v_field<>'provider_current_tuition_validation' and w.interpretation_id=l4.layer3_interpretation_id and w.status='layer4_required'
      returning w.id),
    hand as (update pipeline.layer3_fact_handoffs h set work_item_id=null, attempts=0, pinned_profile_id=v_pin from fact where h.work_item_id=fact.id returning h.id),
    tui as (
      update pipeline.layer3_work_items w set status='pending', profile_id=v_tuition, reserved_at=null, reserved_by=null, interpretation_id=null, available_at=now(), updated_at=now(),
             last_error='requeued: sent back to Layer 3 (Admin control)'
        from l4 where v_field='provider_current_tuition_validation' and v_tuition is not null and w.interpretation_id=l4.layer3_interpretation_id and w.status='layer4_required'
      returning w.id)
    select (select count(*) from l4) into v_n;
  elsif p_action='retry_failed' then
    if v_task in ('provider_intake_validation','provider_english_validation') then
      update pipeline.layer3_fact_handoffs h set attempts=0 where h.task_class=v_task and h.work_item_id is null and h.attempts>0;
      get diagnostics v_n = row_count;
    elsif v_task='provider_current_tuition_validation' then
      select id into v_tuition from pipeline.layer3_model_profiles where 'provider_current_tuition_validation'=any(allowed_task_classes) and enabled and not paused and retired_at is null
         and coalesce((quality_benchmark->>'pass')::boolean,false) order by updated_at desc limit 1;
      update pipeline.layer3_work_items set status='pending', profile_id=v_tuition, reserved_at=null, reserved_by=null, interpretation_id=null, available_at=now(), updated_at=now(),
             last_error='requeued: retry failed (Admin control)'
       where task_class=v_task and status in ('failed','parked') and v_tuition is not null
         and security.tuition_chase_enabled((select c.provider_id from catalogue.courses c where c.id=entity_id));
      get diagnostics v_n = row_count;
    else raise exception 'unknown task'; end if;
  else raise exception 'unknown action'; end if;
  insert into pipeline.admin_control_events(area,action,target,detail,actor) values ('requeue',p_action,coalesce(v_field,v_task),p_args||jsonb_build_object('moved',v_n),auth.uid());
  return security.admin_requeue_read_v1()||jsonb_build_object('moved',v_n);
end $$;


ALTER FUNCTION "security"."admin_requeue_v1"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_scholarship_publishing_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'scholarship', 'catalogue', 'security'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  return (with p as (select * from security.scholarship_publishability_v1())
  select jsonb_build_object('can_control',security.current_role_rank()>=5,
    'counts',jsonb_build_object('published',(select count(*) from scholarship.scholarships where publication_status='published'),
       'eligible',(select count(*) from p join scholarship.scholarships s on s.id=p.scholarship_id where p.publishable and coalesce(s.publication_status,'unpublished')<>'published'
         and not exists (select 1 from security.layer4_search_blocked_scholarships b where b.scholarship_id=s.id)),
       'held',(select count(*) from pipeline.scholarship_publication_holds where released_at is null),
       'domestic_only',(select count(*) from p join scholarship.scholarships s on s.id=p.scholarship_id where s.lifecycle_status='active' and 'eligibility lists domestic students only'=any(p.missing)),
       'active',(select count(*) from scholarship.scholarships where lifecycle_status='active'),
       'published_failing',(select count(*) from p join scholarship.scholarships s on s.id=p.scholarship_id where s.publication_status='published' and not p.publishable)),
    'published_failing',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'provider',coalesce(pr.display_name,pr.canonical_name),'page',s.source_url,'reason',array_to_string(p.missing,'; ')) order by coalesce(pr.display_name,pr.canonical_name),s.name),'[]'::jsonb)
       from p join scholarship.scholarships s on s.id=p.scholarship_id left join catalogue.providers pr on pr.id=s.provider_id where s.publication_status='published' and not p.publishable),
    'not_publishable_reasons',(select jsonb_object_agg(m,n) from (select unnest(p.missing) m,count(*) n from p join scholarship.scholarships s on s.id=p.scholarship_id where s.lifecycle_status='active' group by 1) x),
    'eligible',(select coalesce(jsonb_agg(x order by x->>'provider',x->>'name'),'[]'::jsonb) from (select jsonb_build_object('id',s.id,'name',s.name,'provider',coalesce(pr.display_name,pr.canonical_name),
         'value',scholarship.value_label(s.id),
         'page',s.source_url,'courses',(select count(*) from scholarship.course_mappings m where m.scholarship_id=s.id and m.mapping_state='mapped')) x
       from p join scholarship.scholarships s on s.id=p.scholarship_id left join catalogue.providers pr on pr.id=s.provider_id
      where p.publishable and coalesce(s.publication_status,'unpublished')<>'published'
        and not exists (select 1 from security.layer4_search_blocked_scholarships b where b.scholarship_id=s.id) limit 300) y),
    'domestic_only',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'provider',coalesce(pr.display_name,pr.canonical_name),'page',s.source_url,
         'published',s.publication_status='published',
         'words',(select left(cr.human_text,240) from scholarship.criteria cr where cr.scholarship_id=s.id and cr.status='active' and cr.criterion_type='student_type' and cr.value_json->>'by'='scholarship_sweep' limit 1))
         order by coalesce(pr.display_name,pr.canonical_name),s.name),'[]'::jsonb)
       from p join scholarship.scholarships s on s.id=p.scholarship_id left join catalogue.providers pr on pr.id=s.provider_id
      where s.lifecycle_status='active' and 'eligibility lists domestic students only'=any(p.missing)),
    'held',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'provider',coalesce(pr.display_name,pr.canonical_name),'reason',h.reason,'at',h.held_at) order by h.held_at desc),'[]'::jsonb)
       from pipeline.scholarship_publication_holds h join scholarship.scholarships s on s.id=h.scholarship_id left join catalogue.providers pr on pr.id=s.provider_id where h.released_at is null),
    'published',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'provider',coalesce(pr.display_name,pr.canonical_name),'page',s.source_url) order by coalesce(pr.display_name,pr.canonical_name),s.name),'[]'::jsonb)
       from scholarship.scholarships s left join catalogue.providers pr on pr.id=s.provider_id where s.publication_status='published'),
    'events',(select coalesce(jsonb_agg(jsonb_build_object('at',e.created_at,'action',e.action,'target',e.target,'detail',e.detail) order by e.created_at desc),'[]'::jsonb)
                from (select * from pipeline.admin_control_events where area='scholarships' order by created_at desc limit 10) e)));
end $$;


ALTER FUNCTION "security"."admin_scholarship_publishing_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_scholarship_publishing_v1"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'scholarship', 'security'
    AS $$
declare v_id uuid:=nullif(p_args->>'id','')::uuid; v_res jsonb;
begin
  if auth.uid() is null or security.current_role_rank()<5 then raise exception 'Platform Admin role required' using errcode='42501'; end if;
  if p_action='publish_batch' then
    if coalesce(btrim(p_args->>'approval'),'')='' then raise exception 'an approval note is required'; end if;
    if (security.scholarship_publish_batch_v1('dry run',false)->>'eligible')::int<>(p_args->>'expected')::int then raise exception 'the eligible list changed; refresh and check again'; end if;
    v_res:=security.scholarship_publish_batch_v1('CF-CHG-20260915-247; Decision 139; '||btrim(p_args->>'approval'),true);
  elsif p_action='hold' then
    if coalesce(btrim(p_args->>'reason'),'')='' then raise exception 'a reason is required'; end if;
    insert into pipeline.scholarship_publication_holds(scholarship_id,reason,held_by) values (v_id,btrim(p_args->>'reason'),'admin')
    on conflict (scholarship_id) do update set reason=excluded.reason, held_by='admin', held_at=now(), released_at=null, release_note=null;
    update scholarship.scholarships set publication_status='withdrawn', updated_at=now() where id=v_id and publication_status='published';
  elsif p_action='release' then
    update pipeline.scholarship_publication_holds set released_at=now(), release_note=coalesce(p_args->>'note','released by an admin') where scholarship_id=v_id and released_at is null;
  elsif p_action='withdraw' then
    update scholarship.scholarships set publication_status='withdrawn', updated_at=now() where id=v_id and publication_status='published';
    insert into pipeline.scholarship_publication_batches(kind,approval_ref,scholarship_ids) values ('withdraw','Admin control: '||coalesce(p_args->>'reason','withdrawn'),array[v_id]);
  elsif p_action='confirm_international' then
    if coalesce(btrim(p_args->>'note'),'')='' then raise exception 'a note is required'; end if;
    insert into scholarship.criteria(scholarship_id,criterion_type,operator,value_codes,value_json,human_text,is_mandatory,machine_evaluable,status,confidence)
    values (v_id,'student_type','in',array['international'],jsonb_build_object('by','person','actor',auth.uid(),'decision','Decision 212'),left(btrim(p_args->>'note'),300),true,true,'active',1);
  else raise exception 'unknown action'; end if;
  insert into pipeline.admin_control_events(area,action,target,detail,actor) values ('scholarships',p_action,v_id::text,p_args||coalesce(jsonb_build_object('result',v_res),'{}'::jsonb),auth.uid());
  return security.admin_scholarship_publishing_read_v1();
end $$;


ALTER FUNCTION "security"."admin_scholarship_publishing_v1"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_scholarship_semantic_summary"("p_scholarship_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'scholarship', 'catalogue', 'ref', 'pipeline'
    AS $$
declare
  v_rank integer;
begin
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0) < 1 then
    raise exception 'assigned CourseFinder role required' using errcode='42501';
  end if;

  return jsonb_build_object(
    'record_provenance', coalesce((
      select jsonb_build_object(
        'source', case when ps.id is null then null else jsonb_build_object(
          'id',ps.id,'label',ps.label,'type',ps.source_type,'url',ps.url
        ) end,
        'evidence', case when pe.id is null then null else jsonb_build_object(
          'id',pe.id,'type',pe.evidence_type,'source_url',pe.source_url,
          'captured_at',pe.captured_at,'content_hash',pe.content_hash,
          'valid_from',pe.valid_from,'valid_to',pe.valid_to
        ) end
      )
      from scholarship.scholarships s
      left join pipeline.sources ps on ps.id=s.source_id
      left join pipeline.evidence_artifacts pe on pe.id=s.evidence_id
      where s.id=p_scholarship_id
    ), '{}'::jsonb),
    'cycles', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',cy.id,
          'cycle_code',cy.cycle_code,
          'academic_year',cy.academic_year,
          'intake_label',cy.intake_label,
          'valid_from',cy.valid_from,
          'valid_to',cy.valid_to,
          'status',cy.status,
          'metadata',cy.metadata,
          'source',case when cys.id is null then null else jsonb_build_object('id',cys.id,'label',cys.label,'type',cys.source_type,'url',cys.url) end,
          'evidence',case when cye.id is null then null else jsonb_build_object('id',cye.id,'type',cye.evidence_type,'source_url',cye.source_url,'captured_at',cye.captured_at,'content_hash',cye.content_hash) end,
          'application_windows',coalesce((
            select jsonb_agg(jsonb_build_object(
              'id',w.id,'round_code',w.round_code,'label',w.label,'opens_at',w.opens_at,'closes_at',w.closes_at,
              'application_method',w.application_method,'application_url',w.application_url,'status',w.status,'metadata',w.metadata,
              'source',case when ws.id is null then null else jsonb_build_object('id',ws.id,'label',ws.label,'type',ws.source_type,'url',ws.url) end,
              'evidence',case when we.id is null then null else jsonb_build_object('id',we.id,'type',we.evidence_type,'source_url',we.source_url,'captured_at',we.captured_at,'content_hash',we.content_hash) end
            ) order by w.opens_at nulls last,w.closes_at nulls last,w.label)
            from scholarship.application_windows w
            left join pipeline.sources ws on ws.id=w.source_id
            left join pipeline.evidence_artifacts we on we.id=w.evidence_id
            where w.scholarship_id=p_scholarship_id and w.cycle_id=cy.id
          ),'[]'::jsonb),
          'scopes',coalesce((
            select jsonb_agg(jsonb_build_object(
              'id',sc.id,'scope_type',sc.scope_type,'include_exclude',sc.include_exclude,
              'target',jsonb_strip_nulls(jsonb_build_object(
                'provider',case when p.id is null then null else jsonb_build_object('id',p.id,'stable_key',p.stable_key,'name',p.canonical_name) end,
                'course',case when c.id is null then null else jsonb_build_object('id',c.id,'stable_key',c.stable_key,'name',c.canonical_title) end,
                'course_collection',case when cc.id is null then null else jsonb_build_object('id',cc.id,'stable_key',cc.stable_key,'code',cc.code,'name',cc.name) end,
                'study_level',case when sl.id is null then null else jsonb_build_object('id',sl.id,'code',sl.code,'name',sl.name) end,
                'field',case when f.id is null then null else jsonb_build_object('id',f.id,'code',f.code,'name',f.name) end,
                'country',case when co.id is null then null else jsonb_build_object('id',co.id,'code',co.iso_alpha2,'name',co.name) end,
                'campus',case when ca.id is null then null else jsonb_build_object('id',ca.id,'stable_key',ca.stable_key,'name',ca.name) end
              )),
              'source',case when ss.id is null then null else jsonb_build_object('id',ss.id,'label',ss.label,'type',ss.source_type,'url',ss.url) end,
              'evidence',case when se.id is null then null else jsonb_build_object('id',se.id,'type',se.evidence_type,'source_url',se.source_url,'captured_at',se.captured_at,'content_hash',se.content_hash) end
            ) order by sc.scope_type,sc.include_exclude)
            from scholarship.scopes sc
            left join catalogue.providers p on p.id=sc.provider_id
            left join catalogue.courses c on c.id=sc.course_id
            left join catalogue.course_collections cc on cc.id=sc.course_collection_id
            left join ref.study_levels sl on sl.id=sc.study_level_id
            left join ref.fields_of_study f on f.id=sc.field_id
            left join ref.countries co on co.id=sc.country_id
            left join catalogue.campuses ca on ca.id=sc.campus_id
            left join pipeline.sources ss on ss.id=sc.source_id
            left join pipeline.evidence_artifacts se on se.id=sc.evidence_id
            where sc.scholarship_id=p_scholarship_id and sc.cycle_id=cy.id
          ),'[]'::jsonb),
          'eligibility_groups',coalesce((
            select jsonb_agg(jsonb_build_object(
              'id',g.id,'group_code',g.group_code,'label',g.label,'parent_group_id',g.parent_group_id,
              'conjunction',g.conjunction,'is_mandatory',g.is_mandatory,'display_order',g.display_order,
              'source',case when gs.id is null then null else jsonb_build_object('id',gs.id,'label',gs.label,'type',gs.source_type,'url',gs.url) end,
              'evidence',case when ge.id is null then null else jsonb_build_object('id',ge.id,'type',ge.evidence_type,'source_url',ge.source_url,'captured_at',ge.captured_at,'content_hash',ge.content_hash) end,
              'criteria',coalesce((
                select jsonb_agg(jsonb_build_object(
                  'id',cr.id,'criterion_type',cr.criterion_type,'operator',cr.operator,'value_text',cr.value_text,
                  'value_number',cr.value_number,'value_codes',cr.value_codes,'value_json',cr.value_json,'human_text',cr.human_text,
                  'is_mandatory',cr.is_mandatory,'machine_evaluable',cr.machine_evaluable,'status',cr.status,'confidence',cr.confidence,
                  'source',case when crs.id is null then null else jsonb_build_object('id',crs.id,'label',crs.label,'type',crs.source_type,'url',crs.url) end,
                  'evidence',case when cre.id is null then null else jsonb_build_object('id',cre.id,'type',cre.evidence_type,'source_url',cre.source_url,'captured_at',cre.captured_at,'content_hash',cre.content_hash) end
                ) order by cr.criterion_type,cr.id)
                from scholarship.criteria cr
                left join pipeline.sources crs on crs.id=cr.source_id
                left join pipeline.evidence_artifacts cre on cre.id=cr.evidence_id
                where cr.scholarship_id=p_scholarship_id and cr.criterion_group_id=g.id
              ),'[]'::jsonb)
            ) order by g.display_order,g.group_code)
            from scholarship.criterion_groups g
            left join pipeline.sources gs on gs.id=g.source_id
            left join pipeline.evidence_artifacts ge on ge.id=g.evidence_id
            where g.scholarship_id=p_scholarship_id and g.cycle_id=cy.id
          ),'[]'::jsonb),
          'award_tiers',coalesce((
            select jsonb_agg(jsonb_build_object(
              'id',a.id,'tier_code',a.tier_code,'label',a.label,'amount',a.amount,'currency_code',a.currency_code,
              'percentage',a.percentage,'basis',a.basis,'maximum_amount',a.maximum_amount,'notes',a.notes,'display_order',a.display_order,
              'source',case when axs.id is null then null else jsonb_build_object('id',axs.id,'label',axs.label,'type',axs.source_type,'url',axs.url) end,
              'evidence',case when axe.id is null then null else jsonb_build_object('id',axe.id,'type',axe.evidence_type,'source_url',axe.source_url,'captured_at',axe.captured_at,'content_hash',axe.content_hash) end
            ) order by a.display_order,a.label)
            from scholarship.award_tiers a
            left join pipeline.sources axs on axs.id=a.source_id
            left join pipeline.evidence_artifacts axe on axe.id=a.evidence_id
            where a.scholarship_id=p_scholarship_id and a.cycle_id=cy.id
          ),'[]'::jsonb),
          'coverage',coalesce((
            select jsonb_agg(jsonb_build_object(
              'id',cv.id,'coverage_type',cv.coverage_type,'percentage',cv.percentage,'amount',cv.amount,'currency_code',cv.currency_code,
              'duration_value',cv.duration_value,'duration_unit',cv.duration_unit,'notes',cv.notes,
              'source',case when cvs.id is null then null else jsonb_build_object('id',cvs.id,'label',cvs.label,'type',cvs.source_type,'url',cvs.url) end,
              'evidence',case when cve.id is null then null else jsonb_build_object('id',cve.id,'type',cve.evidence_type,'source_url',cve.source_url,'captured_at',cve.captured_at,'content_hash',cve.content_hash) end
            ) order by cv.coverage_type)
            from scholarship.coverage cv
            left join pipeline.sources cvs on cvs.id=cv.source_id
            left join pipeline.evidence_artifacts cve on cve.id=cv.evidence_id
            where cv.scholarship_id=p_scholarship_id and cv.cycle_id=cy.id
          ),'[]'::jsonb)
        ) order by cy.academic_year desc nulls last,cy.cycle_code
      )
      from scholarship.offering_cycles cy
      left join pipeline.sources cys on cys.id=cy.source_id
      left join pipeline.evidence_artifacts cye on cye.id=cy.evidence_id
      where cy.scholarship_id=p_scholarship_id
    ),'[]'::jsonb),
    'unscoped', jsonb_build_object(
      'application_windows',coalesce((select jsonb_agg(to_jsonb(w) order by w.opens_at nulls last,w.label) from scholarship.application_windows w where w.scholarship_id=p_scholarship_id and w.cycle_id is null),'[]'::jsonb),
      'scopes',coalesce((select jsonb_agg(to_jsonb(sc) order by sc.scope_type) from scholarship.scopes sc where sc.scholarship_id=p_scholarship_id and sc.cycle_id is null),'[]'::jsonb),
      'eligibility_groups',coalesce((select jsonb_agg(to_jsonb(g) order by g.display_order,g.group_code) from scholarship.criterion_groups g where g.scholarship_id=p_scholarship_id and g.cycle_id is null),'[]'::jsonb),
      'criteria',coalesce((select jsonb_agg(to_jsonb(cr) order by cr.criterion_type) from scholarship.criteria cr where cr.scholarship_id=p_scholarship_id and cr.cycle_id is null),'[]'::jsonb),
      'award_tiers',coalesce((select jsonb_agg(to_jsonb(a) order by a.display_order,a.label) from scholarship.award_tiers a where a.scholarship_id=p_scholarship_id and a.cycle_id is null),'[]'::jsonb),
      'coverage',coalesce((select jsonb_agg(to_jsonb(cv) order by cv.coverage_type) from scholarship.coverage cv where cv.scholarship_id=p_scholarship_id and cv.cycle_id is null),'[]'::jsonb)
    )
  );
end;
$$;


ALTER FUNCTION "security"."admin_scholarship_semantic_summary"("p_scholarship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_scholarships_page"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'scholarship', 'catalogue', 'ref', 'pipeline', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_sort text:=lower(coalesce(nullif(p_args->>'sort',''),'scholarship'));
  v_dir text:=case when lower(coalesce(nullif(p_args->>'direction',''),'asc'))='desc' then 'desc' else 'asc' end;
  v_provider_id uuid:=nullif(p_args->>'provider_id','')::uuid;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0)<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;

  return (
    with pub as materialized (select scholarship_id, publishable, missing from security.scholarship_publishability_v1()),
    base as (
      select s.id,s.stable_key,s.name,s.scholarship_type,s.description,s.audience,s.nationalities,scholarship.value_label(s.id) value_label,
        case when s.lifecycle_status <> 'active' then 'inactive' when s.publication_status = 'published' then 'published' when coalesce(pb.publishable, false) then 'ready' else 'held' end status,
        coalesce(pb.missing, '{}'::text[]) held_reasons,s.award_value_text,s.award_value_type,s.award_percentage,s.award_amount,s.award_currency_code,s.academic_year,s.application_required,s.application_open_date,s.application_close_date,s.lifecycle_status,s.publication_status,s.source_url,s.created_at,s.updated_at,s.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,co.iso_alpha2::text country_code,co.name country_name,co.default_currency_code::text currency_code,
        (select count(*)::int from scholarship.offering_cycles oc where oc.scholarship_id=s.id) cycle_count,
        (select count(*)::int from scholarship.application_windows aw where aw.scholarship_id=s.id) window_count,
        (select count(*)::int from pipeline.evidence_artifacts e where e.entity_id=s.id)+case when s.evidence_id is not null then 1 else 0 end evidence_count,
        (select count(*)::int from scholarship.course_mappings m where m.scholarship_id=s.id and m.mapping_state='mapped') mapped_course_count,
        (select count(*)::int from scholarship.course_mapping_candidates mc where mc.scholarship_id=s.id and mc.status='needs_review') review_course_count,
        left(regexp_replace(coalesce(s.description,''),'\s+',' ','g'),220) description_excerpt
      from scholarship.scholarships s
      left join catalogue.providers p on p.id=s.provider_id
      left join ref.countries co on co.id=p.country_id
      left join pub pb on pb.scholarship_id=s.id
      where (nullif(trim(coalesce(p_args->>'query','')),'') is null
          or s.name ilike '%'||trim(p_args->>'query')||'%'
          or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_args->>'query')||'%'
          or coalesce(s.stable_key,'') ilike '%'||trim(p_args->>'query')||'%'
          or coalesce(s.description,'') ilike '%'||trim(p_args->>'query')||'%'
          or coalesce(s.award_value_text,'') ilike '%'||trim(p_args->>'query')||'%'
          or coalesce(s.scholarship_type,'') ilike '%'||trim(p_args->>'query')||'%'
          or coalesce(s.academic_year::text,'') ilike '%'||trim(p_args->>'query')||'%')
        and (nullif(p_args->>'country_code','') is null or co.iso_alpha2::text=upper(p_args->>'country_code'))
        and (v_provider_id is null or s.provider_id=v_provider_id)
        and (nullif(p_args->>'lifecycle_status','') is null or s.lifecycle_status=p_args->>'lifecycle_status')
        and (nullif(p_args->>'publication_status','') is null or s.publication_status=p_args->>'publication_status')
        and (nullif(p_args->>'audience','') is null or s.audience::text=p_args->>'audience')
        and (nullif(trim(coalesce(p_args->>'course','')),'') is null or exists (
              select 1 from scholarship.course_mappings cm join catalogue.courses c on c.id=cm.course_id
               where cm.scholarship_id=s.id and cm.mapping_state='mapped'
                 and (c.canonical_title ilike '%'||trim(p_args->>'course')||'%' or coalesce(c.display_title,'') ilike '%'||trim(p_args->>'course')||'%' or coalesce(c.course_code,'') ilike trim(p_args->>'course')||'%')))
    ), numbered as (
      select *,count(*) over() total_count from base
       where case when coalesce(p_args->>'status','') = '' then status <> 'inactive' else status = p_args->>'status' end
    ), ordered as (
      select * from numbered order by
        case when v_sort='scholarship' and v_dir='asc' then lower(name) end asc,
        case when v_sort='scholarship' and v_dir='desc' then lower(name) end desc,
        case when v_sort='provider' and v_dir='asc' then lower(coalesce(provider_name,'')) end asc,
        case when v_sort='provider' and v_dir='desc' then lower(coalesce(provider_name,'')) end desc,
        case when v_sort='type' and v_dir='asc' then lower(coalesce(scholarship_type,'')) end asc,
        case when v_sort='type' and v_dir='desc' then lower(coalesce(scholarship_type,'')) end desc,
        case when v_sort='audience' and v_dir='asc' then lower(coalesce(audience::text,'')) end asc,
        case when v_sort='audience' and v_dir='desc' then lower(coalesce(audience::text,'')) end desc,
        case when v_sort='award' and v_dir='asc' then coalesce(award_percentage,award_amount) end asc nulls last,
        case when v_sort='award' and v_dir='desc' then coalesce(award_percentage,award_amount) end desc nulls last,
        case when v_sort='year' and v_dir='asc' then academic_year end asc nulls last,
        case when v_sort='year' and v_dir='desc' then academic_year end desc nulls last,
        case when v_sort='close' and v_dir='asc' then application_close_date end asc nulls last,
        case when v_sort='close' and v_dir='desc' then application_close_date end desc nulls last,
        case when v_sort='courses' and v_dir='asc' then mapped_course_count end asc,
        case when v_sort='courses' and v_dir='desc' then mapped_course_count end desc,
        case when v_sort='evidence' and v_dir='asc' then evidence_count end asc,
        case when v_sort='evidence' and v_dir='desc' then evidence_count end desc,
        case when v_sort='publication' and v_dir='asc' then lower(coalesce(publication_status,'')) end asc,
        case when v_sort='publication' and v_dir='desc' then lower(coalesce(publication_status,'')) end desc,
        case when v_sort='updated' and v_dir='asc' then updated_at end asc,
        case when v_sort='updated' and v_dir='desc' then updated_at end desc,
        lower(name),id
      limit v_limit offset v_offset
    )
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir,'status_counts',(select coalesce(jsonb_object_agg(z.status, z.n), '{}'::jsonb) from (select b.status, count(*) n from base b group by 1) z))
    from ordered o
  );
end
$$;


ALTER FUNCTION "security"."admin_scholarships_page"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_source_comparison_read_v1"("p_entity_type" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'scholarship', 'security', 'auth'
    AS $$
declare
  v_provider jsonb; v_gov jsonb; v_current jsonb; v_weeks numeric; v_reg jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 1 then
    raise exception 'assigned CourseFinder role required' using errcode='42501';
  end if;

  if p_entity_type = 'scholarship' then
    if not exists (select 1 from scholarship.scholarships where id = p_id) then return null; end if;

    select jsonb_build_object(
             'url', coalesce(sp.final_url, sp.url), 'read_at', sp.read_at, 'read_status', sp.read_status,
             'url_source', sp.url_source, 'evidence_id', sp.evidence_id, 'heading', sp.facts->>'h1',
             'value', sp.facts->'value', 'deadline', sp.facts->'deadline', 'levels', sp.facts->'levels',
             'international', sp.facts->'international')
      into v_provider
      from pipeline.scholarship_pages sp
     where sp.scholarship_id = p_id
     order by (sp.facts is not null) desc, sp.read_at desc nulls last
     limit 1;
    if v_provider is null then
      select jsonb_build_object('url', i.identifier_value, 'evidence_id', i.evidence_id)
        into v_provider from scholarship.identifiers i
       where i.scholarship_id = p_id and i.scheme = 'first_party_detail_url' and coalesce(i.status,'active') = 'active'
       order by i.is_primary desc, i.created_at desc limit 1;
    end if;

    with urls as (
      select s.source_url u from scholarship.scholarships s where s.id = p_id and security.reference_url_has_use(s.source_url, 'scholarship_placeholder')
      union select c.before_value->>'source_url' from pipeline.scholarship_sweep_changes c
        where c.scholarship_id = p_id and security.reference_url_has_use(c.before_value->>'source_url', 'scholarship_placeholder')
    ), ids as (
      select i.identifier_value v from scholarship.identifiers i where i.scholarship_id = p_id and i.scheme = 'study_australia_scholarship_id'
    ), rec as (
      select r.* from pipeline.scholarship_source_records r
       where r.source_record_id in (select v from ids) or r.source_record_url in (select u from urls)
       order by r.observed_at desc nulls last limit 1
    )
    select jsonb_build_object(
             'url', coalesce(rec.source_record_url, (select u from urls limit 1)),
             'observed_at', rec.observed_at, 'evidence_id', rec.evidence_id,
             'value_text', rec.payload->>'award_value_text',
             'amount', rec.payload->'cycles'->0->'award_tiers'->0->'amount',
             'currency', rec.payload->'cycles'->0->'award_tiers'->0->>'currency_code',
             'closing_date', coalesce(rec.payload->>'application_close_date', rec.payload->>'close_date', rec.payload->'cycles'->0->'windows'->0->>'closes_at'),
             'closing_text', coalesce(rec.payload->>'application_close_text', rec.payload->'cycles'->0->'metadata'->>'source_closing_text'),
             'levels_text', coalesce(rec.payload->>'level_of_study_text', rec.payload->'cycles'->0->'metadata'->>'source_level_of_study'),
             'study_levels', rec.payload->'study_levels')
      into v_gov
      from (select 1) one left join rec on true
     where rec.id is not null or exists (select 1 from urls);

    select jsonb_build_object('value_text', s.award_value_text, 'source_url', s.source_url,
             'closing_date', (select min(w.closes_at) from scholarship.application_windows w where w.scholarship_id = s.id))
      into v_current from scholarship.scholarships s where s.id = p_id;

    return jsonb_build_object('entity_type','scholarship','id',p_id,
      'provider', v_provider, 'government', v_gov, 'current', v_current);
  end if;

  if p_entity_type = 'course' then
    if not exists (select 1 from catalogue.courses where id = p_id) then return null; end if;
    select case when c.duration_unit = 'weeks' then c.duration_value end into v_weeks from catalogue.courses c where c.id = p_id;

    select jsonb_build_object(
             'cricos_code', (select o.registration_code from catalogue.course_regulatory_observations o
                               where o.course_id = p_id and o.scheme = 'cricos' order by (o.valid_to is null) desc, o.observed_at desc nulls last limit 1),
             'tuition', (select jsonb_build_object('amount', f.amount, 'currency', f.currency_code, 'basis', f.basis, 'fee_year', f.fee_year,
                                   'evidence_id', f.evidence_id, 'verified_at', f.last_verified_at,
                                   'per_year_estimate', case when v_weeks > 0 and f.basis = 'registered_total_course' then round(f.amount / (v_weeks / 52.0)) end)
                           from catalogue.course_fees f
                          where f.course_id = p_id and f.fee_type = 'tuition' and coalesce(f.status,'active') = 'active'
                          order by f.fee_year desc nulls last, f.updated_at desc nulls last limit 1),
             'duration', (select jsonb_build_object('value', c.duration_value, 'unit', c.duration_unit) from catalogue.courses c where c.id = p_id and c.duration_value is not null),
             'campuses', (select coalesce(jsonb_agg(distinct cp.name order by cp.name), '[]'::jsonb)
                            from catalogue.course_campuses cc join catalogue.campuses cp on cp.id = cc.campus_id where cc.course_id = p_id))
      into v_reg;

    select jsonb_build_object(
             'url', coalesce((select g.url from pipeline.coverage_course_pages g where g.course_id = p_id and g.status = 'bound' limit 1),
                             (select l.url from catalogue.course_links l where l.course_id = p_id and l.link_type = 'official_course' and coalesce(l.status,'active') = 'active'
                               order by (l.audience = 'international') desc, l.last_verified_at desc nulls last limit 1)),
             'read_at', (select g.read_at from pipeline.coverage_course_pages g where g.course_id = p_id and g.status = 'bound' limit 1),
             'tuition', (select jsonb_build_object('amount', f.amount, 'currency', f.currency_code, 'basis', f.basis, 'fee_year', f.fee_year,
                                   'evidence_id', f.evidence_id, 'verified_at', f.last_verified_at, 'source_type', s.source_type)
                           from catalogue.course_fees f left join pipeline.sources s on s.id = f.source_id
                          where f.course_id = p_id and f.fee_type = 'provider_current_tuition' and coalesce(f.status,'active') = 'active'
                          order by f.fee_year desc nulls last, f.updated_at desc nulls last limit 1),
             'duration', null, 'campuses', null)
      into v_provider;

    return jsonb_build_object('entity_type','course','id',p_id,'provider', v_provider, 'regulator', v_reg);
  end if;

  raise exception 'unsupported entity type %', p_entity_type using errcode='22023';
end
$$;


ALTER FUNCTION "security"."admin_source_comparison_read_v1"("p_entity_type" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_summary_snapshots_refresh"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare v_caller text; t timestamptz; v jsonb; d_ms int; l_ms int;
begin
  v_caller := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.role',true),''),session_user);
  if v_caller not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  t := clock_timestamp(); v := security.admin_dashboard_maturity_compute(); d_ms := round(extract(epoch from clock_timestamp()-t)*1000);
  insert into security.admin_summary_snapshots(snapshot_key,payload,computed_at,compute_ms) values('dashboard',v,now(),d_ms)
  on conflict(snapshot_key) do update set payload=excluded.payload, computed_at=excluded.computed_at, compute_ms=excluded.compute_ms;
  t := clock_timestamp(); v := security.admin_layer_status_summary_compute(); l_ms := round(extract(epoch from clock_timestamp()-t)*1000);
  insert into security.admin_summary_snapshots(snapshot_key,payload,computed_at,compute_ms) values('layer_status_summary',v,now(),l_ms)
  on conflict(snapshot_key) do update set payload=excluded.payload, computed_at=excluded.computed_at, compute_ms=excluded.compute_ms;
  return jsonb_build_object('ok',true,'dashboard_ms',d_ms,'layer_status_summary_ms',l_ms);
end $$;


ALTER FUNCTION "security"."admin_summary_snapshots_refresh"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admission_lifecycle_apply_l2_v1"("p_actor" "uuid", "p_limit" integer DEFAULT 300) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$
declare r record; v_done int := 0; v_err int := 0; v_left int; t0 timestamptz := clock_timestamp();
begin
  for r in
    select sp.id, v.configuration cfg, (pol.cycle_days*24) target_h
    from pipeline.layer2_source_profiles sp
    join pipeline.layer2_source_profile_versions v on v.id=sp.current_version_id
    join pipeline.admission_lifecycle_policy pol on pol.data_type = case sp.domain when 'course_facts' then 'course_facts' when 'scholarship' then 'scholarships' when 'provider_asset' then 'provider_assets' end
    where sp.enabled and coalesce(sp.freshness_sla_hours,-1) <> pol.cycle_days*24
    order by sp.id limit greatest(1,least(coalesce(p_limit,300),1000))
  loop
    begin
      perform public.layer2_create_profile_version(p_actor, r.id, jsonb_set(r.cfg,'{freshness_sla_hours}',to_jsonb(r.target_h)), 'CF-CHG-20260915-247', 'Decision-152-admission-lifecycle');
      v_done := v_done+1;
    exception when others then v_err := v_err+1;
    end;
  end loop;
  select count(*) into v_left from pipeline.layer2_source_profiles sp join pipeline.admission_lifecycle_policy pol
    on pol.data_type = case sp.domain when 'course_facts' then 'course_facts' when 'scholarship' then 'scholarships' when 'provider_asset' then 'provider_assets' end
   where sp.enabled and coalesce(sp.freshness_sla_hours,-1) <> pol.cycle_days*24;
  return jsonb_build_object('versioned',v_done,'errors',v_err,'remaining',v_left,'ms',round(extract(epoch from clock_timestamp()-t0)*1000));
end $$;


ALTER FUNCTION "security"."admission_lifecycle_apply_l2_v1"("p_actor" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."apply_provider_fee_profiles_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue'
    AS $$
declare n int; b int;
begin
  with m as (
    select w.id, pf.rule_code, pf.resolved_basis
    from pipeline.layer3_work_items w
    join catalogue.courses c on c.id=w.entity_id
    join pipeline.provider_fee_profiles pf on pf.provider_id=c.provider_id and pf.active and pf.review_by>=current_date
    join pipeline.evidence_artifacts e on e.id=w.evidence_id
    join pipeline.layer3_interpretations i on i.id=w.interpretation_id
    where w.task_class='provider_current_tuition_validation'
      and w.status in ('pending','layer4_required')
      and w.candidate_context->'provider_current_tuition'->>'basis' in ('annual_or_indicative_requires_validation', pf.resolved_basis)
      and coalesce(w.candidate_context->'provider_current_tuition'->>'audience','')=pf.audience
      and e.source_url ~* pf.page_url_pattern
      and coalesce(i.evidence_quotes::text,'') !~* pf.exclusion_pattern
      and not (w.candidate_context ? 'provider_fee_rule'))
  update pipeline.layer3_work_items w
  set candidate_context = jsonb_set(jsonb_set(w.candidate_context,'{provider_current_tuition,basis}',to_jsonb(m.resolved_basis)),
                                    '{provider_current_tuition,basis_source}',to_jsonb('provider_fee_rule:'||m.rule_code))
                          || jsonb_build_object('provider_fee_rule',m.rule_code,'provider_fee_rule_applied_at',now()),
      updated_at=now()
  from m where w.id=m.id;
  get diagnostics n = row_count;
  update pipeline.layer3_work_items w
  set candidate_context = jsonb_set(w.candidate_context,'{provider_current_tuition,basis_source}',to_jsonb('provider_fee_rule:'||(w.candidate_context->>'provider_fee_rule'))),
      updated_at=now()
  where w.candidate_context ? 'provider_fee_rule'
    and not (w.candidate_context->'provider_current_tuition' ? 'basis_source')
    and w.status in ('pending','layer4_required');
  get diagnostics b = row_count;
  return jsonb_build_object('applied',n,'stamped',b);
end $$;


ALTER FUNCTION "security"."apply_provider_fee_profiles_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."au_regional_class"("p_state" "text", "p_postcode" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $_$
  with x as (select upper(btrim(p_state)) st, case when btrim(coalesce(p_postcode,'')) ~ '^\d{4}$' then btrim(p_postcode)::int end pc),
  r as (select g.category, g.metro_area from ref.au_regional_postcode_ranges g, x where g.state_code=x.st and x.pc between g.pc_from and g.pc_to order by g.category limit 1)
  select case
    when x.st is null or x.st !~ '^AU-' or x.pc is null then null
    when x.st='AU-ACT' then jsonb_build_object('category',2,'metro_area','Canberra')
    when x.st='AU-NT' or x.pc=2899 then jsonb_build_object('category',3,'metro_area',null)
    when exists (select 1 from r) then (select jsonb_build_object('category',r.category,'metro_area',r.metro_area) from r)
    when x.st in ('AU-WA','AU-SA','AU-TAS') then jsonb_build_object('category',3,'metro_area',null)
    when x.st='AU-NSW' then jsonb_build_object('category',1,'metro_area','Sydney')
    when x.st='AU-VIC' then jsonb_build_object('category',1,'metro_area','Melbourne')
    when x.st='AU-QLD' then jsonb_build_object('category',1,'metro_area','Brisbane')
  end from x
$_$;


ALTER FUNCTION "security"."au_regional_class"("p_state" "text", "p_postcode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."australian_university"("p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref', 'security'
    AS $$
  select exists (select 1 from catalogue.providers p join ref.countries c on c.id=p.country_id
     where p.id=p_provider_id and c.iso_alpha2='AU' and p.lifecycle_status='active'
       and (jsonb_array_length(coalesce(security.provider_university_groups(p.id),'[]'))>0
            or (p.canonical_name ~* '\muniversity\M' and p.canonical_name !~* '(college|pathways?|language cent|senior|theology|divinity)')))
$$;


