CREATE OR REPLACE FUNCTION "security"."cf093_park_exhausted_discovery_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security', 'catalogue'
    AS $$
declare
  v_preview uuid;
  v_profile uuid;
  v_binding pipeline.scheduler_workflow_async_bindings%rowtype;
  v_retry_max integer:=3;
  v_exhausted integer:=0;
  v_total integer:=0;
  v_unresolved uuid[]:='{}'::uuid[];
  v_source uuid;
  v_l3_profile uuid;
  v_rr uuid;
  v_course uuid;
begin
  if new.job_type<>'layer2_discovery' or new.status not in ('failed','completed','cancelled','blocked','succeeded','success') then return new; end if;
  begin v_preview:=nullif(new.payload->>'scheduler_preview_token','')::uuid; exception when others then v_preview:=null; end;
  begin v_profile:=nullif(new.payload->>'profile_id','')::uuid; exception when others then v_profile:=null; end;
  if v_preview is null or v_profile is null then return new; end if;

  select * into v_binding from pipeline.scheduler_workflow_async_bindings b
  where b.preview_token=v_preview and b.profile_id=v_profile for update;
  if not found or v_binding.status<>'active' then return new; end if;

  begin
    select greatest(coalesce(nullif(pv.configuration#>>'{retry,max_attempts}','')::integer,3),1)
    into v_retry_max from pipeline.layer2_source_profile_versions pv where pv.id=v_binding.profile_version_id;
  exception when others then v_retry_max:=3; end;
  v_retry_max:=coalesce(v_retry_max,3);

  select coalesce(array_agg(c order by c),'{}'::uuid[]) into v_unresolved
  from unnest(v_binding.discovery_course_ids) c
  where not exists(
    select 1 from pipeline.layer2_course_discovery_candidates dc
    join pipeline.layer2_provider_attempts pa on pa.id=dc.provider_attempt_id
    join pipeline.jobs j on j.id=pa.job_id
    where dc.course_id=c
      and dc.source_profile_version_id=v_binding.profile_version_id
      and dc.selected=true
      and nullif(dc.discovered_url,'') is not null
      and dc.created_at>=v_binding.activated_at
      and coalesce(j.payload->>'scheduler_preview_token','')=v_preview::text
  );
  v_total:=cardinality(v_unresolved);
  if v_total<=0 then return new; end if;

  with attempts as (
    select (r->>'course_id')::uuid course_id,count(*)::integer n
    from pipeline.jobs j cross join lateral jsonb_array_elements(coalesce(j.result->'results','[]'::jsonb)) r
    where j.job_type='layer2_discovery'
      and j.payload->>'scheduler_preview_token'=v_preview::text
      and j.payload->>'profile_id'=v_profile::text
      and nullif(r->>'course_id','') is not null
      and (r->>'course_id')::uuid=any(v_unresolved)
      and r->>'status' in ('failed','candidate')
    group by (r->>'course_id')::uuid
  )
  select count(*)::integer into v_exhausted from attempts where n>=v_retry_max;
  if v_exhausted<v_total then return new; end if;

  select source_id into v_source from pipeline.layer2_source_profiles where id=v_profile;
  select id into v_l3_profile from pipeline.layer3_model_profiles
  where enabled and not paused and 'official_course_url'=any(allowed_task_classes)
    and coalesce((quality_benchmark->>'pass')::boolean,false)=true
  order by updated_at desc,id limit 1;

  foreach v_course in array v_unresolved loop
    select id into v_rr from pipeline.refresh_requests
    where requested_layer=3 and entity_type='course' and entity_id=v_course
      and revalidation_ref='CF093-DISCOVERY-PARK:'||v_preview::text||':'||v_course::text limit 1;
    if v_rr is null then
      insert into pipeline.refresh_requests(
        requested_layer,country_code,source_profile_id,entity_type,entity_id,reason,trigger_type,status,
        requested_by,change_control_ref,source_id,evidence_id,layer3_profile_id,revalidation_ref,schedule_error
      ) values(
        3,'AU',v_profile,'course',v_course,
        'Layer 2 URL discovery exhausted Firecrawl/ZenRows; park for governed Layer 3 when course-specific Evidence is available',
        'manual_governed','blocked',v_binding.actor_id,'CF-CHG-20260910-093',v_source,null,v_l3_profile,
        'CF093-DISCOVERY-PARK:'||v_preview::text||':'||v_course::text,
        'Layer 3 is evidence-gated; no course-specific retained Evidence was produced by bounded discovery'
      ) returning id into v_rr;
    end if;
    if not exists(
      select 1 from pipeline.layer4_review_items li
      where li.entity_type='course' and li.entity_id=v_course and li.field_code='official_course_url'
        and li.status='pending' and li.layer2_state->>'scheduler_preview_token'=v_preview::text
    ) then
      insert into pipeline.layer4_review_items(
        entity_type,entity_id,field_code,evidence_id,layer3_interpretation_id,before_value,proposed_value,
        layer2_state,layer3_state,status,escalation_reason,change_control_ref
      ) values(
        'course',v_course,'official_course_url',null,null,null,null,
        jsonb_build_object('status','scraper_exhausted','scheduler_preview_token',v_preview,'source_profile_id',v_profile,
          'retry_max_attempts',v_retry_max,'route','firecrawl_then_zenrows','canonical_mutation_authorised',false),
        jsonb_build_object('status','blocked_pending_evidence','refresh_request_id',v_rr,'profile_id',v_l3_profile,
          'reason','Layer 3 requires governed course-specific Evidence; none was retained by bounded URL discovery'),
        'pending','Firecrawl/ZenRows URL discovery exhausted. Do not perfect site-specific gatekeeper mechanics; resolve through governed Layer 3 when Evidence is available or Layer 4 human review.','CF-CHG-20260910-093'
      );
    end if;
  end loop;

  update pipeline.scheduler_workflow_async_bindings
  set status='handoff_started',handoff_started_at=coalesce(handoff_started_at,now())
  where preview_token=v_preview and profile_id=v_profile and status='active';
  return new;
end
$$;


ALTER FUNCTION "security"."cf093_park_exhausted_discovery_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cf245_admit_official_url_record_v1"("p_source_record_id" "uuid", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref', 'search'
    AS $$ declare r pipeline.course_fact_source_records%rowtype; v_provider uuid; v_course uuid; v_url text; v_existing boolean:=false; v_gate boolean:=false; begin if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; select * into r from pipeline.course_fact_source_records where id=p_source_record_id; if not found then return jsonb_build_object('ok',false,'eligible',false,'reason','source_record_not_found'); end if; if r.evidence_id is null then return jsonb_build_object('ok',true,'eligible',false,'reason','evidence_required'); end if; if coalesce((r.parsed_payload->>'identity_match')::boolean,false)=false then return jsonb_build_object('ok',true,'eligible',false,'reason','identity_mismatch'); end if; if coalesce((r.parsed_payload->>'regulatory_code_seen')::boolean,false)=false then return jsonb_build_object('ok',true,'eligible',false,'reason','regulatory_code_not_seen'); end if; v_url:=nullif(btrim(r.parsed_payload->>'official_course_url'),''); if v_url is null then return jsonb_build_object('ok',true,'eligible',false,'reason','official_url_not_resolved'); end if; if v_url is distinct from r.source_url then return jsonb_build_object('ok',true,'eligible',false,'reason','official_url_evidence_url_mismatch'); end if; if v_url !~ '^https?://' then return jsonb_build_object('ok',true,'eligible',false,'reason','official_url_invalid_scheme'); end if; select pr.provider_id into v_provider from catalogue.provider_registrations pr join catalogue.providers p on p.id=pr.provider_id join ref.countries c on c.id=p.country_id where trim(c.iso_alpha2)='AU' and lower(pr.registration_scheme)='cricos' and upper(btrim(pr.registration_code))=upper(btrim(r.provider_cricos)) and coalesce(pr.status,'active') not in('inactive','cancelled','archived') order by pr.checked_at desc nulls last limit 1; if v_provider is null then return jsonb_build_object('ok',true,'eligible',false,'reason','provider_cricos_not_resolved'); end if; select cr.course_id into v_course from catalogue.course_registrations cr join catalogue.courses c on c.id=cr.course_id where c.provider_id=v_provider and lower(cr.scheme)='cricos' and upper(btrim(cr.registration_code))=upper(btrim(r.course_cricos)) limit 1; if v_course is null then return jsonb_build_object('ok',true,'eligible',false,'reason','course_cricos_not_resolved'); end if; if security.layer4_entity_or_parent_blocked('course',v_course,'operational') then return jsonb_build_object('ok',true,'eligible',false,'reason','layer4_operational_block'); end if; if not exists(select 1 from pipeline.course_fact_source_qualifications q where q.source_id=r.source_id and q.provider_cricos=upper(btrim(r.provider_cricos)) and q.qualification_status in('qualified','bounded') and 'official_course_url'=any(q.admitted_domains)) then return jsonb_build_object('ok',true,'eligible',false,'reason','source_not_qualified_for_official_url'); end if; select exists(select 1 from search.enrichment_source_gates sg where sg.projection_code='courses' and sg.domain_code='official_course_url' and sg.source_id=r.source_id and sg.gate_status='approved') into v_gate; if not v_gate then return jsonb_build_object('ok',true,'eligible',false,'reason','search_source_gate_not_approved'); end if; select exists(select 1 from catalogue.course_links l where l.course_id=v_course and l.link_type='official_course' and l.url=v_url and l.status='active') into v_existing; if not p_apply then return jsonb_build_object('ok',true,'eligible',true,'course_id',v_course,'url',v_url,'would_change',not v_existing,'search_admission_eligible',true); end if; insert into catalogue.course_links(course_id,link_type,url,audience,label,is_primary,status,source_id,evidence_id,confidence,last_verified_at,updated_at) values(v_course,'official_course',v_url,'international','Official provider course page',false,'active',r.source_id,r.evidence_id,1,now(),now()) on conflict(course_id,link_type,url) do update set audience=excluded.audience,label=excluded.label,status='active',source_id=excluded.source_id,evidence_id=excluded.evidence_id,confidence=1,last_verified_at=now(),updated_at=now(); insert into pipeline.layer2_field_admissions(source_record_id,course_id,source_id,evidence_id,field_key,status,reason_code,candidate_payload,canonical_changed,search_admission_eligible) values(r.id,v_course,r.source_id,r.evidence_id,'official_course_url',case when v_existing then 'unchanged' else 'admitted' end,case when v_existing then 'already_active_same_url' else 'qualified_exact_cricos_evidence_match' end,jsonb_build_object('url',v_url),not v_existing,true) on conflict(source_record_id,field_key) do update set status=excluded.status,reason_code=excluded.reason_code,candidate_payload=excluded.candidate_payload,canonical_changed=excluded.canonical_changed,search_admission_eligible=excluded.search_admission_eligible,decided_at=now(); return jsonb_build_object('ok',true,'eligible',true,'applied',true,'course_id',v_course,'url',v_url,'canonical_changed',not v_existing,'search_admission_eligible',true); end $$;


ALTER FUNCTION "security"."cf245_admit_official_url_record_v1"("p_source_record_id" "uuid", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cf245_admit_official_url_wave_v1"("p_batch_id" "uuid", "p_limit" integer DEFAULT 25, "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$ declare r record; v jsonb; v_checked int:=0; v_eligible int:=0; v_changed int:=0; v_reasons jsonb:='{}'::jsonb; v_reason text; begin if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; for r in select distinct l.source_record_id from pipeline.layer2_enrichment_operational_ledger_v1 l where l.batch_id=p_batch_id and l.source_record_id is not null and not exists(select 1 from pipeline.layer2_field_admissions a where a.source_record_id=l.source_record_id and a.field_key='official_course_url' and a.status in('admitted','unchanged')) order by l.source_record_id limit greatest(1,least(coalesce(p_limit,25),100)) loop v_checked:=v_checked+1; v:=security.cf245_admit_official_url_record_v1(r.source_record_id,p_apply); if coalesce((v->>'eligible')::boolean,false) then v_eligible:=v_eligible+1; end if; if coalesce((v->>'canonical_changed')::boolean,false) then v_changed:=v_changed+1; end if; v_reason:=coalesce(v->>'reason',case when coalesce((v->>'eligible')::boolean,false) then 'eligible' else 'unknown' end); v_reasons:=jsonb_set(v_reasons,array[v_reason],to_jsonb(coalesce((v_reasons->>v_reason)::int,0)+1),true); end loop; return jsonb_build_object('ok',true,'batch_id',p_batch_id,'apply',p_apply,'checked',v_checked,'eligible',v_eligible,'canonical_changed',v_changed,'reasons',v_reasons,'change_control_ref','CF-CHG-20260915-245'); end $$;


ALTER FUNCTION "security"."cf245_admit_official_url_wave_v1"("p_batch_id" "uuid", "p_limit" integer, "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."consumer_api_compare_v1"("p_before" "jsonb", "p_after" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('case',k,'before',p_before->k,'after',p_after->k)),'[]'::jsonb)
  from jsonb_object_keys(p_before) k
  where (p_before->k->>'md5') is distinct from (p_after->k->>'md5') or (p_before->k->>'ok') is distinct from (p_after->k->>'ok')
$$;


ALTER FUNCTION "security"."consumer_api_compare_v1"("p_before" "jsonb", "p_after" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."consumer_api_snapshot_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'api', 'security'
    AS $_$
declare res jsonb := '{}'::jsonb; r jsonb; t0 timestamptz; c record;
begin
  for c in select * from (values
    ('search_bachelor_au', $q$select to_jsonb(public.zoho_edge_course_search_v2('bachelor',array['AU'],null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,20,0))$q$),
    ('search_master_page2', $q$select to_jsonb(public.zoho_edge_course_search_v2('master',array['AU'],null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,20,20))$q$),
    ('search_has_provider_tuition', $q$select to_jsonb(public.zoho_edge_course_search_v2(null,array['AU'],null,null,null,null,null,null,null,null,true,null,null,null,null,null,null,null,null,null,null,null,25,0))$q$),
    ('search_has_scholarship', $q$select to_jsonb(public.zoho_edge_course_search_v2(null,array['AU'],null,null,null,null,null,true,null,null,null,null,null,null,null,null,null,null,null,null,null,null,25,0))$q$),
    ('search_tuition_range', $q$select to_jsonb(public.zoho_edge_course_search_v2(null,array['AU'],null,null,null,null,null,null,null,null,null,null,null,null,null,null,40000,60000,null,null,null,null,25,0))$q$),
    ('search_nz', $q$select to_jsonb(public.zoho_edge_course_search_v2(null,array['NZ'],null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,20,0))$q$),
    ('lookup_080729G', $q$select to_jsonb(public.zoho_edge_course_lookup_v1('080729G'))$q$),
    ('lookup_121174E', $q$select to_jsonb(public.zoho_edge_course_lookup_v1('121174E'))$q$),
    ('providers_university_au', $q$select to_jsonb(public.zoho_edge_provider_search_v1('university','AU',null,20,0))$q$),
    ('filter_country', $q$select to_jsonb(public.zoho_edge_filter_options_v1('country',null,null,50,0))$q$),
    ('filter_subdivision_au', $q$select to_jsonb(public.zoho_edge_filter_options_v1('subdivision','AU',null,50,0))$q$),
    ('reference_bundle', $q$select to_jsonb(public.zoho_edge_reference_bundle_v1())$q$),
    ('website_preview_080729G', $q$select api.website_course_lookup_preview_v1('080729G')$q$)
  ) v(case_name, stmt) loop
    begin
      t0 := clock_timestamp();
      execute c.stmt into r;
      r := r - 'generated_at';
      res := res || jsonb_build_object(c.case_name, jsonb_build_object('ok',true,'md5',md5(r::text),'bytes',length(r::text),'ms',round(extract(epoch from clock_timestamp()-t0)*1000)));
    exception when others then
      res := res || jsonb_build_object(c.case_name, jsonb_build_object('ok',false,'error',sqlerrm));
    end;
  end loop;
  return res;
end $_$;


ALTER FUNCTION "security"."consumer_api_snapshot_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_completeness_build_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v jsonb;
begin
  truncate pipeline.course_completeness;
  insert into pipeline.course_completeness(course_id,provider_id,tier,attributes,admitted,accounted,completeness,accounted_pct,missing,country_code)
  select course_id, max(provider_id::text)::uuid, max(tier), count(*),
         count(*) filter (where state='admitted'),
         count(*) filter (where state in ('admitted','candidate','in_review','awaiting_l3','not_on_page','blocked')),
         round(100.0*count(*) filter (where state='admitted')/count(*),1),
         round(100.0*count(*) filter (where state in ('admitted','candidate','in_review','awaiting_l3','not_on_page','blocked'))/count(*),1),
         coalesce(array_agg(attribute order by attribute) filter (where state<>'admitted'),'{}'),
         max(country_code)
    from pipeline.course_attribute_coverage group by course_id;
  delete from pipeline.completeness_daily where snapshot_date=current_date;
  insert into pipeline.completeness_daily(snapshot_date,scope,scope_id,courses,completeness,accounted_pct,fully_complete)
  select current_date,'platform',null,count(*),round(avg(completeness),1),round(avg(accounted_pct),1),count(*) filter (where admitted=attributes) from pipeline.course_completeness
  union all
  select current_date,'provider',provider_id,count(*),round(avg(completeness),1),round(avg(accounted_pct),1),count(*) filter (where admitted=attributes) from pipeline.course_completeness where provider_id is not null group by provider_id;
  -- Decision 213: one row per country; provider rows carry their country
  insert into pipeline.completeness_daily(snapshot_date,scope,scope_id,courses,completeness,accounted_pct,fully_complete,country_code)
  select current_date,'country:'||country_code,null,count(*),round(avg(completeness),1),round(avg(accounted_pct),1),count(*) filter (where admitted=attributes),country_code
    from pipeline.course_completeness group by country_code;
  update pipeline.completeness_daily x set country_code = (select max(c.country_code) from pipeline.course_completeness c where c.provider_id = x.scope_id)
   where x.snapshot_date = current_date and x.scope = 'provider';
  select to_jsonb(d) - 'scope_id' into v from pipeline.completeness_daily d where snapshot_date=current_date and scope='platform';
  return v;
end $$;


ALTER FUNCTION "security"."course_completeness_build_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_coverage_build_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'ref', 'security'
    AS $$
declare v_n int; v_t0 timestamptz:=clock_timestamp();
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  create temp table _c on commit drop as
    select co.id course_id, co.provider_id, co.duration_value, k.iso_alpha2::text country_code
      from catalogue.courses co join catalogue.providers p on p.id=co.provider_id join ref.countries k on k.id=p.country_id
     where co.lifecycle_status='active'; -- Decision 213: every country
  create temp table _tier on commit drop as
    select provider_id, case when rk<=10 then 'top_10' when rk<=40 then 'top_11_40' when rk<=100 then 'top_41_100' else 'rest' end tier
      from (select provider_id, row_number() over (partition by min(country_code) order by count(*) desc, provider_id) rk from _c group by provider_id) x; -- tiers within each country
  create temp table _site on commit drop as
    select t.provider_id from _tier t join catalogue.providers p on p.id=t.provider_id
     where nullif(btrim(p.website),'') is not null or exists(select 1 from pipeline.provider_discovery_links l where l.provider_id=t.provider_id);
  create temp table _found on commit drop as
    select distinct course_id from pipeline.layer2_course_discovery_candidates where selected and course_id is not null;
  create temp table _read on commit drop as
    select entity_id course_id, bool_or(status in ('resolved_l2','layer3_required')) read_ok, bool_or(status='blocked') blocked
      from pipeline.layer2_run_items where entity_type='course' group by entity_id;
  create temp table _sw on commit drop as
    select course_id, status, read_status, identity_basis,
           (read_status='read' and identity_basis='cricos_code') verified,
           coalesce((candidates->'fee'->>'value') is not null,false) c_tuition,
           coalesce(candidates->'english' ? 'ielts_overall' or candidates->'english' ? 'pte_overall' or candidates->'english' ? 'toefl_overall',false) c_english,
           coalesce(jsonb_array_length(candidates->'intakes')>0,false) c_intakes
      from pipeline.coverage_course_pages;
  create temp table _val on commit drop as
    select c.course_id,
      exists(select 1 from catalogue.course_links l where l.course_id=c.course_id and l.status='active' and l.link_type='official_course') url,
      exists(select 1 from catalogue.course_fees f where f.course_id=c.course_id and f.status='active' and f.fee_type='provider_current_tuition') tuition,
      exists(select 1 from catalogue.course_english_requirements e where e.course_id=c.course_id and e.status='active') english,
      exists(select 1 from catalogue.course_intakes i where i.course_id=c.course_id and coalesce(i.status,'active')='active') intakes,
      exists(select 1 from catalogue.course_fees f where f.course_id=c.course_id and f.status='active' and f.fee_type='tuition') reg_tuition,
      exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.course_id) campus
    from _c c;
  create temp table _l4 on commit drop as
    select entity_id course_id, case when field_code in ('official_course_url') then 'official_url'
                                     when field_code in ('provider_current_tuition_validation','provider_current_tuition') then 'provider_tuition'
                                     when field_code ilike '%english%' then 'english' when field_code ilike '%intake%' then 'intakes' end attribute
      from pipeline.layer4_review_items where entity_type='course' and status='pending'
    union
    select entity_id, case when task_class='provider_current_tuition_validation' then 'provider_tuition' when task_class ilike '%english%' then 'english'
                           when task_class ilike '%intake%' then 'intakes' when task_class ilike '%url%' then 'official_url' end
      from pipeline.layer3_work_items where entity_type='course' and status='layer4_required';
  create temp table _l3 on commit drop as
    select entity_id course_id, case when task_class='provider_current_tuition_validation' then 'provider_tuition' when task_class ilike '%english%' then 'english'
                                     when task_class ilike '%intake%' then 'intakes' when task_class ilike '%url%' then 'official_url' end attribute
      from pipeline.layer3_work_items where entity_type='course' and status in ('pending','reserved','failed','retry');

  truncate pipeline.course_attribute_coverage;
  insert into pipeline.course_attribute_coverage(course_id,provider_id,attribute,state,tier,computed_at,country_code)
  select c.course_id, c.provider_id, a.attribute,
    case
      when a.l1 then case when a.has then 'admitted' else 'missing_l1' end
      when a.has then 'admitted'
      when exists(select 1 from _l4 x where x.course_id=c.course_id and x.attribute=a.attribute) then 'in_review'
      when exists(select 1 from _l3 x where x.course_id=c.course_id and x.attribute=a.attribute) then 'awaiting_l3'
      when sw.verified and (a.attribute='official_url' or (a.attribute='provider_tuition' and sw.c_tuition) or (a.attribute='english' and sw.c_english) or (a.attribute='intakes' and sw.c_intakes)) then 'candidate'
      when r.read_ok or sw.verified then 'not_on_page'
      when r.blocked or sw.read_status in ('blocked','robots_disallowed') then 'blocked'
      when f.course_id is not null or v.url or sw.status='bound' then 'page_found'
      when s.provider_id is not null then 'site_known'
      else 'no_website' end,
    t.tier, now(), c.country_code
  from _c c join _val v using (course_id) join _tier t using (provider_id)
  left join _read r using (course_id) left join _found f using (course_id) left join _sw sw using (course_id) left join _site s on s.provider_id=c.provider_id
  cross join lateral (values
    ('official_url', v.url, false), ('provider_tuition', v.tuition, false), ('english', v.english, false), ('intakes', v.intakes, false),
    ('registered_tuition', v.reg_tuition, true), ('duration', c.duration_value is not null, true), ('campus', v.campus, true)) a(attribute, has, l1);
  get diagnostics v_n=row_count;

  delete from pipeline.course_coverage_daily where snapshot_date=current_date;
  insert into pipeline.course_coverage_daily(snapshot_date,attribute,state,tier,courses)
  select current_date, attribute, state, tier, count(*) from pipeline.course_attribute_coverage where country_code='AU' group by 2,3,4;
  -- Decision 213: daily counts by country
  update pipeline.course_coverage_daily_by_country set courses = 0, computed_at = now() where snapshot_date = current_date;
  insert into pipeline.course_coverage_daily_by_country(snapshot_date,country_code,attribute,state,tier,courses)
  select current_date, country_code, attribute, state, tier, count(*) from pipeline.course_attribute_coverage group by 2,3,4,5
  on conflict (snapshot_date,country_code,attribute,state,tier) do update set courses = excluded.courses, computed_at = now();
  return jsonb_build_object('rows',v_n,'courses',(select count(*) from _c),'ms',round(extract(epoch from clock_timestamp()-v_t0)*1000));
end $$;


ALTER FUNCTION "security"."course_coverage_build_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_fee_dedupe_v1"("p_apply" boolean DEFAULT false, "p_course_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'search', 'pipeline'
    AS $$
declare v_list jsonb; v_n int := 0; v_courses uuid[];
begin
  with a as (
    select f.*, security.course_fee_rank_key(f) rk,
           count(*) over (partition by f.course_id, f.audience, f.fee_type, f.amount) n
    from catalogue.course_fees f
    where f.fee_type='provider_current_tuition' and f.status='active'
      and (p_course_ids is null or f.course_id = any(p_course_ids))),
  r as (select a.*, row_number() over (partition by course_id, audience, fee_type, amount order by rk desc) pos from a where n>1)
  select jsonb_agg(jsonb_build_object('course',(select course_code from catalogue.courses c where c.id=r.course_id),
            'keep', pos=1, 'amount', amount, 'year', fee_year, 'basis', basis, 'origin',
            case when notes like 'CF-247 provider rule admission%' then 'provider rule' when notes ilike '%layer 3%' then 'Layer 3 AI' else 'other' end)
          order by course_id, pos),
         array_agg(distinct course_id)
  into v_list, v_courses from r;
  if p_apply and v_courses is not null then
    with a as (
      select f.id, row_number() over (partition by f.course_id, f.audience, f.fee_type, f.amount order by security.course_fee_rank_key(f) desc) pos,
             count(*) over (partition by f.course_id, f.audience, f.fee_type, f.amount) n
      from catalogue.course_fees f
      where f.fee_type='provider_current_tuition' and f.status='active' and f.course_id = any(v_courses))
    update catalogue.course_fees f set status='superseded', updated_at=now(),
           notes = f.notes || ' | superseded by one-current-tuition rule (Decision 132) ' || to_char(now(),'YYYY-MM-DD')
    from a where a.id=f.id and a.n>1 and a.pos>1;
    get diagnostics v_n = row_count;
    update catalogue.course_fees f set basis=pf.resolved_basis, updated_at=now(),
           notes = f.notes || ' | basis set to the approved provider rule wording (' || pf.rule_code || ', Decision 132)'
    from catalogue.courses c
    join pipeline.provider_fee_profiles pf on pf.provider_id=c.provider_id and pf.active
    where c.id=f.course_id and f.course_id = any(v_courses) and f.status='active'
      and f.fee_type='provider_current_tuition' and f.audience=pf.audience
      and f.basis='annual' and pf.resolved_basis<>'annual';
    perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
  end if;
  return jsonb_build_object('mode',case when p_apply then 'apply' else 'proof' end,'courses',coalesce(cardinality(v_courses),0),'superseded',v_n,'rows',coalesce(v_list,'[]'::jsonb));
end $$;


ALTER FUNCTION "security"."course_fee_dedupe_v1"("p_apply" boolean, "p_course_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_fee_one_current_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue'
    AS $$
begin
  if new.fee_type='provider_current_tuition' and new.status='active' then
    perform security.course_fee_dedupe_v1(true, array[new.course_id]);
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."course_fee_one_current_trg"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "catalogue"."course_fees" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "course_id" "uuid" NOT NULL,
    "fee_year" integer,
    "audience" "text" DEFAULT 'international'::"text" NOT NULL,
    "fee_type" "text" NOT NULL,
    "amount" numeric(14,2),
    "currency_code" character(3),
    "basis" "text",
    "load_basis" "text",
    "is_csp" boolean,
    "notes" "text",
    "valid_from" "date",
    "valid_to" "date",
    "source_id" "uuid",
    "evidence_id" "uuid",
    "confidence" numeric(5,4),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "campus_id" "uuid",
    "source_fee_key" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "last_verified_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source_snapshot_at" timestamp with time zone,
    CONSTRAINT "course_fees_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'inactive'::"text", 'superseded'::"text", 'unverified'::"text"]))),
    CONSTRAINT "course_fees_valid_range_check" CHECK ((("valid_to" IS NULL) OR ("valid_from" IS NULL) OR ("valid_to" >= "valid_from")))
);


ALTER TABLE "catalogue"."course_fees" OWNER TO "postgres";


COMMENT ON TABLE "catalogue"."course_fees" IS 'Temporal evidence-backed Course fee observations. Layer 1 regulatory ingestion does not fabricate fee facts; authoritative/provider Layer 2 sources populate this relation.';



COMMENT ON COLUMN "catalogue"."course_fees"."campus_id" IS 'Optional campus scope only when the authoritative fee source explicitly differentiates fees by campus/location; null means no such scoped distinction is asserted.';



COMMENT ON COLUMN "catalogue"."course_fees"."source_fee_key" IS 'Stable source-local fee observation key used for Layer 2 replay/idempotency. It is not Course identity.';



COMMENT ON COLUMN "catalogue"."course_fees"."source_snapshot_at" IS 'Timestamp/version of the source snapshot that asserted this fee observation. Does not imply a fee year.';



CREATE OR REPLACE FUNCTION "security"."course_fee_rank_key"("f" "catalogue"."course_fees") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue'
    AS $$
  select (case when exists(select 1 from pipeline.sources s where s.id=f.source_id and s.label like 'Layer 4 human review%') then '1' else '0' end)
      || (case when f.fee_year is not null then '1' else '0' end)
      || (case when f.notes like 'CF-247 provider rule admission%' then '1' else '0' end)
      || to_char(coalesce(f.last_verified_at, f.updated_at, 'epoch'::timestamptz),'YYYYMMDDHH24MISS')
      || f.id::text
$$;


ALTER FUNCTION "security"."course_fee_rank_key"("f" "catalogue"."course_fees") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_fee_used_v1"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_year int := extract(year from now())::int; pg record; cr record; v_yrs numeric; v_locked boolean; v_ann numeric; v_ev boolean;
begin
  select f.amount, f.fee_year, f.currency_code, f.evidence_id into pg from catalogue.course_fees f
   where f.course_id = p_course_id and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and f.status = 'active' and f.amount > 0
     and f.basis in ('annual', 'indicative_annual', 'current indicative annual international tuition')
   order by f.fee_year desc nulls last, f.created_at desc limit 1;
  select f.amount, f.currency_code into cr from catalogue.course_fees f
   where f.course_id = p_course_id and f.fee_type = 'tuition' and f.audience = 'international' and f.status = 'active' and f.amount > 0 and f.basis = 'registered_total_course'
   order by f.created_at desc limit 1;
  select case c.duration_unit when 'weeks' then c.duration_value / 52.0 when 'years' then c.duration_value when 'months' then c.duration_value / 12.0 end into v_yrs
    from catalogue.courses c where c.id = p_course_id;
  v_locked := exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = p_course_id and m.field in ('tuition', 'fee', 'fees'));
  if cr.amount is not null and coalesce(v_yrs, 0) > 0 then v_ann := round(cr.amount / greatest(v_yrs, 1), 0); end if;
  v_ev := pg.amount is not null and pg.evidence_id is not null and security.fee_evidence_own_site_v1(pg.evidence_id, p_course_id);
  if pg.amount is not null and (cr.amount is null or (not v_locked and v_ev) or (v_locked and pg.fee_year >= v_year)) then
    return jsonb_build_object('source', 'page', 'per_year', pg.amount, 'currency', pg.currency_code, 'year', pg.fee_year, 'cricos_per_year', v_ann, 'locked', v_locked, 'rule', 'rule_2',
      'reason', case when cr.amount is null then 'No CRICOS fee is registered, so the course page fee is used.'
                     when v_locked then 'The course page names ' || pg.fee_year || ', this year or later, so the page fee is used (fee entered or locked by hand: earlier rule kept).'
                     else 'The provider''s own course page gives this fee' || coalesce(' for ' || pg.fee_year, '') || ' and its evidence is captured, so it is used over the CRICOS registered fee (Rule 2).' end);
  elsif cr.amount is not null and v_ann is not null then
    return jsonb_build_object('source', 'cricos', 'per_year', v_ann, 'currency', cr.currency_code, 'year', null, 'page_per_year', pg.amount, 'page_year', pg.fee_year, 'locked', v_locked, 'rule', 'rule_2',
      'reason', case when pg.amount is null then 'No course page fee has been read, so the CRICOS registered fee is held (the registered total, divided by the course length when that is a year or more).'
                     when v_locked then 'A fee is entered or locked by hand and the course page names no current year, so the CRICOS registered fee is kept.'
                     when pg.evidence_id is null then 'The course page fee has no captured evidence, so the CRICOS registered fee is held.'
                     else 'The course page fee was read from a site shared by several providers, not the provider''s own site, so the CRICOS registered fee is held.' end);
  end if;
  return jsonb_build_object('source', null, 'locked', v_locked, 'reason', 'No page fee or CRICOS fee with a course length is stored.');
end $$;


ALTER FUNCTION "security"."course_fee_used_v1"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_field_lock_flags_v1"() RETURNS TABLE("entity_id" "uuid", "li" boolean, "le" boolean, "lf" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select l.entity_id, bool_or(l.field in ('intakes','intake')), bool_or(l.field in ('english','english_requirements')), bool_or(l.field in ('tuition','fee','fees'))
    from pipeline.manual_locks l where l.entity = 'course' group by l.entity_id
$$;


ALTER FUNCTION "security"."course_field_lock_flags_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_field_source_build_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int; v_t0 timestamptz := clock_timestamp();
begin
  create temp table _lk on commit drop as select * from security.course_field_lock_flags_v1();
  create temp table _fs on commit drop as
  select c.id course_id, c.provider_id, k.iso_alpha2::text cc,
    case when i.months is null then 'missing' when lk.li then 'hand' when i.calendar then 'central'
         when pg.evidence_id is not null and i.from_page then case when pg.candidates->>'intakes_by'='adapter' then 'adapter' else 'reader' end else 'other' end isrc,
    case when e.id is null then 'missing' when lk.le then 'hand' when e.source_requirement_key like 'policy:%' then 'central'
         when pg.evidence_id is not null and e.evidence_id=pg.evidence_id then case when pg.candidates->>'english_by'='adapter' then 'adapter' else 'reader' end else 'other' end esrc,
    case when f.id is null then 'missing' when lk.lf then 'hand'
         when pg.evidence_id is not null and f.evidence_id=pg.evidence_id then case when pg.candidates->>'fee_by'='adapter' then 'adapter' else 'reader' end else 'other' end fsrc
    from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries k on k.id=p.country_id
    left join pipeline.coverage_course_pages pg on pg.course_id=c.id left join _lk lk on lk.entity_id=c.id
    left join lateral (select array_agg(distinct x.intake_label) months, bool_or(coalesce(x.source_intake_key,'') like 'calendar%') calendar, bool_or(pg.evidence_id is not null and x.evidence_id=pg.evidence_id) from_page from catalogue.course_intakes x where x.course_id=c.id and x.status='active') i on true
    left join lateral (select r.id, r.source_requirement_key, r.evidence_id from catalogue.course_english_requirements r join ref.english_tests t on t.id=r.english_test_id where r.course_id=c.id and t.code='IELTS' and coalesce(r.status,'active')='active' order by r.last_verified_at desc nulls last limit 1) e on true
    left join lateral (select x.id, x.evidence_id from catalogue.course_fees x where x.course_id=c.id and x.status='active' and x.fee_type='provider_current_tuition' and x.audience='international' order by x.fee_year desc nulls last, x.updated_at desc nulls last limit 1) f on true
   where c.lifecycle_status='active';
  insert into pipeline.course_field_source (course_id, provider_id, country_code, tier, intakes_src, english_src, fee_src, computed_at)
  select s.course_id, s.provider_id, s.cc, (select x.tier from pipeline.course_attribute_coverage x where x.course_id=s.course_id limit 1), s.isrc, s.esrc, s.fsrc, now() from _fs s
  on conflict (course_id) do update set provider_id=excluded.provider_id, country_code=excluded.country_code, tier=excluded.tier, intakes_src=excluded.intakes_src, english_src=excluded.english_src, fee_src=excluded.fee_src, computed_at=excluded.computed_at;
  get diagnostics v_n = row_count;
  return jsonb_build_object('rows', v_n, 'ms', round(extract(epoch from clock_timestamp()-v_t0)*1000));
end $$;


ALTER FUNCTION "security"."course_field_source_build_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_field_source_prune_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n integer;
begin
  delete from pipeline.course_field_source s where not exists (select 1 from catalogue.courses c where c.id = s.course_id and c.lifecycle_status = 'active');
  get diagnostics v_n = row_count;
  return v_n;
end $$;


ALTER FUNCTION "security"."course_field_source_prune_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_full_time_years"("p_course_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (select case when co.duration_value > 0 then greatest(0.5, least(8, round(case co.duration_unit when 'weeks' then co.duration_value / 26.0 when 'months' then co.duration_value / 6.0 when 'years' then co.duration_value * 2 when 'semesters' then co.duration_value when 'trimesters' then co.duration_value / 1.5 end) / 2)) end
       from catalogue.courses co where co.id = p_course_id),
    (select greatest(0.5, least(8, round(coalesce(security.course_years_from_text(pg.candidates->'adapter_extra'->>'course_years'), security.course_years_from_text(pg.candidates->'adapter_extra'->>'duration')) * 2) / 2))
       from pipeline.coverage_course_pages pg where pg.course_id = p_course_id))
$$;


ALTER FUNCTION "security"."course_full_time_years"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_bind_v1"("p_course_id" "uuid", "p_provider_id" "uuid", "p_url" "text", "p_basis" "text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  insert into pipeline.coverage_course_pages(course_id, provider_id, url, basis, status, bound_at, next_read_at, read_attempts)
  select p_course_id, p_provider_id, p_url, p_basis, 'bound', now(), now(), 0
   where not exists (select 1 from pipeline.course_page_blocks b where b.course_id = p_course_id and b.url = p_url)
  on conflict (course_id) do update set url = excluded.url, basis = excluded.basis, status = 'bound', bound_at = now(),
         score = null, runner_up = null, read_status = null, read_at = null, http_status = null, fetched_via = null,
         identity_basis = null, evidence_id = null, candidates = null, leased_until = null, read_attempts = 0, next_read_at = now()
   where pipeline.coverage_course_pages.status <> 'bound' or pipeline.coverage_course_pages.basis in ('cricos_search','title_search');
$$;


ALTER FUNCTION "security"."course_link_bind_v1"("p_course_id" "uuid", "p_provider_id" "uuid", "p_url" "text", "p_basis" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_pick_v1"("p_provider_id" "uuid", "p_urls" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  with pat as (select ord, e->>'re' re, replace(e->>'rep','{year}',extract(year from now())::int::text) rep
                 from pipeline.course_link_recipes r, jsonb_array_elements(r.patterns) with ordinality x(e, ord)
                where r.provider_id = p_provider_id and r.active),
       u as (select case when url ~* '\.(php|aspx?|cfm|jsp)\?' then regexp_replace(url, '#.*$', '') else regexp_replace(url, '[?#].*$', '') end url, i from unnest(p_urls) with ordinality y(url, i) where url is not null),
       m as (select pat.ord, u.i, regexp_replace(u.url, pat.re, pat.rep) cand from pat join u on u.url ~ pat.re),
       d as (select cand, min(ord*1000+i) k from m group by cand)
  select coalesce(array_agg(cand order by k), '{}') from d
$_$;


ALTER FUNCTION "security"."course_link_pick_v1"("p_provider_id" "uuid", "p_urls" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_reverse_enqueue_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v int;
begin
  insert into pipeline.course_link_reverse(url, provider_id)
  select distinct regexp_replace(u.url, '#.*$', ''), u.provider_id
    from pipeline.coverage_provider_urls u join pipeline.course_link_recipes rc on rc.provider_id = u.provider_id and rc.active
   where exists (select 1 from jsonb_array_elements(rc.patterns) e where regexp_replace(u.url, '[?#].*$', '') ~ (e->>'re'))
     and not exists (select 1 from pipeline.coverage_course_pages p where p.provider_id = u.provider_id and p.status = 'bound' and p.url = u.url)
  on conflict (url) do nothing;
  get diagnostics v = row_count;
  return v;
end $_$;


ALTER FUNCTION "security"."course_link_reverse_enqueue_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_reverse_tick_v1"("p_batch" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; n_done int := 0; n_bound int := 0; n_sent int := 0;
begin
  -- 1. Store the CRICOS codes printed on each page read.
  for r in select x.url, h.status_code, h.content from pipeline.course_link_reverse x join net._http_response h on h.id = x.req_id where x.state = 'sent' loop
    n_done := n_done + 1;
    if r.status_code = 200 and r.content is not null then
      update pipeline.course_link_reverse set state = 'done', done_at = now(),
             codes = array(select distinct m[1] from regexp_matches(upper(r.content), '(?:^|[^0-9A-Z])([0-9]{6}[0-9A-Z])(?![0-9A-Z])', 'g') m)
       where url = r.url;
    else
      update pipeline.course_link_reverse set state = 'error', done_at = now() where url = r.url;
    end if;
  end loop;
  update pipeline.course_link_reverse set state = 'queued'
   where state = 'sent' and sent_at < now() - interval '20 minutes' and not exists (select 1 from net._http_response h where h.id = req_id);

  -- 2. For universities whose pages are all read: bind a course still being searched for when its code is on exactly
  --    one page, and that page shows no more than three of the university's codes.
  for r in with done_prov as (select provider_id from pipeline.course_link_reverse group by provider_id
                               having bool_and(state in ('done','error')) and bool_or(state = 'done')),
                pc as (select x.provider_id, x.url, co.id course_id, co.course_code
                         from pipeline.course_link_reverse x join done_prov using (provider_id)
                         join catalogue.courses co on co.provider_id = x.provider_id and co.lifecycle_status = 'active' and co.course_code = any(x.codes)
                        where x.state = 'done'),
                per_page as (select url, count(*) n from pc group by url),
                per_code as (select course_id, count(distinct url) n from pc group by course_id)
           select pc.provider_id, pc.url, pc.course_id from pc join per_page pp using (url) join per_code pk using (course_id)
             join pipeline.course_link_search s on s.course_id = pc.course_id and s.state in ('queued','none','error')
            where pp.n <= 3 and pk.n = 1 loop
    update pipeline.course_link_search set state = 'found', candidates = to_jsonb(array[r.url]), cand_idx = 1, bound_url = r.url, done_at = now()
     where course_id = r.course_id;
    perform security.course_link_bind_v1(r.course_id, r.provider_id, r.url, 'cricos_search');
    update pipeline.course_link_reverse set bound = bound + 1 where url = r.url;
    n_bound := n_bound + 1;
  end loop;

  -- 3. Read the next pages, universities in turn.
  for r in select x.url from pipeline.course_link_reverse x where x.state = 'queued'
            order by row_number() over (partition by x.provider_id order by x.url) limit greatest(1, least(coalesce(p_batch, 30), 60)) loop
    update pipeline.course_link_reverse set state = 'sent', sent_at = now(),
           req_id = net.http_get(r.url, headers := jsonb_build_object('user-agent', 'Mozilla/5.0 (compatible; CourseFinderBot/1.0)'), timeout_milliseconds := 30000)
     where url = r.url;
    n_sent := n_sent + 1;
  end loop;
  return jsonb_build_object('read', n_done, 'bound', n_bound, 'sent', n_sent);
end $$;


ALTER FUNCTION "security"."course_link_reverse_tick_v1"("p_batch" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_search_enqueue_v1"("p_provider_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v int;
begin
  insert into pipeline.course_link_search(course_id, provider_id)
  select c.id, c.provider_id
    from catalogue.courses c join pipeline.course_link_recipes r on r.provider_id = c.provider_id and r.active
    left join pipeline.coverage_course_pages p on p.course_id = c.id
   where c.lifecycle_status = 'active' and c.course_code ~ '^[0-9]{6}[0-9A-Z]$'
     and (p_provider_id is null or c.provider_id = p_provider_id)
     and (p.course_id is null or p.status = 'mismatch' or (p.status = 'ambiguous' and p.read_status is not null))
  on conflict (course_id) do nothing;
  get diagnostics v = row_count;
  return v;
end $_$;


ALTER FUNCTION "security"."course_link_search_enqueue_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_search_tick_v1"("p_batch" integer DEFAULT 40) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v_urls text[]; v_c text[]; v_cap numeric; v_on boolean; v_used numeric; v_key text; v_dom text;
        n_harvest int := 0; n_found int := 0; n_moved int := 0; n_sent int := 0; v_next text;
begin
  select enabled, monthly_credit_cap into v_on, v_cap from pipeline.course_link_search_settings where id = 1;

  -- 1. Collect finished searches.
  for r in select s.*, h.status_code, h.content from pipeline.course_link_search s join net._http_response h on h.id = s.req_id
            where s.state = 'sent' loop
    n_harvest := n_harvest + 1;
    if r.status_code = 200 and left(r.content, 1) = '{' then
      perform public.svc_coverage_usage(2, 'course_link_search', r.provider_id, r.query);
      v_urls := array(select e->>'url' from jsonb_array_elements(coalesce((r.content::jsonb)->'data', '[]'::jsonb)) e);
      v_c := security.course_link_pick_v1(r.provider_id, v_urls);
      if cardinality(v_c) > 0 then
        update pipeline.course_link_search set state = 'found', results = to_jsonb(v_urls), candidates = to_jsonb(v_c), cand_idx = 1,
               bound_url = v_c[1], done_at = now() where course_id = r.course_id;
        perform security.course_link_bind_v1(r.course_id, r.provider_id, v_c[1], case r.stage when 'cricos' then 'cricos_search' else 'title_search' end);
        n_found := n_found + 1;
      elsif r.stage = 'cricos' then
        update pipeline.course_link_search set stage = 'title', state = 'queued', results = to_jsonb(v_urls), attempts = 0 where course_id = r.course_id;
      else
        update pipeline.course_link_search set state = 'none', results = to_jsonb(v_urls), done_at = now() where course_id = r.course_id;
      end if;
    else
      update pipeline.course_link_search set attempts = attempts + 1, state = case when attempts + 1 >= 3 then 'error' else 'queued' end,
             results = jsonb_build_object('http_status', r.status_code, 'body', left(r.content, 300)) where course_id = r.course_id;
    end if;
  end loop;
  -- searches with no response after 20 minutes are sent again
  update pipeline.course_link_search set state = 'queued', attempts = attempts + 1
   where state = 'sent' and sent_at < now() - interval '20 minutes' and not exists (select 1 from net._http_response h where h.id = req_id);

  -- 2. Pages the reader could not confirm move to the next candidate, then to the title search.
  for r in select s.*, p.status pstatus, p.read_status, p.read_attempts from pipeline.course_link_search s
             join pipeline.coverage_course_pages p on p.course_id = s.course_id and p.url = s.bound_url
            where s.state = 'found' and (p.status = 'mismatch' or (p.read_status in ('fetch_failed','blocked','robots_disallowed') and (p.read_attempts >= 2 or p.http_status in (404, 410)))) loop
    if r.cand_idx < jsonb_array_length(r.candidates) then
      v_next := r.candidates->>r.cand_idx;
      update pipeline.course_link_search set cand_idx = cand_idx + 1, bound_url = v_next where course_id = r.course_id;
      perform security.course_link_bind_v1(r.course_id, r.provider_id, v_next, case r.stage when 'cricos' then 'cricos_search' else 'title_search' end);
    elsif r.stage = 'cricos' then
      update pipeline.course_link_search set stage = 'title', state = 'queued', attempts = 0, done_at = null where course_id = r.course_id;
    else
      update pipeline.course_link_search set state = 'none', done_at = now() where course_id = r.course_id;
    end if;
    n_moved := n_moved + 1;
  end loop;
  update pipeline.course_link_search s set state = 'verified' from pipeline.coverage_course_pages p
   where s.state = 'found' and p.course_id = s.course_id and p.url = s.bound_url and p.status = 'bound' and p.identity_basis is not null;

  -- 2b. Decision 217: courses without a CRICOS code whose earlier page was read again and is not theirs are searched by title.
  insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at)
  select p.course_id, p.provider_id, 'title', 'queued', now()
    from pipeline.coverage_course_pages p join catalogue.courses c on c.id = p.course_id and c.lifecycle_status = 'active'
   where p.status = 'mismatch' and p.basis not in ('cricos_search', 'title_search')
     and coalesce(c.course_code, '') !~ '^[0-9]{6}[0-9A-Z]$'
     and exists (select 1 from pipeline.course_link_recipes rc where rc.provider_id = p.provider_id and rc.active)
     and not exists (select 1 from pipeline.course_link_search s where s.course_id = p.course_id)
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = p.course_id and k.field = 'official_url')
   limit 200
  on conflict (course_id) do nothing;

  -- 2c. Decision 252: pages from the Serper search pass, after the reader.
  perform security.search_pass_advance_v1();

  -- 3. Send the next batch, inside the monthly credit cap.
  select coalesce(sum(units), 0) into v_used from pipeline.coverage_vendor_usage where purpose = 'course_link_search' and at >= date_trunc('month', now());
  if v_on and coalesce((select x.send_via from pipeline.course_link_search_settings x where x.id = 1), 'pg_net') = 'pg_net' and v_used + 2 * p_batch <= v_cap then
    v_key := public.svc_coverage_firecrawl()->>'secret';
    if v_key is not null then
      for r in select s.course_id, s.provider_id, s.stage, c.course_code, c.canonical_title, rc.search_domain
                 from pipeline.course_link_search s join catalogue.courses c on c.id = s.course_id
                 join pipeline.course_link_recipes rc on rc.provider_id = s.provider_id and rc.active
                 left join pipeline.provider_priority pp on pp.provider_id = s.provider_id
                where s.state = 'queued' order by (s.stage <> 'cricos'), row_number() over (partition by s.provider_id order by md5(s.course_id::text)), coalesce(pp.rank, 100000)
                limit greatest(1, least(coalesce(p_batch, 40), 100)) loop
        v_dom := case r.stage when 'cricos' then '"' || r.course_code || '" site:' || r.search_domain
                                         else '"' || replace(regexp_replace(r.canonical_title, '\s*\(\s*Level\s+\d{1,2}\s*\)\s*$', '', 'i'), '"', '') || '" site:' || r.search_domain end;
        update pipeline.course_link_search set state = 'sent', sent_at = now(), query = v_dom,
               req_id = net.http_post(url := 'https://api.firecrawl.dev/v1/search',
                          headers := jsonb_build_object('Authorization', 'Bearer ' || v_key, 'Content-Type', 'application/json'),
                          body := jsonb_build_object('query', v_dom, 'limit', 5), timeout_milliseconds := 60000)
         where course_id = r.course_id;
        n_sent := n_sent + 1;
      end loop;
    end if;
  end if;
  return jsonb_build_object('collected', n_harvest, 'found', n_found, 'moved_on', n_moved, 'sent', n_sent, 'credits_this_month', v_used, 'cap', v_cap);
end $_$;


ALTER FUNCTION "security"."course_link_search_tick_v1"("p_batch" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_title_key"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select btrim(regexp_replace(replace(lower(coalesce(p, '')), '&', ' and '), '[^a-z0-9]+', ' ', 'g'))
$$;


ALTER FUNCTION "security"."course_title_key"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_years_from_text"("p_text" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  s text := lower(coalesce(p_text, ''));
  u text := '(years?|yrs?|months?|weeks?|semesters?|trimesters?)';
  m text[]; n numeric; y numeric;
begin
  if s ~ '^\s*[0-9]+(\.[0-9]+)?\s*$' then n := btrim(s)::numeric; return case when n > 0 and n <= 10 then n end; end if;
  s := regexp_replace(s, '(up to\s*)?[0-9]+(\.[0-9]+)?\s*' || u || '\s*,?\s*(of\s+)?part[ -]time', ' ', 'g');
  s := regexp_replace(s, 'up to\s*[0-9]+(\.[0-9]+)?\s*' || u, ' ', 'g');
  s := regexp_replace(s, 'part[ -]time[^0-9]{0,40}[0-9]+(\.[0-9]+)?\s*' || u, ' ', 'g');
  if s ~ '[0-9](\.[0-9]+)?\s*(–|—|-|to)\s*[0-9]' then return null; end if;
  if s ~ ('[0-9]\s*' || u || '[^0-9]{0,60}\mor\M[^0-9]{0,30}[0-9]+(\.[0-9]+)?\s*' || u) then return null; end if;
  m := regexp_match(s, '([0-9]+(?:\.[0-9]+)?)\s*' || u);
  if m is null then return null; end if;
  n := m[1]::numeric;
  y := case when m[2] ~ '^month' then n / 12 when m[2] ~ '^week' then n / 52 when m[2] ~ '^semester' then n / 2 when m[2] ~ '^trimester' then n / 3 else n end;
  if m[2] ~ '^(year|yr)' then
    m := regexp_match(s, '[0-9]+(?:\.[0-9]+)?\s*(?:years?|yrs?)\s*(?:and\s*)?([0-9]+)\s*months?');
    if m is not null then y := y + m[1]::numeric / 12; end if;
  end if;
  y := round(y, 2);
  return case when y > 0 and y <= 10 then y end;
end $_$;


ALTER FUNCTION "security"."course_years_from_text"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_admission_apply_v1"("p_limit" integer DEFAULT 300, "p_extractor" "text" DEFAULT 'coverage-sweep-v0.5.4'::"text", "p_attributes" "text"[] DEFAULT ARRAY['official_url'::"text", 'english'::"text"]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security', 'search'
    AS $$
declare r record; v_src uuid; v_ok int:=0; v_err int:=0; v_l4 int:=0; v_courses uuid[]:='{}'; v_before jsonb; v_after jsonb; v_payload jsonb; v_last text;
begin
  drop table if exists _adm;
  create temp table _adm on commit drop as select * from security.coverage_admission_plan_v1(p_extractor) where action in ('write','differs') and attribute=any(p_attributes);
  if not exists (select 1 from _adm) then return jsonb_build_object('written',0,'layer4',0); end if;

  insert into pipeline.course_fact_source_qualifications(source_id,country_id,source_key,source_class,authority_name,provider_cricos,admitted_domains,mapping_strategy,evidence_strategy,qualification_status,notes,metadata)
  select distinct on (s.id) s.id, s.country_id, 'au_'||lower(a.provider_cricos)||'_coverage_sweep','provider_first_party',
         coalesce(p.display_name,p.canonical_name), upper(a.provider_cricos), array['official_course_url','english_requirement','intake'],
         'course page accepted only when it prints the course''s CRICOS code',
         'page stored gzipped as evidence with its SHA-256; values written only where the course has none',
         'bounded','Decision 163 admission rule (Platform Admin 29 Sep 2026)',
         jsonb_build_object('decision','Decision 163','apply_admitted',true,'search_admitted',true,'identity_authority',false,'change_control_ref','CF-CHG-20260915-247')
    from _adm a join catalogue.providers p on p.id=a.provider_id
    cross join lateral (select security.coverage_sweep_source(a.provider_id) id) x
    join pipeline.sources s on s.id=x.id
   where a.action='write' and a.provider_cricos is not null
     and not exists (select 1 from pipeline.course_fact_source_qualifications q where q.source_id=s.id and q.provider_cricos=upper(a.provider_cricos));

  insert into search.enrichment_source_gates(projection_code,domain_code,source_id,gate_status,approval_ref,approved_at,created_at,updated_at)
  select distinct 'courses', d, security.coverage_sweep_source(a.provider_id), 'approved',
         'CF-CHG-20260915-247; Decision 163 admission rule; Platform Admin approval 29 Sep 2026 09:56 IST', now(), now(), now()
    from _adm a cross join unnest(array_remove(array['official_course_url', case when 'english'=any(p_attributes) then 'course_english' end, case when 'intakes'=any(p_attributes) then 'course_intake' end],null)) d
   where a.action='write'
     and not exists (select 1 from search.enrichment_source_gates g where g.projection_code='courses' and g.domain_code=d and g.source_id=security.coverage_sweep_source(a.provider_id));

  v_before:=security.consumer_api_snapshot_v1();
  for r in select a.course_id, a.provider_id, a.provider_cricos, a.course_cricos, a.evidence_id, a.content_hash, a.page_url,
                  jsonb_object_agg(a.attribute, a.proposed) props
             from _adm a where a.action='write'
            group by 1,2,3,4,5,6,7 order by md5(a.course_id::text||clock_timestamp()::text) limit greatest(1,least(coalesce(p_limit,300),1000)) loop
    v_payload:='{}'::jsonb;
    if r.props ? 'official_url' then v_payload:=v_payload||jsonb_build_object('course_url',r.props->'official_url'->>'course_url','link_type','official_course','audience','international'); end if;
    if r.props ? 'english' and not security.uni_adapter_excluded(r.course_id, 'english') then v_payload:=v_payload||jsonb_build_object('english_requirements',r.props->'english'->'english_requirements'); end if;
    if r.props ? 'intakes' and not security.uni_adapter_excluded(r.course_id, 'intakes') then v_payload:=v_payload||jsonb_build_object('intakes',r.props->'intakes'->'intakes'); end if;
    begin
      if r.provider_cricos is null or r.course_cricos is null then
        perform security.coverage_apply_course_v1(r.course_id, security.coverage_sweep_source(r.provider_id), r.evidence_id, r.page_url, r.content_hash, v_payload);
      else
      perform public.svc_coursefacts_apply_record(security.coverage_sweep_source(r.provider_id), r.evidence_id, r.provider_cricos, r.course_cricos,
              'coverage:'||r.course_id, r.page_url, r.content_hash, v_payload, true);
      end if;
      v_ok:=v_ok+1; v_courses:=v_courses||r.course_id;
    exception when others then v_err:=v_err+1; v_last:=left(sqlerrm,200);
    end;
  end loop;

  insert into pipeline.layer4_review_items(entity_type,entity_id,field_code,evidence_id,before_value,proposed_value,layer2_state,layer3_state,status,escalation_reason,change_control_ref)
  select 'course', a.course_id,
         case a.attribute when 'official_url' then 'official_course_url' when 'english' then 'course_english' else 'course_intake' end,
         a.evidence_id, a.current, a.proposed, jsonb_build_object('source','coverage sweep','page',a.page_url), '{}'::jsonb, 'pending',
         case a.attribute
           when 'official_url' then 'The course page that shows this course''s CRICOS code is a different address from the official page we hold. Please check which page is current.'
           when 'english' then 'The course page gives a different English score from the one we hold. Please check the page and confirm the requirement.'
           else 'The course page lists different intake months from the ones we hold. Please check the page and confirm the intakes.' end,
         'CF-CHG-20260915-247'
    from _adm a
   where a.action='differs'
     and not exists (select 1 from pipeline.layer4_review_items i where i.entity_type='course' and i.entity_id=a.course_id and i.status='pending'
                       and i.field_code=case a.attribute when 'official_url' then 'official_course_url' when 'english' then 'course_english' else 'course_intake' end);
  get diagnostics v_l4=row_count;

  if cardinality(v_courses)>0 then
    perform search.refresh_course_enrichment_scoped_v1(v_courses,true);
    v_after:=security.consumer_api_snapshot_v1();
    insert into pipeline.consumer_api_baselines(label,snapshot) values
      ('before coverage admission batch ('||cardinality(v_courses)||' courses, Decision 163)',v_before),
      ('after coverage admission batch ('||cardinality(v_courses)||' courses, Decision 163)',v_after);
  end if;
  return jsonb_build_object('written',v_ok,'errors',v_err,'last_error',v_last,'layer4',v_l4);
end $$;


ALTER FUNCTION "security"."coverage_admission_apply_v1"("p_limit" integer, "p_extractor" "text", "p_attributes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_admission_plan_v1"("p_extractor" "text" DEFAULT 'coverage-sweep-v0.5.3'::"text") RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "provider_cricos" "text", "course_cricos" "text", "evidence_id" "uuid", "content_hash" "text", "page_url" "text", "attribute" "text", "action" "text", "proposed" "jsonb", "current" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
  with pg as (
    select p.course_id, p.provider_id, p.url, p.evidence_id, p.candidates c, e.content_hash, p.identity_basis ib,
           (select pr.registration_code from catalogue.provider_registrations pr where pr.provider_id=p.provider_id and lower(pr.registration_scheme)='cricos' and coalesce(pr.status,'active') not in ('inactive','cancelled','archived') order by pr.checked_at desc nulls last limit 1) pc,
           (select cr.registration_code from catalogue.course_registrations cr where cr.course_id=p.course_id and lower(cr.scheme)='cricos' limit 1) cc
      from pipeline.coverage_course_pages p join pipeline.evidence_artifacts e on e.id=p.evidence_id
      join catalogue.courses co on co.id=p.course_id and co.lifecycle_status='active'
     where p.read_status='read' and security.coverage_identity_allowed(p.provider_id, p.identity_basis, null) and p.candidates->>'extractor'=p_extractor
       and not security.layer4_entity_or_parent_blocked('course',p.course_id,'operational')),
  url as (
    select pg.*, 'official_url'::text attribute,
           jsonb_build_object('course_url',coalesce(nullif(pg.c->>'final_url',''),pg.url)) proposed,
           (select jsonb_agg(l.url) from catalogue.course_links l where l.course_id=pg.course_id and l.link_type='official_course' and l.status='active') cur
      from pg where security.coverage_identity_allowed(pg.provider_id, pg.ib, 'official_url')),
  eng as (
    select pg.*, 'english'::text attribute,
           jsonb_build_object('english_requirements',
             (select jsonb_agg(x) from (
                select jsonb_build_object('test_code','IELTS','overall_score',(pg.c->'english'->>'ielts_overall')::numeric,
                         'component_scores',case when pg.c->'english' ? 'ielts_min_band' then jsonb_build_object('listening',(pg.c->'english'->>'ielts_min_band')::numeric,'reading',(pg.c->'english'->>'ielts_min_band')::numeric,'writing',(pg.c->'english'->>'ielts_min_band')::numeric,'speaking',(pg.c->'english'->>'ielts_min_band')::numeric) else '{}'::jsonb end,
                         'notes','Course page (CRICOS code on page), coverage sweep') x where pg.c->'english' ? 'ielts_overall'
                union all select jsonb_build_object('test_code','PTE','overall_score',(pg.c->'english'->>'pte_overall')::numeric,'notes','Course page (CRICOS code on page), coverage sweep') where pg.c->'english' ? 'pte_overall'
                union all select jsonb_build_object('test_code','TOEFL_IBT','overall_score',(pg.c->'english'->>'toefl_overall')::numeric,'notes','Course page (CRICOS code on page), coverage sweep') where pg.c->'english' ? 'toefl_overall') q)) proposed,
           (select jsonb_agg(jsonb_build_object('test',t.code,'overall',r.overall_score)) from catalogue.course_english_requirements r join ref.english_tests t on t.id=r.english_test_id where r.course_id=pg.course_id and r.status='active') cur
      from pg where pg.c->'english' ?| array['ielts_overall','pte_overall','toefl_overall'] and security.coverage_identity_allowed(pg.provider_id, pg.ib, 'english') and (coalesce(pg.c->>'english_by','')<>'adapter' or exists (select 1 from pipeline.uni_adapters u where u.provider_id=pg.provider_id and u.enabled and u.admit and 'english' = any (u.admit_fields)))),
  itk as (
    select pg.*, 'intakes'::text attribute,
           jsonb_build_object('intakes',(select jsonb_agg(jsonb_build_object('intake_label',m,'source_intake_key',lower(pg.cc)||':current:'||lower(m))) from jsonb_array_elements_text(pg.c->'intakes') mm(m))) proposed,
           (select jsonb_agg(i.intake_label) from catalogue.course_intakes i where i.course_id=pg.course_id and coalesce(i.status,'active')='active') cur
      from pg where jsonb_array_length(coalesce(pg.c->'intakes','[]'))>0 and security.coverage_identity_allowed(pg.provider_id, pg.ib, 'intakes') and pg.c->>'intakes_by'='adapter' and exists (select 1 from pipeline.uni_adapters u where u.provider_id=pg.provider_id and u.enabled and u.admit and 'intakes' = any (u.admit_fields))),
  allx as (select * from url union all select * from eng union all select * from itk)
  select a.course_id, a.provider_id, a.pc, a.cc, a.evidence_id, a.content_hash, a.url, a.attribute,
         case
           when (a.pc is null or a.cc is null) and security.coverage_country(a.provider_id) = 'AU' then 'unresolved'
           when a.cur is null then 'write'
           when a.attribute='official_url' and exists (select 1 from jsonb_array_elements_text(a.cur) k(v) where security.coverage_norm_url(k.v)=security.coverage_norm_url(a.proposed->>'course_url')) then 'same'
           when a.attribute='english' and not exists (
                  select 1 from jsonb_array_elements(a.proposed->'english_requirements') r(p)
                   where not exists (select 1 from jsonb_array_elements(a.cur) k(v) where k.v->>'test'=p->>'test_code' and (k.v->>'overall')::numeric=(p->>'overall_score')::numeric)
                     and exists (select 1 from jsonb_array_elements(a.cur) k(v) where k.v->>'test'=p->>'test_code')) then 'same'
           when a.attribute='intakes' and not exists (
                  select 1 from jsonb_array_elements(a.proposed->'intakes') r(p)
                   where not exists (select 1 from jsonb_array_elements_text(a.cur) k(v) where k.v ilike '%'||(p->>'intake_label')||'%')) then 'same'
           else 'differs' end,
         a.proposed, a.cur
    from allx a
$$;


ALTER FUNCTION "security"."coverage_admission_plan_v1"("p_extractor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_ai_match_prepare_v1"("p_providers" integer DEFAULT 4, "p_courses" integer DEFAULT 300) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $_$
declare r record; v jsonb := '[]'::jsonb; v_n int;
begin
  for r in
    with missing as (
      select co.provider_id, count(*) n
        from catalogue.courses co
        left join pipeline.coverage_course_pages p on p.course_id = co.id
       where co.lifecycle_status = 'active'
         and (p.course_id is null or p.status = 'mismatch')
         and not exists (select 1 from pipeline.coverage_ai_match q where q.course_id = co.id and q.state in ('ready', 'leased', 'no_candidates'))
         and (select count(*) from pipeline.coverage_ai_match q where q.course_id = co.id) < 3
       group by 1)
    select m.provider_id, m.n from missing m
     where exists (select 1 from pipeline.coverage_provider_urls u where u.provider_id = m.provider_id)
     order by coalesce((select pp.rank from pipeline.provider_priority pp where pp.provider_id = m.provider_id), 100000), m.n desc
     limit greatest(1, least(p_providers, 500))
  loop
    insert into pipeline.coverage_ai_match(course_id, provider_id, attempt, state, candidates)
    with c as (
      select co.id course_id, lower(coalesce(co.course_code, '')) code,
             security.coverage_text_tokens(regexp_replace(co.canonical_title, '\(\s*level\s+\d+\s*\)', '', 'i')) tok,
             (select count(*) from pipeline.coverage_ai_match q where q.course_id = co.id) prev
        from catalogue.courses co
        left join pipeline.coverage_course_pages p on p.course_id = co.id
       where co.provider_id = r.provider_id and co.lifecycle_status = 'active'
         and (p.course_id is null or p.status = 'mismatch')
         and not exists (select 1 from pipeline.coverage_ai_match q where q.course_id = co.id and q.state in ('ready', 'leased', 'no_candidates'))
         and (select count(*) from pipeline.coverage_ai_match q where q.course_id = co.id) < 3
       order by coalesce(co.open_to_international, false) desc, co.id
       limit greatest(1, least(p_courses, 1000))),
    tried as (
      select p.course_id, p.url from pipeline.coverage_course_pages p join c using (course_id)
      union select q.course_id, q.chosen_url from pipeline.coverage_ai_match q join c using (course_id) where q.chosen_url is not null),
    u as (
      select url, title, tokens, title_tokens, cardinality(tokens) ns, cardinality(title_tokens) nt
        from pipeline.coverage_provider_urls where provider_id = r.provider_id
         and url !~* '/(inherent-requirements|entry-requirements|admission-requirements|english-requirements|fees?|tuition-fees?|scholarships?|apply|how-to-apply|applying|careers?|credit|recognition-of-prior-learning|timetables?|news|events?|stories|blog|alumni|contact|faqs?)(/|$)'
         and url !~* '\.(pdf|jpe?g|png|gif|svg|docx?|xlsx?|zip)(\?|$)'),
    ct as (select course_id, cardinality(tok) nc, t from c, unnest(tok) t),
    ut as (select url, ns n, t from u, unnest(tokens) t union all select url, nt, t from u, unnest(title_tokens) t),
    m as (select ct.course_id, ut.url, max(ct.nc) nc, max(ut.n) nu, count(*) hits from ct join ut using (t) group by 1, 2),
    s as (select m.course_id, m.url, max(2.0 * hits / nullif(nc + nu, 0)) sc from m group by 1, 2
          union all
          select c.course_id, u.url, 2.0 from c join u on length(c.code) >= 6 and position(c.code in lower(u.url)) > 0),
    best as (select s.course_id, s.url, max(s.sc) sc from s where not exists (select 1 from tried t where t.course_id = s.course_id and t.url = s.url) group by 1, 2),
    rk as (select b.*, row_number() over (partition by b.course_id order by b.sc desc, length(b.url)) n from best b)
    select c.course_id, r.provider_id, c.prev + 1,
           case when count(rk.url) = 0 then 'no_candidates' else 'ready' end,
           coalesce(jsonb_agg(jsonb_build_object('url', rk.url, 'title', left(coalesce(u.title, ''), 160)) order by rk.n) filter (where rk.url is not null), '[]'::jsonb)
      from c left join rk on rk.course_id = c.course_id and rk.n <= 25
      left join u on u.url = rk.url
     group by c.course_id, c.prev;
    get diagnostics v_n = row_count;
    v := v || jsonb_build_object('provider_id', r.provider_id, 'prepared', v_n);
  end loop;
  return v;
end $_$;


ALTER FUNCTION "security"."coverage_ai_match_prepare_v1"("p_providers" integer, "p_courses" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_apply_course_v1"("p_course_id" "uuid", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_url" "text", "p_hash" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c record; r jsonb; v_test uuid; v_key text; v_links int := 0; v_intakes int := 0; v_english int := 0; v_fees int := 0; v_cur text;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select co.id, co.provider_id, lower(coalesce(nullif(btrim(co.course_code), ''), co.id::text)) code, a.currency_code
    into c from catalogue.courses co join catalogue.providers p on p.id = co.provider_id
    join pipeline.coverage_admission_countries a on a.country_id = p.country_id and a.active
   where co.id = p_course_id;
  if c.id is null then raise exception 'course not found or its country has no admission rule'; end if;
  if security.layer4_entity_or_parent_blocked('course', p_course_id, 'operational') then raise exception 'course operationally blocked by Layer 4' using errcode = '42501'; end if;
  if p_source_id is null or p_evidence_id is null or coalesce(btrim(p_url), '') = '' or coalesce(btrim(p_hash), '') = '' then raise exception 'source, evidence, page and hash required'; end if;

  if nullif(btrim(p_payload->>'course_url'), '') is not null then
    insert into catalogue.course_links(course_id, link_type, url, audience, label, is_primary, status, source_id, evidence_id, confidence, last_verified_at, updated_at)
    values (p_course_id, 'official_course', btrim(p_payload->>'course_url'), 'international', 'Official provider course page', false, 'active', p_source_id, p_evidence_id, 1, now(), now())
    on conflict (course_id, link_type, url) do update set status = 'active', source_id = excluded.source_id, evidence_id = excluded.evidence_id,
           confidence = 1, last_verified_at = now(), updated_at = now();
    v_links := 1;
  end if;
  for r in select value from jsonb_array_elements(coalesce(p_payload->'intakes', '[]'::jsonb)) loop
    if nullif(btrim(r->>'intake_label'), '') is null then raise exception 'intake_label required'; end if;
    v_key := coalesce(nullif(r->>'source_intake_key', ''), c.code || ':' || coalesce(r->>'intake_year', 'current') || ':' || lower(r->>'intake_label'));
    insert into catalogue.course_intakes(course_id, intake_year, intake_label, start_date, status, source_id, evidence_id, confidence, source_intake_key)
    values (p_course_id, nullif(r->>'intake_year', '')::int, r->>'intake_label', nullif(r->>'start_date', '')::date, 'active', p_source_id, p_evidence_id, 1, v_key)
    on conflict (course_id, source_id, source_intake_key) where source_id is not null and source_intake_key is not null
    do update set intake_year = excluded.intake_year, intake_label = excluded.intake_label, start_date = excluded.start_date, status = 'active',
                  evidence_id = excluded.evidence_id, confidence = 1;
    v_intakes := v_intakes + 1;
  end loop;
  for r in select value from jsonb_array_elements(coalesce(p_payload->'english_requirements', '[]'::jsonb)) loop
    select id into v_test from ref.english_tests where code = upper(btrim(r->>'test_code')) limit 1;
    if v_test is null then raise exception 'english test not seeded: %', r->>'test_code'; end if;
    insert into catalogue.course_english_requirements(course_id, english_test_id, overall_score, component_scores, notes, source_id, evidence_id, confidence,
                                                      source_requirement_key, status, last_verified_at)
    values (p_course_id, v_test, nullif(r->>'overall_score', '')::numeric, coalesce(r->'component_scores', '{}'::jsonb), r->>'notes', p_source_id, p_evidence_id, 1,
            coalesce(nullif(r->>'source_requirement_key', ''), c.code || ':' || upper(btrim(r->>'test_code'))), 'active', now())
    on conflict (course_id, english_test_id) do update set overall_score = excluded.overall_score, component_scores = excluded.component_scores,
           notes = excluded.notes, source_id = excluded.source_id, evidence_id = excluded.evidence_id, confidence = 1,
           source_requirement_key = excluded.source_requirement_key, status = 'active', last_verified_at = now();
    v_english := v_english + 1;
  end loop;
  if p_payload ? 'fee_amount' then
    v_cur := coalesce(nullif(btrim(p_payload->>'currency_code'), ''), c.currency_code);
    if v_cur is distinct from c.currency_code then raise exception 'fee currency % does not match the country currency %', v_cur, c.currency_code; end if;
    if nullif(p_payload->>'fee_amount', '')::numeric is null or (p_payload->>'fee_amount')::numeric <= 0 then raise exception 'positive fee amount required'; end if;
    insert into catalogue.course_fees(course_id, fee_year, audience, fee_type, amount, currency_code, basis, notes, source_id, evidence_id, confidence,
                                      source_fee_key, status, last_verified_at, source_snapshot_at, updated_at)
    values (p_course_id, nullif(p_payload->>'fee_year', '')::int, 'international', 'provider_current_tuition', (p_payload->>'fee_amount')::numeric, v_cur,
            nullif(btrim(p_payload->>'fee_basis'), ''), p_payload->>'fee_notes', p_source_id, p_evidence_id, 1,
            c.code || ':international:' || coalesce(p_payload->>'fee_year', 'current') || ':' || coalesce(nullif(btrim(p_payload->>'fee_basis'), ''), 'tuition'),
            'active', now(), now(), now())
    on conflict (course_id, source_id, source_fee_key) where source_id is not null and source_fee_key is not null
    do update set amount = excluded.amount, currency_code = excluded.currency_code, basis = excluded.basis, fee_year = excluded.fee_year,
                  evidence_id = excluded.evidence_id, confidence = 1, status = 'active', last_verified_at = now(), source_snapshot_at = now(), updated_at = now();
    v_fees := 1;
  end if;
  return jsonb_build_object('course_id', p_course_id, 'links_applied', v_links, 'intakes_applied', v_intakes, 'english_applied', v_english, 'fees_applied', v_fees);
end $$;


ALTER FUNCTION "security"."coverage_apply_course_v1"("p_course_id" "uuid", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_url" "text", "p_hash" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_bind_tick_v1"("p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare r record; v jsonb:='[]'::jsonb;
begin
  for r in select provider_id from pipeline.coverage_provider_discovery
            where mapped_at is not null and (bound_at is null or bound_at<mapped_at) order by mapped_at limit greatest(1,least(p_limit,50)) loop
    v:=v||jsonb_build_object('provider_id',r.provider_id,'result',security.coverage_bind_v2(r.provider_id));
  end loop;
  return v;
end $$;


ALTER FUNCTION "security"."coverage_bind_tick_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_bind_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
declare v_bound int; v_amb int;
begin
  with c as (
    select co.id course_id, lower(co.course_code) code, security.coverage_text_tokens(co.canonical_title) tok
      from catalogue.courses co where co.provider_id=p_provider_id and co.lifecycle_status='active'),
  s as (
    select c.course_id, u.url,
           greatest(
             2.0*(select count(*) from unnest(c.tok) t where t=any(u.tokens))/nullif(cardinality(c.tok)+cardinality(u.tokens),0),
             2.0*(select count(*) from unnest(c.tok) t where t=any(u.title_tokens))/nullif(cardinality(c.tok)+cardinality(u.title_tokens),0)) sc0,
           c.code is not null and length(c.code)>=6 and (position(c.code in lower(u.url))>0 or position(c.code in lower(coalesce(u.title,'')))>0) by_code
      from c join pipeline.coverage_provider_urls u on u.provider_id=p_provider_id and (u.tokens && c.tok or u.title_tokens && c.tok
           or (c.code is not null and length(c.code)>=6 and (position(c.code in lower(u.url))>0 or position(c.code in lower(coalesce(u.title,'')))>0)))),
  s2 as (select course_id, url, case when by_code then 1.0 else coalesce(sc0,0) end sc, by_code from s),
  r as (select course_id, url, sc, by_code, row_number() over (partition by course_id order by sc desc, length(url)) rk,
               lead(sc) over (partition by course_id order by sc desc, length(url)) nxt from s2),
  best as (select course_id, url, sc, coalesce(nxt,0) nxt, by_code from r where rk=1 and sc>=0.6)
  insert into pipeline.coverage_course_pages(course_id,provider_id,url,score,runner_up,basis,status,bound_at,next_read_at)
  select course_id, p_provider_id, url, round(sc,3), round(nxt,3),
         case when by_code then 'cricos_code' else 'title_match' end,
         case when by_code or (sc>=0.8 and sc-nxt>=0.1) then 'bound' else 'ambiguous' end, now(), now()
    from best
  on conflict (course_id) do update set url=excluded.url, score=excluded.score, runner_up=excluded.runner_up, basis=excluded.basis,
         status=excluded.status, bound_at=now(), read_status=case when pipeline.coverage_course_pages.url is distinct from excluded.url then null else pipeline.coverage_course_pages.read_status end,
         next_read_at=case when pipeline.coverage_course_pages.url is distinct from excluded.url then now() else pipeline.coverage_course_pages.next_read_at end
   where not (pipeline.coverage_course_pages.status='bound' and excluded.status<>'bound');
  select count(*) filter (where status='bound'), count(*) filter (where status='ambiguous') into v_bound, v_amb from pipeline.coverage_course_pages where provider_id=p_provider_id;
  return jsonb_build_object('bound',v_bound,'ambiguous',v_amb);
end $$;


ALTER FUNCTION "security"."coverage_bind_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_bind_v2"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $_$
declare v_bound int; v_amb int;
begin
  drop table if exists _cb_c, _cb_u, _cb_s, _cb_best;
  create temp table _cb_c on commit drop as
    select co.id course_id, lower(co.course_code) code, security.coverage_text_tokens(co.canonical_title) tok
      from catalogue.courses co where co.provider_id=p_provider_id and co.lifecycle_status='active';
  create temp table _cb_u on commit drop as
    select url, title, tokens, title_tokens, cardinality(tokens) ns, cardinality(title_tokens) nt
      from pipeline.coverage_provider_urls where provider_id=p_provider_id
       and url !~* '/(inherent-requirements|entry-requirements|admission-requirements|english-requirements|fees?|tuition-fees?|scholarships?|apply|how-to-apply|applying|careers?|pathways?|credit|recognition-of-prior-learning|timetables?|news|events?|stories|blog|alumni|research|contact|faqs?)(/|$)';
  create temp table _cb_s on commit drop as
    with ct as (select course_id, cardinality(tok) nc, t from _cb_c, unnest(tok) t),
         ut as (select url, 's' k, ns n, t from _cb_u, unnest(tokens) t union all select url, 't', nt, t from _cb_u, unnest(title_tokens) t),
         m as (select ct.course_id, ut.url, ut.k, max(ct.nc) nc, max(ut.n) nu, count(*) hits from ct join ut using (t) group by 1,2,3)
    select course_id, url, max(2.0*hits/nullif(nc+nu,0)) sc, false by_code from m group by 1,2
    union all
    select c.course_id, u.url, 1.0, true from _cb_c c join _cb_u u
      on c.code is not null and length(c.code)>=6 and (position(c.code in lower(u.url))>0 or position(c.code in lower(coalesce(u.title,'')))>0);
  create temp table _cb_best on commit drop as
    with s as (select course_id, url, max(sc) sc, bool_or(by_code) by_code from _cb_s group by 1,2),
         rc as (select *, row_number() over (partition by course_id order by sc desc, length(url)) rk_c,
                          lead(sc) over (partition by course_id order by sc desc, length(url)) nxt_c,
                          row_number() over (partition by url order by sc desc) rk_u,
                          lead(sc) over (partition by url order by sc desc) nxt_u from s)
    select course_id, url, sc, coalesce(nxt_c,0) nxt, by_code,
           by_code or (sc>=0.8 and sc-coalesce(nxt_c,0)>=0.1 and rk_u=1 and sc-coalesce(nxt_u,0)>=0.1) or (sc>=0.999 and coalesce(nxt_c,0)<0.999 and rk_u=1 and coalesce(nxt_u,0)<0.999) mutual
      from rc where rk_c=1 and sc>=0.6;
  insert into pipeline.coverage_course_pages(course_id,provider_id,url,score,runner_up,basis,status,bound_at,next_read_at)
  select course_id, p_provider_id, url, round(sc,3), round(nxt,3), case when by_code then 'cricos_code' else 'title_match' end,
         case when mutual then 'bound' else 'ambiguous' end, now(), now()
    from _cb_best
  on conflict (course_id) do update set url=excluded.url, score=excluded.score, runner_up=excluded.runner_up, basis=excluded.basis,
         status=excluded.status, bound_at=now(),
         read_status=case when pipeline.coverage_course_pages.url is distinct from excluded.url then null else pipeline.coverage_course_pages.read_status end,
         next_read_at=case when pipeline.coverage_course_pages.url is distinct from excluded.url then now() else pipeline.coverage_course_pages.next_read_at end
   where (pipeline.coverage_course_pages.status not in ('mismatch') or pipeline.coverage_course_pages.url is distinct from excluded.url)
     and coalesce(pipeline.coverage_course_pages.basis,'') not in ('cricos_search','title_search','manual','ai_match');
  -- courses whose earlier binding no longer holds (page gone or no longer a mutual best) are released
  update pipeline.coverage_course_pages p set status='ambiguous'
   where p.provider_id=p_provider_id and p.status='bound' and coalesce(p.basis,'') not in ('cricos_search','title_search','manual','ai_match')
     and not exists(select 1 from _cb_best b where b.course_id=p.course_id and b.url=p.url and b.mutual);
  update pipeline.coverage_provider_discovery set bound_at=now() where provider_id=p_provider_id;
  select count(*) filter (where status='bound'), count(*) filter (where status='ambiguous') into v_bound, v_amb from pipeline.coverage_course_pages where provider_id=p_provider_id;
  return jsonb_build_object('bound',v_bound,'ambiguous',v_amb);
end $_$;


ALTER FUNCTION "security"."coverage_bind_v2"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_completeness_state"("p_state" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case p_state
    when 'admitted' then 'present'
    when 'not_on_page' then 'source_null'
    when 'missing_l1' then 'source_null'
    when 'candidate' then 'ambiguous'
    when 'awaiting_l3' then 'ambiguous'
    when 'in_review' then 'ambiguous'
    else 'not_yet_enriched' end
$$;


ALTER FUNCTION "security"."coverage_completeness_state"("p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_country"("p_provider_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select k.iso_alpha2::text from catalogue.providers p join ref.countries k on k.id = p.country_id where p.id = p_provider_id
$$;


