CREATE OR REPLACE FUNCTION "security"."coverage_fetch_area_v1"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_country text := upper(coalesce(p_args->>'country', ''));
  v_type text := coalesce(nullif(p_args->>'scope_type', ''), 'country'); v_id uuid := nullif(p_args->>'scope_id', '')::uuid;
  v_q text := lower(nullif(btrim(coalesce(p_args->>'query', '')), '')); v_off int := greatest(coalesce((p_args->>'offset')::int, 0), 0);
  v_kind text; v_target uuid; v_label text; n_pin int := 0; n_new int := 0; n_site int := 0; n_map int := 0; n_search int := 0; n_read int := 0; v_items jsonb; v_total int;
begin
  if auth.uid() is null or v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
  if p_action = 'options' then
    return jsonb_build_object('countries', coalesce((select jsonb_agg(jsonb_build_object('code', x.code, 'name', x.name, 'providers', x.pn, 'courses', x.cn) order by x.cn desc) from (
      select k.iso_alpha2::text code, k.name, count(distinct c.provider_id) pn, count(*) cn
        from catalogue.courses c join catalogue.providers p on p.id = c.provider_id join ref.countries k on k.id = p.country_id
       where c.lifecycle_status = 'active' group by 1, 2) x), '[]'::jsonb));
  end if;
  if v_country !~ '^[A-Z]{2}$' then raise exception 'choose a country'; end if;
  if v_type not in ('country','state','university') then raise exception 'choose a country, state or university'; end if;
  if v_type <> 'country' and v_id is null and p_action in ('preview','start') then raise exception 'choose a %', case v_type when 'state' then 'state' else 'university' end; end if;
  if p_action = 'scope_page' then
    if coalesce(p_args->>'kind', '') = 'state' then
      select coalesce(jsonb_agg(jsonb_build_object('value', q.id, 'label', q.name, 'meta', q.code) order by lower(q.name)), '[]'::jsonb), max(q.total)
        into v_items, v_total
        from (select sd.id, sd.name, sd.code, count(*) over () total from ref.subdivisions sd join ref.countries k on k.id = sd.country_id
               where k.iso_alpha2 = v_country and (v_q is null or lower(sd.name || ' ' || coalesce(sd.code, '')) like '%' || v_q || '%')
                 and exists (select 1 from catalogue.providers p where p.subdivision_id = sd.id
                              and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active'))
               order by lower(sd.name) limit 10 offset v_off) q;
    else
      select coalesce(jsonb_agg(jsonb_build_object('value', q.id, 'label', q.name,
               'meta', q.courses || ' courses · ' || case when q.dstatus = 'mapped' then 'site found, ' || q.read_pages || ' pages read'
                                                          when q.dstatus = 'no_website' then 'no website found yet'
                                                          when q.dstatus = 'failed' then 'site map failed'
                                                          when q.dstatus = 'pending' then 'site waiting to be mapped'
                                                          else 'not in the sweep yet' end) order by lower(q.name)), '[]'::jsonb), max(q.total)
        into v_items, v_total
        from (select p.id, coalesce(p.display_name, p.canonical_name) name, count(*) over () total,
                     (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active') courses,
                     (select d.status from pipeline.coverage_provider_discovery d where d.provider_id = p.id) dstatus,
                     (select count(*) from pipeline.coverage_course_pages g where g.provider_id = p.id and g.read_status = 'read') read_pages
                from catalogue.providers p join security.coverage_scope_providers(v_country, case when nullif(p_args->>'state_id', '') is null then 'country' else 'state' end, nullif(p_args->>'state_id', '')::uuid) s on s.provider_id = p.id
               where v_q is null or lower(coalesce(p.display_name, '') || ' ' || p.canonical_name) like '%' || v_q || '%'
               order by lower(coalesce(p.display_name, p.canonical_name)) limit 10 offset v_off) q;
    end if;
    return jsonb_build_object('items', v_items, 'total', coalesce(v_total, 0), 'offset', v_off, 'has_more', v_off + jsonb_array_length(v_items) < coalesce(v_total, 0));
  end if;
  if p_action = 'preview' then
    return security.coverage_scope_summary(v_country, v_type, v_id) || jsonb_build_object('country', v_country, 'scope_type', v_type, 'scope_id', v_id);
  end if;
  if p_action <> 'start' then raise exception 'unknown action'; end if;

  -- 1. first in the sweep: the same priority pins as Scheduled jobs › Priority
  v_kind := case v_type when 'university' then 'provider' else v_type end;
  v_target := case when v_type = 'country' then (select k.id from ref.countries k where k.iso_alpha2 = v_country) else v_id end;
  v_label := security.priority_pin_label(v_kind, v_target)->>'label';
  if v_label is null then raise exception 'not found'; end if;
  insert into pipeline.priority_pins(kind, target_id, sort, note, created_by)
  values (v_kind, v_target, coalesce((select min(sort) from pipeline.priority_pins), 1) - 1, 'Fetch an area', auth.uid())
  on conflict (kind, target_id) do update set sort = (select min(sort) from pipeline.priority_pins) - 1;
  get diagnostics n_pin = row_count;
  perform security.provider_priority_refresh_v1();
  -- 2. providers not yet in the sweep join it
  insert into pipeline.coverage_provider_discovery(provider_id, website, status, attempts, updated_at)
  select p.id, nullif(btrim(p.website), ''), case when nullif(btrim(p.website), '') is null then 'no_website' else 'pending' end, 0, now()
    from catalogue.providers p join security.coverage_scope_providers(v_country, v_type, v_id) s on s.provider_id = p.id
  on conflict (provider_id) do nothing;
  get diagnostics n_new = row_count;
  -- 3. site search again where the site was not found; failed site maps retried
  update pipeline.coverage_provider_discovery d set site_searched_at = null, leased_until = null, updated_at = now()
    from security.coverage_scope_providers(v_country, v_type, v_id) s
   where d.provider_id = s.provider_id and d.status = 'no_website' and d.site_searched_at is not null;
  get diagnostics n_site = row_count;
  update pipeline.coverage_provider_discovery d set status = 'pending', attempts = 0, next_due_at = null, last_error = null, leased_until = null, updated_at = now()
    from security.coverage_scope_providers(v_country, v_type, v_id) s
   where d.provider_id = s.provider_id and d.status = 'failed';
  get diagnostics n_map = row_count;
  -- 4. a page search for active courses with no page (a search that found nothing is repeated only after 7 days)
  insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at)
  select c.id, c.provider_id, case when c.course_code ~ '^[0-9]{6}[0-9A-Z]$' then 'cricos' else 'title' end, 'queued', now()
    from catalogue.courses c join security.coverage_scope_providers(v_country, v_type, v_id) s on s.provider_id = c.provider_id
   where c.lifecycle_status = 'active'
     and exists (select 1 from pipeline.course_link_recipes r where r.provider_id = c.provider_id and r.active)
     and not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c.id and g.status <> 'mismatch')
  on conflict (course_id) do update set state = 'queued', stage = excluded.stage, queued_at = now(), sent_at = null, done_at = null
   where pipeline.course_link_search.state = 'none' and coalesce(pipeline.course_link_search.done_at, pipeline.course_link_search.queued_at) < now() - interval '7 days';
  get diagnostics n_search = row_count;
  -- 5. found pages not yet read are read now
  update pipeline.coverage_course_pages g set next_read_at = now(), read_attempts = 0
    from security.coverage_scope_providers(v_country, v_type, v_id) s
   where g.provider_id = s.provider_id and g.status in ('bound','ambiguous') and g.read_status is distinct from 'read'
     and coalesce(g.leased_until, '-infinity') < now();
  get diagnostics n_read = row_count;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fetch_area', 'start', v_label, p_args || jsonb_build_object('pinned', n_pin, 'joined', n_new, 'site_search_again', n_site, 'site_map_retry', n_map,
          'page_searches_queued', n_search, 'pages_to_read_now', n_read), auth.uid());
  return security.coverage_scope_summary(v_country, v_type, v_id) || jsonb_build_object('country', v_country, 'scope_type', v_type, 'scope_id', v_id, 'label', v_label,
    'started', jsonb_build_object('joined', n_new, 'site_search_again', n_site, 'site_map_retry', n_map, 'page_searches_queued', n_search, 'pages_to_read_now', n_read));
end $_$;


ALTER FUNCTION "security"."coverage_fetch_area_v1"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_identity_allowed"("p_provider_id" "uuid", "p_basis" "text", "p_attr" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when p_basis in ('adapter_code', 'adapter_title')
                   and not exists (select 1 from pipeline.uni_adapters u where u.provider_id = p_provider_id and u.enabled and u.admit and (p_attr is null or p_attr not in ('intakes', 'english', 'tuition') or (case p_attr when 'tuition' then 'fee' else p_attr end) = any (u.admit_fields))) then false
         else coalesce((
    select case when p_attr is null
                then exists (select 1 from jsonb_each(a.identities) e, jsonb_array_elements_text(e.value) b where b = p_basis)
                else coalesce(a.identities->p_attr ? p_basis, false) end
      from catalogue.providers p join pipeline.coverage_admission_countries a on a.country_id = p.country_id and a.active
     where p.id = p_provider_id), false) end
$$;


ALTER FUNCTION "security"."coverage_identity_allowed"("p_provider_id" "uuid", "p_basis" "text", "p_attr" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_norm_url"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select rtrim(regexp_replace(regexp_replace(lower(coalesce(p,'')),'^https?://(www\.)?',''),'[?#].*$',''),'/')
$_$;


ALTER FUNCTION "security"."coverage_norm_url"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_page_refused_host_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status in ('bound', 'ambiguous') and security.refused_host(new.url)
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field = 'official_url') then
    new.status := 'mismatch'; new.read_status := 'refused_host'; new.identity_basis := null; new.next_read_at := null;
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."coverage_page_refused_host_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_scope_providers"("p_country" "text", "p_type" "text", "p_id" "uuid") RETURNS TABLE("provider_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p.id from catalogue.providers p join ref.countries k on k.id = p.country_id
   where k.iso_alpha2 = upper(p_country)
     and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
     and case coalesce(p_type, 'country')
           when 'country' then true
           when 'university' then p.id = p_id
           when 'state' then p.subdivision_id = p_id or exists (
             select 1 from catalogue.courses c join catalogue.course_campuses cc on cc.course_id = c.id
               join catalogue.campuses cam on cam.id = cc.campus_id
              where c.provider_id = p.id and c.lifecycle_status = 'active' and cam.subdivision_id = p_id)
           else false end
$$;


ALTER FUNCTION "security"."coverage_scope_providers"("p_country" "text", "p_type" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_scope_summary"("p_country" "text", "p_type" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with sp as (select provider_id from security.coverage_scope_providers(p_country, p_type, p_id)),
  co as (select c.id, c.provider_id from catalogue.courses c join sp on sp.provider_id = c.provider_id where c.lifecycle_status = 'active'),
  di as (select d.* from pipeline.coverage_provider_discovery d join sp on sp.provider_id = d.provider_id),
  pg as (select g.* from pipeline.coverage_course_pages g join co on co.id = g.course_id),
  cv as (select a.attribute, count(*) filter (where a.state = 'admitted') n from pipeline.course_attribute_coverage a join co on co.id = a.course_id
          where a.attribute in ('official_url','english','intakes','provider_tuition') group by 1)
  select jsonb_build_object(
    'providers', (select count(*) from sp),
    'courses', (select count(*) from co),
    'sites', jsonb_build_object(
       'known', (select count(*) from di where di.status in ('mapped','pending') and di.website is not null),
       'mapped', (select count(*) from di where di.status = 'mapped'),
       'not_found', (select count(*) from di where di.status = 'no_website' and di.site_searched_at is not null),
       'to_search', (select count(*) from di where di.status = 'no_website' and di.site_searched_at is null),
       'failed', (select count(*) from di where di.status = 'failed'),
       'not_queued', (select count(*) from sp where not exists (select 1 from di where di.provider_id = sp.provider_id))),
    'pages', jsonb_build_object(
       'found', (select count(*) from pg where pg.status in ('bound','ambiguous')),
       'read', (select count(*) from pg where pg.read_status = 'read'),
       'to_read', (select count(*) from pg where pg.status in ('bound','ambiguous') and pg.read_status is distinct from 'read'),
       'not_this_course', (select count(*) from pg where pg.status = 'mismatch'),
       'no_page', (select count(*) from co where not exists (select 1 from pg where pg.course_id = co.id))),
    'searches_waiting', (select count(*) from pipeline.course_link_search s join co on co.id = s.course_id where s.state in ('queued','sent')),
    'facts', coalesce((select jsonb_object_agg(attribute, n) from cv), '{}'::jsonb),
    'facts_built_at', (select max(computed_at) from pipeline.course_attribute_coverage),
    'first_in_sweep', exists (select 1 from pipeline.priority_pins x where x.kind = case coalesce(p_type,'country') when 'university' then 'provider' else coalesce(p_type,'country') end
                               and x.target_id = case when coalesce(p_type,'country') = 'country' then (select k.id from ref.countries k where k.iso_alpha2 = upper(p_country)) else p_id end))
$$;


ALTER FUNCTION "security"."coverage_scope_summary"("p_country" "text", "p_type" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_slug"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select coalesce((regexp_match(regexp_replace(regexp_replace(p_url,'[?#].*$',''),'/+$',''),'/([^/]+)$'))[1],'')
$_$;


ALTER FUNCTION "security"."coverage_slug"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_sweep_source"("p_provider_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline'
    AS $$
declare v uuid;
begin
  select id into v from pipeline.sources where source_type='provider_course_page_sweep' and provider_id=p_provider_id limit 1;
  if v is null then
    insert into pipeline.sources(source_type,system_id,provider_id,country_id,url,label,trust_rank,status,metadata)
    select 'provider_course_page_sweep', s.system_id, p.id, p.country_id, p.website,
           coalesce(p.display_name,p.canonical_name)||' course pages (coverage sweep)', 80, 'active',
           jsonb_build_object('facts',jsonb_build_array('official_course_url','international_fee','english_requirement','intake'),'decision','CF-247 complete coverage','admission','not admitted: candidates only')
      from catalogue.providers p cross join lateral (select system_id from pipeline.sources where source_type='provider_course_page' limit 1) s
     where p.id=p_provider_id returning id into v;
  end if;
  return v;
end $$;


ALTER FUNCTION "security"."coverage_sweep_source"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_text_tokens"("p" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(array_agg(distinct t),'{}') from unnest(regexp_split_to_array(lower(coalesce(p,'')),'[^a-z0-9]+')) t
   where length(t)>1 and t not in ('of','and','in','the','with','for','www','html','htm','php','aspx','au','edu','com','study','course','courses',
     'program','programs','programme','international','students','student','detail','details','index','overview','home')
$$;


ALTER FUNCTION "security"."coverage_text_tokens"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_tuition_target_v1"("p_fee" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  with c as (
    select x, row_number() over (order by (x->>'score')::numeric desc nulls last, (x->>'amount')::numeric desc) rk
      from jsonb_array_elements(coalesce(p_fee->'candidates','[]'::jsonb)) x
     where coalesce((x->>'international')::boolean,false) and not coalesce((x->>'domestic')::boolean,false)
       and not coalesce((x->>'total')::boolean,false) and (x->>'amount')::numeric > 0
       and ((p_fee->>'value') is null or (x->>'amount')::numeric=(p_fee->>'value')::numeric))
  select case when p_fee->>'basis'='total' then null else
         (select jsonb_build_object('amount',(x->>'amount')::numeric,'currency_code','AUD',
                   'basis',case when p_fee->>'basis'='annual' or coalesce((x->>'annualLocal')::boolean,false) then 'annual' else 'annual_or_indicative_requires_validation' end,
                   'fee_year',nullif(x->>'fee_year','')::int,'audience','international')
            from c where rk=1) end
$$;


ALTER FUNCTION "security"."coverage_tuition_target_v1"("p_fee" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."current_role_rank"() RETURNS smallint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'security', 'auth'
    AS $$
select coalesce(max(r.rank),0)::smallint
from security.user_roles ur join security.roles r on r.code=ur.role_code
where ur.user_id=auth.uid() and (ur.expires_at is null or ur.expires_at>now()) and r.status='active'
$$;


ALTER FUNCTION "security"."current_role_rank"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_campus_base"("p_country_code" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "entity_name" "text", "stable_key" "text", "provider_id" "uuid", "provider_name" "text", "country_code" "text", "source_id" "uuid", "evidence_id" "uuid", "last_verified_at" timestamp with time zone, "updated_at" timestamp with time zone, "publication_status" "text", "identity_ok" boolean, "geography_present" boolean, "evidence_count" integer, "channel_state_count" integer, "channel_published_count" integer, "channel_rejected_count" integer, "channel_distinct_status_count" integer, "review_domains" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'pipeline', 'workflow', 'publishing', 'auth'
    AS $$
with scope as (
 select ca.*,co.iso_alpha2::text country_code,coalesce(p.display_name,p.canonical_name) provider_name
 from catalogue.campuses ca join catalogue.providers p on p.id=ca.provider_id join ref.countries co on co.id=ca.country_id
 where (p_country_code is null and co.iso_alpha2 in ('AU','NZ')) or (p_country_code is not null and co.iso_alpha2=upper(p_country_code))
), ev as (
 select el.entity_id,count(distinct el.evidence_id)::int evidence_count,(array_agg(el.evidence_id order by el.updated_at desc))[1] evidence_id
 from pipeline.evidence_entity_links el join scope s on s.id=el.entity_id where el.entity_type='campus' group by el.entity_id
), pub as (
 select es.entity_id,count(*)::int state_count,count(*) filter(where lower(es.publication_status)='published')::int published_count,
 count(*) filter(where lower(es.publication_status)='rejected')::int rejected_count,count(distinct lower(es.publication_status))::int distinct_status_count
 from publishing.entity_states es join scope s on s.id=es.entity_id group by es.entity_id
), rev as (
 select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) review_domains
 from workflow.review_queue q join scope s on s.id=q.entity_id group by q.entity_id
)
select s.id,s.name,s.stable_key,s.provider_id,s.provider_name,s.country_code,s.source_id,coalesce(s.evidence_id,ev.evidence_id),s.last_verified_at,s.updated_at,s.publication_status,
 (s.stable_key is not null and btrim(s.stable_key)<>'' and s.name is not null and btrim(s.name)<>'' and s.provider_id is not null and s.country_id is not null),
 (s.subdivision_id is not null or coalesce(nullif(btrim(s.city),''),null) is not null or coalesce(nullif(btrim(s.address_line1),''),null) is not null or (s.latitude is not null and s.longitude is not null)),
 coalesce(ev.evidence_count,case when s.evidence_id is not null then 1 else 0 end),coalesce(pub.state_count,0),coalesce(pub.published_count,0),coalesce(pub.rejected_count,0),coalesce(pub.distinct_status_count,0),coalesce(rev.review_domains,'{}'::text[])
from scope s left join ev on ev.entity_id=s.id left join pub on pub.entity_id=s.id left join rev on rev.entity_id=s.id
$$;


ALTER FUNCTION "security"."data_quality_campus_base"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_course_base"("p_country_code" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "entity_name" "text", "stable_key" "text", "provider_id" "uuid", "provider_name" "text", "country_code" "text", "source_id" "uuid", "evidence_id" "uuid", "last_verified_at" timestamp with time zone, "updated_at" timestamp with time zone, "publication_status" "text", "identity_ok" boolean, "registration_count" integer, "campus_count" integer, "has_delivery" boolean, "taxonomy_complete" boolean, "taxonomy_ambiguous" boolean, "taxonomy_rejected" boolean, "reg_fee_count" integer, "reg_fee_value_count" integer, "reg_fee_zero_count" integer, "reg_fee_positive_count" integer, "reg_fee_source_id" "uuid", "reg_fee_evidence_id" "uuid", "provider_fee_count" integer, "provider_fee_value_count" integer, "provider_fee_zero_count" integer, "provider_fee_positive_count" integer, "provider_fee_suppressed" boolean, "provider_fee_rejected" boolean, "provider_fee_source_id" "uuid", "provider_fee_evidence_id" "uuid", "has_url" boolean, "url_suppressed" boolean, "url_rejected" boolean, "url_source_id" "uuid", "url_evidence_id" "uuid", "intake_count" integer, "intake_suppressed" boolean, "intake_rejected" boolean, "intake_source_id" "uuid", "intake_evidence_id" "uuid", "english_count" integer, "english_suppressed" boolean, "english_rejected" boolean, "english_source_id" "uuid", "english_evidence_id" "uuid", "scholarship_include_count" integer, "scholarship_exclude_count" integer, "evidence_count" integer, "search_projected" boolean, "search_status" "text", "channel_state_count" integer, "channel_published_count" integer, "channel_rejected_count" integer, "channel_distinct_status_count" integer, "review_domains" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'scholarship', 'pipeline', 'workflow', 'search', 'publishing', 'auth'
    AS $$
with scope as materialized (
  select c.id,c.provider_id,c.stable_key,c.canonical_title,c.display_title,c.course_code,c.course_url,c.delivery_mode,
    c.study_level_id,c.primary_field_id,c.canonical_source_id,c.last_verified_at,c.updated_at,c.publication_status,
    co.iso_alpha2::text as country_code,coalesce(p.display_name,p.canonical_name) as provider_name
  from catalogue.courses c
  join catalogue.providers p on p.id=c.provider_id
  join ref.countries co on co.id=p.country_id
  where (p_country_code is null and co.iso_alpha2 in ('AU','NZ'))
     or (p_country_code is not null and co.iso_alpha2=upper(p_country_code))
), reg as (
  select r.course_id,
    count(*) filter(where coalesce(r.status,'active')='active')::int active_count,
    (array_agg(r.source_id order by r.valid_from desc nulls last,r.id) filter(where r.source_id is not null))[1] source_id,
    (array_agg(r.evidence_id order by r.valid_from desc nulls last,r.id) filter(where r.evidence_id is not null))[1] evidence_id
  from catalogue.course_registrations r join scope s on s.id=r.course_id group by r.course_id
), campus as (
  select cc.course_id,count(*)::int campus_count,
    bool_or(coalesce(nullif(btrim(cc.delivery_mode),''),null) is not null) has_delivery,
    (array_agg(cc.source_id order by cc.is_primary desc,cc.campus_id) filter(where cc.source_id is not null))[1] source_id,
    (array_agg(cc.evidence_id order by cc.is_primary desc,cc.campus_id) filter(where cc.evidence_id is not null))[1] evidence_id
  from catalogue.course_campuses cc join scope s on s.id=cc.course_id group by cc.course_id
), tax as (
  select o.course_id,
    bool_or(lower(o.mapping_status) in ('review_required','ambiguous')) filter(where o.status='current') ambiguous,
    bool_or(lower(o.mapping_status)='rejected') filter(where o.status='current') rejected
  from catalogue.course_study_level_observations o join scope s on s.id=o.course_id group by o.course_id
), fee as (
  select f.course_id,
    count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active')::int reg_count,
    count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount is not null)::int reg_values,
    count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount=0)::int reg_zero,
    count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount>0)::int reg_positive,
    (array_agg(f.source_id order by f.source_snapshot_at desc nulls last,f.created_at desc) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and f.source_id is not null))[1] reg_source_id,
    (array_agg(f.evidence_id order by f.source_snapshot_at desc nulls last,f.created_at desc) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and f.evidence_id is not null))[1] reg_evidence_id,
    count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active')::int provider_count,
    count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount is not null)::int provider_values,
    count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount=0)::int provider_zero,
    count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount>0)::int provider_positive,
    bool_or(lower(coalesce(f.status,''))='suppressed') filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course') provider_suppressed,
    bool_or(lower(coalesce(f.status,''))='rejected') filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course') provider_rejected,
    (array_agg(f.source_id order by f.source_snapshot_at desc nulls last,f.created_at desc) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and f.source_id is not null))[1] provider_source_id,
    (array_agg(f.evidence_id order by f.source_snapshot_at desc nulls last,f.created_at desc) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and f.evidence_id is not null))[1] provider_evidence_id
  from catalogue.course_fees f join scope s on s.id=f.course_id group by f.course_id
), link as (
  select l.course_id,
    count(*) filter(where lower(coalesce(l.status,'active'))='active')::int active_count,
    bool_or(lower(coalesce(l.status,''))='suppressed') suppressed,
    bool_or(lower(coalesce(l.status,''))='rejected') rejected,
    (array_agg(l.source_id order by l.is_primary desc,l.updated_at desc) filter(where l.source_id is not null))[1] source_id,
    (array_agg(l.evidence_id order by l.is_primary desc,l.updated_at desc) filter(where l.evidence_id is not null))[1] evidence_id
  from catalogue.course_links l join scope s on s.id=l.course_id where l.link_type = 'official_course' group by l.course_id
), intake as (
  select i.course_id,count(*) filter(where lower(coalesce(i.status,'active'))='active')::int active_count,
    bool_or(lower(coalesce(i.status,''))='suppressed') suppressed,
    bool_or(lower(coalesce(i.status,''))='rejected') rejected,
    (array_agg(i.source_id order by i.intake_year desc nulls last,i.start_date desc nulls last,i.id) filter(where i.source_id is not null))[1] source_id,
    (array_agg(i.evidence_id order by i.intake_year desc nulls last,i.start_date desc nulls last,i.id) filter(where i.evidence_id is not null))[1] evidence_id
  from catalogue.course_intakes i join scope s on s.id=i.course_id group by i.course_id
), english as (
  select e.course_id,count(*) filter(where lower(coalesce(e.status,'active'))='active')::int active_count,
    bool_or(lower(coalesce(e.status,''))='suppressed') suppressed,
    bool_or(lower(coalesce(e.status,''))='rejected') rejected,
    (array_agg(e.source_id order by e.last_verified_at desc nulls last,e.id) filter(where e.source_id is not null))[1] source_id,
    (array_agg(e.evidence_id order by e.last_verified_at desc nulls last,e.id) filter(where e.evidence_id is not null))[1] evidence_id
  from catalogue.course_english_requirements e join scope s on s.id=e.course_id group by e.course_id
), sch_course as (
  select sc.course_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int include_count,
    count(*) filter(where coalesce(sc.include_exclude,'include')='exclude')::int exclude_count
  from scholarship.scopes sc join scope s on s.id=sc.course_id where sc.course_id is not null group by sc.course_id
), sch_provider as (
  select sc.provider_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int include_count,
    count(*) filter(where coalesce(sc.include_exclude,'include')='exclude')::int exclude_count
  from scholarship.scopes sc join (select distinct provider_id from scope) p on p.provider_id=sc.provider_id
  where sc.scope_type='provider' and sc.provider_id is not null group by sc.provider_id
), ev as (
  select el.entity_id,count(distinct el.evidence_id)::int evidence_count,
    (array_agg(el.evidence_id order by el.updated_at desc))[1] evidence_id
  from pipeline.evidence_entity_links el join scope s on s.id=el.entity_id
  where el.entity_type='course' group by el.entity_id
), pub as (
  select es.entity_id,count(*)::int state_count,
    count(*) filter(where lower(es.publication_status)='published')::int published_count,
    count(*) filter(where lower(es.publication_status)='rejected')::int rejected_count,
    count(distinct lower(es.publication_status))::int distinct_status_count
  from publishing.entity_states es join scope s on s.id=es.entity_id group by es.entity_id
), rev as (
  select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) review_domains
  from workflow.review_queue q join scope s on s.id=q.entity_id group by q.entity_id
)
select s.id,coalesce(s.display_title,s.canonical_title),s.stable_key,s.provider_id,s.provider_name,s.country_code,
  coalesce(s.canonical_source_id,reg.source_id),coalesce(ev.evidence_id,reg.evidence_id),s.last_verified_at,s.updated_at,s.publication_status,
  (s.stable_key is not null and btrim(s.stable_key)<>'' and s.canonical_title is not null and btrim(s.canonical_title)<>'' and s.course_code is not null and btrim(s.course_code)<>'' and s.provider_id is not null),
  coalesce(reg.active_count,0),coalesce(campus.campus_count,0),coalesce(campus.has_delivery,false) or coalesce(nullif(btrim(s.delivery_mode),''),null) is not null,
  (s.study_level_id is not null and s.primary_field_id is not null),coalesce(tax.ambiguous,false),coalesce(tax.rejected,false),
  coalesce(fee.reg_count,0),coalesce(fee.reg_values,0),coalesce(fee.reg_zero,0),coalesce(fee.reg_positive,0),fee.reg_source_id,fee.reg_evidence_id,
  coalesce(fee.provider_count,0),coalesce(fee.provider_values,0),coalesce(fee.provider_zero,0),coalesce(fee.provider_positive,0),coalesce(fee.provider_suppressed,false),coalesce(fee.provider_rejected,false),fee.provider_source_id,fee.provider_evidence_id,
  (coalesce(nullif(btrim(s.course_url),''),null) is not null or coalesce(link.active_count,0)>0),coalesce(link.suppressed,false),coalesce(link.rejected,false),coalesce(link.source_id,s.canonical_source_id),coalesce(link.evidence_id,ev.evidence_id),
  coalesce(intake.active_count,0),coalesce(intake.suppressed,false),coalesce(intake.rejected,false),intake.source_id,intake.evidence_id,
  coalesce(english.active_count,0),coalesce(english.suppressed,false),coalesce(english.rejected,false),english.source_id,english.evidence_id,
  coalesce(sch_course.include_count,0)+coalesce(sch_provider.include_count,0),coalesce(sch_course.exclude_count,0)+coalesce(sch_provider.exclude_count,0),coalesce(ev.evidence_count,0),
  (d.course_id is not null),d.publication_status,
  coalesce(pub.state_count,0),coalesce(pub.published_count,0),coalesce(pub.rejected_count,0),coalesce(pub.distinct_status_count,0),
  coalesce(rev.review_domains,'{}'::text[])
from scope s
left join reg on reg.course_id=s.id
left join campus on campus.course_id=s.id
left join tax on tax.course_id=s.id
left join fee on fee.course_id=s.id
left join link on link.course_id=s.id
left join intake on intake.course_id=s.id
left join english on english.course_id=s.id
left join sch_course on sch_course.course_id=s.id
left join sch_provider on sch_provider.provider_id=s.provider_id
left join ev on ev.entity_id=s.id
left join search.course_documents d on d.course_id=s.id
left join pub on pub.entity_id=s.id
left join rev on rev.entity_id=s.id
$$;


ALTER FUNCTION "security"."data_quality_course_base"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_exceptions_impl"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'scholarship', 'pipeline', 'workflow', 'search', 'publishing'
    SET "work_mem" TO '128MB'
    AS $$
declare
 v_entity text:=lower(coalesce(nullif(p_args->>'entity_type',''),'course'));
 v_domain text:=lower(coalesce(nullif(p_args->>'domain',''),'identity_completeness'));
 v_state text:=lower(nullif(p_args->>'state',''));
 v_country text:=nullif(upper(btrim(coalesce(p_args->>'country_code',''))),'');
 v_query text:=nullif(btrim(coalesce(p_args->>'query','')),'');
 v_limit int:=least(greatest(coalesce(nullif(p_args->>'limit','')::int,50),1),200);
 v_offset int:=greatest(coalesce(nullif(p_args->>'offset','')::int,0),0);
 v_result jsonb;
begin
 if v_entity='course' then
  with scope as (
   select c.id,coalesce(c.display_title,c.canonical_title) entity_name,c.stable_key,c.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,
    co.iso_alpha2::text country_code,c.canonical_source_id,c.last_verified_at,c.updated_at,c.publication_status,c.course_code,c.course_url,c.delivery_mode,c.study_level_id,c.primary_field_id
   from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
   where (v_country is null and co.iso_alpha2 in ('AU','NZ') or v_country is not null and co.iso_alpha2=v_country)
    and (v_query is null or c.canonical_title ilike '%'||v_query||'%' or coalesce(c.display_title,'') ilike '%'||v_query||'%' or coalesce(p.display_name,p.canonical_name,'') ilike '%'||v_query||'%' or c.stable_key ilike '%'||v_query||'%' or coalesce(c.course_code,'') ilike '%'||v_query||'%')
  ), classified as (
   select c.*,
    case v_domain
     when 'identity_completeness' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when c.stable_key is not null and btrim(c.stable_key)<>'' and c.entity_name is not null and btrim(c.entity_name)<>'' and c.course_code is not null and btrim(c.course_code)<>'' and c.provider_id is not null then 'present' else 'source_null' end
     when 'regulatory_completeness' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from catalogue.course_registrations r where r.course_id=c.id and coalesce(r.status,'active')='active') then 'present' else 'source_null' end
     when 'geography_delivery' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.id) and (coalesce(nullif(btrim(c.delivery_mode),''),null) is not null or exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.id and coalesce(nullif(btrim(cc.delivery_mode),''),null) is not null)) then 'present'
      when c.country_code='AU' and not exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.id) then 'source_null' else 'not_yet_enriched' end
     when 'taxonomy' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) or exists(select 1 from catalogue.course_study_level_observations o where o.course_id=c.id and o.status='current' and lower(o.mapping_status) in ('review_required','ambiguous')) then 'ambiguous'
      when exists(select 1 from catalogue.course_study_level_observations o where o.course_id=c.id and o.status='current' and lower(o.mapping_status)='rejected') then 'rejected'
      when c.study_level_id is not null and c.primary_field_id is not null then 'present' when c.country_code='AU' then 'source_null' else 'not_yet_enriched' end
     when 'regulatory_fee' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when c.country_code<>'AU' then 'not_applicable'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount>0) then 'present'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount=0) then 'zero'
      else 'source_null' end
     when 'provider_current_fee' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount>0) then 'present'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount=0) then 'zero'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount is null) then 'source_null'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and lower(coalesce(f.status,''))='rejected') then 'rejected'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and lower(coalesce(f.status,''))='suppressed') then 'suppressed'
      else 'not_yet_enriched' end
     when 'course_url' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when coalesce(nullif(btrim(c.course_url),''),null) is not null or exists(select 1 from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=c.id and lower(coalesce(l.status,'active'))='active') then 'present'
      when exists(select 1 from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=c.id and lower(coalesce(l.status,''))='rejected') then 'rejected'
      when exists(select 1 from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=c.id and lower(coalesce(l.status,''))='suppressed') then 'suppressed'
      else 'not_yet_enriched' end
     when 'intake' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from catalogue.course_intakes i where i.course_id=c.id and lower(coalesce(i.status,'active'))='active') then 'present'
      when exists(select 1 from catalogue.course_intakes i where i.course_id=c.id and lower(coalesce(i.status,''))='rejected') then 'rejected'
      when exists(select 1 from catalogue.course_intakes i where i.course_id=c.id and lower(coalesce(i.status,''))='suppressed') then 'suppressed'
      else 'not_yet_enriched' end
     when 'english_requirement' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from catalogue.course_english_requirements e where e.course_id=c.id and lower(coalesce(e.status,'active'))='active') then 'present'
      when exists(select 1 from catalogue.course_english_requirements e where e.course_id=c.id and lower(coalesce(e.status,''))='rejected') then 'rejected'
      when exists(select 1 from catalogue.course_english_requirements e where e.course_id=c.id and lower(coalesce(e.status,''))='suppressed') then 'suppressed'
      else 'not_yet_enriched' end
     when 'scholarship' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from scholarship.scopes s where coalesce(s.include_exclude,'include')='include' and (s.course_id=c.id or (s.scope_type='provider' and s.provider_id=c.provider_id))) then 'present'
      when exists(select 1 from scholarship.scopes s where coalesce(s.include_exclude,'include')='exclude' and (s.course_id=c.id or (s.scope_type='provider' and s.provider_id=c.provider_id))) then 'not_applicable'
      else 'not_yet_enriched' end
     when 'evidence' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from pipeline.evidence_entity_links el where el.entity_type='course' and el.entity_id=c.id) then 'present' else 'not_yet_enriched' end
     when 'verification_freshness' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when c.last_verified_at is null or c.last_verified_at<now()-interval '180 days' then 'stale' else 'present' end
     when 'search_admission' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from search.course_documents d where d.course_id=c.id) then 'present' else 'not_yet_enriched' end
     when 'publication_readiness' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when (select count(distinct lower(es.publication_status)) from publishing.entity_states es where es.entity_id=c.id)>1 then 'ambiguous'
      when lower(coalesce(c.publication_status,''))='rejected' or exists(select 1 from publishing.entity_states es where es.entity_id=c.id and lower(es.publication_status)='rejected') then 'rejected'
      when lower(coalesce(c.publication_status,''))='published' or exists(select 1 from publishing.entity_states es where es.entity_id=c.id and lower(es.publication_status)='published') then 'present'
      else 'not_yet_enriched' end
     else null end state
   from scope c
  ), filtered as (
   select c.* from classified c where c.state is not null
    and ((v_state is not null and c.state=v_state) or (v_state is null and c.state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected')))
  ), numbered as (select f.*,count(*) over() total_count from filtered f), paged0 as (
   select * from numbered order by case state when 'rejected' then 1 when 'ambiguous' then 2 when 'source_null' then 3 when 'suppressed' then 4 when 'stale' then 5 else 6 end,lower(entity_name),id limit v_limit offset v_offset
  ), paged as (
   select p.*,
    coalesce(
      case v_domain
       when 'regulatory_fee' then (select f.source_id from catalogue.course_fees f where f.course_id=p.id and f.basis='registered_total_course' and f.fee_type='tuition' and f.source_id is not null order by f.source_snapshot_at desc nulls last,f.created_at desc limit 1)
       when 'provider_current_fee' then (select f.source_id from catalogue.course_fees f where f.course_id=p.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and f.source_id is not null order by f.source_snapshot_at desc nulls last,f.created_at desc limit 1)
       when 'course_url' then (select l.source_id from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=p.id and l.source_id is not null order by l.is_primary desc,l.updated_at desc limit 1)
       when 'intake' then (select i.source_id from catalogue.course_intakes i where i.course_id=p.id and i.source_id is not null order by i.intake_year desc nulls last,i.start_date desc nulls last limit 1)
       when 'english_requirement' then (select e.source_id from catalogue.course_english_requirements e where e.course_id=p.id and e.source_id is not null order by e.last_verified_at desc nulls last limit 1)
       else null end,
      p.canonical_source_id,
      (select r.source_id from catalogue.course_registrations r where r.course_id=p.id and r.source_id is not null order by r.valid_from desc nulls last limit 1)
    ) domain_source_id,
    coalesce(
      case v_domain
       when 'regulatory_fee' then (select f.evidence_id from catalogue.course_fees f where f.course_id=p.id and f.basis='registered_total_course' and f.fee_type='tuition' and f.evidence_id is not null order by f.source_snapshot_at desc nulls last,f.created_at desc limit 1)
       when 'provider_current_fee' then (select f.evidence_id from catalogue.course_fees f where f.course_id=p.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and f.evidence_id is not null order by f.source_snapshot_at desc nulls last,f.created_at desc limit 1)
       when 'course_url' then (select l.evidence_id from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=p.id and l.evidence_id is not null order by l.is_primary desc,l.updated_at desc limit 1)
       when 'intake' then (select i.evidence_id from catalogue.course_intakes i where i.course_id=p.id and i.evidence_id is not null order by i.intake_year desc nulls last,i.start_date desc nulls last limit 1)
       when 'english_requirement' then (select e.evidence_id from catalogue.course_english_requirements e where e.course_id=p.id and e.evidence_id is not null order by e.last_verified_at desc nulls last limit 1)
       else null end,
      (select el.evidence_id from pipeline.evidence_entity_links el where el.entity_type='course' and el.entity_id=p.id order by el.updated_at desc limit 1),
      (select r.evidence_id from catalogue.course_registrations r where r.course_id=p.id and r.evidence_id is not null order by r.valid_from desc nulls last limit 1)
    ) domain_evidence_id
   from paged0 p
  )
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object(
    'entity_id',p.id,'entity_type','course','entity_name',p.entity_name,'stable_key',p.stable_key,'provider_id',p.provider_id,'provider_name',p.provider_name,'country_code',p.country_code,
    'domain',v_domain,'state',p.state,'source_id',p.domain_source_id,'source_label',src.label,'evidence_id',p.domain_evidence_id,
    'review_id',(select q.id from workflow.review_queue q where q.entity_id=p.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review') order by q.priority desc,q.created_at limit 1),
    'last_verified_at',p.last_verified_at,'updated_at',p.updated_at,'context',jsonb_build_object('canonical_publication',p.publication_status)
   ) order by lower(p.entity_name)),'[]'::jsonb),'total',coalesce(max(p.total_count),0),'limit',v_limit,'offset',v_offset,'entity_type','course','domain',v_domain,'state',v_state)
  into v_result from paged p left join pipeline.sources src on src.id=p.domain_source_id;
  return v_result;
 elsif v_entity='provider' then
  with classified as (
   select p.*,case v_domain when 'identity_completeness' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.identity_ok then 'present' else 'source_null' end when 'regulatory_completeness' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.registration_count>0 then 'present' else 'source_null' end when 'geography_delivery' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.geography_present then 'present' else 'not_yet_enriched' end when 'evidence' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.evidence_count>0 then 'present' else 'not_yet_enriched' end when 'verification_freshness' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.last_verified_at is null or p.last_verified_at<now()-interval '180 days' then 'stale' else 'present' end when 'publication_readiness' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.channel_rejected_count>0 or lower(coalesce(p.publication_status,''))='rejected' then 'rejected' when p.channel_distinct_status_count>1 then 'ambiguous' when p.channel_published_count>0 or lower(coalesce(p.publication_status,''))='published' then 'present' else 'not_yet_enriched' end else null end state from security.data_quality_provider_base(v_country) p
  ), filtered as (select p.* from classified p where p.state is not null and ((v_state is not null and p.state=v_state) or (v_state is null and p.state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected'))) and (v_query is null or p.entity_name ilike '%'||v_query||'%' or p.stable_key ilike '%'||v_query||'%')), numbered as (select f.*,count(*) over() total_count from filtered f), paged as (select * from numbered order by lower(entity_name),id limit v_limit offset v_offset)
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('entity_id',p.id,'entity_type','provider','entity_name',p.entity_name,'stable_key',p.stable_key,'country_code',p.country_code,'domain',v_domain,'state',p.state,'source_id',p.source_id,'source_label',src.label,'evidence_id',p.evidence_id,'review_id',(select q.id from workflow.review_queue q where q.entity_id=p.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review') order by q.priority desc,q.created_at limit 1),'last_verified_at',p.last_verified_at,'updated_at',p.updated_at) order by lower(p.entity_name)),'[]'::jsonb),'total',coalesce(max(p.total_count),0),'limit',v_limit,'offset',v_offset,'entity_type','provider','domain',v_domain,'state',v_state) into v_result from paged p left join pipeline.sources src on src.id=p.source_id; return v_result;
 elsif v_entity='campus' then
  with classified as (
   select c.*,case v_domain when 'identity_completeness' then case when v_domain=any(c.review_domains) then 'ambiguous' when c.identity_ok then 'present' else 'source_null' end when 'geography_delivery' then case when v_domain=any(c.review_domains) then 'ambiguous' when c.geography_present then 'present' else 'source_null' end when 'evidence' then case when v_domain=any(c.review_domains) then 'ambiguous' when c.evidence_count>0 then 'present' else 'not_yet_enriched' end when 'verification_freshness' then case when v_domain=any(c.review_domains) then 'ambiguous' when c.last_verified_at is null or c.last_verified_at<now()-interval '180 days' then 'stale' else 'present' end when 'publication_readiness' then case when v_domain=any(c.review_domains) then 'ambiguous' when c.channel_rejected_count>0 or lower(coalesce(c.publication_status,''))='rejected' then 'rejected' when c.channel_distinct_status_count>1 then 'ambiguous' when c.channel_published_count>0 or lower(coalesce(c.publication_status,''))='published' then 'present' else 'not_yet_enriched' end else null end state from security.data_quality_campus_base(v_country) c
  ), filtered as (select c.* from classified c where c.state is not null and ((v_state is not null and c.state=v_state) or (v_state is null and c.state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected'))) and (v_query is null or c.entity_name ilike '%'||v_query||'%' or c.provider_name ilike '%'||v_query||'%' or c.stable_key ilike '%'||v_query||'%')), numbered as (select f.*,count(*) over() total_count from filtered f), paged as (select * from numbered order by lower(entity_name),id limit v_limit offset v_offset)
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('entity_id',p.id,'entity_type','campus','entity_name',p.entity_name,'stable_key',p.stable_key,'provider_id',p.provider_id,'provider_name',p.provider_name,'country_code',p.country_code,'domain',v_domain,'state',p.state,'source_id',p.source_id,'source_label',src.label,'evidence_id',p.evidence_id,'review_id',(select q.id from workflow.review_queue q where q.entity_id=p.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review') order by q.priority desc,q.created_at limit 1),'last_verified_at',p.last_verified_at,'updated_at',p.updated_at) order by lower(p.entity_name)),'[]'::jsonb),'total',coalesce(max(p.total_count),0),'limit',v_limit,'offset',v_offset,'entity_type','campus','domain',v_domain,'state',v_state) into v_result from paged p left join pipeline.sources src on src.id=p.source_id; return v_result;
 elsif v_entity='scholarship' then
  with classified as (
   select s.*,case v_domain when 'identity_completeness' then case when v_domain=any(s.review_domains) then 'ambiguous' when s.identity_ok then 'present' else 'source_null' end when 'scholarship' then case when v_domain=any(s.review_domains) then 'ambiguous' when s.semantic_present then 'present' else 'not_yet_enriched' end when 'evidence' then case when v_domain=any(s.review_domains) then 'ambiguous' when s.evidence_count>0 then 'present' else 'not_yet_enriched' end when 'verification_freshness' then case when v_domain=any(s.review_domains) then 'ambiguous' else 'not_yet_enriched' end when 'publication_readiness' then case when v_domain=any(s.review_domains) then 'ambiguous' when s.channel_rejected_count>0 or lower(coalesce(s.publication_status,''))='rejected' then 'rejected' when s.channel_distinct_status_count>1 then 'ambiguous' when s.channel_published_count>0 or lower(coalesce(s.publication_status,''))='published' then 'present' else 'not_yet_enriched' end else null end state from security.data_quality_scholarship_base(v_country) s
  ), filtered as (select s.* from classified s where s.state is not null and ((v_state is not null and s.state=v_state) or (v_state is null and s.state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected'))) and (v_query is null or s.entity_name ilike '%'||v_query||'%' or coalesce(s.provider_name,'') ilike '%'||v_query||'%' or s.stable_key ilike '%'||v_query||'%')), numbered as (select f.*,count(*) over() total_count from filtered f), paged as (select * from numbered order by lower(entity_name),id limit v_limit offset v_offset)
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('entity_id',p.id,'entity_type','scholarship','entity_name',p.entity_name,'stable_key',p.stable_key,'provider_id',p.provider_id,'provider_name',p.provider_name,'country_code',p.country_code,'domain',v_domain,'state',p.state,'source_id',p.source_id,'source_label',src.label,'evidence_id',p.evidence_id,'review_id',(select q.id from workflow.review_queue q where q.entity_id=p.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review') order by q.priority desc,q.created_at limit 1),'updated_at',p.updated_at) order by lower(p.entity_name)),'[]'::jsonb),'total',coalesce(max(p.total_count),0),'limit',v_limit,'offset',v_offset,'entity_type','scholarship','domain',v_domain,'state',v_state) into v_result from paged p left join pipeline.sources src on src.id=p.source_id; return v_result;
 else raise exception 'unsupported data quality entity type: %',v_entity using errcode='22023'; end if;
end
$$;


ALTER FUNCTION "security"."data_quality_exceptions_impl"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_overview_cached"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare
  v_country text:=nullif(upper(btrim(coalesce(p_args->>'country_code',''))),'');
  v_scope text;
  v_row security.data_quality_overview_snapshots%rowtype;
  v_reason text;
begin
  if v_country is not null and v_country not in ('AU','NZ') then
    raise exception 'unsupported Data Quality country scope: %',v_country using errcode='22023';
  end if;
  v_scope:=coalesce(v_country,'AU+NZ');
  select * into v_row from security.data_quality_overview_snapshots where scope_code=v_scope;
  if not found then
    raise exception 'Data Quality overview snapshot unavailable for scope %',v_scope using errcode='55000';
  end if;
  v_reason:=coalesce(v_row.payload#>>'{policy,reason}','Domain readiness is reported by governed domain.')
    ||' Aggregate snapshot computed at '||v_row.computed_at::text
    ||'; refreshed off-peak daily and after explicit post-ingestion refresh; exception drill-down is live.';
  return jsonb_set(v_row.payload,'{policy,reason}',to_jsonb(v_reason),true)
    || jsonb_build_object('snapshot',jsonb_build_object('scope_code',v_row.scope_code,'computed_at',v_row.computed_at,'compute_duration_ms',v_row.compute_duration_ms,'refresh_interval_minutes',1440,'refresh_mode','off_peak_daily_plus_explicit_post_ingestion','live_drilldown',true));
end
$$;


ALTER FUNCTION "security"."data_quality_overview_cached"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_overview_impl"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'scholarship', 'pipeline', 'workflow', 'search', 'publishing'
    SET "work_mem" TO '128MB'
    AS $$
with params as (select nullif(upper(btrim(coalesce(p_args->>'country_code',''))),'') country_code),
course_scope as materialized (
 select c.id,c.provider_id,c.stable_key,c.canonical_title,c.course_code,c.course_url,c.delivery_mode,c.study_level_id,c.primary_field_id,c.last_verified_at,c.publication_status,
        co.iso_alpha2::text country_code
 from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
 where (((select country_code from params) is null and co.iso_alpha2 in ('AU','NZ')) or co.iso_alpha2=(select country_code from params))
), course_reg as (select r.course_id,count(*) filter(where coalesce(r.status,'active')='active')::int n from catalogue.course_registrations r join course_scope c on c.id=r.course_id group by r.course_id),
course_geo as (select cc.course_id,count(*)::int n,bool_or(coalesce(nullif(btrim(cc.delivery_mode),''),null) is not null) has_delivery from catalogue.course_campuses cc join course_scope c on c.id=cc.course_id group by cc.course_id),
course_tax as (select o.course_id,bool_or(lower(o.mapping_status) in ('review_required','ambiguous')) filter(where o.status='current') ambiguous,bool_or(lower(o.mapping_status)='rejected') filter(where o.status='current') rejected from catalogue.course_study_level_observations o join course_scope c on c.id=o.course_id group by o.course_id),
reg_fee as (select f.course_id,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active')::int n,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount is not null)::int values_n,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount=0)::int zeros,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount>0)::int positives from catalogue.course_fees f join course_scope c on c.id=f.course_id group by f.course_id),
provider_fee as (select f.course_id,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active')::int n,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount is not null)::int values_n,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount=0)::int zeros,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount>0)::int positives,bool_or(lower(coalesce(f.status,''))='suppressed') filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course') suppressed,bool_or(lower(coalesce(f.status,''))='rejected') filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course') rejected from catalogue.course_fees f join course_scope c on c.id=f.course_id group by f.course_id),
course_link as (select l.course_id,count(*) filter(where lower(coalesce(l.status,'active'))='active')::int n,bool_or(lower(coalesce(l.status,''))='suppressed') suppressed,bool_or(lower(coalesce(l.status,''))='rejected') rejected from catalogue.course_links l join course_scope c on c.id=l.course_id where l.link_type = 'official_course' group by l.course_id),
course_intake as (select i.course_id,count(*) filter(where lower(coalesce(i.status,'active'))='active')::int n,bool_or(lower(coalesce(i.status,''))='suppressed') suppressed,bool_or(lower(coalesce(i.status,''))='rejected') rejected from catalogue.course_intakes i join course_scope c on c.id=i.course_id group by i.course_id),
course_english as (select e.course_id,count(*) filter(where lower(coalesce(e.status,'active'))='active')::int n,bool_or(lower(coalesce(e.status,''))='suppressed') suppressed,bool_or(lower(coalesce(e.status,''))='rejected') rejected from catalogue.course_english_requirements e join course_scope c on c.id=e.course_id group by e.course_id),
sch_course as (select sc.course_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int inc,count(*) filter(where coalesce(sc.include_exclude,'include')='exclude')::int exc from scholarship.scopes sc join course_scope c on c.id=sc.course_id where sc.course_id is not null group by sc.course_id),
sch_provider as (select sc.provider_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int inc,count(*) filter(where coalesce(sc.include_exclude,'include')='exclude')::int exc from scholarship.scopes sc join (select distinct provider_id from course_scope) p on p.provider_id=sc.provider_id where sc.scope_type='provider' and sc.provider_id is not null group by sc.provider_id),
course_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join course_scope c on c.id=el.entity_id where el.entity_type='course' group by el.entity_id),
course_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join course_scope c on c.id=es.entity_id group by es.entity_id),
course_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join course_scope c on c.id=q.entity_id group by q.entity_id),
course_flags as materialized (
 select c.*,
  (c.stable_key is not null and btrim(c.stable_key)<>'' and c.canonical_title is not null and btrim(c.canonical_title)<>'' and c.course_code is not null and btrim(c.course_code)<>'' and c.provider_id is not null) identity_ok,
  coalesce(r.n,0) reg_n,coalesce(g.n,0) campus_n,(coalesce(g.has_delivery,false) or coalesce(nullif(btrim(c.delivery_mode),''),null) is not null) has_delivery,
  (c.study_level_id is not null and c.primary_field_id is not null) taxonomy_complete,coalesce(t.ambiguous,false) taxonomy_ambiguous,coalesce(t.rejected,false) taxonomy_rejected,
  coalesce(rf.n,0) reg_fee_n,coalesce(rf.values_n,0) reg_fee_values,coalesce(rf.zeros,0) reg_fee_zero,coalesce(rf.positives,0) reg_fee_positive,
  coalesce(pf.n,0) provider_fee_n,coalesce(pf.values_n,0) provider_fee_values,coalesce(pf.zeros,0) provider_fee_zero,coalesce(pf.positives,0) provider_fee_positive,coalesce(pf.suppressed,false) provider_fee_suppressed,coalesce(pf.rejected,false) provider_fee_rejected,
  (coalesce(nullif(btrim(c.course_url),''),null) is not null or coalesce(cl.n,0)>0) has_url,coalesce(cl.suppressed,false) url_suppressed,coalesce(cl.rejected,false) url_rejected,
  coalesce(ci.n,0) intake_n,coalesce(ci.suppressed,false) intake_suppressed,coalesce(ci.rejected,false) intake_rejected,
  coalesce(ce.n,0) english_n,coalesce(ce.suppressed,false) english_suppressed,coalesce(ce.rejected,false) english_rejected,
  coalesce(sc.inc,0)+coalesce(sp.inc,0) scholarship_inc,coalesce(sc.exc,0)+coalesce(sp.exc,0) scholarship_exc,
  coalesce(ev.n,0) evidence_n,(sd.course_id is not null) search_projected,
  coalesce(cp.n,0) channel_n,coalesce(cp.published,0) channel_published,coalesce(cp.rejected,0) channel_rejected,coalesce(cp.statuses,0) channel_statuses,
  coalesce(rv.domains,'{}'::text[]) review_domains
 from course_scope c left join course_reg r on r.course_id=c.id left join course_geo g on g.course_id=c.id left join course_tax t on t.course_id=c.id left join reg_fee rf on rf.course_id=c.id left join provider_fee pf on pf.course_id=c.id left join course_link cl on cl.course_id=c.id left join course_intake ci on ci.course_id=c.id left join course_english ce on ce.course_id=c.id left join sch_course sc on sc.course_id=c.id left join sch_provider sp on sp.provider_id=c.provider_id left join course_ev ev on ev.entity_id=c.id left join search.course_documents sd on sd.course_id=c.id left join course_pub cp on cp.entity_id=c.id left join course_rev rv on rv.entity_id=c.id
),
provider_scope as materialized (select p.id,p.stable_key,p.canonical_name,p.country_id,p.subdivision_id,p.primary_city,p.address_line1,p.last_verified_at,p.publication_status,co.iso_alpha2::text country_code from catalogue.providers p join ref.countries co on co.id=p.country_id where (((select country_code from params) is null and co.iso_alpha2 in ('AU','NZ')) or co.iso_alpha2=(select country_code from params))),
provider_reg as (select r.provider_id,count(*) filter(where coalesce(r.status,'active')='active')::int n from catalogue.provider_registrations r join provider_scope p on p.id=r.provider_id group by r.provider_id),
provider_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join provider_scope p on p.id=el.entity_id where el.entity_type='provider' group by el.entity_id),
provider_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join provider_scope p on p.id=es.entity_id group by es.entity_id),
provider_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join provider_scope p on p.id=q.entity_id group by q.entity_id),
provider_flags as materialized (select p.*,(p.stable_key is not null and btrim(p.stable_key)<>'' and p.canonical_name is not null and btrim(p.canonical_name)<>'' and p.country_id is not null) identity_ok,coalesce(r.n,0) reg_n,(p.subdivision_id is not null or coalesce(nullif(btrim(p.primary_city),''),null) is not null or coalesce(nullif(btrim(p.address_line1),''),null) is not null) geography_present,coalesce(e.n,0) evidence_n,coalesce(pb.n,0) channel_n,coalesce(pb.published,0) channel_published,coalesce(pb.rejected,0) channel_rejected,coalesce(pb.statuses,0) channel_statuses,coalesce(rv.domains,'{}'::text[]) review_domains from provider_scope p left join provider_reg r on r.provider_id=p.id left join provider_ev e on e.entity_id=p.id left join provider_pub pb on pb.entity_id=p.id left join provider_rev rv on rv.entity_id=p.id),
campus_scope as materialized (select ca.id,ca.stable_key,ca.name,ca.provider_id,ca.country_id,ca.subdivision_id,ca.city,ca.address_line1,ca.latitude,ca.longitude,ca.evidence_id,ca.last_verified_at,ca.publication_status,co.iso_alpha2::text country_code from catalogue.campuses ca join ref.countries co on co.id=ca.country_id where (((select country_code from params) is null and co.iso_alpha2 in ('AU','NZ')) or co.iso_alpha2=(select country_code from params))),
campus_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join campus_scope c on c.id=el.entity_id where el.entity_type='campus' group by el.entity_id),
campus_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join campus_scope c on c.id=es.entity_id group by es.entity_id),
campus_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join campus_scope c on c.id=q.entity_id group by q.entity_id),
campus_flags as materialized (select c.*,(c.stable_key is not null and btrim(c.stable_key)<>'' and c.name is not null and btrim(c.name)<>'' and c.provider_id is not null and c.country_id is not null) identity_ok,(c.subdivision_id is not null or coalesce(nullif(btrim(c.city),''),null) is not null or coalesce(nullif(btrim(c.address_line1),''),null) is not null or (c.latitude is not null and c.longitude is not null)) geography_present,coalesce(e.n,case when c.evidence_id is not null then 1 else 0 end) evidence_n,coalesce(pb.n,0) channel_n,coalesce(pb.published,0) channel_published,coalesce(pb.rejected,0) channel_rejected,coalesce(pb.statuses,0) channel_statuses,coalesce(rv.domains,'{}'::text[]) review_domains from campus_scope c left join campus_ev e on e.entity_id=c.id left join campus_pub pb on pb.entity_id=c.id left join campus_rev rv on rv.entity_id=c.id),
scholarship_scope as materialized (select s.id,s.stable_key,s.name,s.provider_id,s.description,s.source_url,s.evidence_id,s.publication_status,coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text) country_code from scholarship.scholarships s left join catalogue.providers p on p.id=s.provider_id left join ref.countries pc on pc.id=p.country_id left join pipeline.sources src on src.id=s.source_id left join ref.countries sc on sc.id=src.country_id where ((((select country_code from params) is null) and coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text) in ('AU','NZ')) or coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text)=(select country_code from params))),
sch_scope as (select sc.scholarship_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int inc from scholarship.scopes sc join scholarship_scope s on s.id=sc.scholarship_id group by sc.scholarship_id),
sch_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join scholarship_scope s on s.id=el.entity_id where el.entity_type='scholarship' group by el.entity_id),
sch_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join scholarship_scope s on s.id=es.entity_id group by es.entity_id),
sch_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join scholarship_scope s on s.id=q.entity_id group by q.entity_id),
sch_flags as materialized (select s.*,(s.stable_key is not null and btrim(s.stable_key)<>'' and s.name is not null and btrim(s.name)<>'') identity_ok,(coalesce(nullif(btrim(s.description),''),null) is not null and coalesce(nullif(btrim(s.source_url),''),null) is not null and s.evidence_id is not null and (coalesce(ss.inc,0)>0 or s.provider_id is null)) semantic_present,coalesce(e.n,case when s.evidence_id is not null then 1 else 0 end) evidence_n,coalesce(pb.n,0) channel_n,coalesce(pb.published,0) channel_published,coalesce(pb.rejected,0) channel_rejected,coalesce(pb.statuses,0) channel_statuses,coalesce(rv.domains,'{}'::text[]) review_domains from scholarship_scope s left join sch_scope ss on ss.scholarship_id=s.id left join sch_ev e on e.entity_id=s.id left join sch_pub pb on pb.entity_id=s.id left join sch_rev rv on rv.entity_id=s.id),
all_states as (
 select 'course'::text entity_type,v.domain,v.state from course_flags c cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(c.review_domains) then 'ambiguous' when c.identity_ok then 'present' else 'source_null' end),
  ('regulatory_completeness',case when 'regulatory_completeness'=any(c.review_domains) then 'ambiguous' when c.reg_n>0 then 'present' else 'source_null' end),
  ('geography_delivery',case when 'geography_delivery'=any(c.review_domains) then 'ambiguous' when c.campus_n>0 and c.has_delivery then 'present' when c.country_code='AU' and c.campus_n=0 then 'source_null' else 'not_yet_enriched' end),
  ('taxonomy',case when 'taxonomy'=any(c.review_domains) or c.taxonomy_ambiguous then 'ambiguous' when c.taxonomy_rejected then 'rejected' when c.taxonomy_complete then 'present' when c.country_code='AU' then 'source_null' else 'not_yet_enriched' end),
  ('regulatory_fee',case when 'regulatory_fee'=any(c.review_domains) then 'ambiguous' when c.country_code<>'AU' then 'not_applicable' when c.reg_fee_n=0 or c.reg_fee_values=0 then 'source_null' when c.reg_fee_positive>0 then 'present' when c.reg_fee_zero>0 then 'zero' else 'source_null' end),
  ('provider_current_fee',case when 'provider_current_fee'=any(c.review_domains) then 'ambiguous' when c.provider_fee_rejected then 'rejected' when c.provider_fee_suppressed and c.provider_fee_n=0 then 'suppressed' when c.provider_fee_n=0 then 'not_yet_enriched' when c.provider_fee_values=0 then 'source_null' when c.provider_fee_positive>0 then 'present' when c.provider_fee_zero>0 then 'zero' else 'source_null' end),
  ('course_url',case when 'course_url'=any(c.review_domains) then 'ambiguous' when c.url_rejected then 'rejected' when c.url_suppressed and not c.has_url then 'suppressed' when c.has_url then 'present' else 'not_yet_enriched' end),
  ('intake',case when 'intake'=any(c.review_domains) then 'ambiguous' when c.intake_rejected then 'rejected' when c.intake_suppressed and c.intake_n=0 then 'suppressed' when c.intake_n>0 then 'present' else 'not_yet_enriched' end),
  ('english_requirement',case when 'english_requirement'=any(c.review_domains) then 'ambiguous' when c.english_rejected then 'rejected' when c.english_suppressed and c.english_n=0 then 'suppressed' when c.english_n>0 then 'present' else 'not_yet_enriched' end),
  ('scholarship',case when 'scholarship'=any(c.review_domains) then 'ambiguous' when c.scholarship_inc>0 then 'present' when c.scholarship_exc>0 then 'not_applicable' else 'not_yet_enriched' end),
  ('evidence',case when 'evidence'=any(c.review_domains) then 'ambiguous' when c.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(c.review_domains) then 'ambiguous' when c.last_verified_at is null or c.last_verified_at<now()-interval '180 days' then 'stale' else 'present' end),
  ('search_admission',case when 'search_admission'=any(c.review_domains) then 'ambiguous' when c.search_projected then 'present' else 'not_yet_enriched' end),
  ('publication_readiness',case when 'publication_readiness'=any(c.review_domains) then 'ambiguous' when c.channel_rejected>0 or lower(coalesce(c.publication_status,''))='rejected' then 'rejected' when c.channel_statuses>1 then 'ambiguous' when c.channel_published>0 or lower(coalesce(c.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
 union all select 'provider',v.domain,v.state from provider_flags p cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(p.review_domains) then 'ambiguous' when p.identity_ok then 'present' else 'source_null' end),
  ('regulatory_completeness',case when 'regulatory_completeness'=any(p.review_domains) then 'ambiguous' when p.reg_n>0 then 'present' else 'source_null' end),
  ('geography_delivery',case when 'geography_delivery'=any(p.review_domains) then 'ambiguous' when p.geography_present then 'present' else 'not_yet_enriched' end),
  ('evidence',case when 'evidence'=any(p.review_domains) then 'ambiguous' when p.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(p.review_domains) then 'ambiguous' when p.last_verified_at is null or p.last_verified_at<now()-interval '180 days' then 'stale' else 'present' end),
  ('publication_readiness',case when 'publication_readiness'=any(p.review_domains) then 'ambiguous' when p.channel_rejected>0 or lower(coalesce(p.publication_status,''))='rejected' then 'rejected' when p.channel_statuses>1 then 'ambiguous' when p.channel_published>0 or lower(coalesce(p.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
 union all select 'campus',v.domain,v.state from campus_flags c cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(c.review_domains) then 'ambiguous' when c.identity_ok then 'present' else 'source_null' end),
  ('geography_delivery',case when 'geography_delivery'=any(c.review_domains) then 'ambiguous' when c.geography_present then 'present' else 'source_null' end),
  ('evidence',case when 'evidence'=any(c.review_domains) then 'ambiguous' when c.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(c.review_domains) then 'ambiguous' when c.last_verified_at is null or c.last_verified_at<now()-interval '180 days' then 'stale' else 'present' end),
  ('publication_readiness',case when 'publication_readiness'=any(c.review_domains) then 'ambiguous' when c.channel_rejected>0 or lower(coalesce(c.publication_status,''))='rejected' then 'rejected' when c.channel_statuses>1 then 'ambiguous' when c.channel_published>0 or lower(coalesce(c.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
 union all select 'scholarship',v.domain,v.state from sch_flags s cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(s.review_domains) then 'ambiguous' when s.identity_ok then 'present' else 'source_null' end),
  ('scholarship',case when 'scholarship'=any(s.review_domains) then 'ambiguous' when s.semantic_present then 'present' else 'not_yet_enriched' end),
  ('evidence',case when 'evidence'=any(s.review_domains) then 'ambiguous' when s.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(s.review_domains) then 'ambiguous' else 'not_yet_enriched' end),
  ('publication_readiness',case when 'publication_readiness'=any(s.review_domains) then 'ambiguous' when s.channel_rejected>0 or lower(coalesce(s.publication_status,''))='rejected' then 'rejected' when s.channel_statuses>1 then 'ambiguous' when s.channel_published>0 or lower(coalesce(s.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
), defs(domain,label,sort_order,definition,authority) as (values
 ('identity_completeness','Identity completeness',10,'Stable governed identity fields required to resolve the entity without title/name inference.','Layer 1 canonical identity'),('regulatory_completeness','Regulatory completeness',20,'Current authoritative registration/Layer 1 regulatory presence; country-specific authority is preserved.','CRICOS / NZQA Layer 1'),('geography_delivery','Geography / delivery',30,'Provider/Campus geography and Course delivery relationships remain distinct. AU CRICOS source-absent Course Locations are not synthesised.','Layer 1 location authority / later enrichment'),('taxonomy','Taxonomy',40,'Governed Study Level and Field mappings; ambiguous/rejected source mappings remain exceptions.','Governed reference taxonomy'),('regulatory_fee','Regulatory fee',50,'AU CRICOS registered total-course tuition only. NZ has no CRICOS-equivalent fee dimension in the accepted Layer 1 contract.','CRICOS regulatory source'),('provider_current_fee','Current Provider fee',60,'Current Provider-published fee observations remain separate from CRICOS registered total-course fees.','Layer 2 Provider first-party source'),('course_url','Course URL',70,'Official Course URL/link enrichment; absence before a successful enrichment is not treated as source-null.','Layer 2 Provider first-party source'),('intake','Intake',80,'Provider-current intake observations with suppression/rejection retained distinctly.','Layer 2 Provider first-party source'),('english_requirement','English requirement',90,'Provider-current English entry requirements with suppression/rejection retained distinctly.','Layer 2 Provider first-party source'),('scholarship','Scholarship',100,'Relational Scholarship applicability; no scholarship relationship is not treated as a canonical Course defect.','Layer 2 Scholarship sources'),('evidence','Evidence',110,'Presence of governed evidence lineage for the canonical/enrichment entity.','Evidence workspace / source snapshots'),('verification_freshness','Verification / freshness',120,'Explicit verification timestamps only; missing or older-than-180-day verification is stale. Scholarship verification is not inferred from updated_at.','Canonical verification semantics'),('search_admission','Search admission',130,'Presence in the governed Search projection; this does not imply enrichment admission or publication.','Search course-v2 projection'),('publication_readiness','Publication readiness',140,'Recorded canonical/channel publication progression; no channel state is not invented as published.','Canonical + publishing channel state')),
agg as (select entity_type,domain,count(*)::bigint scope_count,count(*) filter(where state<>'not_applicable')::bigint applicable_count,count(*) filter(where state in ('present','zero'))::bigint ready_count,count(*) filter(where state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected'))::bigint attention_count,jsonb_build_object('present',count(*) filter(where state='present'),'source_null',count(*) filter(where state='source_null'),'not_applicable',count(*) filter(where state='not_applicable'),'zero',count(*) filter(where state='zero'),'suppressed',count(*) filter(where state='suppressed'),'not_yet_enriched',count(*) filter(where state='not_yet_enriched'),'stale',count(*) filter(where state='stale'),'ambiguous',count(*) filter(where state='ambiguous'),'rejected',count(*) filter(where state='rejected')) states from all_states group by entity_type,domain),
metrics as (select a.*,d.label,d.sort_order,d.definition,d.authority,case when a.applicable_count=0 then null else round(a.ready_count*100.0/a.applicable_count,2) end readiness_pct from agg a join defs d using(domain))
select jsonb_build_object('scope',jsonb_build_object('country_code',(select country_code from params),'default_scope',case when (select country_code from params) is null then 'AU+NZ' else (select country_code from params) end,'as_of',now()),'policy',jsonb_build_object('composite_score','not_exposed','reason','Cross-domain equal weighting conflates regulatory authority, enrichment coverage, Search admission and publication state. Domain readiness is reported instead.','ready_states',jsonb_build_array('present','zero'),'excluded_from_denominator',jsonb_build_array('not_applicable')),'state_vocabulary',jsonb_build_array('present','source_null','not_applicable','zero','suppressed','not_yet_enriched','stale','ambiguous','rejected'),'metrics',coalesce((select jsonb_agg(jsonb_build_object('entity_type',entity_type,'domain',domain,'label',label,'scope_count',scope_count,'applicable_count',applicable_count,'ready_count',ready_count,'attention_count',attention_count,'readiness_pct',readiness_pct,'states',states,'definition',definition,'authority',authority) order by sort_order,entity_type) from metrics),'[]'::jsonb))
$$;


ALTER FUNCTION "security"."data_quality_overview_impl"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_provider_base"("p_country_code" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "entity_name" "text", "stable_key" "text", "country_code" "text", "source_id" "uuid", "evidence_id" "uuid", "last_verified_at" timestamp with time zone, "updated_at" timestamp with time zone, "publication_status" "text", "identity_ok" boolean, "registration_count" integer, "geography_present" boolean, "evidence_count" integer, "channel_state_count" integer, "channel_published_count" integer, "channel_rejected_count" integer, "channel_distinct_status_count" integer, "review_domains" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'pipeline', 'workflow', 'publishing', 'auth'
    AS $$
with scope as (
  select p.*,co.iso_alpha2::text country_code
  from catalogue.providers p join ref.countries co on co.id=p.country_id
  where (p_country_code is null and co.iso_alpha2 in ('AU','NZ')) or (p_country_code is not null and co.iso_alpha2=upper(p_country_code))
), reg as (
  select r.provider_id,count(*) filter(where coalesce(r.status,'active')='active')::int active_count,
    (array_agg(r.source_id order by r.checked_at desc nulls last,r.id) filter(where r.source_id is not null))[1] source_id,
    (array_agg(r.evidence_id order by r.checked_at desc nulls last,r.id) filter(where r.evidence_id is not null))[1] evidence_id
  from catalogue.provider_registrations r join scope s on s.id=r.provider_id group by r.provider_id
), ev as (
  select el.entity_id,count(distinct el.evidence_id)::int evidence_count,(array_agg(el.evidence_id order by el.updated_at desc))[1] evidence_id
  from pipeline.evidence_entity_links el join scope s on s.id=el.entity_id where el.entity_type='provider' group by el.entity_id
), pub as (
  select es.entity_id,count(*)::int state_count,count(*) filter(where lower(es.publication_status)='published')::int published_count,
    count(*) filter(where lower(es.publication_status)='rejected')::int rejected_count,count(distinct lower(es.publication_status))::int distinct_status_count
  from publishing.entity_states es join scope s on s.id=es.entity_id group by es.entity_id
), rev as (
  select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) review_domains
  from workflow.review_queue q join scope s on s.id=q.entity_id group by q.entity_id
)
select s.id,coalesce(s.display_name,s.canonical_name),s.stable_key,s.country_code,coalesce(s.canonical_source_id,reg.source_id),coalesce(ev.evidence_id,reg.evidence_id),
 s.last_verified_at,s.updated_at,s.publication_status,
 (s.stable_key is not null and btrim(s.stable_key)<>'' and s.canonical_name is not null and btrim(s.canonical_name)<>'' and s.country_id is not null),
 coalesce(reg.active_count,0),
 (s.subdivision_id is not null or coalesce(nullif(btrim(s.primary_city),''),null) is not null or coalesce(nullif(btrim(s.address_line1),''),null) is not null),
 coalesce(ev.evidence_count,0),coalesce(pub.state_count,0),coalesce(pub.published_count,0),coalesce(pub.rejected_count,0),coalesce(pub.distinct_status_count,0),coalesce(rev.review_domains,'{}'::text[])
from scope s left join reg on reg.provider_id=s.id left join ev on ev.entity_id=s.id left join pub on pub.entity_id=s.id left join rev on rev.entity_id=s.id
$$;


ALTER FUNCTION "security"."data_quality_provider_base"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_quarantine_impl"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'scholarship', 'pipeline', 'ref'
    AS $$
declare
  v_entity text:=lower(nullif(btrim(coalesce(p_args->>'entity_type','')),''));
  v_country text:=upper(nullif(btrim(coalesce(p_args->>'country_code','')),''));
  v_query text:=nullif(btrim(coalesce(p_args->>'query','')),'');
  v_limit int:=least(greatest(coalesce(nullif(p_args->>'limit','')::int,50),1),200);
  v_offset int:=greatest(coalesce(nullif(p_args->>'offset','')::int,0),0);
  v_result jsonb;
begin
  if v_entity is not null and v_entity not in ('provider','course','campus','scholarship','provider_contact') then
    raise exception 'unsupported quarantine entity type' using errcode='22023';
  end if;

  with entities as (
    select 'provider'::text entity_type,p.id entity_id,coalesce(p.display_name,p.canonical_name) entity_name,
           p.id provider_id,coalesce(p.display_name,p.canonical_name) provider_name,co.iso_alpha2::text country_code
    from catalogue.providers p join ref.countries co on co.id=p.country_id
    union all
    select 'course',c.id,coalesce(c.display_title,c.canonical_title),p.id,coalesce(p.display_name,p.canonical_name),co.iso_alpha2::text
    from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
    union all
    select 'campus',ca.id,ca.name,p.id,coalesce(p.display_name,p.canonical_name),co.iso_alpha2::text
    from catalogue.campuses ca join catalogue.providers p on p.id=ca.provider_id join ref.countries co on co.id=p.country_id
    union all
    select 'scholarship',s.id,s.name,p.id,coalesce(p.display_name,p.canonical_name),co.iso_alpha2::text
    from scholarship.scholarships s left join catalogue.providers p on p.id=s.provider_id left join ref.countries co on co.id=p.country_id
    union all
    select 'provider_contact',o.id,coalesce(nullif(btrim(o.full_name),''),nullif(btrim(o.job_title),''),'Provider contact'),p.id,
           coalesce(p.display_name,p.canonical_name),co.iso_alpha2::text
    from pipeline.provider_contact_observations o join catalogue.providers p on p.id=o.provider_id join ref.countries co on co.id=p.country_id
  ), effective as (
    select e.*,
      db.id direct_decision_id,db.reason_code direct_reason_code,db.comment direct_comment,db.review_at direct_review_at,db.expires_at direct_expires_at,db.created_at direct_created_at,
      pb.id provider_decision_id,pb.reason_code provider_reason_code,pb.comment provider_comment,pb.review_at provider_review_at,pb.expires_at provider_expires_at,pb.created_at provider_created_at
    from entities e
    left join security.layer4_active_blocks db
      on db.entity_type=e.entity_type and db.entity_id=e.entity_id and db.block_scope='data_quality_quarantine'
    left join security.layer4_active_blocks pb
      on e.entity_type<>'provider' and e.provider_id is not null
     and pb.entity_type='provider' and pb.entity_id=e.provider_id and pb.block_scope='data_quality_quarantine'
    where db.id is not null or pb.id is not null
  ), filtered as (
    select *,count(*) over() total_count
    from effective
    where (v_entity is null or entity_type=v_entity)
      and (v_country is null or country_code=v_country)
      and (v_query is null or entity_name ilike '%'||v_query||'%' or coalesce(provider_name,'') ilike '%'||v_query||'%')
  ), paged as (
    select * from filtered
    order by entity_type,lower(entity_name),entity_id
    limit v_limit offset v_offset
  )
  select jsonb_build_object(
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'entity_type',entity_type,'entity_id',entity_id,'entity_name',entity_name,
      'provider_id',provider_id,'provider_name',provider_name,'country_code',country_code,
      'direct_quarantine',direct_decision_id is not null,
      'inherited_provider_quarantine',provider_decision_id is not null,
      'effective_decision_id',coalesce(direct_decision_id,provider_decision_id),
      'reason_code',coalesce(direct_reason_code,provider_reason_code),
      'comment',coalesce(direct_comment,provider_comment),
      'review_at',coalesce(direct_review_at,provider_review_at),
      'expires_at',coalesce(direct_expires_at,provider_expires_at),
      'created_at',coalesce(direct_created_at,provider_created_at)
    ) order by entity_type,lower(entity_name),entity_id),'[]'::jsonb),
    'total',coalesce(max(total_count),0),
    'limit',v_limit,'offset',v_offset,
    'entity_type',v_entity,'country_code',v_country,
    'scope','data_quality_quarantine'
  ) into v_result
  from paged;

  return coalesce(v_result,jsonb_build_object(
    'items','[]'::jsonb,'total',0,'limit',v_limit,'offset',v_offset,
    'entity_type',v_entity,'country_code',v_country,'scope','data_quality_quarantine'
  ));
end $$;


ALTER FUNCTION "security"."data_quality_quarantine_impl"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_scholarship_base"("p_country_code" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "entity_name" "text", "stable_key" "text", "provider_id" "uuid", "provider_name" "text", "country_code" "text", "source_id" "uuid", "evidence_id" "uuid", "updated_at" timestamp with time zone, "publication_status" "text", "identity_ok" boolean, "semantic_present" boolean, "evidence_count" integer, "channel_state_count" integer, "channel_published_count" integer, "channel_rejected_count" integer, "channel_distinct_status_count" integer, "review_domains" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'scholarship', 'catalogue', 'ref', 'pipeline', 'workflow', 'publishing', 'auth'
    AS $$
with scope as (
 select s.*,coalesce(p.display_name,p.canonical_name) provider_name,coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text) country_code
 from scholarship.scholarships s
 left join catalogue.providers p on p.id=s.provider_id
 left join ref.countries pc on pc.id=p.country_id
 left join pipeline.sources src on src.id=s.source_id
 left join ref.countries sc on sc.id=src.country_id
 where ((p_country_code is null and coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text) in ('AU','NZ'))
    or (p_country_code is not null and coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text)=upper(p_country_code)))
), scp as (
 select sc.scholarship_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int include_count
 from scholarship.scopes sc join scope s on s.id=sc.scholarship_id group by sc.scholarship_id
), ev as (
 select el.entity_id,count(distinct el.evidence_id)::int evidence_count,(array_agg(el.evidence_id order by el.updated_at desc))[1] evidence_id
 from pipeline.evidence_entity_links el join scope s on s.id=el.entity_id where el.entity_type='scholarship' group by el.entity_id
), pub as (
 select es.entity_id,count(*)::int state_count,count(*) filter(where lower(es.publication_status)='published')::int published_count,
 count(*) filter(where lower(es.publication_status)='rejected')::int rejected_count,count(distinct lower(es.publication_status))::int distinct_status_count
 from publishing.entity_states es join scope s on s.id=es.entity_id group by es.entity_id
), rev as (
 select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) review_domains
 from workflow.review_queue q join scope s on s.id=q.entity_id group by q.entity_id
)
select s.id,s.name,s.stable_key,s.provider_id,s.provider_name,s.country_code,s.source_id,coalesce(s.evidence_id,ev.evidence_id),s.updated_at,s.publication_status,
 (s.stable_key is not null and btrim(s.stable_key)<>'' and s.name is not null and btrim(s.name)<>''),
 (coalesce(nullif(btrim(s.description),''),null) is not null and coalesce(nullif(btrim(s.source_url),''),null) is not null and s.evidence_id is not null and (coalesce(scp.include_count,0)>0 or s.provider_id is null)),
 coalesce(ev.evidence_count,case when s.evidence_id is not null then 1 else 0 end),coalesce(pub.state_count,0),coalesce(pub.published_count,0),coalesce(pub.rejected_count,0),coalesce(pub.distinct_status_count,0),coalesce(rev.review_domains,'{}'::text[])
from scope s left join scp on scp.scholarship_id=s.id left join ev on ev.entity_id=s.id left join pub on pub.entity_id=s.id left join rev on rev.entity_id=s.id
$$;


ALTER FUNCTION "security"."data_quality_scholarship_base"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."delivery_mode_from_location"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with a as (select lower(coalesce(p_text, '')) s),
       b as (select s ~ '(\monline\M|\mon-line\M|\mremote\M|\mdistance\M|\mexternal\M|off[ -]campus)' o,
                    regexp_replace(s, '(university of [a-z]+ online|[a-z]+ online|\monline\M|\mon-line\M|\mremote\M|\mdistance\M|\mexternal\M|off[ -]campus|learning|study|and|or|only|campus(es)?|location(s)?|[^a-z])', ' ', 'g') rest from a)
  select case when btrim(p_text) = '' or p_text is null then null
              when o and length(btrim(rest)) >= 3 then 'on_campus_and_online'
              when o then 'online'
              when length(btrim(rest)) >= 3 then 'on_campus'
              else null end
  from b
$$;


ALTER FUNCTION "security"."delivery_mode_from_location"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."delivery_mode_from_text"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with a0 as (select lower(coalesce(p_text, '')) s),
       a1 as (select regexp_replace(s, '(online\s*-\s*no\M|online[^.]{0,40}only for non-international[^.]{0,120}|not offered online|\(includes blended\)|distance\s*\((?:assessment|recognition) of prior learning[^)]{0,60}\))', ' ', 'g') s from a0),
       a2 as (select regexp_replace(s, '(online with (?:some )?(?:face[ -]to[ -]face|on[ -]?campus|block)|mixed attendance mode|virtual classroom)', ' blended ', 'g') s from a1),
       a2b as (select regexp_replace(s, '([0-9]+\s*(?:hours?|hrs?|%)[^.]{0,40}(?:face[ -]to[ -]face|classroom|on[ -]?campus|in[ -]person)[^.]{0,80}[0-9]+\s*(?:hours?|hrs?|%)[^.]{0,40}(?:online|distance)|(?:face[ -]to[ -]face|classroom|on[ -]?campus|in[ -]person)[^.]{0,20}[0-9]+\s*(?:hours?|hrs?|%)[^.]{0,80}(?:online|distance)[^.]{0,20}[0-9]+\s*(?:hours?|hrs?|%))', ' blended ', 'g') s from a2),
       a3 as (select regexp_replace(regexp_replace(s, '\mon-line\M', 'online', 'g'), '\mexternal\M', ' distance ', 'g') s from a2b),
       a4 as (select regexp_replace(regexp_replace(s, '(study(ing)? from home|\mfrom home\M)', ' online ', 'g'), '(\mclassroom\M|\min[ -]class\M|\monsite\M|\mon-site\M|residential (?:seminars?|blocks?|study)|\mnoho\M)', ' on campus ', 'g') s from a3),
       b as (select regexp_replace(s, 'off[ -]campus', ' distance ', 'g') s from a4),
       c as (select s ~ '(100% online|\monline\M|\mdistance\M)' o, s ~ '(on[ -]?campus|face[ -]to[ -]face|in[ -]person|\mcampus\M)' k, s ~ '(blended|mixed mode|multi[ -]?modal|hybrid)' m from b)
  select case when o and k then 'on_campus_and_online'
              when m then 'blended'
              when o then 'online'
              when k then 'on_campus'
              else null end
  from c
$$;


ALTER FUNCTION "security"."delivery_mode_from_text"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."directory_match_v1"("p_site" "text" DEFAULT 'hotcourses'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline'
    AS $$
declare v_matched int; v_counts int;
begin
  with p as (
    select p.id, k.iso_alpha2 cc,
           array[trim(regexp_replace(regexp_replace(lower(regexp_replace(coalesce(p.display_name, p.canonical_name), '\s*\([^)]*\)', '', 'g')), '[^a-z0-9]+', ' ', 'g'), '^the ', '')),
                 trim(regexp_replace(regexp_replace(lower(regexp_replace(p.canonical_name, '\s*\([^)]*\)', '', 'g')), '[^a-z0-9]+', ' ', 'g'), '^the ', ''))] names
      from catalogue.providers p join ref.countries k on k.id = p.country_id where p.lifecycle_status = 'active'),
  m as (
    select d.site, d.country_code, d.directory_id, (array_agg(p.id order by p.id))[1] provider_id, count(distinct p.id) n
      from pipeline.directory_institutions d
      join p on p.cc = d.country_code and trim(regexp_replace(regexp_replace(lower(d.name), '[^a-z0-9]+', ' ', 'g'), '^the ', '')) = any(p.names)
     where d.site = p_site group by 1, 2, 3)
  update pipeline.directory_institutions d set provider_id = m.provider_id, matched_by = 'exact_name', updated_at = now()
    from m where m.n = 1 and d.site = m.site and d.country_code = m.country_code and d.directory_id = m.directory_id
     and d.provider_id is distinct from m.provider_id;
  get diagnostics v_matched = row_count;
  update pipeline.directory_institutions d set course_count_hint = x.n, updated_at = now()
    from (select distinct on (di.directory_id, di.country_code) di.directory_id, di.country_code,
                 nullif(regexp_replace(substring(dp.page_text from '(?i)(\d[\d,]{0,6})\s+courses?\M'), ',', '', 'g'), '')::int n
            from pipeline.directory_institutions di join pipeline.directory_pages dp on split_part(dp.url, '#', 1) = di.profile_url
           where di.site = p_site order by di.directory_id, di.country_code, dp.captured_at desc) x
   where d.site = p_site and d.directory_id = x.directory_id and d.country_code = x.country_code and x.n is not null and d.course_count_hint is distinct from x.n;
  get diagnostics v_counts = row_count;
  return jsonb_build_object('matched', v_matched, 'course_counts', v_counts);
end $$;


ALTER FUNCTION "security"."directory_match_v1"("p_site" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_table_plan_v1"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb") RETURNS TABLE("course_id" "uuid", "course_cricos" "text", "title" "text", "study_level" "text", "plan" "text", "reason" "text", "program" "text", "requirements" "jsonb", "existing" "jsonb", "comparison" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'ref', 'security'
    AS $$
declare v_provider uuid; v_aliases jsonb; v_double text;
begin
  select s.provider_id, coalesce(s.metadata->'aliases','{}'::jsonb), s.metadata->>'double_degree_rule' into v_provider, v_aliases, v_double from pipeline.sources s
   where s.source_type='provider_english_requirements' and s.metadata->>'provider_cricos'=upper(btrim(p_provider_cricos)) limit 1;
  if v_provider is null then raise exception 'no English requirements source for provider %', p_provider_cricos; end if;
  return query
  with t1 as materialized (
    select e->>'name' name, coalesce(e->>'section','coursework') section, e->'requirements' reqs,
           coalesce(v_aliases->>security.english_title_key(e->>'name'), security.english_title_key(e->>'name')) k
      from jsonb_array_elements(coalesce(p_programs,'[]'::jsonb)) e),
  t1t as materialized (select t1.*, security.english_title_tokens(t1.k) tok from t1),
  c as materialized (
    select co.id, co.canonical_title t, security.english_title_key(co.canonical_title) k, sl.code lvl,
           (select min(upper(btrim(cr.registration_code))) from catalogue.course_registrations cr where cr.course_id=co.id and lower(cr.scheme)='cricos') cricos,
           (select coalesce(jsonb_object_agg(et.code, r.overall_score),'{}'::jsonb) from catalogue.course_english_requirements r join ref.english_tests et on et.id=r.english_test_id
             where r.course_id=co.id and r.status='active') ex
      from catalogue.courses co left join ref.study_levels sl on sl.id=co.study_level_id
     where co.provider_id=v_provider and co.lifecycle_status='active'),
  ct as materialized (select c.*, security.english_title_tokens(c.k) tok from c),
  m as materialized (
    select ct.*,
           (select jsonb_agg(jsonb_build_object('name',t1.name,'reqs',t1.reqs)) from t1 where t1.k=ct.k) exact,
           exists(select 1 from t1t where t1t.k<>ct.k and (position(t1t.k in ct.k)>0
                  or (select count(*) from unnest(ct.tok) u where u = any(t1t.tok))::numeric / nullif(greatest(cardinality(ct.tok),cardinality(t1t.tok)),0) >= 0.75)) close
      from ct),
  p as materialized (
    select m.*,
      case when m.exact is not null and (select count(distinct x->'reqs') from jsonb_array_elements(m.exact) x)>1 then 'held'
           when m.exact is not null then 'table1'
           when m.lvl='non_aqf_award' or m.lvl is null then 'held'
           when m.t ~* 'exit award' then 'held'
           when m.lvl in ('doctorate','masters_research') then 'held'
           when m.k ~ '/' or m.k ~ ' and (bachelor|master|doctor|graduate|diploma|associate) (of|in) ' then 'held'
           when m.close then 'held'
           else 'minimum' end pl,
      case when m.exact is not null and (select count(distinct x->'reqs') from jsonb_array_elements(m.exact) x)>1 then 'conflicting Table 1 entries for one name'
           when m.exact is not null then null
           when m.lvl is null then 'study level unknown'
           when m.lvl='non_aqf_award' then 'not an award program'
           when m.t ~* 'exit award' then 'exit award only: not an admission program'
           when m.lvl in ('doctorate','masters_research') then 'research degree: Table 1 research rule is not tied to a named program'
           when m.k ~ '/' or m.k ~ ' and (bachelor|master|doctor|graduate|diploma|associate) (of|in) ' then 'double degree: the policy has no double-degree rule'
           when m.close then 'close to a Table 1 program name: review'
           else null end rs
      from m),
  dd as materialized (
    select p.id, comp.ord, btrim(comp.c) c,
           (select t1.reqs from t1 where t1.k=btrim(comp.c) limit 1) t1reqs,
           (select t1.name from t1 where t1.k=btrim(comp.c) limit 1) t1name,
           exists(select 1 from p p2 where p2.k=btrim(comp.c) and p2.pl='minimum') single_min
      from p, regexp_split_to_table(p.k,'/| and (?=(bachelor|master|doctor|graduate|diploma|associate) (of|in) )') with ordinality comp(c,ord)
     where p.rs='double degree: the policy has no double-degree rule'),
  ddr as materialized (
    select dd.id,
           bool_and(dd.t1reqs is not null or dd.single_min) all_known,
           string_agg(dd.c,'; ' order by dd.ord) filter (where dd.t1reqs is null and not dd.single_min) unknown,
           count(distinct dd.t1reqs) n_t1,
           (array_agg(dd.t1reqs order by dd.ord) filter (where dd.t1reqs is not null))[1] reqs,
           string_agg(dd.t1name,' + ' order by dd.ord) filter (where dd.t1name is not null) t1names
      from dd group by dd.id),
  q as materialized (
    select p.*,
      case when ddr.id is null then p.pl
           when not ddr.all_known or ddr.n_t1>1 then 'held'
           when v_double='higher_component_v1' then case when ddr.n_t1=1 then 'table1' else 'minimum' end
           else 'held' end pl2,
      case when ddr.id is null then p.rs
           when not ddr.all_known then 'double degree: component not recognised ('||ddr.unknown||')'
           when ddr.n_t1>1 then 'double degree: components carry different Table 1 requirements'
           when v_double='higher_component_v1' then 'double degree: higher component ('||case when ddr.n_t1=1 then 'Table 1: '||ddr.t1names else 'minimum' end||')'
           else 'double degree trial: would take '||case when ddr.n_t1=1 then 'Table 1 ('||ddr.t1names||')' else 'the minimum' end end rs2,
      case when ddr.id is null then case when p.pl='table1' then p.exact->0->>'name' end
           when ddr.all_known and ddr.n_t1=1 then ddr.t1names end prog2,
      case when ddr.id is null then case when p.pl='table1' then p.exact->0->'reqs' when p.pl='minimum' then p_minimum end
           when ddr.all_known and ddr.n_t1<=1 then coalesce(ddr.reqs,p_minimum) end reqs2
      from p left join ddr on ddr.id=p.id)
  select q.id, q.cricos, q.t, q.lvl, q.pl2, q.rs2, q.prog2, q.reqs2, q.ex,
         case when q.reqs2 is null then null
              when q.ex='{}'::jsonb then 'none'
              when exists(select 1 from jsonb_array_elements(q.reqs2) r
                           where q.ex ? (r->>'test_code') and (q.ex->>(r->>'test_code'))::numeric<>(r->>'overall_score')::numeric) then 'differs'
              when exists(select 1 from jsonb_array_elements(q.reqs2) r where q.ex ? (r->>'test_code')) then 'agrees'
              else 'other_tests_only' end
    from q;
end $$;


ALTER FUNCTION "security"."english_table_plan_v1"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_title_key"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select btrim(regexp_replace(regexp_replace(regexp_replace(
           replace(regexp_replace(lower(coalesce(p,'')),'\(\s*\d+\s+units(\s+and\s+\d+\s+units)?\s*\)','','g'),'&',' and '),
           '[^a-z0-9/]+',' ','g'),' ?/ ?','/','g'),'\s+',' ','g'))
$$;


ALTER FUNCTION "security"."english_title_key"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_title_overlap"("a" "text", "b" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  with x as (select distinct t from unnest(regexp_split_to_array(a,'[ /]+')) t where t not in ('of','and','in','the','')),
       y as (select distinct t from unnest(regexp_split_to_array(b,'[ /]+')) t where t not in ('of','and','in','the',''))
  select coalesce((select count(*) from x join y using (t))::numeric / nullif(greatest((select count(*) from x),(select count(*) from y)),0),0)
$$;


ALTER FUNCTION "security"."english_title_overlap"("a" "text", "b" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_title_tokens"("p" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(array_agg(distinct t),'{}') from unnest(regexp_split_to_array(coalesce(p,''),'[ /]+')) t where t not in ('of','and','in','the','')
$$;


ALTER FUNCTION "security"."english_title_tokens"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."evidence_row_entity_links"("p_table" "text", "p_row" "jsonb") RETURNS TABLE("entity_type" "text", "entity_id" "uuid", "provider_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'scholarship'
    AS $$
declare v_course uuid; v_provider uuid; v_campus uuid; v_scholarship uuid;
begin
  v_course:=nullif(p_row->>'course_id','')::uuid; v_provider:=nullif(p_row->>'provider_id','')::uuid; v_campus:=nullif(p_row->>'campus_id','')::uuid; v_scholarship:=nullif(p_row->>'scholarship_id','')::uuid;
  if p_table='catalogue.campuses' then return query select 'campus'::text,nullif(p_row->>'id','')::uuid,v_provider; return;
  elsif p_table='catalogue.provider_associations' then return query select 'provider'::text,nullif(p_row->>'from_provider_id','')::uuid,nullif(p_row->>'from_provider_id','')::uuid; return query select 'provider'::text,nullif(p_row->>'to_provider_id','')::uuid,nullif(p_row->>'to_provider_id','')::uuid; return;
  elsif p_table like 'catalogue.provider_%' then if v_provider is not null then return query select 'provider'::text,v_provider,v_provider; end if; return;
  elsif p_table='catalogue.student_flow_observations' then if v_course is not null then select c.provider_id into v_provider from catalogue.courses c where c.id=v_course; return query select 'course'::text,v_course,v_provider; elsif v_provider is not null then return query select 'provider'::text,v_provider,v_provider; end if; return;
  elsif p_table like 'catalogue.course_%' then if v_course is not null then if v_provider is null then select c.provider_id into v_provider from catalogue.courses c where c.id=v_course; end if; return query select 'course'::text,v_course,v_provider; end if; if v_campus is not null then return query select 'campus'::text,v_campus,v_provider; end if; return;
  elsif p_table='scholarship.scholarships' then v_scholarship:=nullif(p_row->>'id','')::uuid; if v_scholarship is not null then return query select 'scholarship'::text,v_scholarship,v_provider; end if; return;
  elsif p_table='scholarship.scopes' then if v_scholarship is not null then if v_provider is null then select s.provider_id into v_provider from scholarship.scholarships s where s.id=v_scholarship; end if; return query select 'scholarship'::text,v_scholarship,v_provider; end if; if v_course is not null then select c.provider_id into v_provider from catalogue.courses c where c.id=v_course; return query select 'course'::text,v_course,v_provider; end if; if v_campus is not null then return query select 'campus'::text,v_campus,v_provider; end if; if nullif(p_row->>'provider_id','') is not null then return query select 'provider'::text,nullif(p_row->>'provider_id','')::uuid,nullif(p_row->>'provider_id','')::uuid; end if; return;
  elsif p_table like 'scholarship.%' then if v_scholarship is not null then if v_provider is null then select s.provider_id into v_provider from scholarship.scholarships s where s.id=v_scholarship; end if; return query select 'scholarship'::text,v_scholarship,v_provider; end if; return;
  end if; return;
end $$;


ALTER FUNCTION "security"."evidence_row_entity_links"("p_table" "text", "p_row" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."evidence_row_rejected"("p_row" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select lower(coalesce(p_row->>'status',p_row->>'lifecycle_status',''))='rejected'
$$;


ALTER FUNCTION "security"."evidence_row_rejected"("p_row" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."evidence_row_source_null"("p_table" "text", "p_row" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  return case p_table
    when 'catalogue.course_fees' then (p_row->'amount') is null or jsonb_typeof(p_row->'amount')='null'
    when 'catalogue.course_intakes' then coalesce(p_row->>'intake_label','')='' and (p_row->'intake_year' is null or jsonb_typeof(p_row->'intake_year')='null') and (p_row->'start_date' is null or jsonb_typeof(p_row->'start_date')='null')
    when 'catalogue.course_english_requirements' then (p_row->'overall_score' is null or jsonb_typeof(p_row->'overall_score')='null') and coalesce(p_row->'component_scores','{}'::jsonb)='{}'::jsonb
    when 'catalogue.course_links' then coalesce(p_row->>'url','')=''
    when 'catalogue.course_registrations' then coalesce(p_row->>'registration_code','')=''
    when 'catalogue.course_study_level_observations' then coalesce(p_row->>'source_value','')=''
    when 'catalogue.course_field_observations' then coalesce(p_row->>'source_field_code','')='' and coalesce(p_row->>'source_field_name','')=''
    when 'catalogue.provider_outcomes' then (p_row->'metric_value' is null or jsonb_typeof(p_row->'metric_value')='null')
    when 'catalogue.student_flow_observations' then (p_row->'metric_value' is null or jsonb_typeof(p_row->'metric_value')='null') and coalesce((p_row->>'is_suppressed')::boolean,false)=false
    when 'scholarship.criteria' then (p_row->'value_text' is null or jsonb_typeof(p_row->'value_text')='null') and (p_row->'value_number' is null or jsonb_typeof(p_row->'value_number')='null') and (p_row->'value_codes' is null or jsonb_typeof(p_row->'value_codes')='null') and (p_row->'value_json' is null or jsonb_typeof(p_row->'value_json')='null')
    when 'scholarship.award_tiers' then (p_row->'amount' is null or jsonb_typeof(p_row->'amount')='null') and (p_row->'percentage' is null or jsonb_typeof(p_row->'percentage')='null') and (p_row->'maximum_amount' is null or jsonb_typeof(p_row->'maximum_amount')='null')
    else false
  end;
end
$$;


ALTER FUNCTION "security"."evidence_row_source_null"("p_table" "text", "p_row" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."evidence_storage_dedupe_v1"("p_scope" "text" DEFAULT 'layer1'::"text", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'storage'
    AS $$
declare v_groups int; v_rows int; v_paths int; v_bytes bigint; v_unequal int; v_missing int;
begin
  if p_scope not in ('layer1','layer2') then raise exception 'scope % is not approved', p_scope; end if;
  create temp table if not exists t_dd(source_id uuid, content_hash text, id uuid, path text, sz bigint, created_at timestamptz, keeper_path text) on commit drop;
  truncate t_dd;
  insert into t_dd(source_id,content_hash,id,path,sz,created_at)
  select e.source_id, e.content_hash, e.id, e.storage_path, (o.metadata->>'size')::bigint, e.created_at
    from pipeline.evidence_artifacts e
    join pipeline.sources s on s.id=e.source_id
    left join storage.objects o on o.bucket_id='evidence' and o.name=e.storage_path
   where e.content_hash is not null and e.storage_path is not null and e.storage_path !~ '^[a-z-]+://'
     and ((p_scope='layer1' and s.provider_id is null and e.evidence_type='regulatory_snapshot')
       or (p_scope='layer2' and s.provider_id is not null and e.evidence_type in ('layer2_screenshot','layer2_html_snapshot')));
  create index if not exists t_dd_group on t_dd(source_id,content_hash);
  analyze t_dd;
  -- keeper: the earliest record whose stored object exists
  update t_dd t set keeper_path=k.path from (
    select distinct on (source_id,content_hash) source_id, content_hash, path from t_dd where sz is not null order by source_id, content_hash, created_at, path) k
   where k.source_id=t.source_id and k.content_hash=t.content_hash;
  -- group facts: distinct paths, keeper size, and whether any stored copy differs in size
  create temp table if not exists t_dd_g(source_id uuid, content_hash text, paths int, keeper_sz bigint, sizes int) on commit drop;
  truncate t_dd_g;
  insert into t_dd_g
  select t.source_id, t.content_hash, count(distinct t.path), max(t.sz) filter (where t.path=t.keeper_path), count(distinct t.sz)
    from t_dd t group by 1,2;
  select count(*) into v_unequal from t_dd_g where sizes>1;
  -- only groups with more than one distinct path, a keeper, and one identical size
  delete from t_dd t using t_dd_g g
   where g.source_id=t.source_id and g.content_hash=t.content_hash
     and (t.keeper_path is null or g.paths<2 or g.sizes>1);
  select count(*) into v_missing from t_dd where sz is null and path<>keeper_path;
  select count(distinct (source_id,content_hash)), count(*) filter (where path<>keeper_path), count(distinct path) filter (where path<>keeper_path and sz is not null),
         coalesce(sum(sz) filter (where path<>keeper_path),0)
    into v_groups, v_rows, v_paths, v_bytes from t_dd;
  if p_apply then
    update pipeline.evidence_artifacts e set storage_path=t.keeper_path,
           metadata=coalesce(e.metadata,'{}'::jsonb)||jsonb_build_object('storage_deduplicated_from',t.path,'storage_deduplicated_at',now())
      from t_dd t where t.id=e.id and t.path<>t.keeper_path;
    insert into pipeline.evidence_storage_dedupe_log(path,keeper_path,content_hash,bytes,source_id,scope,repointed_rows)
    select t.path, min(t.keeper_path), min(t.content_hash), max(t.sz), min(t.source_id::text)::uuid, p_scope, count(*)
      from t_dd t where t.path<>t.keeper_path and t.sz is not null
     group by t.path
    on conflict (path) do nothing;
  end if;
  return jsonb_build_object('scope',p_scope,'applied',p_apply,'duplicate_groups',v_groups,'records_repointed',v_rows,'copies_to_remove',v_paths,
    'bytes_to_free',v_bytes,'size_mismatch_groups_skipped',v_unequal,'records_without_object',v_missing);
end $$;


ALTER FUNCTION "security"."evidence_storage_dedupe_v1"("p_scope" "text", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."exit_awards_apply_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v_src uuid; v_hash text; v_fee record; v_itk text[]; v_payload jsonb; v_mode text; v_done int := 0; v_err int := 0; v_last text; v_courses uuid[] := '{}';
begin
  if not exists (select 1 from pipeline.uni_adapters u where u.provider_id = p_provider_id and u.enabled and u.admit and 'exit_awards' = any (u.admit_fields)) then
    return jsonb_build_object('ok', false, 'note', 'exit awards are not admitted for this university'); end if;
  v_src := security.coverage_sweep_source(p_provider_id);
  for r in
    select x.*, pc.course_url parent_url, pc.delivery_mode parent_mode, ch.delivery_mode child_mode
      from pipeline.course_exit_awards x join catalogue.courses pc on pc.id = x.parent_course_id join catalogue.courses ch on ch.id = x.child_course_id and ch.lifecycle_status = 'active'
     where x.provider_id = p_provider_id and x.active and x.evidence_id is not null
       and not security.layer4_entity_or_parent_blocked('course', x.child_course_id, 'operational')
  loop
    begin
      select e.content_hash into v_hash from pipeline.evidence_artifacts e where e.id = r.evidence_id;
      v_payload := jsonb_build_object('course_url', regexp_replace(r.page_url, '#.*$', ''));
      select f.amount, f.fee_year, f.currency_code into v_fee from catalogue.course_fees f
       where f.course_id = r.parent_course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and f.amount > 0
       order by f.fee_year desc nulls last, f.updated_at desc nulls last limit 1;
      if v_fee.amount is not null and not security.uni_adapter_excluded(r.child_course_id, 'fee')
         and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.child_course_id and k.field in ('tuition', 'fee', 'fees'))
         and (select f.amount from catalogue.course_fees f where f.course_id = r.child_course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and coalesce(f.fee_year, 0) = coalesce(v_fee.fee_year, 0) order by f.updated_at desc nulls last limit 1) is distinct from v_fee.amount then
        update catalogue.course_fees set status = 'superseded', updated_at = now() where course_id = r.child_course_id and status = 'active' and fee_type = 'provider_current_tuition' and audience = 'international' and source_id is not null and coalesce(fee_year, 0) = coalesce(v_fee.fee_year, 0) and amount <> v_fee.amount;
        v_payload := v_payload || jsonb_build_object('fee_amount', v_fee.amount, 'fee_year', v_fee.fee_year, 'currency_code', v_fee.currency_code, 'fee_basis', 'annual', 'audience', 'international',
                       'fee_notes', 'Exit award after ' || r.exit_years || ' years of full-time study in the course on this page: annual fee as the course, whole fee ' || round(v_fee.amount * r.exit_years, 2) || ' (annual x ' || r.exit_years || ')');
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url)
          values (r.child_course_id, p_provider_id, 'fee', null, jsonb_build_object('amount', v_fee.amount, 'year', v_fee.fee_year, 'exit_award_of', r.parent_course_id, 'years', r.exit_years, 'whole_fee', round(v_fee.amount * r.exit_years, 2)), r.evidence_id, r.page_url);
      end if;
      v_itk := (select array_agg(distinct i.intake_label order by i.intake_label) from catalogue.course_intakes i where i.course_id = r.parent_course_id and i.status = 'active');
      if v_itk is not null and not security.uni_adapter_excluded(r.child_course_id, 'intakes')
         and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.child_course_id and k.field in ('intakes', 'intake'))
         and (select array_agg(distinct i.intake_label order by i.intake_label) from catalogue.course_intakes i where i.course_id = r.child_course_id and i.status = 'active') is distinct from v_itk then
        update catalogue.course_intakes set status = 'withdrawn' where course_id = r.child_course_id and status = 'active' and source_id is not null and intake_label <> all (v_itk);
        v_payload := v_payload || jsonb_build_object('intakes', (select jsonb_agg(jsonb_build_object('intake_label', m, 'source_intake_key', 'exit-award:' || r.child_course_id || ':' || lower(m))) from unnest(v_itk) m));
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url)
          values (r.child_course_id, p_provider_id, 'intakes', null, jsonb_build_object('months', to_jsonb(v_itk), 'exit_award_of', r.parent_course_id), r.evidence_id, r.page_url);
      end if;
      perform security.coverage_apply_course_v1(r.child_course_id, v_src, r.evidence_id, r.page_url, v_hash, v_payload);
      if not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.child_course_id and k.field in ('course_url', 'official_url')) then
        update catalogue.courses set course_url = regexp_replace(r.page_url, '#.*$', ''), updated_at = now() where id = r.child_course_id and course_url is distinct from regexp_replace(r.page_url, '#.*$', '');
        update catalogue.course_links set status = 'inactive', is_primary = false, updated_at = now() where course_id = r.child_course_id and link_type = 'official_course' and url = r.page_url and r.page_url <> regexp_replace(r.page_url, '#.*$', '');
        update catalogue.course_links set is_primary = (url = regexp_replace(r.page_url, '#.*$', '')), updated_at = now() where course_id = r.child_course_id and link_type = 'official_course' and status = 'active';
      end if;
      v_mode := r.parent_mode;
      if v_mode is not null and r.child_mode is distinct from v_mode and not security.uni_adapter_excluded(r.child_course_id, 'delivery')
         and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.child_course_id and k.field in ('delivery_mode', 'delivery')) then
        update catalogue.courses set delivery_mode = v_mode, updated_at = now() where id = r.child_course_id;
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url)
          values (r.child_course_id, p_provider_id, 'delivery', to_jsonb(r.child_mode), jsonb_build_object('mode', v_mode, 'exit_award_of', r.parent_course_id), r.evidence_id, r.page_url);
      end if;
      update pipeline.course_exit_awards set applied_at = now(), annual_fee = v_fee.amount, fee_year = v_fee.fee_year, total_fee = round(v_fee.amount * r.exit_years, 2) where child_course_id = r.child_course_id;
      v_done := v_done + 1; v_courses := v_courses || r.child_course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if cardinality(v_courses) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;
  return jsonb_build_object('ok', true, 'applied', v_done, 'errors', v_err, 'last_error', v_last);
end $_$;


ALTER FUNCTION "security"."exit_awards_apply_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."exit_awards_apply_v2"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_src uuid; v_hash text; v_fee record; v_itk text[]; v_payload jsonb; v_mode text; v_done int := 0; v_err int := 0; v_skipped int := 0; v_last text; v_courses uuid[] := '{}'; v_af text[];
begin
  select u.admit_fields into v_af from pipeline.uni_adapters u where u.provider_id = p_provider_id and u.enabled and u.admit and 'exit_awards' = any (u.admit_fields);
  if v_af is null then
    return jsonb_build_object('ok', false, 'note', 'exit awards are not admitted for this university'); end if;
  v_src := security.coverage_sweep_source(p_provider_id);
  for r in
    select x.*, pc.course_url parent_url, pc.delivery_mode parent_mode, ch.delivery_mode child_mode
      from pipeline.course_exit_awards x join catalogue.courses pc on pc.id = x.parent_course_id join catalogue.courses ch on ch.id = x.child_course_id and ch.lifecycle_status = 'active'
     where x.provider_id = p_provider_id and x.active and x.evidence_id is not null
       and not security.layer4_entity_or_parent_blocked('course', x.child_course_id, 'operational')
  loop
    if r.register_check = 'fail' and r.set_by <> 'hand' then v_skipped := v_skipped + 1; continue; end if;
    begin
      select e.content_hash into v_hash from pipeline.evidence_artifacts e where e.id = r.evidence_id;
      v_payload := jsonb_build_object('course_url', r.page_url);
      select null::numeric amount, null::int fee_year, null::text currency_code into v_fee;
      if 'fee' = any (v_af) then
        select f.amount, f.fee_year, f.currency_code into v_fee from catalogue.course_fees f
         where f.course_id = r.parent_course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and f.amount > 0
         order by f.fee_year desc nulls last, f.updated_at desc nulls last limit 1;
      end if;
      if v_fee.amount is not null and not security.uni_adapter_excluded(r.child_course_id, 'fee')
         and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.child_course_id and k.field in ('tuition', 'fee', 'fees'))
         and (select f.amount from catalogue.course_fees f where f.course_id = r.child_course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and coalesce(f.fee_year, 0) = coalesce(v_fee.fee_year, 0) order by f.updated_at desc nulls last limit 1) is distinct from v_fee.amount then
        update catalogue.course_fees set status = 'superseded', updated_at = now() where course_id = r.child_course_id and status = 'active' and fee_type = 'provider_current_tuition' and audience = 'international' and source_id is not null and coalesce(fee_year, 0) = coalesce(v_fee.fee_year, 0) and amount <> v_fee.amount;
        v_payload := v_payload || jsonb_build_object('fee_amount', v_fee.amount, 'fee_year', v_fee.fee_year, 'currency_code', v_fee.currency_code, 'fee_basis', 'annual', 'audience', 'international',
                       'fee_notes', case r.link_type when 'nested_award' then 'Award within the course on this page (' || r.exit_years || ' years of full-time study): annual fee as the course, whole fee ' || round(v_fee.amount * r.exit_years, 2) || ' (annual x ' || r.exit_years || ')'
                                    else 'Exit award after ' || r.exit_years || ' years of full-time study in the course on this page: annual fee as the course, whole fee ' || round(v_fee.amount * r.exit_years, 2) || ' (annual x ' || r.exit_years || ')' end);
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url)
          values (r.child_course_id, p_provider_id, 'fee', null, jsonb_build_object('amount', v_fee.amount, 'year', v_fee.fee_year, 'exit_award_of', r.parent_course_id, 'link_type', r.link_type, 'years', r.exit_years, 'whole_fee', round(v_fee.amount * r.exit_years, 2), 'register_check', r.register_check), r.evidence_id, r.page_url);
      end if;
      v_itk := null;
      if 'intakes' = any (v_af) then
        v_itk := (select array_agg(distinct i.intake_label order by i.intake_label) from catalogue.course_intakes i where i.course_id = r.parent_course_id and i.status = 'active');
      end if;
      if v_itk is not null and not security.uni_adapter_excluded(r.child_course_id, 'intakes')
         and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.child_course_id and k.field in ('intakes', 'intake'))
         and (select array_agg(distinct i.intake_label order by i.intake_label) from catalogue.course_intakes i where i.course_id = r.child_course_id and i.status = 'active') is distinct from v_itk then
        update catalogue.course_intakes set status = 'withdrawn' where course_id = r.child_course_id and status = 'active' and source_id is not null and intake_label <> all (v_itk);
        v_payload := v_payload || jsonb_build_object('intakes', (select jsonb_agg(jsonb_build_object('intake_label', m, 'source_intake_key', 'exit-award:' || r.child_course_id || ':' || lower(m))) from unnest(v_itk) m));
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url)
          values (r.child_course_id, p_provider_id, 'intakes', null, jsonb_build_object('months', to_jsonb(v_itk), 'exit_award_of', r.parent_course_id), r.evidence_id, r.page_url);
      end if;
      perform security.coverage_apply_course_v1(r.child_course_id, v_src, r.evidence_id, r.page_url, v_hash, v_payload);
      v_mode := case when 'delivery' = any (v_af) then r.parent_mode end;
      if v_mode is not null and r.child_mode is distinct from v_mode and not security.uni_adapter_excluded(r.child_course_id, 'delivery')
         and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.child_course_id and k.field in ('delivery_mode', 'delivery')) then
        update catalogue.courses set delivery_mode = v_mode, updated_at = now() where id = r.child_course_id;
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url)
          values (r.child_course_id, p_provider_id, 'delivery', to_jsonb(r.child_mode), jsonb_build_object('mode', v_mode, 'exit_award_of', r.parent_course_id), r.evidence_id, r.page_url);
      end if;
      update pipeline.course_exit_awards set applied_at = now(), annual_fee = v_fee.amount, fee_year = v_fee.fee_year, total_fee = round(v_fee.amount * r.exit_years, 2) where child_course_id = r.child_course_id;
      v_done := v_done + 1; v_courses := v_courses || r.child_course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if cardinality(v_courses) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;
  return jsonb_build_object('ok', true, 'applied', v_done, 'skipped_check_failed', v_skipped, 'errors', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "security"."exit_awards_apply_v2"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."exit_awards_detect_v1"("p_provider_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int := 0; r record; m text[]; v_child uuid;
begin
  for r in
    select pg.course_id, pg.url, pg.evidence_id, pg.candidates->'adapter_extra'->>'exit_awards' ex, co.canonical_title
      from pipeline.coverage_course_pages pg join catalogue.courses co on co.id = pg.course_id and co.lifecycle_status = 'active'
     where pg.provider_id = p_provider_id and pg.read_status = 'read' and pg.identity_basis is not null
       and coalesce(pg.candidates->'adapter_extra'->>'exit_awards', '') <> ''
  loop
    for m in select regexp_matches(r.ex, '([0-9](?:\.[0-9])?)\s+years?\s+of\s+full[ -]time\s+study[^|]{0,60}exit\s+with\s+(?:an?\s+)?([A-Z][^|.\n]{4,150})', 'gi') loop
      select co.id into v_child from catalogue.courses co
       where co.provider_id = p_provider_id and co.lifecycle_status = 'active' and co.id <> r.course_id
         and security.course_title_key(co.canonical_title) = security.course_title_key(btrim(m[2]))
       order by co.id limit 1;
      continue when v_child is null or security.course_title_key(m[2]) = security.course_title_key(r.canonical_title);
      insert into pipeline.course_exit_awards(child_course_id, parent_course_id, provider_id, exit_years, page_url, evidence_id, printed, reason)
        values (v_child, r.course_id, p_provider_id, m[1]::numeric, r.url, r.evidence_id, left(m[1] || ' years: ' || btrim(m[2]), 300), 'read from the course page by the adapter')
      on conflict (child_course_id) do update set parent_course_id = excluded.parent_course_id, exit_years = excluded.exit_years, page_url = excluded.page_url, evidence_id = excluded.evidence_id, printed = excluded.printed, set_at = now() where pipeline.course_exit_awards.set_by = 'adapter';
      n := n + 1;
    end loop;
  end loop;
  return n;
end $$;


ALTER FUNCTION "security"."exit_awards_detect_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."exit_awards_detect_v2"("p_provider_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int := 0; r record; m text[]; v_child uuid; v_name text; v_years numeric; v_single uuid; v_chk text[];
begin
  -- A. "After completing N years of full-time study You can exit with a <Award>" (La Trobe wording)
  --    and "<Award> is available as an exit award of this degree" (RMIT wording)
  for r in
    select pg.course_id, pg.url, pg.evidence_id, pg.candidates->'adapter_extra'->>'exit_awards' ex, co.canonical_title
      from pipeline.coverage_course_pages pg join catalogue.courses co on co.id = pg.course_id and co.lifecycle_status = 'active'
     where pg.provider_id = p_provider_id and pg.read_status = 'read' and pg.identity_basis is not null
       and coalesce(pg.candidates->'adapter_extra'->>'exit_awards', '') <> ''
       and not security.is_double_degree_title(co.canonical_title)
  loop
    for m in select regexp_matches(r.ex, '([0-9](?:\.[0-9])?)\s+years?\s+of\s+full[ -]time\s+study[^|]{0,60}exit\s+with\s+(?:an?\s+)?([A-Z][^|.\n]{4,150})', 'gi') loop
      select co.id into v_child from catalogue.courses co
       where co.provider_id = p_provider_id and co.lifecycle_status = 'active' and co.id <> r.course_id
         and security.course_title_key(co.canonical_title) = security.course_title_key(btrim(m[2]))
       order by co.id limit 1;
      continue when v_child is null or security.course_title_key(m[2]) = security.course_title_key(r.canonical_title);
      insert into pipeline.course_exit_awards(child_course_id, parent_course_id, provider_id, exit_years, page_url, evidence_id, printed, reason, link_type)
        values (v_child, r.course_id, p_provider_id, m[1]::numeric, r.url, r.evidence_id, left(m[1] || ' years: ' || btrim(m[2]), 300), 'read from the course page by the adapter', 'exit_award')
      on conflict (child_course_id) do update set parent_course_id = excluded.parent_course_id, exit_years = excluded.exit_years, page_url = excluded.page_url, evidence_id = excluded.evidence_id, printed = excluded.printed, link_type = excluded.link_type, set_at = now() where pipeline.course_exit_awards.set_by = 'adapter';
      n := n + 1;
    end loop;
    for m in select regexp_matches(r.ex, '((?:Graduate|Diploma|Associate|Advanced|Bachelor|Master|Certificate)[^|.\n]{4,200})\s+(?:is|are)\s+available\s+as\s+(?:an?\s+)?exit\s+awards?', 'gi') loop
      foreach v_name in array regexp_split_to_array(m[1], '\s*(?:,|\mand\M)\s*(?=(?:Graduate|Diploma|Associate|Advanced|Bachelor|Master|Certificate))') loop
        v_name := btrim(regexp_replace(v_name, '^(the|a|an)\s+', '', 'i'));
        continue when length(v_name) < 8;
        select co.id into v_child from catalogue.courses co
         where co.provider_id = p_provider_id and co.lifecycle_status = 'active' and co.id <> r.course_id
           and security.course_title_key(co.canonical_title) = security.course_title_key(v_name)
         order by co.id limit 1;
        continue when v_child is null;
        v_years := security.course_full_time_years(v_child);
        continue when v_years is null;
        insert into pipeline.course_exit_awards(child_course_id, parent_course_id, provider_id, exit_years, page_url, evidence_id, printed, reason, link_type)
          values (v_child, r.course_id, p_provider_id, v_years, r.url, r.evidence_id, left(v_name || ' is available as an exit award (' || v_years || ' years from its registered length)', 300), 'read from the course page by the adapter', 'exit_award')
        on conflict (child_course_id) do update set parent_course_id = excluded.parent_course_id, exit_years = excluded.exit_years, page_url = excluded.page_url, evidence_id = excluded.evidence_id, printed = excluded.printed, link_type = excluded.link_type, set_at = now() where pipeline.course_exit_awards.set_by = 'adapter';
        n := n + 1;
      end loop;
    end loop;
  end loop;
  -- B. Nested awards by title: Graduate Certificate/Diploma in X within Master of X, Diploma/Associate Degree/Advanced
  --    Diploma of X within Bachelor of X, where the award has no confirmed page of its own (or sits on the parent's
  --    page or a handbook page) and exactly one single-degree parent with a confirmed page matches.
  for r in
    select ch.id child_id, ch.canonical_title child_title,
           (select array_agg(pc.id) from catalogue.courses pc join pipeline.coverage_course_pages pp on pp.course_id = pc.id and pp.read_status = 'read' and pp.identity_basis is not null
             where pc.provider_id = p_provider_id and pc.lifecycle_status = 'active' and pc.id <> ch.id and not security.is_double_degree_title(pc.canonical_title)
               and security.course_title_key(pc.canonical_title) = security.course_title_key(
                     case when sl.code in ('graduate_certificate', 'graduate_diploma') then regexp_replace(ch.canonical_title, '^Graduate (Certificate|Diploma) (in|of) ', 'Master of ', 'i')
                          else regexp_replace(ch.canonical_title, '^(Diploma|Associate Degree|Advanced Diploma) (in|of) ', 'Bachelor of ', 'i') end)) parents
      from catalogue.courses ch join ref.study_levels sl on sl.id = ch.study_level_id
      left join pipeline.coverage_course_pages pg on pg.course_id = ch.id
     where ch.provider_id = p_provider_id and ch.lifecycle_status = 'active'
       and sl.code in ('graduate_certificate', 'graduate_diploma', 'diploma', 'associate_degree', 'advanced_diploma')
       and (pg.course_id is null or pg.read_status is distinct from 'read' or pg.identity_basis is null or pg.url ~* 'handbook'
            or exists (select 1 from pipeline.coverage_course_pages p2 where p2.url = pg.url and p2.course_id <> ch.id and p2.identity_basis is not null))
       and not exists (select 1 from pipeline.course_exit_awards x where x.child_course_id = ch.id and x.set_by = 'hand')
  loop
    continue when r.parents is null or cardinality(r.parents) <> 1;
    v_single := r.parents[1];
    v_years := security.course_full_time_years(r.child_id);
    continue when v_years is null;
    insert into pipeline.course_exit_awards(child_course_id, parent_course_id, provider_id, exit_years, page_url, evidence_id, printed, reason, link_type)
      select r.child_id, v_single, p_provider_id, v_years, pg.url, pg.evidence_id, left(r.child_title || ' within ' || pc.canonical_title || ' (title match, ' || v_years || ' years from its registered length)', 300), 'matched by title to the parent course', 'nested_award'
        from pipeline.coverage_course_pages pg join catalogue.courses pc on pc.id = pg.course_id where pg.course_id = v_single
    on conflict (child_course_id) do update set parent_course_id = excluded.parent_course_id, exit_years = excluded.exit_years, page_url = excluded.page_url, evidence_id = excluded.evidence_id, printed = excluded.printed, link_type = excluded.link_type, set_at = now() where pipeline.course_exit_awards.set_by = 'adapter' and pipeline.course_exit_awards.link_type = 'nested_award';
    n := n + 1;
  end loop;
  -- C. Adapter links whose parent is a double degree move to the single degree with the same title, when it has a
  --    confirmed page.
  for r in
    select x.child_course_id, x.parent_course_id, pc.canonical_title ptitle
      from pipeline.course_exit_awards x join catalogue.courses pc on pc.id = x.parent_course_id
     where x.provider_id = p_provider_id and x.set_by = 'adapter' and security.is_double_degree_title(pc.canonical_title)
  loop
    v_single := null;
    for v_name in select btrim(s) from unnest(regexp_split_to_array(r.ptitle, '\s*(?:/| and (?=Bachelor|Master|Diploma))\s*')) s loop
      select pc.id into v_single from catalogue.courses pc join pipeline.coverage_course_pages pp on pp.course_id = pc.id and pp.read_status = 'read' and pp.identity_basis is not null
       where pc.provider_id = p_provider_id and pc.lifecycle_status = 'active' and not security.is_double_degree_title(pc.canonical_title)
         and security.course_title_key(pc.canonical_title) = security.course_title_key(v_name)
         and position(security.course_title_key(regexp_replace((select canonical_title from catalogue.courses where id = r.child_course_id), '^[A-Za-z ]+ (in|of) ', '')) in security.course_title_key(pc.canonical_title)) > 0
       order by pc.id limit 1;
      exit when v_single is not null;
    end loop;
    if v_single is not null then
      update pipeline.course_exit_awards x set parent_course_id = v_single, page_url = pp.url, evidence_id = pp.evidence_id, set_at = now(), check_detail = 'moved from the double degree to its single degree' from pipeline.coverage_course_pages pp where pp.course_id = v_single and x.child_course_id = r.child_course_id;
    end if;
  end loop;
  -- D. Register check on every link of this university (hand links are checked too, never changed).
  for r in select x.child_course_id, x.parent_course_id, x.check_detail from pipeline.course_exit_awards x where x.provider_id = p_provider_id loop
    v_chk := security.award_register_check(r.child_course_id, r.parent_course_id);
    update pipeline.course_exit_awards set register_check = v_chk[1], check_detail = case when r.check_detail like 'moved from%' then r.check_detail || ' / ' || v_chk[2] else v_chk[2] end where child_course_id = r.child_course_id;
  end loop;
  return n;
end $$;


ALTER FUNCTION "security"."exit_awards_detect_v2"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."exit_awards_hourly_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u record; v jsonb := '[]'::jsonb;
begin
  for u in select a.provider_id from pipeline.uni_adapters a where a.enabled and a.admit and 'exit_awards' = any (a.admit_fields) loop
    v := v || jsonb_build_array(jsonb_build_object('provider_id', u.provider_id, 'found', security.exit_awards_detect_v2(u.provider_id), 'apply', security.exit_awards_apply_v2(u.provider_id)));
  end loop;
  return v;
end $$;


ALTER FUNCTION "security"."exit_awards_hourly_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_evidence_own_site_v1"("p_evidence_id" "uuid", "p_course_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when ea.id is null then false
              when h is null then true
              when not (h = any(security.l4_shared_hosts_v1())) then true
              else coalesce(h = ph or h like '%.' || ph, false) end
    from (select 1) one
    left join pipeline.evidence_artifacts ea on ea.id = p_evidence_id
    left join lateral (select substring(ea.source_url from '^https?://(?:www\.)?([^/:?#]+)') h) a on true
    left join lateral (select substring(p.website from '^https?://(?:www\.)?([^/:?#]+)') ph
                         from catalogue.courses c join catalogue.providers p on p.id = c.provider_id where c.id = p_course_id) b on true
$$;


ALTER FUNCTION "security"."fee_evidence_own_site_v1"("p_evidence_id" "uuid", "p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_period_settle_v1"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_rule text; v_quote text; v_wording int := 0; v_short int := 0; v_left int := 0; v_ids uuid[] := '{}';
  yr constant text := '(per\s+(year|annum|academic\s+year)|a\s+year\M|\mannual(ly)?\M|\myearly\M|\m1\s*(yr|year)\M|\mone\s+year\M|\m(first|1st)[- ]year\M|\mp\.?a\.?\M|/\s*(year|yr)\M|each\s+year|full[- ]time\s+year)';
  other constant text := '(per\s+(semester|trimester|term|unit|subject|credit|study\s+period|session)|\m(semester|trimester)s?\M|\mtotal\M|\m(whole|entire|full)\s+(course|program|programme|degree)\M)';
begin
  if current_user not in ('postgres', 'service_role') and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required' using errcode = '42501'; end if;
  for r in select fl.id, fl.entity_id, fl.record_id, coalesce(fl.detail->>'quotes', '') q, c.duration_value dv, lower(coalesce(c.duration_unit, '')) du
             from pipeline.data_flags fl join catalogue.courses c on c.id = fl.entity_id
             join catalogue.course_fees fe on fe.id = fl.record_id and fe.status = 'active'
            where fl.status = 'open' and fl.flag_code = 'tuition_period_assumed_annual'
            order by fl.created_at limit greatest(1, least(coalesce(p_limit, 500), 2000))
            for update of fl skip locked loop
    v_rule := null; v_quote := null;
    if r.q ~* other then v_left := v_left + 1; continue; end if;
    if r.q ~* yr then v_rule := 'per_year_wording'; v_quote := substring(r.q from '(?i)([^"]{0,80}' || yr || '[^"]{0,40})');
    elsif (r.du in ('week', 'weeks') and r.dv <= 52) or (r.du in ('month', 'months') and r.dv <= 12) or (r.du in ('year', 'years') and r.dv <= 1) then
      v_rule := 'course_one_year_or_less';
    end if;
    if v_rule is null then v_left := v_left + 1; continue; end if;
    update catalogue.course_fees set last_verified_at = now(), updated_at = now(),
           notes = coalesce(notes, '') || case v_rule when 'per_year_wording' then ' | period confirmed per year from the page wording (automatic check, Decision 218)'
                                                 else ' | course runs a year or less, so per year equals the whole course (automatic check, Decision 218)' end
     where id = r.record_id;
    update pipeline.data_flags set status = 'confirmed', resolved_at = now(), resolved_by = null,
           resolution = jsonb_build_object('action', 'confirm', 'by', 'automatic period check', 'rule', v_rule, 'quote', v_quote,
                                           'duration', case when v_rule = 'course_one_year_or_less' then r.dv || ' ' || r.du end, 'decision', 'Decision 218')
     where id = r.id;
    if v_rule = 'per_year_wording' then v_wording := v_wording + 1; else v_short := v_short + 1; end if;
    v_ids := v_ids || r.entity_id;
  end loop;
  if cardinality(v_ids) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_ids, true); end if;
  return jsonb_build_object('confirmed_by_wording', v_wording, 'confirmed_short_course', v_short, 'left_for_a_person', v_left);
end $$;


ALTER FUNCTION "security"."fee_period_settle_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_rule_matches"("p_provider_id" "uuid", "p_phrase" "text", "p_url_pattern" "text" DEFAULT NULL::"text") RETURNS TABLE("course_id" "uuid", "evidence_id" "uuid", "url" "text", "amount" numeric, "fee_year" integer, "matched_text" "text", "amounts" integer, "has_fee" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  with q as (select regexp_replace(btrim(p_phrase), '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') ph),
  m as (
    select g.course_id, g.evidence_id, g.url, x.ctx, q.ph,
           regexp_match(x.ctx, '(?i)' || q.ph || '((?:[^$0-9]|20[2-3][0-9]){0,30}?)(?:A\$|AUD\s*\$?|\$)\s*([0-9]{1,3}(?:,[0-9]{3})+|[0-9]{4,6})(?![0-9]|,[0-9])') mm
      from q, pipeline.coverage_course_pages g
      cross join lateral (select distinct c->>'context' ctx from jsonb_array_elements(coalesce(g.candidates->'fee'->'candidates', '[]'::jsonb)) c) x
     where g.provider_id = p_provider_id and g.read_status = 'read' and g.identity_basis in ('cricos_code','manual') and g.evidence_id is not null
       and (p_url_pattern is null or g.url ~* p_url_pattern)),
  hit as (select *, coalesce(substring(mm[1] from '(20[2-3][0-9])'), substring(ctx from '(?i)(20[2-3][0-9])[^0-9$]{0,6}' || ph))::int yr from m where mm is not null)
  select h.course_id, min(h.evidence_id::text)::uuid, min(h.url),
         min(replace(h.mm[2], ',', '')::numeric), min(h.yr),
         min(left(btrim(coalesce(h.yr::text || ' ', '') || btrim(p_phrase) || h.mm[1] || '$' || h.mm[2]), 200)),
         count(distinct h.mm[2])::int,
         exists (select 1 from catalogue.course_fees f where f.course_id = h.course_id and f.fee_type = 'provider_current_tuition' and f.status = 'active')
    from hit h group by h.course_id
$_$;


ALTER FUNCTION "security"."fee_rule_matches"("p_provider_id" "uuid", "p_phrase" "text", "p_url_pattern" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_rule_run_v1"("p_rule_id" bigint, "p_apply" boolean, "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.fee_wording_rules%rowtype; m record; v_src uuid; v_fee uuid; n_ok int := 0; n_amb int := 0; n_has int := 0; n_locked int := 0;
        v_courses uuid[] := '{}'; v_op bigint;
begin
  select * into r from pipeline.fee_wording_rules where id = p_rule_id;
  if r.id is null then raise exception 'rule not found'; end if;
  for m in select * from security.fee_rule_matches(r.provider_id, r.phrase, r.url_pattern) loop
    if m.amounts > 1 then n_amb := n_amb + 1; continue; end if;
    if m.has_fee then n_has := n_has + 1; continue; end if;
    if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = m.course_id and l.field = 'tuition') then n_locked := n_locked + 1; continue; end if;
    if not p_apply then n_ok := n_ok + 1; continue; end if;
    select source_id into v_src from pipeline.evidence_artifacts where id = m.evidence_id;
    v_fee := null;
    insert into catalogue.course_fees(course_id, fee_year, audience, fee_type, amount, currency_code, basis, notes, source_id, evidence_id, confidence, source_fee_key, status, last_verified_at, source_snapshot_at, updated_at)
    values (m.course_id, m.fee_year, 'international', 'provider_current_tuition', m.amount, 'AUD', r.basis,
            format('CF-247 Layer 4 fee wording rule #%s (%s)', r.id, r.label), v_src, m.evidence_id, 1,
            'fee-rule:' || r.id || ':' || coalesce(m.fee_year::text, '') || ':' || r.basis, 'active', now(), now(), now())
    on conflict (course_id, source_id, source_fee_key) where source_id is not null and source_fee_key is not null do nothing
    returning id into v_fee;
    if v_fee is null then n_has := n_has + 1; continue; end if;
    update pipeline.layer4_review_items set status = 'superseded', decided_at = now(),
           escalation_reason = format('Settled by Layer 4 fee wording rule #%s (%s)', r.id, r.label)
     where entity_type = 'course' and entity_id = m.course_id and field_code = 'provider_current_tuition_validation' and status in ('pending','returned_layer3');
    update pipeline.layer3_work_items set status = 'admitted', completed_at = now(), last_error = null, updated_at = now()
     where entity_id = m.course_id and task_class = 'provider_current_tuition_validation' and status in ('pending','layer4_required','failed','no_candidate','rejected');
    insert into pipeline.fee_rule_admissions(rule_id, course_id, course_fee_id, amount, fee_year, basis, matched_text)
    values (r.id, m.course_id, v_fee, m.amount, m.fee_year, r.basis, m.matched_text);
    v_courses := v_courses || m.course_id; n_ok := n_ok + 1;
  end loop;
  if p_apply then
    update pipeline.fee_wording_rules set last_run_at = now(), admitted = admitted + n_ok where id = r.id;
    if n_ok > 0 then
      insert into pipeline.layer4_mass_operations(target_kind, action, actor_id, group_key, reason, before_count, affected_count, result, change_control_ref)
      values ('course_tuition', 'fee_wording_rule_run', coalesce(p_actor, r.approved_by, r.created_by), jsonb_build_object('rule_id', r.id, 'provider_id', r.provider_id, 'phrase', r.phrase),
              format('Fee wording rule #%s: %s', r.id, r.label), n_ok + n_amb + n_has + n_locked, n_ok,
              jsonb_build_object('admitted', n_ok, 'ambiguous', n_amb, 'already_had_fee', n_has, 'entered_by_hand', n_locked), 'CF-CHG-20260915-247');
      perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
    end if;
  end if;
  return jsonb_build_object('mode', case when p_apply then 'run' else 'preview' end, 'admitted', n_ok, 'ambiguous', n_amb, 'already_had_fee', n_has, 'entered_by_hand', n_locked);
end $$;


