CREATE OR REPLACE FUNCTION "security"."fee_schedule_settle_flags_v1"("p_source_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_same int := 0; v_period int := 0; v_courses uuid[] := '{}';
begin
  for r in
    with sched as (
      select fr.provider_id, fr.course_code, fr.amount, fr.fee_year, s.id source_id,
             min(fr.amount) over (partition by fr.source_id, fr.course_code) amin, max(fr.amount) over (partition by fr.source_id, fr.course_code) amax,
             row_number() over (partition by fr.provider_id, fr.course_code order by fr.fee_year desc nulls last, s.decided_at desc) pick
        from pipeline.provider_fee_rows fr join pipeline.provider_fact_sources s on s.id = fr.source_id
       where s.decision = 'approved' and fr.current and fr.basis = 'annual' and (p_source_id is null or s.id = p_source_id))
    select f.id flag_id, f.entity_id course_id, fe.id fee_id, fe.amount, sc.amount sched_amount, sc.fee_year, sc.source_id
      from pipeline.data_flags f
      join catalogue.course_fees fe on fe.id = f.record_id and fe.status = 'active'
      join catalogue.courses c on c.id = f.entity_id
      join sched sc on sc.provider_id = c.provider_id and sc.course_code = upper(btrim(c.course_code)) and sc.pick = 1 and sc.amin = sc.amax
     where f.status = 'open' and f.flag_code = 'tuition_period_assumed_annual'
     for update of f
  loop
   begin
    if r.amount = r.sched_amount then
      update catalogue.course_fees set fee_year = coalesce(fee_year, r.fee_year), last_verified_at = now(), updated_at = now(),
             notes = coalesce(notes, '') || format(' | per year confirmed by the approved fee schedule (%s) %s', coalesce(r.fee_year::text, 'year not stated'), to_char(now(), 'DD Mon YYYY'))
       where id = r.fee_id;
      update pipeline.data_flags set status = 'confirmed', resolved_at = now(),
             resolution = jsonb_build_object('action', 'confirmed_by_fee_schedule', 'source_id', r.source_id, 'fee_year', r.fee_year, 'schedule_amount', r.sched_amount)
       where id = r.flag_id;
      v_same := v_same + 1; v_courses := v_courses || r.course_id;
    elsif r.amount > 0 and r.sched_amount / r.amount between 0.85 and 1.15 then
      update catalogue.course_fees set last_verified_at = now(), updated_at = now(),
             notes = coalesce(notes, '') || format(' | per year supported by the approved fee schedule (%s a year in %s) %s', r.sched_amount, coalesce(r.fee_year::text, 'year not stated'), to_char(now(), 'DD Mon YYYY'))
       where id = r.fee_id;
      update pipeline.data_flags set status = 'confirmed', resolved_at = now(),
             resolution = jsonb_build_object('action', 'period_confirmed_by_fee_schedule', 'source_id', r.source_id, 'fee_year', r.fee_year, 'schedule_amount', r.sched_amount)
       where id = r.flag_id;
      v_period := v_period + 1; v_courses := v_courses || r.course_id;
    end if;
   exception when others then null; -- a value locked by hand is left for a person
   end;
  end loop;
  if cardinality(v_courses) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;
  return jsonb_build_object('confirmed_same_fee', v_same, 'confirmed_period', v_period);
end $$;


ALTER FUNCTION "security"."fee_schedule_settle_flags_v1"("p_source_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_suggest_phrase"("p_ctx" "text", "p_amount" numeric) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare a text := to_char(p_amount, 'FM999,999,999'); p int; pre text; tail text;
begin
  p := strpos(coalesce(p_ctx, ''), a);
  if p = 0 then return null; end if;
  pre := left(p_ctx, p - 1);
  pre := regexp_replace(pre, '(A\$|AUD\s*\$?|\$)\s*$', '');
  pre := regexp_replace(pre, '[\s:*>-]*$', '');
  pre := regexp_replace(pre, '\s*(20[2-3][0-9])(\s+(are|is))?$', '');
  tail := right(pre, 60);
  if tail ~ '20[2-3][0-9]' then tail := regexp_replace(tail, '^.*20[2-3][0-9]\s*', ''); else tail := regexp_replace(tail, '^\S*\s+', ''); end if;
  if position('. ' in tail) > 0 and length(regexp_replace(tail, '^.*\.\s+', '')) >= 12 then tail := regexp_replace(tail, '^.*\.\s+', ''); end if;
  tail := btrim(regexp_replace(tail, '\s+', ' ', 'g'));
  if length(tail) < 8 or tail !~ '[A-Za-z]{3}' then return null; end if;
  return tail;
end $_$;


ALTER FUNCTION "security"."fee_suggest_phrase"("p_ctx" "text", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."firecrawl_backlog_v1"("p_use_case" "text") RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "country" "text", "url" "text", "input" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_statuses text[]; v_retry boolean; v_like text; v_skip text;
begin
  select coalesce(array_agg(e), '{}') into v_statuses from jsonb_array_elements_text(coalesce(security.firecrawl_setting('read_statuses'), '[]'::jsonb)) e;
  v_retry := coalesce((security.firecrawl_setting('find_retry_refused') #>> '{}')::boolean, false);
  v_like := coalesce(nullif(btrim(security.firecrawl_setting('read_url_pattern') #>> '{}'), ''), '.');
  v_skip := nullif(btrim(coalesce(security.firecrawl_setting('read_skip_url_pattern') #>> '{}', '')), '');
  if p_use_case = 'read_page' then
    return query
    select pg.course_id, pg.provider_id, t.country, pg.url,
           jsonb_build_object('course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'page_status', pg.status, 'earlier_read', pg.read_status, 'earlier_http', pg.http_status)
    from security.firecrawl_targets_fast() t
    join pipeline.coverage_course_pages pg on pg.provider_id = t.provider_id
    join catalogue.courses c on c.id = pg.course_id
    where t.included and c.lifecycle_status = 'active' and pg.status in ('bound', 'ambiguous') and pg.read_status = any(v_statuses)
      and pg.url is not null and coalesce(pg.http_status, 0) not in (404, 410) and pg.evidence_id is null
      and pg.url ~* v_like and (v_skip is null or pg.url !~* v_skip);
  elsif p_use_case = 'find_page' then
    return query
    select c.id, t.provider_id, t.country, null::text,
           jsonb_build_object('course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'provider', t.name, 'domain', t.domain,
                              'earlier_url', pg.url, 'earlier_status', pg.status,
                              'refind', coalesce(pg.status in ('bound', 'ambiguous'), false))
    from security.firecrawl_targets_fast() t
    join catalogue.courses c on c.provider_id = t.provider_id
    left join pipeline.coverage_course_pages pg on pg.course_id = c.id
    where t.included and t.domain is not null and c.lifecycle_status = 'active'
      and (pg.course_id is null or pg.status not in ('bound', 'ambiguous')
           or (pg.read_status = any(v_statuses) and pg.evidence_id is null and (pg.url !~* v_like or (v_skip is not null and pg.url ~* v_skip))))
      and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field = 'official_url')
      and (pg.read_status is not distinct from 'refused_host'
           or not exists (select 1 from pipeline.search_pass_links l where l.course_id = c.id and (l.state in ('found', 'verified') or (l.state = 'none' and not v_retry))));
  end if;
end $$;


ALTER FUNCTION "security"."firecrawl_backlog_v1"("p_use_case" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."firecrawl_credit_observe_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v jsonb; n int := 0; fc jsonb := public.svc_coverage_firecrawl(); v_pid uuid; v_req bigint;
begin
  for r in select q.req_id, q.provider_id, x.status_code, x.content from pipeline.vendor_credit_requests q
             join net._http_response x on x.id = q.req_id where not q.collected loop
    update pipeline.vendor_credit_requests set collected = true where req_id = r.req_id;
    begin v := r.content::jsonb; exception when others then v := null; end;
    if r.status_code = 200 and (v->'data'->>'remaining_credits') ~ '^[0-9]+(\.[0-9]+)?$' then
      insert into pipeline.vendor_credit_observations(provider_id, remaining_units, plan_units, period_end, raw)
      values (r.provider_id, (v->'data'->>'remaining_credits')::numeric, nullif(v->'data'->>'plan_credits', '')::numeric,
              nullif(v->'data'->>'billing_period_end', '')::timestamptz, v->'data');
      n := n + 1;
    end if;
  end loop;
  update pipeline.vendor_credit_requests set collected = true where not collected and sent_at < now() - interval '30 minutes';
  v_pid := nullif(fc->'budget_status'->>'provider_id', '')::uuid;
  if v_pid is not null and fc->>'secret' is not null then
    v_req := net.http_get(url := 'https://api.firecrawl.dev/v1/team/credit-usage',
               headers := jsonb_build_object('Authorization', 'Bearer ' || (fc->>'secret')), timeout_milliseconds := 30000);
    insert into pipeline.vendor_credit_requests(req_id, provider_id) values (v_req, v_pid);
  end if;
  return jsonb_build_object('collected', n, 'sent', v_req);
end $_$;


ALTER FUNCTION "security"."firecrawl_credit_observe_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."firecrawl_panel_refresh_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  with c as (
    select t.provider_id, jsonb_build_object('courses', count(*),
           'confirmed', count(*) filter (where pg.status = 'bound' and pg.read_status = 'read' and pg.identity_basis is not null),
           'unreadable', count(*) filter (where pg.status in ('bound', 'ambiguous') and pg.read_status in ('needs_render', 'blocked', 'fetch_failed', 'too_thin', 'robots_disallowed')),
           'no_page', count(*) filter (where pg.course_id is null or pg.status not in ('bound', 'ambiguous')),
           'adapter_confirmed', count(*) filter (where pg.read_status = 'read' and pg.identity_basis in ('adapter_code', 'adapter_title')),
           'waiting_read', count(*) filter (where pg.status = 'bound' and (pg.read_status is null or pg.read_status = 'needs_render')),
           'intakes', count(*) filter (where exists (select 1 from catalogue.course_intakes i where i.course_id = cc.id and coalesce(i.status, 'active') = 'active')),
           'english', count(*) filter (where exists (select 1 from catalogue.course_english_requirements e where e.course_id = cc.id and coalesce(e.status, 'active') = 'active')),
           'any_fee', count(*) filter (where exists (select 1 from catalogue.course_fees f where f.course_id = cc.id and coalesce(f.audience, '') ~* 'int'))) s
    from pipeline.firecrawl_target_cache t join catalogue.courses cc on cc.provider_id = t.provider_id and cc.lifecycle_status = 'active'
    left join pipeline.coverage_course_pages pg on pg.course_id = cc.id
    where t.name is not null
    group by t.provider_id
  )
  update pipeline.firecrawl_target_cache t set stats = c.s, stats_at = now() from c where c.provider_id = t.provider_id;
  get diagnostics n = row_count;
  insert into pipeline.firecrawl_panel_figures(id, backlog, refreshed_at)
    values (1, jsonb_build_object('read_page', (select count(*) from security.firecrawl_backlog_v1('read_page')), 'find_page', (select count(*) from security.firecrawl_backlog_v1('find_page'))), now())
  on conflict (id) do update set backlog = excluded.backlog, refreshed_at = now() where pipeline.firecrawl_panel_figures.id = 1;
  return n;
end $$;


