CREATE OR REPLACE FUNCTION "security"."firecrawl_targets_v1"() RETURNS TABLE("provider_id" "uuid", "country" "text", "name" "text", "courses" integer, "rule_match" boolean, "included" boolean, "override_reason" "text", "domain" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_countries text[]; v_pat text; v_excl text; v_regs text[]; v_min jsonb := '{}'::jsonb; x text;
begin
  select coalesce(array_agg(upper(btrim(e))), '{}') into v_countries from jsonb_array_elements_text(coalesce(security.firecrawl_setting('target_countries'), '[]'::jsonb)) e;
  v_pat := coalesce(security.firecrawl_setting('target_name_pattern') #>> '{}', '(^|[^a-z])universit(y|ies)([^a-z]|$)');
  v_excl := nullif(btrim(coalesce(security.firecrawl_setting('target_exclude_pattern') #>> '{}', '')), '');
  select coalesce(array_agg(lower(btrim(e))), '{}') into v_regs from jsonb_array_elements_text(coalesce(security.firecrawl_setting('target_registers'), '[]'::jsonb)) e;
  for x in select jsonb_array_elements_text(coalesce(security.firecrawl_setting('target_min_courses'), '[]'::jsonb)) loop
    if x ~ '^\s*[A-Za-z]{2}\s*:\s*[0-9]+\s*$' then v_min := v_min || jsonb_build_object(upper(btrim(split_part(x, ':', 1))), btrim(split_part(x, ':', 2))::int); end if;
  end loop;
  return query
  with cand as (
    select p.id, k.iso_alpha2::text cc, coalesce(p.display_name, p.canonical_name) nm, p.website, p.enrols_international,
           (select count(*)::int from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active') n,
           t.included ov, t.reason ovr
    from catalogue.providers p join ref.countries k on k.id = p.country_id
    left join pipeline.firecrawl_targets t on t.provider_id = p.id
    where t.provider_id is not null or (k.iso_alpha2 = any(v_countries) and coalesce(p.display_name, p.canonical_name) ~* v_pat)
  ), ruled as (
    select c.*, (c.cc = any(v_countries) and c.nm ~* v_pat and (v_excl is null or c.nm !~* v_excl)
                 and c.n >= coalesce((v_min->>c.cc)::int, 0)
                 and (c.enrols_international is true or exists (select 1 from catalogue.provider_registrations r where r.provider_id = c.id and lower(r.registration_scheme) = any(v_regs)))) rm
    from cand c
  )
  select r.id, r.cc, r.nm, r.n, r.rm, coalesce(r.ov, r.rm), r.ovr,
         coalesce(nullif(regexp_replace(lower(substring(r.website from '^(?:https?://)?([^/?#]+)')), '^www\.', ''), ''),
                  (select regexp_replace(lower(substring(pg.url from '^https?://([^/?#]+)')), '^www\.', '') h from pipeline.coverage_course_pages pg
                    where pg.provider_id = r.id and pg.status = 'bound' and pg.read_status = 'read' group by 1 order by count(*) desc limit 1))
  from ruled r;
end $_$;


ALTER FUNCTION "security"."firecrawl_targets_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."firecrawl_upgrade_run_v1"("p_provider_id" "uuid", "p_query" "text", "p_page_pattern" "text", "p_cap" numeric, "p_reason" "text", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_settings jsonb; v_run uuid; v_n int; v_budget jsonb; v_domain text;
begin
  if length(btrim(coalesce(p_reason, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if not security.uni_adapter_pattern_ok(p_page_pattern) or coalesce(p_page_pattern, '') = '' then raise exception 'the page pattern cannot be read'; end if;
  if exists (select 1 from pipeline.firecrawl_runs r where r.use_case = 'find_page' and r.status = 'running') then raise exception 'a Find pages run is still open. Let it finish or stop it first'; end if;
  v_budget := security.layer2_provider_budget_status((select p.id from pipeline.layer2_acquisition_providers p where p.provider_key = 'firecrawl'), 1);
  if not coalesce((v_budget->>'allowed')::boolean, false) then raise exception 'Firecrawl is at its reserve'; end if;
  select coalesce(jsonb_object_agg(s.key, s.value), '{}'::jsonb) into v_settings from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl';
  v_settings := v_settings || jsonb_build_object('find_query', to_jsonb(p_query));
  v_domain := (select c.domain from pipeline.firecrawl_target_cache c where c.provider_id = p_provider_id);
  insert into pipeline.firecrawl_runs(use_case, settings, reason, requested_by, credits_cap) values ('find_page', v_settings, p_reason, p_actor, p_cap) returning id into v_run;
  insert into pipeline.firecrawl_run_items(run_id, course_id, provider_id, country, url, input)
    select v_run, pg.course_id, pg.provider_id, k.iso_alpha2::text, null,
           jsonb_build_object('course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'provider', coalesce(p.display_name, p.canonical_name), 'domain', v_domain,
                              'upgrade', true, 'upgrade_pattern', p_page_pattern, 'earlier_url', pg.url, 'earlier_status', pg.read_status, 'refind', true)
      from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id and c.lifecycle_status = 'active'
      join catalogue.providers p on p.id = pg.provider_id join ref.countries k on k.id = p.country_id
     where pg.provider_id = p_provider_id and pg.url !~* p_page_pattern
       and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = pg.course_id and l.field = 'official_url')
     order by pg.course_id;
  get diagnostics v_n = row_count;
  update pipeline.firecrawl_runs set items = v_n, status = case when v_n = 0 then 'done' else 'running' end, finished_at = case when v_n = 0 then now() end where id = v_run;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'firecrawl_run_start', 'find_page', jsonb_build_object('run_id', v_run, 'items', v_n, 'credits_cap', p_cap, 'upgrade_pattern', p_page_pattern, 'query', p_query, 'provider_id', p_provider_id, 'reason', p_reason), p_actor);
  if v_n > 0 then perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'fc_run', 'run_id', v_run)); end if;
  return jsonb_build_object('run_id', v_run, 'items', v_n);
end $$;


ALTER FUNCTION "security"."firecrawl_upgrade_run_v1"("p_provider_id" "uuid", "p_query" "text", "p_page_pattern" "text", "p_cap" numeric, "p_reason" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."host_pages_apply_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_done int := 0;
begin
  if not exists (select 1 from pipeline.uni_adapters u where u.provider_id = p_provider_id and u.enabled and u.admit and 'host_pages' = any (u.admit_fields)) then
    return jsonb_build_object('ok', false, 'note', 'host pages are not admitted for this university'); end if;
  for r in
    select h.course_id, h.host_course_id, h.host_url from pipeline.course_host_pages h
     where h.provider_id = p_provider_id and h.active and h.link_type = 'shared_page' and coalesce(h.register_check, 'none') <> 'fail'
       and exists (select 1 from pipeline.coverage_course_pages pg where pg.course_id = h.course_id and pg.url = h.host_url and pg.read_status = 'identity_mismatch')
       and exists (select 1 from pipeline.coverage_course_pages hp where hp.course_id = h.host_course_id and hp.url = h.host_url and hp.read_status = 'read' and hp.identity_basis is not null)
  loop
    update pipeline.coverage_course_pages pg set read_status = 'read', identity_basis = 'host_page', candidates = case when pg.candidates ? 'adapter_extra' then pg.candidates else coalesce(pg.candidates, '{}'::jsonb) || coalesce((select jsonb_build_object('adapter_extra', hp.candidates->'adapter_extra') from pipeline.coverage_course_pages hp where hp.course_id = r.host_course_id and hp.candidates ? 'adapter_extra'), '{}'::jsonb) end, evidence_id = coalesce(pg.evidence_id, (select hp.evidence_id from pipeline.coverage_course_pages hp where hp.course_id = r.host_course_id)) where pg.course_id = r.course_id and pg.url = r.host_url;
    update pipeline.course_host_pages set applied_at = now() where course_id = r.course_id;
    v_done := v_done + 1;
  end loop;
  return jsonb_build_object('ok', true, 'confirmed', v_done);
end $$;


ALTER FUNCTION "security"."host_pages_apply_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."host_pages_detect_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_shared int; v_double int; v_gone int; v_r record; v_chk text[];
begin
  -- shared_page: the course's page failed the identity check, but the same page is confirmed for another course of
  -- the university whose title is the start of this course's title (majors, research disciplines).
  with cand as (
    select ch.id child_id, hp.course_id host_id, pg.url, hp.evidence_id, hc.canonical_title host_title, ch.canonical_title child_title
      from pipeline.coverage_course_pages pg join catalogue.courses ch on ch.id = pg.course_id and ch.lifecycle_status = 'active'
      join pipeline.coverage_course_pages hp on hp.url = pg.url and hp.provider_id = pg.provider_id and hp.course_id <> pg.course_id and hp.read_status = 'read' and hp.identity_basis is not null
      join catalogue.courses hc on hc.id = hp.course_id and hc.lifecycle_status = 'active'
     where pg.provider_id = p_provider_id and pg.read_status = 'identity_mismatch' and pg.http_status = 200
       and not security.is_double_degree_title(ch.canonical_title)
       and (security.course_title_key(ch.canonical_title) = security.course_title_key(hc.canonical_title)
            or lower(ch.canonical_title) like lower(hc.canonical_title) || ' (%')
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = ch.id and k.field in ('official_url', 'course_url'))),
  one as (select distinct on (child_id) * from cand order by child_id, length(host_title) desc, host_id),
  ins as (
    insert into pipeline.course_host_pages(course_id, provider_id, link_type, host_course_id, host_url, basis, printed, evidence_id, reason)
    select child_id, p_provider_id, 'shared_page', host_id, url, 'title', left(child_title || ' on the page of ' || host_title, 300), evidence_id, 'the same page is confirmed for the host course'
      from one
    on conflict (course_id) do update set host_course_id = excluded.host_course_id, host_url = excluded.host_url, printed = excluded.printed, evidence_id = excluded.evidence_id, set_at = now() where pipeline.course_host_pages.set_by = 'detector'
    returning 1)
  select count(*) into v_shared from ins;
  for v_r in select h.course_id, h.host_course_id from pipeline.course_host_pages h where h.provider_id = p_provider_id and h.link_type = 'shared_page' loop
    v_chk := security.award_register_check(v_r.course_id, v_r.host_course_id);
    update pipeline.course_host_pages set register_check = v_chk[1], check_detail = v_chk[2] where course_id = v_r.course_id;
  end loop;
  -- double_degree: a double degree bound to a page that was read but not confirmed, and not shared with another course
  with cand as (
    select ch.id child_id, pg.url, pg.evidence_id, ch.canonical_title
      from pipeline.coverage_course_pages pg join catalogue.courses ch on ch.id = pg.course_id and ch.lifecycle_status = 'active'
     where pg.provider_id = p_provider_id and pg.read_status = 'identity_mismatch' and pg.http_status = 200
       and security.is_double_degree_title(ch.canonical_title)
       and not exists (select 1 from pipeline.coverage_course_pages p2 where p2.url = pg.url and p2.course_id <> pg.course_id)
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = ch.id and k.field in ('official_url', 'course_url'))),
  ins as (
    insert into pipeline.course_host_pages(course_id, provider_id, link_type, host_url, basis, printed, evidence_id, reason)
    select child_id, p_provider_id, 'double_degree', url, 'bound page', left(canonical_title || ' bound to ' || url, 300), evidence_id, 'read but the identity was not confirmed: confirm by hand'
      from cand
    on conflict (course_id) do update set host_url = excluded.host_url, printed = excluded.printed, evidence_id = excluded.evidence_id, set_at = now() where pipeline.course_host_pages.set_by = 'detector'
    returning 1)
  select count(*) into v_double from ins;
  -- no_public_page: the bound page is gone (404 twice or more)
  with cand as (
    select ch.id child_id, pg.url, ch.canonical_title
      from pipeline.coverage_course_pages pg join catalogue.courses ch on ch.id = pg.course_id and ch.lifecycle_status = 'active'
     where pg.provider_id = p_provider_id and pg.read_status = 'fetch_failed' and pg.http_status = 404 and coalesce(pg.read_attempts, 0) >= 2
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = ch.id and k.field in ('official_url', 'course_url'))),
  ins as (
    insert into pipeline.course_host_pages(course_id, provider_id, link_type, host_url, basis, printed, reason)
    select child_id, p_provider_id, 'no_public_page', url, '404', left(canonical_title || ': ' || url || ' is gone', 300), 'the page returned 404 twice or more: record no public page by hand'
      from cand
    on conflict (course_id) do update set host_url = excluded.host_url, printed = excluded.printed, set_at = now() where pipeline.course_host_pages.set_by = 'detector'
    returning 1)
  select count(*) into v_gone from ins;
  return jsonb_build_object('shared_page', v_shared, 'double_degree', v_double, 'no_public_page', v_gone);
end $$;


ALTER FUNCTION "security"."host_pages_detect_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."host_pages_hourly_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u record; v jsonb := '[]'::jsonb;
begin
  for u in select a.provider_id from pipeline.uni_adapters a where a.enabled and a.admit and 'host_pages' = any (a.admit_fields) loop
    v := v || jsonb_build_array(jsonb_build_object('provider_id', u.provider_id, 'found', security.host_pages_detect_v1(u.provider_id), 'apply', security.host_pages_apply_v1(u.provider_id)));
  end loop;
  return v;
end $$;


ALTER FUNCTION "security"."host_pages_hourly_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."important_date_queue_targeted_refresh_impl"("p_important_date_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_d pipeline.important_dates%rowtype; v_id uuid;
begin
  if auth.uid() is null or security.current_role_rank()<3 then
    raise exception 'curator role required' using errcode='42501';
  end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'refresh reason required'; end if;
  select * into v_d from pipeline.important_dates where id=p_important_date_id and status='active';
  if not found then raise exception 'active important date not found'; end if;
  if v_d.refresh_layer is null then raise exception 'important date has no governed refresh layer'; end if;
  if v_d.source_id is null and v_d.source_profile_id is null and v_d.entity_id is null then
    raise exception 'country-wide important date cannot trigger ingestion';
  end if;
  insert into pipeline.refresh_requests(
    requested_layer,country_code,source_id,source_profile_id,entity_type,entity_id,reason,
    trigger_type,important_date_id,requested_by,change_control_ref
  ) values (
    v_d.refresh_layer,v_d.country_code,v_d.source_id,v_d.source_profile_id,v_d.entity_type,v_d.entity_id,
    trim(p_reason),'important_date',v_d.id,auth.uid(),v_d.change_control_ref
  ) returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "security"."important_date_queue_targeted_refresh_impl"("p_important_date_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."important_date_upsert_impl"("p_id" "uuid", "p_country_code" "text", "p_event_type" "text", "p_title" "text", "p_source_url" "text", "p_evidence_id" "uuid", "p_scope_type" "text", "p_source_profile_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_date_precision" "text", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text", "p_source_wording" "text", "p_warning_days" integer, "p_expires_at" timestamp with time zone, "p_refresh_layer" smallint) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$ declare v_id uuid:=coalesce(p_id,gen_random_uuid()); begin
 if auth.uid() is null or security.current_role_rank()<3 then raise exception 'curator role required' using errcode='42501'; end if;
 if p_warning_days not between 0 and 365 then raise exception 'warning days must be 0..365'; end if;
 if p_date_precision='exact' and p_starts_at is null then raise exception 'exact dates require a sourced timestamp'; end if;
 if p_date_precision='source_vague' and nullif(trim(coalesce(p_source_wording,'')),'') is null then raise exception 'vague source wording must be retained'; end if;
 insert into pipeline.important_dates(id,country_code,event_type,title,source_url,evidence_id,scope_type,source_profile_id,entity_type,entity_id,date_precision,starts_at,ends_at,timezone,source_wording,warning_window,expires_at,status,refresh_layer,change_control_ref,created_by,updated_by)
 values(v_id,upper(p_country_code),p_event_type,trim(p_title),trim(p_source_url),p_evidence_id,p_scope_type,p_source_profile_id,p_entity_type,p_entity_id,p_date_precision,p_starts_at,p_ends_at,p_timezone,p_source_wording,make_interval(days=>p_warning_days),p_expires_at,'active',p_refresh_layer,'CF-CHG-20260825-038',auth.uid(),auth.uid())
 on conflict(id) do update set country_code=excluded.country_code,event_type=excluded.event_type,title=excluded.title,source_url=excluded.source_url,evidence_id=excluded.evidence_id,scope_type=excluded.scope_type,source_profile_id=excluded.source_profile_id,entity_type=excluded.entity_type,entity_id=excluded.entity_id,date_precision=excluded.date_precision,starts_at=excluded.starts_at,ends_at=excluded.ends_at,timezone=excluded.timezone,source_wording=excluded.source_wording,warning_window=excluded.warning_window,expires_at=excluded.expires_at,refresh_layer=excluded.refresh_layer,updated_by=auth.uid(),updated_at=now(); return v_id; end $$;


