    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select lower(coalesce(p, '')) ~ '( / |/| and bachelor| and master| and diploma|\mdouble\M|\mdual\M|\mcombined\M)'
$$;


