CREATE OR REPLACE FUNCTION "security"."l4_rule6_apply_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_kept_hand int := 0; v_done int := 0; v_itk int := 0; v_en int := 0; v_fee int := 0; v_ln int := 0; n int; v_courses uuid[] := '{}'; v_res jsonb;
begin
  for r in select c.course_id, c.provider_id, c.url, c.course_code, c.found, c.codes
             from pipeline.rule6_page_checks c
            where c.checked_at is not null and c.found is not true and c.action is null loop
    if exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = r.course_id and m.field in ('official_url', 'course_url')) then
      update pipeline.rule6_page_checks set action = 'kept: page chosen by hand', acted_at = now() where course_id = r.course_id;
      v_kept_hand := v_kept_hand + 1; continue;
    end if;
    if not exists (select 1 from pipeline.coverage_course_pages p where p.course_id = r.course_id and p.url = r.url) then
      update pipeline.rule6_page_checks set action = 'skipped: no longer bound to this page', acted_at = now() where course_id = r.course_id;
      continue;
    end if;
    insert into pipeline.course_page_blocks(course_id, url, reason)
    values (r.course_id, r.url, 'Rule 6 (8 Oct 2026): page named for another course and the course''s own CRICOS code is not on it') on conflict do nothing;
    update pipeline.coverage_course_pages set status = 'mismatch', read_status = 'identity_mismatch', leased_until = null where course_id = r.course_id;
    update catalogue.course_intakes i set status = 'withdrawn'
     where i.course_id = r.course_id and i.status = 'active' and i.source_id is not null
       and i.evidence_id in (select e.id from pipeline.evidence_artifacts e where e.source_url = r.url);
    get diagnostics n = row_count; v_itk := v_itk + n;
    update catalogue.course_english_requirements q set status = 'withdrawn'
     where q.course_id = r.course_id and coalesce(q.status, 'active') = 'active' and q.source_id is not null
       and q.evidence_id in (select e.id from pipeline.evidence_artifacts e where e.source_url = r.url);
    get diagnostics n = row_count; v_en := v_en + n;
    update catalogue.course_fees f set status = 'superseded', updated_at = now()
     where f.course_id = r.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.source_id is not null
       and f.evidence_id in (select e.id from pipeline.evidence_artifacts e where e.source_url = r.url);
    get diagnostics n = row_count; v_fee := v_fee + n;
    update catalogue.course_links l set status = 'inactive'
     where l.course_id = r.course_id and l.status = 'active' and l.url = r.url and l.source_id is not null;
    get diagnostics n = row_count; v_ln := v_ln + n;
    insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at)
    values (r.course_id, r.provider_id, case when r.course_code is not null then 'cricos' else 'title' end, 'queued', now())
    on conflict (course_id) do update set stage = excluded.stage, state = 'queued', attempts = 0, query = null, req_id = null, results = null,
           candidates = null, cand_idx = 0, bound_url = null, queued_at = now(), sent_at = null, done_at = null;
    update pipeline.rule6_page_checks set action = 'unbound and sent back to page finding', acted_at = now() where course_id = r.course_id;
    v_done := v_done + 1; v_courses := v_courses || r.course_id;
  end loop;
  if cardinality(v_courses) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;
  v_res := jsonb_build_object('unbound', v_done, 'kept_hand_chosen', v_kept_hand, 'intakes_withdrawn', v_itk, 'english_withdrawn', v_en,
                              'fees_superseded', v_fee, 'links_inactive', v_ln);
  insert into pipeline.layer4_rule_runs(rule, raised) values ('unclear_identity', v_res);
  return v_res;
end $$;


ALTER FUNCTION "security"."l4_rule6_apply_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."l4_rule_fee_year_align_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_year int := extract(year from now())::int; v_fees int; v_items int; v_conf int; v_new int; v_old int; v_courses uuid[]; v_r jsonb;
begin
  create temporary table rule3_all on commit drop as
    select f.id, f.course_id, f.audience, ea.captured_at,
           (select g.id from catalogue.course_fees g where g.course_id = f.course_id and g.fee_type = 'provider_current_tuition' and g.audience = f.audience
               and g.status = 'active' and g.fee_year = v_year and g.id <> f.id
             order by g.updated_at desc nulls last limit 1) other_id
      from catalogue.course_fees f join pipeline.evidence_artifacts ea on ea.id = f.evidence_id
     where f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.fee_year is null and f.amount > 0
       and extract(year from ea.captured_at)::int = v_year
       and not exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = f.course_id and m.field in ('tuition', 'fee', 'fees'));
  select count(*) filter (where other_id is not null) into v_conf from rule3_all;

  -- same-year conflicts: newest evidence wins (a this-year fee with no evidence counts as older)
  create temporary table rule3_conf on commit drop as
    select a.id, a.course_id, a.other_id,
           (a.captured_at > coalesce((select eg.captured_at from catalogue.course_fees g join pipeline.evidence_artifacts eg on eg.id = g.evidence_id where g.id = a.other_id), '-infinity'::timestamptz)) yearless_newer
      from rule3_all a where a.other_id is not null;
  update catalogue.course_fees g
     set status = 'superseded', updated_at = now(),
         notes = concat_ws(' | ', nullif(g.notes, ''), 'Rule 3 (8 Oct 2026): superseded by a newer course page reading for ' || v_year || ' (newest evidence wins)')
   where g.id in (select other_id from rule3_conf where yearless_newer);
  get diagnostics v_new = row_count;
  update catalogue.course_fees f
     set status = 'superseded', updated_at = now(),
         notes = concat_ws(' | ', nullif(f.notes, ''), 'Rule 3 (8 Oct 2026): no year on the page; the ' || v_year || ' fee on record has newer evidence, so it stays (newest evidence wins)')
   where f.id in (select id from rule3_conf where not yearless_newer);
  get diagnostics v_old = row_count;

  create temporary table rule3_fees on commit drop as
    select id, course_id, audience from rule3_all where other_id is null
    union all select c.id, c.course_id, null from rule3_conf c where c.yearless_newer;
  create temporary table rule3_closed on commit drop as
    select course_id from rule3_all;

  update catalogue.course_fees f
     set fee_year = v_year, updated_at = now(),
         notes = concat_ws(' | ', nullif(f.notes, ''), 'Rule 3 (8 Oct 2026): no year on the page; evidence captured in ' || v_year || ', so aligned to ' || v_year || ' without review')
   where f.id in (select id from rule3_fees);
  get diagnostics v_fees = row_count;

  update pipeline.layer4_review_items i
     set status = 'superseded', decided_at = now(),
         escalation_reason = i.escalation_reason || ' Closed by Rule 3 (8 Oct 2026): evidence captured in ' || v_year || ', fee aligned to ' || v_year || ' (where another ' || v_year || ' fee was on record, the newest evidence wins); no review needed.'
   where i.status = 'pending' and i.entity_type = 'course' and i.field_code = 'provider_current_tuition_validation'
     and i.escalation_reason like 'No fee year on record%'
     and i.entity_id in (select course_id from rule3_closed);
  get diagnostics v_items = row_count;

  select coalesce(array_agg(distinct course_id), '{}') into v_courses from rule3_closed;
  if cardinality(v_courses) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;

  v_r := jsonb_build_object('year', v_year, 'fees_aligned', v_fees, 'items_closed', v_items, 'same_year_conflicts', v_conf, 'conflict_yearless_newer_won', v_new, 'conflict_dated_fee_kept', v_old);
  insert into pipeline.layer4_rule_runs(rule, raised) values ('fee_year_align', v_r);
  return v_r;
end $$;


ALTER FUNCTION "security"."l4_rule_fee_year_align_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."l4_rule_low_agreement_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a record; q jsonb; v_add text[]; v_done jsonb := '[]'::jsonb; v_checked int := 0; v_country text;
begin
  for a in select u.provider_id, u.admit, u.admit_fields from pipeline.uni_adapters u where u.enabled order by u.provider_id loop
    v_checked := v_checked + 1;
    q := security.adapter_qualify_one_v1(a.provider_id, 0.5, 0.9);
    select k.iso_alpha2 into v_country from catalogue.providers p left join ref.countries k on k.id = p.country_id where p.id = a.provider_id;
    v_add := array(
      select x.k from jsonb_each(coalesce(q->'fields', '{}'::jsonb)) x(k, v)
       where x.k in ('intakes', 'english', 'fee', 'delivery')
         and (x.v->>'read_share')::numeric >= 0.5 and (x.v->>'agree_share')::numeric < 0.9
         and not (a.admit and x.k = any(coalesce(a.admit_fields, '{}')))
         and not (x.k = 'fee' and v_country = 'CA')
         and not exists (select 1 from pipeline.l4_rule4_holds h where h.provider_id = a.provider_id and h.field = x.k)
       order by x.k);
    if cardinality(v_add) > 0 then
      update pipeline.uni_adapters u
         set admit = true,
             admit_fields = array(select distinct f from unnest(case when a.admit then coalesce(a.admit_fields, '{}') else '{}'::text[] end || v_add) f order by f),
             admit_reason = 'Rule 4 (daily): low agreement, page wins - ' || array_to_string(v_add, ', ') || ' admitted', admit_changed_at = now()
       where u.provider_id = a.provider_id;
      insert into pipeline.admin_control_events(area, action, target, detail, actor)
      values ('toolsets', 'uni_adapter_admit', a.provider_id::text,
              jsonb_build_object('admit', true, 'fields', (select to_jsonb(u.admit_fields) from pipeline.uni_adapters u where u.provider_id = a.provider_id),
                                 'reason', 'Rule 4 (daily): low agreement, page wins', 'rule', 'rule_4', 'qualify', q->'fields'), null);
      perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_apply', 'provider_id', a.provider_id));
      v_done := v_done || jsonb_build_object('provider_id', a.provider_id, 'fields', to_jsonb(v_add));
    end if;
  end loop;
  insert into pipeline.layer4_rule_runs(rule, raised) values ('low_agreement', jsonb_build_object('adapters_checked', v_checked, 'admitted', v_done));
  return jsonb_build_object('adapters_checked', v_checked, 'admitted', jsonb_array_length(v_done));
end $$;


ALTER FUNCTION "security"."l4_rule_low_agreement_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."l4_rule_unofficial_source_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_i int; v_e int; v_l int; v_hosts text[]; v_r jsonb;
begin
  select array(select distinct h from (
      select substring(pg.url from '^https?://(?:www\.)?([^/:?#]+)') h from pipeline.coverage_course_pages pg
       group by 1 having count(distinct pg.provider_id) >= 3
      union
      select jsonb_array_elements_text(coalesce((select e.detail->'hosts' from pipeline.retention_estimates e where e.category = 'directory_urls'), '[]'::jsonb))) x where h is not null)
    into v_hosts;

  create temporary table rule_pages on commit drop as
    select pg.course_id, pg.provider_id, pg.url, pg.evidence_id, substring(pg.url from '^https?://(?:www\.)?([^/:?#]+)') host
      from pipeline.coverage_course_pages pg join catalogue.providers p on p.id = pg.provider_id
     where pg.evidence_id is not null and substring(pg.url from '^https?://(?:www\.)?([^/:?#]+)') = any(v_hosts)
       and (p.website is null or not (
             substring(pg.url from '^https?://(?:www\.)?([^/:?#]+)') = substring(p.website from '^https?://(?:www\.)?([^/:?#]+)')
             or substring(pg.url from '^https?://(?:www\.)?([^/:?#]+)') like '%.' || substring(p.website from '^https?://(?:www\.)?([^/:?#]+)')));

  insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, status, escalation_reason, change_control_ref)
  select 'course', d.course_id, 'course_intake', d.evidence_id, jsonb_agg(distinct i.intake_label),
         jsonb_build_object('intakes', jsonb_agg(distinct jsonb_build_object('intake_label', i.intake_label, 'source_intake_key', null))), 'pending',
         format('Rule 1, source is not the provider''s own site: read from %s (%s), a site shared by several providers. The register confirms the course; confirm the intakes on the provider''s own course page. Approve keeps them as they are; the value stays shown until decided.', d.host, d.url),
         'CF-CHG-20260915-247'
    from rule_pages d join catalogue.course_intakes i on i.course_id = d.course_id and i.evidence_id = d.evidence_id and i.status = 'active'
   where not exists (select 1 from pipeline.layer4_review_items r where r.entity_type = 'course' and r.entity_id = d.course_id and r.field_code = 'course_intake'
                       and (r.status = 'pending' or r.evidence_id = d.evidence_id))
   group by d.course_id, d.evidence_id, d.host, d.url;
  get diagnostics v_i = row_count;

  insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, status, escalation_reason, change_control_ref)
  select 'course', d.course_id, 'course_english', d.evidence_id, jsonb_agg(jsonb_build_object('test', t.code, 'overall', e.overall_score)),
         jsonb_build_object('english_requirements', jsonb_agg(jsonb_build_object('notes', 'Shared-site page, kept after review', 'test_code', t.code, 'overall_score', e.overall_score, 'component_scores', coalesce(e.component_scores, '{}'::jsonb)))), 'pending',
         format('Rule 1, source is not the provider''s own site: read from %s (%s), a site shared by several providers. The register confirms the course; confirm the English requirement on the provider''s own course page. Approve keeps it as it is; the value stays shown until decided.', d.host, d.url),
         'CF-CHG-20260915-247'
    from rule_pages d join catalogue.course_english_requirements e on e.course_id = d.course_id and e.evidence_id = d.evidence_id and e.status = 'active'
    join ref.english_tests t on t.id = e.english_test_id
   where not exists (select 1 from pipeline.layer4_review_items r where r.entity_type = 'course' and r.entity_id = d.course_id and r.field_code = 'course_english'
                       and (r.status = 'pending' or r.evidence_id = d.evidence_id))
   group by d.course_id, d.evidence_id, d.host, d.url;
  get diagnostics v_e = row_count;

  insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, status, escalation_reason, change_control_ref)
  select distinct on (d.course_id) 'course', d.course_id, 'official_course_url', d.evidence_id, jsonb_build_array(l.url), jsonb_build_object('course_url', l.url), 'pending',
         format('Rule 1, source is not the provider''s own site: the official course page on record is on %s, a site shared by several providers. Find the provider''s own course page and edit the address, or reject. The link stays shown until decided.', d.host),
         'CF-CHG-20260915-247'
    from rule_pages d join catalogue.course_links l on l.course_id = d.course_id and l.url = d.url and l.status = 'active'
   where not exists (select 1 from pipeline.layer4_review_items r where r.entity_type = 'course' and r.entity_id = d.course_id and r.field_code = 'official_course_url'
                       and (r.status = 'pending' or r.evidence_id = d.evidence_id))
   order by d.course_id, l.is_primary desc;
  get diagnostics v_l = row_count;

  v_r := jsonb_build_object('hosts', to_jsonb(v_hosts), 'intake_items', v_i, 'english_items', v_e, 'course_link_items', v_l);
  insert into pipeline.layer4_rule_runs(rule, raised) values ('unofficial_source', v_r);
  return v_r;
end $$;


ALTER FUNCTION "security"."l4_rule_unofficial_source_v1"() OWNER TO "postgres";


