ALTER FUNCTION "security"."layer1_housekeeping_tick_impl"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer1_plan_finish_v1"("p_run_id" "uuid", "p_force" boolean DEFAULT false, "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'security', 'search'
    AS $$
declare p pipeline.layer1_run_plans; v_ids uuid[]; v_n int; v_expected int; v_reactivated int:=0; v_providers int:=0;
        v_limit int; v_before jsonb; v_after jsonb; v_snapshot text; v_result jsonb; v_country uuid;
begin
  select * into p from pipeline.layer1_run_plans where run_id=p_run_id for update;
  if not found then raise exception 'run plan not found'; end if;
  if p.departures_status='applied' then return p.departures_result; end if;
  if p.course_hash='seen-tracking' then return security.layer1_seen_departures_v1(p_run_id,p_force,p_actor); end if;
  select s.country_id into v_country from pipeline.sources s where s.id=p.source_id;
  v_snapshot:=coalesce((select to_char(created_at at time zone 'Australia/Sydney','DD Mon YYYY') from pipeline.layer1_run_plans where run_id=p_run_id),'');

  -- Reactivate planned 'new' records that match a retired course.
  with back as (
    select distinct r.course_id from pipeline.layer1_course_retirements r
    join catalogue.course_registrations cr on cr.course_id=r.course_id and lower(cr.scheme)='cricos'
    join jsonb_array_elements(p.items) i on upper(i->>0)=upper(cr.registration_code) and i->>2='new'
    join catalogue.courses c on c.id=r.course_id
    join catalogue.providers pv on pv.id=c.provider_id and pv.country_id=v_country
    where r.reactivated_at is null and c.lifecycle_status='inactive'),
  upd as (update catalogue.courses c set lifecycle_status='active', updated_at=now() from back where c.id=back.course_id returning c.id)
  select count(*) into v_reactivated from upd;
  update pipeline.layer1_course_retirements r set reactivated_at=now()
   where r.reactivated_at is null and exists (select 1 from catalogue.courses c where c.id=r.course_id and c.lifecycle_status='active');

  -- Departures: active courses whose register code is listed as departed.
  select array_agg(distinct c.id) into v_ids
    from catalogue.course_registrations cr
    join catalogue.courses c on c.id=cr.course_id
    join catalogue.providers pv on pv.id=c.provider_id and pv.country_id=v_country
   where lower(cr.scheme)='cricos' and upper(cr.registration_code)=any(select upper(x) from unnest(p.departed_keys) x)
     and c.lifecycle_status='active';
  v_expected:=coalesce(cardinality(v_ids),0);
  v_limit:=greatest(50, ceil(p.register_total*0.02)::int);

  if v_expected>v_limit and not p_force then
    v_result:=jsonb_build_object('status','held','departed',p.departed_count,'to_retire',v_expected,'limit',v_limit,'reactivated',v_reactivated,
      'message',format('%s courses left the register, more than the automatic limit of %s. A Platform Admin must approve the retirement.',v_expected,v_limit));
    update pipeline.layer1_run_plans set departures_status='held', departures_result=v_result where run_id=p_run_id;
    return v_result;
  end if;

  if v_expected>0 then
    v_before:=security.consumer_api_snapshot_v1();
    insert into pipeline.layer1_course_retirements(course_id,provider_id,previous_status,reason,evidence_id,run_id,approved_by)
    select c.id, c.provider_id, c.lifecycle_status, 'Not in the register as of '||v_snapshot, p.course_evidence_id, p_run_id, p_actor
      from catalogue.courses c where c.id=any(v_ids);
    update catalogue.courses set lifecycle_status='inactive', updated_at=now() where id=any(v_ids) and lifecycle_status='active';
    get diagnostics v_n = row_count;
    if v_n<>v_expected then raise exception 'retired % courses, expected %; nothing changed', v_n, v_expected; end if;
    update catalogue.course_registrations set status='inactive' where course_id=any(v_ids) and lower(scheme)='cricos' and status='active';

    -- Providers with no active courses left: record for a person (closure or merger).
    with gone as (select distinct c.provider_id from catalogue.courses c where c.id=any(v_ids)),
    empty as (select g.provider_id from gone g where not exists (select 1 from catalogue.courses c2 where c2.provider_id=g.provider_id and c2.lifecycle_status='active')),
    ins as (insert into pipeline.layer1_provider_departures(provider_id,run_id,courses_retired,note)
            select e.provider_id, p_run_id, (select count(*) from catalogue.courses c where c.id=any(v_ids) and c.provider_id=e.provider_id),
                   'All registered courses left the register; review as a closure or a merger and record any successor.'
              from empty e returning 1)
    select count(*) into v_providers from ins;

    v_after:=security.consumer_api_snapshot_v1();
    insert into pipeline.consumer_api_baselines(label, snapshot) values
      (format('before retiring %s register departures (run %s)', v_expected, left(p_run_id::text,8)), v_before),
      (format('after retiring %s register departures (run %s)', v_expected, left(p_run_id::text,8)), v_after);
  end if;

  delete from pipeline.layer1_register_row_state s where s.source_id=p.source_id and s.record_key=any(p.departed_keys);
  update catalogue.courses c set last_verified_at=now()
    from catalogue.course_registrations cr, pipeline.layer1_register_row_state s
   where cr.course_id=c.id and lower(cr.scheme)='cricos' and cr.status='active' and s.source_id=p.source_id and s.record_key=upper(cr.registration_code)
     and s.seen_at>=p.created_at-interval '1 hour' and c.lifecycle_status='active' and (c.last_verified_at is null or c.last_verified_at<now()-interval '30 days');
  update catalogue.providers pv set last_verified_at=now()
   where pv.country_id=v_country and pv.lifecycle_status='active' and (pv.last_verified_at is null or pv.last_verified_at<now()-interval '30 days')
     and exists (select 1 from catalogue.courses c where c.provider_id=pv.id and c.lifecycle_status='active' and c.last_verified_at>=now()-interval '1 hour');
  if v_expected>0 or v_reactivated>0 then
    insert into search.refresh_requests(requested_by) values (format('register departures: %s retired, %s reactivated (run %s)', v_expected, v_reactivated, left(p_run_id::text,8)));
  end if;
  v_result:=jsonb_build_object('status','applied','departed',p.departed_count,'retired',v_expected,'reactivated',v_reactivated,'providers_to_review',v_providers,'approved_by',p_actor);
  update pipeline.layer1_run_plans set departures_status='applied', departures_result=v_result where run_id=p_run_id;
  return v_result;
end $$;


ALTER FUNCTION "security"."layer1_plan_finish_v1"("p_run_id" "uuid", "p_force" boolean, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer1_queue_system_run_v1"("p_source_id" "uuid", "p_mode" "text", "p_resume_cursor" bigint DEFAULT 0, "p_retry_of_run_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT 'Background run (system)'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_profile pipeline.layer1_source_operations; v_country text; v_id uuid; v_mode text:=lower(coalesce(p_mode,'dry_run'));
begin
  if v_mode not in ('dry_run','apply') then raise exception 'invalid mode'; end if;
  select * into v_profile from pipeline.layer1_source_operations where source_id=p_source_id;
  if not found then raise exception 'source operations profile missing'; end if;
  if not v_profile.active or v_profile.paused then raise exception 'source is inactive or paused'; end if;
  if coalesce(v_profile.verification_status,'') not in ('passed','warning') then raise exception 'source verification must pass before run'; end if;
  if v_profile.next_verification_at is not null and v_profile.next_verification_at<now() then raise exception 'source verification is stale'; end if;
  if v_profile.variance_decision='block' then raise exception 'record-count variance is blocked'; end if;
  if v_mode='apply' and v_profile.variance_decision='warn' then raise exception 'variance warning needs an operator acknowledgement'; end if;
  if exists(select 1 from pipeline.layer1_run_queue where source_id=p_source_id and status in ('queued','running')) then raise exception 'a run is already queued or running for this source'; end if;
  select co.iso_alpha2::text into v_country from pipeline.sources s join ref.countries co on co.id=s.country_id where s.id=p_source_id;
  v_country:=coalesce(v_country,'GLOBAL');
  insert into pipeline.layer1_run_queue(source_id,country_code,mode,status,idempotency_key,requested_by,expected_count,resume_cursor,processed_count,source_hash,warning_acknowledged,current_stage,heartbeat_at,retry_of_run_id,result)
  values(p_source_id,v_country,v_mode,'queued','system:'||p_source_id::text||':'||extract(epoch from clock_timestamp())::text,'c0ffee00-0000-4000-8000-000000000150',
         v_profile.last_expected_count,greatest(coalesce(p_resume_cursor,0),0),greatest(coalesce(p_resume_cursor,0),0),v_profile.last_source_hash,false,'queued',now()-interval '5 minutes',p_retry_of_run_id,
         jsonb_build_object('start_cursor',greatest(coalesce(p_resume_cursor,0),0),'requested_reason',left(coalesce(p_reason,''),300)))
  returning id into v_id;
  return jsonb_build_object('run_id',v_id,'status','queued','country_code',v_country,'mode',v_mode);
end $$;


ALTER FUNCTION "security"."layer1_queue_system_run_v1"("p_source_id" "uuid", "p_mode" "text", "p_resume_cursor" bigint, "p_retry_of_run_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer1_regulatory_scheduler_tick_impl"("p_now" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 20, "p_dispatch" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare v_created int:=0; v_dispatched int:=0; v_recovered int:=0; v_failed int:=0; rec record; v_net bigint;
begin
  with stale as (
    update pipeline.refresh_requests r
       set status='failed',completed_at=p_now,schedule_error='Scheduled Layer 1 verification dispatch exceeded 30 minute heartbeat window.'
     where r.requested_layer=1 and r.status='running' and r.dispatched_at is not null and r.dispatched_at < p_now-interval '30 minutes'
     returning r.source_id
  ), upd as (
    update pipeline.layer1_source_operations o
       set last_schedule_status='failed',last_schedule_error='Scheduled Layer 1 verification dispatch exceeded 30 minute heartbeat window.',consecutive_failures=o.consecutive_failures+1,updated_at=p_now
     where o.source_id in (select source_id from stale)
     returning 1
  ) select count(*) into v_recovered from stale;

  with due as (
    select o.source_id,coalesce(c.iso_alpha2::text,'GLOBAL') country_code
      from pipeline.layer1_source_operations o
      join pipeline.sources s on s.id=o.source_id
      left join ref.countries c on c.id=s.country_id
     where o.active and not o.paused and o.next_verification_at is not null and o.next_verification_at<=p_now
       and not exists(select 1 from pipeline.refresh_requests r where r.requested_layer=1 and r.source_id=o.source_id and r.status in ('queued','running'))
     order by o.next_verification_at
     limit least(greatest(p_limit,1),100)
     for update of o skip locked
  ), ins as (
    insert into pipeline.refresh_requests(requested_layer,country_code,source_id,reason,trigger_type,status,requested_by,change_control_ref)
    select 1,d.country_code,d.source_id,'Layer 1 scheduled authoritative-source verification due','freshness_expired','queued',null,'CF-CHG-20260826-043' from due d
    returning id
  ) select count(*) into v_created from ins;

  if p_dispatch then
    for rec in
      select r.id,r.source_id from pipeline.refresh_requests r
      join pipeline.layer1_source_operations o on o.source_id=r.source_id
      where r.requested_layer=1 and r.status='queued' and o.active and not o.paused
      order by r.created_at
      limit least(greatest(p_limit,1),100)
      for update of r skip locked
    loop
      begin
        update pipeline.refresh_requests set status='running',dispatched_at=p_now,schedule_error=null where id=rec.id;
        v_net:=pipeline.svc_pilot_submit_nonce('layer1-operations-scheduled',jsonb_build_object('refresh_request_id',rec.id));
        update pipeline.refresh_requests set dispatch_request_id=v_net where id=rec.id;
        v_dispatched:=v_dispatched+1;
      exception when others then
        update pipeline.refresh_requests set status='failed',completed_at=p_now,schedule_error=left(sqlerrm,1000) where id=rec.id;
        update pipeline.layer1_source_operations set last_schedule_status='failed',last_schedule_error=left(sqlerrm,1000),consecutive_failures=consecutive_failures+1,updated_at=p_now where source_id=rec.source_id;
        v_failed:=v_failed+1;
      end;
    end loop;
  end if;
  return jsonb_build_object('ok',true,'created',v_created,'dispatched',v_dispatched,'dispatch_failed',v_failed,'stuck_recovered',v_recovered,'at',p_now,'dispatch_enabled',p_dispatch);
end $$;


ALTER FUNCTION "security"."layer1_regulatory_scheduler_tick_impl"("p_now" timestamp with time zone, "p_limit" integer, "p_dispatch" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer1_run_driver_tick_v1"("p_limit" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare rec record; v_dispatched int:=0; v_gave_up int:=0;
begin
  for rec in
    select q.id, q.current_stage, q.driver_dispatches
      from pipeline.layer1_run_queue q
     where q.status in ('queued','running')
       and (q.lease_until is null or q.lease_until<now())
       and coalesce(q.driver_dispatched_at,'-infinity'::timestamptz)<now()-interval '3 minutes'
       and (
         (q.current_stage='retry_waiting' and coalesce(nullif(q.result->'retry'->>'next_at','')::timestamptz,now())<=now())
         or (q.current_stage is distinct from 'retry_waiting' and coalesce(q.heartbeat_at,q.requested_at)<now()-interval '3 minutes')
       )
     order by q.requested_at
     limit greatest(1,least(coalesce(p_limit,3),10))
     for update of q skip locked
  loop
    if rec.driver_dispatches>=40 then
      update pipeline.layer1_run_queue
         set status='failed',current_stage='failed',completed_at=now(),heartbeat_at=now(),failed_count=failed_count+1,
             error_text='Stopped after 40 background restarts without finishing. Check the source, then use Retry / resume.',updated_at=now()
       where id=rec.id;
      v_gave_up:=v_gave_up+1;
      continue;
    end if;
    update pipeline.layer1_run_queue
       set driver_dispatched_at=now(),driver_dispatches=driver_dispatches+1,
           result=coalesce(result,'{}'::jsonb)||jsonb_build_object('driver',jsonb_build_object('last_dispatch_at',now(),'dispatches',rec.driver_dispatches+1,'reason',case when rec.current_stage='retry_waiting' then 'retry_due' else 'worker_quiet' end))
     where id=rec.id;
    perform pipeline.svc_pilot_submit_nonce('layer1-operations-control',jsonb_build_object('action','continue','run_id',rec.id));
    v_dispatched:=v_dispatched+1;
  end loop;
  return jsonb_build_object('dispatched',v_dispatched,'gave_up',v_gave_up,'at',now());
end $$;


ALTER FUNCTION "security"."layer1_run_driver_tick_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer1_seen_departures_v1"("p_run_id" "uuid", "p_force" boolean DEFAULT false, "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'security', 'search'
    AS $$
declare q pipeline.layer1_run_queue; o pipeline.layer1_source_operations; v_country uuid; v_scheme text; v_since timestamptz;
        v_ids uuid[]; v_back uuid[]; v_expected int; v_n int; v_limit int; v_total int; v_providers int:=0; v_ev uuid;
        v_before jsonb; v_after jsonb; v_result jsonb; v_plan pipeline.layer1_run_plans;
begin
  select * into q from pipeline.layer1_run_queue where id=p_run_id;
  if not found then raise exception 'run not found'; end if;
  select * into o from pipeline.layer1_source_operations where source_id=q.source_id;
  if o.seen_tracking_since is null then raise exception 'source is not seen-tracked'; end if;
  select * into v_plan from pipeline.layer1_run_plans where run_id=p_run_id for update;
  if found and v_plan.departures_status='applied' then return v_plan.departures_result; end if;
  v_since:=coalesce(q.started_at,q.requested_at);
  if v_since < o.seen_tracking_since then
    return jsonb_build_object('status','skipped','reason','run started before seen tracking began');
  end if;
  select s.country_id into v_country from pipeline.sources s where s.id=q.source_id;
  select lower(pr.registration_scheme) into v_scheme from catalogue.provider_registrations pr where pr.source_id=q.source_id limit 1;
  select count(*) into v_total from pipeline.layer1_register_row_state where source_id=q.source_id and seen_at>=v_since-interval '1 day';

  select coalesce(array_agg(distinct c.id),'{}') into v_ids
    from catalogue.courses c
    join catalogue.providers p on p.id=c.provider_id and p.country_id=v_country
    join catalogue.provider_registrations pr on pr.provider_id=p.id and lower(pr.registration_scheme)=v_scheme and pr.checked_at>=v_since
    join catalogue.course_registrations cr on cr.course_id=c.id and lower(cr.scheme)=v_scheme
   where c.lifecycle_status='active'
     and not exists (select 1 from pipeline.layer1_register_row_state s where s.source_id=q.source_id
                      and s.record_key=upper(pr.registration_code)||'|'||upper(cr.registration_code) and s.seen_at>=v_since-interval '1 day');
  select coalesce(array_agg(distinct c.id),'{}') into v_back
    from pipeline.layer1_course_retirements r
    join catalogue.courses c on c.id=r.course_id and c.lifecycle_status='inactive'
    join catalogue.provider_registrations pr on pr.provider_id=c.provider_id and lower(pr.registration_scheme)=v_scheme
    join catalogue.course_registrations cr on cr.course_id=c.id and lower(cr.scheme)=v_scheme
    join pipeline.layer1_register_row_state s on s.source_id=q.source_id and s.record_key=upper(pr.registration_code)||'|'||upper(cr.registration_code) and s.seen_at>=v_since-interval '1 day'
   where r.reactivated_at is null;

  v_expected:=cardinality(v_ids);
  v_limit:=greatest(50, ceil(v_total*0.02)::int);
  insert into pipeline.layer1_run_plans(run_id,source_id,register_total,new_count,changed_count,unchanged_count,departed_count,items,departed_keys,course_hash)
  values(p_run_id,q.source_id,v_total,0,0,v_total,v_expected,'[]'::jsonb,'{}','seen-tracking')
  on conflict (run_id) do update set register_total=excluded.register_total, departed_count=excluded.departed_count, course_hash='seen-tracking';

  if v_expected>v_limit and not p_force then
    v_result:=jsonb_build_object('status','held','departed',v_expected,'to_retire',v_expected,'limit',v_limit,'reactivated',0,
      'message',format('%s courses were not seen in this run, more than the automatic limit of %s. A Platform Admin must approve the retirement.',v_expected,v_limit));
    update pipeline.layer1_run_plans set departures_status='held', departures_result=v_result where run_id=p_run_id;
    return v_result;
  end if;

  if cardinality(v_back)>0 then
    update catalogue.courses set lifecycle_status='active', updated_at=now() where id=any(v_back) and lifecycle_status='inactive';
    update catalogue.course_registrations set status='active' where course_id=any(v_back) and lower(scheme)=v_scheme;
    update pipeline.layer1_course_retirements set reactivated_at=now() where course_id=any(v_back) and reactivated_at is null;
  end if;

  if v_expected>0 then
    select e.id into v_ev from pipeline.evidence_artifacts e where e.source_id=q.source_id and e.created_at>=v_since-interval '1 day' order by e.created_at desc limit 1;
    v_before:=security.consumer_api_snapshot_v1();
    insert into pipeline.layer1_course_retirements(course_id,provider_id,previous_status,reason,evidence_id,run_id,approved_by)
    select c.id, c.provider_id, c.lifecycle_status, 'Not listed by the register as of '||to_char(v_since at time zone 'Australia/Sydney','DD Mon YYYY'), v_ev, p_run_id, p_actor
      from catalogue.courses c where c.id=any(v_ids);
    update catalogue.courses set lifecycle_status='inactive', updated_at=now() where id=any(v_ids) and lifecycle_status='active';
    get diagnostics v_n = row_count;
    if v_n<>v_expected then raise exception 'retired % courses, expected %; nothing changed', v_n, v_expected; end if;
    update catalogue.course_registrations set status='inactive' where course_id=any(v_ids) and lower(scheme)=v_scheme and status='active';
    with gone as (select distinct c.provider_id from catalogue.courses c where c.id=any(v_ids)),
    empty as (select g.provider_id from gone g where not exists (select 1 from catalogue.courses c2 where c2.provider_id=g.provider_id and c2.lifecycle_status='active')
               and not exists (select 1 from pipeline.layer1_provider_departures d where d.provider_id=g.provider_id and d.status='needs_review')),
    ins as (insert into pipeline.layer1_provider_departures(provider_id,run_id,courses_retired,note)
            select e.provider_id, p_run_id, (select count(*) from catalogue.courses c where c.id=any(v_ids) and c.provider_id=e.provider_id),
                   'All registered courses left the register; review as a closure or a merger and record any successor.' from empty e returning 1)
    select count(*) into v_providers from ins;
    v_after:=security.consumer_api_snapshot_v1();
    insert into pipeline.consumer_api_baselines(label, snapshot) values
      (format('before retiring %s register departures (run %s)', v_expected, left(p_run_id::text,8)), v_before),
      (format('after retiring %s register departures (run %s)', v_expected, left(p_run_id::text,8)), v_after);
  end if;
  if v_expected>0 or cardinality(v_back)>0 then
    insert into search.refresh_requests(requested_by) values (format('register departures: %s retired, %s reactivated (run %s)', v_expected, cardinality(v_back), left(p_run_id::text,8)));
  end if;
  v_result:=jsonb_build_object('status','applied','departed',v_expected,'retired',v_expected,'reactivated',cardinality(v_back),'providers_to_review',v_providers,'approved_by',p_actor,'basis','seen tracking');
  update pipeline.layer1_run_plans set departures_status='applied', departures_result=v_result where run_id=p_run_id;
  return v_result;
end $$;


ALTER FUNCTION "security"."layer1_seen_departures_v1"("p_run_id" "uuid", "p_force" boolean, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_assert_profile_executable"("p_profile_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare
  v_enabled boolean;
  v_paused boolean;
  v_version_id uuid;
  v_status text;
begin
  select p.enabled,p.paused,p.current_version_id,v.validation_status
    into v_enabled,v_paused,v_version_id,v_status
  from pipeline.layer2_source_profiles p
  left join pipeline.layer2_source_profile_versions v on v.id=p.current_version_id
  where p.id=p_profile_id;
  if not found then raise exception 'Layer 2 profile not found' using errcode='22023'; end if;
  if not v_enabled then raise exception 'Layer 2 profile is disabled' using errcode='55000'; end if;
  if v_paused then raise exception 'Layer 2 profile is paused' using errcode='55000'; end if;
  if v_version_id is null then raise exception 'Layer 2 profile has no current version' using errcode='55000'; end if;
  if v_status <> 'valid' then raise exception 'Layer 2 profile current version is not valid' using errcode='55000'; end if;
  return v_version_id;
end
$$;


