CREATE OR REPLACE FUNCTION "security"."layer2_operational_alerts_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'public'
    AS $$
declare v_rank integer; v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;

  with alerts as (
    select
      'critical'::text severity,
      'stuck_run'::text code,
      'Layer 2 managed run is stale'::text title,
      ('Run '||b.id::text||' exceeded its '||coalesce(ep.stale_after_minutes,30)||'-minute heartbeat threshold.')::text message,
      b.profile_id,
      b.id run_id,
      null::uuid provider_id,
      coalesce(b.heartbeat_at,b.updated_at,b.started_at,b.created_at) occurred_at
    from pipeline.layer2_run_batches b
    join pipeline.layer2_execution_policies ep on ep.profile_id=b.profile_id
    where b.status='running'
      and coalesce(b.heartbeat_at,b.updated_at,b.started_at,b.created_at)
          < now()-make_interval(mins=>coalesce(ep.stale_after_minutes,30))

    union all

    select
      'warning','paused_profile','Layer 2 Course profile is paused',
      (coalesce(cp.canonical_name,s.label,p.profile_key)||' is paused; scheduled/discovery execution is blocked until explicitly resumed.'),
      p.id,null::uuid,null::uuid,p.updated_at
    from pipeline.layer2_source_profiles p
    join pipeline.sources s on s.id=p.source_id
    left join catalogue.providers cp on cp.id=s.provider_id
    where p.domain='course_facts' and p.enabled and p.paused

    union all

    select
      'warning','blocked_items','Layer 2 run items are blocked',
      (count(*)::text||' Layer 2 item(s) are blocked and require source or route review.'),
      null::uuid,null::uuid,null::uuid,max(updated_at)
    from pipeline.layer2_run_items
    where status='blocked'
    having count(*)>0

    union all

    select
      'warning','provider_failure_streak','Acquisition provider has repeated failures',
      (ap.display_name||' has '||x.failure_count||' failures/blocks in its latest 10 attempts.'),
      null::uuid,null::uuid,ap.id,x.latest_at
    from pipeline.layer2_acquisition_providers ap
    cross join lateral (
      select count(*) filter(where z.status in ('failed','error','blocked')) failure_count,
             max(z.created_at) latest_at
      from (
        select a.status,a.created_at
        from pipeline.layer2_provider_attempts a
        where a.acquisition_provider_id=ap.id
        order by a.created_at desc
        limit 10
      ) z
    ) x
    where ap.enabled and x.failure_count>=5

    union all

    select
      'warning','provider_quota_reserve','Acquisition provider is near quota reserve',
      (ap.display_name||' has '||q.remaining_units||' unit(s) remaining; configured stop reserve is '||q.stop_units||'.'),
      null::uuid,null::uuid,ap.id,q.latest_at
    from pipeline.layer2_acquisition_providers ap
    cross join lateral (
      select
        nullif(a.metrics#>>'{budget_at_start,remaining_after_planned}','')::numeric remaining_units,
        coalesce(nullif(ap.billing_config->>'stop_at_vendor_units_remaining','')::numeric,0) stop_units,
        a.created_at latest_at
      from pipeline.layer2_provider_attempts a
      where a.acquisition_provider_id=ap.id
        and a.metrics#>>'{budget_at_start,remaining_after_planned}' is not null
      order by a.created_at desc
      limit 1
    ) q
    where ap.enabled
      and q.remaining_units is not null
      and q.remaining_units <= q.stop_units + greatest(50,q.stop_units*0.2)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'severity',severity,'code',code,'title',title,'message',message,
    'profile_id',profile_id,'run_id',run_id,'provider_id',provider_id,'occurred_at',occurred_at
  ) order by case severity when 'critical' then 1 when 'warning' then 2 else 3 end, occurred_at desc),'[]'::jsonb)
  into v_result
  from alerts;

  return v_result;
end $$;


ALTER FUNCTION "security"."layer2_operational_alerts_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_provider_budget_status"("p_provider_id" "uuid", "p_planned_units" numeric DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare
  v_provider pipeline.layer2_acquisition_providers%rowtype;
  v_limit numeric;
  v_stop numeric:=0;
  v_unit numeric:=1;
  v_used numeric:=0;
  v_remaining numeric;
  v_allowed boolean:=true;
begin
  select * into v_provider from pipeline.layer2_acquisition_providers where id=p_provider_id;
  if not found then raise exception 'Layer 2 provider not found' using errcode='22023'; end if;
  begin v_limit:=nullif(v_provider.billing_config->>'monthly_vendor_units_limit','')::numeric; exception when invalid_text_representation then v_limit:=null; end;
  begin v_stop:=coalesce(nullif(v_provider.billing_config->>'stop_at_vendor_units_remaining','')::numeric,0); exception when invalid_text_representation then v_stop:=0; end;
  begin v_unit:=coalesce(nullif(v_provider.request_template->>'fixed_credit_units','')::numeric,1); exception when invalid_text_representation then v_unit:=1; end;
  if v_limit is null then
    return jsonb_build_object('provider_id',p_provider_id,'provider_key',v_provider.provider_key,'bounded',false,'planned_units',greatest(coalesce(p_planned_units,v_unit),0),'allowed',true);
  end if;
  select count(*)::numeric*v_unit into v_used
  from pipeline.layer2_provider_attempts
  where acquisition_provider_id=p_provider_id
    and started_at>=date_trunc('month',now())
    and started_at<date_trunc('month',now())+interval '1 month'; v_used:=v_used+coalesce((select sum(u.units) from pipeline.coverage_vendor_usage u where u.acquisition_provider_id=p_provider_id and u.at>=date_trunc('month',now()) and u.at<date_trunc('month',now())+interval '1 month'),0);
  v_remaining:=greatest(v_limit-v_used,0);
  -- the vendor's own balance (read every 15 minutes) less what the platform used since, when lower
  -- Decision 253: Firecrawl's own balance is the authority when read in the last 2 hours.
  v_remaining:=coalesce((select greatest(o.remaining_units
      - coalesce((select sum(u.units) from pipeline.coverage_vendor_usage u where u.acquisition_provider_id=p_provider_id and u.at>o.observed_at),0)
      - (select count(*)::numeric*v_unit from pipeline.layer2_provider_attempts a where a.acquisition_provider_id=p_provider_id and a.started_at>o.observed_at),0)
    from pipeline.vendor_credit_observations o where o.provider_id=p_provider_id and o.observed_at>now()-interval '2 hours'
    order by o.observed_at desc limit 1), v_remaining);
  v_allowed:=(v_remaining-greatest(coalesce(p_planned_units,v_unit),0))>=v_stop;
  return jsonb_build_object(
    'provider_id',p_provider_id,'provider_key',v_provider.provider_key,'bounded',true,
    'period_start',date_trunc('month',now()),'period_end',date_trunc('month',now())+interval '1 month',
    'limit_units',v_limit,'used_units',v_used,'remaining_units',v_remaining,
    'planned_units',greatest(coalesce(p_planned_units,v_unit),0),'remaining_after_planned',greatest(v_remaining-greatest(coalesce(p_planned_units,v_unit),0),0),
    'stop_at_remaining_units',v_stop,'allowed',v_allowed,
    'no_silent_paid_fallback',coalesce((v_provider.billing_config->>'no_silent_paid_fallback')::boolean,false)
  );
end
$$;


ALTER FUNCTION "security"."layer2_provider_budget_status"("p_provider_id" "uuid", "p_planned_units" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_provider_effective_cost_usd"("p_billing" "jsonb", "p_units" numeric DEFAULT 1) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare v_direct numeric;v_plan numeric;v_included numeric;v_per_request numeric;begin
 if p_billing is null or jsonb_typeof(p_billing)<>'object' then return null;end if;
 if coalesce(upper(p_billing->>'currency'),'USD')<>'USD' then return null;end if;
 v_direct:=nullif(p_billing->>'unit_cost_usd','')::numeric;
 if v_direct is not null then return round(v_direct*greatest(coalesce(p_units,1),0),8);end if;
 v_plan:=nullif(p_billing->>'plan_cost_usd','')::numeric;
 v_included:=nullif(p_billing->>'included_units','')::numeric;
 v_per_request:=coalesce(nullif(p_billing->>'units_per_request','')::numeric,1);
 if v_plan is null or v_included is null or v_included<=0 then return null;end if;
 return round((v_plan/v_included)*v_per_request*greatest(coalesce(p_units,1),0),8);
exception when invalid_text_representation then return null;end$$;


ALTER FUNCTION "security"."layer2_provider_effective_cost_usd"("p_billing" "jsonb", "p_units" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_provider_has_secret_keys"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare k text;v jsonb;begin
 if p_value is null then return false;end if;
 if jsonb_typeof(p_value)='object' then
  for k,v in select key,value from jsonb_each(p_value) loop
   if lower(replace(k,'-','_')) in ('secret','password','token','access_token','refresh_token','bearer_token','api_key','authorization','cookie','client_secret','private_key') then return true;end if;
   if security.layer2_provider_has_secret_keys(v) then return true;end if;
  end loop;
 elsif jsonb_typeof(p_value)='array' then
  for v in select value from jsonb_array_elements(p_value) loop if security.layer2_provider_has_secret_keys(v) then return true;end if;end loop;
 end if;return false;end$$;


ALTER FUNCTION "security"."layer2_provider_has_secret_keys"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_provider_sanitise_json"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare k text;v jsonb;result jsonb;begin
 if p_value is null then return null;end if;
 if jsonb_typeof(p_value)='object' then result:='{}'::jsonb;for k,v in select key,value from jsonb_each(p_value) loop if lower(replace(k,'-','_')) not in ('secret','password','token','access_token','refresh_token','bearer_token','api_key','authorization','cookie','client_secret','private_key') then result:=result||jsonb_build_object(k,security.layer2_provider_sanitise_json(v));end if;end loop;return result;
 elsif jsonb_typeof(p_value)='array' then select coalesce(jsonb_agg(security.layer2_provider_sanitise_json(value)),'[]'::jsonb) into result from jsonb_array_elements(p_value);return result;
 end if;return p_value;end$$;


