CREATE OR REPLACE FUNCTION "security"."layer2_sanitise_config"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $_$
declare
  v_type text;
  v_result jsonb;
  v_key text;
  v_item jsonb;
begin
  if p_value is null then return null; end if;
  v_type:=jsonb_typeof(p_value);
  if v_type='object' then
    v_result:='{}'::jsonb;
    for v_key,v_item in select key,value from jsonb_each(p_value) loop
      if lower(v_key) ~ '^(secret|password|token|api[_-]?key|authorization|cookie|client[_-]?secret)$' then
        continue;
      end if;
      v_result:=v_result||jsonb_build_object(v_key,security.layer2_sanitise_config(v_item));
    end loop;
    return v_result;
  elsif v_type='array' then
    select coalesce(jsonb_agg(security.layer2_sanitise_config(value)),'[]'::jsonb) into v_result from jsonb_array_elements(p_value);
    return v_result;
  end if;
  return p_value;
end
$_$;


ALTER FUNCTION "security"."layer2_sanitise_config"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_scheduler_discovery_context_v1"("p_preview_token" "uuid", "p_profile_id" "uuid", "p_course_ids" "uuid"[], "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_binding pipeline.scheduler_workflow_async_bindings%rowtype; v_ctx jsonb; v_courses jsonb; v_resolved jsonb; v_requested uuid[]; v_requested_count integer:=0;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 if p_preview_token is null or p_profile_id is null then raise exception 'scheduler preview/profile binding required' using errcode='22023'; end if;
 select coalesce(array_agg(distinct x order by x),'{}'::uuid[]) into v_requested from unnest(coalesce(p_course_ids,'{}'::uuid[])) x; v_requested_count:=cardinality(v_requested);
 if v_requested_count=0 or v_requested_count>1000 then raise exception 'bounded course_ids required' using errcode='22023'; end if;
 select * into v_binding from pipeline.scheduler_workflow_async_bindings b where b.preview_token=p_preview_token and b.profile_id=p_profile_id for update;
 if not found then raise exception 'scheduler async binding not found' using errcode='22023'; end if;
 if v_binding.status<>'active' then raise exception 'scheduler async binding is not active' using errcode='22023'; end if;
 if v_binding.execution_expires_at is null or v_binding.execution_expires_at<=now() then raise exception 'scheduler async execution binding expired' using errcode='22023'; end if;
 if not (v_binding.discovery_course_ids @> v_requested) then raise exception 'requested discovery chunk is outside the exact Preview-bound set' using errcode='22023'; end if;
 select public.layer2_runtime_context(p_profile_id) into v_ctx;
 if v_ctx is null or v_ctx->>'domain'<>'course_facts' then raise exception 'course_facts profile required' using errcode='22023'; end if;
 if nullif(v_ctx->>'version_id','')::uuid<>v_binding.profile_version_id then raise exception 'profile version changed after Preview' using errcode='22023'; end if;
 with requested as (select unnest(v_requested) course_id), resolved as (
  select r.course_id from requested r where exists(select 1 from pipeline.layer2_course_discovery_candidates d where d.course_id=r.course_id and d.source_profile_version_id=v_binding.profile_version_id and d.selected=true and nullif(d.discovered_url,'') is not null and d.created_at>=v_binding.activated_at)
 ), unresolved as (select r.course_id from requested r where not exists(select 1 from resolved x where x.course_id=r.course_id)), bounded as (
  select c.id,c.canonical_title,c.display_title,c.course_code from unresolved u join catalogue.courses c on c.id=u.course_id join pipeline.sources s on s.provider_id=c.provider_id join pipeline.layer2_source_profiles lp on lp.source_id=s.id and lp.id=p_profile_id order by c.canonical_title,c.id limit least(greatest(coalesce(p_limit,50),1),50)
 )
 select coalesce((select jsonb_agg(to_jsonb(b) order by b.canonical_title,b.id) from bounded b),'[]'::jsonb),coalesce((select jsonb_agg(r.course_id order by r.course_id) from resolved r),'[]'::jsonb) into v_courses,v_resolved;
 return jsonb_build_object('runtime',v_ctx,'courses',v_courses,'scheduler_preview_token',p_preview_token,'requested_count',v_requested_count,'resolved_course_ids',v_resolved,'resolved_count',jsonb_array_length(v_resolved),'historical_dispositions_are_retryable',true);
end
$$;


ALTER FUNCTION "security"."layer2_scheduler_discovery_context_v1"("p_preview_token" "uuid", "p_profile_id" "uuid", "p_course_ids" "uuid"[], "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_validate_profile_config"("p_config" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare v_errors jsonb:='[]'::jsonb;v_method text:=coalesce(p_config->>'acquisition_method','');
v_target text:=coalesce(p_config->>'target_entity_type','');v_text text:=lower(p_config::text);
begin
 if v_method not in ('website','course_catalogue','course_detail','fee_schedule','intake_calendar','english_requirements','scholarship_catalogue','document','structured_api','json_endpoint','csv_feed','xlsx_feed','sitemap','search_endpoint','other_deterministic') then v_errors:=v_errors||jsonb_build_array('unsupported acquisition_method'); end if;
 if v_target not in ('provider','course','campus','scholarship','provider_asset','provider_outcome','student_flow','course_fact','mixed') then v_errors:=v_errors||jsonb_build_array('unsupported target_entity_type'); end if;
 if coalesce(p_config->>'base_domain','')='' and coalesce(p_config->>'discovery_url','')='' then v_errors:=v_errors||jsonb_build_array('base_domain or discovery_url is required'); end if;
 if coalesce((p_config->>'timeout_seconds')::integer,30)<1 or coalesce((p_config->>'timeout_seconds')::integer,30)>120 then v_errors:=v_errors||jsonb_build_array('timeout_seconds must be between 1 and 120'); end if;
 if coalesce((p_config->>'concurrency')::integer,1)<1 or coalesce((p_config->>'concurrency')::integer,1)>20 then v_errors:=v_errors||jsonb_build_array('concurrency must be between 1 and 20'); end if;
 if coalesce((p_config->>'max_payload_mb')::integer,10)<1 or coalesce((p_config->>'max_payload_mb')::integer,10)>100 then v_errors:=v_errors||jsonb_build_array('max_payload_mb must be between 1 and 100'); end if;
 if v_text ~ '"(secret|password|token|api[_-]?key|authorization|cookie|client[_-]?secret)"[[:space:]]*:' then v_errors:=v_errors||jsonb_build_array('secret-like configuration keys are prohibited; use server-side secret references only'); end if;
 if coalesce(p_config->>'evidence_required','true')<>'true' then v_errors:=v_errors||jsonb_build_array('Layer 2 evidence_required must be true'); end if;
 return jsonb_build_object('valid',jsonb_array_length(v_errors)=0,'errors',v_errors,'validated_at',now());
exception when others then return jsonb_build_object('valid',false,'errors',jsonb_build_array('configuration type validation failed'),'validated_at',now());
end $$;


ALTER FUNCTION "security"."layer2_validate_profile_config"("p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_wave_parent_stamp"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'ref', 'security'
    AS $$
declare
  v_terminal uuid;
  v_root uuid;
begin
  select q.id into v_terminal
  from pipeline.layer2_scale_qualification_runs q
  join ref.countries c on c.id=q.country_id
  where q.requested_by=new.requested_by
    and c.iso_alpha2::text=upper(new.country_code)
    and q.scope_type=new.scope_type
    and q.scope_id is not distinct from new.scope_id
    and q.status in('completed','partial')
    and coalesce((q.result_summary->>'auto_progress_scope')::boolean,false)
  order by
    case when not coalesce((q.result_summary->>'auto_progress_processed')::boolean,false) then 0 else 1 end,
    q.completed_at desc nulls last,q.created_at desc
  limit 1;

  if v_terminal is not null then
    v_root:=security.layer2_qualification_root(v_terminal);
  end if;

  update pipeline.layer2_scope_wave_requests
  set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
    'parent_run_id',coalesce(v_root,new.id),
    'parent_run_kind',case when v_root is null then 'scope_wave_request' else 'qualification_root' end,
    'qualification_terminal_run_id',v_terminal,
    'scope_wave_request_id',new.id,
    'lineage_version','a26-v1'
  )
  where id=new.id;
  return new;
end $$;


ALTER FUNCTION "security"."layer2_wave_parent_stamp"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_benchmark_claim_impl"("p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_job pipeline.layer3_benchmark_jobs%rowtype;
begin
  update pipeline.layer3_benchmark_jobs
  set status='expired'
  where status='pending' and expires_at<=now();
  select * into v_job from pipeline.layer3_benchmark_jobs
  where token_hash=p_token_hash and status='pending' and expires_at>now()
  for update skip locked;
  if not found then raise exception 'benchmark job not available' using errcode='42501'; end if;
  update pipeline.layer3_benchmark_jobs set status='claimed',claimed_at=now() where id=v_job.id;
  return jsonb_build_object('job_id',v_job.id,'profile_id',v_job.profile_id,'actor_id',v_job.actor_id);
end $$;


ALTER FUNCTION "security"."layer3_benchmark_claim_impl"("p_token_hash" "text") OWNER TO "postgres";


