    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$ declare v pipeline.layer3_benchmark_jobs%rowtype; begin
 update pipeline.layer3_benchmark_jobs set status='expired' where status='pending' and expires_at<=now();
 select * into v from pipeline.layer3_benchmark_jobs where id=p_job_id and status='pending' and expires_at>now() for update skip locked;
 if not found then raise exception 'benchmark job not available' using errcode='42501'; end if;
 update pipeline.layer3_benchmark_jobs set status='claimed',claimed_at=now() where id=v.id;
 return jsonb_build_object('job_id',v.id,'profile_id',v.profile_id,'actor_id',v.actor_id);
end $$;


ALTER FUNCTION "security"."layer3_benchmark_claim_job_impl"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_benchmark_profile_impl"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare p pipeline.layer3_model_profiles%rowtype;
begin
  select * into p from pipeline.layer3_model_profiles where id=p_profile_id;
  if not found then raise exception 'profile not found'; end if;
  return jsonb_build_object(
    'id',p.id,'code',p.code,'aggregator_provider',p.aggregator_provider,'base_url',p.base_url,'model_identifier',p.model_identifier,
    'allowed_task_classes',p.allowed_task_classes,'prompt_profile_version',p.prompt_profile_version,'prompt_system',p.prompt_system,
    'structured_output_schema',p.structured_output_schema,'deterministic_validators',p.deterministic_validators,
    'max_input_tokens',p.max_input_tokens,'max_output_tokens',p.max_output_tokens,'requests_per_minute',p.requests_per_minute,
    'requests_per_day',p.requests_per_day,'retry_ceiling',p.retry_ceiling,'timeout_ms',p.timeout_ms,'cost_ceiling_usd',p.cost_ceiling_usd,
    'fallback_profile_id',p.fallback_profile_id,'enabled',p.enabled,'paused',p.paused,'last_validation_result',p.last_validation_result
  );
end $$;


ALTER FUNCTION "security"."layer3_benchmark_profile_impl"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_benchmark_record_impl"("p_job_id" "uuid", "p_profile_id" "uuid", "p_actor" "uuid", "p_pass" boolean, "p_provider_cases" "jsonb", "p_control_cases" "jsonb", "p_configured_model" "text", "p_returned_models" "text"[], "p_external_call_count" integer, "p_input_tokens" integer, "p_output_tokens" integer, "p_estimated_cost_usd" numeric, "p_max_latency_ms" integer, "p_evidence_ids" "uuid"[], "p_summary" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_rank int:=0; v_run_id uuid; v_profile pipeline.layer3_model_profiles%rowtype; v_state text;
begin
  select coalesce(max(r.rank),0) into v_rank from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=p_actor and r.status='active' and (ur.expires_at is null or ur.expires_at>now());
  if v_rank<6 then raise exception 'platform admin role required' using errcode='42501'; end if;
  select * into v_profile from pipeline.layer3_model_profiles where id=p_profile_id;
  if not found then raise exception 'profile not found'; end if;
  if coalesce(v_profile.last_validation_result->>'state','')<>'credential_verified_pending_benchmark' then raise exception 'credential verification required before benchmark'; end if;
  v_state:=case when p_pass then 'benchmark_passed' else 'benchmark_failed' end;
  insert into pipeline.layer3_quality_benchmark_runs(profile_id,actor_id,status,provider_case_results,control_case_results,configured_model,returned_models,external_call_count,input_tokens,output_tokens,estimated_cost_usd,max_latency_ms,evidence_ids,prompt_profile_version,validator_profile,summary,completed_at)
  values(p_profile_id,p_actor,case when p_pass then 'pass' else 'fail' end,coalesce(p_provider_cases,'[]'::jsonb),coalesce(p_control_cases,'[]'::jsonb),p_configured_model,coalesce(p_returned_models,'{}'::text[]),greatest(coalesce(p_external_call_count,0),0),greatest(coalesce(p_input_tokens,0),0),greatest(coalesce(p_output_tokens,0),0),greatest(coalesce(p_estimated_cost_usd,0),0),greatest(coalesce(p_max_latency_ms,0),0),coalesce(p_evidence_ids,'{}'::uuid[]),v_profile.prompt_profile_version,coalesce(v_profile.deterministic_validators,'{}'::jsonb),left(coalesce(p_summary,''),1000),now()) returning id into v_run_id;
  update pipeline.layer3_model_profiles set
    paused=not p_pass,
    quality_benchmark=jsonb_build_object('run_id',v_run_id,'pass',p_pass,'completed_at',now(),'configured_model',p_configured_model,'returned_models',coalesce(p_returned_models,'{}'::text[]),'external_call_count',p_external_call_count,'input_tokens',p_input_tokens,'output_tokens',p_output_tokens,'estimated_cost_usd',p_estimated_cost_usd,'max_latency_ms',p_max_latency_ms,'summary',left(coalesce(p_summary,''),1000),'change_control_ref','CF-CHG-20260825-038','uat_ref','M2.3-Go5-real-provider-benchmark'),
    last_validation_result=jsonb_build_object('state',v_state,'validated',p_pass,'credential_configured',true,'credential_verified',true,'benchmark_passed',p_pass,'benchmark_run_id',v_run_id,'completed_at',now(),'message',left(coalesce(p_summary,''),500)),
    updated_at=now()
  where id=p_profile_id;
  update pipeline.layer3_benchmark_jobs set status=case when p_pass then 'completed' else 'failed' end,completed_at=now() where id=p_job_id and profile_id=p_profile_id and actor_id=p_actor;
  return jsonb_build_object('ok',true,'pass',p_pass,'run_id',v_run_id,'state',v_state,'profile_paused',not p_pass);
end $$;


ALTER FUNCTION "security"."layer3_benchmark_record_impl"("p_job_id" "uuid", "p_profile_id" "uuid", "p_actor" "uuid", "p_pass" boolean, "p_provider_cases" "jsonb", "p_control_cases" "jsonb", "p_configured_model" "text", "p_returned_models" "text"[], "p_external_call_count" integer, "p_input_tokens" integer, "p_output_tokens" integer, "p_estimated_cost_usd" numeric, "p_max_latency_ms" integer, "p_evidence_ids" "uuid"[], "p_summary" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_evidence_candidates_impl"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'auth'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<3 then
    raise exception 'curator role required' using errcode='42501';
  end if;
  return coalesce((
    with eligible as (
      select
        ri.entity_type,ri.entity_id,ri.status as layer2_status,ri.outcome_code,
        pa.id as provider_attempt_id,pa.completed_at,
        ev.id as evidence_id,ev.evidence_type,ev.source_url,ev.mime_type,ev.content_hash,
        ev.captured_at,ev.review_state,
        case when ev.id=pa.raw_evidence_id then 1 else 2 end as evidence_rank,
        row_number() over(
          partition by ri.entity_type,ri.entity_id
          order by
            case when ev.id=pa.raw_evidence_id then 1 else 2 end,
            pa.completed_at desc nulls last,
            ev.captured_at desc nulls last,
            ev.id
        ) as rn
      from pipeline.layer2_run_items ri
      join pipeline.layer2_provider_attempts pa on pa.job_id=ri.job_id and pa.status='succeeded'
      join lateral (
        select e.*
        from pipeline.evidence_artifacts e
        where e.id in (pa.raw_evidence_id,pa.html_evidence_id)
          and e.storage_path is not null
          and e.content_hash is not null
          and (e.valid_to is null or e.valid_to>now())
          and coalesce(e.review_state,'') not in ('rejected','invalid')
          and (
            e.mime_type is null
            or e.mime_type like 'text/%'
            or e.mime_type in ('application/json','application/xml','application/xhtml+xml')
          )
        order by case when e.id=pa.raw_evidence_id then 1 else 2 end
      ) ev on true
      where ri.entity_type='course'
        and ri.status='layer3_required'
    ),
    chosen as (
      select e.*,
             coalesce(c.display_title,c.canonical_title,c.course_code,e.entity_id::text) as entity_label
      from eligible e
      left join catalogue.courses c on c.id=e.entity_id
      where e.rn=1
      order by e.completed_at desc nulls last,e.captured_at desc nulls last
      limit least(greatest(coalesce(p_limit,50),1),100)
    )
    select jsonb_agg(jsonb_build_object(
      'entity_type',entity_type,
      'entity_id',entity_id,
      'entity_label',entity_label,
      'layer2_status',layer2_status,
      'outcome_code',outcome_code,
      'provider_attempt_id',provider_attempt_id,
      'evidence_id',evidence_id,
      'evidence_type',evidence_type,
      'source_url',source_url,
      'mime_type',mime_type,
      'content_hash',content_hash,
      'captured_at',captured_at,
      'review_state',review_state,
      'selection_reason',case when evidence_rank=1
        then 'latest_successful_layer2_native_evidence'
        else 'latest_successful_layer2_html_evidence'
      end
    ))
    from chosen
  ),'[]'::jsonb);
end $$;


ALTER FUNCTION "security"."layer3_evidence_candidates_impl"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_fact_admit_v1"("p_task_class" "text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security', 'search'
    AS $$
declare p pipeline.layer3_model_profiles; r record; v_payload jsonb; v_cur jsonb; v_prop jsonb; v_same boolean; v_ok int:=0; v_same_n int:=0; v_l4 int:=0; v_err int:=0; v_last text;
        v_courses uuid[]:='{}'; v_before jsonb; v_after jsonb; v_src uuid; v_domain text; v_gate text; v_field text; v_label text;
begin
  if current_user not in ('postgres','service_role') and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
  if p_task_class not in ('provider_intake_validation','provider_english_validation') then raise exception 'unsupported task class'; end if;
  p:=pipeline.layer3_routed_profile(p_task_class);
  if p.id is null then return jsonb_build_object('admitted',0,'reason','no routed profile: admission stopped for '||p_task_class); end if;
  v_domain:=case p_task_class when 'provider_intake_validation' then 'intake' else 'english_requirement' end;
  v_gate:=case p_task_class when 'provider_intake_validation' then 'course_intake' else 'course_english' end;
  v_field:=v_gate;
  if not exists (select 1 from pipeline.layer3_work_items w where w.task_class=p_task_class and w.status='validated') then
    return jsonb_build_object('task_class',p_task_class,'admitted',0,'note','nothing waiting');
  end if;
  v_before:=security.consumer_api_snapshot_v1();
  for r in
    select w.id wid, w.entity_id course_id, w.evidence_id, i.id iid, i.candidate_value cv, i.aggregator_response_model model, i.profile_id,
           pg.provider_id, pg.url, e.content_hash,
           (select pr.registration_code from catalogue.provider_registrations pr where pr.provider_id=pg.provider_id and lower(pr.registration_scheme)='cricos' and coalesce(pr.status,'active') not in ('inactive','cancelled','archived') order by pr.checked_at desc nulls last limit 1) pc,
           (select cr.registration_code from catalogue.course_registrations cr where cr.course_id=w.entity_id and lower(cr.scheme)='cricos' limit 1) cc
      from pipeline.layer3_work_items w
      join pipeline.layer3_interpretations i on i.id=w.interpretation_id and i.status='validated'
      join pipeline.coverage_course_pages pg on pg.course_id=w.entity_id and pg.evidence_id=w.evidence_id and security.coverage_identity_allowed(pg.provider_id, pg.identity_basis, case p_task_class when 'provider_intake_validation' then 'intakes' else 'english' end)
      join pipeline.evidence_artifacts e on e.id=w.evidence_id
     where w.task_class=p_task_class and w.status='validated'
       and (i.profile_id=p.id or exists (select 1 from pipeline.layer3_route_tiers t where t.task_class=p_task_class and t.active and t.profile_id=i.profile_id))
     order by w.updated_at limit greatest(1,least(coalesce(p_limit,100),300))
     for update of w skip locked
  loop
    begin
      if (r.pc is null or r.cc is null) and security.coverage_country(r.provider_id) = 'AU' then raise exception 'provider or course CRICOS unresolved'; end if;
      if security.layer4_entity_or_parent_blocked('course',r.course_id,'operational') then raise exception 'course operationally blocked by Layer 4'; end if;
      if p_task_class='provider_intake_validation' then
        v_prop:=(select jsonb_agg(jsonb_build_object('intake_label',(array['January','February','March','April','May','June','July','August','September','October','November','December'])[m::int],
                   'source_intake_key',lower(r.cc)||':current:'||lower((array['January','February','March','April','May','June','July','August','September','October','November','December'])[m::int])) order by m::int)
                   from jsonb_array_elements_text(r.cv->'months') m);
        select jsonb_agg(i.intake_label) into v_cur from catalogue.course_intakes i where i.course_id=r.course_id and coalesce(i.status,'active')='active';
        v_same:=v_cur is not null and not exists (select 1 from jsonb_array_elements(v_prop) x where not exists (select 1 from jsonb_array_elements_text(v_cur) k(v) where k.v ilike '%'||(x->>'intake_label')||'%'));
        v_payload:=jsonb_build_object('intakes',v_prop);
      else
        v_prop:=(select jsonb_agg(case when t->>'test'='IELTS' then
                    jsonb_build_object('test_code','IELTS','overall_score',(t->>'overall')::numeric,
                      'component_scores',case when t->>'min_band' is not null then jsonb_build_object('listening',(t->>'min_band')::numeric,'reading',(t->>'min_band')::numeric,'writing',(t->>'min_band')::numeric,'speaking',(t->>'min_band')::numeric) else '{}'::jsonb end,
                      'notes','Course page (CRICOS code on page), Layer 3 '||coalesce(r.model,''))
                  else jsonb_build_object('test_code',t->>'test','overall_score',(t->>'overall')::numeric,'notes','Course page (CRICOS code on page), Layer 3 '||coalesce(r.model,'')) end)
                   from jsonb_array_elements(r.cv->'tests') t);
        select jsonb_agg(jsonb_build_object('test',t.code,'overall',er.overall_score)) into v_cur from catalogue.course_english_requirements er join ref.english_tests t on t.id=er.english_test_id
         where er.course_id=r.course_id and er.status='active';
        v_same:=v_cur is not null and not exists (select 1 from jsonb_array_elements(v_prop) x where not exists (select 1 from jsonb_array_elements(v_cur) k(v) where k.v->>'test'=x->>'test_code' and (k.v->>'overall')::numeric=(x->>'overall_score')::numeric));
        v_payload:=jsonb_build_object('english_requirements',v_prop);
      end if;
      if v_prop is null or jsonb_array_length(v_prop)=0 then raise exception 'empty admitted value'; end if;

      if v_cur is not null then
        if v_same then
          update pipeline.layer3_work_items set status='admitted', completed_at=now(), last_error='admitted: the same value is already held', updated_at=now() where id=r.wid;
          v_same_n:=v_same_n+1;
        else
          insert into pipeline.layer4_review_items(entity_type,entity_id,field_code,evidence_id,layer3_interpretation_id,before_value,proposed_value,layer2_state,layer3_state,status,escalation_reason,change_control_ref)
          values ('course',r.course_id,v_field,r.evidence_id,r.iid,v_cur,v_prop,jsonb_build_object('source','coverage sweep','page',r.url),jsonb_build_object('model',r.model,'candidate_value',r.cv),'pending',
                  case p_task_class when 'provider_intake_validation' then 'The course page lists different intake months from the ones we hold. Please check the page and confirm the intakes.'
                       else 'The course page gives a different English score from the one we hold. Please check the page and confirm the requirement.' end,'CF-CHG-20260915-247');
          update pipeline.layer3_work_items set status='layer4_required', last_error='differs from the value already held', updated_at=now() where id=r.wid;
          v_l4:=v_l4+1;
        end if;
        continue;
      end if;

      v_src:=security.coverage_sweep_source(r.provider_id);
      if r.pc is null then null;
      elsif not exists (select 1 from pipeline.course_fact_source_qualifications q where q.source_id=v_src and q.provider_cricos=upper(r.pc)) then
        insert into pipeline.course_fact_source_qualifications(source_id,country_id,source_key,source_class,authority_name,provider_cricos,admitted_domains,mapping_strategy,evidence_strategy,qualification_status,notes,metadata)
        select v_src, s.country_id, 'au_'||lower(r.pc)||'_coverage_sweep','provider_first_party', coalesce(pv.display_name,pv.canonical_name), upper(r.pc),
               array['official_course_url','english_requirement','intake'], 'course page accepted only when it prints the course''s CRICOS code',
               'page stored gzipped as evidence with its SHA-256; values written only where the course has none; value read by the qualified Layer 3 model',
               'bounded','Decision 163 admission rule; Layer 3 model routing (Platform Admin 29 Sep 2026 18:30 IST)',
               jsonb_build_object('decision','Decision 163','apply_admitted',true,'search_admitted',true,'identity_authority',false,'change_control_ref','CF-CHG-20260915-247')
          from pipeline.sources s join catalogue.providers pv on pv.id=r.provider_id where s.id=v_src;
      else
        update pipeline.course_fact_source_qualifications set admitted_domains=array(select distinct unnest(admitted_domains||array[v_domain])), updated_at=now()
         where source_id=v_src and provider_cricos=upper(r.pc) and not (v_domain=any(admitted_domains));
      end if;
      insert into search.enrichment_source_gates(projection_code,domain_code,source_id,gate_status,approval_ref,approved_at,created_at,updated_at)
      select 'courses',v_gate,v_src,'approved','CF-CHG-20260915-247; Layer 3 model routing; Platform Admin direction 29 Sep 2026 18:30 IST',now(),now(),now()
       where not exists (select 1 from search.enrichment_source_gates g where g.projection_code='courses' and g.domain_code=v_gate and g.source_id=v_src);

      if r.pc is null or r.cc is null then perform security.coverage_apply_course_v1(r.course_id, v_src, r.evidence_id, r.url, r.content_hash, v_payload); else perform public.svc_coursefacts_apply_record(v_src, r.evidence_id, r.pc, r.cc, 'l3:'||p_task_class||':'||r.course_id, r.url, r.content_hash, v_payload, true); end if;
      update pipeline.layer3_work_items set status='admitted', completed_at=now(), last_error=null, updated_at=now() where id=r.wid;
      v_ok:=v_ok+1; v_courses:=v_courses||r.course_id;
    exception when others then
      v_err:=v_err+1; v_last:=left(sqlerrm,200);
      update pipeline.layer3_work_items set status='layer4_required', last_error=left('admission failed: '||sqlerrm,500), updated_at=now() where id=r.wid;
      insert into pipeline.layer4_review_items(entity_type,entity_id,field_code,evidence_id,layer3_interpretation_id,proposed_value,layer2_state,layer3_state,status,escalation_reason,change_control_ref)
      values ('course',r.course_id,v_field,r.evidence_id,r.iid,r.cv,'{}'::jsonb,jsonb_build_object('admission_error',left(sqlerrm,300)),'pending',
              'The AI''s answer could not be recorded automatically. Please check the page and confirm the value.','CF-CHG-20260915-247');
    end;
  end loop;
  if cardinality(v_courses)>0 then
    perform search.refresh_course_enrichment_scoped_v1(v_courses,true);
    v_after:=security.consumer_api_snapshot_v1();
    v_label:=case p_task_class when 'provider_intake_validation' then 'intake' else 'English' end;
    insert into pipeline.consumer_api_baselines(label,snapshot) values
      ('before Layer 3 '||v_label||' admission batch ('||cardinality(v_courses)||' courses, model routing)',v_before),
      ('after Layer 3 '||v_label||' admission batch ('||cardinality(v_courses)||' courses, model routing)',v_after);
  end if;
  return jsonb_build_object('task_class',p_task_class,'admitted',v_ok,'already_held_same',v_same_n,'layer4_differs',v_l4,'errors',v_err,'last_error',v_last);
end $$;


ALTER FUNCTION "security"."layer3_fact_admit_v1"("p_task_class" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_model_profile_set_state_impl"("p_profile_id" "uuid", "p_enabled" boolean, "p_paused" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<4 then raise exception 'administrator role required' using errcode='42501'; end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'governance reason required'; end if;
  if p_paused is false and exists(select 1 from pipeline.layer3_model_profiles where id=p_profile_id and paused) then
    raise exception 'unpausing a Layer 3 profile requires the governed activation gate (layer3_profile_activate)' using errcode='42501';
  end if;
  update pipeline.layer3_model_profiles set enabled=p_enabled,paused=p_paused,
    last_validation_result=coalesce(last_validation_result,'{}'::jsonb)||jsonb_build_object('state_change_reason',trim(p_reason),'state_changed_at',now(),'state_changed_by',auth.uid()),
    updated_at=now() where id=p_profile_id;
  if not found then raise exception 'profile not found'; end if;
  return jsonb_build_object('ok',true,'profile_id',p_profile_id,'enabled',p_enabled,'paused',p_paused);
end $$;


