CREATE OR REPLACE FUNCTION "security"."layer3_model_profiles_admin_impl"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth', 'vault'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'curator role required' using errcode='42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id',p.id,'code',p.code,'aggregator_provider',p.aggregator_provider,'base_url',p.base_url,'model_identifier',p.model_identifier,
    'allowed_task_classes',p.allowed_task_classes,'prompt_profile_version',p.prompt_profile_version,'structured_output_schema',p.structured_output_schema,
    'deterministic_validators',p.deterministic_validators,'max_input_tokens',p.max_input_tokens,'max_output_tokens',p.max_output_tokens,
    'requests_per_minute',p.requests_per_minute,'requests_per_day',p.requests_per_day,'retry_ceiling',p.retry_ceiling,'timeout_ms',p.timeout_ms,
    'fallback_profile_id',p.fallback_profile_id,'cost_ceiling_usd',p.cost_ceiling_usd,'enabled',p.enabled,'paused',p.paused,
    'credential_configured',exists(select 1 from vault.secrets s where s.name=security.layer3_provider_credential_name(p.id)),
    'credential_updated_at',(select s.updated_at from vault.secrets s where s.name=security.layer3_provider_credential_name(p.id) limit 1),
    'last_validation_result',p.last_validation_result,'quality_benchmark',p.quality_benchmark,'change_control_ref',p.change_control_ref,'uat_ref',p.uat_ref,
    'updated_at',p.updated_at
  ) order by p.code) from pipeline.layer3_model_profiles p),'[]'::jsonb);
end $$;


ALTER FUNCTION "security"."layer3_model_profiles_admin_impl"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_operational_alerts_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare
  v_rank integer;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode='42501';
  end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0) < 4 then
    raise exception 'pipeline_operator role required' using errcode='42501';
  end if;

  with alerts as (
    select
      'critical'::text severity,
      'stale_execution'::text code,
      'Layer 3 execution exceeded recovery window'::text title,
      ('Interpretation '||i.id::text||' has remained '||i.status||' beyond the governed 20-minute recovery window.')::text message,
      i.profile_id,
      i.id interpretation_id,
      i.created_at occurred_at
    from pipeline.layer3_interpretations i
    where i.status in ('reserved','calling')
      and i.created_at < now()-interval '20 minutes'

    union all

    select
      'warning','paused_profile','Layer 3 model profile is paused',
      (p.code||' is enabled but paused; governed AI execution is blocked until explicitly resumed.'),
      p.id,null::uuid,p.updated_at
    from pipeline.layer3_model_profiles p
    where p.enabled and p.paused

    union all

    select
      'critical','unqualified_profile','Layer 3 enabled profile is not benchmark-qualified',
      (p.code||' is enabled/unpaused but its current governed quality benchmark is not PASS.'),
      p.id,null::uuid,p.updated_at
    from pipeline.layer3_model_profiles p
    where p.enabled and not p.paused
      and not coalesce((p.quality_benchmark->>'pass')::boolean,false)

    union all

    select
      'warning','latest_benchmark_failed','Latest Layer 3 benchmark failed',
      (p.code||' latest benchmark status is '||b.status||'; retain failure evidence and requalify before relying on the profile.'),
      p.id,null::uuid,b.created_at
    from pipeline.layer3_model_profiles p
    join lateral (
      select q.status,q.created_at
      from pipeline.layer3_quality_benchmark_runs q
      where q.profile_id=p.id
      order by q.created_at desc
      limit 1
    ) b on true
    where p.enabled and not p.paused and b.status <> 'pass'

    union all

    select
      'warning','provider_error_streak','Layer 3 profile has repeated provider errors',
      (p.code||' has '||x.failure_count||' provider_error result(s) in its latest 10 interpretations.'),
      p.id,null::uuid,x.latest_at
    from pipeline.layer3_model_profiles p
    cross join lateral (
      select
        count(*) filter(where z.status='provider_error') failure_count,
        max(z.created_at) latest_at
      from (
        select i.status,i.created_at
        from pipeline.layer3_interpretations i
        where i.profile_id=p.id
        order by i.created_at desc
        limit 10
      ) z
    ) x
    where p.enabled and x.failure_count>=5

    union all

    select
      'warning','cost_ceiling_exceeded','Layer 3 recorded cost exceeded profile ceiling',
      (p.code||' has a recent recorded call cost above its configured per-execution ceiling; review provider/model billing telemetry.'),
      p.id,null::uuid,max(i.created_at)
    from pipeline.layer3_model_profiles p
    join pipeline.layer3_interpretations i on i.profile_id=p.id
    where i.created_at>=now()-interval '30 days'
      and coalesce(i.external_call_count,0)>0
      and i.estimated_cost_usd is not null
      and p.cost_ceiling_usd is not null
      and i.estimated_cost_usd>p.cost_ceiling_usd
    group by p.id,p.code
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'severity',severity,
    'code',code,
    'title',title,
    'message',message,
    'profile_id',profile_id,
    'interpretation_id',interpretation_id,
    'occurred_at',occurred_at
  ) order by case severity when 'critical' then 1 when 'warning' then 2 else 3 end, occurred_at desc),'[]'::jsonb)
  into v_result
  from alerts;

  return v_result;
end
$$;


ALTER FUNCTION "security"."layer3_operational_alerts_read"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer3_operational_alerts_read"() IS 'M2.4.4 operator alert surface for Layer 3 stale execution, profile qualification/state, provider-error streaks and recorded cost-ceiling breaches. Does not mutate canonical, Evidence or history.';



CREATE OR REPLACE FUNCTION "security"."layer3_profile_activate_impl"("p_profile_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth', 'vault'
    AS $_$
declare
  p pipeline.layer3_model_profiles%rowtype;
  v_fail text[] := '{}';
  v_completed timestamptz;
  v_hash text;
  v_conflict text;
  v_checks jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then
    raise exception 'administrator role required to activate a Layer 3 profile' using errcode='42501';
  end if;
  if length(btrim(coalesce(p_reason,''))) < 8 then raise exception 'activation reason required (8+ characters)'; end if;
  select * into p from pipeline.layer3_model_profiles where id = p_profile_id for update;
  if not found then raise exception 'profile not found'; end if;

  v_completed := nullif(p.quality_benchmark->>'completed_at','')::timestamptz;
  v_hash := p.quality_benchmark->>'binding_hash';
  if not p.enabled then v_fail := array_append(v_fail, 'profile is disabled'); end if;
  if not p.paused then v_fail := array_append(v_fail, 'profile is already active'); end if;
  if coalesce((p.quality_benchmark->>'pass')::boolean,false) is not true then v_fail := array_append(v_fail, 'quality benchmark has not passed'); end if;
  if v_completed is null or v_completed < now() - interval '14 days' then
    v_fail := array_append(v_fail, 'benchmark pass is missing or older than 14 days; re-benchmark required');
  end if;
  if 'provider_current_tuition_validation' = any(p.allowed_task_classes) and coalesce(v_hash,'') !~ '^[0-9a-f]{64}$' then
    v_fail := array_append(v_fail, 'no qualified binding hash on record');
  end if;
  if not exists(select 1 from vault.secrets s where s.name = security.layer3_provider_credential_name(p.id)) then
    v_fail := array_append(v_fail, 'provider credential not configured');
  end if;
  select string_agg(o.code, ', ' order by o.code) into v_conflict
  from pipeline.layer3_model_profiles o
  where o.id <> p.id and o.enabled and not o.paused and o.allowed_task_classes && p.allowed_task_classes;
  if v_conflict is not null then v_fail := array_append(v_fail, ('another profile is already active for this task class: ' || v_conflict)); end if;

  v_checks := jsonb_build_object('benchmark_completed_at', v_completed, 'benchmark_pass', p.quality_benchmark->'pass',
    'binding_hash', v_hash, 'model_identifier', p.model_identifier, 'failed', to_jsonb(v_fail));

  if cardinality(v_fail) > 0 then
    insert into pipeline.layer3_profile_activation_events(profile_id, action, actor_id, reason, binding_hash, benchmark_run_id, checks)
    values (p.id, 'activation_refused', auth.uid(), btrim(p_reason), v_hash, p.quality_benchmark->>'run_id', v_checks);
    return jsonb_build_object('ok', false, 'profile_id', p.id, 'refused', to_jsonb(v_fail));
  end if;

  update pipeline.layer3_model_profiles
  set paused = false,
      last_validation_result = coalesce(last_validation_result,'{}'::jsonb) || jsonb_build_object(
        'activated_at', now(), 'activated_by', auth.uid(), 'activation_reason', btrim(p_reason), 'activated_binding_hash', v_hash),
      updated_at = now()
  where id = p.id;
  insert into pipeline.layer3_profile_activation_events(profile_id, action, actor_id, reason, binding_hash, benchmark_run_id, checks)
  values (p.id, 'activated', auth.uid(), btrim(p_reason), v_hash, p.quality_benchmark->>'run_id', v_checks);
  return jsonb_build_object('ok', true, 'profile_id', p.id, 'activated', true, 'binding_hash', v_hash);
end $_$;


ALTER FUNCTION "security"."layer3_profile_activate_impl"("p_profile_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_profile_pause_impl"("p_profile_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare p pipeline.layer3_model_profiles%rowtype;
begin
  if auth.uid() is null or security.current_role_rank() < 4 then
    raise exception 'pipeline operator role required to pause a Layer 3 profile' using errcode='42501';
  end if;
  if length(btrim(coalesce(p_reason,''))) < 5 then raise exception 'governance reason required'; end if;
  select * into p from pipeline.layer3_model_profiles where id = p_profile_id for update;
  if not found then raise exception 'profile not found'; end if;
  if not p.paused then
    update pipeline.layer3_model_profiles set paused = true,
      last_validation_result = coalesce(last_validation_result,'{}'::jsonb) || jsonb_build_object('paused_at', now(), 'paused_by', auth.uid(), 'pause_reason', btrim(p_reason)),
      updated_at = now() where id = p.id;
    insert into pipeline.layer3_profile_activation_events(profile_id, action, actor_id, reason, binding_hash, benchmark_run_id)
    values (p.id, 'paused', auth.uid(), btrim(p_reason), p.quality_benchmark->>'binding_hash', p.quality_benchmark->>'run_id');
  end if;
  return jsonb_build_object('ok', true, 'profile_id', p.id, 'paused', true);
end $$;


