CREATE OR REPLACE FUNCTION "security"."layer3_provider_credential_resolve_impl"("p_profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'vault', 'pipeline'
    AS $$
declare v_secret text;
begin
  select decrypted_secret into v_secret from vault.decrypted_secrets
  where name=security.layer3_provider_credential_name(p_profile_id) limit 1;
  if v_secret is not null then return v_secret; end if;
  select d.decrypted_secret into v_secret
  from pipeline.layer3_model_profiles p
  join security.layer3_aggregator_credentials a on a.aggregator=p.aggregator_provider
  join vault.decrypted_secrets d on d.name=a.vault_secret_name
  where p.id=p_profile_id limit 1;
  return v_secret;
end $$;


ALTER FUNCTION "security"."layer3_provider_credential_resolve_impl"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_provider_credential_set_impl"("p_actor" "uuid", "p_profile_id" "uuid", "p_secret" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'vault'
    AS $$
declare
  v_rank smallint := 0;
  v_profile pipeline.layer3_model_profiles%rowtype;
  v_name text;
  v_secret_id uuid;
  v_action text;
begin
  if p_actor is null then raise exception 'actor required' using errcode='42501'; end if;
  select coalesce(max(r.rank),0)::smallint into v_rank
  from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
  if v_rank < 6 then raise exception 'platform admin role required' using errcode='42501'; end if;
  if p_secret is null or length(btrim(p_secret)) < 20 then raise exception 'provider credential is required' using errcode='22023'; end if;
  if p_reason is null or length(btrim(p_reason)) < 4 then raise exception 'reason is required' using errcode='22023'; end if;
  select * into v_profile from pipeline.layer3_model_profiles where id=p_profile_id;
  if not found then raise exception 'layer3 model profile not found' using errcode='22023'; end if;
  v_name := security.layer3_provider_credential_name(p_profile_id);
  select id into v_secret_id from vault.secrets where name=v_name limit 1;
  if v_secret_id is null then
    v_secret_id := vault.create_secret(btrim(p_secret), v_name, 'CourseFinder Layer 3 provider credential for ' || v_profile.code);
    v_action := 'set';
  else
    perform vault.update_secret(v_secret_id, btrim(p_secret), v_name, 'CourseFinder Layer 3 provider credential for ' || v_profile.code);
    v_action := 'replace';
  end if;
  update pipeline.layer3_model_profiles
  set paused=true,
      last_validation_result=jsonb_build_object(
        'state','credential_configured_pending_benchmark',
        'validated',false,
        'credential_configured',true,
        'credential_configured_at',now(),
        'provider',aggregator_provider
      ),
      updated_at=now()
  where id=p_profile_id;
  insert into pipeline.layer3_provider_credential_audit(profile_id,action,actor_id,reason)
  values(p_profile_id,v_action,p_actor,btrim(p_reason));
  return jsonb_build_object('ok',true,'profile_id',p_profile_id,'credential_configured',true,'state','credential_configured_pending_benchmark');
end $$;


ALTER FUNCTION "security"."layer3_provider_credential_set_impl"("p_actor" "uuid", "p_profile_id" "uuid", "p_secret" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_provider_validation_record_impl"("p_actor" "uuid", "p_profile_id" "uuid", "p_ok" boolean, "p_provider_model" "text", "p_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare v_rank smallint := 0; v_state text;
begin
  if p_actor is null then raise exception 'actor required' using errcode='42501'; end if;
  select coalesce(max(r.rank),0)::smallint into v_rank
  from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
  if v_rank < 6 then raise exception 'platform admin role required' using errcode='42501'; end if;
  if not exists(select 1 from pipeline.layer3_model_profiles where id=p_profile_id) then raise exception 'layer3 model profile not found' using errcode='22023'; end if;
  v_state := case when p_ok then 'credential_verified_pending_benchmark' else 'credential_verification_failed' end;
  update pipeline.layer3_model_profiles
  set paused=true,
      last_validation_result=jsonb_build_object(
        'state',v_state,
        'validated',false,
        'credential_configured',true,
        'credential_verified',p_ok,
        'credential_verified_at',now(),
        'provider_model',p_provider_model,
        'message',left(coalesce(p_message,''),500)
      ),
      updated_at=now()
  where id=p_profile_id;
  insert into pipeline.layer3_provider_credential_audit(profile_id,action,actor_id,reason)
  values(p_profile_id,case when p_ok then 'verified' else 'verification_failed' end,p_actor,left(coalesce(nullif(btrim(p_message),''),'provider credential verification'),500));
  return jsonb_build_object('ok',p_ok,'profile_id',p_profile_id,'state',v_state,'provider_model',p_provider_model);
end $$;


ALTER FUNCTION "security"."layer3_provider_validation_record_impl"("p_actor" "uuid", "p_profile_id" "uuid", "p_ok" boolean, "p_provider_model" "text", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_provider_validation_record_impl"("p_actor" "uuid", "p_profile_id" "uuid", "p_ok" boolean, "p_provider_model" "text", "p_message" "text", "p_external_call_count" integer, "p_input_tokens" integer, "p_output_tokens" integer, "p_estimated_cost_usd" numeric, "p_latency_ms" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare v_rank smallint := 0; v_state text;
begin
  if p_actor is null then raise exception 'actor required' using errcode='42501'; end if;
  select coalesce(max(r.rank),0)::smallint into v_rank
  from security.user_roles ur join security.roles r on r.code=ur.role_code
  where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and r.status='active';
  if v_rank < 6 then raise exception 'platform admin role required' using errcode='42501'; end if;
  if not exists(select 1 from pipeline.layer3_model_profiles where id=p_profile_id) then raise exception 'layer3 model profile not found' using errcode='22023'; end if;
  if p_external_call_count is not null and p_external_call_count < 0 then raise exception 'invalid external call count' using errcode='22023'; end if;
  if p_input_tokens is not null and p_input_tokens < 0 then raise exception 'invalid input tokens' using errcode='22023'; end if;
  if p_output_tokens is not null and p_output_tokens < 0 then raise exception 'invalid output tokens' using errcode='22023'; end if;
  if p_estimated_cost_usd is not null and p_estimated_cost_usd < 0 then raise exception 'invalid estimated cost' using errcode='22023'; end if;
  if p_latency_ms is not null and p_latency_ms < 0 then raise exception 'invalid latency' using errcode='22023'; end if;

  v_state := case when p_ok then 'credential_verified_pending_benchmark' else 'credential_verification_failed' end;
  update pipeline.layer3_model_profiles
  set paused=true,
      last_validation_result=jsonb_build_object(
        'state',v_state,
        'validated',false,
        'credential_configured',true,
        'credential_verified',p_ok,
        'credential_verified_at',now(),
        'provider_model',p_provider_model,
        'message',left(coalesce(p_message,''),500),
        'external_call_count',p_external_call_count,
        'input_tokens',p_input_tokens,
        'output_tokens',p_output_tokens,
        'estimated_cost_usd',p_estimated_cost_usd,
        'latency_ms',p_latency_ms
      ),
      updated_at=now()
  where id=p_profile_id;

  insert into pipeline.layer3_provider_credential_audit(
    profile_id,action,actor_id,reason,provider_model,external_call_count,input_tokens,output_tokens,estimated_cost_usd,latency_ms
  ) values(
    p_profile_id,
    case when p_ok then 'verified' else 'verification_failed' end,
    p_actor,
    left(coalesce(nullif(btrim(p_message),''),'provider credential verification'),500),
    p_provider_model,p_external_call_count,p_input_tokens,p_output_tokens,p_estimated_cost_usd,p_latency_ms
  );

  return jsonb_build_object(
    'ok',p_ok,'profile_id',p_profile_id,'state',v_state,'provider_model',p_provider_model,
    'external_call_count',p_external_call_count,'input_tokens',p_input_tokens,'output_tokens',p_output_tokens,
    'estimated_cost_usd',p_estimated_cost_usd,'latency_ms',p_latency_ms
  );
end $$;


ALTER FUNCTION "security"."layer3_provider_validation_record_impl"("p_actor" "uuid", "p_profile_id" "uuid", "p_ok" boolean, "p_provider_model" "text", "p_message" "text", "p_external_call_count" integer, "p_input_tokens" integer, "p_output_tokens" integer, "p_estimated_cost_usd" numeric, "p_latency_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_queue_status_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_rank int := security.scholarship_ai_role_rank(); v_result jsonb;
begin
  if v_rank < 3 then raise exception 'curator role required' using errcode='42501'; end if;
  with counts as (
    select task_class, status, count(*) as n
    from pipeline.layer3_work_items
    group by task_class, status
  ), by_task as (
    select
      task_class,
      jsonb_object_agg(status, n) as status_counts,
      sum(n) as total
    from counts
    group by task_class
  ), oldest_pending as (
    select task_class, min(available_at) as oldest_available_at
    from pipeline.layer3_work_items
    where status = 'pending'
    group by task_class
  ), last_completed as (
    select task_class, max(completed_at) as last_completed_at
    from pipeline.layer3_work_items
    where completed_at is not null
    group by task_class
  )
  select jsonb_build_object(
    'by_task_class', coalesce((
      select jsonb_agg(jsonb_build_object(
        'task_class', bt.task_class,
        'status_counts', bt.status_counts,
        'total', bt.total,
        'oldest_pending_seconds', case when op.oldest_available_at is null then null
          else extract(epoch from (now() - op.oldest_available_at))::int end,
        'last_completed_at', lc.last_completed_at
      ) order by bt.task_class)
      from by_task bt
      left join oldest_pending op on op.task_class = bt.task_class
      left join last_completed lc on lc.task_class = bt.task_class
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end $$;


ALTER FUNCTION "security"."layer3_queue_status_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_recent_interpretations_impl"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
begin
 if auth.uid() is null or security.current_role_rank()<3 then
   raise exception 'curator role required' using errcode='42501';
 end if;
 return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (
   select i.id,i.evidence_id,i.entity_type,i.entity_id,i.task_class,i.eligibility_reason,
          i.selected_evidence_reason,i.status,i.candidate_value,i.confidence,i.rationale,
          i.aggregator_response_model,i.input_tokens,i.output_tokens,i.estimated_cost_usd,
          i.external_call_count,i.retry_count,i.call_latency_ms,i.fallback_profile_id_used,
          i.execution_trace,i.interpretation_expires_at,i.change_control_ref,i.uat_ref,i.created_at,
          case when pend.v then null else p.code end as profile_code,p.aggregator_provider,
          case when pend.v then null else p.model_identifier end as model_identifier,p.prompt_profile_version,
          i.cascade_tier_no,pend.v as model_pending,
          r.id as review_item_id,r.status as review_state,r.escalation_reason
   from pipeline.layer3_interpretations i
   join pipeline.layer3_model_profiles p on p.id=i.profile_id
   -- Decision 221: a cascade claim not yet answered by any step carries a placeholder profile, not the model used
   cross join lateral (select coalesce((select b.route_mode='ladder' from pipeline.layer3_route_budget b where b.task_class=i.task_class),false)
                         and i.cascade_tier_no is null and i.aggregator_response_model is null as v) pend
   left join lateral (
     select rr.id,rr.status,rr.escalation_reason
     from pipeline.layer4_review_items rr
     where rr.layer3_interpretation_id=i.id
     order by rr.created_at desc limit 1
   ) r on true
   order by i.created_at desc limit least(greatest(p_limit,1),250)
 ) x),'[]'::jsonb);
end $$;


ALTER FUNCTION "security"."layer3_recent_interpretations_impl"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_renumber_tiers"("p_task" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin
  update pipeline.layer3_route_tiers t set tier_no=-t.tier_no where t.task_class=p_task;
  update pipeline.layer3_route_tiers t set tier_no=x.rn, updated_at=now()
    from (select id, row_number() over (order by -tier_no) rn from pipeline.layer3_route_tiers where task_class=p_task) x where x.id=t.id;
  update pipeline.layer3_route_tiers t set is_final = (t.active and t.tier_no=(select max(tier_no) from pipeline.layer3_route_tiers where task_class=p_task and active)) where t.task_class=p_task;
end $$;


ALTER FUNCTION "security"."layer3_renumber_tiers"("p_task" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_source_pattern_queue_impl"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'auth'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<3 then
    raise exception 'curator role required' using errcode='42501';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.created_at)
    from (
      select rr.id request_id,rr.status,rr.country_code,rr.entity_type,rr.entity_id,
             p.display_name provider_name,rr.source_id,rr.source_profile_id,
             rr.evidence_id,e.evidence_type,e.source_url,e.mime_type,e.content_hash,e.captured_at,
             rr.layer3_profile_id,mp.code layer3_profile_code,mp.model_identifier,
             rr.revalidation_ref,rr.reason,rr.trigger_type,rr.schedule_error,
             rr.created_at,rr.dispatched_at
      from pipeline.refresh_requests rr
      join catalogue.providers p on p.id=rr.entity_id and rr.entity_type='provider'
      join pipeline.evidence_artifacts e on e.id=rr.evidence_id
      join pipeline.layer3_model_profiles mp on mp.id=rr.layer3_profile_id
      where rr.requested_layer=3
        and rr.revalidation_ref like 'A23-SOURCE-PATTERN:%'
        and rr.status in('queued','failed','blocked')
      order by rr.created_at
      limit least(greatest(coalesce(p_limit,100),1),250)
    ) x
  ),'[]'::jsonb);
end
$$;


ALTER FUNCTION "security"."layer3_source_pattern_queue_impl"("p_limit" integer) OWNER TO "postgres";


