CREATE OR REPLACE FUNCTION "security"."layer4_batch_decide_v1_impl"("p_item_ids" "uuid"[], "p_action" "text", "p_reason" "text", "p_confirmation" "text", "p_batch_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_ids uuid[]; v_n int; v_kinds int; v_not_pending int; v_field text; v_entity text; v_res jsonb; v_results jsonb:='[]'::jsonb; v_id uuid; v_op uuid;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank()<4 then raise exception 'Pipeline Operator role is required for batch decisions' using errcode='42501'; end if;
  if p_action not in ('approve','reject','request_more_evidence','return_layer2','return_layer3') then raise exception 'this action cannot be applied as a batch'; end if;
  if length(trim(coalesce(p_reason,'')))<8 then raise exception 'a batch reason of at least 8 characters is required'; end if;
  select array_agg(distinct x) into v_ids from unnest(p_item_ids) x where x is not null;
  v_n := coalesce(cardinality(v_ids),0);
  if v_n<2 then raise exception 'a batch needs at least 2 items'; end if;
  if v_n>100 then raise exception 'a batch can hold at most 100 items'; end if;
  if trim(coalesce(p_confirmation,'')) <> upper(p_action)||' '||v_n then
    raise exception 'confirmation must exactly match "%"', upper(p_action)||' '||v_n;
  end if;
  select count(*) filter (where status<>'pending'), count(distinct (entity_type,field_code)), min(field_code), min(entity_type)
    into v_not_pending, v_kinds, v_field, v_entity
  from pipeline.layer4_review_items where id = any(v_ids);
  if (select count(*) from pipeline.layer4_review_items where id=any(v_ids)) <> v_n then raise exception 'some items were not found'; end if;
  if v_not_pending>0 then raise exception '% item(s) in this batch have already been decided; refresh and preview again', v_not_pending; end if;
  if v_kinds<>1 then raise exception 'a batch must contain one kind of item'; end if;
  if exists(select 1 from pipeline.layer4_review_items where id=any(v_ids) and assigned_to is not null and assigned_to<>v_actor and claimed_at > now()-interval '30 minutes') then
    raise exception '% item(s) in this batch are being reviewed by someone else; untick them or try later', (select count(*) from pipeline.layer4_review_items where id=any(v_ids) and assigned_to is not null and assigned_to<>v_actor and claimed_at > now()-interval '30 minutes');
  end if;
  if p_action='approve' and v_entity<>'course' then raise exception 'only course facts can be approved in a batch'; end if;

  foreach v_id in array v_ids loop
    v_res := security.layer4_review_decide_impl(v_id, p_action, trim(p_reason), null);
    v_results := v_results || jsonb_build_array(jsonb_build_object('review_item_id',v_id,'decision_id',v_res->>'decision_id','status',v_res->>'status'));
  end loop;

  insert into pipeline.layer4_mass_operations(target_kind,action,actor_id,group_key,reason,before_count,affected_count,result,change_control_ref)
  values ('review_batch',p_action,v_actor,jsonb_build_object('batch_label',p_batch_label,'entity_type',v_entity,'field_code',v_field,'item_ids',to_jsonb(v_ids)),
          trim(p_reason),v_n,jsonb_array_length(v_results),jsonb_build_object('decisions',v_results),'CF-CHG-20260915-247')
  returning id into v_op;
  return jsonb_build_object('ok',true,'mass_operation_id',v_op,'decided',jsonb_array_length(v_results),'action',p_action);
end $$;


ALTER FUNCTION "security"."layer4_batch_decide_v1_impl"("p_item_ids" "uuid"[], "p_action" "text", "p_reason" "text", "p_confirmation" "text", "p_batch_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_block_state_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank int;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
  if not security.layer4_entity_exists(p_entity_type,p_entity_id) then
    raise exception 'entity not found' using errcode='22023';
  end if;
  if p_block_scope is not null and p_block_scope not in ('operational','publication','search','data_quality_quarantine') then
    raise exception 'invalid block scope' using errcode='22023';
  end if;

  return coalesce((
    with latest as (
      select distinct on(block_scope)
        id,block_scope,event_type,reason_code,comment,actor_id,actor_email,
        expires_at,review_at,created_at
      from pipeline.layer4_block_decisions
      where entity_type=p_entity_type and entity_id=p_entity_id
        and (p_block_scope is null or block_scope=p_block_scope)
      order by block_scope,created_at desc,id desc
    )
    select jsonb_build_object(
      'entity_type',p_entity_type,'entity_id',p_entity_id,
      'states',coalesce(jsonb_agg(jsonb_build_object(
        'scope',block_scope,
        'blocked',event_type='block' and (expires_at is null or expires_at>now()),
        'event_type',event_type,'reason_code',reason_code,'comment',comment,
        'actor_id',actor_id,'actor_email',actor_email,
        'expires_at',expires_at,'review_at',review_at,'created_at',created_at
      ) order by block_scope),'[]'::jsonb)
    ) from latest
  ),jsonb_build_object('entity_type',p_entity_type,'entity_id',p_entity_id,'states','[]'::jsonb));
end $$;


ALTER FUNCTION "security"."layer4_block_state_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_claim_v1_impl"("p_review_item_id" "uuid", "p_release" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_item pipeline.layer4_review_items%rowtype; v_active boolean;
begin
  if v_actor is null or security.current_role_rank()<3 then raise exception 'curator role required' using errcode='42501'; end if;
  select * into v_item from pipeline.layer4_review_items where id=p_review_item_id for update;
  if not found then raise exception 'review item not found'; end if;
  v_active := v_item.assigned_to is not null and v_item.claimed_at is not null and v_item.claimed_at > now()-interval '30 minutes';
  if p_release then
    if v_item.assigned_to = v_actor then update pipeline.layer4_review_items set assigned_to=null, claimed_at=null where id=v_item.id; end if;
    return jsonb_build_object('ok',true,'released',v_item.assigned_to = v_actor);
  end if;
  if v_item.status<>'pending' then return jsonb_build_object('ok',false,'reason','already decided'); end if;
  if v_active and v_item.assigned_to<>v_actor then
    return jsonb_build_object('ok',false,'reason','claimed','claimed_by',(select email from auth.users where id=v_item.assigned_to),
      'minutes_left',ceil(extract(epoch from (v_item.claimed_at+interval '30 minutes'-now()))/60));
  end if;
  update pipeline.layer4_review_items set assigned_to=v_actor, claimed_at=now() where id=v_item.id;
  return jsonb_build_object('ok',true,'claimed',true);
end $$;


ALTER FUNCTION "security"."layer4_claim_v1_impl"("p_review_item_id" "uuid", "p_release" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_clean_quote"("q" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  -- "Fees[A$60952](https://...)Duration" -> "Fees A$60952 Duration"
  select nullif(btrim(regexp_replace(regexp_replace(coalesce(q,''), '\[([^\]]*)\]\([^)]*\)', ' \1 ', 'g'), '\s+', ' ', 'g')),'')
$_$;


ALTER FUNCTION "security"."layer4_clean_quote"("q" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_course_link_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'pipeline', 'search'
    AS $_$
declare v_item pipeline.layer4_review_items%rowtype; v_url text; v_host text; v_link uuid;
begin
  select * into v_item from pipeline.layer4_review_items where id=p_item_id;
  if v_item.entity_type<>'course' then raise exception 'course links apply to courses only'; end if;
  v_url := btrim(coalesce(case jsonb_typeof(p_value) when 'string' then p_value#>>'{}' when 'object' then p_value->>'url' end,
                          case jsonb_typeof(v_item.proposed_value) when 'string' then v_item.proposed_value#>>'{}' when 'object' then v_item.proposed_value->>'url' end,''));
  if v_url='' then raise exception 'enter the official course page link, then approve'; end if;
  if v_url !~* '^https://[a-z0-9.-]+\.[a-z]{2,}(/[^\s]*)?$' then raise exception 'the link must be a full https:// web address'; end if;
  v_host := lower(substring(v_url from '^https://([^/]+)'));
  if security.reference_url_has_use(v_url, 'not_course_page') then
    raise exception 'use the provider''s own course page, not a search, social or course-listing site (%)', v_host;
  end if;
  insert into catalogue.course_links(course_id,link_type,url,audience,label,is_primary,status,source_id,evidence_id,confidence,last_verified_at,updated_at)
  values (v_item.entity_id,'official_course',v_url,'international','Official provider course page (confirmed by reviewer)',false,'active',(select id from pipeline.sources where source_type='layer4_human_review' limit 1),v_item.evidence_id,1,now(),now())
  on conflict(course_id,link_type,url) do update set label=excluded.label,status='active',source_id=excluded.source_id,confidence=1,last_verified_at=now(),updated_at=now()
  returning id into v_link;
  perform search.refresh_course_enrichment_scoped_v1(array[v_item.entity_id], true);
  return jsonb_build_object('course_link_id',v_link,'url',v_url,'search_refreshed',true);
end $_$;


ALTER FUNCTION "security"."layer4_course_link_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_course_scalar_resolve_impl"("p_actor" "uuid", "p_course_id" "uuid", "p_field_code" "text", "p_value" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'pipeline', 'auth'
    AS $$
declare v_overlay jsonb; v_prior jsonb; v_prev_id uuid; v_resolution_id uuid;
begin
  if p_field_code not in ('course_description','official_course_url','delivery_mode','duration') then
    raise exception 'field is not enabled for scalar Layer 4 editing' using errcode='22023';
  end if;
  v_prior:=security.layer4_underlying_value('course',p_course_id,p_field_code);
  v_overlay:=security.layer4_override_apply_impl(
    p_actor,'course',p_course_id,p_field_code,p_value,'human_resolution',p_reason,'{}'::uuid[],'{}'::jsonb
  );
  select id into v_prev_id from pipeline.layer4_course_field_resolutions
   where course_id=p_course_id and field_code=p_field_code and status='applied'
   order by created_at desc limit 1;
  if v_prev_id is not null then
    update pipeline.layer4_course_field_resolutions set status='superseded' where id=v_prev_id;
  end if;
  insert into pipeline.layer4_course_field_resolutions(
    course_id,field_code,prior_value,resolved_value,resolution_reason,actor_id,supersedes_id
  ) values (
    p_course_id,p_field_code,v_prior,p_value,trim(p_reason),p_actor,v_prev_id
  ) returning id into v_resolution_id;
  return v_overlay||jsonb_build_object('resolution_id',v_resolution_id,'legacy_resolution_bridge',true,'canonical_changed',false,'search_changed',false);
end $$;


ALTER FUNCTION "security"."layer4_course_scalar_resolve_impl"("p_actor" "uuid", "p_course_id" "uuid", "p_field_code" "text", "p_value" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_effective_entity_read"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rows jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(security.layer4_effective_field_read(r.entity_type,p_entity_id,r.field_code) order by r.display_label),'[]'::jsonb)
  into v_rows
  from pipeline.layer4_field_registry r
  where r.entity_type=p_entity_type and r.enabled;
  return jsonb_build_object(
    'entity_type',p_entity_type,'entity_id',p_entity_id,
    'fields',coalesce(v_rows,'[]'::jsonb),
    'active_override_count',(
      select count(*) from (
        select distinct on (field_code) field_code,event_type
        from pipeline.layer4_override_decisions
        where entity_type=p_entity_type and entity_id=p_entity_id
        order by field_code,created_at desc,id desc
      ) q where event_type='apply'
    )
  );
end $$;


ALTER FUNCTION "security"."layer4_effective_entity_read"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_effective_field_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank int; v_reg pipeline.layer4_field_registry%rowtype; v_last pipeline.layer4_override_decisions%rowtype; v_underlying jsonb; v_effective jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  select * into v_reg from pipeline.layer4_field_registry where entity_type=p_entity_type and field_code=p_field_code and enabled;
  if not found then return null; end if;
  v_underlying:=security.layer4_underlying_value(p_entity_type,p_entity_id,p_field_code);
  select * into v_last from pipeline.layer4_override_decisions
   where entity_type=p_entity_type and entity_id=p_entity_id and field_code=p_field_code
   order by created_at desc,id desc limit 1;
  v_effective:=case when found and v_last.event_type='apply' then v_last.override_value else v_underlying end;
  return jsonb_build_object(
    'field_code',p_field_code,'display_label',v_reg.display_label,'value_kind',v_reg.value_kind,
    'editability_class',v_reg.editability_class,'min_role_rank',v_reg.min_role_rank,
    'can_edit',(v_reg.editability_class<>'immutable' and v_rank>=v_reg.min_role_rank),
    'underlying_value',v_underlying,'effective_value',v_effective,
    'effective_source',case when found and v_last.event_type='apply' then 'L4' else 'UNDERLYING' end,
    'override_id',case when found then v_last.id else null end,
    'override_event',case when found then v_last.event_type else null end,
    'actor_id',case when found then v_last.actor_id else null end,
    'actor_email',case when found then v_last.actor_email else null end,
    'edited_at',case when found then v_last.created_at else null end,
    'reason_code',case when found then v_last.reason_code else null end,
    'comment',case when found then v_last.comment else null end,
    'upstream_changed',case when found and v_last.event_type='apply' then v_underlying is distinct from v_last.underlying_value else false end,
    'history_count',(select count(*) from pipeline.layer4_override_decisions d where d.entity_type=p_entity_type and d.entity_id=p_entity_id and d.field_code=p_field_code)
  );
end $$;


ALTER FUNCTION "security"."layer4_effective_field_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_entity_blocked"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select coalesce((
    select d.event_type='block' and (d.expires_at is null or d.expires_at>now())
    from pipeline.layer4_block_decisions d
    where d.entity_type=p_entity_type and d.entity_id=p_entity_id and d.block_scope=p_block_scope
    order by d.created_at desc,d.id desc
    limit 1
  ),false)
$$;


ALTER FUNCTION "security"."layer4_entity_blocked"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_entity_exists"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'scholarship', 'pipeline'
    AS $$
  select case p_entity_type
    when 'course' then exists(select 1 from catalogue.courses where id=p_entity_id)
    when 'provider' then exists(select 1 from catalogue.providers where id=p_entity_id)
    when 'campus' then exists(select 1 from catalogue.campuses where id=p_entity_id)
    when 'scholarship' then exists(select 1 from scholarship.scholarships where id=p_entity_id)
    when 'provider_contact' then exists(select 1 from pipeline.provider_contact_observations where id=p_entity_id)
    when 'provider_contact_import_row' then exists(select 1 from pipeline.provider_contact_import_rows where id=p_entity_id)
    else false
  end
$$;


ALTER FUNCTION "security"."layer4_entity_exists"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_entity_or_parent_blocked"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'scholarship', 'pipeline'
    AS $$
declare v_type text:=lower(btrim(coalesce(p_entity_type,''))); v_provider uuid;
begin
  if p_block_scope not in ('operational','publication','search','data_quality_quarantine') then
    raise exception 'invalid block scope' using errcode='22023';
  end if;
  if exists(
    select 1 from security.layer4_active_blocks b
    where b.entity_type=v_type and b.entity_id=p_entity_id and b.block_scope=p_block_scope
  ) then return true; end if;

  if v_type='course' then
    select provider_id into v_provider from catalogue.courses where id=p_entity_id;
  elsif v_type='campus' then
    select provider_id into v_provider from catalogue.campuses where id=p_entity_id;
  elsif v_type='scholarship' then
    select provider_id into v_provider from scholarship.scholarships where id=p_entity_id;
  elsif v_type='provider_contact' then
    select provider_id into v_provider from pipeline.provider_contact_observations where id=p_entity_id;
  end if;

  return v_provider is not null and exists(
    select 1 from security.layer4_active_blocks b
    where b.entity_type='provider' and b.entity_id=v_provider and b.block_scope=p_block_scope
  );
end $$;


ALTER FUNCTION "security"."layer4_entity_or_parent_blocked"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_money_text"("p" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select case when p is null or jsonb_typeof(p)<>'object' or nullif(p->>'amount','') is null then null else
    concat_ws(' · ',
      case upper(coalesce(p->>'currency_code',p->>'currency','')) when 'AUD' then 'A$' when 'NZD' then 'NZ$' else coalesce(nullif(upper(coalesce(p->>'currency_code',p->>'currency','')),'')||' ','') end
        || to_char((p->>'amount')::numeric,'FM999,999,999')
        || case lower(coalesce(p->>'basis','')) when 'annual' then ' per year' when 'indicative_annual' then ' per year (indicative)' when 'per_year_explicit' then ' per year'
             when 'annual_or_indicative_requires_validation' then ' (frequency not confirmed)' when '' then '' else ' ('||replace(p->>'basis','_',' ')||')' end,
      nullif(p->>'fee_year',''),
      nullif(lower(p->>'audience'),''))
  end
$_$;


ALTER FUNCTION "security"."layer4_money_text"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_override_apply_impl"("p_actor" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text", "p_value" "jsonb", "p_reason_code" "text", "p_comment" "text" DEFAULT NULL::"text", "p_evidence_refs" "uuid"[] DEFAULT '{}'::"uuid"[], "p_approval_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank int:=0; v_reg pipeline.layer4_field_registry%rowtype; v_underlying jsonb;
        v_prev uuid; v_id uuid; v_email text;
begin
  if p_actor is null or p_actor<>auth.uid() then raise exception 'authenticated actor required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  select * into v_reg from pipeline.layer4_field_registry where entity_type=p_entity_type and field_code=p_field_code and enabled;
  if not found then raise exception 'field is not registered for Layer 4' using errcode='22023'; end if;
  if v_reg.editability_class='immutable' then raise exception 'field is immutable source/history and cannot be edited through Layer 4' using errcode='42501'; end if;
  if v_rank<v_reg.min_role_rank then raise exception 'insufficient role for Layer 4 field' using errcode='42501'; end if;
  if not security.layer4_entity_exists(p_entity_type,p_entity_id) then raise exception 'entity not found' using errcode='22023'; end if;
  if length(trim(coalesce(p_reason_code,'')))<3 then raise exception 'reason code required' using errcode='22023'; end if;
  perform security.layer4_validate_override_value(v_reg.value_kind,p_value);
  v_underlying:=security.layer4_underlying_value(p_entity_type,p_entity_id,p_field_code);
  select id into v_prev from pipeline.layer4_override_decisions
   where entity_type=p_entity_type and entity_id=p_entity_id and field_code=p_field_code
   order by created_at desc,id desc limit 1;
  select email into v_email from auth.users where id=p_actor;
  insert into pipeline.layer4_override_decisions(
    entity_type,entity_id,field_code,event_type,underlying_value,override_value,
    reason_code,comment,evidence_refs,actor_id,actor_email,supersedes_override_id,
    approval_context
  ) values (
    p_entity_type,p_entity_id,p_field_code,'apply',v_underlying,p_value,
    trim(p_reason_code),nullif(trim(coalesce(p_comment,'')),''),coalesce(p_evidence_refs,'{}'),
    p_actor,v_email,v_prev,coalesce(p_approval_context,'{}')
  ) returning id into v_id;
  return jsonb_build_object(
    'ok',true,'override_id',v_id,'entity_type',p_entity_type,'entity_id',p_entity_id,
    'field_code',p_field_code,'underlying_value',v_underlying,'effective_value',p_value,
    'effective_source','L4','layer',4,'publication_changed',false,'canonical_changed',false
  );
end $$;


ALTER FUNCTION "security"."layer4_override_apply_impl"("p_actor" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text", "p_value" "jsonb", "p_reason_code" "text", "p_comment" "text", "p_evidence_refs" "uuid"[], "p_approval_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_provider_departure_decide_v1"("p_id" bigint, "p_decision" "text", "p_successor_provider_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue'
    AS $$
declare d pipeline.layer1_provider_departures; p catalogue.providers; s catalogue.providers; v_before jsonb; v_after jsonb; v_changed boolean:=false;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank()<6 then raise exception 'Platform Admin role required' using errcode='42501'; end if;
  if p_decision not in ('closed','merged','reviewed') then raise exception 'decision must be closed, merged or reviewed' using errcode='22023'; end if;
  if length(btrim(coalesce(p_reason,'')))<8 then raise exception 'a reason of at least 8 characters is required' using errcode='22023'; end if;
  select * into d from pipeline.layer1_provider_departures where id=p_id for update;
  if not found then raise exception 'departure not found' using errcode='22023'; end if;
  if d.status<>'needs_review' then raise exception 'this departure was already decided (%)', d.status using errcode='55000'; end if;
  select * into p from catalogue.providers where id=d.provider_id for update;
  if exists (select 1 from catalogue.courses c where c.provider_id=p.id and c.lifecycle_status='active') and p_decision<>'reviewed' then
    raise exception 'the provider has active courses again; choose reviewed' using errcode='55000'; end if;
  if p_decision='merged' then
    if p_successor_provider_id is null then raise exception 'a merger needs a successor provider' using errcode='22023'; end if;
    select * into s from catalogue.providers where id=p_successor_provider_id;
    if not found or s.id=p.id then raise exception 'successor provider not valid' using errcode='22023'; end if;
    if s.country_id is distinct from p.country_id then raise exception 'successor must be in the same country' using errcode='22023'; end if;
    if s.lifecycle_status<>'active' then raise exception 'successor provider is not active' using errcode='22023'; end if;
  elsif p_successor_provider_id is not null then
    raise exception 'a successor is only recorded for a merger' using errcode='22023';
  end if;

  if p_decision in ('closed','merged') and p.lifecycle_status='active' then
    v_before:=security.consumer_api_snapshot_v1();
    update catalogue.providers set lifecycle_status='inactive', updated_at=now() where id=p.id;
    v_changed:=true;
  end if;
  if p_decision='merged' then
    insert into catalogue.provider_associations(from_provider_id,to_provider_id,association_type,valid_from,status,notes)
    values(p.id, s.id, 'merged_into', current_date, 'active', left('Recorded on provider departure review: '||btrim(p_reason),500));
  end if;
  update pipeline.layer1_provider_departures set status=p_decision, successor_provider_id=p_successor_provider_id,
         note=left(coalesce(note,'')||' | Decision: '||btrim(p_reason),1000), reviewed_by=auth.uid(), reviewed_at=now()
   where id=p_id;
  if v_changed then
    v_after:=security.consumer_api_snapshot_v1();
    insert into pipeline.consumer_api_baselines(label, snapshot) values
      (format('before provider departure decision %s (%s)', p_id, p_decision), v_before),
      (format('after provider departure decision %s (%s)', p_id, p_decision), v_after);
    insert into search.refresh_requests(requested_by) values (format('provider departure %s: %s', p_id, p_decision));
  end if;
  return jsonb_build_object('id',p_id,'decision',p_decision,'provider_id',p.id,'provider_inactive',v_changed,'successor_provider_id',p_successor_provider_id);
end $$;


ALTER FUNCTION "security"."layer4_provider_departure_decide_v1"("p_id" bigint, "p_decision" "text", "p_successor_provider_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_provider_departures_read_v1"("p_status" "text" DEFAULT 'needs_review'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref'
    AS $$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank()<4 then raise exception 'Pipeline Operator role required' using errcode='42501'; end if;
  return coalesce((select jsonb_agg(x order by x->>'created_at' desc) from (
    select jsonb_build_object(
      'id',d.id,'provider_id',d.provider_id,'provider_name',coalesce(p.display_name,p.canonical_name),'country_code',co.iso_alpha2,
      'provider_status',p.lifecycle_status,'courses_retired',d.courses_retired,'status',d.status,'note',d.note,'run_id',d.run_id,
      'created_at',d.created_at,'reviewed_at',d.reviewed_at,'successor_provider_id',d.successor_provider_id,
      'successor_name',(select coalesce(s.display_name,s.canonical_name) from catalogue.providers s where s.id=d.successor_provider_id),
      'suggested_successor',(select jsonb_build_object('provider_id',s.id,'name',coalesce(s.display_name,s.canonical_name),'courses',count(*))
          from pipeline.layer1_course_retirements r join catalogue.providers s on s.id=r.successor_provider_id
         where r.provider_id=d.provider_id and r.successor_provider_id is not null group by s.id, s.display_name, s.canonical_name order by count(*) desc limit 1),
      'registrations',(select coalesce(jsonb_agg(jsonb_build_object('scheme',pr.registration_scheme,'code',pr.registration_code,'status',pr.status)),'[]'::jsonb)
          from catalogue.provider_registrations pr where pr.provider_id=d.provider_id),
      'active_courses',(select count(*) from catalogue.courses c where c.provider_id=d.provider_id and c.lifecycle_status='active')) x
    from pipeline.layer1_provider_departures d
    join catalogue.providers p on p.id=d.provider_id
    left join ref.countries co on co.id=p.country_id
    where p_status is null or p_status='all' or d.status=p_status) z),'[]'::jsonb);
end $$;


ALTER FUNCTION "security"."layer4_provider_departures_read_v1"("p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_publication_state_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_target_scope" "text" DEFAULT 'governed_publication'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_last pipeline.layer4_publication_decisions%rowtype; v_rank int;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  select * into v_last from pipeline.layer4_publication_decisions
  where entity_type=p_entity_type and entity_id=p_entity_id and target_scope=p_target_scope
  order by created_at desc,id desc limit 1;
  return jsonb_build_object(
    'target_scope',p_target_scope,
    'can_decide',(v_rank>=5),
    'effective_decision',case when found and v_last.event_type<>'revert' then v_last.event_type else 'no_override' end,
    'decision_id',case when found then v_last.id else null end,
    'actor_id',case when found then v_last.actor_id else null end,
    'actor_email',case when found then v_last.actor_email else null end,
    'decided_at',case when found then v_last.created_at else null end,
    'reason_code',case when found then v_last.reason_code else null end,
    'comment',case when found then v_last.comment else null end,
    'readiness_snapshot',case when found then v_last.readiness_snapshot else '{}'::jsonb end,
    'overridden_checks',case when found then v_last.overridden_checks else '[]'::jsonb end
  );
end $$;


ALTER FUNCTION "security"."layer4_publication_state_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_target_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_return_layer3_requeue_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare v_item pipeline.layer4_review_items%rowtype;
begin
  if new.action<>'return_layer3' then return new; end if;
  select * into v_item from pipeline.layer4_review_items where id=new.review_item_id;
  if v_item.field_code<>'provider_current_tuition_validation' or v_item.layer3_interpretation_id is null then return new; end if;
  update pipeline.layer3_work_items w
  set status='pending', available_at=now(), completed_at=null, reserved_at=null, reserved_by=null,
      last_error='Returned by a Layer 4 reviewer for another AI check',
      corrective_retry_reason=left('Layer 4 send-back: '||coalesce(new.reason,''),2000),
      corrective_retry_count=w.corrective_retry_count + case when w.attempt_count>=5 then 1 else 0 end,
      corrective_retry_authorized_at=case when w.attempt_count>=5 then now() else w.corrective_retry_authorized_at end,
      updated_at=now()
  where w.interpretation_id=v_item.layer3_interpretation_id and w.status in ('layer4_required','parked','no_candidate','rejected');
  return new;
end $$;


ALTER FUNCTION "security"."layer4_return_layer3_requeue_trg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_review_batches_v1_impl"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'auth'
    AS $$
declare v_desk jsonb;
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'curator role required' using errcode='42501'; end if;
  v_desk := security.layer4_review_desk_v1_impl('pending',500);
  return jsonb_build_object(
    'can_apply', security.current_role_rank()>=4,
    'groups', coalesce((select jsonb_agg(g order by (g->>'count')::int desc) from (
      select jsonb_build_object(
        'key', i->>'field_code'||'|'||(i->'suggestion'->>'action')||'|'||md5(i->'suggestion'->>'text'),
        'field_code', i->>'field_code', 'task', i->>'task',
        'action', i->'suggestion'->>'action', 'text', i->'suggestion'->>'text',
        'count', count(*), 'oldest_days', max((i->>'age_days')::int),
        'can_approve', bool_and(coalesce((i->>'can_approve')::boolean,false)),
        'item_ids', jsonb_agg(i->>'id' order by (i->>'age_days')::int desc),
        'samples', (jsonb_agg(jsonb_build_object('id',i->>'id','title',coalesce(i->'entity'->>'title',i->>'task'),'code',i->'entity'->>'code','provider',i->'entity'->>'provider','quote',i->>'page_quote','ai_suggested',i->>'ai_suggested') order by (i->>'age_days')::int desc))
      ) g
      from jsonb_array_elements(v_desk->'items') i
      group by i->>'field_code', i->>'task', i->'suggestion'->>'action', i->'suggestion'->>'text'
      having count(*)>=2
    ) x),'[]'::jsonb));
end $$;


ALTER FUNCTION "security"."layer4_review_batches_v1_impl"() OWNER TO "postgres";


