    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$ select security.layer4_review_context_impl(p_review_item_id) $$;


ALTER FUNCTION "security"."layer4_review_context_browser_bridge"("p_review_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_review_context_impl"("p_review_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v jsonb;
begin
  if auth.uid() is null or security.current_role_rank()<3 then
    raise exception 'curator role required' using errcode='42501';
  end if;
  select jsonb_build_object(
    'review',to_jsonb(r),
    'evidence',jsonb_build_object(
      'id',e.id,'source_id',e.source_id,'source_url',e.source_url,'storage_path',e.storage_path,
      'content_hash',e.content_hash,'mime_type',e.mime_type,'captured_at',e.captured_at,
      'valid_from',e.valid_from,'valid_to',e.valid_to,'review_state',e.review_state,
      'retention_class',e.retention_class,'metadata',e.metadata
    ),
    'layer3',case when i.id is null then null else jsonb_build_object(
      'id',i.id,'profile_id',i.profile_id,'profile_code',p.code,'aggregator_provider',p.aggregator_provider,
      'configured_model',p.model_identifier,'response_model',i.aggregator_response_model,
      'prompt_profile_version',i.prompt_profile_version,'eligibility_reason',i.eligibility_reason,
      'revalidation_ref',i.revalidation_ref,'status',i.status,'candidate_value',i.candidate_value,
      'confidence',i.confidence,'rationale',i.rationale,'evidence_quotes',i.evidence_quotes,
      'validator_result',i.validator_result,'input_tokens',i.input_tokens,'output_tokens',i.output_tokens,
      'estimated_cost_usd',i.estimated_cost_usd,'interpretation_expires_at',i.interpretation_expires_at
    ) end,
    'history',coalesce((
      select jsonb_agg(to_jsonb(d) order by d.created_at)
      from pipeline.layer4_decisions d where d.review_item_id=r.id
    ),'[]'::jsonb)
  ) into v
  from pipeline.layer4_review_items r
  left join pipeline.evidence_artifacts e on e.id=r.evidence_id
  left join pipeline.layer3_interpretations i on i.id=r.layer3_interpretation_id
  left join pipeline.layer3_model_profiles p on p.id=i.profile_id
  where r.id=p_review_item_id;
  if v is null then raise exception 'review item not found'; end if;
  return v;
end $$;


ALTER FUNCTION "security"."layer4_review_context_impl"("p_review_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_review_decide_impl"("p_review_item_id" "uuid", "p_action" "text", "p_reason" "text", "p_final_value" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare
  v_actor uuid:=auth.uid(); v_rank int; v_item pipeline.layer4_review_items%rowtype;
  v_final jsonb; v_state text; v_scalar jsonb; v_scalar_id uuid; v_decision uuid;
  v_refresh_id uuid; v_search_signal_id uuid; v_evidence pipeline.evidence_artifacts%rowtype;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
  if p_action not in ('approve','edit_and_approve','reject','request_more_evidence','return_layer2','return_layer3') then
    raise exception 'invalid action';
  end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'decision reason required'; end if;

  select * into v_item from pipeline.layer4_review_items where id=p_review_item_id for update;
  if not found then raise exception 'review item not found'; end if;
  if v_item.status<>'pending' then raise exception 'review item already decided'; end if;
  select * into v_evidence from pipeline.evidence_artifacts where id=v_item.evidence_id;

  v_final:=case when p_action='approve' then v_item.proposed_value when p_action='edit_and_approve' then p_final_value else null end;
  if p_action='edit_and_approve' and p_final_value is null then raise exception 'edited final value required'; end if;

  if p_action in ('approve','edit_and_approve') then
    if v_item.field_code='provider_current_tuition_validation' then
      -- Layer 4 tuition decisions record the fee (same convention as Layer 3 admission).
      v_scalar:=security.layer4_tuition_apply_impl(v_actor,v_item.id,v_final,trim(p_reason));
      v_scalar_id:=null;
    elsif v_item.field_code='official_course_url' then
      v_scalar:=security.layer4_course_link_apply_impl(v_actor,v_item.id,v_final,trim(p_reason));
      v_scalar_id:=null;
    elsif v_item.entity_type='scholarship' and v_item.field_code='scope_resolution' then
      v_scalar:=security.layer4_scholarship_scope_close_impl(v_item.id);
      v_scalar_id:=null;
    else
    if v_item.entity_type<>'course' then raise exception 'terminal apply currently supports course scalar facts only'; end if;
    v_scalar:=security.layer4_course_scalar_resolve_impl(v_actor,v_item.entity_id,v_item.field_code,v_final,trim(p_reason));
    v_scalar_id:=nullif(v_scalar->>'resolution_id','')::uuid;
    end if;
    v_state:=case when p_action='approve' then 'approved' else 'edited_approved' end;
  elsif p_action='reject' then v_state:='rejected';
  elsif p_action='request_more_evidence' then v_state:='more_evidence';
  elsif p_action='return_layer2' then v_state:='returned_layer2';
  else v_state:='returned_layer3'; end if;

  update pipeline.layer4_review_items set status=v_state,decided_at=now() where id=v_item.id;
  insert into pipeline.layer4_decisions(
    review_item_id,action,actor_id,reason,before_value,proposed_value,final_value,evidence_id,
    layer2_state,layer3_state,scalar_resolution_id,change_control_ref
  ) values (
    v_item.id,p_action,v_actor,trim(p_reason),v_item.before_value,v_item.proposed_value,v_final,
    v_item.evidence_id,v_item.layer2_state,v_item.layer3_state,v_scalar_id,v_item.change_control_ref
  ) returning id into v_decision;

  if p_action in ('request_more_evidence','return_layer2') then
    insert into pipeline.refresh_requests(
      requested_layer,source_id,entity_type,entity_id,evidence_id,reason,trigger_type,requested_by,change_control_ref
    ) values (
      2,v_evidence.source_id,v_item.entity_type,v_item.entity_id,v_item.evidence_id,trim(p_reason),
      'layer4_return',v_actor,v_item.change_control_ref
    ) returning id into v_refresh_id;
  elsif p_action='return_layer3' then
    insert into pipeline.refresh_requests(
      requested_layer,source_id,entity_type,entity_id,evidence_id,layer3_profile_id,revalidation_ref,
      reason,trigger_type,requested_by,change_control_ref
    ) values (
      3,v_evidence.source_id,v_item.entity_type,v_item.entity_id,v_item.evidence_id,
      nullif(v_item.layer3_state->>'profile_id','')::uuid,
      'L4:'||v_decision::text,trim(p_reason),'layer4_return',v_actor,v_item.change_control_ref
    ) returning id into v_refresh_id;
  end if;

  if p_action in ('approve','edit_and_approve') then
    insert into pipeline.search_refresh_signals(
      entity_type,entity_id,review_decision_id,reason,change_control_ref
    ) values (
      v_item.entity_type,v_item.entity_id,v_decision,
      'Accepted Layer 4 canonical change: '||trim(p_reason),v_item.change_control_ref
    ) returning id into v_search_signal_id;
  end if;

  return jsonb_build_object(
    'ok',true,'decision_id',v_decision,'review_item_id',v_item.id,'action',p_action,'status',v_state,
    'final_value',v_final,'scalar_resolution_id',v_scalar_id,'refresh_request_id',v_refresh_id,
    'publication_changed',false,'search_refresh_required',v_search_signal_id is not null,
    'search_refresh_signal_id',v_search_signal_id
  );
end $$;


ALTER FUNCTION "security"."layer4_review_decide_impl"("p_review_item_id" "uuid", "p_action" "text", "p_reason" "text", "p_final_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_review_desk_v1_impl"("p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 250) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'auth'
    AS $$
declare v_items jsonb; v_summary jsonb;
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'curator role required' using errcode='42501'; end if;

  with base as (
    select r.*, c.id course_id, coalesce(nullif(c.display_title,''),c.canonical_title,sc.name) course_title, c.course_code, c.course_url,
           coalesce(nullif(p.display_name,''),p.canonical_name,nullif(p2.display_name,''),p2.canonical_name,nullif(p3.display_name,''),p3.canonical_name) provider_name, coalesce(p.id,p2.id,p3.id) provider_id,
           e.source_url page_url, e.captured_at page_captured_at,
           i.evidence_quotes, i.confidence ai_confidence, i.validator_result l3_validator,
           lower(coalesce((select string_agg(security.layer4_clean_quote(q),' ') from jsonb_array_elements_text(coalesce(i.evidence_quotes,'[]'::jsonb)) q),'')) quotes_text,
           (select security.layer4_money_text(jsonb_build_object('amount',f.amount,'currency_code',f.currency_code,'basis',f.basis,'fee_year',f.fee_year,'audience',f.audience))
              from catalogue.course_fees f where r.entity_type='course' and f.course_id=r.entity_id and f.fee_type='provider_current_tuition' and f.status='active'
              order by f.fee_year desc nulls last limit 1) recorded_fee
    from pipeline.layer4_review_items r
    left join catalogue.courses c on r.entity_type='course' and c.id=r.entity_id
    left join catalogue.providers p on p.id=c.provider_id
    left join catalogue.providers p2 on r.entity_type='provider' and p2.id=r.entity_id
    left join scholarship.scholarships sc on r.entity_type='scholarship' and sc.id=r.entity_id
    left join catalogue.providers p3 on p3.id=sc.provider_id
    left join pipeline.evidence_artifacts e on e.id=r.evidence_id
    left join pipeline.layer3_interpretations i on i.id=r.layer3_interpretation_id
    where (p_status is null or p_status='' or r.status=p_status)
    order by r.created_at asc
    limit least(greatest(coalesce(p_limit,250),1),500)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', b.id, 'can_approve', coalesce(case
      when b.field_code='provider_current_tuition_validation' then jsonb_typeof(b.proposed_value)='object' and lower(coalesce(b.proposed_value->>'basis','')) in ('annual','indicative_annual','per_year_explicit')
      when b.field_code='official_course_url' then jsonb_typeof(b.proposed_value)='string' or (jsonb_typeof(b.proposed_value)='object' and b.proposed_value ? 'url')
      when b.entity_type='scholarship' and b.field_code='scope_resolution' then not exists(select 1 from scholarship.course_mapping_candidates m where m.scholarship_id=b.entity_id and m.status='needs_review')
      else b.entity_type='course' end,false),
    'scope_pending', case when b.entity_type='scholarship' then (select count(*) from scholarship.course_mapping_candidates m where m.scholarship_id=b.entity_id and m.status='needs_review') end,
    'provider_domain', case when b.field_code='official_course_url' then (select lower(substring(l.url from '^https?://([^/]+)')) from catalogue.course_links l join catalogue.courses c2 on c2.id=l.course_id where c2.provider_id=b.provider_id and l.link_type='official_course' and l.status='active' group by 1 order by count(*) desc limit 1) end, 'status', b.status, 'field_code', b.field_code,
    'task', case b.field_code when 'provider_current_tuition_validation' then 'Tuition fee' when 'official_course_url' then 'Official course link'
              when 'scope_resolution' then 'Scholarship scope' else initcap(replace(b.field_code,'_',' ')) end,
    'created_at', b.created_at, 'decided_at', b.decided_at, 'assigned_to', b.assigned_to,
    'claimed_at', b.claimed_at,
    'claim_active', (b.assigned_to is not null and b.claimed_at is not null and b.claimed_at > now()-interval '30 minutes'),
    'claimed_by_me', (b.assigned_to = auth.uid() and b.claimed_at > now()-interval '30 minutes'),
    'claimed_by', (select u.email from auth.users u where u.id=b.assigned_to and b.claimed_at > now()-interval '30 minutes'),
    'age_days', floor(extract(epoch from now()-b.created_at)/86400)::int,
    'reason', case
      when b.escalation_reason is null then null
      when b.entity_type='scholarship' and b.field_code='scope_resolution' then 'Decide which courses this scholarship applies to before it can be published. Use batch work for scholarship scope.'
      when b.escalation_reason ~* '(firecrawl|zenrows|gatekeeper|governed layer|discovery exhausted|deterministic|fall-?out)' then
        case b.field_code
          when 'official_course_url' then 'We couldn''t find this course''s official page automatically. Find it on the provider''s website and add the link.'
          when 'scope_resolution' then 'We couldn''t tell automatically which provider or course this belongs to. Please check and confirm.'
          when 'provider_current_tuition_validation' then 'We couldn''t confirm this fee automatically. Please check the page and confirm the fee.'
          else 'This couldn''t be resolved automatically. Please check and decide.' end
      else b.escalation_reason end,
    'search_url', 'https://www.google.com/search?q='||security.layer4_url_query(concat_ws(' ',b.course_title,b.course_code,b.provider_name,case b.field_code when 'provider_current_tuition_validation' then 'international fees' else 'course' end)),
    'entity', jsonb_build_object('type',b.entity_type,'title',b.course_title,'code',b.course_code,'provider',b.provider_name,'provider_id',b.provider_id),
    'recorded', case when b.field_code='provider_current_tuition_validation' then coalesce(b.recorded_fee,'No fee recorded') else null end,
    'ai_suggested', coalesce(security.layer4_money_text(b.proposed_value), case when b.proposed_value is not null and jsonb_typeof(b.proposed_value)='string' then b.proposed_value#>>'{}' end),
    'page_quote', (select security.layer4_clean_quote(q) from jsonb_array_elements_text(coalesce(b.evidence_quotes,'[]'::jsonb)) q limit 1),
    'links', jsonb_build_object('page_url',b.page_url,'page_captured_at',b.page_captured_at,'course_url',b.course_url,'evidence_id',b.evidence_id),
    'suggestion', case
      when b.field_code='official_course_url' and b.course_title ~* 'exit award' then jsonb_build_object('action','reject','text','Exit award: students cannot enrol in it directly, so there is no course page to link.')
      when b.field_code='official_course_url' and b.course_title ~* '^(study abroad|research exchange|exchange)\M' then jsonb_build_object('action','reject','text','Study abroad or exchange programme: not a standalone course, so there is no course page to link.')
      when b.field_code='official_course_url' and b.course_title ~* '^(doctor|master) of philosophy' then jsonb_build_object('action','check','text','Research degree: use the provider''s page for this research degree, then approve.')
      when b.field_code<>'provider_current_tuition_validation' then jsonb_build_object('action','check','text','Check the page, then decide.')
      when b.field_code='provider_current_tuition_validation' and exists(select 1 from pipeline.layer3_work_items w2 where w2.interpretation_id=b.layer3_interpretation_id and w2.candidate_context ? 'provider_fee_rule')
        then jsonb_build_object('action','return_layer3','text','The provider publishes this figure as its indicative annual fee (approved provider rule). Send it back to record it.')
      when coalesce(b.l3_validator->'errors','[]'::jsonb) ? 'evidence quote not present in governed Evidence'
        and exists(select 1 from pipeline.layer3_model_profiles mp where mp.enabled and not mp.paused
                   and 'provider_current_tuition_validation'=any(mp.allowed_task_classes)
                   and coalesce(mp.quality_benchmark->>'binding_hash','') not in ('','c45afa505cb3dbf1bc4bafb43713ae8a55c43ae20e88ff61063df8e92218e0bf'))
        then jsonb_build_object('action','return_layer3','text','The AI''s quote was refused only because the page is saved with link formatting. That is now fixed: send it back for another AI check.')
      when b.quotes_text ~ '\m(total|whole course|full course|entire course)\M' then jsonb_build_object('action','reject','text','The page shows this amount as a course total, not a yearly fee.')
      when b.quotes_text ~ '\m(per semester|per trimester|per unit|per credit|per subject)\M' then jsonb_build_object('action','reject','text','The page shows this amount per semester or per unit, not per year.')
      when b.quotes_text ~ '\m(annual|annually|per year|per annum|a year|yearly)\M' and jsonb_typeof(b.proposed_value)='object' and lower(coalesce(b.proposed_value->>'basis','')) in ('annual','indicative_annual','per_year_explicit') then jsonb_build_object('action','approve','text','The page shows this amount as a yearly fee.')
      when b.quotes_text ~ '\m(annual|annually|per year|per annum|a year|yearly)\M' and jsonb_typeof(b.proposed_value)='object' then jsonb_build_object('action','check','text','The page shows a yearly fee. Use Edit and approve to confirm the amount and that it is charged per year.')
      when b.quotes_text ~ '\m(annual|annually|per year|per annum|a year|yearly)\M' then jsonb_build_object('action','check','text','The page shows a yearly fee, but no amount was proposed. Use Edit and approve to enter it.')
      when b.quotes_text='' then jsonb_build_object('action','check','text','The AI could not quote this fee from the page. Check the page.')
      else jsonb_build_object('action','check','text','The page does not say how often this fee is charged. Check the page.') end,
    'technical', jsonb_build_object('original_reason',b.escalation_reason,'entity_id',b.entity_id,'evidence_id',b.evidence_id,'layer3_interpretation_id',b.layer3_interpretation_id,
      'ai_confidence',b.ai_confidence,'before_value',b.before_value,'proposed_value',b.proposed_value,'layer2_state',b.layer2_state,'layer3_state',b.layer3_state,'change_control_ref',b.change_control_ref)
  ) order by b.created_at asc),'[]'::jsonb) into v_items from base b;

  select jsonb_build_object(
    'waiting',(select count(*) from pipeline.layer4_review_items where status='pending'),
    'oldest_days',(select floor(extract(epoch from now()-min(created_at))/86400)::int from pipeline.layer4_review_items where status='pending'),
    'target_days',7,
    'by_task',(select coalesce(jsonb_object_agg(t,n),'{}'::jsonb) from (select case field_code when 'provider_current_tuition_validation' then 'Tuition fee' when 'official_course_url' then 'Official course link' when 'scope_resolution' then 'Scholarship scope' else initcap(replace(field_code,'_',' ')) end t, count(*) n from pipeline.layer4_review_items where status='pending' group by 1) x)
  ) into v_summary;

  return jsonb_build_object('items',v_items,'summary',v_summary);
end $$;


ALTER FUNCTION "security"."layer4_review_desk_v1_impl"("p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_review_queue_impl"("p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
begin
 if auth.uid() is null or security.current_role_rank()<3 then raise exception 'curator role required' using errcode='42501'; end if;
 return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select id,entity_type,entity_id,field_code,evidence_id,layer3_interpretation_id,before_value,proposed_value,layer2_state,layer3_state,status,assigned_to,escalation_reason,change_control_ref,created_at,decided_at from pipeline.layer4_review_items where status=coalesce(p_status,status) order by created_at desc limit least(greatest(p_limit,1),250)) x),'[]'::jsonb);
end $$;


ALTER FUNCTION "security"."layer4_review_queue_impl"("p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_scholarship_scope_close_impl"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'scholarship'
    AS $$
declare v_item pipeline.layer4_review_items%rowtype; v_open int;
begin
  select * into v_item from pipeline.layer4_review_items where id=p_item_id;
  select count(*) into v_open from scholarship.course_mapping_candidates where scholarship_id=v_item.entity_id and status='needs_review';
  if v_open>0 then raise exception '% course(s) still need a scope decision. Decide them in Batches, then mark this as done.', v_open; end if;
  return jsonb_build_object('scope_closed',true);
end $$;


ALTER FUNCTION "security"."layer4_scholarship_scope_close_impl"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_scope_rule_apply_one_impl"("p_candidate_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'scholarship', 'catalogue'
    AS $$
declare v_c scholarship.course_mapping_candidates%rowtype;v_s scholarship.scholarships%rowtype;v_course catalogue.courses%rowtype;v_rule pipeline.layer4_scope_rules%rowtype;v_inserted int:=0;
begin
 select * into v_c from scholarship.course_mapping_candidates where id=p_candidate_id for update;
 if not found or v_c.status<>'needs_review' or v_c.evidence_id is null then return jsonb_build_object('applied',false,'reason','not_eligible'); end if;
 select * into v_s from scholarship.scholarships where id=v_c.scholarship_id;
 select * into v_course from catalogue.courses where id=v_c.course_id;
 if v_course.provider_id is distinct from v_s.provider_id then return jsonb_build_object('applied',false,'reason','provider_mismatch'); end if;
 select * into v_rule from pipeline.layer4_scope_rules r where r.enabled and r.scholarship_id=v_c.scholarship_id and r.candidate_reason=v_c.candidate_reason and r.evidence_id=v_c.evidence_id and r.provider_id=v_s.provider_id order by r.updated_at desc limit 1;
 if not found then return jsonb_build_object('applied',false,'reason','no_matching_rule'); end if;
 if v_rule.decision='accept' then
   insert into scholarship.course_mappings(scholarship_id,course_id,mapping_state,mapping_basis,evidence_id,mapped_by)
   values(v_c.scholarship_id,v_c.course_id,'mapped','layer4_reusable_rule:'||v_rule.id::text,v_c.evidence_id,v_rule.created_by)
   on conflict(scholarship_id,course_id) do nothing;
   get diagnostics v_inserted=row_count;
   update scholarship.course_mapping_candidates set status='accepted',updated_at=now() where id=v_c.id;
 else
   update scholarship.course_mapping_candidates set status='rejected',updated_at=now() where id=v_c.id;
 end if;
 update pipeline.layer4_scope_rules set apply_count=apply_count+1,last_applied_at=now(),updated_at=now() where id=v_rule.id;
 return jsonb_build_object('applied',true,'rule_id',v_rule.id,'decision',v_rule.decision,'mapping_inserted',v_inserted);
end$$;


ALTER FUNCTION "security"."layer4_scope_rule_apply_one_impl"("p_candidate_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_scope_rule_candidate_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'scholarship', 'catalogue'
    AS $$
begin
 if new.status='needs_review' and new.evidence_id is not null then perform security.layer4_scope_rule_apply_one_impl(new.id); end if;
 return new;
end$$;


ALTER FUNCTION "security"."layer4_scope_rule_candidate_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_team_forecast_v1_impl"("p_days" integer DEFAULT 7) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_rank int; v_days int:=case when p_days>=30 then 30 else 7 end; v_since timestamptz;
  v_waiting int; v_in int; v_out int; v_net numeric; v_clear jsonb; v_people jsonb; v_daily jsonb; v_ages jsonb; v_outcomes jsonb;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
  v_since := date_trunc('day', now()) - make_interval(days=>v_days-1);

  select count(*) into v_waiting from pipeline.layer4_review_items where status='pending';
  select count(*) into v_in from pipeline.layer4_review_items where created_at>=v_since;
  select count(*) into v_out from pipeline.layer4_decisions where created_at>=v_since;
  v_net := (v_out - v_in)::numeric / v_days;
  v_clear := case
    when v_waiting=0 then jsonb_build_object('state','clear','text','Nothing waiting.')
    when v_net<=0 then jsonb_build_object('state','growing','text',format('Not clearing at the current pace: about %s more arrive than are decided each day.', round(-v_net,1)),'per_day',round(v_net,1))
    else jsonb_build_object('state','clearing','days',ceil(v_waiting/v_net),'date',(current_date + ceil(v_waiting/v_net)::int),'text',format('At the current pace the queue clears in about %s days.', ceil(v_waiting/v_net)),'per_day',round(v_net,1)) end;

  select coalesce(jsonb_agg(jsonb_build_object('day',d::date,'arrived',(select count(*) from pipeline.layer4_review_items i where i.created_at>=d and i.created_at<d+interval '1 day'),
         'decided',(select count(*) from pipeline.layer4_decisions x where x.created_at>=d and x.created_at<d+interval '1 day')) order by d),'[]'::jsonb)
    into v_daily from generate_series(v_since, date_trunc('day',now()), interval '1 day') d;

  select jsonb_build_object('0-2',count(*) filter (where now()-created_at<interval '3 days'),
    '3-7',count(*) filter (where now()-created_at>=interval '3 days' and now()-created_at<interval '8 days'),
    '8-14',count(*) filter (where now()-created_at>=interval '8 days' and now()-created_at<interval '15 days'),
    '15+',count(*) filter (where now()-created_at>=interval '15 days'),
    'over_target',count(*) filter (where now()-created_at>interval '7 days'))
    into v_ages from pipeline.layer4_review_items where status='pending';

  select coalesce(jsonb_object_agg(action,n),'{}'::jsonb) into v_outcomes
    from (select action, count(*) n from pipeline.layer4_decisions where created_at>=v_since and (v_rank>=5 or actor_id=v_actor) group by 1) o;

  select coalesce(jsonb_agg(p order by (p->>'decided')::int desc),'[]'::jsonb) into v_people from (
    select jsonb_build_object('actor_id',d.actor_id,'who',coalesce(u.email,'Unknown'),'is_me',d.actor_id=v_actor,'decided',count(*),
      'median_minutes',round((percentile_cont(0.5) within group (order by extract(epoch from d.created_at-i.claimed_at)/60)
          filter (where i.claimed_at is not null and i.claimed_at<=d.created_at and d.created_at-i.claimed_at<interval '12 hours'))::numeric,1),
      'approved',count(*) filter (where d.action in ('approve','edit_and_approve')),'rejected',count(*) filter (where d.action='reject'),
      'sent_back',count(*) filter (where d.action in ('request_more_evidence','return_layer2','return_layer3')),
      'last_at',max(d.created_at)) p
    from pipeline.layer4_decisions d join pipeline.layer4_review_items i on i.id=d.review_item_id left join auth.users u on u.id=d.actor_id
    where d.created_at>=v_since and (v_rank>=5 or d.actor_id=v_actor)
    group by d.actor_id,u.email) x;

  return jsonb_build_object('days',v_days,'scope',case when v_rank>=5 then 'team' else 'me' end,'target_days',7,
    'waiting',v_waiting,'arrived',v_in,'decided',v_out,'forecast',v_clear,'daily',v_daily,'ages',v_ages,'outcomes',v_outcomes,'people',v_people,
    'computed_at',now());
end $$;


ALTER FUNCTION "security"."layer4_team_forecast_v1_impl"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_tuition_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'pipeline', 'search', 'ref'
    AS $$
declare v_item pipeline.layer4_review_items%rowtype; v_code text; v_source uuid; v_amount numeric; v_cur text; v_basis text; v_year int; v_aud text; v_key text; v_fee uuid;
begin
  select * into v_item from pipeline.layer4_review_items where id=p_item_id;
  if v_item.entity_type<>'course' then raise exception 'tuition decisions apply to courses only'; end if;
  -- Plain Approve: use the item's proposed value, otherwise the AI's answer on the Layer 3 result.
  if p_value is null or jsonb_typeof(p_value)<>'object' then
    p_value := coalesce(case when jsonb_typeof(v_item.proposed_value)='object' then v_item.proposed_value end,
      (select case when jsonb_typeof(i.candidate_value)='object' then i.candidate_value end from pipeline.layer3_interpretations i where i.id=v_item.layer3_interpretation_id));
  end if;
  if p_value is null or jsonb_typeof(p_value)<>'object' then raise exception 'there is no fee to approve; use Edit and approve to enter it'; end if;
  v_amount := nullif(p_value->>'amount','')::numeric;
  v_cur := upper(nullif(btrim(coalesce(p_value->>'currency_code',p_value->>'currency')),''));
  v_basis := lower(nullif(btrim(p_value->>'basis'),''));
  v_year := nullif(p_value->>'fee_year','')::int;
  v_aud := lower(coalesce(nullif(btrim(p_value->>'audience'),''),'international'));
  if v_amount is null or v_amount<=0 then raise exception 'fee amount must be greater than 0'; end if;
  if v_cur not in ('AUD','NZD','CAD') then raise exception 'currency must be AUD, NZD or CAD'; end if;
  if v_basis not in ('annual','indicative_annual','per_year_explicit') then raise exception 'fee must be charged per year to approve (basis annual or indicative_annual)'; end if;
  if v_year is not null and (v_year<2024 or v_year>2030) then raise exception 'fee year must be between 2024 and 2030'; end if;
  if v_aud<>'international' then raise exception 'only international tuition fees are recorded here'; end if;
  select course_code into v_code from catalogue.courses where id=v_item.entity_id;
  if v_code is null then raise exception 'course code unavailable'; end if;
  select source_id into v_source from pipeline.evidence_artifacts where id=v_item.evidence_id;
  if v_source is null then raise exception 'the review item has no Evidence source'; end if;
  v_key := lower(upper(btrim(v_code))||':'||v_aud||':'||coalesce(v_year::text,'current')||':'||v_basis);
  insert into catalogue.course_fees(course_id,fee_year,audience,fee_type,amount,currency_code,basis,notes,source_id,evidence_id,confidence,campus_id,source_fee_key,status,last_verified_at,source_snapshot_at,updated_at)
  values (v_item.entity_id,v_year,v_aud,'provider_current_tuition',v_amount,v_cur,v_basis,
          format('CF-247 Layer 4 human decision; review item %s; %s',v_item.id,left(trim(p_reason),200)),
          v_source,v_item.evidence_id,1,null,v_key,'active',now(),now(),now())
  on conflict(course_id,source_id,source_fee_key) where source_id is not null and source_fee_key is not null
  do update set amount=excluded.amount,currency_code=excluded.currency_code,basis=excluded.basis,fee_year=excluded.fee_year,
                notes=excluded.notes,evidence_id=excluded.evidence_id,confidence=1,status='active',last_verified_at=now(),updated_at=now()
  returning id into v_fee;
  perform search.refresh_course_enrichment_scoped_v1(array[v_item.entity_id], true);
  return jsonb_build_object('course_fee_id',v_fee,'fee_key',v_key,'search_refreshed',true);
end $$;


ALTER FUNCTION "security"."layer4_tuition_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_tuition_settle_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n_dup int := 0; n_diff int := 0; n_none int := 0;
begin
  with d as (
    select r.id, row_number() over (partition by r.entity_id order by r.created_at desc) rn
      from pipeline.layer4_review_items r
     where r.status = 'pending' and r.field_code = 'provider_current_tuition_validation'
       and coalesce(r.claimed_at, '-infinity') < now() - interval '30 minutes')
  update pipeline.layer4_review_items r set status = 'superseded', decided_at = now(),
         layer3_state = coalesce(r.layer3_state, '{}'::jsonb) || jsonb_build_object('superseded', jsonb_build_object(
           'reason', 'A newer review for the same course is waiting.', 'at', now(), 'ref', 'Decision 224'))
    from d where d.id = r.id and d.rn > 1;
  get diagnostics n_dup = row_count;

  with s as (
    select r.id, r.entity_id, (r.layer2_state->'candidate_context'->'provider_current_tuition'->>'amount')::numeric asked,
           (security.coverage_tuition_target_v1(g.candidates->'fee')->>'amount')::numeric tgt,
           g.candidates->'fee'->'candidates' @> '[{"international": true}]'::jsonb intl_any
      from pipeline.layer4_review_items r
      join pipeline.coverage_course_pages g on g.course_id = r.entity_id and g.read_status = 'read'
     where r.status = 'pending' and r.field_code = 'provider_current_tuition_validation'
       and coalesce(r.claimed_at, '-infinity') < now() - interval '30 minutes'
       and g.candidates->>'extractor' >= 'coverage-sweep-v0.5.6'
       and r.layer2_state->'candidate_context'->'provider_current_tuition'->>'amount' is not null),
  u as (
    update pipeline.layer4_review_items r set status = 'superseded', decided_at = now(),
           layer3_state = coalesce(r.layer3_state, '{}'::jsonb) || jsonb_build_object('superseded', jsonb_build_object(
             'reason', case when s.tgt is null
                         then 'The amount asked about is not an international annual tuition fee, and the page''s international view shows none.'
                         else 'The amount asked about is not the page''s international annual tuition fee; the international fee on the page went to the AI check.' end,
             'asked_amount', s.asked, 'page_international_fee', s.tgt, 'at', now(), 'ref', 'Decision 224'))
      from s where s.id = r.id and s.tgt is distinct from s.asked and (s.tgt is not null or not s.intl_any)
    returning r.entity_id, s.tgt)
  , h as (
    update pipeline.coverage_course_pages g set l3_handoff_at = null, l3_work_item_id = null
      from u where u.entity_id = g.course_id and u.tgt is not null
    returning g.course_id)
  select count(*) filter (where tgt is not null), count(*) filter (where tgt is null) into n_diff, n_none from u;

  return jsonb_build_object('duplicates', n_dup, 'resent_with_international_fee', n_diff, 'no_international_fee', n_none, 'at', now());
end $$;


ALTER FUNCTION "security"."layer4_tuition_settle_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_underlying_value"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'scholarship', 'pipeline'
    AS $$
declare v jsonb;
begin
  if p_entity_type='course' then
    if p_field_code='course_description' then select to_jsonb(description) into v from catalogue.courses where id=p_entity_id;
    elsif p_field_code='delivery_mode' then select to_jsonb(delivery_mode) into v from catalogue.courses where id=p_entity_id;
    elsif p_field_code='duration' then select jsonb_build_object('value',duration_value,'unit',duration_unit) into v from catalogue.courses where id=p_entity_id;
    elsif p_field_code='official_course_url' then
      select to_jsonb(coalesce(
        (select cl.url from catalogue.course_links cl where cl.course_id=p_entity_id and cl.link_type='official_course' and coalesce(cl.status,'active')='active'
         order by (cl.audience='international') desc,cl.last_verified_at desc nulls last,cl.created_at desc limit 1),
        c.course_url
      )) into v from catalogue.courses c where c.id=p_entity_id;
    elsif p_field_code='stable_key' then select to_jsonb(stable_key) into v from catalogue.courses where id=p_entity_id;
    elsif p_field_code='canonical_title' then select to_jsonb(canonical_title) into v from catalogue.courses where id=p_entity_id;
    elsif p_field_code='course_code' then select to_jsonb(course_code) into v from catalogue.courses where id=p_entity_id;
    elsif p_field_code='canonical_source_id' then select to_jsonb(canonical_source_id) into v from catalogue.courses where id=p_entity_id;
    end if;
  elsif p_entity_type='provider' then
    if p_field_code='display_name' then select to_jsonb(display_name) into v from catalogue.providers where id=p_entity_id;
    elsif p_field_code='website' then select to_jsonb(website) into v from catalogue.providers where id=p_entity_id;
    elsif p_field_code='description' then select to_jsonb(description) into v from catalogue.providers where id=p_entity_id;
    elsif p_field_code='primary_city' then select to_jsonb(primary_city) into v from catalogue.providers where id=p_entity_id;
    elsif p_field_code='phone' then select to_jsonb(phone) into v from catalogue.providers where id=p_entity_id;
    elsif p_field_code='email' then select to_jsonb(email) into v from catalogue.providers where id=p_entity_id;
    elsif p_field_code='stable_key' then select to_jsonb(stable_key) into v from catalogue.providers where id=p_entity_id;
    elsif p_field_code='canonical_name' then select to_jsonb(canonical_name) into v from catalogue.providers where id=p_entity_id;
    elsif p_field_code='country_id' then select to_jsonb(country_id) into v from catalogue.providers where id=p_entity_id;
    elsif p_field_code='canonical_source_id' then select to_jsonb(canonical_source_id) into v from catalogue.providers where id=p_entity_id;
    end if;
  elsif p_entity_type='campus' then
    if p_field_code='name' then select to_jsonb(name) into v from catalogue.campuses where id=p_entity_id;
    elsif p_field_code='city' then select to_jsonb(city) into v from catalogue.campuses where id=p_entity_id;
    elsif p_field_code='address_line1' then select to_jsonb(address_line1) into v from catalogue.campuses where id=p_entity_id;
    elsif p_field_code='address_line2' then select to_jsonb(address_line2) into v from catalogue.campuses where id=p_entity_id;
    elsif p_field_code='postcode' then select to_jsonb(postcode) into v from catalogue.campuses where id=p_entity_id;
    elsif p_field_code='phone' then select to_jsonb(phone) into v from catalogue.campuses where id=p_entity_id;
    elsif p_field_code='website' then select to_jsonb(website) into v from catalogue.campuses where id=p_entity_id;
    elsif p_field_code='stable_key' then select to_jsonb(stable_key) into v from catalogue.campuses where id=p_entity_id;
    elsif p_field_code='provider_id' then select to_jsonb(provider_id) into v from catalogue.campuses where id=p_entity_id;
    elsif p_field_code='source_id' then select to_jsonb(source_id) into v from catalogue.campuses where id=p_entity_id;
    elsif p_field_code='evidence_id' then select to_jsonb(evidence_id) into v from catalogue.campuses where id=p_entity_id;
    end if;
  elsif p_entity_type='scholarship' then
    if p_field_code='name' then select to_jsonb(name) into v from scholarship.scholarships where id=p_entity_id;
    elsif p_field_code='description' then select to_jsonb(description) into v from scholarship.scholarships where id=p_entity_id;
    elsif p_field_code='audience' then select to_jsonb(audience) into v from scholarship.scholarships where id=p_entity_id;
    elsif p_field_code='award_value_text' then select to_jsonb(award_value_text) into v from scholarship.scholarships where id=p_entity_id;
    elsif p_field_code='source_url' then select to_jsonb(source_url) into v from scholarship.scholarships where id=p_entity_id;
    elsif p_field_code='stable_key' then select to_jsonb(stable_key) into v from scholarship.scholarships where id=p_entity_id;
    elsif p_field_code='provider_id' then select to_jsonb(provider_id) into v from scholarship.scholarships where id=p_entity_id;
    elsif p_field_code='source_id' then select to_jsonb(source_id) into v from scholarship.scholarships where id=p_entity_id;
    elsif p_field_code='evidence_id' then select to_jsonb(evidence_id) into v from scholarship.scholarships where id=p_entity_id;
    end if;
  elsif p_entity_type='provider_contact' then
    if p_field_code='full_name' then select to_jsonb(full_name) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='job_title' then select to_jsonb(job_title) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='team_name' then select to_jsonb(team_name) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='territory_text' then select to_jsonb(territory_text) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='work_email' then select to_jsonb(work_email) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='work_phone' then select to_jsonb(work_phone) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='professional_profile_url' then select to_jsonb(professional_profile_url) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='source_url' then select to_jsonb(source_url) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='provider_id' then select to_jsonb(provider_id) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='profile_id' then select to_jsonb(profile_id) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='evidence_id' then select to_jsonb(evidence_id) into v from pipeline.provider_contact_observations where id=p_entity_id;
    elsif p_field_code='identity_hash' then select to_jsonb(identity_hash) into v from pipeline.provider_contact_observations where id=p_entity_id;
    end if;
  end if;
  return v;
end $$;


ALTER FUNCTION "security"."layer4_underlying_value"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_underlying_value"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text") IS 'A16 cross-platform underlying-value reader for Provider/Course/Campus/Scholarship/provider_contact. It reads but never mutates source/canonical/history rows.';



CREATE OR REPLACE FUNCTION "security"."layer4_url_query"("t" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select replace(replace(replace(replace(replace(replace(btrim(coalesce(t,'')),'%','%25'),'&','%26'),'+','%2B'),'#','%23'),'/','%2F'),' ','+')
$$;


ALTER FUNCTION "security"."layer4_url_query"("t" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_validate_override_value"("p_value_kind" "text", "p_value" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $_$
declare v_text text; v_num numeric;
begin
  if p_value is null then raise exception 'override value is required' using errcode='22023'; end if;
  if p_value_kind in ('text','url','email','phone') then
    if jsonb_typeof(p_value)<>'string' then raise exception 'override value must be a JSON string' using errcode='22023'; end if;
    v_text:=trim(p_value #>> '{}');
    if v_text='' then raise exception 'override value cannot be empty' using errcode='22023'; end if;
    if p_value_kind='url' and v_text !~* '^https?://[^[:space:]]+$' then raise exception 'URL override must use http/https' using errcode='22023'; end if;
    if p_value_kind='email' and v_text !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'invalid email override' using errcode='22023'; end if;
    if p_value_kind='phone' and length(regexp_replace(v_text,'[^0-9+]','','g'))<5 then raise exception 'invalid phone override' using errcode='22023'; end if;
  elsif p_value_kind='duration' then
    if jsonb_typeof(p_value)<>'object' then raise exception 'duration override must be an object' using errcode='22023'; end if;
    v_num:=nullif(p_value->>'value','')::numeric;
    if v_num is null or v_num<=0 or nullif(trim(p_value->>'unit'),'') is null then raise exception 'duration requires positive value and unit' using errcode='22023'; end if;
  elsif p_value_kind='uuid' then
    perform (p_value #>> '{}')::uuid;
  end if;
end $_$;


ALTER FUNCTION "security"."layer4_validate_override_value"("p_value_kind" "text", "p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."link_refresh_policy_days"("p_course_id" "uuid", "p_link_type" "text") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select r.every_days from pipeline.link_refresh_policies r
    join catalogue.courses c on c.id = p_course_id join catalogue.providers p on p.id = c.provider_id
   where r.active and r.link_type = p_link_type
     and (r.provider_id is null or r.provider_id = c.provider_id)
     and (r.country_id is null or r.country_id = p.country_id)
   order by (r.provider_id is not null) desc, (r.country_id is not null) desc
   limit 1
$$;


ALTER FUNCTION "security"."link_refresh_policy_days"("p_course_id" "uuid", "p_link_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."link_refresh_tick_v1"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_lim int := greatest(1, least(coalesce(p_limit, 500), 5000)); v_reread int := 0; v_research int := 0; v_verified int := 0;
        v_unverified int := 0; v_reg int := 0; v_manual uuid; v_l4 uuid;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select id into v_manual from pipeline.sources where source_type = 'manual_entry' limit 1;
  select id into v_l4 from pipeline.sources where source_type = 'layer4_human_review' limit 1;

  -- 1. Official pages due for a re-check: the reader reads them again.
  with due as (
    select p.course_id from pipeline.coverage_course_pages p
     where p.status = 'bound' and p.read_status = 'read' and p.identity_basis is not null
       and coalesce(p.next_read_at, now()) <= now() and coalesce(p.leased_until, '-infinity') < now()
       and p.read_at < now() - make_interval(days => coalesce(security.link_refresh_policy_days(p.course_id, 'official_course'), 30))
     order by p.read_at limit v_lim)
  update pipeline.coverage_course_pages p set next_read_at = now(), read_attempts = 0 from due where p.course_id = due.course_id;
  get diagnostics v_reread = row_count;

  -- 2. Courses whose page search found nothing are searched again after their policy period.
  with due as (
    select s.course_id from pipeline.course_link_search s
     where s.state in ('none','error')
       and coalesce(s.done_at, s.queued_at) < now() - make_interval(days => coalesce(security.link_refresh_policy_days(s.course_id, 'official_course'), 30))
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = s.course_id and k.field = 'official_url')
     order by coalesce(s.done_at, s.queued_at) limit v_lim)
  update pipeline.course_link_search s set state = 'queued', stage = 'cricos', attempts = 0, done_at = null, queued_at = now()
    from due where s.course_id = due.course_id;
  get diagnostics v_research = row_count;

  -- 3. Carry each read to the catalogue link (never a link set by a person or confirmed in Layer 4).
  update catalogue.course_links l set last_verified_at = p.read_at, updated_at = now()
    from pipeline.coverage_course_pages p
   where l.link_type = 'official_course' and l.status = 'active' and p.course_id = l.course_id
     and security.coverage_norm_url(p.url) = security.coverage_norm_url(l.url)
     and p.read_status = 'read' and p.identity_basis is not null and p.read_at > coalesce(l.last_verified_at, '-infinity')
     and l.source_id is distinct from v_manual and l.source_id is distinct from v_l4;
  get diagnostics v_verified = row_count;

  with gone as (
    select l.id, l.course_id from catalogue.course_links l
      join pipeline.coverage_course_pages p on p.course_id = l.course_id and security.coverage_norm_url(p.url) = security.coverage_norm_url(l.url)
     where l.link_type = 'official_course' and l.status = 'active'
       and l.source_id is distinct from v_manual and l.source_id is distinct from v_l4
       and p.read_at > coalesce(l.last_verified_at, l.created_at)
       and p.read_status = 'fetch_failed' and p.http_status in (404, 410) and p.read_attempts >= 2
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = l.course_id and k.field = 'official_url')
     limit v_lim),
  upd as (update catalogue.course_links l set status = 'unverified', is_primary = false, updated_at = now() from gone where l.id = gone.id returning l.course_id),
  -- a page that still loads but no longer shows the course's code keeps its link; the course is searched again, and a
  -- better page found that way reaches Layer 4 as "differs" through the normal admission path.
  doubt as (
    select l.course_id from catalogue.course_links l
      join pipeline.coverage_course_pages p on p.course_id = l.course_id and security.coverage_norm_url(p.url) = security.coverage_norm_url(l.url)
     where l.link_type = 'official_course' and l.status = 'active' and p.read_status = 'identity_mismatch'
       and p.read_at > coalesce(l.last_verified_at, l.created_at)
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = l.course_id and k.field = 'official_url')
     limit v_lim),
  ins as (
    insert into pipeline.course_link_search(course_id, provider_id)
    select distinct x.course_id, c.provider_id from (select course_id from upd union select course_id from doubt) x join catalogue.courses c on c.id = x.course_id
     where exists (select 1 from pipeline.course_link_recipes r where r.provider_id = c.provider_id and r.active)
    on conflict (course_id) do update set state = 'queued', stage = 'cricos', attempts = 0, done_at = null, queued_at = now()
     where pipeline.course_link_search.state in ('none','error')
       and coalesce(pipeline.course_link_search.done_at, pipeline.course_link_search.queued_at)
           < now() - make_interval(days => coalesce(security.link_refresh_policy_days(excluded.course_id, 'official_course'), 30))
    returning 1)
  select (select count(*) from upd) into v_unverified;

  -- 4. Regulator listings for NZ courses that gained an NZQA code.
  insert into catalogue.course_links(course_id, link_type, url, label, is_primary, status, source_id, confidence)
  select r.course_id, 'regulator_listing',
         'https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=' || upper(btrim(r.registration_code)),
         'NZQA qualification listing', false, 'active',
         (select s.id from pipeline.sources s where s.url ilike 'https://www.nzqa.govt.nz/providers/%' order by s.created_at limit 1), 0.95
    from catalogue.course_registrations r join catalogue.courses c on c.id = r.course_id and c.lifecycle_status = 'active'
   where lower(r.scheme) = 'nzqa' and coalesce(r.status, 'active') = 'active' and btrim(r.registration_code) ~* '^[A-Z0-9]{3,12}$'
     and exists (select 1 from pipeline.link_portals lp where lp.code = 'nzqa' and lp.active)
     and not exists (select 1 from catalogue.course_links l where l.course_id = r.course_id and l.link_type = 'regulator_listing')
   limit v_lim
  on conflict (course_id, link_type, url) do nothing;
  get diagnostics v_reg = row_count;

  update pipeline.link_refresh_policies set last_run_at = now(),
         last_result = jsonb_build_object('reread', v_reread, 'searched_again', v_research, 'verified', v_verified, 'unverified', v_unverified, 'regulator_added', v_reg)
   where active and provider_id is null and country_id is null;
  return jsonb_build_object('reread', v_reread, 'searched_again', v_research, 'verified', v_verified, 'unverified', v_unverified, 'regulator_added', v_reg);
end $_$;


ALTER FUNCTION "security"."link_refresh_tick_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."live_worker_summary"("p_content" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare j jsonb;
begin
  begin j := p_content::jsonb; exception when others then return null; end;
  if jsonb_typeof(j) <> 'object' then return null; end if;
  return (select jsonb_object_agg(e.key, e.value) from jsonb_each(j) e
           where jsonb_typeof(e.value) in ('number','string','boolean')
              or (jsonb_typeof(e.value) = 'object' and e.key in ('tally','changes','candidates')));
end $$;


ALTER FUNCTION "security"."live_worker_summary"("p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."m2_5_readiness_snapshot_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$
declare v_rank integer;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;

  return jsonb_build_object(
    'production_source_capabilities_enabled',
      (select count(*) from pipeline.environment_source_gates where environment='production' and enabled),
    'production_scrapers_enabled',
      (select count(*) from pipeline.layer2_provider_environment_gates where environment='production' and enabled),
    'production_ai_profiles_enabled',
      (select count(*) from pipeline.layer3_profile_environment_gates where environment='production' and enabled),
    'production_uat_open',
      (select count(*) from pipeline.platform_uat_catalogue
       where environment_scope in ('production','both') and hard_gate and status<>'pass'),
    'capacity',security.platform_capacity_snapshot_internal('pilot'),
    'retention_policy_classes',(select count(*) from pipeline.retention_class_policies),
    'performance_profiles',(select count(*) from pipeline.performance_workload_profiles),
    'current_layer2_wave',(
      select coalesce(to_jsonb(x),'{}'::jsonb)
      from (
        select id,status,country_code,scope_type,requested_wave_size,accepted_wave_size,
               schedule_remaining,total_items,dispatched_items,completed_items,failed_items,
               last_wave_at,updated_at
        from pipeline.layer2_scope_wave_requests
        order by created_at desc limit 1
      ) x
    )
  );
end $$;


