    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$ select security.onboarding_cases_list_impl(p_stage,p_outcome,p_country_code,p_case_type,p_limit) $$;


ALTER FUNCTION "security"."onboarding_cases_list_browser_bridge"("p_stage" "text", "p_outcome" "text", "p_country_code" "text", "p_case_type" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."onboarding_cases_list_impl"("p_stage" "text" DEFAULT NULL::"text", "p_outcome" "text" DEFAULT NULL::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_case_type" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank() < 3 then
    raise exception 'curator role required' using errcode='42501';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.updated_at desc, x.id)
    from (
      select c.id,c.case_type,c.country_code,c.title,c.source_id,c.source_profile_id,c.provider_id,c.course_id,
             c.stage,c.outcome,c.adapter_family,c.source_qualification,c.adapter_assessment,c.schema_assessment,
             c.operational_manifest,c.change_control_ref,c.uat_ref,c.created_by,c.updated_by,c.created_at,c.updated_at,
             security.onboarding_next_stage(c.stage) as next_stage,
             (select count(*) from pipeline.onboarding_lifecycle_events e where e.case_id=c.id) as history_count
      from pipeline.onboarding_cases c
      where (p_stage is null or c.stage=p_stage)
        and (p_outcome is null or c.outcome=p_outcome)
        and (p_country_code is null or c.country_code=upper(p_country_code))
        and (p_case_type is null or c.case_type=p_case_type)
      order by c.updated_at desc,c.id
      limit least(greatest(coalesce(p_limit,100),1),500)
    ) x
  ),'[]'::jsonb);
end $$;


ALTER FUNCTION "security"."onboarding_cases_list_impl"("p_stage" "text", "p_outcome" "text", "p_country_code" "text", "p_case_type" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."onboarding_next_stage"("p_stage" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
select case p_stage
  when 'draft' then 'source_qualification'
  when 'source_qualification' then 'adapter_assessment'
  when 'adapter_assessment' then 'schema_assessment'
  when 'schema_assessment' then 'l1_uat'
  when 'l1_uat' then 'l2_uat'
  when 'l2_uat' then 'l3_ready'
  when 'l3_ready' then 'operational_certification'
  when 'operational_certification' then 'production_promotion_ready'
  else null end
$$;


ALTER FUNCTION "security"."onboarding_next_stage"("p_stage" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."pipeline_setting_cron_arg"("p_jobname" "text", "p_key" "text", "p_value" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cmd text; v_json text; v_new text; v_jobid bigint;
begin
  select jobid, command into v_jobid, v_cmd from cron.job where jobname = p_jobname;
  if v_jobid is null then raise exception 'job % not found', p_jobname; end if;
  v_json := substring(v_cmd from ',''(\{.*\})''::jsonb');
  if v_json is null then raise exception 'job % has no JSON body', p_jobname; end if;
  v_new := jsonb_set(v_json::jsonb, array[p_key], to_jsonb(p_value), true)::text;
  perform cron.alter_job(job_id := v_jobid, command := replace(v_cmd, '''' || v_json || '''', '''' || v_new || ''''));
end $$;


ALTER FUNCTION "security"."pipeline_setting_cron_arg"("p_jobname" "text", "p_key" "text", "p_value" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."place_presentable"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case when p is null then null
              when p ~ '[a-z]' or p !~ '[A-Z]' then btrim(p)
              else regexp_replace(initcap(btrim(p)),'\mMc([a-z])','Mc\1','g') end
$$;


ALTER FUNCTION "security"."place_presentable"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_capacity_snapshot_internal"("p_environment" "text" DEFAULT 'pilot'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'storage', 'public'
    AS $_$
declare
  v_db bigint;
  v_temp_bytes bigint;
  v_temp_files bigint;
  v_obj_count bigint;
  v_obj_bytes bigint;
  v_evidence_count bigint;
  v_unlinked_raw bigint;
  v_duplicate_unlinked bigint;
  v_reconciled_orphans bigint;
  v_orphans bigint;
  v_direct_virtual_refs bigint;
  v_reconciled_legacy_refs bigint;
  v_virtual_refs bigint;
  v_failed_raw bigint;
  v_failed bigint;
  v_largest jsonb;
  v_evidence_policy jsonb;
  v_policy jsonb;
  v_severity text := 'ok';
  v_integrity_count bigint;
  v_evidence_pct numeric;
  v_prev_temp_bytes bigint;
  v_prev_observed_at timestamptz;
  v_temp_delta bigint;
begin
  if p_environment not in ('pilot','production') then
    raise exception 'invalid environment';
  end if;

  select pg_database_size(current_database()) into v_db;
  select coalesce(temp_bytes,0),coalesce(temp_files,0)
    into v_temp_bytes,v_temp_files
  from pg_stat_database where datname=current_database();

  select count(*),
         coalesce(sum(case when coalesce(metadata->>'size','') ~ '^[0-9]+$'
                           then (metadata->>'size')::bigint else 0 end),0)
    into v_obj_count,v_obj_bytes
  from storage.objects
  where bucket_id='evidence' and not is_delete_marker;

  select count(*) into v_evidence_count
  from pipeline.evidence_artifacts;

  select count(*) into v_unlinked_raw
  from storage.objects o
  where o.bucket_id='evidence'
    and not o.is_delete_marker
    and not exists (
      select 1 from pipeline.evidence_artifacts e
      where e.storage_path in (o.name, 'evidence/'||o.name)
    );

  select count(*) into v_duplicate_unlinked
  from storage.objects o
  where o.bucket_id='evidence'
    and not o.is_delete_marker
    and not exists (
      select 1 from pipeline.evidence_artifacts e
      where e.storage_path in (o.name, 'evidence/'||o.name)
    )
    and coalesce(o.metadata->>'eTag','')<>''
    and coalesce(o.metadata->>'size','') ~ '^[0-9]+$'
    and exists (
      select 1
      from storage.objects retained
      where retained.bucket_id='evidence'
        and not retained.is_delete_marker
        and retained.id<>o.id
        and retained.metadata->>'eTag'=o.metadata->>'eTag'
        and retained.metadata->>'size'=o.metadata->>'size'
        and exists (
          select 1 from pipeline.evidence_artifacts e
          where e.storage_path=retained.name or e.storage_path=('evidence/'||retained.name)
        )
    );

  select count(*) into v_reconciled_orphans
  from storage.objects o
  join pipeline.evidence_lineage_reconciliations r
    on r.target_kind='storage_object'
   and r.reconciliation_class='historical_orphan_explained'
   and r.storage_path=o.name
  where o.bucket_id='evidence'
    and not o.is_delete_marker
    and not exists (
      select 1 from pipeline.evidence_artifacts e
      where e.storage_path in (o.name, 'evidence/'||o.name)
    )
    and not (
      coalesce(o.metadata->>'eTag','')<>''
      and coalesce(o.metadata->>'size','') ~ '^[0-9]+$'
      and exists (
        select 1 from storage.objects retained
        where retained.bucket_id='evidence'
          and not retained.is_delete_marker
          and retained.id<>o.id
          and retained.metadata->>'eTag'=o.metadata->>'eTag'
          and retained.metadata->>'size'=o.metadata->>'size'
          and exists (
            select 1 from pipeline.evidence_artifacts e
            where e.storage_path=retained.name or e.storage_path=('evidence/'||retained.name)
          )
      )
    );

  v_orphans:=greatest(v_unlinked_raw-v_duplicate_unlinked-v_reconciled_orphans,0);

  select count(*) into v_direct_virtual_refs
  from pipeline.evidence_artifacts e
  where nullif(btrim(e.storage_path),'') is not null
    and e.storage_path ~ '^[A-Za-z][A-Za-z0-9+.-]*://';

  select count(*) into v_reconciled_legacy_refs
  from pipeline.evidence_artifacts e
  join pipeline.evidence_lineage_reconciliations r
    on r.target_kind='evidence_artifact'
   and r.reconciliation_class='legacy_virtual_reference'
   and r.evidence_id=e.id
  where nullif(btrim(e.storage_path),'') is not null
    and e.storage_path !~ '^[A-Za-z][A-Za-z0-9+.-]*://'
    and not exists (
      select 1 from storage.objects o
      where o.bucket_id='evidence'
        and not o.is_delete_marker
        and (o.name in (e.storage_path, regexp_replace(e.storage_path,'^evidence/','')))
    );

  v_virtual_refs:=v_direct_virtual_refs+v_reconciled_legacy_refs;

  select count(*) into v_failed_raw
  from pipeline.evidence_artifacts e
  where nullif(btrim(e.storage_path),'') is not null
    and e.storage_path !~ '^[A-Za-z][A-Za-z0-9+.-]*://'
    and not exists (
      select 1 from storage.objects o
      where o.bucket_id='evidence'
        and not o.is_delete_marker
        and (o.name in (e.storage_path, regexp_replace(e.storage_path,'^evidence/','')))
    );

  select count(*) into v_failed
  from pipeline.evidence_artifacts e
  where nullif(btrim(e.storage_path),'') is not null
    and e.storage_path !~ '^[A-Za-z][A-Za-z0-9+.-]*://'
    and not exists (
      select 1 from storage.objects o
      where o.bucket_id='evidence'
        and not o.is_delete_marker
        and (o.name in (e.storage_path, regexp_replace(e.storage_path,'^evidence/','')))
    )
    and not exists (
      select 1 from pipeline.evidence_lineage_reconciliations r
      where r.target_kind='evidence_artifact'
        and r.reconciliation_class='legacy_virtual_reference'
        and r.evidence_id=e.id
    );

  v_integrity_count:=greatest(v_orphans,v_failed);

  select coalesce(jsonb_agg(jsonb_build_object(
           'schema',schema_name,'relation',relation_name,'bytes',total_bytes
         ) order by total_bytes desc),'[]'::jsonb)
  into v_largest
  from (
    select n.nspname schema_name,c.relname relation_name,pg_total_relation_size(c.oid) total_bytes
    from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where c.relkind in ('r','m')
      and n.nspname not in ('pg_catalog','information_schema')
    order by total_bytes desc
    limit 10
  ) x;

  select coalesce(to_jsonb(p),'{}'::jsonb) into v_evidence_policy
  from pipeline.evidence_capacity_policy p where id=true;

  if coalesce((v_evidence_policy->>'planning_capacity_bytes')::bigint,0)>0 then
    v_evidence_pct:=round((v_obj_bytes::numeric/(v_evidence_policy->>'planning_capacity_bytes')::numeric)*100,2);
  end if;

  select coalesce(to_jsonb(p),'{}'::jsonb) into v_policy
  from pipeline.platform_capacity_policy p where environment=p_environment;

  select cumulative_temp_bytes,observed_at
    into v_prev_temp_bytes,v_prev_observed_at
  from pipeline.platform_capacity_observations
  where environment=p_environment
  order by observed_at desc limit 1;

  if v_prev_temp_bytes is not null then
    v_temp_delta:=greatest(v_temp_bytes-v_prev_temp_bytes,0);
  end if;

  if coalesce((v_policy->>'database_critical_bytes')::bigint,9223372036854775807) <= v_db
     or coalesce((v_policy->>'integrity_critical_count')::integer,2147483647) <= v_integrity_count
     or coalesce((v_evidence_policy->>'critical_pct')::numeric,101) <= coalesce(v_evidence_pct,0)
  then v_severity:='critical';
  elsif coalesce((v_policy->>'database_high_bytes')::bigint,9223372036854775807) <= v_db
     or coalesce((v_policy->>'integrity_high_count')::integer,2147483647) <= v_integrity_count
     or coalesce((v_evidence_policy->>'high_pct')::numeric,101) <= coalesce(v_evidence_pct,0)
  then v_severity:='high';
  elsif coalesce((v_policy->>'database_warn_bytes')::bigint,9223372036854775807) <= v_db
     or coalesce((v_policy->>'integrity_warn_count')::integer,2147483647) <= v_integrity_count
     or coalesce((v_evidence_policy->>'warn_pct')::numeric,101) <= coalesce(v_evidence_pct,0)
  then v_severity:='warning';
  end if;

  return jsonb_build_object(
    'environment',p_environment,
    'observed_at',now(),
    'severity',v_severity,
    'database_bytes',v_db,
    'cumulative_temp_bytes',v_temp_bytes,
    'cumulative_temp_files',v_temp_files,
    'temp_bytes_since_previous_observation',v_temp_delta,
    'previous_observation_at',v_prev_observed_at,
    'evidence_object_count',v_obj_count,
    'evidence_object_bytes',v_obj_bytes,
    'evidence_planning_capacity_pct',v_evidence_pct,
    'evidence_artifact_count',v_evidence_count,
    'unlinked_storage_object_count_raw',v_unlinked_raw,
    'duplicate_unlinked_storage_object_count',v_duplicate_unlinked,
    'reconciled_historical_orphan_count',v_reconciled_orphans,
    'orphan_object_count',v_orphans,
    'direct_virtual_evidence_reference_count',v_direct_virtual_refs,
    'reconciled_legacy_reference_count',v_reconciled_legacy_refs,
    'virtual_evidence_reference_count',v_virtual_refs,
    'missing_storage_object_count_raw',v_failed_raw,
    'missing_storage_object_count',v_failed,
    'failed_upload_count',v_failed,
    'integrity_count_for_severity',v_integrity_count,
    'integrity_classification',jsonb_build_object(
      'raw_unlinked_storage_objects',v_unlinked_raw,
      'proven_duplicate_unlinked_objects',v_duplicate_unlinked,
      'reconciled_historical_orphans',v_reconciled_orphans,
      'unresolved_orphan_objects',v_orphans,
      'direct_virtual_or_external_evidence_references',v_direct_virtual_refs,
      'reconciled_legacy_references',v_reconciled_legacy_refs,
      'virtual_or_external_evidence_references',v_virtual_refs,
      'raw_missing_bucket_objects',v_failed_raw,
      'missing_bucket_objects',v_failed,
      'duplicate_rule','same ETag + size as an Evidence-linked object',
      'reconciliation_rule','explicit private CF-governed provenance ledger'
    ),
    'largest_relations',v_largest,
    'evidence_capacity_policy',v_evidence_policy,
    'platform_capacity_policy',v_policy,
    'backup_status','platform_api_required',
    'pitr_status','platform_api_required'
  );
end $_$;


ALTER FUNCTION "security"."platform_capacity_snapshot_internal"("p_environment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_capacity_snapshot_read"("p_environment" "text" DEFAULT 'pilot'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare v_rank integer;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
  return security.platform_capacity_snapshot_internal(p_environment);
end $$;


ALTER FUNCTION "security"."platform_capacity_snapshot_read"("p_environment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_cron_field_values"("p_field" "text", "p_lo" integer, "p_hi" integer) RETURNS integer[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare part text; rng text; step int; a int; b int; acc int[]:='{}'; i int;
begin
  foreach part in array string_to_array(p_field,',') loop
    step:=1; rng:=part;
    if position('/' in part)>0 then rng:=split_part(part,'/',1); step:=split_part(part,'/',2)::int; end if;
    if rng='*' then a:=p_lo; b:=p_hi;
    elsif position('-' in rng)>0 then a:=split_part(rng,'-',1)::int; b:=split_part(rng,'-',2)::int;
    else a:=rng::int; b:=case when position('/' in part)>0 then p_hi else a end; end if;
    if step<1 then return null; end if;
    i:=a; while i<=b loop acc:=acc||i; i:=i+step; end loop;
  end loop;
  return (select array_agg(distinct x order by x) from unnest(acc) x);
end $$;


ALTER FUNCTION "security"."platform_cron_field_values"("p_field" "text", "p_lo" integer, "p_hi" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_cron_interval_seconds"("p_schedule" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $_$
declare f text[]; mins int[]; hrs int[]; days int[]; t int[];
begin
  if p_schedule ~* '^\s*\d+\s+seconds?\s*$' then return substring(p_schedule from '\d+')::int; end if;
  f:=regexp_split_to_array(trim(p_schedule),'\s+');
  if cardinality(f)<>5 or f[4]<>'*' then return null; end if;
  if f[3]<>'*' then return 31*86400; end if;
  if f[5]<>'*' then
    days:=security.platform_cron_field_values(f[5],0,7);
    days:=(select array_agg(distinct (d%7)) from unnest(days) d);
    return security.platform_cyclic_max_gap(days,7)*86400;
  end if;
  mins:=security.platform_cron_field_values(f[1],0,59); hrs:=security.platform_cron_field_values(f[2],0,23);
  select array_agg(h*60+m) into t from unnest(hrs) h cross join unnest(mins) m;
  return security.platform_cyclic_max_gap(t,1440)*60;
exception when others then return null;
end $_$;


ALTER FUNCTION "security"."platform_cron_interval_seconds"("p_schedule" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_cyclic_max_gap"("p_values" integer[], "p_mod" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select max(nx-x) from (select x, coalesce(lead(x) over (order by x), min(x) over ()+p_mod) nx from unnest(p_values) x) z
$$;


ALTER FUNCTION "security"."platform_cyclic_max_gap"("p_values" integer[], "p_mod" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_check_v1"("p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security', 'public', 'catalogue', 'scholarship'
    SET "statement_timeout" TO '60s'
    AS $_$
declare
  v_t0 timestamptz:=clock_timestamp(); v_t timestamptz;
  v_found jsonb:='[]'::jsonb; v_ok text[]:='{}'; v_ms jsonb:='{}'::jsonb; v_det jsonb:='{}'::jsonb;
  v_slow_used boolean:=false; r record; v_n bigint; v_n2 bigint; v_n3 bigint; v_x jsonb; v_q jsonb; v_prev jsonb;
  v_ts timestamptz; v_ts2 timestamptz; v_num numeric; v_num2 numeric; v_txt text; v_args text; v_arr text[]; v_bool boolean;
  v_counts jsonb; v_jobs int:=0; v_fail int:=0; v_stale int:=0;
begin
  -- 4.1 scheduled jobs: failures in the last hour; active jobs not run in more than 3x their interval
  if security.platform_health_due_v1('cron',p_force) then
    v_t:=clock_timestamp();
    begin
      for r in
        with agg as (
          select d.jobid, max(d.start_time) last_run, min(d.start_time) first_run,
                 count(*) filter (where d.status='failed' and d.start_time>=now()-interval '1 hour') fails_1h,
                 count(*) filter (where d.start_time>=now()-interval '1 hour') runs_1h,
                 (array_agg(left(d.return_message,200) order by d.start_time desc) filter (where d.status='failed'))[1] last_error
            from cron.job_run_details d group by d.jobid)
        select j.jobid, j.jobname, j.schedule, security.platform_cron_interval_seconds(j.schedule) ival,
               a.last_run, coalesce(a.fails_1h,0) fails_1h, coalesce(a.runs_1h,0) runs_1h, a.last_error,
               (select min(a2.first_run) from agg a2 where a2.jobid>j.jobid) created_before
          from cron.job j left join agg a on a.jobid=j.jobid where j.active
      loop
        v_jobs:=v_jobs+1;
        if r.fails_1h>0 then
          v_fail:=v_fail+1;
          select bool_and(x.status='failed') into v_bool from (select d.status from cron.job_run_details d where d.jobid=r.jobid order by d.start_time desc limit 3) x;
          v_found:=v_found||security.platform_health_issue_v1('cron:failed:'||r.jobname, case when v_bool and r.runs_1h>=3 then 'critical' else 'warning' end,
            'scheduled jobs', 'Scheduled job "'||r.jobname||'" failed '||r.fails_1h||' of '||r.runs_1h||' run(s) in the last hour',
            jsonb_build_object('job',r.jobname,'schedule',r.schedule,'failures_1h',r.fails_1h,'runs_1h',r.runs_1h,'last_error',r.last_error,'last_three_failed',coalesce(v_bool,false)));
        end if;
        v_ts:=coalesce(r.last_run, r.created_before);
        if r.ival is not null and v_ts is not null and now()-v_ts > make_interval(secs=>3*r.ival) + interval '2 minutes' then
          v_stale:=v_stale+1;
          v_found:=v_found||security.platform_health_issue_v1('cron:stale:'||r.jobname,
            case when now()-v_ts > greatest(make_interval(secs=>12*r.ival), interval '2 hours') and r.ival<=3600 then 'critical' else 'warning' end,
            'scheduled jobs', 'Scheduled job "'||r.jobname||'" has not run '||case when r.last_run is null then 'since it was scheduled' else 'since '||to_char(r.last_run at time zone 'UTC','DD Mon HH24:MI')||' UTC' end,
            jsonb_build_object('job',r.jobname,'schedule',r.schedule,'expected_every_minutes',round(r.ival/60.0,1),'last_run',r.last_run));
        end if;
      end loop;
      v_det:=v_det||jsonb_build_object('cron',jsonb_build_object('active_jobs',v_jobs,'jobs_failing',v_fail,'jobs_overdue',v_stale));
      v_ok:=array_append(v_ok,'cron');
    exception when others then
      v_ok:=array_append(v_ok,'cron');
      v_found:=v_found||security.platform_health_issue_v1('cron:check_error','warning','scheduled jobs','The scheduled-job health check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('cron',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.2 Edge function calls made through pg_net over the last 30 minutes, grouped by function
  if security.platform_health_due_v1('edge_calls',p_force) then
    v_t:=clock_timestamp(); v_n:=0; v_n2:=0; v_q:='[]'::jsonb;
    begin
      for r in
        with resp as (
          select rr.id, rr.status_code, rr.timed_out, rr.error_msg, rr.content,
                 coalesce(c.function_name, substring(rr.content from '"workerVersion"\s*:\s*"([a-z0-9-]+?)-v[0-9]'), 'unattributed') fn,
                 (coalesce(rr.status_code,0)>=400 or rr.timed_out is true or rr.error_msg is not null) failed
            from net._http_response rr left join pipeline.platform_edge_calls c on c.id=rr.id
           where rr.created>=now()-interval '30 minutes')
        select fn, count(*) total, count(*) filter (where failed) failures, count(*) filter (where timed_out) timeouts,
               count(*) filter (where status_code=404 and (content ilike '%NOT_FOUND%' or content ilike '%function was not found%')) not_deployed,
               array_agg(distinct coalesce(status_code::text, case when timed_out then 'timeout' else 'error' end)) filter (where failed) codes,
               (array_agg(left(coalesce(content,error_msg),200) order by id desc) filter (where failed))[1] sample
          from resp group by fn order by count(*) filter (where failed) desc
      loop
        v_n:=v_n+r.total; v_n2:=v_n2+r.failures;
        if jsonb_array_length(v_q)<15 then v_q:=v_q||jsonb_build_object('function',r.fn,'calls',r.total,'failures',r.failures,'timeouts',r.timeouts); end if;
        if r.not_deployed>0 then
          v_found:=v_found||security.platform_health_issue_v1('edge_calls:not_deployed:'||r.fn,'critical','edge functions',
            'Edge function "'||r.fn||'" is called but not deployed (404, '||r.not_deployed||' call(s) in 30 minutes)',
            jsonb_build_object('function',r.fn,'calls',r.total,'not_found',r.not_deployed,'sample',r.sample));
        elsif r.failures>=2 then
          v_found:=v_found||security.platform_health_issue_v1('edge_calls:failing:'||r.fn,
            case when r.failures>=3 and r.failures=r.total then 'critical' else 'warning' end,'edge functions',
            case when r.fn='unattributed' then 'Edge function calls' else 'Edge function "'||r.fn||'"' end||': '||r.failures||' of '||r.total||' call(s) failed in the last 30 minutes'
              ||case when r.timeouts>0 then ' ('||r.timeouts||' timed out)' else '' end,
            jsonb_build_object('function',r.fn,'calls',r.total,'failures',r.failures,'timeouts',r.timeouts,'codes',to_jsonb(r.codes),'sample',r.sample));
        end if;
      end loop;
      select count(*) into v_n3 from net.http_request_queue;
      if v_n3>100 then
        v_found:=v_found||security.platform_health_issue_v1('edge_calls:queue_backlog', case when v_n3>500 then 'critical' else 'warning' end,'edge functions',
          v_n3||' outbound calls are waiting in the pg_net queue',jsonb_build_object('queued',v_n3));
      end if;
      v_det:=v_det||jsonb_build_object('edge_calls',jsonb_build_object('window_minutes',30,'calls',v_n,'failures',v_n2,'queued',v_n3,'by_function',v_q));
      v_ok:=array_append(v_ok,'edge_calls');
    exception when others then
      v_ok:=array_append(v_ok,'edge_calls');
      v_found:=v_found||security.platform_health_issue_v1('edge_calls:check_error','warning','edge functions','The Edge function call check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('edge_calls',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.3 Edge functions deployed vs expected: not queryable from the database (skipped; recently invoked list only)
  if security.platform_health_due_v1('edge_deployed',p_force) then
    v_t:=clock_timestamp();
    begin
      v_det:=v_det||jsonb_build_object('edge_deployed',jsonb_build_object(
        'note','Skipped: the live Edge function list cannot be read from the database. Compare supabase/functions in git with the live list (Supabase list_edge_functions). A call to a missing function shows here as a 404 under Edge function calls.',
        'invoked_last_24h',coalesce((select jsonb_agg(distinct function_name order by function_name) from pipeline.platform_edge_calls where created_at>=now()-interval '24 hours'),'[]'::jsonb)));
      v_ok:=array_append(v_ok,'edge_deployed');
    exception when others then null;
    end;
    v_ms:=v_ms||jsonb_build_object('edge_deployed',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.4 coverage sweep queues
  if security.platform_health_due_v1('coverage_queues',p_force) then
    v_t:=clock_timestamp(); v_q:='[]'::jsonb;
    begin
      select max(read_at) into v_ts from pipeline.coverage_course_pages;
      v_q:=v_q||security.platform_health_stall_v1('coverage_queues:read','coverage sweep','Coverage page reading','coverage-read',v_ts,
        $q$select count(*) from pipeline.coverage_course_pages p where p.status in ('bound','ambiguous') and coalesce(p.next_read_at,now())<=now() and p.read_attempts<3$q$);
      select max(updated_at) into v_ts from pipeline.coverage_provider_discovery;
      v_q:=v_q||security.platform_health_stall_v1('coverage_queues:discover','coverage sweep','Coverage provider discovery','coverage-discover',v_ts,
        $q$select count(*) from pipeline.coverage_provider_discovery d where (d.status='pending' or (d.status in ('mapped','failed') and d.next_due_at<=now())) and d.attempts<3$q$);
      -- re-extract has no timestamp: progress means the number of pages on an older extractor went down
      select c.candidates->>'extractor' into v_txt from pipeline.coverage_course_pages c where c.read_status='read' and c.read_at is not null order by c.read_at desc limit 1;
      select count(*) into v_n from pipeline.coverage_course_pages cp
       where cp.read_status='read' and cp.identity_basis is not null and cp.evidence_id is not null and coalesce(cp.candidates->>'extractor','')<>coalesce(v_txt,'');
      select c.detail->'reextract' into v_prev from pipeline.platform_health_checks c where c.key='coverage_queues';
      v_ts:=case when v_n=0 or v_n<coalesce((v_prev->>'pending')::bigint, v_n+1) then now() else coalesce((v_prev->>'progress_at')::timestamptz, now()) end;
      v_q:=v_q||(security.platform_health_stall_v1('coverage_queues:reextract','coverage sweep','Coverage re-extraction','coverage-reextract',v_ts,'select '||v_n)
                 ||jsonb_build_object('pending',v_n,'progress_at',v_ts,'extractor',v_txt));
      -- tuition hand-off to Layer 3 (only runs while a qualified tuition profile exists)
      select max(l3_handoff_at) into v_ts from pipeline.coverage_course_pages;
      v_bool:=exists(select 1 from pipeline.layer3_model_profiles where 'provider_current_tuition_validation'=any(allowed_task_classes) and enabled and not paused and coalesce((quality_benchmark->>'pass')::boolean,false));
      v_x:=security.platform_health_stall_v1('coverage_queues:tuition_handoff','coverage sweep','Tuition hand-off to Layer 3','coverage-tuition-handoff',v_ts,
        $q$select count(*) from pipeline.coverage_course_pages p join catalogue.courses co on co.id=p.course_id and co.lifecycle_status='active'
            where p.read_status='read' and p.identity_basis='cricos_code' and p.l3_work_item_id is null
              and (p.l3_handoff_at is null or p.l3_handoff_at<now()-interval '1 day')
              and security.coverage_tuition_target_v1(p.candidates->'fee') is not null
              and not exists (select 1 from catalogue.course_fees f where f.course_id=p.course_id and f.fee_type='provider_current_tuition' and f.status='active')$q$);
      if not v_bool and v_x ? 'issue' then
        v_x:=jsonb_set(v_x,'{issue}',(v_x->'issue')||jsonb_build_object('severity','info',
          'title','Tuition hand-off is paused: no qualified, enabled tuition model profile ('||(v_x->>'pending')||' pages waiting)'));
      end if;
      v_q:=v_q||(v_x||jsonb_build_object('qualified_profile',v_bool));
      select coalesce(jsonb_agg(e->'issue'),'[]'::jsonb) into v_x from jsonb_array_elements(v_q) e where e ? 'issue';
      v_found:=v_found||v_x;
      v_det:=v_det||jsonb_build_object('coverage_queues',jsonb_build_object('queues',(select jsonb_agg(e-'issue') from jsonb_array_elements(v_q) e),
        'reextract',(select e-'issue'-'queue'-'status' from jsonb_array_elements(v_q) e where e->>'queue'='coverage_queues:reextract')));
      v_ok:=array_append(v_ok,'coverage_queues');
    exception when others then
      v_ok:=array_append(v_ok,'coverage_queues');
      v_found:=v_found||security.platform_health_issue_v1('coverage_queues:check_error','warning','coverage sweep','The coverage queue check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('coverage_queues',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.5 scholarship queues
  if security.platform_health_due_v1('scholarship_queues',p_force) then
    v_t:=clock_timestamp(); v_q:='[]'::jsonb;
    begin
      select max(read_at) into v_ts from pipeline.scholarship_pages;
      v_q:=v_q||security.platform_health_stall_v1('scholarship_queues:read','scholarships','Scholarship page reading','scholarship-read',v_ts,
        $q$select count(*) from pipeline.scholarship_pages p join scholarship.scholarships s on s.id=p.scholarship_id and s.lifecycle_status='active'
            where p.next_read_at<=now() and p.attempts<5$q$);
      select max(read_at) into v_ts from pipeline.scholarship_page_candidates;
      v_q:=v_q||security.platform_health_stall_v1('scholarship_queues:candidates','scholarships','Scholarship candidate page reading','scholarship-discover',v_ts,
        $q$select count(*) from pipeline.scholarship_page_candidates c join pipeline.scholarship_discovery_providers d on d.provider_id=c.provider_id and d.priority in (0,1,3,4)
            where c.matched_scholarship_id is null and c.admit_status is null and c.next_read_at<=now() and c.attempts<3$q$);
      select max(updated_at) into v_ts from pipeline.scholarship_discovery_providers;
      v_q:=v_q||security.platform_health_stall_v1('scholarship_queues:discover','scholarships','Scholarship provider discovery','scholarship-discover',v_ts,
        $q$select count(*) from pipeline.scholarship_discovery_providers d where d.status='pending' and d.attempts<3$q$);
      select coalesce(jsonb_agg(e->'issue'),'[]'::jsonb) into v_x from jsonb_array_elements(v_q) e where e ? 'issue';
      v_found:=v_found||v_x;
      v_det:=v_det||jsonb_build_object('scholarship_queues',jsonb_build_object('queues',(select jsonb_agg(e-'issue') from jsonb_array_elements(v_q) e)));
      v_ok:=array_append(v_ok,'scholarship_queues');
    exception when others then
      v_ok:=array_append(v_ok,'scholarship_queues');
      v_found:=v_found||security.platform_health_issue_v1('scholarship_queues:check_error','warning','scholarships','The scholarship queue check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('scholarship_queues',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.6 Layer 2 run items, Layer 3 work items, Layer 4 review backlog
  if security.platform_health_due_v1('layer_queues',p_force) then
    v_t:=clock_timestamp(); v_q:='[]'::jsonb;
    begin
      select count(*), min(coalesce(updated_at,created_at)) into v_n, v_ts from pipeline.layer2_run_items
       where status in ('queued','discovering','acquiring','extracting') and coalesce(updated_at,created_at)<now()-interval '2 hours';
      if v_n>0 then
        v_found:=v_found||security.platform_health_issue_v1('layer_queues:layer2_stuck','warning','Layer 3',
          v_n||' Layer 2 run item(s) have not moved for more than 2 hours',jsonb_build_object('stuck',v_n,'oldest_update',v_ts));
      end if;
      v_q:=v_q||jsonb_build_object('queue','layer2_run_items','stuck_over_2h',v_n);
      select count(*), min(coalesce(reserved_at,updated_at)), (array_agg(id order by coalesce(reserved_at,updated_at)))[1:5]::text
        into v_n, v_ts, v_txt from pipeline.layer3_work_items where status in ('reserved','interpreting') and coalesce(reserved_at,updated_at)<now()-interval '1 hour';
      if v_n>0 then
        v_found:=v_found||security.platform_health_issue_v1('layer_queues:layer3_stuck','warning','Layer 3',
          v_n||' Layer 3 work item(s) stuck in reserved/interpreting for more than an hour',jsonb_build_object('stuck',v_n,'since',v_ts,'ids',v_txt));
      end if;
      select max(completed_at) into v_ts from pipeline.layer3_work_items;
      v_x:=security.platform_health_stall_v1('layer_queues:layer3_dispatch','Layer 3','Layer 3 work dispatch','layer3-tuition-dispatch',v_ts,
        $q$select count(*) from pipeline.layer3_work_items w where w.status='pending' and coalesce(w.available_at,now())<=now()$q$);
      if v_x ? 'issue' then v_found:=v_found||jsonb_build_array(v_x->'issue'); end if;
      v_q:=v_q||(v_x-'issue')||jsonb_build_object('queue','layer3_stuck_over_1h','count',v_n);
      select count(*) filter (where status='pending'), count(*) filter (where created_at>=now()-interval '24 hours'),
             count(*) filter (where decided_at>=now()-interval '24 hours'), count(*) filter (where decided_at>=now()-interval '48 hours')
        into v_n, v_n2, v_n3, v_num from pipeline.layer4_review_items;
      if v_n2-v_n3>300 and v_num=0 then
        v_found:=v_found||security.platform_health_issue_v1('layer_queues:layer4_backlog','warning','Layer 3',
          'Layer 4 review backlog grew by '||(v_n2-v_n3)||' in 24 hours with no decisions in 48 hours ('||v_n||' waiting)',
          jsonb_build_object('pending',v_n,'created_24h',v_n2,'decided_24h',v_n3,'decided_48h',v_num));
      elsif v_n2-v_n3>100 then
        v_found:=v_found||security.platform_health_issue_v1('layer_queues:layer4_backlog','info','Layer 3',
          'Layer 4 review backlog grew by '||(v_n2-v_n3)||' in 24 hours ('||v_n||' waiting)',
          jsonb_build_object('pending',v_n,'created_24h',v_n2,'decided_24h',v_n3,'decided_48h',v_num));
      end if;
      v_q:=v_q||jsonb_build_object('queue','layer4_review','pending',v_n,'created_24h',v_n2,'decided_24h',v_n3);
      v_det:=v_det||jsonb_build_object('layer_queues',jsonb_build_object('queues',v_q));
      v_ok:=array_append(v_ok,'layer_queues');
    exception when others then
      v_ok:=array_append(v_ok,'layer_queues');
      v_found:=v_found||security.platform_health_issue_v1('layer_queues:check_error','warning','Layer 3','The Layer 2 to 4 queue check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('layer_queues',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.7 consumer API snapshot (slow, hourly)
  if (p_force or not v_slow_used) and security.platform_health_due_v1('consumer_snapshot',p_force) then
    v_t:=clock_timestamp(); v_slow_used:=true;
    begin
      v_x:=security.consumer_api_snapshot_v1();
      select coalesce(array_agg(e.k order by e.k),'{}'), max((e.v->>'ms')::numeric) into v_arr, v_num
        from jsonb_each(coalesce(v_x,'{}'::jsonb)) e(k,v) where jsonb_typeof(e.v)='object' and e.v ? 'ok' and (e.v->>'ok')::boolean is not true;
      select max((e.v->>'ms')::numeric) into v_num from jsonb_each(coalesce(v_x,'{}'::jsonb)) e(k,v) where jsonb_typeof(e.v)='object' and e.v ? 'ms';
      if v_x is null then
        v_found:=v_found||security.platform_health_issue_v1('consumer_snapshot:empty','critical','search/API','The consumer API snapshot returned nothing','{}'::jsonb);
      elsif cardinality(v_arr)>0 then
        v_found:=v_found||security.platform_health_issue_v1('consumer_snapshot:failing','critical','search/API',
          'Consumer API: '||cardinality(v_arr)||' probe(s) failing ('||array_to_string(v_arr[1:5],', ')||')',jsonb_build_object('failing',to_jsonb(v_arr)));
      end if;
      v_det:=v_det||jsonb_build_object('consumer_snapshot',jsonb_build_object('probes',(select count(*) from jsonb_each(coalesce(v_x,'{}'::jsonb)) e(k,v) where jsonb_typeof(e.v)='object' and e.v ? 'ok'),
        'failing',to_jsonb(v_arr),'slowest_probe_ms',v_num,'run_ms',round(extract(epoch from clock_timestamp()-v_t)*1000)));
      v_ok:=array_append(v_ok,'consumer_snapshot');
    exception when others then
      v_ok:=array_append(v_ok,'consumer_snapshot');
      v_found:=v_found||security.platform_health_issue_v1('consumer_snapshot:check_error','critical','search/API','The consumer API snapshot failed to run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('consumer_snapshot',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.8 admission: coverage-admit applied nothing in an hour while candidates exist (the plan is evaluated at most hourly)
  if security.platform_health_due_v1('admission',p_force) then
    v_t:=clock_timestamp();
    begin
      select max(captured_at) into v_ts from pipeline.consumer_api_baselines where label like 'after coverage admission batch%';
      select c.detail into v_prev from pipeline.platform_health_checks c where c.key='admission';
      if v_ts>=now()-interval '1 hour' then
        v_det:=v_det||jsonb_build_object('admission',jsonb_build_object('last_batch',v_ts,'plan_checked_at',v_prev->'plan_checked_at','candidates',v_prev->'candidates'));
        v_ok:=array_append(v_ok,'admission');
      elsif p_force or (not v_slow_used and coalesce((v_prev->>'plan_checked_at')::timestamptz,'-infinity'::timestamptz)<now()-interval '55 minutes') then
        v_slow_used:=true;
        -- follow the live defaults of coverage_admission_apply_v1 (what the coverage-admit job runs)
        v_args:=pg_get_function_arguments('security.coverage_admission_apply_v1'::regproc);
        v_txt:=substring(v_args from 'p_extractor text DEFAULT ''([^'']+)''');
        v_arr:=array(select m[1] from regexp_matches(coalesce(substring(v_args from 'p_attributes text\[\] DEFAULT ARRAY\[(.*)\]'),''),'''([^'']+)''','g') m);
        if cardinality(v_arr)=0 then v_arr:=array['official_url','english']; end if;
        execute 'select count(*) from security.coverage_admission_plan_v1($1) where action=''write'' and attribute=any($2)' into v_n using coalesce(v_txt,'coverage-sweep-v0.5.4'), v_arr;
        if v_n>0 then
          v_found:=v_found||security.platform_health_issue_v1('admission:stalled',
            case when v_ts is null or v_ts<now()-interval '3 hours' then 'critical' else 'warning' end,'admission',
            'Coverage admission has applied nothing for over an hour while '||v_n||' value(s) are ready to write',
            jsonb_build_object('candidates',v_n,'last_batch',v_ts,'extractor',v_txt,'attributes',to_jsonb(v_arr)));
        end if;
        v_det:=v_det||jsonb_build_object('admission',jsonb_build_object('last_batch',v_ts,'plan_checked_at',now(),'candidates',v_n,'extractor',v_txt));
        v_ok:=array_append(v_ok,'admission');
      end if;
    exception when others then
      v_ok:=array_append(v_ok,'admission');
      v_found:=v_found||security.platform_health_issue_v1('admission:check_error','warning','admission','The admission check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('admission',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.9 budgets
  if security.platform_health_due_v1('budgets',p_force) then
    v_t:=clock_timestamp();
    begin
      select security.layer2_provider_budget_status(p.id,1) into v_x from pipeline.layer2_acquisition_providers p where p.provider_key='firecrawl' and p.enabled;
      if v_x is null then
        v_found:=v_found||security.platform_health_issue_v1('budgets:firecrawl_disabled','warning','budgets','Firecrawl is not enabled: coverage site maps and scholarship searches cannot use it','{}'::jsonb);
      else
        v_num:=coalesce((v_x->>'remaining_units')::numeric,0)-coalesce((v_x->>'stop_at_remaining_units')::numeric,0);
        if (v_x->>'allowed')::boolean is false or v_num<=0 then
          v_found:=v_found||security.platform_health_issue_v1('budgets:firecrawl','critical','budgets',
            'Firecrawl has reached its reserve: paid page reads and site maps have stopped until '||to_char((v_x->>'period_end')::timestamptz,'DD Mon'),
            v_x-'provider_id');
        elsif v_num<0.1*coalesce((v_x->>'limit_units')::numeric,0) then
          v_found:=v_found||security.platform_health_issue_v1('budgets:firecrawl','warning','budgets',
            'Firecrawl is close to its reserve: '||v_num||' credits left above the reserve this period',v_x-'provider_id');
        end if;
      end if;
      -- scholarship work has its own 3,000-credit Firecrawl allowance (coverage-sweep SCH_FC_CAP)
      select coalesce(sum(units),0) into v_num2 from pipeline.coverage_vendor_usage where purpose in ('sch_map','sch_search','sch_scrape');
      if v_num2>=3000 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:scholarship_firecrawl','warning','budgets',
          'Scholarship Firecrawl allowance is used up ('||v_num2||' of 3,000 credits): scholarship discovery falls back to direct reads only',jsonb_build_object('used',v_num2,'cap',3000));
      elsif v_num2>=2700 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:scholarship_firecrawl','info','budgets',
          'Scholarship Firecrawl allowance is 90% used ('||v_num2||' of 3,000 credits)',jsonb_build_object('used',v_num2,'cap',3000));
      end if;
      -- OpenRouter: recorded spend over 24 hours against the US$5 daily ceiling (delivery plan v1.1)
      select coalesce((select sum(estimated_cost_usd) from pipeline.layer3_interpretations where created_at>=now()-interval '24 hours'),0)
           + coalesce((select sum(estimated_cost_usd) from pipeline.layer3_quality_benchmark_runs where created_at>=now()-interval '24 hours'),0)
           + coalesce((select sum(cost_usd) from pipeline.scholarship_ai_runs where created_at>=now()-interval '24 hours'),0) into v_num;
      if v_num>=14 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_daily','critical','budgets',
          'OpenRouter spend in the last 24 hours is US$'||round(v_num,2)||', at or over the US$14 combined daily ceiling',jsonb_build_object('spend_24h_usd',round(v_num,4),'ceiling_usd',14));
      elsif v_num>=11.2 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_daily','warning','budgets',
          'OpenRouter spend in the last 24 hours is US$'||round(v_num,2)||' (80% of the US$14 combined daily ceiling)',jsonb_build_object('spend_24h_usd',round(v_num,4),'ceiling_usd',14));
      end if;
      select count(*) into v_num from pipeline.layer3_interpretations i
       where i.created_at>=now()-interval '30 minutes' and i.validator_result::text ~ 'provider_(401|402|403|429)';
      if v_num>=5 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_refusing','critical','Layer 3',
          'OpenRouter is refusing Layer 3 calls ('||v_num||' in 30 minutes): '||coalesce((select left(i.validator_result->'errors'->>0,160)
             from pipeline.layer3_interpretations i where i.created_at>=now()-interval '30 minutes' and i.validator_result::text ~ 'provider_(401|402|403|429)' order by i.created_at desc limit 1),'see the Layer 3 work queue')||'. Check the OpenRouter key and billing.',
          jsonb_build_object('refusals_30m',v_num));
      end if;
      select o.remaining_usd into v_num from pipeline.layer3_openrouter_observations o where o.kind='credits' and o.remaining_usd is not null order by o.observed_at desc limit 1;
      if v_num is not null and v_num<=5 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_credit','critical','budgets',
          'OpenRouter credit is US$'||round(v_num,2)||': at the US$5 floor, so automated Layer 3 admission has stopped. Top up the credit.',jsonb_build_object('remaining_usd',round(v_num,2),'floor_usd',5));
      elsif v_num is not null and v_num<10 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_credit','warning','budgets',
          'OpenRouter credit is US$'||round(v_num,2)||': automated Layer 3 admission stops at US$5. Top up soon.',jsonb_build_object('remaining_usd',round(v_num,2),'floor_usd',5));
      end if;
      for r in select p.code, count(*) n, max(i.estimated_cost_usd) mx, p.cost_ceiling_usd ceil
                 from pipeline.layer3_interpretations i join pipeline.layer3_model_profiles p on p.id=i.profile_id
                where i.created_at>=now()-interval '24 hours' and coalesce(i.external_call_count,0)>0 and p.cost_ceiling_usd is not null and i.estimated_cost_usd>p.cost_ceiling_usd
                group by p.code, p.cost_ceiling_usd loop
        v_found:=v_found||security.platform_health_issue_v1('budgets:call_ceiling:'||r.code,'warning','budgets',
          r.n||' Layer 3 call(s) on "'||r.code||'" cost more than its US$'||r.ceil||' per-call ceiling in 24 hours',jsonb_build_object('profile',r.code,'calls',r.n,'max_cost_usd',r.mx,'ceiling_usd',r.ceil));
      end loop;
      for r in select p.code, count(*) n, max(b.estimated_cost_usd) mx, p.cost_ceiling_usd ceil
                 from pipeline.layer3_quality_benchmark_runs b join pipeline.layer3_model_profiles p on p.id=b.profile_id
                where b.created_at>=now()-interval '24 hours' and p.cost_ceiling_usd is not null and b.estimated_cost_usd>p.cost_ceiling_usd*greatest(coalesce(b.external_call_count,1),1)
                group by p.code, p.cost_ceiling_usd loop
        v_found:=v_found||security.platform_health_issue_v1('budgets:benchmark_ceiling:'||r.code,'warning','budgets',
          r.n||' benchmark run(s) on "'||r.code||'" cost more than the per-call ceiling allows in 24 hours',jsonb_build_object('profile',r.code,'runs',r.n,'max_cost_usd',r.mx,'ceiling_usd_per_call',r.ceil));
      end loop;
      for r in select s.country_code, s.daily_budget_usd, coalesce(sum(x.cost_usd),0) spent from pipeline.scholarship_ai_settings s
                 left join pipeline.scholarship_ai_runs x on x.country_code=s.country_code and x.created_at>=now()-interval '24 hours'
                group by s.country_code, s.daily_budget_usd having coalesce(sum(x.cost_usd),0)>s.daily_budget_usd loop
        v_found:=v_found||security.platform_health_issue_v1('budgets:scholarship_ai:'||r.country_code,'warning','budgets',
          'Scholarship AI spend for '||r.country_code||' is US$'||round(r.spent,2)||' in 24 hours, over its US$'||r.daily_budget_usd||' daily budget',jsonb_build_object('spent_usd',r.spent,'budget_usd',r.daily_budget_usd));
      end loop;
      v_det:=v_det||jsonb_build_object('budgets',jsonb_build_object(
        'firecrawl',case when v_x is null then null else jsonb_build_object('used',v_x->'used_units','limit',v_x->'limit_units','remaining',v_x->'remaining_units','reserve',v_x->'stop_at_remaining_units','period_end',v_x->'period_end') end,
        'scholarship_firecrawl_used',v_num2,'scholarship_firecrawl_cap',3000,'openrouter_spend_24h_usd',round(v_num,4),'openrouter_daily_ceiling_usd',5));
      v_ok:=array_append(v_ok,'budgets');
    exception when others then
      v_ok:=array_append(v_ok,'budgets');
      v_found:=v_found||security.platform_health_issue_v1('budgets:check_error','warning','budgets','The budget check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('budgets',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.10 database size and connections
  if security.platform_health_due_v1('db_capacity',p_force) then
    v_t:=clock_timestamp();
    begin
      v_n:=pg_database_size(current_database());
      select p.database_warn_bytes, p.database_high_bytes, p.database_critical_bytes into v_n2, v_n3, v_num
        from pipeline.platform_capacity_policy p order by (p.environment='production') desc, (p.environment='pilot') desc limit 1;
      if v_num is not null and v_n>=v_num then
        v_found:=v_found||security.platform_health_issue_v1('db_capacity:size','critical','storage/DB','Database is '||pg_size_pretty(v_n)||', over the critical level of '||pg_size_pretty(v_num::bigint),jsonb_build_object('bytes',v_n,'warn',v_n2,'high',v_n3,'critical',v_num));
      elsif v_n3 is not null and v_n>=v_n3 then
        v_found:=v_found||security.platform_health_issue_v1('db_capacity:size','warning','storage/DB','Database is '||pg_size_pretty(v_n)||', over the high level of '||pg_size_pretty(v_n3),jsonb_build_object('bytes',v_n,'warn',v_n2,'high',v_n3,'critical',v_num));
      elsif v_n2 is not null and v_n>=v_n2 then
        v_found:=v_found||security.platform_health_issue_v1('db_capacity:size','info','storage/DB','Database is '||pg_size_pretty(v_n)||', over the watch level of '||pg_size_pretty(v_n2),jsonb_build_object('bytes',v_n,'warn',v_n2,'high',v_n3,'critical',v_num));
      end if;
      select count(*), count(*) filter (where state='active') into v_n2, v_n3 from pg_stat_activity where backend_type='client backend';
      select coalesce(max_connections, current_setting('max_connections')::int) into v_num2 from pipeline.platform_compute_profile where id=1;
      v_num2:=coalesce(v_num2, current_setting('max_connections')::numeric);
      if v_n2>=0.9*v_num2 then
        v_found:=v_found||security.platform_health_issue_v1('db_capacity:connections','critical','storage/DB',v_n2||' of '||v_num2||' database connections in use',jsonb_build_object('connections',v_n2,'active',v_n3,'max',v_num2));
      elsif v_n2>=0.75*v_num2 then
        v_found:=v_found||security.platform_health_issue_v1('db_capacity:connections','warning','storage/DB',v_n2||' of '||v_num2||' database connections in use',jsonb_build_object('connections',v_n2,'active',v_n3,'max',v_num2));
      end if;
      v_det:=v_det||jsonb_build_object('db_capacity',jsonb_build_object('db_bytes',v_n,'db_size',pg_size_pretty(v_n),'connections',v_n2,'active_connections',v_n3,'max_connections',v_num2,
        'compute_size',(select compute_size from pipeline.platform_compute_profile where id=1)));
      v_ok:=array_append(v_ok,'db_capacity');
    exception when others then
      v_ok:=array_append(v_ok,'db_capacity');
      v_found:=v_found||security.platform_health_issue_v1('db_capacity:check_error','warning','storage/DB','The database capacity check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('db_capacity',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.11 search probe
  if security.platform_health_due_v1('search_probe',p_force) and (p_force or not ('consumer_snapshot'=any(v_ok))) then
    v_t:=clock_timestamp();
    begin
      v_x:=public.website_edge_course_search_v1('{}'::jsonb,1,5);
      v_num:=round(extract(epoch from clock_timestamp()-v_t)*1000);
      if v_x is null or not (v_x ? 'items') then
        v_found:=v_found||security.platform_health_issue_v1('search_probe:bad_response','critical','search/API','Course search returned an unexpected response',jsonb_build_object('ms',v_num,'keys',(select jsonb_agg(k) from jsonb_object_keys(coalesce(v_x,'{}'::jsonb)) k)));
      elsif v_num>3000 then
        v_found:=v_found||security.platform_health_issue_v1('search_probe:slow','warning','search/API','Course search took '||v_num||' ms (limit 3,000 ms)',jsonb_build_object('ms',v_num));
      end if;
      v_det:=v_det||jsonb_build_object('search_probe',jsonb_build_object('ms',v_num,'items',jsonb_array_length(coalesce(v_x->'items','[]'::jsonb))));
      v_ok:=array_append(v_ok,'search_probe');
    exception when others then
      v_ok:=array_append(v_ok,'search_probe');
      v_found:=v_found||security.platform_health_issue_v1('search_probe:check_error','critical','search/API','Course search failed',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('search_probe',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.12 reference bundle cache
  if security.platform_health_due_v1('reference_bundle',p_force) then
    v_t:=clock_timestamp();
    begin
      select max(built_at) into v_ts from pipeline.consumer_reference_bundle_cache;
      if v_ts is null or v_ts<now()-interval '6 hours' then
        v_found:=v_found||security.platform_health_issue_v1('reference_bundle:stale','critical','search/API',
          'Consumer reference bundle has not been rebuilt '||case when v_ts is null then 'at all' else 'since '||to_char(v_ts at time zone 'UTC','DD Mon HH24:MI')||' UTC' end,jsonb_build_object('built_at',v_ts));
      elsif v_ts<now()-interval '2 hours' then
        v_found:=v_found||security.platform_health_issue_v1('reference_bundle:stale','warning','search/API',
          'Consumer reference bundle is '||round(extract(epoch from now()-v_ts)/3600.0,1)||' hours old (rebuilt hourly)',jsonb_build_object('built_at',v_ts));
      end if;
      v_det:=v_det||jsonb_build_object('reference_bundle',jsonb_build_object('built_at',v_ts));
      v_ok:=array_append(v_ok,'reference_bundle');
    exception when others then
      v_ok:=array_append(v_ok,'reference_bundle');
      v_found:=v_found||security.platform_health_issue_v1('reference_bundle:check_error','warning','search/API','The reference bundle check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('reference_bundle',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.13 nightly scholarship publication review
  if security.platform_health_due_v1('scholarship_review',p_force) then
    v_t:=clock_timestamp();
    begin
      select j.jobid, j.active, j.schedule into r from cron.job j where j.jobname='scholarship-publication-review';
      if r.jobid is null or not r.active then
        v_found:=v_found||security.platform_health_issue_v1('scholarship_review:missing','warning','scholarships','The nightly scholarship publication review is not scheduled','{}'::jsonb);
        v_det:=v_det||jsonb_build_object('scholarship_review',jsonb_build_object('scheduled',false));
      else
        select max(d.start_time) filter (where d.status='succeeded'), max(d.start_time) into v_ts, v_ts2 from cron.job_run_details d where d.jobid=r.jobid;
        select d.status, left(d.return_message,200) into v_txt, v_args from cron.job_run_details d where d.jobid=r.jobid order by d.start_time desc limit 1;
        if v_txt='failed' then
          v_found:=v_found||security.platform_health_issue_v1('scholarship_review:failed','warning','scholarships','The last nightly scholarship publication review failed',jsonb_build_object('at',v_ts2,'error',v_args));
        end if;
        v_ts2:=coalesce(v_ts,(select min(d.start_time) from cron.job_run_details d where d.jobid>r.jobid));
        if v_ts2 is not null and v_ts2<now()-interval '26 hours' then
          v_found:=v_found||security.platform_health_issue_v1('scholarship_review:not_run','warning','scholarships',
            'The nightly scholarship publication review has not completed '||case when v_ts is null then 'since it was scheduled' else 'since '||to_char(v_ts at time zone 'UTC','DD Mon HH24:MI')||' UTC' end,
            jsonb_build_object('last_success',v_ts,'schedule',r.schedule));
        end if;
        v_det:=v_det||jsonb_build_object('scholarship_review',jsonb_build_object('scheduled',true,'schedule',r.schedule,'last_success',v_ts,'last_status',v_txt));
      end if;
      v_ok:=array_append(v_ok,'scholarship_review');
    exception when others then
      v_ok:=array_append(v_ok,'scholarship_review');
      v_found:=v_found||security.platform_health_issue_v1('scholarship_review:check_error','warning','scholarships','The scholarship review check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('scholarship_review',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 5. record issues (dedup on check_key), auto-resolve what cleared, store check status
  for r in select distinct on (x.check_key) x.check_key, x.severity, x.area, x.title, x.detail
             from jsonb_to_recordset(v_found) x(check_key text, severity text, area text, title text, detail jsonb)
            order by x.check_key, case x.severity when 'critical' then 1 when 'warning' then 2 else 3 end loop
    insert into pipeline.platform_issues as i (check_key,severity,area,title,detail)
    values (r.check_key, r.severity, r.area, left(r.title,300), coalesce(r.detail,'{}'::jsonb))
    on conflict (check_key) where resolved_at is null do update set
      severity=excluded.severity, area=excluded.area, title=excluded.title, detail=excluded.detail,
      last_seen=now(), occurrences=i.occurrences+1,
      acknowledged_at=case when (case excluded.severity when 'critical' then 1 when 'warning' then 2 else 3 end) < (case i.severity when 'critical' then 1 when 'warning' then 2 else 3 end) then null else i.acknowledged_at end,
      acknowledged_by=case when (case excluded.severity when 'critical' then 1 when 'warning' then 2 else 3 end) < (case i.severity when 'critical' then 1 when 'warning' then 2 else 3 end) then null else i.acknowledged_by end,
      acknowledged_note=case when (case excluded.severity when 'critical' then 1 when 'warning' then 2 else 3 end) < (case i.severity when 'critical' then 1 when 'warning' then 2 else 3 end) then null else i.acknowledged_note end;
  end loop;

  update pipeline.platform_issues i set resolved_at=now()
   where i.resolved_at is null and split_part(i.check_key,':',1)=any(v_ok)
     and not exists (select 1 from jsonb_array_elements(v_found) f where f->>'check_key'=i.check_key);

  update pipeline.platform_health_checks c set
    status=case when c.key='edge_deployed' then 'skipped'
                else coalesce((select case min(case f->>'severity' when 'critical' then 1 when 'warning' then 2 else 3 end) when 1 then 'critical' when 2 then 'warning' else 'ok' end
                                 from jsonb_array_elements(v_found) f where split_part(f->>'check_key',':',1)=c.key),'ok') end,
    detail=coalesce(v_det->c.key, c.detail), checked_at=now(), duration_ms=(v_ms->>c.key)::numeric::int
   where c.key=any(v_ok);

  delete from pipeline.platform_edge_calls where created_at<now()-interval '2 days';
  delete from pipeline.platform_health_runs where started_at<now()-interval '14 days';
  delete from pipeline.platform_issues where resolved_at<now()-interval '90 days';

  select jsonb_build_object('critical',count(*) filter (where severity='critical'),'warning',count(*) filter (where severity='warning'),'info',count(*) filter (where severity='info'))
    into v_counts from pipeline.platform_issues where resolved_at is null;
  insert into pipeline.platform_health_runs(started_at,duration_ms,checks_ran,check_ms,counts)
  values (v_t0, round(extract(epoch from clock_timestamp()-v_t0)*1000), v_ok, v_ms, v_counts);
  return jsonb_build_object('ran',to_jsonb(v_ok),'duration_ms',round(extract(epoch from clock_timestamp()-v_t0)*1000),'check_ms',v_ms,'open',v_counts,'found',jsonb_array_length(v_found));
end $_$;


ALTER FUNCTION "security"."platform_health_check_v1"("p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_due_v1"("p_key" "text", "p_force" boolean) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select p_force or coalesce((select c.checked_at is null
                                  or c.checked_at <= now() - make_interval(mins=>c.cadence_minutes) + least(interval '3 minutes', make_interval(mins=>c.cadence_minutes)*0.3)
                               from pipeline.platform_health_checks c where c.key=p_key), true)
$$;


ALTER FUNCTION "security"."platform_health_due_v1"("p_key" "text", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_issue_v1"("p_key" "text", "p_severity" "text", "p_area" "text", "p_title" "text", "p_detail" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$ select jsonb_build_object('check_key',p_key,'severity',p_severity,'area',p_area,'title',p_title,'detail',coalesce(p_detail,'{}'::jsonb)) $$;


ALTER FUNCTION "security"."platform_health_issue_v1"("p_key" "text", "p_severity" "text", "p_area" "text", "p_title" "text", "p_detail" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_stall_v1"("p_key" "text", "p_area" "text", "p_label" "text", "p_job" "text", "p_last_progress" timestamp with time zone, "p_pending_sql" "text", "p_default_interval_s" integer DEFAULT 600) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security', 'public', 'catalogue', 'scholarship'
    AS $$
declare v_int int; v_active boolean; v_warn interval; v_crit interval; v_pending bigint; v_age interval:=now()-coalesce(p_last_progress,'-infinity'::timestamptz);
begin
  select security.platform_cron_interval_seconds(j.schedule), j.active into v_int, v_active from cron.job j where j.jobname=p_job;
  v_int:=coalesce(v_int,p_default_interval_s);
  v_warn:=greatest(make_interval(secs=>3*v_int), interval '15 minutes');
  v_crit:=greatest(make_interval(secs=>12*v_int), interval '2 hours');
  if v_age <= v_warn then
    return jsonb_build_object('queue',p_key,'status','moving','last_progress',p_last_progress);
  end if;
  execute p_pending_sql into v_pending;
  if coalesce(v_pending,0)=0 then
    return jsonb_build_object('queue',p_key,'status','idle','pending',0,'last_progress',p_last_progress);
  end if;
  return jsonb_build_object('queue',p_key,'status','stalled','pending',v_pending,'last_progress',p_last_progress,
    'job',p_job,'job_active',coalesce(v_active,false),'stalled_minutes',round(extract(epoch from least(v_age, interval '365 days'))/60),
    'threshold_minutes',round(extract(epoch from v_warn)/60),
    'issue',security.platform_health_issue_v1(p_key,
      case when v_age>v_crit or coalesce(v_active,false)=false then 'critical' else 'warning' end, p_area,
      p_label||' has stopped: '||v_pending||' waiting, nothing processed for '||
        case when p_last_progress is null then 'as long as records exist' else round(extract(epoch from v_age)/60)||' minutes' end||
        case when v_active is distinct from true then ' (its scheduled job is missing or paused)' else '' end,
      jsonb_build_object('pending',v_pending,'last_progress',p_last_progress,'job',p_job,'job_active',coalesce(v_active,false),
        'threshold_minutes',round(extract(epoch from v_warn)/60))));
end $$;


ALTER FUNCTION "security"."platform_health_stall_v1"("p_key" "text", "p_area" "text", "p_label" "text", "p_job" "text", "p_last_progress" timestamp with time zone, "p_pending_sql" "text", "p_default_interval_s" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_state_v1"("p_detail" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select jsonb_build_object(
    'generated_at', now(),
    'overall', coalesce((select case min(case severity when 'critical' then 1 when 'warning' then 2 else 3 end) when 1 then 'critical' when 2 then 'warning' else 'ok' end
                           from pipeline.platform_issues where resolved_at is null and acknowledged_at is null),'ok'),
    'counts', (select jsonb_build_object('critical',count(*) filter (where severity='critical'),'warning',count(*) filter (where severity='warning'),'info',count(*) filter (where severity='info'))
                 from pipeline.platform_issues where resolved_at is null),
    'issues', coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'check_key',i.check_key,'severity',i.severity,'area',i.area,'title',i.title,
                           'detail',case when p_detail then i.detail else '{}'::jsonb end,'first_seen',i.first_seen,'last_seen',i.last_seen,
                           'occurrences',i.occurrences,'acknowledged_at',i.acknowledged_at) order by i.rk, i.last_seen desc)
                          from (select p.*, case p.severity when 'critical' then 1 when 'warning' then 2 else 3 end rk from pipeline.platform_issues p
                                 where p.resolved_at is null order by rk, p.last_seen desc limit 200) i),'[]'::jsonb),
    'checks', coalesce((select jsonb_agg(jsonb_build_object('key',c.key,'area',c.area,'label',c.label,'status',c.status,
                           'detail',case when p_detail then c.detail else '{}'::jsonb end,'checked_at',c.checked_at) order by c.sort_order)
                          from pipeline.platform_health_checks c),'[]'::jsonb),
    'history', (select jsonb_agg(jsonb_build_object('day',to_char(g.d,'YYYY-MM-DD'),
                   'critical',(select count(*) from pipeline.platform_issues i where i.severity='critical' and i.first_seen<(g.d at time zone 'UTC')+interval '1 day' and coalesce(i.resolved_at,'infinity'::timestamptz)>=(g.d at time zone 'UTC')),
                   'warning',(select count(*) from pipeline.platform_issues i where i.severity='warning' and i.first_seen<(g.d at time zone 'UTC')+interval '1 day' and coalesce(i.resolved_at,'infinity'::timestamptz)>=(g.d at time zone 'UTC'))) order by g.d)
                  from generate_series(((now() at time zone 'UTC')::date-13)::timestamp,((now() at time zone 'UTC')::date)::timestamp,interval '1 day') g(d)))
$$;


ALTER FUNCTION "security"."platform_health_state_v1"("p_detail" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_summary_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v jsonb:=security.platform_health_state_v1(true); v_at timestamptz; v_ms int; v_lines text[]; e jsonb; v_res bigint;
begin
  select started_at, duration_ms into v_at, v_ms from pipeline.platform_health_runs order by started_at desc limit 1;
  select count(*) into v_res from pipeline.platform_issues where resolved_at>=now()-interval '24 hours';
  v_lines:=array['Platform health: '||upper(v->>'overall')||' - '||(v->'counts'->>'critical')||' critical, '||(v->'counts'->>'warning')||' warning, '||(v->'counts'->>'info')||' info open issue(s); '||v_res||' resolved in the last 24 hours.',
                 'Last health run: '||coalesce(to_char(v_at at time zone 'Asia/Kolkata','DD Mon HH24:MI')||' IST ('||v_ms||' ms)','never')||'.'];
  for e in select x from jsonb_array_elements(v->'issues') x limit 15 loop
    v_lines:=v_lines||('- ['||(e->>'severity')||'] '||(e->>'area')||': '||(e->>'title')||' (since '||to_char((e->>'first_seen')::timestamptz at time zone 'Asia/Kolkata','DD Mon HH24:MI')||' IST'
                       ||case when e->>'acknowledged_at' is not null then ', acknowledged' else '' end||')');
  end loop;
  if jsonb_array_length(v->'issues')=0 then v_lines:=v_lines||'- No open issues.'::text;
  elsif jsonb_array_length(v->'issues')>15 then v_lines:=v_lines||('- ... and '||(jsonb_array_length(v->'issues')-15)||' more.'); end if;
  return jsonb_build_object('generated_at',now(),'overall',v->'overall','counts',v->'counts','resolved_24h',v_res,'last_run_at',v_at,'last_run_ms',v_ms,
    'text',array_to_string(v_lines,E'\n'),'issues',v->'issues','checks',v->'checks');
end $$;


ALTER FUNCTION "security"."platform_health_summary_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_notices_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  w_or int := coalesce((security.toolset_setting('openrouter', 'notice_window_hours'))::text::int, 24);
  w_job int := coalesce((security.toolset_setting('scheduled_jobs', 'notice_window_hours'))::text::int, 24);
  w_edge int := coalesce((security.toolset_setting('edge_functions', 'notice_window_hours'))::text::int, 6);
  v_or_mode text := coalesce((select t.enforcement from pipeline.platform_toolsets t where t.key = 'openrouter'), 'stop');
  v jsonb := '[]'::jsonb;
begin
  -- OpenRouter refused calls (Layer 3)
  v := v || coalesce((select jsonb_agg(jsonb_build_object(
      'key', 'openrouter:3:refused:' || z.code, 'layer', 3, 'toolset', 'openrouter', 'kind', 'refused', 'severity', 'high',
      'title', case z.code when 'credit' then 'OpenRouter refused calls: out of credit'
                           when 'key_limit' then 'OpenRouter refused calls: the key''s own spending limit was reached'
                           when 'rate' then 'OpenRouter refused calls: rate limit'
                           else 'OpenRouter refused calls: key not accepted' end,
      'detail', format('%s work items in the last %s hours were released and will be retried.', z.n, w_or),
      'hint', case z.code when 'credit' then 'Top up the OpenRouter balance, then the released items are picked up again.'
                          when 'key_limit' then 'The limit is set on the key at OpenRouter (Workspaces › Keys), not in CourseFinder. Raise or clear it there; the items retry by themselves.'
                          when 'rate' then 'Usually clears by itself; the items retry.'
                          else 'Check the key on Platform settings › Environment & integrations.' end,
      'count', z.n, 'first_at', z.first_at, 'last_at', z.last_at))
    from (select case when i.last_error ilike '%key limit exceeded%' or i.last_error ilike '%key weekly limit%' then 'key_limit'
                      when i.last_error ~ 'provider_402' then 'credit' when i.last_error ~ 'provider_429' then 'rate' else 'key' end code,
                 count(*) n, min(i.updated_at) first_at, max(i.updated_at) last_at
          from pipeline.layer3_work_items i
          where i.updated_at > now() - make_interval(hours => w_or)
            and (i.last_error ~ 'provider_(40[123]|429)' or i.last_error ilike '%key weekly limit%')
          group by 1) z where z.code is not null), '[]'::jsonb);

  -- OpenRouter balance (Layer 3)
  v := v || coalesce((select jsonb_agg(x) from (
    select jsonb_build_object('key', 'openrouter:3:low_balance', 'layer', 3, 'toolset', 'openrouter', 'kind', 'low_balance', 'severity', 'warning',
      'title', format('OpenRouter balance is US$%s', round(o.remaining_usd, 2)),
      'detail', format('Below the warning level of US$%s. Layer 3 is set to %s.', security.toolset_setting('openrouter', 'low_balance_warn_usd'),
                       case v_or_mode when 'observe' then 'observe only, so it keeps running until OpenRouter refuses calls' else 'stop at limits' end),
      'hint', 'Top up when you are ready; nothing is stopped by this notice.',
      'count', 1, 'first_at', o.observed_at, 'last_at', o.observed_at) x
    from (select * from pipeline.layer3_openrouter_observations where kind = 'credits' order by observed_at desc limit 1) o
    where o.remaining_usd < coalesce((security.toolset_setting('openrouter', 'low_balance_warn_usd'))::text::numeric, 0)
    union all
    select jsonb_build_object('key', 'openrouter:3:not_observed', 'layer', 3, 'toolset', 'openrouter', 'kind', 'not_observed', 'severity', 'warning',
      'title', 'OpenRouter balance has not been read recently',
      'detail', format('Last reading %s.', coalesce(o.observed_at::text, 'never')),
      'hint', 'The balance is read by the route guard job on Layer 3; check it is running.',
      'count', 1, 'first_at', o.observed_at, 'last_at', now())
    from (select max(observed_at) observed_at from pipeline.layer3_openrouter_observations where kind = 'credits') o
    where o.observed_at is null or o.observed_at < now() - make_interval(mins => coalesce((security.toolset_setting('openrouter', 'balance_stale_minutes'))::text::int, 30))
  ) q), '[]'::jsonb);

  -- Spend past a daily guard today (Layer 3)
  v := v || coalesce((select jsonb_agg(jsonb_build_object(
      'key', 'openrouter:3:over_guard:' || z.task_class || ':' || to_char(now() at time zone 'UTC', 'YYYY-MM-DD'), 'layer', 3, 'toolset', 'openrouter', 'kind', 'over_guard',
      'severity', case v_or_mode when 'observe' then 'info' else 'warning' end,
      'title', format('%s spent US$%s today, past its guard of US$%s', replace(z.task_class, '_', ' '), round(z.spent, 2), z.guard),
      'detail', case v_or_mode when 'observe' then 'Observe only: the task keeps running. This is recorded for the top-up review.' else 'The task has stopped until the UTC day changes.' end,
      'hint', 'Change the guard on Platform settings › Environment & integrations, or the mode on Models & services › Toolsets and limits.',
      'count', 1, 'first_at', z.first_at, 'last_at', z.last_at))
    from (select b.task_class, b.daily_usd_max guard, sum(i.estimated_cost_usd) spent, min(i.created_at) first_at, max(i.created_at) last_at
          from pipeline.layer3_route_budget b join pipeline.layer3_interpretations i on i.task_class = b.task_class
          where i.created_at >= date_trunc('day', now() at time zone 'UTC') at time zone 'UTC'
          group by 1, 2 having sum(i.estimated_cost_usd) >= b.daily_usd_max) z), '[]'::jsonb);

  -- Firecrawl balance, scholarship share, course-link search cap (Layer 2)
  v := v || coalesce((select jsonb_agg(x) from (
    select jsonb_build_object('key', 'firecrawl:2:low_balance', 'layer', 2, 'toolset', 'firecrawl', 'kind', 'low_balance', 'severity', 'warning',
      'title', format('Firecrawl has %s credits left this month', o.remaining_units),
      'detail', format('Below the warning level of %s. The period ends %s.', security.toolset_setting('firecrawl', 'low_balance_warn_units'), to_char(o.period_end at time zone 'Australia/Melbourne', 'DD Mon YYYY')),
      'hint', 'Work that needs Firecrawl stops at the reserve set on Scrapers & fetchers.', 'count', 1, 'first_at', o.observed_at, 'last_at', o.observed_at) x
    from (select v2.* from pipeline.vendor_credit_observations v2 join pipeline.layer2_acquisition_providers p on p.id = v2.provider_id and p.provider_key = 'firecrawl' order by v2.observed_at desc limit 1) o
    where o.remaining_units < coalesce((security.toolset_setting('firecrawl', 'low_balance_warn_units'))::text::numeric, 0)
    union all
    select jsonb_build_object('key', 'firecrawl:2:scholarship_share', 'layer', 2, 'toolset', 'firecrawl', 'kind', 'cap_reached', 'severity', 'warning',
      'title', format('Scholarship Firecrawl share: %s of %s credits used', s.used, s.cap),
      'detail', format('Fewer than the reserve of %s are left, so newly found scholarship pages that refuse a direct read are not read.', s.reserve),
      'hint', 'Raise the cap on Layer 2 › Scholarships if you want them read.', 'count', 1, 'first_at', now(), 'last_at', now())
    from (select (b->>'used')::numeric used, (b->>'cap')::numeric cap, (b->>'reserve')::numeric reserve
          from (select jsonb_build_object(
                  'used', (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.purpose in ('sch_map', 'sch_search', 'sch_scrape')),
                  'cap', (select s2.value from pipeline.scholarship_layer_settings s2 where s2.key = 'firecrawl_cap'),
                  'reserve', (select s2.value from pipeline.scholarship_layer_settings s2 where s2.key = 'firecrawl_reserve')) b) q) s
    where s.cap - s.used <= s.reserve
    union all
    select jsonb_build_object('key', 'firecrawl:2:course_link_cap:' || to_char(now(), 'YYYY-MM'), 'layer', 2, 'toolset', 'firecrawl', 'kind', 'cap_reached', 'severity', 'warning',
      'title', format('Course-link search used %s of its %s monthly credits', l.used, l.cap),
      'detail', 'Course-link search stops for the rest of the month.', 'hint', 'Change the monthly cap on Jobs › Priority.',
      'count', 1, 'first_at', now(), 'last_at', now())
    from (select (select monthly_credit_cap from pipeline.course_link_search_settings limit 1) cap,
                 (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.purpose = 'course_link_search' and u.at >= date_trunc('month', now())) used) l
    where l.used >= l.cap
  ) q), '[]'::jsonb);

  -- Scheduled jobs that timed out or failed (the job's layer)
  v := v || coalesce((select jsonb_agg(jsonb_build_object(
      'key', 'scheduled_jobs:' || z.layer || ':' || z.kind || ':' || z.jobname, 'layer', z.layer, 'toolset', 'scheduled_jobs', 'kind', z.kind,
      'severity', case when z.n >= 5 then 'high' else 'warning' end,
      'title', case z.kind when 'timeout' then format('Job "%s" hit the database time limit %s times', z.jobname, z.n)
                           else format('Job "%s" failed %s times', z.jobname, z.n) end,
      'detail', format('In the last %s hours (%s runs in all). Last message: %s', w_job, z.runs, z.msg),
      'hint', case z.kind when 'timeout' then 'Lower the job''s batch size setting so each run finishes inside the limit.' else 'Usually clears by itself (for example a deadlock); if it repeats, the job needs a fix.' end,
      'count', z.n, 'first_at', z.first_at, 'last_at', z.last_at))
    from (select j.jobname, coalesce(l.layer, 2) layer,
                 case when d.return_message ilike '%statement timeout%' then 'timeout' else 'failed' end kind,
                 count(*) n, min(d.end_time) first_at, max(d.end_time) last_at, left(max(d.return_message), 140) msg,
                 (select count(*) from cron.job_run_details d2 where d2.jobid = j.jobid and d2.end_time > now() - make_interval(hours => w_job)) runs
          from cron.job_run_details d join cron.job j on j.jobid = d.jobid left join pipeline.platform_job_layers l on l.jobname = j.jobname
          where d.status = 'failed' and d.end_time > now() - make_interval(hours => w_job)
            and not (select coalesce(bool_and(r.status = 'succeeded'), false) and count(*) = 3
                       from (select d3.status from cron.job_run_details d3 where d3.jobid = j.jobid and d3.status in ('succeeded', 'failed')
                             order by d3.start_time desc limit 3) r)
          group by j.jobid, j.jobname, l.layer, 3
          having count(*) >= coalesce((security.toolset_setting('scheduled_jobs', 'min_failures'))::text::int, 1)) z), '[]'::jsonb);

  -- Edge function calls that timed out (platform)
  v := v || coalesce((select jsonb_agg(jsonb_build_object(
      'key', 'edge_functions:0:timeout', 'layer', 0, 'toolset', 'edge_functions', 'kind', 'timeout', 'severity', 'warning',
      'title', format('%s edge function calls timed out or hit the worker limit', z.n),
      'detail', format('In the last %s hours.', w_edge), 'hint', 'The worker runs too long per call; lower its per-run limit.',
      'count', z.n, 'first_at', z.first_at, 'last_at', z.last_at))
    from (select count(*) n, min(r.created) first_at, max(r.created) last_at from net._http_response r
          where r.created > now() - make_interval(hours => w_edge) and (r.timed_out or r.status_code in (504, 546))) z
    where z.n >= coalesce((security.toolset_setting('edge_functions', 'min_timeouts'))::text::int, 1)), '[]'::jsonb);

  return v;
end $_$;


ALTER FUNCTION "security"."platform_notices_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_resource_observe_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'cron', 'net'
    AS $$
declare h timestamptz := date_trunc('hour', now()); h0 timestamptz := date_trunc('hour', now()) - interval '1 hour';
  m timestamptz := date_trunc('month', now()); cp pipeline.platform_compute_profile%rowtype; r pipeline.platform_resource_observations%rowtype;
begin
  select * into cp from pipeline.platform_compute_profile where id=1;
  r.observed_at := h; r.memory_bytes := cp.memory_bytes; r.compute_size := cp.compute_size;
  r.db_bytes := pg_database_size(current_database());
  select round(100.0*sum(blks_hit)/nullif(sum(blks_hit)+sum(blks_read),0),2) into r.cache_hit_pct from pg_stat_database where datname=current_database();
  select count(*), count(*) filter (where state='active') into r.connections, r.active_connections from pg_stat_activity where backend_type='client backend';
  select count(*), count(*) filter (where status not in ('succeeded','running')), round(max(extract(epoch from coalesce(end_time, case when status in ('running','starting','sending','connecting') then now() end)-start_time))::numeric,1)
    into r.cron_runs, r.cron_failures, r.cron_max_seconds from cron.job_run_details where start_time >= h0 and start_time < h;
  select coalesce(max(c) filter (where t >= h0 and t < h and d = 1),0) into r.cron_max_concurrent from (
    select e.t, e.d, sum(e.d) over (order by e.t, e.d desc) c from (
      select b.start_time t, 1 d from cron.job_run_details b where b.start_time >= h0 - interval '1 hour' and b.start_time < h
      union all
      select coalesce(b.end_time, case when b.status in ('running','starting','sending','connecting') then now() else b.start_time end), -1
        from cron.job_run_details b where b.start_time >= h0 - interval '1 hour' and b.start_time < h) e) z;
  select count(*) into r.http_requests from net._http_response where created >= h0 and created < h;
  select coalesce(jsonb_agg(jsonb_build_object('provider',coalesce(ap.provider_key,'unknown'),'units',u,'cost_usd',cst)),'[]'::jsonb) into r.acquisition
    from (select ri.selected_provider_id, sum(coalesce(ri.vendor_units,0)) u, sum(coalesce(ri.vendor_cost_usd,0)) cst
          from pipeline.layer2_run_items ri where ri.completed_at >= h0 and ri.completed_at < h group by 1) x
    left join pipeline.layer2_acquisition_providers ap on ap.id=x.selected_provider_id;
  select sum(coalesce(vendor_units,0)), sum(coalesce(vendor_cost_usd,0)) into r.acquisition_units_mtd, r.acquisition_cost_mtd_usd
    from pipeline.layer2_run_items where completed_at >= m;
  select count(*), sum(coalesce(input_tokens,0)+coalesce(output_tokens,0)), sum(coalesce(estimated_cost_usd,0)) into r.ai_calls, r.ai_tokens, r.ai_cost_usd
    from (select input_tokens, output_tokens, estimated_cost_usd from pipeline.layer3_interpretations where call_completed_at >= h0 and call_completed_at < h
          union all select input_tokens, output_tokens, estimated_cost_usd from pipeline.layer3_quality_benchmark_runs where completed_at >= h0 and completed_at < h) z;
  select coalesce(sum(estimated_cost_usd),0) into r.ai_cost_mtd_usd
    from (select estimated_cost_usd from pipeline.layer3_interpretations where call_completed_at >= m
          union all select estimated_cost_usd from pipeline.layer3_quality_benchmark_runs where completed_at >= m) z;
  select coalesce(jsonb_agg(jsonb_build_object('table',t,'bytes',b) order by b desc),'[]'::jsonb) into r.largest_tables
    from (select n.nspname||'.'||c.relname t, pg_total_relation_size(c.oid) b from pg_class c join pg_namespace n on n.oid=c.relnamespace
          where c.relkind='r' and n.nspname not in ('pg_catalog','information_schema') order by 2 desc limit 5) z;
  insert into pipeline.platform_resource_observations select r.* on conflict (observed_at) do update set
    db_bytes=excluded.db_bytes, cache_hit_pct=excluded.cache_hit_pct, connections=excluded.connections, active_connections=excluded.active_connections,
    cron_runs=excluded.cron_runs, cron_failures=excluded.cron_failures, cron_max_seconds=excluded.cron_max_seconds, cron_max_concurrent=excluded.cron_max_concurrent,
    http_requests=excluded.http_requests, acquisition=excluded.acquisition, acquisition_units_mtd=excluded.acquisition_units_mtd, acquisition_cost_mtd_usd=excluded.acquisition_cost_mtd_usd,
    ai_calls=excluded.ai_calls, ai_tokens=excluded.ai_tokens, ai_cost_usd=excluded.ai_cost_usd, ai_cost_mtd_usd=excluded.ai_cost_mtd_usd, largest_tables=excluded.largest_tables;
  delete from pipeline.platform_resource_observations where observed_at < now() - interval '180 days';
  return to_jsonb(r);
end $$;


ALTER FUNCTION "security"."platform_resource_observe_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."priority_pin_label"("p_kind" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref'
    AS $$
  select case p_kind
    when 'provider' then (select jsonb_build_object('label',coalesce(pr.display_name,pr.canonical_name),'detail',concat_ws(' · ',s.name,k.name),'courses',(select count(*) from catalogue.courses c where c.provider_id=pr.id and c.lifecycle_status='active'))
                            from catalogue.providers pr left join ref.subdivisions s on s.id=pr.subdivision_id left join ref.countries k on k.id=pr.country_id where pr.id=p_id)
    when 'state' then (select jsonb_build_object('label',s.name,'detail',k.name,'courses',(select count(*) from catalogue.courses c join catalogue.providers pr on pr.id=c.provider_id where pr.subdivision_id=s.id and c.lifecycle_status='active'))
                         from ref.subdivisions s left join ref.countries k on k.id=s.country_id where s.id=p_id)
    when 'country' then (select jsonb_build_object('label',k.name,'detail','Whole country','courses',(select count(*) from catalogue.courses c join catalogue.providers pr on pr.id=c.provider_id where pr.country_id=k.id and c.lifecycle_status='active'))
                           from ref.countries k where k.id=p_id)
    else (select jsonb_build_object('label',coalesce(c.display_title,c.canonical_title),'detail',concat_ws(' · ',c.course_code,coalesce(pr.display_name,pr.canonical_name)),'courses',1)
            from catalogue.courses c left join catalogue.providers pr on pr.id=c.provider_id where c.id=p_id) end
$$;


ALTER FUNCTION "security"."priority_pin_label"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_basis_rule_admit_v1"("p_apply" boolean DEFAULT false, "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'search'
    AS $_$
declare r record; v_text text; v_m text[]; v_basis text; v_year int; v_code text; v_source uuid; v_key text; v_fee uuid; v_review uuid;
        v_admitted int:=0; v_nomatch int:=0; v_courses uuid[]:='{}'; v_samples jsonb:='[]'::jsonb; v_amt_re text;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  for r in
    select w.id wid, w.entity_id course_id, w.evidence_id, w.interpretation_id, br.rule_code, br.fee_pattern, br.basis_map,
           (w.candidate_context->'provider_current_tuition'->>'amount')::numeric amount,
           (select f->>'context' from jsonb_array_elements(coalesce(w.candidate_context->'fee_candidates','[]'::jsonb)) f
             where jsonb_typeof(f)='object' and (f->>'amount')::numeric=(w.candidate_context->'provider_current_tuition'->>'amount')::numeric
               and coalesce((f->>'domestic')::boolean,false)=false order by (f->>'score')::numeric desc nulls last limit 1) ctx
      from pipeline.layer3_work_items w
      join catalogue.courses c on c.id=w.entity_id
      join pipeline.provider_fee_basis_rules br on br.provider_id=c.provider_id and br.active and br.review_by>=current_date
      join pipeline.evidence_artifacts e on e.id=w.evidence_id and e.source_url ~* br.page_url_pattern
     where w.task_class='provider_current_tuition_validation'
       and w.status in ('pending','layer4_required','failed','no_candidate','rejected')
       and coalesce(w.candidate_context->'provider_current_tuition'->>'audience','')='international'
       and not exists (select 1 from catalogue.course_fees f where f.course_id=w.entity_id and f.fee_type='provider_current_tuition' and f.status='active')
     limit greatest(1,least(coalesce(p_limit,200),2000))
  loop
    v_text:=security.layer4_clean_quote(r.ctx);
    v_amt_re:=replace(to_char(trunc(r.amount)::bigint,'FM999,999,999'),',',',?');
    v_m:=regexp_match(coalesce(v_text,''), replace(r.fee_pattern,'{AMOUNT}',v_amt_re)||'([^0-9,]|$)', 'i');
    if v_m is null then v_nomatch:=v_nomatch+1; continue; end if;
    v_year:=v_m[1]::int; v_basis:=r.basis_map->>lower(v_m[2]);
    if v_basis is null then v_nomatch:=v_nomatch+1; continue; end if;
    if jsonb_array_length(v_samples)<6 then v_samples:=v_samples||jsonb_build_object('amount',r.amount,'year',v_year,'basis',v_basis,'text',left(substring(v_text from '(?i)full-fee places.{0,60}'),90)); end if;
    if not p_apply then v_admitted:=v_admitted+1; continue; end if;
    select course_code into v_code from catalogue.courses where id=r.course_id;
    select source_id into v_source from pipeline.evidence_artifacts where id=r.evidence_id;
    if v_code is null or v_source is null then v_nomatch:=v_nomatch+1; continue; end if;
    v_key:=lower(upper(btrim(v_code))||':international:'||v_year||':'||v_basis);
    v_fee:=null;
    insert into catalogue.course_fees(course_id,fee_year,audience,fee_type,amount,currency_code,basis,notes,source_id,evidence_id,confidence,campus_id,source_fee_key,status,last_verified_at,source_snapshot_at,updated_at)
    values (r.course_id,v_year,'international','provider_current_tuition',r.amount,'AUD',v_basis,
            format('CF-247 provider basis rule admission (deterministic, Decision 162); rule %s; work item %s',r.rule_code,r.wid),
            v_source,r.evidence_id,1,null,v_key,'active',now(),now(),now())
    on conflict(course_id,source_id,source_fee_key) where source_id is not null and source_fee_key is not null do nothing
    returning id into v_fee;
    update pipeline.layer3_work_items set status='admitted', completed_at=now(), last_error=null, updated_at=now() where id=r.wid;
    v_review:=null;
    if r.interpretation_id is not null then
      update pipeline.layer4_review_items set status='superseded', decided_at=now() where layer3_interpretation_id=r.interpretation_id and status='pending' returning id into v_review;
    end if;
    insert into pipeline.provider_rule_admissions(work_item_id,review_item_id,course_id,course_fee_id,rule_code,amount,basis,matched_text)
    values (r.wid,v_review,r.course_id,v_fee,r.rule_code,r.amount,v_basis,left(v_text,500));
    v_courses:=v_courses||r.course_id; v_admitted:=v_admitted+1;
  end loop;
  if p_apply and cardinality(v_courses)>0 then perform search.refresh_course_enrichment_scoped_v1(v_courses,true); end if;
  return jsonb_build_object('mode',case when p_apply then 'apply' else 'proof' end,'admitted',v_admitted,'not_matched',v_nomatch,'samples',v_samples);
end $_$;


ALTER FUNCTION "security"."provider_basis_rule_admit_v1"("p_apply" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_contact_append_version"("p_contact_id" "uuid", "p_actor" "uuid", "p_payload" "jsonb", "p_source_class" "text", "p_source_authority" "text", "p_reason" "text", "p_import_batch_id" "uuid" DEFAULT NULL::"uuid", "p_import_row_id" "uuid" DEFAULT NULL::"uuid", "p_evidence_id" "uuid" DEFAULT NULL::"uuid", "p_source_observation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $_$
declare
 v_contact pipeline.provider_contacts%rowtype;v_prev pipeline.provider_contact_versions%rowtype;
 v_version_no int;v_new_id uuid;v_full_name text;v_team_name text;v_job_title text;v_functional_area text;
 v_region_scope text;v_markets text;v_email text;v_phone text;v_location text;v_verification text;v_verified_on date;
 v_source_url text;v_source_page_title text;v_source_notes text;v_hash text;v_identity text;v_payload jsonb;v_domain text;
begin
 select * into v_contact from pipeline.provider_contacts where id=p_contact_id for update;
 if not found then raise exception 'managed contact not found' using errcode='P0002'; end if;
 if v_contact.current_version_id is not null then select * into v_prev from pipeline.provider_contact_versions where id=v_contact.current_version_id; end if;

 v_full_name:=case when p_payload?'full_name' then nullif(btrim(p_payload->>'full_name'),'') else v_prev.full_name end;
 v_team_name:=case when p_payload?'team_name' then nullif(btrim(p_payload->>'team_name'),'') else v_prev.team_name end;
 v_job_title:=case when p_payload?'job_title' then nullif(btrim(p_payload->>'job_title'),'') else v_prev.job_title end;
 v_functional_area:=case when p_payload?'functional_area' then nullif(btrim(p_payload->>'functional_area'),'') else v_prev.functional_area end;
 v_region_scope:=case when p_payload?'region_scope' then nullif(btrim(p_payload->>'region_scope'),'') else v_prev.region_scope end;
 v_markets:=case when p_payload?'countries_or_markets' then nullif(btrim(p_payload->>'countries_or_markets'),'') else v_prev.countries_or_markets end;
 v_email:=case when p_payload?'work_email' then nullif(lower(btrim(p_payload->>'work_email')),'') else v_prev.work_email end;
 v_phone:=case when p_payload?'work_phone' then nullif(btrim(p_payload->>'work_phone'),'') else v_prev.work_phone end;
 v_location:=case when p_payload?'staff_location' then nullif(btrim(p_payload->>'staff_location'),'') else v_prev.staff_location end;
 v_verification:=case when p_payload?'verification_state' then nullif(lower(btrim(p_payload->>'verification_state')),'') else coalesce(v_prev.verification_state,'manual') end;
 v_verified_on:=case when p_payload?'verified_on' and nullif(btrim(p_payload->>'verified_on'),'') is not null then (p_payload->>'verified_on')::date when p_payload?'verified_on' then null else v_prev.verified_on end;
 v_source_url:=case when p_payload?'source_url' then nullif(btrim(p_payload->>'source_url'),'') else v_prev.source_url end;
 v_source_page_title:=case when p_payload?'source_page_title' then nullif(btrim(p_payload->>'source_page_title'),'') else v_prev.source_page_title end;
 v_source_notes:=case when p_payload?'source_notes' then nullif(btrim(p_payload->>'source_notes'),'') else v_prev.source_notes end;

 if v_contact.record_type='named_staff' and v_full_name is null then raise exception 'named staff contact requires full_name' using errcode='22023'; end if;
 if v_contact.record_type='team_contact' and coalesce(v_team_name,v_job_title,v_functional_area,v_email,v_phone,v_source_url) is null then raise exception 'team contact requires team/function/contact/source context' using errcode='22023'; end if;
 if coalesce(v_email,v_phone,v_job_title,v_functional_area,v_region_scope,v_source_url) is null then raise exception 'contact requires meaningful assignment/contact/source context' using errcode='22023'; end if;
 if v_email is not null then
  if v_email !~* '^[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}$' then raise exception 'invalid professional email' using errcode='22023'; end if;
  v_domain:=split_part(v_email,'@',2);
  if v_domain in ('gmail.com','googlemail.com','yahoo.com','yahoo.com.au','hotmail.com','outlook.com','live.com','icloud.com','proton.me','protonmail.com') then
   raise exception 'personal/free-mail address is not permitted for Provider Contacts' using errcode='22023';
  end if;
 end if;
 if v_source_url is not null and v_source_url !~* '^https?://' then raise exception 'source_url must be HTTP(S)' using errcode='22023'; end if;

 v_payload:=jsonb_build_object('full_name',v_full_name,'team_name',v_team_name,'job_title',v_job_title,'functional_area',v_functional_area,
  'region_scope',v_region_scope,'countries_or_markets',v_markets,'work_email',v_email,'work_phone',v_phone,'staff_location',v_location,
  'verification_state',v_verification,'verified_on',case when v_verified_on is null then null else v_verified_on::text end,
  'source_authority',p_source_authority,'source_url',v_source_url);
 v_hash:=security.provider_contact_payload_hash(v_payload);
 select coalesce(max(version_no),0)+1 into v_version_no from pipeline.provider_contact_versions where contact_id=p_contact_id;

 insert into pipeline.provider_contact_versions(contact_id,version_no,full_name,team_name,job_title,functional_area,region_scope,countries_or_markets,
  work_email,work_phone,staff_location,verification_state,verified_on,source_class,source_authority,source_url,source_page_title,source_notes,
  source_observation_id,evidence_id,import_batch_id,import_row_id,content_hash,effective_from,change_reason,created_at,created_by,metadata)
 values(p_contact_id,v_version_no,v_full_name,v_team_name,v_job_title,v_functional_area,v_region_scope,v_markets,v_email,v_phone,v_location,
  v_verification,v_verified_on,p_source_class,p_source_authority,v_source_url,v_source_page_title,v_source_notes,p_source_observation_id,
  p_evidence_id,p_import_batch_id,p_import_row_id,v_hash,now(),p_reason,now(),p_actor,jsonb_build_object('change_control','CF-CHG-20260902-080'))
 returning id into v_new_id;

 if v_contact.current_version_id is not null then update pipeline.provider_contact_versions set effective_to=now(),superseded_by=v_new_id where id=v_contact.current_version_id and effective_to is null; end if;
 v_identity:=security.provider_contact_identity_key(v_contact.record_type,v_full_name,v_job_title,v_region_scope,v_email,v_source_url);
 update pipeline.provider_contacts set current_version_id=v_new_id,identity_key=v_identity,updated_at=now(),updated_by=p_actor where id=p_contact_id;
 return v_new_id;
end $_$;


