CREATE OR REPLACE FUNCTION "security"."provider_contact_disposition_current"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank int; v pipeline.provider_contact_dispositions%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank(); if v_rank<1 then raise exception 'assigned CourseFinder role required' using errcode='42501'; end if;
  select * into v from pipeline.provider_contact_dispositions where provider_id=p_provider_id order by created_at desc,id desc limit 1;
  if not found then return jsonb_build_object('disposition','pending_acquisition'); end if;
  return jsonb_build_object(
    'id',v.id,'disposition',v.disposition,'international_students_url',v.international_students_url,
    'contact_team_url',v.contact_team_url,'general_email',v.general_email,
    'named_contact_count',v.named_contact_count,'territory_contact_count',v.territory_contact_count,
    'source_urls',v.source_urls,'evidence_ids',v.evidence_ids,'layer3_interpretation_id',v.layer3_interpretation_id,
    'interpretation_source',v.interpretation_source,'observed_at',v.observed_at,'last_verified_at',v.last_verified_at
  );
end $$;


ALTER FUNCTION "security"."provider_contact_disposition_current"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_contact_export_audit_impl"("p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;v_rows int:=greatest(coalesce(nullif(p_payload->>'row_count','')::int,0),0);
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank();if v_rank<5 then raise exception 'PIM Operator role required' using errcode='42501'; end if;
 insert into pipeline.provider_contact_audit_events(event_type,actor_id,reason,metadata)
 values('export',v_actor,coalesce(nullif(p_payload->>'reason',''),'Provider Contacts export'),
 jsonb_build_object('row_count',v_rows,'filters',coalesce(p_payload->'filters','{}'::jsonb),'columns',coalesce(p_payload->'columns','[]'::jsonb),'format',coalesce(nullif(p_payload->>'format',''),'csv'),'change_control','CF-CHG-20260902-080'));
 return jsonb_build_object('ok',true,'row_count',v_rows,'audited',true);
end $$;


ALTER FUNCTION "security"."provider_contact_export_audit_impl"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_contact_identity_key"("p_record_type" "text", "p_full_name" "text", "p_job_title" "text", "p_region_scope" "text", "p_work_email" "text", "p_source_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select case
  when nullif(lower(btrim(coalesce(p_work_email,''))),'') is not null then 'email:'||lower(btrim(p_work_email))
  when p_record_type='named_staff' and nullif(security.provider_contact_normalise(p_full_name),'') is not null
    then 'person:'||security.provider_contact_normalise(p_full_name)||':'||security.provider_contact_normalise(p_job_title)||':'||security.provider_contact_normalise(p_region_scope)
  when p_record_type='team_contact'
    then 'team:'||md5(security.provider_contact_normalise(p_source_url)||'|'||security.provider_contact_normalise(p_job_title)||'|'||security.provider_contact_normalise(p_region_scope))
  else null
 end
$$;


ALTER FUNCTION "security"."provider_contact_identity_key"("p_record_type" "text", "p_full_name" "text", "p_job_title" "text", "p_region_scope" "text", "p_work_email" "text", "p_source_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_contact_manage_impl"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'catalogue', 'auth'
    AS $$
declare v_rank int:=0;v_actor uuid:=auth.uid();v_action text:=lower(btrim(coalesce(p_action,'')));v_contact_id uuid;v_provider_id uuid;
 v_record_type text;v_identity text;v_version_id uuid;v_reason text;v_current pipeline.provider_contacts%rowtype;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank();if v_rank<5 then raise exception 'PIM Operator role required' using errcode='42501'; end if;
 if v_action='create' then
  v_provider_id:=nullif(p_payload->>'provider_id','')::uuid;
  if v_provider_id is null or not exists(select 1 from catalogue.providers where id=v_provider_id) then raise exception 'valid provider_id required' using errcode='22023'; end if;
  v_record_type:=lower(coalesce(nullif(p_payload->>'record_type',''),'named_staff'));if v_record_type not in ('named_staff','team_contact') then raise exception 'invalid record_type' using errcode='22023'; end if;
  v_identity:=security.provider_contact_identity_key(v_record_type,p_payload->>'full_name',p_payload->>'job_title',p_payload->>'region_scope',p_payload->>'work_email',p_payload->>'source_url');
  if v_identity is null then raise exception 'insufficient contact identity' using errcode='22023'; end if;
  insert into pipeline.provider_contacts(provider_id,record_type,lifecycle_status,identity_key,created_by,updated_by,metadata)
  values(v_provider_id,v_record_type,'active',v_identity,v_actor,v_actor,jsonb_build_object('origin','manual','change_control','CF-CHG-20260902-080')) returning id into v_contact_id;
  v_version_id:=security.provider_contact_append_version(v_contact_id,v_actor,p_payload,'manual','manual',coalesce(nullif(p_payload->>'reason',''),'Manual Provider Contact creation'));
  insert into pipeline.provider_contact_audit_events(contact_id,event_type,actor_id,reason,after_version_id,metadata)
  values(v_contact_id,'create',v_actor,coalesce(nullif(p_payload->>'reason',''),'Manual Provider Contact creation'),v_version_id,jsonb_build_object('change_control','CF-CHG-20260902-080'));
  return jsonb_build_object('ok',true,'action','create','contact_id',v_contact_id,'version_id',v_version_id);
 end if;
 v_contact_id:=nullif(coalesce(p_payload->>'contact_id',p_payload->>'id'),'')::uuid;if v_contact_id is null then raise exception 'contact_id required' using errcode='22023'; end if;
 select * into v_current from pipeline.provider_contacts where id=v_contact_id for update;if not found then raise exception 'managed contact not found' using errcode='P0002'; end if;
 if v_action in ('update','verify') then
  if v_current.lifecycle_status='deleted' then raise exception 'restore deleted contact before editing' using errcode='22023'; end if;
  if v_action='verify' then p_payload:=p_payload||jsonb_build_object('verification_state','current','verified_on',current_date::text); end if;
  v_reason:=coalesce(nullif(p_payload->>'reason',''),case when v_action='verify' then 'Contact verification' else 'Manual Provider Contact update' end);
  v_version_id:=security.provider_contact_append_version(v_contact_id,v_actor,p_payload,'manual','manual',v_reason,null,null,nullif(p_payload->>'evidence_id','')::uuid,null);
  insert into pipeline.provider_contact_audit_events(contact_id,event_type,actor_id,reason,before_version_id,after_version_id,metadata)
  values(v_contact_id,v_action,v_actor,v_reason,v_current.current_version_id,v_version_id,jsonb_build_object('change_control','CF-CHG-20260902-080'));
  return jsonb_build_object('ok',true,'action',v_action,'contact_id',v_contact_id,'version_id',v_version_id);
 end if;
 if v_action='delete' then
  v_reason:=nullif(btrim(coalesce(p_payload->>'reason','')),'');if v_reason is null then raise exception 'delete reason required' using errcode='22023'; end if;
  if v_current.lifecycle_status='deleted' then return jsonb_build_object('ok',true,'action','delete','contact_id',v_contact_id,'unchanged',true); end if;
  update pipeline.provider_contacts set lifecycle_status='deleted',deleted_at=now(),deleted_by=v_actor,delete_reason=v_reason,updated_at=now(),updated_by=v_actor where id=v_contact_id;
  insert into pipeline.provider_contact_audit_events(contact_id,event_type,actor_id,reason,before_version_id,metadata)
  values(v_contact_id,'delete',v_actor,v_reason,v_current.current_version_id,jsonb_build_object('change_control','CF-CHG-20260902-080'));
  return jsonb_build_object('ok',true,'action','delete','contact_id',v_contact_id);
 end if;
 if v_action='restore' then
  v_reason:=coalesce(nullif(btrim(p_payload->>'reason'),''),'Restore deleted Provider Contact');
  if v_current.lifecycle_status<>'deleted' then return jsonb_build_object('ok',true,'action','restore','contact_id',v_contact_id,'unchanged',true); end if;
  update pipeline.provider_contacts set lifecycle_status='active',deleted_at=null,deleted_by=null,delete_reason=null,restored_at=now(),restored_by=v_actor,updated_at=now(),updated_by=v_actor where id=v_contact_id;
  insert into pipeline.provider_contact_audit_events(contact_id,event_type,actor_id,reason,after_version_id,metadata)
  values(v_contact_id,'restore',v_actor,v_reason,v_current.current_version_id,jsonb_build_object('change_control','CF-CHG-20260902-080'));
  return jsonb_build_object('ok',true,'action','restore','contact_id',v_contact_id);
 end if;
 if v_action in ('deactivate','activate') then
  v_reason:=coalesce(nullif(btrim(p_payload->>'reason'),''),initcap(v_action)||' Provider Contact');
  if v_current.lifecycle_status='deleted' then raise exception 'deleted contact must be restored first' using errcode='22023'; end if;
  update pipeline.provider_contacts set lifecycle_status=case when v_action='activate' then 'active' else 'inactive' end,updated_at=now(),updated_by=v_actor where id=v_contact_id;
  insert into pipeline.provider_contact_audit_events(contact_id,event_type,actor_id,reason,after_version_id,metadata)
  values(v_contact_id,v_action,v_actor,v_reason,v_current.current_version_id,jsonb_build_object('change_control','CF-CHG-20260902-080'));
  return jsonb_build_object('ok',true,'action',v_action,'contact_id',v_contact_id);
 end if;
 raise exception 'unsupported Provider Contact action: %',v_action using errcode='22023';
end $$;


ALTER FUNCTION "security"."provider_contact_manage_impl"("p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_contact_normalise"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select lower(regexp_replace(
   regexp_replace(regexp_replace(btrim(coalesce(p_value,'')),'^the[[:space:]]+','','i'),'\([^)]*\)',' ','g'),
   '[^a-zA-Z0-9]+','','g'
 ))
$$;


ALTER FUNCTION "security"."provider_contact_normalise"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_contact_payload_hash"("p_payload" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select md5(concat_ws('|',
  security.provider_contact_normalise(p_payload->>'full_name'),
  security.provider_contact_normalise(p_payload->>'team_name'),
  security.provider_contact_normalise(p_payload->>'job_title'),
  security.provider_contact_normalise(p_payload->>'functional_area'),
  security.provider_contact_normalise(p_payload->>'region_scope'),
  security.provider_contact_normalise(p_payload->>'countries_or_markets'),
  lower(btrim(coalesce(p_payload->>'work_email',''))),
  regexp_replace(coalesce(p_payload->>'work_phone',''),'[[:space:]]+','','g'),
  security.provider_contact_normalise(p_payload->>'staff_location'),
  lower(btrim(coalesce(p_payload->>'verification_state',''))),
  coalesce(p_payload->>'verified_on',''),
  lower(btrim(coalesce(p_payload->>'source_authority',''))),
  lower(btrim(coalesce(p_payload->>'source_url','')))
 ))
$$;


ALTER FUNCTION "security"."provider_contact_payload_hash"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_contact_provider_map"("p_country_code" "text", "p_label" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref'
    AS $$
declare v_norm text:=security.provider_contact_normalise(p_label);v_ids uuid[];v_count int:=0;v_provider_id uuid;v_provider_name text;v_stable_key text;v_reason text;
begin
 if v_norm='' then return jsonb_build_object('state','unmatched','reason','blank_provider_label'); end if;
 select array_agg(distinct m.provider_id) into v_ids from pipeline.provider_contact_provider_mappings m
 where m.country_code=upper(coalesce(p_country_code,'')) and m.normalized_label=v_norm and m.status='accepted';
 v_count:=coalesce(cardinality(v_ids),0);
 if v_count=1 then v_provider_id:=v_ids[1];v_reason:='contact_mapping';
 elsif v_count>1 then return jsonb_build_object('state','ambiguous','reason','contact_mapping_multiple','candidate_provider_ids',to_jsonb(v_ids));
 else
  with candidates as (
   select p.id from catalogue.providers p join ref.countries c on c.id=p.country_id
   where upper(c.iso_alpha2)=upper(coalesce(p_country_code,'')) and (
    security.provider_contact_normalise(p.canonical_name)=v_norm or security.provider_contact_normalise(p.display_name)=v_norm)
   union
   select a.provider_id from catalogue.provider_aliases a join catalogue.providers p on p.id=a.provider_id
   join ref.countries c on c.id=p.country_id
   where upper(c.iso_alpha2)=upper(coalesce(p_country_code,'')) and security.provider_contact_normalise(a.alias)=v_norm
  )
  select array_agg(distinct id) into v_ids from candidates;
  v_count:=coalesce(cardinality(v_ids),0);
  if v_count=0 then return jsonb_build_object('state','unmatched','reason','no_provider_match','normalized_label',v_norm);
  elsif v_count>1 then return jsonb_build_object('state','ambiguous','reason','multiple_provider_matches','normalized_label',v_norm,'candidate_provider_ids',to_jsonb(v_ids));
  end if;
  v_provider_id:=v_ids[1];v_reason:='catalogue_or_alias';
 end if;
 select p.canonical_name,p.stable_key into v_provider_name,v_stable_key from catalogue.providers p where p.id=v_provider_id;
 return jsonb_build_object('state','mapped','provider_id',v_provider_id,'provider_name',v_provider_name,'stable_key',v_stable_key,'reason',v_reason,'normalized_label',v_norm);
end $$;


ALTER FUNCTION "security"."provider_contact_provider_map"("p_country_code" "text", "p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_contact_reconciliation_decide_impl"("p_review_item_id" "uuid", "p_action" "text", "p_reason" "text", "p_target_provider_id" "uuid" DEFAULT NULL::"uuid", "p_target_contact_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'auth'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_rank int;
  v_item pipeline.layer4_review_items%rowtype;
  v_row pipeline.provider_contact_import_rows%rowtype;
  v_batch pipeline.provider_contact_import_batches%rowtype;
  v_contact pipeline.provider_contacts%rowtype;
  v_version pipeline.provider_contact_versions%rowtype;
  v_contact_id uuid;
  v_version_id uuid;
  v_decision_id uuid;
  v_identity text;
  v_core_in text;
  v_core_current text;
  v_status text;
  v_final jsonb;
  v_candidate_ok boolean:=false;
  v_remaining int:=0;
  v_record_type text;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
  if p_action not in ('merge_existing','accept_incoming','keep_existing','keep_separate','map_provider_apply','reject_import') then
    raise exception 'invalid Provider Contact reconciliation action';
  end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'decision reason required'; end if;

  select * into v_item from pipeline.layer4_review_items where id=p_review_item_id for update;
  if not found then raise exception 'review item not found'; end if;
  if v_item.status<>'pending' then raise exception 'review item already decided'; end if;
  if v_item.entity_type<>'provider_contact_import_row' or v_item.field_code<>'provider_contact_reconciliation' then
    raise exception 'review item is not a Provider Contact reconciliation';
  end if;

  select * into v_row from pipeline.provider_contact_import_rows where id=v_item.entity_id for update;
  if not found then raise exception 'Provider Contact import row not found'; end if;
  select * into v_batch from pipeline.provider_contact_import_batches where id=v_row.batch_id;

  v_record_type:=coalesce(nullif(v_row.source_payload->>'contact_record_type',''),'named_staff');

  if p_action='map_provider_apply' then
    if p_target_provider_id is null then raise exception 'target Provider required'; end if;
    select exists(
      select 1 from jsonb_array_elements(coalesce(v_item.layer2_state->'candidate_providers','[]'::jsonb)) x
      where nullif(x->>'provider_id','')::uuid=p_target_provider_id
    ) into v_candidate_ok;
    if not v_candidate_ok then raise exception 'target Provider is not an approved ambiguity candidate'; end if;

    v_identity:=security.provider_contact_identity_key(
      v_record_type,
      v_row.normalized_payload->>'full_name',
      v_row.normalized_payload->>'job_title',
      v_row.normalized_payload->>'region_scope',
      v_row.normalized_payload->>'work_email',
      v_row.normalized_payload->>'source_url'
    );
    if v_identity is null then raise exception 'resolved Provider row has insufficient contact identity'; end if;

    update pipeline.provider_contact_import_rows
    set mapped_provider_id=p_target_provider_id,mapping_state='mapped',
        logical_key=p_target_provider_id::text||'|'||v_identity
    where id=v_row.id;

    select * into v_contact
    from pipeline.provider_contacts
    where provider_id=p_target_provider_id and identity_key=v_identity
    limit 1;

    if found then
      v_contact_id:=v_contact.id;
      select * into v_version from pipeline.provider_contact_versions where id=v_contact.current_version_id;
      v_core_current:=security.provider_contact_core_hash(jsonb_build_object(
        'full_name',v_version.full_name,'team_name',v_version.team_name,'job_title',v_version.job_title,
        'functional_area',v_version.functional_area,'region_scope',v_version.region_scope,
        'countries_or_markets',v_version.countries_or_markets,'work_email',v_version.work_email,
        'work_phone',v_version.work_phone,'staff_location',v_version.staff_location,
        'verification_state',v_version.verification_state,
        'verified_on',case when v_version.verified_on is null then null else v_version.verified_on::text end,
        'source_url',v_version.source_url
      ));
      v_core_in:=security.provider_contact_core_hash(v_row.normalized_payload);
      if v_core_current is distinct from v_core_in then
        v_version_id:=security.provider_contact_append_version(
          v_contact_id,v_actor,v_row.normalized_payload,'import','first_party',
          'Layer 4 Provider mapping accepted incoming contact',v_row.batch_id,v_row.id,v_batch.evidence_artifact_id,null
        );
      else
        v_version_id:=v_contact.current_version_id;
      end if;
    else
      insert into pipeline.provider_contacts(
        provider_id,record_type,lifecycle_status,identity_key,created_by,updated_by,metadata
      ) values (
        p_target_provider_id,v_record_type,'active',v_identity,v_actor,v_actor,
        jsonb_build_object('origin','layer4_contact_reconciliation','import_batch_id',v_row.batch_id,'change_control','CF-CHG-20260902-080')
      ) returning id into v_contact_id;
      v_version_id:=security.provider_contact_append_version(
        v_contact_id,v_actor,v_row.normalized_payload,'import','first_party',
        'Layer 4 Provider mapping created contact',v_row.batch_id,v_row.id,v_batch.evidence_artifact_id,null
      );
    end if;

    update pipeline.provider_contact_import_rows
    set matched_contact_id=v_contact_id,applied_action='layer4_map_provider_apply',applied_at=now()
    where id=v_row.id;

  elsif p_action in ('merge_existing','accept_incoming') then
    if p_target_contact_id is not null then
      select * into v_contact from pipeline.provider_contacts where id=p_target_contact_id;
      if not found then raise exception 'target managed contact not found'; end if;
      if v_row.mapped_provider_id is not null and v_contact.provider_id<>v_row.mapped_provider_id then
        raise exception 'target managed contact belongs to a different Provider';
      end if;
      v_contact_id:=v_contact.id;
    else
      v_identity:=split_part(coalesce(v_row.logical_key,''),'|',2);
      if v_row.mapped_provider_id is not null and v_identity<>'' then
        select * into v_contact from pipeline.provider_contacts
        where provider_id=v_row.mapped_provider_id and identity_key=v_identity limit 1;
        if found then v_contact_id:=v_contact.id; end if;
      end if;
      if v_contact_id is null and v_row.matched_contact_id is not null then
        v_contact_id:=v_row.matched_contact_id;
        select * into v_contact from pipeline.provider_contacts where id=v_contact_id;
      end if;
    end if;

    if v_contact_id is null then
      raise exception 'apply deterministic import rows before resolving this duplicate/merge candidate';
    end if;

    if p_action='accept_incoming' then
      v_version_id:=security.provider_contact_append_version(
        v_contact_id,v_actor,v_row.normalized_payload,'import','first_party',
        'Layer 4 accepted incoming Provider Contact version',v_row.batch_id,v_row.id,v_batch.evidence_artifact_id,null
      );
      update pipeline.provider_contact_import_rows
      set matched_contact_id=v_contact_id,applied_action='layer4_accept_incoming',applied_at=now()
      where id=v_row.id;
    else
      update pipeline.provider_contact_import_rows
      set matched_contact_id=v_contact_id,applied_action='layer4_merge_existing',applied_at=now()
      where id=v_row.id;
    end if;

  elsif p_action='keep_existing' then
    update pipeline.provider_contact_import_rows
    set applied_action='layer4_keep_existing',applied_at=now()
    where id=v_row.id;

  elsif p_action='reject_import' then
    update pipeline.provider_contact_import_rows
    set applied_action='layer4_reject_import',applied_at=now()
    where id=v_row.id;

  elsif p_action='keep_separate' then
    if v_row.mapped_provider_id is null then
      raise exception 'map the Provider before keeping this contact separate';
    end if;

    insert into pipeline.provider_contacts(
      provider_id,record_type,lifecycle_status,identity_key,created_by,updated_by,metadata
    ) values (
      v_row.mapped_provider_id,v_record_type,'active','exception:'||v_row.id::text,v_actor,v_actor,
      jsonb_build_object(
        'origin','layer4_contact_reconciliation','identity_exception',true,
        'import_batch_id',v_row.batch_id,'import_row_id',v_row.id,'change_control','CF-CHG-20260902-080'
      )
    ) returning id into v_contact_id;

    insert into pipeline.provider_contact_versions(
      contact_id,version_no,full_name,team_name,job_title,functional_area,region_scope,countries_or_markets,
      work_email,work_phone,staff_location,verification_state,verified_on,source_class,source_authority,
      source_url,source_page_title,source_notes,evidence_id,import_batch_id,import_row_id,content_hash,
      effective_from,change_reason,created_at,created_by,metadata
    ) values (
      v_contact_id,1,
      nullif(v_row.normalized_payload->>'full_name',''),
      nullif(v_row.normalized_payload->>'team_name',''),
      nullif(v_row.normalized_payload->>'job_title',''),
      nullif(v_row.normalized_payload->>'functional_area',''),
      nullif(v_row.normalized_payload->>'region_scope',''),
      nullif(v_row.normalized_payload->>'countries_or_markets',''),
      nullif(v_row.normalized_payload->>'work_email',''),
      nullif(v_row.normalized_payload->>'work_phone',''),
      nullif(v_row.normalized_payload->>'staff_location',''),
      nullif(v_row.normalized_payload->>'verification_state',''),
      nullif(v_row.normalized_payload->>'verified_on','')::date,
      'import','first_party',
      nullif(v_row.normalized_payload->>'source_url',''),
      nullif(v_row.normalized_payload->>'source_page_title',''),
      nullif(v_row.normalized_payload->>'source_notes',''),
      v_batch.evidence_artifact_id,v_row.batch_id,v_row.id,
      security.provider_contact_payload_hash(v_row.normalized_payload),
      now(),'Layer 4 kept duplicate candidate as separate contact',now(),v_actor,
      jsonb_build_object('change_control','CF-CHG-20260902-080','identity_exception',true)
    ) returning id into v_version_id;

    update pipeline.provider_contacts
    set current_version_id=v_version_id,updated_at=now(),updated_by=v_actor
    where id=v_contact_id;

    update pipeline.provider_contact_import_rows
    set matched_contact_id=v_contact_id,applied_action='layer4_keep_separate',applied_at=now()
    where id=v_row.id;
  end if;

  v_status:=case when p_action='reject_import' then 'rejected' else 'approved' end;
  v_final:=jsonb_strip_nulls(jsonb_build_object(
    'reconciliation_action',p_action,
    'target_provider_id',p_target_provider_id,
    'target_contact_id',coalesce(p_target_contact_id,v_contact_id),
    'result_version_id',v_version_id
  ));

  update pipeline.layer4_review_items
  set status=v_status,decided_at=now()
  where id=v_item.id;

  insert into pipeline.layer4_decisions(
    review_item_id,action,actor_id,reason,before_value,proposed_value,final_value,evidence_id,
    layer2_state,layer3_state,change_control_ref
  ) values (
    v_item.id,p_action,v_actor,trim(p_reason),v_item.before_value,v_item.proposed_value,v_final,
    v_item.evidence_id,v_item.layer2_state,v_item.layer3_state,'CF-CHG-20260902-080'
  ) returning id into v_decision_id;

  insert into pipeline.provider_contact_audit_events(
    contact_id,batch_id,event_type,actor_id,reason,after_version_id,metadata
  ) values (
    coalesce(v_contact_id,v_row.matched_contact_id),v_row.batch_id,'layer4_reconciliation',v_actor,trim(p_reason),v_version_id,
    jsonb_build_object(
      'layer4_review_item_id',v_item.id,'layer4_decision_id',v_decision_id,
      'action',p_action,'import_row_id',v_row.id,'change_control','CF-CHG-20260902-080'
    )
  );

  select count(*) into v_remaining
  from pipeline.provider_contact_import_rows r
  join pipeline.layer4_review_items l on l.id=r.layer4_review_item_id
  where r.batch_id=v_row.batch_id and l.status='pending';

  if v_batch.status='applied_with_review_pending' and v_remaining=0 then
    update pipeline.provider_contact_import_batches
    set status='applied',
        apply_summary=coalesce(apply_summary,'{}'::jsonb)||
          jsonb_build_object(
            'layer4_review_pending',0,
            'layer4_resolved',(select count(*) from pipeline.provider_contact_import_rows r
              join pipeline.layer4_review_items l on l.id=r.layer4_review_item_id
              where r.batch_id=v_row.batch_id and l.status<>'pending')
          )
    where id=v_row.batch_id;
  else
    update pipeline.provider_contact_import_batches
    set apply_summary=coalesce(apply_summary,'{}'::jsonb)||jsonb_build_object('layer4_review_pending',v_remaining)
    where id=v_row.batch_id;
  end if;

  return jsonb_build_object(
    'ok',true,'review_item_id',v_item.id,'decision_id',v_decision_id,'action',p_action,
    'status',v_status,'import_row_id',v_row.id,'contact_id',coalesce(v_contact_id,v_row.matched_contact_id),
    'version_id',v_version_id,'layer4_review_remaining',v_remaining
  );
end $$;


ALTER FUNCTION "security"."provider_contact_reconciliation_decide_impl"("p_review_item_id" "uuid", "p_action" "text", "p_reason" "text", "p_target_provider_id" "uuid", "p_target_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_course_whole_fees_v1"("p_provider_id" "uuid") RETURNS TABLE("provider_id" "uuid", "course_id" "uuid", "title" "text", "level_code" "text", "country_currency" "text", "currency_code" "text", "whole_fee" numeric, "source" "text", "fee_amount" numeric, "fee_basis" "text", "fee_year" integer, "years" numeric, "years_from" "text", "register_as_of" "date", "skip" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with st as (select * from pipeline.provider_fee_range_settings where id = 1),
  c as (
    select co.id, co.provider_id, co.canonical_title, sl.code level_code, cn.default_currency_code ccy,
           case co.duration_unit when 'weeks' then co.duration_value / 52.0 when 'months' then co.duration_value / 12.0 when 'years' then co.duration_value
                                 when 'semesters' then co.duration_value / 2.0 when 'trimesters' then co.duration_value / 3.0 end cat_years,
           pg.candidates->'adapter_extra' ax
      from catalogue.courses co
      join catalogue.providers p on p.id = co.provider_id
      join ref.countries cn on cn.id = p.country_id
      join ref.study_levels sl on sl.id = co.study_level_id
      cross join st
      left join pipeline.coverage_course_pages pg on pg.course_id = co.id
     where (p_provider_id is null or co.provider_id = p_provider_id)
       and co.lifecycle_status = 'active' and co.open_to_international is not false
       and sl.code <> all (st.excluded_level_codes)
       and not security.uni_adapter_excluded(co.id, 'fee')),
  cur as (
    select distinct on (f.course_id) f.course_id, f.amount, f.basis, coalesce(f.fee_year, extract(year from now())::int) fy, f.currency_code
      from catalogue.course_fees f join c on c.id = f.course_id cross join st
     where f.fee_type = 'provider_current_tuition' and f.status = 'active' and f.audience in ('international', 'all') and f.amount > 0
       and coalesce(f.fee_year, extract(year from now())::int) between st.min_fee_year and extract(year from now())::int + 1
     order by f.course_id, coalesce(f.fee_year, extract(year from now())::int) desc, (f.basis = 'total_indicative') desc, f.amount desc),
  reg as (
    select distinct on (f.course_id) f.course_id, f.amount, f.currency_code, coalesce(f.source_snapshot_at::date, f.valid_from) as_of
      from catalogue.course_fees f join c on c.id = f.course_id
     where f.fee_type = 'tuition' and f.basis = 'registered_total_course' and f.status = 'active' and f.audience in ('international', 'all') and f.amount > 0
     order by f.course_id, coalesce(f.source_snapshot_at::date, f.valid_from) desc nulls last, f.amount desc),
  y as (
    select c.*, security.course_years_from_text(c.ax->>'course_years') ax_years, security.course_years_from_text(c.ax->>'duration') ax_dur from c),
  x as (
    select y.*, coalesce(round(y.cat_years, 2), y.ax_years, y.ax_dur) yrs,
           case when y.cat_years is not null then 'catalogue' when y.ax_years is not null then 'course page (years)' when y.ax_dur is not null then 'course page (duration)' end yfrom,
           cur.amount c_amt, cur.basis c_basis, cur.fy c_fy, cur.currency_code c_ccy, reg.amount r_amt, reg.currency_code r_ccy, reg.as_of r_asof
      from y left join cur on cur.course_id = y.id left join reg on reg.course_id = y.id
     where cur.course_id is not null or reg.course_id is not null),
  z as (
    select x.*,
           case when x.c_amt is not null and x.c_basis = 'total_indicative' then 'current_total'
                when x.c_amt is not null and x.yrs is not null then 'current_annual_x_years'
                when x.r_amt is not null then 'register_total' end src,
           case x.c_basis when 'per_semester' then 2 when 'per_trimester' then 3 else 1 end per_year
      from x)
  select z.provider_id, z.id, z.canonical_title, z.level_code, z.ccy,
         case z.src when 'register_total' then z.r_ccy else z.c_ccy end,
         case z.src when 'current_total' then z.c_amt when 'current_annual_x_years' then round(z.c_amt * z.per_year * z.yrs, 2) when 'register_total' then z.r_amt end,
         z.src,
         case z.src when 'register_total' then z.r_amt else z.c_amt end,
         case z.src when 'register_total' then 'registered_total_course' else z.c_basis end,
         case when z.src in ('current_total', 'current_annual_x_years') then z.c_fy end,
         z.yrs, z.yfrom,
         case when z.src = 'register_total' then z.r_asof end,
         case when z.src is null then 'no_course_length'
              when (case z.src when 'register_total' then z.r_ccy else z.c_ccy end) is distinct from z.ccy then 'other_currency'
              when not st.include_under_one_year and z.yrs is not null and z.yrs < 1 then 'under_one_year'
              when (case z.src when 'current_total' then z.c_amt when 'current_annual_x_years' then round(z.c_amt * z.per_year * z.yrs, 2) when 'register_total' then z.r_amt end) < st.min_whole_fee then 'below_floor' end
    from z cross join (select * from pipeline.provider_fee_range_settings where id = 1) st
$$;


ALTER FUNCTION "security"."provider_course_whole_fees_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_credit_fee_apply_v1"("p_rule_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.provider_credit_fees%rowtype; v_ev uuid; v_hash text; v_src uuid; v_fee numeric; c uuid; v_cur numeric;
        v_done int := 0; v_same int := 0; v_skip int := 0; v_err int := 0; v_last text; v_courses uuid[] := '{}';
begin
  select * into r from pipeline.provider_credit_fees where id = p_rule_id;
  if r.id is null then raise exception 'unknown credit fee rule'; end if;
  if not r.active then return jsonb_build_object('ok', false, 'note', 'the rule is switched off'); end if;
  v_ev := coalesce(r.evidence_id, (select s.evidence_id from pipeline.provider_fact_sources s where s.id = r.fact_source_id));
  if v_ev is null then raise exception 'the rate page has not been read yet (no evidence)'; end if;
  select e.content_hash into v_hash from pipeline.evidence_artifacts e where e.id = v_ev;
  v_fee := round(r.rate / r.rate_credits * r.annual_credits, 2);
  if v_fee not between 1000 and 500000 then raise exception 'the annual fee % is outside 1,000 to 500,000', v_fee; end if;
  v_src := security.coverage_sweep_source(r.provider_id);
  insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
    select 'courses', 'provider_current_tuition', v_src, 'approved', 'CF-CHG-20260915-247, Decision 254, Platform Admin 5 Oct 2026 13:25 (fees per credit)', now(), now(), now()
    where not exists (select 1 from search.enrichment_source_gates g where g.projection_code = 'courses' and g.domain_code = 'provider_current_tuition' and g.source_id = v_src);
  foreach c in array r.course_ids loop
    if not exists (select 1 from catalogue.courses co where co.id = c and co.provider_id = r.provider_id and co.lifecycle_status = 'active')
       or security.uni_adapter_excluded(c, 'fee')
       or exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c and k.field in ('tuition', 'fee', 'fees')) then
      v_skip := v_skip + 1;
      continue;
    end if;
    select f.amount into v_cur from catalogue.course_fees f where f.course_id = c and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and coalesce(f.fee_year, 0) = r.fee_year order by f.updated_at desc nulls last limit 1;
    if v_cur = v_fee then v_same := v_same + 1; continue; end if;
    begin
      update catalogue.course_fees set status = 'superseded', updated_at = now() where course_id = c and status = 'active' and fee_type = 'provider_current_tuition' and audience = 'international' and source_id is not null and coalesce(fee_year, 0) = r.fee_year and amount <> v_fee;
      perform security.coverage_apply_course_v1(c, v_src, v_ev, r.source_url, v_hash, jsonb_build_object('fee_amount', v_fee, 'fee_year', r.fee_year, 'currency_code', r.currency_code, 'fee_basis', 'annual', 'audience', 'international',
                 'fee_notes', 'Per-credit rate x credits in a full-time year: ' || r.rate || ' per ' || r.rate_credits || ' credits x ' || r.annual_credits || ' credits (' || r.label || ')',
                 'fee_key', 'credit-fee:' || r.id || ':' || c || ':' || r.fee_year));
      insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url)
        values (c, r.provider_id, 'fee', to_jsonb(v_cur), jsonb_build_object('amount', v_fee, 'year', r.fee_year, 'currency', r.currency_code, 'formula', jsonb_build_object('rate', r.rate, 'rate_credits', r.rate_credits, 'annual_credits', r.annual_credits), 'rule_id', r.id), v_ev, r.source_url);
      v_done := v_done + 1; v_courses := v_courses || c;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if cardinality(v_courses) > 0 then
    perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
    foreach c in array v_courses loop perform scholarship.refresh_course_financial_calculations(c, null); end loop;
  end if;
  update pipeline.provider_credit_fees set applied_at = now(), last_result = jsonb_build_object('fee', v_fee, 'written', v_done, 'same', v_same, 'skipped', v_skip, 'errors', v_err, 'last_error', v_last) where id = r.id;
  return jsonb_build_object('fee', v_fee, 'written', v_done, 'same', v_same, 'skipped', v_skip, 'errors', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "security"."provider_credit_fee_apply_v1"("p_rule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_english_apply_all_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare r record; v jsonb; v_total int := 0; v_n int := 0; v_failed int := 0;
begin
  for r in select id from pipeline.provider_policy_proposals where kind = 'english_policy' and status = 'approved' order by decided_at loop
    begin
      v := security.provider_english_apply_v1(r.id); v_total := v_total + coalesce((v->>'written')::int, 0); v_n := v_n + 1;
    exception when others then
      v_failed := v_failed + 1;
      update pipeline.provider_policy_proposals set apply_summary = coalesce(apply_summary, '{}'::jsonb) || jsonb_build_object('last_error', left(sqlerrm, 200), 'last_failed_at', now()), updated_at = now() where id = r.id;
    end;
  end loop;
  return jsonb_build_object('proposals', v_n, 'written', v_total, 'not_applied', v_failed);
end $$;


ALTER FUNCTION "security"."provider_english_apply_all_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_english_apply_v1"("p_proposal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security', 'search'
    AS $$
declare x pipeline.provider_policy_proposals%rowtype; v_src uuid; v_name text; r record; v_ok int := 0; v_err int := 0; v_courses uuid[] := '{}'; v_last text;
  v_flag boolean; v_flagged int := 0;
begin
  select * into x from pipeline.provider_policy_proposals where id = p_proposal_id;
  if x.id is null or x.kind <> 'english_policy' then raise exception 'not an English policy proposal'; end if;
  if x.status <> 'approved' then raise exception 'proposal is not approved'; end if;
  if x.evidence_id is null then
    select fs.evidence_id into x.evidence_id from pipeline.provider_fact_sources fs where fs.id = x.fact_source_id and fs.url = x.url and fs.evidence_id is not null;
  end if;
  if x.evidence_id is null or coalesce(x.content_hash, '') = '' then raise exception 'the policy document has no stored evidence'; end if;
  v_src := security.coverage_sweep_source(x.provider_id);
  select coalesce(p.display_name, p.canonical_name) into v_name from catalogue.providers p where p.id = x.provider_id;
  v_flag := security.provider_english_flagged(x.proposal);
  -- courses open to international students first
  for r in select pl.* from security.provider_english_plan_v1(p_proposal_id) pl join catalogue.courses co on co.id = pl.course_id
            where pl.outcome = 'write' order by co.open_to_international desc nulls last, pl.title loop
    begin
      perform security.coverage_apply_course_v1(r.course_id, v_src, x.evidence_id, x.url, x.content_hash,
        jsonb_build_object('english_requirements', (select jsonb_agg(jsonb_build_object(
            'test_code', q->>'test_code', 'overall_score', q->'overall_score', 'component_scores', coalesce(q->'component_scores', '{}'::jsonb),
            'source_requirement_key', 'policy:' || x.id || ':' || lower(q->>'test_code'),
            'notes', case when r.plan = 'named' then 'From ' || v_name || '''s English language policy, which names this course (approved by a Platform Admin, Decision 227)'
                          else 'Default for ' || case when r.study_level in ('graduate_certificate', 'graduate_diploma', 'masters', 'masters_coursework', 'masters_extended') then 'postgraduate coursework' else 'undergraduate' end
                               || ' courses in ' || v_name || '''s English language policy (approved by a Platform Admin, Decision 227)'
                               || case when v_flag then '. Flagged: this is the university standard; the policy says some courses need more and does not list them, so check the course page' else '' end end))
          from jsonb_array_elements(r.requirements) q where q->>'test_code' in (select code from ref.english_tests))));
      if v_flag and r.plan <> 'named' then
        update catalogue.course_english_requirements set confidence = 0.6
         where course_id = r.course_id and source_requirement_key like 'policy:' || x.id || ':%';
        v_flagged := v_flagged + 1;
      end if;
      v_ok := v_ok + 1; v_courses := v_courses || r.course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if v_ok > 0 then
    insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
    select 'courses', 'course_english', v_src, 'approved', 'CF-CHG-20260915-247; Decision 227 (English from the provider''s policy, approved by a Platform Admin)', now(), now(), now()
     where not exists (select 1 from search.enrichment_source_gates g where g.projection_code = 'courses' and g.domain_code = 'course_english' and g.source_id = v_src);
    perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
  end if;
  update pipeline.provider_policy_proposals
     set apply_summary = coalesce(apply_summary, '{}'::jsonb) || jsonb_build_object('written', coalesce((apply_summary->>'written')::int, 0) + v_ok,
           'refused', v_err, 'last_error', v_last, 'last_applied_at', now(),
           'flagged', coalesce((apply_summary->>'flagged')::int, 0) + v_flagged), updated_at = now()
   where id = p_proposal_id;
  return jsonb_build_object('written', v_ok, 'refused', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "security"."provider_english_apply_v1"("p_proposal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_english_flagged"("p_proposal" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce((p_proposal->>'flag_standard')::boolean, false)
      or coalesce(p_proposal->'caveats', '[]'::jsonb) ?| array['higher_unlisted', 'exceptions_unlisted', 'level_not_stated']
$$;


ALTER FUNCTION "security"."provider_english_flagged"("p_proposal" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_english_plan_v1"("p_proposal_id" "uuid") RETURNS TABLE("course_id" "uuid", "title" "text", "study_level" "text", "plan" "text", "reason" "text", "requirements" "jsonb", "existing" "jsonb", "outcome" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'ref', 'security'
    AS $$
declare x pipeline.provider_policy_proposals%rowtype; v_named jsonb; v_defaults jsonb;
begin
  select * into x from pipeline.provider_policy_proposals where id = p_proposal_id;
  if x.id is null or x.kind <> 'english_policy' then raise exception 'not an English policy proposal'; end if;
  v_defaults := coalesce(x.proposal->'defaults', '{}'::jsonb);
  select coalesce(jsonb_agg(jsonb_build_object('k', s.k, 'reqs', s.reqs)), '[]'::jsonb) into v_named from (
    select security.english_title_key(n) k, null::jsonb reqs from jsonb_array_elements_text(coalesce(x.proposal->'named', '[]'::jsonb)) n
    union all
    select security.english_title_key(e->>'name'), case when jsonb_typeof(e->'reqs') = 'array' and jsonb_array_length(e->'reqs') > 0
                                                       then (select jsonb_agg(q - 'quote') from jsonb_array_elements(e->'reqs') q) end
      from jsonb_array_elements(coalesce(x.proposal->'exceptions', '[]'::jsonb)) e) s where length(s.k) >= 4;
  return query
  with named as materialized (
    select e->>'k' k, nullif(e->'reqs', 'null'::jsonb) reqs,
           array(select distinct t from unnest(regexp_split_to_array(e->>'k', '[ /]+')) t where t not in ('of', 'and', 'in', 'the', '')) toks
      from jsonb_array_elements(v_named) e),
  c0 as materialized (
    select co.id, co.canonical_title t, security.english_title_key(co.canonical_title) k, sl.code lvl
      from catalogue.courses co left join ref.study_levels sl on sl.id = co.study_level_id
     where co.provider_id = x.provider_id and co.lifecycle_status = 'active'),
  c as materialized (
    select c0.*, array(select distinct t from unnest(regexp_split_to_array(c0.k, '[ /]+')) t where t not in ('of', 'and', 'in', 'the', '')) toks,
           case when c0.lvl in ('bachelor', 'bachelor_honours', 'associate_degree') then 'undergraduate'
                when c0.lvl in ('graduate_certificate', 'graduate_diploma', 'masters', 'masters_coursework', 'masters_extended') then 'postgraduate' end grp,
           (select coalesce(jsonb_object_agg(et.code, r.overall_score), '{}'::jsonb) from catalogue.course_english_requirements r
              join ref.english_tests et on et.id = r.english_test_id where r.course_id = c0.id and r.status = 'active') ex,
           exists (select 1 from catalogue.course_english_requirements r where r.course_id = c0.id) any_row,
           exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = c0.id and l.field in ('english', 'english_requirements', 'course_english')) locked,
           exists (select 1 from pipeline.layer4_review_items i where i.entity_type = 'course' and i.entity_id = c0.id and i.field_code = 'course_english' and i.status = 'pending') in_review,
           exists (select 1 from pipeline.layer3_fact_handoffs h left join pipeline.layer3_work_items w on w.id = h.work_item_id
                    where h.course_id = c0.id and h.task_class = 'provider_english_validation'
                      and (h.work_item_id is null or w.status in ('interpreting', 'validated', 'queued', 'pending'))) in_l3,
           exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c0.id and g.status in ('bound', 'ambiguous')
                      and (g.read_status is null or g.read_status = 'needs_render')) page_waiting
      from c0),
  m as (
    select c.*,
           (select jsonb_agg(distinct named.reqs) from named where named.k = c.k and named.reqs is not null) exact_reqs,
           exists (select 1 from named where named.k = c.k) exact_named,
           exists (select 1 from named where named.k <> c.k and (position(named.k in c.k) > 0 or position(c.k in named.k) > 0
                     or (cardinality(c.toks) > 0 and cardinality(named.toks) > 0
                         and (select count(*) from unnest(c.toks) t where t = any(named.toks))::numeric / greatest(cardinality(c.toks), cardinality(named.toks)) >= 0.75))) close_named,
           case when c.grp is not null then v_defaults->c.grp end dflt
      from c),
  p as (
    select m.*,
           case when m.lvl is null then 'held|study level unknown'
                when m.lvl in ('doctorate', 'masters_research') then 'held|research degree'
                when m.t ~* 'exit award' then 'held|exit award only'
                when m.k ~ '/' or m.k ~ ' and (bachelor|master|doctor|graduate|diploma|associate) (of|in) ' then 'held|double degree'
                when m.exact_reqs is not null and jsonb_array_length(m.exact_reqs) > 1 then 'held|the policy gives this course more than one requirement'
                when m.exact_reqs is not null then 'named|'
                when m.exact_named or m.close_named then 'held|named in the policy (it may have its own requirement)'
                when m.grp is null then 'held|level not covered by the policy default'
                when m.dflt is null or jsonb_typeof(m.dflt) <> 'array' then 'held|the policy gives no default for this level'
                else 'default|' end pr
      from m),
  q as (
    select p.*, split_part(p.pr, '|', 1) pl, nullif(split_part(p.pr, '|', 2), '') rs,
           case when p.pr like 'named|%' then p.exact_reqs->0 when p.pr like 'default|%' then p.dflt end reqs
      from p)
  select q.id, q.t, q.lvl, q.pl, q.rs, q.reqs, q.ex,
         case when q.pl = 'held' then 'held'
              when q.any_row and exists (select 1 from jsonb_array_elements(q.reqs) r where q.ex ? (r->>'test_code') and (q.ex->>(r->>'test_code'))::numeric <> (r->>'overall_score')::numeric) then 'differs'
              when q.any_row and exists (select 1 from jsonb_array_elements(q.reqs) r where q.ex ? (r->>'test_code')) then 'agrees'
              when q.any_row then 'other_value'
              when q.locked then 'set_by_hand'
              when q.in_review then 'in_review'
              when q.in_l3 or q.page_waiting then 'waiting'
              else 'write' end
    from q;
end $$;


ALTER FUNCTION "security"."provider_english_plan_v1"("p_proposal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_fee_proposal_rows"("p_source_id" "uuid") RETURNS TABLE("row_id" "uuid", "course_code" "text", "course_id" "uuid", "course_title" "text", "amount" numeric, "currency_code" "text", "basis" "text", "fee_year" integer, "current_amount" numeric, "current_basis" "text", "outcome" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with f as (select * from pipeline.provider_fact_sources where id = p_source_id),
  r as (
    select fr.*, c.id cid, c.canonical_title,
           min(fr.amount) over (partition by fr.course_code, fr.basis) amin, max(fr.amount) over (partition by fr.course_code, fr.basis) amax,
           bool_or(fr.basis = 'annual') over (partition by fr.course_code) has_annual,
           count(*) over (partition by fr.course_code, fr.basis) rcnt
      from pipeline.provider_fee_rows fr join f on f.id = fr.source_id
      left join catalogue.courses c on c.provider_id = fr.provider_id and upper(btrim(c.course_code)) = fr.course_code and c.lifecycle_status = 'active'
     where fr.current)
  select r.id, r.course_code, r.cid, r.canonical_title, r.amount, r.currency_code, r.basis, r.fee_year, cur.amount, cur.basis,
         case when r.cid is null then 'no_course'
              when r.basis not in ('annual','total_indicative') then 'basis_not_used'
              when r.basis = 'total_indicative' and r.has_annual then 'annual_used'
              when r.basis = 'annual' and r.rcnt = 2 and r.amax = 8 * r.amin and r.amount = r.amin then 'per_unit_row'
              when r.amin <> r.amax and not (r.basis = 'annual' and r.rcnt = 2 and r.amax = 8 * r.amin) then 'several_amounts'
              when cur.amount is not null and cur.amount = r.amount then 'same'
              when cur.amount is not null then 'differs'
              when exists (select 1 from pipeline.layer4_review_items l where l.entity_type = 'course' and l.entity_id = r.cid
                             and l.field_code = 'provider_current_tuition_validation' and l.status = 'pending') then 'in_review'
              else 'new' end
    from r
    left join lateral (select x.amount, x.basis from catalogue.course_fees x where x.course_id = r.cid and x.fee_type = 'provider_current_tuition'
                         and x.status = 'active' order by x.updated_at desc limit 1) cur on true
$$;


ALTER FUNCTION "security"."provider_fee_proposal_rows"("p_source_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_fee_range_json_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('provider_id', r.provider_id, 'name', coalesce(p.display_name, p.canonical_name), 'country', trim(cn.iso_alpha2::text),
           'currency', coalesce(r.currency_code, cn.default_currency_code),
           'low', coalesce(r.manual_low, r.low_amount), 'high', coalesce(r.manual_high, r.high_amount),
           'by_hand', r.manual_low is not null or r.manual_high is not null,
           'computed', jsonb_build_object('low', r.low_amount, 'high', r.high_amount, 'low_course_id', r.low_course_id, 'high_course_id', r.high_course_id,
                         'low_course', lc.canonical_title, 'high_course', hc.canonical_title, 'low_source', r.low_source, 'high_source', r.high_source,
                         'courses', r.course_count, 'sources', r.source_counts, 'skipped', r.skipped, 'fee_year_from', r.fee_year_from, 'fee_year_to', r.fee_year_to,
                         'register_as_of', r.register_as_of, 'meets_minimum', r.meets_minimum, 'computed_at', r.computed_at),
           'manual', jsonb_build_object('low', r.manual_low, 'high', r.manual_high, 'note', r.manual_note, 'at', r.manual_at),
           'published', r.published, 'published_at', r.published_at, 'publish_reason', r.publish_reason)
    from catalogue.provider_fee_ranges r join catalogue.providers p on p.id = r.provider_id join ref.countries cn on cn.id = p.country_id
    left join catalogue.courses lc on lc.id = r.low_course_id left join catalogue.courses hc on hc.id = r.high_course_id
   where r.provider_id = p_provider_id
$$;


ALTER FUNCTION "security"."provider_fee_range_json_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_fee_ranges_refresh_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int; v_min int := (select s.min_courses from pipeline.provider_fee_range_settings s where s.id = 1);
begin
  with rws as materialized (select * from security.provider_course_whole_fees_v1(p_provider_id)),
  w as (select * from rws r where r.skip is null),
  a as (
    select w.provider_id, max(w.country_currency) ccy, count(*) n, min(w.whole_fee) lo, max(w.whole_fee) hi,
           jsonb_build_object('current_total', count(*) filter (where w.source = 'current_total'),
                              'current_annual_x_years', count(*) filter (where w.source = 'current_annual_x_years'),
                              'register_total', count(*) filter (where w.source = 'register_total')) sc,
           min(w.fee_year) fy_from, max(w.fee_year) fy_to, max(w.register_as_of) reg_asof
      from w group by w.provider_id),
  lo as (select distinct on (w.provider_id) w.provider_id, w.course_id, w.source from w order by w.provider_id, w.whole_fee asc, w.course_id),
  hi as (select distinct on (w.provider_id) w.provider_id, w.course_id, w.source from w order by w.provider_id, w.whole_fee desc, w.course_id),
  sk as (select k.provider_id, jsonb_object_agg(k.skip, k.n) j from (select r.provider_id, r.skip, count(*) n from rws r where r.skip is not null group by 1, 2) k group by k.provider_id),
  allp as (select r.provider_id from rws r group by r.provider_id
           union select f.provider_id from catalogue.provider_fee_ranges f where p_provider_id is null or f.provider_id = p_provider_id)
  insert into catalogue.provider_fee_ranges(provider_id, currency_code, low_amount, high_amount, low_course_id, high_course_id, low_source, high_source, course_count, source_counts, skipped, fee_year_from, fee_year_to, register_as_of, meets_minimum, computed_at)
  select allp.provider_id, a.ccy, a.lo, a.hi, lo.course_id, hi.course_id, lo.source, hi.source, coalesce(a.n, 0), coalesce(a.sc, '{}'::jsonb), coalesce(sk.j, '{}'::jsonb), a.fy_from, a.fy_to, a.reg_asof, coalesce(a.n, 0) >= v_min, now()
    from allp left join a on a.provider_id = allp.provider_id left join lo on lo.provider_id = allp.provider_id left join hi on hi.provider_id = allp.provider_id left join sk on sk.provider_id = allp.provider_id
  on conflict (provider_id) do update set currency_code = excluded.currency_code, low_amount = excluded.low_amount, high_amount = excluded.high_amount, low_course_id = excluded.low_course_id, high_course_id = excluded.high_course_id, low_source = excluded.low_source, high_source = excluded.high_source, course_count = excluded.course_count, source_counts = excluded.source_counts, skipped = excluded.skipped, fee_year_from = excluded.fee_year_from, fee_year_to = excluded.fee_year_to, register_as_of = excluded.register_as_of, meets_minimum = excluded.meets_minimum, computed_at = excluded.computed_at;
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'providers', v_n);
end $$;


ALTER FUNCTION "security"."provider_fee_ranges_refresh_v1"("p_provider_id" "uuid") OWNER TO "postgres";


