CREATE OR REPLACE FUNCTION "security"."refresh_data_quality_overview_snapshots"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    SET "statement_timeout" TO '120s'
    SET "work_mem" TO '128MB'
    AS $$
declare
  r record;
  v_started timestamptz;
  v_finished timestamptz;
  v_payload jsonb;
  v_result jsonb := '[]'::jsonb;
begin
  for r in select * from (values
    ('AU+NZ'::text,null::text,'{}'::jsonb),
    ('AU'::text,'AU'::text,'{"country_code":"AU"}'::jsonb),
    ('NZ'::text,'NZ'::text,'{"country_code":"NZ"}'::jsonb)
  ) v(scope_code,country_code,args)
  loop
    v_started:=clock_timestamp();
    v_payload:=security.data_quality_overview_impl(r.args);
    v_finished:=clock_timestamp();
    insert into security.data_quality_overview_snapshots(scope_code,country_code,payload,computed_at,compute_duration_ms,refreshed_by)
    values(r.scope_code,r.country_code,v_payload,v_finished,round((extract(epoch from (v_finished-v_started))*1000.0)::numeric,2),current_user)
    on conflict(scope_code) do update set country_code=excluded.country_code,payload=excluded.payload,computed_at=excluded.computed_at,compute_duration_ms=excluded.compute_duration_ms,refreshed_by=excluded.refreshed_by;
    v_result:=v_result||jsonb_build_array(jsonb_build_object('scope_code',r.scope_code,'computed_at',v_finished,'compute_duration_ms',round((extract(epoch from (v_finished-v_started))*1000.0)::numeric,2)));
  end loop;
  return jsonb_build_object('snapshots',v_result,'completed_at',clock_timestamp());
end
$$;


ALTER FUNCTION "security"."refresh_data_quality_overview_snapshots"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."refresh_intelligence_overview_impl"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<3 then
    raise exception 'curator role required' using errcode='42501';
  end if;
  return jsonb_build_object(
   'policies',coalesce((
     select jsonb_agg(to_jsonb(x) order by x.next_due_at nulls last)
     from (
       select id,country_code,layer,source_id,source_profile_id,entity_type,entity_id,
              freshness_class,cadence_interval,next_due_at,hash_sensitive,important_date_sensitive,
              enabled,change_control_ref,updated_at
       from pipeline.refresh_policies
       order by next_due_at nulls last
       limit least(greatest(p_limit,1),250)
     ) x
   ),'[]'::jsonb),
   'requests',coalesce((
     select jsonb_agg(to_jsonb(x) order by x.created_at desc)
     from (
       select id,requested_layer,country_code,source_id,source_profile_id,entity_type,entity_id,
              evidence_id,layer3_profile_id,revalidation_ref,reason,trigger_type,important_date_id,
              status,requested_by,change_control_ref,created_at,completed_at
       from pipeline.refresh_requests
       order by created_at desc
       limit least(greatest(p_limit,1),250)
     ) x
   ),'[]'::jsonb),
   'search_signals',coalesce((
     select jsonb_agg(to_jsonb(x) order by x.created_at desc)
     from (
       select id,entity_type,entity_id,review_decision_id,reason,status,change_control_ref,created_at,completed_at
       from pipeline.search_refresh_signals
       order by created_at desc
       limit least(greatest(p_limit,1),250)
     ) x
   ),'[]'::jsonb)
  );
end $$;


ALTER FUNCTION "security"."refresh_intelligence_overview_impl"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."refresh_policy_upsert_impl"("p_id" "uuid", "p_country_code" "text", "p_layer" smallint, "p_source_profile_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_freshness_class" "text", "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_hash_sensitive" boolean, "p_important_date_sensitive" boolean, "p_enabled" boolean, "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$ declare v_id uuid:=coalesce(p_id,gen_random_uuid()); begin
 if auth.uid() is null or security.current_role_rank()<4 then raise exception 'pipeline operator role required' using errcode='42501'; end if;
 if length(trim(coalesce(p_reason,'')))<5 then raise exception 'governance reason required'; end if;
 if p_layer=4 and p_freshness_class<>'event-driven' then raise exception 'Layer 4 refresh policy must be event-driven'; end if;
 if p_layer in (1,2,3) and p_source_profile_id is null and p_entity_id is null then raise exception 'bounded source or entity target required'; end if;
 insert into pipeline.refresh_policies(id,country_code,layer,source_profile_id,entity_type,entity_id,freshness_class,cadence_interval,next_due_at,hash_sensitive,important_date_sensitive,enabled,change_control_ref)
 values(v_id,upper(nullif(p_country_code,'')),p_layer,p_source_profile_id,p_entity_type,p_entity_id,p_freshness_class,case when p_cadence_days is null then null else make_interval(days=>p_cadence_days) end,p_next_due_at,p_hash_sensitive,p_important_date_sensitive,p_enabled,'CF-CHG-20260825-038')
 on conflict(id) do update set country_code=excluded.country_code,layer=excluded.layer,source_profile_id=excluded.source_profile_id,entity_type=excluded.entity_type,entity_id=excluded.entity_id,freshness_class=excluded.freshness_class,cadence_interval=excluded.cadence_interval,next_due_at=excluded.next_due_at,hash_sensitive=excluded.hash_sensitive,important_date_sensitive=excluded.important_date_sensitive,enabled=excluded.enabled,change_control_ref=excluded.change_control_ref,updated_at=now(); return v_id; end $$;


