CREATE OR REPLACE FUNCTION "security"."retention_catalogue_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_array(
    jsonb_build_object('key', 'adapter_screenshots', 'label', 'Adapter builder screenshots', 'kind', 'files', 'purge', true,
      'rule', 'Screenshots captured by the adapter builder more than 7 days ago. The stored page HTML and text blocks that proposals use are kept; the builder shows "screenshot removed".'),
    jsonb_build_object('key', 'retired_layer2', 'label', 'Retired Layer 2 tables', 'kind', 'rows', 'purge', true,
      'rule', 'Rows of the Layer 2 tables retired on 2 Oct 2026: scope wave items, scale qualification items, provider attempts, course discovery candidates and provider trial results. Run items are kept because Layer 3 work items point to them.'),
    jsonb_build_object('key', 'job_log', 'label', 'Scheduled-job run log', 'kind', 'rows', 'purge', true,
      'rule', 'Run records of scheduled jobs older than 7 days. Platform health and the job notices only use the last 24 hours.'),
    jsonb_build_object('key', 'directory_urls', 'label', 'Course-directory sitemap copies', 'kind', 'rows', 'purge', true,
      'rule', 'Sitemap addresses on third-party course directories shared by 3 or more providers, kept for providers whose own website is a different site. Addresses bound to a course are kept (they are in Layer 4 review).'),
    jsonb_build_object('key', 'evidence_audit', 'label', 'Evidence files (audit)', 'kind', 'files', 'purge', false,
      'rule', 'Count only: evidence records and files not referenced by any value, decision or pipeline record. Nothing is deleted. Run it before purging unreferenced evidence.'),
    jsonb_build_object('key', 'evidence_unreferenced', 'label', 'Unreferenced evidence', 'kind', 'files', 'purge', true,
      'rule', 'Evidence records and their files that the last completed audit found referenced nowhere, created before that audit and more than 7 days ago. Each batch is checked again just before removal; anything referenced by then is skipped. Evidence kept for 365 days by policy and ranking publisher source files are never purged. A file shared with another evidence record is kept.'))
$$;


ALTER FUNCTION "security"."retention_catalogue_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."retention_dry_run_read"("p_environment" "text" DEFAULT 'pilot'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$
declare v_rank integer; v_terminal bigint; v_immutable bigint;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
  if p_environment not in ('pilot','production') then raise exception 'invalid environment'; end if;

  select count(*) into v_terminal
  from pipeline.jobs
  where status in ('completed','failed','cancelled')
    and coalesce(completed_at,created_at) < now()-interval '90 days';

  select count(*) into v_immutable
  from pipeline.retention_class_policies where immutable;

  return jsonb_build_object(
    'environment',p_environment,
    'mode','dry_run_only',
    'delete_performed',false,
    'terminal_job_candidates_older_than_90d',v_terminal,
    'immutable_policy_classes',v_immutable,
    'evidence_delete_candidates',0,
    'layer4_delete_candidates',0,
    'publication_audit_delete_candidates',0,
    'rule','Any future purge requires explicit class mapping, immutable exclusions, bounded delete and post-delete integrity verification.'
  );
end $$;


ALTER FUNCTION "security"."retention_dry_run_read"("p_environment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."retention_estimate_v1"("p_cat" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_size bigint; v_rows bigint; v_bytes bigint; v_detail jsonb := '{}'::jsonb;
begin
  if p_cat = 'adapter_screenshots' then
    select coalesce(sum((o.metadata->>'size')::bigint), 0), count(*) filter (where o.created_at < now() - interval '7 days'),
           coalesce(sum((o.metadata->>'size')::bigint) filter (where o.created_at < now() - interval '7 days'), 0)
      into v_size, v_rows, v_bytes from storage.objects o where o.bucket_id = 'adapter-captures';
  elsif p_cat = 'retired_layer2' then
    select sum(pg_total_relation_size(t::regclass)) into v_size
      from unnest(array['pipeline.layer2_provider_trial_results', 'pipeline.layer2_course_discovery_candidates', 'pipeline.layer2_provider_attempts',
                        'pipeline.layer2_scale_qualification_items', 'pipeline.layer2_scope_wave_items']) t;
    v_rows := (select count(*) from pipeline.layer2_provider_trial_results) + (select count(*) from pipeline.layer2_course_discovery_candidates)
            + (select count(*) from pipeline.layer2_provider_attempts) + (select count(*) from pipeline.layer2_scale_qualification_items)
            + (select count(*) from pipeline.layer2_scope_wave_items);
    v_bytes := v_size;
    v_detail := jsonb_build_object('trial_results', (select count(*) from pipeline.layer2_provider_trial_results), 'discovery_candidates', (select count(*) from pipeline.layer2_course_discovery_candidates),
      'provider_attempts', (select count(*) from pipeline.layer2_provider_attempts), 'scale_qualification_items', (select count(*) from pipeline.layer2_scale_qualification_items),
      'scope_wave_items', (select count(*) from pipeline.layer2_scope_wave_items));
  elsif p_cat = 'job_log' then
    v_size := pg_total_relation_size('cron.job_run_details');
    select count(*) filter (where d.start_time < now() - interval '7 days'), count(*) into v_rows, v_bytes from cron.job_run_details d;
    v_bytes := case when v_bytes > 0 then v_size * v_rows / v_bytes else 0 end;
  elsif p_cat = 'directory_urls' then
    v_size := pg_total_relation_size('pipeline.coverage_provider_urls');
    with h as (select provider_id, substring(url from '^https?://(?:www\.)?([^/:?#]+)') host from pipeline.coverage_provider_urls),
         shared as (select host from h group by host having count(distinct provider_id) >= 3)
    select coalesce(jsonb_agg(host order by host), '[]'::jsonb) into v_detail from shared;
    v_detail := jsonb_build_object('hosts', v_detail);
    select count(*) into v_rows from pipeline.coverage_provider_urls u join catalogue.providers p on p.id = u.provider_id
     where substring(u.url from '^https?://(?:www\.)?([^/:?#]+)') in (select jsonb_array_elements_text(v_detail->'hosts'))
       and (p.website is null or p.website not ilike '%' || substring(u.url from '^https?://(?:www\.)?([^/:?#]+)') || '%')
       and not exists (select 1 from pipeline.coverage_course_pages pg where pg.url = u.url);
    v_bytes := case when (select reltuples from pg_class where oid = 'pipeline.coverage_provider_urls'::regclass) > 0
                    then (v_size * v_rows / greatest(1, (select reltuples from pg_class where oid = 'pipeline.coverage_provider_urls'::regclass)))::bigint else 0 end;
  elsif p_cat = 'evidence_audit' then
    v_size := pg_total_relation_size('pipeline.evidence_artifacts');
    select count(*), count(*) filter (where c.done_at is not null) into v_rows, v_bytes from pipeline.evidence_audit_columns c;
    v_detail := jsonb_build_object('columns', v_rows, 'columns_done', v_bytes, 'references', (select count(*) from pipeline.evidence_audit_refs),
      'evidence_records', (select count(*) from pipeline.evidence_artifacts),
      'evidence_files_bytes', (select coalesce(sum((o.metadata->>'size')::bigint), 0) from storage.objects o where o.bucket_id = 'evidence'));
    if v_rows > 0 and v_rows = v_bytes then
      select count(*), coalesce(sum((o.metadata->>'size')::bigint), 0) into v_rows, v_bytes
        from pipeline.evidence_artifacts e left join storage.objects o on o.bucket_id = 'evidence' and o.name = e.storage_path
       where not exists (select 1 from pipeline.evidence_audit_refs r where r.evidence_id = e.id);
    else
      v_rows := null; v_bytes := null;
    end if;
  elsif p_cat = 'evidence_unreferenced' then
    v_size := pg_total_relation_size('pipeline.evidence_artifacts');
    if exists (select 1 from pipeline.retention_runs r where r.category = 'evidence_audit' and r.status = 'done')
       and not exists (select 1 from pipeline.retention_runs r where r.category = 'evidence_audit' and r.status in ('queued', 'running')) then
      -- bytes: each file once, and only files no other (kept) evidence record uses
      with c as materialized (select evidence_id, storage_path from security.retention_evidence_candidates_v1()),
           f as (select distinct storage_path from c where storage_path is not null)
      select (select count(*) from c),
             coalesce((select sum((o.metadata->>'size')::bigint) from f join storage.objects o on o.bucket_id = 'evidence' and o.name = f.storage_path
                        where not exists (select 1 from pipeline.evidence_artifacts e where e.storage_path = f.storage_path
                                            and not exists (select 1 from c where c.evidence_id = e.id))), 0)
        into v_rows, v_bytes;
      v_detail := (select jsonb_build_object('audit_run', r.id, 'audit_started_at', r.started_at, 'audit_finished_at', r.finished_at)
                     from pipeline.retention_runs r where r.category = 'evidence_audit' and r.status = 'done' order by r.finished_at desc limit 1);
    else
      v_rows := null; v_bytes := null; v_detail := jsonb_build_object('note', 'Run the evidence audit first (and let it finish).');
    end if;
  else
    raise exception 'unknown category';
  end if;
  insert into pipeline.retention_estimates(category, size_bytes, purgeable_rows, purgeable_bytes, detail, measured_at)
  values (p_cat, v_size, v_rows, v_bytes, v_detail, now())
  on conflict (category) do update set size_bytes = excluded.size_bytes, purgeable_rows = excluded.purgeable_rows, purgeable_bytes = excluded.purgeable_bytes,
         detail = excluded.detail, measured_at = excluded.measured_at;
end $$;


ALTER FUNCTION "security"."retention_estimate_v1"("p_cat" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."retention_evidence_candidates_v1"() RETURNS TABLE("evidence_id" "uuid", "storage_path" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with a as (select r.started_at from pipeline.retention_runs r where r.category = 'evidence_audit' and r.status = 'done' order by r.finished_at desc limit 1)
  select e.id, e.storage_path, e.created_at
    from pipeline.evidence_artifacts e, a
   where e.created_at < least(a.started_at, now() - interval '7 days')
     and coalesce(e.retention_class, '') not in ('standard_365', 'source_evidence')
     and coalesce(e.storage_path, '') not like 'regulatory/%'
     and not exists (select 1 from pipeline.evidence_audit_refs r where r.evidence_id = e.id)
$$;


ALTER FUNCTION "security"."retention_evidence_candidates_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."retention_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.retention_runs%rowtype; v_n bigint := 0; v_cat text; v_hosts text[]; v_t text; v_col record; v_done int := 0;
        v_ev record; v_del int := 0; v_skip int := 0; v_q int := 0;
begin
  -- keep the estimates fresh (one category per run, oldest first)
  select c->>'key' into v_cat from jsonb_array_elements(security.retention_catalogue_v1()) c
   left join pipeline.retention_estimates e on e.category = c->>'key'
   where c->>'key' <> 'evidence_audit' and (e.measured_at is null or e.measured_at < now() - interval '1 hour')
   order by e.measured_at nulls first limit 1;
  if v_cat is not null then perform security.retention_estimate_v1(v_cat); end if;

  select * into r from pipeline.retention_runs where status in ('queued', 'running') order by created_at limit 1 for update skip locked;
  if r.id is null then return jsonb_build_object('idle', true); end if;
  begin
    if r.status = 'queued' then
      perform security.retention_estimate_v1(r.category);
      update pipeline.retention_runs set status = 'running', started_at = now(), estimate = (select to_jsonb(e) from pipeline.retention_estimates e where e.category = r.category),
             note = 'Running in small batches.', updated_at = now() where id = r.id;
      if r.category = 'evidence_audit' then
        delete from pipeline.evidence_audit_refs;
        delete from pipeline.evidence_audit_columns;
        insert into pipeline.evidence_audit_columns(tbl, col)
        select distinct format('%I.%I', n.nspname, c.relname), a.attname
          from pg_attribute a join pg_class c on c.oid = a.attrelid join pg_namespace n on n.oid = c.relnamespace
         where c.relkind = 'r' and a.attnum > 0 and not a.attisdropped and a.atttypid = 'uuid'::regtype
           and n.nspname in ('catalogue', 'pipeline', 'scholarship', 'ranking', 'workflow', 'pim', 'search')
           and (a.attname in ('evidence_id', 'evidence_artifact_id', 'source_artifact_id', 'supersedes_evidence_id') or a.attname like '%\_evidence\_id' escape '\')
           and c.relname not in ('evidence_audit_refs');
      end if;
      return jsonb_build_object('started', r.id);
    end if;

    if r.category = 'job_log' then
      delete from cron.job_run_details where runid in (select d.runid from cron.job_run_details d where d.start_time < coalesce(r.started_at, now()) - interval '7 days' limit 20000);
      get diagnostics v_n = row_count;
    elsif r.category = 'retired_layer2' then
      foreach v_t in array array['pipeline.layer2_provider_trial_results', 'pipeline.layer2_course_discovery_candidates', 'pipeline.layer2_provider_attempts',
                                 'pipeline.layer2_scale_qualification_items', 'pipeline.layer2_scope_wave_items'] loop
        execute format('delete from %s where ctid = any(array(select ctid from %s limit 5000))', v_t, v_t);
        get diagnostics v_n = row_count;
        exit when v_n > 0;
      end loop;
    elsif r.category = 'directory_urls' then
      select array(select jsonb_array_elements_text(coalesce(r.estimate->'detail'->'hosts', '[]'::jsonb))) into v_hosts;
      delete from pipeline.coverage_provider_urls where (provider_id, url) in (
        select u.provider_id, u.url from pipeline.coverage_provider_urls u join catalogue.providers p on p.id = u.provider_id
         where substring(u.url from '^https?://(?:www\.)?([^/:?#]+)') = any(v_hosts)
           and (p.website is null or p.website not ilike '%' || substring(u.url from '^https?://(?:www\.)?([^/:?#]+)') || '%')
           and not exists (select 1 from pipeline.coverage_course_pages pg where pg.url = u.url)
         limit 20000);
      get diagnostics v_n = row_count;
    elsif r.category = 'adapter_screenshots' then
      -- files go through Storage: hand the run to the worker; it reports back with svc_retention_files_done
      if r.note is distinct from 'Removing files through Storage.' or r.updated_at < now() - interval '10 minutes' then
        update pipeline.retention_runs set note = 'Removing files through Storage.', updated_at = now() where id = r.id;
        perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'retention_files', 'run_id', r.id));
      end if;
      return jsonb_build_object('handed_to_worker', r.id);
    elsif r.category = 'evidence_unreferenced' then
      -- files of the last batch still with the worker: hand them again if the worker has not reported for 10 minutes
      if exists (select 1 from pipeline.retention_file_queue q where q.run_id = r.id and q.status in ('queued', 'handed')) then
        if r.updated_at < now() - interval '10 minutes' or exists (select 1 from pipeline.retention_file_queue q where q.run_id = r.id and q.status = 'queued') then
          update pipeline.retention_file_queue set status = 'queued' where run_id = r.id and status = 'handed' and handed_at < now() - interval '10 minutes';
          update pipeline.retention_runs set updated_at = now() where id = r.id;
          perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'retention_files', 'run_id', r.id));
        end if;
        return jsonb_build_object('handed_to_worker', r.id);
      end if;
      if not exists (select 1 from pipeline.retention_runs a where a.category = 'evidence_audit' and a.status = 'done')
         or exists (select 1 from pipeline.retention_runs a where a.category = 'evidence_audit' and a.status in ('queued', 'running')) then
        raise exception 'Run the evidence audit first and let it finish.';
      end if;
      -- next batch: candidates not yet skipped in this run
      create temporary table ev_batch on commit drop as
        select c.evidence_id id, c.storage_path from security.retention_evidence_candidates_v1() c
         where not exists (select 1 from pipeline.retention_evidence_skips s where s.run_id = r.id and s.evidence_id = c.evidence_id)
         order by c.created_at limit 500;
      if not exists (select 1 from ev_batch) then
        perform security.retention_estimate_v1('evidence_unreferenced');
        update pipeline.retention_runs set status = 'done', finished_at = now(), updated_at = now(),
               note = format('Done: %s records and %s MB of files removed; %s skipped because they were referenced again.', removed, round(bytes / 1e6),
                             (select count(*) from pipeline.retention_evidence_skips s where s.run_id = r.id))
         where id = r.id;
        return jsonb_build_object('run', r.id, 'done', true);
      end if;
      -- re-check every reference column of the audit just before removal
      for v_col in select * from pipeline.evidence_audit_columns order by tbl, col loop
        execute format('insert into pipeline.retention_evidence_skips(run_id, evidence_id, reason) select %L::uuid, b.id, %L from pg_temp.ev_batch b where exists (select 1 from %s t where t.%I = b.id) on conflict do nothing',
                       r.id, 'referenced: ' || v_col.tbl || '.' || v_col.col, v_col.tbl, v_col.col);
      end loop;
      create temporary table ev_gone (storage_path text) on commit drop;
      for v_ev in select b.id, b.storage_path from ev_batch b
                   where not exists (select 1 from pipeline.retention_evidence_skips s where s.run_id = r.id and s.evidence_id = b.id) loop
        begin
          delete from pipeline.evidence_artifacts where id = v_ev.id;
          insert into ev_gone values (v_ev.storage_path);
          v_del := v_del + 1;
        exception when foreign_key_violation then
          insert into pipeline.retention_evidence_skips(run_id, evidence_id, reason) values (r.id, v_ev.id, 'still referenced (foreign key)') on conflict do nothing;
          v_skip := v_skip + 1;
        end;
      end loop;
      -- a file goes only when no remaining evidence record uses it
      insert into pipeline.retention_file_queue(run_id, bucket, name, size)
      select r.id, 'evidence', o.name, coalesce((o.metadata->>'size')::bigint, 0)
        from (select distinct storage_path from ev_gone where storage_path is not null) g
        join storage.objects o on o.bucket_id = 'evidence' and o.name = g.storage_path
       where not exists (select 1 from pipeline.evidence_artifacts e where e.storage_path = g.storage_path);
      get diagnostics v_q = row_count;
      update pipeline.retention_runs set removed = removed + v_del, updated_at = now(),
             note = format('Running: %s records removed, %s MB of files so far.', removed + v_del, round(bytes / 1e6)) where id = r.id;
      if v_q > 0 then perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'retention_files', 'run_id', r.id)); end if;
      return jsonb_build_object('run', r.id, 'removed', v_del, 'files_queued', v_q, 'skipped_fk', v_skip);
    elsif r.category = 'evidence_audit' then
      for v_col in select * from pipeline.evidence_audit_columns where done_at is null order by tbl, col limit 3 loop
        execute format('insert into pipeline.evidence_audit_refs(evidence_id) select distinct %I from %s where %I is not null on conflict do nothing', v_col.col, v_col.tbl, v_col.col);
        get diagnostics v_n = row_count;
        update pipeline.evidence_audit_columns set done_at = now(), rows_found = v_n where tbl = v_col.tbl and col = v_col.col;
        v_done := v_done + 1;
      end loop;
      if v_done = 0 then
        perform security.retention_estimate_v1('evidence_audit');
        update pipeline.retention_runs set status = 'done', finished_at = now(), updated_at = now(),
               removed = 0, estimate = (select to_jsonb(e) from pipeline.retention_estimates e where e.category = 'evidence_audit'),
               note = format('Audit complete: %s evidence records are not referenced anywhere (%s MB of files). Nothing was deleted.',
                             (select purgeable_rows from pipeline.retention_estimates where category = 'evidence_audit'),
                             round(coalesce((select purgeable_bytes from pipeline.retention_estimates where category = 'evidence_audit'), 0) / 1e6))
         where id = r.id;
      else
        update pipeline.retention_runs set note = format('Auditing: %s of %s reference columns done.', (select count(*) from pipeline.evidence_audit_columns where done_at is not null),
               (select count(*) from pipeline.evidence_audit_columns)), updated_at = now() where id = r.id;
      end if;
      return jsonb_build_object('audited_columns', v_done);
    end if;

    if v_n = 0 then
      perform security.retention_estimate_v1(r.category);
      update pipeline.retention_runs set status = 'done', finished_at = now(), updated_at = now(), note = format('Done: %s rows removed.', removed) where id = r.id;
    else
      update pipeline.retention_runs set removed = removed + v_n, note = format('Running: %s rows removed so far.', removed + v_n), updated_at = now() where id = r.id;
    end if;
    return jsonb_build_object('run', r.id, 'removed', v_n);
  exception when others then
    update pipeline.retention_runs set status = 'failed', error = left(sqlerrm, 500), finished_at = now(), updated_at = now() where id = r.id;
    return jsonb_build_object('failed', r.id, 'error', sqlerrm);
  end;
end $$;


ALTER FUNCTION "security"."retention_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."review_reason_key"("p_reason" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select regexp_replace(regexp_replace(coalesce(p_reason,''),'(A\$|AUD\s?\$?|\$)\s?[0-9][0-9,]*(\.[0-9]+)?','[amount]','g'),'\m[0-9][0-9,\.]*\M','[n]','g')
$_$;


ALTER FUNCTION "security"."review_reason_key"("p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."rule6_list_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  with s as (select url, provider_id from pipeline.coverage_course_pages where read_status = 'read' group by 1, 2 having count(*) > 1),
  r as (select pg.url, pg.provider_id, pg.course_id, pg.evidence_id, c.display_title,
               regexp_replace(lower(c.display_title), '[^a-z]', '', 'g') t,
               regexp_replace(lower(regexp_replace(pg.url, '^https?://[^/]+', '')), '[^a-z]', '', 'g') u
          from pipeline.coverage_course_pages pg join s using (url, provider_id) join catalogue.courses c on c.id = pg.course_id
         where pg.read_status = 'read'),
  g as (select url, provider_id from r group by 1, 2 having count(distinct t) > 1),
  m as (select r.*,
               (select r2.display_title from r r2 where r2.url = r.url and r2.provider_id = r.provider_id and strpos(r2.u, r2.t) > 0 order by length(r2.t) desc limit 1) named,
               (select max(length(r2.t)) from r r2 where r2.url = r.url and r2.provider_id = r.provider_id and strpos(r2.u, r2.t) > 0) best_len
          from r join g using (url, provider_id))
  insert into pipeline.rule6_page_checks(course_id, provider_id, url, evidence_id, storage_path, course_code, named_course)
  select m.course_id, m.provider_id, m.url, m.evidence_id, e.storage_path,
         (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = m.course_id and lower(cr.scheme) = 'cricos' limit 1), m.named
    from m left join pipeline.evidence_artifacts e on e.id = m.evidence_id
   where m.best_len is not null and not (strpos(m.u, m.t) > 0 and length(m.t) = m.best_len)
  on conflict (course_id) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "security"."rule6_list_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_actor_display"("p_actor" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    nullif(trim(u.raw_user_meta_data->>'full_name'),''),
    nullif(trim(u.raw_user_meta_data->>'name'),''),
    nullif(trim(u.email),''),
    case when p_actor is null then null else 'User '||left(p_actor::text,8) end
  )
  from auth.users u
  where u.id=p_actor
$$;


ALTER FUNCTION "security"."scheduler_actor_display"("p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_capture_action_actor"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_email text;
  v_display text;
begin
  if new.actor_id is not null and (new.actor_display_snapshot is null or new.actor_email_snapshot is null) then
    select
      coalesce(nullif(trim(u.raw_user_meta_data->>'full_name'),''),nullif(trim(u.raw_user_meta_data->>'name'),''),nullif(trim(u.email),''),'User '||left(u.id::text,8)),
      nullif(trim(u.email),'')
    into v_display,v_email
    from auth.users u where u.id=new.actor_id;
    new.actor_display_snapshot:=coalesce(new.actor_display_snapshot,v_display,'User '||left(new.actor_id::text,8));
    new.actor_email_snapshot:=coalesce(new.actor_email_snapshot,v_email);
  end if;
  return new;
end
$$;


ALTER FUNCTION "security"."scheduler_capture_action_actor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_capture_policy_creator"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_email text;
  v_display text;
begin
  if new.created_by is null and v_actor is not null then
    new.created_by:=v_actor;
  end if;
  if new.created_by is not null and (new.created_by_display_snapshot is null or new.created_by_email_snapshot is null) then
    select
      coalesce(nullif(trim(u.raw_user_meta_data->>'full_name'),''),nullif(trim(u.raw_user_meta_data->>'name'),''),nullif(trim(u.email),''),'User '||left(u.id::text,8)),
      nullif(trim(u.email),'')
    into v_display,v_email
    from auth.users u where u.id=new.created_by;
    new.created_by_display_snapshot:=coalesce(new.created_by_display_snapshot,v_display,'User '||left(new.created_by::text,8));
    new.created_by_email_snapshot:=coalesce(new.created_by_email_snapshot,v_email);
  elsif new.created_by is null and new.created_by_display_snapshot is null then
    new.created_by_display_snapshot:='System / automation';
  end if;
  return new;
end
$$;


ALTER FUNCTION "security"."scheduler_capture_policy_creator"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_entity_display"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_label text; begin
 if p_entity_id is null then return null; end if;
 case lower(coalesce(p_entity_type,''))
  when 'provider' then select coalesce(nullif(trim(p.display_name),''),nullif(trim(p.canonical_name),'')) into v_label from catalogue.providers p where p.id=p_entity_id;
  when 'course' then select coalesce(nullif(trim(c.display_title),''),nullif(trim(c.canonical_title),''),nullif(trim(c.course_code),'')) into v_label from catalogue.courses c where c.id=p_entity_id;
  when 'campus' then select nullif(trim(c.name),'') into v_label from catalogue.campuses c where c.id=p_entity_id;
  when 'scholarship' then select nullif(trim(s.name),'') into v_label from scholarship.scholarships s where s.id=p_entity_id;
  else v_label:=null;
 end case;
 return v_label;
end $$;


ALTER FUNCTION "security"."scheduler_entity_display"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_policies_list_v1_browser_bridge"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT ''::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer:=least(greatest(coalesce(p_limit,50),1),100);
  v_offset integer:=greatest(coalesce(p_offset,0),0);
  v_query text:=replace(replace(replace(lower(trim(coalesce(p_query,''))), E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_');
begin
  if auth.uid() is null or security.current_role_rank() < 3 then
    raise exception 'curator role required' using errcode='42501';
  end if;
  return jsonb_build_object(
    'total',(
      select count(*) from pipeline.refresh_policies p
      left join pipeline.sources s on s.id=p.source_id
      left join pipeline.layer2_source_profiles lp on lp.id=p.source_profile_id
      left join pipeline.sources ps on ps.id=lp.source_id
      where p.layer between 1 and 3
        and (p.source_id is not null or p.source_profile_id is not null or p.entity_id is not null)
        and (v_query=''
          or lower(coalesce(s.label,'')) like '%'||v_query||'%'
          or lower(coalesce(ps.label,'')) like '%'||v_query||'%'
          or lower(coalesce(lp.profile_key,'')) like '%'||v_query||'%'
          or lower(coalesce(lp.domain,'')) like '%'||v_query||'%'
          or lower(replace(coalesce(lp.domain,''),'_',' ')) like '%'||v_query||'%'
          or lower(coalesce(lp.acquisition_method,'')) like '%'||v_query||'%'
          or lower(coalesce(p.country_code,'')) like '%'||v_query||'%'
          or lower(coalesce(p.entity_type,'')) like '%'||v_query||'%'
          or lower(coalesce(security.scheduler_entity_display(p.entity_type,p.entity_id),'')) like '%'||v_query||'%'
          or lower(coalesce(p.entity_id::text,'')) like '%'||v_query||'%'
          or lower(coalesce(p.source_id::text,'')) like '%'||v_query||'%'
          or lower(coalesce(p.source_profile_id::text,'')) like '%'||v_query||'%'
          or lower(coalesce(p.created_by_display_snapshot,case when p.created_by is null then 'System / legacy' when exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.created_by) else 'Former user' end,'')) like '%'||v_query||'%'
          or (p.created_by is not null and not exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) and lower('Former user — '||coalesce(p.created_by_display_snapshot,security.scheduler_actor_display(p.created_by),'unknown')) like '%'||v_query||'%')
          or lower(coalesce(p.owner_display_snapshot,case when p.owner_user_id is null then null when exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.owner_user_id) else 'Former user' end,'')) like '%'||v_query||'%'
          or (p.owner_user_id is not null and not exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) and lower('Former user — '||coalesce(p.owner_display_snapshot,security.scheduler_actor_display(p.owner_user_id),'unknown')) like '%'||v_query||'%')
          or lower(coalesce(p.freshness_class,'')) like '%'||v_query||'%'
          or lower(coalesce(p.cadence_interval::text,'')) like '%'||v_query||'%'
          or lower('layer '||p.layer::text) like '%'||v_query||'%'
          or (v_query='enabled' and p.enabled)
          or (v_query='disabled' and not p.enabled))
    ),
    'items',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.next_due_at nulls last,x.id) from (
        select p.id,p.country_code,p.layer,p.source_id,p.source_profile_id,p.entity_type,p.entity_id,
               p.freshness_class,p.cadence_interval,p.next_due_at,p.hash_sensitive,p.important_date_sensitive,
               p.enabled,p.change_control_ref,p.updated_at,
               coalesce(s.label,ps.label,lp.profile_key,security.scheduler_entity_display(p.entity_type,p.entity_id),case when p.entity_id is not null then initcap(replace(coalesce(p.entity_type,'entity'),'_',' ')) else null end,'Scheduled task') as task_label,
               coalesce(s.label,ps.label) as source_label,lp.profile_key as source_profile_key,lp.domain as dataset_domain,lp.acquisition_method,
               p.created_by,
               coalesce(p.created_by_display_snapshot,case when p.created_by is null then 'System / legacy' when exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.created_by) else 'Former user' end) as created_by_display,
               case when p.created_by is null then 'system_or_legacy' when exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then 'active' else 'former_user' end as created_by_state,
               p.owner_user_id,
               coalesce(p.owner_display_snapshot,case when p.owner_user_id is null then null when exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.owner_user_id) else 'Former user' end) as owner_display,
               case when p.owner_user_id is null then 'unassigned' when exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then 'active' else 'former_user' end as owner_state
        from pipeline.refresh_policies p
        left join pipeline.sources s on s.id=p.source_id
        left join pipeline.layer2_source_profiles lp on lp.id=p.source_profile_id
        left join pipeline.sources ps on ps.id=lp.source_id
        where p.layer between 1 and 3
          and (p.source_id is not null or p.source_profile_id is not null or p.entity_id is not null)
          and (v_query=''
            or lower(coalesce(s.label,'')) like '%'||v_query||'%'
            or lower(coalesce(ps.label,'')) like '%'||v_query||'%'
            or lower(coalesce(lp.profile_key,'')) like '%'||v_query||'%'
            or lower(coalesce(lp.domain,'')) like '%'||v_query||'%'
            or lower(replace(coalesce(lp.domain,''),'_',' ')) like '%'||v_query||'%'
            or lower(coalesce(lp.acquisition_method,'')) like '%'||v_query||'%'
            or lower(coalesce(p.country_code,'')) like '%'||v_query||'%'
            or lower(coalesce(p.entity_type,'')) like '%'||v_query||'%'
            or lower(coalesce(security.scheduler_entity_display(p.entity_type,p.entity_id),'')) like '%'||v_query||'%'
            or lower(coalesce(p.entity_id::text,'')) like '%'||v_query||'%'
            or lower(coalesce(p.source_id::text,'')) like '%'||v_query||'%'
            or lower(coalesce(p.source_profile_id::text,'')) like '%'||v_query||'%'
            or lower(coalesce(p.created_by_display_snapshot,case when p.created_by is null then 'System / legacy' when exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.created_by) else 'Former user' end,'')) like '%'||v_query||'%'
            or (p.created_by is not null and not exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) and lower('Former user — '||coalesce(p.created_by_display_snapshot,security.scheduler_actor_display(p.created_by),'unknown')) like '%'||v_query||'%')
            or lower(coalesce(p.owner_display_snapshot,case when p.owner_user_id is null then null when exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.owner_user_id) else 'Former user' end,'')) like '%'||v_query||'%'
            or (p.owner_user_id is not null and not exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) and lower('Former user — '||coalesce(p.owner_display_snapshot,security.scheduler_actor_display(p.owner_user_id),'unknown')) like '%'||v_query||'%')
            or lower(coalesce(p.freshness_class,'')) like '%'||v_query||'%'
            or lower(coalesce(p.cadence_interval::text,'')) like '%'||v_query||'%'
            or lower('layer '||p.layer::text) like '%'||v_query||'%'
            or (v_query='enabled' and p.enabled)
            or (v_query='disabled' and not p.enabled))
        order by p.next_due_at nulls last,p.id limit v_limit offset v_offset
      ) x
    ),'[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "security"."scheduler_policies_list_v1_browser_bridge"("p_limit" integer, "p_offset" integer, "p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_policy_edit_v1_browser_bridge"("p_policy_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_enabled" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_policy pipeline.refresh_policies%rowtype;
  v_before jsonb;
begin
  if v_actor is null or security.current_role_rank() < 4 then raise exception 'pipeline operator role required' using errcode='42501'; end if;
  if length(trim(coalesce(p_reason,''))) < 5 then raise exception 'governance reason required' using errcode='22023'; end if;
  if p_expected_updated_at is null then raise exception 'expected policy version required' using errcode='22023'; end if;
  if p_cadence_days is null or p_cadence_days < 1 or p_cadence_days > 3650 then raise exception 'cadence days must be 1..3650' using errcode='22023'; end if;
  if p_next_due_at is null then raise exception 'next run required' using errcode='22023'; end if;
  select * into v_policy from pipeline.refresh_policies where id=p_policy_id for update;
  if not found then raise exception 'refresh policy not found' using errcode='22023'; end if;
  if v_policy.updated_at is distinct from p_expected_updated_at then raise exception 'schedule changed since it was opened; refresh and try again' using errcode='40001'; end if;
  if v_policy.layer not in (1,2,3) then raise exception 'only Layer 1..3 schedules are editable here' using errcode='22023'; end if;
  if v_policy.freshness_class='event-driven' then raise exception 'event-driven policy has no recurring schedule' using errcode='22023'; end if;
  if v_policy.source_id is null and v_policy.source_profile_id is null and v_policy.entity_id is null then raise exception 'bounded target required' using errcode='22023'; end if;
  v_before:=jsonb_build_object('cadence_interval',v_policy.cadence_interval::text,'next_due_at',v_policy.next_due_at,'enabled',v_policy.enabled,'updated_at',v_policy.updated_at,'change_control_ref',v_policy.change_control_ref);
  update pipeline.refresh_policies set cadence_interval=make_interval(days=>p_cadence_days),next_due_at=p_next_due_at,enabled=p_enabled,change_control_ref='CF-CHG-20260910-092',updated_at=now() where id=v_policy.id;
  insert into pipeline.refresh_policy_action_events(policy_id,action,reason,actor_id,change_control_ref,before_state,after_state,outcome)
  values(v_policy.id,'edit_schedule',trim(p_reason),v_actor,'CF-CHG-20260910-092',v_before,jsonb_build_object('cadence_days',p_cadence_days,'next_due_at',p_next_due_at,'enabled',p_enabled,'change_control_ref','CF-CHG-20260910-092'),'applied');
  return jsonb_build_object('ok',true,'policy_id',v_policy.id,'action','edit_schedule');
end
$$;


ALTER FUNCTION "security"."scheduler_policy_edit_v1_browser_bridge"("p_policy_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_enabled" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_policy_run_now_v1_browser_bridge"("p_policy_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid := auth.uid(); v_policy pipeline.refresh_policies%rowtype; v_request_id uuid; v_existing boolean := false;
begin
  if v_actor is null or security.current_role_rank() < 4 then raise exception 'pipeline operator role required' using errcode='42501'; end if;
  if length(trim(coalesce(p_reason,''))) < 5 then raise exception 'governance reason required' using errcode='22023'; end if;
  select * into v_policy from pipeline.refresh_policies where id=p_policy_id for update;
  if not found then raise exception 'refresh policy not found' using errcode='22023'; end if;
  if not v_policy.enabled then raise exception 'enable this schedule before running it on demand' using errcode='22023'; end if;
  if v_policy.layer not in (1,2) then raise exception 'Layer 3 on-demand execution requires Evidence/profile-specific control from the Layer 3 workspace' using errcode='22023'; end if;
  if v_policy.source_id is null and v_policy.source_profile_id is null and v_policy.entity_id is null then raise exception 'bounded target required' using errcode='22023'; end if;
  select r.id into v_request_id from pipeline.refresh_requests r where r.status in ('queued','running') and r.requested_layer=v_policy.layer and r.country_code is not distinct from v_policy.country_code and r.source_id is not distinct from v_policy.source_id and r.source_profile_id is not distinct from v_policy.source_profile_id and r.entity_type is not distinct from v_policy.entity_type and r.entity_id is not distinct from v_policy.entity_id order by r.created_at desc limit 1;
  if v_request_id is null then
    insert into pipeline.refresh_requests(requested_layer,country_code,source_id,source_profile_id,entity_type,entity_id,reason,trigger_type,status,requested_by,change_control_ref)
    values(v_policy.layer,v_policy.country_code,v_policy.source_id,v_policy.source_profile_id,v_policy.entity_type,v_policy.entity_id,trim(p_reason),'manual_governed','queued',v_actor,'CF-CHG-20260910-092') returning id into v_request_id;
  else v_existing:=true; end if;
  insert into pipeline.refresh_policy_action_events(policy_id,action,reason,actor_id,change_control_ref,before_state,after_state,refresh_request_id,outcome)
  values(v_policy.id,'run_on_demand',trim(p_reason),v_actor,'CF-CHG-20260910-092',jsonb_build_object('cadence_interval',v_policy.cadence_interval::text,'next_due_at',v_policy.next_due_at,'enabled',v_policy.enabled),jsonb_build_object('policy_unchanged',true,'request_id',v_request_id),v_request_id,case when v_existing then 'existing_active' else 'queued' end);
  return jsonb_build_object('ok',true,'policy_id',v_policy.id,'request_id',v_request_id,'existing_active',v_existing,'action','run_on_demand');
end $$;


ALTER FUNCTION "security"."scheduler_policy_run_now_v1_browser_bridge"("p_policy_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_admission_withdraw_v1"("p_scholarship_id" "uuid", "p_reason" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'search'
    AS $$
declare s record; v_courses uuid[];
begin
  select * into s from scholarship.scholarships where id=p_scholarship_id for update;
  if s.id is null or s.lifecycle_status<>'active' then return jsonb_build_object('withdrawn',false); end if;
  if s.publication_status='published' then return jsonb_build_object('withdrawn',false,'reason','published; left for the publication review'); end if;
  if not exists (select 1 from pipeline.scholarship_pages where scholarship_id=s.id and url_source='admitted') then return jsonb_build_object('withdrawn',false,'reason','not admitted from a provider page'); end if;
  select coalesce(array_agg(course_id),'{}') into v_courses from scholarship.course_mappings where scholarship_id=s.id and mapping_basis='sweep_level_field_scope';
  delete from scholarship.course_mappings where scholarship_id=s.id and mapping_basis='sweep_level_field_scope';
  update scholarship.scholarships set lifecycle_status='inactive', updated_at=now() where id=s.id;
  update pipeline.scholarship_page_candidates set admit_status='withdrawn', admit_reasons=array(select jsonb_array_elements_text(coalesce(p_reason->'reasons','[]'))) where admitted_scholarship_id=s.id;
  insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value) values (s.id,'admission_withdrawn',jsonb_build_object('lifecycle_status','active'),p_reason);
  insert into pipeline.scholarship_admission_log(scholarship_id,provider_id,action,detail) values (s.id,s.provider_id,'withdrawn',p_reason);
  if cardinality(v_courses)>0 then perform search.refresh_course_enrichment_scoped_v1(v_courses,true); end if;
  return jsonb_build_object('withdrawn',true);
end $$;


ALTER FUNCTION "security"."scholarship_admission_withdraw_v1"("p_scholarship_id" "uuid", "p_reason" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_admit_from_provider_page_v1"("p_candidate_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'catalogue', 'pim', 'security'
    AS $$
declare c record; d record; f jsonb; v_name text; v_url text; v_norm text; v_key text; v_id uuid; v_src uuid; v_ev uuid; v_dup uuid; v_dup_sa boolean; v_apply jsonb; r jsonb;
begin
  select * into c from pipeline.scholarship_page_candidates where id=p_candidate_id for update;
  if c.id is null then return jsonb_build_object('admitted',false,'reason','no candidate'); end if;
  if c.admitted_scholarship_id is not null or c.matched_scholarship_id is not null then return jsonb_build_object('admitted',false,'reason','already handled'); end if;
  select * into d from pipeline.scholarship_discovery_providers where provider_id=c.provider_id;
  f:=c.facts; v_name:=btrim(f->'admission'->>'name'); v_url:=coalesce(c.final_url,c.url); v_norm:=security.scholarship_url_norm(v_url);
  -- the rules, checked again here from the recorded page facts
  if c.read_status is distinct from 'read' or c.storage_path is null then r:=jsonb_build_object('admitted',false,'reason','page not read');
  elsif not security.scholarship_university(c.provider_id) then r:=jsonb_build_object('admitted',false,'reason','not a university provider in a scholarship country');
  elsif not security.url_on_provider_sites(v_url, c.provider_id) or security.reference_url_has_use(v_url, 'scholarship_placeholder') then r:=jsonb_build_object('admitted',false,'reason','not on the provider site');
  elsif coalesce(v_name,'')='' or length(v_name)<8 or v_name !~* '(scholarship|bursary|award|grant|fee (remission|reduction|waiver|discount)|tuition (discount|reduction|waiver))' then r:=jsonb_build_object('admitted',false,'reason','no named scholarship title');
  elsif coalesce((f->'admission'->>'detail_page')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','not a single scholarship page');
  elsif coalesce((f->'admission'->>'international_explicit')::boolean,false) is not true or coalesce((f->>'international')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','not explicitly open to international students');
  elsif coalesce((f->'admission'->>'offered')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','not currently offered');
  elsif coalesce((f->'admission'->>'admit')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','page rules not met');
  end if;
  if r is not null then
    update pipeline.scholarship_page_candidates set admit_status='rejected', admit_reasons=array[r->>'reason'] where id=c.id;
    insert into pipeline.scholarship_admission_log(candidate_id,provider_id,action,detail) values (c.id,c.provider_id,'rejected',r);
    return r;
  end if;
  -- already held: same page, or same name at this provider
  select s.id, security.reference_url_has_use(s.source_url, 'scholarship_placeholder') into v_dup, v_dup_sa from scholarship.scholarships s
   where s.provider_id=c.provider_id and s.lifecycle_status='active'
     and (security.scholarship_url_norm(s.source_url)=v_norm or scholarship.normalise_title(s.name)=scholarship.normalise_title(v_name)
          or exists (select 1 from scholarship.identifiers i where i.scholarship_id=s.id and i.scheme='first_party_detail_url' and security.scholarship_url_norm(i.identifier_value) in (v_norm, c.url_norm))
          or exists (select 1 from pipeline.scholarship_pages sp where sp.scholarship_id=s.id and security.scholarship_url_norm(sp.url) in (v_norm, c.url_norm)))
   order by (security.reference_url_has_use(s.source_url, 'scholarship_placeholder')) limit 1;
  if v_dup is not null then
    if v_dup_sa and not exists (select 1 from pipeline.scholarship_pages where scholarship_id=v_dup) then
      -- a held Study Australia-only scholarship named by this page's heading: step 1 match, read and confirmed by the reader
      r:=security.scholarship_page_match_v1(v_dup, c.url, 'page_heading', c.id);
      update pipeline.scholarship_page_candidates set admit_status='matched_held' where id=c.id;
      insert into pipeline.scholarship_admission_log(candidate_id,scholarship_id,provider_id,action,detail) values (c.id,v_dup,c.provider_id,'matched_held',r);
      return jsonb_build_object('admitted',false,'reason','held scholarship matched','scholarship_id',v_dup,'match',r);
    end if;
    update pipeline.scholarship_page_candidates set admit_status='duplicate', admit_reasons=array['already held'] where id=c.id;
    insert into pipeline.scholarship_admission_log(candidate_id,scholarship_id,provider_id,action,detail) values (c.id,v_dup,c.provider_id,'duplicate',jsonb_build_object('name',v_name));
    return jsonb_build_object('admitted',false,'reason','already held','scholarship_id',v_dup);
  end if;

  v_key:='scholarship:'||coalesce((select k.iso_alpha2 from catalogue.providers pp join ref.countries k on k.id=pp.country_id where pp.id=c.provider_id),'AU')||':first-party:'||replace(c.provider_id::text,'-','')||':'||md5(v_norm);
  v_id:=scholarship.deterministic_uuid(v_key);
  if exists (select 1 from scholarship.scholarships where id=v_id) then
    update pipeline.scholarship_page_candidates set admit_status='duplicate', admit_reasons=array['same stable key'] where id=c.id;
    return jsonb_build_object('admitted',false,'reason','same stable key','scholarship_id',v_id);
  end if;
  v_src:=security.coverage_sweep_source(c.provider_id);
  insert into pim.entity_registry(id,entity_type,stable_key,lifecycle_status) values (v_id,'scholarship',v_key,'active') on conflict (stable_key) do update set lifecycle_status='active', updated_at=now();
  insert into pipeline.evidence_artifacts(entity_id,source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata,capture_version,evidence_group_key)
  values (v_id, v_src, 'scholarship_page', v_url, c.storage_path, c.content_hash, 'application/gzip',
          jsonb_build_object('worker','coverage-sweep scholarship_discover','decision','CF-247 scholarship discovery (Decision 139 sweep)','candidate_id',c.id,'extractor',f->>'extractor'), 1, 'scholarship:'||v_id)
  returning id into v_ev;
  insert into scholarship.scholarships(id,stable_key,provider_id,name,scholarship_type,audience,source_url,lifecycle_status,publication_status,source_id,evidence_id,confidence,award_value_type,updated_at)
  values (v_id,v_key,c.provider_id,left(v_name,300),'provider_scholarship','international',v_url,'active','unpublished',v_src,v_ev,0.9,'text_only',now());
  insert into scholarship.identifiers(scholarship_id,scheme,identifier_value,source_id,evidence_id,is_primary,status)
  values (v_id,'first_party_detail_url',v_url,v_src,v_ev,true,'active') on conflict do nothing;
  insert into pipeline.scholarship_acquisition_trace(provider_id,observed_title,first_party_detail_url,scholarship_id,verification_evidence_id,stage,verification_status,observed_at,verified_at,updated_at,metadata)
  values (c.provider_id,left(v_name,300),v_url,v_id,v_ev,'canonical_unpublished','verified_first_party',c.found_at,now(),now(),
          jsonb_build_object('admission','security.scholarship_admit_from_provider_page_v1','candidate_id',c.id,'candidate_source',c.source,'rule','single named scholarship detail page on the provider site, explicitly open to international students, currently offered'));
  insert into pipeline.scholarship_pages(scholarship_id,url,url_source,candidate_id,final_url,read_status,http_status,fetched_via,read_at,next_read_at,attempts,evidence_id,facts,name_check)
  values (v_id,v_url,'admitted',c.id,c.final_url,'read',c.http_status,c.fetched_via,c.read_at,now()+interval '90 days',0,v_ev,f,jsonb_build_object('ok',true,'basis','admitted_from_page_title','heading',v_name));
  update pipeline.scholarship_page_candidates set admit_status='admitted', admitted_scholarship_id=v_id, admitted_at=now() where id=c.id;
  insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value,evidence_id) values (v_id,'admitted',null,jsonb_build_object('name',v_name,'url',v_url,'candidate_id',c.id),v_ev);
  v_apply:=security.scholarship_sweep_apply_v1(v_id);
  insert into pipeline.scholarship_admission_log(candidate_id,scholarship_id,provider_id,action,detail) values (c.id,v_id,c.provider_id,'admitted',jsonb_build_object('name',v_name,'url',v_url,'apply',v_apply));
  return jsonb_build_object('admitted',true,'scholarship_id',v_id,'apply',v_apply);
end $$;


ALTER FUNCTION "security"."scholarship_admit_from_provider_page_v1"("p_candidate_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_control_read_impl"("p_country_code" "text" DEFAULT 'AU'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'scholarship', 'security'
    AS $$
declare v_rank int:=security.scholarship_ai_role_rank(); v_country text:=upper(coalesce(nullif(p_country_code,''),'AU')); v_result jsonb;
begin
 if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
 select jsonb_build_object(
   'country_code',v_country,
   'role_rank',v_rank,
   'settings',(select to_jsonb(s)-'schedule_actor'-'updated_by' from pipeline.scholarship_ai_settings s where s.country_code=v_country),
   'profiles',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'code',p.code,'model_identifier',p.model_identifier,'enabled',p.enabled,'paused',p.paused,'benchmark_pass',coalesce((p.quality_benchmark->>'pass')::boolean,false),'benchmark_state',coalesce(p.quality_benchmark->>'state',p.last_validation_result->>'state'),'cost_ceiling_usd',p.cost_ceiling_usd,'requests_per_minute',p.requests_per_minute,'requests_per_day',p.requests_per_day) order by p.code) from pipeline.layer3_model_profiles p where p.code like 'openrouter-scholarship-%'), '[]'::jsonb),
   'queue',jsonb_build_object(
      'unclassified',(select count(*) from pipeline.layer2_scholarship_discovery_candidates c where c.evidence_id is not null and c.classification is null),
      'needs_review',(select count(*) from pipeline.layer2_scholarship_discovery_candidates c where c.evidence_id is not null and c.classification='needs_review'),
      'detail_ready',(select count(*) from pipeline.layer2_scholarship_discovery_candidates c where c.evidence_id is not null and c.classification='detail_ready')
   ),
   'telemetry',jsonb_build_object(
      'runs_total',(select count(*) from pipeline.scholarship_ai_runs r where r.country_code=v_country),
      'runs_active',(select count(*) from pipeline.scholarship_ai_runs r where r.country_code=v_country and r.status in ('queued','running')),
      'processed',(select coalesce(sum(r.processed_items),0) from pipeline.scholarship_ai_runs r where r.country_code=v_country),
      'api_calls',(select coalesce(sum(r.api_calls),0) from pipeline.scholarship_ai_runs r where r.country_code=v_country),
      'input_tokens',(select coalesce(sum(r.input_tokens),0) from pipeline.scholarship_ai_runs r where r.country_code=v_country),
      'output_tokens',(select coalesce(sum(r.output_tokens),0) from pipeline.scholarship_ai_runs r where r.country_code=v_country),
      'cost_usd',(select coalesce(sum(r.cost_usd),0) from pipeline.scholarship_ai_runs r where r.country_code=v_country),
      'today_cost_usd',(select coalesce(sum(r.cost_usd),0) from pipeline.scholarship_ai_runs r where r.country_code=v_country and r.created_at>=date_trunc('day',now()))
   ),
   'recent_runs',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select id,country_code,task_class,profile_id,trigger_mode,changes_only,status,total_items,processed_items,validated_items,review_items,no_candidate_items,failed_items,api_calls,input_tokens,output_tokens,cost_usd,started_at,completed_at,created_at from pipeline.scholarship_ai_runs where country_code=v_country order by created_at desc limit 12) x),'[]'::jsonb)
 ) into v_result;
 return v_result;
end $$;


ALTER FUNCTION "security"."scholarship_ai_control_read_impl"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_role_rank"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
 select coalesce(max(r.rank),0)::int from security.user_roles ur join security.roles r on r.code=ur.role_code
 where ur.user_id=auth.uid() and r.status='active' and (ur.expires_at is null or ur.expires_at>now())
$$;


ALTER FUNCTION "security"."scholarship_ai_role_rank"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_run_create_impl"("p_country_code" "text", "p_task_class" "text", "p_profile_id" "uuid", "p_limit" integer, "p_trigger_mode" "text" DEFAULT 'manual'::"text", "p_changes_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_rank int:=security.scholarship_ai_role_rank(); v_actor uuid:=auth.uid(); v_profile pipeline.layer3_model_profiles%rowtype; v_run uuid; v_count int:=0; v_limit int:=least(greatest(coalesce(p_limit,10),1),100); v_benchmark boolean:=coalesce(p_trigger_mode,'manual')='benchmark';
begin
 if v_rank<4 then raise exception 'pipeline operator role required' using errcode='42501'; end if;
 select * into v_profile from pipeline.layer3_model_profiles where id=p_profile_id and p_task_class=any(allowed_task_classes);
 if not found then raise exception 'Scholarship AI model profile/task mismatch'; end if;
 if not v_benchmark and (not v_profile.enabled or v_profile.paused or coalesce((v_profile.quality_benchmark->>'pass')::boolean,false) is not true) then raise exception 'model profile benchmark must pass before governed execution'; end if;
 if v_benchmark and v_rank<5 then raise exception 'PIM Admin role required for model benchmark'; end if;
 if v_benchmark then v_limit:=least(v_limit,5); end if;
 insert into pipeline.scholarship_ai_runs(country_code,task_class,profile_id,trigger_mode,changes_only,requested_limit,requested_by,status,started_at,metadata)
 values(upper(p_country_code),p_task_class,p_profile_id,case when v_benchmark then 'benchmark' else coalesce(p_trigger_mode,'manual') end,p_changes_only,v_limit,v_actor,'queued',now(),jsonb_build_object('change_control_ref','CF-CHG-20260906-221')) returning id into v_run;
 with eligible as (
   select c.id candidate_id,c.evidence_id,e.content_hash,c.classification,c.created_at
   from pipeline.layer2_scholarship_discovery_candidates c
   join pipeline.evidence_artifacts e on e.id=c.evidence_id and e.content_hash is not null and e.storage_path is not null
   where c.evidence_id is not null
     and ((p_task_class='scholarship_page_classification' and (c.classification is null or c.classification='needs_review'))
       or (p_task_class='scholarship_detail_extract' and c.classification in ('detail_ready','needs_review')))
     and (not p_changes_only or not exists(
       select 1 from pipeline.scholarship_ai_run_items oldi
       join pipeline.scholarship_ai_runs oldr on oldr.id=oldi.run_id
       where oldi.candidate_id=c.id and oldr.task_class=p_task_class and oldi.evidence_hash=e.content_hash
         and oldi.status in ('validated','needs_review','no_candidate')
         and ((v_benchmark and oldr.trigger_mode='benchmark' and oldr.profile_id=p_profile_id)
              or (not v_benchmark and oldr.trigger_mode<>'benchmark'))
     ))
   order by case when c.classification='needs_review' then 0 when c.classification is null then 1 else 2 end,c.created_at asc,c.id
   limit v_limit
 )
 insert into pipeline.scholarship_ai_run_items(run_id,candidate_id,evidence_id,evidence_hash,metadata)
 select v_run,candidate_id,evidence_id,content_hash,jsonb_build_object('classification_at_queue',classification,'benchmark_isolated',v_benchmark) from eligible;
 get diagnostics v_count=row_count;
 update pipeline.scholarship_ai_runs set total_items=v_count,status=case when v_count=0 then 'completed' else 'queued' end,completed_at=case when v_count=0 then now() else null end where id=v_run;
 return jsonb_build_object('ok',true,'run_id',v_run,'total_items',v_count,'trigger_mode',case when v_benchmark then 'benchmark' else coalesce(p_trigger_mode,'manual') end,'changes_only',p_changes_only);
end $$;


ALTER FUNCTION "security"."scholarship_ai_run_create_impl"("p_country_code" "text", "p_task_class" "text", "p_profile_id" "uuid", "p_limit" integer, "p_trigger_mode" "text", "p_changes_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_scheduler_tick_impl"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare s pipeline.scholarship_ai_settings%rowtype; v_runs int:=0; v_changed int; v_profile pipeline.layer3_model_profiles%rowtype; v_run uuid;
begin
 for s in select * from pipeline.scholarship_ai_settings where enabled and schedule_on_change and schedule_actor is not null loop
   select * into v_profile from pipeline.layer3_model_profiles where id=s.default_profile_id and enabled and not paused and coalesce((quality_benchmark->>'pass')::boolean,false) is true;
   if not found then continue; end if;
   select count(*) into v_changed
   from pipeline.layer2_scholarship_discovery_candidates c join pipeline.evidence_artifacts e on e.id=c.evidence_id and e.content_hash is not null and e.storage_path is not null
   where c.evidence_id is not null and (c.classification is null or c.classification='needs_review')
     and not exists(select 1 from pipeline.scholarship_ai_run_items i join pipeline.scholarship_ai_runs r on r.id=i.run_id where i.candidate_id=c.id and r.task_class=s.default_task_class and r.trigger_mode<>'benchmark' and i.evidence_hash=e.content_hash and i.status in ('validated','needs_review','no_candidate'));
   if v_changed=0 then continue; end if;
   if exists(select 1 from pipeline.scholarship_ai_runs r where r.country_code=s.country_code and r.trigger_mode='scheduled' and r.status in ('queued','running')) then continue; end if;
   insert into pipeline.scholarship_ai_runs(country_code,task_class,profile_id,trigger_mode,changes_only,requested_limit,requested_by,status,started_at,metadata)
   values(s.country_code,s.default_task_class,s.default_profile_id,'scheduled',true,least(s.max_records_per_run,v_changed),s.schedule_actor,'queued',p_now,jsonb_build_object('scheduled_on_change',true,'detected_changes',v_changed,'change_control_ref','CF-CHG-20260906-221')) returning id into v_run;
   insert into pipeline.scholarship_ai_run_items(run_id,candidate_id,evidence_id,evidence_hash,metadata)
   select v_run,c.id,c.evidence_id,e.content_hash,jsonb_build_object('scheduled_on_change',true)
   from pipeline.layer2_scholarship_discovery_candidates c join pipeline.evidence_artifacts e on e.id=c.evidence_id and e.content_hash is not null and e.storage_path is not null
   where c.evidence_id is not null and (c.classification is null or c.classification='needs_review')
     and not exists(select 1 from pipeline.scholarship_ai_run_items i join pipeline.scholarship_ai_runs r on r.id=i.run_id where i.candidate_id=c.id and r.task_class=s.default_task_class and r.trigger_mode<>'benchmark' and i.evidence_hash=e.content_hash and i.status in ('validated','needs_review','no_candidate'))
   order by c.created_at asc,c.id limit s.max_records_per_run;
   update pipeline.scholarship_ai_runs set total_items=(select count(*) from pipeline.scholarship_ai_run_items where run_id=v_run) where id=v_run;
   v_runs:=v_runs+1;
 end loop;
 return jsonb_build_object('ok',true,'scheduled_runs',v_runs,'observed_at',p_now);
end $$;


ALTER FUNCTION "security"."scholarship_ai_scheduler_tick_impl"("p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_audience_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare v_changed int := 0; v_read int := 0; v_counts jsonb;
  c_intl constant text := '\m(international students?|overseas students?|student visa|subclass 500|onshore|offshore|citizens? of (india|china|sri lanka|bangladesh|indonesia|malaysia|vietnam|nepal|pakistan|philippines|thailand|cambodia|kenya|nigeria|colombia|brazil|mexico|chile|peru|hong kong|singapore|japan|korea|taiwan|turkey|saudi|uae|iran|iraq|egypt|ghana|south africa|canada|usa|united states|uk|united kingdom|germany|france|italy|spain)|from (india|china|sri lanka|bangladesh|indonesia|malaysia|vietnam|nepal|pakistan|philippines|thailand|latin america|africa|asia|europe|the americas)|full[- ]fee[- ]paying international|global excellence|international (merit|excellence|academic))\M';
  c_dom constant text := '\m(domestic students?|australian citizens?|australian permanent residents?|permanent residen(t|cy) of australia|commonwealth supported|csp|hecs|fee[- ]help|home students?|new zealand citizens?|humanitarian visa|aboriginal|torres strait|indigenous|first nations)\M';
  c_dom_nz constant text := '\m(domestic students?|new zealand citizens?|new zealand permanent residents?|permanent residen(t|cy) of new zealand|australian citizens?|home students?|fees[- ]free|studylink|student allowance|maori|māori|pasifika)\M';
  c_dom_ca constant text := '\m(domestic students?|canadian citizens?|canadian permanent residents?|permanent residents? of canada|protected persons?|indigenous|first nations|métis|metis|inuit|osap|canada student (loans?|grants?)|residents? of (british columbia|alberta|ontario|quebec|québec|manitoba|saskatchewan|nova scotia|new brunswick))\M';
  c_both constant text := '\m(all students|domestic and international|international and domestic|regardless of (citizenship|residency|nationality)|open to all)\M';
begin
  with t as (
    select s.id, lower(coalesce(s.name,'') || ' ' || coalesce(s.description,'') || ' ' || coalesce((select string_agg(c.human_text, ' ') from scholarship.criteria c where c.scholarship_id = s.id), '')) txt,
           (select k.iso_alpha2 from catalogue.providers pp join ref.countries k on k.id = pp.country_id where pp.id = s.provider_id) cc
      from scholarship.scholarships s where s.lifecycle_status = 'active'),
  r as (
    select t.id, substring(t.txt from c_intl) p_intl, substring(t.txt from case t.cc when 'NZ' then c_dom_nz when 'CA' then c_dom_ca when 'AU' then c_dom else coalesce((select '\m(' || o.domestic_terms || ')\M' from scholarship.country_onboarding o where o.country_code = t.cc and coalesce(o.domestic_terms, '') <> ''), c_dom) end) p_dom, substring(t.txt from c_both) p_both from t),
  v as (
    select r.id, case when r.p_both is not null or (r.p_intl is not null and r.p_dom is not null) then 'international_and_domestic'
                      when r.p_intl is not null then 'international' when r.p_dom is not null then 'domestic' else 'not_stated' end audience,
           r.p_intl, r.p_dom, r.p_both from r),
  up as (
    insert into scholarship.audience_readings(scholarship_id, audience, phrase_international, phrase_domestic, phrase_both, reader_version, read_at)
    select v.id, v.audience, v.p_intl, v.p_dom, v.p_both, 'scholarship-audience-v1', now() from v
    on conflict (scholarship_id) do update set audience = excluded.audience, phrase_international = excluded.phrase_international, phrase_domestic = excluded.phrase_domestic, phrase_both = excluded.phrase_both, reader_version = excluded.reader_version, read_at = now()
    returning scholarship_id)
  select count(*) into v_read from up;
  update scholarship.scholarships s set audience = a.audience, updated_at = now() from scholarship.audience_readings a where a.scholarship_id = s.id and s.lifecycle_status = 'active' and s.audience is distinct from a.audience and not security.scholarship_from_record_register(s.id) and not exists (select 1 from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id and k.field = 'audience');
  get diagnostics v_changed = row_count;
  select jsonb_object_agg(x.audience, x.n) into v_counts from (select a.audience, count(*) n from scholarship.audience_readings a group by 1) x;
  if v_changed > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('scholarships', 'audience_read', 'Audience read from each scholarship''s wording', jsonb_build_object('read', v_read, 'changed', v_changed, 'counts', v_counts, 'decision', 'Decision 244'), '63ba56cb-48d4-4169-98c2-7c4d1f72925b');
  end if;
  return jsonb_build_object('read', v_read, 'changed', v_changed, 'counts', v_counts);
end $$;


ALTER FUNCTION "security"."scholarship_audience_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_award_tiers_from_page_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare v_sch int := 0; v_tiers int := 0;
begin
  -- the value text first (the candidate set is unchanged by it), then every tier in one statement
  update scholarship.scholarships s set award_value_type = 'text_only', award_value_is_maximum = c.up_to, updated_at = now(), award_value_text = security.scholarship_tier_text(c.pcts, c.amts, c.up_to, scholarship.provider_currency(s.provider_id)) from security.scholarship_page_tier_candidates() c where c.id = s.id;
  get diagnostics v_sch = row_count;
  insert into scholarship.award_tiers(scholarship_id, tier_code, label, percentage, amount, currency_code, basis, notes, display_order, source_id, evidence_id)
  select c.id, 'page_tier_p' || o, 'Stated on the page', p, null, null, 'tuition_fee_reduction', 'One of several values stated on the provider page (Decision 245)', 100 + o, c.source_id, c.evidence_id
    from security.scholarship_page_tier_candidates() c, unnest(c.pcts) with ordinality u(p, o)
  union all
  select c.id, 'page_tier_a' || o, 'Stated on the page', null, a, scholarship.provider_currency((select x.provider_id from scholarship.scholarships x where x.id = c.id)), 'as_stated', 'One of several values stated on the provider page (Decision 245)', 200 + o, c.source_id, c.evidence_id
    from security.scholarship_page_tier_candidates() c, unnest(c.amts) with ordinality u(a, o);
  get diagnostics v_tiers = row_count;
  if v_sch > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('scholarships', 'award_tiers_from_page', 'Award tiers recorded from pages stating several values', jsonb_build_object('scholarships', v_sch, 'tiers', v_tiers, 'decision', 'Decision 245'), '63ba56cb-48d4-4169-98c2-7c4d1f72925b');
  end if;
  return jsonb_build_object('scholarships', v_sch, 'tiers', v_tiers);
end $$;


ALTER FUNCTION "security"."scholarship_award_tiers_from_page_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_country_readiness_v1"() RETURNS TABLE("country_code" "text", "country" "text", "active_courses" bigint, "providers" bigint, "universities" bigint, "switched_on" boolean, "status" "text", "domestic_terms" boolean, "nationality_term" boolean, "registers_live" integer, "registers_planned" integer, "discovery_queued" bigint, "ready" boolean, "missing" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with c as (
    select k.id, k.iso_alpha2::text cc, k.name, k.scholarship_ingestion_enabled sw,
           (select count(*) from catalogue.courses co join catalogue.providers p on p.id = co.provider_id where p.country_id = k.id and co.lifecycle_status = 'active') courses,
           (select count(*) from catalogue.providers p where p.country_id = k.id and p.lifecycle_status = 'active') providers,
           o.status, o.domestic_terms, o.government_registers
      from ref.countries k left join scholarship.country_onboarding o on o.country_code = k.iso_alpha2
     where k.scholarship_ingestion_enabled or o.country_code is not null
        or exists (select 1 from catalogue.providers p join catalogue.courses co on co.provider_id = p.id where p.country_id = k.id and co.lifecycle_status = 'active'))
  select c.cc, c.name, c.courses, c.providers,
         (select count(*) from catalogue.providers p where p.country_id = c.id and p.lifecycle_status = 'active'
             and (security.australian_university(p.id) or jsonb_array_length(coalesce(security.provider_university_groups(p.id), '[]')) > 0
                  or (p.canonical_name ~* '\m(university|université|universite)\M' and p.canonical_name !~* '(college|pathways?|language cent|senior|theology|divinity)'))) unis,
         c.sw, coalesce(c.status, 'not listed'),
         c.cc in ('AU','NZ','CA') or coalesce(c.domestic_terms, '') <> '',
         c.cc = 'AU' or exists (select 1 from ref.nationality_terms x where x.code = c.cc),
         (select count(*)::int from scholarship.registers r where r.country_code = c.cc and r.status = 'live'),
         (select count(*)::int from scholarship.registers r where r.country_code = c.cc and r.status = 'planned'),
         (select count(*) from pipeline.scholarship_discovery_providers d join catalogue.providers p on p.id = d.provider_id where p.country_id = c.id),
         x.missing = '{}', x.missing
    from c cross join lateral (select array_remove(array[
         case when c.courses = 0 then 'no active courses in the catalogue yet' end,
         case when c.status is null then 'no onboarding entry (scholarship.country_onboarding)' end,
         case when not (c.cc in ('AU','NZ','CA') or coalesce(c.domestic_terms, '') <> '') then 'no domestic-student wording for the audience reader' end,
         case when not (c.cc = 'AU' or exists (select 1 from ref.nationality_terms x where x.code = c.cc)) then 'no nationality term for the country' end,
         case when c.courses > 0 and not exists (select 1 from catalogue.providers p where p.country_id = c.id and p.lifecycle_status = 'active'
                and (security.australian_university(p.id) or jsonb_array_length(coalesce(security.provider_university_groups(p.id), '[]')) > 0
                     or (p.canonical_name ~* '\m(university|université|universite)\M' and p.canonical_name !~* '(college|pathways?|language cent|senior|theology|divinity)')))
              then 'no university providers recognised' end,
         case when c.sw and c.courses > 0 and not exists (select 1 from pipeline.scholarship_discovery_providers d join catalogue.providers p on p.id = d.provider_id where p.country_id = c.id)
              then 'switched on but no provider queued for scholarship discovery' end
       ], null) missing) x
   order by (c.courses > 0) desc, c.cc
$$;


ALTER FUNCTION "security"."scholarship_country_readiness_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_country_watch_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_raised int := 0; v_resolved int := 0; v_keys text[] := '{}';
begin
  for r in select * from security.scholarship_country_readiness_v1() where active_courses > 0 and (not switched_on or not ready) loop
    v_keys := v_keys || ('scholarship_country:' || r.country_code);
    insert into pipeline.platform_issues as i (check_key, severity, area, title, detail)
    values ('scholarship_country:' || r.country_code, 'warning', 'scholarships',
            left(case when not r.switched_on then r.country || ' has ' || r.active_courses || ' courses but scholarships are not switched on'
                      else r.country || ': scholarships switched on but not ready' end, 300),
            jsonb_build_object('country', r.country_code, 'active_courses', r.active_courses, 'universities', r.universities,
                               'switched_on', r.switched_on, 'missing', to_jsonb(r.missing), 'registers_planned', r.registers_planned,
                               'next_steps', jsonb_build_array(
                                 'Check the domestic-student wording and government registers in scholarship.country_onboarding',
                                 'Build the planned government registers (Layer 1 record registers) for the country',
                                 'Switch the country on: admin_scholarship_country(code, true, reason) - queues its universities for discovery',
                                 'Check reporting views that list countries (data quality, Zoho reference bundle)')))
    on conflict (check_key) where resolved_at is null do update set title = excluded.title, detail = excluded.detail, last_seen = now(), occurrences = i.occurrences + 1;
    v_raised := v_raised + 1;
  end loop;
  update pipeline.platform_issues set resolved_at = now()
   where resolved_at is null and check_key like 'scholarship_country:%' and not (check_key = any(v_keys));
  get diagnostics v_resolved = row_count;
  return jsonb_build_object('raised_or_updated', v_raised, 'resolved', v_resolved, 'at', now());
end $$;


ALTER FUNCTION "security"."scholarship_country_watch_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_course_attribute_sync_v1"("p_full" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'search', 'security'
    AS $$
declare v_since timestamptz; v_now timestamptz := now(); v_ids uuid[]; v_res jsonb; v_done int := 0; v_batch uuid[]; i int := 0;
begin
  select last_run_at into v_since from pipeline.scholarship_attribute_sync where id = 1;
  if p_full then
    select array_agg(distinct x) into v_ids from (
      select course_id x from scholarship.course_mappings where mapping_state = 'mapped'
      union select d.course_id from search.course_documents d where coalesce(jsonb_array_length(d.scholarship_options), 0) > 0) q;
  else
    select array_agg(distinct x) into v_ids from (
      select m.course_id x from scholarship.course_mappings m join scholarship.scholarships s on s.id = m.scholarship_id where s.updated_at > v_since
      union select fc.course_id from scholarship.course_financial_calculations fc where fc.calculated_at > v_since
      union select m.course_id from scholarship.course_mappings m join pipeline.scholarship_publication_batches b on m.scholarship_id = any(b.scholarship_ids) where b.created_at > v_since
      union select m.course_id from scholarship.course_mappings m where m.updated_at > v_since) q;
  end if;
  v_ids := coalesce(v_ids, '{}');
  while i * 2000 < cardinality(v_ids) loop
    v_batch := v_ids[i * 2000 + 1 : (i + 1) * 2000];
    v_res := search.refresh_course_enrichment_core_scoped_v1(v_batch, true);
    v_done := v_done + coalesce((v_res->>'changed')::int, 0);
    i := i + 1;
  end loop;
  v_res := jsonb_build_object('full', p_full, 'courses', cardinality(v_ids), 'changed', v_done, 'since', v_since);
  update pipeline.scholarship_attribute_sync set last_run_at = v_now, last_result = v_res where id = 1;
  return v_res;
end $$;


ALTER FUNCTION "security"."scholarship_course_attribute_sync_v1"("p_full" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_criteria_apply_v1"("p_scholarship_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare pg record; s record; v_src uuid; v_new jsonb; v_old jsonb; v_changes text[] := '{}'; v_dur text; n int;
begin
  select * into pg from pipeline.scholarship_pages where scholarship_id = p_scholarship_id;
  select * into s from scholarship.scholarships where id = p_scholarship_id;
  if s.id is null or pg.read_status is distinct from 'read' or pg.facts is null or not (pg.facts ? 'criteria') then return v_changes; end if;
  v_src := security.coverage_sweep_source(s.provider_id);

  -- the reader's criteria, in a fixed order, compared with the sweep's active rows
  select coalesce(jsonb_agg(x order by x->>'type', x->>'value_text', x->>'value_codes'), '[]') into v_new
    from (select jsonb_build_object('type', c->>'type', 'operator', c->>'operator', 'value_text', c->>'value_text',
                 'value_number', (c->>'value_number')::numeric, 'value_codes', c->'value_codes', 'scale', (c->>'scale')::numeric) x
            from jsonb_array_elements(case when jsonb_typeof(pg.facts->'criteria') = 'array' then pg.facts->'criteria' else '[]' end) c
           where c->>'type' in ('student_type','study_stage','study_load','academic_minimum','gender','nationality','application_method')) q;
  select coalesce(jsonb_agg(x order by x->>'type', x->>'value_text', x->>'value_codes'), '[]') into v_old
    from (select jsonb_build_object('type', cr.criterion_type, 'operator', cr.operator, 'value_text', cr.value_text,
                 'value_number', cr.value_number, 'value_codes', to_jsonb(cr.value_codes), 'scale', (cr.value_json->>'scale')::numeric) x
            from scholarship.criteria cr
           where cr.scholarship_id = s.id and cr.status = 'active' and cr.value_json->>'by' = 'scholarship_sweep') q;
  if v_new is distinct from v_old then
    update scholarship.criteria set status = 'superseded'
     where scholarship_id = s.id and status = 'active' and value_json->>'by' = 'scholarship_sweep';
    insert into scholarship.criteria(scholarship_id, criterion_type, operator, value_text, value_number, value_codes, value_json,
                                     human_text, is_mandatory, machine_evaluable, status, source_id, evidence_id, confidence)
    select s.id, c->>'type', c->>'operator', c->>'value_text', (c->>'value_number')::numeric,
           case when jsonb_typeof(c->'value_codes') = 'array' then array(select jsonb_array_elements_text(c->'value_codes')) end,
           jsonb_strip_nulls(jsonb_build_object('by', 'scholarship_sweep', 'extractor', coalesce(pg.facts->>'criteria_extractor', pg.facts->>'extractor'), 'scale', (c->>'scale')::numeric)),
           left(c->>'text', 300), true, c->>'type' <> 'application_method', 'active', v_src, pg.evidence_id, 0.7
      from jsonb_array_elements(case when jsonb_typeof(pg.facts->'criteria') = 'array' then pg.facts->'criteria' else '[]' end) c
     where c->>'type' in ('student_type','study_stage','study_load','academic_minimum','gender','nationality','application_method');
    get diagnostics n = row_count;
    insert into pipeline.scholarship_sweep_changes(scholarship_id, field, before_value, after_value, evidence_id)
    values (s.id, 'criteria', v_old, v_new, pg.evidence_id);
    v_changes := v_changes || 'criteria'::text;
  end if;

  -- award duration, only where the record has none (values entered by hand or by other sources stay)
  v_dur := pg.facts->'award_scope'->>'duration';
  if s.award_duration_basis is null and v_dur in ('one_off','first_year','annual','annual_program_duration','program_duration','per_semester') then
    begin
      update scholarship.scholarships set award_duration_basis = v_dur, updated_at = now() where id = s.id;
      insert into pipeline.scholarship_sweep_changes(scholarship_id, field, before_value, after_value, evidence_id)
      values (s.id, 'award_duration_basis', null, pg.facts->'award_scope', pg.evidence_id);
      v_changes := v_changes || 'award_duration'::text;
    exception when others then null; -- a value locked by hand is left as it is
    end;
  end if;
  -- Decision 212: one stated maximum ("up to $5,000", "up to 50%") is recorded as a maximum, only where the record has no value
  declare v_val jsonb := pg.facts->'value'; na int; np int; amt numeric; pct numeric;
  begin
    if not (s.award_value_type in ('percentage','fixed_amount') and coalesce(s.award_percentage, s.award_amount) is not null)
       and v_val->>'type' = 'ambiguous' and coalesce((v_val->>'up_to')::boolean, false) and not coalesce((v_val->>'foreign_currency')::boolean, false) then
      na := jsonb_array_length(case when jsonb_typeof(v_val->'amounts') = 'array' then v_val->'amounts' else '[]' end);
      np := jsonb_array_length(case when jsonb_typeof(v_val->'percentages') = 'array' then v_val->'percentages' else '[]' end);
      amt := case when na = 1 and np = 0 then (v_val->'amounts'->>0)::numeric end;
      pct := case when np = 1 and na = 0 then (v_val->'percentages'->>0)::numeric end;
      if amt between 500 and 200000 then
        update scholarship.scholarships set award_value_type = 'fixed_amount', award_amount = amt, award_currency_code = scholarship.provider_currency(s.provider_id), award_value_is_maximum = true,
               award_value_text = coalesce(award_value_text, 'Up to ' || scholarship.money_prefix(scholarship.provider_currency(s.provider_id)) || to_char(amt, 'FM999,999,999')), evidence_id = pg.evidence_id, updated_at = now()
         where id = s.id;
      elsif pct between 5 and 100 then
        update scholarship.scholarships set award_value_type = 'percentage', award_percentage = pct, award_value_is_maximum = true,
               award_applies_to_fee_type = case when coalesce(pg.facts->'award_scope'->'applies_to', '[]') ? 'tuition_fee' then coalesce(award_applies_to_fee_type, 'tuition_fee') else award_applies_to_fee_type end,
               award_value_text = coalesce(award_value_text, 'Up to ' || pct::text || '%' || case when coalesce(pg.facts->'award_scope'->'applies_to', '[]') ? 'tuition_fee' then ' of tuition fees' else '' end),
               evidence_id = pg.evidence_id, updated_at = now()
         where id = s.id;
      end if;
      if amt between 500 and 200000 or pct between 5 and 100 then
        insert into pipeline.scholarship_sweep_changes(scholarship_id, field, before_value, after_value, evidence_id)
        values (s.id, 'award_value_maximum', jsonb_build_object('type', s.award_value_type, 'text', s.award_value_text), v_val, pg.evidence_id);
        v_changes := v_changes || 'award_value_maximum'::text;
      end if;
    end if;
  exception when others then null; -- a value locked by hand is left as it is
  end;

  return v_changes;
end $_$;


ALTER FUNCTION "security"."scholarship_criteria_apply_v1"("p_scholarship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_discovery_refill_v1"("p_keep" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_pending int; v_added int := 0;
begin
  select count(*) into v_pending from pipeline.scholarship_discovery_providers where status = 'pending';
  if v_pending < p_keep then
    insert into pipeline.scholarship_discovery_providers(provider_id, website, priority, reason, status)
    select q.provider_id, q.website, case when q.cc = 'AU' then 4 else 1 end, case when q.cc = 'AU' then 'largest_unsearched' else 'university_' || lower(q.cc) end, 'pending'
      from (select p.id provider_id, k.iso_alpha2 cc,
                   coalesce(nullif(btrim(p.website), ''), (select nullif(btrim(d.website), '') from pipeline.coverage_provider_discovery d where d.provider_id = p.id and d.status = 'mapped')) website,
                   count(*) n
              from catalogue.courses co join catalogue.providers p on p.id = co.provider_id join ref.countries k on k.id = p.country_id
             where co.lifecycle_status = 'active' and k.scholarship_ingestion_enabled
               and (k.iso_alpha2 = 'AU' or security.scholarship_university(p.id))
               and not exists (select 1 from pipeline.scholarship_discovery_providers d where d.provider_id = p.id)
             group by p.id, p.website, k.iso_alpha2) q
     where q.website is not null
     order by (q.cc <> 'AU') desc, q.n desc, q.provider_id limit greatest(0, p_keep - v_pending)
    on conflict do nothing;
    get diagnostics v_added = row_count;
  end if;
  return jsonb_build_object('pending_before', v_pending, 'added', v_added);
end $$;


ALTER FUNCTION "security"."scholarship_discovery_refill_v1"("p_keep" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_fee_alignment_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_courses int := 0; v_refreshed int := 0;
begin
  for r in
    select distinct x.course_id from (
      select f.course_id from catalogue.course_fees f
       where f.audience = 'international' and f.fee_type = 'provider_current_tuition' and f.updated_at > now() - interval '70 minutes'
      union
      select c.course_id from pipeline.adapter_overwrite_changes c where c.field = 'fee' and c.at > now() - interval '70 minutes') x
    where exists (select 1 from scholarship.course_mappings m where m.course_id = x.course_id and m.mapping_state = 'mapped')
  loop
    v_courses := v_courses + 1;
    v_refreshed := v_refreshed + coalesce((scholarship.refresh_course_financial_calculations(r.course_id, null)->>'refreshed')::int, 0);
  end loop;
  return jsonb_build_object('courses', v_courses, 'refreshed', v_refreshed);
end $$;


ALTER FUNCTION "security"."scholarship_fee_alignment_v1"() OWNER TO "postgres";


