    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from scholarship.scholarships s join scholarship.registers r on r.source_id = s.source_id and r.role = 'record'
                  where s.id = p_scholarship_id)
$$;


ALTER FUNCTION "security"."scholarship_from_record_register"("p_scholarship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_held_without_page"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('scholarship_id',s.id,'name',s.name) order by s.name),'[]'::jsonb)
    from scholarship.scholarships s
   where s.provider_id=p_provider_id and s.lifecycle_status='active' and security.reference_url_has_use(s.source_url, 'scholarship_placeholder')
     and not exists (select 1 from pipeline.scholarship_pages sp where sp.scholarship_id=s.id and not (sp.url_source='discovered' and sp.read_status in ('name_mismatch','robots_disallowed','gone')))
     and not exists (select 1 from scholarship.identifiers i where i.scholarship_id=s.id and i.scheme='first_party_detail_url')
$$;


ALTER FUNCTION "security"."scholarship_held_without_page"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_level_codes"("p_levels" "jsonb") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(array_agg(distinct c),'{}') from jsonb_array_elements_text(coalesce(p_levels,'[]')) l
  cross join lateral unnest(case l
    when 'undergraduate' then array['bachelor','bachelor_honours','associate_degree']
    when 'postgraduate_coursework' then array['masters_coursework','masters_extended','masters','graduate_certificate','graduate_diploma']
    when 'research' then array['masters_research','doctorate']
    when 'pathway' then array['diploma','advanced_diploma','certificate_iv','non_aqf_award']
    else array[]::text[] end) c
$$;


ALTER FUNCTION "security"."scholarship_level_codes"("p_levels" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_maintenance_tick_impl"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'scholarship', 'catalogue'
    AS $$
declare
  v_run uuid;
  v_mappings integer:=0;
  v_candidates integer:=0;
  v_source_records integer:=0;
  v_unapplied integer:=0;
  v_discovery integer:=0;
  v_stale integer:=0;
begin
  if current_user not in('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  insert into pipeline.scholarship_maintenance_runs(status) values('running') returning id into v_run;

  with deterministic as(
    select distinct s.id scholarship_id,c.id course_id,sc.id scope_id,coalesce(sc.evidence_id,s.evidence_id) evidence_id,
      case when sc.scope_type='course' then 'explicit_course_scope' else 'explicit_provider_scope' end basis
    from scholarship.scholarships s
    join scholarship.scopes sc on sc.scholarship_id=s.id and sc.include_exclude='include'
    join catalogue.courses c
      on (sc.scope_type='course' and sc.course_id=c.id)
      or (sc.scope_type='provider' and sc.provider_id=c.provider_id)
    where sc.scope_type in('course','provider')
      and not exists(
        select 1 from scholarship.scopes ex
        where ex.scholarship_id=s.id and ex.include_exclude='exclude'
          and ((ex.scope_type='course' and ex.course_id=c.id)
            or (ex.scope_type='provider' and ex.provider_id=c.provider_id))
      )
  ), upserted as(
    insert into scholarship.course_mappings(
      scholarship_id,course_id,mapping_state,mapping_basis,source_scope_id,evidence_id,mapped_by,updated_at
    )
    select scholarship_id,course_id,'mapped',basis,scope_id,evidence_id,null,p_now
    from deterministic
    on conflict(scholarship_id,course_id) do update set
      mapping_state='mapped',
      mapping_basis=excluded.mapping_basis,
      source_scope_id=excluded.source_scope_id,
      evidence_id=excluded.evidence_id,
      updated_at=p_now
    returning 1
  )
  select count(*) into v_mappings from upserted;

  select count(*) into v_candidates
  from scholarship.course_mapping_candidates where status='needs_review';

  select count(*) into v_source_records from pipeline.scholarship_source_records;
  select count(*) into v_unapplied
  from pipeline.scholarship_source_records where status<>'applied' or applied_at is null;
  select count(*) into v_discovery
  from pipeline.layer2_scholarship_discovery_candidates where status='discovered';
  select count(*) into v_stale
  from pipeline.scholarship_source_records
  where observed_at<p_now-interval '45 days';

  update pipeline.scholarship_maintenance_runs
  set completed_at=p_now,status='completed',
      deterministic_mappings=v_mappings,
      mapping_candidates=v_candidates,
      source_records=v_source_records,
      unapplied_source_records=v_unapplied,
      discovery_candidates=v_discovery,
      stale_source_records=v_stale,
      evidence_deleted=0,
      source_records_deleted=0,
      notes=jsonb_build_object(
        'mapping_rule','explicit course/provider include scopes only',
        'evidence_retained',true,
        'source_history_retained',true
      )
  where id=v_run;

  return jsonb_build_object(
    'ok',true,'run_id',v_run,'deterministic_mappings',v_mappings,
    'mapping_candidates',v_candidates,'source_records',v_source_records,
    'unapplied_source_records',v_unapplied,'discovery_candidates',v_discovery,
    'stale_source_records',v_stale,'evidence_deleted',0,'source_records_deleted',0
  );
exception when others then
  if v_run is not null then
    update pipeline.scholarship_maintenance_runs
    set completed_at=now(),status='failed',notes=jsonb_build_object('error',sqlerrm)
    where id=v_run;
  end if;
  raise;
end $$;


ALTER FUNCTION "security"."scholarship_maintenance_tick_impl"("p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_mapping_decision_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d pipeline.scholarship_scope_decisions%rowtype;
begin
  if NEW.mapping_basis is distinct from 'sweep_level_field_scope' then return NEW; end if;
  select * into d from pipeline.scholarship_scope_decisions where scholarship_id = NEW.scholarship_id;
  if d.scholarship_id is not null and not security.scholarship_scope_match(NEW.course_id, d.decision, d.filter) then return null; end if;
  return NEW;
end $$;


ALTER FUNCTION "security"."scholarship_mapping_decision_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_nationality_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security', 'ref', 'catalogue'
    AS $$
declare v_read int := 0; v_changed int := 0; v_with int := 0;
begin
  with t as (
    select s.id, k.iso_alpha2 study_country,
           coalesce(s.name,'') || ' ' || coalesce(s.description,'') || ' ' || coalesce((select string_agg(c.human_text, ' ') from scholarship.criteria c where c.scholarship_id = s.id), '') txt
      from scholarship.scholarships s left join catalogue.providers p on p.id = s.provider_id left join ref.countries k on k.id = p.country_id
     where s.lifecycle_status = 'active'
       and not exists (select 1 from scholarship.nationality_readings a where a.scholarship_id = s.id and a.reader_version = 'scholarship-nationality-v1' and a.read_at >= s.updated_at
                         and a.read_at >= coalesce((select max(c.created_at) from scholarship.criteria c where c.scholarship_id = s.id), '-infinity'::timestamptz))
     order by (select a.read_at from scholarship.nationality_readings a where a.scholarship_id = s.id) nulls first, s.id
     limit 150),
  m as (
    select t.id, x.code,
           coalesce(substring(t.txt from ('(?i)\m(?:citizens?|nationals?|passport holders?|permanent residents?|residents?|students?|applicants?|candidates?|scholars?) (?:of|from) (?:the )?(?:' || x.names || ')\M')),
                    substring(t.txt from ('(?i)\m(?:' || coalesce(nullif(x.demonyms, ''), 'ZZZZ') || ') (?:citizens?|nationals?|passport holders?|students?|applicants?|candidates?)\M')),
                    substring(t.txt from ('(?i)\m(?:' || x.names || ') (?:citizens?|nationals?|passport holders?)\M'))) phrase
      from t, ref.nationality_terms x
     where x.code <> coalesce(t.study_country, 'AU') and not (x.code = 'AU' and coalesce(t.study_country, 'AU') in ('AU', 'NZ')) and not (x.code = 'NZ' and t.study_country = 'AU')),
  r as (
    select t.id, coalesce((select array_agg(m.code order by m.code) from m where m.id = t.id and m.phrase is not null), '{}'::text[]) codes,
           coalesce((select jsonb_object_agg(m.code, m.phrase) from m where m.id = t.id and m.phrase is not null), '{}'::jsonb) phrases
      from t),
  up as (
    insert into scholarship.nationality_readings(scholarship_id, codes, phrases, reader_version, read_at)
    select r.id, r.codes, r.phrases, 'scholarship-nationality-v1', now() from r
    on conflict (scholarship_id) do update set codes = excluded.codes, phrases = excluded.phrases, reader_version = excluded.reader_version, read_at = now()
    returning scholarship_id, codes)
  select count(*), count(*) filter (where cardinality(codes) > 0) into v_read, v_with from up;
  update scholarship.scholarships s set nationalities = a.codes, updated_at = now() from scholarship.nationality_readings a where a.scholarship_id = s.id and s.lifecycle_status = 'active' and s.nationalities is distinct from a.codes and not security.scholarship_from_record_register(s.id) and not exists (select 1 from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id and k.field = 'nationalities');
  get diagnostics v_changed = row_count;
  if v_changed > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('scholarships', 'nationality_read', 'Nationality read from each scholarship''s wording', jsonb_build_object('read', v_read, 'with_nationality', v_with, 'changed', v_changed, 'decision', 'Decision 246'), '63ba56cb-48d4-4169-98c2-7c4d1f72925b');
  end if;
  return jsonb_build_object('read', v_read, 'with_nationality', v_with, 'changed', v_changed);
end $$;


ALTER FUNCTION "security"."scholarship_nationality_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_page_match_v1"("p_scholarship_id" "uuid", "p_url" "text", "p_basis" "text", "p_candidate_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare s record; v_site text; v_norm text:=security.scholarship_url_norm(p_url);
begin
  select * into s from scholarship.scholarships where id=p_scholarship_id for update;
  if s.id is null or s.lifecycle_status<>'active' then return jsonb_build_object('matched',false,'reason','not active'); end if;
  if not security.reference_url_has_use(coalesce(s.source_url,''), 'scholarship_placeholder') then return jsonb_build_object('matched',false,'reason','already has a provider source'); end if;
  -- a page already read for it stays, except a discovered page the reader rejected (it did not name the scholarship)
  if exists (select 1 from pipeline.scholarship_pages where scholarship_id=s.id and not (url_source='discovered' and read_status in ('name_mismatch','robots_disallowed','gone')))
    then return jsonb_build_object('matched',false,'reason','already has a page'); end if;
  select coalesce(site_origin, website) into v_site from pipeline.scholarship_discovery_providers where provider_id=s.provider_id;
  if v_site is null or not security.url_on_provider_sites(p_url, s.provider_id) or security.reference_url_has_use(p_url, 'scholarship_placeholder') then return jsonb_build_object('matched',false,'reason','not on the provider site'); end if;
  if exists (select 1 from pipeline.scholarship_pages sp where security.scholarship_url_norm(sp.url)=v_norm)
     or exists (select 1 from scholarship.scholarships x where x.id<>s.id and security.scholarship_url_norm(x.source_url)=v_norm)
     or exists (select 1 from scholarship.identifiers i where i.scheme='first_party_detail_url' and security.scholarship_url_norm(i.identifier_value)=v_norm)
    then return jsonb_build_object('matched',false,'reason','page already belongs to another scholarship'); end if;
  delete from pipeline.scholarship_pages where scholarship_id=s.id and url_source='discovered' and read_status in ('name_mismatch','robots_disallowed','gone');
  insert into pipeline.scholarship_pages(scholarship_id,url,url_source,candidate_id,next_read_at) values (s.id,p_url,'discovered',p_candidate_id,now());
  if p_candidate_id is not null then
    update pipeline.scholarship_page_candidates set matched_scholarship_id=s.id, match_basis=p_basis, matched_at=now() where id=p_candidate_id;
  end if;
  insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value)
  values (s.id,'provider_page_matched',jsonb_build_object('source_url',s.source_url),jsonb_build_object('url',p_url,'basis',p_basis,'candidate_id',p_candidate_id));
  return jsonb_build_object('matched',true);
end $$;


ALTER FUNCTION "security"."scholarship_page_match_v1"("p_scholarship_id" "uuid", "p_url" "text", "p_basis" "text", "p_candidate_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_page_tier_candidates"() RETURNS TABLE("id" "uuid", "source_id" "uuid", "evidence_id" "uuid", "up_to" boolean, "pcts" numeric[], "amts" numeric[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline'
    AS $$
  with src as (
    select s.id, s.source_id, sp.evidence_id,
           coalesce((sp.facts->'value'->>'up_to')::boolean, false) up_to,
           coalesce((select array_agg(x::numeric order by x::numeric) from jsonb_array_elements_text(coalesce(sp.facts->'value'->'percentages', '[]'::jsonb)) x), '{}'::numeric[]) pcts,
           coalesce((select array_agg(x::numeric order by x::numeric) from jsonb_array_elements_text(coalesce(sp.facts->'value'->'amounts', '[]'::jsonb)) x), '{}'::numeric[]) amts
      from scholarship.scholarships s join pipeline.scholarship_pages sp on sp.scholarship_id = s.id
     where s.lifecycle_status = 'active' and (s.award_value_type is null or s.award_value_type = 'text_only')
       and sp.read_status = 'read' and sp.facts->'value'->>'type' = 'ambiguous' and coalesce((sp.facts->'value'->>'foreign_currency')::boolean, false) = false
       and not exists (select 1 from scholarship.award_tiers t where t.scholarship_id = s.id)
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id and k.field in ('award_amount', 'award_percentage', 'award_value_type', 'award_value_text')))
  select src.id, src.source_id, src.evidence_id, src.up_to, src.pcts, src.amts from src
   where cardinality(src.pcts) + cardinality(src.amts) >= 1 and cardinality(src.pcts) <= 6 and cardinality(src.amts) <= 6
$$;


ALTER FUNCTION "security"."scholarship_page_tier_candidates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_publication_review_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare v_ids uuid[];
begin
  select coalesce(array_agg(s.id),'{}') into v_ids
    from scholarship.scholarships s join security.scholarship_publishability_v1() p on p.scholarship_id=s.id
   where s.publication_status='published' and not p.publishable;
  if cardinality(v_ids)>0 then
    update scholarship.scholarships set publication_status='withdrawn', updated_at=now() where id=any(v_ids);
    insert into pipeline.scholarship_publication_batches(kind,approval_ref,scholarship_ids) values ('withdraw','Decision 139 automatic withdrawal',v_ids);
  end if;
  return jsonb_build_object('withdrawn',cardinality(v_ids));
end $$;


ALTER FUNCTION "security"."scholarship_publication_review_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_publish_batch_v1"("p_approval_ref" "text", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare v_ids uuid[]; v_before jsonb; v_after jsonb;
begin
  if coalesce(btrim(p_approval_ref),'')='' then raise exception 'approval reference required'; end if;
  select coalesce(array_agg(p.scholarship_id),'{}') into v_ids
    from security.scholarship_publishability_v1() p join scholarship.scholarships s on s.id=p.scholarship_id
   where p.publishable and coalesce(s.publication_status,'unpublished')<>'published'
     and not exists (select 1 from security.layer4_search_blocked_scholarships b where b.scholarship_id=s.id);
  if not p_apply or cardinality(v_ids)=0 then return jsonb_build_object('apply',p_apply,'eligible',cardinality(v_ids),'ids',to_jsonb(v_ids)); end if;
  v_before:=security.consumer_api_snapshot_v1();
  update scholarship.scholarships set publication_status='published', updated_at=now() where id=any(v_ids);
  insert into pipeline.scholarship_publication_batches(kind,approval_ref,scholarship_ids) values ('publish',p_approval_ref,v_ids);
  v_after:=security.consumer_api_snapshot_v1();
  insert into pipeline.consumer_api_baselines(label,snapshot) values
    ('before scholarship publication batch ('||cardinality(v_ids)||', Decision 139)',v_before),
    ('after scholarship publication batch ('||cardinality(v_ids)||', Decision 139)',v_after);
  return jsonb_build_object('apply',true,'published',cardinality(v_ids),'ids',to_jsonb(v_ids));
end $$;


ALTER FUNCTION "security"."scholarship_publish_batch_v1"("p_approval_ref" "text", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_publishability_v1"() RETURNS TABLE("scholarship_id" "uuid", "publishable" boolean, "missing" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline'
    AS $$
  select s.id,
         cardinality(m.missing)=0,
         m.missing
    from scholarship.scholarships s
    left join pipeline.scholarship_pages sp on sp.scholarship_id=s.id and sp.read_status='read'
    cross join lateral (select array_remove(array[
        case when s.lifecycle_status<>'active' then 'not active' end,
        case when coalesce(s.source_url,'')='' or security.reference_url_has_use(s.source_url, 'scholarship_placeholder') then 'no provider page' end,
        case when coalesce(s.audience,'') !~* 'international' then 'not for international students' end,
        case when sp.facts is not null and not security.scholarship_from_record_register(s.id) and coalesce(sp.facts->>'eligibility_excerpt','') ~* '(australian citizen|permanent resident|domestic student|new zealand citizen|canadian citizen)'
                  and coalesce(sp.facts->>'eligibility_excerpt','') !~* 'international' then 'provider page limits it to citizens and residents' end,
        case when sp.facts is not null and sp.facts->>'international'='false' and not security.scholarship_from_record_register(s.id) then 'provider page does not mention international students' end,
        case when not ((s.award_value_type in ('percentage','fixed_amount') and coalesce(s.award_percentage,s.award_amount) is not null) or exists (select 1 from scholarship.award_tiers t where t.scholarship_id=s.id and t.tier_code like 'page_tier_%') or (security.scholarship_from_record_register(s.id) and exists (select 1 from scholarship.coverage cv where cv.scholarship_id=s.id and cv.coverage_type='tuition_fees' and cv.percentage=100))) then 'no stated award value' end,
        case when exists (select 1 from scholarship.criteria cr where cr.scholarship_id=s.id and cr.status='active' and cr.criterion_type='student_type'
                                and cr.value_json->>'by'='scholarship_sweep' and cr.value_codes='{domestic}')
              and not exists (select 1 from scholarship.criteria cr where cr.scholarship_id=s.id and cr.status='active' and cr.criterion_type='student_type'
                                and coalesce(cr.value_json->>'by','')<>'scholarship_sweep' and 'international'=any(cr.value_codes))
             then 'eligibility lists domestic students only' end,
        case when s.evidence_id is null then 'no evidence' end,
        case when exists (select 1 from pipeline.scholarship_publication_holds h where h.scholarship_id=s.id and h.released_at is null) then 'held after hand-check' end,
        case when sp.facts is not null and coalesce((sp.facts->>'not_offered')::boolean,false) then 'not currently offered (provider page)' end,
        case when sp.facts ? 'english_course' and exists (select 1 from scholarship.course_mappings cm join catalogue.courses c on c.id=cm.course_id
                   left join ref.study_levels sl on sl.id=c.study_level_id where cm.scholarship_id=s.id and cm.mapping_state='mapped' and coalesce(sl.code,'')<>'non_aqf_award')
             then 'English language course linked to other courses' end,
        case when not exists (select 1 from scholarship.course_mappings cm where cm.scholarship_id=s.id and cm.mapping_state='mapped') then 'no linked course' end,
        case when exists (select 1 from scholarship.course_mappings cm where cm.scholarship_id=s.id and cm.mapping_state='mapped')
              and not exists (select 1 from scholarship.course_mappings cm where cm.scholarship_id=s.id and cm.mapping_state='mapped' and cm.mapping_basis<>'explicit_provider_scope')
              and s.name ~* '(engineer|undergrad|postgrad|research|ph\.?d|doctor|master|bachelor|honours|diploma|law|medic|nurs|business|commerce|science|arts|information tech|computing|education|design|music|health|pharm|faculty|school of|college of|mba)'
             then 'course link broader than the scholarship' end,
        case when greatest(s.updated_at,(select e.captured_at from pipeline.evidence_artifacts e where e.id=s.evidence_id)) < now()-interval '12 months' then 'not verified in 12 months' end
      ], null) missing) m
$$;


ALTER FUNCTION "security"."scholarship_publishability_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_reread_cadence_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'scholarship', 'security'
    AS $$
declare v_n int := 0;
begin
  update pipeline.scholarship_pages sp set next_read_at = sp.read_at + make_interval(days => security.scholarship_setting('reread_days', 30)::int) from scholarship.scholarships s where s.id = sp.scholarship_id and s.lifecycle_status = 'active' and sp.read_at is not null and (sp.next_read_at is null or sp.next_read_at > sp.read_at + make_interval(days => security.scholarship_setting('reread_days', 30)::int)) and (s.publication_status = 'published' or exists (select 1 from security.scholarship_publishability_v1() p where p.scholarship_id = s.id and p.publishable));
  get diagnostics v_n = row_count;
  return jsonb_build_object('brought_forward', v_n);
end $$;


ALTER FUNCTION "security"."scholarship_reread_cadence_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scheduler_tick_impl"("p_now" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare
  r record;
  v_dispatch jsonb;
  v_results jsonb:='[]'::jsonb;
  v_count integer:=0;
begin
  if current_user not in('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  for r in
    select s.*
    from pipeline.scholarship_etl_schedules s
    where s.enabled
      and s.next_due_at<=p_now
      and exists(
        select 1
        from pipeline.scholarship_source_qualifications q
        where q.source_key=s.source_key and q.qualification_status='qualified'
      )
    order by s.next_due_at,s.feed
    limit greatest(1,least(coalesce(p_limit,5),10))
    for update skip locked
  loop
    begin
      v_dispatch:=pipeline.svc_pilot_invoke_scholarship_edge(
        jsonb_strip_nulls(jsonb_build_object(
          'mode',r.mode,
          'feed',r.feed,
          'max_records',r.max_records,
          'page_start',r.page_start,
          'page_end',r.page_end
        ))
      );

      update pipeline.scholarship_etl_schedules
      set last_dispatched_at=p_now,
          last_request_id=nullif(v_dispatch->>'request_id','')::bigint,
          last_nonce=nullif(v_dispatch->>'nonce','')::uuid,
          last_dispatch=v_dispatch,
          last_error=null,
          next_due_at=p_now+make_interval(hours=>cadence_hours),
          updated_at=p_now
      where feed=r.feed;

      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'feed',r.feed,'status','dispatched','request_id',v_dispatch->>'request_id',
        'next_due_at',p_now+make_interval(hours=>r.cadence_hours)
      ));
      v_count:=v_count+1;
    exception when others then
      update pipeline.scholarship_etl_schedules
      set last_error=sqlerrm,next_due_at=p_now+interval '1 hour',updated_at=p_now
      where feed=r.feed;
      v_results:=v_results||jsonb_build_array(jsonb_build_object('feed',r.feed,'status','failed','error',sqlerrm));
    end;
  end loop;

  return jsonb_build_object('ok',true,'dispatched_count',v_count,'results',v_results);
end $$;


ALTER FUNCTION "security"."scholarship_scheduler_tick_impl"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scope_apply_saved_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; n int := 0;
begin
  for r in select distinct d.scholarship_id, d.decided_by from pipeline.scholarship_scope_decisions d
             join scholarship.course_mapping_candidates c on c.scholarship_id = d.scholarship_id and c.status = 'needs_review' loop
    perform security.scholarship_scope_apply_v1(r.scholarship_id, r.decided_by); n := n + 1;
  end loop;
  return n;
end $$;


ALTER FUNCTION "security"."scholarship_scope_apply_saved_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scope_apply_v1"("p_scholarship_id" "uuid", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d pipeline.scholarship_scope_decisions%rowtype; n_acc int := 0; n_rej int := 0; n_removed int := 0; n_sweep int := 0;
begin
  select * into d from pipeline.scholarship_scope_decisions where scholarship_id = p_scholarship_id;
  if d.scholarship_id is null then return jsonb_build_object('applied', false); end if;
  create temp table if not exists pg_temp._ssa(candidate_id uuid, course_id uuid, evidence_id uuid, status text, ok boolean) on commit drop;
  truncate pg_temp._ssa;
  insert into pg_temp._ssa select c.id, c.course_id, c.evidence_id, c.status, security.scholarship_scope_match(c.course_id, d.decision, d.filter)
    from scholarship.course_mapping_candidates c join catalogue.courses co on co.id = c.course_id
    join scholarship.scholarships s on s.id = c.scholarship_id
   where c.scholarship_id = p_scholarship_id and co.provider_id = s.provider_id;
  insert into scholarship.course_mappings(scholarship_id, course_id, mapping_state, mapping_basis, evidence_id, mapped_by)
  select p_scholarship_id, x.course_id, 'mapped', 'scope_decision:' || d.decision, x.evidence_id, p_actor from pg_temp._ssa x where x.ok
  on conflict (scholarship_id, course_id) do update set mapping_basis = excluded.mapping_basis, mapping_state = 'mapped', mapped_by = excluded.mapped_by, updated_at = now()
   where scholarship.course_mappings.mapping_basis in ('sweep_level_field_scope') or scholarship.course_mappings.mapping_basis like 'scope_decision:%';
  delete from scholarship.course_mappings m using pg_temp._ssa x
   where m.scholarship_id = p_scholarship_id and m.course_id = x.course_id and not x.ok and m.mapping_basis like 'scope_decision:%';
  get diagnostics n_removed = row_count;
  delete from scholarship.course_mappings m
   where m.scholarship_id = p_scholarship_id and m.mapping_basis = 'sweep_level_field_scope'
     and not security.scholarship_scope_match(m.course_id, d.decision, d.filter);
  get diagnostics n_sweep = row_count;
  update scholarship.course_mapping_candidates c set status = case when x.ok then 'accepted' else 'rejected' end, updated_at = now()
    from pg_temp._ssa x where c.id = x.candidate_id and c.status is distinct from case when x.ok then 'accepted' else 'rejected' end;
  select count(*) filter (where ok), count(*) filter (where not ok) into n_acc, n_rej from pg_temp._ssa;
  update pipeline.scholarship_scope_decisions set accepted = n_acc, rejected = n_rej, last_applied_at = now() where scholarship_id = p_scholarship_id;
  return jsonb_build_object('applied', true, 'accepted', n_acc, 'rejected', n_rej, 'removed', n_removed, 'sweep_removed', n_sweep);
end $$;


ALTER FUNCTION "security"."scholarship_scope_apply_v1"("p_scholarship_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scope_match"("p_course_id" "uuid", "p_decision" "text", "p_filter" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case p_decision when 'all' then true when 'none' then false else
    exists (select 1 from catalogue.courses c
             where c.id = p_course_id
               and (   c.id::text in (select jsonb_array_elements_text(coalesce(p_filter->'courses', '[]'::jsonb)))
                    or (    (jsonb_array_length(coalesce(p_filter->'levels', '[]'::jsonb)) > 0 or jsonb_array_length(coalesce(p_filter->'fields', '[]'::jsonb)) > 0
                             or nullif(btrim(coalesce(p_filter->>'title', '')), '') is not null)
                        and (jsonb_array_length(coalesce(p_filter->'levels', '[]'::jsonb)) = 0
                             or c.study_level_id::text in (select jsonb_array_elements_text(p_filter->'levels')))
                        and (jsonb_array_length(coalesce(p_filter->'fields', '[]'::jsonb)) = 0
                             or security.broad_field_id(c.primary_field_id)::text in (select jsonb_array_elements_text(p_filter->'fields')))
                        and (nullif(btrim(coalesce(p_filter->>'title', '')), '') is null
                             or exists (select 1 from regexp_split_to_table(p_filter->>'title', '\s*,\s*') w
                                         where btrim(w) <> '' and coalesce(c.display_title, c.canonical_title) ilike '%' || btrim(w) || '%')))))
  end
$$;


ALTER FUNCTION "security"."scholarship_scope_match"("p_course_id" "uuid", "p_decision" "text", "p_filter" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scope_suggest"("p_scholarship_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare v_name text; v_title text; v_levels jsonb := '[]'::jsonb; v_fields jsonb := '[]'::jsonb; v_why text[] := '{}';
begin
  select s.name into v_name from scholarship.scholarships s where s.id = p_scholarship_id;
  if v_name is null then return null; end if;
  if v_name ~* '\y(travel|conference|accommodation|hardship|emergency|relocation|prize|placement|exchange|study abroad|mobility|internship)\y' then
    return jsonb_build_object('decision', 'none', 'filter', '{}'::jsonb, 'why', 'The name suggests support that is not tied to a course''s tuition (for example travel or hardship).');
  end if;
  v_title := nullif(btrim(regexp_replace(substring(v_name from '(?:Bachelor|Master|Graduate Certificate|Graduate Diploma|Diploma|Doctor) of [A-Z][A-Za-z&'' -]+'),
                   '(\s+(Scholarship|Scholarships|Award|Awards|Prize|Bursary|Grant|Pioneers|Excellence|Top-Up|Fund))+\s*$', '', 'i')), '');
  if v_title is not null then
    return jsonb_build_object('decision', 'filter', 'filter', jsonb_build_object('title', v_title), 'why', 'The name mentions one course: ' || v_title || '.');
  end if;
  if v_name ~* '\y(research|phd|doctoral|hdr|higher degree)\y' then
    v_levels := (select jsonb_agg(id) from ref.study_levels where name in ('Doctorate / PhD','Masters Degree (Research)')); v_why := array_append(v_why, 'research degrees');
  elsif v_name ~* '\yundergraduate\y' then
    v_levels := (select jsonb_agg(id) from ref.study_levels where name in ('Bachelor','Bachelor Honours Degree','Diploma','Advanced Diploma','Associate Degree')); v_why := array_append(v_why, 'undergraduate courses');
  elsif v_name ~* '\y(postgraduate|masters|master''s)\y' then
    v_levels := (select jsonb_agg(id) from ref.study_levels where name in ('Masters Degree (Coursework)','Masters Degree (Extended)','Graduate Certificate','Graduate Diploma','Masters')); v_why := array_append(v_why, 'postgraduate coursework');
  end if;
  v_fields := (select jsonb_agg(id) from ref.fields_of_study where path ~ '^asced/[0-9]{2}$' and (
                  (path = 'asced/02' and v_name ~* '\y(IT|information technology|computing|computer|data science|cyber)\y')
               or (path = 'asced/03' and v_name ~* '\yengineering\y')
               or (path = 'asced/04' and v_name ~* '\y(architecture|built environment|building)\y')
               or (path = 'asced/06' and v_name ~* '\y(health|medicine|medical|nursing|pharmacy|dentistry|physiotherapy)\y')
               or (path = 'asced/07' and v_name ~* '\y(education|teaching)\y')
               or (path = 'asced/08' and v_name ~* '\y(business|commerce|accounting|finance|MBA|management|economics)\y')
               or (path = 'asced/09' and v_name ~* '\y(law|arts|humanities|social science|psychology)\y')
               or (path = 'asced/10' and v_name ~* '\y(creative|music|design|fine art|media)\y')
               or (path = 'asced/01' and v_name ~* '\yscience\y' and v_name !~* '\y(computer|data|social) science\y')));
  if v_fields is not null then v_why := array_append(v_why, 'the field named in the title'); end if;
  if jsonb_array_length(coalesce(v_levels, '[]'::jsonb)) > 0 or v_fields is not null then
    return jsonb_build_object('decision', 'filter', 'filter', jsonb_strip_nulls(jsonb_build_object('levels', v_levels, 'fields', v_fields)),
                              'why', 'The name points to ' || array_to_string(v_why, ' and ') || '.');
  end if;
  return jsonb_build_object('decision', 'all', 'filter', '{}'::jsonb, 'why', 'The name does not narrow it down; check the scholarship page before accepting all.');
end $_$;


