CREATE OR REPLACE FUNCTION "security"."search_pass_advance_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_next text; n_ver int := 0; n_next int := 0; n_none int := 0;
begin
  update pipeline.search_pass_links l set state = 'verified', updated_at = now() from pipeline.coverage_course_pages p where l.state = 'found' and p.course_id = l.course_id and p.url = l.bound_url and p.status = 'bound' and p.identity_basis is not null;
  get diagnostics n_ver = row_count;
  for r in select l.*, p.status pstatus from pipeline.search_pass_links l join pipeline.coverage_course_pages p on p.course_id = l.course_id and p.url = l.bound_url
            where l.state = 'found' and (p.status = 'mismatch' or (p.read_status in ('fetch_failed', 'blocked', 'robots_disallowed') and (p.read_attempts >= 2 or p.http_status in (404, 410)))) loop
    if r.cand_idx < jsonb_array_length(r.candidates) then
      v_next := r.candidates->>r.cand_idx;
      insert into pipeline.page_link_repairs(course_id, provider_id, old_url, new_url, reason, run_id) values (r.course_id, r.provider_id, r.bound_url, v_next, 'search pass: next candidate after the reader refused the page', r.run_id);
      update pipeline.coverage_course_pages set url = v_next, basis = case when r.engine = 'firecrawl' then 'firecrawl_search' else 'serper_search' end, status = 'bound', bound_at = now(), read_status = null, read_at = null, http_status = null, fetched_via = null, identity_basis = null, evidence_id = null, read_attempts = 0, next_read_at = now(), leased_until = null where course_id = r.course_id and url = r.bound_url;
      update pipeline.search_pass_links set cand_idx = cand_idx + 1, bound_url = v_next, updated_at = now() where course_id = r.course_id;
      n_next := n_next + 1;
    else
      update pipeline.search_pass_links set state = 'none', updated_at = now() where course_id = r.course_id;
      n_none := n_none + 1;
    end if;
  end loop;
  return jsonb_build_object('verified', n_ver, 'next_candidate', n_next, 'none', n_none);
end $$;


ALTER FUNCTION "security"."search_pass_advance_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."search_refresh_requested_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'search'
    AS $$
declare v_ids bigint[]; r jsonb;
begin
  select array_agg(id) into v_ids from search.refresh_requests where processed_at is null;
  if v_ids is null then return jsonb_build_object('pending',0); end if;
  r := search.refresh_course_documents_v3(true);
  update search.refresh_requests set processed_at=now(), result=jsonb_build_object('base_applied',r->'base'->'applied_rows','base_changed',r->'base'->'changed','generation',r->'base'->'generation') where id = any(v_ids);
  return jsonb_build_object('processed',cardinality(v_ids),'base_applied',r->'base'->'applied_rows');
end $$;


ALTER FUNCTION "security"."search_refresh_requested_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."semester_intake_apply_v1"("p_provider_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security', 'search'
    AS $$
declare r record; v_ev pipeline.evidence_artifacts%rowtype; v_ok int := 0; v_err int := 0; v_last text; v_courses uuid[] := '{}'; v_reason text;
  v_names text[] := array['January','February','March','April','May','June','July','August','September','October','November','December'];
begin
  for r in select * from security.semester_intake_plan_v1(p_provider_id) where outcome = 'answer' loop
    begin
      select * into v_ev from pipeline.evidence_artifacts where id = (select evidence_id from pipeline.layer4_review_items where id = r.review_id);
      perform security.coverage_apply_course_v1(r.course_id, security.coverage_sweep_source(r.provider_id), v_ev.id, v_ev.source_url, v_ev.content_hash,
        jsonb_build_object('intakes', (select jsonb_agg(jsonb_build_object('intake_label', v_names[m], 'source_intake_key', 'calendar:' || r.course_id || ':' || lower(v_names[m])))
                                         from unnest(r.months) m)));
      v_reason := 'Answered from the course page (' || left(r.quotes, 200) || ') and the university''s approved calendar ('
                  || (select string_agg(initcap(replace(x, '_', ' ')) || ' starts in ' || v_names[(security.calendar_period_months(r.provider_id)->>x)::int], '; ') from unnest(r.periods) x)
                  || '); Decision 228.';
      update pipeline.layer4_review_items set status = 'superseded', decided_at = now(), escalation_reason = v_reason where id = r.review_id and status = 'pending';
      v_ok := v_ok + 1; v_courses := v_courses || r.course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if v_ok > 0 then
    insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
    select distinct 'courses', 'course_intake', security.coverage_sweep_source(c.provider_id), 'approved', 'CF-CHG-20260915-247; Decision 228 (intakes from the course page and the approved calendar)', now(), now(), now()
      from catalogue.courses c where c.id = any(v_courses)
       and not exists (select 1 from search.enrichment_source_gates g where g.projection_code = 'courses' and g.domain_code = 'course_intake' and g.source_id = security.coverage_sweep_source(c.provider_id));
    perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
  end if;
  return jsonb_build_object('answered', v_ok, 'refused', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "security"."semester_intake_apply_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."semester_intake_plan_v1"("p_provider_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("review_id" "uuid", "course_id" "uuid", "provider_id" "uuid", "title" "text", "quotes" "text", "periods" "text"[], "months" integer[], "outcome" "text", "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
begin
  return query
  with r as (
    select l.id, l.entity_id cid, c.provider_id pid, c.canonical_title t,
           (select string_agg(q, ' | ') from jsonb_array_elements_text(coalesce(l.layer3_state->'answer'->'quotes', '[]'::jsonb)) q) qs
      from pipeline.layer4_review_items l join catalogue.courses c on c.id = l.entity_id
     where l.status = 'pending' and l.entity_type = 'course' and l.field_code = 'course_intake' and l.before_value is null and l.evidence_id is not null
       and (p_provider_id is null or c.provider_id = p_provider_id)),
  p as (select r.*, security.quoted_study_periods(r.qs) per, security.calendar_period_months(r.pid) cal, security.calendar_set_by_hand(r.pid) byhand from r),
  q as (
    select p.*, (select array_agg(distinct (p.cal->>x)::int order by (p.cal->>x)::int) from unnest(p.per) x where p.cal ? x) mon,
           (select count(*) from unnest(p.per) x where not p.cal ? x) missing
      from p where cardinality(p.per) > 0)
  select q.id, q.cid, q.pid, q.t, q.qs, q.per, q.mon,
         case when q.qs ~* '\m(january|february|march|april|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\M' then 'held'
              when q.qs ~* '\m(hong kong|HK|singapore|malaysia|sarawak|dubai|mauritius|sri lanka|vietnam|china|indonesia|online)\M' then 'held'
              when q.cal = '{}'::jsonb then 'no_calendar'
              when q.missing > 0 and not (q.byhand and q.mon is not null) then 'period_unknown'
              when exists (select 1 from catalogue.course_intakes i where i.course_id = q.cid and i.status = 'active') then 'held'
              when exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = q.cid and k.field = 'intakes') then 'held'
              else 'answer' end,
         case when q.qs ~* '\m(january|february|march|april|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\M' then 'the quotes also name months'
              when q.qs ~* '\m(hong kong|HK|singapore|malaysia|sarawak|dubai|mauritius|sri lanka|vietnam|china|indonesia|online)\M' then 'the quotes name a campus outside Australia or online study'
              when q.cal = '{}'::jsonb then 'no approved calendar for this university'
              when q.missing > 0 and not (q.byhand and q.mon is not null) then 'a period has no approved start month'
              when exists (select 1 from catalogue.course_intakes i where i.course_id = q.cid and i.status = 'active') then 'the course already has intakes'
              when exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = q.cid and k.field = 'intakes') then 'intakes set by hand'
              end
    from q;
end $$;


ALTER FUNCTION "security"."semester_intake_plan_v1"("p_provider_id" "uuid") OWNER TO "postgres";


