CREATE OR REPLACE FUNCTION "security"."uni_adapter_pattern_ok"("p" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p is null or btrim(p) = '' then return true; end if;
  if position('.|\s' in p) > 0 or position('\s|.' in p) > 0 or position('.|\W' in p) > 0 or position('\S|\s' in p) > 0 or position('\s|\S' in p) > 0 then return false; end if;
  perform '' ~* p;
  return true;
exception when others then return false;
end $$;


ALTER FUNCTION "security"."uni_adapter_pattern_ok"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."uni_adapter_requeue_v1"("p_provider_id" "uuid", "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int; v_ids uuid[];
begin
  -- 5 Oct: a page refused after a Firecrawl read is sent back once only, and only when the adapter reads page data
  v_ids := array(select pg.course_id from pipeline.coverage_course_pages pg
                  where pg.provider_id = p_provider_id and exists (select 1 from pipeline.uni_adapters u0 where u0.provider_id = pg.provider_id and coalesce(u0.json_source, '') <> '') and (pg.read_status = 'needs_render' or (pg.read_status = 'identity_mismatch' and pg.fetched_via = 'firecrawl' and exists (select 1 from pipeline.uni_adapters u where u.provider_id = pg.provider_id and coalesce(u.json_source, '') <> '') and not exists (select 1 from pipeline.page_link_repairs x where x.course_id = pg.course_id and x.reason like 'university adapter: page read again%')))
                    and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = pg.course_id and k.field = 'official_url'));
  insert into pipeline.page_link_repairs(course_id, provider_id, old_url, new_url, reason)
    select pg.course_id, pg.provider_id, pg.url, pg.url, 'university adapter: page read again (' || p_reason || ')'
    from pipeline.coverage_course_pages pg where pg.course_id = any (v_ids);
  update pipeline.coverage_course_pages pg set status = 'bound', read_status = 'needs_render', next_read_at = now(), leased_until = null where pg.course_id = any (v_ids);
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "security"."uni_adapter_requeue_v1"("p_provider_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."uni_adapter_view_requeue_v1"("p_provider_id" "uuid", "p_reason" "text", "p_limit" integer DEFAULT 600) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int; v_ids uuid[]; v_pat text;
begin
  select coalesce(nullif(btrim(u.page_view->>'url_pattern'), ''), '.') into v_pat from pipeline.uni_adapters u
   where u.provider_id = p_provider_id and u.enabled and coalesce(u.page_view->>'render', 'false') = 'true';
  if v_pat is null then raise exception 'the adapter names no international view to read'; end if;
  v_ids := array(select pg.course_id from pipeline.coverage_course_pages pg join pipeline.uni_adapters u on u.provider_id = pg.provider_id
                  join catalogue.courses co on co.id = pg.course_id and co.lifecycle_status = 'active'
                  where pg.provider_id = p_provider_id and pg.url is not null
                    and ((pg.url ~* v_pat and pg.read_status in ('read', 'identity_mismatch', 'needs_render', 'fetch_failed', 'blocked')
                          and (pg.read_at is null or pg.read_at < u.updated_at))
                      or (pg.url !~* v_pat and pg.read_status <> 'read'
                          and exists (select 1 from pipeline.page_link_repairs x where x.course_id = pg.course_id and x.reason like 'university adapter: international view read%')))
                  order by pg.course_id limit greatest(1, least(coalesce(p_limit, 600), 600)));
  insert into pipeline.page_link_repairs(course_id, provider_id, old_url, new_url, reason)
    select pg.course_id, pg.provider_id, pg.url, pg.url, case when pg.url ~* v_pat then 'university adapter: international view read (' else 'university adapter: read again outside the international view (' end || left(p_reason, 300) || ')'
    from pipeline.coverage_course_pages pg where pg.course_id = any (v_ids);
  update pipeline.coverage_course_pages pg set status = 'bound', read_status = 'needs_render', read_attempts = 0, next_read_at = now(), leased_until = null where pg.course_id = any (v_ids);
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "security"."uni_adapter_view_requeue_v1"("p_provider_id" "uuid", "p_reason" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."uni_adapter_view_requeue_v2"("p_provider_id" "uuid", "p_reason" "text", "p_limit" integer, "p_only" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int; v_ids uuid[]; v_pat text; v_sfx text; v_only text := coalesce(nullif(btrim(p_only), ''), 'all');
begin
  if v_only not in ('all', 'view', 'outside') then raise exception 'only must be all, view or outside'; end if;
  select coalesce(nullif(btrim(u.page_view->>'url_pattern'), ''), '.'), coalesce(u.page_view->>'suffix', '') into v_pat, v_sfx from pipeline.uni_adapters u
   where u.provider_id = p_provider_id and u.enabled and coalesce(u.page_view->>'render', 'false') = 'true';
  if v_pat is null then raise exception 'the adapter names no international view to read'; end if;
  v_ids := array(select pg.course_id from pipeline.coverage_course_pages pg
                  join catalogue.courses co on co.id = pg.course_id and co.lifecycle_status = 'active'
                  where pg.provider_id = p_provider_id and pg.url is not null
                    and ((v_only in ('all', 'view') and pg.url ~* v_pat and pg.read_status in ('read', 'identity_mismatch', 'needs_render', 'fetch_failed', 'blocked')
                          and (v_sfx = '' or strpos(coalesce(pg.candidates->>'final_url', ''), substr(v_sfx, 2)) = 0))
                      or (v_only in ('all', 'outside') and pg.url !~* v_pat and pg.read_status <> 'read'
                          and exists (select 1 from pipeline.page_link_repairs x where x.course_id = pg.course_id and x.reason like 'university adapter: international view read%')))
                  order by pg.course_id limit greatest(1, least(coalesce(p_limit, 600), 600)));
  insert into pipeline.page_link_repairs(course_id, provider_id, old_url, new_url, reason)
    select pg.course_id, pg.provider_id, pg.url, pg.url, case when pg.url ~* v_pat then 'university adapter: international view read (' else 'university adapter: read again outside the international view (' end || left(p_reason, 300) || ')'
    from pipeline.coverage_course_pages pg where pg.course_id = any (v_ids);
  update pipeline.coverage_course_pages pg set status = 'bound', read_status = 'needs_render', read_attempts = 0, next_read_at = now(), leased_until = null where pg.course_id = any (v_ids);
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "security"."uni_adapter_view_requeue_v2"("p_provider_id" "uuid", "p_reason" "text", "p_limit" integer, "p_only" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."university_course_delivery_v1"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('value', c.delivery_mode,
           'read', pg.candidates->'adapter_extra'->>'mode',
           'source', case when nullif(c.delivery_mode, '') is null then 'missing'
                          when exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field in ('delivery_mode', 'delivery')) then 'hand'
                          when exists (select 1 from pipeline.adapter_overwrite_changes x where x.course_id = c.id and x.field = 'delivery' and x.after = to_jsonb(c.delivery_mode)) then 'adapter'
                          else 'other' end,
           'excluded', security.uni_adapter_excluded(c.id, 'delivery'))
  from catalogue.courses c left join pipeline.coverage_course_pages pg on pg.course_id = c.id
  where c.id = p_course_id
$$;


ALTER FUNCTION "security"."university_course_delivery_v1"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."university_course_fields_v1"("p_provider_id" "uuid") RETURNS TABLE("course_id" "uuid", "course" "text", "code" "text", "level" "text", "url" "text", "read_status" "text", "evidence_id" "uuid", "intakes" "text"[], "intakes_src" "text", "intakes_x" boolean, "ielts" numeric, "english_src" "text", "english_x" boolean, "fee" numeric, "fee_year" integer, "fee_currency" "text", "fee_src" "text", "fee_x" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select c.id, coalesce(c.display_title, c.canonical_title), c.course_code, sl.code, pg.url, pg.read_status, pg.evidence_id,
         i.months,
         case when i.months is null then 'missing'
              when exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field in ('intakes', 'intake')) then 'hand'
              when i.calendar then 'central'
              when pg.evidence_id is not null and i.from_page then case when pg.candidates->>'intakes_by' = 'adapter' then 'adapter' else 'reader' end
              else 'other' end,
         security.uni_adapter_excluded(c.id, 'intakes'),
         e.overall_score,
         case when e.id is null then 'missing'
              when exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field in ('english', 'english_requirements')) then 'hand'
              when e.source_requirement_key like 'policy:%' then 'central'
              when pg.evidence_id is not null and e.evidence_id = pg.evidence_id then case when pg.candidates->>'english_by' = 'adapter' then 'adapter' else 'reader' end
              else 'other' end,
         security.uni_adapter_excluded(c.id, 'english'),
         f.amount, f.fee_year, f.currency_code,
         case when f.id is null then 'missing'
              when exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field in ('tuition', 'fee', 'fees')) then 'hand'
              when pg.evidence_id is not null and f.evidence_id = pg.evidence_id then case when pg.candidates->>'fee_by' = 'adapter' then 'adapter' else 'reader' end
              else 'other' end,
         security.uni_adapter_excluded(c.id, 'fee')
  from catalogue.courses c
  left join ref.study_levels sl on sl.id = c.study_level_id
  left join pipeline.coverage_course_pages pg on pg.course_id = c.id
  left join lateral (select array_agg(distinct x.intake_label order by x.intake_label) months,
                            bool_or(coalesce(x.source_intake_key, '') like 'calendar%') calendar,
                            bool_or(pg.evidence_id is not null and x.evidence_id = pg.evidence_id) from_page
                       from catalogue.course_intakes x where x.course_id = c.id and x.status = 'active') i on true
  left join lateral (select r.id, r.overall_score, r.source_requirement_key, r.evidence_id from catalogue.course_english_requirements r join ref.english_tests t on t.id = r.english_test_id
                      where r.course_id = c.id and t.code = 'IELTS' and coalesce(r.status, 'active') = 'active' order by r.last_verified_at desc nulls last limit 1) e on true
  left join lateral (select x.id, x.amount, x.fee_year, x.currency_code, x.evidence_id from catalogue.course_fees x
                      where x.course_id = c.id and x.status = 'active' and x.fee_type = 'provider_current_tuition' and x.audience = 'international'
                      order by x.fee_year desc nulls last, x.updated_at desc nulls last limit 1) f on true
  where c.provider_id = p_provider_id and c.lifecycle_status = 'active'
$$;


ALTER FUNCTION "security"."university_course_fields_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."university_course_host_v1"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (select jsonb_build_object('kind', x.link_type, 'host', pc.canonical_title, 'host_course_id', x.parent_course_id, 'years', x.exit_years, 'register_check', x.register_check, 'active', x.active, 'applied', x.applied_at is not null)
       from pipeline.course_exit_awards x join catalogue.courses pc on pc.id = x.parent_course_id where x.child_course_id = p_course_id),
    (select jsonb_build_object('kind', h.link_type, 'host', hc.canonical_title, 'host_course_id', h.host_course_id, 'url', h.host_url, 'register_check', h.register_check, 'active', h.active, 'applied', h.applied_at is not null, 'set_by', h.set_by)
       from pipeline.course_host_pages h left join catalogue.courses hc on hc.id = h.host_course_id where h.course_id = p_course_id))
$$;


ALTER FUNCTION "security"."university_course_host_v1"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."university_course_location_v1"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
           'value', coalesce((select string_agg(distinct cp.name, ', ' order by cp.name) from catalogue.course_campuses cc join catalogue.campuses cp on cp.id = cc.campus_id where cc.course_id = p_course_id),
                             case when co.delivery_mode = 'online' then 'Online' end),
           'read', coalesce(pg.candidates->'adapter_extra'->>'campus', pg.candidates->'adapter_extra'->>'location'),
           'source', case when exists (select 1 from catalogue.course_campuses cc where cc.course_id = p_course_id) then 'catalogue'
                          when co.delivery_mode = 'online' then 'catalogue'
                          when coalesce(pg.candidates->'adapter_extra'->>'campus', pg.candidates->'adapter_extra'->>'location') is not null then 'adapter'
                          else 'missing' end)
  from (select 1) one left join catalogue.courses co on co.id = p_course_id left join pipeline.coverage_course_pages pg on pg.course_id = p_course_id
$$;


