CREATE OR REPLACE VIEW "pipeline"."au_nz_enrichment_backlog_v1" WITH ("security_invoker"='true') AS
 WITH "search_base" AS (
         SELECT "course_documents"."course_id",
            "course_documents"."country_code",
            "course_documents"."has_link",
            "course_documents"."has_intake",
            "course_documents"."has_english",
            "course_documents"."has_provider_current_tuition",
            "course_documents"."has_scholarship"
           FROM "search"."course_documents"
          WHERE ("course_documents"."country_code" = ANY (ARRAY['AU'::"text", 'NZ'::"text"]))
        ), "scoped" AS (
         SELECT 'AU'::"text" AS "country_code",
            "s"."profile_id",
            "s"."profile_key",
            "s"."provider_id",
            "s"."provider_name",
            "s"."course_id",
            "s"."source_url"
           FROM "public"."layer2_scope_courses"('AU'::"text", 'country'::"text", NULL::"uuid") "s"("profile_id", "profile_key", "provider_id", "provider_name", "course_id", "source_url")
        UNION ALL
         SELECT 'NZ'::"text" AS "country_code",
            "s"."profile_id",
            "s"."profile_key",
            "s"."provider_id",
            "s"."provider_name",
            "s"."course_id",
            "s"."source_url"
           FROM "public"."layer2_scope_courses"('NZ'::"text", 'country'::"text", NULL::"uuid") "s"("profile_id", "profile_key", "provider_id", "provider_name", "course_id", "source_url")
        ), "exec_policy" AS (
         SELECT "layer2_execution_policies"."profile_id",
            "bool_or"("layer2_execution_policies"."enabled") AS "enabled"
           FROM "pipeline"."layer2_execution_policies"
          GROUP BY "layer2_execution_policies"."profile_id"
        ), "joined" AS (
         SELECT "sb"."course_id",
            "sb"."country_code",
            "sb"."has_link",
            "sb"."has_intake",
            "sb"."has_english",
            "sb"."has_provider_current_tuition",
            "sb"."has_scholarship",
            "sc"."profile_id",
            "sc"."profile_key",
            "sc"."provider_id",
            "sc"."provider_name",
            "sc"."source_url",
            COALESCE("ep"."enabled", false) AS "execution_policy_enabled"
           FROM (("search_base" "sb"
             LEFT JOIN "scoped" "sc" ON ((("sc"."country_code" = "sb"."country_code") AND ("sc"."course_id" = "sb"."course_id"))))
             LEFT JOIN "exec_policy" "ep" ON (("ep"."profile_id" = "sc"."profile_id")))
        ), "fields" AS (
         SELECT "j"."course_id",
            "j"."country_code",
            "j"."has_link",
            "j"."has_intake",
            "j"."has_english",
            "j"."has_provider_current_tuition",
            "j"."has_scholarship",
            "j"."profile_id",
            "j"."profile_key",
            "j"."provider_id",
            "j"."provider_name",
            "j"."source_url",
            "j"."execution_policy_enabled",
            "f"."field_key",
            "f"."covered"
           FROM ("joined" "j"
             CROSS JOIN LATERAL ( VALUES ('official_course_url'::"text","j"."has_link"), ('intake_availability'::"text","j"."has_intake"), ('english_requirements'::"text","j"."has_english"), ('provider_current_international_tuition'::"text","j"."has_provider_current_tuition"), ('scholarship'::"text","j"."has_scholarship")) "f"("field_key", "covered"))
        )
 SELECT "course_id",
    "country_code",
    "field_key",
    "covered",
    "profile_id",
    "profile_key",
    "provider_id",
    "provider_name",
    "source_url",
    "execution_policy_enabled",
        CASE
            WHEN "covered" THEN 'covered'::"text"
            WHEN ("field_key" = 'scholarship'::"text") THEN 'awaiting_source_profile_qualification'::"text"
            WHEN ("profile_id" IS NULL) THEN 'awaiting_source_profile_qualification'::"text"
            WHEN (("source_url" IS NOT NULL) AND "execution_policy_enabled") THEN 'queueable'::"text"
            WHEN (("source_url" IS NOT NULL) AND (NOT "execution_policy_enabled")) THEN 'blocked'::"text"
            WHEN (("source_url" IS NULL) AND "execution_policy_enabled") THEN 'blocked'::"text"
            ELSE 'awaiting_source_profile_qualification'::"text"
        END AS "backlog_state",
        CASE
            WHEN "covered" THEN NULL::"text"
            WHEN ("field_key" = 'scholarship'::"text") THEN 'scholarship_requires_separate_qualified_scholarship_source_and_admission_path'::"text"
            WHEN ("profile_id" IS NULL) THEN 'no_qualified_course_fact_profile_in_current_scope'::"text"
            WHEN (("source_url" IS NOT NULL) AND "execution_policy_enabled") THEN NULL::"text"
            WHEN (("source_url" IS NOT NULL) AND (NOT "execution_policy_enabled")) THEN 'execution_policy_not_enabled_for_profile'::"text"
            WHEN (("source_url" IS NULL) AND "execution_policy_enabled") THEN 'course_url_requires_governed_discovery'::"text"
            WHEN ("source_url" IS NULL) THEN 'course_url_requires_discovery_and_execution_policy'::"text"
            ELSE 'not_queueable'::"text"
        END AS "blocker_reason",
    "now"() AS "observed_at"
   FROM "fields";


ALTER VIEW "pipeline"."au_nz_enrichment_backlog_v1" OWNER TO "postgres";


COMMENT ON VIEW "pipeline"."au_nz_enrichment_backlog_v1" IS 'CF-245 per-course/per-field AU/NZ enrichment demand classification. Missing values are never synthesized.';



CREATE OR REPLACE VIEW "pipeline"."au_nz_enrichment_backlog_summary_v1" WITH ("security_invoker"='true') AS
 SELECT "country_code",
    "field_key",
    "backlog_state",
    COALESCE("blocker_reason", ''::"text") AS "blocker_reason",
    "count"(*) AS "courses"
   FROM "pipeline"."au_nz_enrichment_backlog_v1"
  GROUP BY "country_code", "field_key", "backlog_state", COALESCE("blocker_reason", ''::"text");


