CREATE OR REPLACE VIEW "pipeline"."cf245_layer3_fee_validation_backlog_v1" WITH ("security_barrier"='true') AS
 WITH "ranked" AS (
         SELECT "r_1"."id",
            "r_1"."source_id",
            "r_1"."source_record_id",
            "r_1"."source_url",
            "r_1"."provider_cricos",
            "r_1"."course_cricos",
            "r_1"."content_hash",
            "r_1"."evidence_id",
            "r_1"."parsed_payload",
            "r_1"."status",
            "r_1"."observed_at",
            "r_1"."applied_at",
            "r_1"."error_text",
            "q"."admitted_domains",
            "q"."metadata" AS "qualification_metadata",
            "row_number"() OVER (PARTITION BY "r_1"."source_id", "r_1"."course_cricos" ORDER BY "r_1"."observed_at" DESC, "r_1"."id" DESC) AS "rn"
           FROM ("pipeline"."course_fact_source_records" "r_1"
             JOIN "pipeline"."course_fact_source_qualifications" "q" ON ((("q"."source_id" = "r_1"."source_id") AND ("upper"("btrim"("q"."provider_cricos")) = "upper"("btrim"("r_1"."provider_cricos"))) AND ("q"."qualification_status" = ANY (ARRAY['qualified'::"text", 'bounded'::"text"])))))
          WHERE (("r_1"."status" = 'observed'::"text") AND ("r_1"."evidence_id" IS NOT NULL) AND COALESCE((("r_1"."parsed_payload" ->> 'identity_match'::"text"))::boolean, false) AND COALESCE((("r_1"."parsed_payload" ->> 'regulatory_code_seen'::"text"))::boolean, false))
        )
 SELECT "id" AS "source_record_id",
    "source_id",
    "evidence_id",
    (("parsed_payload" ->> 'course_id'::"text"))::"uuid" AS "course_id",
    "provider_cricos",
    "course_cricos",
    "source_url",
    "observed_at",
    ("parsed_payload" -> 'provider_current_tuition'::"text") AS "candidate_payload",
    'requires_layer3_fee_validation'::"text" AS "reason_code",
    'benchmark_required_before_automatic_interpretation'::"text" AS "execution_state",
    'CF-CHG-20260915-245'::"text" AS "change_control_ref"
   FROM "ranked" "r"
  WHERE (("rn" = 1) AND ('international_fee'::"text" = ANY ("admitted_domains")) AND COALESCE((("parsed_payload" ->> 'fee_safe'::"text"))::boolean, false) AND ((NULLIF((("parsed_payload" -> 'provider_current_tuition'::"text") ->> 'amount'::"text"), ''::"text"))::numeric > (0)::numeric) AND (COALESCE((("parsed_payload" -> 'provider_current_tuition'::"text") ->> 'basis'::"text"), ''::"text") = 'annual_or_indicative_requires_validation'::"text") AND (NULLIF(("parsed_payload" ->> 'course_id'::"text"), ''::"text") IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM "catalogue"."courses" "c"
          WHERE ("c"."id" = (("r"."parsed_payload" ->> 'course_id'::"text"))::"uuid"))) AND (NOT "security"."layer4_entity_or_parent_blocked"('course'::"text", (("parsed_payload" ->> 'course_id'::"text"))::"uuid", 'operational'::"text")) AND (NOT (EXISTS ( SELECT 1
           FROM "catalogue"."course_fees" "f"
          WHERE (("f"."course_id" = (("r"."parsed_payload" ->> 'course_id'::"text"))::"uuid") AND ("f"."fee_type" = 'provider_current_tuition'::"text") AND (COALESCE("f"."status", 'active'::"text") = 'active'::"text"))))));


ALTER VIEW "pipeline"."cf245_layer3_fee_validation_backlog_v1" OWNER TO "postgres";


