CREATE OR REPLACE VIEW "pipeline"."evidence_acquisition_provenance_v1" AS
 SELECT DISTINCT ON ("e"."id") "e"."id" AS "evidence_id",
    "e"."evidence_type",
    "e"."source_url",
    "e"."mime_type",
    "e"."captured_at",
    "e"."capture_version",
    "ap"."provider_key" AS "acquisition_tool",
    "ap"."display_name" AS "acquisition_tool_name",
    "ap"."adapter_type",
    ("ap"."request_template" ->> 'response_adapter'::"text") AS "response_adapter",
    "a"."id" AS "attempt_id",
    "a"."status" AS "attempt_status",
    "a"."response_http_status",
    "a"."response_mime_type",
    "a"."runtime_platform",
    "a"."runtime_region",
    "a"."started_at",
    "a"."completed_at",
        CASE
            WHEN ("e"."id" = "a"."raw_evidence_id") THEN 'raw'::"text"
            WHEN ("e"."id" = "a"."html_evidence_id") THEN 'html'::"text"
            WHEN ("e"."id" = "a"."screenshot_evidence_id") THEN 'screenshot'::"text"
            ELSE NULL::"text"
        END AS "evidence_role"
   FROM (("pipeline"."evidence_artifacts" "e"
     JOIN "pipeline"."layer2_provider_attempts" "a" ON ((("e"."id" = "a"."raw_evidence_id") OR ("e"."id" = "a"."html_evidence_id") OR ("e"."id" = "a"."screenshot_evidence_id"))))
     JOIN "pipeline"."layer2_acquisition_providers" "ap" ON (("ap"."id" = "a"."acquisition_provider_id")))
  ORDER BY "e"."id", "a"."completed_at" DESC NULLS LAST;


ALTER VIEW "pipeline"."evidence_acquisition_provenance_v1" OWNER TO "postgres";


