    "ends_on" "date",
    CONSTRAINT "important_dates_bounded_scope_check" CHECK ((("scope_type" = 'country_reference'::"text") OR ("source_id" IS NOT NULL) OR ("source_profile_id" IS NOT NULL) OR ("entity_id" IS NOT NULL))),
    CONSTRAINT "important_dates_check1" CHECK ((("date_precision" <> 'source_vague'::"text") OR ("source_wording" IS NOT NULL))),
