    CONSTRAINT "important_dates_exact_source_value_check" CHECK ((("date_precision" <> 'exact'::"text") OR ("starts_at" IS NOT NULL) OR ("starts_on" IS NOT NULL))),
    CONSTRAINT "important_dates_refresh_layer_check" CHECK ((("refresh_layer" >= 1) AND ("refresh_layer" <= 4))),
    CONSTRAINT "important_dates_scope_type_check" CHECK (("scope_type" = ANY (ARRAY['source'::"text", 'provider'::"text", 'course'::"text", 'scholarship'::"text", 'country_reference'::"text"]))),
    CONSTRAINT "important_dates_source_url_check" CHECK (("source_url" ~* '^https?://'::"text")),
    CONSTRAINT "important_dates_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'expired'::"text", 'cancelled'::"text", 'unverified'::"text"])))
);


