CREATE OR REPLACE VIEW "pipeline"."layer2_enrichment_operational_ledger_v1" WITH ("security_invoker"='true') AS
 WITH "evidence_by_job" AS (
         SELECT "e"."job_id",
            ("count"(*))::integer AS "evidence_count",
            ("count"(*) FILTER (WHERE ("e"."evidence_type" = 'layer2_screenshot'::"text")))::integer AS "screenshot_evidence_count",
            ("count"(*) FILTER (WHERE ("e"."evidence_type" = 'layer2_extraction_input'::"text")))::integer AS "normalized_evidence_count"
           FROM "pipeline"."evidence_artifacts" "e"
          WHERE ("e"."job_id" IS NOT NULL)
          GROUP BY "e"."job_id"
        ), "base" AS (
         SELECT "ri"."id" AS "run_item_id",
            "ri"."batch_id",
            "rb"."profile_id",
            "ri"."entity_type",
            "ri"."entity_id",
            "ri"."source_url",
            "ri"."status" AS "run_item_status",
            "ri"."outcome_code",
            "ri"."failure_class",
            "ri"."blocker",
            "ri"."fields_targeted",
            "ri"."fields_resolved",
            GREATEST((COALESCE("ri"."fields_targeted", 0) - COALESCE("ri"."fields_resolved", 0)), 0) AS "fields_unresolved",
            "ri"."vendor_units",
            "ri"."vendor_cost_usd",
            "ri"."retry_count",
            "ri"."response_ms",
            "ri"."extraction_ms",
            "ri"."evidence_bytes" AS "recorded_evidence_bytes",
            "ri"."created_at" AS "queued_at",
            "ri"."started_at",
            "ri"."completed_at",
            "ri"."updated_at",
                CASE
                    WHEN ("ri"."started_at" IS NOT NULL) THEN GREATEST((0)::bigint, ("round"((EXTRACT("epoch" FROM ("ri"."started_at" - "ri"."created_at")) * (1000)::numeric)))::bigint)
                    ELSE NULL::bigint
                END AS "queue_wait_ms",
                CASE
                    WHEN (("ri"."started_at" IS NOT NULL) AND (COALESCE("ri"."completed_at", "ri"."updated_at") IS NOT NULL)) THEN GREATEST((0)::bigint, ("round"((EXTRACT("epoch" FROM (COALESCE("ri"."completed_at", "ri"."updated_at") - "ri"."started_at")) * (1000)::numeric)))::bigint)
                    ELSE NULL::bigint
                END AS "execution_ms",
            "j"."id" AS "job_id",
            "j"."job_type",
            "j"."domain",
            "j"."status" AS "job_status",
            "j"."created_at" AS "job_created_at",
            "j"."started_at" AS "job_started_at",
            "j"."completed_at" AS "job_completed_at",
            "j"."result" AS "job_result",
            "pa"."id" AS "provider_attempt_id",
            "pa"."profile_version_id" AS "source_profile_version_id",
            "pa"."acquisition_provider_id",
            "ap"."provider_key" AS "acquisition_provider_key",
            "pa"."attempt_no",
            "pa"."status" AS "provider_attempt_status",
            "pa"."response_http_status",
            "pa"."extraction_status",
            "pa"."blocker" AS "provider_attempt_blocker",
            "pa"."metrics" AS "provider_attempt_metrics",
            COALESCE("ebj"."evidence_count", 0) AS "evidence_count",
            COALESCE("ebj"."screenshot_evidence_count", 0) AS "screenshot_evidence_count",
            COALESCE("ebj"."normalized_evidence_count", 0) AS "normalized_evidence_count",
            (NULLIF(("pa"."metrics" ->> 'bytes'::"text"), ''::"text"))::bigint AS "known_response_bytes",
            (NULLIF(("pa"."metrics" ->> 'latency_ms'::"text"), ''::"text"))::integer AS "provider_response_ms",
            (NULLIF(("pa"."metrics" ->> 'vendor_units'::"text"), ''::"text"))::numeric AS "attempt_vendor_units",
            (NULLIF(("pa"."metrics" ->> 'estimated_request_cost_usd'::"text"), ''::"text"))::numeric AS "attempt_vendor_cost_usd",
            COALESCE((("pa"."metrics" ->> 'content_changed'::"text"))::boolean, (("j"."result" ->> 'content_changed'::"text"))::boolean) AS "content_changed",
            "sr"."id" AS "source_record_id",
            "sr"."status" AS "source_record_status",
            "sr"."applied_at" AS "source_record_applied_at",
            "sr"."parsed_payload",
            "sp"."profile_key",
            "sp"."domain" AS "profile_domain",
            "c_1"."id" AS "course_id",
            "c_1"."course_code",
            "c_1"."provider_id",
            "p"."display_name" AS "provider_name",
            TRIM(BOTH FROM "rc"."iso_alpha2") AS "country_code",
            "sd"."has_link" AS "search_has_official_link",
            "sd"."has_intake" AS "search_has_intake",
            "sd"."has_english" AS "search_has_english",
            "sd"."has_provider_current_tuition" AS "search_has_provider_current_tuition",
            "sd"."has_scholarship" AS "search_has_scholarship"
           FROM (((((((((((("pipeline"."layer2_run_items" "ri"
             JOIN "pipeline"."layer2_run_batches" "rb" ON (("rb"."id" = "ri"."batch_id")))
             LEFT JOIN "pipeline"."jobs" "j" ON (("j"."id" = "ri"."job_id")))
             LEFT JOIN "pipeline"."layer2_provider_attempts" "pa" ON (("pa"."job_id" = "j"."id")))
             LEFT JOIN "pipeline"."layer2_acquisition_providers" "ap" ON (("ap"."id" = "pa"."acquisition_provider_id")))
             LEFT JOIN "evidence_by_job" "ebj" ON (("ebj"."job_id" = "j"."id")))
             LEFT JOIN "pipeline"."course_fact_source_records" "sr" ON ((("sr"."evidence_id")::"text" = ("pa"."metrics" ->> 'normalised_evidence_id'::"text"))))
             LEFT JOIN "pipeline"."layer2_source_profile_versions" "spv" ON (("spv"."id" = COALESCE("pa"."profile_version_id", "j"."source_profile_version_id"))))
             LEFT JOIN "pipeline"."layer2_source_profiles" "sp" ON (("sp"."id" = COALESCE("spv"."profile_id", "rb"."profile_id"))))
             LEFT JOIN "catalogue"."courses" "c_1" ON ((("ri"."entity_type" = 'course'::"text") AND ("c_1"."id" = "ri"."entity_id"))))
             LEFT JOIN "catalogue"."providers" "p" ON (("p"."id" = "c_1"."provider_id")))
             LEFT JOIN "ref"."countries" "rc" ON (("rc"."id" = "p"."country_id")))
             LEFT JOIN "search"."course_documents" "sd" ON (("sd"."course_id" = "c_1"."id")))
        ), "classified" AS (
         SELECT "b"."run_item_id",
            "b"."batch_id",
            "b"."profile_id",
            "b"."entity_type",
            "b"."entity_id",
            "b"."source_url",
            "b"."run_item_status",
            "b"."outcome_code",
            "b"."failure_class",
            "b"."blocker",
            "b"."fields_targeted",
            "b"."fields_resolved",
            "b"."fields_unresolved",
            "b"."vendor_units",
            "b"."vendor_cost_usd",
            "b"."retry_count",
            "b"."response_ms",
            "b"."extraction_ms",
            "b"."recorded_evidence_bytes",
            "b"."queued_at",
            "b"."started_at",
            "b"."completed_at",
            "b"."updated_at",
            "b"."queue_wait_ms",
            "b"."execution_ms",
            "b"."job_id",
            "b"."job_type",
            "b"."domain",
            "b"."job_status",
            "b"."job_created_at",
            "b"."job_started_at",
            "b"."job_completed_at",
            "b"."job_result",
            "b"."provider_attempt_id",
            "b"."source_profile_version_id",
            "b"."acquisition_provider_id",
            "b"."acquisition_provider_key",
            "b"."attempt_no",
            "b"."provider_attempt_status",
            "b"."response_http_status",
            "b"."extraction_status",
            "b"."provider_attempt_blocker",
            "b"."provider_attempt_metrics",
            "b"."evidence_count",
            "b"."screenshot_evidence_count",
            "b"."normalized_evidence_count",
            "b"."known_response_bytes",
            "b"."provider_response_ms",
            "b"."attempt_vendor_units",
            "b"."attempt_vendor_cost_usd",
            "b"."content_changed",
            "b"."source_record_id",
            "b"."source_record_status",
            "b"."source_record_applied_at",
            "b"."parsed_payload",
            "b"."profile_key",
            "b"."profile_domain",
            "b"."course_id",
            "b"."course_code",
            "b"."provider_id",
            "b"."provider_name",
            "b"."country_code",
            "b"."search_has_official_link",
            "b"."search_has_intake",
            "b"."search_has_english",
            "b"."search_has_provider_current_tuition",
            "b"."search_has_scholarship",
            "array_remove"(ARRAY[
                CASE
                    WHEN (((("b"."parsed_payload" -> 'baseline_factual'::"text") ->> 'course_url'::"text") = 'not_yet_enriched'::"text") AND (COALESCE(("b"."parsed_payload" ->> 'official_course_url'::"text"), ''::"text") = ''::"text")) THEN 'official_course_url'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (((("b"."parsed_payload" -> 'baseline_factual'::"text") ->> 'intakes'::"text") = 'not_yet_enriched'::"text") AND (COALESCE(("b"."parsed_payload" -> 'intakes'::"text"), '[]'::"jsonb") = '[]'::"jsonb")) THEN 'intakes'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (((("b"."parsed_payload" -> 'baseline_factual'::"text") ->> 'english_requirements'::"text") = 'not_yet_enriched'::"text") AND (COALESCE(("b"."parsed_payload" -> 'english_requirements'::"text"), '{}'::"jsonb") = '{}'::"jsonb")) THEN 'english_requirements'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (((("b"."parsed_payload" -> 'baseline_factual'::"text") ->> 'provider_current_tuition'::"text") = 'not_yet_enriched'::"text") AND ((("b"."parsed_payload" -> 'provider_current_tuition'::"text") IS NULL) OR (("b"."parsed_payload" -> 'provider_current_tuition'::"text") = 'null'::"jsonb"))) THEN 'provider_current_tuition'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (((("b"."parsed_payload" -> 'baseline_factual'::"text") ->> 'description'::"text") = 'not_yet_enriched'::"text") AND ((("b"."parsed_payload" -> 'description_candidate'::"text") IS NULL) OR (("b"."parsed_payload" -> 'description_candidate'::"text") = 'null'::"jsonb"))) THEN 'description'::"text"
                    ELSE NULL::"text"
                END], NULL::"text") AS "unresolved_domains"
           FROM "base" "b"
        )
 SELECT "run_item_id",
    "batch_id",
    "profile_id",
    "entity_type",
    "entity_id",
    "source_url",
    "run_item_status",
    "outcome_code",
    "failure_class",
    "blocker",
    "fields_targeted",
    "fields_resolved",
    "fields_unresolved",
    "vendor_units",
    "vendor_cost_usd",
    "retry_count",
    "response_ms",
    "extraction_ms",
    "recorded_evidence_bytes",
    "queued_at",
    "started_at",
    "completed_at",
    "updated_at",
    "queue_wait_ms",
    "execution_ms",
    "job_id",
    "job_type",
    "domain",
    "job_status",
    "job_created_at",
    "job_started_at",
    "job_completed_at",
    "job_result",
    "provider_attempt_id",
    "source_profile_version_id",
    "acquisition_provider_id",
    "acquisition_provider_key",
    "attempt_no",
    "provider_attempt_status",
    "response_http_status",
    "extraction_status",
    "provider_attempt_blocker",
    "provider_attempt_metrics",
    "evidence_count",
    "screenshot_evidence_count",
    "normalized_evidence_count",
    "known_response_bytes",
    "provider_response_ms",
    "attempt_vendor_units",
    "attempt_vendor_cost_usd",
    "content_changed",
    "source_record_id",
    "source_record_status",
    "source_record_applied_at",
    "parsed_payload",
    "profile_key",
    "profile_domain",
    "course_id",
    "course_code",
    "provider_id",
    "provider_name",
    "country_code",
    "search_has_official_link",
    "search_has_intake",
    "search_has_english",
    "search_has_provider_current_tuition",
    "search_has_scholarship",
    "unresolved_domains",
        CASE
            WHEN ("run_item_status" = 'blocked'::"text") THEN COALESCE(NULLIF("failure_class", ''::"text"), 'runtime_blocked'::"text")
            WHEN ("provider_attempt_id" IS NULL) THEN 'capture_or_attempt_not_started'::"text"
            WHEN ("provider_attempt_status" = 'failed'::"text") THEN 'provider_or_runtime_blocker'::"text"
            WHEN (("extraction_status" = ANY (ARRAY['not_attempted'::"text", 'acquired'::"text"])) AND ("source_record_id" IS NULL)) THEN 'extraction_not_completed'::"text"
            WHEN (COALESCE((("parsed_payload" ->> 'identity_match'::"text"))::boolean, true) = false) THEN 'identity_mismatch'::"text"
            WHEN (("run_item_status" = 'layer3_required'::"text") AND ("cardinality"("unresolved_domains") > 0)) THEN 'layer3_unresolved_target_fields'::"text"
            WHEN ("run_item_status" = 'layer3_required'::"text") THEN 'layer3_required'::"text"
            WHEN (("source_record_applied_at" IS NULL) AND ("run_item_status" = 'resolved_l2'::"text")) THEN 'resolved_candidate_not_admitted'::"text"
            WHEN ("source_record_applied_at" IS NOT NULL) THEN 'admitted'::"text"
            ELSE COALESCE(NULLIF("outcome_code", ''::"text"), "run_item_status", 'unknown'::"text")
        END AS "stop_reason_code",
    NULLIF(("parsed_payload" ->> 'fee_rejection_reason'::"text"), ''::"text") AS "fee_rejection_reason",
    COALESCE((("parsed_payload" ->> 'identity_match'::"text"))::boolean, true) AS "identity_match",
    COALESCE((("parsed_payload" ->> 'canonical_mutation_authorised'::"text"))::boolean, (("job_result" ->> 'canonical_mutation_authorised'::"text"))::boolean, false) AS "canonical_mutation_authorised",
        CASE
            WHEN ("source_record_applied_at" IS NOT NULL) THEN COALESCE("fields_resolved", 0)
            ELSE 0
        END AS "fields_admitted_lower_bound",
        CASE
            WHEN ("source_record_applied_at" IS NULL) THEN 0
            ELSE NULL::integer
        END AS "fields_rejected_known",
    COALESCE("recorded_evidence_bytes", "known_response_bytes") AS "evidence_bytes_known",
    ("recorded_evidence_bytes" IS NOT NULL) AS "evidence_bytes_complete",
    COALESCE("updated_at", "completed_at", "job_completed_at", "started_at", "job_started_at", "queued_at") AS "operational_event_at"
   FROM "classified" "c";


ALTER VIEW "pipeline"."layer2_enrichment_operational_ledger_v1" OWNER TO "postgres";


COMMENT ON VIEW "pipeline"."layer2_enrichment_operational_ledger_v1" IS 'CF-245 governed operational ledger derived from Layer 2 run items, jobs, attempts, Evidence, candidates and Search state. Observability only; no mutation authority.';



CREATE OR REPLACE VIEW "pipeline"."layer2_enrichment_hourly_v1" WITH ("security_invoker"='true') AS
 SELECT "date_trunc"('hour'::"text", COALESCE("job_started_at", "started_at", "job_created_at", "queued_at")) AS "hour_utc",
    "country_code",
    "profile_domain" AS "domain",
    ("count"(*))::integer AS "items",
    ("count"(*) FILTER (WHERE ("started_at" IS NOT NULL)))::integer AS "started",
    ("count"(*) FILTER (WHERE ("provider_attempt_status" = 'succeeded'::"text")))::integer AS "fetched",
    ("count"(*) FILTER (WHERE ("provider_attempt_status" = 'failed'::"text")))::integer AS "fetch_failures",
    "sum"("evidence_count") AS "evidence_created",
    ("sum"(COALESCE("evidence_bytes_known", (0)::bigint)))::bigint AS "evidence_bytes_known",
    "bool_and"("evidence_bytes_complete") AS "evidence_bytes_complete",
    ("count"(*) FILTER (WHERE ("extraction_status" = 'normalised'::"text")))::integer AS "extraction_attempted",
    ("count"(*) FILTER (WHERE (COALESCE(("parsed_payload" ->> 'official_course_url'::"text"), ''::"text") <> ''::"text")))::integer AS "official_urls_found",
    ("count"(*) FILTER (WHERE (COALESCE(("parsed_payload" -> 'intakes'::"text"), '[]'::"jsonb") <> '[]'::"jsonb")))::integer AS "intakes_found",
    ("count"(*) FILTER (WHERE (COALESCE(("parsed_payload" -> 'english_requirements'::"text"), '{}'::"jsonb") <> '{}'::"jsonb")))::integer AS "english_requirements_found",
    ("count"(*) FILTER (WHERE ((("parsed_payload" -> 'provider_current_tuition'::"text") IS NOT NULL) AND (("parsed_payload" -> 'provider_current_tuition'::"text") <> 'null'::"jsonb"))))::integer AS "provider_current_tuition_found",
    0 AS "scholarships_found",
    "sum"("fields_admitted_lower_bound") AS "facts_admitted_lower_bound",
    ("count"(*) FILTER (WHERE ("content_changed" = false)))::integer AS "unchanged",
    ("count"(*) FILTER (WHERE ("stop_reason_code" = ANY (ARRAY['identity_mismatch'::"text", 'provider_or_runtime_blocker'::"text", 'runtime_blocked'::"text"]))))::integer AS "rejected_or_blocked",
    ("count"(*) FILTER (WHERE ("run_item_status" = 'layer3_required'::"text")))::integer AS "layer3_escalated",
    ("count"(*) FILTER (WHERE ("run_item_status" ~~* '%layer4%'::"text")))::integer AS "layer4_referred",
    ("count"(*) FILTER (WHERE ("source_record_applied_at" IS NOT NULL)))::integer AS "courses_improved_lower_bound",
    "sum"(COALESCE("attempt_vendor_units", (0)::numeric)) AS "vendor_units",
    "sum"(COALESCE("attempt_vendor_cost_usd", (0)::numeric)) AS "vendor_cost_usd",
    "percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("response_ms")::double precision)) FILTER (WHERE ("response_ms" IS NOT NULL)) AS "p50_response_ms",
    "percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY (("response_ms")::double precision)) FILTER (WHERE ("response_ms" IS NOT NULL)) AS "p95_response_ms",
    "percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("extraction_ms")::double precision)) FILTER (WHERE ("extraction_ms" IS NOT NULL)) AS "p50_extraction_ms",
    "percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY (("extraction_ms")::double precision)) FILTER (WHERE ("extraction_ms" IS NOT NULL)) AS "p95_extraction_ms",
    "sum"(COALESCE("retry_count", 0)) AS "retries",
    ("count"(*) FILTER (WHERE ("response_http_status" = 429)))::integer AS "http_429",
    ("count"(*) FILTER (WHERE ("response_http_status" >= 500)))::integer AS "http_5xx",
    ("count"(*) FILTER (WHERE (("run_item_status" = 'blocked'::"text") OR ("failure_class" IS NOT NULL))))::integer AS "other_runtime_failures"
   FROM "pipeline"."layer2_enrichment_operational_ledger_v1"
  GROUP BY ("date_trunc"('hour'::"text", COALESCE("job_started_at", "started_at", "job_created_at", "queued_at"))), "country_code", "profile_domain";


ALTER VIEW "pipeline"."layer2_enrichment_hourly_v1" OWNER TO "postgres";


COMMENT ON VIEW "pipeline"."layer2_enrichment_hourly_v1" IS 'CF-245 hourly enrichment outcome metrics; service-role only until governed Admin read projection is added.';



