    "qualification_provider_wave_size" integer DEFAULT 50 NOT NULL,
    "qualification_provider_wave_max" integer DEFAULT 100 NOT NULL,
    "qualification_sample_size" integer DEFAULT 10 NOT NULL,
    "qualification_retry_hours" integer DEFAULT 168 NOT NULL,
    "production_target_wave_size" integer DEFAULT 500 NOT NULL,
    "production_max_wave_size" integer DEFAULT 1000 NOT NULL,
    "schedule_remaining" boolean DEFAULT true NOT NULL,
    "route_mode" "text" DEFAULT 'scraper_first'::"text" NOT NULL,
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "change_control_ref" "text" DEFAULT 'CF-CHG-20260830-048'::"text" NOT NULL,
    "qualification_finalizer_run_limit" integer DEFAULT 2 NOT NULL,
    "qualification_pattern_provider_limit" integer DEFAULT 3 NOT NULL,
    CONSTRAINT "layer2_execution_policy_production_max_wave_size_check" CHECK ((("production_max_wave_size" >= 1) AND ("production_max_wave_size" <= 5000))),
    CONSTRAINT "layer2_execution_policy_production_target_wave_size_check" CHECK ((("production_target_wave_size" >= 1) AND ("production_target_wave_size" <= 5000))),
    CONSTRAINT "layer2_execution_policy_qualification_finalizer_run_limit_check" CHECK ((("qualification_finalizer_run_limit" >= 1) AND ("qualification_finalizer_run_limit" <= 10))),
    CONSTRAINT "layer2_execution_policy_qualification_pattern_provider_limit_ch" CHECK ((("qualification_pattern_provider_limit" >= 1) AND ("qualification_pattern_provider_limit" <= 5))),
    CONSTRAINT "layer2_execution_policy_qualification_provider_wave_max_check" CHECK ((("qualification_provider_wave_max" >= 1) AND ("qualification_provider_wave_max" <= 500))),
    CONSTRAINT "layer2_execution_policy_qualification_provider_wave_size_check" CHECK ((("qualification_provider_wave_size" >= 1) AND ("qualification_provider_wave_size" <= 200))),
    CONSTRAINT "layer2_execution_policy_qualification_retry_hours_check" CHECK ((("qualification_retry_hours" >= 1) AND ("qualification_retry_hours" <= 2160))),
    CONSTRAINT "layer2_execution_policy_qualification_sample_size_check" CHECK ((("qualification_sample_size" >= 1) AND ("qualification_sample_size" <= 50))),
    CONSTRAINT "layer2_execution_policy_route_mode_check" CHECK (("route_mode" = ANY (ARRAY['scraper_first'::"text", 'managed'::"text"])))
);


