    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "onboarding_cases_adapter_family_check" CHECK ((("adapter_family" IS NULL) OR ("adapter_family" = ANY (ARRAY['structured_api'::"text", 'csv_xlsx'::"text", 'json'::"text", 'xml'::"text", 'sitemap_catalogue'::"text", 'html_detail'::"text", 'document_pdf'::"text", 'direct_http'::"text", 'approved_scraper_browser'::"text", 'custom_adapter'::"text"])))),
    CONSTRAINT "onboarding_cases_case_type_check" CHECK (("case_type" = ANY (ARRAY['country'::"text", 'source'::"text", 'provider'::"text", 'course'::"text"]))),
    CONSTRAINT "onboarding_cases_check" CHECK ((("case_type" <> 'provider'::"text") OR ("provider_id" IS NOT NULL))),
    CONSTRAINT "onboarding_cases_check1" CHECK ((("case_type" <> 'course'::"text") OR ("course_id" IS NOT NULL))),
    CONSTRAINT "onboarding_cases_check2" CHECK ((("case_type" <> 'source'::"text") OR ("source_id" IS NOT NULL))),
    CONSTRAINT "onboarding_cases_country_code_check" CHECK ((("country_code" IS NULL) OR ("country_code" ~ '^[A-Z]{2}$'::"text"))),
    CONSTRAINT "onboarding_cases_outcome_check" CHECK ((("outcome" IS NULL) OR ("outcome" = ANY (ARRAY['READY'::"text", 'CONDITIONAL'::"text", 'BLOCKED'::"text", 'PAUSED'::"text", 'REJECTED'::"text"])))),
    CONSTRAINT "onboarding_cases_stage_check" CHECK (("stage" = ANY (ARRAY['draft'::"text", 'source_qualification'::"text", 'adapter_assessment'::"text", 'schema_assessment'::"text", 'l1_uat'::"text", 'l2_uat'::"text", 'l3_ready'::"text", 'operational_certification'::"text", 'production_promotion_ready'::"text"]))),
    CONSTRAINT "onboarding_cases_title_check" CHECK ((("length"(TRIM(BOTH FROM "title")) >= 3) AND ("length"(TRIM(BOTH FROM "title")) <= 240)))
);


