CREATE OR REPLACE VIEW "pipeline"."scholarship_candidate_classification_stats" AS
 SELECT "s"."provider_id",
    "p"."canonical_name" AS "provider_name",
    "count"(*) AS "candidate_total",
    "count"(*) FILTER (WHERE (("c"."status" = 'discovered'::"text") AND ("c"."classification" = ANY (ARRAY['detail_ready'::"text", 'detail_redirect'::"text"])))) AS "detail_ready_total",
    "count"(*) FILTER (WHERE (("c"."status" = 'discovered'::"text") AND ("c"."classification" = 'needs_review'::"text"))) AS "needs_review_total",
    "count"(*) FILTER (WHERE ("c"."status" = 'rejected'::"text")) AS "rejected_total",
    "count"(*) FILTER (WHERE ("c"."status" = 'acquired'::"text")) AS "acquired_total",
    "max"("c"."classified_at") AS "last_classified_at"
   FROM (("pipeline"."layer2_scholarship_discovery_candidates" "c"
     JOIN "pipeline"."sources" "s" ON (("s"."id" = "c"."source_id")))
     JOIN "catalogue"."providers" "p" ON (("p"."id" = "s"."provider_id")))
  GROUP BY "s"."provider_id", "p"."canonical_name";


