    "application_open_date" "date",
    "application_close_date" "date",
    "academic_year" integer,
    "source_url" "text",
    "lifecycle_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "publication_status" "text" DEFAULT 'unpublished'::"text" NOT NULL,
    "source_id" "uuid",
    "evidence_id" "uuid",
    "confidence" numeric(5,4),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "award_value_type" "text",
    "award_percentage" numeric(7,4),
    "award_amount" numeric(14,2),
    "award_currency_code" character(3),
    "award_applies_to_fee_type" "text",
    "award_fee_basis" "text",
    "award_duration_basis" "text",
    "award_value_is_maximum" boolean DEFAULT false NOT NULL,
    "nationalities" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    CONSTRAINT "scholarships_award_percentage_check" CHECK ((("award_percentage" IS NULL) OR (("award_percentage" > (0)::numeric) AND ("award_percentage" <= (100)::numeric)))),
    CONSTRAINT "scholarships_award_value_type_check" CHECK ((("award_value_type" IS NULL) OR ("award_value_type" = ANY (ARRAY['percentage'::"text", 'fixed_amount'::"text", 'text_only'::"text"]))))
);


ALTER TABLE "scholarship"."scholarships" OWNER TO "postgres";


COMMENT ON COLUMN "scholarship"."scholarships"."award_percentage" IS 'Percentage award value when explicitly evidenced. CF-199 structures only unambiguous first-party percentage tuition/reduction text; tiered/up-to and non-tuition awards remain unresolved.';



COMMENT ON COLUMN "scholarship"."scholarships"."award_amount" IS 'Fixed award amount when explicitly evidenced. CF-204 records UWA International Student Award as AUD 5,000 per year tuition reduction for program duration; fixed-amount Course net-fee calculation is not yet authorised by the percentage-only calculator.';



COMMENT ON COLUMN "scholarship"."scholarships"."award_applies_to_fee_type" IS 'Exact catalogue.course_fees.fee_type against which the award may be calculated when verified by first-party evidence.';



COMMENT ON COLUMN "scholarship"."scholarships"."award_fee_basis" IS 'Expected fee basis for deterministic calculation, e.g. annual or registered_total_course. Null means calculation is unresolved.';



COMMENT ON COLUMN "scholarship"."scholarships"."award_duration_basis" IS 'Governed award duration. CF-203 records UNSW International Student Award as 20% tuition for program duration from captured first-party detail Evidence; Course/country eligibility remains a separate review gate.';



COMMENT ON COLUMN "scholarship"."scholarships"."award_value_is_maximum" IS 'Decision 212: the stated value is a maximum ("up to"); shown as "Up to ..." and never used for a fee saving.';



CREATE OR REPLACE VIEW "pipeline"."scholarship_provider_stats" AS
 WITH "canonical" AS (
         SELECT "scholarships"."provider_id",
            ("count"(*))::integer AS "canonical_total",
            ("count"(*) FILTER (WHERE ("scholarships"."publication_status" = 'published'::"text")))::integer AS "published_total",
            ("count"(*) FILTER (WHERE ("scholarships"."publication_status" <> 'published'::"text")))::integer AS "unpublished_total"
           FROM "scholarship"."scholarships"
          GROUP BY "scholarships"."provider_id"
        ), "trace" AS (
         SELECT "scholarship_acquisition_trace"."provider_id",
            ("count"(*))::integer AS "trace_total",
            ("count"(*) FILTER (WHERE ("scholarship_acquisition_trace"."verification_status" = 'verified_first_party'::"text")))::integer AS "first_party_verified_total",
            ("count"(*) FILTER (WHERE ("scholarship_acquisition_trace"."review_queue_id" IS NOT NULL)))::integer AS "layer4_linked_total",
            ("count"(*) FILTER (WHERE ("scholarship_acquisition_trace"."scholarship_id" IS NOT NULL)))::integer AS "canonical_linked_total",
            ("count"(*) FILTER (WHERE ("scholarship_acquisition_trace"."publication_decision_id" IS NOT NULL)))::integer AS "publication_decision_linked_total",
            ("count"(*) FILTER (WHERE (("scholarship_acquisition_trace"."verification_evidence_id" IS NOT NULL) AND ("scholarship_acquisition_trace"."source_record_id" IS NOT NULL))))::integer AS "evidence_acquired_total",
            "max"("scholarship_acquisition_trace"."updated_at") AS "trace_last_updated_at"
           FROM "pipeline"."scholarship_acquisition_trace"
          GROUP BY "scholarship_acquisition_trace"."provider_id"
        ), "candidates" AS (
         SELECT "s"."provider_id",
            ("count"(*))::integer AS "candidate_total",
            ("count"(*) FILTER (WHERE (("c_1"."status" = 'discovered'::"text") AND ("c_1"."classification" = 'detail_ready'::"text"))))::integer AS "detail_ready_total",
            ("count"(*) FILTER (WHERE (("c_1"."status" = 'discovered'::"text") AND ("c_1"."classification" = 'needs_review'::"text"))))::integer AS "candidate_needs_review_total",
            ("count"(*) FILTER (WHERE ("c_1"."status" = 'rejected'::"text")))::integer AS "candidate_rejected_total",
            ("count"(*) FILTER (WHERE ("c_1"."status" = 'acquired'::"text")))::integer AS "candidate_acquired_total",
            "max"("c_1"."classified_at") AS "candidate_last_classified_at"
           FROM ("pipeline"."layer2_scholarship_discovery_candidates" "c_1"
             JOIN "pipeline"."sources" "s" ON (("s"."id" = "c_1"."source_id")))
          WHERE ("s"."provider_id" IS NOT NULL)
          GROUP BY "s"."provider_id"
        ), "latest_benchmark" AS (
         SELECT DISTINCT ON ("scholarship_coverage_benchmarks"."provider_id") "scholarship_coverage_benchmarks"."provider_id",
            "scholarship_coverage_benchmarks"."observed_count" AS "landscape_benchmark_total",
            "scholarship_coverage_benchmarks"."observed_at" AS "benchmark_observed_at"
           FROM "pipeline"."scholarship_coverage_benchmarks"
          WHERE (("scholarship_coverage_benchmarks"."benchmark_scope" = 'provider'::"text") AND ("scholarship_coverage_benchmarks"."provider_id" IS NOT NULL))
          ORDER BY "scholarship_coverage_benchmarks"."provider_id", "scholarship_coverage_benchmarks"."observed_at" DESC
        )
 SELECT "p"."id" AS "provider_id",
    "p"."canonical_name" AS "provider_name",
    COALESCE("c"."canonical_total", 0) AS "canonical_total",
    COALESCE("c"."published_total", 0) AS "published_total",
    COALESCE("c"."unpublished_total", 0) AS "unpublished_total",
    COALESCE("t"."trace_total", 0) AS "trace_total",
    COALESCE("t"."first_party_verified_total", 0) AS "first_party_verified_total",
    COALESCE("t"."layer4_linked_total", 0) AS "layer4_linked_total",
    COALESCE("t"."canonical_linked_total", 0) AS "canonical_linked_total",
    COALESCE("t"."publication_decision_linked_total", 0) AS "publication_decision_linked_total",
    "lb"."landscape_benchmark_total",
        CASE
            WHEN ("lb"."landscape_benchmark_total" IS NULL) THEN NULL::integer
            ELSE GREATEST(("lb"."landscape_benchmark_total" - COALESCE("c"."canonical_total", 0)), 0)
        END AS "indicative_gap_to_landscape",
        CASE
            WHEN (("lb"."landscape_benchmark_total" IS NULL) OR ("lb"."landscape_benchmark_total" = 0)) THEN NULL::numeric
            ELSE "round"((((COALESCE("c"."canonical_total", 0))::numeric / ("lb"."landscape_benchmark_total")::numeric) * (100)::numeric), 1)
        END AS "canonical_to_landscape_pct",
    "lb"."benchmark_observed_at",
    "t"."trace_last_updated_at",
    COALESCE("t"."evidence_acquired_total", 0) AS "evidence_acquired_total",
    COALESCE("k"."candidate_total", 0) AS "candidate_total",
    COALESCE("k"."detail_ready_total", 0) AS "detail_ready_total",
    COALESCE("k"."candidate_needs_review_total", 0) AS "candidate_needs_review_total",
    COALESCE("k"."candidate_rejected_total", 0) AS "candidate_rejected_total",
    COALESCE("k"."candidate_acquired_total", 0) AS "candidate_acquired_total",
    "k"."candidate_last_classified_at"
   FROM (((("catalogue"."providers" "p"
     LEFT JOIN "canonical" "c" ON (("c"."provider_id" = "p"."id")))
     LEFT JOIN "trace" "t" ON (("t"."provider_id" = "p"."id")))
     LEFT JOIN "candidates" "k" ON (("k"."provider_id" = "p"."id")))
     LEFT JOIN "latest_benchmark" "lb" ON (("lb"."provider_id" = "p"."id")))
  WHERE ((COALESCE("c"."canonical_total", 0) > 0) OR (COALESCE("t"."trace_total", 0) > 0) OR (COALESCE("k"."candidate_total", 0) > 0) OR ("lb"."provider_id" IS NOT NULL));


