CREATE OR REPLACE VIEW "pipeline"."scholarship_verified_detail_reconciliation_candidates" AS
 WITH "base" AS (
         SELECT "sr"."id" AS "source_record_id",
            "sr"."source_id",
            "src"."provider_id",
            COALESCE("p"."display_name", "p"."canonical_name") AS "provider_name",
            ("c"."iso_alpha2")::"text" AS "country_code",
            "sr"."evidence_id",
            "sr"."source_record_url",
            "scholarship"."normalise_first_party_url"("sr"."source_record_url") AS "normalised_url",
            "sr"."payload",
            "sr"."status",
            "sr"."observed_at",
            "sr"."created_at",
            NULLIF(TRIM(BOTH FROM ("sr"."payload" ->> 'name'::"text")), ''::"text") AS "observed_name",
            "scholarship"."normalise_title"(("sr"."payload" ->> 'name'::"text")) AS "normalised_title",
            COALESCE((NULLIF(("sr"."payload" ->> 'confidence'::"text"), ''::"text"))::numeric, (0)::numeric) AS "confidence",
            "row_number"() OVER (PARTITION BY "src"."provider_id", ("scholarship"."normalise_first_party_url"("sr"."source_record_url")) ORDER BY "sr"."observed_at" DESC NULLS LAST, "sr"."created_at" DESC, "sr"."id" DESC) AS "url_recency_rank"
           FROM ((("pipeline"."scholarship_source_records" "sr"
             JOIN "pipeline"."sources" "src" ON (("src"."id" = "sr"."source_id")))
             JOIN "catalogue"."providers" "p" ON (("p"."id" = "src"."provider_id")))
             JOIN "ref"."countries" "c" ON (("c"."id" = "p"."country_id")))
          WHERE (("src"."provider_id" IS NOT NULL) AND ("sr"."evidence_id" IS NOT NULL) AND ("sr"."status" = ANY (ARRAY['captured'::"text", 'applied'::"text"])))
        ), "classified" AS (
         SELECT "b"."source_record_id",
            "b"."source_id",
            "b"."provider_id",
            "b"."provider_name",
            "b"."country_code",
            "b"."evidence_id",
            "b"."source_record_url",
            "b"."normalised_url",
            "b"."payload",
            "b"."status",
            "b"."observed_at",
            "b"."created_at",
            "b"."observed_name",
            "b"."normalised_title",
            "b"."confidence",
            "b"."url_recency_rank",
                CASE
                    WHEN ("lower"("replace"(COALESCE("b"."observed_name", ''::"text"), '&amp;'::"text", '&'::"text")) ~ '^(about us|academic scholarships|external scholarships|scholarships and fees|financial aid for international students|domestic student scholarships|scholarships & grants|prestigious.*scholarships|home country sponsored scholarships)$'::"text") THEN 'generic_or_navigation_title'::"text"
                    WHEN ("b"."status" = 'applied'::"text") THEN 'already_applied'::"text"
                    WHEN ("b"."url_recency_rank" > 1) THEN 'duplicate_source'::"text"
                    WHEN (COALESCE(("b"."payload" ->> 'identifier_scheme'::"text"), ''::"text") <> 'first_party_detail_url'::"text") THEN 'not_first_party_detail'::"text"
                    WHEN ("lower"(COALESCE(("b"."payload" ->> 'audience'::"text"), ''::"text")) <> 'international'::"text") THEN 'not_international'::"text"
                    WHEN ("b"."confidence" < 0.8) THEN 'low_confidence'::"text"
                    WHEN (("b"."normalised_url" IS NULL) OR ("b"."normalised_url" !~ '^https?://'::"text")) THEN 'invalid_url'::"text"
                    WHEN (("b"."source_record_url" ~* '[?&](query|collection|form|num_ranks|f\.)='::"text") OR ("b"."source_record_url" ~ '#!/'::"text")) THEN 'catalogue_or_filter'::"text"
                    WHEN ("b"."normalised_url" ~* '/(scholarships|international-scholarships|global-scholarships-and-fellowships|scholarships-for-international-students)$'::"text") THEN 'catalogue_or_filter'::"text"
                    WHEN (("b"."observed_name" IS NULL) OR ("length"("b"."observed_name") < 8)) THEN 'generic_or_navigation_title'::"text"
                    WHEN ("b"."observed_name" ~* '^(eligibility|faq|guidelines?|menu|go to top|skip to main content|find a scholarship|scholarships? for international students|international student scholarships|all scholarship opportunities for international students|global curtin scholarships|international scholarship detail|external scholarship opportunities|internal scholarship opportunities|government-funded scholarships|scholarships for commencing international students)$'::"text") THEN 'generic_or_navigation_title'::"text"
                    WHEN ("b"."observed_name" ~* 'is blocked$'::"text") THEN 'generic_or_navigation_title'::"text"
                    ELSE 'ready'::"text"
                END AS "reconciliation_state"
           FROM "base" "b"
        )
 SELECT "source_record_id",
    "source_id",
    "provider_id",
    "provider_name",
    "country_code",
    "evidence_id",
    "source_record_url",
    "normalised_url",
    "payload",
    "status",
    "observed_at",
    "created_at",
    "observed_name",
    "normalised_title",
    "confidence",
    "url_recency_rank",
    "reconciliation_state"
   FROM "classified";


ALTER VIEW "pipeline"."scholarship_verified_detail_reconciliation_candidates" OWNER TO "postgres";


COMMENT ON VIEW "pipeline"."scholarship_verified_detail_reconciliation_candidates" IS 'CF-194 current-state reconciliation boundary: captured/applied Evidence only; individual first-party international Scholarship details only; generic/support/filter records remain review/unmapped.';



