CREATE OR REPLACE VIEW "public"."catalogue_stats" WITH ("security_invoker"='true') AS
 SELECT (("d" ->> 'courses'::"text"))::bigint AS "courses",
    (("d" ->> 'providers'::"text"))::bigint AS "providers",
    (0)::numeric AS "avg_completeness"
   FROM ( SELECT "public"."ui_dashboard"() AS "d") "x";


